(window.GIM_TP=window.GIM_TP||{})["Niddah.0"]={"from":0,"a":[[["מתני׳ \u0001שמאי\u0002 אומר כל הנשים דיין שעתן הלל אומר מפקידה לפקידה ואפילו לימים הרבה","וחכ\"א לא כדברי זה ולא כדברי זה אלא מעת לעת ממעטת על יד מפקידה לפקידה ומפקידה לפקידה ממעטת על יד מעת לעת","כל אשה שיש לה וסת דיה שעתה והמשמשת בעדים הרי זו כפקידה וממעטת על יד מעת לעת ועל יד מפקידה לפקידה","כיצד דיה שעתה היתה יושבת במטה ועסוקה בטהרות ופרשה וראתה היא טמאה והן טהורות","אע\"פ שאמרו מטמאה מעת לעת אינה מונה אלא משעה שראתה","\u0001גמ׳\u0002 מאי טעמיה דשמאי קסבר העמד אשה על חזקתה ואשה בחזקת טהורה עומדת והלל כי אמר העמד דבר על חזקתו היכא דלית ליה ריעותא מגופיה אבל איתתא"],[[0,"מתני' שמאי אומר כל הנשים דיין שעתן","אם ראתה דם די לנו אם תטמא תרומה וטהרות שתגע בהן משעת ראייה ואילך ולא אמרי' כי היכי דהשתא אישתכח דם בבית החיצון אי הות בדקה נמי מקמי הכי הוה אישתכח וכותלי בית הרחם העמידוהו וקיימא לן בפ' יוצא דופן (לקמן נדה דף מ.) כל הנשים מטמאות בבית החיצון:"],[0,"מפקידה לפקידה","בדקה עצמה באחד בשבת ומצאתה טהורה וליום רביעי בדקה ומצאתה טמאה חיישינן ומטמאה מספק כל הטהרות שנתעסקה בהן משעת בדיקת אחד בשבת דשמא עם סילוק ידיה ראתה וכותלי בית הרחם העמידוהו:"],[0,"ואפי' לימים הרבה","בין בדיקה ראשונה לשניה מטמאינן כל הטהרות שנתעסקה בהן בינתיים אבל הנך דמקמי בדיקה קמייתא טהורות דהא כשבדקה עצמה מצאתה טהורה:"],[1,"לא כדברי זה","שהחמיר יותר מדאי דודאי כולי האי ימים רבים לא מוקמי ליה כותלי בית הרחם:"],[1,"ולא כדברי זה","שמיקל יותר מדאי:"],[1,"אלא מעת לעת ממעטת על יד מפקידה לפקידה","שאם יש ימים הרבה בין פקידה לפקידה לא מטמאינן להו לכולהו טהרות דביני וביני אלא אותם שנתעסקה בהם מאתמול בשעה הזאת וטעמייהו דרבנן מפרש לקמן בגמרא נמצא מעת לעת ממעטת זמן מפקידה לפקידה:"],[1,"ומפקידה לפקידה ממעטת על יד מעת לעת","שאם היה זמן מפקידה לפקידה מועט מזמן מעת לעת הולכין אחריו להקל כגון בדקה עצמה שחרית ומצאתה טהורה וחזרה ובדקה ערבית ומצאתה טמאה דאמרי' לקמן במתני' (נדה דף יא.) פעמים צריכה להיות בודקת שחרית ובין השמשות לא מטמאינן טהרות של ליל אמש דהא בדקה שחרית ומצאתה טהורה וליכא למימר דהוי דם מאתמול בהאי שעתא אלא הנך טהרות דמבדיקת שחרית ואילך מטמאינן דהיינו מפקידה לפקידה:"],[1,"על יד","על כח מפקידה לפקידה הוא בא וממעטו כמו פוסל על ידו דיבמות (דף צו.) וכן הרבה:"],[2,"כל אשה שיש לה וסת","קבוע ג' פעמים ובדקה בשעת וסתה ומצאתה טמאה:"],[2,"דיה שעתה","וליכא למימר דמעיקרא הוה התם דודאי אורח בזמנו בא:"],[2,"המשמשת בעדים","שבדקה עצמה בעד דהיינו בסדין קודם תשמיש ולאחר תשמיש:"],[2,"הרי זו כפקידה וממעטת על יד כו'","ואם ראתה דם אחר כך בבדיקת ערבית והיא שמשה בצהרים בעדים לא מטמאינן טהרות דמבדיקת שחרית עד תשמיש שהרי קודם תשמיש בדקה ומצאתה טהורה וליכא למימר מקמי הכי הוה אלא הנך דמתשמיש ואילך טמאות:"],[4,"אף על פי שאמרו כו'","אשאין לה וסת קאי:"],[4,"אינה מונה","ימי נדה אלא משעה כו':"],[5,"גמ' העמד אשה על חזקתה","שהרי מספק אתה בא לטמאותה לענין טהרות דקודם ראייה ספק הוה לה דם מקודם לכן ספק לא הוה הלכך העמד אשה על חזקתה שהיתה קודם ראייה כשנתעסקה בטהרות אלו:"],[5,"","\u0003כגון ספק לא נגע\u0004 ל\"ג דהתם לאו משום חזקה הוא דהא ספק טומאה ברשות הרבים טהור דהיינו ספק נגע הלכתא גמירי לה:"]],[[1,"מתני' מעת לעת","מפרש בגמ' דתולין לא אוכלין ולא שורפין ודוקא לקדשים או לתרומה אבל לחולין לכ\"ע דיה שעתה דאוקמא לה בחזקת טהורה וא\"ת מאי שנא מכל ספק טומאה דברה\"י טמא ודאי אף לחולין ולא מוקמינן בחזקת טהרה משום דילפי' (לקמן נדה דף ג.) מסוטה מדפריך בגמרא לר\"ש אי מה סוטה טמאה ודאי ברה\"י אף הכא טמאה ודאי ומשני שאני סוטה דאיכא רגלים לדבר משמע דלרבנן דאמרי ברה\"י טמאות אתי שפיר וטעם דתרתי לריעותא לא הוצרך אלא לטמא אפילו בר\"ה וי\"ל דלא ילפינן מסוטה לטמאה למפרע ולכך בטומאה דמעת לעת מוקמינן לה אחזקתה וא\"ת במעת לעת דקיל טפי משאר טומאות כדפרישית אמאי החמירו בו לטמאה אף בר\"ה ובכל שאר טומאות אמרינן בר\"ה ספקו טהור כדמוכח בשמעתין דקאמר והלל כי קאמר אוקי מילתא אחזקתה כגון ספק נגע ספק לא נגע אבל במעל\"ע כו' ולא אמרינן אוקי מילתא אחזקתה אלא בר\"ה אלמא במעת לעת אף בר\"ה טמא וכן לקמן (נדה דף ה:) מוקי מתני' כשנושאין אותה חברותיה במטה א\"כ הוו להו תלתא והוי ר\"ה כדמוכח בריש שני נזירים (נזיר נז.) ואפ\"ה המטה טמאה ואע\"ג דיש לדחות כגון שהכילה מפסקת בין נדה לחברותיה אין נראה דבהדיא יש בירושל' דמגעה בר\"ה מטמא במעת לעת וי\"ל דאף בר\"ה לא נטהר בקדשים משום חזקת טהרה כיון איכא ריעותא מגופה ואע\"ג דמסוטה ילפינן לטהר בר\"ה אפי' היכא דליכא חזקה כמו שאפרש לקמן הכא לא ילפינן מסוטה משום שהאשה שראתה השתא ודאי טמאה היא ולא גמרינן מסוטה לטהר בר\"ה אלא כמו ספק נגע ספק לא נגע שגם עתה בספק דומיא דסוטה ומיהו בדבר שאין בו דעת לישאל טהור במעת לעת דלקמן מקשינן אמתני' דבר שאין בו דעת לישאל הוא ומוקמינן בשחברותיה נושאות אותה במטה והיינו משום דדבר שאין בו דעת לישאל לא גמרינן מסוטה [אף על גב דר\"ש מטהר במקוה שנמדד מסוטה. גי'] אלא גמרינן לטהר מדרב גידל דאמר רב גידל (סוטה דף כט.) כתיב והבשר אשר יגע בכל טמא לא יאכל הא ספק טהור וכתיב כל טהור יאכל בשר הא ספק טמא אלא כאן שאין בו דעת לישאל כאן שיש בו דעת לישאל ובטומאת בשר קדש שייך למפרע כמו להבא ועוד י\"ל דלא גמרינן מסוטה אלא טומאת מגע ולא טומאת ראייה לכך מטמא אף ברה\"ר אבל דבר שאין בו דעת לישאל טהור דבטומאת בשר קדש שייך טומאה ע\"י ראיית הזב או הזבה או הנדה דאסרינן לאכול בשר קדש והוי בכלל כל טהור יאכל בשר (ויקרא ז׳:י״ט) וא\"ת מאי שנא דבנגע באחד בלילה (לקמן נדה דף ד.) דמטמאין רבנן אף בר\"ה כדמוכח בתוספתא היכא דלא ראהו חי מבערב משום דכל הטומאות כשעת מציאתן ואשה נמי אמרינן (לקמן נדה דף ד.) כיון דשכיחי בה דמים כאינה בדוקה דמיא ואמאי מטהרינן לחולין אף ברה\"י וי\"ל דלקמן [נמי] בנגע באחד בלילה מיירי בקדשים וכן קופה (לקמן נדה דף ג:) דפריך הלל לשמאי איירי בקדשים דאי לאו הכי תקשה ליה לנפשיה וכן פלוגתא דחזקיה ור' יוחנן (שם) המדלה י' דליים מים מיירי במים שנעשו על טהרת הקדש ללוש בהן עיסת מנחות או להדיח בהן בשר קדש דכקדש דמו וא\"ת ומ\"ש דאמרינן בנגע באחד לשרוף ובמעת לעת אמרינן תולין דאשה נמי מיקריא במקום מציאתה דכל מקום שהיא טומאתה עמה דאי לאו הכי תקשי אשה לחזקיה דמטהר בקופה ממקום למקום וי\"ל משום דלבו נוקפו ויבטל מפריה ורביה דסבור דשכיחא טומאה כיון ששורפין עליה תרומה ופריש דכה\"ג אמרינן לקמן (נדה דף ג:) והא דפריך הלל לשמאי היינו משום דלבו נוקפו לא היה לו לטהר לגמרי [אך קשה דמטהר אף ברה\"י ובקופה מטהר ר' יוחנן ברה\"י וכן בנגע בא' בלילה אפילו רואהו חי לכך נראה דטעמא דשמאי משום ביטול פריה ורביה ולהכי לא עבדינן סייג ברה\"י אפי אי לא כבדוק דמיא. גי':] אך קשה לפ\"ז מאי פריך להלל ממקוה נימא משום דלבו נוקפו וא\"ת אמאי מטהר שמאי טפי באשה מבקופה ונגע באחד אע\"ג דמשני שמאי דאשה אין לה שוליים היינו להאי לישנא דאי הוה דם מעיקרא הוה אתי אבל לשאר לישני לית לן האי טעמא וי\"ל דטעמא דשמאי משום דאשה בדוקה היא והא דקאמר כיון דשכיחי בה דמים כאינה בדוקה דמיא היינו להלל וא\"ת לר\"מ אמאי מטהר בנגע באחד ובאשה תולין וי\"ל משום דמוקמה אחזקתה ואשה משום דאיכא ריעותא מגופה:"],[5,"","והלל כי אמר דמוקי מילתא אחזקתיה. כגון ספק נגע ספק לא נגע היינו בר\"ה כדפרישית אבל ברה\"י לא מוקמינן אחזקתיה והוי טומאה ודאי ילפינן מסוטה ודוקא ספק נגע ספק לא נגע הוי ודאי טמא אבל טמא שנגע באחד מן החביות ואינו יודע באיזה מהם נגע הוו שניהם טמאים מספק ואינן טמאין שניהם בודאי דלא גמרינן מסוטה אלא דבר שיכול להיות והכא האחד טהור בודאי וכן משמע בריש שני נזירים (נזיר נז.) דקתני אמר להם אחד ראיתי אחד מכם שנטמא ואיני יודע איזה מכם מביאין קרבן טומאה וקרבן טהרה ולא מייתי כל אחד קרבן טומאה משום דלא גמרינן מסוטה אלא דבר שיכול להיות והא דפריך התם אמאי מייתו קרבן טומאה לייתו תרוייהו קרבן טהרה דאחד שאמר לשנים הוו להו ג' והוי ר\"ה וספקו טהור אע\"ג דאין יכול להיות שיהו שניהם טהורין דהאחד ודאי טמא וכן גבי שני שבילים בפ\"ק דפסחים (דף י.) מטהרינן שניהם בבאו לישאל זה אחר זה אע\"ג שבודאי נטמא האחד התם לא מסוטה גמרינן אלא דמוקמינן כל אחד בחזקת טהרה כדאיתא הכא דהוי טעמא משום דמוקמינן מילתא אחזקתיה [ומיירי כעין ב' נזירים דליכא למילף מסוטה וצריכא טעמא דחזקה. גי':] ומיהו היכא דליכא חזקה לטהרה מטהרין בר\"ה מסוטה כמו מקוה שנמדד ונמצא חסר דמטהר ר\"ש בר\"ה דגמרינן מסוטה אע\"ג דליכא למימר העמד מקוה על חזקתו דאדרבה העמד טמא על חזקתו ואם תאמר והיכי ילפינן מסוטה לטהר ברשות הרבים אפילו ליכא חזקה הא סוטה אית לה חזקת טהרה ויש לומר כיון דקינא לה ונסתרה איתרע חזקתה ואע\"ג דאין סתירה בר\"ה מכל מקום איתרע חזקתה דשייך קצת סתירה באפילה ובלילה [מיהו בירושלמי דסוטה משמע דאפילה ולילה הוי רה\"י גמור. גי'] ובעת שאין בני אדם מצויין וא\"ת א\"כ היכי ילפינן מסוטה דברה\"י ספקו טמא אפי' איכא חזקה הא בסוטה איתרע חזקה וקרא דונטמאה דאייתר לאגמורי בעלמא טומאה מסוטה אימא דוקא היכא דליכא חזקה ואיצטריך קרא לאשמועינן דהוי טמא ודאי אע\"ג שאינו אלא ספק וגם לטהר בר\"ה אע\"ג דליכא חזקה וי\"ל דילפינן מסוטה שעשאה הכתוב ודאי טמאה אע\"ג דאית לה חזקה שאינה טמאה ודאי ולא איתרע אלא חזקת טהרה ודאית:"]]],[["כיון דמגופה קחזיא לא אמרינן אוקמה אחזקתה","ומאי שנא ממקוה דתנן מקוה שנמדד ונמצא חסר כל טהרות שנעשו על גביו למפרע בין בר\"ה בין ברה\"י טמאות","לשמאי קשיא למפרע","להלל קשיא ודאי דאילו מעת לעת שבנדה תולין לא אוכלין ולא שורפין ואילו הכא טומאה ודאי","התם משום דאיכא למימר העמד טמא על חזקתו ואימא לא טבל אדרבה העמד מקוה על חזקתו ואימא לא חסר הרי חסר לפניך","הכא נמי הרי דם לפניך השתא הוא דחזאי הכא נמי השתא הוא דחסר","הכי השתא התם איכא למימר חסר ואתא חסר ואתא הכא מי איכא למימר חזאי ואתא חזאי ואתא ומאי קושיא דלמא הגס הגס חזיתיה","התם איכא תרתי לריעותא הכא איכא חדא לריעותא","ומאי שנא מחבית דתנן היה בודק את החבית להיות מפריש עליה תרומה והולך ואח\"כ נמצא חומץ כל ג' ימים (הראשונים) ודאי","מכאן ואילך ספק קשיא לשמאי","התם משום דאיכא למימר העמד טבל על חזקתו ואימר לא נתקן אדרבה העמד יין על חזקתו ואימר לא החמיץ","הרי החמיץ לפניך הכא נמי הרי דם לפניך השתא הוא דחזאי התם נמי השתא הוא דהחמיץ","הכי השתא התם איכא למימר החמיץ ואתא החמיץ ואתא הכא מי איכא למימר חזאי ואתא חזאי ואתא ומאי קושיא דלמא הגס הגס חזיתיה","התם איכא תרתי לריעותא הכא איכא חדא לריעותא","ורמי חבית אמקוה מאי שנא הכא ודאי ומ\"ש הכא ספק","א\"ר חנינא מסורא מאן תנא חבית ר\"ש היא דלגבי מקוה נמי ספקא משוי ליה","דתנן מקוה שנמדד ונמצא חסר כל הטהרות שנעשו על גביו למפרע בין בר\"ה בין ברה\"י טמאות","ר\"ש אומר בר\"ה טהורות ברה\"י תולין"],[[0,"כיון דמגופה קחזיא","מועדה ועלולה היא לכך אין לה חזקת טהרה:"],[1,"ומאי שנא ממקוה","לתרוייהו פריך:"],[1,"שנעשו על גביו","טהרות שנשתמשו בכלים שטבלו בו:"],[1,"בין בר\"ה בין ברה\"י","בין שהמקוה עומד בר\"ה דקיימא לן ספק טומאה בר\"ה ספקו טהור הכא טמא דלאו ספק הוא אלא ודאי כדמפרש טעמא לקמן בשמעתין:"],[2,"לשמאי קשיא למפרע","דהא מטמאינן טהרות למפרע ולא אמרינן העמד מקוה על חזקתו:"],[3,"דאילו מעת לעת","טהרות דמטמאין להו משום ספקא דמעת לעת לרבנן וה\"ה מפקידה לפקידה דהלל:"],[3,"תולין","אם תרומה הן:"],[3,"ולא שורפין","כדקתני בברייתא דהרואה כתם לקמן בפירקין (נדה דף ו.):"],[3,"ואילו הכא","במקוה:"],[3,"טומאה ודאית","מטמאינן להו למפרע ושורפין את התרומה מדקתני בר\"ה טמא אלמא כודאי משוי ליה:"],[4,"לא טבל","טבילה הוגנת הלכך טומאה ודאית יש:"],[6,"חסר ואתא חסר ואתא","ואיתרע לה לחזקה מקמי הכי טובא ולא ידעינן מאימת הלכך ריע טפי מאשה:"],[6,"הכא מי איכא למימר כו'","הלכך עד שעת מציאת דם לא איתרעי חזקה והך דאישתכח השתא איכא למימר דהשתא הוא דחזאי:"],[6,"הגס הגס","לשון רבייה שהדם הולך וגדל ודומה לו במסכת שביעית בפ\"ד בראשונה היו אומרים מלקט אדם מתוך שדהו עצים ועשבים הגס הגס כדרך שמלקט משל חבירו כו'. כלומר ע\"י שיהיה הדם רבה במקור יוצא ממנו מעט מעט כחרדל מה שאין המקור יכול להחזיקה ויוצא מעט לבית החיצון וזה כמה ימים התחיל והיא נטמאת מטיפת דם כחרדל כדלקמן (נדה דף מ.):"],[7,"תרתי לריעותא","העמד טמא על חזקת טומאה ובחזקת טהרה דמקוה איכא ריעותא שהרי חסר לפניך. אבל באשה בדידה הוא דאיכא ריעותא שהורע חזקת טהרתה קצת שהרי דם לפניך ומשום הך ריעותא לחודה לא מרעינן לה הואיל ובטהרות לא משכחת ריעותא אחריתא דכי אמרת העמידם על חזקתם בחזקת טהרתם הם:"],[8,"ומאי שנא מחבית","לב\"ש פריך:"],[8,"היה בודק את החבית","טועמה אם היא בחזקתה שלא החמיצה:"],[8,"להיות מפריש עליה","כלומר להיות סומך עליה והולך ושותה שאר חביות ונותן עיניו בזו להפריש ממנה עליהם לאחר זמן שהתרומה ניטלת במחשבה:"],[8,"כל ג' ימים ודאי","פלוגתא דר' יוחנן ור' יהושע בן לוי בבבא בתרא בפ' המוכר פירות (בבא בתרא דף צו.) ר' יוחנן אומר כל ג' ימים לאחר בדיקה ראשונה שמצאה בחזקתה ודאי יין ואם אמר בתוך ג' ימים הרי זו תרומה על אלו הסמוכין לה כולם מתוקנות מכאן ואילך ספק ותרומה היא ויחזור ויתרום ור' יהושע בן לוי אומר כל ג' ימים קודם בדיקה אחרונה שנמצאת חומץ ודאי חומץ דכיון דעכשיו חומץ גמור הוא ודאי אין פחות מג' ימים שהתחיל להחמיץ ואם עשאו בתוך אותן ג' ימים תרומה על מקום אחר אינו תרומה אליבא דרבי דאמר בהמוכר את הספינה (ב ב פד:) יין וחומץ שני מינין הן דאי לרבנן הא קיימא לן (תרומות פ\"ב מ\"ו) תרם מן הרעה על היפה תרומתו תרומה מכאן ואילך למפרע ספק והויא זו תרומה ויחזור ויתרום. אלמא בין למר בין למר מספקינן ריעותא למפרע:"],[14,"ורמי חבית אמקוה","דהא תרוייהו איכא תרתי לריעותא:"],[14,"מאי שנא","במקוה דמחזקינן למפרע טומאת ודאי ומ\"ש בחבית דקאמר ספק:"],[17,"ברה\"י תולין","טעמא מפרש לקמן:"]],[[0,"","דאיכא ריעותא מגופה. אבל אי לאו האי טעמא הוה מוקמינן לה אחזקת טהרה אע\"ג דהשתא ודאי טמאה כמו בנגע באחד דמטהרים אף רבנן בראהו חי מבערב אע\"ג דהשתא הוא מת וליכא עוד חזקת חיות [והא דאמרי' פ\"ק דחולין (דף ט.) גבי בא זאב ונטל בני מעיים התם גמרינן מסוטה דבר\"ה ספיקו טהור היינו לפי סברת דברי המקשה דמדמי איסור לסכנתא אבל מסקנא דשני לן בין איסורא לסכנתא לא ילפי' מסוטה. גי'] ומ\"מ אם עשו מבהמה גבינות ושחטוה ונמצאת טרפה אין להתיר הגבינות מטעם אוקי בהמ' בחזק' שלא היתה טרפה מתחלה כיון דמעולם לא היתה אותה שעה מבוררת לא חשיבה חזקה כדמוכח בהכל שוחטין (חולין יא:) דקאמר אתיא ממכה אביו ומפרה אדומה דאזלינן בתר רובא והיכי מוכח דלמא משום דמוקי לה בחזקת שאינה טרפה אלא לא חשיב אותה חזקה כדפרישית וצ\"ע להתיר הגבינות:"],[3,"","להלל קשה ודאי. דמדקאמר ר' שמעון בסיפא ברה\"י תולין מכלל דטמאות דקאמרי רבנן ברישא היינו ודאי:"],[5,"","השתא הוא דחזאי. ורב דאמר בפ' י' יוחסין (קידושין עט.) הרי היא בוגרת לפנינו גבי קדשה אבי' בדרך וקדשה עצמה בעיר ושניהם ביומא דמשלים ו' חדשים שבין נערות לבגרות ולא קאמר השתא הוא דבגרה היינו משום דרגילות שערות לבא מצפרא וכי פריך התם לשמואל ממקוה וחבית ה\"נ מצי למיפרך לרב דדוקא בשערות קאמר רב אלא דפריך לשמואל טפי בפשיטות והא דקאמר התם לימא רב דאמר כר' נתן דאמר אם בריא הוא עליו להביא ראיה ששכיב מרע היה אע\"ג דרב דוקא בשערות קאמר התם נמי רוב העולם בריאים ואית לן למימר דבריא היה כמו שהוא עכשיו:"],[7,"","התם תרתי לריעותא. תימה דבפ\"ק דחולין (דף י. ושם) אמרינן שחטה ונמצא הסכין פגום ושבר בו עצמות אחרי כן רב חסדא אמר כשרה משום דעצם ודאי פוגם כו' ופריך ליה מטבל ועלה ונמצא עליו דבר חוצץ אע\"פ שנתעסק באותו המין כל היום כולו לא עלתה לו טבילה ומשני סכין איתרעי בהמה לא איתרעי והשתא הא איכא תרתי לריעותא דהרי פגום לפניך והעמד בהמה בחזקת איסור כדאמר הכא דה\"נ איתרעי מקוה ואדם לא איתרעי ואפ\"ה מטמאינן וי\"ל דהתם משום דעצם ודאי פוגם כדאמר התם א\"נ אין סברא לחלק בין מקוה איתרעי לאדם איתרעי והתם ה\"פ סכין איתרעי ואיכא ספיקי טובא שמא בעצם נפגם ואפי' בעור נפגם שמא נפגם במיעוט בתרא ואת\"ל נפגם במיעוט קמא שמא לא שחט כנגד הפגימה אך קשה דאמר התם מנלן דאזלינן בתר חזקה דכתיב ויצא הכהן מן הבית ודילמא אדנפיק ואתי בציר ליה שיעורא אלא אוקמי' אחזקה וקשה התם משום דליכא ריעותא ואכתי היכא דאיכא ריעותא מנלן דאזלינן בתר חזקה וי\"ל דמוכח היכא דבא כהן בסוף שבוע וראה והנה כהה הנגע ואיתרע חזקה מטמאינן אדם הנכנס שם באותו שבוע וחייב קרבן אם נכנס בעזרה וקשה אדרבה נימא התם הרי חסר הנגע לפניך ואוקי גברא בחזקת טהרה כדאמר הכא גבי מקוה לטמא בודאי וי\"ל דגבי מקוה רגילות להתחסר מעט מעט ולכך איכא למימר דמעיקרא חסר אבל הנגע רגילות להתחסר בבת אחת פחות מכגריס לכך אמרינן התם השתא הוא דחסר ואוקי הנגע בחזקת שלם ביציאת כהן מן הבית וכשטימא הכהן את הבית אפי' נתחסר הנגע אחרי כן קודם שנכנס זה גזירת הכתוב הוא שהבית טמא עד שיראה הכהן בסוף שבוע ויטהרנו:"],[8,"","היה בודק את החבית. אפי' לרבנן דאית להו בהמוכר את הספינה (ב\"ב פד.) יין וחומץ מין אחד הוא היינו כשמתכוין לתרום מן החומץ והכא מיירי שנתכוין לתרום מן היין ונמצא חומץ דהוה ליה תרומה בטעות כדמשמע בתוספתא דתרומות פרק התודה והמעשר:"]]],[["ושניהם לא למדוה אלא מסוטה","רבנן סברי כי סוטה מה סוטה ספק היא ועשאוה כודאי הכא נמי ספק ועשאוה כודאי","אי מסוטה אימא כי סוטה מה סוטה ברה\"ר טהור הכא נמי ברה\"ר טהור","הכי השתא התם משום סתירה הוא וסתירה ברה\"ר ליכא הכא משום חסר הוא מה לי חסר ברה\"ר מה לי חסר ברה\"י","וכי תימא הא כל ספק טומאה ברה\"ר טהור כיון דאיכא תרתי לריעותא כודאי טומאה דמי","ורבי שמעון סבר כי סוטה מה סוטה ברה\"ר טהור הכא נמי ברה\"ר טהור","אי מסוטה אימא כי סוטה מה סוטה ברה\"י טמאה ודאי הכא נמי ברה\"י טמאה ודאי","הכי השתא התם יש רגלים לדבר שהרי קינא לה ונסתרה הכא מאי רגלים לדבר איכא","ואי בעית אימא היינו טעמא דרבי שמעון גמר סוף טומאה מתחלת טומאה","מה תחלת טומאה ספק נגע ספק לא נגע ברה\"ר טהור אף סוף טומאה ספק טבל ספק לא טבל ברה\"ר טהור","ורבנן הכי השתא התם גברא בחזקת טהרה קאי מספקא לא מחתינן ליה לטומאה הכא גברא בחזקת טומאה קאי מספקא לא מפקינן ליה מטומאתו","ומאי שנא ממבוי דתנן השרץ שנמצא במבוי מטמא למפרע עד שיאמר בדקתי את המבוי הזה ולא היה בו שרץ או עד שעת הכיבוד","התם נמי כיון דאיכא שרצים דגופיה ושרצים דאתו מעלמא כתרתי לריעותא דמי","ואב\"א היינו טעמא דשמאי הואיל ואשה מרגשת בעצמה והלל כסבורה הרגשת מי רגלים היא","ולשמאי האיכא ישנה ישנה נמי אגב צערה מיתערא מידי דהוה אהרגשת מי רגלים","והאיכא שוטה מודה שמאי בשוטה הא כל הנשים קתני כל הנשים פקחות","וליתני נשים לאפוקי מדרבי אליעזר דא\"ר אליעזר ארבע נשים ותו לא קמ\"ל כל הנשים","והאיכא כתמים לימא תנן כתמים דלא כשמאי אמר אביי מודה שמאי בכתמים מ\"ט בצפור לא נתעסקה בשוק של טבחים לא עברה האי דם מהיכא אתי","אי בעית אימא היינו טעמיה דשמאי דאם איתא דהוה דם מעיקרא הוה אתי והלל כותלי בית הרחם העמידוהו ושמאי כותלי בית הרחם לא מוקמי דם","משמשת במוך מאי איכא למימר אמר אביי מודה שמאי במשמשת במוך","רבא אמר מוך נמי אגב זיעה מכויץ כויץ ומודה רבא במוך דחוק","ומאי איכא בין הני לישני להאיך לישנא"],[[0,"מסוטה","דכתיב (במדבר ה) והיא נטמאה איתקש טומאה לסוטה:"],[1,"ועשאוה כודאי","שאסורה לבעלה עד שתשתה:"],[2,"סוטה ברשות הרבים טהורה","אין רשות הרבים מקום סתירה:"],[7,"רגלים לדבר","סימן טומאה איכא:"],[7,"שהרי קינא לה ונסתרה","התרה בה אל תסתרי עמו ונסתרה:"],[7,"מאי רגלים לדבר איכא","דליהוי חסר מקודם לכן דילמא השתא הוא דחסר וש\"מ דקסבר ר' שמעון בשאר ספק טומאה דעלמא נמי ברה\"י תולין דהא אין רגלים לדבר:"],[8,"ואיבעית אימא","אי מסוטה גמרי רבנן הוה להו למימר ברה\"ר טהור אלא לאו מסוטה מצינן למגמר דתחלת טומאה איתקש לסוטה סוף טומאה לא איתקש ואם כן מאי טעמא דרבי שמעון דמטהר ברה\"ר:"],[8,"גמר סוף טומאה","דהיינו טבילה מתחלת מגע הטומאה:"],[11,"ומאי שנא ממבוי","לשמאי פריך:"],[11,"מטמא למפרע","כל טהרות שנעשו במבוי:"],[11,"עד שיאמר","עליו אדם באותו היום בדקתי ושוב אינו מטמא מאותו היום ולמפרע אבל עד אותו יום הוא מטמא:"],[11,"או עד שעת הכיבוד","אבל טהרות דקודם כיבוד טהורין דחזקת ישראל בודקין מבואותיהן בשעת כיבודיהן ואי הוה בההיא שעתא הוה מישתכח אבל טהרות דלאחר כיבוד טמאות מספק שמא לאחר כיבוד מיד נפל:"],[13,"מרגשת","שנט\"ר בלע\"ז. כלומר יודעת בעצמה כשיוצא דם ממנה והא מדלא ארגשה מאתמול ודאי השתא בבדיקת עד נפק:"],[15,"והא איכא שוטה","שאינה מבינה להרגיש:"],[16,"לאפוקי מדר' אליעזר","במתני' היא לקמן (נדה דף ז.):"],[17,"והא איכא כתמים","הרואה כתם דקיימא לן לקמן (נדה דף נו.) מטמאה למפרע עד שתאמר בדקתי חלוק זה ולא היה בו כתם או עד שעת כבוס ולא אמרינן אי נפיק מגופה הוה מרגשת:"],[17,"לימא תנן כתמים דלא כשמאי","דכיון דאמר אשה מרגשת אמאי טמאה לימא לאו מגופה הוה הואיל ולא ארגשה:"],[17,"בצפור לא נתעסקה","דנימא מדם צפור הוה דאמר התם תולה בכל דבר שהיא יכולה לתלות בפ' הרואה כתם (לקמן נדה נח:):"],[19,"משמשת במוך","ממלאה אשה אותו מקום מוכין לשאוב את הזרע שלא תתעבר ואינה נוטלתו משם אלא בשעת הצורך ושמא מוך העמיד את הדם. ג' נשים משמשות במוך קטנה מעוברת ומניקה:"],[20,"מכויץ כויץ","ויש מקומות לדם לצאת:"],[20,"כויץ","דשריי\"ט בלע\"ז:"],[21,"בין הני לישני","אשה מרגשת ומעיקרא הוה אתי:"],[21,"להאיך לישנא","העמד אשה על חזקתה:"]],[[0,"","ושניהם לא למדוה אלא מסוטה. תימה דהא רבנן מטמאין אף בר\"ה משום דהוי תרתי לריעותא אם כן לא הוי ספק ולא שייך זה לסוטה מידי וכן בחבית דהוי ודאי טבל לרבנן דומיא דמקוה הא לא גמרינן מסוטה אלא טומאה ורבי שמעון נמי דגמר חבית מטומאה הא לא שייך מידי לסוטה ואומר ר\"ת דלא קאמר הכי אלא לפרש דלא תקשי להו מסוטה וטעמא דרבנן משום דהוי תרתי לריעותא והוי ודאי ולא ספק ולרבי שמעון הוי ספק דלית ליה טעמא דהרי חסר לפניך דהשתא הוא דחסר וכנגד העמד מקוה בחזקת שלם איכא למימר העמד טמא על חזקתו ולכך ברה\"י תולין מדינא ואע\"ג דלא ילפינן מסוטה ולכך בחבית נמי ספק אבל ברה\"ר מטהר אע\"ג דליכא חזקה דמסוטה ילפינן כדפי' לעיל ובכל ספק טומאה אית ליה ברה\"י תולין:"],[8,"","גמר סוף טומאה מתחלת טומאה. תימה דשפיר קאמרי רבנן דהתם איכא חזקת טהרה וי\"ל דגמר מתחלת טומאה היכא דליכא חזקת טהרה כגון ההיא דתנוק דפ' בתרא דקדושין (דף פ.) דאיכא רוב תינוקות מטפחין כנגד חזקת העיסה ואינו רוב גמור והוי פלגא כנגד החזקה ואילו היה בה דעת לישאל מן התורה היה ברה\"י טמא גמור וברה\"ר טהור גמור דגמרינן מסוטה ורבנן התם איכא חזקת טהרה פי' כנגד רוב טיפוח והוי ספק וגמרי מסוטה לטהר ברה\"ר אבל הכא גברא בחזקת טומאה והוי תרתי לריעותא והוי ודאי:"],[11,"","השרץ שנמצא במבוי. לשמאי פריך דמטהר לגמרי:"],[12,"","ושרצים דמעלמא. וא\"ת סיפא דקתני התם כתם שנמצא בחלוקה מטמא למפרע עד שתאמר בדקתי את החלוק ולא היה בו כתם או עד שעת הכבוס מאי איכא למימר דהתם ליכא למימר דאיכא דם מגופה ומעלמא דמשום דם דמעלמא אינו טמא אלא חלוק ולקמן בפרקין (נדה דף ו.) נמי אמרינן הרואה כתם מקולקלת למנינה וי\"ל דהואיל ואם הכתם יבש הוא ע\"כ טמאה למפרע ופעמים נמי אף כשהוא לח מוכיח דלא אתא השתא אלא על ידי שחייה או ע\"י ריקוד כדאמר בהרואה כתם (לקמן נדה נז:) לא פלוג רבנן בכתמים:"],[13,"","ואיבעית אימא טעמא דשמאי הואיל ואשה מרגשת בעצמה. נראה דלהאי לישנא נמי צריך טעמא דהעמד אשה על חזקתה דאל\"כ כי קאמר מודה שמאי בשוטה וכן מודה שמאי במוך וכי יטמאנה למפרע אף לחולין והלא כל הנשים דיין שעתן לחולין אף להלל אלא הני טעמי לא איצטריך אלא כי היכי דלא נעבד סייג בקדשים [ומיהו לפי זה לא א\"ש הא דאמר לקמן עשה סייג לדבריך כיון דאיכא דהוה דם כו' לא הוה אלא סייג ושמא טעמא דהגרושה אהני אף בשוטה לחולין. גיליון:]:"],[13,"","מרגשת בעצמה. פי' כשנעקר דם מן המקור ומדלא הרגישה עד עכשיו השתא הוא דחזאי וא\"ת וכי בדקה עצמה ומצאה טמאה ולא הרגישה מאי [טעמא דשמאי נימא כמו שלא הרגישה עכשיו כך נימא שמא נעקר מאתמול ולא הרגישה] וי\"ל דלא פלוג רבנן הואיל ורוב פעמים מרגשת דהא לטעמא דאם איתא דהוה דם מעיקרא הוה אתי שוכבת אפרקיד מאי איכא למימר אלא לא פלוג רבנן והא דקאמר מודה שמאי בשוטה ובמוך משום דהנהו חלוקות משאר נשים ולא שייך למימר בהו לא פלוג רבנן ורש\"י פירש מה שעכשיו לא הרגישה כסבורה הרגשת עד הוא וקשה מאתמול נמי נימא הא דלא הרגישה אם שמשה כסבורה הרגשת שמש הוא ואמאי מטהרין למפרע אלא שמאי אית ליה דלעולם אשה מרגשת ואינה חוששת בהרגשת עד ושמש כמו שאינה חוששת בהרגשת מי רגלים:"],[15,"","מודה שמאי בשוטה. ואם תאמר והא אין בו דעת לישאל וי\"ל כגון אדם שנגע בה ורוצה לעסוק בקדשים ואותו אדם יש בו דעת לישאל:"],[17,"","והא איכא כתמים. פירוש לשמאי דאית ליה טעמא דהרגשה לטהר אף בקדשים היה לנו לטהר כתמים אפי' מכאן ולהבא דאית לן למימר כיון דלא הרגישה ודאי מעלמא אתי כדאמר (לקמן נדה דף ה.) גבי תינוקת שלא הגיע זמנה לראות אפילו סדינין שלה מלוכלכין בדם אין חוששין לה אימר בשוק של טבחים עברה ולאו אדעתה אבל להלל לא קשה כיון דאינו ברור לו טעמא דהרגשה לטהר בקדשים אין לנו לתלות בכתמים ולומר דמעלמא אתי אפילו לחולין דרגלים לדבר הוא דמגופה אתי אפילו למפרע:"]]],[["איכא בינייהו למרמי חבית ומקוה ומבוי להאיך לישנא איכא למרמינהו להני לישני ליכא למרמי","ומאי איכא בין האי לישנא להאיך לישנא לאביי איכא מוך","לרבא איכא מוך דחוק","תניא כי האי לישנא דאם איתא דהוה דם מעיקרא הוה אתי אמר לו הלל לשמאי אי אתה מודה בקופה שנשתמשו בה טהרות בזוית זו ונמצא שרץ בזוית אחרת שטהרות הראשונות טמאות אמר לו אבל","ומה הפרש בין זו לזו לזו יש לה שולים לזו אין לה שולים","רבא אמר טעמא דשמאי משום בטול פריה ורביה תניא נמי הכי אמר לו שמאי להלל א\"כ בטלת בנות ישראל מפריה ורביה","ומאן דתני האי לישנא הא תניא כי האיך לישנא דאם איתא דהוה דם מעיקרא הוה אתי התם הלל הוא דקטעי הוא סבר טעמא דשמאי דאם איתא דהוה דם מעיקרא הוה אתי וקא מקשי ליה קופה","ואמר ליה שמאי טעמא דידי משום בטול פריה ורביה ולמאי דקטעית נמי דקמקשית קופה לזו יש לה שולים ולזו אין לה שולים","ולמאן דתני האי לישנא הא תניא כי האיך לישנא משום בטול פריה ורביה","הכי קאמר ליה הלל לשמאי אין טעמא קאמרת דאם איתא דהוה דם מעיקרא הוה אתי ומיהו עשה סייג לדבריך דמאי שנא מכל התורה כולה דעבדינן סייג","אמר ליה א\"כ בטלת בנות ישראל מפריה ורביה והלל מפריה ורביה מי קאמינא לטהרות הוא דקאמינא","ושמאי לטהרות נמי לא דאם כן לבו נוקפו ופורש","(שולי\"ם בדוקי\"ן מכוסי\"ן בזוי\"ת סימ\"ן) איתמר קופה שנשתמשו בה טהרות בזוית זו ונמצא שרץ בזוית אחרת חזקיה אמר טהרות הראשונות טהורות רבי יוחנן אמר טהרות הראשונות טמאות והא (בית) שמאי והלל מודו בקופה דטהרות הראשונות טמאות","כי מודו שמאי והלל בקופה שיש לה שולים כי פליגי חזקיה ורבי יוחנן בקופה שאין לה שולים","אין לה שולים מ\"ט דר' יוחנן אין לה שולים ויש לה אוגנים","והתניא המדלה עשרה דליים מים בזה אחר זה ונמצא שרץ באחד מהן הוא טמא וכולן טהורין ואמר ריש לקיש משום רבי ינאי לא שנו אלא שאין לה אוגנים אבל יש לה אוגנים כולן טמאין","לימא חזקיה לית ליה דר' ינאי מיא שרקי פירי לא שרקי","אי נמי מיא לא קפיד עלייהו פירי קפיד עלייהו","ואי בעית אימא כי מודו שמאי והלל בקופה שאינה בדוקה"],[[1,"לאביי איכא מוך","ללישנא דאשה מרגשת אפי' משמשת במוך נמי דיה שעתה וללישנא דמעיקרא הוה אתי משמשת במוך מטמאה למפרע:"],[3,"ונמצא בה שרץ בזוית אחרת","לאחר שניטלו טהרות מן הקופה:"],[3,"שטהרות הראשונות טמאות","למפרע. ודוקא בזוית אחרת כגון קופה ארוכה אמתים וג' אמות דאיכא למימר קודם שניטלו הטהרות הוה התם ונטמא הכלי מחמת השרץ וטהרות מחמת הכלי ואיהו הוא דלא נתעסק באותו זוית ולא אשכחיה אבל באותו זוית לא דודאי בתר הכי נפל דאי הוה התם בשעת טהרות הוה חזי ליה כשהוציאן:"],[3,"אבל","כן הדבר:"],[4,"ומה הפרש בין זו לזו","והא טומאה דלמפרע הוא:"],[4,"שולים","פונ\"ץ בלע\"ז. ועכבו השולים את השרץ מלצאת והוא הוציא טהרות דרך פיה מלמעלה והשרץ שבזוית אחרת לא ראה:"],[4,"ולזו אין לה שולים","ואי הוה דם מאתמול בבית החיצון הוה נפיק ונפיל:"],[5,"מפריה ורביה","דכיון דחיישינן לדם בבית החיצון לבו נוקפו ופורש מן האשה:"],[6,"וקא מקשי ליה קופה","הרי קופה דלא אמר אם איתא דהוה שרץ מעיקרא הוה נפיק עם הטהרות כשעירה את הקופה:"],[9,"סייג","חזוק וגדר מדרבנן לטמא למפרע. וה\"ה דמצי למיפרך הני מתני' אהנך לישנא דלעיל ולתרוצי כי האי גוונא הלל טעי וסבר טעמא דשמאי אם איתא כו' וקשיא ליה קופה וקאמר ליה שמאי טעמא דידי משום העמד אשה על חזקתה אי משום אשה מרגשת ולמאי דקא טעית נמי דקא מקשת לי קופה זו יש לה שולים כו':"],[13,"שיש לה שולים","והוא הוציאן דרך הפה הלכך אם שרץ היה בה לא ראהו ולא יצא:"],[13,"שאין לה שולים","כגון חבית של עץ שניטלו שוליהם ויכול להשתמש באורך חללן כשהן מוטלות בקרקע וכשהוא מערה אותן הוא מגביה ראש האחד ומערה והכל יוצא ממנה:"],[14,"מאי טעמא דר' יוחנן","הא ודאי אילו הוה התם בשעת טהרות הוה נפיק בהדייהו:"],[14,"אוגנים","במקום השוליים יש אוגנים שכפופין ראשי הנסרים כלפי פנים וכשהוא מערה איכא למימר אוגנים עכבו:"],[15,"עשרה דליים","י' פעמים בדלי אחד ומערה בכלי גדול:"],[15,"וכולן טהורין","דאמר השתא הוא דנפל דהואיל שלא מצא קודם שעירה הדלי בפעם הזאת לתוך הכלי טהורין:"],[15,"שאין לו אוגנים","לדלי דהשתא ודאי אם איתא דהוה התם בזימנא קמאי הוה נפיל מן הדלי עם המים:"],[16,"מיא שרקי","ואין צריך להפוך הדלי על פניו כשהוא מערה הלכך איכא למימר אוגנים עכבוהו לשרץ אבל פירי לא שרקי וכשעירה טהרות ממנה הפכה כולה על פניה לפי שאין פירות נוחין לישרק ולצאת הלכך אי הוה שרץ עם הטהרות הוה שריק ונפיל בהדייהו:"],[17,"לא קפיד עלייהו","אי משייר מינייהו לתוך הדלי הלכך אינו שופך כל הדלי על פניו ומצו אוגנים לעכובי שרץ:"],[17,"קפיד עלייהו","לאפוקינהו כולהו והופך קופה על פיה ולא משייר מידי ואם איתא דהוה שרץ הכי נמי דלא אישתייר:"],[18,"בקופה שאינה בדוקה","שלא בדקה בשעה שנתן טהרות לתוכה הלכך אין להעמידה על חזקת טהרה:"]],[[0,"","איכא בינייהו למרמי חבית ומקוה. וא\"ת להני טעמי נמי איכא למרמי דהא מודה שמאי בשוטה דלא מרגשת דלמפרע תולין ובמקוה שורפין וכן להלל דלית ליה הני טעמי צריך לשנויי כדמשני דהתם תרתי לריעותא וי\"ל דטעמא דהרגשה מהני להלל שלא לטמא ודאי ולשמאי מהני אף בשוטה שלא לטמאותה בודאי א\"נ יש לומר דידע טעמא דתרתי לריעותא לשרוף אבל תולין אע\"ג דליכא תרתי לריעותא ועיקר פירכא דלעיל לשמאי דמשום דליכא באשה תרתי לריעותא מ\"מ לא היה לו לטהר לגמרי וא\"ת אכתי איכא למירמי דבמקוה מטמאינן אף ברה\"ר ובנגע באחד בלילה מטהרים חכמים ברה\"ר בראהו חי מבערב אלא ע\"כ היינו טעמא משום דבמקוה איכא תרתי לריעותא וי\"ל דלא קשה ליה לעיל אלא במאי דמטהר שמאי אף ברשות היחיד:"],[1,"","לאביי איכא מוך. ה\"מ למימר נמי דאיכא בינייהו שוטה דללישנא קמא דאשה מרגשת מודה שמאי בשוטה ואין לומר דללישנא דאי הוה דם מעיקרא הוה אתי מודה נמי שמאי בשוטה דשמא דם אחר נפל קודם בדיקה משום דמשמע דעל דם שנמצא עכשיו קאמר:"],[13,"","כי פליגי חזקיה ור' יוחנן בקופה שאין לה שולים. שאז משתמשין בה כשהיא מושכבת וקופה היא מרובעת ומשתמשין בה לרחבה ונמצאו טהרות בימין ושרץ בשמאל ופליגי דלחזקיה אית ליה טהרות האחרונות טמאות אבל הראשונות טהורות דשרץ בתר הכי נפל דאילו הוה התם מעיקר' כשהגביה הקופה לערות ממנה הטהרות היה נופל גם השרץ ור' יוחנן אמר דטהרות הראשונות נמי טמאות שהאוגנים עכבו השרץ מליפול בארץ ולכך לא ראהו לפי שהטהרות נפלו לצד ימין ולצד שמאל שהשרץ שם לא ראה אבל אם היתה הקופה עגולה מודה רבי יוחנן דהראשונות טהורות דאז נופלין השרץ והטהרות במקום אחד ואע\"פ שהאוגנים מעכבין מליפול בארץ מ\"מ אי הוה השרץ התם היה רואהו ולכך נקט דוקא נמצא בזוית אחרת וכן מוכח בפ\"ק דשבת (דף ח.) דסתם קופה מרובעת גבי כוורת נקט רחבה ששה לפי שהיא עגולה וצריך להיות בה ד' מרובעים ובקופה נקט רחבה ד' [לפי שהיא מרובעת] ודליים אפי' הם עגולים אתי שפיר דרגילות הוא לערות המים מהר ואין רואין אם נשאר שרץ בכלים ולר' יוחנן קופה דשמאי ה\"ה דמצי למנקט אפילו באין לה שולים אך יש לה אוגנים:"],[15,"","והתניא המדלה י' דליים כו'. הקשה הר\"ר מנחם אמאי לא מייתי מתניתין דטהרות פ\"ד (מ\"ד) דתנן המדלה י' דליים ונמצא שרץ בא' מהן הוא טמא וכולן טהורין וי\"ל דהתם לא קתני זה אחר זה ואיכא למימר דמיירי כשמדלה שם י' דליים והם כולם יחד בבור והעשירי שהגביה נמצא בו שרץ ולא ידעינן כשהיה השרץ על המים בבור אם בשאר דליים נגע בעודן בבור והוי ספק טומאה צפה על פני המים דטהור אף ברה\"ר כדאיתא בסוף נזיר (דף סד.) ואין חילוק בין יש לה אוגנים בין אין לה אוגנים אי נמי לא קתני מים במתניתין ואיכא למימר דמיירי בבור שיש בו יין ושמן וקמ\"ל דט' דליים הראשונים טהורים ולא אמרינן שהשרץ היה תחלה בבור וטימא הכל אלא אמרינן דבדלי זה אחרון נפל תחלה בעודו ריקן וכשדלאו לבור לבסוף הוא טמא ומטמא כל מה שבבור אבל שאר דליים הראשונים טהורים:"]]],[["כי פליגי חזקיה ור' יוחנן בקופה בדוקה מר סבר הא בדקה ומר סבר אימור עם סילוק ידו נפל","והא דומיא דאשה קתני ואשה בדוקה היא כיון דשכיחי בה דמים כשאינה בדוקה דמיא","ואיבעית אימא כי מודו שמאי והלל בקופה שאינה מכוסה כי פליגי חזקיה ורבי יוחנן בקופה מכוסה מכוסה היכי נפל כגון שתשמישה ע\"י כסוי","והא דומיא דאשה קתני ואשה מכוסה היא כיון דשכיחי בה דמים כשאין מכוסה דמיא","ואיבעית אימא כי מודו שמאי והלל בזוית קופה כי פליגי חזקיה ורבי יוחנן בזוית בית והא קופה קאמר","ה\"ק קופה שנשתמשו בה טהרות בזוית בית זו וטלטלוה בזוית אחרת ונמצא שרץ בזוית אחרת חזקיה סבר לא מחזקינן טומאה ממקום למקום ורבי יוחנן סבר מחזקינן","ומי מחזקינן והתנן נגע באחד בלילה ואינו יודע אם חי אם מת ולמחר השכים ומצאו מת ר\"מ מטהר","וחכמים מטמאין שכל הטמאות כשעת מציאתן","ותני עלה כשעת מציאתן ובמקום מציאתן","וכי תימא הני מילי לשרוף אבל לתלות תלינן ומי תלינן","והתנן מחט שנמצאת מלאה חלודה או שבורה טהורה שכל הטמאות כשעת מציאתן ואמאי לימא האי מעיקרא מחט מעלייתא היא והשתא הוא דהעלה חלודה","ועוד תנן מצא שרץ שרוף על גבי הזיתים וכן מטלית המהומהם טהור שכל הטמאות כשעת מציאתן","וכי תימא כשעת מציאתן בין לקולא בין לחומרא ובמקום מציאתן אבל שלא במקום מציאתן משרף לא שרפינן מתלא תלינן","והתנן ככר ע\"ג הדף ומדף טמא מונח תחתיו אע\"פ שאם נפלה א\"א אלא א\"כ נגעה טהורה שאני אומר אדם טהור נכנס לשם ונטלה","עד שיאמר ברי לי שלא נכנס אדם שם וא\"ר אלעזר לא נצרכה אלא למקום מדרון","התם כדקתני טעמא"],[[1,"והא דומיא דאשה קתני","בההיא דהלל ושמאי דקתני מה הפרש בין זו לזו:"],[1,"ואשה בדוקה היא","מקודם לכן דהא כל שחרית וערבית היא בודקת אפ\"ה טהרות דקופה טמאות וקשיא לחזקיה:"],[1,"כשאינה בדוקה דמיא","וקופה נמי בשאינה בדוקה עסקינן:"],[2,"ואיבעית אימא","הא והא בבדוקה אלא דשמאי והלל כשאינה מכוסה ופיה מלמעלה הלכך איכא למימר עם סילוק ידיו נפלו וחזקיה במכוסה מש\"ה מטהר:"],[2,"מכוסה","בתמיה. היכי נפל האי שרץ והיכי אישתכח בה השתא:"],[2,"שתשמישה ע\"י כסוי","כשהוא רוצה להכניס לתוכה ולהוציא מתוכה מגלה ומכסה אותה הלכך חזקיה סבר כל זמן שהטהרות בתוכה נזהר בה וכסה והשתא לאחר שניטלו ממנה הסיח דעתו משמירתה ולא נזהר לכסותה ונפל ור' יוחנן סבר חיישינן שמא כשגילה להשתמש בה בעוד שהטהרות בתוכה נפל:"],[3,"מכוסה היא","דלא נפיל בה דם מעלמא וקופה דכוותה במכוסה עסקי' ואפ\"ה טמאה וקשיא לחזקיה:"],[4,"בזוית בית","כדמפרש ואזיל שטלטלה לקופה בזוית אחרת לאחר שניטלו טהרות ממנה:"],[5,"ממקום למקום","דלא אמרינן מאידך זוית הוה בה שרץ עם הטהרות אלא אמרינן לאחר שהביאה כאן נפל בה:"],[8,"ובמקום מציאתן","אם מצאו שחרית מת באותו מקום שנגע בו בלילה טמא אבל מצאו במקום אחר מת טהור ולא אמרינן כי היכי דהכא מת התם נמי הוה מת במקומו הראשון:"],[9,"לשרוף","דלא מחזקינן טומאה ודאית ממקום למקום לשרוף עליה תרומה:"],[9,"אבל מתלא תלינן","דהרי משמע במקום מציאתן הוא דחכמים מטמאין טומאה ודאי אבל שלא במקום מציאתן טומאתן הוה ספק ור' יוחנן נמי לתלות קאמר:"],[10,"חלודה","רדוליר\"א:"],[10,"או שבורה","ע\"ג טהרות ומכיר בה שהיא טמאה:"],[10,"טהורה","מלטמא טהרות שנמצאת עליהן ולא אמרינן שלמה נפלה עליהם וטמאתם ואח\"כ נשברה אלא אמרינן שבורה או חלודה כאשר היתה עתה נפלה עליהם. אלמ' כל הטמאות כשעת מציאתן מחזקי' להו ואפי' תלייה ליכא דקתני טהורה וקס\"ד דה\"ה נמי למקום מציאתן דמחזקינן להו בטומאה ולא מספקינן לה במקום אחר אפילו לתלות וקשיא לר' יוחנן:"],[11,"נמצא שרוף","השרץ:"],[11,"מטלית","טלית של זב היתה:"],[11,"(המהומהם)","הבלויה. מצאה בלויה ע\"ג זיתים:"],[11,"טהורה","מלטמא הזיתים דאמרינן הכי נפלה עלייהו לאחר שבלתה וטהרה מטומאתה. אלמא לא מחזקינן טומאה משעה לשעה אפי' לתלות דקתני טהורה וה\"ה ממקום למקום:"],[12,"וכי תימא","לא דמי דהכא משום הכי טהור משום דשעת מציאתה ומקום מציאתה בטהרה הואי דבתר שעת מציאתן אזלינן בין לקולא בין לחומרא בין לקולא כי הכא גבי מחט ומטלית לאחזוקי בטהורה ודאי בין לחומרא כגון נגע באחד בלילה לאחזוקי בטומאה ודאית:"],[12,"ושלא במקום מציאתן","דליכא רגלים לדבר כולי האי משרף לא שרפינן מתלא תלינן:"],[13,"הדף","קרש מונח על גבי יתדות בכותל:"],[13,"ומדף טמא","בגד טמא מונח תחת הדף בקרקע. בת\"כ קרי מדף לעליונו של זב ומדף לשון טומאה קלה הוא כדלקמן וס\"ד השתא שהוא עליונו של זב דטמא מדאורייתא ומיהו טומאתו קלה משל מדרס דלא הוי אב הטומאה לטמא אדם וכלים. ובא ומצא את הככר ע\"ג הקרקע מן הבגד והלאה:"],[13,"ונטלה","ולא נפלה על גבי המדף שנטלו מעל הדף והניחה לארץ:"],[14,"לא נצרכה","האי שאני אומר:"],[14,"אלא למקום מדרון","שאע\"פ שהדף שהככר עליה מקום מדרון וראויה הככר ליפול ואם נפלה נגעה בבגד אפילו הכי טהורה שאני אומר כו' אלמא לא מחזקינן טומאה ממקום למקום דנימא מעל הדף נפל ונתגלגל לכאן:"]],[[0,"","כי פליגי חזקיה ור' יוחנן בקופה בדוקה. וא\"ת דבנגע באחד בלילה אמרו חכמים אם ראוהו חי מבערב טהור שספק טומאה ברה\"ר ספקו טהור משמע דברה\"י אפילו ראוהו חי טמא והשתא הך קופה היכי דמיא או ברה\"ר מאי טעמא דרבי יוחנן דמטמא ואי ברה\"י מ\"ט דחזקיה דמטהר וי\"ל דברה\"י איירי וחזקיה יפרש הברייתא דבראוהו חי מבערב טהור אפילו ברה\"י וספק טומאה ברה\"ר טהור דקאמר היינו דהוי כאילו הוא ספק טומאה ברה\"ר כיון שהיא בדוקה תחלה ואגב דברישא נקט האי לישנא במילתיה דר\"מ היכא דלא ראוהו חי מבערב מתחלה דקתני בתוספתא ר\"מ מטהר ברה\"ר נקט נמי במילתייהו דחכמים בסיפא רה\"ר:"],[3,"","והא אשה מכוסה היא. פי' רש\"י דלא נפל בה דם מעלמא וקשה דכ\"ש שהיא טמאה דאין לתלות בדם אחר אלא בא מגופה לכך י\"ל מכוסה היא שהמקום סתום וכשהדם יוצא נפתח והיה לה להרגיש וא\"ת והא בקופה בדוקה פליגי דאי לאו הכי מאי מועיל כשהיא מכוסה וא\"כ מאי פריך והא אשה מכוסה מאי מועיל כסוי כיון דלאו כבדוקה דמיא וי\"ל שרוצה ליישב אפי' אי חשיב לה כבדוקה:"],[7,"","שכל הטמאות כשעת מציאתן. לעיל פי' דהיינו דוקא לקדשים והא דמחט שנמצאת מלאה חלודה דטהורה דכל הטמאות כשעת מציאתן אפילו להקל לאו משום דהוי כשעת מציאתן דאורייתא אלא משום דמוקי הטהרות אחזקתייהו וא\"ת מאי פריך מככר הנתונה על גבי דף דלמא בככר של חולין איירי וי\"ל דאפילו בחולין לא היה לנו לעשות כל כך לתלות באדם טהור שהנפילה נראית יותר והיה לנו לטמא ממקום למקום כיון דלא אפשר ליפול אלא אם כן נגע אי בשום מקום אנו מחמירין אפילו בקדשים:"],[9,"","ומי תלינן והא אנן תנן כו'. וא\"ת והיא הנותנת משום דאזלינן בתר שעת מציאתה לגמרי אפילו ממקום למקום לתלות לכך מחט שנמצאת מלאה חלודה טהורה לגמרי ואע\"ג דמצינן למימר דהיינו דקאמר וכ\"ת כשעת מציאתן לגמרי בין לקולא בין לחומרא מ\"מ מאי ס\"ד דמקשה וי\"ל דס\"ד כיון דמחמיר כל כך בטומאה לתלות אפי' ממקום למקום [ע\"כ אינו טעם גמור דדוקא בקדשים הוא ומשום חומרא] א\"כ במחט לא היה לו לטהר לגמרי משום שעת מציאתה אלא הוה ליה למימר השתא הוא דעלתה חלודה:"],[13,"","ככר הנתונה על גבי דף. וא\"ת שאני התם שאין בו דעת לישאל כדאמר בסמוך וי\"ל דפריך אי בשום מקום אנו מחמירין ממקום למקום אפילו בקדשים לא היה לנו לעשות ספק ולתלות באדם טהור דיותר יש לתלות בנפילה:"],[13,"","שאני אומר אדם טהור. וא\"ת דהכא תלינן באדם טהור ובפ\"ק דחולין (דף ט:) גבי צלוחית שהניחה מכוסה ובא ומצאה מגולה תלינן באדם טמא וכן פ\"ק דפסחים (דף י:) גבי קורדום ותירץ ר\"ת דגבי כלים הנמצאין דווקא גזרינן טומאה משום דאית להו טהרה במקוה וליכא פסידא אבל באוכלין דאיכא פסידא דלית להו טהרה במקוה לא החמירו אי נמי הכא מוכחא מילתא דאדם טהור הסירה בכוונה כדי שלא תפול על מדף טמא אבל בעלמא טמאין בין באוכלין בין בכלים דליכא למימר אדם בכוונה עשה לתקנתא:"],[14,"","לא נצרכה אלא למקום מדרון. פירוש כשהמדף במקום מדרון דאפילו נפל הככר על גבי מדף לא נשאר לשם אבל אם המדף בקרקע שוה פשיטא דטהור:"]]],[["שאני אומר אדם טהור נכנס לשם ונטלה","הכא נמי נימא עורב אתא ושדא אדם דבכונה אמרינן עורב דשלא בכונה לא אמרינן","מכדי האי ככר ספק טומאה ברה\"י הוא וכל ספק טומאה ברה\"י ספקה טמא משום דהוי דבר שאין בו דעת לישאל וכל דבר שאין בו דעת לישאל בין ברה\"ר בין ברשות היחיד ספקו טהור","ואב\"א הכא בטומאה דרבנן דיקא נמי דקתני מדף כדכתיב (ויקרא כו:לו) עלה נדף","וחכ\"א לא כדברי זה כו' ת\"ר וחכ\"א לא כדברי זה ולא כדברי זה לא כדברי שמאי שלא עשה סייג לדבריו ולא כדברי הלל שהפריז על מדותיו","אלא מעת לעת ממעטת על יד מפקידה לפקידה ומפקידה לפקידה ממעטת על יד מעת לעת","מעת לעת ממעטת על יד מפקידה לפקידה כיצד בדקה עצמה באחד בשבת ומצאת טהורה וישבה שני ושלישי ולא בדקה ולרביעי בדקה ומצאה טמאה אין אומרים תטמא מפקידה לפקידה אלא מעת לעת","ומפקידה לפקידה ממעטת על יד מעת לעת כיצד בדקה עצמה בשעה ראשונה ומצאת טהורה וישבה לה שניה ושלישית ולא בדקה ולרביעית בדקה ומצאה טמאה אין אומרים תטמא מעת לעת אלא מפקידה לפקידה","פשיטא כיון דבדקה עצמה בשעה ראשונה ומצאת טהורה לא מטמינן לה מעת לעת איידי דתנא מעל\"ע ממעטת על יד מפקידה לפקידה תנא נמי מפקידה לפקידה ממעטת על יד מעת לעת","אמר רבה מאי טעמייהו דרבנן אשה מרגשת בעצמה א\"ל אביי אם כן תהא דיה שעתה ורבה לחדודי לאביי הוא דבעי אלא מאי טעמייהו דרבנן","כי הא דאמר רב יהודה אמר שמואל חכמים תקנו להן לבנות ישראל שיהו בודקות עצמן שחרית וערבית שחרית להכשיר טהרות של לילה וערבית להכשיר טהרות של יום","וזו הואיל ולא בדקה הפסידה עונה מאי עונה עונה יתירה","א\"ל רב פפא לרבא והא זימנין משכחת לה ג' עונות במעת לעת השוו חכמים מדותיהן שלא תחלוק במעת לעת","איבעית אימא שלא יהא חוטא נשכר","מאי בינייהו איכא בינייהו דאתניסה ולא בדקה","כל אשה שיש לה וסת [וכו'] לימא מתני' ר' דוסא היא ולא רבנן דתניא ר\"א אומר ארבע נשים דיין שעתן בתולה מעוברת מניקה וזקנה ר' דוסא אומר כל אשה שיש לה וסת דיה שעתה","אפילו תימא רבנן עד כאן לא פליגי רבנן עליה דר' דוסא אלא שלא בשעת וסתה אבל בשעת וסתה מודו ליה ומתניתין בשעת וסתה ודברי הכל","מכלל דר' דוסא אפילו שלא בשעת וסתה אמר מאן תנא להא דת\"ר אשה שיש לה וסת כתמה טמא למפרע שאם תראה שלא בשעת וסתה מטמאה מעת לעת","נימא רבנן היא ולא רבי דוסא אפילו תימא רבי דוסא ע\"כ לא פליג רבי דוסא עלייהו דרבנן אלא בשעת וסתה אבל שלא בשעת וסתה מודי להו ומתניתין בשעת וסתה ור' דוסא היא"],[[0,"שאני אומר כו'","אבל בקופה הא נמצא שרץ לתוכה ושעת מציאתה טמאה היא:"],[1,"עורב אייתי ושדא","לאחר שטלטל הקופה לזוית אחרת ובזוית הראשונה לא היה:"],[2,"מכדי האי ככר ספק טומאה הוא","ספק נגע ספק לא נגע אבל אקופה לא פריך דהא לא איתחזיק טומאה בזוית של בית הראשון. וכי היכי דפריך אככר מצי למיפרך אמחט ואמטלית ולשנויי כדמשני:"],[2,"שאין בו דעת לישאל","אם נגע אם לא נגע:"],[2,"ספקו טהור","דהא קיימא לן ספקו טמא ברה\"י משום דגמרינן מסוטה שסוטה יש בה דעת לישאל אם נטמאה אם לאו:"],[3,"בטומאה דרבנן","כגון הנך מעלות דחומר בקדש (חגיגה כ:) בגדי פרושין מדרס לאוכלי תרומה (שם יח:) ומש\"ה אפילו ברה\"י ספקו טהור:"],[3,"עלה נדף","דבר הקל ה\"נ טומאה קלה. אית דאמרי מדף עליונו של זב ושבוש הוא דעליונו של זב מטמא ככר מן התורה בפרק בנות כותים (לקמן נדה דף לב:) נתקו הכתוב מטומאה חמורה לטומאה קלה לומר לך דאינו מטמא אלא אוכלין ומשקין ומעיקרא כי אותביניה הכי הוה ס\"ד דעליונו של זב הוא:"],[4,"שהפריז","שהגדיל והרחיב מדתו שטמאה למפרע מפקידה לפקידה:"],[8,"איידי דתנא מעת לעת ממעטת על יד מפקידה לפקידה","דאיצטריך למיתניה דלא תימא עם סילוק ידיה ראתה באחד בשבת תנא נמי כו':"],[9,"מאי טעמא דרבנן","מאי האי שיעורא דמעת לעת דבשלמא מפקידה לפקידה דהלל ניחא דשמא עם סילוק ידיה ראתה אלא מעת לעת מאי שיעורא הוא:"],[9,"אשה מרגשת בעצמה","ואם איתא דעם סילוק ידיה ראתה הות מרגשת:"],[9,"אם כן","דאשה מרגשת:"],[9,"תהא דיה שעתה","ואפילו מעת לעת אמאי מטמא למפרע:"],[10,"חכמים תקנו להן וכו'","מתני' היא (לקמן נדה יא.) פעמים היא צריכה להיות בודקת כו':"],[10,"שחרית","להכשיר טהרות של לילה להוציא מכלל ספק טומאה שאם תמצא טהורה תדע שלא ראתה בלילה ולכשתמצא ערבית טמאה יצאו אלו מספק:"],[11,"וזו","שבדקה עכשיו ומצאה טמאה והרי ימים רבים שלא בדקה:"],[11,"הפסידה עונה","כל טהרות שנתעסקה בהן בעונה הזאת הפסידוה:"],[11,"מאי עונה","הרי שתי עונות הן היום והלילה דהיינו מעת לעת כגון אם מצאה ערבית טמאה הפסידוה כל טהרות של יום ושל אמש:"],[11,"ומשני עונה יתירה","הפסידוה משום קנס שהרי הפסידוה טהרות של אמש משום קנס אבל טהרות של יום לאו קנס הוא דאי נמי בדקה שחרית ומצאתה טהורה וערבית ומצאתה טמאה הפסידה טהרות של יום דהיינו מפקידה לפקידה ממעטת על יד מעת לעת:"],[12,"ג' עונות","כגון אם לא בדקה ימים רבים ובדקה בצהרים דמטמאין לה מעת לעת דהוה להו ג' עונות היום אמש ואתמול למפרע עד צהרים והשתא קנסינן לה שתי עונות ורבנן חדא הוא דקנסו ותו לא:"],[12,"ומשני חכמים השוו מדותיהם שלא תחלוק במעת לעת","זמן קבוע וחלוט נתנו לה למפרע ואפילו עשתה אותו זמן מג' עונות כגון שבדקה בצהרים ולא בדקה שחרית ואמש לא רצו לגרוע ולמעט זמנה הקבוע לה אלא פסקו דבריהם שלא תתן דברים לשיעורין:"],[13,"אב\"א","להכי מטמינן לה מצהרים דאתמול דאי אמרת לא נקנס אלא עונה יתירה נמצא חוטא נשכר דאילו זו שלא בדקה עצמה ימים רבים ובדקה לה היום שחרית היתה נקנסת מעת לעת שלם ומפני שאיחרה עד הצהרים והוסיפה לחטוא לא תפסיד אלא לילה וחצי יום:"],[14,"דאיתניסה","שנאנסה שחרית ולא בדקה ללישנא דחוטא נשכר ליכא דהא נאנסה ללישנא דלא תחלוק איכא:"],[15,"ד' נשים דיין שעתן","מפני שדמיהן מסולקים ואין דם מצוי בהן:"],[15,"בתולה","בתולת דמים שלא ראתה דם מימיה ואפילו היא נשואה קרי לה בתולה והכי מפרש במתני' וכולה מפרש במתני':"],[15,"רבי דוסא אומר כו'","ופליגי רבנן בעלמא עליה:"],[16,"אלא שלא בשעת וסתה","דכיון דראתה שלא בזמנה איכא למיחש דלמא מקמי הכי הוה דהא ליכא למימר אורח בזמנו בא:"],[17,"כתמה טמא למפרע","עד שעת הכבוס. אף על גב דבראייתה דיה שעתה מטמאינן כתמה למפרע דהא אשכחינן בראייה טומאה למפרע שאם תראה שלא בשעת וסתה מטמאה למפרע:"],[18,"לימא רבנן היא","דאמרי שלא בשעת וסתה מטמאה למפרע:"]],[[1,"","הכא נמי נימא עורב אתא ושדא. אף על גב דאדם שנשתמש בקופה יש בו דעת לישאל מכל מקום פריך כיון דעל ידי תליית אדם טהור אין אתה חושבו ספק אף על גב שהנפילה נראה יותר אם כן הרבה מצוי הוא שאדם טהור בא לשם הכא נמי נימא אתא עורב ושדא ולא הוי ספק:"],[3,"","ואיבעית אימא בטומאה דרבנן. לא בא לתרץ דאפילו אי הוי דבר שיש בו דעת לישאל דאתי שפיר דמה לו לתרץ זה כיון דאמת הוא דככר ומדף אין בהם דעת לישאל אלא מתרץ אפי' אין לתלות באדם טהור כמו בנפילה לפי שהנפילה קרובה לודאי כמו שסובר המקשה אתי שפיר דאיירי בטומאה דרבנן ואיירי בבגדי עם הארץ לפרושים ורש\"י דפי' בבגדי פרושים דהוי מדרס לאוכלי תרומה נראה שסובר שעתה בא לתרץ אפי' בשיש בו דעת לישאל ולכך לא רצה לפרש בבגדי ע\"ה לפרושים משום דהתם לא היינו מקילין כדאמרינן בשבת פ\"ק (דף טו:) דעל ו' ספיקות שורפין את התרומה וחשיב בגדי ע\"ה דעל ודאי מגען שורפין ועל ספק מגען תולין (וחשיב בגדי ע\"ה):[ולפי שיטתו היה יכול לפרש דס\"ד דמקשה דמדף היינו בגדי עם הארץ ושמא לא פירש כן משום דבת\"כ איקרי מדף עליונו של זב וכן במסכת זבין פ\"ה [מ\"ב] ובעדיות פ\"ו [מ\"ב]:]"],[15,"","כל אשה שיש לה וסת דיה שעתה. תימה למה הפסיק ושנה המשמשת בעדים ה\"ל למיתני מיד כיצד דיה שעתה וי\"ל דקמ\"ל אע\"ג דיש לה וסת צריכה לשמש בעדים כדאמר בגמרא אע\"ג דתנן לקמן (נדה דף יא.) אע\"ג שאמרו דיה שעתה צריכה בודקת הכא תנא ליה לאשמועינן דאותה בדיקה חשובה היא למעט מעת לעת דהוי חדוש כדאמרי' בגמרא ודלקמן היינו בד' נשים דדיין שעתן והא דמשמע הכא דאפי' אותן דדיין שעתן צריכין בדיקה ובשילהי בנות כותים (לקמן נדה דף לח:) תנן דכל י\"א שבין נדה לנדה הרי היא בחזקת טהרה ומפרש בגמרא דאינה צריכה בדיקה ואפ\"ה קאמר התם דמטמא מעל\"ע בע\"ה אפרש לשם:"]]],[["וברייתא דברי הכל","ולוקמא איפכא","כיון דאיכא לאוקומי לקולא ולחומרא לחומרא מוקמינן","קתני שאם תראה שלא בשעת וסתה מטמאה מעת לעת טעמא דאשה שיש לה וסת הוא דפליגי רבנן בין כתמה לראייתה","הא שאר נשים שאמרו חכמים דיין שעתן כתמן כראייתן","מני רבי חנינא בן אנטיגנוס היא דאמר רב יהודה אמר שמואל משום רבי חנינא בן אנטיגנוס כל הנשים כתמן טמא למפרע ונשים שאמרו חכמים דיין שעתן כתמן כראייתן חוץ מתינוקת שלא הגיע זמנה לראות שאפילו סדינין שלה מלוכלכין בדם אין חוששין לה","ומי אית ליה לרבי חנינא כתם כלל והתניא כל הנשים כתמן טמא ונשים שאמרו חכמים דיין שעתן כתמן טמא ר' חנינא בן אנטיגנוס אומר נשים שאמרו חכמים דיין שעתן אין להן כתם מאי לאו אין להן כתם כלל לא אין להן כתם למפרע אבל יש להן כתם מכאן ולהבא","מכלל דתנא קמא סבר אפי' למפרע אין ר\"מ היא דמחמיר גבי כתמים דתניא כל הנשים כתמן טמא למפרע ונשים שאמרו חכמים דיין שעתן כתמן טמא למפרע דר\"מ","רבי חנינא בן אנטיגנוס אומר נשים שאמרו חכמים דיין שעתן כתמן כראייתן ותינוקת שהגיע זמנה לראות יש לה כתם ושלא הגיע זמנה לראות אין לה כתם ואימתי הגיע זמנה לראות משהגיעו ימי הנעורים","והמשמשת בעדים כו' אמר רב יהודה אמר שמואל עד שלפני תשמיש אינו ממעט כפקידה","מ\"ט אמר רב קטינא מתוך שמהומה לביתה וכי מהומה לביתה מאי הוי מתוך שמהומה לביתה אינה מכנסת לחורין ולסדקין","תנן המשמשת בעדים הרי זו כפקידה מאי לאו חד לפני תשמיש וחד לאחר תשמיש לא אידי ואידי לאחר תשמיש ואחד לו ואחד לה כדתנן דרך בנות ישראל משמשות בשני עדים אחד לו ואחד לה","האי מאי אי אמרת בשלמא חד לפני תשמיש וחד לאחר תשמיש איצטריך סד\"א מתוך שמהומה לביתה לא בדקה שפיר קמ\"ל הרי זו כפקידה אלא אי אמרת אידי ואידי לאחר תשמיש פשיטא","מהו דתימא שמא תראה טפת דם כחרדל ותחפנה שכבת זרע קמ\"ל","ואיבעית אימא שתי בדיקות אצרכוה רבנן חד לפני תשמיש וחד לאחר תשמיש וכי קתני הרי זו כפקיד' אלאחר תשמיש והא המשמשת קתני תני ומשמשת","ממעטת על יד מעת לעת השתא מעת לעת ממעטת"],[[1,"ולוקמא איפכא","כדאוקמיה מעיקרא ומ\"ט הדרי בה הא שפיר מצי לאוקמי מתני' דברי הכל וברייתא רבנן:"],[2,"לקולא ולחומרא","מעיקרא אוקימנא לקולא דבשעת וסתה דברי הכל דיה שעתה ובשלא בשעת וסתה פליגי והשתא אוקימנא פלוגתא בשעת וסתה ואיכא דמחמיר ומטמא לה למפרע ושלא בשעת וסתה ד\"ה מטמאה למפרע:"],[3,"קתני שאם תראה","כמו אמר מר:"],[3,"שאם תראה כו'","אלמא דטעם דכתמה מטמא למפרע משום דאשכחן בהו ראייה טמאה למפרע דהשתא לא הוה כתמה חמור מראייתה וש\"מ דאשה דיש לה וסת הוא דפלוג רבנן בין כתמה לראייתה דכתמה מטמא למפרע ובראייתה דיה שעתה משום דבראייתה שלא בשעת וסתה אשכחן טומאה למפרע:"],[4,"הא שאר נשים שאמרו חכמים דיין שעתן","כגון ארבע נשים דלא אשכחן בהו ראייה טמא' למפרע כתמן נמי אינו טמא למפרע:"],[5,"כתמן כראייתן","מכאן ואילך טמאות:"],[5,"חוץ מתינוקת כו'","דאפילו מכאן ולהבא נמי לא והא דאמר בתולת דמים כתמן כראייתן דמכאן ולהבא מיהא טמאה היינו כשהגיע זמנה לראות ולא ראתה:"],[5,"מלוכלכין בדם","ולא ידעה אי אתי מגופה אי לא:"],[5,"אין חוששין לה","ואפילו אין לה במה לתלות דבשוק של טבחים לא עברה איכא למימר עברה ולאו אדעתה דהא בגופה אין לתלות כל עיקר דכתמין דרבנן נינהו וכי גזור רבנן בהגיע זמנה דדם מצוי בה אבל בהא לא גזור הואיל ואין בה דמים. ולקמן מפרש איזה הוא זמנה משיגיעו ימי הנעורים שהביאה שתי שערות או בת י\"ב שנה ויום אחד ואע\"פ שלא הביאה שתי שערות:"],[6,"ומי אית ליה לרבי חנינא כתם כלל","בארבע נשים ואפילו מכאן ולהבא:"],[7,"דמחמיר בכתמים","טפי מבראייתה דראיית ארבע נשים הואיל ואין דם מצוי בהן אמרינן השתא אתי ומכי אתי חזיתיה אבל בכתם איכא למימר אי בדקה לחלוק מעיקרא הוה אישתכח:"],[8,"רבי חנינא בן אנטיגנוס אומר נשים שאמרו חכמים דיין שעתן כתמן כראייתן","כלומר נשים שאמרו חכמים דיין שעתן כתמן כראייתן לטמאה מכאן ולהבא:"],[8,"יש לה כתם","מכאן ולהבא אע\"פ שלא ראתה מימיה:"],[9,"אינו ממעט","על יד מעת לעת ועל יד מפקידה לפקידה:"],[10,"שמהומה לביתה","ממהרת לשמש:"],[11,"אחד לו","שמקנח בו בעצמו:"],[13,"ותחפנה שכבת זרע","ואפי' דלאחר תשמיש נמי לא ליהוי כפקידה קמ\"ל:"],[14,"ואי בעית אימא","לעולם חד לפני תשמיש וחד לאחר תשמיש ואפ\"ה הרי זו כפקידה אלאחר תשמיש קאי. וא\"ת עד שלפני תשמיש למה הוזכר מתניתין תרתי קתני ואשמועינן תנא דמתניתין דשני בדיקות אצרכוה רבנן וה\"ק משמשת בעדים כלומר מצוה עליה לשמש בעדים ואע\"פ שיש לה וסת הרי זו כפקידה ההוא דלאחר תשמיש:"],[14,"והא המשמשת קתני","דלאו לשון חובה הוא אלמא חדא קתני ומשום הרי זו כפקידה נקט לה וה\"ק ואשה המשמשת בעדים הרי זו כפקידה ואקמא נמי קאי דאי אבתרא לחודה ראשון למה הוזכר:"],[14,"תני ומשמשת","ותרתי מילי נינהו וה\"ק מצוה עליה לשמש בעדים והרי כפקידה אבתרא וקמא לא נקט ליה אלא לאשמועינן דמצוה לבדוק קודם תשמיש:"],[15,"השתא מעת לעת","דאתמול דזמן ארוך הוא ממעטת פקידה זו דעדים:"]],[[0,"","וברייתא דברי הכל. דשלא בשעת וסתה מטמא למפרע אבל לגמרי לא אתי כרבנן דלדידהו אפי' בשעת וסתה נמי וא\"ת מעיקרא מאי סבר דאמרי' איפכא ולא אמרי' לחומרא ויש לומר דמעיקרא בעי לאוקומי מתניתין ככ\"ע אבל כשהביא הברייתא לא מצי לאוקמי ככ\"ע הדר ביה וקאמר לחומרא:"],[4,"","הא שאר נשים שאמרו חכמים דיין שעתן כתמן כראייתן. משמע שיש להחמיר ביש לה וסת טפי מבד' נשים א\"כ ר' דוסא דאמר ביש לה וסת דיה שעתה כל שכן דאית ליה בד' נשים וקשה דא\"כ לקמן (נדה דף ז:) דפסיק כרבי אליעזר בד' אמאי חשיב הך בהדייהו כיון דרבי דוסא סבר כותיה לא ה\"ל למיחשב דכה\"ג אמרינן לקמן וי\"ל הא דביש לה וסת כתמה טמא למפרע לאו משום דחמיר טפי מד' נשים אלא משום דגזור בשעת וסתה אטו שלא בשעת וסתה אע\"ג דבראייה לא גזרינן:"],[7,"","ר\"מ היא דמחמיר בכתמים. פירש\"י דמחמיר בכתמים טפי מבראייה ואין נראה דא\"כ מה לו להש\"ס להאריך ולומר דמחמיר בכתמים הוה ליה למימר ר\"מ היא דתניא וכו' ולא יותר ותו דבסמוך תניא הרואה כתם מקולקלת למנינה וברואה דם אינה מקולקלת למנינה אלמא שאר תנאים נמי אחמירו טפי בכתמים מבראייה ואע\"ג דהך ברייתא כר\"מ דקתני מטמאה את בועלה למפרע ובפרק כל היד (לקמן נדה דף טו.) אמרינן דוקא לר\"מ מטמאה בועלה למפרע מכל מקום הא דמקולקלת למנינה מיהו אתי ככ\"ע וכן שילהי בא סימן (לקמן נדה נג:) תניא הרואה כתם מטמאה עצמה למפרע בקדשים והיינו לענין שמקולקלת למנינה כמו שאפרש שם בע\"ה ונראה לפרש רבי מאיר היא דמחמיר בכתמים שהוא רגיל להחמיר בכתמים טפי מרבנן כדתנן פרק בא סימן (נדה נב:) הרואה כתם חוששין משום זוב דברי ר\"מ וחכמים אומרים אין בכתמים משום זוב ואמרי' התם מאן חכמים ר' חנינא בן אנטיגנוס דמיקל יותר בכתמים כדאמרינן הכא ובכמה דוכתי מחמיר ר\"מ כדאמרינן לקמן (נדה דף נט:) גבי אשה שעושה צרכיה ובפרק כל היד (לקמן נדה דף יד.) אמרינן בדקה בעד [שאין] בדוק לה והניחה בקופסא ולמחר מצאה עליו דם ר\"מ מטמא וחכמים מטהרין ולכך קאמר הכא ר\"מ דמחמיר בכתמים ואע\"ג דבפ' האשה (לקמן נדה דף נט.) תניא השאילה חלוקה לנכרית אינה תולה בנכרית ר\"מ אומר תולה בנכרית אלמא מיקל טפי מרבנן מ\"מ ברוב מקומות מחמיר:"],[7,"","כל הנשים כתמן טמא למפרע ונשים שאמרו כו'. לא זו אף זו קתני:"],[14,"","תני ומשמשת. אף על פי שאמרו דיה שעתה:"],[15,"","השתא מעת לעת ממעטת. פירוש השתא מעת לעת דפשעה ולא בדקה שחרית כי בדקה ערבית ומצאה טמאה בדיקה של צהרים דלאחר תשמיש מיעטה דלא מטמאה מעת לעת כל שכן כשבדקה שחרית ולא פשעה כלום דממעטת דלא מטמאה משחרית:"]]],[["מפקידה לפקידה מיבעיא","מהו דתימא מעת לעת חשו בה רבנן לפסידא דטהרות אבל מפקידה לפקידה לא קמ\"ל","כיצד דיה שעתה וכו' למה לי למיתני היתה יושבת במטה ועסקה בטהרות ליתני היתה עסוקה בטהרות ופרשה וראתה","הא קמ\"ל טעמא דדיה שעתה הא מעת לעת מטה נמי מטמיא מסייע ליה לזעירי דאמר זעירי מעת לעת שבנדה עושה משכב ומושב לטמא אדם לטמא בגדים","מכדי האי מטה דבר שאין בו דעת לישאל הוא וכל דבר שאין בו דעת לישאל ספקו טהור תרגמה זעירי כשחברותיה נושאות אותה במטה דהויא ליה יד חברותיה","והשתא דא\"ר יוחנן ספק טומאה הבאה בידי אדם נשאלין עליה אפי' בכלי מונח ע\"ג קרקע כמי שיש בו דעת לישאל אע\"פ שאין חברותיה נושאות אותה במטה","גופא א\"ר יוחנן ספק טומאה הבאה בידי אדם נשאלים עליה אפי' בכלי המונח על גבי קרקע כמי שיש בו דעת לישאל","מיתיבי היה מתעטף בטליתו וטהרות וטומאות בצדו וטהרות וטומאות למעלה מראשו ספק נגע ספק לא נגע טהור ואם אי אפשר אא\"כ נגע טמא","רשב\"ג אומר אומרים לו שנה ושונה אמרו לו אין שונים בטהרות","אמאי הא ספק טומאה הבאה בידי אדם הוא","בר מיניה דההיא דתני רב הושעיא ברשות היחיד ספקו טמא ברשות הרבים טהור","גופא אמר זעירי מעת לעת שבנדה עושה משכב ומושב לטמא אדם לטמא בגדים","איני והא כי אתא אבימי מבי חוזאי אתא ואייתי מתניתא בידיה מעת לעת שבנדה משכבה ומושבה כמגעה מאי לאו מה מגעה לא מטמא אדם אף משכבה לא מטמא אדם","אמר רבא ותסברא קל וחומר הוא ומה כלי חרס המוקף צמיד פתיל הניצול באוהל המת אינו ניצול במעת לעת שבנדה משכבות ומושבות שאינן ניצולין באהל המת אינו דין שאין ניצולין במעת לעת שבנדה","והא אבימי מבי חוזאי מתניתא קאמר אימא משכבה ומושבה"],[[0,"מפקידה לפקידה","דשחרית היום דזמן מועט מבעיא:"],[3,"טעמא משום דיה שעתה","משום דיש לה וסת הא אם אין לה וסת דמטמיא מעת לעת מטה נמי טמאה כמשכב נדה עצמה שמטמא אדם הנוגע בו טומאה חמורה לטמא בגדים שעליו דכתיב (ויקרא ט״ו:כ״א) וכל (אשר יגע) במשכבה יכבס בגדיו:"],[3,"ה\"ג לטמא אדם לטמא בגדים","שהאדם מטמא בגדים שעליו ואע\"פ שלא נגעו בגדים במטה:"],[4,"מכדי הך מטה דבר שאין בו דעת לישאל הוא","ומעת לעת ספק טומאה הוא וכל שאין בו דעת לישאל כו' דבשלמא אטהרות בלא מטה ניחא דכיון דהיא עסוקה בהן ואוחזתן בידה הוו להו כידה והיא יש בה דעת לישאל אלא מטה כיון דע\"ג קרקע מונחת דלאו בידה הוא וספקו טהור דכל ספק טומאה לטמא מסוטה גמרינן לה וסוטה יש בה דעת לישאל:"],[4,"כשחברותיה נושאות אותה במטה","באותו מעת לעת דהויא ליה הך מטה ביד חברותיה שיש בה דעת לישאל הלכך טמאה:"],[5,"הבאה בידי אדם","כגון זו דטומאה על ידה באה וכגון נושא שרץ בידו ספק נגע בכלי המונח ע\"ג קרקע ספק לא נגע ואע\"פ שאדם לא היה עסוק בכלי המיטמא הואיל והטומאה באה ע\"י אדם ספק נגעה הטומאה בכלי ספק לא נגעה חשבינן לה כמו שיש בה דעת לישאל וברה\"י ספקו טמא:"],[5,"נשאלין","כלומר טמא:"],[5,"כמי שיש בו דעת לישאל","וכי אמרינן דבר שאין בו דעת לישאל ספקו טהור כגון שרץ המוטל אצל כלי ע\"ג קרקע ספק נגע ספק לא נגע:"],[7,"היה מתעטף בטליתו וטהרות בצדו","והוא היה טמא ספק טימא טהרות בטלית כשהגביהו על כתפו ספק לא נגע או טמאות בצדו כגון שרץ והוא טהור ספק נטמא טליתו ספק לא נטמא:"],[7,"טהור","קס\"ד דאפילו ברה\"י משום דהוי דבר שאין בו דעת לישאל ואע\"ג דבאה בידי אדם הואיל וטהרות מונחות על גבי קרקע ואין אוחזן בידו אין נשאלין עליהם:"],[8,"שנה","פעם אחרת אם יגע עכשיו בידוע שנגע בתחלה:"],[8,"אין שונין","שמא עכשיו נגע וקודם לכן לא נגע או חילוף:"],[12,"כמגעה","בכלי שנגעה בו נדה שאינו מטמא אדם שהרי ראשון הוא ואינו מטמא אדם אלא אב הטומאה:"],[12,"אף משכבה לא מטמא אדם","וקשיא לזעירי דאמר משכבה ומושבה מטמא אדם אף לטמא בגדים:"],[13,"כלי חרס","ניצול באהל המת דכתיב (במדבר יט) וכל כלי פתוח אשר אין צמיד פתיל עליו טמא הא יש צמיד פתיל עליו טהור:"],[13,"אינו ניצול","אם הסיט בתוך מעת לעת טמא כאילו הסיטתה לאחר ראייתה כדתניא בברייתא לקמן:"],[13,"אינו דין שאינן ניצולין במעת לעת","שיטמאו כמשכב נדה עצמה אדם ובגדים שעליו:"]],[[3,"","מסייע ליה לזעירי. תימה דממתני' לא שמעינן לטמא אדם ובגדים:"],[4,"","מכדי מטה אין בו דעת לישאל. מטהרות לא פריך דכיון שעסוקין בהן מיקרי שפיר יש בו דעת לישאל כדפירש הקונטרס:"],[4,"","כשחברותיה נושאות אותה במטה. משמע הכא דפשיטא דכיון דחברותיה נושאות אותה במטה דמקרי מטה דבר שיש בו דעת לישאל ותימה לריב\"א דבסוף פ\"ק דפסחים (דף יט.) קאמר ועל המחט שנמצא בבשר שהסכין והידים טהורות ומוקי לה במחט טמא מת וטהורות משום דעזרה רה\"ר הוא אבל אי הוה רה\"י הוה טמא ופריך אמאי והא אין בו דעת לישאל הוא דאמר כרבי יוחנן דאמר ספק טומאה הבאה בידי אדם נשאלין עליה והשתא מאי מקשה התם ומה צריך לאתויי הך דרבי יוחנן דכיון דאדם תופס את הסכין חשוב דבר שיש בו דעת לישאל אפילו בלא רבי יוחנן כדמשמע הכא וי\"ל דהכא חשיב טפי דבר שיש בו דעת לישאל כשחברותיה נושאות אותה במטה משום דנדה נמי המטמאה יש בה דעת לישאל אי נמי משום שגם חברותיה הנושאות גם הם טמאות במשא הנדה אבל התם אין האדם טמא אלא הסכין שנגע במחט והשתא נמי אתי שפיר דפריך בסמוך לרבי יוחנן מהיה מתעטף בטליתו ולא פריך נמי לזעירי משום דאדם התופס הטלית לא דמי לחברותיה שגם הן טמאות ויש בהן דעת לישאל[או משום שהנדה הטמאה יש בה דעת לישאל]:"],[5,"","ספק טומאה הבאה בידי אדם נשאלין עליה ואפילו בכלי המונח ע\"ג קרקע. וא\"ת מאי קמ\"ל רבי יוחנן מתני' היא (טהרות פ\"ג מ\"ח) תינוק שנמצא בצד העיסה כו' דחכמים מטמאין משום דעשו לתינוק כיש בו דעת לישאל אע\"פ שהעיסה אין בה דעת לישאל ובמס' טהרות פ\"ד (מ\"ט) תנן טמא שפשט רגלו לבין המשקין ספק נגע ספק לא נגע טמא ברה\"י עוד תנן התם בסיפא היה מקל בידו ובראשו מלאה משקין טמאין וזרקה לבין הככרות ספק נגע בו טהור וטעמא משום דטומאת משקין לטמא אחרים לאו דאורייתא וה\"ל ספק [לטמא אחרים] דרבנן כדמפרש התם הא לאו הכי ספקו טמא וי\"ל דמצי למימר שהעיסה והמשקין והככרות בידי אדם וקמ\"ל רבי יוחנן אפילו מונחים ע\"ג קרקע או טהרות ביד טהור וטומאה מונחת ע\"ג קרקע:"],[7,"","היה מתעטף בטליתו. פירוש טליתו טמא וטהרות בצדו או טליתו טהור וטמאות בצדו כגון שרץ ואינו יודע אם נגע בו או טומאה וטהרות לפניו וטליתו טהור ואינו יודע אם נגע לטומאה ואח\"כ לטהרות וקמ\"ל דלא הוי ספק ספקא שמא לא נגע הטלית בשרץ ואפילו נגע ספק לא נגע בטהרות דאם נגע בשרץ כמו כן נגע בטהרות:"],[7,"","ואם אי אפשר אא\"כ נגע טמא. וא\"ת פשיטא כיון דאי אפשר ודאי נגע וי\"ל דלאו א\"א כלל קאמר אלא כלומר קרוב לודאי ובתוספתא נמי תניא אם אי אפשר אא\"כ נגע ספקו טמא מדקאמר ספקו טמא משמע דלא הוי ודאי נגע וכן מדקאמר רבן שמעון בן גמליאל אומרים לו שנה דליכא למימר דארישא קאי דקאמר ספקו טהור וקאמר איהו אומרים לו שנה ואם נגע טמא דא\"כ לא הוי פליגי רבנן לומר אין שונין בטהרות דבפרק הרואה (לקמן נדה נח.) אמרינן דדוקא להקל אין שונין אבל להחמיר שונין וכן בריש שחיטת חולין (דף ב:) אמרינן אי אמר ברי לי שלא נגעתי לאו דוקא ברי דעזרה רה\"ר כדאמרינן בפסחים (דף):"],[13,"","ומה כלי חרס שהוא מוקף צמיד פתיל. וא\"ת ונימא דיו כמשכבות דאהל המת דלא מטמא אדם ובגדים או דיו ככלי חרס דמעת לעת ועוד נימא פכין קטנים יוכיחו דטמאים במת וטהורים במעת לעת שבנדה דלא אתו לכלל מגע אף משכבות כמו כן ומיהו רש\"י פי' דהכי עביד ק\"ו ומה כלי חרס שטהור באהל המת טמא במעת לעת שבנדה כמו בנדה עצמה משכבות ומושבות דטמאים באהל המת אינו דין שיטמאו במעת לעת שבנדה כנדה עצמה ומיהו אכתי קשה מה לכלי חרס שכן אין לו טהרה במקוה כדפריך בפ' כשם (סוטה כט:) או שכן מטמא מאוירו וי\"ל טהרות דשאר כלים יוכיחו שאין להם טומאת אויר ויש להם טהרה במקוה וטמאין במעת לעת שבנדה כבנדה עצמה שהם ראשונים דהא פשיטא ליה דאפילו משכבות טמאין במעת לעת כדאמר בברייתא ועביד ק\"ו לטמא אדם ובגדים ולא מצי למיעבד הכי ק\"ו ומה כלי חרס שאינו מטמא מגבו ככל טמאות טמא תוכו במעת לעת שבנדה כנדה עצמה משכבות לא כל שכן כדאמר בפרק בהמה המקשה (חולין עא:) אטו מגבו קאמרינן מתוכו קאמרינן והתם מפורש הפשט:"],[13,"[ה\"ג הניצול באהל המת כו'","תימה הא דאינו ניצול במעת לעת היינו בהיסט דחשיב כאילו נגע בתוכו דמריבויא דמגע אתי ובמגע אהל המת נמי טמא דכך צ\"ל (כר\"ע) דקאמר מה פכין קטנים שטהורים בזב א\"ד שטימא באהל המת נימא כלי חרס המוקף צמיד פתיל יוכיח דהא טהור מן המדרס]:"]]],[["כמגע עצמה מה מגע עצמה מטמא אדם לטמא בגדים אף משכבה ומושבה מטמא אדם לטמא בגדים","תניא כוותיה דרבא הרואה דם מטמאה מעת לעת ומה היא מטמאה משכבות ומושבות אוכלין ומשקין וכלי חרס המוקף צמיד פתיל ואינה מקולקלת למנינה ואינה מטמאה את בועלה למפרע ר' עקיבא אומר מטמאה את בועלה ואינה מונה אלא משעה שראתה","הרואה כתם מטמאה למפרע ומה היא מטמאה אוכלין ומשקין משכבות ומושבות וכלי חרס המוקף צמיד פתיל ומקולקלת למנינה ומטמאה את בועלה ואינה מונה אלא משעה שראתה","וזה וזה תולין לא אוכלין ולא שורפין","ורבא אי שמיע ליה מתניתא לימא מתניתא ואי לא שמיע ליה מתניתא קל וחומר מנא ליה","לעולם שמיע ליה מתניתא ואי ממתניתא הוה אמינא או אדם או בגדים אבל אדם ובגדים לא משום הכי קאמר ק\"ו","אמר רב הונא מעת לעת שבנדה לקדש אבל לא לתרומה אי הכי ליתני גבי מעלות כי קתני היכא דאית ליה דררא דטומאה אבל היכא דלית ליה דררא דטומאה לא קתני","מיתיבי מה היא מטמאה אוכלין ומשקין מאי לאו בין דקדש בין דתרומה לא דקדש","תא שמע רבי יהודה אומר אף בשעת עברתן מלאכול בתרומה והוינן בה מאי דהוה הוה","אמר רב חסדא לא נצרכה אלא לתקן שירים שבפניה","רב הונא מתני לישרוף שירים שבידיה שבדקה עצמה כשיעור וסת","ת\"ש מעשה ועשה רבי כר\"א","לאחר שנזכר אמר כדי הוא ר\"א לסמוך עליו"],[[0,"כמגע עצמה","כנגיעת עצמה. כלומר אדם הנוגע במשכבה בתוך מעת לעת כאילו נוגע בבשר נדה עצמה שהוא ובגדים שעליו טמאים דכתיב (ויקרא טו) וכל הנוגע בה יטמא ותניא בתורת כהנים יכול לא יהא הנוגע בה מטמא בגדים במגע קל וחומר אם משכבה מטמא אדם לטמא בגדים היא עצמה לא כל שכן אם כן למה נאמר כל הנוגע בה יטמא שאינו חוזר ומטמא אדם וכלי חרס:"],[0,"אף משכבה","בתוך מעת לעת:"],[1,"וכלי חרס המוקף כו'","כלומר אפילו הוא מוקף צמיד פתיל שאי אפשר ליגע בתוכו מטמאה אותו בהיסט שהזב והנדה מטמאין כלי חרס בהיסט מה שאין כן בשאר טמאין דכתיב (שם) וכלי חרס אשר יגע בו הזב ישבר ותניא בתורת כהנים יכול יטמא הזב כלי חרס מאחוריו במגע נאמר כאן בו ונאמר להלן וכלי חרס אשר תבושל בו ישבר מה להלן מאוירו אף כאן מאוירו אם כן מה ת\"ל אשר יגע בו והלא אויר כלי חרס טמא בלא נגיעה כדקיימא לן בהכל שוחטין (חולין כד:) תוכו אע\"פ שלא נגע בו אלא איזהו מגעו שהוא ככולו הוי אומר זה היסטו:"],[1,"ואינה מקולקלת למנינה","דהא ודאי מהשתא הויא פתח נדותה וליום שמיני לראייתה יתחילו י\"א יום שבין נדה לנדה ורבנן לא גזור מעת לעת אלא לטהרות אבל גבי כתמים לא ידעינן אימת נפיק מינה ואינה מונה שבעה ימים דקודם טבילה אלא משעה שראתה וכן בכתם לסוף ז' ימים טובלת וטהורה אבל פתח נדותה לידע אימת מתחילין ימי זיבה אבדה עד שתשב ז' נקיים כדתניא בערכין (דף ח.):"],[2,"הרואה כתם מטמאה למפרע","עד שעת כיבוסו של חלוק זה שכבסה קודם לבישה זו:"],[2,"מקולקלת למנינה","אבדה פתח נדותה שאילו היתה יודעת יום ראייתה תהא סופרת אם תראה לאחר שבעה שומרת יום כנגד יום ואם תראה ג' תהא זבה אבל עכשיו שאינה יודעת יום ראייתה אינה יודעת אימתי היא בתוך י\"א יום שבין נדה לנדה והרי היא טועה:"],[4,"ורבא","דפשיטא ליה בכלי חרס לעיל וגמר משכבות מכלי חרס מאי שנא דפשיטא ליה בכלי חרס טפי ממשכב:"],[4,"אי שמיע ליה הא מתניתא","דקתני כלי חרס לימא מתניתא וליפשוט מינה משכבה להדיא:"],[4,"ואי לא שמיע ליה מתניתא קל וחומר מנא ליה","מכלי חרס הא כלי חרס אכתי לא קאמר ליה:"],[5,"אי ממתניתא הוי אמינא","למשכבות דקתני לטמא אדם או בגדים:"],[5,"אבל אדם ובגדים","שהאדם יטמא בגדיו שלא נגעו במשכבות אימא לא קמ\"ל קל וחומר מכלי חרס וה\"ק ומה כלי חרס שניצול באהל המת אינו ניצול במעת לעת שבנדה מלטמא בהיסט כאילו ניסט מנדה עצמה משכבות שאין נצולין באהל המת אינו דין שאין נצולין במעת לעת שבנדה מלטמא כמשכב נדה גמורה:"],[6,"גבי מעלות","בפרק חומר בקדש (חגיגה כ:):"],[6,"","מעת לעת ליכא דררא דטומאה דהשתא הוא דחזאי אלא גזירה בעלמא הוא:"],[7,"מה היא מטמאה","היינו ברייתא דלעיל:"],[7,"לא דקדש","כגון שמן דמנחות ויין דנסכים:"],[8,"אף בשעת עברתן","מתניתין היא (לקמן נדה ד' יא.) אף בשעה שהם מסתלקות ומסיימות לאכול תרומה צריכות לבדוק:"],[9,"לתקן שירים שבפניה","שנגעה בהם ומהניא לה הך בדיקה שאם תמצא עכשיו טהורה לכשתבדוק ערבית כמשפטה ותמצא טמאה לא תטמא למפרע אלא עד שעת בדיקתה ולא תהא התרומה בכלל טומאה דמפרע שהרי בדקה לאחר העברתה. אלמא טומאת מפרע לתרומה נמי גזור:"],[9,"לתקן","דומיא דלהכשיר דאמר לעיל שחרית להכשיר טהרות של לילה כו':"],[10,"ומשנינן רב הונא מתני","להא דרבי יהודה שבדיקה זו באה לשרוף שירים שבידיה אם תמצא טמאה תשרפם וכגון שבודקת עצמה לאחר עברתה לאלתר:"],[10,"כשיעור וסת","מיד סמוך לנגיעה בדיקה דאם תמצא טמאה ודאי בשעת נגיעה נמי טמאה היתה דאפילו חולין נמי מטמו. ומצריך לה ר' יהודה בדיקה לתרומה כשיעור וסת כי היכי דלא תיכול תרומה טמאה לאחר זמן אבל לתקן לא סבירא ליה לרב הונא דכל כמה דלא בדקה מיתקנא וקיימא דטומאת מפרע לא גזור ביה רבנן:"],[10,"[כשיעור] וסת","מפרש בפ\"ב (לקמן נדה יד:) משל לשמש ועד שעומדין בצד המשקוף ביציאת השמש נכנס העד ולשון וסת היינו מיד:"],[11,"מעשה ועשה רבי כר' אליעזר","באשה ילדה שעברו עליה שלש עונות של שלשים יום שלא ראתה ואמר רבי אליעזר במתניתין (לקמן נדה ז:) כל אשה שעברו עליה שלש עונות דיה שעתה ופליגי רבנן עליה דאין דיה שעתה אלא שעברו עליה ג' עונות מחמת זקנה סמוך לזקנתה:"],[12,"לאחר שנזכר","שלא יפה עשה:"]],[[2,"","ואינה מונה אלא משעה שראתה. תימה פשיטא כיון דמקולקלת למנינה משעת כיבוס ואינה יודעת מתי ראתה אם כן לא תוכל לספור ז' ימים ולטבול אלא מיום מציאת הכתם וי\"ל דמיירי שראתה יום אחד או ב' ימים אחר מציאת הכתם וקמ\"ל דאינה מונה מיום מציאת הכתם אלא מיום שראתה דאימר לאו מגופה אתא אלא מעלמא:"],[5,"[ואי ממתניתא ה\"א או אדם או בגדים","הקשה השר היכי מצי למימר או אדם או בגדים והא ברייתא דקתני אבימי קתני משכבה ומושבה כמגעה והשתא מגעה לא מטמא לא אדם ולא בגדים ואי במגע עצמה מטמאה אדם ובגדים. גי']:"],[6,"","אבל היכא דליכא דררא דטומאה לא קתני. וא\"ת ליתני ליה במעלות אחרונות דאמרינן התם (חגיגה דף כא:) חמש קמייתא אית להו דררא דטומאה דאורייתא איתנהו בין בקדש ובין בחולין שנעשו על טהרת קדש בתרייתא דלית להו דררא דטומאה דאורייתא איתנהו בקדש כו' ופי' דאית להו דררא דטומאה דאורייתא כלומר שייכי בטומאה הנוהגת בחולין דאורייתא אבל בתרייתא לא שייכי כלל בטומאה דאורייתא הנוהגת בחולין אבל אין לפרש דרישא קתני טומאה דאורייתא וסיפא טומאה דרבנן דהא קתני בקמייתא בגדי אוכלי תרומה מדרס לאוכלי קדש דהוי דרבנן ובבתרייתא נמי קתני צירוף ורביעי בקדש דהוי דאורייתא וי\"ל דמעת לעת לית ליה אפילו דררא דטומאה דרבנן וא\"ת והא מעת לעת אפילו בחולין טמא כשנעשו על טהרת הקדש כדאמר בסמוך קבלה מיניה רב שמואל ברבי יצחק בחולין שנעשו על טהרת הקדש והנך בתרייתא ליתנהו בחולין שנעשו על טהרת הקדש ואית להו דררא דטומאה טפי כדפרישית וי\"ל לפי שרגילות הוא קצת שנעקר הדם לפני ראייתה לכך גזרו רבנן אף בחולין שנעשו על טהרת הקדש ואף לתרומה לאיכא דאמרי ומכל מקום לית להו דררא דטומאה משום דבשעה שעוסקין בטהרות אין שם ספק טומאה ואין לה להניח ולפרוש מלעסוק בטהרות שאינה יודעת מתי תראה אחרי כן:"],[7,"","מאי לאו בין דקדש בין דתרומה. וא\"ת ואמאי לא פריך ממתני' דמטמאה מעת לעת ונימא מאי לאו בין דקדש בין דתרומה וי\"ל דפריך מהכא משום דנחית לפרושי אוכלין ומשקין והוה ליה לפרושי גם דקדש ואם תאמר ואמאי לא מייתי סייעתא מדתניא בפרק בא סימן (לקמן נדה נג:) דמטמאה עצמה וקדשים למפרע דמשמע קדשים ולא תרומה וקשה לאיכא דאמרי אף לתרומה וי\"ל דנקט התם קדשים משום דרשב\"א פליג התם אף בקדשים:"],[10,"","כשבדקה עצמה כשיעור וסת. לאו בדיקה לגמרי קאמר דבדיקה הויא לחורין ולסדקין כדאמר פרק כל היד (לקמן נדה דף יד:) דהויא טפי משיעור. וסת אלא כלומר קנחה עצמה והוה מצי למימר בדיקה ממש לתלות דאפילו אחר זמן הוי ספיקא דאורייתא דמחייב לקמן בכל היד (שם) אשם תלוי ואפילו למאן דפטר היינו משום דבעי חתיכה משתי חתיכות אבל ספיקא דאורייתא משוי לה אלא דניחא ליה למנקט שיעור וסת ולשרוף (הג\"ה. אף ברה\"ר דבשמעתין של פרוזדור מוכיח דאין חילוק בין רה\"ר לרה\"י לטומאה דאתא מגופה) אבל לאחר זמן אע\"ג דהוה ספק דאורייתא אין שורפין כדאמר בשמעתין דפרוזדור ולקמן בפרק האשה (נדה דף ס:) אמרינן כל שבעלה באשם תלוי טהרותיו תלויות וכל שבעלה בחטאת טהרותיו טמאות ואיכא דאמרי כל שבעלה בחטאת טהרותיו תלויות אבל טמאות לא הוו:"]]],[["בשעת הדחק והוינן בה מאי לאחר שנזכר אילימא לאחר שנזכר דאין הלכה כרבי אליעזר אלא כרבנן בשעת הדחק היכי עביד כותיה","אלא (לאו) דלא איתמר הלכתא לא כמר ולא כמר וכיון שנזכר דלאו יחיד פליג עליה אלא רבים פליגי עליה אמר כדי הוא רבי אליעזר לסמוך עליו בשעת הדחק","אי אמרת בשלמא לתרומה היינו דהואי תרומה בימי רבי אלא אי אמרת לקדש קדש בימי רבי מי הואי","כדעולא דאמר עולא חבריא מדכן בגלילא הכא נמי בימי רבי","ת\"ש מעשה בשפחתו של רבן גמליאל שהיתה אופה ככרות של תרומה ובין כל אחת ואחת מדיחה ידה במים ובודקת באחרונה בדקה ומצאה טמאה ובאת ושאלה את רבן גמליאל ואמר לה כולן טמאות אמרה לו רבי והלא בדיקה היתה לי בין כל אחת ואחת אמר לה א\"כ היא טמאה וכולן טהורות","קתני מיהת ככרות של תרומה מאי תרומה תרומת לחמי תודה תרומת לחמי תודה באפיה מאי בעיא","דאפרשינהו בלישייהו וכי הא דאמר רב טובי בר רב קטינא לחמי תודה שאפאן ד' חלות יצא והוינן בה והא בעינן ארבעים למצוה","והא בעינן אפרושי תרומה מינייהו וכי תימא דמפריש פרוסה מכל חד וחד אחד אמר רחמנא שלא יטול פרוסה ואמרינן דאפרשינהו בלישייהו הכא נמי דאפרשינהו בלישייהו","ת\"ש שוב מעשה בשפחה של רבן גמליאל שהיתה גפה חביות של יין ובין כל אחת ואחת מדיחה ידיה במים ובודקת ובאחרונה בדקה ומצאה טמאה ובאת ושאלה לרבן גמליאל ואמר לה כולן טמאות אמרה לו והלא בדיקה היתה לי בין כל אחת ואחת אמר לה אם כן היא טמאה וכולן טהורות","אי אמרת בשלמא חדא דקדש וחדא דתרומה היא היינו דהדרה ושיילה אלא אי אמרת אידי ואידי דקדש למה לה למהדר ולשייליה מעשה שהיה בשתי שפחות היה","לישנא אחרינא אמרי לה אמר רב הונא מעת לעת שבנדה מטמאה בין לקדש ובין לתרומה ממאי מדלא קתני לה גבי מעלות א\"ל רב נחמן והא תני תנא לקדש אבל לא לתרומה","קבלה מיניה רב שמואל בר רב יצחק בחולין שנעשו על טהרת קדש ולא בחולין שנעשו על טהרת תרומה","תנן התם נולד לה ספק טומאה עד שלא גלגלה תעשה בטומאה משגלגלה תעשה בטהרה","עד שלא גלגלה תעשה בטומאה חולין נינהו ומותר לגרום טומאה לחולין שבארץ ישראל משגלגלה תעשה בטהרה חולין הטבולין לחלה כחלה דמו ואסור לגרום טומאה לחלה","תנא"],[[0,"בשעת הדחק","שני בצורת היו ולא רצה להפסיד טהרות:"],[1,"אלא רבים פליגי עליה","ובטלין דברי היחיד והתחיל להתחרט ואמר כדי הוא כו':"],[2,"קדש בימי רבי מי הוה","כמה שנים היה אחר החורבן בסוף התנאים:"],[3,"חבריא מדכן בגלילא","חבירים שבגליל מטהרים יינם לנסכים ושמנן למנחו' שמא יבנה בהמ\"ק בימיהם ולעול' קדש הוו. כך שמעתי בחומר בקדש וכך היא שנויה:"],[4,"כולן טמאות","משום מעת לעת שבנדה:"],[4,"היא טמאה","משום פקידה לפקידה:"],[5,"תרומת לחמי תודה","ארבע חלות מד' מינין שבתודה נותנין לכהן דכתיב (ויקרא ז׳:י״ד) והקריב ממנו אחד מכל קרבן תרומה וגו':"],[5,"באפיה מאי בעיא","הא מ' חלות בעי לה למיפא והדר אפרושי ד' לתרומה וארבעין לא מיקרו תרומה:"],[6,"ומשני דאפרשינהו בלישייהו","לעולם מאי תרומה תרומת לחמי תודה ודקאמר באפיה מאי בעיא כגון שהפריש לד' מהארבעים חלות בעיסתן ולאחר אפיית כולן שחט תודה עליהן:"],[6,"שאפאן ד' חלות","עשר עשרונים של חמץ אפאן כולן בחלה אחת וג' עשרונות ושליש שבחלות מצה אפאן בחלה אחת וכן של רקיקין וכן של רבוכה:"],[6,"הא בעינן מ'","במנחות ילפינן לה בפרק התודה (מנחות דף עו.) ואמאי יצא:"],[6,"ומשני למצוה","אבל עיכובא ליכא:"],[7,"והא בעי אפרושי תרומה","אחת מכל מין דהיינו א' מעשר וכיון דליכא עשר היאך יפריש:"],[7,"וכ\"ת דמפריש פרוסה מכל","חלה מעט לכהן:"],[7,"אחד אמר רחמנא","והקריב ממנו אחד מכל קרבן וגו' ודרשינן במנחות (דף עז:) שלא יטול פרוסה לתרומת כהן:"],[7,"דאפרשינהו בלישייהו","נטל אחד מעשר לתרומה ותשע הנותרים לבעלים מכל מין ומין אפה בחלה אחת:"],[8,"גפה","סותמת בטיט בידיה ומדיחה ידיה מן הטיט:"],[11,"קבלה מיניה רב שמואל","להך תיובתא מרב נחמן ואוקמא להא דקתני לקדש אבל לא לתרומה הכי קאמר בחולין שנעשו על טהרת קדש כו' אבל בתרומה ממש נהגא:"],[11,"נולד לה גרסי'","נולד בעיסה ספק טומאה: גלגול בחולין זהו גמר מלאכה לחלה:"],[12,"תעשה בטומאה","אם ירצה יטמאנה ביד דסוף סוף חלת ספק היא ולא תאכל:"],[13,"תעשה בטהרה","בכלים טהורים ואל יטמאנה ביד ואע\"פ דסוף סוף חלתה אסורה אסור לטמאה ביד הואיל ונגמרה מלאכתה לחלה אסור לגרום לה טומאה ודאית דכתיב ואני נתתי לך את משמרת תרומותי ודרשינן בבכורות (דף לד.) שתי תרומות במשמע טהורה ותלויה ואמר קרא שומרנה:"]],[[0,"","בשעת הדחק. פירש רש\"י בשני בצורת ולא דק דבפירקין (לקמן נדה דף ט:) אמר דאפי' רבנן מודו בשני בצורת וי\"ל דהאי בשעת הדחק היינו אדם שנגע במעת לעת שבנדה ועשה מעט טהרות לפני ראייתה ואחר הוראתו עסק בטהרות הרבה ולא דמי לשני בצורת כיון דמקודם לכן לא היתה שעת הדחק ואפיש בטהרות ע\"י הוראת טעות ועוד י\"ל שעת הדחק שהשואל הלך לו והיה טורח גדול לרדוף אחריו כדאמר בפרק אע\"פ (כתובות דף ס:) רהט אבתריה תלתא מילי בחלא ולא אדרכיה:"],[6,"","דאפרשינהו בלישייהו. אף על גב דאין הלחם קדוש אלא משקרמו פניו בתנור ונשחט עליו הזבח (מנחות עח:) מ\"מ קרי להו תרומה לפי שיחדו אותה לקרות לה שם תרומה לאחר אפייה ושחיטת הזבח והיתה מופרשת בלישייהו ולא לאחר אפייה משום דבעודה עיסה יכול לעשותה עבות ונאות ונראה דקדושת (הפת) איכא עלייהו ואסור לשנותה בחלות אחרות כדמשמע סוף פרק קמא דנדרים (דף יב.) כחלת אהרן ובניו וכתרומתו מותרין ודייק הא כתרומת לחמי תודה אסור ומוקי דאפרשינהו בלישייהו ומדאסר הככר שהתפיס בלחמי תודה משמע דאיכא עליה קדושת הפת בעודה עיסה:"],[8,"","בשפחתו של ר\"ג. פירש רשב\"ם דהיינו ר\"ג הזקן דאמרינן בשילהי פ\"ק דשבת (ד' טו.) הלל ושמעון גמליאל ושמעון נהגו נשיאותן לפני הבית ק' שנה ומיהו אין רגילות להזכיר סתם ר\"ג אלא ר\"ג הזקן ויכול להיות שזהו ר\"ג דיבנה חבירו של רבי אליעזר ורבי יהושע:"],[12,"","נולד לה ספק טומאה עד שלא גלגלה. פירוש נולד לה ספק טומאה הנוהגת אף בחולין קודם גלגול יכול לגרום לה טומאה ודאית ואין לאסור משום משמרת תרומותי דקודם גלגול אכתי לא פתיכא ביה חלה כמו המפריש חלתו קמח דלא עשה ולא כלום והפסד כהן נמי ליכא כיון דנולד לה ספק טומאה כבר משגלגלה תעשה בטהרה פירוש אם לאחר גלגול נולד לה ספק טומאה דלא שייך בחולין אלא בחלה תעשה בטהרה אע\"ג דחלתה תלויה וליכא הפסד כהן אסור לגרום לה טומאה משום משמרת תרומותי וה\"ה דאפי' נולד לה ספק טומאה דשייכא אף לחולין דאסור לגרום טומאה אלא דמפרש בברייתא איזה ספק אמרו בספק חלה דאפילו בספק טומאה דלא שייכא בחולין חלתה תלויה ואשמועינן חולין הטבולין לחלה כחלה דמו אבל אין לפרש דרישא נמי שנולד לה ספק טומאה עד שלא גלגלה איירי נמי בספק חלה דהיינו בטומאה דלא שייכא בחולין ואע\"ג דעדיין טהורה גמורה היא תעשה בטומאה ודאית דקודם גלגול אכתי לא איקרי טבולה לחלה ולא אסור משום משמרת תרומותי והפסד כהן נמי ליכא שיפריש עליה ממקום אחר דאין נראה דקרי ספק טומאה קודם גלגול כיון שטהורה גמורה היא ואם תאמר דאמר בעבודה זרה פ' רבי ישמעאל (עבודה זרה דף נו. ושם) אין בוצרין עם ישראל העושה פירותיו בטומאה ויש פירוש שפירש רש\"י בהם משום דאסור לגרום טומאה לתרומה משום משמרת תרומותי והשתא הלא אין קבע למעשר אלא עד שיקפה או עד שישלה והכא אמר עד שלא גלגלה תעשה בטומאה וי\"ל דהתם אם הפריש אפילו קודם שיקפה או שישלה הוי תרומה כמו בהקדימו בשבלין אבל הכא אם הפריש חלה קודם גלגול הוי כמו הפריש חלתו קמח דאמר בהאיש מקדש (קדושין דף מו:) דלא עשה ולא כלום ולכך לא מיקריא טבולה לחלה (ועל פירוש הקונטרס קשה דבתוספתא דחלה מסיים בה הכי וכן פירות עד שלא נגמרה מלאכתן יעשו בטומאה משנגמרה מלאכתן יעשו בטהרה. גי') אי נמי יש לפרש דהתם נמי לא אסור משום משמרת תרומותי כפירש\"י כיון דאכתי לא הוקבע לתרום אלא משום הפסד כהן אסר לה אבל הכא כבר נולד לה ספק וליכא הפסד כהן ועוד דאפילו לא נולד לה ספק שרי לטמאותה וליכא הפסד כהן דחבר הוא ויפריש עליה ממקום אחר אבל התם איירי בעם הארץ שלא יפריש ממקום אחר וא\"ת דבפרק הניזקין (גיטין דף סא.) תנן משאלת אשה לחברתה החשודה על השביעית נפה וכברה כו' אבל לא תבור ותטחון עמה משאלת אשת חבר לאשת ע\"ה נפה וכברה ובוררת וטוחנת עמה אבל משתטיל למים לא תגע בהם ובעי בגמרא מ\"ש רישא ומ\"ש סיפא אמר אביי בדמאי הקילו ומשתטיל למים דהוכשרו לא תגע בהם אף קודם לישה רבא אמר בעם הארץ דר\"מ וטומאה וטהרה דרבנן ופריך והא מדקתני סיפא משתטיל למים מכלל דרישא מיירי בלא הכשר ומאי טומאה וטהרה איכא ומשני אידי ואידי בהוכשר ורישא בטומאת חולין וסיפא בטומאת חלה ומשתטיל למים היינו לישה וגלגול אלמא אוסר אביי ליגע כי הוכשר לברור ולטחון אף קודם גלגול ולישה אע\"ג דאם הפריש קודם לישה וגלגול לא עשה ולא כלום (וי\"ל) ולדידיה נמי צריך לתרץ דהתם אסור משום הפסד כהן ובשמעתין ליכא הפסד כהן כדפרישית ולרבא דשרי לגרום טומאה קודם גלגול אע\"ג דאיכא הפסד כהן צריך לתרץ אההיא דפרק רבי ישמעאל (ע\"ז דף נו.) כתירוץ ראשון דהתם אסור משום משמרת תרומותי אבל בעיסה קודם גלגול לא מיקריא טבלה לחלה כיון דאם הפריש חלת קמח לא עשה ולא כלום אי נמי כמו שתירץ ר\"ת שם דהתם בגיטין ליכא כי אם חשדא בעלמא אבל ההיא דאין בוצרין מיירי בודאי עושה פירותיו בטומאה ושם יש להאריך:"]]],[["וחלתה תלויה לא אוכלין ולא שורפין באיזה ספק אמרו בספק חלה מאי ספק חלה","אביי ורבא דאמרי תרוייהו שלא תאמר בהוכחות שנינו כמו שני שבילין דהתם חולין גרידא נמי מטמו","אלא בנשען דתנן זב וטהור שהיו פורקין מן החמור או טוענין בזמן שמשאן כבד טמא משאן קל טהור וכולן טהורין לבני הכנסת וטמאין לתרומה","וחולין הטבולין לחלה כחלה דמו והתניא אשה שהיא טבולת יום לשה את העיסה וקוצה הימנה חלתה ומניחתה בכפישה או באנחותא ומקפת וקורא לה שם","מפני שהוא שלישי ושלישי טהור בחולין ואי אמרת חולין הטבולין לחלה כחלה דמו הא טמיתנהו","אמר אביי כל שודאי מטמא חולין גזרו על ספקו משום חולין הטבולין לחלה והאי טבול יום כיון דלא מטמא ודאי חולין לא גזרו עליו משום חולין הטבולין לחלה","והא מעת לעת שבנדה דודאי מטמא חולין ולא גזרו על ספקה משום חולין הטבולין לחלה","דאמר מר קבלה מיניה רב שמואל בר רב יצחק בחולין שנעשו על טהרת קדש ולא בחולין שנעשו על טהרת תרומה","התם לא פתיכא בהו תרומה הכא פתיכא בהו תרומה","ואיבעית אימא הנח מעת לעת דרבנן","\u0001מתני׳\u0002 רבי אליעזר אומר ארבע נשים דיין שעתן בתולה מעוברת מניקה וזקינה אמר רבי יהושע אני לא שמעתי אלא בתולה"],[[0,"וחלתה תלויה","כשעשאה בטהרה משום ספק הנולד לה ראשון:"],[0,"באיזה ספק אמרו","כלומר באיזה ספק הוצרכו לומר חלתה תלויה:"],[0,"בספק חלה","בספק טומאה הנוהגת בחלה ואינה נוהגת בחולין כגון נשען כדמפרש בסמוך דטהור לבני הכנסת ואסור לתרומה ואיצטריך לאשמועינן דאע\"ג דלא נהגא בחולין גרידא הכא כיון דטבולין לחלה נהגא בהן:"],[0,"מאי ספק חלה","כלומר מאי קאמר:"],[1,"שלא תאמר בהוכחות שנינו","בספק טומאה מוכחת:"],[1,"כגון שני שבילין","אחד טמא ואחד טהור ספק הלך בטמא ספק הלך בטהור והא ספקא היא דמהניא בחולין הטבולין לחלה אבל טומאה שאינה מוכחת לא דהא לא איצטריך לאשמועינן דאפילו לחולין גרידא נמי מהני לאוכל חולין בטהרה הלכך מהניא נמי הכא:"],[2,"אלא אפילו בנשען","דהוי ספק טומאה שאינה מוכחת הואיל ותנן לקמן דמהניא לתרומה מהניא נמי לחולין הטבולין לחלה:"],[2,"פורקין","משאוי:"],[2,"טמא","דשמא מתוך כובד המשא נשען זה על הטהור ונמצא טהור מסיטו או טהור ניסט עליו וכתיב במרכב הזב (ויקרא ט״ו:י׳) והנושא אותם וכ\"ש זב בעצמו:"],[2,"וכולן","אפי' משא כבד:"],[2,"טהורין לבני הכנסת","אוכלין חוליהן בטהרה שאין זה היסט גמור וכל שכן שספק הוא:"],[2,"וטמאין לתרומה","מדרבנן ואפי' בספק:"],[3,"וחולין הטבולין לחלה כחלה דמו","דמהני בהו ספק נשען כחלה גמורה:"],[3,"וקוצה לה חלה","שכל זמן שלא קראה שם עליה הרי היא כחולין וטבול יום דינו כשני ואינו עושה שלישי בחולין וכשהיא קוצה לא תקרא לה שם אלא מניחתה לחלה בכפישה או באנחותא הם כלים שאין להם בית קיבול כגון נסרים ואין מקבלין טומאה. ואצרכוה רבנן הני משום היכרא שלא תגע בה שוב מאחר שקראה לה שם ודכוותה אמר בסוף פ' הניזקין (גיטין סב.) ובתשובת רב האי ראיתי אנחותא נסרים לווחין שמנסרין הנגרים ומשפין הלווחין:"],[3,"ומקפת","מקרבתה לכלי אצל העיסה וקוראה לה שם שמצוה לתרום מן המוקף. מוקף סמוך כמו מקיפין שתי חביות במס' ביצה (דף לב:) וכמו אין מקיפין בבועי (חולין מו:) שמקיפין זו לזו לראות אם דומים הם בנקביהן:"],[5,"שודאי מטמא חולין","כמו משא הזב:"],[6,"דודאי","נדה ממש:"],[6,"ספקה","מעת לעת:"],[7,"ולא בחולין שנעשו על טהרת תרומה","וקס\"ד הוא הדין לחולין הטבולין לחלה דהם נמי נעשין בטהרת חלה המעורבת בהן: ומשנינן חולין הטבולין לחלה חמירי מחולין שנעשו על טהרת תרומה דהכא עריבא בהו חלה אבל התם נטירותא יתירתא קביל עליה:"],[8,"פתיכא","מעורבת:"]],[[1,"","שלא תאמר בהוכחות שנינו. פירש\"י כגון שני שבילים ספק הלך בטהור ולדבריו צריך לומר שבאו לשאול בבת אחת דאי בזה אחר זה טהורין ונראה לפרש כי ההיא דתניא בתוספתא דטהרות (פ\"ו) ב' שבילין אחד טמא ואחד טהור והלך באחד מהם ועשה טהרות והלך בשני ועשה טהרות אלו ואלו מוכיחים פירוש מוכיחים לטומאה דאיזה מהם נטהר ומשום לישנא דמוכיחים קאמר הכא בהוכחות שנינו:"],[2,"","וכולן טהורים לבני הכנסת. פרש\"י דקאי אמשאן כבד ואין נראה דבמשאן כבד נראה דטמא אף לחולין דאי אפשר שלא יסוט זה את זה אלא אמשאן קל קאי וכן משמע במס' זבין (פ\"ג מ\"ב) דקתני התם משאן קל טהורין לבני הכנסת וטמאין לתרומה והא דקתני הכא כולן טהורין לבני הכנסת אכל ענינא דטהרה דהתם קאי וא\"ת דהכא קרי ליה בני הכנסת לחברים האוכלין חולין בטהרה ובפרק פסולי המוקדשין (בכורות לו:) גבי מומי בכור קאמר דהתרתם על פי ג' בני הכנסת והתם אפילו ג' הדיוטות כשרים וי\"ל דהכא נמי מזכיר בני הכנסת לגריעותא כלומר שאינם אוכלין תרומה:"],[3,"","ומקפת וקורא לה שם. הכא משמע דאפילו בשעת קריאת שם צריך הקפה וקשה דאמר בסוטה פרק כשם (דף ל.) רבי אליעזר אומר חלה ניטלת מן המוקף מן הטהור על הטמא כיצד ב' עיסות אחת טמאה ואחת טהורה נוטל שיעור חלה מעיסה שלא הורמה חלתה ונותן פחות מכביצה מעיסה טהורה באמצע בין שיעור חלה לעיסה טמאה כדי ליטול מן המוקף והתניא כביצה ומשני הך ברייתא סברה חולין הטבולין לחלה לאו כחלה דמו ולהכי לא אתי כביצה דהוי שני ומטמא לשיעור חלה והשתא מ\"מ קשה כשיקרא לה שם חלה יהיה שלישי אלא משמע דבשעת קריאת שם ירחיק מעט שיעור חלה שלא יגע בכביצה וחשיב שפיר מוקף כיון דלפני קריאת שם היתה מחוברת וי\"ל דהתם מיירי כשיש הרבה מעיסה טהורה ולא שיעור חלה גרידא כדקתני ב' עיסות אחת טהורה ואחת טמאה ורוצה להפריש קצת מן הטהורה כדי לתקן עצמה ואף הטמאה הלכך כיון דחולין הטבולין לחלה לאו כחלה דמו לאו האי ביצה דהוא שני מטמא העיסה הטהורה וכי יפריש ממנה חלה ויקיף לה אין בכך כלום [ועי\"ל דאפילו [בלא] מוקף אפשר שיועיל צירוף סל ובפרק כשם דבעי ר' אליעזר נגיעה משום דמקפיד על נגיעותו משום טומאה אין מועיל צירוף כלי וכן משמע קצת בירושלמי דאמר במסכת חלה בפ\"ב דבר שהוא מקפיד על [חברו] אין הבית מצטרף (נראה במקום בית גרסינן כלי) אינו מקפיד על תערובותו הכלי מצטרף עיסה טהורה ועיסה טמאה עשו אותם כדבר שמקפיד על תערובתו. גי':] והא דפסקינן לקמן כר' אליעזר דאמר הסל מצרפן לחלה ולא בעי נגיעה היינו להתחייב בחלה אם לש פחות מכשיעור דהכי תנא במסכת חלה (פ\"ב מ\"ד) העושה עיסתו קביים ונגעו זה בזה פטורין מן החלה עד שישוכו ר\"א אומר אף הרודה ונותן לסל הסל מצרפן וכן משמע באלו עוברין (פסחים מח:) והשתא אתי שפיר דר\"א גופיה מצריך נגיעה בשעת קריאת שם בפרק כשם (סוטה דף ל.) ונכון בפסח להגיע כל המצות (בסל) כשמפרישין אחת על כולן דאין הסל מצרפן לכך ואע\"ג דאמרינן בפ\"ק דביצה (דף ט.) ובבכורות בפרק עד כמה (בכורות דף כז.) אמרינן תרומת חוצה לארץ אוכל והולך ואח\"כ מפריש אע\"ג דאין מוקף למה שאכל כבר היינו בעיסה שנילושה יחד והיתה כבר מחוברת הקילו בתרומת חוצה לארץ וצ\"ע אי חשוב מוקף בנגיעה גרידא בלא צירוף הכלי או בלא נשיכה דנותן פחות מכביצה באמצע מצינן למימר דהיינו נשיכה:"],[5,"","והאי טבול יום כיון דודאי לא מטמא חולין לא גזרו עליו משום חולין הטבולין. ותימה דהכא משמע דאין שני פוסל בחולין הטבולין לחלה ובברייתא נמי קתני ובשלישי טהור בחולין משמע דכ\"ש דאין שני פוסל בחולין שנעשו על טהרת תרומה כדאמר בסמוך דמשמע דקילי מחולין הטבולין לחלה ובפרק שני דחולין (דף לג:) אמרינן דשלישי נוהג בחולין שנעשו על טהרת תרומה ובפרק כשם (סוטה דף ל.) שהבאתי לעיל מוכח דשני עושה שלישי בחולין הטבולין לחלה למ\"ד כחלה דמו וי\"ל דטבול יום קיל טפי דאין צריך רק הערב שמש והא דתניא בברייתא דשלישי טהור בחולין היינו שלישי דטבול יום אי נמי ה\"פ כיון דשלישי טהור בחולין דעלמא לא גזרו חכמים בחולין הטבולין לחלה ליטמא מטבול יום ולכך פריך מיניה טפי אנשען ולא פריך מיניה אכל שלישי דנוהג בחולין הטבולין לחלה משום דנשען נמי טומאה קלישא הוא ומטמא אפילו משא קל כדפרישית לעיל:"],[9,"","הנח מעת לעת דרבנן. אע\"ג דנשען נמי דרבנן טומאת מעת לעת קיל טפי שאין שום ספק טומאה בשעה שעוסקת בטהרות:"]]],[["אבל הלכה כרבי אליעזר","איזו היא בתולה כל שלא ראתה דם מימיה אע\"פ שנשואה מעוברת משיודע עוברה מניקה עד שתגמול את בנה נתנה בנה למניקה גמלתו או מת ר\"מ אומר מטמאה מעת לעת וחכ\"א דיה שעתה","איזוהי זקנה כל שעברו עליה שלש עונות סמוך לזקנתה רבי אליעזר אומר כל אשה שעברו עליה שלש עונות דיה שעתה רבי יוסי אומר מעוברת ומניקה שעברו עליהן שלש עונות דיין שעתן","ובמה אמר דיה שעתה בראייה ראשונה אבל בשניה מטמאה מעת לעת ואם ראתה הראשונה מאונס אף השניה דיה שעתה","\u0001גמ׳\u0002 תניא אמר לו רבי אליעזר לרבי יהושע אתה לא שמעת אני שמעתי אתה לא שמעת אלא אחת ואני שמעתי הרבה","אין אומרים למי שלא ראה את החדש יבא ויעיד אלא למי שראהו כל ימיו של רבי אליעזר היו עושין כרבי יהושע לאחר פטירתו של רבי אליעזר החזיר רבי יהושע את הדבר ליושנו","כרבי אליעזר בחייו מ\"ט לא משום דרבי אליעזר שמותי הוא וסבר אי עבדינן כוותיה בחדא עבדינן כוותיה באחרנייתא","ומשום כבודו דר\"א לא מצינן מחינן בהו לאחר פטירתו של ר\"א דמצינו מחינן בהו החזיר את הדבר ליושנו","אמר רב יהודה אמר שמואל הלכה כרבי אליעזר בארבע חדא דאמרן","ואידך המקשה כמה תשפה ותהא זבה מעת לעת דברי ר\"א והלכה כדבריו","ואידך הזב והזבה שבדקו עצמן יום ראשון ומצאו טהור יום שביעי ומצאו טהור ושאר הימים לא בדקו רבי אליעזר אומר הרי אלו בחזקת טהרה רבי יהושע אומר אין להן אלא יום הראשון ויום השביעי בלבד","רבי עקיבא אומר אין להם אלא יום שביעי בלבד ותניא ר\"ש ורבי יוסי אומרים נראין דברי רבי אליעזר מדברי רבי יהושע ודברי ר\"ע מדברי כולן אבל הלכה כר' אליעזר","ואידך דתנן אחורי כלים שנטמאו במשקין ר' אליעזר אומר מטמאין את המשקין ואין פוסלין את האוכלין מטמאין את המשקין ואפילו דחולין ואין פוסלין את האוכלין ואפילו דתרומה רבי יהושע אומר מטמאין את המשקין ופוסלין את האוכלין","א\"ר יהושע ק\"ו ומה טבול יום שאין מטמא משקה חולין פוסל אוכלי תרומה אחורי כלים שמטמא משקה חולין אינו דין שפוסל אוכלי תרומה","ורבי אליעזר אחורי כלים דרבנן וטבול יום דאורייתא ורבנן מדאורייתא לא עבדינן קל וחומר דמדאורייתא אין אוכל מטמא כלי ואין משקה מטמא כלי","ורבנן הוא דגזור גזרה משום משקין דזב וזבה משקין דעלולין לקבל טומאה גזרו בהו רבנן אוכלין דאין עלולין לקבל טומאה לא גזרו בהו רבנן","ומאי שנא אחורי כלים דנקט משום דקילי דתנן כלי שנטמא מאחוריו במשקין אחוריו טמא תוכו אזנו אוגנו ידיו טהורין נטמא תוכו כולו טמא","מאי קמ\"ל שמואל בכולהו תנן הלכתא","וכי תימא אחורי כלים קמ\"ל דלא תנן ולימא הלכה כר\"א באחורי כלים אלא הא קמ\"ל שאין למדין הלכה מפי תלמוד","ותו ליכא והאיכא דתנן ר\"א אומר"],[[1,"מתני' וחכ\"א דיה שעתה","עד כ\"ד חדש שהוא זמן הנקת התינוק. ובגמרא מפרש טעמא:"],[2,"שעברו עליה","שלא ראתה:"],[2,"שלש עונות","מפרש לה בגמרא:"],[2,"סמוך לזקנתה","מפרש בגמרא:"],[2,"כל אשה","וה\"ה ילדה:"],[2,"מעוברת ומניקה כו'","אבל לא עברו עליה לא ופליג אדרבי אליעזר ואת\"ק דאמר לעיל מעוברת דיה שעתה משיודע העובר ומניקה משנולד:"],[3,"בראייה ראשונה","שראתה הבתולה או המעוברת או הזקנה לאחר שלש עונות:"],[3,"אבל בשנייה מטמאה מעת לעת","שהרי חזרה לקדמותה להיות דמים מצויים בה:"],[5,"גמ' אין אומרים למי שלא ראה את החדש שיבא ויעיד","שראה:"],[6,"שמותי","לשון שמתא שהרי ברכוהו כדאמרינן בהזהב (ב\"מ דף נט:) הלכך לא עבדינן כוותיה באחרנייתא:"],[7,"דמצינן מחינן בהו","אי עבדי כוותיה באחרנייתא:"],[9,"המקשה","מחמת ולד בתוך אחד עשר יום שבין נדה לנדה וקשתה שלשה ימים רצופין ובכל יום ראתה דם וקי\"ל דאינה זבה מחמת שלשה ימי קישוי ליטען שבעה נקיים וקרבן דכתיב כי יזוב זוב דמה ודרשינן בבנות כותים דמה מחמת עצמה ולא מחמת ולד ואם שפתה מן הצער שעמדה בלא צער לאחר השלשה ימים וילדה נתגלה הדבר למפרע שלא בא הדם מחמת הולד והרי היא יולדת בזוב וצריכה שבעה נקיים לבד ימי טומאת לידה וצריכה שני קרבנות אחד לזוב ואחד ללידה:"],[9,"וכמה תשפה","תעמוד ותנוח מצערה לאחר השלשה של קושי ותהא זבה למפרע מחמת הקושי:"],[9,"מעת לעת","אם שפתה מחצות היום זה עד כעת מחר איכא למימר דלאו משום ולד הוה וקרינן ביה כי יזוב זוב דמה ופליג ר' יהושע עליה בפרק בנות כותים:"],[10,"שבדקו עצמן","כשפסקו מזובן הוצרכו לספור שבעה נקיים בלא ראייה כדכתיב וספר לו וגו' ובדקו עצמן ראשון ושביעי ושאר חמשה ימים שבינתיים לא בדקו:"],[10,"בחזקת טהרה","הואיל ותחלתו וסופו בטהרה וטובל לערב של שביעי:"],[10,"אלא ראשון ושביעי","וצריכין למנות עוד חמשה ימים דחוששים שמא ראו בינתיים ומיהו אי הוה ידעה בודאי שראתה בינתיים סתרה לנקיות הראשון דרחמנא אמר (ויקרא טו) ואחר תטהר אחר אחר לכולן שלא תהא טומאה מפסקת בינתיים אבל השתא חששא היא ומונה לסירוגין:"],[11,"אלא יום שביעי בלבד","דשמא ראתה ימים שבינתיים וסתרה את טהרת יום הראשון דכולהו נקיים בעינן דכתיב ואחר תטהר אחר אחר לכולן שלא תהא טומאה מפסקת בינתיים:"],[11,"מדברי ר' יהושע","שר\"א השוה מדותיו דקסבר כיון דתחלתן וסופן בטהרה מחזקינן נמי לאמצעיים בטהרה אבל רבי יהושע כיון דאמצעיים חייש לטומאה נסתרה טהרת יום ראשון:"],[12,"אחורי כלים","דאמרינן לקמן אחורים טמאין ותוכו טהור דטומאת משקין לטמא כלים דרבנן והכי הוא דגזור שלא יטמא תוכו בנגיעת אחוריו וטעמא מפרש בבכורות עבדו רבנן היכרא בהך טומאה דלידעו אינשי דמדרבנן היא ולא נשרוף עליה תרומה וקדשים:"],[12,"שנטמאו במשקין","ומשקין בשרץ והוו ראשונים ולא מטמו כלים מדאורייתא אלא אב הטומאה ורבנן הוא דגזור:"],[12,"מטמאין את המשקין","מדרבנן דכיון דעלולין לקבל טומאה מיטמו בכל דהו להיות ראשונים ויפסלו את השני בחולין:"],[12,"ואין פוסלין את האוכלין","רבותא קתני דאפילו מפסל לא פסלי כדמפרש טעמא ואזיל:"],[13,"","טבול יום שני הוא ואינו מטמא משקה חולין דקי\"ל כל הפוסל את התרומה מטמא משקה להיות תחלה חוץ מטבול יום וטעמא מפרש בפ\"ק דשבת (דף יד:):"],[13,"אחורי כלים","בטומאת משקין דרבנן דכלי אינו מקבל טומאה מדאורייתא אלא מאב הטומאה בפ\"ק דפסחים (דף יח.):"],[14,"וטבול יום","לפסול אוכלי תרומה דאורייתא כדקיימא לן טבל ועלה אוכל במעשר כו' ומקרא נפקא לן ביבמות (דף עד:) ואפילו בנגיעה:"],[15,"משום משקה זב וזבה","רוקו ומימי רגליו שהן אבות הטומאה כדכתיב (ויקרא ט״ו:ח׳) וכי ירוק הזב וגו':"],[16,"ומ\"ש אחורי כלים דנקט","לינקוט תוכי כלים וכגון דנגעו משקין טמאין לתוכו והוו נמי דרבנן:"],[16,"משום דקילי","אבל תוכי כלים כיון דאחמירו בהו רבנן כדקתני נטמא תוכו כולו טמא מודה רבי אליעזר שפוסלין את האוכלין:"],[18,"הא קמ\"ל","מדאיצטריך למימר להו הלכה שמע מינה דאין למידין הלכה מפי תלמוד מתוך המשנה וברייתא ששנויה בהן הלכה כפלוני אין למידין מהן שהאמוראים האחרונים דקדקו בטעמי התנאים והעמידו הלכה על בוריה אבל הראשונים לא דקדקו איש בדברי חבירו אלא כל אחד מה ששמע מרבו מלמדה לתלמידו שמועה כמו שהיא והיא היתה נקרא משנה וברייתא והיה נותן לבו לתת טעם לשמועתו זה נותן טעם לדבריו וזה נותן בה טעם אחר כדאמר (שבת דף סג.) ליגמר איניש והדר ליסבר ואותה סברא היתה נקראת תלמוד בימי התנאים ומשנה ששנויה בה פסק הלכה מסברת תלמוד שלהן נישנית ואין למידין הימנה:"]],[[6,"","שמותי הוא. פירש\"י שברכוהו וקשה דמסתמא לא היה מזכיר לשון שמתא ובמעשה גופיה דפרק הזהב (ב\"מ דף נט:) אינו מזכיר אלא לשון ברכה ופירש ר\"ת ורשב\"ם דשמותי הוא היינו דהוה מתלמידי שמאי וכן איתא בירושלמי פרק קמא דתרומות דתנן סאה של תרומה טמאה שנפלה לתוך מאה של תרומה טהורה ב\"ש אוסרין ובית הלל מתירין לאחר שהודו א\"ר אליעזר תירום ותשרף מי הודה למי וקאמר ב\"ש לב\"ה א\"ר אסי מתניתין אמרה כן לאחר שהודו אמר ר' אליעזר יתרום ותרום ותשרף ורבי אליעזר לאו שמותי הוה בתמיה וכן מפרש באלפא ביתא דרבי מכיר:"],[6,"","[הקשה הר' ראבי\"ה דבאלו מגלחין (דף טו.) איבעיא לן מנודה מהו בתפילין תיקו ור' אליעזר היה מניח תפילין כדאמר בסוף פ' ד' מיתות (סנהדרין דף סח.) ואין לומר דלא חש לנידוי דהא חלץ מנעליו. פסק. גי':]"],[10,"","רבי אליעזר אומר הרי היא בחזקת טהרה. מכאן משמע אשה שספרה ז' נקיים ובדקה יום ראשון ויום ז' ומצאה טהורה דחשיב ספירה רק שבדקה עצמה יום שפסקה בו לערב והפסיקה בטהרה ודוקא יום ז' אבל יום ח' לא ומיהו לכתחלה [לא מועיל] וצריכה לבדוק בכל יום:"],[16,"","משום דקילי. אבל תוך כלי פוסל אוכלין דתרומה משום דהוי מי\"ח דבר (שבת יג:) האוכלין והכלים שנטמאו במשקין:"]]],[["מלמדין את הקטנה שתמאן בו ואמר רב יהודה אמר שמואל הלכה כר' אליעזר כי אמר שמואל הלכה כר' אליעזר בד' בסדר טהרות אבל בשאר סדרים איכא טובא","וה\"נ מסתברא דתנן ר' אליעזר אומר אף הרודה ונותן לסל הסל מצרפן לחלה ואמר רב יהודה אמר שמואל הלכה כר\"א ש\"מ","ומאי אולמיה דהאי מהאי משום דקאי רבי אלעזר כותיה","דתנן רבי אלעזר אומר מלמדין את הקטנה שתמאן בו","ומי קאי והא אצרכו מצרכינן להו ולא דמיין להדדי אלא משום דקאי רבי יהודה בן בבא כותיה","דתניא רבי יהודה בן בבא העיד ה' דברים שממאנים את הקטנות","ושמשיאין את האשה ע\"פ עד אחד ושנסקל תרנגול בירושלים על שהרג את הנפש ועל יין בן מ' יום שנתנסך ע\"ג המזבח ועל תמיד של שחר שקרב בד' שעות","מאי קטנות לאו חדא דר' אלעזר וחד דר' אליעזר לא מאי קטנות קטנות דעלמא","אי הכי גבי אשה נמי נתני נשים ונימא נשים דעלמא אלא מדהכא קתני אשה והכא קתני קטנות ש\"מ דוקא קתני ש\"מ","וכן א\"ר אלעזר הלכה כר\"א בד' ותו ליכא והתנן רבי אליעזר אומר מלמדין את הקטנה שתמאן בו וא\"ר אלעזר הלכה כר\"א וכי תימא כי א\"ר אלעזר הלכה כר\"א בד' בסדר טהרות אבל בשאר סדרי איכא ומי איכא","והתנן הורד והכופר והלטום והקטף יש להן שביעית ולדמיהן שביעית יש להן ביעור ולדמיהן ביעור וא\"ר פדת מאן תנא קטפא פירא ר\"א","וא\"ר זירא חזי דמינך ומאבוך קשריתו קטפא לעלמא את אמרת מאן תנא קטפא פירא ר\"א ואבוך אמר הלכה כר\"א בד'","ואם איתא לימא ליה כי אמר אבא הלכה כר\"א בד' בסדר טהרות אבל בשאר סדרי איכא","אלא קשיא ההיא משום דקאי רבי אלעזר כותיה דתנן רבי אלעזר אומר מלמדים את הקטנה שתמאן בו","ומי קאי והא אצרוכי מצרכינן להו ולא דמיין להדדי אלא משום דקאי רבי יהודה בן בבא כוותיה","ותו ליכא והתנן ר\"ע אומר אומרה ברכה רביעית בפני עצמה ר' אליעזר אומר אומרה בהודאה וא\"ר אלעזר הלכה כר\"א","א\"ר אבא ההוא דאמר משום רבי חנינא בן גמליאל דתניא רבי עקיבא אומר אומרה ברכה רביעית בפני עצמה רבי חנינא בן גמליאל אומר אומרה בהודאה"],[[0,"מלמדין את הקטנה","בפרק בית שמאי ביבמות ב' אחין נשואין ב' אחיות יתומות אחת גדולה ואחת קטנה מת בעלה של גדולה ונמצאת זקוקה ליבם בעל הקטנה ודוחה זיקתה נישואי אחותה הקטנה ואוסרתה עליו שאין נישואי קטנה כלום ואם יגרשנה לקטנה בגט שוב אינו יכול ליבם את הגדולה שאחות גרושתו היא אלא מלמדין את הקטנה שתמאן בו ומיאון עוקר נישואין הראשונים ומותר ליבם הגדולה:"],[1,"הרודה ונותן לסל","כגון שהיה לש את עיסתו פחות פחות מחמשת רבעים לפוטרו מן החלה:"],[1,"הסל מצרפן","כשרודן מן התנור:"],[2,"מאי אולמיה דהאי","דחלה מההיא דמיאון דפשטת לה מינה דאמרת ה\"נ מסתברא הא שמעינן מההיא דמיאון דבשאר סדרי איכא הלכה כר\"א:"],[2,"","ומשני מההיא דמיאון ליכא למשמע מינה דבשאר סדרים איכא דהתם משום דקאי ר' אלעזר כר\"א ואיכא למימר משום דמסייע ר' אלעזר לר\"א מש\"ה הלכה כמותו בהא אבל משום דידיה לחודיה לא:"],[3,"מלמדין את הקטנה","במילתא אחריתי היא בפ' ב\"ש:"],[4,"ומי קאי והא אצרוכי מצרכינן ליה","התם דאמר שמואל בקמייתא הלכה כר\"א ובאידך נמי הלכה כר' אלעזר ואמרי' צריכא דאי אשמועינן כו' אלמא ר' אלעזר ור\"א לאו חד טעמא קאמרי מדאיצטריך לשמואל למימר בתרווייהו הלכה:"],[5,"שממאנין את הקטנות","מבקשין מהן שימאנו כגון הנך דרבי אלעזר ור\"א כדי לקיים מצות יבום:"],[6,"ושמשיאין אשה","שהלך בעלה למדינת הים ושמעה מפי עד אחד שמת משיאין אותה לאחר:"],[6,"ושנסקל תרנגול","כדכתיב (שמות כ״א:כ״ט) והמית איש או אשה השור יסקל והוא הדין לכל חיה ועוף כדאוקימנא בשור שנגח את הפרה (ב\"ק דף נד:) דיליף שור שור משבת אלא שדבר הכתוב בהווה:"],[6,"בן מ' יום","ומקמי הכי פסול דה\"ל יין מגתו:"],[7,"קטנות דעלמא","ולעולם עדות בן בבא אדר' אלעזר קאי ולא אדר\"א וה\"ק כל קטנות שיבאו למאן לפנינו כי ההיא דר\"א מלמדין אותן למאן:"],[8,"ליתני נשים","שמשיאין נשים ע\"פ עד אחד:"],[8,"ונימא מאי נשים נשים דעלמא","כי היכי דאמר מאי קטנות קטנות דעלמא:"],[8,"דוקא קתני","קטנות שתים אחת דר' אלעזר ואחת דר' אליעזר ואשה דליכא למימר הכי נסבה בלשון יחיד:"],[9,"וכן אמר ר' אלעזר","אדשמואל קאי. ואמורא הוא והוא ר' אלעזר בן פדת ורבי אלעזר דמיאון תנא הוא והוא ר' אלעזר בן שמוע:"],[10,"הורד והכופר","מין בשמים הן:"],[10,"קטף","מין אילן ואין עושה פרי אלא שרף (יוצא ונוטף מהן) וזהו פריו:"],[10,"יש להן שביעית","שצריך להפקירם ואסור לעשות בהן סחורה ולא אמרי' עצים בעלמא נינהו ושביעית אינה נוהגת בעצים כדאמרי' בלולב הגזול (סוכה דף מ.):"],[10,"ביעור","כשכלה לחיה מן השדה. ואע\"ג דיש להן שביעית איצטריך למימר יש להן ביעור דיש שיש לו שביעית ליאסר בסחורה ומלוגמא ואין לו ביעור כגון דבר המתקיים בארץ כל ימי החורף שאינה כלה לחיה מן השדה אבל כל דבר שיש לו ביעור יש לו שביעית:"],[10,"וא\"ר פדת","בריה דר\"א בן פדת:"],[10,"מאן תנא","להא דקתני יש להן שביעית דקסבר קטפא פירא ר' אליעזר כדאמר לקמן ר\"א אומר המעמיד בשרף הערלה אסור:"],[11,"שריתו קטפא","בשביעית:"],[11,"כר\"א בד'","ותו לא. אלמא בקטפא פירא לא עביד כוותיה לחומרא:"],[15,"אומרה ברכה רביעית","להבדלה במוצאי שבתות ואינו כוללה בחונן הדעת:"],[15,"ואמר רבי אלעזר הלכה כרבי אליעזר","בברכות ירושלמי:"]],[[6,"","ועל היין בן מ' יום. פרש\"י דקודם לכן הוי יין מגתו אע\"ג דאמרי' בהמוכר פירות (ב\"ב דף צז.) יין מגתו אם הביא כשר בן מ' יום לכתחילה נמי יביא אפילו יש הרבה מיין אחר:"],[10,"","יש להן ביעור ולדמיהם ביעור. אע\"ג דשביעית תופסת דמיה יש חילוק בביעור בין דמיה לעצמה כדתנן בפ\"ב דשביעית ר' מאיר אומר דמיה מתבערים עד ר\"ה אבל הן מתבערין עד הפסח:"],[10,"","קטף. פירש רש\"י שם העץ וכן בברייתא פ\"ק דכריתות (דף ו.) רשב\"ג אומר הצרי אינו אלא שרף מעצי הקטף ושרף עצמו נקרא קטף על שם העץ כדאמר הכא דיש בו שביעית ובסמוך נמי אמר דקטפו זהו פריו וצרי ולוט (בראשית ל״ז:כ״ה) מתרגמינן קטף ולוטא ומה שפירש\"י דאינו עושה פירות אלא שרף נוטף ממנו וזהו פריו אינו למאי דמוקי ליה ר' זירא בסמוך בקטפא דפירא:[\u0003ונראה\u0004 דרש\"י פירש כן לשינויא בתרא. גי':]"],[10,"","ואמר רבי פדת מאן תנא כו'. ואם תאמר דבפרק קמא דברכות (דף ה:) אמר ליה ר' יוחנן לרבי אלעזר אי משום בני דין גרמא דעשיראה ביר משמע דלרבי אלעזר לא היו לו בנים ויש לומר שאחרי כן נולד לו או היו לו בנים הרבה ומתו מקצתם ואמר ליה רבי יוחנן כך כדי לנחמו:"],[10,"","מאן תנא דאמר קטפא פירא ר' אליעזר. ואם תאמר במאי פליגי אי ביעורו והנאתו שוה מאי טעמא דרבנן דאפי' עצים הוו אסירי בשביעית אי לאו דאין הנאתו וביעורו שוה ואי אין הנאתו וביעורו שוה לא אסור בשביעית ואין סברא לומר דפליגי אי הנאתו וביעורו שוה אי לאו ויש לומר דודאי הנאתו וביעורו שוה ולפי שאינו כי אם לחלוחי העץ שרו רבנן דבטל אגב העץ ורבי אליעזר סבר דהנאתו חשיבא והוי פירי:"],[11,"","ואבוך אמר הלכה כר\"א בד'. אע\"ג דר' יוסי קאי כוותיה דבהגוזל קמא (ב\"ק דף קב.) אית להו דשביעית נוהגת בעצים וא\"כ כ\"ש קטפא ומשום דרבי יוסי קאי כותיה לא חשיב ליה עם הנך דטעמא דר' יוסי משום דלא בעי הנאתו וביעורו שוה ולא קיימא לן כוותיה אלא אין שביעית נוהגת בעצים דר' יוסי נמי מודה דקטפא לאו פירא הוא לענין ערלה:"],[14,"[משום דקאי רבי יהודה בן בבא כותיה","אע\"ג דבמתני' נמי חזר בו ר' יהושע וקאי כוותיה ואפ\"ה מני לה בד' וי\"ל דשמא ר' יהושע סבר כר' יוסי דמצריך ג' עונות במעוברת ומניקה דפליג ארבי אליעזר ולא הדר ביה אלא ממה שאמר אני לא שמעתי אלא בתולה. גי':]"]]],[["והא קשיש מיניה טובא אלא משום דקאי רבי חנינא בן גמליאל בשיטתיה","ומי קאי והתניא אור יוה\"כ מתפלל שבע ומתודה שחרית מתפלל שבע ומתודה מוסף מתפלל שבע ומתודה מנחה מתפלל שבע ומתודה בנעילה מתפלל שבע ומתודה בערבית מתפלל שבע מעין שמנה עשרה","רבי חנינא בן גמליאל משום אבותיו אומר מתפלל שמנה עשרה מפני שצ\"ל הבדלה בחונן הדעת אמר ר\"נ בר יצחק איהו אמר משום אבותיו וליה לא ס\"ל","א\"ל ר' ירמיה לר' זירא ואת לא תסברא דמאן תנא קטפא פירא ר\"א הוא והתנן ר\"א אומר המעמיד בשרף ערלה אסור","אפילו תימא רבנן ע\"כ לא פליגי רבנן עליה דר\"א אלא בקטפא דגווזא אבל בקטפא דפירא מודו ליה דתנן א\"ר יהושע שמעתי בפירוש שהמעמיד בשרף העלין בשרף העיקרין מותר בשרף הפגין אסור מפני שהוא פרי","ואיבעית אימא כי פליגי רבנן עליה דר\"א באילן העושה פירות אבל באילן שאינו עושה פירות מודו דקטפו זהו פריו דתנן ר\"ש אומר אין לקטף שביעית וחכ\"א יש לקטף שביעית מפני שקטפו זהו פריו","מאן חכמים לאו רבנן דפליגי עליה דר\"א א\"ל ההוא סבא הכי א\"ר יוחנן מאן חכמים ר\"א דאמר קטפו זהו פריו","אי ר\"א מאי איריא אילן שאינו עושה פרי אפילו אילן העושה פרי קטפו זהו פריו לדבריהם דרבנן קאמר להו לדידי אפי' אילן העושה פירות נמי קטפו זהו פריו לדידכו אודו לי מיהת באילן שאינו עושה פירות דקטפו זהו פריו ורבנן אמרי ליה לא שנא","איזו היא בתולה כל שלא ראתה כו' ת\"ר נשאת וראתה דם מחמת נישואין ילדה וראתה דם מחמת לידה עדיין אני קורא לה בתולה שהרי בתולה שאמרו בתולת דמים ולא בתולת בתולים","איני והאמר רב כהנא תנא ג' בתולות הן בתולת אדם בתולת קרקע בתולת שקמה בתולת אדם כל זמן שלא נבעלה נפקא מינה לכ\"ג א\"נ לכתובתה מאתים","בתולת קרקע כ\"ז שלא נעבדה נפקא מינה לנחל איתן א\"נ למקח וממכר","בתולת שקמה כ\"ז שלא נקצצה נפקא מינה למקח וממכר אי נמי למקצצה בשביעית כדתנן אין קוצצין בתולת שקמה בשביעית מפני שהיא עבודה ואם איתא ליתני נמי הא","אמר ר\"נ בר יצחק כי קתני מידי דלית ליה שם לווי אבל מידי דאית ליה שם לווי לא קתני רב ששת בריה דרב אידי אמר כי קתני מידי דתלי במעשה מידי דלא תלי במעשה לא קתני","רבי חנינא בריה דרב איקא אמר כי קתני מידי דלא הדר לברייתו מידי דהדר לברייתו לא קתני רבינא אמר כי קתני מידי דקפיד עליה זבינא מידי דלא קפיד עליה זבינא לא קתני","ולא קפדי והתניא רבי חייא אומר כשם שהשאור יפה לעיסה כך דמים יפין לאשה ותניא משום ר\"מ כל אשה שדמיה מרובין בניה מרובין אלא כי קתני מידי דקפיץ עליה זבינא מידי דלא קפיץ עליה זבינא לא קתני","ת\"ר איזוהי בתולת קרקע כל שמעלה רשושין ואין עפרה תיחוח נמצא בה חרס בידוע שנעבדה צונמא הרי זו בתולת קרקע","מעוברת משיודע עוברה וכמה הכרת העובר סומכוס אומר משום רבי מאיר שלשה חדשים ואע\"פ שאין ראיה לדבר זכר לדבר שנאמר (בראשית לח, כד) ויהי כמשלש חדשים וגומר","זכר לדבר קרא כתיב וראיה גדולה היא משום דאיכא דילדה לט' ואיכא דילדה לשבעה","ת\"ר הרי שהיתה בחזקת מעוברת וראתה דם ואח\"כ הפילה רוח או כל דבר שאינו של קיימא הרי היא בחזקתה ודיה שעתה","ואע\"ג שאין ראיה לדבר זכר לדבר שנאמר (ישעיהו כו, יח) הרינו חלנו כמו ילדנו רוח מאי זכר לדבר הרי ראיה גדולה היא כי כתיב האי קרא בזכרים כתיב","ורמינהי קשתה שנים ולשלישי הפילה רוח או כל דבר שאינו של קיימא הרי זו יולדת בזוב ואי אמרת לידה מעלייתא היא"],[[0,"והא קשיש מיניה טובא","דהא ר' אליעזר היה בימי ר\"ג בנו של ר\"ש הנהרג בהרוגי מלכות ובעל אחותו היה כדאמרי' בהזהב (ב\"מ דף נט:) ור' חנינא בנו של ר\"ג היה:"],[1,"אור","ליל כניסתו:"],[1,"מעין שמנה עשרה","שאומר בשבעה ברכות מעין שמונה עשרה כגון ג' ראשונות וג' אחרונות כתקנן ואומר הביננו באמצע ומסיים בשומע תפלה כדאמרינן בברכות (דף כט.) ויש בה מעין כולם:"],[3,"המעמיד","חלב בהמה לעשות גבינה:"],[4,"בקטפא דגווזא","בשרף הנוטף מן העץ דכעץ בעלמא הוי אבל קטף הוי שרף הפגין ומודו בהו רבנן:"],[6,"לאו רבנן דפליגי עליה דר\"א","בשאר אילנות וחזינן דבקטף סבירא להו כוותיה:"],[8,"בתולת דמים","דמי נדה ולא דמי בתולים דאפילו נבעלה עדיין היא בתולת דמים:"],[9,"לכהן גדול","שמצווה ליקח בתולה:"],[9,"לכתובתה מאתים","דאם נבעלה תו לא מיקרי בתולה וכתובתה מנה:"],[10,"למקח וממכר","שאם אמר לו קרקע בתולה אני מוכר לך נותן לו קרקע שלא נעבדה לפי שעושה פירות מרובין ושמנים:"],[11,"שלא נקצצה","כן מנהג לקוצצה כדי שירבה עוביו ויוציא ענפים הרבה במקום החתך ונקרא סדן שקמה:"],[11,"למקח וממכר","לפי שנוח לו בבתולה שילדה היא ויקצצנה ומתעבה:"],[11,"ליתני נמי הא","ונימא ארבע בתולות הן:"],[12,"שם לווי","כגון בתולה דמתניתין לאו בתולה סתם מיקריא אלא בתולת דמים דסתם בתולה בנשים היינו בתולת בתולים וכן קרקע בתולה וכן שקמה בתולה לא בעי שם לווי:"],[12,"דתלי במעשה","שאינו מאבד שמו אלא ע\"י מעשה אבל ראיית דם מאיליה באה ואבדה שם בתולה:"],[13,"דהדר לברייתו","כגון זקנה שמסתלקין דמיה:"],[13,"דקפיד עליה זבינא","נותן עיניו בכך כגון בתולה נוחה לינשא מבעולה וכן קרקע ושקמה אבל בתולת דמים אין אדם נותן עיניו בדמים דלא חייש אי חזיא אי לא חזיא:"],[14,"דקפיץ עליה","שנוחה בתולה ללקוחות כגון בתולת בתולים וקרקע ושקמה אבל בתולת דמים כל כמה דחזיא ניחא ליה טפי כדאמרינן:"],[15,"רשושין","אבנים דקין שקורין פרדוי\"א. לשון אחר רגבי אדמה קשין שאין עפרם מתפזר:"],[15,"חרס","מכיתת חרשים:"],[15,"בידוע שנעבדה","דאי לא נעבדה חרס זה מאין בא לתוכה:"],[15,"צונמא","סלע:"],[17,"דילדה לז'","שמא ניכר עוברה לשליש ימיה דהיינו שני חדשים ושליש קמ\"ל דאזלינן בתר רוב נשים:"],[18,"דיה שעתה","לא אמרינן איגלאי מילתא למפרע דלאו הריון הוא ונטמאו טהרות דמעת לעת של ראיה:"],[19,"זכר לדבר","דהריון רוח שמיה הריון:"],[20,"קשתה שני ימים","בתוך אחד עשר ימי זוב ולשלישי נמי ראתה ואח\"כ הפילה רוח בו ביום ולא שפתה מן הצער הרי לידה זו בזוב וצריכה שבעה נקיים וקרבן לזיבתה דכיון דלאו ולד הוא הויא זיבה מעליא:"]],[[0,"","והא קשיש מיניה טובא. ר\"א מרבי חנינא פרש\"י שר' חנינא היה בנו של ר\"ג דיבנה וכ\"נ דבפרק המפלת (לקמן נדה דף כג.) א\"ר חנינא בן גמליאל נראין דברי ר\"מ בבהמה ובחיה וא\"ת והא בת\"כ (פ' אמור) גבי פנחס איש הסתת שעלה גורלו להיות כ\"ג כו' אמר ר' חנינא בן רבן גמליאל וכי סתת היה והלא חתנינו היה וחורש היה ואי בן ר\"ג דיבנה היה היאך היה לו חתן כ\"ג והלא היה אחר החורבן וי\"ל דלאו חתנינו ממש קאמר אלא חתן אבותיו וכן משמע דלא אמר חתני אלא חתנינו היה:"],[1,"[ומאי קאי","הר\"מ ז\"ל אמר דלא פריך מברייתא אברייתא משום דה\"א דהדר ביה מההיא דהודאה (אחרינא שמע) מרבותיו אבל השתא דקאמר דקאי בשיטתיה משמע דלא הדר ביה דאל\"כ אכתי תיקשי ותו ליכא לכך פריך שפיר ומאי קאי. גי']:"],[2,"","מפני שצריך לומר הבדלה בחונן הדעת. הקשה הר\"ר יעקב מאורלינ\"ש ונכלליה מכלל דהכי פריך פרק תפלת השחר (ברכות דף כט.) אהא דאמר שמואל כל השנה מתפלל הביננו חוץ ממוצאי שבת מפני שצ\"ל הבדלה בחונן הדעת ופריך ונכלליה מכלל וי\"ל דהתם פריך משום דלא ישנה אדם משום הבדלה מכמו שהוא מתפלל כל השנה [כיון דסבר דכל השנה מתפלל הביננו] אלא יכלול בהביננו והכא קאמר ר' חנינא [כיון דס\"ל דכל השנה אינו מתפלל הביננו א\"כ] במוצאי יוה\"כ מפני טורח תענית לא ישנה מכמו שהוא מתפלל כל השנה כדי שיאמר הבדלה בחונן הדעת:"],[4,"","בקטפא דפירא מודו ליה דתנן א\"ר יהושע כו'. וא\"ת [א\"כ] אמאי אוקי רבי פדת מתניתין כר\"א כיון דרבנן מודו בקטפא דפירא ואי משום דבעי לאוקומי בכל מיני קטף אפי' בדגווזא מ\"מ היכי קאמר ליה ר' זירא חזי דמשתריא קטפא לעלמא הא ודאי אמת הוא דקטפא דגווזא שרי דאף ר' זירא מודה דאין הלכה כר\"א אלא בד' וליכא למימר דאתי למטעי ולמשרי אף קטפא דפירא מדלא מוקי רבי פדת מתני' בקטפא דפירא ודברי הכל מכלל דסבר אף בקטפא דפירא רבנן הוא דשרו הא לא אתי למטעי דהא חזינן במשנה שאוסר רבי יהושע שרף הפגים וי\"ל שיטעו ויסברו שרבי יהושע שמעתי קאמר וליה לא ס\"ל מדלא מוקי ר' פדת מתני' כוותיה ובקטפא דפירא ואפשר דר' פדת סבר דקטפא דפירא שרי ור' [יהושע] קאמר שמעתי וליה לא סבירא ליה:"],[6,"","מאן חכמים (א\"ר יוחנן) ר\"א. אע\"ג דתנא בלשון חכמים ניחא ליה לאוקומי כר\"א ולא לימא ג' מחלוקות בדבר:"]]],[["קושי סמוך ללידה רחמנא טהריה אמר רב פפי הנח מעת לעת דרבנן","רב פפא אמר מידי הוא טעמא אלא משום דראשה כבד עליה ואבריה כבדין עליה הכא נמי ראשה ואבריה כבדין עליה","בעא מיניה רבי ירמיה מרבי זירא ראתה ואח\"כ הוכר עוברה מהו כיון דבעידנא דחזאי לא הוכר עוברה מטמיא או דלמא כיון דסמוך לה חזאי לא מטמיא","א\"ל מידי הוא טעמא אלא משום דראשה כבד עליה ואבריה כבדין עליה בעידנא דחזאי אין ראשה כבד עליה ואין אבריה כבדין עליה","בעא מיניה ההוא סבא מר' יוחנן הגיע עת וסתה בימי עבורה ולא בדקה מהו קא מיבעיא לי אליבא דמ\"ד וסתות דאורייתא מאי כיון דוסתות דאורייתא בעיא בדיקה או דלמא כיון דדמיה מסולקין לא בעיא בדיקה","א\"ל תניתוה רבי מאיר אומר אם היתה במחבא והגיע שעת וסתה ולא בדקה טהורה שחרדה מסלקת את הדמים טעמא דאיכא חרדה הא ליכא חרדה והגיע וסתה ולא בדקה טמאה","אלמא וסתות דאורייתא וכיון דאיכא חרדה דמיה מסולקין ולא בעיא בדיקה הכא נמי דמיה מסולקין ולא בעיא בדיקה","מניקה עד שתגמול וכו' ת\"ר מניקה שמת בנה בתוך עשרים וארבע חדש הרי היא ככל הנשים ומטמאה מעת לעת ומפקידה לפקידה לפיכך אם היתה מניקתו והולכת ארבע או חמש שנים דיה שעתה דברי ר\"מ","רבי יהודה ורבי יוסי ורבי שמעון אומרים דיין שעתן כל עשרים וארבע חדש לפיכך אם היתה מניקתו ארבע וחמש שנים מטמאה מעת לעת ומפקידה לפקידה","כשתמצא לומר לדברי ר\"מ דם נעכר ונעשה חלב לדברי רבי יוסי ורבי יהודה ורבי שמעון אבריה מתפרקין ואין נפשה חוזרת עד עשרים וארבע חדש","לפיכך דר\"מ למה לי משום לפיכך דרבי יוסי","ולפיכך דרבי יוסי למה לי מהו דתימא רבי יוסי תרתי אית ליה קמ\"ל","תניא נמי הכי דם נעכר ונעשה חלב דברי ר\"מ רבי יוסי אומר אבריה מתפרקין ואין נפשה חוזרת עליה עד עשרים וארבע חדש א\"ר אלעאי מאי טעמא דר\"מ דכתיב (איוב יד, ד) מי יתן טהור מטמא לא אחד","ורבנן א\"ר יוחנן זו שכבת זרע שהוא טמא ואדם הנוצר ממנו טהור","ור\"א אומר אלו מי הנדה שהמזה ומזין עליו טהור ונוגע טמא ומזה טהור והכתיב (במדבר יט, כא) ומזה מי הנדה יכבס בגדיו מאי מזה נוגע","והכתיב מזה והכתיב נוגע ועוד מזה בעי כבוס נוגע לא בעי כבוס אלא מאי מזה נושא","וליכתוב נושא קמ\"ל דעד דדרי כשיעור הזאה הניחא למ\"ד הזאה צריכה שיעור אלא למ\"ד אין צריכה שיעור מאי איכא למימר","אפילו למ\"ד אינה צריכה שיעור ה\"מ אגבא דגברא אבל במנא בעינא שיעור כדתנן כמה יהיו במים ויהא בהן כדי הזאה כדי שיטבול ראשי גבעולין ויזה","והיינו דאמר שלמה (קהלת ז, כג) אמרתי אחכמה והיא רחוקה ממני","איזו היא זקנה כל שעברו עליה שלש עונות [סמוך לזקנתה] היכי דמי סמוך לזקנתה אמר רב יהודה כל שחברותיה אומרות עליה זקנה היא ורבי שמעון אומר"],[[0,"קושי סמוך ללידה","שלא שפתה בינתים ודם הקושי מחמת הולד הוא בא:"],[0,"רחמנא טהריה","מזיבה בתוך י\"א יום בפרק בנות כותים (לקמן נדה לו:):"],[0,"אמר רב פפי","אין ודאי דלאו לידה היא אבל לענין דיה שעתה חשיב ולד דמעת לעת דרבנן:"],[1,"רב פפא אמר","אף על גב דלאו ולד הוא אפילו הכי דיה שעתה דטעמא דמעוברת דיה שעתה משום דראשה ואבריה כבדין מחמת חולי ולפיכך דמיה מסולקין הלכך בהריון של רוח נמי ראשה ואבריה כבדין:"],[2,"ואח\"כ הוכר עוברה","סמוך לראייתה מיד:"],[4,"וסתות דאורייתא","אותה בדיקה שהצריכוה לאשה להבדק בשעת וסתה דבר תורה הוא הלכה למשה מסיני דאורח בזמנו בא ואם בא יום וסתה ולא בדקה מחזקינן לה טמאה לקמן בפרק כל היד (נדה דף טז.) וקא מבעיא לן אם לא בדקה ביום וסתה בימי עיבורה מהו:"],[5,"אם היתה במחבא","מחמת פחד כרכום או ליסטין:"],[6,"","ה\"ג אלמא וסתות דאורייתא וכיון דאיכא חרדה כו':"],[6,"ה\"נ","במעוברת הואיל ודמיה מסולקין טהורה:"],[7,"ומטמאה מעת לעת","שאין הדבר תלוי אלא בהנקת התינוק לפי שהדם נעכר ונעשה חלב וכיון שמת חוזר הדם לקדמותו:"],[7,"לפיכך","כיון דביניקה תליא מילתא אם היתה מניקתו כו':"],[8,"דיה שעתה","אע\"פ שמת שאין הטעם תלוי ביניקת הולד אלא מתוך צער לידה אבריה מתפרקין ודמה מסתלק ואינו חוזר עד כ\"ד חדש הלכך לא שנא מת לא שנא חי:"],[8,"לפיכך","כיון דלאו בתינוק תליא מילתא אם היתה מניקתו כו' שהרי לסוף כ\"ד חדש חוזר הדם:"],[9,"נפשה","דמה:"],[10,"למה לי","כיון דאמר הרי היא ככל הנשים אלמא בתינוק תליא מילתא פשיטא דאם מניקתו לעולם דדיה שעתה:"],[11,"מהו דתימא רבי יוסי תרתי אית ליה","דם נעכר ואבריה מתפרקין והיכא דמת בתוך כ\"ד חדש דיה שעתה משום דעדיין לא חזר דמה והיכא דמניקתו חמש שנים נמי דיה שעתה אף על פי שחוזר נפשה לסוף כ\"ד חדש. הנקת תינוק עוכרת לדם ונעשה חלב:"],[11,"קמ\"ל","לפיכך דדוקא קאמר רבי יוסי שאין הטעם תלוי אלא בפירוק אברים בין יונק בין שאינו יונק דיה שעתה כ\"ד חדש לא פחות ולא יותר אבל לפיכך דר\"מ לא איצטריך דלר\"מ אין סילוק דמים תוך כ\"ד חדש טפי מלאחר כ\"ד חדש דאי יש סילוק אמאי אמרינן דכי מת תוך כ\"ד חדש מטמאה מעת לעת וכיון דאין סילוק אין חזרה והלכך כי מניקתו לעולם על כרחך דיה שעתה:"],[12,"מ\"ט דר\"מ","כלומר מנ\"ל לר\"מ דדם נעכר ונעשה חלב:"],[12,"טהור מטמא","חלב מדם:"],[12,"לא אחד","בתמיה. כלומר יחידו של עולם:"],[13,"ורבנן אמר רבי יוחנן","כלומר ורבנן האי קרא מאי עבדי ליה לכדרבי יוחנן כו':"],[15,"ועוד נוגע לא בעי כבוס","דכתיב ומזה מי הנדה יכבס בגדיו והנוגע במי הנדה יטמא עד הערב:"],[16,"הניחא למאן דאמר כו'","פלוגתא היא במסכת זבחים בפ' כל הזבחים שנתערבו (זבחים דף פ.):"],[17,"כדי שיטבול ראשי גבעולין","של אזוב ולא שיספוק בקינוח:"],[18,"אמרתי אחכמה","בטעם זה למה מזה ומזין עליו טהור ונוגע טמא והיא רחוקה ממני:"]],[[0,"","קושי סמוך ללידה רחמנא טהריה. וא\"ת דבפרק בנות כותים (לקמן נדה לו:) אמר דמה מחמת עצמה ולא מחמת ולד ופריך ונימא דמה מחמת עצמה ולא מחמת אונס ומשני מטהר אני בולד שכן יש לו טהרה אחרי כן מה שאין כן באונס והשתא והא בלידת רוח אין טהרה ויש לומר דפריך אואי בעית אימא דקאמר התם ולד אין לך אונס גדול מזה:"],[0,"","[ \u0003 אי \u0004 נמי הואיל ואיכא לידה דיש טהרה אחרי כן איכא לאוקמיה קרא בכל ענין לידה אפילו בלידת רוח שאין טהרה אחרי כן בשפיר שאינו מרוקם אע\"ג דאין טהרה אלא בשפיר מרוקם. גליון:]"],[5,"","הא ליכא חרדה ולא בדקה טמאה אלמא וסתות דאורייתא. [כי הגיע שעת וסתה] וא\"ת ודלמא לעולם וסתות דרבנן ומיירי דהשתא בדקה עצמה ומצאה טמאה וכי איכא חרדה טהורה למפרע ולא מטמאינן אלא משעה שמצאה טמאה ואילך הא ליכא חרדה ובדקה אחרי כן ומצאה טמאה טמאה משעת וסתה דהכי אמרינן פרק כל היד (לקמן נדה דף טו.) למ\"ד וסתות דרבנן [בדקה אחרי כן] ומצאה טמאה טמאה טהורה טהורה ולמ\"ד וסתות דאורייתא אפילו בדקה ומצאה טהור טמא דאורח בזמנו בא (וי\"ל דסמיך ארישא דתנא פ' בנות כותים (לקמן נדה לט.) הגיע שעת וסתה ולא בדקה טמאה אלמא וסתות דאורייתא ומיהו קשה דבפרק כל היד (נדה דף טז.) מוכיח מהכא דסבר רבי מאיר וסתות דאורייתא ואיכא מאן דלא מפרש התם רישא כר' מאיר ואם כן דלמא ר\"מ פליג ארישא) וי\"ל דדייק מדקתני מסלקת הדמים משמע הדמים הידועים בה והמבוררים לבא אלמא וסתות דאורייתא:"],[10,"","לפיכך דרבי מאיר למה לי. השתא לא' בעי לשנויי [מהו דתימא] דתרתי בעי רבי מאיר קמ\"ל לפיכך דבחד סגי דאין סברא שלא תהא מסולקת בדמים אלא ע\"י שני דברים אבל על ר' יוסי ס\"ד שתהא מסולקת באחד מב' דברים או בזה או בזה:"],[14,"","ונוגע טמא. וא\"ת והלא מזין עליו נמי בעי טבילה והערב שמש כמו נוגע וי\"ל דמ\"מ הוי חדוש שזה בא לו טומאה על ידי הזאה וזה בא לו טהרה ע\"י הזאה א\"נ בטהור שמזין עליו בחנם קאמר הכא וכרבנן דפ\"ק דיומא (דף יד.) דתניא טהור שנפל עליו הזאה טמאתו דברי רבי עקיבא ורבנן אמרי ק\"ו על הטמא טהור על הטהור לא כ\"ש:"],[14,"נוגע","ונושא דטמא היינו בחנם אבל כדי להזות על הטמא לא:"],[15,"","ועוד מזה בעי כבוס. בפ' יוצא דופן (לקמן נדה דף מב:) מפורש מה שמקשים על זה מנבלת בהמה טמאה:"],[15,"","מאי מזה נושא. וא\"ת ומנ\"ל לאפוקי קרא ממשמעותיה וי\"ל מדכתיב והזה הטהור על הטמא משמע שהוא טהור לעולם ואע\"ג דדרשינן נמי (ביומא דף מג:) הטהור מכלל שהוא טמא לימד על טבול יום שטהור בפרה תרתי ש\"מ: [ה\"ג א\"נ כיון דצורך מצוה הוא נוגע סברא הוא דטהור) (בח' מזין עליו) ע\"כ ודוחק] (א\"נ):"]]],[["כל שקורין לה אמא אמא ואינה בושה ר' זירא ור' שמואל בר רב יצחק חד אמר כל שאינה מקפדת וחד אמר כל שאינה בושה מאי בינייהו איכא בינייהו בושה ואינה מקפדת","וכמה עונה אמר ריש לקיש משום רבי יהודה נשיאה עונה בינונית שלשים יום ורבא אמר רב חסדא עשרים יום ולא פליגי מר קחשיב ימי טומאה וימי טהרה ומר לא חשיב ימי טומאה","ת\"ר זקנה שעברו עליה שלש עונות וראתה דיה שעתה ועוד עברו עליה שלש עונות וראתה דיה שעתה ועוד עברו עליה שלש עונות וראתה הרי היא ככל הנשים ומטמאה מעת לעת ומפקידה לפקידה","ולא (מיבעיא) שכוונה אלא אפי' פיחתה (ואפילו) והותירה","אפי' פיחתה ולא מבעיא כוונה אדרבה כי כוונה קבעה לה וסתה ודיה שעתה","וכי תימא רבנן היא דפליגי עליה דרבי דוסא דאמרי אשה שיש לה וסת מטמאה מעת לעת איפכא מבעי ליה ולימא ולא שפיחתה והותירה אלא אפי' כוונה","תני לא שפיחתה והותירה אלא אפי' כוונה ואיבעית אימא ה\"ק ולא שכוונה אלא שפיחתה והותירה אבל כוונה קבעה לה וסת ודיה שעתה ומני רבי דוסא היא","ר\"א אומר כל אשה שעברו עליה וכו' תניא אמר להם רבי אליעזר לחכמים מעשה בריבה אחת בהיתלו שהפסיקה שלש עונות ובא מעשה לפני חכמים ואמרו דיה שעתה","אמרו לו אין שעת הדחק ראיה מאי שעת הדחק איכא דאמרי שני בצורת הוו איכא דאמרי טהרות אפיש לעבידא וחשו רבנן להפסד דטהרות","ת\"ר מעשה ועשה רבי כר' אליעזר לאחר שנזכר אמר כדי הוא ר' אליעזר לסמוך עליו בשעת הדחק מאי לאחר שנזכר אילימא לאחר שנזכר דאין הלכה כר' אליעזר אלא כרבנן בשעת הדחק היכי עביד כוותיה","אלא דלא איתמר הילכתא לא כמר ולא כמר ומאי לאחר שנזכר לאחר שנזכר דלאו יחיד פליג עליה אלא רבים פליגי עליה אמר כדי הוא ר' אליעזר לסמוך עליו בשעת הדחק","ת\"ר תנוקת שלא הגיע זמנה לראות וראתה פעם ראשונה דיה שעתה שניה דיה שעתה שלישית הרי היא ככל הנשים ומטמאה מעת לעת ומפקידה לפקידה","עברו עליה שלש עונות וראתה דיה שעתה ועוד עברו עליה שלש עונות וראתה דיה שעתה ועוד עברו עליה שלש עונות וראתה הרי היא ככל הנשים ומטמאה מעת לעת ומפקידה לפקידה","וכשהגיע זמנה לראות פעם ראשונה דיה שעתה שניה מטמאה מעת לעת ומפקידה לפקידה עברו עליה שלש עונות וראתה דיה שעתה","אמר מר עברו עליה שלש עונות דיה שעתה"],[[1,"ימי טומאה וימי טהרה","מראייה ועד ראייה שלשים יום ימי טומאה עשרה שבעה לנדה ושלשה לזיבה ועשרים ימי טהרה:"],[2,"הרי היא ככל הנשים","דכיון דעשתה כך שלש פעמים אין זה סילוק דמים אלא שינוי וסת. וכי תימא תיגלי מלתא למפרע שאף בראשונה מתוך שדמים מצויין בה ראתה ונטמא טהרות למפרע לא אחמור רבנן כולי האי במעת לעת:"],[3,"בשכיונה","שראתה שלש ראיות הללו בתשעים יום או ביום תשעים ואחד:"],[3,"אלא אפילו פיחתה","כגון ראשונה לתשעים ושלשה ושניה לסוף תשעים ושנים ושלישית לתשעים ואחד או הותירה כגון ראשונה לצ\"א יום ושניה לצ\"ב ושלישית לצ\"ג אפילו הכי מטמאה מעת לעת. ולקמן פריך מאי אפילו הא ודאי הכי הוא דמטמאה מעת לעת דכיון שפיחתה או הותירה במה נטהר וסת אין כאן סילוק דמים אין כאן אבל אם כוונה יש כאן וסת ודיה שעתה:"],[5,"איפכא מיבעי ליה","ולא כשפיחתה או הותירה בלבד אמרו חכמים שתטמא מעת לעת:"],[5,"אלא אפילו כיונה","דאיכא למימר יש כאן קביעות וסת ודיה שעתה אפילו הכי מטמאה מעת לעת כרבנן דפליגי עליה דרבי דוסא:"],[6,"ואיבעית אימא","סמי מכאן אפילו ורבי דוסא היא והכי קאמר ולא כשכיונה דאי כיונה קבעה וסת ודיה שעתה אלא שפיחתה והותירה:"],[7,"בהיתלו","שם מקום:"],[8,"שני בצורת הוו","ואיכא הפסד מרובה חששו:"],[9,"לאחר שנזכר","שלא יפה הורה:"],[11,"שניה דיה שעתה","שבראייה ראשונה לא הוחזקה בדמים הואיל ולא הגיע זמנה לראות עד שתתחזק כשאר חזקות:"],[11,"שלישית מטמאה מעת לעת","וכדאמר לקמן דהא מתניתין רבי היא דאמר בתרי זימני הוה חזקה הלכך בשני ראיות הוחזקה להיות דמים מצויין בה ומשהוחזקה ואילך גזור בה רבנן מעת לעת:"],[12,"עברו עליה שלש עונות וראתה","סילוק דמים הוא זה ואפילו בהגיע זמנה לראות אית ליה להאי תנא דעברו עליה שלש עונות דיה שעתה כדקתני סיפא ור' אליעזר היא דאמר במתניתין כל אשה שעברו עליה ג' עונות דיה שעתה כדלקמן:"],[12,"","בס\"א אינו ה\"ג \u0003ת\"ר תינוקת שלא הגיע זמנה לראות וראתה פעם ראשונה דיה שעתה שניה דיה שעתה שלישית הרי היא ככל הנשים \u0004- ואע\"ג דלגבי בתולת דמים במתני' תנן במה אמרו דיין שעתן בראייה ראשונה אבל בשניה מטמאה מעת לעת הני מילי בהגיע זמנה לראות דמים דדמים מצויין בה ובחדא זימנא איתחזקה אבל זו שאינה ראויה לראות צריכה שתתחזק בחזקה גמורה ובתרי זימני הויא חזקה דהא מתניתין רבי היא וכדמוקמינן ליה לקמן הילכך בשתי ראיות הויא חזקה ובשלישית מטמאה מעת לעת ובההיא ראייה דאיתחזק בה לא גזרו רבנן טומאה למפרע כי היכי דבתולה דמתני' דהגיע זמנה לראות דמיחזקה בחדא ראייה ואמרו רבנן דיה שעתה באותה ראייה אף זאת המוחזקת בראייה שניה דיה שעתה עד שתראה את השלישית:"],[12,"עברו עליה שלש עונות","לאחר שהוחזקה וראתה:"],[12,"דיה שעתה","כרבי אליעזר אוקמינן לה לקמן דאמר כל אשה שעברו עליה שלש עונות דיה שעתה כדקתני סיפא אף בהגיע זמנה וראתה עברו עליה שלש עונות וראתה דיה שעתה אלמא ר\"א היא:"],[12,"ועוד עברו עליה שלש עונות וראתה דיה שעתה","לקמן בעי גמרא דאי לא עברו עליה שלשה עונות שניות אלא לסוף עונה חזאי כשאר נשים מאי לפי שיש לנטות הדבר לשני צדדים כדבעי לפרושי בסיפא:"],[12,"ועוד עברו עליה ג' עונות וראתה מטמאה מעת לעת","דאיגלאי מילתא דהנך הפסקות לאו סילוק דמים הם אלא שינוי וסת ולא שכיונה אלא שפיחתה והותירה כדאמרינן לעיל ואף על גב דלרבי הוי חזקה בתרי זימני והוכחה דשינוי וסת לדילוגו לאו סילוק דמים הן אפילו הכי לא מטמאינן לה בשניה מעת לעת דכיון דלא הגיע זמנה לראות הויא הפסקה ראשונה מחזקינן לה בחוזרת לקדמותה שלא יהו עוד דמים מצויין בה וצריכה שתתחזק כבתחלה ופעם ראשונה ושניה דיה שעתה ושלישית מטמאה מעת לעת הלכך ראייה הסמוכה לה לשלש עונות קמאי היא ראשונה והסמוכה לשניה היא השניה ובשלישית תטמא מעת לעת ואף על גב דבהפסקה חזיתה שינוי וסת הוא ולא סילוק דמים. ע\"כ:"],[13,"וכשהגיע זמנה לראות פעם ראשונה דיה שעתה שניה מטמאה מעת לעת","דהיינו בתולה דמתניתין דתנן בה במה אמרו דיה שעתה בראייה ראשונה אבל בשניה מטמאה מעת לעת:"],[13,"עברו עליה כו'","רבי אליעזר היא דאמר אפילו ילדה שעברו עליה שלש עונות דיה שעתה:"],[14,"אמר מר","גבי תינוקת שלא הגיע זמנה לראות וראתה שלש פעמים ואחר כך עברו עליה שלש עונות וראתה דיה שעתה:"]],[[0,"","כל שקורין לה אמא אמא ואינה בושה. ובירושלמי פריך וכי בדעתה תלויה הדבר ומשני כל שראויה לקרותה אמא:"],[1,"","ימי טומאה וימי טהרה. פרש\"י שבעה ימי נדות ושלשה ימי זיבה אך קצת דוחק דקרי לאחד עשר יום ימי טומאה ולקמן תנן בפרק בנות כותים (נדה דף לח:) כל י\"א יום בחזקת טהרה וקרא נמי קרי להו בלא עת נדתה ור\"ח גריס אמר רבא אמר רב חסדא כ\"ג:"],[2,"","זקנה שעברו עליה שלש עונות. פירוש סמוך לזקנתה ועוד עברו עליה שלש עונות דיה שעתה והא דתנן (לעיל נדה דף ז.) במה אמרו דיה שעתה בראשונה אבל בשניה מטמאה מעת לעת היינו כי ראתה בשניה בסוף שלשים:"],[3,"","פיחתה והותירה. פרש\"י כגון לצ\"א לצ\"ב ולצ\"ג לאו דוקא בענין זה דהא לקמן בפרק האשה (נדה דף סד.) פליגי בה רב ושמואל בראתה בט\"ו לחדש זה וט\"ז לחודש זה וי\"ז לחדש זה אי קבעה וסת לדילוג ומיהו למאי דפריש התם דדוקא ברואה לדילוג לחדש אבל ראתה היום ואחר ט\"ז יום ואחר י\"ז ימים לא קבעה וסת לדילוג אתי שפיר:"]]],[["הדר קחזיא בעונות מאי אמר רב גידל אמר רב פעם ראשונה ושניה דיה שעתה שלישית מטמאה מעת לעת ומפקידה לפקידה","ועוד עברו עליה ג' עונות וראתה דיה שעתה הדר קחזיא בעונות מאי","אמר רב כהנא אמר רב גידל אמר רב פעם ראשונה דיה שעתה שניה מטמאה מעת לעת ומפקידה לפקידה","מני רבי היא דאמר בתרי זימני הוי חזקה","אימא סיפא עברו עליה ג' עונות וראתה דיה שעתה אתאן לר\"א","וכי תימא רבי היא ובעונות סבר לה כר\"א ומי סבר לה והא לאחר שנזכר קאמר אלא ר\"א היא ובוסתות סבר לה כרבי","כתם שבין ראשונה ושניה טהור שבין שניה ושלישית חזקיה אמר טמא רבי יוחנן אמר טהור חזקיה אמר טמא כיון דאילו חזיא מטמאה כתמה נמי טמא ורבי יוחנן אמר טהור כיון דלא אתחזקה בדם כתמה נמי לא מטמינן לה"],[[0,"הדר קא חזיא בעונות","אחר ראיה זו:"],[0,"מאי","דיה שעתה או מטמאה מעת לעת מי אמרינן הא דקתני בתרה ועוד עברו עליה ג' עונות דוקא קתני עברו דאי חזאי לסוף עונה מטמאה מעת לעת דאע\"ג דלא הגיע זמנה כיון דהוחזקה רואה קודם הפסקת ג' עונות ראשונות הרי היא כהגיע זמנה וכי הפסיקה בראשונות וראתה דיה שעתה בההיא ראיה כר\"א וכי חזיא תו לסוף עונה מטמאה מעת לעת ככל אשה שעברו עליה ג' עונות דאין דיה שעתה אלא בראשונה אבל היכא דחזרו ועברו ג' שניות וראתה דיה שעתה בההיא ראיה כר\"א. ואע\"ג דלא חזינן דקמיירי רבי אליעזר אלא בהעברה ראשונה מיהו מודה דדיה שעתה בשניות עד דתתחזק או כרבי או כרשב\"ג ואע\"ג דרישא רבי היא סיפא כרשב\"ג דאי כרבי כיון דחזאי בעונות הוה מדמינן לה להגיע זמנה כי חזאי בהפסקה נמי כיון דתרי זימני חזאי בהפסקה איגלאי מילתא למפרע דשינוי וסת הוא ולא סילוק דמים ובשניה מטמאה מעת לעת שאין זו צריכה להתחזק בדמים או דילמא אי חזאי לסוף עונה נמי כ\"ש דדיה שעתה דמוכח מילתא דהפסקה ראשונה זו סילוק דמים היתה ולא שינוי וסת ויש לומר חזרה לקדמותה וצריכה להתחזק עוד אחר ההפסקה בשתי ראיות כבתחלה. והאי דנקט ועוד עברו וראתה דיה שעתה רבותא אשמעינן אע\"ג דתרי זימני חזאי בהפסקה לא אמרינן איגלאי מילתא דשינוי וסת הוא ולא סילוק דמים ותטמא בשניה מעת לעת אלא אפילו לרבי דיה שעתה דהפסקה קמייתא לעולם בחוזרת לקדמותה נדון אותה ולא דמיא להגיע זמנה וצריכה שתתחזק בשתי ראיות ובג' תטמא מעת לעת כדקתני ואזיל:"],[0,"אמר רב גידל פעם ראשונה","היא הראיה הסמוכה להפסקה ראשונה:"],[0,"ושניה","היא הראיה שתראה לסוף עונה דיה שעתה:"],[0,"ושלישית","אם תראה עוד לסוף עונה:"],[0,"מטמאה מעת לעת","והאי דנקט תנא ועוד עברו עליה ג' עונות רבותא הוא דנקט כדפי' דכל שכן אי חזאי בעונות דמוכחא מילתא דהפסקה קמייתא סילוק הואי וכולה רבי היא:"],[1,"ועוד עברו עליה ג' עונות וראתה דיה שעתה הדר קחזיא בעונות","אחר ראיה זו:"],[1,"מאי","דיה שעתה או מטמאה מעת לעת מי אמרינן הא דהדר תנא בתרא ראיה שלישית בהפסקה דוקא נקט דהכא הוא דמטמאה מעת לעת דאיגלאי מילתא דשינוי וסת הואי הפסקותיה לראות בדילוג שהרי הוחזקה בהפסקות וא\"נ לא חשבת להפסקה קמייתא בהדייהו הא מחזקא בתרתי בתרייתא אבל אי חזיא לסוף עונה הרי היא דיה שעתה דלא אתחזק בדילוג ואמרינן הפסקה שניה נמי חוזרת לקדמותה וכל דמיה מסולקין וצריכה להתחזק בשתי ראיות אחת הסמוכה להפסקה שניה והשניה היא שתראה לסוף עונה ובשלישית תטמא מעת לעת או דילמא כולי האי לא אמרינן דחזרה לקדמותה ובהפסקה שניה דיינינן לה כהגיע זמנה והפסיקה וראתה דבההיא ראיה לחודה הוא דדיה שעתה אבל בשניה תטמא מעת לעת. והאי דנקט תנא בשלישית ועוד עברו עליה וראתה מטמאה מעת לעת הוא הדין נמי אם לא עברו ורבותא אשמועינן דלא תימא כל ראיה הסמוכה להפסקה דיה שעתה אלא כיון דאיתחזק בדילוג אמרינן שינוי וסת הוא ולא סילוק דמים:"],[2,"אמר רב גידל אמר רב","ראשונה לסדר ראיות הללו שאנו עסוקין בהן לישאל קא חזיא בעונות מאי היא הראיה הסמוכה להפסקה שניה דעלה קיימינן דיה שעתה ושניה היא הראיה שתראה לסוף עונה מטמאה מעת לעת. והא דתנא הפסקה שלישית גבי מעת לעת לרבותא הוא דנקט כדפרישית דלא תימא כל ראיה שלאחר הפסקה תהא דיה שעתה:"],[3,"מני רבי היא","דהא בין רישא בין סיפא כרבי שנינן לה:"],[4,"אימא סיפא","דהגיע זמנה לראות אתאן לר\"א דאמר כל אשה שעברו עליה ג' עונות דיה שעתה. ומרישא דאיירי בלא הגיע זמנה לא מצי למיפרך ליה דאיכא למימר בההיא אפילו רבנן מודו דחוזרת לקדמותה היא:"],[5,"ובעונות סבר לה כרבי אליעזר","בהפסקת שלש עונות סבר לה כרבי אליעזר:"],[5,"והא לאחר שנזכר קאמר","למדנו שהוקשה בעיניו על שעשה כמותו:"],[5,"ובוסתות סבר לה כרבי","דאמר בתרי זימני הויא חזקה לכל דבר:"],[6,"כתם שבין ראשונה לשניה","שנמצא בבגדה של תינוקת שלא הגיע זמנה ודאי טהור דאכתי לאו בחזקת דמים היא ואמרינן לעיל (נדה דף ה.) תינוקת שלא הגיע זמנה לראות אפילו סדינין שלה כו':"],[6,"חזקיה אמר טמא","דהא בתרי זימני איתחזקה בדמים והויא חזקה דאילו הדרא חזיא מטמיא למפרע אלמא בחזקת דמים הוחזקה:"],[6,"ורבי יוחנן אמר טהור כיון דלא אתחזקה בדם","כלומר כל זמן שלא נהגנו בה עדיין תורת מוחזקת בדמים לטמאה למפרע לא גזרו על כתמה:"]],[[0,"","קחזיא בעונות מאי. פרש\"י דמבעיא ליה אי חזיא לסוף ל' שלאחר הפסקת ג' עונות ראשונות אם מטמאה מעת לעת דכיון דהוחזקה לרואה קודם הפסקת ג' עונות ראשונות הרי היא כהגיע זמנה לראות וככל אשה שעברו עליה ג' עונות דאין דיה שעתה אלא בראשונה ודוקא בחזרו ועברו עליה שלש עונות שניות דיה שעתה כר\"א ואע\"ג דלא חזינן דמיירי ר\"א בעונות שניות אלא בעונות ראשונות מיהו מודה דדיה שעתה בשניות [עד שתתחזק] או כרבי או כרשב\"ג ואע\"ג דרישא רבי היא סיפא רשב\"ג דלרבי כי חזיא לסוף עונות שאחר הפסקת שלש עונות (ראשונות) מטמאה מעת לעת ודמיא להגיע זמנה לראות וכי חזרו ועברו עליה שלש עונות שניות נמי מטמאה מעת לעת דכיון דתרתי זימני חזיא בהפסקה איגלאי מילתא לרבי דשינוי וסת הוא ולא סילוק דמים שאין זו צריכה להתחזק בדמים ולפי' זה הא דתניא (לעיל נדה דף ז:) זקנה שעברו עליה שלש עונות שניות דדיה שעתה אתיא דלא כרבי דלרבי מטמאה מעת לעת כאילו חזיא לסוף עונה וכן פי' רשב\"ם בפרק אחרון (דף סח.) ואין נראה דלא היה להש\"ס להסתפק בזה והיה לו לפסוק מדרישא רבי סיפא נמי רבי ובחזיא לסוף עונה נמי דיה שעתה כמו בחזרו ועברו עליה שלש עונות לכך נראה דאפילו מטמאה מעת לעת כי חזיא לסוף עונה שלאחר הפסקת שלש עונות ראשונות כהפסקת שלש עונות שניות דהויא מסולקת בדמים דיה שעתה אפילו לרבי כיון שלא הגיע זמנה לראות [ואין חילוק בין לא הגיע זמנה לראות לזקנה] וההיא ברייתא דזקנה נמי רבי היא וצ\"ע בהגיע זמנה לראות ועברו עליה שלש עונות שניות לר\"א מי אמרינן דיה שעתה כמו בזקנה לרבנן ומדלא אשמעינן בהגיע זמנה לראות דהוי דיה שעתה עד הפסקת שלש עונות שלישיות דהויא רבותא טפי מבלא הגיע זמנה לראות אין להוכיח דאפילו ראתה סוף שלש עונות שניות מטמאה מעת לעת דמצינו למימר דמשום הכי אשמעינן בלא הגיע זמנה לראות דאפילו הכי מטמאה בשלישית מעת לעת:"],[2,"","\u0003ברוב\u0004 ספרים גרסינן וכשהגיע זמנה לראות פעם ראשונה דיה שעתה שניה מטמאה מעת לעת מני רבי היא ושבוש הוא ולא גרסינן ליה אלא ה\"ג מני רבי היא ומוכח מרישא מתינוקת שלא הגיע זמנה לראות דקתני שלישית הרי היא ככל הנשים והיינו משום דבתרי זימני הוי חזקה ובההיא דמיתחזקא לא מטמאה מעת לעת דאילו לרשב\"ג עד ראיה רביעית לא הויא ככל הנשים אבל סיפא דהגיע זמנה לראות דשניה מטמאה מעת לעת אתי ככולי עלמא דבראייתה ראשונה הוחזקה כדתנן במה אמרו דיה שעתה בראיה ראשונה כו' ומתניתין ע\"כ אתיא כרשב\"ג דבפרק הבא על יבמתו (יבמות דף סד:) אמרינן וסתות ושור המועד סתם לן תנא כרשב\"ג אבל כרבי לא סתם לן תנא ועוד אי מסיפא דייק ורישא כרשב\"ג תקשי רישא רשב\"ג וסיפא רבי וא\"ת דהכא אמר דבההיא ראיה דמחזקינן לה לא מטמאה מעת לעת ובפרק אלו הנשרפין (סנהדרין דף פא:) גבי מי שלקה ושנה אמר דאין עבירות מחזקות אחר שעבר שתי עבירות מיד כונסין אותו לכיפה אליבא דרבי וי\"ל דהתם כיון שהוחזק לעבירה מה לנו להמתין עד שיעבור פעם שלישית אבל הכא חכמים תקנו מעת לעת אם תראה אחר שהוחזקה לראות:"],[6,"","רבי יוחנן אמר טהור. משמע הא כתם שאחר שלישי טמא דהיינו כרבי ובשלהי פרק הבא על יבמתו (יבמות דף סד:) אמר ר' יצחק בר' יוסי אמר רבי יוחנן גבי מלה בנה ראשון כו' כרבן שמעון בן גמליאל וי\"ל דהתם מסיק דר' יצחק סומקא לאו בר סמכא הוא אי נמי כל הך סוגיא קיימא אברייתא דלעיל דאתא כרבי:"]]],[["מתקיף לה ר' אלעאי וכי מה בין זו לבתולה שדמיה טהורין א\"ל ר' זירא זו שירפה מצוי וזו אין שירפה מצוי","אמר עולא א\"ר יוחנן משום ר\"ש בן יהוצדק תינוקת שלא הגיע זמנה לראות וראתה פעם ראשונה ושניה רוקה ומדרסה בשוק טהור כתמה נמי טהור ולא ידענא אם דידיה אם דרביה","למאי נפקא מינה למיהוי דבריו של אחד במקום שנים","כי אתא רבין וכל נחותי ימא אמרוה כר\"ש בן יהוצדק","אמר רב חלקיה בר טובי תינוקת שלא הגיע זמנה לראות אפילו שופעת כל ז' אינה אלא ראיה אחת אפילו שופעת ולא מבעיא פוסקת אדרבה פוסקת הויא לה כשתי ראיות","אלא תינוקת שלא הגיע זמנה לראות ושופעת כל ז' אינה אלא ראיה אחת","אמר רב שימי בר חייא מדלפת אינה כרואה והא קחזיא אימא אינה כשופעת אלא כפוסקת","מכלל דשופעת (נמי) כי נהרא אלא אימא אינה אלא כשופעת","תנו רבנן חזקה בנות ישראל עד שלא הגיעו לפרקן הרי הן בחזקת טהרה ואין הנשים בודקות אותן משהגיעו לפרקן הרי הן בחזקת טומאה ונשים בודקות אותן","רבי יהודה אומר אין בודקין אותן ביד מפני שמעוותות אותן אלא סכות אותן בשמן מבפנים ומקנחות אותן מבחוץ והן נבדקות מאיליהן","רבי יוסי אומר מעוברת וכו' תני תנא קמיה דר' אלעזר רבי יוסי אומר מעוברת ומניקה שעברו עליה ג' עונות דיה שעתה א\"ל פתחת בתרי וסיימת בחדא","דלמא מעוברת והיא מניקה קאמרת ומילתא אגב אורחיה קמ\"ל דימי עיבורה עולין לה לימי מניקותה וימי מניקותה עולין לה לימי עיבורה כדתניא ימי עיבורה עולין לה לימי מניקותה וימי מניקותה עולין לה לימי עיבורה","כיצד הפסיקה שתים בימי עיבורה ואחת בימי מניקותה שתים בימי מניקותה ואחת בימי עיבורה אחת ומחצה בימי עיבורה ואחת ומחצה בימי מניקותה מצטרפות לג' עונות","בשלמא ימי עיבורה עולין לה לימי מניקותה משכחת לה דקמניקה ואזלא ומיעברה אלא ימי מניקותה עולין לה לימי עיבורה היכי משכחת לה","איבעית אימא בלידה יבשתא ואיבעית אימא דם נדה לחוד ודם לידה לחוד ואיבעית אימא תני חדא","במה אמרו דיה שעתה וכו' אמר רב אכולהו","ושמואל אמר ל\"ש אלא בתולה וזקנה אבל מעוברת ומניקה דיין כל ימי עיבורן דיין כל ימי מניקותן","וכן אמר ר' שמעון בן לקיש אכולהו ורבי יוחנן אמר לא שנו אלא בתולה וזקנה אבל מעוברת ומניקה דיין כל ימי עיבורן דיין כל ימי מניקותן כתנאי מעוברת ומניקה שהיו"],[[0,"מתקיף לה רבי אלעאי","לחזקיה מה בין זו לבתולה שדמיה טהורין בתולה שנשאת יש שדמיה טהורין עד שתחיה המכה דתלינן בבתולים ויש שדמיה טהורין ד' לילות ויש שדמיה טהורין כל לילה הראשונה כדאמרינן פרק בתרא (לקמן נדה דף סד:) וכולהו קי\"ל דכל זמן שדמיה טהורין אין לה כתם דקתני בפ' האשה (לקמן נדה דף ס.) ושוין שתולה בשומרת יום כנגד יום בראשון שלה ובבתולה שדמיה טהורים מהתם שמעינן דאין לה כתם ואע\"ג דראתה פעם אחת דלא מפלגינן בין הגיע זמנה ללא הגיע בין שראתה פעם אחת בבית אביה שהיא אחת מן הבתולות שדמיה טהורין והא הכא דאילו חזת בשינוי מראה דמיה מטמאה מעת לעת דהגיע זמנה לראות וראתה בבית אביה אפילו הכי לא מטמאינן כתמה ומ\"ש הך מהא:"],[0,"זו שירפה מצוי","בתולה שדמיה טהורין שרף שלה מצוי מחמת בתולים הילכך כתמה טהור דתלינן בדם בתולין:"],[0,"וזו אין שירפה מצוי","לטהרה ולתלות בו:"],[1,"רוקה ומדרסה בשוק טהור","כגון שנמצא רוקה בשוק וקים לן שקודם לכן ראתה ב' פעמים ואין אנו יודעים אם נדה היא אם לאו מספיקא לא מחזקינן לה כספק הרוקין הואיל ולא הוחזקה רואה:"],[1,"ולא ידענא כו'","עולא הוא דקאמר לא ידענא אי א\"ר יוחנן מסקנא דהא מילתא דקאמר כתמה נמי טהור מדעתיה או משמיה דר\"ש בן יהוצדק כרוקה ומדרסה:"],[2,"דבריו של אחד במקום שנים","אי אמר להא וכתמה נמי טהור משמיה דרביה הוי חזקיה דאמר לעיל טמא אחד במקום שנים דהא פליג עליה ר' יוחנן לעיל מלביה וחזינן דקאי ר\"ש כוותיה:"],[3,"ה\"ג אמרו כר\"ש בן יהוצדק","בשמו של ר\"ש בן יהוצדק וה\"ל חזקיה אחד במקום ב' וש\"מ הלכה כר' יוחנן:"],[4,"אינה אלא ראיה אחת","לאחזוקה כרואה ודיה שעתה עד שתפסוק ותחזור ותראה שתי ראיות:"],[4,"ולא מבעיא פוסקת","וחוזרת ורואה:"],[5,"ושופעת כל שבעה","סמי מכאן אפילו:"],[6,"מדלפת","טיף אחר טיף:"],[6,"אינה כרואה","דמשמע דאפילו כראיה אחת אינה חשובה:"],[6,"אלא כפוסקת","והוו להו ראיות טובא והוחזקה רואה ולכשתפסוק ותחזור ותראה מטמאה מעת לעת:"],[7,"","ופרכינן מכלל דשופעת דאמר לעיל אינה אלא ראיה אחת היינו דשופעת כי נהרא בתמיה כיון דמדלפת אינה חשובה שופעת וא\"א להיות שופעת כמעין כל שבעה וחיה:"],[8,"בחזקת טומאה","כלומר בחזקת דמים מצוים בהם:"],[9,"שמעוותות אותן","כלומר מסרטין לה בצפורן ומייתו לה לידי ראיה:"],[9,"מבפנים","שסיכת שמן מביא הדם אם זמנו הוא:"],[10,"פתחת בתרתי","מעוברת ומניקה:"],[10,"וסיימת בחדא","דקאמר דיה שעתה דיין שעתן מיבעי ליה:"],[11,"מעוברת והיא מניקה","שנולד עוברה ומניקתו א\"נ מניקה ונתעברה והוא הדין למעוברת גרידתא והא דנקט מעוברת והיא מניקה לומר לך שמצטרפין ימי מניקה לימי עיבורה לג' עונות כגון שהפסיקה שתים בימי עיבורה ואחת בימי מניקותה או חלוף דהכי משמע מעוברת והיא מניקה בתוך הפסקת העונות הללו:"],[11,"ימי עיבורה עולין לה לימי מניקותה","כגון אם היתה מניקה ונתעברה והפסיקה תחלת עונה קצת בימי מניקותה והשלימה בימי עיבורה:"],[13,"אלא ימי מניקותה עולין לה לימי עיבורה היכי משכחת לה","דילדה ולא חזאי הא ראתה דם בלידתה ונמצא שלא עברו עליה ג' עונות:"],[14,"תני חדא","ימי עיבורה עולין לה לימי מניקותה ולא תיתני ימי מניקותה עולים לה לימי עיבורה:"],[15,"אכולהו","ד' נשים כולהו קתני לה דבשניה מטמאה מעל\"ע:"],[16,"בתולה וזקנה","בתולה כיון דראתה פעם ראשונה ושניה הוחזקה רואה. זקנה נמי כיון דאיתחזקא תרי זימני אחר ג' עונות אישתכח דלאו סילוק דמים הוא אלא דילוג וסת:"],[16,"אבל מעוברת ומניקה","ודאי דמיה מסולקין ואפילו לא נסתלקו מתחלתן מסתלקין והולכין הן תדיר. ברוך:"]],[[0,"","וכי מה בין זו לבתולה שדמיה טהורין. דאם נשתנו מראה דמיה למחרת מראיית שעת תשמיש טמאה ואילו מצאה כתם לאחר תשמיש טהורה כדאי' בפ' האשה (לקמן נדה דף ס.) תולה בבתולה שדמיה טהורין ומדלא מפליג משמע אפילו הדם משונה טהור ומשני הכא אין שירפה של טהרה מצוי דאם הכתם בא מגופה טמאה ודאי אבל התם שירפה של טהרה מצוי לכך טהורה דאיכא למימר האי כתם מעלמא בא ואפילו אי אתא מגופה איכא למימר דם בתולים הוא (ואיכא למימר) ולא חיתה עדיין המכה:"],[1,"","אמר רבי יוחנן משום רבי שמעון בן יהוצדק. משמע שהיה רבו ובפרק זה בורר (סנהדרין דף כו.) קרי ליה ר\"ל לר\"ש בן יהוצדק רועי בקר ולא היה מוחה ר' יוחנן על כבוד רבו ואומר ר\"ת דתרי הוו:"],[1,"","רוקה בשוק טהור. פי' בשוק שאין ידוע אם ראתה אם לאו אין להחזיקה כרואה כיון שלא הגיע זמנה לראות ולא ראתה שלשה פעמים ומיירי אפילו בבת ע\"ה אבל בבית ידוע אם ראתה אם לאו:"],[2,"","למהוי דבריו של אחד במקום שנים. וא\"ת ודילמא ר\"ש בן יהוצדק סבר לה כרשב\"ג דבג' זימני הוי חזקה וחזקיה נמי מודה דלרשב\"ג כתמה טהור וי\"ל דרוקה ומדרסה קיל טפי מבכתמה מדמספקא ליה בכתם אי טמא אם לאו וכיון דקיל טפי אי ס\"ל כרשב\"ג ה\"ל לטהר רוקה ומדרסה עד פעם רביעית:"],[8,"","הרי הן בחזקת טהרה. וא\"ת במתני' דקתני צריכה להיות בודקת חוץ מן הנדה כו' אמאי לא מפקא מי שלא הגיע זמנה וההוא דבנות כותים (לקמן נדה דף לח:) דכל י\"א בחזקת טהרה ומפרש בגמרא לענין שאינה צריכה בדיקה וי\"ל דלא מפרש במתני' אלא הנהו דאינן צריכים בדיקה מחמת דאין קפידא בראייתם דנדה בלאו הכי טמאה ויושבת על דם טוהר אפילו אם תראה לעולם טהור אבל לא הגיע זמנה לראות וי\"א דאינה צריכה בדיקה מחמת דמסולקין בדמים לא קתני:"],[10,"","פתחת בתרי וסיימת בחדא. וא\"ת והא במתני' נמי ד' נשים קתני במה אמרו דיה שעתה וי\"ל דהתם ליכא למיטעי אבל הכא איכא למיטעי ולומר מעוברת והיא מניקה:"],[11,"","דהויא מניקה ואיעברה. וא\"ת והיכי איעברה בלא ראיה והא אמרינן בשלהי המפלת (לקמן נדה לא:) דאין אשה מתעברת אלא סמוך לטבילתה או לוסתה וי\"ל דרוב פעמים כך הוא וזימנין דמיתרמי ומיעברה א\"נ בימים שהיא רגילה לראות אין מתעברת אלא סמוך לטבילתה או סמוך לוסתה:"],[16,"","דיין כל ימי עיבורן. משמע אפילו רואה כמה פעמים ואף על פי דבלא הגיע זמנה לראות אמר לעיל שלישית מטמאה מעת לעת היינו משום דכיון שהוחזקה לראות בטל הסילוק אבל הכא מעוברת ומניקה המסתלקין עדיין קיימים ואפילו לא נסתלקו בתחלה מסתלקין והולכין בסוף וא\"ת מ\"ש דלא הגיע זמנה לראות לא בעיא בדיקה ומעוברת ומניקה בעיא בדיקה כדקתני במתניתין צריכה להיות בודקת אכולהו וי\"ל דכל זמן שלא הוחזקה היא מסולקת בדמים יותר מכולן:"]]],[["שופעות דם ובאות דיין כל ימי עיבורן ודיין כל ימי מניקותן דברי ר\"מ רבי יוסי ור' יהודה ורבי שמעון אומרים לא אמרו דיין שעתן אלא בראייה ראשונה אבל בשניה מטמאה מעת לעת ומפקידה לפקידה","ואם ראתה ראשונה וכו' א\"ר הונא קפצה וראתה קפצה וראתה קפצה וראתה קבעה לה וסת למאי אילימא לימים הא כל יומא דלא קפיץ לא חזאי","אלא לקפיצות והתניא כל שתקבענה מחמת אונס אפילו כמה פעמים לא קבעה וסת מאי לאו לא קבעה וסת כלל","לא לא קבעה וסת לימים לחודייהו ולקפיצות לחודייהו אבל קבעה לה וסת לימים ולקפיצות לימים לחודייהו פשיטא אמר רב אשי כגון דקפיץ בחד בשבת וחזאי וקפיץ בחד בשבת וחזאי [ובשבת קפצה ולא חזאי] ולחד בשבת חזאי בלא קפיצה","מהו דתימא איגלאי מילתא למפרע דיומא הוא דקגרים ולא קפיצה קמ\"ל דקפיצה נמי דאתמול גרמא והאי דלא חזאי משום דאכתי לא מטא זמן קפיצה","לישנא אחרינא א\"ר הונא קפצה וראתה קפצה וראתה קפצה וראתה קבעה לה וסת לימים ולא לקפיצות היכי דמי א\"ר אשי דקפיץ בחד בשבת וחזאי וקפיץ בחד בשבת וחזאי (ובשבת קפצה ולא חזאי) ולחד בשבת (אחרינא) חזאי בלא קפיצה דהתם איגלאי מילתא דיומא הוא דקא גרים","\u0001מתני׳\u0002 אע\"פ שאמרו דיה שעתה צריכה להיות בודקת חוץ מן הנדה והיושבת על דם טוהר","ומשמשת בעדים חוץ מיושבת על דם טוהר ובתולה שדמיה טהורים","ופעמים צריכה להיות בודקת שחרית ובין השמשות ובשעה שהיא עוברת לשמש את ביתה יתירות עליהן כהנות בשעה שהן אוכלות בתרומה רבי יהודה אומר אף בשעת עברתן מלאכול בתרומה","\u0001גמ׳\u0002 חוץ מן הנדה דבתוך ימי נדתה לא בעי בדיקה","הניחא לרבי שמעון בן לקיש דאמר אשה קובעת לה וסת בתוך ימי זיבתה ואין אשה קובעת לה וסת בתוך ימי נדתה שפיר אלא לרבי יוחנן דאמר אשה קובעת לה וסת בתוך ימי נדתה תבדוק דילמא קבעה לה וסת","אמר לך רבי יוחנן כי אמינא אנא היכא דחזיתיה ממעין סתום אבל חזיתיה ממעין פתוח לא אמרי","והיושבת על דם טוהר קס\"ד מבקשת לישב על דם טוהר","הניחא לרב דאמר מעין אחד הוא התורה טמאתו והתורה טהרתו שפיר","אלא ללוי דאמר שני מעינות הם תבדוק דילמא אכתי לא פסק ההוא מעין טמא אמר לך לוי הא מני"],[[0,"שופעות","לאו דוקא:"],[1,"קפצה","הוי אונס:"],[1,"קפצה וראתה","ג' פעמים קבעה לה וסת כדמפרש ואזיל:"],[1,"אילימא לימים","כגון קפצה באחד בשבת וראתה וקפצה באחד בשבת וראתה וכן שלישית קבעה לה וסת באחד בשבת וכל זמן שתראה עוד באחד בשבת ואפילו בלא קפיצה דיה שעתה ואם הגיע אחד בשבת ולא בדקה עצמה טמאה מספק דאורח בזמנו הוא בא כל יומא באחד בשבת:"],[1,"דלא קפיץ לא חזאי","אלמא לאו וסתה הוא:"],[2,"אלא לקפיצות","כיון דראתה שלש פעמים על ידי קפיצה הורגלה לראיית קפיצה ובכל יום שתקפוץ מחזקינן לה ברואה ואם לא בדקה טמאה ואפילו שאר ימות שבת:"],[3,"לימים ולקפיצות","כל אחד בשבת שתקפוץ מחזקינן לה ברואה דזמנה הוא לראות באחד בשבת על ידי קפיצה:"],[3,"לימים לחודייהו פשיטא","דלא קבעה:"],[4,"דיומא הוא דקא גרים","ויהא באחד בשבת וסתה אפילו בלא קפיצה:"],[4,"קמ\"ל","הא דאמר דלא קבעה וסת לימים דקפיצה דאתמול גרמה לראייה דהאידנא ואין לה וסת באחד בשבת בלא קפיצה ולא לקפיצה בלא אחד בשבת מדלא חזיא מאתמול:"],[6,"מתני' אע\"פ שאמרו דיה שעתה","באשה שיש לה וסת:"],[6,"צריכה להיות בודקת","בכל יום שחרית וערבית כשאר נשים:"],[6,"חוץ מן הנדה","משראתה יום אחד טמאה שבעה ואינה צריכה בדיקה כל שבעה שהרי בלא ראייה היא טמאה:"],[6,"והיושבת על דם טוהר","דלמה לה בדיקה אפילו תראה דם טהורה היא:"],[7,"ומשמשת בעדים","אע\"פ שיש לה וסת צריכה לשמש בעדים ולבדוק לפני תשמיש ולאחר תשמיש:"],[7,"ובתולה שדמיה טהורין","ד' לילות דהיא אינה צריכה לשמש בעדים שהרי דמה טהור ואפילו נשתנו מראה דמיה הואיל ושמשה אמרינן דמשום תשמיש נשתנה אבל שחרית וערבית היכא דלא שמשה אחר בעילה ראשונה צריכה בדיקה כדמפרש בגמרא שמא נשתנו מראה דמים שלה:"],[8,"ופעמים צריכה להיות בודקת","כל אשה:"],[8,"שחרית ובין השמשות","שחרית להכשיר טהרות של לילה ערבית להכשיר טהרות של יום כדאמרינן טעמא בריש פירקין:"],[8,"לשמש את ביתה","עם בעלה:"],[10,"גמ' מתוך ימי זיבתה","כגון ראתה בראש חודש וחזרה וראתה בט\"ו לחודש כשעומדת בימים שהיא ראויה לזיבה דהיינו י\"א יום שבין נדה לנדה וחזרה וראתה בראש חודש ובט\"ו לחודש וחזרה וראתה בט\"ו לחודש ולא ראתה בראש חודש שלפניו שקבעה לה וסת לט\"ו בחודש ומצטרפין תרתי ראיות דימי זיבה להך ראייה לקביעות וסת:"],[10,"ואין אשה קובעת לה וסת בימי נדתה","כגון ראתה בראש חודש וחזרה וראתה בחמישי בחודש דהיינו בימי נדות וחזרה וראתה עוד פעמים בחמישי בחודש לא קבעה וסת שאין ראיית ימי נדה ראייה לקבוע שהיא עלולה לראות בימי נדותה:"],[10,"שפיר","קתני במתניתין דלא בעיא בדיקה דאי לטמויי טמאה היא ואי לקבוע וסת ולידע אם תשנה וסת שלשה פעמים ליום אחר שאינה למודה עד עכשיו הא אמרת דלא קבעה:"],[11,"ממעין סתום","כדמפרש אליבא דר' יוחנן בשילהי פ' בנות כותים (לקמן נדה דף לט:) כגון דחזאי ריש ירחא וריש ירחא ועשרים וחמשה וריש ירחא דהוה ראייה בתרייתא בימי נדותה דאפילו הכי הוה קביעות וסת בריש ירחא כדמפרש התם דאמר וסתה בריש ירחא קבעה והא דאקדים וחזאי דמים יתירי איתוספו בה דהא ודאי קבעה משום דתחילת הוסת הוחזק ממעין סתום וגם ראייה אחרונה חשבינן לה כמעין סתום כדאמר הא דאקדים וחזאי תוספת דמים הוא אבל ממעין פתוח כגון שהראיות הראשונות של וסת יהו בתוך ימי נדה כי מתניתין (דלא מיירי בתחלת נדה דהא לא מפליג בה מידי אלא סתמא קתני חוץ מן הנדה) הילכך לא בעיא בדיקה בימי נדות שהרי נפתח מעינה ואפילו היא רואה לא תקבע וסת. לישנא אחרינא ממעין סתום שראתה היום ופסקה וחזרה וראתה ברביעי או בחמישי לנדתה אבל ממעין פתוח כגון שלא פסקה וראתה א' ב' ג' ד' לחודש וראתה פעם שניה בד' בחודש וכן שלישית לא מהניא ראייה דרביעי בחודש דנדות קמא למיקבע ומתניתין במעיין פתוח וראשון ישר בעיני:"],[12,"מבקשת לישב","כשכלין ימי לידה כגון בשביעי לזכר או יום י\"ד לנקבה לא בעיא בדיקה דהא אפילו אינה רואה היא טמאה:"],[13,"הניחא לרב דאמר","בפרק בנות כותים (לקמן נדה דף לה:):"],[13,"מעין אחד הוא","דם הבא בתוך ז' של לידה ודם הבא לאחר שבעה ממעין אחד הוא:"],[13,"התורה טמאתו","תוך שבעה לזכר וי\"ד לנקבה:"],[13,"והתורה טהרתו","כל ימי הטוהר:"],[13,"שפיר","קתני מתניתין דלא בעיא בדיקה דהא בין פסקה ובין לא פסקה טמאה היום וטהורה למחר:"],[14,"אלא ללוי דאמר שני מעיינות הן","נפתח הטמא כל ימי הלידה ונסתם הטהור ולסוף שבעה לזכר וי\"ד לנקבה נסתם הטמא ונפתח הטהור ואוקימנא התם דשופעת מתוך שבעה לאחר שבעה ס\"ל ללוי דאפילו בשמיני לעולם היא טמאה עד שתפסוק דהא לא נסתם הטמא תבדוק בשביעי דילמא וכו':"]],[[2,"","אלא לקפיצות והתניא כו'. פרש\"י לקפיצות לחודייהו וקשה דאם כן לישני בסמוך לא קבעה וסת לימים אלא לקפיצות לחודייהו ולמה חוזר מסברתו ובסמוך נמי דפריך לימים פשיטא לישני דלא קבעה וסת לקפיצות לחודיה כדקס\"ד מעיקרא ונראה לפרש אלא לקפיצות אף לקפיצות דהיינו לימים עם קפיצות אבל קפיצות לחודייהו פשיטא להש\"ס דלא קבעה:"],[5,"","קפצה וראתה. ג' זימני גרסי' כדאמרינן [בהבא על יבמתו] (יבמות דף סד:) דבוסתות סתם לן תנא כרשב\"ג לקמן פרק האשה (נדה דף סג.) דתנן אין האשה קובעת וסת עד שתקבענו ג' פעמים:"],[11,"","ממעין סתום. פירש רש\"י כגון דחזאי ריש ירחא וריש ירחא וכ\"ה בירחא וריש ירחא ומעין פתוח כגון שהראיות הראשונות של וסת היו בתוך ימי נדה (או כ\"ה בירחא וריש ירחא) או ריש ירחא וה' בירחא וכן בשניה ובשלישית חזאי חמש בירחא ולא חזאי ריש ירחא וא\"ת ולרב פפא דמפרש שילהי בנות כותים (לקמן נדה דף לט:) ריש ירחא וחמש בירחא תרי זימני ובשלישי חמש בירחא ולא חזאי ריש ירחא דקבעה לה וסת בה' בירחא ברביעית קשה אליביה מתניתין לרבי יוחנן וי\"ל דאיהו יפרש מעין פתוח דחזאי שלשה זימני ריש ירחא וחמש בירחא ולמאי דפריש לקמן דר\"פ איירי דחזאי ג' זימנין ריש ירחא וחמש בירחא דהאי נמי מקרי מעין סתום יפרש מתני' מעין פתוח כפירוש אחר דרש\"י דפירש שראתה א' ב' ג' ד' רצופים בג' חדשים ראשונים:"]]],[["בית שמאי היא דאמרי מעין אחד הוא וסתם לן תנא כב\"ש סתם ואחר כך מחלוקת הוא וכל סתם ואח\"כ מחלוקת אין הלכה כסתם","ואבע\"א מי קתני מבקשת לישב יושבת קתני אי יושבת מאי למימרא מהו דתימא תיבדוק דדילמא קבעה לה וסת קמ\"ל דמעין טהור למעין טמא לא קבעה","הניחא ללוי דאמר שני מעינות הם אלא לרב דאמר מעין אחד הוא תבדוק דילמא קבעה לה וסת אפילו הכי מימי טהרה לימי טומאה לא קבעה","ומשמשת בעדים וכו' תנן התם תינוקת שלא הגיע זמנה לראות ונשאת ב\"ש אומרים נותנין לה ארבע לילות וב\"ה אומרים עד שתחיה המכה","אמר רב גידל אמר שמואל לא שנו אלא שלא פסקה מחמת תשמיש וראתה שלא מחמת תשמיש אבל פסקה מחמת תשמיש וראתה טמאה","עבר לילה אחת בלא תשמיש וראתה טמאה נשתנו מראה דמים שלה טמאה מתיב ר' יונה ובתולה שדמיה טהורים אמאי תשמש בעדים דדילמא נשתנו מראה דמים שלה","אמר רבא אימא רישא חוץ מן הנדה והיושבת על דם טוהר הוא דלא בעיא בדיקה אבל בתולה שדמיה טהורין בעיא בדיקה אלא קשיין אהדדי","כאן ששמשה דאימא שמש עכרן כאן שלא שמשה","תניא נמי הכי בד\"א שלא פסקה מחמת תשמיש וראתה שלא מחמת תשמיש","אבל פסקה מחמת תשמיש וראתה טמאה עבר לילה אחת בלא תשמיש וראתה טמאה נשתנו מראה דמים שלה טמאה","פעמים היא צריכה וכו' א\"ר יהודה אמר שמואל לא שנו אלא לטהרות אבל לבעלה מותרת פשיטא שחרית תנן","אלא אי אתמר אסיפא אתמר ובשעה שהיא עוברת לשמש את ביתה א\"ר יהודה אמר שמואל לא שנו אלא באשה עסוקה בטהרות דמגו דבעיא בדיקה לטהרות בעיא נמי בדיקה לבעלה אבל אינה עסוקה בטהרות לא בעיא בדיקה","מאי קמ\"ל תנינא כל הנשים בחזקת טהרה לבעליהן אי ממתני' הוה אמינא הני מילי באשה שיש לה וסת אבל אשה שאין לה וסת בעיא בדיקה","והא מתני' באשה שיש לה וסת עסקינן מתני' בין שיש לה וסת בין אין לה וסת והא קמ\"ל דאע\"ג דיש לה וסת מגו דבעיא בדיקה לטהרות בעיא נמי בדיקה לבעלה","והא אמרה שמואל חדא זימנא דאמר רבי זירא אמר רבי אבא בר ירמיה אמר שמואל אשה שאין לה וסת אסורה לשמש עד שתבדוק ואוקימנא בעסוקה בטהרות חדא מכלל חברתה אתמר","תניא נמי הכי בד\"א לטהרות אבל לבעלה מותרת בד\"א שהניחה בחזקת טהורה אבל הניחה בחזקת טמאה לעולם היא בטומאתה עד שתאמר לו טהורה אני"],[[0,"ב\"ש היא דאמרי","בפרק בנות כותים מעין אחד הוא:"],[1,"יושבת קתני","שכבר נכנסו ימי טוהר:"],[2,"דילמא קבעה לה וסת","תוך שמונים דנקבה ג' ראיות מעשרים לעשרים לרשב\"ג ולרבי ב' ראיות משלשים לשלשים שכשיכלו ימי טוהר ה\"ל וסת לעשרים:"],[3,"המכה","מכת בעילה דכל זמן שתהא רואה דם מחמת תשמיש דם בתולים הוא:"],[4,"לא שנו","אבית הלל קאי:"],[4,"שלא פסקה","ממראות דם:"],[4,"מחמת תשמיש","דכל זמן ששמשה ראתה:"],[4,"וראתה שלא מחמת תשמיש","כלומר אפילו חזרה וראתה ביום שלא מחמת תשמיש מחזקינן לה בדם בתולים הואיל ומחמת תשמיש לא פסקה:"],[4,"אבל פסקה מחמת תשמיש","ששמשה פעם אחת ולא ראתה ואחרי כן ראתה בין שראתה מחמת תשמיש בין שלא ראתה מחמת תשמיש טמאה דאמרינן כיון דבשעת תשמיש פסקה פעם אחת רגלים לדבר שהבתולים כלו כבר וזה ממקום טמא ירד:"],[5,"נשתנו מראה דמים","ממראה דם בעילה ראשונה:"],[5,"תשמש בעדים","אחד לפני תשמיש ואחד לאחר תשמיש:"],[7,"כאן ששמשה","הא דקתני שאינה משמשת בעדים משום דשמשה עכשיו דאי נמי חזיא לאחר תשמיש ונשתנו מראה הדם טהורין:"],[7,"דאימור שמש עכרן","אבר התשמיש:"],[7,"כאן שלא שמשה","הא דאמר נשתנו מראה דמים שלה טמאה שלא שמשה היום אלא בטהרות עסקה סמוך לבדיקה הילכך לענין טהרות שחרית וערבית בעיא בדיקה ולפני תשמיש היינו טעמא דלא בעיא בדיקה דכיון דלאחר תשמיש לא בעיא בדיקה לפני תשמיש נמי לא אצרכוה רבנן דאמרינן לקמן כל לבעלה לא בעיא בדיקה אלא מגו דבעיא בדיקה לאחר תשמיש לטהרות בעיא נמי בדיקה לפני תשמיש לבעלה והכא ליכא מגו. לישנא אחרינא כאן ששמשה לאחר תשמיש ראשון לא בעיא בדיקה ואפילו שחרית וערבית ואפילו נשתנו אימור שמש עכרן והא דתני נשתנו טמאין כשלא שמשה לאחר לילה הראשון ולאו טעמא הוא דא\"כ אפילו לא נשתנו נמי טמאה דהא עברה עליה לילה אחת בלא תשמיש אמרינן לעיל דטמאה:"],[10,"לא שנו","הא דתנן שחרית וערבית בודקת:"],[10,"אבל לבעלה מותרת","בלא בדיקה:"],[10,"פשיטא שחרית תנן","דטהרות הוא דהא אין משמשין מטה ביום:"],[11,"מגו דבעיא בדיקה לטהרות","לאחר תשמיש שמא ראתה לאחר תשמיש מחמת תשמיש:"],[11,"בעיא נמי בדיקה לבעלה","לפני תשמיש:"],[12,"הא נמי תנינא","במתני' פ\"ב (לקמן נדה טו.):"],[12,"בחזקת טהרה לבעליהן","ומתניתין דקתני דבעינן בדיקה על כרחך הכי מתרצת לה מתניתין דהכא בעסוקה בטהרות והתם בשאינה עסוקה בטהרות:"],[13,"והא מתני' דהכא ביש לה וסת עסקינן","דקתני ואע\"פ שאמרו דיה שעתה וכו' והא ודאי בשיש לה וסת ועלה מיירי שמואל ואמר אבל לבעלה מותרת אבל אין לה וסת לא קאמר:"],[13,"בין יש לה בין אין לה","דכיון דאמר יש לה וסת בעיא בדיקה כ\"ש דאין לה וסת ואכולהו קאמר שמואל אבל לבעלה מותרת. והא דאיירי מתניתין ביש לה וסת הא קא משמע לן דאף על גב כו':"],[14,"והאמר שמואל חדא זימנא","דאפילו אין לה וסת לא בעיא בדיקה לבעלה אלא אם כן רגילה לעשות טהרות:"],[14,"ואוקימנא","לקמן:"],[15,"במה דברים אמורים","דבעיא בדיקה:"],[15,"לטהרות","כלומר בעסוקה בטהרות אבל לבעלה גרידא שאינה עסוקה בטהרות לא:"]],[[2,"","אלא לרב דאמר מעין אחד הוא תבדוק. הוה מצי לשנויי דרב מוקי במבקשת לישב אלא דניחא ליה לשנויי אליבא דתרוייהו מתני' בענין אחד:"],[2,"","אפילו הכי מימי טהרה לימי טומאה לא קבעה. ואין להקשות לר\"א דאמר כל אשה שעברו עליה ג' עונות כו' תבדוק בימי טוהר שמא תפסוק ג' עונות דהכי נמי מימי טהרה לימי טומאה לא מקרי הפסקה:"],[3,"","ומשמשת בעדים. אארבע נשים ואאשה שיש לה וסת קאי:"],[4,"","שלא פסקה מחמת תשמיש. דכל פעם שמשמשת רואה אפילו תשמיש מופלג מחבירו חדש או שלשה חדשים הוי דם תשמיש וטהור כדאמר בפ' בתרא (לקמן נדה סה:) מעשה ונתן לה רבי ד' לילות מתוך שנים עשר חדש וכי שמשה בלילה וראתה למחרתו או בלילה שלאחר כך בלא תשמיש טהורה אבל אם ראתה יום שני לשמושה טמאה כדקאמר עבר עליה לילה אחת בלא תשמיש כו' וביום תשמיש נמי אם נשתנו מראה דמים שלה משל אמש טמאה ואם פסקה מחמת תשמיש וראתה אחרי כן אפילו באותו יום בין בתשמיש בין בלא תשמיש טמאה דודאי חיתה המכה וכלו בביאה ראשונה כל דמי בתולים ואפילו לרב אשי דאמר בפרק בתרא (נדה סד:) בעל ולא מצא דם וחזר ובעל ומצא דם טהורה היינו משום דאימא בביאה ראשונה בעל בהטייה כשמואל אבל הכא דבביאה ראשונה מצא דם ובשניה לא מצא דם ודאי חיתה המכה:"],[12,"","כל הנשים בחזקת טהרה לבעליהן. פירשתי לקמן פ\"ב (נדה דף טו.):"],[14,"","חדא מכלל חברתה איתמר. פי' רשב\"ם דהך דהכא איתמר מכלל ההיא דלקמן ואין נראה דבההיא לא פירש שמואל דאיירי בעסוקה בטהרות אלא רבא דייק בפירקין מדלא מפליג ליה רבי ירמיה בר אבא לרבי זירא ביש לה וסת לטהרות בעיא בדיקה לבעלה לא בעיא בדיקה אין לה וסת לבעלה נמי בעיא בדיקה ש\"מ קסבר שמואל כל לבעלה לא בעיא בדיקה לכך נראה לפרש דההיא איתמר מכלל הך דהכא ומשום דרבי אבא הוה ידע מהך דהכא דאף אין לה וסת לא בעיא בדיקה לבעלה לא מפליג לרבי זירא הכי:"],[15,"","תניא נמי הכי כו' אבל לבעלה מותרת. וא\"ת ודילמא דוקא ביש לה וסת איירי וי\"ל מדתני סיפא אבל הניחה בחזקת טמאה מכלל דמיירי באין לה וסת דאי ביש לה וסת דוקא ה\"ל לפלוגי בדידה אפילו אם הניחה בחזקת טהורה אם אין לה וסת כו' אלא משום דאף באין לה וסת לא משכחת טמאה לבעלה אלא בהניחה בחזקת טמאה ובסמוך בברייתא דחמרין ופועלין כו' דקתני נמי אבל הניחה בחזקת טמאה אע\"ג דביש לה וסת מיירי היינו משום דבהניחה בחזקת טמאה אשמועינן אפילו ערה טמאה עד שתאמר טהורה אני אבל הניחה בחזקת טהורה באין לה וסת היכא דערה לא בעיא בדיקה דכיון דבא מן הדרך מסתמא תובעה ואמרינן לקמן (נדה דף יב.) כיון שתבעה אין לך בדיקה גדולה מזו וה\"ר יהודה בן הר\"ר י\"ט כתב דרישא דברייתא זו הכי שנויה בתוספתא מעוברת ומניקה בועלה טהור פירוש אפילו לרבי עקיבא דאמר לעיל ברואה דם דמטמאה בועלה למפרע וכל אשה שיש לה וסת וכן שאר כל הנשים פי' דאין להן וסת דאין סברא לפרש בתולה וזקנה דאם כן הוה תני להו בהדי מעוברת ומניקה דרישא מטמאות במגע פירוש לטהרות וטהורות לבעליהן אלמא ברייתא מיירי דאין לה וסת:"]]],[["בעא מיניה רבי זירא מרב יהודה אשה מהו שתבדוק עצמה לבעלה אמר ליה לא תבדוק ותבדוק ומה בכך אם כן לבו נוקפו ופורש","בעא מיניה רבי אבא מרב הונא אשה מהו שתבדוק עצמה כשיעור וסת כדי לחייב בעלה חטאת","א\"ל מי משכחת לה לבדיקה כשיעור וסת והתניא איזהו שיעור וסת משל לשמש ועד שעומדים בצד המשקוף ביציאות השמש נכנס עד","הוי וסת שאמרו לקנוח ולא לבדיקה אלא מהו שתקנח","איכא דאמרי הכי בעא מיניה אשה מהו שתבדוק עצמה כדי לחייב בעלה אשם תלוי אמר לו לא תבדוק ותבדוק ומה בכך א\"כ לבו נוקפו ופורש","ובשעה שהיא עוברת וכו' אמר ר' אמי אמר רבי ינאי וזהו עדן של צנועות א\"ל רבי אבא בר ממל לר' אמי תנא תני צריכות ואת תני צנועות אמר ליה שאני אומר כל המקיים דברי חכמים נקרא צנוע","אמר רבא ושאינו מקיים דברי חכמים צנוע הוא דלא מקרי הא רשע לא מקרי אלא אמר רבא צנועות עד שבדקו בו עצמן לפני תשמיש זה אין בודקות בו לפני תשמיש אחר ושאינן צנועות בודקות ולא איכפת להן","גופא אמר רבי זירא אמר רבי אבא בר ירמיה אמר שמואל אשה שאין לה וסת אסורה לשמש עד שתבדוק אמר ליה ר' זירא לרבי אבא בר ירמיה אין לה וסת בעיא בדיקה יש לה וסת לא בעיא בדיקה","א\"ל יש לה וסת ערה בעיא בדיקה ישנה לא בעיא בדיקה אין לה וסת בין ערה בין ישנה בעיא בדיקה","אמר רבא ולימא ליה יש לה וסת לטהרות בעיא בדיקה לבעלה לא בעיא בדיקה אין לה וסת אפילו לבעלה נמי בעיא בדיקה ומדלא א\"ל הכי ש\"מ קסבר שמואל כל לבעלה לא בעיא בדיקה","ת\"ר חמרין ופועלין והבאין מבית האבל ומבית המשתה נשיהם להם בחזקת טהרה ובאין ושוהין עמהם בין ישנות בין ערות בד\"א שהניחן בחזקת טהרה אבל הניחן בחזקת טומאה לעולם היא טמאה עד שתאמר לו טהורה אני","והא שמואל במאי מוקי לה אי בשיש לה וסת קשיא ערה ואי בשאין לה וסת קשיא בין ערה בין ישנה","לעולם בשיש לה וסת וכיון שתבעה אין לך בדיקה גדולה מזו אמר ליה רב פפא לרבא מהו למעבד כי הא מתניתא"],[[1,"כשיעור וסת","מיד לאחר בעילה בחטאת דאמרינן לקמן בפ\"ב (נדה דף יד.) נמצא על סדין שלה אותיום כלומר מיד לאחר בעילה חייבין בקרבן דודאי דם הוה בשעת ביאה:"],[2,"לבדיקה","לחורין ולסדקין הילכך כשיעור וסת לא משכחת לה:"],[2,"לשמש","אבר:"],[2,"ועד","סדין שמקנחת בו:"],[3,"לקינוח","מבחוץ. אם בקינוח מצאה דם בכשיעור הזה חייבין חטאת אבל אם בבדיקתה מצאה כבר ארך השיעור שהרי לא בצד המשקוף עומד אלא בידה אוחזתו ויש כאן שיעור עודף כדי הבאה מידה למשקוף ואשם תלוי איכא ולא חטאת:"],[3,"מהו שתקנח","אשה שאינה עסוקה בטהרות מי בעיא קינוח לאחר תשמיש כשיעור וסת לידע אם תמצא דם ויהא בעלה חייב חטאת:"],[4,"מהו שתבדוק","בדיקה ממש:"],[4,"באשם תלוי","דאמרינן לקמן (שם:) נמצא על שלה לאחר זמן יותר מכשיעור וסת חייבין באשם תלוי דספק הוה דם בשעת ביאה ספק בא לאחר מכאן:"],[4,"א\"כ","שתצריכנה לבדוק אחר ביאה:"],[4,"לבו נוקפו","קודם ביאה והא דתנן לקמן (שם.) דרך בנות ישראל משמשות בשני עדים בעסוקות בטהרות:"],[5,"וזהו עדן של צנועות","כלומר מדת חסידות שנו כאן ולאו חיובא הוא דאמרינן בפרק שני (שם.) הצנועות מתקנות להן שלישי לתקן את הבית. זהו עדן אלפני תשמיש קאי:"],[6,"אין בודקת בו לפני תשמיש אחר","לפי שמטונף וכהה מראית ליבונו בבדיקה ראשונה ושוב אין נראית בו טיפה כחרדל:"],[7,"יש לה וסת לא בעיא בדיקה","בתמיה. והא קתני מתניתין ביש לה וסת דבעיא בדיקה כיון דעסוקה בטהרות. ולקמן פריך לישני ליה הא בשאינה עסוקה בטהרות ומשני קסבר שמואל כי אינה עסוקה אפילו אין לה וסת לא בעיא בדיקה לבעלה הואיל ואינה עסוקה בטהרות:"],[8,"ערה","דחזיא לעסוקי בטהרות בעיא בדיקה לבעלה אי נמי דליכא טירחא לצעורה אבל ישנה איכא צערא ולא אטרחוה רבנן אי נמי ישנה דלא חזיא לטהרות אפילו רגילה לעסוק בטהרות לא בעיא בדיקה:"],[9,"לטהרות בעיא בדיקה","כלומר העסוקה בטהרות בעיא בדיקה אפילו לבעלה:"],[9,"לבעלה לא בעיא בדיקה","היכא דאינה עסוקה:"],[9,"אין לה וסת אפילו לבעלה","גרידא דאינה עסוקה בטהרות בעיא בדיקה:"],[9,"כל לבעלה","בלא טהרות:"],[9,"לא בעיא בדיקה","אפילו אין לה וסת הילכך הא דאמר שמואל אסורה לשמש עד שתבדוק בעסוקה [בטהרות] קאי והיינו דאמר לעיל ואוקימנא בעסוקה בטהרות:"],[12,"כיון שתבעה","לתשמיש:"],[12,"אין לך בדיקה גדולה מזו","דאי לא קים לה דטהורה היא הוה בדקה ובדיקה דקאמר שמואל לעיל בתביעה סגי ולבי מגמגם:"],[12,"כי הא מתניתא","בעיא בדיקה או תביעה:"]],[[0,"","בעי ר' זירא אשה מהו שתבדוק. פי' לפני תשמיש:"],[0,"","לבו נוקפו ופורש. פר\"ח כיון דרואה אשתו בודקת מחשב שאם לא הרגישה לא היתה בודקת לפי שיודעת שחכמים לא תקנו לבדוק:"],[1,"","כדי לחייב בעלה חטאת. הכא נמי הוה מצי למיבעי מהו שתבדוק קודם תשמיש ותניח העד עד הבקר כדי לחייב בעלה חטאת אלא דכבר השיב לו שאם תבדוק לפני תשמיש לבו נוקפו ופורש:"],[6,"","צנוע לא מיקרי רשע לא מיקרי. בתמיה וא\"ת בריש כתובות (דף ב:) דאמר משום צנועות ומשום פרוצות כיון דקרי להו צנועות הנהו דלא עבדי הכי אמאי קרי להו פרוצות וי\"ל דהתם קרי להו צנועות כדאמרינן התם זמנין דלא אניס וסברה דאניס ואע\"ג שבדין היה לה לתלות שאין אניס דרוב העולם אינן אנוסים ופרוצות משום דזימנין דאנוס פירוש פעמים דיודעת שהוא אנוס ואמרה דלא אנוס ול\"ג התם וסברה:"],[7,"","אשה שאין לה וסת אסורה לשמש עד שתבדוק. ובעסוקה בטהרות איירי וא\"ת מאי קמ\"ל מתניתין היא (לעיל נדה יא.) ובשעה שהיא עוברת לשמש את ביתה וליכא למימר דאתא לאשמועינן דאע\"ג דאין לה וסת דמותר לקיימה על ידי בדיקה כר\"ח בן אנטיגנוס וכן פירש רש\"י לקמן דהלשון משמע דלא בא להשמיענו היתרא אלא להשמיענו שצריכה בדיקה וי\"ל דקמ\"ל באין לה וסת דאפילו ישנה צריכה בדיקה:"],[10,"","בין ישנות. פי' דליכא איסור נדות אבל אסור לבא על הישנה כדאמר בנדרים (כ:) א\"נ הכא לא לגמרי בישנה איירי אלא אינה ערה כל כך שתדע להשיב אם היא טהורה אם לאו:"],[11,"שמואל במאי מוקי לה","וא\"ת ולוקמה באינה עסוקה בטהרות ויש לומר דדייק מלישנא יתירא דקתני נשיהם להם בחזקת טהרה ואמאי איצטריך תו למיתני ובאין ושוהים עמהם אלא לגלויי דאיירי דעסוקה בטהרות ובפ\"ב (לקמן נדה דף טו.) דקתני כל הנשים בחזקת טהרה וקתני בתר הכי והבאין מן הדרך נשיהם להם בחזקת טהרה וקתני תרתי אע\"ג דאינה עסוקה בטהרות איירי התם אשמועינן דאין לחלק בין באין מן הדרך לבני העיר וא\"ת בלא שמואל תקשי מתניתין דמצרכת בדיקה בעסוקה בטהרות אברייתא דהכא וי\"ל דפריך לשמואל אפילו בישנה באין לה וסת אבל מתני' לא מיירי בישנה וכן פי' רשב\"ם. [א\"נ ממתני' ה\"מ לדחוקי ולאוקומי באין לה וסת ודיה שעתה לא קאי אלא אצריכה להיות בודקת ותו לא אע\"ג דפשטא דמתניתין ביש לה וסת כדפריך לעיל והא מתניתין ביש לה וסת עסקינן]:"],[12,"","כיון שתבעה. פירוש כיון שבא מן הדרך מפייסה ותובעה לתשמיש ואי חזיא כבר רמיא אנפשה שהרגישה בשעת ראייה וזוכרת אבל אם לא בא מן הדרך אסור בערה לפי שאינו מאריך בפיוס של תשמיש אלא בא עליה מיד ולא רמיא אנפשה לאזכורי שהרגישה:"],[12,"","מהו למעבד כי הא מתניתא. פי' רש\"י כי הא מתניתא דבעיא בדיקה או תביעה וקשה דבערה דוקא מצריך בדיקה ואם כן מאי קא מהדר ליה דמגניא באפיה דבתביעה לא מגניא באפיה ועוד אי לבעלה גרידא קבעי כדמשמע דלבני בבל היה שואל הא פשיטא דאמר לעיל (נדה דף יא:) כל לבעלה לא בעיא בדיקה וגם אין להחמיר לבדוק דא\"כ לבו נוקפו ופורש כדאמר לעיל ואי בעסוקה בטהרות קבעי פשיטא שצריכה בדיקה כדתנן ובשעה שהיא עוברת לשמש ביתה כו' ותו למה תולה בעייתו בברייתא זו כיון דמתניתין נמי מצרכה בדיקה לטהרות ונראה לפרש מהו למעבד כי הא מתניתא דלא מצרכה מידי בישנה דשמא אף לבעלה גרידא צריך להקיצה ולתובעה והא דאמרינן לעיל דאפילו באין לה וסת לא בעיא בדיקה לבעלה בישנה מ\"מ דילמא תביעה בעיא אי נמי לעיל איירי כשהוא בעיר דאם איתא דהיתה טמאה הוה אמרה ליה קודם לכן אבל בבא מן הדרך איכא למיחש ומתני' דפ\"ב (לקמן נדה טו.) דבאין מן הדרך נשיהם להם בחזקת טהרה איכא נמי למימר דהיינו דלא בעו בדיקה אבל בעו תביעה אי נמי בערות דווקא אי נמי ביש לה וסת:"]]],[["א\"ל סודני לא דמגניא באפיה אמר רב כהנא שאלתינהו לאינשי ביתיה דרב פפא ודרב הונא בריה דרב יהושע כי אתו רבנן מבי רב מצרכי לכו בדיקה ואמרו לי לא ולישיילינהו לדידהו דילמא אינהו קא מחמירי אנפשייהו","ת\"ר אשה שאין לה וסת אסורה לשמש ואין לה לא כתובה ולא פירות ולא מזונות ולא בלאות ויוציא ולא מחזיר עולמית דברי ר\"מ","רבי חנינא בן אנטיגנוס אומר משמשת בשני עדים הן עותוה הן תקנוה משום אבא חנן אמרו אוי לו לבעלה","אסורה לשמש דילמא מקלקלת ליה ואין לה כתובה כיון דלא חזיא לביאה לית לה כתובה","ולא פירות ולא מזונות ולא בלאות תנאי כתובה ככתובה דמו","ויוציא ולא יחזיר עולמית פשיטא לא צריכא דהדרה ואתקנה מהו דתימא ליהדרה קמ\"ל דזימנין דאזלא ומנסבא ומתקנא","ואמר אילו הייתי יודע שכך היה אפילו הייתם נותנין לי מאה מנה לא הייתי מגרשה ונמצא גט בטל ובניה ממזרין","משום אבא חנן אמרו אוי לו לבעלה איכא דאמרי לר\"מ אמר ליה דבעי לאגבויה כתובתה איכא דאמרי לרבי חנינא בן אנטיגנוס קא\"ל דמקלקלת ליה","אמר רב יהודה אמר שמואל הלכה כר' חנינא בן אנטיגנוס ובמאי אי בעסוקה בטהרות הא אמרה שמואל חדא זימנא","ואי בשאינה עסוקה בטהרות הא אמר כל לבעלה לא בעיא בדיקה דא\"ר זירא א\"ר אבא בר ירמיה אמר שמואל אשה שאין לה וסת אסורה לשמש עד שתבדוק ואוקימנא לה בעסוקה בטהרות מאן דמתני הא לא מתני הא","\u0001הדרן עלך שמאי אומר\u0002"],[[0,"סודני","תלמיד חכם על שם (תהלים כה) סוד ה' ליראיו:"],[0,"לא","בעיא בדיקה דכי מצטרכא לה בדיקה מיגניא באפיה. ל\"א מהו למעבד כי הא מתניתא דלא בעיא בדיקה דאיהו ס\"ל באין מן הדרך לאו דוקא וכ\"ש יושב בביתו. אמר ליה סודני רב פפא מטיל שכר הוא כדאמר באיזהו נשך (ב\"מ דף סה.) שיכראי לא פסיד ומטיל שכר נקרא סודני כדאמרינן בערבי פסחים (פסחים דף קיג.) תמרי בחלוזך לבי סודנא רהוט:"],[0,"לא מיגניא באפיה","בתמיה. אם אתה מצריכה בדיקה והלא תמאס ותתגנה בפניו:"],[0,"דלמא אינהו מחמירי אנפשייהו","ומצריכים בדיקה לנשותיהן ומורים לאחרים היתר כהילכתא דאוקימנא דלא בעיא בדיקה לפיכך שאל לנשותיהן דאיהו נמי בעי לאחמורי כוותייהו. לישנא אחרינא אינהו מחמירי אנפשייהו ומורים דצריכה בדיקה להחמיר והם אין מצריכין נשותיהן לבדוק ושיבוש הוא דלאו היינו מחמירי אנפשייהו אלא מקילי אנפשייהו ומחמירי לאחרים וחלילה לעשות כן:"],[1,"ולא פירות","שאוכל בעלה מנכסי מלוג שלה ולא אמרינן כיון דאין לה כתובה הימנו אישתכח דלאו אשתו היא וליהדר לה פירי דאכל:"],[1,"ולא מזונות","אם הלך למדינת הים קודם שגרשה אין בית דין פוסקים לה מזונות מנכסיו:"],[1,"ולא בלאות","כגון אם הכניסה לו בגדים בשומת כתובתה ואמרינן בכתובות (דף עט:) עיילא ליה גלימא מכסי בה ואזיל עד דבלי וזו כשמגרשה אע\"ג שקצת הבלאות קיימין אין מחזירין לה:"],[2,"בשני עדים","סדינין:"],[2,"עותוה","אי חזאי:"],[2,"תקנוה","אי לא חזאי:"],[2,"אוי לבעלה","כדמפרש לקמן:"],[4,"מזונות","תנאי כתובה הן את תהא יתבא בביתי ומיתזנא מנכסי ובלאות נמי משומת כתובה הן ששמו לה מה שהיא מכנסת והוא מקבלן עליו לשלם לכשימות או לכשיגרשנה כמו שאנו כותבין ודין נדוניא דהנעלת ליה וכו':"],[6,"ובניה ממזרים","הילכך אומרים לו הוי יודע שהמגרש את אשתו משום וסת לא יחזיר ואפילו היא חוזרת וקובעת ותו לא מצי למימר אילו הייתי יודע שכך כו' שהרי התרו בו וגמר בדעתו וגרשה והכי נמי אמרינן גבי מוציא את אשתו משום שם רע או משום נדר במס' גיטין (דף מו.):"],[7,"דבעי לאגבויה כתובתה","והכי קאמר ליה את אמרת אין לה כתובה ואנא סבירא לי אוי לו לבעלה שנחסר ממונו דודאי יש לה כתובה:"],[7,"דמקלקלה ליה","את אמרת משמשת בעדים אוי לבעלה דדילמא לא חזיא לפני תשמיש וחזיא בשעת תשמיש:"],[8,"הא אמר שמואל חדא זימנא","כדמותיב ואזיל מדר' אבא בר ירמיה ומינה שמעינן דס\"ל לשמואל דעסוקה בטהרות בעיא בדיקה לבעלה ושאינה עסוקה בטהרות לא בעיא בדיקה:"],[9,"מאן דמתני הא לא מתני הא","לעולם בעסוקה ודקשיא לך תרתי למה לי רב יהודה דמתני הא משמיה דשמואל לא מתני הא דר' אבא ורבי אבא לא מתני הא דרב יהודה. ואי קשיא הא רב יהודה נמי אמרה דאמר רב יהודה לעיל גבי מתני' דקתני לעיל ובשעה שהיא עוברת לשמש את ביתה ואמר רב יהודה אמר שמואל לא שנו אלא בעסוקה כו' לאו פירכא היא דרב יהודה לא אשמועינן התם בעסוקה מידי דממתני' הוה שמעינן בין עסוקה בין אינה עסוקה ואתא רב יהודה למימר ואשמועינן משמיה דשמואל דשאינה עסוקה לא בעיא בדיקה והכא אשמועינן דהלכה כר\"ח וכאותה משנה דעסוקה בטהרות בעיא בדיקה והכא עיקר. ואית דמפרשי כי האי לישנא והאמר שמואל חדא זימנא לעיל דאוקימנא למתני' דקתני משמשת בעדים בעסוקה בטהרות מאן דמתני הא כו' לעולם בשאינה עסוקה ודקשיא לך דרבי אבא בר ירמיה אהא דרב יהודה לא תקשי אמוראי נינהו אליבא דשמואל וטועין בדבר דא\"כ קשיא דרב יהודה אדרב יהודה דהא איהו גופיה אמר דשאינה עסוקה לא בעיא בדיקה:"]],[[0,"","אמר ליה מגניא באפיה. פירוש אם צריך להקיצה עד שתתיישב דעתה להשיב אם טהורה היא אם לאו:"],[0,"","מי מצריכי לכו בדיקה. פירוש להקיץ אתכם עד שתתיישב דעתכם להשיב אם טהורה היא וכגון שהיו באין מדי שבת או מדי חדש אבל לא לזמן מרובה כדאמר לקמן (נדה דף טו.) והוא שבא תוך ימי עונתה אבל יותר יש לחוש שמא ראתה בינתיים:"],[1,"","לא פירות. נכסי מלוג שאכל ולא דין פירות דהיינו פרקונה ואיירי בין הכיר בה ובין לא הכיר בה דבלא הכיר בה הוי מקח טעות ומחלה ליה דניחא לה דניפוק עלה שמא דאישות כדאמרינן גבי אילונית בפרק איזהו נשך (ב\"מ דף סז.) ובהכיר בה נמי אין לה כלום כדאמר ביש מותרות (יבמו' פה:) בשניו' לעריות שהיא מרגילתו משום דזרעה כשר:"],[3,"","כיון דלא חזיא לביאה לית לה כתובה. אע\"ג דאיכא מאן דאמר בפ' בנות כותים (לקמן נדה דף לט.) אפילו לר\"מ אשה שאין לה וסת מותרת לשמש בי\"א שבין נדה לנדה לפי שהיא מסולקת מדמים מ\"מ צריך לגרשה דילמא מקלקלת ליה בשאר יומי וכיון דאסור לקיימה אין לה כתובה וכל זמן שלא גרשה מותר לשמש באותן י\"א יום ולאבא חנן דאית לה כתובה היינו משום דמותרת לשמש בי\"א יום כיון דחזיא לביאה אע\"פ שגזרו חכמים עליו לגרשה לא תפסיד בכך כתובתה:"],[6,"","אילו הייתי יודע שכך הוא. וא\"ת והא כיון דאינה תובעת כתובתה לא מצי להוציא לעז כדאמר בפרק הבא על יבמתו (יבמות דף סה.) גבי נשאת לשלישי ולא היו לה בנים ונשאת לרביעי והיו לה בנים כו' וקאמר אומרים לה שתיקותיך יפה ליך מדבוריך שלא יוציא לעז ויאמר אילו הייתי יודע כו' ופריך אי איהי שתקה אנן מי שתקינן ומשני השתא הוא דבריאת וי\"ל דהכא בקל ע\"י סממנים תחזיר לוסתה ואיכא לעז טפי ולא דמי לעקרה דאין לה רפואה בקל לבא לידי בנים ומשמיא הוא דמסו לה והר\"ר שלמה מדריו\"ש תירץ דהכא איכא למיחש דמתקנא וקבעה לה וסת כמו שהיה סמוך לגרושין דאיגלאי מילתא דבעוד שהיא תחתיו איברית ולא השתא והכא לא שייך למיפרך אנן מי שתקינן כיון דלא שייך כאן לומר השתא הוא דאיברית דכיון שאומרים לו הוי יודע כו' תו ליכא לעז וכן לר\"י בהשולח (גיטין דף מו: ושם) גבי אילונית לא שייך למפרך אע\"ג דאינו כ\"א חשש אילונית דודאי אילונית אין לה רפואה ולא שייך השתא הוא דאיברית דכיון שאומרים לו הוי יודע מגרשה לגמרי [אבל אם תובעת כתובתה יכול לומר אדעתא דהכי לא גירשתיך] וגבי נשאת לרביעי אין צ\"ל הוי יודע דאינו יכול להוציא לעז דאיכא למימר השתא הוא דאיברית ואי לאו טעמא דהשתא הוא דאיברית אפילו לרבנן לא חיישינן לקלקול גבי אילונית לא הוה שתקינן משום דכיון דכבר גרשה ראשון ושני ניכר שגם השלישי שגרשה משום בנים מגרשה ואיכא לעז אי לאו טעמא דהשתא הוא דאיברית:"],[9,"","דמתני הא לא מתני הא. פירש רש\"י רב יהודה דפסיק הלכה כר\"ח דאיירי בעסוקה בטהרות לא מתני ההיא דר' אבא בר' ירמיה והקשה רש\"י הא רב יהודה גופיה אמר משמיה דשמואל לא שנו אלא לטהרות ותירץ דהתם לא אשמועינן רב יהודה אלא דלבעלה לא בעיא בדיקה וא\"ת והא מתני' ביש לה וסת אבל אין לה וסת איכא למימר דאסורה כר\"מ א\"כ שמואל דאוקמא אפילו באין לה וסת משמע דסבר כר\"ח בן אנטיגנוס וי\"ל דמתני' משמע שפיר גם באין לה וסת וה\"ק אפילו אותה שדיה שעתה משמשת בעדים וכ\"ש שאין לה וסת וא\"ת ואמאי לא משני הכא דחדא מכלל חברתה איתמר כדלעיל וי\"ל דלעיל אינו בפירוש בדברי רבי אבא בר ירמיה דלבעלה לא בעיא בדיקה ואף רבי אבא לא חילק לר' זירא בין יש לה וסת לאין לה וסת בין טהרות לבעלה משום דשמיע לה מכלל דרב יהודה דלבעלה לא בעיא בדיקה אבל הכא פירש בהדיא משמיה דשמואל דאין לה וסת מותר לקיימה אם תבדוק וכן בפסקא דהלכה כר\"ח אין להקשות דמה צריך לפסוק כר\"ח כיון דבעסוקה בטהרות איירי וכי הילכתא למשיחא דהא בא\"י לעולם היו עסוקים בטהרות כדאמר לעיל (נדה דף ו:) חבריא מדכן בגליל:"]]],[["מתני׳ \u0001כל\u0002 היד המרבה לבדוק בנשים משובחת ובאנשים תקצץ","\u0001גמ׳\u0002 מ\"ש נשים ומאי שנא אנשים נשים לאו בנות הרגשה נינהו משובחות אנשים דבני הרגשה נינהו תקצץ","אי הכי מאי איריא מרבה כי לא מרבה נמי כי קתני מרבה אנשים","תנא בד\"א לענין שכבת זרע אבל לענין זוב אף הוא משובח כנשים","ואפי' לענין שכבת זרע אם בא לבדוק בצרור או בחרס בודק","ובמטלית לא והתניא בודק עצמו במטלית ובכל דבר שרוצה כדאמר אביי במטלית עבה הכא נמי במטלית עבה","והיכא איתמר דאביי אהא דתנן היה אוכל בתרומה והרגיש שנזדעזעו איבריו אוחז באמתו ובולע את התרומה","אוחז והתניא רבי אליעזר אומר כל האוחז באמתו ומשתין כאילו מביא מבול לעולם אמר אביי במטלית עבה","רבא אמר אפילו תימא במטלית רכה כיון דעקר עקר ואביי חייש דלמא אתי לאוסופי ורבא לא חייש דלמא אתי לאוסופי","ולא והתניא הא למה זה דומה לנותן אצבע בעין שכל זמן שאצבע בעין עין מדמעת וחוזרת ומדמעת","ורבא כל אחמומי והדר אחמומי בשעתיה לא שכיח","גופא ר\"א אומר כל האוחז באמה ומשתין כאילו מביא מבול לעולם אמרו לו לרבי אליעזר והלא נצוצות נתזין על רגליו ונראה ככרות שפכה ונמצא מוציא לעז על בניו שהן ממזרים","אמר להן מוטב שיוציא לעז על בניו שהן ממזרים ואל יעשה עצמו רשע שעה אחת לפני המקום","תניא אידך אמר להן רבי אליעזר לחכמים אפשר יעמוד אדם במקום גבוה וישתין או ישתין בעפר תיחוח ואל יעשה עצמו רשע שעה אחת לפני המקום","הי אמר להו ברישא אילימא קמייתא אמר להו ברישא בתר דאמר להו איסורא הדר אמר להו תקנתא","אלא הא אמר להו ברישא ואמרו ליה אין לו מקום גבוה ועפר תיחוח מאי אמר להן מוטב שיוציא לעז על בניו ואל יעשה עצמו רשע שעה אחת לפני המקום","וכל כך למה מפני שמוציא שכבת זרע לבטלה דא\"ר יוחנן כל המוציא שכבת זרע לבטלה חייב מיתה שנאמר (בראשית לח, י) וירע בעיני ה' (את) אשר עשה וימת גם אותו","רבי יצחק ורבי אמי אמרי כאילו שופך דמים שנאמר (ישעיהו נז, ה) הנחמים באלים תחת כל עץ רענן שוחטי הילדים בנחלים תחת סעיפי הסלעים אל תקרי שוחטי אלא סוחטי","רב אסי אמר כאילו עובד עבודת כוכבים כתיב הכא תחת כל עץ רענן וכתיב התם (דברים יב, ב) על ההרים הרמים ותחת כל עץ רענן","רב יהודה ושמואל הוו קיימי אאיגרא דבי כנישתא דשף ויתיב בנהרדעא אמר ליה רב יהודה לשמואל צריך אני להשתין א\"ל שיננא אחוז באמתך והשתן לחוץ","היכי עביד הכי והתניא ר\"א אומר כל האוחז באמתו ומשתין כאילו מביא מבול לעולם","אמר אביי עשאו כבולשת דתנן בולשת שנכנס לעיר בשעת שלום חביות פתוחות אסורות סתומות מותרות בשעת מלחמה אלו ואלו מותרות לפי שאין להן פנאי לנסך אלמא דכיון דבעיתי לא אתי לנסוכי הכא נמי כיון דבעיתי לא אתי להרהורי","והכא מאי ביעתותא איכא איבעית אימא ביעתותא דליליא ודאיגרא ואיבעית אימא ביעתותא דרביה ואב\"א ביעתותא דשכינה ואיבעית אימא אימתא דמריה עליה דקרי שמואל עליה אין זה ילוד אשה","ואיבעית אימא נשוי הוה דאמר רב נחמן אם היה נשוי מותר","ואיבעית אימא כי הא אורי ליה דתני אבא בריה דרבי בנימין בר חייא אבל מסייע בביצים מלמטה ואיבעית אימא כי הא אורי ליה דאמר רבי אבהו אמר רבי יוחנן גבול יש לו מעטרה ולמטה מותר"],[[0,"מתני' כל היד המרבה לבדוק","שבודקת תמיד שמא ראתה:"],[0,"בנשים משובחת","שמתוך כך לא אתי לידי ספק טומאה ובעלה לא אתי לידי איסורא:"],[0,"ובאנשים","שבודק עצמו תדיר באמתו שמא יצא ממנו קרי:"],[0,"תקצץ","שמתחמם ומרגיש כשממשמש באמה ומוציא שכבת זרע לבטלה:"],[1,"גמ' הרגשה","שמזדעזעין אבריו כשמתחמם ורואה קרי:"],[2,"אנשים","משובחת דקתני קאי מרבה אבל אתקצץ דבאנשים אפילו חדא זימנא:"],[3,"לענין זיבה","שיצא זוב ממנו ורוצה לבדוק כדי למנות ראיותיו שתים לטומאה ושלש לקרבן. זוב דומה למי בצק של שעורים ובא מבשר המת ושכבת זרע בא מבשר החי וקשורה כלובן ביצה שאינה מוזרת:"],[4,"בצרור","דבר קשה אינו מחמם:"],[5,"במטלית עבה","קשה היא ואינה מחממת:"],[6,"שנזדעזעו אבריו","שנעקר זרע מגופו:"],[6,"אוחז באמה","שלא יצא הזרע עד שיבלע את התרומה שבפיו דתנן לקמן בפ' יוצא דופן (נדה דף מ.) הזב ובעל קרי אין מטמאין עד שתצא טומאתן לחוץ:"],[7,"כאילו מביא מבול","שעבירה זו היתה בידם דכתיב (בראשית ו׳:י״ב) כי השחית כל בשר ואמרו ברותחין קלקלו:"],[8,"כיון דעקר עקר","ומשום חמום דהשתא לא נפיק מידי:"],[10,"לא שכיח","וכי קתני למה זה דומה דתחילתו לא יצא אלא ע\"י משמוש האבר שאינו נעקר יחד אלא כשהוא ממשמש יוצא מעט מעט והולך אבל היכא דיצא מהרגשה ונעקר כולו כאחד תו לא מוסיף:"],[11,"ניצוצות ניתזין","שאינו אוחז ואינו מטיל למרחוק:"],[11,"כרות שפכה","סריס אין מימי רגליו עושים כיפה:"],[14,"איסורא","אסור לאחוז ואפילו אי אפשר לו בענין אחר אע\"פ שמוציא לעז כדקתני מוטב שיוציא לעז כו':"],[14,"תקנתא","ישתין על גבי עפר תיחוח דמשמע דאי ליכא הני יאחוז באמה:"],[17,"הנחמים באלים","שמתחממים בעצי אילנות במדורות גדולים כלומר בעלי הנאות:"],[17,"באלים","כמו (שם לה) תחת האלה:"],[19,"דשף ויתיב","שם מקום המובלע במלכות נהרדעא מפי מורי הזקן:"],[19,"אחוז באמה","שלא יפלו מים על הגג:"],[21,"עשאוהו","להא דרב יהודה:"],[21,"כבולשת","בולשת חיל שמחפשין ובוזזין כדמתרגמינן (שם לא) ויחפש ובלש:"],[22,"דליליא","ומתיירא שמא יפול:"],[22,"דרביה","שמואל:"],[22,"דשכינה","שורה בבית הכנסת:"],[22,"אימתא דמריה","הקב\"ה ואפי' במקום אחר נמי שרי לדידיה:"],[24,"עטרה","שפה גבוהה המקפת את ראש הגיד:"]],[[0,"","מתני' כל היד. באנשים תקצץ. ואם צריך לבדוק יבדוק בצרור או בחרס כדאמר בגמ' וא\"ת הא לקמן אמר דלמטה מעטרה מותר והיינו בפי האמה ושם הוא בודק עצמו וי\"ל דגם למעלה לצד הגוף צריך לבדוק שמא הלך שם טפת קרי א\"נ אפי' מעטרה ולמטה לא שרי אלא להשתין משום ניצוצות או משום בית הכנסת אבל כדי לבדוק עצמו לא:"],[1,"[נשים דלאו בנות הרגשה נינהו","לר\"ת דמפרש (יבמות יב) ג' נשים משמשות במוך היינו צריכות ושאר נשים מותורות משום [דלא] מיפקדא אפריה ורביה י\"ל כיון דלאו בנות איסור הרגשה נינהו אפילו הוו מרגישות לפי' ר\"ת קשה לר' יוחנן בן ברוקה דתניא (שם דף ס\"ה) על שניהם נאמר פרו ורבו ועוד נהי נמי דלא מפקידו אפ\"ו להשחית זרע הוקשו לאיש לכל עונשין שבתורה וי\"ל דהיינו טעמא שהנשים לעולם מזריעות בפנים ושם הוא דרך להזריע אבל אנשים מזריעים בחוץ ואין דרך להזריע שם. גי']:"],[7,"","אוחז והתניא רבי אליעזר אומר כו'. ואם תאמר לימא הא דקאמר אוחז ובולע היינו למטה מעטרה דשרי וי\"ל אם יניח הזרע לבא עד פי האמה שוב לא יוכל לעכבו אי נמי כיון שאוחז באמה בדוחק שלא יצא זרע יש הרהור אפי' למטה מעטרה וא\"ת ומאי פריך מר' אליעזר והלא רבנן פליגי עליה ושרו וכן לקמן מאי פריך. אדרב יהודה מרבי אליעזר וי\"ל דרבנן לא שרו אלא במשתין משום לעז ממזרות אבל לצורך ד\"א אסרי ורב יהודה נמי היה עומד במקום גבוה דליכא ניצוצות ולא היה אוחז אלא כדי שלא יפול מי רגלים על הכותל ובהא לא שרו רבנן אי נמי לסוף הודו חכמים לדברי ר' אליעזר מדאמר בפרק כיצד מברכין (ברכות דף מ.) אין מי רגלים כלין אלא בישיבה או בעפר תיחוח או במקום גבוה והיינו כרבי אליעזר אבל אוחז באמה לא קאמר אע\"ג דמסתמא כמו כן כלין ולקמן בפירקין (נדה דף טז:) שלש שנאתי וחשיב אוחז באמה ומשתין ולא הוזכר שם רבי אליעזר:"],[11,"","והלא ניצוצות ניתזין. וא\"ת וישפשף בידו כדאמרי' בפ' אמר להם הממונה (יומא ל.) דמצוה לשפשף וי\"ל דכשאין אוחז איכא רוב ניצוצות ולא סגי בשפשוף אבל באוחז ליכא אלא מעט וסגי בשפשוף דאי הוה סגי בשפשוף אף כשאינו אוחז גם רבנן לא הוו שרו:"],[13,"","ויעמוד במקום גבוה. ואפילו בקרקע קשה והא דאמר בפרק מומין אלו (בכורות דף מד:) לא ישתין לא על גבי מקום קשה ולא על גבי כלי דאמר רב הני מודרי דבבל מהדרי מיא לעין עיטם וי\"ל דהתם מיירי סמוך לפרת שהיא גבוה מכל הנהרות כדאמרינן (בכורות דף נה.) כל הנהרות למטה משלש נהרות ושלש נהרות למטה מפרת ומפרת שהוא גבוה מכולם יורד לעין עיטם שהוא גבוה כדאמרי' (זבחים דף נד:) סבור למבנייה בעין עיטם דמדלי טפי אבל רחוק מפרת או אפילו לתוך שאר נהרות שרי:"],[23,"","אם היה נשוי מותר. ובפ' כל כתבי (שבת דף קיח:) דקאמר דקרי ליה לרבי רבינו הקדוש שלא הניח ידו למטה מאבנטו היינו רבותא שהיה נשוי והיה מחמיר על עצמו:"]]],[["מעטרה ולמעלה אסור","אמר רב המקשה עצמו לדעת יהא בנדוי ולימא אסור דקמגרי יצה\"ר אנפשיה ורבי אמי אמר נקרא עבריין שכך אומנתו של יצר הרע היום אומר לו עשה כך ולמחר אומר לו עשה כך ולמחר אומר לו לך עבוד עבודת כוכבים והולך ועובד","איכא דאמרי אמר רבי אמי כל המביא עצמו לידי הרהור אין מכניסין אותו במחיצתו של הקב\"ה כתיב הכא (בראשית לח, י) וירע בעיני ה' וכתיב התם (תהלים ה, ה) כי לא אל חפץ רשע אתה לא יגורך רע","ואמר ר' אלעזר מאי דכתיב (ישעיהו א, טו) ידיכם דמים מלאו אלו המנאפים ביד תנא דבי רבי ישמעאל (שמות כ, יג) לא תנאף לא תהא בך ניאוף בין ביד בין ברגל","ת\"ר הגרים והמשחקין בתינוקות מעכבין את המשיח בשלמא גרים כדר' חלבו דא\"ר חלבו קשין גרים לישראל כספחת אלא משחקין בתנוקות מאי היא","אילימא משכב זכור בני סקילה נינהו אלא דרך אברים בני מבול נינהו","אלא דנסיבי קטנות דלאו בנות אולודי נינהו דא\"ר יוסי אין בן דוד בא עד שיכלו כל הנשמות שבגוף שנאמר (ישעיהו נז, טז) כי רוח מלפני יעטוף ונשמות אני עשיתי","באנשים תקצץ איבעיא להו דינא תנן או לטותא תנן דינא תנן כי הא דרב הונא קץ ידא או לטותא תנן","ת\"ש דתניא רבי טרפון אומר יד לאמה תקצץ ידו על טבורו אמרו לו ישב לו קוץ בכריסו לא יטלנו א\"ל לא אמר להן מוטב תבקע כריסו ואל ירד לבאר שחת","אי אמרת בשלמא דינא תנן היינו דאמרי והלא כריסו נבקעת אלא אי אמרת לטותא תנן מאי כריסו נבקעת אלא מאי דינא תנן לא סגי דלאו על טבורו","אלא ה\"ק רבי טרפון כל המכניס ידו למטה מטבורו תקצץ אמרו לו לרבי טרפון ישב לו קוץ בכריסו לא יטלנו אמר להן לא והלא כריסו נבקעת אמר להן מוטב תבקע כריסו ואל ירד לבאר שחת","\u0001מתני׳\u0002 החרשת והשוטה והסומא ושנטרפה דעתה אם יש להן פקחות מתקנות אותן והן אוכלות בתרומה","\u0001גמ׳\u0002 חרשת איהי תבדוק לנפשה דתניא אמר רבי חרשת היתה בשכונתינו לא דיה שבודקת לעצמה אלא שחברותיה רואות ומראות לה","התם במדברת ואינה שומעת הכא בשאינה מדברת ואינה שומעת כדתנן חרש שדברו חכמים בכל מקום אינו שומע ואינו מדבר","הסומא איהי תבדוק לנפשה ותיחזי לחבירתה א\"ר יוסי ברבי חנינא סומא אינה משנה","ושנטרפה דעתה היינו שוטה שנטרפה דעתה מחמת חולי","תנו רבנן כהן שוטה מטבילין אותו ומאכילין אותו תרומה לערב ומשמרין אותו שלא יישן ישן טמא לא ישן טהור","רבי אליעזר ברבי צדוק אומר עושין לו כיס של עור אמרו לו כל שכן שמביא לידי חימום אמר להן לדבריכם שוטה אין לו תקנה","אמרו לו לדברינו ישן טמא לא ישן טהור לדבריך שמא יראה טפה כחרדל ותבלע בכיס","תנא משום רבי אלעזר אמרו עושין לו כיס של מתכת","אמר אביי ושל נחשת כדתניא רבי יהודה אומר רואין אותן גבעולין של אזוב כאילו הן של נחשת","אמר רב פפא שמע מינה מכנסים אסורים והכתיב (שמות כח, מב) ועשה להם מכנסי בד לכסות בשר ערוה","ההוא כדתניא מכנסי כהנים למה הן דומין כמין פמלניא של פרשים למעלה עד מתנים למטה עד ירכים ויש להם שנצים ואין להם לא בית הנקב ולא בית הערוה","אמר אביי"],[[0,"מעטרה ולמעלה","לצד הגוף:"],[2,"וירע","אלמא מיקרי רע:"],[2,"וכתיב לא יגורך","לא יגור עמך רע:"],[3,"ביד","מוציא זרע לבטלה:"],[4,"כספחת","דכתיב בגרים (ישעיהו יד) ונלוה הגר עליהם ונספחו על בית יעקב לשון ספחת שקשים לישראל כספחת שאין בקיאים במצות ומביאין פורענות ועוד שמא למדים ישראל ממעשיהן מפי מורי הזקן. ויש אומר שכל ישראל ערבים זה בזה ולאו מילתא היא שלא נתערבו בשביל הגרים דאמרינן במס' סוטה (דף לז:) נמצא לכל אחד מישראל שש מאות אלף ושלשת אלפים ותק\"ן בריתות שכולן נתערבו זה בזה אלמא לא נתערבו על הגרים:"],[5,"בני סקילה נינהו","ואת אמרת מעכבים את המשיח ותו לא הלא במיתה הן נידונים:"],[5,"דרך אברים","היינו שכבת זרע לבטלה ואינו משכב זכור דבמשכב זכור כתיב (ויקרא כ) משכבי אשה:"],[6,"דנסיבי קטנות","והוא ראוי להוליד נמצא בטל מפריה ורביה כל ימי קטנותה:"],[6,"שבגוף","חדר. כי גוף שם מקום המיוחד לנשמות העתידים להיות נולדים:"],[6,"כי רוח","הרוחות שלפני שגזרתי להיות נולדים קודם יעטוף מעכב את הגאולה דקרא בגאולה כתיב כי לא לעולם אריב ולא לנצח אקצוף וגו' נשמות שאני עשיתי יעטוף ומסיפיה לרישיה מדריש. יעטוף כמו (בראשית ל) והעטופים ללבן:"],[7,"קץ ידא","דאמרינן בסנהדרין כל המרים ידו על חבירו תקצץ דכתיב וזרוע רמה תשבר. רב הונא קץ ידא אלמא תקצץ דינא הוא:"],[8,"תקצץ ידו על טבורו","קס\"ד טבורו ממש והיינו דאמרי ליה והלא כריסו נבקעת כשקוצצין שם את ידו:"],[9,"והלא כריסו נבקעת","מפני הקוץ:"],[10,"למטה מטבורו","והכי קאמר תקצץ על שהכניסה למטה מטבורו:"],[11,"מתני' מתקנות אותן","בודקות אותו ומטבילין אותן:"],[12,"גמ' ומראות לה","שהיתה בקיאה במראה דם טמא ודם טהור:"],[13,"מדברת ואינה שומעת","כבר שמעה ולמדה לדבר ואחר כן נתחרשה:"],[13,"בכל מקום","להוציא מכלל בן דעת:"],[16,"שלא יישן","כדי שלא יתחמם ויראה:"],[17,"כיס של עור","וכשירצו להאכילו יבדקו בכיס:"],[18,"ותבלע בכיס","וקאכיל תרומה בטומאת הגוף והוי במיתה דכתיב (ויקרא כ״ב:ט׳) ומתו בו כי יחללוהו:"],[20,"רואין אותן","לענין מי חטאת קאמר לטמא במשא דבעי' עד דדרי כשיעור הזאה כדאמר בפ\"ק (לעיל נדה ט.) כמה יהו במים ויהיה בהם כדי הזאה כדי שיטבול ראשי גבעולין ויזה כלומר כדי שיהא בהם כדי להזות לבד מה שהאזוב בולע:"],[20,"רבי יהודה אומר כו' של נחשת","אלמא של נחשת לא בלע:"],[21,"שמע מינה","מדקתני כל שכן שאתה מביאו לידי חימום אלמא מכנסים אסורין:"],[22,"פמלניא","סינר פורצינ\"ט. חללו תלוי למטה ברוחב שלא יתעטף האבר ויתחמם:"],[22,"של פרושים","צנועים ל\"א של פרשים:"],[22,"שנצים","אשרלט\"ש כעין שלנו:"],[22,"ואין להם לא בית הנקב ולא בית הערוה","כלומר חללו רחב ותלוי למטה ולא היה תיק בין הירכיים להיות האבר מתעטף בו שלא יבא (האבר) לידי הרהור והיינו בית הערוה. ובית הנקב כשהן קצרות כנגד נקב הרעי כתבנית אדם נכנסות בין עגבותיו ומלוכלכות בזיעה וגנאי הוא לבגדי קדש בכך. לישנא אחרינא בית הנקב ובית הערוה דרכן היה לעשות נקבים במכנסים כנגד בית הערוה להשתין מים לחוץ דרך שם וכן כנגד בית הרעי וכשגומר קושר הנקב ברצועה וסותמו:"]],[[1,"","המקשה עצמו לדעת יהא בנדוי. אינו מנודה מעצמו אלא כלומר חייבים לנדותו כדאמרי' בפ\"ק דקדושין (דף כח:) עד היכן הוא גלגול שבועה עד שיאמר השבע לי שאין עבדי אתה ההוא שמותי משמתינן ליה דתניא הקורא לחברו עבד יהא בנדוי משמע דיהא בנדוי היינו דמשמתינן ליה:"],[3,"","בין ביד בין ברגל. היינו דמשפשף מילתו ביד או ברגל:"],[4,"","קשים גרים לישראל כספחת. מה שמקשה רש\"י דלא חשיב בסוטה ערבות דערב רב י\"ל לפי שלא ידע חשבונן מיהו במכילתא אמר דערב רב היו כפלים כיוצאי מצרים ור\"י מפרש דלפיכך קשים שמטמעים בישראל ואמר בפ' עשרה יוחסין (קדושין דף ע:) אין שכינה שורה אלא על משפחות המיוחסות שבישראל וכן נראה דהתם על ההיא מילתא מייתי דר' חלבו: [וע\"ע תוס' יבמות מז: ותוס' קדושין ע: ד\"ה קשים]:"],[6,"","עד שיכלו כל הנשמות שבגוף. והא דאמר (שבת דף קיח:) אילמלי שמרו ישראל ב' שבתות מיד היו נגאלים וי\"ל דהרבה היו יולדות בכרס אחד:"],[9,"","דינא תנן. ובשבת (דף קח:) דאמרי' יד לפה תקצץ אינו לא דינא ולא לטותא אלא כלומר טוב לו לקוץ ידו קודם שיגע למקומות הללו משום בת מלך:"],[9,"","אלמא דינא תנן. השתא סבור דתקצץ ממש והיינו דקאמר כריסו נבקעת ומשני ה\"ק תקצץ ידו על טבורו פי' על שנגע על טבורו ולעולם לטותא הוא והא דקתני כריסו נבקעת לא קאי אתקצץ אלא על ישב לו קוץ דאם לא יסיר הקוץ תבקע כריסו וקשה דמאי ס\"ד מעיקרא דהא בהדיא קתני והלא כריסו נבקעת אחר ישב לו קוץ ומיהו בתוספתא גריס והלא כריסו נבקעת ברישא והשתא אתי שפיר ומ\"מ משני דה\"ק אם אסור לעולם ליגע פעמים שכריסו נבקעת כגון אם ישב לו קוץ:"]]],[["רוכבי גמלים אסורין לאכול בתרומה תניא נמי הכי רוכבי גמלים כולם רשעים הספנים כולם צדיקים","החמרים מהן רשעים מהן צדיקים איכא דאמרי הא דמכף הא דלא מכף ואיכא דאמרי הא דמטרטין הא דלא מטרטין","ריב\"ל לייט אמאן דגני אפרקיד איני והאמר רב יוסף פרקדן לא יקרא קרית שמע קרית שמע הוא דלא יקרא הא מגנא שפיר דמי","לענין מגנא כי מצלי שפיר דמי לענין ק\"ש כי מצלי אסור והא ר' יוחנן מצלי וקרי ק\"ש שאני רבי יוחנן דבעל בשר הוה","\u0001מתני׳\u0002 דרך בנות ישראל משמשות בשני עדים אחד לו ואחד לה והצנועות מתקנות שלישי לתקן את הבית","נמצא על שלו טמאין וחייבין קרבן נמצא על שלה אותיום טמאין וחייבין בקרבן נמצא על שלה לאחר זמן טמאין מספק ופטורים מן הקרבן","איזהו אחר זמן כדי שתרד מן המטה ותדיח פניה ואח\"כ מטמאה מעת לעת ואינה מטמאה את בועלה ר\"ע אומר אף מטמאה את בועלה","מודים חכמים לרבי עקיבא ברואה כתם שמטמאה את בועלה","\u0001גמ׳\u0002 וניחוש דלמא דם מאכולת הוא אמר רבי זירא אותו מקום בדוק הוא אצל מאכולת ואיכא דאמרי דחוק הוא אצל מאכולת","מאי בינייהו איכא בינייהו דאשתכח מאכולת רצופה להך לישנא דאמר בדוק הוא הא מעלמא אתאי להך לישנא דאמר דחוק הוא אימא שמש רצפה","אתמר בדקה בעד הבדוק לה וטחתו בירכה ולמחר מצאה עליה דם אמר רב טמאה נדה א\"ל רב שימי בר חייא והא חוששת אמרת לן","איתמר נמי אמר שמואל טמאה נדה וכן מורין בי מדרשא טמאה נדה","אתמר בדקה בעד שאינו בדוק לה והניחתו בקופסא ולמחר מצאה עליו דם א\"ר יוסף כל ימיו של ר' חייא טימא ולעת זקנתו טיהר","איבעיא להו היכי קאמר כל ימיו טימא משום נדה ולעת זקנתו טיהר משום נדה וטימא משום כתם","או דלמא כל ימיו טימא משום כתם ולעת זקנתו טיהר מולא כלום","תא שמע דתניא בדקה בעד שאינו בדוק לה והניחתו בקופסא ולמחר מצאה עליו דם רבי אומר טמאה משום נדה ורבי חייא אמר טמאה משום כתם"],[[0,"רוכבי גמלים","אבריהם מתחממים בבשר הגמל ומוציאים זרע:"],[0,"כולם רשעים","כדאמר:"],[0,"כולם צדיקים","שדרים בסכנה ולבם לאביהם שבשמים:"],[1,"דמכף","לשון אוכף של חמור. אם יש לו אוכף האבר אינו מתחמם שהעץ קשה הוא ואם אין לו אוכף מתחמם בבשר החמור אבל דרך גמלים לרכוב בלא אוכף אלא במרדעת ומתחמם:"],[1,"דמטרטין","ירך מכאן וירך מכאן ואברו מתחמם:"],[1,"דלא מטרטין","רוכב כאשה:"],[1,"מטרטין","לשון מאזנים כדאמרי' במנחות (דף פז:) וכי טורטני יכניס:"],[2,"אפרקיד","פניו למעלה וגנות הוא שפעמים שיתקשה אבר תוך שינתו ויתגלה ועוד שידיו מונחות לו על אברו ומתחמם:"],[3,"מצלי","מוטה מעט על צדו:"],[3,"כי מצלי נמי אסור","אא\"כ יושב או שוכב כולו על צדו:"],[4,"מתני' אחד לו ואחד לה","לקנח לאחר תשמיש:"],[4,"לתקן את הבית","כלומר לבדוק לפני תשמיש ולהכין עצמה לבעלה. וה\"ה לכל הנשים כדתנן בפ\"ק (לעיל נדה יא.) ובשעה שהיא עוברת לשמש את ביתה והא דנקט צנועות כדמפרש בפ\"ק צנועות עד שבודקת בו לפני תשמיש זה אין בודקת בו לפני תשמיש אחר:"],[5,"נמצא דם על שלו","ואפילו לאחר זמן ששהה לאחר בעילה זמן ארוך קודם קינוח בידוע שהיה דם בשעת תשמיש:"],[5,"טמאים","שניהם טומאת שבעה כדין בועל נדה כדכתיב (ויקרא ט״ו:כ״ד) ותהי נדתה עליו:"],[5,"אותיום","מיד לאחר בעילה:"],[5,"לאחר זמן","לאחר אותיום טמאים מספק שניהם שבעה ימים ומיהו טומאת ספק הוא לתלות אבל לא לשרוף:"],[6,"את פניה","פניה שלמטה:"],[6,"ואח\"כ","כלומר שהתה יותר מכשיעור הזה אחר אחר הוא זה:"],[6,"מטמאות מעת לעת","טהרות ואדם במגע טומאת ערב ומדרבנן כדין מעת לעת דאמר בפ\"ק ומה היא מטמאה משכבה ומושבה וכיון דעושה משכב ומושב לטמא אדם כל שכן דהיא עצמה מטמאה אדם:"],[6,"ואינה מטמאה את בועלה","טומאת שבעה ימים:"],[6,"ר\"ע אומר אף מטמאה את בועלה","ר\"ע לטעמיה דאמר כל מעת לעת מטמאה את בועלה מספק טומאת שבעה בפ\"ק (לעיל נדה ו.):"],[8,"גמ' מאכולת","כינה. ואמאי טמאין ודאי לשרוף תרומה ולהתחייב בקרבן ודאי להוי ספק לתלות תרומה ולהביא אשם תלוי ולא חטאת דדלמא דם מאכולת הוא שהיה באותו מקום באשה וכשבעל נדבק בו:"],[8,"בדוק","דודאי אין שם מאכולת ודם ודאי מגופה אתיא:"],[8,"דחוק הוא","שאין מאכולת יכולה ליכנס שם:"],[9,"רצופה","מעוכה על העד רחוק מן הדם קצת. ללישנא דבדוק כיון דקים להו לרבנן דאין שם מאכולת ודאי דם מגופה הוא שהרי העד היה בדוק לה קודם הקינוח ומאכולת (מעלמא הואי התם בעד שהיא רצופה) וללישנא דדחוק איכא לספוקי שמא האי דם ממאכולת ומתוך שדחוק הוא מעכה השמש בשעת תשמיש:"],[10,"ולמחר מצאה עליה דם","על הירך:"],[11,"טמאה נדה","טומאה ודאית דכיון דהעד בדוק לה שלא היה בו דם קודם בדיקה ודאי מגופה אתאי על העד ומשם הוטח בירכה ולא אמרינן דלמא מעלמא אתא על ירכה וספק טומאה היא:"],[12,"ולמחר מצאה עליו דם","על העד ואיכא לספוקי דלמא מקמי הכי הוה ביה. להכי לא נקט הכא טחתו בירכה דא\"כ הוו להו תרי ספיקי לקולא חדא דלמא לאו מן העד הוטח על ירכה ואפילו את\"ל מן העד אתא דלמא כיון דאינו בדוק מקמי הכי הוה:"],[13,"משום נדה","טומאה ודאית דכיון דחזקת דמים שם לא מספקינן במקמי הכי:"],[13,"משום כתם","כלומר טומאת ספק ותולין:"]],[[0,"","רוכבי גמלים אסורין לאכול בתרומה. ואע\"ג דאמר שמואל בפ' יוצא דופן (לקמן נדה דף מג.) כל שכבת זרע שאין כל גופו מרגיש אינו מטמא הכא דלמא הרגיש כל גופו ולאו אדעתיה:"],[0,"","רוכבי גמלים כולם רשעים החמרים מהן רשעים מהן צדיקים. וא\"ת דאמרינן בפרק עשרה יוחסין (קדושין דף פב.) גמלים רובן כשרים חמרים רובן ליסטין וי\"ל דהכא מיירי ברוכבים ומשום הרהור והתם לא מיירי ברוכבים אלא בנותנין סחורה על הגמלים והם הולכים ברגל רחוק במקום סכנה וחמרין [שהם ליסטים משום דבשעה שקונים] עושין רמאות במשא ובמתן:"],[2,"","אפרקיד. פי' הקונטרס פניו למעלה וכן משמע בהמוכר את הספינה (ב\"ב דף עד.) גבי מתי מדבר דגנו אפרקיד וחליף טייעא תותי ברכייהו ורומחא בידיה ולשון אפרקיד אפורייאה קדל (קדקדא) ולא כפירוש הערוך דפי' פניו מטה ולשון אפרקיד אפוי קיד ועוד קשה רי\"ש דאפרקיד למה לי. [וע\"ע תוספות פסחים קח. ד\"ה פרקדן]:"],[2,"","לייט אמאן דגני אפרקיד. פי' בקונטרס שידיו מונחות על מילתו ומתחמם ורשב\"ם פירש שבגדיו נופלין על אמתו ומתחמם ומה שפי' עוד שפעמים [מתקשה ומתגלה] לא נראה דבבית סגור או אפל מאי א\"ל. [ועוד שמעתי כששוכב אפרקיד מתחמם השדרה ומחמת זה יתקשה האבר ויבא לידי קרי. גליון:]"],[3,"","ק\"ש כי מצלי אסור. היינו כשהוא קצת אפרקיד אבל על צדו לגמרי שרי כדאמר בפ' מי שמתו (ברכות דף כד.) שנים שהן ישנים במטה זה הופך פניו לכאן וזה הופך פניו לכאן וקורין ק\"ש:"],[8,"","וליחוש דלמא דם מאכולת הוא. אבל על בדיקות דמטמאינן לה אם מצא דם לא פריך דדלמא חומרא היא אבל הכא פריך אמאי חייבין בקרבן דלמא מייתי חולין בעזרה ועוד נראה וכן פר\"ח דפריך אנמצא על שלו כי לא נמצא על שלה אמאי מטמאין כיון דאיכא הוכחה דלא אתי מגופה:"],[8,"","דחוק הוא אצל מאכולת. אין לפרש שאינה יכולה ליכנס אלא בדוחק ולפעמים נכנסת דא\"כ הוה ליה למימר בסמוך ללישנא דדחוק הוא אימר איתרמויי איתרמי ולמה צריך להזכיר דשמש רצפה לכך י\"ל בדוק הוא שאינה באה כלל סמוך לרחם מפני הזוהמא שיוכל השמש להכניס ודחוק הוא אצל מאכולת היינו דאינה נכנסת בשום פנים מאליה אלא שפעמים שמתקרבת לרחם כ\"כ עד שהשמש מכניסה ומרצפה:"],[10,"","וטחתו בירכה. פירוש במקום שאין דם המקור יכול ליפול שם:"],[10,"","ולמחר מצאה עליה דם. ה\"ג רש\"י פי' על ירכה וקאמר דטמאה נדה דאיכא למימר דמן העד נתלכלך ירכה ולא מעלמא וא\"ת ותבדוק העד וי\"ל שנאבד העד א\"נ שמא דם העד עצמו בא מדם ירכה כיון שנמצא על העד רק במקום שנגע בירכה וכגון שיש כגריס ועוד דליכא חששא דמאכולת [או שמא כיון שנמצא על ירכה במקום שנגע בעד מוכח מילתא שמחמת העד הוא וטמאה. גליון:] ודוקא בעד הבדוק לה אבל בשאינו בדוק לה הוי ספק ספקא כדפי' רש\"י ודוקא טחתו בירכה אבל הניחתו בקופסא פשיטא דטמאה ור\"ח גרס ומצאה עליו פירוש על העד וטחתו בירכה היינו בגלוי שלא הניחתו בקופסא דבהניחתו בקופסא פשיטא דטמאה ופריך והא חוששין אמרת לן דאימר מעלמא אתי:"],[11,"","אמר שמואל טמאה נדה. אפי' ר' חייא דמטהר בסמוך מודה הכא דהא ר' חייא כר' יוסי ס\"ל ושמואל גופיה פסיק בהאשה (לקמן נדה נט:) כרבי יוסי והכא קאמר דטמאה נדה:"],[12,"","בעד שאינו בדוק לה. נראה לפרש דידעה שהיה נקי לפני יום או יומים ועתה בשעת בדיקה נטלתו ממקום המוצנע ולא בדקה העד אבל אין נראה לפרש שלא היה בדוק מעולם דבהא לא היה רבי מחזיק טומאה ודאי:"]]],[["אמר לו ר' חייא אי אתה מודה שצריכה כגריס ועוד א\"ל אבל אמר לו א\"כ (אתה) אף אתה עשיתו כתם","ורבי סבר בעינן כגריס ועוד לאפוקי מדם מאכולת וכיון דנפק לה מדם מאכולת ודאי מגופה אתא","מאי לאו בזקנותו קאי הא בילדותו טימא משום נדה שמע מינה","משתבח ליה רבי לרבי ישמעאל ברבי יוסי ברבי חמא בר ביסא דאדם גדול הוא אמר לו לכשיבא לידך הביאהו לידי","כי אתא א\"ל בעי מינאי מילתא בעא מיניה בדקה בעד שאינו בדוק לה והניחתו בקופסא ולמחר מצאה עליו דם מהו","אמר לו כדברי אבא אימא לך או כדברי רבי אימא לך א\"ל כדברי רבי אימא לי","אמר רבי ישמעאל זהו שאומרין עליו דאדם גדול הוא היאך מניחין דברי הרב ושומעין דברי התלמיד","ור' חמא בר ביסא סבר רבי ריש מתיבתא הוא ושכיחי רבנן קמיה ומחדדי שמעתתיה","מאי רבי ומאי רבי יוסי אמר רב אדא בר מתנא תנא רבי מטמא ורבי יוסי מטהר","ואמר רבי זירא כשטימא רבי כר\"מ וכשטיהר רבי יוסי לעצמו טיהר","דתניא האשה שהיתה עושה צרכיה וראתה דם ר\"מ אומר אם עומדת טמאה אם יושבת טהורה","רבי יוסי אומר בין כך ובין כך טהורה","א\"ל רב אחא בריה דרבא לרב אשי והא א\"ר יוסי בר' חנינא כשטימא ר\"מ לא טימא אלא משום כתם ואילו רבי משום נדה קאמר א\"ל אנן הכי קאמרינן כי איתמר ההיא משום נדה איתמר","נמצא על שלה אותיום טמאין וכו' ת\"ר איזהו שיעור וסת משל לשמש ועד שעומדין בצד המשקוף ביציאת שמש נכנס עד","הוי וסת שאמרו לקינוח אבל לא לבדיקה","נמצא על שלה לאחר זמן וכו' תנא וחייבין אשם תלוי ותנא דידן מ\"ט","בעינן חתיכה משתי חתיכות","איזהו אחר זמן וכו' ורמינהי איזהו אחר זמן פירש ר' אליעזר ברבי צדוק כדי שתושיט ידה תחת הכר או תחת הכסת ותטול עד ותבדוק בו","אמר רב חסדא מאי אחר אחר אחר","והא קתני עלה נמצא על שלה לאחר זמן טמאין מספק ופטורין מן הקרבן איזהו אחר זמן כדי שתרד מן המטה ותדיח פניה","ה\"ק איזהו אחר זמן כדי שתושיט ידה לתחת הכר או לתחת הכסת ותטול עד ותבדוק בו וכדי שתרד מן המטה ותדיח את פניה מחלוקת ר\"ע וחכמים","והא אח\"כ קתני ה\"ק וזהו אח\"כ שנחלקו ר\"ע וחכמים","רב אשי אמר אידי ואידי חד שיעורא הוא עד בידה כדי שתרד מן המטה ותדיח את פניה אין עד בידה כדי שתושיט ידה לתחת הכר או לתחת הכסת ותטול עד ותבדוק בו","מיתיבי איזהו אחר זמן דבר זה שאל רבי אלעזר ברבי צדוק לפני חכמים באושא ואמר להם"],[[0,"שצריכה כגריס ועוד","כשיעור שאר כתמים שאין מטמאין אלא בכגריס ועוד כדאמרינן בהרואה כתם (לקמן נדה דף נח:) דעד כגריס יכולה לתלות ולומר דם מאכולת הוא:"],[0,"אבל","הן באמת:"],[0,"אמר לו","ר' חייא:"],[0,"אף אתה עשיתו כתם","נוהג אתה בו דין כתם דשיעורו כגריס ועוד ובפחות מכאן לאו כלום הלכך טומאתו נמי ספק דאי ודאי ראיה הואי מגופה כדקאמרת האמר בפ' יוצא דופן (לקמן נדה דף מ.) אפי' כעין החרדל ובפחות מכן:"],[1,"לאפוקי מדם מאכולת","דכיון דאינו בדוק לה כל כמה דליכא כגריס ועוד הוה לה לספוקי בדם מאכולת קודם בדיקה:"],[2,"מאי לאו בזקנותו קאי","מדפליג עליה דרבי רביה:"],[4,"אמר ליה","רבי ישמעאל לרבי חמא בעי מינאי מילתא:"],[5,"כדברי אבא","רבי יוסי או כדברי רבי ולקמן תני פלוגתייהו בשמעתין:"],[9,"לעצמו טיהר","לטעמיה אזיל דאמר נמי הכי בדוכתא אחריתי (לקמן נדה דף נט:):"],[10,"צרכיה","מטילה מים:"],[10,"עומדת טמאה","דכיון דדחוקה היא הדור מי רגלים למקור ואייתי דם והכי מפרש בפ' האשה (שם):"],[10,"יושבת טהורה","דממקום מי רגלים הוא בא ואין טמא אלא דם המקור. ומדקאמר רבי מאיר עומדת טמאה ואף על גב דאיכא לספוקינהו במקום מי רגלים כיון דרגלים לדבר דדחיק לה עלמא וחזקת דמים מן המקור מיטמיא ה\"נ מיטמיא:"],[12,"משום כתם","טומאת ספק לתלות ואילו רבי לעיל טימא משום נדה דקתני רבי אומר טמאה נדה:"],[12,"כי איתמר","ההיא דר' יוסי בר חנינא:"],[14,"הוי וסת שאמרו","לחייבה בחטאת:"],[14,"לקינוח","מבחוץ ולא לבדיקה מבפנים דא\"כ שהתה יותר מכשיעור ואין כאן אלא טומאת ספק ואשם תלוי:"],[15,"תנא וחייבין באשם תלוי","אנמצא לאחר אותיום קאי דקתני במתניתין ופטורין מן הקרבן:"],[16,"בעינן חתיכה משתי חתיכות","דכתיב באשם תלוי (ויקרא ה׳:י״ז) אחת מכל מצות ה' וקסבר יש אם למקרא מצוות קרינן הילכך בעינן שתים אחת של איסור ואחת של היתר ואכל אחת ואינו יודע איזהו אכל אשתו ואחותו עמו בבית ובא על אחת מהן כסבור אשתו היא ונודע ששתיהן היו במטה ואינו יודע על איזהו מהן בא אבל הכא חדא חתיכה היא ספק שריא ספק אסורה ותנא ברא סבר יש אם למסורת והכי פליגי במסכת כריתות (דף יז:):"],[17,"שתושיט","ועודה במטה הא כדי שתרד שיעורא רבה ואינה מטמאה את בועלה אלא כשאר מגע מעת לעת:"],[18,"מאי אחר","דקתני במתני' איזהו אחר זמן כדי שתרד לאו אאחר אותיום קאי דטמאים מספק אלא איזהו אחר זמן שהוא אחר אותו שלאחר אותיום שאינה מטמאה את בועלה לרבנן אלא לר\"ע כדי שתרד כו':"],[19,"והא עלה קתני כו'","אלמא אטמאין מספק קאי משום שמטמאה את בועלה אפי' לרבנן:"],[20,"הכי קאמר","חסורי מחסרא והכי קתני איזהו אחר זמן שהן טמאין מספק כדי שתושיט אבל שהתה כדי שתרד מטמאה מעת לעת ואינה מטמאה את בועלה רבי עקיבא אומר מטמאה את בועלה ואפילו כל מעת לעת:"],[21,"והא אח\"כ קתני","דקתני במתני' ואח\"כ מטמאה מעת לעת ואינה מטמאה כו' אלמא כששהתה יותר מכדי שתרד הוא דפליגי אבל בכדי שתרד טומאה אפילו לרבה וקשיא ברייתא דכדי שתושיט:"],[21,"וזהו אח\"כ","האי שיעורא דכדי שתרד זהו אח\"כ שנחלקו בו ר\"ע וחכמים:"],[22,"עד בידה","שאינה צריכה להושיט ידה תחת הכר הוי שיעורא בכדי שתרד ותדיח באותו עד:"],[22,"אין עד בידה","דבעיא להושיט ידה תחת הכר:"],[22,"בכדי שתושיט","ותבדוק ועודה במטה ולרב חסדא אפי' עד בידה נפיש כדי שתרד מכדי שתושיט הילכך אחר אחר הוא:"]],[[2,"","מאי לאו בזקנותו. פרש\"י מדפליג על רבי ואין נראה דמצינו הרבה תלמידים שחולקים על רבם בילדותם ורשב\"ם פירש דרבי חייא תחילה למד בבבל ולעת זקנתו עלה ולמד לפני רבי כדאמרינן (סוכה דף כ.) חזרה ונשתכחה עלו רבי חייא ובניו ויסדוה ועי\"ל מדקאמר רבי חייא אף אתה עשיתו כתם ולא קאמר אף אתה רבי ש\"מ דבזקנותו היה דהוה תלמיד חבר כדאמר בשילהי מי שמת (ב\"ב דף קנח:) בן עזאי תלמיד חבר של רבי עקיבא דאמר ליה (שב אתה ולא קאמר שב מר):"],[6,"","האיך מניחין דברי הרב. משמע דר' יוסי היה רבו של רבי וקשה דאמר בפ' זה בורר (סנהדרין כד.) כמה מחבבים זה את זה דאילו ר' יוסי קיים הוה כפוף ויושב לפני רבי ואמר כבר הורה זקן ורש\"י פי' התם שהיה כפוף מחמת כבוד נשיאותו של רבי ואין נראה דא\"כ היכי מוכיח דמחבבין זה את זה וכי בשביל נשיאות לא היה לו לפסוק כרבו ואור\"ת דבבחרותו של רבי היה ר' יוסי גדול יותר ובזקנותו [מחמת התלמידים] נתחכם רבי יותר כדאמר נמי הכא הואיל ושכיחי רבנן קמיה מחדדין שמעתתיה:"],[8,"","ורבי יוסי מטהר. נראה דלגמרי מטהר מדקאמר לעצמו טיהר כמו גבי אשה שעשתה צרכיה דהתם נראה דלגמרי מטהר דאין נראה לפרש לעצמו טיהר דמדמטהר גבי אשה שעשתה צרכיה לגמרי הכא בעד שאינו בדוק יטהר לכל הפחות מנדה ויעשנה כמו כתם דא\"כ מאי פריך בסמוך האמר ר' יוסי בר' חנינא לא טימא ר\"מ כו' מאי קושיא והלא יש להחמיר בעד שאינו בדוק לה טפי מבאשה שעושה צרכיה מיהו ר\"ח פירש דר' יוסי לאו לגמרי מטהר באשה שעושה צרכיה וכמסקנא דר\"מ משום נדה איתמר ולפי' זה הא דתנן בפ' האשה (לקמן נדה דף נט:) איש ואשה שעשו צרכיהן בספל ונמצא דם דר' יוסי מטהר ופריך בגמרא למה לי הך בבא ומשני אי מרישא ה\"א דיעבד קמ\"ל סיפא דאף לכתחלה לפי' ר\"ח לא קאי אף לכתחלה ארישא אלא אסיפא דוקא:"],[16,"","בעינן חתיכה מב' חתיכות. וא\"ת בריש פ' ספק אכל (כריתות דף יז:) דפריך לר' חייא בר רב דבעי חתיכה מב' חתיכות מברייתא דהכא ומשני רבי אליעזר היא דאמר כוי חייבין על חלבו אשם תלוי אדמקשה מברייתא לסייעיה ממתני' דהכא דפטרה מקרבן וי\"ל דשמא מתניתין לא פטריה אלא מחטאת ולא פליג אברייתא והא דקאמר ותנא דידן ה\"ק את\"ל דמתניתין פוטר אף מאשם תלוי היינו טעמא דסבר בעינן חתיכה מב' חתיכות:"],[18,"","מאי אחר אחר אחר. ותימה כיון דתנא כדי שתושיט ידה ותטול עד תחת הכר דהוי טמא בועלה שבעה וחייב אשם תלוי ממילא ידעינן דאם תשהה יותר עד שתרד מן המטה דאחר אחר הוא ואינה מטמאה בועלה טומאת שבעה [עיין ברשב\"א]:"]]],[["שמא כרבי עקיבא אתם אומרים שמטמאה את בועלה אמרו לו לא שמענו","אמר להם כך פרשו חכמים ביבנה לא שהתה כדי שתרד מן המטה ותדיח את פניה תוך זמן הוא זה וטמאין מספק ופטורין מקרבן וחייבין באשם תלוי","שהתה כדי שתרד מן המטה ותדיח את פניה אחר הזמן הוא זה","וכן כששהתה מעת לעת ומפקידה לפקידה בועלה מטמא משום מגע ואינו מטמא משום בועל רבי עקיבא אומר אף מטמא משום בועל רבי יהודה בנו של רבן יוחנן בן זכאי אומר בעלה נכנס להיכל ומקטיר קטורת","בשלמא לרב חסדא היינו דמטהרי רבנן","אלא לרב אשי אמאי מטהרי רבנן","וכי תימא דאין עד בידה האי עד בידה ואין עד בידה מיבעי ליה קשיא","רבי יהודה בנו של רבן יוחנן בן זכאי אומר בעלה נכנס להיכל ומקטיר קטורת ותיפוק ליה דהוה נוגע במעת לעת שבנדה","הוא דאמר כשמאי דאמר כל הנשים דיין שעתן","ותיפוק ליה דהוה בעל קרי בשלא גמר ביאתו","ומודים חכמים לרבי עקיבא ברואה כתם אמר רב למפרע ורבי מאיר היא","ושמואל אמר מכאן ולהבא ורבנן היא מכאן ולהבא פשיטא","מהו דתימא הואיל ומעת לעת דרבנן וכתמים דרבנן מה מעת לעת לא מטמאה את בועלה אף כתמים לא מטמאה את בועלה קא משמע לן","ואימא הכי נמי התם אין שור שחוט לפניך הכא יש שור שחוט לפניך","וכן אמר ריש לקיש למפרע ורבי מאיר היא רבי יוחנן אמר מכאן ולהבא ורבנן היא","\u0001מתני׳\u0002 כל הנשים בחזקת טהרה לבעליהן הבאין מן הדרך נשיהן להן בחזקת טהרה","\u0001גמ׳\u0002 למה ליה למתני הבאין מן הדרך סד\"א הני מילי היכא דאיתיה במתא דרמיא אנפשה ובדקה אבל היכא דליתא במתא דלא רמיא אנפשה לא קא משמע לן","אמר ריש לקיש משום רבי יהודה נשיאה והוא שבא ומצאה בתוך ימי עונתה","אמר רב הונא ל\"ש אלא שאין לה וסת אבל יש לה וסת אסור לשמש","כלפי לייא אדרבה איפכא מסתברא אין לה וסת אימא חזאי יש לה וסת וסת קביע לה","אלא אי איתמר הכי איתמר אמר רב הונא ל\"ש אלא שלא הגיע שעת וסתה אבל הגיע שעת וסתה אסורה קסבר וסתות דאורייתא","רבה בר בר חנה אמר אפילו הגיע שעת וסתה נמי מותרת קסבר וסתות דרבנן","רב אשי מתני הכי אמר רב הונא"],[[0,"שמא כר\"ע אתם אומרים שמטמאה את בועלה","כל מעת לעת ואין לכם שיעור בדבר אלא מעת לעת:"],[0,"לא שמענו","את שיעורו וכר\"א לא סבירא לן:"],[1,"לא שהתה כדי שתרד","אלא כדי שתשב ותבדוק ועודה במטה טמאין מספק דהיינו אחר אותיום כרב חסדא:"],[2,"שהתה כדי שתרד","דנפיש שיעוריה:"],[2,"אחר הזמן הוא זה","כלומר אחר אחר הוא זה:"],[3,"וכן מעת לעת","כלומר כשיעור הזה ומכאן ולהלן כל מעת לעת של בעילה אם בדקה ומצאתה טמאה בועלה מטמאה משום נוגע במעת לעת בנדה טומאת ערב וספק מדרבנן לתלות ואינו מטמא משום בועל נדה טומאת שבעה ואפילו לתלות:"],[3,"נכנס להיכל","לקמן מפרש לה:"],[4,"בשלמא לרב חסדא","דאמר כדי שתרד אחר אחר הוא היינו דמטהרי רבנן:"],[6,"וכי תימא דאין עד בידה","דאחר שתרד הוצרכה להושיט דהוה להו תרי שיעורי א\"כ איבעי ליה למיתני ולפלוגי בין עד בידה לאין עד בידה דלא תיפוק חורבה מיניה דהשתא משמע דאפילו עד בידה דלא שהתה אלא כדי שתרד מטהרי רבנן ומדלא מפליג ש\"מ דודאי מטהרי רבנן בכדי שתרד לחודיה:"],[9,"בשלא גמר ביאתו","ואפילו הכי לר\"ע מטמאה את בועלה דהעראה בנדה כגמר ביאה דכתיב (ויקרא כ׳:י״ח) את מקורה הערה אבל לענין קרי עד שיזריע:"],[10,"ור\"מ היא","דמחמיר בכתמים כדאמר בפ\"ק (לעיל נדה ה.) ולקמן בפרק בא סימן (נדה דף נב:):"],[11,"פשיטא","מאי מודי הא בלמפרע פליגי לגבי מעת לעת ולא במכאן ולהבא:"],[12,"וכתמים דרבנן","אפי' מכאן ולהבא:"],[13,"אין שור שחוט","דאתמול לא חזאי אלא סייג בעלמא הוא:"],[13,"הכא הרי שור שחוט לפניך","דבצפור לא נתעסקה ובשוק של טבחים לא עברה ומיום שלבשתו היא בספק זה:"],[15,"מתני' כל הנשים בחזקת טהרה לבעליהן","בלא בדיקה שלא הוזכרה בדיקה אלא לעסוקה בטהרות:"],[17,"גמ' בתוך ימי עונתה","ל' יום לראייה אבל לאחר ל' בעיא בדיקה הואיל וסתם נשים חזיין לסוף עונה:"],[20,"לא שנו","דכי מצאה תוך ימי עונתה לא בעיא בדיקה:"],[20,"אלא שלא הגיע עת וסתה","בתוך אותן ימים שהיה בדרך כגון אשה שיש לה וסת ולא הגיע בתוך אותן הימים:"],[20,"אבל הגיע עת וסתה","קודם ביאתו מן הדרך:"],[20,"אסורה","דאורח בזמנו בא:"],[20,"דאורייתא","הלמ\"מ דמחזקינן לה בטומאת ספק:"],[21,"וסתות דרבנן","הצריכוה חכמים לבדוק ביום וסתה שמא תראה ומיהו היכא דלא הוה בעיר ולא ידעינן אי בדקה אי לא בדקה לא מספקינן לה בטומאה:"]],[[1,"","לא שהתה כדי שתרד מן המטה מטמאה את בועלה [וחייבת באשם תלוי] שהתה כדי שתרד כו' ר\"ע אומר מטמאה בועלה. תימה אי ר\"ע מודה ברישא כדמשמע דלא פליג אלא אסיפא א\"כ סבר יש אם למסורת ובפ\"ק דסנהדרין (דף ד.) אית ליה לר\"ע יש אם למקרא גבי רביעית דם הבא משני מתים דקאמר נפשות קרינן וליכא למימר דהכא פליג נמי ברישא דהתנן פ' דם שחיטה (כריתות דף כב:) בחתיכה של קודש וחתיכה של חולין אכל אחד את הראשונה ובא אחר ואכל את השניה זה מביא אשם תלוי וזה מביא אשם תלוי דברי ר\"ע ואמאי חייב השני הא בשעה שאכל לא היו לפניו ב' חתיכות ולמאן דבעי ב' חתיכות פטור בכה\"ג כדאמר התם בסוף פרקין ורבי נמי אית ליה בפ' ספק אכל (שם דף יח.) היכא דאכל את הראשונה במזיד והשניה בשוגג דחייב אשם תלוי על השניה ורבי סבר בפ\"ק דסנהדרין (דף ד.) יש אם למקרא וצ\"ל דיש שום חילוק בין מקרא למסורת זה למקרא ומסורת דעלמא דחייא בר רב דבעי ב' חתיכות סבר דכ\"ע סברי הכא דיש אם למקרא ורב אסי דפליג עליה סבר דכ\"ע סברי יש אם למסורת כמו שמצינו (ב\"מ דף כב:) גבי יותן דומיא דיתן ועובד דומיא דעבד (פסחים דף כו:) ועוני דומיא דעני (שם לו.) וכפות דומיא דכפת (סוכה דף לב.) והתם יש טעמא אחרינא ותדע דכי פריך התם טובא לחייא בר רב ומשני ר\"א היא דמחייב אשם תלוי על חלב כוי והא כמה תנאי פליגי במקרא ובמסורת ואמאי נקט טפי ר\"א דשמותי הוא וגם המקשה וכי לא הוה ידע דטובא תנאי פליגי במקרא ובמסורת אלא כדפרישית ועוד י\"ל דר\"ע ורבי איירו דהראשון לא אכל כל החתיכה אלא חציה וכשאכל השניה היו עדיין ב' החתיכות לפניו וכענין זה מתרץ הירושלמי בהאשה רבה:"],[6,"","האי עד בידה ואין עד בידה מיבעי ליה. פרש\"י דה\"ל לפלוגי הכל בשהתה וקשה דלמא מפליג בדידה באין עד בידה בין שהתה ללא שהתה ונראה לפרש דה\"ל לפרושי בברייתא באין עד בידה כיון דמתניתין איירי ביש עד בידה:"],[8,"","כשמאי דאמר דיה שעתה. ומ\"מ מודה שמאי בחד אחר דטמא שבעה כיון דחייב אשם תלוי:"],[10,"","אמר רב למפרע ור\"מ היא. וא\"ת דבפ\"ק דיומא (דף ב.) תנן מפרישין כ\"ג מביתו ז' ימים דשמא יבא על אשתו ספק נדה וקאמר כמאן כר\"ע דאמר אף מטמאה את בועלה וקאמר רב חסדא דאתי אפילו כרבנן ובחד אחר מודו דבועלה טמא ז' אמאי לא משני שמא תמצא כתם דהא מודים חכמים לר\"ע ברואה כתם וי\"ל משום שמואל דאמר הכא מכאן ולהבא ועוד י\"ל דהיא תבדוק חלוקה קודם פרישתו ואז לא נטמא הכהן קודם בדיקה וא\"ת אמאי קאמר שמא תמצא אשתו ספק נדה לימא ודאי נדה אם תבדוק שיעור וסת סמוך לבעילה וי\"ל דהא לא שכיחא:"],[20,"","הכי איתמר לא שנו אלא שלא הגיע שעת וסתה. לא היה לו לחזור ממה שאמר תחלה לא שנו אלא שאין לה וסת דאמת הוא דהיא בחזקת טהרה כדאמרינן בפ\"ק (לעיל נדה יב.) כל לבעלה לא בעיא בדיקה אפילו אין לה וסת והיה יכול להוסיף ויש לה וסת נמי כשלא הגיע שעת וסתה כו' אלא מיישב הלשון שאמר תחלה בלא תוספת:"],[21,"","אפי' הגיע זמן וסתה מותרת. תימה היאך מותרת הא אמרינן בשבועות פ\"ב (דף יח:) ולקמן פרק האשה (נדה דף סג:) אזהרה לבני ישראל שיפרשו מנשותיהן סמוך לוסתן וי\"ל כששהתה אחר וסתה שבעה ימים שיכולה לטבול איירי דספק טבילה מוציאה מידי ספק ראתה כההוא דר' יוחנן דבסמוך ולמ\"ד וסתות דאורייתא אפילו שהתה כשיעור זמן טבילה אסורה דודאי ראתה חשבינן לה ומתוך כך יש לדקדק דס\"ל לרבי יוחנן דבסמוך וסתות דרבנן:"]]],[["לא שנו אלא שאין לה וסת לימים אלא יש לה וסת לימים ולקפיצות כיון דבמעשה תליא מילתא אימא לא קפיץ ולא חזאי אבל יש לה וסת לימים אסורה לשמש","קסבר וסתות דאורייתא","רבה בר בר חנה אמר אפילו יש לה וסת לימים מותרת קסבר וסתות דרבנן","אמר רב שמואל משמיה דרבי יוחנן אשה שיש לה וסת בעלה מחשב ימי וסתה ובא עליה","אמר ליה רב שמואל בר ייבא לרבי אבא אמר רבי יוחנן אפילו ילדה דבזיזא למטבל","אמר ליה אטו ודאי ראתה מי אמר רבי יוחנן אימר דאמר רבי יוחנן ספק ראתה ספק לא ראתה ואם תמצא לומר ראתה אימא טבלה","אבל ודאי ראתה מי יימר דטבלה הוה ליה ספק וודאי ואין ספק מוציא מידי ודאי","ולא והתניא חבר שמת והניח מגורה מלאה פירות אפילו הן בני יומן הרי הן בחזקת מתוקנין והא הכא ודאי טבל ספק מעושר ספק אינו מעושר וקאתי ספק ומוציא מידי ודאי","התם ודאי וודאי הוא כדרב חנינא חוזאה דאמר רב חנינא חוזאה חזקה על חבר שאינו מוציא מתחת ידו דבר שאינו מתוקן","ואיבעית אימא ספק וספק הוא וכדרבי אושעיא דא\"ר אושעיא מערים אדם על תבואתו ומכניסה במוץ שלה כדי שתהא בהמתו אוכלת ופטורה מן המעשר","ואכתי אין ספק מוציא מידי ודאי והתניא מעשה בשפחתו של מסיק אחד ברימון שהטילה נפל לבור ובא כהן והציץ בו לידע אם זכר אם נקבה","ובא מעשה לפני חכמים וטהרוהו מפני שחולדה וברדלס מצויים שם","והא הכא דודאי הטילה נפל ספק גררוהו ספק לא גררוהו וקאתי ספק ומוציא מידי ודאי","לא תימא הטילה נפל לבור אלא אימא"],[[0,"לא שנו","הא דתנן בחזקת טהרה דמשמע אפילו הגיע עת וסתה:"],[0,"אלא באין לה וסת לימים","לחודייהו בלא קפיצה אלא לקפיצה ולימים:"],[3,"מחשב ימי וסתה","אם שהה בדרך שבעה ימים אחר וסתה דעכשיו עומדת בימים שיכולה להטהר אפילו הגיע וסתה אמרינן טבלה ואין צריך לשואלה:"],[4,"דבזיזא","בושה היא לטבול עד שיפייסנה:"],[5,"ודאי ראתה מי א\"ר יוחנן","שלא יהא צריך לשואלה ואפילו היא זקנה:"],[5,"אימר טבלה","וכיון דטעמא דר' יוחנן משום ספיקא הוא לא שנא ילדה לא שנא זקנה:"],[6,"הוי ספק","להיתר:"],[6,"ודאי","לאיסור:"],[6,"ואין ספק מוציא","את הדבר מידי ודאי שלו:"],[7,"והא הכא דודאי טבל","דהא חזינן שנגמרה מלאכתן וממורחין הן:"],[9,"איבעית אימא ספק וספק הוא","דכי היכי דמספקא לן אי מעשרי אי לא ה\"נ מספקא לן דלמא לא טביל ולא איחייב במעשר דאימא כרבי אושעיא עיילה ומכניסה במוץ שלה דאין טבל מתחייב במעשר אלא בראיית פני הבית כשרואה את הפתח וכיון דבשעת ראיית פני הבית לא נגמרה מלאכתו למעשר תו לא מיחייבא אע\"פ שהוא דשה וממרחה לאחר שהכניסה מידי דהוה אמכניס פירות דרך גגו וקרפיפו לבית אפילו היא ממורחת דקיימא לן דפטורה מן המעשר הואיל ולא ראתה את הפתח:"],[9,"כדי שתהא בהמתו אוכלת","אפי' לאחר מירוח. ולהכי נקט בהמתו דאילו אמאכל אדם לא מצי למימר הכי דאי נמי לא מחייב מדאורייתא רבנן גזור על אכילת קבע אפי' בדבר שלא נגמרה מלאכתו אבל מאכל בהמה קבע שלה עראי חשיב לה דתנן במסכת פאה (פ\"א מ\"ו) מאכיל לבהמה לעופות ולחיות עד שימרח הילכך כל כמה דלא חל עליה שם טבל דאורייתא מאכיל לבהמתו. והכא כיון דאיכא למימר דעביד להו כרבי אושעיא מותרין לאדם דלגבי איסורא דרבנן מהניא חזקת חבר:"],[10,"אם זכר הוא כו'","כהן חכם היה ומורה הוראות ומתכוין להורות לה ימי טומאה וטהרה. אי נמי שגורה אצלו בבית ונוגעת בתרומתו ורוצה להזהר ממנה כל ימי טומאתה. וי\"א לידע אימתי יהא זמן הבאת קרבנה אם יארע במשמרתו אם לאו. ולא סבירא לי דבשביל תור עולה אחת לכולה משמרה לא עייל האי כהן נפשיה להכי ועוד שהרי היא יכולה לאחר קרבנה כל זמן שתרצה וגם לשון ראשון אינו נראה דאי חכם הוא כלום הוא בא להאהיל ולעבור על לאו דטומאת מת אלא כהן עם הארץ היה או קטן ושגרתו אשה להציץ ולראות:"],[11,"וטהרוהו","מאהל המת:"]],[[4,"","אפילו ילדה דבזיזא למיטבל. פ\"ה אפי' נערה שבושה לטבול ומשני ודאי ראתה מי א\"ר יוחנן הך נמי כיון שלא ראתה בודאי שרי רבי יוחנן ואינו מיושב ור\"ח מפרש וכן ר\"ת אפי' ילדה דבזיזא למיטבל פי' שהולידה ומפחדת לטבול תוך ל' כדאמר בפ' מפנין (שבת דף קכט.) דבת רב חסדא טבלה תוך שלשים ללידה וחלתה ואמטיה רבא לערסא ואיתסיאת והשתא אתי שפיר דא\"ל ודאי ראתה מי א\"ר יוחנן א\"כ יולדת אפילו לא היתה דואגת לטבול לא יתיר רבי יוחנן דספק טבילה אינו מוציאה מידי ודאי ראתה ובזיז לשון פחד כההיא דפ\"ב דיבמות (דף כו.) לא מיבעיא אביו דבזיז בריה מיניה מיהו בפ' אלו דברים (פסחים דף עב:) משמע שהוא לשון בושת גבי יבמתו בזיזה מיניה ובפ' ב\"ש (יבמות דף קיב.) מבזז בזיז מיניה מיהו גם יש לפרש לשון פחד ובערוך פי' לשון בושת:"],[7,"","חבר שמת והניח מגורה מלאה פירות כו'. בפ\"ק דחולין (דף י.) גבי שחט ונמצא סכין פגומה קאמר נמי אין ספק מוציא מידי ודאי ולא מייתי מהך דחבר ושפחה משום דהכא הוי ספק טוב ורגיל ואפי' לקולא מוציא מידי ודאי וה\"נ לא שייך לאתויי ההיא דהתם דטבל ועלה דאתי ספק ומוציא מידי ודאי דהתם היינו משום דהוי לחומרא:"],[9,"","בהמתו אוכלת. דוקא בהמתו כדפ\"ה דכל מה שהיא אוכלת מיקרי עראי אבל אדם אסור מדרבנן לאכול אכילת קבע וכן משמע בתוספתא ומייתי לה בפ\"ק דביצה (דף יג.) הכניס לבית שבלים לעשות מהן עיסה אוכל מהן עראי ופטור וכן משמע נמי מדנקט בהמתו והא דפריך במנחות בפרק רבי ישמעאל (מנחות דף סז.) אמאי דקאמר מירוח העובד כוכבים אינו פוטר משום בעלי כיסים פירוש עשירים שמוכרין תבואתן לעובדי כוכבים קודם מירוח וחוזרין וקונין אחר מירוח אפשר דעבד כר' אושעיא פירוש שיוכל להערים ולפטור שיכניס התבואה במוץ שלה ומה הועילו חכמים בתקנתם משמע דלגמרי פטור ה\"פ עביד ליה כרבי אושעיא ובמידי דמאכל בהמה מה הועילו חכמים בתקנתם מיהו אי מירוח העובד כוכבים אינו פוטר רק עראי כמו שהיה קודם מירוח אתי שפיר אך צ\"ע בשילהי פ\"ק דבכורות (דף יא:) והשתא קשה כיון דהוי ודאי טבל לענין אכילת קבע אפילו הכניסה במוץ כדפרישית היכי אתי ספק ומוציא מידי ודאי דחשבינן להו בחזקת מתוקנים וליכא למימר דספק מוציא מידי ודאי דרבנן דהא בפרק קמא דפסחים (דף ט.) פריך מיניה אהא דקאמר התם כל מקום שחולדה וברדלס מצויין שם אין צריך בדיקה הא ודאי חמץ צריך בדיקה דספק אכל אין מוציא מידי ודאי ופריך מהך דחבר ומשני ספק וספק הוא כדרבי אושעיא והשתא מ\"מ חזינא הכא דמוציא מידי ודאי דרבנן ובדיקת חמץ נמי הוי דרבנן דמדאורייתא בבטול בעלמא סגי ואומר ר\"י דמתניתי' דהתם איירי שלא בטלו דהוי ודאי דאורייתא ועוד אומר ר\"י דהא דקאמר הכא דהוו בחזקת מתוקנים היינו בהנך דלא חזו אלא לבהמה:[וע\"ע תוס' פסחים לד. ד\"ה מחמין לו]:"],[9,"","כדי שתהא בהמתו אוכלת. משמע דבטבל שראה פני הבית אפילו בהמתו נמי לא אכלה ותימה לר\"י מ\"ש משאר הנאות דשרו דלא מצינו טבל שיהיה אסור בהנאה וי\"ל דדרשינן בבמה מדליקין (שבת דף כו.) גבי אין מדליקין בטבל טמא משום דכתיב את משמרת תרומותי בשתי תרומות הכתוב מדבר אחת טהורה ואחת טמאה מה טהורה אין לך בה פי' אכילתה אלא משעת הרמה ואילך אף טמאה כן דהיינו הדלקה והדר גמר טהורה מטמאה דמיתסרה בהדלקה קודם הרמה וה\"ה למאכיל לבהמתו וכל שאר הנאה של כילוי ומהכא נמי שמעינן דאין ישראל מאכיל לבהמתו כרשיני תרומה:"],[10,"","בשפחתו של מסיק. משמע דשפחה מטמאה בלידה וכן מוכח בפ' רבי אליעזר דמילה (שבת דף קלה:) דקאמר לקח שפחה ונתעברה אצלו זהו יליד בית שנימול לשמונה והתם קאמר כל שאין אמו טמאה לידה אינו נימול לשמונה ובת\"כ תניא נמי בהדיא אין לי אלא בני ישראל גיורת ושפחה בין משוחררת ובין שאינה משוחררת מנין ת\"ל אשה ונראה דהא דיליף לאינה משוחררת מאשה אסמכתא בעלמא הוא ואגב אחריני נקט לה דבפ\"ק דכריתות (דף ז:) משמע מג\"ש דלה לה אתיא ובפ' הערל (יבמות דף עד:) לא יליף מאשה אלא גיורת ומשוחררת ושאינה משוחררת אינו מזכיר שם:"],[10,"","ובא כהן והציץ. אומר ר\"ת דכהן שוטה היה דאפילו אם נאמר דשל גבירתה היה וכהן זה קרוב היה לא היה לו לטמאות דאמר בת\"כ דאין כהנים מטמאין לנפלים דבעינן דומיא דאביו ואמו ועוד דכאן לא היה לצורך המת:"],[10,"","מסיק. בסמ\"ך גרס שהיה מוסק זיתים:"],[12,"","ספק גררוהו ההיא שעתא כו'. וא\"ת והאי בור היכא קאי אי ברה\"ר אפילו בספקא אחת טהור אי ברה\"י מאי משני שהטילה כמין נפל לבור והתניא דברה\"י כל ספקות שאתה יכול להרבות טמא וי\"ל דגרירת חולדה וברדלס הוי ספק הרגיל וקרוב לודאי ותדע דאפילו מידי ודאי בעי למימר שמוציא זה הספק ואומר ר\"י דצריך לומר דרגלי הכהן היו ברה\"ר דאי רגליו היו ברה\"י ניחוש דלמא גררוהו כנגד רגליו וטומאה בוקעת ועולה דע\"כ ליכא בחוריהן פותח טפח דכי איכא מאי מועלת גרירה והא בפותח טפח מביא הטומאה ועוד י\"ל דרגלי הכהן ברשות היחיד וגררוהו ואכלוהו הוי ספק הרגיל:"]]],[["כמין נפל","והא לידע אם זכר אם נקבה קתני","ה\"ק ובא כהן והציץ בו לידע אם נפל הפילה אם רוח הפילה ואת\"ל נפל הפילה לידע אם זכר אם נקבה","ואיבעית אימא כיון דחולדה וברדלס מצויים שם ודאי גררוהו","בעו מיניה מרב נחמן וסתות דאורייתא או דרבנן","אמר להו מדאמר הונא חברין משמיה דרב אשה שיש לה וסת והגיע שעת וסתה ולא בדקה ולבסוף ראתה חוששת לוסתה וחוששת לראייתה אלמא וסתות דאורייתא","איכא דאמרי הכי קא\"ל טעמא דראתה הא לא ראתה אין חוששין אלמא וסתות דרבנן","איתמר אשה שיש לה וסת והגיע שעת וסתה ולא בדקה ולבסוף בדקה אמר רב בדקה ומצאת טמאה טמאה טהורה טהורה ושמואל אמר אפילו בדקה ומצאת טהורה נמי טמאה מפני שאורח בזמנו בא","לימא בוסתות קמיפלגי דמ\"ס דאורייתא ומ\"ס דרבנן","אמר ר' זירא דכ\"ע וסתות דאורייתא כאן שבדקה עצמה כשיעור וסת כאן שלא בדקה עצמה כשיעור וסת","ר\"נ בר יצחק אמר בוסתות גופייהו קמיפלגי דמ\"ס וסתות דאורייתא ומר סבר וסתות דרבנן","אמר רב ששת כתנאי ר' אליעזר אומר טמאה נדה","ורבי יהושע אומר תבדק והני תנאי כי הני תנאי דתניא רבי מאיר אומר טמאה נדה וחכ\"א תבדק","אמר אביי אף אנן נמי תנינא דתנן ר\"מ אומר אם היתה במחבא והגיע שעת וסתה ולא בדקה טהורה שחרדה מסלקת את הדמים טעמא דאיכא חרדה הא ליכא חרדה טמאה אלמא וסתות דאורייתא","לימא הני תנאי בהא נמי פליגי דתניא הרואה דם מחמת מכה אפילו בתוך ימי נדתה טהורה דברי רשב\"ג","רבי אומר אם יש לה וסת חוששת לוסתה","מאי לאו בהא קמיפלגי דמר סבר וסתות דאורייתא ומר סבר וסתות דרבנן","אמר רבינא לא דכ\"ע וסתות דרבנן והכא במקור מקומו טמא קמיפלגי","רשב\"ג סבר אשה טהורה ודם טמא דקאתי דרך מקור","ואמר ליה רבי אי חיישת לוסת אשה נמי טמאה ואי לא חיישת לוסת מקור מקומו טהור הוא","\u0001מתני׳\u0002 בית שמאי אומרים צריכה ב' עדים על כל תשמיש ותשמיש או תשמש לאור הנר בית הלל אומרים דיה בשני עדים כל הלילה:"],[[0,"כמין נפל","הלכך ספק וספק הוא דדלמא מעיקרא לאו נפל הוא:"],[3,"ודאי גררוהו","הלכך ודאי וודאי הוא:"],[4,"וסתות דאורייתא או דרבנן","הא דקיימא לן דבעי בדיקה בשעת וסתה דאורייתא היא דאם לא בדקה טמאה ואפילו בדקה אחר זמן ומצאתה טהורה דאורח בזמנו בא ודם חזאי ונפל לקרקע או דרבנן הוא דאצרכוה ואם לא בדקה טהורה:"],[5,"ולבסוף ראתה","בבדיקה ראשונה שבדקה עצמה לאחר זמן ומצאתה טמאה:"],[5,"חוששת לוסתה וחוששת לראייתה","אם זמן וסתה קודם מעת לעת של ראייתה מטמאינן טהרות דוסתה ואילך דלמא בזמנו בא ואם מעת לעת של ראייתה קודם לוסתה דלא שהתה משעת וסתה עד ראייתה מעת לעת אזלינן בתר ראייה וטמאה מעת לעת. וקס\"ד דה\"ה נמי אם בדקה ומצאתה טהורה דחוששת לוסתה והא דנקט ראתה משום דבעי למימר וחוששת לראייתה:"],[6,"טעמא דראתה","דכיון דבבדיקה ראשונה מצאתה טמאה אם בדקה נמי בשעת וסתה הוה משכחא:"],[9,"דכ\"ע","אפי' רב מודה דוסתות דאורייתא והא דקאמר דבמצאתה טהורה טהורה כשבדקה בשיעור וסת של וסתה דודאי אי הוה דם הוה משכחא ושמואל סבר אפי' הכי טמאה דאורח בזמנו בא הואיל ולא בדקה בשעת וסת ממש:"],[9,"וכאן שלא בדקה עצמה כו'","הא דקאמר לעיל וסתות דאורייתא וטמאה אפילו לרב בשלא בדקה עצמה בשיעור וסת ואח\"כ בדקה ומצאתה טהורה טמאה ואיכא דאמרי דמר אמר חדא ומר אמר חדא ולא פליגי:"],[11,"טמאה נדה","אם הגיע וסתה ולא בדקה. קסבר וסתות דאורייתא:"],[12,"תבדק","לאחר וסתה מצאתה טמאה טמאה משעת וסתה טהורה טהורה:"],[13,"אף אנן נמי תנינא","דלרבי מאיר וסתות דאורייתא:"],[13,"במחבא","מחמת פחד ליסטין ובולשת:"],[14,"הרואה דם מחמת מכה","שיש לה במעיה:"],[14,"אפי' בתוך ימי נדתה","כלומר בימים שהיא למודה לראות דהיינו שעת עונתה או שעת וסתה:"],[14,"טהורה","דתלינן במכה שבאותו מקום:"],[15,"אם יש לה וסת חוששת לוסתה","כלומר כשאין לה וסת קבוע מודינא לך שאף על פי שעברה עונתה תולה במכה אבל אם יש לה וסת קבוע וראתה ביום וסתה אפי' מחמת מכה חיישינן שמא טיפת נדה מעורבת בו:"],[17,"מקומו טמא","וכל דם הבא דרך שם ואפילו אינו דם נדה הוי אב הטומאה לטמא אדם טומאת ערב ואם נגעה בטהרות טמאים. וקאמר ליה רבי כו' ולהקל על דבריו בא וה\"ק אם יש לה וסת כלומר אם אתה אומר לטמאה מפני וסתה חוששת לוסתה כלומר יש לך לטמאה טומאת שבעה והואיל ואינך חושש לכך שהרי אתה אומר טהורה משום נדה שוב אין לה טומאה:"],[20,"מתני' שני עדים","חדשים על כל תשמיש אחד לפניו ואחד לאחריו ולמחר תעיין בהם:"],[20,"או תשמש לאור הנר","ותבדוק לאחר תשמיש עד שקנחה בו:"],[20,"דיה בשני עדים כל הלילה","אחד לפני תשמיש ראשון ואחד לאחר תשמיש אחרון. ואע\"ג דמשמשת ולא ידעה אי חזאי ביני וביני בין לבית שמאי בין לבית הלל לא איכפת לן דלא הוצרכו לבדוק אלא לחומר טהרות:"]],[[5,"","וחוששת לראייתה. פרש\"י לענין מעת לעת אע\"ג דקי\"ל כרבי דוסא דאשה שיש לה וסת דיה שעתה שלא בשעת וסת מודה דמטמא למפרע ועוד י\"ל דהכא מיירי לענין שתהא מקולקלת למניינה:"],[5,"","אלמא וסתות דאורייתא. השתא סבר הא דנקט ראתה לאשמועינן דחוששת לראייתה ולא חשבינן לה כאילו ודאי ראתה מזמן הוסת וה\"ה דכי לא ראתה חוששת ואם תאמר היאך רוצה להוכיח דוסתות דאורייתא והלא אפי' אי וסתות דרבנן כיון דראתה עכשיו טמאה גם מזמן הוסת מספק וי\"ל הני מילי לטהרות אבל מקולקלת למניינה לא הויא:"],[6,"","אלמא וסתות דרבנן. וא\"ת דלעיל (נדה דף טו.) אמר רב הונא לא שנו אלא שלא הגיע שעת וסתה כו' אלמא וסתות דאורייתא וי\"ל דהכא קאמר משמיה דרב וליה לא ס\"ל ואליבא דרב איכא לקמן ב' לשונות אי נמי לעיל אתי כלישנא קמא דהכא:"],[10,"","ורב נחמן בר יצחק אמר בוסתות גופייהו פליגי. נראה דהלכה דוסתות דרבנן דהא רב נחמן בר יצחק דהוא בתראה אית ליה דלרב וסתות דרבנן ובפ' יש בכור (בכורות דף מט:) פסיק כרב באיסורי ועוד דקיימא לן כר' יהושע דבסמוך לגבי רבי אליעזר וכחכמים לגבי ר' מאיר ואע\"ג דתנן בפ' בנות כותים (לקמן נדה דף לט.) ברישא דהיתה במחבא הגיע שעת וסתה ולא בדקה טמאה מ\"מ נראה דהלכה הוי וסתות דרבנן כדפרישית ועוד דאיכא דמוקי לה בפרק בנות כותים (שם) כרבי מאיר וכן פסק בשאלתות דרב אחאי ור\"ח הילכך אשה שיש לה וסת ולא בדקה בשעת וסתה ואח\"כ בדקה ומצאתה טהורה טהורה לבעלה ומיהו נראה לכתחלה צריכה לבדוק בשעת הוסת:"],[16,"","ומר סבר וסתות דרבנן. נראה דדוקא במרגשת שבא דם זה מן המכה ואפ\"ה אם זמן וסת הוא אי וסתות דאורייתא חיישינן שמא גם מן המקור בא הדם אבל אם אינה מרגשת יציאת דם מן המכה טמאה לכ\"ע אם הוא זמן וסתה דאי לאו הכי וכי לעולם לא תהא נדה והלא קודם מכה הוה לה וסת:"],[17,"","במקור מקומו טמא קמיפלגי. ורשב\"ג לטעמיה בריש תינוקת (לקמן נדה דף סו.) ואע\"ג דטומאת בית הסתרים היא ובפרק דם הנדה (לקמן נדה נה:) אמר נמי דדם בעי רביעית והכא קאמר טמא אע\"ג דליכא רביעית כדאמרינן בפ' יוצא דופן (לקמן נדה דף מא:) מקור שהזיע כב' טיפי מרגליות טמאה שמא הכא הלמ\"מ הוא תדע שהמקור טמא והאשה טהורה:"],[20,"","ב\"ש אומרים צריכה ב' עדים על כל תשמיש. פרש\"י ב' עדים חדשים א' לפני תשמיש ואחד לאחר תשמיש ומצנעת עד הבקר ובה\"א דיה בב' עדים כל הלילה אחד לפני תשמיש ראשון ואחד לאחר תשמיש אחרון [ועוד דמשמע או משמש לאור הנר אם רוצה להקל כב\"ה ואפילו תשמש לאור הנר צריכה לב\"ש בדיקה בכל תשמיש אבל לפירוש רש\"י ולפירוש ר\"י א\"ש תשמש לאור הנר פי' שבודקת מיד מסתמא אם היתה שם טיפת חרדל היתה רואה אפי' על עד ישן. ולפירוש ר\"י קיימא שפיר ב\"ש אדם שעל העד אבל לעולם קיימא אדם שבתוך הפה דלישנא בתוך הפה דלישנא בתוך הפה הכי משמע גי'] וקשה דלפני תשמיש לא בעו חדשים אלא צנועות ועוד קשה מה שפירש לב\"ה דלא מצרכי לבדוק בכל תשמיש דלעיל אמר דאינן צנועות עד שבודקות בו לפני תשמיש זה בודקות בו לפני תשמיש אחר משמע דבכל תשמיש בודקות מיהו הא י\"ל בודקות בתשמיש אחר שבלילה שניה ועוד קשה מה יודעת מתי שימש באחרונה שתבדוק אחריו ואם היתה בודקת בשחר כשהיא עומדת א\"כ אינה בודקת סמוך לתשמיש לידע אם בועל בנדות לטמא בועלה ז' ועוד קשה דקאמר ב\"ש שמא תחפנה שכבת זרע בביאה שניה היה לו לומר בביאה אחרונה כיון דלב\"ה אינה בודקת עד לאחר תשמיש אחרון ועוד דב\"ה נקט נימוק וב\"ש נקט לישנא אחרינא שמא תחפנה היה לו לב\"ש נמי למינקט נימוק כיון דקאי על דם שברחם ולא על הדם שעל העד דהא בית הלל לא מצרכי בדיקה אחר תשמיש ראשון ועוד דקאמר מדברי כולן נלמד בעל נפש לא יבעול וישנה פירוש בלא בדיקה בינתים אפילו לבעלה גרידא הא לב\"ה אף לטהרות לא צריכה בדיקה ונראה לר\"י כפירוש רשב\"ם דלב\"ש צריכה ב' עדים חדשים אחר תשמיש אחד לו ואחד לה והא דקתני צריכה היינו כלומר שהיא מכינה כדתנן בנות ישראל משמשות בב' עדים אחד לו ואחד לה אע\"ג דלפני תשמיש אינה צריכה חדש אלא צנועות היינו לפי שאין העד מלוכלך כ\"כ אבל לאחר תשמיש שמלוכלך בשכבת זרע צריכות בכל פעם חדש וב\"ה אומרים דיה בב' עדים כל הלילה מודים שצריכה בדיקה אחר כל תשמיש אך דלא מצרכי חדש וטעמא משום דאחר תשמיש איכא רוב לכלוך משכבת זרע ואין ריוח בעד חדש ואפשר דאפילו צנועות לא בעו חדש לאחר תשמיש והשתא אתי שפיר הכל:"]]],[["\u0001גמ׳\u0002 ת\"ר אע\"פ שאמרו המשמש מטתו לאור הנר הרי זה מגונה בש\"א צריכה שני עדים על כל תשמיש או תשמש לאור הנר ובה\"א דיה בשני עדים כל הלילה","תניא אמרו להם ב\"ש לב\"ה לדבריכם ליחוש שמא תראה טיפת דם כחרדל בביאה ראשונה ותחפנה שכבת זרע בביאה שניה","א\"ל ב\"ה אף לדבריכם ליחוש עד שהרוק בתוך הפה שמא נימוק והולך לו","אמרו להם לפי שאינו דומה נימוק פעם אחת לנימוק שתי פעמים","תניא א\"ר יהושע רואה אני את דברי ב\"ש אמרו לו תלמידיו רבי כמה הארכת עלינו אמר להם מוטב שאאריך עליכם בעוה\"ז כדי שיאריכו ימיכם לעוה\"ב","אמר ר' זירא מדברי כולם נלמד בעל נפש לא יבעול וישנה","רבא אמר בועל ושונה כי תניא ההיא לטהרות","תניא נמי הכי בד\"א לטהרות אבל לבעלה מותרת ובד\"א שהניחה בחזקת טהרה אבל הניחה בחזקת טמאה לעולם היא בחזקתה עד שתאמר לו טהורה אני","א\"ר אבא א\"ר חייא בר אשי אמר רב בדקה בעד ואבד אסורה לשמש עד שתבדוק מתקיף לה ר' אילא אילו איתא מי לא משמשה ואע\"ג דלא ידעה השתא נמי תשמש","א\"ל רבא זו מוכיחה קיים וזו אין מוכיחה קיים","א\"ר יוחנן אסור לאדם שישמש מטתו ביום אמר רב המנונא מאי קרא שנאמר (איוב ג, ג) יאבד יום אולד בו והלילה אמר הורה גבר לילה ניתן להריון ויום לא ניתן להריון ריש לקיש אמר מהכא (משלי יט, טז) בוזה דרכיו ימות","ור\"ל האי קרא דר' יוחנן מאי דריש ביה מבעי ליה לכדדריש רבי חנינא בר פפא דדריש ר' חנינא בר פפא אותו מלאך הממונה על ההריון לילה שמו ונוטל טפה ומעמידה לפני הקב\"ה ואומר לפניו רבש\"ע טפה זו מה תהא עליה גבור או חלש חכם או טיפש עשיר או עני","ואילו רשע או צדיק לא קאמר כדר' חנינא דא\"ר חנינא הכל בידי שמים חוץ מיראת שמים שנאמר (דברים י, יב) ועתה ישראל מה ה' אלהיך שואל מעמך כי אם ליראה וגו'","ור' יוחנן א\"כ נכתוב קרא גבר הורה מאי הורה גבר לילה ניתן להריון ויום לא ניתן להריון","ור' יוחנן האי קרא דר\"ל מאי דריש ביה מבעי לי' לכדכתיב בספר בן סירא שלשה שנאתי וארבעה לא אהבתי שר הנרגל בבית המשתאות ואמרי לה שר הנרגן ואמרי לה שר הנרגז","והמושיב שבת במרומי קרת והאוחז באמה ומשתין מים והנכנס לבית חבירו פתאום אמר רבי יוחנן ואפילו לביתו","אמר רבי שמעון בן יוחאי ארבעה דברים הקב\"ה שונאן ואני איני אוהבן הנכנס לביתו פתאום ואצ\"ל לבית חבירו והאוחז באמה ומשתין מים"],[[0,"גמ' מגונה","טעמא מפרש לקמן:"],[1,"שמא תראה","בביאה ראשונה ויעמידוהו כותלי בית הרחם וכיון דלא מצריכיתו בדיקה בין תשמיש לתשמיש כי הדר משמש תחפנה שכבת זרע בביאה שניה וכי בדקה לאחר תשמיש אחרון לא מינכר למחר ונהי נמי דלדידן משמשא לאחר קינוח ואע\"ג דלא ידעינן עד למחר מיהו בעינן מוכיחה קיים דאי לאו הכי מה הועילו חכמים בתקנתם:"],[2,"עד שהרוק בתוך הפה כו'","רוק דם. פה אותו מקום. כלומר אפילו כשהיתה בודקת לאחר תשמיש שמא ראתה טפה כחרדל וחפתה שכבת זרע באותה ביאה עצמה:"],[4,"הארכת","החמרת:"],[5,"בעל נפש","חסיד:"],[5,"לא יבעול וישנה","בלא בדיקה בינתים דאפילו ב\"ה מצרכי בדיקה לסוף תשמיש אלמא חיישינן לשמא ראתה דם מחמת תשמיש אלמא מי שהוא ירא ופורש מספק איסור לא יבעול וישנה:"],[7,"בד\"א","דבעיא בדיקה:"],[8,"בדקה בעד","בלילה לפני תשמיש:"],[8,"ואע\"ג דלא ידעה","דהא לב\"ה עד למחר לא בדקה ואפי' לב\"ש נמי אם יש לה ב' עדים לכל תשמיש משמשת בלא נר אף ע\"ג דלא ידעה אי איכא דם בעדים של תשמיש ראשון:"],[9,"זו מוכיחה קיים","הרי העד לפנינו ולמחר תראה בו ומהני לה לטהרות דכי אצרכוה רבנן לשמש בעדים משום טהרות הוא וגם אם ימצא דם באותו שלפני תשמיש תביא חטאת כפרתה:"],[9,"וזו","שאבד עדה אין מוכיחה קיים ואי אמרת תשמש מה תקנת חכמים יש כאן דהרי היא כמו שלא בדקה:"],[10,"בוזה דרכיו","תשמיש כמו (משלי ל,יט) דרך גבר בעלמה. והמשמש ביום בא לידי בזיון שמא יראה בה דבר מגונה ותתגנה עליו:"],[12,"הכל בידי שמים","כל מדותיו וקורותיו של אדם באין לו בגזרת מלך חוץ מזו:"],[12,"כי אם ליראה","דבר זה לבדו הוא שואל ממך לפי שהכל בידו וזה בידך:"],[13,"מאי הורה גבר","מדסמך הריון ללילה ש\"מ למדרש הכי לילה ניתן להריון ולא יום מדאסמכיה קרא שמעינן לדר' יוחנן ומגופה דקרא שמעינן להא דר' חנינא בר פפא:"],[14,"מיבעי ליה כו'","והיינו בוזה דרכיו שמגנה עצמו שמלעיזין עליו בני המדינה במנהגו:"],[14,"שר","תלמיד חכם:"],[14,"הנרגל","רגיל:"],[14,"נרגן","מרבה דברים:"],[14,"ואמרי לה נרגז","בזעם דנראה כנבל ומשתכר:"],[15,"והמושיב שבת","לתלמידים במרומי קרת אחת שנראה מגסי הרוח ועוד שמפסיקין אותן עוברי דרכים:"],[15,"ואפילו לביתו","דלמא עבדי מידי דצניעותא:"]],[[5,"","לא יבעול וישנה. פירוש אם לא יבדוק דשמא מחמת חימוד תשמיש ראשון ראתה ודוקא בעל נפש דר' זירא ידע נמי דלבעלה לא בעיא בדיקה ורבא אמר אפי' בעל נפש לא דלמא לבו נוקפו ופורש וא\"ת ומאי מייתי תניא נמי הכי דלמא ברייתא לא מיירי בבעל נפש אלא בסתם בני אדם או בביאה ראשונה וי\"ל דאבל לבעלה מותרת משמע היתר גמור לכל העולם ואפי' בביאה שניה:"],[8,"","בדקה ואבד העד. לפירוש רשב\"ם ה\"פ בדקה לפני תשמיש ואבד העד לפני תשמיש אסורה לשמש עד שתבדוק פעם שניה אבל לאחר תשמיש אפילו לא אבד העד צריכה לעולם בדיקה לפני תשמיש ור\"א פריך ממתני' שפיר אע\"ג דמתני' לא איירי בעד שלפני תשמיש אלא בשל אחר תשמיש א\"נ מיירי הכא בעד שאחר תשמיש אם אבד אסורה לשמש עד שתבדוק אפי' אם רוצה לשמש מיד אחר תשמיש ראשון אבל אם לא אבד מותרת כי למה תבדוק ב' פעמים מיד זה אחר זה:"],[11,"","מלאך הממונה על ההריון. אבל על הלידה אין שום מלאך ממונה כדאמר בריש תענית (דף ב.) ג' מפתחות בידו של הקב\"ה של חיה ושל גשמים ושל תחיית המתים והנהו שלש מפתחות נמי פעמים מוסרין לשליח לפי שעה שהרי אליהו היה בידו מפתח של גשמים והחייה המת וכן אלישע וכמה צדיקים ואף ברי (אותת) (איוב לז) שהוא שר מטר אין עושה אלא ברשות הקב\"ה:"],[12,"","הכל בידי שמים חוץ מיראת שמים. ובאלו נערות (כתובות ל.) דאמר הכל בידי שמים חוץ מצינים ופחים הכא איירי בתולדות האדם ובמדותיו והתם מיירי במאורעות כגון חלאים ופורעניות דהכל נגזר עליו ואינו יכול ליזהר כדאמר בחולין (דף ז:) אין אדם נוקף אצבעו מלמטה אא\"כ מכריזין עליו מלמעלה חוץ מצינים ופחים שיכול לשמור עצמו וא\"ת והא חזקיה חזא דהוו ליה בני דלא מעלו (ברכות י.) אלמא דנגזר קודם לידה שלא יהיו יראי שמים וי\"ל דהראהו מה שעתיד להיות ועוד דהרבה דברים תלוי במזל כדאמר בשילהי שבת (דף קנו.) מאן דאיתיליד בצדק יהא צדקן במצות דאיתיליד בשבת מתקרי קדישא וכן הא דאמרי כלדאי לאמיה דרב נחמן בר יצחק בריך גנבא ליהוי (שם:) ועוד דאין זה בידי שמים כי אין הקב\"ה רוצה לשנות הילוך המזלות:"],[14,"","שר הנרגל. פירש בערוך שמתרעמים עליו בבית המשתאות:"]]],[["ומשתין מים ערום לפני מטתו והמשמש מטתו בפני כל חי אמר ליה רב יהודה לשמואל ואפי' לפני עכברים א\"ל שיננא לא אלא כגון של בית פלוני שמשמשין מטותיהן בפני עבדיהם ושפחותיהם","ואינהו מאי דרוש (בראשית כב, ה) שבו לכם פה עם החמור עם הדומה לחמור","רבה בר רב הונא מקרקש זגי דכילתא אביי באלי דידבי רבא באלי פרוחי","אמר ר\"ש בן יוחי ה' דברים הן שהעושה אותן מתחייב בנפשו ודמו בראשו האוכל שום קלוף ובצל קלוף וביצה קלופה והשותה משקין מזוגין שעבר עליהן הלילה והלן בבית הקברות והנוטל צפרניו וזורקן לרה\"ר והמקיז דם ומשמש מטתו","האוכל שום קלוף כו' ואע\"ג דמנחי בסילתא ומציירי וחתימי רוח רעה שורה עליהן ולא אמרן אלא דלא שייר בהן עיקרן או קליפתן אבל שייר בהן עיקרן או קליפתן לית לן בה","והשותה משקין מזוגין שעבר עליהן הלילה אמר רב יהודה אמר שמואל והוא שלנו בכלי מתכות אמר רב פפא וכלי נתר ככלי מתכות דמו וכן אמר רבי יוחנן והוא שלנו בכלי מתכות וכלי נתר ככלי מתכות דמו","והלן בבית הקברות כדי שתשרה עליו רוח טומאה זימנין דמסכנין ליה","והנוטל צפרניו וזורקן לרשות הרבים מפני שאשה מעוברת עוברת עליהן ומפלת ולא אמרן אלא דשקיל בגנוסטרי ולא אמרן אלא דשקיל דידיה ודכרעיה ולא אמרן אלא דלא גז מידי בתרייהו אבל גז מידי בתרייהו לית לן בה ולא היא לכולה מילתא חיישינן","ת\"ר ג' דברים נאמרו בצפרנים שורפן חסיד קוברן צדיק זורקן רשע","והמקיז דם ומשמש מטתו דאמר מר מקיז דם ומשמש מטתו הויין לו בנים ויתקין הקיזו שניהם ושמשו הויין לו בנים בעלי ראתן אמר רב ולא אמרן אלא דלא טעים מידי אבל טעים מידי לית לן בה","אמר רב חסדא אסור לו לאדם שישמש מטתו ביום שנאמר (ויקרא יט, יח) ואהבת לרעך כמוך מאי משמע אמר אביי שמא יראה בה דבר מגונה ותתגנה עליו אמר רב הונא ישראל קדושים הם ואין משמשין מטותיהן ביום","אמר רבא ואם היה בית אפל מותר ות\"ח מאפיל בכסותו ומשמש","תנן או תשמש לאור הנר אימא תבדוק לאור הנר","ת\"ש אע\"פ שאמרו המשמש מטתו לאור הנר הרי זה מגונה אימא הבודק מטתו לאור הנר הרי זה מגונה","תא שמע ושל בית מונבז המלך היו עושין ג' דברים ומזכירין אותן לשבח היו משמשין מטותיהם ביום ובודקין מטותיהם במילא פרהבא ונוהגין טומאה וטהרה בשלגים קתני מיהא משמשין מטותיהן ביום","אימא בודקין מטותיהם ביום הכי נמי מסתברא דאי ס\"ד משמשין מזכירין אותן לשבח אין ה\"נ דאגב דאיכא אונס שינה מגניא באפיה","ובודקין מטותיהן במילא פרהבא מסייע ליה לשמואל דאמר שמואל אין בודקין את המטה אלא בפקולין או בצמר נקי ורך אמר רב היינו דכי הואי התם בערבי שבתות הוו אמרי מאן בעי פקולי בנהמא ולא ידענא מאי קאמרי","אמר רבא הני שחקי דכיתנא מעלי לבדיקה איני והא תנא דבי מנשה אין בודקין את המטה לא בעד אדום ולא בעד שחור ולא בפשתן אלא בפקולין או בצמר נקי ורך","לא קשיא הא בכיתנא הא במאני דכיתנא ואיבעית אימא הא והא במאני דכיתנא הא בחדתי הא בשחקי","נוהגין טומאה וטהרה בשלגין תנן התם שלג אינו לא אוכל ולא משקה חישב עליו לאכילה אינו מטמא טומאת אוכלין למשקה מטמא טומאת משקין","נטמא מקצתו לא נטמא כולו נטהר מקצתו נטהר כולו","הא גופא קשיא אמרת נטמא מקצתו לא נטמא כולו והדר תני נטהר מקצתו נטהר כולו למימרא דנטמא כולו","אמר אביי כגון שהעבירו על אויר תנור דהתורה העידה על כלי חרס"],[[2,"מקרקש זגי","פעמונים התלויים בכילה שסביב מטתו מקשקשן בעת תשמיש לסור בני ביתו משם:"],[2,"באלי דידבי","מגרש הזבובים שלא לשמש מטתו בפני כל חי:"],[2,"פרוחי","יתושים:"],[3,"דמו בראשו","נענש על עצמו וחובת דמו נדרשת ממנו לאחר מיתתו וראיה לדבר ודמו בראשנו דמרגלים (יהושע ב׳:י״ט) חובת דמו יהא מוטל בראשנו:"],[3,"ומתחייב בנפשו","כלומר הוא גורם לעצמו:"],[3,"שעבר עליהם הלילה","אכולהו קאי אשום ובצל ומשקין:"],[4,"בסילתא","סל:"],[4,"עיקרן","שערות שבראש השום והבצל:"],[6,"רוח טומאה","כמדת הלצים שקורין גרמנטי\"ר האוחזים את העיניים:"],[7,"בגנוסטרי","מספרים:"],[8,"חסיד","עדיף מצדיק. כשקוברן איכא למיחש דהדרי ומגלו:"],[9,"ויתקין","חלשים:"],[9,"בעלי ראתן","חלשים יותר מדאי שיש להם שרץ במוחם כדאמר בכתובות:"],[11,"תלמיד חכם","דידע לאצטנועי נפשיה:"],[13,"אף על פי שאמרו המשמש מטתו כו'","כדאיתא בברייתא דלעיל בריש שמעתין ומסקנא או תשמש לאור הנר אלמא מגונה הוא דהוי אבל איסורא ליכא מדקתני או תשמש והשתא ליכא למימר תבדוק דא\"כ מאי אע\"פ שאמרו כו':"],[13,"אימא הבודק מטתו לאור הנר כו'","משום דלא מיבדיק שפיר אפ\"ה או תביא שני עדים לכל תשמיש או תבדוק לאור הנר:"],[14,"מילא פרהבא","קוטו\"ן. מתוך שהוא לבן נראית בו טיפה כחרדל. לישנא אחרינא צמר נקי ורך:"],[15,"ומזכירין חכמים אותן לשבח","בתמיה. נהי אי הוה מותר בעלמא הוה תמיה לן וכ\"ש שמזכירין לשבח ומה הוא שבחן:"],[15,"אונס שינה","מתוך שהוא נאנס בשינה אינו מתאווה לה כל כך ומשמש לקיום מצות עונה בעלמא או לרצותה ולבו קץ בה והוא מבני תשע מדות דאמרו בנדרי' (דף כ:):"],[16,"פקולין","קוטו\"ן:"],[16,"דכי הואי התם","בארץ ישראל:"],[16,"בערבי שבתות","זמן עונת פרושים ותלמידי חכמים מערב שבת לערב שבת:"],[17,"שחקי דכיתנא","בגדים בלויין של פשתן:"],[17,"ולא בפשתן","שאינו לבן ואין דם ניכר יפה אלא בעד לבן:"],[18,"שחקים","לבנים יותר מן החדשים:"],[19,"חישב עליו וכו'","דקרוב הוא להיות משקה יותר מאוכל:"],[20,"לא נטמא כו'","דאינו חבור אלא כל קורט בפני עצמו חשוב ואינו טמא אלא מקום מגע טומאה:"],[20,"נטהר מקצתו","כגון חישב עליו למשקה ונטמא טומאת משקין סלקא ליה השקה במקוה כשאר מים ולא משום טבילה דאין אוכל ומשקה נטהרין במקוה דלא כתיב טבילה אלא באדם וכלי אבל יין ולא שום משקה אין להם טהרה אלא מים ומשום זריעה דכי משיק להו הוו להו חבור מים שבכלי עם מי המקוה ובטילו להו גבייהו כדתנן (תרומות פ\"ט מ\"ז) שתילי תרומה שנטמאו ושתלן טהרו מלטמא אלמא מטהרא להו זריעה ומים במים זו היא זריעתן:"],[20,"נטהר מקצתו","שלא נגעו המים אלא בפי הכלי:"],[20,"נטהר כולו","ומדקתני נטהר כולו מכלל דטמא כולו והיכי משכחת לה דנגעה טומאה בכולו:"],[22,"שהעבירו","לשלג:"],[22,"על אויר תנור","ושרץ בתוכו דנטמא מאויר כלי חרס:"],[22,"דהתורה העידה","כל אשר בתוכו יטמא (ויקרא י״א:ל״ג):"]],[[0,"","ומשתין מים ערום לפני מטתו. דאמר בשבת (דף סב:) דקשה לעניותא ויש ספרים דגרסי הכא משמש מטתו ערום וכן הוא בויקרא רבה וטעמא שיש לו להיות צנוע בשעת תשמיש כדאמרינן בנדרים (דף כ.):"],[0,"","שמשמשין מטותיהן בפני עבדיהן. ומיירי בלילה או במקום אפל דבמקום אורה אפי' בלא לפני עבדיהם אסור:"],[2,"","מקרקש זגי. פ\"ה פעמונים התלוים בכילה להוציא ממנו בני ביתו וקשה לר\"ת דאין זה מדת צניעות ונראה לו כגירסת ר\"ח והערוך [ערך גזח'] מקרקש גזי זבובים דאמר בבכורות (דף ז:) דבש הגזין והצירעין והוי דומיא דאביי דבלי דידבי ורבא דבלי פרוחי:"],[8,"","שורפן חסיד. דליכא למיחש שמא יתגלו ובערוך [ערך שלש] פירש ששרפת צפורן מזקת לאדם וכן כל דבר הבא מן האדם כדאמר בס\"פ כלל גדול (שבת דף עה:) גבי דם הנדה איידי דחלשא לא מצנעה לשונרא ולכך הוא חסיד שמחמיר לשורפן אע\"ג שמזיק לו:"],[15,"","אימא בודקין מטותיהן ביום. ולכן מזכירין לשבח דאע\"ג דאמרו ב\"ש צריכה ב' עדים על כל תשמיש ותשמיש ולב\"ה דיה בב' עדים כל הלילה ומעיינא בהו למחר מ\"מ מודו דאם רוצה לעיין בלילה לאור הנר הרשות בידה:"],[18,"","הא בחדתי הא בשחקי. תימה דבפ\"ק דשבועות (דף ו:) גבי שאת כצמר לבן שניה לה כקרום ביצה ומפרש כמו גלימא דכיתנא ושחקיה משמע שהחדש לבן מן הישן וי\"ל דהתם בגלימא שאין רגילות לכבס והכא בחלוק וכיוצא בו שמכבסין תדיר ועוד י\"ל דהתם לענין חשיבות מיירי כי הנך דלעיל כגון שבור מלכא וריש גלותא:"]]],[["אפילו מלא חרדל","\u0001מתני׳\u0002 משל משלו חכמים באשה החדר והפרוזדור והעלייה","דם החדר טמא דם העלייה טהור נמצא בפרוזדור ספקו טמא לפי שחזקתו מן המקור","\u0001גמ׳\u0002 רמי בר שמואל ורב יצחק בריה דרב יהודה תנו נדה בי רב הונא אשכחינהו רבה בר רב הונא דיתבי וקאמרי החדר מבפנים והפרוזדור מבחוץ ועלייה בנויה על שתיהן ולול פתוח בין עלייה לפרוזדור","נמצא מן הלול ולפנים ספקו טמא מן הלול ולחוץ ספקו טהור","אתא ואמר ליה לאבוה ספקו טמא אמרת לן מר והא אנן שחזקתו מן המקור תנן","א\"ל אנא הכי קאמינא מן הלול ולפנים ודאי טמא מן הלול ולחוץ ספקו טמא","אמר אביי מאי שנא מן הלול ולחוץ דספקו טמא דדלמא שחתה ומחדר אתא מן הלול ולפנים נמי אימא אזדקרה ומעלייה אתא","אלא אמר אביי אי בתר חששא אזלת אידי ואידי ספק הוא ואי בתר חזקה אזלת מן הלול ולפנים ודאי טמא מן הלול ולחוץ ודאי טהור","תני רבי חייא דם הנמצא בפרוזדור חייבין עליו על ביאת מקדש ושורפין עליו את התרומה ורב קטינא אמר אין חייבין עליו על ביאת מקדש ואין שורפין עליו את התרומה","להך לישנא דאמר אביי אי בתר חששא אזלת מסייע ליה לרב קטינא ופליגא דרבי חייא","להך לישנא דאמרת אי בתר חזקה אזלת מסייע ליה לרבי חייא"],[[0,"ואפילו מלא חרדל","שאין נוגע בתנור אלא גרגרין שאצל הדפנות ואפ\"ה כולו טמא מן האויר:"],[1,"מתני' החדר והפרוזדור","בגמ' מפרש היכי קיימי:"],[2,"דם החדר טמא","והיינו מקור:"],[2,"ספקו טמא","מספק טמא טומאה ודאית:"],[2,"שחזקתו כו'","במקור מחזקינן ליה ולא אמרינן מעלייה אתא ודמים דעלייה טהורין דמפרוזדור לא אתי דם אלא דמי חדר ודמי עלייה פעמים שהן נכנסין לפרוזדור:"],[3,"גמ' חדר מבפנים ופרוזדור מבחוץ","שניהם זה אצל זה בעובי גופה חדר לצד אחוריה ופרוזדור לפניה וכותלי רחם למטה באמצע פרוזדור ודרך שם דמים יוצאים:"],[3,"ולול פתוח כו'","ודמי עלייה באין לפרוזדור דרך הלול:"],[4,"נמצא","בפרוזדור מן הלול ולפנים לצד החדר:"],[4,"ספקו טמא","דאי מעלייה אתא מן הלול ולחוץ איבעי ליה לאשתכוחי דהא כי נחית מן הלול לפרוזדור כלפי חוץ הוא יורד ויוצא דרך יציאה ואינו חוזר לצד אחוריה. ולקמן פריך ודאי טמא הוי ואמאי קתני ספקו טמא:"],[5,"ספקו טמא","ולא ודאי מדקתני מן הלול ולחוץ ספקו טהור:"],[5,"והא אנן שחזקתו מן המקור תנן","מדקתני חזקתו מכלל דטומאה ודאית קאמר ובמאי מוקמת לה לא מן הלול ולפנים ולא מן הלול ולחוץ דלדידך ליכא טומאה ודאית:"],[6,"מן הלול ולפנים ודאי טמא","ומתניתין מן הלול ולפנים:"],[6,"ספקו טמא","לתלות שהרי שני דמים יוצאין דרך שם דמי החדר ודמי העלייה ולא ידעינן מהי אתא ואע\"ג דאיכא לאחזוקי בדם עלייה דאי מחדר אתא לא הוה אזיל בפרוזדור עד מן הלול ולחוץ דהוה נפיק ליה ונחית דרך יציאת פתח פרוזדור אפ\"ה מטמאינן לה מספקא דילמא שחתה ונפלה על פניה ונשתרבב הדם בכל הפרוזדור ובא מצד אחוריה לצד פניה כשיצא מן החדר:"],[7,"דספקו טמא","ולא אמרינן ודאי טהור:"],[7,"אזדקרה","נזקפה לצד אחוריה כגון פרקדנית שקורין שובינ\"א ואיכא למימר מעלייה נחית לפרוזדור והא דלא נפיק ונחית מפרוזדור דרך פתח בית הרחם וחזר לצד החדר משום זקיפה הוא וכיון דאיכא לאחזוקי הכי והכי הוי ספק ולא ודאי:"],[8,"אי בתר חששא אזלת","דלא מחזקת ליה לדם כמנהגו והילוכו אלא באת לחוש לקורות הנולדות כגון שחתה:"],[8,"אידי ואידי ספקא הוי","דכי היכי דמספקא מן הלול ולחוץ דלמא שחתה איכא לספוקי נמי מן הלול ולפנים דלמא אזדקרה:"],[8,"ואי בתר חזקה אזלת","דמחזקת ליה לדם כמנהג הילוכו ולא חיישינן לאימור שחתה ולאימור אזדקרה:"],[8,"מן הלול ולפנים ודאי טמא","דודאי מחדר אתא דאי מעלייה אתא מן הלול ולחוץ איבעי ליה לאשתכוחי ומתניתין דקתני שחזקתו מן המקור נמי מן הלול ולפנים:"],[8,"מן הלול ולחוץ ודאי טהור","ולא אמרינן אימור שחתה והוה ליה ספק לתלות אלא כמנהג מחזקינן ליה ודאי טהור:"],[9,"חייבין עליו","אם נכנסה למקדש דודאי טמאה. ולקמן מפרש אי מן הלול ולפנים אי לחוץ:"],[9,"אין חייבין","אבל איסורא איכא אלמא ספק הוא:"],[10,"להך לישנא","דאי בתר חששא אידי ואידי ספקא הוא:"],[10,"מסייע ליה לרב קטינא","דאמר ספקא הוא ומוקמינן בין מן הלול ולפנים בין מן הלול ולחוץ ופליגא דר' חייא אדאביי דהא על כרחיך לאביי להאי לישנא ליכא טומאה ודאי לא שנא לפנים לא שנא לחוץ לא שנא בגג לא שנא בקרקעית דכיון דתלי טעמא בחששא בכולהו איכא לספוקי הכי והכי:"],[11,"להך לישנא","דבתר חזקה מסייע ליה לר' חייא ומתוקמא במן הלול ולפנים:"]],[[0,"","אפילו מלא חרדל. למאי דמפרש ר\"ת דאין פחות מכביצה מקבל טומאה לאו דוקא מלא חרדל אלא מלא ביצים אלא משום דמדרבנן מקבל טומאה נקט ליה:"],[1,"","פרוזדור. פרוז בלשון יון לפני דור לשון דירה אית דגרס פרוזדור בדלי\"ת:"],[2,"","ודם העלייה. משמע דדם העלייה טהור אפי' הוא ממראה דמים טמאים דאי אין בעלייה מד' מיני דמים טמאים אם כן דם שבפרוזדור אמאי הוי ספק נחזי אי הוי מד' מיני דמים אי לאו ודוחק לומר דאיירי בנאבד והיינו טעמא דטהור דכתיב ממקור דמיה דוקא דמי מקור דהיינו חדר אי נמי דמיה כתיב מקום שמצויין שם הרבה דמים ובעלייה ליכא אלא מין אחד:"],[5,"","והתנן שחזקתו מן המקור. ואע\"ג דבמתני' קתני נמי ספקו טמא היינו ספקו ודאי טמא כדקתני בהדיא שחזקתו מן המקור והוה מצי לשנויי כגון שנמצא בקרקע פרוזדור כדמשני בסמוך אר' חייא א\"נ שמא קרקע פרוזדור לא הוה קרי ליה ספק:"],[7,"","מן הלול ולפנים נמי כו'. פירוש לדבריך שאתה חושש לשינוי אמאי ודאי טמא ניחוש נמי דלמא איזדקרה ומעלייה אתא ותימה דאדרבה כיון דמן הלול ולחוץ אע\"פ שמן העלייה הוא בא שם כדרכו חיישינן לדם החדר שהוא רחוק ואין יכול לבא אלא ע\"י שחייה משום דרוב דמים מן המקור אתו מש\"ה יש לטמא בודאי מן הלול ולפנים ולתלות בדמי החדר המרובים והקרובים יותר מדמי העלייה וע\"ק דבפרק לא יחפור (ב\"ב דף כד.) א\"ר חנינא רוב וקרוב הלך אחר הרוב ומוכח התם דרבי חנינא מיירי אפילו בקורבא דמוכח ואמר אביי אף אנן נמי תנינא כר' חנינא נמצא בפרוזדור ספקו טמא שחזקתו מן המקור ואע\"ג דאיכא עלייה דמקרבה טפי ומאי ראייה מייתי דהא ללישנא דבתר חששא אזלת [וללישנא דבתר חששא אזלינן שחזקתו מן המקור היינו אפילו מן הלול ולחוץ יש לחוש שמא מן המקור בא אלא ליתן טעם אמאי ספיקו טמא מבחוץ ולעולם אידי ואידי ספיקא הויץ גליון] לא אזלינן בתר רובא כלל טפי מקורבא אלא אידי ואידי ספקא הוי ואפילו מן הלול ולפנים שדמי החדר רוב וגם באין משם בלא שינוי חיישינן לדמי העלייה שהם מעטים ואינם יכולין לבא שם אא\"כ נזדקרה וללישנא דבתר חזקה אזלת מטהר מן הלול ולחוץ ולא חייש לרובא דדמי החדר והא דמטמא מן הלול ולפנים לאו משום רובא גרידא אלא משום דבא נמי מן החדר בלא שינוי וקורבא דעלייה לא מוכח כלל דלא חיישינן לאיזדקרה ונראה לפרש דכל אמוראי דשמעתין איירי בגג פרוזדור וכן הענין דגג פרוזדור מן הלול ולפנים גבוה ומשתפע ועולה ואינו יכול לבא שם מן העלייה אלא א\"כ נזדקרה ומן החדר אינו יכול לבא לגג פרוזדור אפילו מן הלול ולפנים אלא א\"כ שחתה ביותר והוא שינוי גדול מדיקור של עלייה כי הלול שדמי החדר יוצאים לפרוזדור הוא לצד קרקע פרוזדור אבל מן הלול ולחוץ משתפע ויורד ובא שם מן העלייה כדרכו ומן החדר בא שם בשינוי גדול יותר ממן הלול ולפנים והשתא פריך שפיר מ\"ש מן הלול ולחוץ דספק אף על גב דמן החדר אינו בא שם אלא בשינוי גדול מאד ומן העלייה בא שם כדרכו אלא משום דשחתה רגילות הוא דאי לא רגילות הוא הוי ודאי טהור ואפילו הכי לא בעי למיזל בתר רובא שיהא ודאי טמא מן הלול לפנים נמי אימור איזדקרה דכיון דשחתה רגילות הוא איזדקרה נמי רגילות ואמאי ודאי טמא ואע\"ג דרוב דמים מן המקור אין ללכת אחר הרוב כמו מן הלול ולחוץ דלא הוי טמא ודאי אף ע\"ג דשחתה הוי רגילות אלא אמר אביי אי בתר חששא אזלת משום דשחתה רגילות הוא כדפרישית אידי ואידי ספקא ואי בתר חזקה אזלת ולא בתר חששא דשחתה לאו רגילות הוא מן הלול ולחוץ ודאי טהור ומ\"מ מן הלול ולפנים אע\"ג דשחתה לאו רגילות הוא הוי ודאי טמא דממה נפשך על ידי שינוי בא או שחתה או איזדקרה ואית לן למימר דמן החדר אתא משום דחזקת דמים מן המקור באין ומוכח שפיר בלא יחפור מהא לישנא דבתר חזקה דהוי עיקר כדמשמע לישנא שחזקתו מן המקור דרוב וקרוב הלך אחר הרוב אפילו בקורבא דמוכחא דמן הלול ולפנים ודאי טמא דאזלינן אחר רוב דמים שמן המקור אע\"ג דהעלייה מקרבא ומוכח דהא מעלייה בא בשינוי מועט יותר ממן החדר כדפרישית:"],[9,"","ואין שורפין עליו את התרומה. תימה כיון דהוי ספק טומאה ברה\"ר טהור ודאי וברה\"י טמא ודאי ושורפין וי\"ל כדפירשתי לעיל (נדה דף ב.) דמסוטה לא ילפינן טומאה דאתיא ע\"י ראיית גופה לכן בכל מקום ספק וצ\"ע במכילתין (דף עא.) גבי דם תבוסה דמשמע דספק יצא מחיים ספק לאחר מיתה ברשות היחיד ספקו טמא ברשות הרבים ספקו טהור ואם תאמר וכיון דלא ילפינן מסוטה נוקי אשה בחזקתה ונטהר אפילו ברשות היחיד ויש לומר משום דדמי החדר מצויין ביותר כדאמר בלא יחפור (ב\"ב דף כד.) רוב ומצוי קאמרת ולא חשיב חזקה וקורבא לגבי רובא אלא כפלגא ופלגא:"]]],[["ופליגא דרב קטינא","לרב הונא לא פליגי כאן מן הלול ולפנים כאן מן הלול ולחוץ","אלא לרמי בר שמואל ולרב יצחק בריה דרב יהודה דאמרי מן הלול ולחוץ ספקו טהור מן הלול ולפנים ספקו טמא הני במאי מתוקמא מן הלול ולפנים","לימא פליגא דרבי חייא","לא קשיא כאן כשנמצא בקרקע פרוזדור וכאן שנמצא בגג פרוזדור","אמר רבי יוחנן בשלשה מקומות הלכו בו חכמים אחר הרוב ועשאום כודאי מקור שליא חתיכה מקור הא דאמרן","שליא דתנן שליא בבית הבית טמא ולא שהשליא ולד אלא שאין שליא בלא ולד ר\"ש אומר נמוק הולד עד שלא יצא","חתיכה דתנן המפלת יד חתוכה ורגל חתוכה אמו טמאה לידה ואין חוששין שמא מגוף אטום באת","ותו ליכא והאיכא תשע חנויות","דתניא תשע חנויות כולן מוכרות בשר שחוטה ואחת מוכרת בשר נבלה ולקח מאחת מהן ואינו יודע מאיזה מהן לקח ספקו אסור","ובנמצא הלך אחר הרוב","טומאה קאמרינן איסור לא קאמרינן","והאיכא תשע צפרדעין ושרץ אחד ביניהם ונגע באחד מהן ואינו יודע באיזה מהן נגע ברה\"י ספקו טמא ברה\"ר ספקו טהור","ובנמצא הלך אחר הרוב","טומאה דאשה קאמרינן טומאה בעלמא לא קאמרינן","והאיכא הא דאמר רבי יהושע בן לוי עברה בנהר"],[[0,"ופליגא דרב קטינא","אהך לישנא דאביי דהא להאי לישנא ליכא טומאת ספק דכיון דתלי טעמא בחזקה לא שנא גג לא שנא קרקע מן הלול ולפנים טמא ודאי מן הלול ולחוץ טהור ודאי:"],[1,"לרב הונא","דאמר ליה לבריה מן הלול ולפנים ודאי מן הלול ולחוץ ספקא:"],[1,"לא פליגי","לא דר' חייא ולא דרב קטינא עליה ואהדדי נמי לא פליגי:"],[1,"כאן מן הלול ולפנים","דר' חייא:"],[1,"כאן מן הלול ולחוץ","דרב קטינא:"],[2,"אלא לרמי בר שמואל ולרב יצחק","דאמרי מן הלול ולחוץ ספק טהור - על כרחך הני מתני' דר' חייא ודרב קטינא במאי מיתוקמי במן הלול ולפנים דהא מן הלול ולחוץ אפילו ספקא ליכא דהא טהור קאמרינן ודרב קטינא קיימא כוותייהו אלא רבי חייא דאמר טומאה ודאית לימא פליגא עלייהו דלדידהו ליכא טומאה ודאית:"],[4,"","ומשנינן לא פליגי הא דרבי חייא דאמר ודאי במן הלול ולפנים בקרקע פרוזדור דהיינו כדרך יציאתו מן החדר ודרמי ורב יצחק דאמרי ספק טמא בגג פרוזדור שקרוב לעלייה ולעולם בתר חזקה אזלי ומודו בקרקע פרוזדור במתני' וכדרבי חייא אבל בגגו במן הלול ולפנים על כרחך יצא זה ממנהג הילוכו דהבא מן החדר היה לו לימצא בקרקע פרוזדור שהחדר נמוך ושוה לפרוזדור ואם מן העלייה בא הוה לו לימצא מן הלול ולחוץ הלכך איכא למיתליה בתרי ספיקי דילמא מעלייה אתא לפרוזדור ואזדקרה או מחדר אתא לפרוזדור וע\"י שנזדקרה עלה הדם מלמטה למעלה כיון דרמי ורב יצחק לא יהבי טעמא למילתייהו איכא לאוקמי בשינוי אבל לאביי ללישנא דבתר חששא ליכא לשנויי הכי ופליג דר' חייא עליה דכיון דאביי תלי טעמא בחששא וכל היכא דאיכא למיחש להאי ולהאי משוי ליה ספק אפילו בקרקע פרוזדור איכא לספוקי בחדר ולעלייה הילכך דרבי חייא פליג עליה:"],[5,"ועשאום כודאי","משום דאזלינן בתר רובא:"],[5,"הא דאמרינן","במתניתין שחזקתו לא בא אלא מן המקור וכדתני רבי חייא אלמא כיון דרוב דמים התם שכיחי מחזקינן ליה מן המקור:"],[6,"הבית טמא","אף אם אין ולד נראה הבית טמא משום אהל המת:"],[6,"שאין שליא בלא ולד","ושורפין עליה את התרומה. אלמא כיון דרוב שליות אינן בלא ולד מחזקינן לה בטומאה ודאית:"],[6,"נימוק הולד","ונעשה דם ונתערב בדם הלידה ובטל ברוב והכי מפרש טעמא לקמן בפ' המפלת (נדה דף כז:):"],[7,"יד חתוכה","מחותכת בצורתה בחיתוך אצבעות:"],[7,"אמו טמאה לידה","ותשב חומר זכר לימי טוהר וחומר נקבה לענין טומאה דמחזקינן לה בלידה ודאית ליתן לה ימי טומאה וימי טהרה דאמרינן הלך אחר הרוב ורוב נשים ולד מעליא ילדן אלא שנימוק:"],[7,"ואין חוששין","לומר לא יהיו לה ימי טוהר שמא אינו ולד דדילמא מגוף אטום הוא בא וקיימא לן בהמפלת (לקמן נדה דף כד.) דאינו ולד והיינו כודאי מדיהבינן לה ימי טוהר הואיל ורוב נשים לאו גוף אטום ילדן:"],[9,"ספקו אסור","דכל קבוע כמחצה על מחצה דמיא וכיון שלקחה ממקום הקביעות מחזקינן לה כמחצה על מחצה:"],[10,"ובנמצא","בקרקע דה\"ל מופרש מהן ולא לקחו ממקום הקביעות:"],[10,"הלך אחר הרוב","ומותר דכל דפריש מרובא פריש:"],[12,"ברשות היחיד כו'","דהוה ליה ספק ואע\"ג דרובא צפרדעים ואין להם טומאה כיון דשרץ קבוע ביניהם הוה ליה מחצה על מחצה:"],[13,"ובנמצא","שפירש אחד מהן למקום אחר ונגע בו אדם שם טהור דהשתא לאו קבוע הוי ואמרינן כל דפריש מרובא פריש וצפרדע הוא:"]],[[4,"","כאן שנמצא בקרקע פרוזדור. פ\"ה דלעיל אלישנא דבתר חששא אזלינן דקאמר דפליגא דר' חייא לא מצי לשנויי הכי דכיון דתלי אביי טעמא בחששא איכא למיחש אפילו בקרקע פרוזדור לדם עלייה וקשה לפירושו דנמצא על שלה או על שלו אמאי חייבין בקרבן מי עדיף מנמצא מן הלול ולפנים דלא הויא אלא ספק אפי' בקרקע פרוזדור ונראה לפרש דלאביי ליכא לאוקמי דר' חייא בקרקע פרוזדור דכיון דאפי' מן הלול ולחוץ דבא מן העלייה כדרכו וקרוב חייש לדם המקור אם כן מן הלול ולפנים בקרקע פרוזדור מילתא דפשיטא היא דמן החדר אתא ולא הוה צריך רבי חייא לאשמועינן:"],[6,"","שליא בבית כו'. פ\"ה דרוב שליות יש להם ולד וקשה דתנן בפ' בהמה המקשה (חולין דף עז.) שליא שיצתה מקצתה אסורה באכילה ואי יש שליא בלא ולד הוה לן למשרי משום דסמוך מיעוטא דאין בה ולד לפלגא שלא יצא רוב הולד וה\"ל מחצה שיש בה רוב ולד מיעוטא דסתם שליא שיצתה מקצתה ויש בה ולד מחצה יש בהן רוב ולד ומחצה אין בהן רוב ולד כדמוכח בפ\"ק דב\"ק (דף יא.) וכה\"ג אמר התם סמוך מיעוטא דנדמה למחצה דנקבות וכן בפ\"ק דבכורות (דף כ:) סמוך מיעוטא דמפילות למחצה דנקבות ויש לישב פ\"ה דהתם מיירי בשליא שיצתה מקצתה ונמצא ולד תוך השליא ונראה לפרש דאין שליא כלל בלא ולד אך מיעוטא נימוק ורובן אין נימוקים עד שיצא לבית החיצון כדאמר בפ' המפלת (לקמן נדה כז.) וא\"ת ואמאי לא מייתי הכא מרישא דתנן בהמפלת (שם דף כד:) המפלת סנדל או שליא תשב לזכר ולנקבה אלמא דרובן אין נימוקין קודם יציאה וי\"ל דאפי' נמוקין מצינן למימר דטמאה לידה דקאמר קרא אשה כי תזריע אפי' לא ילדה אלא כעין שהזריעה אמו טמאה לידה ואע\"ג דההיא דרשא כרבי שמעון בריש יוצא דופן (לקמן נדה דף מ.) ורבנן דרשו לה עד שתלד ממקום שמזריע י\"ל דתרתי ש\"מ א\"נ י\"ל מרישא לא מייתי דהו\"א דטעמא דרבנן משום שאין שום שליא בלא ולד ואין שום ולד נימוק אפילו מיעוט לכך מייתי סיפא דאמר ר' שמעון נימוק הולד אע\"פ שלא יצא וכיון דסבר רבי שמעון דרובן נימוקין ולרבנן אינם נימוקין אלא מיעוטן דאין סברא לומר דלר\"ש רובן נימוקין ולרבנן אפילו מיעוטן אין נימוקין וקצת נראה דאדרבה ארישא סמיך וסיפא לא מייתי אלא משום דמינה מוכיח דטעמא דרבנן משום רובא כדפרישית דאי משליא בבית גופה מייתי מאי איריא משום רוב אפי' מחצה על מחצה שורפין דהוה ליה ספק טומאה ברה\"י דטמא:"],[7,"","המפלת יד חתוכה. הא דלא מייתי מתני' דהמפלת (לקמן נדה דף כח.) המפלת ואין ידוע מהו ובהמפלת חתיכה מיירי כדמוכח התם בגמרא (דשליא בבית) משום דהכא מפרש בהדיא אין חוששין שמא מגוף אטום באה דמשמע דהוי מטעם דהולכים בתר רובא:"],[8,"","ותו ליכא. וא\"ת והא איכא הא דתנן לקמן בפ' האשה (נדה דף נט:) איש ואשה שעשו צרכיהם בספל ונמצא בו דם רבי שמעון מטמא שחזקת דמים מן האשה ואי משום דרבי שמעון קתני לה הא קאמר שליא אע\"ג דרבי מאיר קתני לה כדאמר בהמפלת (לקמן נדה דף כז.) וכ\"ת דאין שורפין על אותו רוב תרומה א\"כ לקמן דדחיק לאשכוחי למעוטי מאי לימא למעוטי רובא דר' שמעון וי\"ל דהתם מסייע חזקת האדם לרוב וא\"ת וליחשוב נמי הא דתנן בהרואה (לקמן נדה דף נז:) נמצאת אתה אומר שלש ספקות באשה ובמגעות ובהסיטות הלך אחר רוב ואי אין שורפין עליו תרומה לימא למעוטי הא ויש לומר דשורפין והוי טעמא משום דרוב דמים באין מן המקור דחשיב בג' דברים:"],[9,"","ספקו אסור. בשילהי פ\"ק דכתובות (דף טו.) נפקא לן קבוע מוארב לו וא\"ת לר\"ש דדריש מוארב לו עד שיתכוין לו קבוע מנא ליה וי\"ל דמסקינן בפ' הנשרפין (סנהדרין דף עט.) דסבר רבי שמעון כרבי דונתת נפש תחת נפש ממון א\"כ מהתם שמעינן עד שיתכוין לו ואייתר וארב לו לקבוע אך לתנא דבי חזקיה דדריש מכה אדם ומכה בהמה דשאינו מתכוין פטור ממיתה וממון ולא דריש ונתת נפש תחת נפש לממון וע\"כ עד שיתכוין לו נפקא ליה מוארב לו קשה קבוע מנא ליה:"],[10,"","הלך אחר הרוב. משמע אפי' נמצא קרוב לחנות המוכרת נבלה וא\"ת א\"כ מאי קמ\"ל ר' חנינא דרוב וקרוב הלך אחר הרוב וי\"ל דקמ\"ל אפי' בקורבה דמוכחא מיהו קשה מקושיא דרבי זירא דהתם תקשי ליה מתני' דט' חנויות:"],[10,"","אחר הרוב. הכא איכא חזקה כנגד הרוב דבהמה בחזקת איסור עומדת וגבי ט' צפרדעים נמי קאמר הלך אחר הרוב ואם רוב שרצים טמאים אע\"ג דאיכא חזקת טהרה דאי לא הוי חזקה כנגד הרוב לא הוה פריך מידי דמצינן למימר דרבי יוחנן לא חשיב אלא היכא דאיכא חזקה כנגד הרוב:"]]],[["והפילה מביאה קרבן ונאכל","הלך אחר רוב נשים ורוב נשים ולד מעליא ילדן","מתניתין קאמרינן שמעתתא לא קאמרינן","והא כי אתא רבין אמר מתיב רבי יוסי בר רבי חנינא טועה ולא ידענא מאי תיובתיה","מאי לאו לא תיובתא אלא סייעתא","לא דלמא לא תיובתא ולא סייעתא","למעוטי מאי","אילימא למעוטי רובא דאיכא חזקה בהדיה דלא שרפינן עליה את התרומה והא אמרה ר' יוחנן חדא זימנא","דתנן תינוק הנמצא בצד העיסה ובצק בידו רבי מאיר מטהר וחכמים מטמאין שדרכו של תינוק לטפח","ואמרינן מאי טעמא דר\"מ קסבר רוב תינוקות מטפחין ומיעוט אין מטפחין ועיסה זו בחזקת טהורה עומדת סמוך מיעוטא לחזקה ואיתרע ליה רובא","ורבנן מיעוטא כמאן דליתיה דמי ורובא וחזקה רובא עדיף","ואמר ריש לקיש משום רבי אושעיא זו היא חזקה ששורפין עליה את התרומה ורבי יוחנן אמר אין זו חזקה ששורפין עליה את התרומה","אלא למעוטי רובא דרבי יהודה דתנן המפלת חתיכה אם יש עמה דם טמאה ואם לאו טהורה רבי יהודה אומר בין כך ובין כך טמאה","ואמר רב יהודה אמר שמואל לא טימא רבי יהודה אלא בחתיכה של ארבע מיני דמים אבל שאר מיני דמים טהורה ורבי יוחנן אמר של ארבע מיני דמים דברי הכל טמאה ושל שאר דמים דברי הכל טהורה לא נחלקו אלא כשהפילה"],[[0,"והפילה","ואין ידוע אם ולד הוא:"],[0,"ונאכל","חטאת העוף שלה נאכלת ולא אמרינן על הספק באה ואינה נאכלת דדלמא לאו ולד הוא וחולין מלוקין הן ומליקת חולין נבלה:"],[2,"שמעתתא","ר' יהושע בן לוי אמורא הוא ושלשה מקומות דאמר ר' יוחנן משנה או ברייתא הן:"],[3,"והא כי אתא רבין אמר","בפ' המפלת (לקמן נדה דף כט.):"],[3,"מתיב רבי יוסי ברבי חנינא","אדרבי יהושע בן לוי מתני' חדא דמיירי באשה טועה שלא ידעה אימתי ילדה והתם קתני לה וקאמר רבין לא ידענא מאי תיובתא דרבי יוסי דלאו תיובתא היא והתם מפרש טעמא:"],[4,"מאי לאו","ה\"ק רבין דהא מתני' לאו תיובתא היא דרבי יהושע אלא סייעתא אלמא מתני' אמרה כרבי יהושע ואשכחן ארבעה מקומות בטומאת נשים במתני' שהלכו אחר הרוב וקשיא לר' יוחנן דלא קחשיב אלא תלת:"],[6,"למעוטי מאי","ג' מקומות דקאמר רבי יוחנן דמשמע הני ותו לא למעוטי מאי דמשום רובא לא נשוויה כודאי:"],[7,"אילימא למעוטי רובא","בטומאת אשה:"],[7,"דאיכא חזקה בהדיה","כלומר כנגדה דמרעא לה חזקה לרובא וקאתי מניינא למעוטי דלא אזלינן בתר ההוא רובא לשוויה מילתא כודאי ולא שורפין תרומה עלה דההיא טומאה:"],[7,"הא אמרה רבי יוחנן חדא זימנא","בשאר טומאות דהיכא דסתרה חזקה לרובא דלא אזלינן בתר רובא לשוייה כודאי וממילא שמעינן לטומאת אשה:"],[8,"לטפח","בשרצים:"],[9,"סמוך מיעוטא לחזקה","והוה להו לטהר תרי ורובא לחודיה לטמא ואין א' עומד במקום שנים:"],[11,"זו היא חזקה כו'","חזקה זו שאנו מחזיקין סתם רוב תינוקות מטפחין חזקה גמורה החזיקוה לעשותה כודאי ולשרוף עליה תרומה:"],[12,"אלא למעוטי רובא דרבי יהודה","דאע\"ג דאמר זיל בתר רובא הכי גמר לה ר' יוחנן דטמא דקאמר רבי יהודה לתלות קאמר ולא לשרוף:"],[12,"חתיכה","בלא צורה:"],[12,"אם יש עמה דם טמאה","האשה טמאה כשאר נדה ולא משום לידה דלאו ולד הוא:"],[13,"של ארבע כו'","שהחתיכה מארבע מראות דם טמא השנויין במתני' ואע\"ג דחמשה תנן שחור אדום הוא אלא שלקה דכיון דמראה דם טמא יש בה אמרינן כולו דם הוא וטמאה נדה ורבנן סברי אין זה דם אלא בשר:"],[13,"של שאר מיני דמים","כגון ירוק ולבן שטהורין הן:"]],[[4,"","אלא סייעתא. דקתני התם כשהביאה ג' שבועות טהורים ועשרה שבועות אחד טמא ואחד טהור וקאמר דלא משמשת עד אור ל\"ה ואי ליתא לדרבי יהושע אמאי והא ספק ספיקא הוא אימר רוח הפילה ואת\"ל נפל הפילה אימא הרחיקה לידתה ואע\"ג דבלאו הכי איכא כמה ספקות אימא זכר ואת\"ל נקבה אימא לא ילדה בזוב ואפילו יולדת נקבה בזוב אימא הרחיקה לידתה מ\"מ אי ליתא לדרבי יהושע איכא ספק אחר יותר דאימא לא ילדה כלל והוה לן למישרי ומשני לא דלמא לא תיובתא ולא סייעתא דבלאו הכי איכא ספיקי טובא ואסרינן ה\"ה אי ליתא דר' יהושע נמי אסרינן:"],[7,"","למעוטי רובא דאיכא חזקה בהדיה. פירוש כנגד הרוב ואם תאמר הלא גם בהני שלשה דברים איכא חזקה דטהרה ושורפין משום רוב ויש לומר דרוב תינוקות מטפחין אינו רוב גמור כמו שאפרש ובהני ג' דברים הוי רוב גמור אי נמי בהני שלשה נמי לא הוי רוב גמור ואשמועינן רבי יוחנן דאפילו הכי שורפין כיון דהריעותא באה מגופה ושליא נמי קרי לה טומאת אשה משום שע\"י אשה טומאה באה לבית ולפי זה אפי' אשכחנא גבי אשה שום מתני' דשורפין על הרוב את התרומה הא דלא חשיב לה רבי יוחנן משום דהתם שמא הוא רוב חשוב ולא הוי שום חדוש ומיהו לפירוש זה לא מייתי לעיל אלא מסיפא משליא בבית דאיכא למימר דרוב דאינם נימוקין אינו רוב גמור דברישא דמפלת שליא תשב לזכר ולנקבה על כרחך הוי רוב חשוב מדלא קתני נמי ולנדה כדדייק בהמפלת (לקמן נדה דף כח.) ואם רוב אינן נימוקין אינו רוב גמור הא דקתני לעיל מביאה קרבן ונאכל אינו מטעם רוב אלא אפי' נימוק הויא טמאה לידה:"],[7,"","האמר ר' יוחנן חדא זימנא. תימה אפי' לא אמר היכי מצינן למעוטי הא טומאת אשה דוקא קאמר ומיהו לר\"ת דמפרש דהא דתינוק טמא משום דנשים נדות מגפפות אותו ניחא קצת דגם תינוק הוי טומאת אשה:"],[9,"","רוב תינוקות מטפחין. פ\"ה מטפחין באשפה שיש בה שרצים אבל ודאי נגע בעיסה שהרי בצק בידו ור\"ת מפרש רוב תינוקות מטפחין בעיסה דטיפוח שייך באוכל ומשקה כדאמר בפ' רבי ישמעאל (ע\"ז דף ס:) או שהיה מטפח על פי החבית מרותחת ובירושלמי איכא מפני שדרכו של תינוק לטפח בעיסה ובתוספתא (פ\"ג דטהרות) נמי משמע שאין ידוע אם התינוק נגע בעיסה דקתני אההיא דתינוק א\"ר יוסי אם יכול לפשוט ידו וליקח טמא ואם לאו טהור אבל התינוק אומר ר\"ת דודאי טמא כדקתני בתוספתא (שם) לפי שנשים נדות מגפפות ומנשקות אותו והא דאמר בפ\"ג דטהרות (מ\"ז) תינוק בצד הקברות ושושנים בידו אע\"פ שאין השושנים אלא ממקום טומאה התינוק טהור שאני אומר אדם טהור כו' היינו טהור מטומאת מת שאינו צריך הזאה ג' וז' אבל טומאת ערב טמא כדין נוגע בנדה א\"נ בידוע שהוא בודאי טהור א\"נ כשהתינוק מלוכלך כדקתני בתוספתא (שם) תינוק שהניחתו אמו ומצאתו כמו שהוא טהור בד\"א שהניחתו מלוכלך אבל הניחתו נקי טמא מפני שנשים נדות מגפפות אותו:"],[9,"","סמוך מיעוטא לחזקה ואיתרע ליה רובא. קשה דבפ' בתרא דיבמות (דף קיט:) אמר סמוך מיעוטא לחזקה והוה ליה פלגא ופלגא ויש לומר דלהכי איתרע הכא רובא משום דתינוק הוי דבר שאין בו דעת לישאל [כמו בפ' י' יוחסין ולא גמרינן מסוטה אלא ביש בו דעת לישאל] ולהכי כי הוי פלגא ופלגא טהור מדרב גידל וא\"ש מהאי טעמא הא דאמר ספק נגע ברה\"י טמא ולא אמר סמוך פלגא דלא נגע לחזקת טהרה ואיתרע לה פלגא דנגע דאפילו רבנן דלית להו סמוך מיעוטא לחזקה מודו דסמכינן פלגא לחזקה אלא כיון שיש בו דעת לישאל גזרת הכתוב הוא דגמרינן מסוטה לטמא ברה\"י אפי' איכא חזקת טהרה אבל בשאין בו דעת לישאל אזלינן בתר רובא ובפלגא ופלגא טהור מדרב גידל:"],[10,"","מיעוטא כמאן דליתא דמי. אע\"ג דאמרינן בפ' י' יוחסין (קדושין פ:) דעשו התינוק כמי שיש בו דעת לישאל איצטריך הכא למימר לרבנן מיעוטא כמאן דליתיה דמי לטמא אף ברה\"ר אך קשה כיון דמיעוטא כמאן דליתיה דמי ורובא וחזקה רובא עדיף אמאי עשאוהו כמי שיש בו דעת לישאל אפילו אין בו דעת לישאל טמא ברה\"ר ועוד דאמאי אין שורפין עליו את התרומה ואומר ר\"ת דרוב תינוקות אינו רוב גמור ולא הוי כנגד חזקה אלא כפלגא ופלגא ומן התורה טהור אף ברה\"י כיון דאין בו דעת לישאל והא דקאמר התם עשאוהו כאילו יש בו דעת לישאל היינו כלומר עשאוהו כאילו הוא רוב גמור לפי שנראה לעולם שהוא רוב אע\"פ שאינו רוב גמור ולכך אין שורפין עליו את התרומה אבל ליכא למימר כיש בו דעת לישאל ממש דאמאי עשאוהו טפי הכא מבחולדה המהלכת ע\"ג ככרות דטהור ואפי' אם תמצי לומר דגזרו אטו תינוק גדול שיש בו דעת לישאל אכתי מ\"מ ברה\"ר אמאי טמא אלא נראה דעשאוהו כאילו הוא רוב גמור כדפרישית ולר\"מ טהור ואע\"פ שעשאוהו כרוב גמור משום סמוך מיעוטא לחזקה ואיתרע ליה רובא וא\"ת לר\"מ ל\"ל סמוך מיעוטא לחזקה אפי' בלא חזקה יטהר כיון דחייש למיעוטא הוי ספק ואין בו דעת לישאל טהור מדרב גידל ואומר ר\"י דנקט חזקה בהדי מיעוטא לאשמועינן דהחזקה אינה מסייעה לרוב דאי הוה חזקה מסייעה לרוב הוי כמו מיעוטא דמיעוטא דלא חייש ר\"מ [והא דר\"מ דחייש למיעוטא אי הוה דאורייתא או דרבנן אין להאריך כאן]:"],[12,"","למעוטי רוב דרבי יהודה. הוי מצי למיפרך הניחא ללישנא דמפרש רבי יוחנן טעמא דרבי יהודה משום דרוב חתיכות של ד' מיני דמים הן אלא ללישנא אחרינא דהמפלת (לקמן נדה דף כא:) דאמר רבי יוחנן טעמא דרבי יהודה דאי אפשר לפתיחת הקבר בלא דם ולא משום רוב למעוטי מאי דכעין זה פריך לקמן (נדה כב:) בגמ' דהמפלת מין דגים דליכא למימר דה\"ק רוב פתיחת הקבר אינו בלא דם ולא שורפין עליה תרומה דהא קאמר התם לרבי יהושע דאמר אי אפשר לפתיחת קבר בלא דם דמביאה קרבן ונאכל אם כן טמא ודאי הוא ושורפין עליו את התרומה:"]]],[["ואינה יודעת מה הפילה רבי יהודה סבר זיל בתר רוב חתיכות ורוב חתיכות של ארבע מיני דמים הויין ורבנן סברי זיל בתר רוב חתיכות לא אמרינן","\u0001מתני׳\u0002 חמשה דמים טמאים באשה האדום והשחור וכקרן כרכום וכמימי אדמה וכמזוג בש\"א אף כמימי תלתן וכמימי בשר צלי וב\"ה מטהרים הירוק עקביא בן מהללאל מטמא וחכמים מטהרין","אמר רבי מאיר אם אינו מטמא משום כתם מטמא משום משקה רבי יוסי אומר לא כך ולא כך","איזהו אדום כדם המכה שחור כחרת עמוק מכן טמא דיהה מכן טהור וכקרן כרכום כברור שבו","וכמימי אדמה מבקעת בית כרם ומיצף מים וכמזוג שני חלקים מים ואחד יין מן היין השרוני","\u0001גמ׳\u0002 מנלן דאיכא דם טהור באשה דלמא כל דם דאתי מינה טמא","אמר רבי חמא בר יוסף אמר רבי אושעיא אמר קרא (דברים יז, ח) כי יפלא ממך דבר למשפט בין דם לדם בין דם טהור לדם טמא","אלא מעתה בין נגע לנגע הכי נמי בין נגע טמא לנגע טהור וכי תימא ה\"נ נגע טהור מי איכא וכי תימא (ויקרא יג, יג) כולו הפך לבן טהור הוא ההוא בוהק מקרי","אלא בין נגעי אדם לנגעי בתים ולנגעי בגדים וכולן טמאין הכא נמי בין דם נדה לדם זיבה וכולן טמאין","האי מאי בשלמא התם איכא לאפלוגי בנגעי אדם ובפלוגתא דרבי יהושע ורבנן","דתנן אם בהרת קודם לשער לבן טמא ואם שער לבן קודם לבהרת טהור ספק טמא ורבי יהושע אומר כהה ואמר רבה כהה וטהור","בנגעי בתים כי הא פלוגתא דרבי אלעזר ברבי שמעון ורבנן דתנן ר\"א בר\"ש אומר לעולם אין הבית טמא עד שיראה כשני גריסין על שני אבנים בשני כותלים בקרן זוית ארכו כשני גריסין ורחבו כגריס","מ\"ט דר\"א בר\"ש כתיב (ויקרא יד) קיר וכתיב קירות איזהו קיר שהוא כשני קירות הוי אומר זה קרן זוית","בנגעי בגדים בפלוגתא דר' יונתן בן אבטולמוס ורבנן דתניא ר' יונתן בן אבטולמוס אומר מנין לפריחת בגדים שהיא טהורה","נאמר (ויקרא י״ג:ל״ט) קרחת וגבחת בבגדים ונאמר קרחת וגבחת באדם","מה להלן פרח בכולו טהור אף כאן נמי פרח בכולו טהור","אלא הכא אי דם טהור ליכא במאי פליגי","וממאי דהני טהורין והני טמאין אמר רבי אבהו דאמר קרא (מלכים ב ג:כב) ויראו מואב את המים אדומים כדם למימרא דדם אדום הוא אימא אדום ותו לא","א\"ר אבהו אמר קרא (ויקרא יב, ז) דמיה (ויקרא כ, יח) דמיה הרי כאן ארבעה","והא אנן חמשה תנן אמר רבי חנינא שחור אדום הוא אלא שלקה","תניא נמי הכי שחור כחרת עמוק מכן טמא דיהה אפי' ככחול טהור ושחור זה לא מתחלתו הוא משחיר אלא כשנעקר הוא משחיר משל לדם מכה לכשנעקר הוא משחיר","בש\"א אף כמימי תלתן ולית להו לב\"ש דמיה דמיה הרי כאן ארבעה","אב\"א לית להו ואב\"א אית להו מי לא א\"ר חנינא שחור אדום הוא אלא שלקה ה\"נ מלקא הוא דלקי","וב\"ה מטהרין היינו תנא קמא","איכא בינייהו"],[[0,"ואינה יודעת מה הפילה","שאבדה החתיכה קודם שבאה לפנינו:"],[0,"לא אמרינן זיל בתר רוב חתיכות כו'","דלא סבירא להו רוב חתיכות של ד' מיני דמים ואשמועינן רבי יוחנן לעיל בג' מקומות הלכו אחר הרוב ותו לא למעוטי הא רובא דר' יהודה דלר' יהודה דאזיל בתר רובא לא כודאי משוית ליה לשרוף על מגעה את התרומה:"],[1,"מתני' וכקרן כרכום","כזוית גן שכרכום גדל בו:"],[1,"וכמימי אדמה","לקמן מפרש לה לכולהו במתניתין. ל\"א כקרן כרכום כנוגה זיו כרכום כמו (שמות ל״ד:כ״ט) כי קרן עור פניו:"],[1,"וכמזוג","כיין אדום המזוג במים ואע\"ג דקליש אדמימות דיליה טמא:"],[1,"תלתן","פנגרי\"ג:"],[1,"וכמימי בשר צלי","מוהל היוצא ממנו:"],[2,"אם אינו מטמא משום כתם כו'","מפרש בגמרא:"],[3,"כדם המכה","מפרש בגמ':"],[3,"כחרת","איידרמינ\"ט:"],[3,"עמוק מכן","שעמוק במראה שחרורית כלומר שחור יותר מחרת טמא:"],[3,"דיהה","פלד\"ש שנדחית מראיתו:"],[3,"כברור שבו","שיש עליו ברורין במראה אדמומית יותר מחבריהן. ובגמרא מפרש להו:"],[4,"בית כרם","מקום ומשם מביא אדמה ונותנה בכלי:"],[4,"ומציף עליה מים","כלומר נותן שם מים עד שיהו המים צפין על האדמה:"],[4,"וכמזוג","כיצד כגון שני חלקים מים כו':"],[7,"","\u0003גמ' אלא מעתה כו'\u0004 עד \u0003וכולן טמאין\u0004 לשון קושיא הוא:"],[7,"בוהק","לשון לובן שנראה באנשים בחורים טפות לבנות מאד בפניהם:"],[9,"בשלמא התם","גבי נגעים אע\"ג דכולהו לטמא איכא לאוקומי קרא דאיירי בפלוגתא דזקן ממרא וסנהדרין שבדורו דכתיב (דברים י״ז:י״ב) והאיש אשר יעשה בזדון כגון דמפלגי בנגעי אדם ובפלוגתא דרבי יהושע כו' דקאמר זקן ממרא כחד מינייהו וסנהדרין כחד מינייהו:"],[10,"אם בהרת קודמת לשער לבן טמא","דשער לבן מסימני טומאה וכגון שקדמתו בהרת דכתיב (ויקרא י״ג:כ״ה) והנה נהפך שער לבן בבהרת:"],[10,"כהה טהור","הרי הוא כנגע שכהה מראיתו בשבוע של הסגר שהוא סימן טהרה דכתיב (שם) והנה כהה הנגע וגו'. ובשם רבי משה הדרשן שמעתי קיהה כלומר קיהה בדבר ונחלק עליו וכן מצאתי בת\"כ ר' יהושע קיהה וטיהר:"],[11,"","שיעור נגע כגריס לאורך ולרוחב:"],[11,"כשני גריסין על שני אבנים שבקרן זוית","אחד בכותל זה ואחד בכותל זה:"],[11,"ארכו כשני גריסין ורחבו כגריס","דכשהוא מוטל ארכו על ב' אבנים נמצא בכל אבן גריס על גריס כשיעור נגע ושתי אבנים בעינן דכתיב (שם יד) וחלצו את האבנים:"],[12,"כתיב קיר","ומראיהן שפל מן הקיר (שם):"],[13,"פריחה","פרחה צרעת בכולהו:"],[13,"שהיא טהורה","ואע\"פ שלא נאמר אלא באדם (שם יג) ואם פרוח תפרח וגו':"],[17,"למימרא דדם אדום הוא","ואלו כולם אדומין הן:"],[17,"ואימא אדום ותו לא","האדום שבאדומים דהיינו כדם המכה דמתניתין:"],[18,"דמיה דמיה","והיא גלתה את מקור דמיה (שם כ) וטהרה ממקור דמיה (שם יב) הרי ד' מיני אדמומית טמאה בה אבל שלמטה מהן לאו דם הוא:"],[20,"דיהה מכן אפילו","הוא שחור ככחול טהור הואיל ואינו שחור כחרת:"],[20,"לכשנעקר","מן הגוף לוקה ומשחיר:"]],[[10,"","רבי יהושע אומר כיהה. הקשה ר\"ת דמאי טעמייהו דרבנן דמטמאי מספיקא נוקי גברא אחזקיה כדקי\"ל בפ\"ק דחולין (דף י:) דמדאורייתא אזלינן בתר חזקה ורבי יהושע נמי אמאי צריך קרא ובפרק המדיר (כתובות דף עה:) נמי דקאמר לא תימא דלא אזיל רבי יהושע בתר חזקה דגופה כלל פירוש דקאמר התם גבי משארסתני נאנסתי לא מפיה אנו חיין אלא הני מילי היכא דאיכא חזקה דממונא אבל היכא דליכא חזקה דממונא אזיל דתנן אם בהרת כו' והשתא מה צריך ראיה על זה דאזיל בתר חזקה ועוד דשאני גבי נגעים דגלי קרא וי\"ל דדרך השער להתלבן מחמת הנגע לפיכך נראין הדברים דבהרת קדמה וכן מוכח בתוספתא בפרק יש נוחלין בשער לבן דקתני אמר להן אף שער שחור סוף שבהרתו הפכתו אלמא דדרך השער ללקות מן הבהרת ובהמדיר (שם) דקאמר היכא דליכא חזקה דממונא אזיל רבי יהושע בתר חזקה דגופה היינו אפילו דאיכא ריעותא דאי לא אזיל לא הוה מוקי קרא דלטהרו אספק בהרת קדמה דשכיח הרבה ואיכא ריעותא טפי אלא הוה מוקי לה לדרשה אחריתי כרבנן אי נמי מהתם יליף דאזיל בתר חזקת הגוף אע\"ג דאיכא ריעותא ור\"ת מפרש בע\"א ואין להאריך כאן:"],[10,"","אמר רבה כיהה וטהור. נראה דרבה גרס דבפרק הפועלים (ב\"מ דף פו.) אמר מאן מוכח רבה בר נחמני ואמר טהור פ\"ה כיהה שיש לו דין כיהה וקשה דבשלהי נזיר (דף סה:) פריך ודלמא כיהה וטמא והיכי מצי למימר הכי והא כיהה משמע טהור ועוד דא\"כ ר' יהושע לא פליג את\"ק ובדוחק י\"ל דאדרבי יהושע פריך ומנליה דטהור (ורבינו תם) גריס ור' יהושע קיהה פירוש עמד למנין דקיהה לשון אסיפה כמו (יבמות דף קי:) מקהו אקהייתא בשוקא והשתא פריך התם אימא עמד למנין והביא ראיה לדברי ת\"ק מיהו דוחק הוא דא\"כ מאי משני אמר קרא לטהרו היכי מוכח מהאי קרא שטיהר דלמא כי היכי דדרשי ליה רבנן דריש נמי רבי יהושע:"],[15,"","מה להלן פרחה בכולו טהור. מדמדמה פריחה דאדם לפריחת בגדים הא דכתיב (ויקרא י״ג:י״ב) וכסתה הצרעת את כל עור הנגע מראשו ועד רגליו אגופו של אדם קאי אע\"ג דפשטיה דקרא משמע דאנגע קאי דאיירי לעיל בנגע שנטמא על ידי שיש בו מחיית בשר חי ועליה קאי וכסתה הצרעת את כל עור הנגע מראשו של נגע עד רגליו כלומר עד סופו אבל הכא משמע דקאי אאדם דומיא דבגד וכן מוכח בכמה מקומות בת\"כ ובריש איזהו מקומן (זבחים מט:):"]]],[["לתלות","הירוק עקביא בן מהללאל מטמא ולית ליה לעקביא דמיה דמיה הרי כאן ארבעה","אב\"א לית ליה ואב\"א אית ליה מי לא א\"ר חנינא שחור אדום הוא אלא שלקה הכא נמי מלקא הוא דלקי","וחכמים מטהרין היינו ת\"ק איכא בינייהו לתלות","א\"ר מאיר אם אינו מטמא משום כתם כו'","א\"ר יוחנן ירד ר\"מ לשיטת עקביא בן מהללאל וטימא וה\"ק להו לרבנן נהי דהיכא דקא משכחת כתם ירוק אמנא לא מטמאיתו היכא דקחזיא דם ירוק מגופה תטמא","אי הכי אם אינו מטמא משום כתם מטמא משום משקה משום רואה מבעיא ליה","אלא ה\"ק להו נהי היכא דקא חזיא דם ירוק מעיקרא לא מטמאיתו היכא דחזיא דם אדום והדר חזיא דם ירוק תטמא מידי דהוה אמשקה זב וזבה","ורבנן דומיא דרוק מה רוק שמתעגל ויוצא אף כל שמתעגל ויוצא לאפוקי האי דאין מתעגל ויוצא אי הכי שפיר קאמרי ליה רבנן לר' מאיר","אלא ה\"ק להו להוי כמשקה להכשיר את הזרעים ורבנן בעי (במדבר כג:כד) דם חללים וליכא אי הכי שפיר קאמרי ליה רבנן לר' מאיר","אלא הכי קאמר להו אלפוה בג\"ש כתיב הכא (שיר השירים ד׳:י״ג) שלחיך פרדס רמונים וכתיב התם (איוב ה, י) ושולח מים על פני חוצות","ורבנן אדם דן ק\"ו מעצמו ואין אדם דן ג\"ש מעצמו","רבי יוסי אומר לא כך וכו' היינו ת\"ק הא קמ\"ל מאן ת\"ק רבי יוסי וכל האומר דבר בשם אומרו מביא גאולה לעולם","איזהו אדום כדם המכה מאי כדם המכה אמר רב יהודה אמר שמואל כדם שור שחוט","ולימא כדם שחיטה אי אמר כדם שחיטה הוה אמינא ככולה שחיטה קמ\"ל כדם המכה כתחילת הכאה של סכין","עולא אמר כדם צפור חיה איבעיא להו חיה לאפוקי שחוט או דלמא לאפוקי כחוש תיקו","זעירי אמר רבי חנינא כדם מאכולת של ראש מיתיבי הרגה מאכולת הרי זה תולה בה מאי לאו דכוליה גופה לא דראשה","אמי ורדינאה א\"ר אבהו כדם אצבע קטנה של יד שנגפה וחייתה וחזרה ונגפה ולא של כל אדם אלא של בחור שלא נשא אשה ועד כמה עד בן עשרים","מיתיבי תולה בבנה ובבעלה בשלמא בבנה משכחת לה אלא בעלה היכי משכחת לה","אמר ר\"נ בר יצחק כגון שנכנסה לחופה ולא נבעלה","ר\"נ אמר כדם הקזה מיתיבי מעשה ותלה ר\"מ"],[[0,"לתלות","ת\"ק סבר ה' דמים טמאין ודאי ואידך ספיקא ולב\"ה טהורין ממש:"],[3,"היינו ת\"ק","דאמר ה' דמים ותו לא:"],[5,"ירד ר' מאיר כו'","ומטמא דם ירוק משום נדה:"],[5,"אמנא","על בגדה:"],[5,"לא מטמאיתו","דכיון דירוק הוא מסתמא לאו מגופה אתא דלא שכיח ולא תלינן בה אלא היכא דחזיא מגופה דם הוא:"],[5,"נהי דהיכא דחזיתיה דם ירוק מעיקרא לא מטמאיתו","משום רואה דלאו דם הוא והיינו משום כתם כלומר כשאר דם שכתמו טמא:"],[6,"תטמא משום משקה","כרוקה וכמי רגליה אם נוגעין בו אדם וכלים וטהרות באותו דם ירוק שראתה בימי נדותה שהיתה נדה מדם אדום ואמאי מטהריתו לגמרי:"],[8,"שמתעגל ויוצא","שמתאסף תחלה ואח\"כ יוצא לאפוקי דם בין טמא בין טהור כשהוא בא נוטף ויוצא ראשון ראשון:"],[9,"להוי כמשקה להכשיר זרעים","שאם יגע שרץ בהן יטמא ואמאי מטהריתו לגמרי:"],[9,"דם חללים ישתה","דם שהנפש יוצאה בו קרוי משקה ולענין הכשר בעינן משקה כדכתיב (ויקרא י״א:ל״ד) ואשר יבא עליו מים יטמא וכל משקה אשר ישתה כלומר אוכל ומשקה אשר ישתה יבא על האוכל והכי מוקמינן לה בפסחים (דף טז.):"],[10,"אלפוה בג\"ש","להכשיר את הזרעים:"],[10,"שלחיך","דם נדות השלוח מן האשה:"],[10,"פרדס רמונים","כפרדס זה שהוא נעול להשתמר כך בנות ישראל נועלות פתחיהן בימי נדותן מהיזקק לבעליהן עם פרי מגדים היינו בנים. וכתיב שילוח במים מה מים מכשירין אף דם נדות מכשיר:"],[11,"אין אדם דן ג\"ש מעצמו","אא\"כ קבלה מרבו הל\"מ דדלמא קרא למילתא אחריתי איצטריך:"],[13,"שור","דמו אדום כדאמר בסדר יומא (דף נו:) האי חיור והאי סומק:"],[14,"","דם שחיטה משתנה והולך:"],[15,"צפור חיה","דם היוצא מצפור חי ע\"י מכה:"],[15,"או דלמא לאפוקי כחוש","והאי חיה לשון בריאה הוא:"],[16,"הרגה מאכולת","אשה הרואה כתם בבגדה אם הרגה מאכולת תולה בה. ואי קשיא הא שיעור כתם כגריס ועוד ומאכולת כולי האי לא הוי כדאמר בפירקין בעינן כגריס ועוד לאפוקי מדם מאכולת לא קשיא ההיא לר' חנינא בן אנטיגנוס הא לרבנן בפרק הרואה כתם (לקמן נדה דף נח:) דלא בעי האי שיעור:"],[16,"מאי לאו מאכולת דכולה גופה","אלמא כל מאכולת דומה לדם נדות ואת אמרת דם מאכולת של ראש הוא דדמי לדם נדות אבל דשאר הגוף לא:"],[17,"אמי ורדינאה","נאה כורד ובגיטין (דף מא.) קרי ליה אמי שפיר נאה. ל\"א ורדינאה מקום הוא ששמו ורדינא בעירובין (דף מט.):"],[18,"תולה","כתמה:"],[18,"בבנה ובבעלה","אם יש בהן מכה שמא נטף עליה כששוכבין יחד. אלמא דם בנה ובעלה דומה לדם נדות:"],[18,"בשלמא בנה משכחת לה","שלא נשא:"],[18,"אלא בעלה","הא נשוי הוא:"],[19,"רב נחמן","אמתני' קאי:"],[20,"ותלה רבי מאיר","כתם:"]],[[1,"","הירוק עקביא בן מהללאל מטמא. האי ירוק היינו כאתרוג ולא ירוק ככרתי דאין זה נוטה לאדמומית וסתם ירוק כן הוא כדאמר בלולב הגזול (סוכה דף לד: ושם) ירוק ככרתי מכלל דסתם ירוק לאו הכי הוא:"],[1,"","לית ליה. פירוש לית ליה ד' דווקא אלא נפקא ליה החמישי מקרא אחרינא:"],[5,"","ירד רבי מאיר לשיטת עקביא בן מהללאל וטימא. תימה והא לקמן בפ' בנות כותים (נדה לג.) גבי כותי מטמא משכב התחתון כעליון מפרש ר' מאיר לפי שמשלימות דם אדום לדם ירוק אלמא אית ליה דטהור ונראה דהכא מיירי מדרבנן וכן מוכח מדקאמר נהי דכי משכחת כתם אמנא לא מטמא היכי דחזיא ירוק מגופה תטמא ויש לדחות דלעולם כי חזיא מגופה מטמא מדאורייתא ומ\"מ כי משכחת אמנא לא מטמא דאין רגילות לצאת דם ירוק מגופה ויש לתלות דמעלמא אתא או שמא דם ירוק לאו דווקא נקט אלא כלומר דם שהוא טהור לכ\"ע משלימות לדם אדום אי נמי עיקר טעמא דר\"מ כטעמא אחרינא דקאמר יום שפוסקת בו סופרת למנין שבעה וטעמא קמא נקט לרבנן:"],[10,"","כתיב הכא שלחיך פרדס. וא\"ת ה\"מ דם שהאשה טמאה בו כדמשמע קרא כפרדס שהוא נעול כך בנות ישראל נועלות פתחיהן מליזקק לבעליהן בימי נדותן אבל דם ירוק שהוא טהור לא ותו דמשמע דלא פליגי אלא בדם ירוק אבל בדם נדה מודו כ\"ע דמכשיר וכיון דרבנן לית להו ג\"ש דם נדה מנא להו וי\"ל דדם נדה נפקא להו בתוספתא דשבת פ' (הזורק) דקתני מנין לדם שהוא משקה נאמר כאן וטהרה ממקור דמיה ונאמר להלן ביום ההוא יהיה מקור נפתח לבית דוד וליושבי ירושלם לחטאת ולנדה ויש לתמוה דהכא משמע דלכ\"ע דם הנדה לא הוה בכלל דם חללים ובשבת פרק חבית (שבת דף קמג:) משמע דחלב האשה טמא משום דם מגפתה דקתני לא אם אמרת בחלב האשה שמכשיר שלא לרצון שכן דם מגפתה מכשיר ומפרש רש\"י דחלב היה דם תחלה כדאמרינן (לעיל נדה דף ט.) דם נעכר ונעשה חלב והכא אמרינן דאפי' דם נדה לא הוי בכלל דם חללים כ\"ש חלב ודוחק לומר דחלב בא מעיקר דם שבגוף כמו דם מגפתה אבל דם נדה לא ומיהו בלאו הכי קשה התם דמאי קמהדר להו רבי עקיבא לרבנן מחמיר אני בחלב מבדם שהחולב לרפואה טמא ומקיז לרפואה טהור ועוד למה לי קרא בפ' דם הנדה (לקמן נדה נה:) דחלב האשה חשיב משקה מדכתיב ותפתח את נאד החלב ותשקהו תיפוק ליה מטעמא דדם נעכר ונעשה חלב ומיהו סוגיא דלקמן איכא למימר דלא סבר לה כרבי מאיר דדם נעכר כו' לכך נראה דה\"פ התם לא אם אמרת בחלב האשה שמכשיר כו' כלומר כיון דאיכא קרא לקמן בחלב שמכשיר לכל הפחות לרצון דין הוא שיכשיר גם שלא לרצון כיון דחזינן גבי אשה בשום מקום דמכשיר שלא לרצון כמו דם מגפתה אבל בהמה אע\"ג דחלבה מכשיר לרצון מותפתח את נאד החלב בשביל כך לא תכשיר שלא לרצון כיון דלא אשכחן בבהמה מידי דמכשיר שלא לרצון שדם מגפתה טהור אמר להם מחמיר אני בחלב יותר מבדם שהחולב לרפואה כו' כלומר חלב דמכשיר לאו בחומרא דדם מגפתה תליא מילתא שהרי מקיז לרפואה טהור דהיינו לרצון ולא אמרינן כשם שחלבה לרצון טמא כך דמה לרפואה טמא אלא ודאי חלב האשה דמטמא משום דמשקה גמור הוא וכ\"ש חלב בהמה דליהוי טפי משקה דמיוחד לקטנים ולגדולים אמרו לו סלי זיתים וענבים יוכיחו דמיוחדים לקטנים ולגדולים ושלא לרצון טהור והשתא לא קשה מדם הנדה דפשיטא דלא הוי בכלל דם חללים ולקמן בעז\"ה נפרש דקראי דפרק דם הנדה אסמכתא בעלמא נינהו:"]]],[["בקילור ורבי תלה בשרף שקמה מאי לאו אאדום","לא אשאר דמים","אמימר ומר זוטרא ורב אשי הוו יתבי קמיה אומנא שקלי ליה קרנא קמייתא לאמימר חזייה אמר להו אדום דתנן כי האי שקלי ליה אחריתי אמר להו אשתני אמר רב אשי כגון אנא דלא ידענא בין האי להאי לא מבעי לי למחזי דמא","שחור כחרת אמר רבה בר רב הונא חרת שאמרו דיו תניא נמי הכי שחור כחרת ושחור שאמרו דיו ולימא דיו אי אמר דיו הוה אמינא כי פכחותא דדיותא קמ\"ל כי חרותא דדיותא","איבעיא להו בלחה או ביבשתא תא שמע דרבי אמי פלי קורטא דדיותא ובדיק בה","אמר רב יהודה אמר שמואל כקיר כדיו וכענב טמאה וזוהי ששנינו עמוק מכן טמאה אמר רבי אלעזר כזית כזפת וכעורב טהור וזוהי ששנינו דיהה מכן טהור","עולא אמר כלבושא סיואה עולא אקלע לפומבדיתא חזייה לההוא טייעא דלבוש לבושא אוכמא אמר להו שחור דתנן כי האי מרטו מיניה פורתא פורתא יהבו ביה ארבע מאה זוזי","רבי יוחנן אמר אלו כלים האוליירין הבאים ממדינת הים למימרא דאוכמי נינהו והאמר להו רבי ינאי לבניו בני אל תקברוני לא בכלים שחורים ולא בכלים לבנים שחורים שמא אזכה ואהיה כאבל בין החתנים לבנים שמא לא אזכה ואהיה כחתן בין האבלים אלא בכלים האוליירין הבאים ממדינת הים","אלמא לאו אוכמי נינהו לא קשיא הא בגלימא הא בפתורא","אמר רב יהודה אמר שמואל וכולם אין בודקין אלא על גבי מטלית לבנה אמר רב יצחק בר אבודימי ושחור על גבי אדום","אמר רב ירמיה מדפתי ולא פליגי הא בשחור הא בשאר דמים מתקיף לה רב אשי אי הכי לימא שמואל חוץ משחור אלא אמר רב אשי בשחור גופיה קמיפלגי","אמר עולא כולן עמוק מכן טמא דיהה מכן טהור כשחור","ואלא מאי שנא שחור דנקט סד\"א הואיל ואמר רבי חנינא שחור אדום הוא אלא שלקה הילכך אפילו דיהה מכן נמי ליטמא קמשמע לן","רבי אמי בר אבא אמר וכולן עמוק מכן טמא דיהה מכן נמי טמא חוץ משחור אלא מאי אהני שיעוריה דרבנן לאפוקי דיהה דדיהה","ואיכא דאמרי רמי בר אבא אמר וכולן עמוק מכן טהור דיהה מכן טהור חוץ משחור ולהכי מהני שיעוריה דרבנן","בר קפרא אמר וכולן עמוק מכן טמא דיהה מכן טהור חוץ ממזג שעמוק מכן טהור דיהה מכן טהור בר קפרא אדיהו ליה ודכי אעמיקו ליה ודכי אמר רבי חנינא כמה נפיש גברא דלביה כמשמעתיה","וכקרן כרכום תנא לח ולא יבש","תני חדא כתחתון ולא כעליון ותניא אידך כעליון ולא כתחתון ותניא אידך כעליון וכל שכן כתחתון ותניא אידך כתחתון וכל שכן כעליון","אמר אביי תלתא דרי ותלתא טרפן הויין","נקוט דרא מציעאה וטרפא מציעתא בידך","כי אתו לקמיה דרבי אבהו אמר להו בגושייהו שנינו","וכמימי אדמה תנו רבנן כמימי אדמה מביא אדמה שמנה מבקעת בית כרם ומציף עליה מים דברי רבי מאיר רבי עקיבא אומר מבקעת יודפת רבי יוסי אומר מבקעת סכני רבי שמעון אומר אף מבקעת גנוסר וכיוצא בהן","תניא אידך וכמימי אדמה מביא אדמה שמנה מבקעת בית כרם ומציף עליה מים כקליפת השום ואין שיעור למים משום דאין שיעור לעפר ואין בודקין אותן צלולין אלא עכורין צללו חוזר ועוכרן וכשהוא עוכרן אין עוכרן ביד אלא בכלי","איבעיא להו אין עוכרין אותן ביד אלא בכלי דלא לרמיה בידיה ולעכרינהו אבל במנא כי עכר ליה בידיה שפיר דמי או דלמא דלא לעכרינהו בידיה אלא במנא","ת\"ש כשהוא בודקן אין בודקן אלא בכוס ועדיין תבעי לך בדיקה בכוס עכירה במאי תיקו","כי אתו לקמיה דרבה בר אבוה אמר להו במקומה שנינו רבי חנינא פלי קורטא דגרגשתא ובדיק ביה לייט עליה רבי ישמעאל ברבי יוסי באסכרה"],[[0,"בקילור","אנפלשט\"ר ואדום הוא ונתעסקה בו. אלמא קילור דומה לדם נדות ואע\"ג דלא הוי סומק כולי האי וקשיא לכולהו דדייקי בין דם בחור לדם נשוי משום דסומק טפי ובין דם מאכולת של ראש לשאר דם מאכולת:"],[2,"אומנא","מקיז דם בקרן:"],[2,"בין האי להאי","בין קמא לבתרא:"],[3,"חרת שאמרו דיו","כלומר לא כשחרורית חרת הניתך במים אלא שחרורית חרת הניתך בדיו:"],[3,"כי פכחותא דדיותא","קלישות הדיו כשהכלי מלא יורד שחרורית החרת למטה ומלמעלה הוא ברור ואינו שחור כל כך:"],[4,"בלחה","בדיו לחה כדמפרש:"],[4,"או ביבשתא","שכן דרך שנותנין חרת בדיו כששולקים קליפות הקוצרים והוא מתייבש:"],[4,"פלי קורטא דדיותא","מבקע חתיכות דיו יבש:"],[4,"ובודק בו","מראית דם שחור:"],[5,"כקיר","שעוה שחורה:"],[5,"כענבה","ענבים שחורים. ל\"א קיר שם עשב שחור:"],[6,"","עולא אשחור דמתניתין קאי דקתני טמא:"],[6,"סיואה","שם מקום ועושין שם מלבושים שחורים:"],[7,"אוליירין","בלנים מחממי מרחצאות. לשון אחר שם מקום:"],[7,"שמא אזכה","לגן עדן והצדיקים מלובשים לבנים:"],[8,"","גלימי אוליירין הוו סומקי אבל פתורי כגון מפה וסדין אוליירין הוו שחורין:"],[9,"וכולן","חמשה דמים:"],[9,"מטלית לבנה","מראות הדמים ניכרים בה:"],[9,"ושחור","דם שחור נבדקה מראיתו אם שחור היא כחרת או דיהה מכן על גבי בגד אדום:"],[11,"כולם","הדמים:"],[11,"עמוק מכן","מאותו שיעור השנוי במתניתין לכל אחד אי הוה סומק טפי טמא:"],[11,"דיהה מכן טהור כשחור","ואע\"פ דלא תנן במתניתין דיהה מכן טהור אלא גבי שחור הוא הדין לכולהו:"],[12,"אפי' דיהה מכן ליטמא","דהאי אדום הוה וע\"י לקותא הושחר:"],[12,"קא משמע לן","דאין דרך דם אדום המשחיר על ידי לקותא להיות דיהה:"],[13,"דיהה דדיהה","שנדחה ממראיתו יותר מדאי:"],[15,"עמוק מכן טהור","אם מאותו מראה הוא אבל אם האדים הרבה עד שבא לכלל אחד משאר המראות של מעלה הימנו הרי בא לחדא מהנך דמתני':"],[15,"אדיהו ליה","דם הדומה למזגא:"],[17,"כתחתון","עלה תחתון:"],[18,"תלתא דרי","דעלין הוו זו למעלה מזו:"],[19,"נקוט דרא מציעא","לבדוק בה את הדם:"],[19,"וטרפא מציעא","דההוא משובח לבדוק מכולן ומיהו כוליה דרא כשרה לבדוק. והא דקתני כתחתון ולא כעליון הכי קאמר כשורה אמצעית ולא כעליונה הימנה והא דקתני כעליון ולא כתחתון כשורה אמצעית ולא כתחתונה הימנה דאין כשר לבדוק אלא בדרא אמצעית והא דתניא כתחתון וכ\"ש כעליון דמשמע דתרוייהו כשרין לבדוק אלא שהעליון משובח לאו אדרי קאי אלא אעלין דדרא מציעא וה\"ק בעלה תחתון שהוא ברור וכ\"ש בעליון הימנה דהיינו אמצעי שהוא ברור מאד והא דתניא כעליון וכ\"ש כתחתון הכי קאמר כעליון כעלה העליון וכ\"ש כתחתון כעלה האמצעי:"],[20,"בגושייהו שנינו","לבדוק בהן ולא לאחר תלישתן:"],[22,"ואין שיעור למים","משום דאין שיעור לעפר - אלא יביא עפר כמו שירצה אם רב אם מעט ויציף על מים כעובי קליפת השום למעלה מן העפר:"],[22,"אלא עכורין","שתהא מראית אדמה נכנסת במים:"],[22,"וכשהוא עוכרן","המים בעפר:"],[23,"לא לרמיה בידיה","לא יתן העפר אל תוך ידו ויעכור המים בעפר שבידו אע\"פ שחוזר ונותנו בכלי לאחר עכירה:"],[23,"אבל","אם העפר בכלי כי עכר להו בידיה באצבע שפיר דמי:"],[23,"או דלמא לא לעכרינהו בידיה","כשהמים בספל לא יעכרם באצבעו אלא בבזך או בכלי אחר:"],[24,"אלא בכוס","של זכוכית. אלמא לא לירמי עפר במים בכפו ויבדוק:"],[25,"אמר להו במקומה שנינו","שאין האדמה דומה לדם אלא במקומה אבל הביאה במקום אחר נשתנה מראיתה:"],[25,"פלי","מבקע:"],[25,"ובדיק לה","בלא מים:"],[25,"לייט עליה ר' ישמעאל","אאחר שיעשה כן באסכרה:"]],[[4,"","פלי קורטא דדיותא. מכאן משמע שדיו שלנו הוא קרוי דיו מדקאמר קורטא דדיותא משמע שהוא יבש ואוסר ר\"ת לכתוב ס\"ת בדיו של עפצים לפי שהוא לעולם לח ובפ' [שני] דגיטין (דף יט.) מפורש:"]]],[["רבי חנינא הוא דחכים כולי עלמא לאו חכימי הכי","אמר רבי יוחנן חכמתא דרבי חנינא גרמא לי דלא אחזי דמא מטמינא מטהר מטהרנא מטמא אמר רבי אלעזר ענוותנותא דרבי חנינא גרמא לי דחזאי דמא ומה רבי חנינא דענותן הוא מחית נפשיה לספק וחזי אנא לא אחזי","אמר רבי זירא טבעא דבבל גרמא לי דלא חזאי דמא דאמינא בטבעא לא ידענא בדמא ידענא","למימרא דבטבעא תליא מלתא והא רבה הוא דידע בטבעא ולא ידע בדמא כל שכן קאמר ומה רבה דידע בטבעא לא חזא דמא ואנא אחזי","עולא אקלע לפומבדיתא אייתו לקמיה דמא ולא חזא אמר ומה רבי אלעזר דמרא דארעא דישראל הוה כי מקלע לאתרא דר' יהודה לא חזי דמא אנא אחזי","ואמאי קרו ליה מרא דארעא דישראל דההיא אתתא דאייתא דמא לקמיה דרבי אלעזר הוה יתיב רבי אמי קמיה ארחיה אמר לה האי דם חימוד הוא בתר דנפקה אטפל לה רבי אמי אמרה ליה בעלי היה בדרך וחמדתיו קרי עליה (תהלים כה, יד) סוד ה' ליראיו","אפרא הורמיז אמיה דשבור מלכא שדרה דמא לקמיה דרבא הוה יתיב רב עובדיה קמיה ארחיה אמר לה האי דם חימוד הוא אמרה ליה לבריה תא חזי כמה חכימי יהודאי א\"ל דלמא כסומא בארובה","הדר שדרה ליה שתין מיני דמא וכולהו אמרינהו ההוא בתרא דם כנים הוה ולא ידע אסתייע מילתא ושדר לה סריקותא דמקטלא כלמי אמרה יהודאי בתווני דלבא יתביתו","אמר רב יהודה מרישא הוה חזינא דמא כיון דאמרה לי אמיה דיצחק ברי האי טיפתא קמייתא לא מייתינן לה קמייהו דרבנן משום דזהימא לא חזינא","בין טמאה לטהורה ודאי חזינא","ילתא אייתא דמא לקמיה דרבה בר בר חנה וטמי לה הדר אייתא לקמיה דרב יצחק בריה דרב יהודה ודכי לה","והיכי עביד הכי והתניא חכם שטימא אין חברו רשאי לטהר אסר אין חבירו רשאי להתיר","מעיקרא טמויי הוה מטמי לה כיון דא\"ל דכל יומא הוה מדכי לי כי האי גונא והאידנא הוא דחש בעיניה דכי לה","ומי מהימני אין והתניא נאמנת אשה לומר כזה ראיתי ואבדתיו","איבעיא להו כזה טיהר איש פלוני חכם מהו","תא שמע נאמנת אשה לומר כזה ראיתי ואבדתיו שאני התם דליתיה לקמה","תא שמע דילתא אייתא דמא לקמיה דרבה בר בר חנה וטמי לה לקמיה דרב יצחק בריה דרב יהודה ודכי לה והיכי עביד הכי והתניא חכם שטימא אין חבירו רשאי לטהר וכו'","ואמרינן טמויי הוה מטמי לה כיון דאמרה ליה דכל יומא מדכי לה כי האי גונא והאידנא הוא דחש בעיניה הדר דכי לה אלמא מהימנא לה","רב יצחק בר יהודה אגמריה סמך","רבי ראה דם בלילה וטימא ראה ביום וטיהר המתין שעה אחת חזר וטימא אמר אוי לי שמא טעיתי","שמא טעיתי ודאי טעה דתניא לא יאמר חכם אילו היה לח היה ודאי טמא","אלא אמר אין לו לדיין אלא מה שעיניו רואות מעיקרא אחזקיה בטמא כיון דחזא לצפרא דאשתני אמר (ליה) ודאי טהור הוה ובלילה הוא דלא אתחזי שפיר כיון דחזא דהדר אשתני אמר האי טמא הוא ומפכח הוא דקא מפכח ואזיל","רבי בדיק לאור הנר רבי ישמעאל ברבי יוסף בדיק ביום המעונן ביני עמודי אמר רב אמי בר שמואל וכולן אין בודקין אותן אלא בין חמה לצל רב נחמן אמר רבה בר אבוה בחמה ובצל ידו","וכמזוג שני חלקים כו' תנא"],[[0,"דרבי חנינא הוא דחכים","ומצי בדיק כה\"ג:"],[4,"דמרא דארעא דישראל","בקי במראות דם מכל חכמי ארץ ישראל כדמפרש לקמן: פומבדיתא אתריה דרב יהודה בשילהי פ\"ק דסנהדרין (דף יז:) סבי דפומבדיתא רב יהודה ורב עינא:"],[4,"ולא חזא","משום כבודו דרב יהודה:"],[5,"ארחיה","הריח בו:"],[5,"חימוד","שנתאוית לבעלה וראתה הדם מחמת תאוה:"],[6,"איפרא הורמיז","נכרית היתה וכן שמה ואעפ\"כ היתה משמרת עצמה מנדות וקרובה להתגייר ואף קרבנות היתה שולחת. ולשון יוני איפרא חן כמו אפריון נמטייה לרבי שמעון (ב\"מ דף קיט.):"],[6,"הורמיז","כמו (ב\"ב דף עג.) הורמיז בר ליליתא כלומר יופי שדים היה לה:"],[6,"ארחיה כו'","ואע\"ג דאמר לעיל רבא לא ידע בדמא ניסא איתרחיש ליה:"],[7,"שלח לה","משום דורון:"],[7,"סריקותא","מסרק נאה:"],[7,"מקטלא כלמי","שהורגין עליה כנים. וסברה ודאי הבין ומשום הכי שלח לי האי:"],[7,"כלמי","כנים כדמתרגמינן כנים כלמתא:"],[7,"בתווני לבאי","בחדרי הלב אתם יושבים. מחדרים מתרגמי' מתווניא. כלומר כל חכמה מצויה בכם:"],[8,"לא חזינא","דדילמא אשתני ואע\"ג דמראה דם טהור יש לה דלמא אי אייתא טיפתא קמייתא הוה מיחזי טמא:"],[9,"בין טמאה לטהורה","כשכלין ימי טוהר של זכר או של נקבה וראתה ביום ארבעים ואחד או ביום שמונים ואחד:"],[9,"חזינא לההוא דמא","אי דם טמא מטמינא ואי לאו מחמשה דמים הוא מטהרינא דההוא ודאי טיפתא קמייתא מייתא דלא מזהמא דעד השתא חזאי ואתא דם טוהר שכל מ' לזכר ופ' לנקבה מעין פתוח ואפי' פסקה יום או יומים הואיל ומוחזקת היא בדמים לא זהמא ומייתא טיפתא קמייתא:"],[12,"מעיקרא טמויי טמי לה","רב יצחק משום כבודו דרבה בר בר חנה:"],[13,"כזה ראיתי","מביאה דם אחר או שלה או של חברתה ואומרת כזה ראיתי ואבדתיו אם דם זה טהור לא מספקינן ליה בטומאה משום דם האבוד דמהימנא למימר כזה ראיתי:"],[14,"כזה טיהר לי פלוני כו' מהו","שתסמוך עליה חברתה שהראתה דמה לזו ואמרה לה כדם זה שלך הראתי גם אני לפלוני חכם וטיהר:"],[15,"נאמנת אשה כו'","אלמא קים לה במראה דמים:"],[15,"דליתיה קמן","אבל הכא דאיתיה קמן ניחזי אנן:"],[18,"אגמריה סמך","דפשיטא ליה דטהור והאי דהוה מטמא מעיקרא משום כבודו דרבה בר בר חנה אבל אי הוה מספקא ליה לא הוה סמיך עלה:"],[19,"ראה ביום","לאותו דם עצמו:"],[19,"חזר וטימא","קס\"ד דלא חזר וראהו אלא מאליו חזר בו וטימא דסבר שמא אמש טמא הוה ועכשיו שיבש נשתנה ממראיתו ממה שהיה לו אמש ואילו הוה לח כמתחלתו הוה נראה טמא לפיכך חזר בו ממה שטיהר:"],[19,"שמא טעיתי","במה שחזרתי וטימאתי הואיל ומראיהו עכשיו טהור:"],[21,"מעיקרא אחזקיה בטומאה","כלומר אמש לא מספק טימא אלא שפיר חזייה ואחזיק בטומאה דאמרי' לקמן רבי בדק לאור הנר:"],[21,"דאישתני","הלבין:"],[21,"דהדר אישתני","עוד יותר:"],[21,"מפכח","מראה אדמומיתו עוברת הילכך הדר למילתיה קמייתא וטימא. והא דאמרינן אין לו לדיין אלא מה שעיניו רואות היכא דלא אחזיה כשהוא לח ולא אידמי ליה כטמא:"],[22,"בין העמודים","היכא דגרסי ואע\"ג דליכא נהורא כולי האי:"],[22,"ובצל ידו","נותן ידו כנגד חמה על הדם ומיצל:"]],[[3,"","והא רבא דידע. רבה גרס דרבא היה בקי כדמוכח בסמוך גבי דאפרא הורמיז ורש\"י פירש בסמוך דאיתרחיש ליה ניסא ואין נראה דדוקא בסוף הוא דאיתרחיש ליה ניסא כדמוכח בסמוך:"],[8,"","טיפתא קמייתא. ושאר חכמים שהיו רואין לא היו מחמירין כ\"כ או שהיו בקיאין ביותר:"],[12,"","כל יומא הוה מטהר לי כה\"ג. משמע שלא היתה רגילה להראות לרב נחמן בעלה ושמא לא היה בקי והא דאמר ר\"נ לעיל (נדה דף יט:) בדם הקזה קבלה היתה בידו אי נמי היתה חוששת שמא היה מחמיר על עצמו להיות לבו נוקפו ופורש ולא יסמוך על חכמתו אי נמי שלא תתגנה בפניו אבל אין לומר דאסור לראות דמי אשתו דהא במס' נגעים (פ\"ב מ\"ה) תנן כל הנגעים אדם רואה חוץ מנגעי עצמו ר\"מ אומר אף לא נגעי קרוביו כל הנדרים אדם מתיר חוץ מנדרי עצמו ר' יהושע אומר אף לא נדרי אשתו ואילו כל הדמים אדם רואה חוץ מדמי אשתו לא קתני:"],[18,"","אגמריה סמך. לפי הפשט משמע דלכך האמין לדבריה אבל בענין אחר [פירוש בלא דבריה] לא היה מתיר אע\"ג דאגמריה סמך וקשה דבפ' אלו טרפות (חולין מט.) אמרו גבי ההיא מחטא דאישתכח בסימפונא דכבדא הונא מר בריה דרב אידי טריף ורב אחא בר מניומי מכשיר לכך נראה לפרש דהשתא הדר ביה משינויא קמא והיכא דאגמריה סמיך רשאי להתיר אע\"ג דחכם כבר אסר ויש מקשה על ילתא היכי עבדה הכי הא אמרינן בפ\"ק דמס' ע\"ז (דף ז.) הנשאל לחכם וטימא לא ישאל לחכם ויטהר וי\"ל דקפידא לא הויא אשואל אלא אחכם אבל השואל ישאל כל מה שירצה דמתוך כך ידקדקו בדבר ופעמים שהראשון טועה ויצא הדבר לאורה: [ועי' תוס' ע\"ז ז. ד\"ה הנשאל ותוס' חולין מד: ד\"ה היכי]:"]]],[["השרוני נידון ככרמלי חי ולא מזוג חדש ולא ישן","אמר רב יצחק בר אבודימי וכולן אין בודקין אותן אלא בכוס טבריא פשוט מאי טעמא אמר אביי של כל העולם כולו מחזיק לוג עושין אותו ממנה שני לוגין עושין אותו ממאתים כוס טבריא פשוט אפי' מחזיק שני לוגין עושין אותו ממנה ואיידי דקליש ידיע ביה טפי","\u0001הדרן עלך כל היד\u0002","מתני׳ \u0001המפלת\u0002 חתיכה אם יש עמה דם טמאה ואם לאו טהורה ר' יהודה אומר בין כך ובין כך טמאה","המפלת כמין קליפה כמין שערה כמין עפר כמין יבחושין אדומים תטיל למים אם נמוחו טמאה ואם לאו טהורה","המפלת כמין דגים חגבים שקצים ורמשים אם יש עמהם דם טמאה ואם לאו טהורה","המפלת מין בהמה חיה ועוף בין טמאין בין טהורין אם זכר תשב לזכר ואם נקבה תשב לנקבה","ואם אין ידוע תשב לזכר ולנקבה דברי רבי מאיר וחכמים אומרים כל שאין בו מצורת אדם אינו ולד","\u0001גמ׳\u0002 אמר רב יהודה אמר שמואל לא טימא רבי יהודה אלא בחתיכה של ארבעת מיני דמים אבל של שאר מיני דמים טהורה","ור' יוחנן אמר של ארבעת מיני דמים דברי הכל טמאה של שאר מיני דמים דברי הכל טהורה","לא נחלקו אלא שהפילה ואינה יודעת מה הפילה רבי יהודה סבר זיל בתר רוב חתיכות ורוב חתיכות של (מיני) ארבעת מיני דמים הויין ורבנן סברי לא אמרינן רוב חתיכות של ארבעת מיני דמים","איני והא כי אתא רב הושעיא מנהרדעא אתא ואייתי מתניתא בידיה המפלת חתיכה אדומה שחורה ירוקה ולבנה אם יש עמה דם טמאה ואם לאו טהורה רבי יהודה אומר בין כך ובין כך טמאה קשיא לשמואל בחדא ולרבי יוחנן בתרתי","לשמואל בחדא דאמר שמואל לא טימא רבי יהודה אלא בחתיכה של ארבעת מיני דמים והא קתני ירוקה ולבנה ופליג רבי יהודה","וכי תימא כי פליג רבי יהודה אאדומה ושחורה ואירוקה ולבנה לא אלא ירוקה ולבנה למאן קתני לה","אילימא רבנן השתא אדומה ושחורה מטהרי רבנן ירוקה ולבנה מיבעיא אלא לאו לרבי יהודה ופליג","ותו לרבי יוחנן דאמר של ארבעת מיני דמים דברי הכל טמאה הא קתני אדומה ושחורה ופליגי רבנן","וכי תימא כי פליגי רבנן אירוקה ולבנה אבל אאדומה ושחורה לא אלא אדומה ושחורה למאן קתני לה","אילימא רבי יהודה השתא ירוקה ולבנה טמאה אדומה ושחורה מיבעיא אלא לאו רבנן ופליגי","אלא אמר רב נחמן בר יצחק באפשר לפתיחת הקבר בלא דם קמיפלגי ובפלוגתא דהני תנאי דתניא קשתה שנים ולשלישי הפילה ואינה יודעת מה הפילה"],[[0,"השרוני","מזוג:"],[0,"נידון ככרמלי חי","דהכי נמי בדקי בכרמלי חי. ואית דגרסי כשרוני נידון הכרמלי:"],[1,"בכוס טבריא של זכוכית פשוט","טנב\"ש ואיידי דקליש נראה בו אדמומית היין:"],[3,"מתני' המפלת חתיכה אם יש עמה דם טמאה","משום נדה:"],[3,"ואם לאו טהורה","דלאו לידה היא דאי לידה הויא בלא דם נמי טמאה דכתיב (ויקרא י״ב:ב׳) כימי נדת דותה תטמא:"],[3,"ר' יהודה אומר כו'","מפרש בגמרא:"],[4,"כמין שערה","שער:"],[4,"יבחושין","יתושין:"],[4,"אם נימוחו טמאה","משום נדה דדם הוא:"],[5,"מין דגים","נמי לאו ולד הוא וטעמא מפרש בגמרא הלכך אי איכא דם טמאה נדה ואם לאו טהורה:"],[6,"תשב לזכר","ימי טומאת שבעה וימי טהרה ל\"ג וכל דמים שתראה בהן טהורין:"],[7,"לזכר ולנקבה","לחומרא ימי טומאה דנקבה שבועים וימי טוהר כלים לסוף ארבעים יום כזכר ולא פ' כנקבה. ובגמרא מפרש מאי שנא דלחיה ועוף קרי ולד יותר מדגים:"],[8,"גמ' של ד' מיני דמים","דקסבר היא גופה דם הלכך טמאה נדה אבל ולד לא הוי:"],[10,"לא אמרינן כו'","דקסברי אין רוב חתיכות של ארבע מיני דמים דלא אתחזק לן האי רובא:"],[11,"ירוקה ולבנה","לאו מארבע מיני דמים הן אלא אדום וכמימי אדמה וכקרן כרכום וכמזוג. ושחור לא קא חשיב דהיינו אדום אלא שלקה:"],[13,"למאן קתני לה","כלומר להודיע דבריו של מי בא:"],[14,"אלא לר' יהודה","להודיע דאירוקה ולבנה נמי פליג:"],[15,"ותו לרבי יוחנן וכו'","כלומר הך קושיא דירוקה ולבנה לא איבעי לן לפרושי דכי היכי דקשיא ליה לשמואל קשיא ליה לרבי יוחנן דהא רבי יוחנן נמי אמר על שאר מינין לרבי יהודה טהורה והכא קתני ירוקה ולבנה ופליג רבי יהודה ותו קשיא אחריתי לר' יוחנן דאמר של ארבעת מיני דמים דברי הכל כו':"],[16,"","הכי גרסינן \u0003וכי תימא כי פליגי רבנן אירוקה ולבנה אלא אדומה ושחורה למאן קתני לה כו' אלא לאו רבנן ופליגי\u0004:"],[18,"פתיחת הקבר","הרחם:"],[18,"בלא דם","דם לידה הלכך לרבנן כי ליכא דם טהורה ואפילו החתיכה של ארבע מיני דמים דחתיכה לאו דם הוא אלא בשר ולא אמר דם אחר איכא ואנן הוא דלא חזינן דקסברי רבנן אפשר לפתיחת הקבר בלא דם לר' יהודה אפילו ירוקה ולבנה טמאה דודאי דם אחר הוה ואנן הוא דלא חזינן דאי אפשר לפתיחת הקבר בלא דם:"],[18,"קשתה שנים","בתוך י\"א יום שבין נדה לנדה וראתה דם מחמת קושי:"],[18,"ולשלישי הפילה","ואינה יודעת אם ראתה דם באותה לידה אם לאו:"],[18,"ואינה יודעת","אם נפל הוא ואם רוח בעלמא הוא:"]],[[8,"","אלא בחתיכה של ד' מיני דמים. דקסבר ר' יהודה דם נדות הוא ונקרש ונעשה חתיכה כדאמר לקמן גבי מפלת מין דגים ורבנן סברי מקור מגדל חתיכה ולא דם נדות הוא:"],[10,"","ורבנן סברי לא אמרינן רוב חתיכות. תימה ונימא דהוה פלגא ופלגא ויהא ודאי טמא ברה\"י אע\"ג דאיכא חזקת טהרה וי\"ל דאמרי' לעיל (נדה דף יח:) דאפילו לרבי יהודה לא הוי רוב גמור ואין שורפין עליו את התרומה ולרבנן אפילו פלגא לא הוי ואדרבה רוב החתיכות לאו של ד' מיני דמים הם:"],[15,"","לרבי יוחנן אדומה ושחורה למאן קתני לה אי לרבי יהודה. וה\"פ המפלת אדומה ושחורה דינו כדמפרש ר' יהודה בסיפא השתא ירוקה כו' ומתוך פי' ר\"ח משמע דל\"ג וכ\"ת כי פליגי רבנן אירוקה ולבנה וכן נראה דהא בהדיא קתני במילתייהו שחורה ואדומה ואין זו סוגיית הש\"ס:"]]],[["הרי זו ספק לידה ספק זיבה מביאה קרבן ואינו נאכל","רבי יהושע אומר מביאה קרבן ונאכל שאי אפשר לפתיחת הקבר בלא דם","לישנא אחרינא אמרי לה אמר רב יהודה אמר שמואל לא טימא רבי יהודה אלא בחתיכה של ארבעה מיני דמים אבל של שאר מיני דמים טהורה","איני והא כי אתא רב הושעיא מנהרדעא אתא ואייתי מתניתא בידיה המפלת חתיכה אדומה ושחורה ירוקה ולבנה אם יש עמה דם טמאה ואם לאו טהורה ורבי יהודה אומר בין כך ובין כך טמאה","קתני אדומה ושחורה ירוקה ולבנה ופליג ר' יהודה","וכי תימא כי פליג ר' יהודה אאדומה ושחורה אבל ירוקה ולבנה לא אלא ירוקה ולבנה מאן קתני לה","אילימא לרבנן השתא אדומה ושחורה קא מטהרי רבנן ירוקה ולבנה מיבעיא אלא לאו לר' יהודה ופליג","אלא אמר רב יהודה באפשר לפתיחת הקבר בלא דם קמיפלגי ובפלוגתא דהני תנאי דתניא קשתה שנים ולשלישי הפילה ואינה יודעת מה הפילה הרי זו ספק לידה ספק זיבה מביאה קרבן ואינו נאכל","רבי יהושע אומר מביאה קרבן ונאכל לפי שאי אפשר לפתיחת הקבר בלא דם","ת\"ר המפלת חתיכה סומכוס אומר משום רבי מאיר וכן היה רבי שמעון בן מנסיא אומר כדבריו קורעה אם יש דם בתוכה טמאה ואם לאו טהורה","כרבנן ועדיפא מדרבנן כרבנן דאמרי אפשר לפתיחת הקבר בלא דם ועדיפא מדרבנן דאינהו סברי עמה אין בתוכה לא וסומכוס סבר אפילו בתוכה","ותניא אידך המפלת חתיכה ר' אחא אומר קורעה אם תוכה מאדים טמאה ואם לאו טהורה","כסומכוס ועדיפא מסומכוס","ותניא אידך המפלת חתיכה רבי בנימין אומר קורעה אם יש בה עצם אמו טמאה לידה אמר רב חסדא ובחתיכה לבנה וכן כי אתא זוגא דמן חדייב אתא ואייתי מתניתא בידיה המפלת חתיכה לבנה קורעה אם יש בה עצם אמו טמאה לידה","אמר רבי יוחנן משום רבי שמעון בן יוחי המפלת חתיכה קורעה אם יש בה דם אגור טמאה ואם לאו טהורה כסומכוס וקילא מכולהו","בעא מיניה רבי ירמיה מרבי זירא הרואה דם בשפופרת מהו (ויקרא טו:ז) בבשרה אמר רחמנא ולא בשפופרת או דלמא האי בבשרה מיבעי ליה שמטמאה מבפנים כבחוץ","אמר ליה בבשרה אמר רחמנא ולא בשפופרת דאי בבשרה מבעי ליה שמטמאה מבפנים כבחוץ א\"כ נימא קרא (בבשר) מאי בבשרה שמע מינה תרתי","והא\"ר יוחנן משום רבי שמעון בן יוחי המפלת חתיכה קורעה אם יש בה דם אגור טמאה ואם לאו טהורה","הכי השתא התם דרכה של אשה לראות דם בחתיכה הכא אין דרכה של אשה לראות דם בשפופרת","לימא שפופרת תנאי היא דתניא המפלת חתיכה אף על פי שמלאה דם אם יש עמה דם טמאה ואם לאו טהורה רבי אליעזר אומר בבשרה ולא בשפיר ולא בחתיכה","ר' אליעזר היינו תנא קמא אימא שרבי אליעזר אומר בבשרה ולא בשפיר ולא בחתיכה","וחכמים אומרים אין זה דם נדה אלא דם חתיכה תנא קמא נמי טהורי מטהר אלא דפלי פלויי איכא בינייהו","תנא קמא סבר בבשרה ולא בשפיר ולא בחתיכה והוא הדין לשפופרת והני מילי היכא דשיעא אבל פלי פלויי טמאה מאי טעמיה בבשרה קרינא ביה","ואתו רבנן למימר אף על גב דפלי פלויי אין זה דם נדה אלא דם חתיכה הא דם נדה ודאי טמא ואפילו בשפופרת נמי","אמר אביי בשפופרת כולי עלמא לא פליגי דטהורה"],[[0,"הרי זו ספק לידה וספק זיבה","ספק אם זיבה היא וחייבת בקרבן זיבה ספק אם לידה היא וחייבת בקרבן לידה ספק אינה לא לידה ולא זיבה ואין עליה קרבן כיצד אם ילדה בשלישי ולד גמור הרי כאן לידה ולא זיבה ואפי' ראתה דם עם לידתה להשלים ג' ראיות דקושי סמוך ללידה רחמנא טהרה לקמן בפ' בנות כותים (נדה דף לו:) כי יזוב זוב דמה דמה מחמת עצמה ולא מחמת ולד ואם לא היה ולד וראתה דם עם לידתה הרי כאן זיבה גמורה דהשתא לאו קושי סמוך ללידה הוא דאין כאן לידה ואם לא היה ולד ולא ראתה דם אין כאן לא לידה ולא זיבה דשני ימים הוא דחזאי הלכך מביאה קרבן אחד לאכול בקדשים דשמא יולדת או זבה היא ואינו נאכל חטאת העוף שלה דשמא אינה לא יולדת ולא זבה דאפשר לפתיחת הקבר בלא דם ובשלישי לא חזאי וולד נמי לא הואי והאי קרבן מליקת חולין היא ונבלה:"],[1,"שאי אפשר","הלכך מה נפשך אם ולד הוא הרי כאן לידה ואם אינו ולד הרי כאן זיבה דבשלישי חזאי:"],[10,"ועדיפא","חמירא:"],[11,"אם תוכה מאדים","הבשר מאדים ואפי' אין שם דם ממש:"],[12,"כסומכוס","דאמר תוכה כעמה ועדיפא מדסומכוס דאיהו בעי דם ממש:"],[13,"טמאה לידה","ויש לה ימי טוהר ותשב לזכר ולנקבה ימי טומאה דנקבה וימי טוהר דזכר:"],[13,"לבנה","דהוא מין בשר:"],[13,"זוגא דמן חדייב","שני תלמידי חכמים מאותו מקום:"],[14,"אגור","דם הרבה:"],[14,"כסומכוס","דאמר דם שבתוכו מטמא אותה משום נדה:"],[14,"וקילא מכולהון","מדסומכוס דלא בעי אגור ומדר' אחא דאמר אפילו אין תוכה אלא מאדים:"],[15,"בשפופרת","הכניסה קנה חלול באותו מקום ונמצא בתוכו דם:"],[15,"בבשרה","דם יהיה זובה בבשרה שיצא דרך כותלי בית הרחם ואין מפסיק והאי קרא בנדה כתיב ופרשה שניה נאמרה בזבה (ויקרא ט״ו:כ״ה) ואשה כי יזוב זוב דמה וגו':"],[15,"שמטמאה בפנים כבחוץ","מאחר שיצא מן המקור לפרוזדור והעמידו כותליה מיד היא מטמאה משא\"כ בזב ובעל קרי דאין מטמאין עד שתצא טומאתן לחוץ:"],[17,"אם יש בה דם אגור כו'","ומאי שנא משפופרת:"],[18,"דרכה של אשה לראות דם בחתיכה","הלכך בבשרה קרינא ביה דמין במינו לא חייץ:"],[19,"שפיר","עור הולד קודם שנבראו בתוכו גידים ועצמות ובשר:"],[21,"דפלי פלויי","שיש בה שורות שורות ביקועים מבחוץ והדם שם:"],[22,"דת\"ק","לא מטהר לה אלא מגזרת הכתוב סבר האי דם טהור הוא ומשום חציצה היא טהורה ומשום גזרת הכתוב וה\"ה לשפופרת כיון דטעמא משום חציצה הוא:"],[22,"וה\"מ דשיעא","חתיכה והדם בתוכה לא נגע:"],[22,"אבל היכא דפלי פלויי","והדם שם ונוגע ברחם:"],[22,"טמאה","דקרינן בבשרה והיינו דקאמרי אם יש עמה דם דפלי פלויי טמאה ואם לאו טהורה:"],[23,"","ורבנן בתראי לא דייקי לישנא דקרא והאי דמטהרי משום דלאו דם נדה הוא הלכך לא שנא בתוכה כי שיעא ולא שנא פלי פלויי דנגע ברחם טהורה אבל שפופרת דם נדה היא טמאה דלא דרשינן בבשרה אלא לטמאה בפנים כבחוץ:"],[24,"","כולי עלמא לא פליגי (דטהורה. דאין דרך הרואה בכך):"]],[[0,"","ואינו נאכל. דאימא לא ראתה ולא ילדה וב' קרבנות אין צריכה להביא משום דאימא ראתה וילדה דא\"כ קושי סמוך ללידה הוא וטהורה כיון דלא שפתה מעת לעת דיש קושי לנפלים וכן צ\"ל לרבי יהושע דסבר יש קושי לנפלים דאי אין קושי היה לה להביא שני קרבנות של זיבה דהוי ודאי נאכל ושל לידה דהוי ספק אינו נאכל דלזיבה וללידה לא סגי בקרבן חד מידי דהוי אחלב ודם כדאמרינן בפ\"ב דכריתות (דף ט:) ולקמן בפ' יוצא דופן (נדה דף מ.):"],[7,"","באפשר לפתיחת הקבר בלא דם קמיפלגי. להך לישנא תימה דג' מקומות דקאמר ר' יוחנן לעיל (נדה דף יח.) דהלכו חכמים אחר הרוב למעוטי מאי:"],[11,"","בתוכה מאדים. ואע\"ג דלא האדים מבחוץ ונראה דאם האדים מבחוץ עדיף טפי אפילו לא האדים מבפנים כמו דם אגור דבפנים אינו מועיל אלא לסומכוס ומבחוץ אפילו לרבנן:"],[13,"","זוזא. פירש בערוך שם חכם:"],[13,"","אם יש בה עצם טמאה לידה. והא דתנן הך קודם הא דדם אגור דמיירי נמי בנדה ולא בלידה משום דתני כל דברייתא ברישא:"],[17,"","והאמר רבי שמעון בן יוחי. וא\"ת וליסייעיה ממתני' דבעי עמה דם וי\"ל היינו משום דקסבר דאינו דם נדות:"],[23,"","הא דם נדה טמאה אפילו בשפופרת. וא\"ת מנליה הא אימא הא דדם נדה טמאה משום דפלי פלויי וקרינן ביה בבשרה כדמשני אביי לפירש\"י וי\"ל דנראה לו למקשה דרבנן פליגי אמאי דקאמר ר' אליעזר בהדיא בבשרה ולא בשפיר ולא בחתיכה ואתו רבנן למימר דלא מטעם בבשרה טהור אלא משום דאינו דם נדות הא אם היה דם נדות טמאה אפילו בשפופרת דאי דם נדות טהור בשפופרת אם כן לא הוו פליגי רבנן אמאי דקאמר רבי אליעזר בהדיא:"]]],[["כי פליגי בחתיכה מר סבר דרכה של אשה לראות דם בחתיכה ומר סבר אין דרכה של אשה לראות דם בחתיכה","רבא אמר דכולי עלמא אין דרכה של אשה לראות דם בחתיכה","והכא באשה טהורה ומקור מקומו טמא קמיפלגי דר' אליעזר סבר אשה טהורה ודם טמא דהא אתי דרך מקור ורבנן סברי אשה טהורה ומקור מקומו טהור","בעא מיניה רבה מרב הונא הרואה קרי בקיסם מהו (ויקרא טו טז) ממנו אמר רחמנא עד דנפיק מבשרו ולא בקיסם או דלמא האי ממנו עד שתצא טומאתו לחוץ ואפי' בקיסם נמי","אמר ליה תיפוק ליה דהוא עצמו אינו מטמא אלא בחתימת פי האמה","למימרא דנוגע הוי אלא מעתה אל יסתור בזיבה","אלמה תניא (ויקרא טו, לב) זאת תורת הזב ואשר תצא ממנו שכבת זרע מה זיבה סותרת אף שכבת זרע נמי סותר","אמר ליה סתירה היינו טעמא דסותר לפי שאי אפשר לה בלא צחצוחי זיבה","אלא מעתה תסתור כל שבעה אלמה תניא זאת תורת הזב וגו' מה זיבה סותרת אף שכבת זרע סותר","אי מה זיבה סותרת כל ז' אף שכבת זרע נמי סותר כל ז' ת\"ל (ויקרא טו, לב) לטמאה בה אין לך בה אלא מה שאמור בה סותרת יום אחד","אמר ליה גזירת הכתוב היא זיבה גמורה דלא ערבה בה שכבת זרע סותרת כל שבעה צחצוחי זיבה דערבה בה שכבת זרע לא סותרת אלא יום אחד","בעא מיניה ר' יוסי ברבי חנינא מרבי אלעזר דם יבש מהו (ויקרא טו, כה) כי יזוב זוב דמה אמר רחמנא עד דמידב דייב ליה לח אין יבש לא או דלמא האי כי יזוב זוב דמה אורחא דמילתא היא ולעולם אפילו יבש נמי","א\"ל תניתוה דם הנדה ובשר המת מטמאין לחים ויבשים אמר ליה לח ונעשה יבש לא קא מיבעיא לי כי מיבעיא לי יבש מעיקרא","הא נמי תניתוה המפלת כמין קליפה כמין שערה כמין עפר כמין יבחושין אדומין תטיל למים"],[[0,"כי פליגי בחתיכה","ודפלי פלויי דת\"ק סבר בבשרה למעוטי תוך חתיכה אבל דם הנראה בבקעים טמא דהא בבשרה קרינן בה ורבנן בתראי סברי אפי' פלי פלויי טהורה דאין זה דם נדה דאין דרכה של אשה לראות דם בחתיכה:"],[2,"אשה טהורה","דלאו ראייה היא ומיהו טיפת דם מטמאה טהרות אם נגעה בהן ואת האשה טומאת ערב משום דנגעה במקור דקרא מתורת ראייה מעטיה ולאו מטומאה:"],[2,"ורבנן סברי","דם נמי טהור והכי קאמר אין זה דם נדה (שתתן שום טומאה עליו) שאילו היה דם היה לו לטמאה כנדה ועכשיו אין לו שום טומאה אלא כחתיכת בשר בעלמא:"],[3,"הרואה קרי בקיסם","הכניס קיסם בפי אמה והוציא בו זרעו:"],[3,"ממנו","אשר תצא ממנו שכבת זרע:"],[4,"הוא עצמו","ואפילו בלא קיסם:"],[4,"אינו מטמא אלא בחתימת פי האמה","עד שיצא ממנו כדי חתימת פי אמתו והכא כיון דהכניס ליה קיסם בצר ליה שיעורא כדי קיסם:"],[5,"למימרא דנוגע הוי","מדיהיב שיעורא מכלל דטומאת קרי לאו משום ראייה היא אלא משום דבשר האבר נוגע בשכבת זרע היוצא ממנו ומשום הכי בעי שיעורא כטומאת כל מגעות דבעי שיעורא כגון שרץ ונבלה ומת דאי ראייה חשיבא ליה בטומאת ראייה לא בעיא שיעורא דהא נדה רואה היא ולא בעיא שיעורא:"],[5,"אל יסתור בזיבה","זב שפסק והתחיל למנות ז' ימי ספירו וראה קרי אל יסתור את מנינו כי היכי דאי נגע בשרץ לא סתר לספירת זיבתו:"],[6,"אלמה תניא זאת תורת הזב","הקיש הכתוב שכבת זרע לזיבה:"],[6,"מה זיבה סותרת","דכתיב וספרה לה ואחר תטהר אחר אחר לכולן שלא תהא טומאה מפסקת ביניהם אף שכבת זרע סותר:"],[7,"לפי שאי אפשר","לראות שכבת זרע הבאה מן הזב בלא טיפת צחצוחי זיבה דהשתא קצת זיבה דאית בה קא סתר:"],[9,"כל ז'","אם ראה בשביעי סותר כל אותן ימים שספר:"],[9,"אלא מה שאמור בה","בשכבת זרע לענין טומאה מה טומאתה יום אחד אף סתירתה אינה סותרת אלא אותו יום ואם ראה בז' אין צריך לספור עוד אלא יום א':"],[11,"דם יבש","כגון שיצא מגופה חתיכה של דם יבש:"],[11,"זוב דמה","משמע לח שהרי אין דרכו לזוב אלא לח:"],[12,"לח ונעשה יבש","דהא קתני מטמאין יבשין בנפל דם לח על הבגד ויבש ואחר כך נגע הדם בטהרות דומיא דיבש בשר המת דיבש מעיקרא בשר המת ליכא:"]],[[0,"","כי פליגי בחתיכה. פ\"ה ודפלי פלויי וקשה דא\"כ השתא אין דרך לראות דם בחתיכה פירוש שאינו דם נדות לא הוי כההוא דאין דרכה לראות בשפופרת דהתם הוי דם נדות מן המקור אלא שאין דרכה לראות באותו ענין ויש לומר דפליגי בחתיכה העשויה כמין שפופרת והוי חציצה בין דם לבשר דת\"ק מטמא דדרכה לצאת בענין זה ורבנן סברי אע\"ג דדם נדות הוא אין דרכה לראות בענין זה ואין זה דם נדות דקאמרי רבנן ה\"פ אין זה דם נדות שטימא הכתוב אבל בפלי פלויי גם רבנן מטמאין כיון דדם נדות הוא ונוגע בבשרה:"],[4,"","אלא בחתימת פי האמה. אין לפרש דבעי שיעור חתימת פי האמה כר\"ש דפ' אלו דברים (פסחים סז:) דסבר כר' נתן דבעי חתימת פי האמה בזב דכתיב (ויקרא טו) או החתים בשרו מזובו ואיתקש בעל קרי לזב דא\"כ מאי פריך למימרא דנוגע הוי אלא מעתה לא יסתור בזיבה הא כיון דאיתקש לזב שפיר יסתור והיכי דייק מינה דנוגע הוי [ועוד אי סבר כר' שמעון מאי פריך רב הונא ותיפוק ליה דהוא עצמו כו' והלא דרך קיסם יכול לראות הרבה מחתימת פי האמה] אלא נראה לפרש דסבר כדתנן לקמן בפרק יוצא דופן (נדה דף מ.) דזוב וקרי מטמאין בכל שהוא והכי קאמר צריך שיגע בחתימת פי האמה משום דטומאת בית הסתרים לא מטמאה לכך פריך כיון דנוגע הוי דקא מטהרת בקיסם עד שיגע בפי האמה מעתה לא יסתור בזיבה:"],[5,"","(למימרא דנוגע הוי). וא\"ת ומנליה למקשה דרב הונא לא מצריך שיעור חתימת פי האמה כרבי שמעון וי\"ל מדקאמר ותיפוק ליה דהוא עצמו אינו מטמא אלא בחתימת פי האמה ולא קאמר כשיעור חתימה ולא קאמר נמי דאיתקש לזב שמע מינה דלא לשיעור נקטיה אלא משום נגיעה ועוד אי סבר כרבי שמעון מאי פריך רב הונא ותיפוק ליה דהוא עצמו כו' והלא דרך קיסם יכול לראות קרי הרבה יותר מחתימת פי האמה וא\"ת ואם נוגע הוי א\"כ למ\"ד בפרק יוצא דופן (לקמן נדה דף מג:) לרואה ולנוגע בכל שהוא למה לי דכתב רחמנא רואה וי\"ל דעל ידי שנכתב רואה הא דדרשינן בפרק אלו דברים בפסחים (דף סו:) זב וכל זב לרבות בעל קרי שמשתלח חוץ לב' מחנות מוקמינן ברואה ולא בנוגע ונפקא מינה הא דאמר הכא דאפי' רואה אינו טמא אלא משום נוגע שאינו טמא אלא בנגיעה מבחוץ וא\"ת ומנלן דנוגע הוי נגמר מדאחמיר ביה רחמנא לענין שילוח מחנות אלמא רואה הוי וכה\"ג בעי למימר פרק יוצא דופן (לקמן נדה דף מב.) גבי פולטת שכבת זרע דרואה הוי מדאזהיר רחמנא על בעלי קריין בסיני וי\"ל דילפינן דנוגע הוי מדאיתקש לנוגע דנוגע מרבינן מאיש איש בפ' יוצא דופן (נדה דף מג:) ועוד דבההוא קרא גופיה איתקש נמי לשרץ וא\"ת ונוגע דכתב רחמנא למה לי תיפוק ליה מוהבגד אשר יהיה עליו שכבת זרע וי\"ל דאדם מבגד לא ילפינן שהרי נושא נבלת בהמה מטמא בגדים שעליו אפילו אם אינו לבוש בהן אבל אדם לא מטמא אפילו הוא עליו והכי איתא בפרק קמא דבבא בתרא (דף ט:) גבי עולא משגש אורחא דאימיה וא\"ת דלקמן בפרק יוצא דופן (נדה דף מב.) אמרינן לרבנן דרבי שמעון דאפילו פולטת שכבת זרע רואה הויא ולכך מטמא בפנים כבחוץ ור' שמעון נמי לא פליג אלא בפולטת שכבת זרע דלא מטמא בפנים כבחוץ אבל בבעל קרי משמע דרואה הוי דלא אשכחן דפליגי וי\"ל דרב הונא סבר כרבי שמעון דלדידיה אפי' בעל קרי נוגע הוי דאי רואה הוי אף בפולטת הוה דריש לטמא בפנים כבחוץ ואפילו לרבנן נמי אפשר דדוקא פולטת רואה הויא ומטמא בפנים כבחוץ משום דאשכחן בטומאת נדות וזיבות דמטמאה בפנים כבחוץ אבל בועלה דלא אשכחן ביה טומאה בפנים כבחוץ לא הוי רואה ומיהו ההיא דר' אליעזר ברבי שמעון פליגא דאמר בפרק יוצא דופן (נדה דף מג:) שכבת זרע לרואה במשהו ולנוגע בכעדשה מדמפליג משמע דסבר דרואה הוי אי נמי שאני התם דגמר טעמא מקרא:"],[5,"","אלא מעתה לא יסתור בזיבה. תימה תקשה ליה אמתני' דמסכת כלים (פ\"א מ\"א) דתנן אבות הטומאה השרץ והשכבת זרע ולא חשיב בעל קרי ותנן נמי בשלהי מסכת זבין בעל קרי כמגע שרץ אלמא נוגע הוי מדלא הוי אלא ראשון ושמא אפי' רואה נמי לא הוי אב הטומאה משום דרשא:"],[7,"","לפי שאי אפשר בלא צחצוחי זיבה. ומהאי טעמא מטמא ר' יהושע קרי של זב במשא והא דלא מצריך קרא התם כי הכא מפרש ר\"ח דהתם מיירי בשרואה זיבות בו ביום דאז יש בו רוב זיבות וסבר ר' יהושע דלא אפשר בלא צחצוחי זיבה בעין ורבי אליעזר דפליג עליה בכיצד הרגל (ב\"ק דף כה.) ואמר דאינו מטמא במשא מודה דאי אפשר בלא ציחצוחי זיבה ואפילו הכי לא מטמא במשא דכיון דפתיכא ביה שכבת זרע והכא נמי אי לאו קרא לא הוה סותר אפילו יום אחד:"]]],[["אם נמוחו טמאה אי הכי בלא נמוחו נמי אמר רבה כי לא נמוחו בריה בפני עצמה היא","ומי איכא כי האי גוונא אין והתניא א\"ר אלעזר בר' צדוק שני מעשים העלה אבא מטבעין ליבנה","מעשה באשה שהיתה מפלת כמין קליפות אדומות ובאו ושאלו את אבא ואבא שאל לחכמים וחכמים שאלו לרופאים ואמרו להם אשה זו מכה יש לה בתוך מעיה שממנה מפלת כמין קליפות תטיל למים אם נמוחו טמאה","ושוב מעשה באשה שהיתה מפלת כמין שערות אדומות ובאה ושאלה את אבא ואבא שאל לחכמים וחכמים לרופאים ואמרו להם שומא יש לה בתוך מעיה שממנה מפלת כמין שערות אדומות תטיל למים אם נמוחו טמאה","אמר ריש לקיש ובפושרין תניא נמי הכי תטיל למים ובפושרין רשב\"ג אומר ממעכתו ברוק על גבי הצפורן מאי בינייהו אמר רבינא מעוך על ידי הדחק איכא בינייהו","התם תנן כמה היא שרייתן בפושרין מעת לעת הכא מאי מי בעינא מעת לעת או לא","שרץ ונבלה דאקושי בעינן מעת לעת אבל דם דרכיך לא או דלמא לא שנא תיקו","המפלת כמין דגים וליפלוג נמי רבי יהודה בהא","אמר ריש לקיש במחלוקת שנויה ורבנן היא ורבי יוחנן אמר אפילו תימא רבי יהודה עד כאן לא קאמר רבי יהודה התם אלא גבי חתיכה דעביד דם דקריש והוי חתיכה אבל בריה לא הוי","ולהך לישנא דא\"ר יוחנן באי אפשר לפתיחת הקבר בלא דם קמיפלגי לפלוג נמי ר' יהודה בהא","מאן דמתני הך לישנא מתני הכי רבי יוחנן וריש לקיש דאמרי תרוייהו במחלוקת שנויה ורבנן היא","המפלת כמין בהמה [וכו']","אמר רב יהודה אמר שמואל מ\"ט דר' מאיר הואיל ונאמרה בו יצירה כאדם","אלא מעתה המפלת דמות תנין תהא אמו טמאה לידה הואיל ונאמר בו יצירה כאדם שנאמר (בראשית א, כא) ויברא אלהים את התנינים הגדולים","אמרי דנין יצירה מיצירה ואין דנין בריאה מיצירה","מאי נפקא מינה הא תנא דבי רבי ישמעאל (ויקרא יד:לט) ושב הכהן (ויקרא יד, מד) ובא הכהן זו היא שיבה זו היא ביאה","ועוד נגמר בריאה מבריאה דכתיב (בראשית א:כז) ויברא אלהים את האדם בצלמו","אמרי ויברא לגופיה וייצר לאפנויי ודנין יצירה מיצירה","אדרבה וייצר לגופיה ויברא לאפנויי ודנין בריאה מבריאה","אלא וייצר מופנה משני צדדין מופנה גבי אדם ומופנה גבי בהמה ויברא גבי אדם מופנה גבי תנינים אינו מופנה","מאי מופנה גבי בהמה אילימא מדכתיב (בראשית א:כה) ויעש אלהים את חית הארץ וכתיב (בראשית ב ) ויצר [ה'] אלהים מן האדמה כל חית השדה גבי תנין נמי אפנויי מופנה דכתיב (בראשית א:כה) ואת כל רמש האדמה וכתיב (בראשית א:כא) ויברא אלהים את התנינים הגדולים","רמש דכתיב התם דיבשה הוא ומאי נפקא מינה בין מופנה מצד אחד למופנה משני צדדין","נפקא מינה דאמר רב יהודה אמר שמואל משום רבי ישמעאל כל גזרה שוה שאינה מופנה כל עיקר אין למדין הימנה מופנה מצד אחד לרבי ישמעאל למדין ואין מושיבין לרבנן למדין ומשיבין מופנה משני צדדין דברי הכל למדין ואין משיבין","ורבי ישמעאל מאי איכא בין מופנה מצד אחד למופנה משני צדדין נפקא מינה דהיכא דאיכא מופנה מצד אחד ומופנה משני צדדין שבקינן מופנה מצד אחד"],[[0,"אם נמוחו טמאין","דדם הוא. אלמא אע\"ג דכי חזיתיה יבש היה כעפר:"],[0,"בריה בפני עצמה","ולא דם:"],[1,"כי האי גוונא","מפלת כמין שערות וקליפות:"],[1,"מטבעין","שם העיר:"],[2,"קליפות","גלדי המכה:"],[3,"","דרך שומא להיות בה שער:"],[4,"ובפושרין","דאי בדק בצונן ולא נימוח לא מטהרינן לה בהכי דדילמא אי היה בפושרין הוה נימוח:"],[4,"מאי בינייהו","מאי פלוגתייהו:"],[4,"ע\"י הדחק","לת\"ק אי נימוח מאליו הוא דהוי דם אבל נימוח על ידי מיעוך לאו דם הוא ולרבן שמעון אפילו נימוח ע\"י מיעוך נמי דם הוא:"],[5,"כמה היא שרייתן","בפ' דם הנדה השרץ והנבלה מטמאין לחין ואין מטמאין יבשין ואם יכולין להשרות ולחזור לכמות שהוא טמאין וכמה היא שרייתן כו':"],[6,"דאקושי","קשים:"],[6,"לא","בעינן מעת לעת אלא או יום או לילה ואם לא נמוחו טהורים:"],[7,"וליפלוג נמי ר' יהודה בהא","ונימא בין כך ובין כך טמאה דהא טעמא דר' יהודה אוקמינן דאי אפשר לפתיחת הקבר בלא דם:"],[8,"במחלוקת שנויה","משנה זו שנויה במחלוקת דלאו סתמא ודברי הכל היא אלא ר' יהודה פליג:"],[8,"והוי חתיכה","דטעמא לאו משום פתיחת הקבר בלא דם הוא אלא בחתיכה עצמה סבירא ליה דהויא דם וכגון שהיא מארבעה מיני דמים:"],[9,"ולהך לישנא כו'","כדאמרן לעיל בשמעתין:"],[12,"יצירה","ויצר ה' אלהים (את חית השדה ואת) עוף וגו' וכתיב באדם וייצר ה' אלהים את האדם עפר מן האדמה ורבנן לית להו גזירה שוה:"],[13,"תנין","דג גדול. ואמאי תנן המפלת מין דגים טהורה:"],[15,"זו היא שיבה זו היא ביאה","כלומר ילפינן גזרה שוה משיבה לביאה כמו דהוו תרוייהו שיבה או תרוייהו ביאה מה שיבה חולץ וקוצה וטח כו':"],[16,"ועוד","גבי אדם נמי כתיב בריאה דכתיב ויברא אלהים את האדם בצלמו ונילף בריאת דגים מבריאת אדם:"],[16,"ויברא","דאדם לגופיה:"],[17,"וייצר לאפנויי","לגזירה שוה ודנין ג\"ש לחיה ולעוף דכתיב בהו יצירה דדמי מדדמי:"],[19,"מופנה","גבי אדם דהא כתיב ויברא:"],[19,"ומופנה גבי בהמה","כדמפרש דהא כתיב ויעש אלהים את חית השדה וגו':"],[19,"גבי אדם מופנה","דהא כתיב וייצר:"],[19,"גבי תנין לאו מופנה","דלא כתיב קרא אחרינא:"],[20,"ופרכינן גבי תנין נמי מופנה הוא","דכתיב בקרא דויעש ואת כל רמש האדמה:"],[21,"ומאי נפקא מינה","דניחא לך למילף משני צדדין טפי:"],[22,"כל ג\"ש שאינה מופנה כל עיקר אין למדין הימנה","ואפילו אין להשיב:"],[22,"אין משיבין","ואפי' יש להשיב:"],[22,"לרבנן למדין","הימנה אם אין להשיב ואם יש להשיב משיבין. והך פלוגתא דרבי ישמעאל ורבנן שמואל גמרא גמיר ליה מרביה וכאן הוא מקומה ואינה לא במשנה ולא בברייתא:"]],[[0,"","אם נמוחו טמאה. וא\"ת והא לא מיקרי יבש דהא הנך דתנן בפ' דם הנדה (לקמן נדה דף נד:) דמטמאין לחים ואינן מטמאין יבשים תני התם אם יכולים לשרות ולחזור לכמות שהיו מטמאין כדאמר התם ויש לומר דמכל מקום פשיט שפיר דלא אמר כי יזוב זוב דמה דמידב דייב אי נמי התם איירי בלחים ונתייבשו ולהכי אע\"ג דנתייבשו כיון שיכולין לחזור לכמות שהיו מטמאין אבל הכא בלחים ונתייבשו לא קמיבעיא ליה אלא ביבש מעיקרו ואפילו אם יכול להיות נימוח במים:"],[6,"","אבל דם דרכיך לא. וא\"ת והא דם הנדה נמי קתני לקמן בהדי אידך דפרק דם הנדה (נדה דף נד:) וי\"ל דהתם מיירי בדם הנדה שנפל על הבגד ונתייבש ביותר אבל דם הנדה באפי נפשיה הוי רכיך וע\"ק דהתם קתני רוק וזוב וניעו דרכיכי וי\"ל דמ\"מ אקושי נינהו טפי מדם דאינהו התחילו ליבש זה כמה ימים דרגילין להתייבש קודם יציאתם אבל דם אינו רגיל להתייבש קודם יציאתו מן הרחם:"],[6,"","או דלמא לא שנא. תימה דבפרק דם הנדה (לקמן נדה דף נו.) תניא רשב\"ג אומר בפושרין מעת לעת ואמאי לא אשמועינן רבותא טפי דאפי' לא יחזור ע\"י פושרין מעת לעת אלא על ידי מיעוך טמא לרשב\"ג דהא אפי' לגבי דם חשיב מיעוך כל שכן בנבלה ושרץ דאקושי דע\"כ ע\"י מיעוך נימוח טפי מפושרין דהא אפילו את\"ל דרבנן בעו מעת לעת במיעוך ע\"י הדחק לא חשיב דם לרבנן:"],[7,"","ליפלוג נמי רבי יהודה בהא. אשערה וקליפה לא פריך דליפלוג רבי יהודה דמועטין נינהו ולא שייך בהו פתיחת קבר:"],[12,"","הואיל ונאמרה בהו יצירה. אף על גב דבבהמה לא כתיב בה יצירה הא אמרי' בבהמה המקשה (חולין דף עא.) דבהמה טהורה בכלל חיה טהורה ליצירה:"],[13,"","המפלת דמות תנין. הוה מצי למנקט דגים סתמא דבקרא דויברא את התנינים כתיב נמי כל נפש חיה הרומשת אשר שרצו המים אלא נקט תנין לפי שהוא סמוך לויברא:"],[15,"","זו היא שיבה זו היא ביאה. וא\"ת אמאי לא משני ה\"מ היכא דליכא דדמי ליה כו' וליכא למימר דה\"פ דלילף תרוייהו יצירה ובריאה לטמא בהמה ודגים דע\"כ לא נתקבלה ג\"ש אלא חדא מינייהו מדקאמר לקמן שבקינן מופנה מצד אחד וילפינן ממופנה מב' צדדים וי\"ל דעיקר קושיא אועוד סמיך:"],[21,"","התם ביבשה כתיב. תימה וכי לא ידע דביבשה כתיב דקרא דתנינים כתיב בחמישי והאי בששי:"]]],[["וילפינן מופנה משני צדדין ולהכי אפניה רחמנא לבהמה משני צדדין כי היכי דלא נגמר מן מופנה מצד אחד","רב אחא בריה דרבא מתני לה משמיה דרבי אלעזר לקולא כל גזרה שוה שאינה מופנה כל עיקר למדין ומשיבין מופנה מצד אחד לרבי ישמעאל למדין ואין משיבין לרבנן למדין ומשיבין מופנה משני צדדין דברי הכל למדין ואין משיבין","ולרבנן מאי איכא בין מופנה מצד אחד לשאינה מופנה כל עיקר","נ\"מ היכא דמשכחת לה מופנה מצד אחד ושאינה מופנה כל עיקר ולאו להאי אית ליה פירכא ולאו להאי אית ליה פירכא שבקינן שאינה מופנה כל עיקר וגמרינן ממופנה מצד אחד","והכא מאי פירכא איכא משום דאיכא למיפרך מה לאדם שכן מטמא מחיים","וכן א\"ר חייא בר אבא א\"ר יוחנן היינו טעמא דר\"מ הואיל ונאמרה בו יצירה כאדם","א\"ל רבי אמי אלא מעתה המפלת דמות הר אמו טמאה לידה שנאמר (עמוס ד:יג) כי הנה יוצר הרים ובורא רוח אמר ליה הר מי קא מפלת אבן היא דקא מפלת ההוא גוש איקרי","אלא מעתה המפלת רוח תהא אמו טמאה לידה הואיל ונאמרה בו בריאה כאדם דכתיב (עמוס ד ) ובורא רוח וכי תימא לא מופנה מדהוה ליה למכתב יוצר הרים ורוח וכתיב ובורא רוח ש\"מ לאפנויי","א\"ל דנין דברי תורה מדברי תורה ואין דנין דברי תורה מדברי קבלה","(אמר) רבה בר בר חנה אמר רבי יוחנן היינו טעמא דר\"מ הואיל ועיניהם דומות כשל אדם","אלא מעתה המפלת דמות נחש תהא אמו טמאה לידה הואיל וגלגל עינו עגולה כשל אדם וכי תימא הכי נמי ליתני נחש","אי תנא נחש הוה אמינא בנחש הוא דפליגי רבנן עליה דר\"מ דלא כתיב ביה יצירה אבל בהמה וחיה לא פליגי דכתיבא ביה יצירה","והא גבי מומין קתני לה את שגלגל עינו עגול כשל אדם לא קשיא הא באוכמא הא בציריא","רבי ינאי אמר היינו טעמא דר\"מ הואיל ועיניהם הולכות לפניהם כשל אדם והרי עוף דאין עיניו הולכות לפניו וקאמר ר\"מ דטמא אמר אביי בקריא וקיפופא ובשאר עופות לא","מיתיבי ר' חנינא בן (אנטיגנוס) אומר נראין דברי ר\"מ בבהמה וחיה ודברי חכמים בעופות","מאי עופות אילימא בקריא וקיפופא מ\"ש בהמה וחיה דעיניהן הולכות לפניהן כשל אדם קריא וקיפופא נמי","אלא פשיטא בשאר עופות מכלל דר\"מ פליג בשאר עופות","חסורי מיחסרא והכי קתני ר' חנינא בן אנטיגנוס אומר נראין דברי ר\"מ בבהמה וחיה והוא הדין לקריא וקיפופא ודברי חכמים בשאר עופות שאף ר\"מ לא נחלק עמהם אלא בקריא וקיפופא אבל בשאר עופות מודי להו","והתניא א\"ר אלעזר בר' צדוק המפלת מין בהמה וחיה לדברי ר\"מ ולד ולדברי חכמים אינו ולד ובעופות תיבדק","למאן תיבדק לאו לדברי ר\"מ דאמר קריא וקיפופא אין שאר עופות לא","אמר רב אחא בריה דרב איקא לא תיבדק לרבנן דאמרי קריא וקיפופא אין שאר עופות לא","ומ\"ש קריא וקיפופא מבהמה וחיה הואיל ויש להן לסתות כאדם","בעא מיניה רבי ירמיה מר' זירא לר\"מ דאמר בהמה במעי אשה ולד מעליא הוא קבל בה אביה קידושין מהו למאי נפקא מינה לאיתסורי באחותה","למימרא דחיי והאמר רב יהודה אמר רב לא אמרה ר\"מ אלא הואיל ובמינו מתקיים אמר רב אחא בר יעקב עד כאן הביאו רבי ירמיה לר' זירא לידי גיחוך ולא גחיך","גופא אמר רב יהודה אמר רב לא אמרה רבי מאיר אלא הואיל ובמינו מתקיים אמר רב ירמיה מדפתי"],[[0,"להכי אפנייה רחמנא כו'","כרבנן:"],[0,"דלא תגמר ממופנה מצד אחד","משום דמשיבין וכאן יש להשיב מה לאיש שכן מטמא מחיים כדלקמיה:"],[1,"לקולא","דלא בעינן מופנה כולי האי:"],[1,"לרבנן","כיון דלמופנה מצד אחד למדין ומשיבין ולשאינו מופנה כל עיקר אמרינן דברי הכל למדין ומשיבין מאי איכא בין מופנה מצד אחד לשאינה מופנה כל עיקר:"],[4,"והכא מאי פירכא איכא","כלומר והכא בג\"ש דתני אאדם מה תשובה איכא דקאמרת דניחא לך למיגמר מחיה דהוי מופנה משני צדדין משום דאין משיבין ולא נגמר בריאה בריאה מתנין משום דמופנה מצד אחד הוא ומשיבין ומאי אית לך לאותובי:"],[4,"שכן מטמא מחיים","מקבל טומאה בחייו משרץ או משאר טומאות דין הוא שתהא יולדתו טמאה לידה תאמר באלו הלכך גבי דגים פרכינן ליה דמופנה מצד אחד הוא אבל גבי בהמה אע\"ג דפירכא היא לא פרכינן לה הואיל ומופנה היא משני צדדין:"],[5,"וכן אמר רבי חייא כו'","אדרב יהודה אמר שמואל קאי:"],[6,"הר מי קמפלת","מי מפלת נפל גדול כהר:"],[6,"דמות אבן הוא דמפלת","חתיכת בשר דמות אבן גוש בעלמא מיקרי ולא כתיבא ביה יצירה:"],[6,"גוש","כמו (איוב ז) גוש עפר:"],[9,"הואיל ועיניהן","של חיה ובהמה:"],[9,"דומות לשל אדם","שחור שבעין הוה עגול בבהמה כשל אדם אבל דדגים לאו עגול הוא:"],[12,"והא גבי מומין תני לה","כלומר היכי אמרת דעין בהמה דומה לאדם והא גבי מומי הבכור קתני לה בבכורות (דף מ.) ושגלגל עינו הוי מום ומדחשיב ליה מום נמצא שאין דרך בהמה להיות עיניה כאדם:"],[12,"באוכמא","שחור שבעין הוי עגול בבהמה כאדם והא דתני דהוי מום בציריא מקום מושב כל העין לא הוי עגול בבהמה כאדם ואי הוי עגול הוי מום דכל בור של מושב העין קרוי גלגל כדאמרי' לקמן (נדה דף כד:) ועמדתי בגלגל עינו של מת עד חוטמי ומפני שהוא עגול כגלגל:"],[13,"לפניהם","לאפוקי דגים דעיניהם בצדיהם וכן נחש:"],[15,"קריא וקיפופא","עוף הצועק בלילה ופניו דומה לחתול ועיניו לפניו:"],[17,"חסורי מיחסרא והכי קתני נראין דברי ר\"מ בבהמה ובחיה והוא הדין לקריא וקיפופא","דעיניו הולכו' לפניו ואע\"פ דפליגי רבנן עליה:"],[17,"ודברי חכמים","נראין לר\"מ בשאר עופות דר\"מ נמי מודה להו:"],[18,"והתניא","בניחותא:"],[21,"ומאי שנא קריא וקיפופא","דקאמר לרבנן דהוי ולד טפי משאר עופות אי משום דעיניהם הולכות לפניהם הרי חיה ובהמה נמי דעיניהן הולכות לפניהם ופליגי רבנן:"],[21,"לסתות","לחיים זקופין כאדם מה שאין כן בבהמה ובחיה:"],[23,"למימרא דחיי","הא אחותה לא מיתסרא אלא בחייה דאין איסור אחות אשה אלא בחייה:"],[23,"ובמינו","כגון בהמה גמורה מתקיימת ובמינו הוא דמתקיים אבל איהו לא:"],[23,"לידי גיחוך","שחוק. בכל תחבולות הללו עסק ר' ירמיה להביא ר' זירא לידי שחוק ולא שחק דאסור לאדם שימלא פיו שחוק ור' זירא מחמיר טפי:"]],[[0,"","וילפינן ממופנה משני צדדין. תימה ולשתוק מהפנאה דאדם דהשתא תנין לא מופנה כלל ובהמה מופנה בצד אחד ואין משיבין:"],[6,"","יוצר הרים. ומופנה הוא כדקאמר בסמוך:"],[10,"","ליתני נחש. ואע\"ג דקתני חיה ונחש בכלל חיה כדכתיב (בראשית ג׳:א׳) והנחש היה ערום מכל חית השדה לאחר שנקצצו רגליו לא מיקרי חיה סתם אלא חיה הרומשת ולא הוי בכלל חיה דמתניתין:"],[17,"","קריא וקיפופא. ג' מיני קיפוף יש הכוס והינשוף (ויקרא יא) מתרגמינן קריא וקיפופא והתנשמת נמי אמר באלו טריפות (חולין דף סג.) זה באות שבעופות ואמר אביי באות שבעופות קיפוף ועוד קיפוף מין חיה כדאמר בהרואה (ברכות נז:) כל מיני חיה יפין לחלום חוץ מן הקוף והקיפוף:"],[22,"","לאיתסורי באחותה. לענין גופה לא בעי אם הבא עליה חייב משום אשת איש או אם חייב ההורגה דפשיטא ליה דאינה חיה ג' שנים שתהא בת ביאה ולא שנה שלא תהא טרפה ומיהו הוה מצי למבעי אם הרובע חייב סקילה כדין הבא על הבהמה:"],[23,"","הואיל ובמינו מתקיים. אע\"פ דדריש ג\"ש דיצירה בעי טעמא הואיל ובמינו מתקיים דאפילו בולד גמור בעינן מתקיים למעוטי נולד חתיכה או חסרה וא\"ת והא גופו תייש ופניו אדם דאינו מתקיים ואמרינן בסמוך דכ\"ע אדם הוי וי\"ל דאע\"ג דלא חיי לא בבהמה ולא באשה מ\"מ גופו תייש כתיקונו ופניו אדם כתיקונו ואינו חסר מאומה:"]]],[["אף אנן נמי תנינא המפלת כמין בהמה חיה ועוף (ולד מעליא הוא) דברי ר\"מ וחכ\"א עד שיהא בו מצורת אדם","והמפלת סנדל או שליא או שפיר מרוקם והיוצא מחותך הבא אחריו בכור לנחלה ואינו בכור לכהן ואי ס\"ד דחיי הבא אחריו בכור לנחלה מי הוי","אמר רבא לעולם דחיי ושאני התם דאמר קרא (דברים כח ) ראשית אונו מי שלבו דוה עליו יצא זה שאין לבו דוה עליו","בעא מיניה רב אדא בר אהבה מאביי לרבי מאיר דאמר בהמה במעי אשה ולד מעליא הוא אדם במעי בהמה מאי למאי נפקא מיניה לאשתרויי באכילה","ותפשוט ליה מהא דר' יוחנן דא\"ר יוחנן השוחט את הבהמה ומצא בה דמות יונה אסורה באכילה","הכי השתא התם לא פרסות איכא ולא פרסה איכא הכא נהי דפרסות ליכא פרסה מיהא איכא","וחכ\"א כל שאין בו כו' אמר רב ירמיה בר אבא אמר רב הכל מודים גופו תייש ופניו אדם אדם גופו אדם ופניו תייש ולא כלום","לא נחלקו אלא שפניו אדם ונברא בעין אחת כבהמה שרבי מאיר אומר מצורת אדם וחכ\"א כל צורת אדם","אמר לו לרב ירמיה בר אבא והא איפכא תניא ר\"מ אומר כל צורת וחכ\"א מצורת אמר להו אי תניא תניא","אמר ר' ירמיה בר אבא אמר רבי יוחנן מצח והגבינים והעינים והלסתות וגבות הזקן עד שיהו כולם כאחד רבא אמר חסא מצח והגבן והעין והלסת וגבת הזקן עד שיהו כולם כאחת","ולא פליגי הא כמ\"ד כל צורת הא כמ\"ד מצורת","מיתיבי צורת פנים שאמרו אפילו פרצוף אחד מן הפרצופין חוץ מן האוזן למימרא דמחד נמי סגי","אמר אביי כי תניא ההיא לעכב תניא וכמ\"ד כל צורת ואיבעית אימא לעולם כמ\"ד מצורת ומאי אחד אחד אחד","אמר רבא נברא בעין אחת ובירך אחד מן הצד אמו טמאה באמצע אמו טהורה","אמר רבא ושטו נקוב אמו טמאה ושטו אטום אמו טהורה","ת\"ר המפלת גוף אטום אין אמו טמאה לידה ואיזהו גוף אטום רבי אומר כדי שינטל מן החי וימות","וכמה ינטל מן החי וימות רבי זכאי אומר"],[[0,"אף אנן נמי תנינא","דלא חיי:"],[0,"המפלת מין בהמה וחיה ועוף דברי ר\"מ","רישא במסכת בכורות (דף מו.) והכי קתני יש בכור לנחלה ואין בכור לכהן וקא חשיב ואזיל המפלת מין בהמה וחיה ועוף הבא אחריו בכור לנחלה דהאי לאו בכור הוא לגבי נחלה דלא חיי:"],[0,"וחכ\"א עד שיהיה בו מצורת אדם","אינו פוטר את הבא אחריו מבכורת כהן:"],[1,"אין בכור לכהן","שהרי זה פטר את הרחם:"],[1,"סנדל","צורה פחותה שאין צורת פניו ניכרת שאין סנדל בלא ולד אחר ומתוך דוחק חבירו הוא נמעך כדמפרש בפירקין (לקמן נדה דף כה:) משל לאדם שסטר את חבירו והחזיר צורתו לאחוריו. ואם יוצא סנדל ראשון פוטר את אחיו מפדיון כהן:"],[1,"או שליא","דאין שליא בלא ולד ופוטר את הבא אחריו לאחר זמן:"],[1,"שפיר","עור דפוס הולד:"],[1,"מרוקם","שכבר אבריו ניכרין קצת ולקמן בפירקין (שם.) מפרש לה:"],[1,"הבא אחריו","אחר כל אלה:"],[1,"בכור לנחלה","דהני לאו בני נחלה נינהו דלא חיי:"],[2,"מי שלבו דוה עליו","לב אביו מתאבל על מותו הוא דחשיב לענין נחלה:"],[3,"אדם במעי בהמה","שחטה ומצא בה דמות אדם מהו מי אמרינן כי היכי דאזיל ר\"מ בתר אימיה הכי נמי זיל בתר בהמה ושרי לאכילה:"],[5,"עוף אין לו פרסה","אבל אדם נהי דפרסות ליכא שאין פרסותיו סדוקות שאין לו שני עקבים כמו לבהמה:"],[5,"פרסה מיהא איכא","וכתיב (ויקרא י״א:ג׳) כל מפרסת פרסה בבהמה תאכלו דאם נמצא תוך מעי בהמה קלוט כל זמן שלא יצא לאויר העולם אע\"ג דאין לו אלא פרסה אוכלו ואפילו לר\"ש דאמר קלוט בן פרה אסור מודה הוא דאם נשחטה אמו ונמצא במעיה דמותר והכי מפרש בפרק בהמה המקשה (חולין סח:):"],[6,"גופו תייש ופניו אדם אדם הוא","דבתר צורת פנים אזלינן:"],[7,"בעין אחד כבהמה","אחת מעיניו דומה לבהמה:"],[7,"ה\"ג רבי מאיר אומר מצורת וחכ\"א כל צורת","שרבי מאיר אומר כיון שיש בו מצורת אדם הוי ולד ואע\"ג דאין כל צורתו כצורת אדם:"],[8,"והא איפכא תניא","שר\"מ אומר כל צורת והאי כל צורת דר\"מ הכי קאמר כל שהוא צורת אדם שבו הוי ולד ואפילו כל פניו תייש אלא שנברא בעין אחת או בלסת אחת הדומה לאדם:"],[8,"וחכ\"א מצורת","עד שיהיה בו מקצת צורה ניכרת כגון חצי הפרצוף דומה לאדם:"],[8,"אי תניא תניא","שמעתי אני מרב מה שאמרתי אבל אתם הואיל ויש משנה בידכם לכו אחריה:"],[9,"הגבינים","גבות עינים שורצי\"ל. וגבות הזקן סנטר שקורין מנטו\"ן:"],[9,"עד שיהיו כולם כאחד","לרבנן כדמפרש בסמוך דר' ירמיה כרבנן וכדפירשה רב לפלוגתא דרב תנא הוא ופליג ולא הדר ביה ממאי דאמר לרבנן דבעו כל צורת האדם והא דקחשיב ר' ירמיה ואזיל הא קמ\"ל דאפילו לרבנן אאזנים לא קפדינן והא דחסא נמי כרבנן ואליבא דתנא דברייתא דאמר לא בעי אלא מצורת וקמ\"ל דבחד צד בעי צורות שלמות ואאוזן לא קא קפיד:"],[11,"אפילו פרצוף אחד","אבר אחד כגון עינו או מצחו או לסת אחד דדומה לאדם הוי ולד:"],[11,"חוץ מן האזנים","אזניו כשל אדם ושאר צורתו כבהמה לא חשיב פרצוף. אלמא למ\"ד מצורת בחד סגי וקשיא לרבא דאמר חסא:"],[12,"אמר אביי כי תניא ההיא לעכב תניא","כלומר צורת פנים שאמרו חכמים דמעכבים אפילו אבר אחד כבהמה מעכבא חוץ מן האוזן דלא מעכבא וכמ\"ד לרבנן כל צורת מתוקמא ואע\"ג דמצי לאוקמי כדאיתא וכדר\"מ דאמר כל דהו צורת ניחא ליה לאוקומי כרבנן:"],[12,"ואיבעית אימא לעולם כמ\"ד מצורת","ולא קשיא לחסא:"],[12,"ומאי אחד אחד אחד","כלומר מכל ראשי איברים יהיה אחד דומה לאדם כחסא דאמר העין והלסת כו' וכמ\"ד מצורת:"],[13,"מן הצד","שעינו בצדו וירכו בצדו כשאר בני אדם:"],[14,"ושטו נקוב אמו טמאה","קסבר טרפה חיה:"],[14,"ושטו אטום","סתום:"]],[[4,"","ומצא בה דמות יונה. וא\"ת ודילמא לרבנן ולא לר\"מ וי\"ל דא\"כ ה\"ל לר' יוחנן למימר לרבנן מצא בה דמות יונה כו' א\"נ י\"ל דלא מיבעיא ליה אלא לר\"מ דבדבר קל עושהו ולד בהמה במעי אדם ואדם במעי בהמה נמי קרוי ולד או לא אבל לרבנן פשיטא ליה דשרי דלא מיקרי ולד אלא אדם במעי אשה ומייתי ראיה מר' יוחנן דאמר אסורה אפילו לרבנן וכ\"ש לרבי מאיר:"],[7,"","שר\"מ אומר מצורת. פי' בקונטרס מקצת כל צורת עין ולסת וגבת וזקן וחכ\"א כל צורת משני צדדים ב' עינים כו' ואע\"ג דלר' מאיר כי לא דמי כלל לאדם טמאה לידה משום דכתיב בהם יצירה כי דמי לאדם בעי שיהא דומה לו במקצת כל היצירה והא פלוגתא דייק מדתנן וחכ\"א כל שאין בו מצורת אדם ולא קתני וחכ\"א אינו ולד מכלל דפליגי נמי בולד שמקצתו אדם ומקצתו בהמה דלר\"מ במקצת כל צורתו קרוי ולד ולרבנן בעיא כל הצורה והא דקתני במתני' מצורת לר\"מ קאמר לדידן בעינן כל צורת לדידך אודי לן מיהא דמקצת צורה בעינן:"],[8,"","והתניא איפכא ר\"מ אומר כל צורה. פ\"ה כל שהוא אפילו עין אחד בלא לסת וגבינין וחכ\"א מצורת כל חצי הצורה וקשה לפירושו דכל צורה דרב ודברייתא אינן שוין ועוד דבהא תניא איפכא לא הוה איפכא ממש ועוד דרב ור' יוחנן דבסמוך פליגי אברייתא וארבי יוחנן ליכא למימר תנא הוא ופליג כמו ארב כדמשמע פ\"ק דכתובות (דף ח.) גבי (אין ברכת) חתנים מן המנין ועוד קשה לפירושו דרבא אמר חסא כרבנן דברייתא וא\"כ כי פריך ליה מברייתא דצורת פנים שאמרו אפילו פרצוף אחד לישני ליה דאתא כר\"מ דברייתא כיון דס\"ל כברייתא דהשתא כי משני ליה אביי כי תניא ההיא לעכב מוקי לה כרב והוא לא ס\"ל הכי ונראה לפרש והתניא איפכא ממש שר\"מ אומר כל צורה דבעיא ב' עינים ולסתות דגרוע מכולה בהמה דהתם יצירה כתיב ורבנן אמרי מצורת חצי צורה והשתא רבי יוחנן דאמר המצח והגבינים והעינים כר\"מ דברייתא ורבא אמר חסא כרבנן ופריך ליה מברייתא ואוקי לה כר\"מ ור\"ח גריס בדברי רב ר\"מ אומר כל צורת וחכ\"א מצורת כמו במתניתין ובברייתא איפכא:"],[14,"","אמר רבא ושטו נקוב אמו טמאה לידה. קסבר טרפה חיה וכן בפ\"ק דתמורה (דף יא:) גבי רגל של זו עולה (או) כולה עולה דקאמר רב חסדא דבדבר שעושה אותה טרפה כולה עולה דטרפה אינה חיה ורבא אמר דוקא דבר שעושה אותה נבלה כולה עולה דטרפה חיה ובפ\"ק דבכורות (דף ג.) פלוגתא איפכא גבי מקצת לעובד כוכבים מקצתה להפקיע מן הבכורה דרב חסדא אמר דבר שעושה אותה נבלה דטרפה חיה ורבא אמר דבר שעושה אותה נמי טריפה דטרפה אינה חיה ואומר ר\"ת דהוי כאיכא דאמרי:"]]],[["עד הארכובה רבי ינאי אומר עד לנקביו ר' יוחנן אומר משום רבי יוסי בן יהושע עד מקום טבורו","בין רבי זכאי לרבי ינאי איכא בינייהו טרפה חיה מר סבר טרפה חיה ומר סבר טרפה אינה חיה","בין ר' ינאי לר' יוחנן איכא בינייהו דר\"א דאמר רבי אלעזר ניטל ירך וחלל שלה נבלה","אמר רב פפא מחלוקת מלמטה למעלה אבל מלמעלה למטה אפי' כל דהו טהורה וכן אמר רב גידל אמר רבי יוחנן המפלת את שגולגלתו אטומה אמו טהורה","ואמר רב גידל אמר רבי יוחנן המפלת כמין אפקתא דדיקלא אמו טהורה","איתמר המפלת מי שפניו מוסמסים רבי יוחנן אמר אמו טמאה ר\"ל אמר אמו טהורה","איתיביה ר' יוחנן לריש לקיש המפלת יד חתוכה ורגל חתוכה אמו טמאה לידה ואין חוששין שמא מגוף אטום באתה ואם איתא ליתני שמא מגוף אטום או ממי שפניו מוסמסין","אמר רב פפי בפניו מוסמסין כולי עלמא לא פליגי דטמאה כי פליגי בפניו טוחות ואיפכא איתמר רבי יוחנן אמר אמו טהורה וריש לקיש אמר אמו טמאה","ולותביה ר\"ל לרבי יוחנן מהא משום דשני ליה היינו גוף אטום היינו מי שפניו טוחות","בני רבי חייא נפיק לקרייתא אתו לקמיה דאבוהון אמר להם כלום בא מעשה לידכם אמרו לו פנים טוחות בא לידינו וטימאנוה","אמר להם צאו וטהרו מה שטמאתם מאי דעתייכו לחומרא חומרא דאתיא לידי קולא היא דקיהביתו לה ימי טוהר","איתמר המפלת בריה שיש לה ב' גבים וב' שדראות אמר רב באשה אינו ולד בבהמה אסור באכילה ושמואל אמר באשה ולד בבהמה מותר באכילה","במאי קמיפלגי בדרב חנין בר אבא דאמר רב חנין בר אבא השסועה בריה שיש לה ב' גבין וב' שדראות","רב אמר בריה בעלמא ליתא וכי אגמריה רחמנא למשה במעי אמה אגמריה ושמואל אמר בריה בעלמא איתא וכי אגמריה רחמנא למשה בעלמא אגמריה אבל במעי אמה שריא","איתיביה רב שימי בר חייא לרב רבי חנינא בן אנטיגנוס אומר כל שיש לו ב' גבין ושני שדראות פסול לעבודה אלמא דחיי (וקשיא לרב) א\"ל שימי את ששדרתו עקומה","מיתיבי יש בעוברין שהן אסורין בן ארבעה לדקה בן שמנה לגסה הימנו ולמטה אסור יצא מי שיש לו שני גבין ושני שדראות","מאי יצא לאו יצא מכלל עוברין שאפילו במעי אמן אסורין","רב מתרץ לטעמיה ושמואל מתרץ לטעמיה רב מתרץ לטעמיה בן ארבעה לדקה בן ח' לגסה הימנו ולמטה אסור","במה דברים אמורים כשיצא לאויר העולם אבל במעי אמו שרי יצא מי שיש לו שני גבין ושני שדראות דאפילו במעי אמו נמי אסור"],[[0,"עד הארכובה","שנחתכו רגליה עד למעלה מן הארכובה שהיא טרפה וקסבר טרפה אינה חיה:"],[0,"עד לנקביו","ונקביו בכלל קסבר טרפה חיה הלכך עד לארכובה הוי ולד אבל עד לנקביו הוי נבלה כר' אלעזר דאמר ניטל הירך וחלל שלה נבלה ואפי' בחייה מטמאה הלכך לא חיה ובשחיטת חולין (דף כא.) מפרש היכי דמי חלל שלה כל שרבוצה ונראית חסרה:"],[0,"עד טבורו","אבל עד נקביו לא דלית ליה דרבי אלעזר ואי משום טרפה קסבר טרפה חיה:"],[2,"בין ר' ינאי לרבי יוחנן איכא בינייהו דר' אלעזר","ותרוייהו אית להו טרפה חיה:"],[3,"מלמעלה","שנחתך מגולגלתו:"],[3,"אטומה","חסרה:"],[4,"כמין אפקתא דדיקלא","שהדקל למטה יחיד ומתפצל מלמעלה כך היו ידיו ורגליו על כתפו ומלמטה הוא בלא צורה:"],[5,"מוסמסין","מעוכין קצת ולא כל כך כפניו טוחות:"],[7,"כי פליגי בפניו טוחות","שאין צורה בהן ניכרת לגמרי:"],[7,"ואיפכא איתמר","ולא משום צורך מפיק לה אלא הכי גמר לה מרביה:"],[8,"לותביה ריש לקיש לר' יוחנן מהא","דאם איתא ליתני או ממי שפניו טוחות:"],[8,"היינו פניו טוחות","אבל בפניו מוסמסין ליכא לשנויי הכי דהא ניכרת בהן הצורה ולאו אטום הוא דאטום היינו חסר לגמרי:"],[10,"לחומרא","שטמאתם אותה שבועים משום ספק נקבה:"],[10,"חומרא דאתי לידי קולא הוא","דכיון דולד הוא יהביתו לה ימי טוהר מיהא ל\"ג דזכר ומטהריתו לדם ראייתה שלא כדין דטמאה נדה היא דלאו ולד הוא:"],[11,"בבהמה אסור באכילה","אם נשחטה אמו ונמצא במעיה וכל שכן יצא לאויר העולם דנפל הוא ונבלה:"],[11,"מותר באכילה","דכתיב (ויקרא י״א:ג׳) כל בבהמה תאכלו כל הנמצא בבהמה תאכלו ובלבד שיהיו לו פרסות או פרסה כדאמר בבהמה המקשה לילד (חולין סט:):"],[12,"השסועה","רחמנא אסרה דכתיב (דברים יד) את זה לא תאכלו וגו' השסועה:"],[13,"רב סבר","האי דאסר רחמנא כשנמצאת במעי בהמה אסורה דהא בריה בעלמא בפני עצמה ליתא:"],[13,"בעלמא אגמריה","אותו המין אסר אבל אם נמצאת במעי פרה מותר:"],[14,"ר' חנינא בן אנטיגנוס","בבכור קאי וקאמר דהוי מום ומדפסל ליה לקרבן מכלל דלהדיוט שרי וקשיא לתרוייהו דהא אפי' יצא לאויר העולם שרי ושמואל לא שרי אלא במעי אמו. והא דאקשי רב שימי טפי לרב מדשמואל משום דגביה הוה קאי ובר בריה הוה כדאמר בפרק כל הבשר (חולין קיא:) רב אקלע לבי רב שימי בר חייא בר בריה:"],[14,"שימי את","בכמה דוכתין אשכחן דמהדר ליה רב הכי שימי את ונראה בעיני משום דבר בריה הוה וקאמר ליה הכי משום חביבותיה כלומר אתה יודע להשיבני. ואני שמעתי שמדת צניעות היה בו ברב שלא היה זוקף עיניו למעלה הלכך לא היה מכירו ולא נהירא לי שהרי לא מצינו שאמר רב כך לשום אדם אלא לזה אמר כן בכמה מקומות כאן ובמנחות (דף קי.) ועוד שמעתי משום דחריף הוה ודחיק ליה כי ההיא דאמר (במועד קטן (דף כט)) רחמנא לישזבא מכיסופיה דרב שימי ולא היא דהתם רב שימי בר אשי הוה דדחיק ליה לרב פפא:"],[14,"ששדרתו עקומה","הא דרבי חנינא דמשמע דחיי לאו שני גבין ממש אלא ששדרתו עקומה (כזה) ונראין כשתים:"],[15,"יש בעוברין","שיצאו לאויר העולם שאסורין משום נבלה:"],[16,"לאו יצא מכלל עוברין","דהני אע\"ג דלא כלו חדשיהן כי נמצאו במעי אמן שרו אבל האי אפי' במעי אמן אסור וקשיא לשמואל:"],[17,"רב מתרץ לטעמיה","דרב לא צריך לתרוצי אלא משום היא גופה דלא משתמע שפיר דהא רישא כשיצאו לאויר העולם מיירי וסיפא דקתני יצא משמע דעלה קאי וכשיצא לאויר העולם משמע דמותר ואי אפשר לומר כן הלכך צריך להוסיף עליה אבל במעי אמו שרי דכתיב כל בבהמה תאכלו בפרק בהמה המקשה (חולין סט.):"],[18,"יצא מי שיש לו שני גבין וכו'","דכי כתב רחמנא השסועה למיסר במעי אמו אסרה דהא מין בפני עצמה ליתא:"]],[[0,"","עד הארכובה. והארכובה בכלל דהיינו מן הארכובה ולמעלה ואין שייך להביא זה גבי כל שיעורי חכמים להחמיר לענין עד ועד בכלל באלו טרפות (חולין נה.) ואע\"ג דתבנית יד אמרי' בפרקין דטמאה לידה היינו כשניכר שהמותר נמחה כשפירש א\"נ כאן מיירי דניכר היטב שלא נברא יותר כגון במקום החסרון יש עור נקרם:"],[6,"","ליתני שמא מגוף אטום באת או ממי שפניו כו'. וא\"ת והא איכא טובא דלא תני כגון פניו תייש (ופניו) אטום ואפקותא דדיקלא וי\"ל דפניו מוסמסין דומה לגוף אטום והויא ליה למיתני בהדיה טפי מאחריני:"],[7,"","אמר רב פפא בפניו מוסמסין כ\"ע לא פליגי. והא דקאמר איתיביה ר' יוחנן לר\"ל לא היו דברים מעולם וכענין זה יש בריש חולין (דף ד):"],[14,"","רבי חנינא בן אנטיגנוס אומר כל שיש כו'. פ\"ה מדהוי מום לקרבן מכלל דלהדיוט שרי וקשה לתרוייהו דהא אפי' יצא לאויר העולם שרי ושמואל לא שרי ליה אלא במעי אמו וקשה לר\"ת דבפ' אלו מומין (דף מג:) תנא ליה גבי מומי כהן ולא גבי מומי בהמה והתם נמי פריך מרב ולא מייתי משמואל מידי ונראה לר\"ת דארב דוקא פריך דאמר באשה אינו ולד אלמא אינו מתקיים והא חשיב ליה גבי מומי כהן אלמא חי אבל לשמואל דאמר באשה ולד מתקיים לא פריך מידי ובבהמה נמי אר\"ת דמתקיים לשמואל והא דאמר בסמוך דכי יצא לאויר העולם אסור היינו משום שסועה דאסר רחמנא ורש\"י פירש בסמוך לפי שיטתו דאסור משום נפל ושסועה דאסר רחמנא היינו מין בהמה דעלמא שיש לאם ולולד שני גבין וכן ב' שדראות אבל הנולד מבהמה שאין לה אלא גב אחד ושדרה אחת לא איצטריך קרא למיסר דנפל גמור הוי ובאשה מיהא מתקיים אף לפירושו מדקאמר באשה ולד וללישנא דבעלמא אגמריה משמע כפירושו וא\"ת בפרק אלו טרפות (חולין ס:) דפריך גבי שסועה שיש לה ב' גבין וכי משה קניגי היה והשתא לפ\"ה אתי שפיר דשסועה מין בעלמא הוא לשמואל ואינה מצויה אלא ביער לכך קאמר וכי קניגי היה אבל לפי' ר\"ת שאף לשמואל אינו מין בפני עצמו אלא שכך נולד מן הבהמה מה ענין זה אצל קניגי וי\"ל דאף לפירוש ר\"ת אם לא היה קניגי ורגיל לראות ומכיר בהמות משונות לא היה מכיר בהמה זו שיש לה ב' גבין אע\"פ שגם נולד מבהמות של ישוב שאינה רגילה להוליד מבהמה שאינה משונה:"]]],[["ושמואל מתרץ לטעמיה בן ארבעה לדקה בן שמנה לגסה הימנו ולמטה אסור במה דברים אמורים בשלא כלו לו חדשיו אבל כלו לו חדשיו מותר יצא מי שיש לו ב' גבין וב' שדראות דאע\"ג דכלו לו חדשיו אם יצא לאויר העולם אסור במעי אמו שרי","תני תנא קמיה דרב המפלת בריית גוף שאינו חתוך ובריית ראש שאינו חתוך יכול תהא אמו טמאה לידה ת\"ל (ויקרא יב, ב) אשה כי תזריע וילדה זכר וגו' וביום השמיני ימול וגו'","מי שראוי לברית שמנה יצאו אלו שאינן ראויין לברית שמנה א\"ל רב וסיים בה הכי ושיש לו שני גבין ושני שדראות","רבי ירמיה בר אבא סבר למעבד עובדא כוותיה דשמואל אמר ליה רב הונא מאי דעתיך לחומרא חומרא דאתי לידי קולא הוא דקיהבת לה דמי טוהר עביד מיהא כותיה דרב דקיימא לן הלכתא כרב באיסורי בין לקולא בין לחומרא","אמר רבא הרי אמרו אשה יולדת לתשעה ויולדת לשבעה בהמה גסה יולדת לתשעה יולדת לשבעה או לא ילדה","אמר רב נחמן בר יצחק ת\"ש הימנו ולמטה אסור מאי לאו אגסה לא אדקה","האי מאי אי אמרת בשלמא אגסה אצטריך סלקא דעתך אמינא הואיל ובאשה חיי בבהמה נמי חיי קמ\"ל דלא חיי","אלא אי אמרת אדקה איתמר פשיטא בת תלתא ירחי מי קא חיי","אצטריך סד\"א כל בציר תרי ירחי חיי קמ\"ל","אמר רב יהודה אמר שמואל המפלת דמות לילית אמו טמאה לידה ולד הוא אלא שיש לו כנפים תנ\"ה א\"ר יוסי מעשה בסימוני באחת שהפילה דמות לילית ובא מעשה לפני חכמים ואמרו ולד הוא אלא שיש לו כנפים","המפלת דמות נחש הורה חנינא בן אחיו של רבי יהושע אמו טמאה לידה הלך ר' יוסף וספר דברים לפני ר\"ג שלח לו רבי יהושע הנהג בן אחיך ובא","בהליכתן יצתה כלת (ר') חנינא לקראתו אמרה לו רבי המפלת כמין נחש מהו אמר לה אמו טהורה אמרה לו והלא משמך אמרה לי חמותי אמו טמאה ואמר לה מאיזה טעם הואיל וגלגל עינו עגול כשל אדם מתוך דבריה נזכר רבי יהושע שלח לו לרבן גמליאל מפי הורה חנינא","אמר אביי ש\"מ צורבא מרבנן דאמר מילתא לימא בה טעמא דכי מדכרו ליה מדכר","\u0001מתני׳\u0002 המפלת שפיר מלא מים מלא דם מלא גנונים אינה חוששת לולד ואם היה מרוקם תשב לזכר ולנקבה המפלת סנדל או שליא תשב לזכר ולנקבה","\u0001גמ׳\u0002 בשלמא דם ומים לא כלום היא אלא גנונים ניחוש שמא ולד הוה ונימוח אמר אביי כמה יין חי שתת אמו של זה שנמוח עוברה בתוך מעיה","רבא אמר מלא תנן ואם איתא דאתמוחי אתמח מחסר חסר רב אדא בר אהבה אמר גוונים תנן ואם איתא דאתמוחי אתמח כולה בחד גוונא הוי קאי","תניא אבא שאול אומר קובר מתים הייתי והייתי מסתכל בעצמות של מתים השותה יין חי עצמותיו שרופין מזוג עצמותיו סכויין כראוי עצמותיו משוחין וכל מי ששתייתו מרובה מאכילתו עצמותיו שרופין אכילתו מרובה משתייתו עצמותיו סכויין כראוי עצמותיו משוחין","תניא אבא שאול אומר ואיתימא רבי יוחנן קובר מתים הייתי פעם אחת רצתי אחר צבי ונכנסתי בקולית של מת ורצתי אחריו שלש פרסאות וצבי לא הגעתי וקולית לא כלתה כשחזרתי לאחורי אמרו לי של עוג מלך הבשן היתה","תניא אבא שאול אומר קובר מתים הייתי פעם אחת נפתחה מערה תחתי ועמדתי בגלגל עינו של מת עד חוטמי כשחזרתי לאחורי אמרו עין של אבשלום היתה","ושמא תאמר אבא שאול ננס הוה אבא שאול ארוך בדורו הוה ורבי טרפון מגיע לכתפו ור' טרפון ארוך בדורו הוה ור\"מ מגיע לכתפו רבי מאיר ארוך בדורו הוה ורבי מגיע לכתפו רבי ארוך בדורו הוה","ורבי חייא מגיע לכתפו ורבי חייא ארוך בדורו הוה ורב מגיע לכתפו רב ארוך בדורו הוה ורב יהודה מגיע לכתפו ורב יהודה ארוך בדורו הוה ואדא דיילא מגיע לכתפו"],[[0,"ושמואל מתרץ לטעמיה","רישא וסיפא בשיצא לאויר העולם:"],[0,"דאע\"ג דכלו לו חדשיו","נפל הוא דלא חיי ונבלה הואי:"],[1,"שאינו חתוך","כולו שלם כעין דף ואין בו חיתוך אברים וצורה אלא חלק כעין עיגול:"],[1,"וטמאה שבעת ימים וביום השמיני ימול","משמע מי שהוא ראוי לחיות שמנה ימים אמו טמאה לידה ומי שאינו ראוי לחיות שמנה לברית לא:"],[2,"א\"ל רב","לתנא סיים בה נמי הכי ואימא יצאו אלו מי שיש לו שני גבין וכו':"],[3,"כוותיה דשמואל","בשני גבין דולד הוא וקאמר טמאה אפילו בלידה יבישתא דולד הוא:"],[4,"הרי אמרו אשה יולדת לט' ויולדת לז'","ואנא נמי אמינא כי היכי דבהמה לט' כדאמרי' לעיל בן ח' לגסה נפל הכא נמי יולדת לז' נפל או לאו נפל הוא ומותר:"],[5,"הימנו ולמטה","בברייתא דלעיל תניא:"],[5,"מאי לאו אגסה","נמי קאי דקתני בן ח' לגסה והימנו ולמטה כגון בר ז' אסור:"],[5,"אדקה","בן ד' לדקה והימנו ולמטה כגון בר תלתא אסור:"],[7,"אלא אי אמרת אדקה פשיטא","הואיל ובר תלתא הוא לא חיי:"],[8,"כל בציר תרי ירחי","מכדרכו חיי כי היכי דבאשה ובבהמה גסה בר ז' חיי דהוי תרי ירחי בציר מכי אורחיה הכי נמי בר תלתא לדקה חיי אע\"ג דבר ד' לא חיי:"],[8,"קמ\"ל","דלא חיי:"],[9,"דמות לילית","שידה. שד יש לו פרצוף אדם ויש לו כנפים:"],[10,"הנהג בן אחיך ובא","כלומר הבא בן אחיך ובא עמו:"],[11,"","ה\"ג בהליכתן יצתה כלת חנינא לקראת רבי יהושע:"],[13,"מתני' מלא גנונים","גוונים:"],[13,"המפלת סנדל","אין סנדל בלא ולד אחר ובשביל סנדל תשב לזכר ולנקבה דספק זכר ספק נקבה הוא ואם הולד אחר נקבה אין הסנדל לא מעלה ולא מוריד ולא תשב אלא לנקבה ימי טומאה וימי טהרה שאפי' הוא זכר הואיל ונקבה בהדיה לא בצירי ימי טומאתה וימי טהרה דנקבה שהרי של זכר מובלעין בתוך של נקבה וכי אצטריך תשב לזכר ולנקבה כגון שהולד השני זכר דיהבינן לה חומרת טומאה דנקבה בשביל הסנדל וימי טוהר לזכר לחומרא:"],[14,"גמ' שמא ולד היה ונימוח","כיון דלאו דם הוא ולאו מים נינהו איכא למיחש לולד:"],[14,"כמה יין חי כו'","לשון גוזמא:"],[15,"","ה\"ג רבא אמר מלא תנן:"],[16,"סכויין","שחורין. שמעתי ל\"א סכויין בלא מוח ומשיחה אלא יבשה:"],[16,"מזוג","יותר מדאי:"],[17,"קולית","עצם הירך:"],[20,"דיילא","שמש דרבנן ואדא שמו:"]],[[2,"","מי שראוי לבריאת נשמה. ואית דגרס לברית שמנה:"],[9,"","המפלת דמות לילית אמו טמאה לידה. וא\"ת פשיטא מי גרע מגופו תיש ופניו אדם דהוי ולד לכ\"ע וי\"ל דהתם יצא מתורת בהמה והוי אדם והכא לא יצא כלל מתורת לילית אך ק\"ק דאמרי' לעיל (נדה כג.) בעופות תבדק לרבנן דקריא וקיפופא הוי ולד אף על גב דלסתות לא מפיק ליה כלל מתורת כוס וינשוף וי\"ל שמואל דהכא יפרש לעיל תבדק לר\"מ:"],[13,"","המפלת סנדל או שליא תשב לזכר ולנקבה. וא\"ת בשליא ליתני נמי ולנדה דאימא הרחיקה לידתה וכבר כלו ימי טוהר כדאיתא לקמן בפירקין (נדה דף כח.) גבי המפלת יד חתוכה אע\"ג דאמר בסמוך אין תולין השליא בולד יותר מג' ימים להחמיר חוששין יותר מג' ימים וי\"ל דלא דמו דבהמפלת יד חתוכה איכא למימר דהראש או רוב הגוף כבר ילדה מקודם וכלו ימי טוהר אבל שליא אימא הולד בתוכה או שלם או נימוק ועוד י\"ל דאי הוה תני ולנדה ה\"א מביאה קרבן ואינו נאכל דספק לידה היא קמ\"ל מביאה קרבן ונאכל והכי נמי קאמר לקמן:"],[16,"","אכילתו מרובה משתייתו. פי' יותר מדאי מרובה על השתיה דהא דרך אכילה להיות מרובה על השתיה כדאמרי' בפ\"ק דמגילה (דף יב.) והשתיה כדת אין אונס כדת של תורה דאכילה מרובה משתייה דקרבנות יש יותר מנסכים והא דאמרי' בערבי פסחים (דף קי.) ובגיטין (דף ע.) אכול שליש ושתה שליש והנח שליש לכשתכעוס תעמוד על מילואך לאו דוקא אלא שבין אכילה ושתיה יהיו שני שלישים:"]]],[["פרשתבינא דפומבדיתא קאי ליה לאדא דיילא עד פלגיה וכולי עלמא קאי לפרשתבינא דפומבדיתא עד חרציה","שאלו לפני רבי המפלת שפיר מלא בשר מהו אמר להם לא שמעתי","אמר לפניו ר' ישמעאל בר' יוסי כך אמר אבא מלא דם טמאה נדה מלא בשר טמאה לידה","א\"ל אילמלי דבר חדש אמרת לנו משום אביך שמענוך עכשיו","מדהא קמייתא כיחידאה קאמר כסומכוס שאמר משום ר\"מ הא נמי שמא כרבי יהושע אמרה ואין הלכה כר' יהושע","דתניא המפלת שפיר שאינו מרוקם ר' יהושע אומר ולד וחכ\"א אינו ולד","אמר ר\"ש בן לקיש משום ר' אושעיא מחלוקת בעכור אבל בצלול דברי הכל אינו ולד ור' יהושע בן לוי אמר בצלול מחלוקת","איבעיא להו בצלול מחלוקת אבל בעכור דברי הכל ולד או דלמא בין בזה ובין בזה מחלוקת תיקו","מיתיבי את זו דרש ר' יהושע בן חנניא (בראשית ג, כא) ויעש ה' אלהים לאדם ולאשתו כתנות עור וילבישם מלמד שאין הקב\"ה עושה עור לאדם אלא א\"כ נוצר","אלמא בעור תליא מילתא לא שנא עכור ול\"ש צלול","אי אמרת בשלמא בצלול מחלוקת היינו דאיצטריך קרא אלא אי אמרת בעכור מחלוקת למה לי קרא סברא בעלמא הוא אלא שמע מינה בצלול מחלוקת שמע מינה","וכן אמר ר\"נ אמר רבה בר אבוה מחלוקת בעכור אבל בצלול דברי הכל אינו ולד","איתיביה רבא לר\"נ אלא אמרו סימן ולד בבהמה דקה טינוף בגסה שליא באשה שפיר ושליא","ואילו שפיר בבהמה לא פטר אי אמרת בשלמא בצלול מחלוקת משום הכי","אשה דרבי בה קרא פטר בה שפיר בבהמה דלא רבי קרא לא פטר בה שפיר","אלא אי אמרת בעכור מחלוקת מכדי סברא הוא מאי שנא אשה ומאי שנא בהמה","מי סברת רבי יהושע מפשט פשיט ליה רבי יהושע ספוקי מספקא ליה ואזיל הכא לחומרא והכא לחומרא","גבי אשה דממונא הוא ספק ממונא לקולא","גבי בהמה דאיסורא הוא דאיכא לגבי גיזה ועבודה ספק איסורא לחומרא ה\"נ גבי אשה ספק טומאה לחומרא","ומי מספקא ליה והא קרא קאמר מדרבנן וקרא אסמכתא בעלמא הוא","א\"ל רב חנינא בר שלמיא לרב הא רבי הא ר' ישמעאל בר' יוסי והא רבי אושעיא והא רבי יהושע בן לוי מר כמאן ס\"ל","א\"ל אני אומר אחד זה ואחד זה אינה חוששת","ושמואל אמר אחד זה ואחד זה חוששת ואזדא שמואל לטעמיה דכי אתא רב דימי אמר מעולם לא דכו שפיר בנהרדעא לבר מההוא שפירא דאתא לקמיה דשמואל דמנח עליה חוט השערה מהאי גיסא וחזיא מהאי גיסא אמר אם איתא דולד הואי לא הוה זיג כולי האי","ואם היה מרוקם וכו' תנו רבנן איזהו שפיר מרוקם אבא שאול אומר תחלת ברייתו מראשו ושתי עיניו כשתי טיפין של זבוב תני רבי חייא מרוחקין זה מזה שני חוטמין כשתי טיפים של זבוב","תני רבי חייא ומקורבין זה לזה ופיו מתוח כחוט השערה וגויתו כעדשה ואם היתה נקבה נדונה כשעורה לארכה","וחתוך ידים ורגלים אין לו ועליו מפורש בקבלה (איוב י, י) הלא כחלב תתיכני וכגבינה תקפיאני עור ובשר תלבישני ועצמות וגידים תסוככני חיים וחסד עשית עמדי ופקודתך שמרה רוחי","ואין בודקין אותו במים שהמים עזין"],[[0,"פרשתבינא","שם האיש:"],[4,"כסומכוס","בריש פירקין דם שבתוך החתיכה מטמא משום נדה ויחידאה היא:"],[4,"כר' יהושע אמרה","דמשום עור שפיר לחודיה מטמא [משום לידה ויחידאה היא דדילמא אפילו במלא בשר פליגי כיון דאינו מרוקם מעולם לא היה ולד ואע\"ג דפליג רבי יהושע בשפיר לחודיה במלא דם מודה דלאו ולד הוא דדם מוכיח עליו]:"],[6,"בעכור","מה שבתוכו עכור דאיכא למימר ולד היה ונימוח:"],[6,"בצלול","שהוא מלא מים צלולין:"],[10,"היינו דאיצטריך קרא","לרבי יהושע דמשום עור לחודיה הוי ולד:"],[10,"אלא אי אמרת","טעמא דרבי יהושע משום דעכור הוא ואיכא למימר נימוח ולאו משום עור קרא ל\"ל:"],[10,"אלא לאו בצלול מחלוקת","ותיובתא דר\"ל:"],[12,"אלא אמרו","רישא בבכורות פרק הלוקח בהמה מן העובד כוכבים (דף יט:) לענין לפטור את שבא אחריו מתורת בכור:"],[12,"טינוף","לאחר שקבלה מן הזכר ונוצר הולד נימוח וזב הימנו ויוצא והולך ואותו טינוף פוטרתה מן הבכורה:"],[12,"שפיר ושליא","או שפיר או שליא:"],[16,"ספוקי מספקא ליה","בעכור גופיה אי ולד הוא אם לאו:"],[16,"הכא לחומרא והכא לחומרא","גבי בכורת בהמה אמר דלאו ולד הוא ולא פטר את הבא אחריו דאי אמרת פטר קא גזיז ועביד ביה עבודה ודילמא לאו ולד הוא ההוא קמא וקאתי לידי תקלה וגבי טומאת ולד אזיל לחומרא דקאמר ולד הוא וטמאה שבועיים וימי טוהר לא ס\"ל דניתיב לה. וגבי בכור אדם דקולא היא דקאמר פטר את הבא אחריו ולא איכפת לן דאין קדושה בבכור אדם אלא ממון כהן ה' סלעים וספק ממונא לקולא דכהן הוי מוציא מחברו עליו הראיה:"],[20,"הא רבי","דאמר לעיל לא שמעתי:"],[20,"והא רבי ישמעאל","דאמר מלא בשר טמאה לידה:"],[20,"והא רבי אושעיא","דאמר בעכור מחלוקת:"],[20,"והא רבי יהושע בן לוי","דאמר בצלול מחלוקת:"],[21,"אחד זה ואחד זה","אחד עכור ואחד צלול:"],[21,"חוששת","ויושבת ימי טומאה ואין לה ימי טוהר דספק ולד הוא ולא ודאי:"],[22,"לא דכו שפיר","לא טיהרו את המפלת שפיר משבועים ואפי' בלידה יבישתא:"],[22,"נהרדעא","אתריה דשמואל:"],[22,"זיג","צלול:"],[23,"טיפין של זבוב","עיני זבוב:"],[24,"ופיו מתוח כחוט השערה","סדק קטן ונראה כאילו חוט השערה מתוח שם:"],[24,"גויתו","גיד אבר הזכר. והא דתנן תשב לזכר ולנקבה אלמא מספקא לן אם זכר אם נקבה כשאין ניכר בו האבר מיירי:"],[24,"כשעורה","היא סדוקה לארכה:"],[25,"וחיתוך ידים ורגלים","עדיין אין נראין כדאמרינן תחלת ברייתו מראשו:"],[25,"כחלב","זהו שכבת זרע שהוא ניתך וקלוש מתחלה בשעת יציאתו כחלב ואח\"כ נעשה קפוי:"]],[[0,"","פרשתבינא. פ\"ה שם איש וכן בערוך ואינו כן דאם כן ה\"ל למימר מפומבדיתא אלא פרשב\"ם לשון פרנסות וממשלה:"],[1,"","מלא בשר מהו. ממתני' דקתני מלא דם ומלא מים ליכא למפשט דדילמא הא מלא בשר חוששת אבל ודאי ולד לא הוי א\"נ הא דלא חשיב משום דבפלוגתא לא מיירי:"],[4,"","שמא כר' יהושע. אע\"ג דבעי למימר בסמוך מחלוקת בצלול אבל בעכור דברי הכל ולד רבי נמי מסופק היה בהא דהא קאמר שמא:"],[4,"","(לעיל) כסומכוס. וא\"ת ואם שפיר מלא דם הוי כחתיכה שבתוכה דם שפיר מלא בשר נמי להוי כחתיכה של בשר דאמר בפירקין דאינה טמאה לידה כשאין בה עצם ויש לומר דשפיר דמיא לולד טפי מחתיכה וטמא אפילו אין בה עצם אע\"ג דבמלא דם שניהם שוים:"],[6,"","מחלוקת בצלול. פ\"ה מלא מים וכן משמע וקשה וכי עדיף ממלאה דם דאמר לעיל דטמאה נדה ולא לידה אפי' לרבי יהושע לכך נראה לפרש דצלול ועכור היינו בשר עכור ובשר צלול:"],[8,"","שאין הקב\"ה עושה עור כו'. דכתנות עור בעור אדם מיירי כדמתרגמינן על משך בשריהון:"],[12,"","סימן ולד בבהמה דקה טינוף. האי טינוף הוא ולד עצמו ולא דמי לטינוף דלקמן דרוב בהמות מטנפות דהתם טינוף של אחר יצירת הולד:"],[18,"","גבי בהמה לחומרא. ואע\"ג דקולא הוא שמוציאין ממון מרשות ישראל היינו משום דאי לא יהיב לכהן אתי למשרי בגיזה ועבודה:"],[21,"","אינה חוששת. וקסבר רב דבעכור מחלוקת [ר\"י] ורבנן:"],[23,"","תחלת ברייתו מראשו. תימה דבפ' בתרא דסוטה (דף מה:) קסבר אבא שאול תחלת ברייתו מטיבורו ומשלח שרשיו אילך ואילך ונראה לר\"ת דגרס ברשון וכן פר\"ח ובתוספתא פירש כעין חגב דסלעם מתרגמינן רשון וכן משמע דמיירי בשיעור האברים:"],[25,"","עור ובשר תלבישני ועצמות וגידים תסוככני. ברישא עור ובשר והדר עצמות וגידים ובתחיית המתים דיחזקאל (סימן לז) איפכא גידין והדר בשר ומפרש במדרש למה הדבר דומה לאדם שפושט וחוזר ולובש מה שפושט ראשון לובש אחרון אבל בתחלת בריית הולד עור ובשר תחלה ואח\"כ עצמות וגידין:"]]],[["וטורדין אותו אלא בודקין אותו בשמן שהשמן רך ומצחצחו ואין רואין אלא בחמה","כיצד בודקין אותו כיצד בודקין אותו כדאמרינן אלא במה בודקין אותו לידע אם זכר הוא אם נקבה היא","אבא שאול בר נש ואמרי לה אבא שאול בר רמש אומר מביא קיסם שראשו חלק ומנענע באותו מקום אם מסכסך בידוע שזכר הוא ואם לאו בידוע שנקבה היא","א\"ר נחמן אמר רבה בר אבוה ל\"ש אלא מלמטה למעלה אבל מן הצדדין אימא כותלי בית הרחם נינהו","א\"ר אדא בר אהבה תנא אם היתה נקבה נדונה כשעורה סדוקה מתקיף לה ר\"נ ודילמא חוט של ביצים נינהו אמר אביי השתא ביצים גופייהו לא ידיעי חוט של ביצים ידיע","א\"ר עמרם תנא ב' ירכותיו כב' חוטין של זהורית וא\"ר עמרם עלה כשל ערב ושני זרועותיו כב' חוטין של זהורית וא\"ר עמרם עלה כשל שתי","א\"ל שמואל לרב יהודה שיננא לא תעביד עובדא עד שישעיר ומי אמר שמואל הכי והאמר שמואל אחת זו ואחת זו חוששת","אמר רב אמי בר שמואל לדידי מפרשא לי מיניה דמר שמואל לחוש חוששת ימי טהרה לא יהבינן לה עד שישעיר","למימרא דמספקא ליה לשמואל והא ההוא שפירא דאתאי לקמיה דמר שמואל אמר הא בר ארבעין וחד יומא וחשיב מיומא דאזלא לטבילה עד ההוא יומא ולא הוה אלא ארבעין יומין","ואמר להו האי בנדה בעל כפתיה ואודי שאני שמואל דרב גובריה","המפלת סנדל וכו' ת\"ר סנדל דומה לדג של ים מתחלתו ולד הוא אלא שנרצף רשב\"ג אומר סנדל דומה ללשון של שור הגדול משום רבותינו העידו סנדל צריך צורת פנים","א\"ר יהודה אמר שמואל הלכה סנדל צריך צורת פנים ... א\"ר אדא א\"ר יוסף א\"ר יצחק סנדל צריך צורת פנים ואפי' מאחוריו משל לאדם שסטר את חבירו והחזיר פניו לאחוריו","בימי רבי ינאי בקשו לטהר את הסנדל שאין לו צורת פנים אמר להם ר' ינאי טיהרתם את הוולדות","והתניא משום רבותינו העידו סנדל צריך צורת פנים אמר רב ביבי בר אביי אמר רבי יוחנן מעדותו של רבי נחוניא נשנית משנה זו אמר רבי זעירא זכה בה רב ביבי בשמעתיה דאנא והוא הוינא יתבינן קמיה דרבי יוחנן כי אמרה להא שמעתא וקדם איהו ואמר וזכה בה","למה הזכירו סנדל והלא אין סנדל שאין עמו ולד","אי דאתילידא נקבה בהדיה ה\"נ הכא במאי עסקינן דאתיליד זכר בהדיה","מהו דתימא הואיל ואמר רב יצחק בר אמי אשה מזרעת תחילה יולדת זכר איש מזריע תחלה יולדת נקבה מדהא זכר הא נמי זכר","קמ\"ל אימא שניהם הזריעו בבת אחת האי זכר והאי נקבה","דבר אחר שאם תלד נקבה לפני שקיעת החמה וסנדל לאחר שקיעת החמה","מונה תחלת נדה לראשון ותחלת נדה לאחרון","סנדל דתנן"],[[0,"וטורדין אותו","ממחין:"],[2,"","בר רמש:"],[2,"ומנענע באותו מקום","מלמטה למעלה כדאמר בסמוך:"],[2,"אם מסכסך","הקיסם שיש דבר המעכב היינו גיד דאי נקבה ליכא עיכובא:"],[3,"מלמטה למעלה","שהרי בסדק השעורה אין עיכוב לארכה:"],[4,"תנא אם היתה נקבה נידונת כשעורה סדוקה","לאוסופי ולפרושי אתא דלעיל תני נידונת כשעורה ולא תני סדוקה:"],[4,"חוט","מבדיל מלמטה למעלה בין ב' הביצים ונראה עמוק כסדק:"],[4,"לא ידיעי","אין ניכרין מחמת קטנן:"],[5,"שתי ירכותיו","כשהוא מתחיל להבראות בחיתוך ידים ורגלים:"],[5,"ערב","עבה משתי:"],[6,"לא תעביד עובדא","לעשותו ולד עד שיהא לו שערות בראשו:"],[7,"לחוש חוששת","להחמיר ולישב שבועים:"],[9,"כפתיה ואודי","אלמא היה בקי ביצירת הולד:"],[9,"דרב גובריה","הוא בקי ואין כולן בקיאין:"],[10,"דג של ים","דג יש בים ושמו סנדל:"],[10,"אלא שנרצף","נמעך:"],[10,"[לשון של שור הגדול","דהיינו פניו טוחות. ואע\"ג דאוקמינן לעיל פניו טוחות אין אמו טמאה גבי סנדל ודאי אמו טמאה לידה (סנדל) דולד שעמו מוכיח עליו דולד הוא אלא שנימוק ע\"י חברו שדחקו]:"],[10,"צריך צורת פנים אפי' מאחוריו","כלומר אפי' אינו אלא מאחוריו הוי ולד:"],[11,"שסטר","הכהו על לחיו:"],[13,"משנה זו","דקתני צריך צורת פנים מעדותו של רבי נחוניא נשנית הוא העיד עליה בבית המדרש ויחידאה היא:"],[13,"זכה בה רב ביבי בשמעתיה","מזלו גרם לומר שמועה זו וקדמני שגם אני שמעתיה מר' יוחנן דמעדותו של רבי נחוניא נשנית ולא זכיתי לאומרה:"],[14,"והלא אין סנדל שאין עמו ולד","ובלא סנדל נמי הויא טמאה לידה:"],[15,"אי דאיתיליד נקבה בהדיה ה\"נ","דלא היה צריך להזכירו דיש לה ימי טומאה וטהרה דנקבה שאפילו הוא זכר גמור כי איכא נקבה בהדיה יושבת לנקבה ימי טומאה וטהרה ושל זכר מובלעים בתוכן:"],[15,"דאיתיליד זכר בהדיה","ומספקי' לסנדל בנקבה ויושבת שבועיים לטומאה אבל טהרה דנקבה לא יהבינן לה דדילמא זכר הוא:"],[16,"האי נמי זכר","ולא תשב אלא לזכר קמ\"ל כו':"],[18,"ד\"א","אפי' ילדה עמו נקבה צריך להזכיר ספק סנדל:"],[18,"","\u0003שאם תפיל שנים אחד לפני שקיעת החמה ואחד לאחר שקיעת החמה מונה תחלת נדה לראשון ותחלת נדה לאחרון\u0004 וה\"ג לה בתוספתא. וה\"פ שאם תפיל שניהם נקבה לפני שקיעת החמה וסנדל לאחר שקיעה מונה לאחר שיכלו ימי טוהר לראשון תחלת נדה וכן לאחרון כגון אם תראה ביום שמונים ואחד לראשון הויא תחלת נדה דדילמא סנדל שנולד לאחר שקיעה זכר הוא וכלו ימי טוהר שלו לסוף מ' ולא משכי בתר פ\"א דנקבה וכשתחזור ותראה בח' לראייתה ותרצה להיות סופרת יום כנגד יום אמרינן דלמא סנדל נקבה הוה ומשוך ימי טוהר שלו עד פ\"א לראשון ומה שראתה ביום פ\"א לראשון דם טוהר הוא ועכשיו מה שהיא רואה ביום פ\"א תחלת נדה הוא והיינו תחלת נדה לאחרון ובהכי הויא מקולקלת דלא ידעינן בהך ראיה בתרייתא אי נדה היא אי שומרת יום כנגד יום. לישנא אחרינא גרסי' שאם תלד נקבה לפני שקיעה וסנדל לאחר שקיעה מונה תחלת לידה מן האחרון וסוף לידה מן הראשון. וה\"פ אפילו היכא דאיתיליד נקבה בהדיה הוצרך סנדל שאם תלד נקבה לפני שקיעה והסנדל שהוא ספק זכר לאחר שקיעה מונה תחלת לידה דהיינו ימי טומאה מן האחרון דדילמא סנדל נמי נקבה היא ומנינן מיניה י\"ד שהוא ט\"ו לראשון וסוף לידה דהיינו ימי טוהר מנינן מן הראשון להחמיר שאם תראה ביום פ\"א דהיינו פ' לאחרון מטמינן לה משום נדה דאמרי' סנדל זכר הוה והרי ארבעים יום ששלמו ימי טוהר שלו ודנקבה קמייתא נמי השתא כלו להו והיינו צורך דאי לאו סנדל הוי מנינה נמי ימי טומאה לראשון ולא מטמאה אלא י\"ד והשתא יתבה ט\"ו ואי הוה פשיטא לן שהסנדל נקבה היא לא הויא תחלת נדה עד פ\"ב לראשון דבתר ולד אחרון אזלינן:"]],[[1,"","לידע אם זכר הוא. הא דאמר גויתו בכעדשה לא שמקומו בולט אלא שמקומו ניכר בכעדשה:"],[16,"","קא משמע לן אימא שניהם הזריעו בבת אחת. לר\"ת שפירש דאין מתעברת וחוזרת ומתעברת ואפילו נפל אתי שפיר וצ\"ל שהזריעו בבת אחת אבל לפרש\"י שפירש גבי ג' נשים משמשות במוך מעוברת שמא תעשה עוברה סנדל שולד אחרון ממעך צורה הראשונה והא דאין אשה חוזרת ומתעברת היינו בן קיימא (דאין) נפל חוזרת ומתעברת לא הוה צ\"ל הכא אימא שניהם הזריעו בבת אחת והל\"ל בביאה ראשונה הזריעה היא תחלה ובביאה שניה הזריע הוא תחלה ומיהו י\"ל דבענין זה בב' ביאות אין חדוש למתני תשב לזכר ולנקבה דפשיטא דפעמים הוא מזריע תחלה ופעמים היא ולא אמר מדהאי זכר האי נמי זכר אבל בביאה אחת סד\"א מדהאי זכר האי נמי זכר קמ\"ל אימא שניהם הזריעו בבת אחת ומיהו קשה מנלן דלא אמרינן בביאה אחת מדהאי זכר האי נמי זכר אימא לעולם אמרי' ומתני' בב' ביאות ואשמועינן מתני' דסנדל הוי ולד אף בלא צורת פנים ולאפוקי מעדותו של רבי נחוניא ואע\"ג דכבר אשמעינן בבכורות ובכריתות דמייתי בסמוך דסנדל הוא ולד מ\"מ איצטריך נמי לאשמועינן דהוי ולד לענין לידה וי\"ל דהיינו דקמשני בלשון שני ומיהו תימה גם לפר\"ת דלקמן (נדה דף כח.) גבי זכר וטומטום משני נמי שהזריעו שניהם בבת אחת ותרתי למה לי ואי אתא לאשמועינן דהוי ולד והא כבר תנא בהדיא ברישא טומטום או אנדרוגינוס תשב לזכר ולנקבה:"]]],[["גבי בכורות למאי הלכתא","לבא אחריו בכור לנחלה ואין בכור לכהן","סנדל דתנן גבי כריתות למאי הלכתא","שאם תלד ולד דרך דופן וסנדל דרך רחם דמייתא קרבן אסנדל","ולרבי שמעון דאמר יוצא דרך דופן ולד מעליא הוא מאי איכא למימר","אמר רבי ירמיה שאם תלד ולד בהיותה עובדת כוכבים וסנדל לאחר שנתגיירה דמייתא קרבן אסנדל","אמרוה רבנן קמיה דרב פפא ומי איתנהו להני שינויי והא תניא כשהן יוצאין אין יוצאין אלא כרוכין","אמר רב פפא שמע מינה מכרך כריך ליה ולד לסנדל אפלגיה ומשלחיף ליה כלפי רישיה גבי בכורות כגון שיצאו דרך ראשיהם דסנדל קדים ונפיק גבי כריתות שיצאו דרך מרגלותיהם דולד קדים ונפיק","רב הונא בר תחליפא משמיה דרבא אמר אפילו תימא מצומצמין ואיפוך שמעתתא גבי בכורות שיצאו דרך מרגלותיהם ולד דאית ביה חיותא סריך ולא נפיק סנדל דלית ביה חיותא שריק ונפיק גבי כריתות שיצאו דרך ראשיהן ולד דאית ביה חיותא מדנפיק רישיה הויא לידה סנדל עד דנפיק רוביה","\u0001מתני׳\u0002 שליא בבית הבית טמא לא שהשליא ולד אלא שאין שליא בלא ולד","רבי שמעון אומר נימוק הולד עד שלא יצא","\u0001גמ׳\u0002 תנו רבנן שליא תחלתה דומה לחוט של ערב וסופה דומה כתורמוס וחלולה כחצוצרת ואין שליא פחותה מטפח רבי שמעון בן גמליאל אומר שליא דומה לקורקבן של תרנגולין שהדקין יוצאין ממנה","תניא רבי אושעיא זעירא דמן חבריא חמשה שיעורן טפח ואלו הן שליא שופר שדרה דופן סוכה והאזוב","שליא הא דאמרן שופר דתניא כמה יהא שיעור שופר פירש רבי שמעון בן גמליאל כדי שיאחזנו בידו ויראה לכאן ולכאן טפח","שדרה מה היא דא\"ר פרנך אמר רבי יוחנן שדרו של לולב צריך שיהא יוצא מן ההדס טפח דופן סוכה דתניא שתים כהלכתן שלישית אפילו טפח אזוב דתני רבי חייא אזוב טפח","אמר רבי חנינא בר פפא דריש שילא איש כפר תמרתא תלת מתניתא ותרתי שמעתתא שיעורא טפח תרתי חדא היא אמר אביי אימא אמר רבי חייא אזוב טפח","ותו ליכא והאיכא טפח על טפח על רום טפח מרובע מביא את הטומאה וחוצץ בפני הטומאה","טפח קאמרינן טפח על טפח לא קאמרינן","והא איכא אבן היוצא מן התנור טפח ומן הכירה שלש אצבעות חבור","כי קאמרינן היכא דבציר מטפח לא חזי אבל הכא כ\"ש דבציר מטפח יד תנור הוא","והאיכא"],[[0,"גבי בכורות","דקתני (בכורות דף מו.) המפלת סנדל הבא אחריו בכור לנחלה ואין בכור לכהן:"],[0,"למאי הלכתא","קס\"ד לבא אחריו לסוף שנה או לסוף שנתיים קמיירי ול\"ל סנדל והלא בלא סנדל פטר ולד דבהדיה את הבא אחריו ומשני לבא אחריו כלומר לכך הוזכר סנדל אם יצא ולד שעמו אחריו הוי בכור לנחלה ולא בכור לכהן:"],[2,"גבי כריתות","בפ\"ק (כריתות דף ז:) לענין חיוב קרבן:"],[2,"למאי הלכתא","תיפוק ליה דמשום ולד שעמו תביא קרבן:"],[3,"ולד יוצא דרך דופן","ע\"י סם לא מיחייבה קרבן דכתיב גבי קרבן (ויקרא יב) אשה כי תזריע וילדה זכר עד שתלד ממקום שמזרעת:"],[4,"ולר' שמעון כו'","לקמן בפ' יוצא דופן (נדה דף מ.):"],[6,"כשהן יוצאין","סנדל וולד שעמו:"],[6,"כרוכין","דבוקין זה בזה ולא דבוקין ממש ומדיוצאין יחד אי אפשר שתתגייר בינתיים:"],[7,"שמע מינה","מדהוזכר סנדל גבי כריתות משום גירות וכגון שיצא ולד תחלה ואחר כן סנדל וגבי בכורות כגון שיצא סנדל תחלה כדאוקמינן לעיל דפוטר ולד מחמש סלעים ותניא דבבת אחת יוצאין שמע מינה אין שוכבין זה אצל זה דא\"כ לא משכחת לה שיצא זה קודם זה אלא האי כרוכין דקתני הכי הוא מכרך כריך ליה ולד לסנדל אפלגיה דראש הולד תחוב כנגד טיבורו של סנדל:"],[7,"ומשלחיף ליה כלפי רישיה","כלומר דחפו ולד בראשו לסנדל כלפי חוץ:"],[7,"גבי בכורות","דבעינן שיצא הסנדל תחילה כגון שיצאו דרך ראשיהן כו':"],[8,"מצומצמין","שוכבין זה אצל זה:"],[8,"ואיפוך שמעתתא","מימרא דרב פפא דאמר בבכורות שיצאו דרך ראשיהן:"],[8,"סריך","אוחז בידיו למעלה ואינו ממהר לצאת וסנדל מחליק ויוצא קודם:"],[8,"שריק","מחליק:"],[8,"הויא לידה","דקיימא לן בהאי פירקא (דף כח.) יצא ראשו הרי הוא כילוד אבל סנדל עד דנפיק רובא דאין ראש נפל חשוב דהכי אמרינן בבכורות (דף מו:) אין הראש פוטר בנפלים ואדנפיק סנדל נתגיירה וטבלה:"],[9,"מתני' הבית טמא","משום אהל המת דולד הוה בה ומת:"],[10,"נימוק הולד","ונעשה דם ונתערב בדם הלידה ובטל ברוב:"],[11,"גמ' וסופה","כשהיא הולכת ורווחת הויא רחב כתורמוס. לישנא אחרינא גרסינן בתוספתא וראשה דומה כתורמוס:"],[13,"שיאחזנו בידו","אחיזה אית בה טפח שהטפח ארבע אצבעות בגודל:"],[14,"שדרו של לולב צריך שיהא יוצא מן ההדס טפח","לבד אורך העלין. שדרה קרי כל זמן שהעלין הולכין ומתחברין ומוסיפין ואחר שכלתה השדרה גבוהין אורך העלין למעלה:"],[15,"חדא היא","דליכא שמעתתא אלא האי דשדרה דאמר ר' יוחנן:"],[15,"אמר אביי","לא תימא תני ר' חייא אזוב טפח דמשמע מתני' היא אלא אימא אמר רבי חייא ומנפשיה קאמרה ורבי חייא תנא ואמורא הוא והיכא דאמר מנפשיה בלשון מימרא הויא שמעתא:"],[16,"טפח על טפח על רום טפח","אהל קטן שהוא טפח אורך וטפח רוחב ורום חללו טפח:"],[16,"מביא הטומאה","אם כזית מן המת בצד זה וכלי בצד זה הוה טמא כלי מחמת אהל המת:"],[16,"וחוצץ בפני הטומאה","אם טומאה תחתיו וכלי על גביו הכלי טהור. ולהכי נקט על רום טפח דאי הוה חלל רומו פחות מטפח הויא טומאה רצוצה וכנגדו למעלה עד לרקיע טמא כדאמרי' בהעור והרוטב (חולין קכו.) ולענין אתויי טומאה נמי לא מייתי דלאו אהל הוא:"],[18,"תנור","מקום שפיתת שתי קדרות. כירה מקום שפיתת קדרה אחת:"],[18,"חבור","וכתנור דמי מפני שצריכה לתנור להיות לו יד שאם נטמא התנור פת שעליה טמא שהתנור אע\"פ שאינו מקבל טומאה מגבו מטמא הוא את אחרים מגבו כדאמר בתורת כהנים הלכך ידו אע\"ג דלית ליה אויר מטמא אבל יותר מטפח עומדת לינטל שהיא גדולה יותר מדאי ולא הויא יד:"]],[[2,"","סנדל. דלית ליה חיותא עד שיצא רובו אבל ראשו לא אע\"ג דשמואל דאמר אין הראש פוטר בנפלים איתותב בפ' יש בכור (בכורות דף מו:) נפל דאית ליה צורת פנים עדיף מסנדל והא דקאמר ולד דאית ליה חיותא מדנפיק רישיה לאו דוקא דאית ביה חיותא דהא אפי' לית ביה חיותא כיון דאיתותב שמואל ועוד דמשמע בירושלמי דולד שעם הסנדל אינו מתקיים אלא כלומר שראוי לחיות דהיינו שנגמר בצורת פנים ור\"ח גריס ולד דאית ביה חיותא מדנפיק רובי' סנדל דלית ביה חיותא מדנפיק כוליה פי' רוביה רוב הראש כוליה כל הראש אבל כל הגוף פשיטא דלא צריך דרובו ככולו:"],[12,"","שדרה טפח. וא\"ת תקשי הך ברייתא לרב יהודה אמר שמואל דאמר צריך שיצא לולב מן ההדס טפח ולא מצריך שדרה ופליג על ר' פרנך וי\"ל דלא מתניא בי ר' חייא ובי ר' אושעיא אי נמי בברייתא לא תני שדרה אלא שהש\"ס קבע בברייתא שדרה משום דקים לן הכי ואם תאמר דטפח זה קטן דמפרש התם אמה בת ה' טפחים עשה אותה בת ו' צא מהם ג' להדס ואחד ללולב ויש לומר דמכל מקום כיון דאיכא שם טפח עליה חשיב ליה הכא עם שאר טפחים אי נמי טפח דלולב לא קאי אטפחים קטנים ולא קאי קטנים כ\"א אטפחים של הדס:"],[16,"","ותו ליכא. ואם תאמר והא איתא בהמוכר את הספינה (ב\"ב דף פט.) קנה של מאזנים טפח ובהעור והרוטב (חולין דף קכג.) בכדי אחיזה טפח גם בטרפות יש דשיעורו טפח ולפי המסקנא דלא איירי בדרבנן אלא בדכתיב ולא מפורש שיעורייהו אתי שפיר:"],[18,"","מן התנור טפח. היינו להוציא הטומאה שאם נטמא התנור מתוכו נטמא היד דחשיב כגוף התנור דאף על גב דאין התנור מקבל טומאה מגבו אם נטמא תוכו גבו נמי טמא כדאמר פ' אלו דברים (ברכות דף נב:) דנטמא תוכו כולן טמאין ובת\"כ נמי אמר מרובה מדת לטמא ממדת ליטמא שמטמא אחרים מגבו ואינו מיטמא מגבו ויד דין גב יש לה ואם נגע השרץ ליד לא נטמא התנור כדאמרינן בתוספתא (ב\"ק דכלים פ\"ו) אין טומאה לכלי חרס אלא מתוכו והיסטו בלבד ולא קתני על ידו ובהעור והרוטב (חולין דף קיח.) דבעי למימר יד להכניס יעמיד התוספתא בתנור שאין לו יד:"]]],[["תנורי בנות טפח דתניא תנור תחלתו ארבעה ושיריו ד' דברי רבי מאיר","וחכמים אומרים במה דברים אמורים בגדול אבל בקטן תחלתו כל שהוא משתגמר מלאכתו ושיריו ברובו","וכמה כל שהוא אמר רבי ינאי טפח שכן עושין תנורי בנות טפח בפלוגתא לא קמיירי","השתא דאתית להכי הא נמי פלוגתא היא דקתני סיפא אמר ר' יהודה לא אמרו טפח אלא מן התנור ולכותל","והאיכא מסגרת טפח בדכתיבן לא קא מיירי והאיכא כפורת טפח בקדשים לא קמיירי","והאיכא דיה לקורה שהיא רחבה טפח בדרבנן לא קמיירי אלא בדכתיבן ולא מפרשי שיעורייהו","יתיב רב יצחק בר שמואל בר מרתא קמיה דרב כהנא ויתיב וקאמר אמר רב יהודה אמר רב כל שלשה ימים הראשונים תולין את השליא בולד מכאן ואילך חוששין לולד אחר","אמר ליה ומי אמר רב הכי והאמר רב אין הולד מתעכב אחר חבירו כלום אישתיק אמר ליה דלמא כאן בנפל כאן בבן קיימא","אמר ליה את אמרת לשמעתתיה דרב בפירוש אמר רב הכי הפילה נפל ואחר כך הפילה שליא כל שלשה ימים תולין את השליא בולד מכאן ואילך חוששין לולד אחר ילדה ואח\"כ הפילה שליא אפילו מכאן ועד עשרה ימים אין חוששין לולד אחר","שמואל ותלמידי דרב ורב יהודה הוו יתבי חליף ואזיל רב יוסף בריה דרב מנשיא מדויל לאפייהו באלי ואתי אמר אתי לן גברא דרמינן ליה בגילא דחטתא ומרמי ומדחי","אדהכי אתא אמר ליה שמואל מאי אמר רב בשליא א\"ל הכי אמר רב אין תולין את השליא אלא בדבר של קיימא שיילינהו שמואל לכל תלמידי דרב ואמרי ליה הכי הדר חזייה לרב יהודה בישות","בעא מיניה רבי יוסי בן שאול מרבי המפלת דמות עורב ושליא מהו אמר ליה אין תולין אלא בדבר שיש במינו שליא","קשורה בו מהו אמר ליה דבר שאינו שאלת איתיביה המפלת מין בהמה חיה ועוף ושליא עמהן בזמן שהשליא קשורה עמהן אין חוששין לולד אחר אין שליא קשורה עמהן חוששין לולד אחר הריני מטיל עליהן"],[[0,"תנורי בנות","נערות קטנות עושין תנורין לשחוק:"],[0,"תחלתו ארבעה","תנור בן ד' טפחים מקבל טומאה אם נגמרה מלאכתו:"],[0,"ושיריו ד'","נטמא תנור גדול ושברו ונשתיירו ד' טפחים עדיין טמא:"],[1,"","ה\"ג תחלתו כל שהוא משתגמר מלאכתו ושיריו ברובו ומקשה בהעור והרוטב רובו דטפח למאי חזי ומשני האי ושיריו אגדול קאי וה\"ק שירי גדול ברובו ומותבינן בגדול והא קאמר שיריו ד' ומשנינן ההוא בתנור בר ז' דד' הוי רובו והא בתנור בר ט':"],[2,"בפלוגתא","כגון הכא דלר\"מ לא הוי שיעורא בטפח:"],[3,"לא אמרו טפח אלא בין תנור ולכותל","דהתם יותר מטפח עומדת ליקצץ מפני שמעכב את התנור מלקרבו לכותל ודוחקת את הכותל הילכך יותר מטפח עומדת לינטל היא אבל לצד הבית אפי' גדולה הרבה יד הוא לתנור:"],[4,"בדכתיבן","ששיעורו מפורש מן התורה:"],[5,"דיה לקורה","לגבי מבוי:"],[5,"מדרבנן","כגון מבוי דכל מצותו מדברי סופרים:"],[6,"כל ג' ימים","כגון יצא ולד תחלה ושליא אחריו בתוך ג' ימים:"],[6,"תולין השליא","בו ואין חוששין לאחר דתוך הזמן הזה עשויה השליא להתעכב אחר הולד שהיתה ממנו טפי לא ואם זה זכר תשב לזכר בלבד ולא אמרינן שליא אחרת היתה עם ולד זה ונימוח ושליא זו דולד אחר היא דדרך שליא לשהות אחר ולד ג' ימים:"],[6,"מכאן ואילך חוששין","שמא ולד אחר היה עמו ונקבה היה ותשב ימי טומאה דנקבה ואי נמי הוי האי ולד נקבה אכתי מהניא ספק דשליא דמנינא ימי טוהר לחומרא שאם תראה ליום פ\"א לולד ופסקה עד יום שמיני וראתה לא הויא שומרת יום כנגד יום (דאמר בהדיא) שליא נקבה הואי ומה שראתה ביום פ\"א דם טוהר הוה דמשליא מנינן והשתא הוא דהויא תחלת נדה והיא נקראת טועה:"],[7,"בנפלים","מתעכב:"],[8,"את אמרת לשמעתתיה דרב","בתמיה. כלומר את אתית לפרושי מדידך:"],[8,"בפירוש","פירשה רב הכי:"],[8,"ילדה","בן קיימא:"],[9,"באלי ואתי","שהיה ממהר לבא כמו (לעיל נדה דף יז.) באלי דידבי פי' מגרש:"],[9,"מדויל","שם מקום:"],[9,"בגילא דחיטתא","כלומר בשאלות מועטות:"],[9,"מירמי ומידחי","כלומר להקשותו ולדחותו שלא ידע להשיב:"],[10,"אלא בדבר של קיימא","שכיוצא בו מתקיים אם היום היו חדשיו כלו למעוטי שאם הפילה דבר שאין ראוי לבריית נשמה כגון בירך אחד באמצע או גוף אטום או מפלת מין בהמה וחיה ועוף ואח\"כ הפילה שליא אפי' בתוך ג' חוששת לולד אחר:"],[10,"חזייה לרב יהודה בישות","דשמעה ולא אמרה ניהליה:"],[11,"המפלת עורב ושליא מהו","מי תלינן שליא בעורב ולא ניחוש לולד אחר או לא תלינן:"],[11,"שיש במינו","כגון אדם ובהמה וחיה אבל עוף לא:"]],[[1,"","אבל בקטן תחלתו כל שהוא. וא\"ת וגדול שאין לו ד' טפחים אמאי טהור והלא אף בקטן טפי טמא וי\"ל דגדול וקטן היינו ברוחב והרוחב הרבה צריך גובה ד' להחזיק חומו אבל קטן שהוא צר די בגובה טפח:"],[1,"","תחלתו כל שהוא. משתגמר מלאכתו שיריו ברובו במשניות גרסינן תחלתו כל שהוא שיריו ברובו משתגמר מלאכתו ואיזהו גמר מלאכתו וכו' ודרך הש\"ס שמהפך פעמים מסדר המשנה לפי הצורך משום דבפ' העור והרוטב (חולין דף קכד.) בעי רובו דטפח למאי חזי ומשני אגדול תני ליה בסוף ופריך והא שיריו ד' קאמר ומשני לא קשיא הא בתנור בר ט' הא בתנור בר ז' ומפרש התם רש\"י דבתנור ט' סגי בארבעה אע\"ג דלא הוי רובא ותנור ז' אע\"ג דלא הוי ד' סגי ברובא וקשה לר\"ת לא יהיה סופו חמור מתחלתו דהא תחלתו ד' ונראה כפירש\"י שפירש כאן דתנור בר ז' וד' הוי רובא ותנור בר תשעה ברובא וקשה דלמה ליה למנקט בר ט' הוה ליה למנקט בר ח' ושיריו ברובו ולפרש\"י דהתם ניחא דנקט ט' אע\"ג דהוי ד' מיעוטא ומה שהקשה ר\"ת לא קשה מידי דהעושה כלי חרס אינו עושה אלא דבר חשוב אבל כלי שנתמעט כל זמן שראוי אינו מתבטל כמו גרדומי ציצית דבשירים סגי וכן משמע מדפריך שיריו טפח למאי חזי משמע דאי הוה חזי הוה ניחא ליה אע\"ג דבציר מתחלתו:"],[2,"","כל שהוא טפח. פר\"ת בלא יחפור (ב\"ב דף יט) דפעמים כל שהוא בציר מטפח ופעמים טפי מטפח:"],[2,"","בפלוגתא לא קמיירי. ואע\"ג דפליגי בדופן סוכה דר\"ש אומר דרביעית טפח מ\"מ טפח לדופן אחד צריך לכ\"ע אבל לתנור אע\"ג דבין התנור ולכותל לכ\"ע טפח מ\"מ בסתם תנור פליגי והא דפרש\"י דכירה מקום שפיתת קדרה אחת לא דק דבפ' כירה (שבת דף לח:) אמר דכירה זהו מקום שפיתת ב' קדרות:"],[8,"","את אמרת שמעתתיה דרב. כלומר כוונת מעצמך ומתחלה שכחת ולכך שתק ולפ\"ה שפי' בתמיה צריך לומר דמתחלה לא חש להשיבו:"],[8,"","ילדה ואח\"כ הפילה שליא אפי' עד י' ימים אין חוששין לולד אחר. אע\"ג דאמר לקמן דנשתהא הולד שלשה חדשים מ\"מ לא שכיח וכל כמה דלא חזינן לא חיישינן:"],[12,"","המפלת חיה ועוף כו'. דוקא נקט חיה ועוף דאי בתחלה ולד ואח\"כ שליא עד ג' ימים תולין ואין חוששין לולד אחר ולכאורה נראה הטעם דחיה ועוף אין דרכן של נשים להפיל ולכך איכא לספוקי שהשליא אינה מהם וקשה דבפרק בהמה המקשה (חולין דף עז:) אהא דתנן שליא שיצתה מקצתה אסורה באכילה ומסיק אר\"א לא שנו אלא שאינה קשורה בולד פי' שיש לה ולד אחר וכיון דאינה קשורה בו חוששין לולד אחר בשליא ולכך אסורה ומייתי תניא נמי הכי מהך דהמפלת חיה ועוף והיכי מייתי הא אדרבה משמע הכא דוקא חיה ועוף דלאו אורחיה אבל נפל דאורחיה תולין כל שלשה ימים ובבן קיימא אפי' כמה ימים וי\"ל דאין הדבר תלוי באורחיה ולא אורחיה אלא קים ליה להש\"ס דאמר צורת אדם רגילה השליא להתעכב אבל לאחר בהמה חיה ועוף אינה רגילה להפרד השליא מן הולד אפי' במעי הבהמה כמו במעי האשה וא\"ת וכי אינה קשורה בולד אמאי קאמר ר\"א דאסורה באכילה הא אמרינן הכא דלא הוי אלא ספק ולא ודאי ולד אחר מדקתני הריני מטיל עליה חומר שני ולדות שמא נימוח שפיר של שליא זו וא\"כ הוי ספק ספקא דלמא אין כאן ולד אחר ואפי' איכא שמא לא יצא לא ראשו ולא רובו ובפ\"ק דב\"ק (דף יא.) גבי שליא שיצתה מקצתה ביום ראשון משמע דספק ספקא שרי דפריך מאי קמ\"'ל דאין מקצת שליא בלא ולד תנינא שליא שיצתה מקצתה אסורה פי' ואם יש מקצת שליא בלא ולד הוה ליה ספק ספקא ושרי וי\"ל דברייתא דקתני שמא איירי בשליא שאחר הולד ור\"א איירי בשליא שיצתה קודם הולד דודאי יש שם ולד אחר כשאינה קשורה בו כדאמרינן בשמעתין לא אמרו תולין השליא בולד אלא בשליא שבאה אחר הולד והתם מייתי ראיה דבאינה קשורה חוששין לולד אחר לאפוקי מדר' יוחנן דהתם אי נמי אפילו בספק ספקא אסרה ר\"א דגזרינן מקצתה אטו רובה או אטו אין עמה ולד אחר דיטעו העולם ויסברו הא דשרינן מה שבפנים לאו משום ספק ספקא אלא משום כל בבהמה וגזרת הכתוב הוא דאפי' יצא רובו שרי מיעוטו שבפנים כיון דחזו דשרינן ביצתה מקצתה ואפשר דיצא הראש באותו מקצת והוי כיוצא רובו ולא יעלו על לבם דמשום ספק ספקא שרי:"]]],[["חומר שני ולדות שאני אומר שמא נמוח שפיר של שליא ונמוח שליא של שפיר תיובתא","אמר רבה בר שילא אמר רב מתנה אמר שמואל מעשה ותלו את השליא בולד עד עשרה ימים ולא אמרו תולין אלא בשליא הבאה אחר הולד","אמר רבה בר בר חנה אמר רבי יוחנן מעשה ותלו את השליא בולד עד כ\"ג ימים אמר ליה רב יוסף עד כ\"ד אמרת לן","אמר רב אחא בריה דרב עוירא א\"ר יצחק מעשה ונשתהה הולד אחר חבירו ל\"ג יום א\"ל רב יוסף ל\"ד אמרת לן","הניחא למאן דאמר יולדת לתשעה יולדת למקוטעין משכחת לה אחד נגמרה צורתו לסוף שבעה ואחד נגמרה צורתו לתחלת תשעה אלא למ\"ד יולדת לתשעה אינה יולדת למקוטעין מאי איכא למימר","איפוך שמעתתא ל\"ג לשליא כ\"ג לולד","א\"ר אבין בר רב אדא אמר רב מנחם איש כפר שערים ואמרי לה בית שערים מעשה ונשתהה ולד אחד אחר חבירו ג' חדשים והרי הם יושבים לפנינו בבית המדרש ומאן נינהו יהודה וחזקיה בני רבי חייא","והא אמר מר אין אשה מתעברת וחוזרת ומתעברת אמר אביי טיפה אחת היתה ונתחלקה לשתים אחד נגמרה צורתו בתחלת ז' ואחד בסוף ט'","שליא בבית הבית טמא תנו רבנן שליא בבית הבית טמא לא שהשליא ולד אלא שאין שליא שאין ולד עמה דברי רבי מאיר רבי יוסי ורבי יהודה ורבי שמעון מטהרין","אמרו לו לרבי מאיר אי אתה מודה שאם הוציאוהו בספל לבית החיצון שהוא טהור אמר להן אבל ולמה לפי שאינו","אמרו לו כשם שאינו בבית החיצון כך אינו בבית הפנימי אמר להן אינו דומה נמוק פעם אחת לנמוק ב' פעמים","יתיב רב פפא אחורי דרב ביבי קמיה דרב המנונא ויתיב וקאמר מאי טעמא דרבי שמעון קסבר כל טומאה שנתערב בה ממין אחר בטלה","אמר להו רב פפא היינו נמי טעמייהו דרבי יהודה ורבי יוסי אחיכו עליה מאי שנא פשיטא","אמר רב פפא אפילו כי הא מילתא לימא איניש ולא נשתוק קמיה רביה משום שנאמר (משלי ל, לב) אם נבלת בהתנשא ואם זמות יד לפה","ואזדא רבי שמעון לטעמיה דתניא מלא תרוד רקב שנפל לתוכו עפר כל שהו טמא ורבי שמעון מטהר","מאי טעמא דרבי שמעון אמר רבה אשכחתינהו לרבנן דבי רב דיתבי וקאמרי אי אפשר שלא ירבו שתי פרידות עפר על פרידה אחת של רקב וחסיר ליה","ואמינא להו אדרבה א\"א שלא ירבו שתי פרידות רקב על"],[[0,"חומר שני ולדות","אם זה זכר חיישינן דלמא נקבה הוה ההוא דשליא ותשב לזכר ולנקבה ולרבנן דאמרי המפלת חיה ועוף אינו ולד מאי חומרא איכא בהאי ולד מחמרינן עלה למימר ליכא שום ולד ואין לה דם טוהר והיינו חומרא דיליה ומשום שליא מטמינן לה שבועים:"],[0,"שאני אומר","ולד הוה עם השליא ונימוח שפיר של שליא:"],[0,"שפיר","ולד:"],[0,"ושמא נימוחה שלייתו של שפיר","כלומר ושלייתו של זה שלפנינו נימוח וזו אינה שלו הואיל ואינה קשורה בו. קתני מיהא בזמן שקשורה עמהן:"],[0,"תיובתא","דרבי דאמר דבר שאינו שאלת:"],[1,"אחר הולד","אבל יצתה שליא קודם חוששין לאחר:"],[4,"הניחא למ\"ד כו'","פלוגתייהו לקמן בפ' בנות כותים (נדה דף לח:):"],[4,"לסוף ז'","יום או יומים בתוך חדש ז' בסופו דחיי:"],[4,"ואחד לתחלת תשעה","יום אחד בחדש דהוו להו ל\"ג:"],[4,"אלא למ\"ד אינה יולדת למקוטעים היכי משכחת לה","תרוייהו בחדש השביעי ליכא למימר דחדש כולי האי לא הוי ואם זה לסוף ז' וזה לסוף ט' טפי איכא ואם זה בז' וזה בח' לא חיי ומדקרי להו ולד ולא נפל מכלל דבני קיימא נינהו:"],[5,"איפוך שמעתא","דר' יוחנן:"],[5,"כ\"ג לולד","משכחת לה דאחד נגמרה צורתו לתחלת ז' ואחד לסוף ז' דלכו\"ע יולדת לז' יולדת למקוטעין:"],[7,"האמר מר כו'","קס\"ד בג' חדשים לא משכחת לה אא\"כ נתעברה זה אחר זה:"],[9,"לבית החיצון","לבית אחר שהבית טהור:"],[9,"אבל","הן:"],[10,"אמרו לו למה","מאי שנא בית ראשון דמטמית ליה אמר להו לפי שאינו הואיל וטלטלוהו נמוק:"],[11,"מ\"ט דר\"ש","נהי דנמוק מ\"מ כל גופו של מת כאן הוה וה\"ל כרקב וכנצל [בשר המת שנימוח ונעשה ליחה סרוחה]:"],[11,"ממין אחר","אפי' ממין טומאה אם אינה שוה לה בטלה:"],[12,"אחיכו עליה","אמרו ליה פשיטא מאי שנא טעמייהו מטעמיה כולה חדא מילתא אמרי:"],[13,"אפי' כי האי מילתא","דאתיא לידי חוכא:"],[13,"לימא איניש","דלמא מתוך דבריו אמרי ליה טעמא:"],[13,"ולא לישתוק","ולימא מסברנא ליה:"],[13,"אם נבלת","עצמך על ד\"ת סופך להתנשא:"],[13,"ואם זמות","ושתקת סופך לשום יד על פה שלא תדע להשיב לשואלין:"],[14,"מלא תרוד","כף:"],[14,"רקב","רקבובית של מת וזה שיעורו לטמא באהל הלכה למשה מסיני:"],[16,"א\"א","אף על גב דרובא רקב אי אפשר למקום שנפל העפר שלא תהא גרגר של רקב בין שני גרגרים של עפר ובטל הרקב ובציר לו שיעורא דתרוד:"]],[[0,"","חומר שני ולדות. פי' הקונטרס לר\"מ דבחיה ועוף טמאה לידה הוי חומר ב' ולדות אם חיה ועוף הם זכר יהבינן לה חומר שליא דמספקינן בנקבה לטומאה וחומר חיה ועוף לטהרה דשמא אין ולד בשליא וקשה לר\"מ אי חיה ועוף זכר אמאי מספקא שליא בנקבה הא הוי ספק ספיקא דשמא אין בשליא ולד ואפילו יש שמא זכר הוא ולכך י\"ל חומר ב' ולדות דקאמר היינו לענין שהפילה שליא בשני אחר חיה ועוף ולרבנן דאמרי דאין טומאת לידה בחיה ועוף לית לה ימי טוהר כלל דשמא אין ולד בשליא ומשום שליא נותנין לה חומרא דזכר ונקבה וא\"ת לרבנן נימא שלא תשב רק ז' לטומאת לידה דאימור אין ולד בשליא ואפי' יש שמא זכר הוא וי\"ל דא\"כ אם תראה ביום ל\"ד ותחזור ותראה ביום מ\"א איכא למימר נמי אימור לא ילדה כלל והויא במ\"א שומרת יום כנגד יום ואפי' איכא ולד אימור נקבה היא ושתי ראיות דם טוהר הוא א\"א בתרווייהו למיזל לקולא דסתרו אהדדי אזלינן בתרווייהו לחומרא וכן צ\"ל אמתניתין דקתני המפלת ואין ידוע אם ולד הוא תשב לזכר ולנקבה ולנדה אע\"ג דאיכא ספק ספיקא שמא לא ילדה ואפי' ילדה שמא זכר הוא ואמאי תשב לנקבה אלא ודאי כדפרישית:"],[4,"","אלא למ\"ד אינה יולדת למקוטעין מאי איכא למימר. וא\"ת ונימא דנגמר צורתו ואשתהי עד שמיני דהכי אית ליה לרבה תוספאה בפ' הערל (יבמות דף פ:) דעבד עובדא באשה שהלך בעלה למדינת הים וילדה לי\"ב חדש ואכשריה ויש לומר דרוב אמוראים לית להו דרבה תוספאה:"],[15,"","מ\"ט דר\"ש. משום דבמתניתין אינו מזכיר כי אם ר\"ש קאמר מ\"ט דר\"ש פ\"ה נהי דנימוק מ\"מ כל הגוף של המת כאן וה\"ל כרקב של מת וכנצל וקשה דא\"כ מאי משני כל טומאה שנתערב בה מין אחר בטלה והיכי בעי למימר דבטל הולד משום דדם הלידה מבטל משהו מן הולד כמו מלא תרוד דמייתי התם ודאי דשיעורו מצומצם כי יתבטל ממנו משהו בציר ליה שיעורא מן התרוד אבל כי יתבטל מעט מן הולד אכתי ישאר יותר מכזית או ממלא תרוד לכך נראה לר\"י דנפל שבשליא אין עליו תורת נצל ורקב כיון שאינו נגמר ואינו בשר לטמא בכזית אלא מטעם מת שלם וה\"פ מ\"ט דר\"ש הרי יש כאן מת שלם ומשני כל טומאות שנתערבה כו' ומהאי טעמא כי נתבטל ממנו משהו טהור והשתא מייתי שפיר ממלא תרוד רקב ופריך אדרבה כו' וה\"נ השפיר מבטל משהו של מין אחר ומשני רבי יוחנן משום בטול ברוב נגעו בה שדם הלידה והליחה רבה על כל השפיר ומשבטל כולו בטל אף בבית ראשון ור\"ל סבר דאפילו בלא בטול ברוב טהור משום בלבול צורה שנטרף במימיו ונתבלבל צורתו לר\"ש אף בבית הראשון ומדר\"ל נמי יש להוכיח דלא מטמא משום רקב ונצל דא\"כ לא הוה מטהרינן משום בלבול אלא ודאי טמא מטעם מת שלם ובעי נמי ר\"ל שלם בצורתו ושאר אמוראי פליגי עליה בבלבול צורה אך בעי שיהא שלם וא\"ת למאי דס\"ד דרבי שמעון מטהר אף בבית הפנימי משום בטול משהו היכי קתני בברייתא כשם שאינו בבית החיצון כך אינו בבית הפנימי משום בטול משהו הלא גם לרבי שמעון לא נתבטל כולו בבית הפנימי כמו בבית החיצון אלא דמטהר משום בטול משהו ויש לומר דה\"ק כשם שאתה מודה בבית החיצון שנימוק כך יש לטהר בבית הפנימי משום בטול משהו דאין כאן מת שלם ואם תאמר בנזיר פרק כ\"ג (דף נ.) דפריך על המת ועל כזית מן המת נזיר מגלח על כזית מן המת מגלח על המת לא כ\"ש ומשני לא נצרכה אלא למת שאין בו כזית בשר ולא נתקשרו אבריו בגידין אמאי לא משני בשליא שאינה מטמא אלא שלם וי\"ל דשליא לא מקריא מת א\"נ היינו הא דמשני התם:"]]],[["פרידה אחת עפר (ונפיל) ליה שיעורא","אלא אמר רבה היינו טעמא דרבי שמעון סופו כתחלתו מה תחלתו נעשה לו דבר אחר גנגילון אף סופו נעשה לו דבר אחר גנגילון","מאי היא דתניא איזהו מת שיש לו רקב ואיזהו מת שאין לו רקב נקבר ערום בארון של שיש או ע\"ג רצפה של אבנים זהו מת שיש לו רקב","ואיזהו מת שאין לו רקב נקבר בכסותו או בארון של עץ או ע\"ג רצפה של לבנים זהו מת שאין לו רקב ולא אמרו רקב אלא למת בלבד למעוטי הרוג דלא","גופא מלא תרוד רקב שנפל לתוכו עפר כל שהוא טמא ור' שמעון מטהר מלא תרוד רקב שנתפזר בבית הבית טמא ורבי שמעון מטהר","וצריכא דאי אשמעינן קמייתא בההיא קאמרי רבנן משום דמכניף אבל נתפזר אימא מודו לו לרבי שמעון דאין מאהיל וחוזר ומאהיל","ואי אשמעינן בהא בהא אמר רבי שמעון דאין מאהיל וחוזר ומאהיל אבל בהא אימא מודה להו לרבנן צריכא","תניא אידך מלא תרוד ועוד עפר בית הקברות טמא ורבי שמעון מטהר מאי טעמייהו דרבנן לפי שא\"א למלא תרוד ועוד עפר בית הקברות שאין בו מלא תרוד רקב","השתא דאמרת טעמא דרבי שמעון משום סופו כתחלתו גבי שליא מאי טעמא אמר רבי יוחנן משום בטול ברוב נגעו בה","ואזדא רבי יוחנן לטעמיה דאמר רבי יוחנן רבי שמעון ור\"א בן יעקב אמרו דבר אחד רבי שמעון הא דאמרן רבי אליעזר דתניא רבי אליעזר בן יעקב אומר בהמה גסה ששפעה חררת דם הרי זו תקבר ופטורה מן הבכורה","ותני רבי חייא עלה אינה מטמאה לא במגע ולא במשא ומאחר שאינה מטמאה לא במגע ולא במשא אמאי תקבר כדי לפרסמה שהיא פטורה מן הבכורה","אלמא ולד מעליא הוא ואמאי תני רבי חייא אינה מטמאה לא במגע ולא במשא אמר רבי יוחנן משום בטול ברוב נגעו בה","א\"ר אמי אמר רבי יוחנן ומודה רבי שמעון שאמו טמאה לידה","אמר ההוא סבא לרבי אמי אסברא לך טעמא דרבי יוחנן דאמר קרא (ויקרא יב, ב) אשה כי תזריע וילדה זכר וגו' אפילו לא ילדה אלא כעין שהזריעה טמאה לידה","ריש לקיש אמר שפיר שטרפוהו במימיו נעשה כמת שנתבלבלה צורתו","אמר ליה רבי יוחנן לריש לקיש מת שנתבלבלה צורתו מנלן דטהור אילימא מהא דאמר רבי שבתאי אמר ר' יצחק מגדלאה ואמרי לה א\"ר יצחק מגדלאה א\"ר שבתאי מת שנשרף ושלדו קיימת טמא מעשה היה וטמאו לו פתחים גדולים"],[[0,"פרידה","גרגיר:"],[1,"סופו","של רקב כתחלתו:"],[1,"מה תחלתו","כשנקבר אם יש דבר הראוי לירקב ולעשות רקב של מת:"],[1,"גנגילון","בטול. שאותו דבר אחר מבטלו אף סופו לאחר שנעשה רקב כשנקבר כהלכתו ד\"א המתערבת בו מבטלו ולשון גנגילון דבר העומד כנגדו לבטלו ולקלקלו. ולקמן פריך הואיל וטעמא דר\"ש ברקב כדאמר השתא גבי שליא דליכא למימר הכי מ\"ט:"],[2,"מאי היא","דאמר תחלתו ד\"א נעשה לו גנגילון:"],[2,"שאין לו רקב","שאין רקב שלו מטמא:"],[2,"ערום בארון של שיש או ע\"ג רצפה של אבנים","דהשתא אין תערובת ברקבוביתו:"],[3,"נקבר בכסותו","דאיכא רקבובית או אפילו ערום בארון של עץ דאיכא רקבובית:"],[3,"או ע\"ג רצפה של לבנים","שעפרן נמחה:"],[3,"שאין לו רקב","מפני דבר אחר המעורב בו:"],[3,"לאפוקי הרוג דלא","לפי שיצא דמו וחסר וקיימא לן במס' נזיר (דף נא.) מת שחסר אין לו רקב:"],[4,"שנתפזר בתוך הבית [הבית] טמא","משום אהל:"],[5,"דאין מאהיל וחוזר ומאהיל","גג שכנגד זה מאהיל על חצי שיעור ושכנגד זה מאהיל על חצי שיעור ושני אהלות הן ואין מצטרפין:"],[7,"מלא תרוד ועוד","יותר ממלא תרוד עפר בית הקברות. ל\"א רקב ממש של מת אלא כגון שנקבר בכסותו או בקרקע בלא ארון של שיש ויש כאן מלא תרוד ועוד מאותו עפר דהוו מעורבין רקב ועפר:"],[8,"בטל ברוב","שדם הלידה נתרבה על מיחוי הולד ומבטלו:"],[9,"אמרו דבר אחד","ולקמן מוקמינן דר\"א בן יעקב משום בטול ברוב:"],[9,"בהמה גסה","שלא היה לה ולד מעולם:"],[9,"תקבר","החררה שהוא מיחוי של בכור:"],[9,"ופטורה מן הבכורה","שאם תלד עוד אין ולדה לכהן:"],[10,"אינה מטמאה","אותה חררה:"],[10,"ומאחר דאינה מטמאה","אלמא לא חיישינן לולד אמאי תקבר:"],[10,"ומשני כדי לפרסמה","שנפטרה מן הבכורה שידעו הכל שזה פטר רחם:"],[11,"","ופרכינן מדפטורה מן הבכורה אלמא ולד מעליא היא אמאי אינה מטמאה:"],[11,"בטול ברוב","מיחוי הנפל בטל בדם:"],[12,"ומודה ר\"ש","במתני' בשליא אע\"ג שהבית טהור אמו טמאה לידה:"],[13,"כעין שהזריעה","כלומר דנימוח כזרע:"],[14,"שטרפוהו","כמו (חולין סד.) ביצים טרופות בקערה. שמחקוהו ובלבלוהו:"],[14,"במימיו","שהדיחוהו בהן. א\"נ במי הלידה והטינוף שיוצא עמו:"],[15,"שנתבלבלה","נמחק כולו כמו שרוף שנתפזר ואין שלדו קיימת:"],[15,"ושלדו קיימת","גופו קיים שלא נתפזר האפר ועדיין נראה כשלם:"],[15,"פתחים גדולים","של ארבעה טפחים:"]],[[1,"","גלגילון. פירש בערוך דבר הנגלל עמו:"],[3,"","למעוטי הרוג. דמחוסר דם והא דאמר עולא בפ' כ\"ג (נזיר נא.) אין רקב למת אלא לבא מן הבשר מן הגידין ומן העצמות א\"כ משמע דאין רקב טמא אא\"כ בא משלשתן יחד אבל רקב מדם לא בעי מ\"מ אם חסר מדמו בשעה שנקבר אין לו דין רקב:"],[7,"","מלא תרוד ועוד. פ\"ה כגון שנקבר בכסותו ואין נראה לרשב\"ם דבתחלה מודו כ\"ע דדבר אחר נעשה לו גלגילון ונראה לרשב\"ם דהכא מיירי בנקבר ערום ודרכן היה לטוח כוכין בסיד ומיד שנתרקב היה התרוד ממנו טמא ואח\"כ נפל מן הסיד ונתערבה עם הרקב שכבר היה טמא ומהך לא עביד צריכותא דקמ\"ל משום דא\"א שלא יהא תרוד מרקב קודם שנתערב בו עפר:"],[10,"","כדי לפרסמה שפטורה. הא דתנן בפ' בהמה המקשה (חולין דף עז.) מבכרת שהפילה שליא ישליכנה לכלבים התם א\"צ פרסום דהכל יודעים שיש ולד בשליא:"],[11,"","משום בטול ברוב נגעו בה. וא\"ת דבבכורות פרק הלוקח בהמה (בכורות כג.) גבי נבלה בטלה בשחוטה וקאמר אין מטמאה במגע אבל מטמאה במשא דטומאה כמאן דאיתא דמיא ופריך מחררת דם דאינה מטמאה לא במגע ולא במשא משום בטול ברוב אלמא דכמאן דליתיה דמיא ומשני משום דה\"ל טומאה סרוחה ופריך הניחא לבר פדא דדריש עד לגר אלא לר' דדריש עד לכלב קשיא ואמאי לא מקשה מהך דשפיר דאינו מטמא באהל משום בטול ברוב אלמא כמאן דליתיה דמי והשתא לא מצי לשנויי משום דהוי טומאה סרוחה דאפילו מת סרוח מטמא וי\"ל משום דאיכא למדחי דטעמא משום בילבול צורה כדר\"ל ולא משום בטול ברוב אי נמי כיון דטעמא דשפיר משום מת שלם אע\"ג דטומאה כמאן דאיתיה דמי אין להחשיבו שלם כיון שנתבטל ברוב לגמרי:"],[15,"","מת שנתבלבלה צורתו מנלן דטהור. וקשה מאי פריך ליה ר' יוחנן האמר בסמוך דר' יוחנן כר\"א וא\"כ ר\"ל ניחא טפי דקאי כרבנן דקתני במסכת אהלות וחכמים מטהרים וי\"ל דר\"י ור\"ל אליבא דרבנן פליגי דר\"ל סבר דלרבנן דמטהרי ברובע ה\"נ דמטהרי אפילו בשלם בשאין שלדו קיימת ונתבלבל צורתו אבל שלדו קיימת טמאה מדרבי יצחק דאתיא כרבנן דאי כר\"א אפי' אין שלדו קיימת טמא דהא מטמא ר\"א ברובע של אפר וא\"ל לר' יוחנן מנלן הא דרבנן מטהרו משום בלבול צורה דלמא טעמא דרבנן דכשנשרף אין עוד שם מת עליו אפילו כולו שלם ושלדו קיימת אבל שפיר שם מת עליו וטמא אי לאו משום דבטל ברוב ומילתא דרבי יצחק לא אתיא כרבנן אלא כר\"א דמטמא מת שרוף וחסר ושלדו קיימת נקט לטהר פתחים קטנים א\"נ קסבר ר' יוחנן דרבנן לא מטהרי אלא ברובע דחסר אבל אם העפר שלם אפי' אין שלדו קיימת טמא והשתא אתי שפיר שא\"צ לחלק בין שפיר ושליא למת שנשרף ואין שלדו קיימת דשניהם שוין לר\"ל ולר' יוחנן ובירושלמי איכא שפיר שנתבלבל צורתו מהו ר' יוחנן אמר טמא ר\"ל אמר טהור איתיביה ר\"ל לר' יוחנן מרבי יצחק מגדלאה ומשני דבר תורה אפילו שלדו קיימת טהורה מפני מה אמרו טמא מפני כבודו פירוש מפני כבודו של מת הוא דלא בטל וזהו כפירוש ראשון דאף בשלדו קיימת טהור דבר תורה וחולק על הגמרא שלנו דמוקי לה כר\"א מילתא דרבי יצחק והתם מוקי לה כרבנן:"]]],[["וטהרו לו פתחים קטנים וקא דייקת מינה טעמא דשלדו קיימת הא לאו הכי טהור","אדרבה דוק מינה להאי גיסא שלדו קיימת הוא דטהרו לו פתחים קטנים הא לאו הכי פתחים קטנים נמי טמאין דכל חד וחד חזי לאפוקי חד חד אבר","א\"ל רבינא לרב אשי ר' יוחנן דאמר כמאן כר' אליעזר דתנן אפר שרופין ר\"א אומר שיעור' ברובע","היכי דמי מת שנשרף ושלדו קיימת אמר אביי כגון ששרפו על גבי קטבלא רבא אמר כגון ששרפו על גבי אפודרים רבינא אמר כגון דאיחרכי אחרוכי","ת\"ר המפלת יד חתוכה ורגל חתוכה אמו טמאה לידה ואין חוששין שמא מגוף אטום באו","רב חסדא ורבה בר רב הונא דאמרי תרוייהו אין נותנין לה ימי טוהר מ\"ט אימא הרחיקה לידתה","מתיב רב יוסף המפלת ואין ידוע מה הפילה תשב לזכר ולנקבה ואי ס\"ד כל כהאי גוונא אימא הרחיקה לידתה לתני ולנדה","אמר אביי אי תנא לנדה הוה אמינא מביאה קרבן ואינו נאכל קמ\"ל דנאכל","אמר רב הונא הוציא עובר את ידו והחזירה אמו טמאה לידה שנאמר (בראשית לח, כח) ויהי בלדתה ויתן יד","מתיב רב יהודה הוציא עובר את ידו אין אמו חוששת לכל דבר אמר רב נחמן לדידי מיפרשא לי מיניה דרב הונא לחוש חוששת ימי טוהר לא יהבינן לה עד דנפיק רוביה","והא אין אמו חוששת לכל דבר קאמר אמר אביי אינה חוששת לכל דבר מדאורייתא אבל מדרבנן חוששת והא קרא קאמר מדרבנן וקרא אסמכתא בעלמא","\u0001מתני׳\u0002 המפלת טומטום ואנדרוגינוס תשב לזכר ולנקבה","טומטום וזכר אנדרוגינוס וזכר תשב לזכר ולנקבה טומטום ונקבה אנדרוגינוס ונקבה תשב לנקבה בלבד","יצא מחותך או מסורס משיצא רובו הרי הוא כילוד יצא כדרכו עד שיצא רוב ראשו ואיזהו רוב ראשו משיצא פדחתו","\u0001גמ׳\u0002 השתא טומטום לחודיה ואנדרוגינוס לחודיה אמר תשב לזכר ולנקבה טומטום וזכר אנדרוגינוס וזכר מיבעיא","איצטריך מהו דתימ' הואיל וא\"ר יצחק אשה מזרעת תחל' יולדת זכר איש מזריע תחלה יולדת נקבה אימא מדהאי זכר האי נמי זכר קמ\"ל אימא שניהם הזריעו בבת אחת זו זכר וזה נקבה","אמר ר\"נ אמר רב טומטום ואנדרוגינוס שראו לובן או אודם אין חייבין על ביאת מקדש ואין שורפין עליהם את התרומה","ראו לובן ואודם כאחד אין חייבין על ביאת מקדש אבל שורפין עליהם את התרומה שנאמר (במדבר ה׳:ג׳ ) מזכר ועד נקבה"],[[0,"וטהרו לו פתחים קטנים","הפחותים מארבעה כשאר מתים שלמים שהגדולים מצילין על הקטנים דקיי\"ל מת פתחו בארבעה אם הוא בבית כל הפתחים טמאים ואם פתח פחות מארבעה טהור והני מילי להציל את שאר פתחים אבל להוציא הא אמרי' פותח טפח מוציא הטומאה לצד שני והכי אמרי' במס' אהלות (פ\"ג מ\"ו) המת פתחו בארבעה בד\"א להציל את הפתחים אבל להוציא את הטומאה בפותח טפח:"],[2,"ר' יוחנן","דפליג עליה דריש לקיש דבעי למימר דמת שנתבלבלה צורתו טמא דאמר כמאן כר' אליעזר:"],[2,"ברובע","רובע הקב:"],[3,"קטבלא","עור שלוק וקשה ואינה נשרפת עם המת:"],[3,"אפודרא","אבן שייש. ותרוייהו כגון שעשויות בית קיבול ומחיצות שאין העפר יכול להתפזר:"],[3,"דאיחרך איחרוכי","המת ולא נעשה אפר:"],[5,"אין נותנין לה ימי טוהר","דאע\"ג דפשיטא לן דולד הוא:"],[5,"אימר הרחיקה לידתה","הרי כמה ימים שיצא רוב הולד לאברים וכבר עברו ימי טוהר שלה ולא ידעינן מאימת נמני:"],[6,"ניתני ולנדה","שכל דמים שתראה יהיו טמאים שלא יהיו לה ימי טוהר והכי איבעי ליה למיתני תשב לזכר ולנקבה ולנדה כלומר שבועיים דנקבה מטמאה בלא שום ראייה דדלמא נקבה הואי וימי טוהר לא יהיה לה שהרי כמה ימים שהתחילה לילד ויצא הרוב והיינו לנדה. ולקמן בהאי פירקא (נדה דף ל.) מפרש למה הוזכר זכר שאם תראה לסוף ל\"ד ותחזור ותראה ליום מ\"א תהא מקולקלת עד יום מ\"ח:"],[7,"הוה אמינא מביאה קרבן ואינו נאכל","דכיון דתני לנדה משמע דמספקא ליה אי ולד הוא אי לא קמ\"ל מדלא תני לנדה אלא לזכר ולנקבה דודאי פשיטא לן דולד הוא ומביאה קרבן ונאכל ומיהו ימי טוהר לית לה אימר הרחיקה לידתה:"],[8,"ויתן יד","אלמא לידת יד קרויה לידה:"],[10,"והא קרא קאמר","רב הונא אלמא לידה דאורייתא קרי ליה:"],[11,"מתני' לזכר ולנקבה","ימי טוהר לזכר וימי טומאה דנקבה:"],[12,"תשב לנקבה בלבד","אפי' הוי טומטום זכר בתר נקבות אזלינן דכל ימי זכר בין לטומאה בין לטהרה מובלעים תוך של נקבה:"],[13,"מסורס","דרך מרגלותיו ולשון היפוך הוא כמו סרס המקרא ודרשהו:"],[15,"גמ' איצטריך","אע\"ג דטומטום לחודיה מספקינן בזכר ובנקבה היכא דאיתיליד זכר בהדיה נימא זכר הוא דמוכחא מילתא דהיא הזריעה תחילה קמ\"ל:"],[16,"לובן","דומה לקרי:"],[16,"אודם","דומה לדם נדות:"],[16,"אין חייבין על ביאת מקדש","דלמא טהור הוא וקמייתי חולין בעזרה דאין זכר מטמא באודם ואין נקבה מטמאה בלובן:"],[16,"ואין שורפין עליהם תרומה","אלא תולין כי חזאי אודם איכא למימר זכר הוא ואין אודם מטמא בו ואי חזאי לובן איכא למימר נקבה היא ואין לובן מטמא בה הילכך תולין:"],[17,"ראו אודם ולובן כאחד","דממ\"נ טמא אפ\"ה לענין טומאת ביאת מקדש פטירי מקרבן כדמפרש טעמא:"]],[[3,"","שנשרף על גבי קטבלא. פי' עור שלוק היה בעור דפוס של אדם וצורתו דכי נמי נשרף עליו צורתו וחתוך אברים ניכרים:"],[16,"","אמר רב נחמן אמר רב טומטום ואנדרוגינוס כו'. קסבר רב דאנדרוגינוס ספק זכר ספק נקבה הוא דאי בריה הוא לא יטמא לא בלובן ולא באודם אלא ודאי סבר ספקא הוא והא דפסיק רב בפרק הערל (יבמות דף פג.) כר' יוסי באנדרוגינוס לא כר' יוסי דמתני' דהתם דאמר מאכיל בחזה ושוק דזכר ודאי הוי אלא כרבי יוסי דברייתא דקאמר התם אנדרוגינוס בריה בפני עצמו הוא ולא הכריעו בו חכמים לידע אם זכר אם נקבה ולאו בריה בעלמא הוא אלא כלומר ספקא וכן משמע לישנא דלא הכריעו והיינו כמו שסובר רב בשמעתין ובפ' בתרא דיומא (ד' עד.) דקאמר כל חלב לרבות כוי וחצי שיעור ופריך איצטריך קרא לרבויי ספקא ומשני דכוי בריה הוי האי בריה הוי בריה ממש ולא ספקא והקשה רבינו שמואל בחור דתניא בתוספתא דמס' בכורי' [פ\"ב] הריני נזיר שזה איש או אשה הרי הוא נזיר ר' יוסי אומר אנדרוגינוס בריה בפני עצמו הוא ולא יכלו חכמים להכריע אם איש או אשה אבל טומטום אינו כן אלא ספק איש או אשה ואי לר' יוסי אנדרוגינוס נמי ספק במאי פליגי ת\"ק והוא ועוד מאי אבל טומטום אינו כן וי\"ל דלעולם ספק הוא ולא דמי לספק טומטום דבטומטום לא שייך למיתני ביה ולא הכריעו חכמים דאין כולן שוין דלפעמים כשנקרע נמצא זכר ולפעמי' נקבה וספק שלו יכול להתברר אבל אנדרוגינוס כולם או זכר או נקבה אבל לא הכריעו חכמים איזהו ונפקא מינה אם קידש טומטום אשה או נתקדשה ונקרע וגם לענין שופר אמרי' (ר\"ה דף כט.) אנדרוגינוס מוציא את מינו טומטום אינו מוציא לא מינו ולא שאינו מינו ולא פליג ר' יוסי את\"ק אלא מפרש מילתיה דת\"ק או כולה ר' יוסי היא אי נמי פליגי וקאמר כיון דלא הכריעו חכמים אינו נזיר דלא היה בדעתו להיות נזיר אא\"כ הוי זכר ודאי או נקבה ודאית וכיון דלא הכריעו הוי לעולם ספק:"],[17,"","שנאמר מזכר ועד נקבה זכר ודאי כו'. תימה בשלמא טומטום איצטריך למעוטי כיון שיש טומטום שהוא זכר ויש טומטום שהוא נקבה ופטרו הכתוב כל זמן שהוא ספק כדממעט במעשר בהמה בקפץ אחד מן המנוין לתוכו עשירי ודאי אמר רחמנא ולא עשירי ספק ולעיל גבי ספק בהרת קדמה לשער לבן דדריש לה מקראי בשלהי נזיר (דף סה:) אבל אנדרוגינוס למה צריך למעוטי כיון דסבר רב דספק הוי וכולן שוין קמי שמיא גליא אם זכר אם נקבה ואמאי ממעט ליה והכי פריך בבכורות בפ' על אלו מומין (בכורות דף מא: ושם) בסופו גבי הא דתניא כשהוא אומר למטה הזכר שאין ת\"ל להוציא טומטום ואנדרוגינוס ופריך מני אילימא ת\"ק קסבר אנדרוגינוס ספקא הוא אצטריך קרא למעוטי ספקא וי\"ל דהתם פריך שפיר דממעט אנדרוגינו' מהזכר יתירא דכתיב גבי עולה ולהכי פריך אצטריך קרא למעוטי ספקא דכיון דקמי שמיא גליא אם נקבה הוי אמאי צריך למעוטי ואם זכר הוא בא למעוטי משום דמשונה משאר זכרים א\"כ ש\"מ דזכר הוא ולא ספק אבל הכא דכתיב מזכר ועד נקבה איכא למימר דממעט לה מטעם שהוא משונה והוי ספק משום דלא ידענא אי מזכר ממעט ליה והוי זכר או מנקבה ממעט ליה והוי נקבה ונראה לומר דתרי מיעוטי נינהו דהוי מצי למכתב מזכר ועד אדם או מנקבה ועד אדם ואתא חד לאנדרוגינוס וחד לטומטום אי נמי מההיא מיעוטא דממעטינן אנדרוגינוס ממעטינן נמי טומטום ולא נימא דתרי מיעוטי נינהו ואי מזכר ממעטינן להו איצטריך למכתב נקבה דלא נימא זכר למעוטי נקבה אתא או איפכא:"]]],[["תשלחו זכר ודאי נקבה ודאית ולא טומטום ואנדרוגינוס .","לימא מסייע ליה טומטום ואנדרוגינוס שראו לובן או אודם אין חייבין על ביאת מקדש ואין שורפין עליהם את התרומה ראו לובן ואודם כאחת אין חייבין על ביאת מקדש אבל שורפין עליהם את התרומה","מ\"ט לאו משום שנאמר (במדבר ה, ג) מזכר ועד נקבה תשלחו זכר ודאי נקבה ודאית ולא טומטום ואנדרוגינוס אמר עולא לא הא מני ר' אליעזר היא","דתנן רבי אליעזר אומר השרץ (ויקרא ה, ב) ונעלם ממנו על העלם שרץ הוא חייב ואינו חייב על העלם מקדש","רבי עקיבא אומר ונעלם ממנו והוא טמא על העלם טומאה הוא חייב ואינו חייב על העלם מקדש","ואמרינן מאי בינייהו ואמר חזקיה שרץ ונבלה איכא בינייהו דרבי אליעזר סבר בעינן עד דידע אי בשרץ איטמי אי בנבילה איטמי ור' עקיבא סבר לא בעינן","לאו אמר רבי אליעזר התם בעינן דידע אי בשרץ איטמי אי בנבלה איטמי הכא נמי בעינן דידע אי בלובן איטמי אי באודם איטמי","אבל לרבי עקיבא דאמר משום טומאה מיחייב הכא נמי משום טומאה מיחייב","ורב מאי שנא ביאת מקדש דלא דכתיב מזכר ועד נקבה תשלחו זכר ודאי נקבה ודאית ולא טומטום ואנדרוגינוס","אי הכי תרומה נמי לא נשרוף דכתיב (ויקרא טו, לג) והזב את זובו לזכר ולנקבה זכר ודאי נקבה ודאית ולא טומטום ואנדרוגינוס","ההוא מבעי ליה לכדרבי יצחק דאמר רבי יצחק לזכר לרבות את המצורע למעינותיו ולנקבה לרבות את המצורעת למעינותיה","האי נמי מבעי ליה במי שיש לו טהרה במקוה פרט לכלי חרס דברי רבי יוסי","אם כן נכתוב רחמנא אדם","וכי תימא אי כתב רחמנא אדם הוה אמינא כלי מתכות לא מכל טמא לנפש נפקא זכר ונקבה למה לי לכדרב","ואימא כוליה לכדרב הוא דאתא אם כן נכתוב זכר ונקבה מאי מזכר ועד נקבה עד כל דבר שיש לו טהרה במקוה","אי הכי כי איטמי בשאר טומאות לא לישלחו אמר קרא מזכר מטומאה הפורשת מן הזכר","וכל היכא דכתיב מזכר עד נקבה למעוטי טומטום ואנדרוגינוס הוא דאתא והא גבי ערכין דכתיב (ויקרא כז ) הזכר","ותניא הזכר ולא טומטום ואנדרוגינוס יכול לא יהא בערך איש אבל יהא בערך אשה תלמוד לומר הזכר ואם נקבה זכר ודאי נקבה ודאית ולא טומטום ואנדרוגינוס","טעמא דכתיב הזכר ואם נקבה הא מזכר ונקבה לא ממעט ההוא מבעי ליה"],[[2,"תשלחו","היינו שילוח טמאים ממקדש:"],[2,"רבי אליעזר היא","דבעי לענין קרבן טומאה עד דידע במאי איטמי אבל לרבנן דלא בעו בשאר טומאות עד דידע במאי איטמי הכא נמי מחייבי דלא דרשינן זכר ודאי נקבה ודאית:"],[3,"השרץ ונעלם","או בנבלת שרץ ונעלם ממנו:"],[3,"על העלם שרץ","שנטמא וידע ובשעה שנכנס נעלם ממנו טומאה חייב:"],[3,"ואינו חייב על העלם מקדש","אם כשנכנס למקדש זכור לטומאה ונעלם ממנו מקדש ונכנס שאינו סבור שזה מקדש וכשיצא נזכר פטור:"],[5,"שרץ ונבלה","לפניו וידע שנגע באחד מהם ואינו יודע באיזה מהם נגע וכשבא למקדש שכח אותו ומשיצא נזכר:"],[6,"ר' אליעזר","דאזכר שם שרץ סבר דבעינן עד דידע אם בשרץ איטמי כו':"],[9,"הזב את זובו לזכר ולנקבה","ולדרוש נמי זכר ודאי נקבה ודאית מטמא בזיבה ולא טומטום:"],[10,"לזכר לרבות מצורע","שהוא מוקש לזב להיות מעינותיו אב הטומאה לטמא אדם וכלים כזב דכתיב ביה (ויקרא ט״ו:ח׳) וכי ירוק הזב וגו':"],[11,"פרט לכלי חרס","טמא שאין טעון שילוח מן העזרה:"],[13,"הוה אמינא כלי מתכות לא","טעון שילוח ולהכי שני בדיבוריה למדרש כל שיש לו דין הנוהג בזכר ובנקבה דהיינו טהרה במקוה:"],[13,"מוכל טמא נפקא","דאף כלי מתכות בעי שילוח ועל כרחין הוה דרשינן אדם ודמי ליה ולא כלי חרס שאין לו טהרה:"],[14,"עד נקבה","משמע כל מי שיש לו דין שהוא מזכר עד נקבה שיש להן טהרה:"],[15,"אי הכי","לעיל קאי. כיון דאמר רב לענין שילוח זכר ודאי ולא טומטום בשאר טומאות נמי כגון טומטום שנטמא במת או בשרץ ונכנס למקדש יפטר:"],[15,"הזכר","והיה ערכך הזכר:"],[17,"תלמוד לומר הזכר","ה\"א דריש:"],[17,"אם נקבה","אם קדריש:"],[18,"ההוא מיבעי ליה","למכתב זכר ונקבה:"]],[[2,"","אמר עולא הא מני ר' אלעזר היא. והא דתנן שלהי הערל (יבמות פג:) רבי אליעזר אומר אנדרוגינוס חייבין עליו סקילה כזכר הא אמרינן התם לא לכל אמר רבי אליעזר אנדרוגינוס חייבין עליו אי נמי י\"ל דהכא הכי קאמר האי תנא דאמר אין חייבין על ביאת מקדש דריש הארץ כרבי אליעזר:"],[11,"","פרט לכלי חרס גרסי'. ותו לא ולא גרס שאין לו טהרה במקוה דבשלהי המוצא תפילין (עירובין קד:) בעי למימר משום דאינו נעשה אב הטומאה ואין צריך למוחקו דאף ע\"ג דאינו מן הברייתא נקטיה הש\"ס משום דמסיק התם דה\"ה שרץ אע\"ג דאב הטומאה הוא וא\"ת דאמר בפ\"ק דסוטה (דף ט) ובפרק אלו דברים (פסחים סז.) אפי' מת מותר ליכנס במחנה לויה שנאמר ויקח משה את עצמות יוסף עמו וגו' מאי אפי' אדרבה מת קיל טפי דאין לו טהרה במקוה ואפילו במחנה שכינה נמי ויש לומר דאיכא למ\"ד שילהי עירובין (דף קד:) דמחייב מכניס שרץ למקדש אע\"ג דאין לו טהרה במקוה וה\"ה מת אי נמי מת מחייב טפי משום דיש במינו טהרה במקוה כגון אדם חי:"],[13,"","הוה אמינא כלי מתכות לא. הוי מצי למנקט כלי שטף אלא נקט כלי מתכות משום דחמיר דחרב הרי הוא כחלל:"],[14,"","עד כל דבר שיש לו טהרה במקוה. מלשון עד דריש כדפ\"ה דמשמע כל מי שיש לו דין שמזכר עד נקבה דהיינו שיש לו טהרה במקוה וא\"ת כל טמא לנפש אם כן למאי אתא ויש לומר דבריש אלו דברים בפסחים (דף סו:) דריש ליה שפיר:"],[15,"","אי הכי בשאר טומאות נמי. פירוש כיון דדריש מזכר ועד נקבה למי שיש לו טהרה במקוה אם כן מוקמינן קרא גם בשאר טומאות דלאו לובן ואודם דשייכו בכלים ואם כן דטומאת מת ושרץ נמי לא לישלחו טומטום ואנדרוגינוס:"],[17,"","תלמוד לומר הזכר. ה\"א דהזכר דריש ותימה דבפ' על אלו מומין (בכורות דף מא:) אמרינן שאני הכא דכתיב הזכר הזכרים משמע משום דכתיב הזכרים אבל ה\"א דהזכר לא חשיב יתור למעט אנדרוגינוס ושמא איכא שום דרשא התם דדריש מה\"א:"],[18,"","הא מזכר לחודיה לא ממעט. הך ברייתא אתיא כרבי יהודה כדמוכח במסכת שבת בפרק ר\"א דמילה (שבת דף קלו:) על הא דקאמר רבי יהודה אנדרוגינוס דוחה שבת דקאמר רב חסדא לא לכל אמר ר' יהודה זכר הוא שאם אתה אומר כן בערכין יערך ותניא הזכר ולא טומטום כו' פירוש סתם ספרא רבי יהודה וקאמר רב נחמן בר יצחק אף אנן נמי תנינא אדרוגינוס פסול לקדוש מי חטאת דברי רבי יהודה ופריך מאי שנא גבי מילה ומשני משום דכתיב המול לכם כל זכר והשתא תימה דהכא גבי ערכין צריך יתורא למעט טומטום ואנדרוגינוס ולא ממעט להו מלשון זכר ונקבה וגבי מילה אדרבה צריך יתורא לרבות וגבי קדוש ממעט ליה אף ע\"ג דליכא יתורא אחרינא לאנדרוגינוס אלא משום דכתיב ונתן ולא כתיב ונתנה למעוטי אשה והנה מצינו למימר דכיון דגלי בערכין דלא הוי בכלל זכר ילפינן קדוש מערכין ומילה נמי הוה ילפינן אי לאו דגלי קרא דכל זכר והא דלא ילפינן קדוש ממילה משום דטפי אית לן למילף מערכין לחומרא והכא דפריך וכל היכא דכתיב זכר למעט טומטום ואנדרוגינוס והא גבי ערכין כו' לא מצי לשנויי דמערכין ילפינן דאדרבה ממילה אית לן למילף דהוי בכלל זכר כדי להטעינו שילוח ולא מערכין לקולא ובפרק על אלו מומין (בכורות מא:) דמצריך קרא יתירא למעט טומטום ואנדרוגינוס דקאמר כשהוא אומר הזכר למטה שאין ת\"ל ולא ילפינן מערכין לחומרא שלא להכשירו לעולה ולהצריך קרבן אחר התם אצטריך קרא לקרבן נדבה כגון שאמר הרי זו עולה והוי קולא שאינו קדוש דלא הוה ילפינן מערכין לקולא אלא ממילה לחומרא ולהכי אצטריך קרא אך קשה דבפ' הערל (יבמות עב:) משמע דלא פסיל ליה ר' יהודה לענין קדוש אלא משום דהוי ספק איש ספק אשה דתנן התם ר' יהודה אומר אנדרוגינוס שקדש קדושיו פסולין משום שהוא ספק אשה ואשה פסולה לקדש וי\"ל דלגבי ערך אף ע\"ג דהוא זכר או נקבה ממעטו הכתוב מערך איש ואשה לפי שהוא משונה ואי הוה מיעוטא דזכר לחודיה הוה אמינא דאפקיה רחמנא מערך זכר ואוקמיה בערך נקבה אפילו הוא זכר וכן איפכא וגבי מילה אי נקבה היא הא איצטריך קרא לרבויי ואי זכר הוא שמא איכא שום דרשא דהוה ממעטינן ליה אי לאו דריבהו הכתוב וההיא דבכורות (דף מא:) דהזכר ולא טומטום ואנדרוגינוס איכא למימר דלא אתיא כר' יהודה דכיון דספק הוא לא אצטריך קרא למעוטי ספקא ואף ע\"ג דסתם ספרא ר' יהודה היא היינו בסתמא אחרינא אבל הא ע\"כ לאו רבי יהודה היא:"]]],[["לחלק בין ערך איש לערך אשה","יצא מחותך או מסורס וכו' א\"ר אלעזר אפילו הראש עמהן","ור' יוחנן אמר לא שנו אלא שאין הראש עמהן אבל הראש עמהן הראש פוטר","לימא בדשמואל קמיפלגי דאמר שמואל אין הראש פוטר בנפלים","בשלם דכולי עלמא לא פליגי כי פליגי במחותך דמר סבר בשלם הוא דקחשיב במחותך לא קחשיב ומר סבר במחותך נמי חשיב","לישנא אחרינא טעמא דיצא מחותך או מסורס הא כתקנו הראש פוטר תרוייהו לית להו דשמואל דאמר שמואל אין הראש פוטר בנפלים","איכא דמתני לה להא שמעתתא באפי נפשה א\"ר אלעזר אין הראש כרוב אברים ורבי יוחנן אמר הראש כרוב אברים וקמיפלגי בדשמואל","תנן יצא מחותך או מסורס משיצא רובו הרי הוא כילוד מדקאמר מסורס מכלל דמחותך כתקנו וקאמר משיצא רובו הרי זה כילוד קשיא לרבי יוחנן","אמר לך רבי יוחנן אימא יצא מחותך ומסורס","והא או קתני הכי קאמר יצא מחותך או שלם וזה וזה מסורס משיצא רובו הרי זה כילוד","אמר רב פפא כתנאי יצא מחותך או מסורס משיצא רובו הרי הוא כילוד רבי יוסי אומר משיצא כתקנו מאי קאמר","אמר רב פפא הכי קאמר יצא מחותך ומסורס משיצא רובו הרי הוא כילוד הא כתקנו הראש פוטר רבי יוסי אומר משיצא רובו כתקנו","מתקיף לה רב זביד מכלל דבמסורס רובו נמי לא פוטר הא קי\"ל דרובו ככולו","אלא אמר רב זביד הכי קאמר יצא מחותך ומסורס משיצא רובו הרי זה כילוד הא כתקנו הראש פוטר רבי יוסי אומר משיצא כתקנו לחיים","תניא נמי הכי יצא מחותך (או) מסורס משיצא רובו הרי זה כילוד הא כתקנו הראש פוטר ר' יוסי אומר משיצא כתקנו לחיים","ואיזהו כתקנו לחיים משיצא רוב ראשו ואיזהו רוב ראשו ר' יוסי אומר משיצאו צדעיו אבא חנן משום ר' יהושע אומר משיצא פדחתו וי\"א משיראו קרני ראשו","\u0001מתני׳\u0002 המפלת ואין ידוע מהו תשב לזכר ולנקבה אין ידוע אם ולד היה אם לאו תשב לזכר ולנקבה ולנדה","\u0001גמ׳\u0002 א\"ר יהושע בן לוי עברה נהר והפילה מביאה קרבן ונאכל הלך אחר רוב נשים ורוב נשים ולד מעליא ילדן","תנן אין ידוע אם ולד היה תשב לזכר ולנקבה ולנדה אמאי תשב לנדה לימא הלך אחר רוב נשים ורוב נשים ולד מעליא ילדן","מתני' בשלא הוחזקה עוברה וכי קאמר ריב\"ל כשהוחזקה עוברה","ת\"ש בהמה שיצאה מלאה ובאה ריקנית הבא אחריו בכור מספק","ואמאי הלך אחר רוב בהמות ורוב בהמות ולד מעליא ילדן והאי פשוט הוא","אמר רבינא משום דאיכא למימר רוב בהמות יולדות דבר הפוטר מבכורה ומעוטן יולדות דבר שאינו פוטר מבכורה וכל היולדות מטנפות וזו הואיל ולא טנפה אתרע לה רובא","אי כל היולדות מטנפות הא מדלא מטנפה בכור מעליא הוא אלא אימא רוב יולדות מטנפות וזו הואיל ולא טנפה אתרע לה רובא","כי אתא רבין אמר מתיב רבי יוסי ברבי חנינא טועה ולא ידענא מאי תיובתא מאי היא דתניא"],[[0,"לחלק","הילכך אי לאו ה\"א ואם לא ממעט טומטום אבל הכא מדה\"ל למכתב אדם תשלחו וכתיב זכר ונקבה ש\"מ לדרשא:"],[1,"ואפילו הראש עמהם","אמחותך קאי דהיכא דיצא מחותך אפי' יצא הראש אין חשוב ולד עד שיצא רובו:"],[3,"אין הראש פוטר בנפלים","יצא ראש הנפל כגון יולדת תאומים לשבעה אחד נגמרה צורתו ואחד לא נגמרה צורתו ויצא ראש הנפל והחזירו ואח\"כ יצא אחיו הוי בכור לכהן שאין ראש הנפל פוטר את הבא אחריו מן הבכורה ורבי אלעזר אית ליה דשמואל:"],[6,"באנפי נפשיה","ולא אמתניתין. ואיכא בינייהו מאן דמתני לה אמתניתין משמע דאמחותך קא פליגי ואיכא למימר כדאמרן דבשלם אפי' ר' אלעזר מודה דלית ליה דשמואל ומאן דמתני לה באנפי נפשיה משמע דאשלם נמי פליגי ובדשמואל:"],[6,"אין הראש כרוב אברים","יצא הראש אינו כילוד. ובנפל קאי דאי בבן קיימא ליכא למ\"ד דהא מתניתין היא יצא כדרכו משיצא רוב ראשו:"],[10,"כתקנו","ראש יצא תחלה וקאמר דבעינן רובא וקשיא לר' יוחנן:"],[10,"מאי קאמר","רבי יוסי משיצא כתקנו ס\"ד דמסורס ברובא לאו ילוד הוא:"],[11,"מחותך ומסורס","מחותך ודרך מרגלותיו:"],[11,"הא כתקנו","דרך ראשו אפי' מחותך הראש פוטר:"],[11,"רובו כתקנו","תרוייהו בעינן במחותך:"],[12,"מתקיף לה רב זביד","לתירוצא דמתרצינן אליבא דרבי יוסי:"],[12,"מכלל דמסורס רובו נמי לא פטר","בתמיה. כיון דרבי יוסי לאו אדיוקא קאי אלא אדקתני בגווה יצא מחותך ומסורס משיצא רובו ועלה קאי דרבי יוסי ואמר אע\"ג דנפיק רובו בעינן נמי כתקנו מכלל דמסורס רובו נמי לא פטר בתמיה:"],[13,"אלא אמר רב זביד","רבי יוסי אדיוקא דת\"ק קאי דאמר הא כתקנו הראש פוטר ואע\"ג דמחותך וקאמר ר' יוסי אין הראש פוטר אלא שיצא כתקנו וכשאר ולדות שיוצאין לחיים אבל מחותך אפילו כתקנו אין הראש פוטר:"],[13,"כתקנו","אפי' מחותך הראש פוטר:"],[14,"מי שיצא כתקנו לחיים","הוא דראש פוטר אבל מחותך אפילו כתקנו בעינן רובו:"],[15,"צדעיו","טנפל\"ש:"],[15,"קרני ראשו","גובה ראשו שאצל העורף:"],[16,"מתני' ואין ידוע מהו","אם זכר אם נקבה אבל יודעת היא שהוא ולד:"],[16,"לזכר ולנקבה","ימי טוהר דזכר וימי טומאה דנקבה:"],[16,"אין ידוע אם ולד היה אם לאו תשב לזכר ולנקבה ולנדה","כלומר כשתראה תהא נדה שאין לה ימי טוהר דשמא לאו ולד הוא. ובגמרא מפרש למה הוזכר זכר הואיל ואין לה דם טוהר דאי משום טומאת לידה הא קתני נקבה:"],[17,"גמ' והפילה","ואינה יודעת מה אם נפל אם רוח שהרי נפל למים:"],[18,"אמאי תשב לנדה","ניתיב לה מיהא ימי טוהר דזכר:"],[20,"שיצאה מלאה","כשהיתה מעוברת יצתה לאפר:"],[20,"ובאה","בו ביום ריקנית:"],[20,"בכור מספק","שמא זה היה ולד והבא אחריו אינו בכור או שמא רוח הפילה והבא אחריו בכור מעליא הוא הילכך ספק הוא ויאכל במומו לבעלים ולא לכהן דהמוציא מחבירו עליו הראיה:"],[21,"והאי פשוט הוא","ויאכל בלא מום:"],[22,"מטנפות","יום אחד קודם לידה כעין גלייר\"א:"],[24,"מתיב רבי יוסי","אדר' יהושע בן לוי:"],[24,"טועה","ממתניתא דמיירי באשה טועה שלא ידעה עת לידתה:"]],[[10,"","ה\"ג אמר רב פפא כתנאי יצא מחותך או מסורס כו' מאי קאמר. דאין סברא דברוב שלם ומסורס או ברוב כתקנו ומחותך לא הוי לרבי יוסי כילוד וקאמר רב פפא דגרסינן בברייתא מחותך ומסורס הא מחותך ויצא כתקנו הראש פוטר ולרבי יוסי אין הראש פוטר והיינו פלוגתייהו דרבי יוחנן ורבי אלעזר:"],[12,"","מכלל דבמסורס רובו נמי לא פוטר. וא\"ת ודלמא ר' יוסי אתא למימר דאפי' כתקנו בעינן רוב ואין הראש פוטר וה\"ה דבמסורס נמי סגי ברוב וי\"ל דא\"כ הוה ליה לרבי יוסי למימר אפילו כתקנו עד שיצא רובו והוה משמע שבא להחמיר לכך משני רב זביד מדקאמר משיצא רובו כתקנו ולא קאמר עד שיצא משמע דרבי יוסי בא להקל וה\"ק יצא מחותך מסורס עד שיצא רובו הא כתקנו הראש פוטר ור' יוסי מקיל וקאמר (או עד שיצא) כתקנו לחיים פירוש מה שחשוב חיים דהיינו רוב ראשו כדמפרש בברייתא בסמוך ר' יוסי אומר משיצא רוב ראשו ורבינו חננאל פירש לחיים בר קיימא דדוקא בר קיימא הראש פוטר אבל לא בנפלים וקשה א\"כ אמאי איתותב שמואל פרק יש בכור (בכורות דף מז:) כיון דרבי יוסי קאי כוותיה:"],[16,"","תשב לזכר ולנקבה ולנדה. אע\"ג דהוי ספק ספקא תשב לנקבה דאי מטהרת לה מטומאת נקבה משום ספק ספקא הכי נמי נטהרנה אם ראתה בל\"ד ומ\"א מספק ספקא ולא ניחוש לזכר והוי תרי קולי דסתרן אהדדי כדפרשינן לעיל (נדה ד' כד:) ומיהו בטועה בגמ' מחמרינן אע\"ג דאיכא כמה ספיקי:"],[22,"","וזו הואיל ולא טנפה. וכגון שלא שהתה הבהמה בחוץ דאם שהתה אימור טנפה וילדה:"]]],[["אשה שיצתה מלאה ובאה ריקנית והביאה לפנינו שלשה שבועין טהורין ועשרה שבועות אחד טמא ואחד טהור","משמשת לאור שלשים וחמש ומטבילין אותה תשעים וחמש טבילות דברי ב\"ש וב\"ה אומרים שלשים וחמש רבי יוסי בר' יהודה אומר דיה לטבילה שתהא באחרונה","בשלמא שבוע ראשון לא משמשת אימר יולדת זכר היא שבוע שני אימר יולדת נקבה היא","שבוע שלישי אימר יולדת נקבה בזוב היא","אלא שבוע רביעי אע\"ג דקא חזיא דם תשמש דהא דם טהור הוא לאו משום דלא אזלינן בתר רובא","אלא מאי לא ידענא מאי תיובתא אימר הרחיקה לידתה","הך שבוע חמישי דטהור הוא תשמש","הך שבוע רביעי כל יומא ויומא מספקין בסוף לידה ובתחלת נדה ועשרין ותמניא גופיה אימר תחלת נדה היא ובעיא למיתב שבעה לנדתה","בעשרים וחד תשמש","רבי שמעון היא דאמר אסור לעשות כן שמא תבא לידי ספק לאורתא תשמש כשראתה בערב","ומטבילין אותה תשעים וחמש טבילות שבוע קמא מטבילין אותה בלילותא אימר יולדת זכר היא","שבוע שני מטבילין אותה בלילותא אימר יולדת נקבה היא ביממא אימר יולדת זכר בזוב היא","שבוע שלישי מטבילין לה ביממא אימר יולדת נקבה בזוב היא","בלילותא ב\"ש לטעמייהו דאמרי טבולת יום ארוך בעי טבילה"],[[0,"האשה שיצאה מלאה וחזרה ריקנית","לסוף זמן מרובה ואינה יודעת אימת יצא הריונה:"],[0,"והביאה לפנינו","כלומר משבאה לפנינו ישבה לה שלשה שבועים טהורים מכל וכל עם יום בואה. ולא דק כולי האי דיום זה ספק טמא דשמא ראתה בו ביום קודם שבאתה לפנינו ואפ\"ה קרי ליה טהור דקאי אמכאן ולהבא דקס\"ד השתא שבאתה לפנינו ביום ומשבאתה לפנינו לא ראתה:"],[0,"ועשרה שבועים אחד טמא ואחד טהור","אחד טמא שהיתה רואה בכל יום ואחד טהור שכל הימים של אותו שבוע היו טהורין:"],[1,"משמשת לאור שלשים וחמש","שהוא ליל סוף שבוע חמישי והוא ליל כניסת שלשים וחמש ויציאת יום ל\"ד ושוב אינה משמשת. וטעמא דכולן מפרש לקמן ואמאי נקט הכי י\"ג שבועים:"],[1,"ומטבילין אותה צ\"ה טבילות","משום דטבילה בזמנה מצוה וכולהו מפרש לקמן. ומשום הני צ\"ה טבילות נקט י\"ג שבועים דספק זמן הטבילות משוך י\"א שבועים ופלגא די\"ב ואיידי דצריך לפלגא נקט כולה ואיידי דתנא שבוע טמא דהיינו י\"ב תנא נמי שבוע י\"ג טהור והכי מפרש לקמיה:"],[1,"וב\"ה סברי ל\"ה","וטעמייהו מפרש לקמן ותרוייהו סבירי להו טבילה בזמנה מצוה:"],[1,"באחרונה","כשתפסוק לגמרי ותטהר דלית ליה טבילה בזמנה מצוה:"],[2,"בשלמא שבוע ראשון כו'","השתא מפרש תיובתא:"],[2,"אימר יולדת זכר היא","וכל יומא ויומא דשבוע ראשון איכא לספוקי דלמא ביום שבאתה ילדה שעה אחת קודם שבאה לפנינו וכל שבעת הימים האלו הוו שבעת ימי לידה:"],[2,"שבוע ראשון","יומא דאתיא לקמן קחשיב בכלל שבוע ראשון:"],[2,"אימר יולדת נקבה היא","וביום שבאת לפנינו ילדה ומשכי ימי לידה הנך תרתי שבועי:"],[3,"בזוב","שמא מתוך י\"א יום דימי זיבה ילדה וראתה ג' רצופין ובלא צער דהוה שופי סמוך ללידה ובעיא שבעה נקיים לזיבתה. ואע\"ג דקא יתבא י\"ד נקיים הואיל ואיכא לספוקינהו בימי לידה לא סלקא לה דקסבר ימי לידה שאינה רואה בהן אין עולין לה לספירת זיבתה:"],[4,"אלא שבוע רביעי","אי אמרינן רוב נשים ולד מעליא ילדן האי ולד הוא שהרי הוחזקה עוברה:"],[4,"תשמש","ואע\"ג דהך שבוע קא חזיא שהרי ראשון הוא לשבועים שעוברים עליה אחד טמא ואחד טהור:"],[4,"האי דם טוהר הוא","דאכתי משכי מ' יום דזכר:"],[4,"לאו משום דלא אזלינן בתר רובא","ומספקינן לה בלא ולד ולית לה דם טוהר וקשה לריב\"ל:"],[5,"אימר הרחיקה לידתה","האי דלא יהבינן לה ימי טוהר לאו משום ספק דלאו ולד הוא אלא אימר הרי ימים רבים קודם שבאת לפנינו ילדה וכלו לה ימי טהרתה אבל לענין קרבן מביאה קרבן ונאכל בין קרבה ובין הרחיקה בת קרבן היא מאחר דקפדינן ארובא:"],[6,"שבוע חמישי דטהור הוא תשמש כו'","ואמאי לא משמשת עד ליל שביעי:"],[7,"ומשנינן שבוע רביעי","שראתה בכל יום כל יומא איכא לספוקי לסוף לידה סוף ימי טוהר כלומר אתמול כלו ימי טוהר והיום היא תחלת נדה הילכך יום כ\"ח שהוא סוף שבוע רביעי מספקינן לה בתחלת נדה ובעיא לממני משבוע חמישי ששה ימים להשלים שבעת ימי נדות ובליל שביעי טובלת ומשמשת שהוא אור לשלשים וחמש משבאת לפנינו וליל שמיני שהוא תחלת שבוע ששי נמי לא משמשת שהשבוע ששי טמא הוא דמוקמינן לה לקמן שהיא רואה מבערב בכל ימי ראייתה מכאן ואילך לא משמשת לעולם דדילמא שבוע רביעי תחלת נדה היא והששי בימי זיבה והרי היא זבה ושבוע שביעי שהוא טהור תספור לנקיים ואם לא שרואה מבערב היתה משמשת ליל תחלת שבוע שמינית ואע\"ג דיכולה לטבול ביום שביעי שמקצת היום ככולו לענין ספירה אפ\"ה לא משמשת ביום דמוקמינן לה כר\"ש דאסר וכן לעולם י\"ל בכל שבועים טמאים שלה זהו בימי זיבה וצריכה ז' נקיים וכל שבוע טהור תספור לנקיים אבל שבוע רביעית ממ\"נ אין אתה יכול לספקו בזיבה שאין זיבה אלא לאחר נדות והרי זו ישבה ג' שבועים טהורים והרביעי הוא דראתה הילכך בתחלת נדה הוא דאיכא לספוקי ולא בעיא למיתב בשבוע חמישי אלא ששה ימים משום ספק יום אחרון של רביעי דמספקינן לה בתחלת נדה:"],[8,"בעשרים וחד","שהוא סוף שבוע שלישית תשמש דהא אפי' קרבה לידתה לילד בו ביום שבאת לפנינו כבר כלו ימי טומאה והיום שביעי לנקיים של ספירה וקי\"ל דטבילת זב וזבה ביום בפ\"ק דיומא (דף ו.) דמקצת היום ככולו הילכך ביום כ\"א תשמש:"],[9,"ר\"ש היא דאמר","בת\"כ אסור לעשות כן לשמש זבה ביום טבילתה:"],[9,"שמא תבא לידי ספק","שמא תראה לאחר תשמיש ונמצא שסתרה כל מניינה דהא לא הוו נקיים כל שבעה ונמצא משמשת זבה:"],[9,"לאורתא תשמש","בליל תחלת שבוע רביעית דקס\"ד השתא שאינה רואה אלא ביום ואף ע\"ג דהאי שבוע רביעי טמא הוא מיהו בליל תחלת שבוע אכתי טהורה היא ותשמש הלילה:"],[9,"ומשני כשראתה מבערב","וכן היא נהוגה לראות בכל שבוע טמא מבערב:"],[10,"בלילותא","בכל לילה ולילה דבכל לילה מספקינן לה [שמא] השתא סוף שבעה ללידתה הוא וטבילה בזמנה מצוה:"],[10,"אימר יולדת זכר בזוב היא","ויום ראשון דשבוע שני אמרינן שמא שבעת ימים קודם שבאת לפנינו ילדה ושבוע ראשון הוה ספירה לנקיים ולמחר ביום תחלת שבוע שני תהא טבילת זיבתה וכן כל ימי שבוע שני כל יומא ויומא איכא לספוקי דלמא קצת משבוע ראשון הוי בכלל ימי לידה והשתא כלין ימי הספירה אבל שבוע ראשון לא טבלה ביום ואף ע\"ג דבכל יום איכא לספוקי שמא הרחיקה לידתה והשתא כלין ימי הספירה משום דבעינן שבעת ימי הנקיים לפנינו ודאין והני דקודם לכן ספק הוו נקיים ספק לא הוו והכי מפרש לקמן ויום אחרון דשבוע קמא הוה בעיא טבילה משום ספקא דהשתא כלין ימי הספירה ואיכא ז' ספורין לפנינו ולקמן מתרצין דטבילה חדא בשבוע לא קחשיב:"],[11,"בלילותא אימור יולדת נקבה הואי","וכל לילה איכא לספוקי האידנא סוף שבועים וליל אחרון מספקינן שמא ביום שבאתה ילדה והשתא כלין:"],[12,"שבוע שלישי מטבלינן לה ביממא אימר יולדת נקבה בזוב היא","וכל יומא איכא לספוקי השתא כלין ימי ספירה יום ראשון דלמא ששה ימים קודם שבאת לפנינו ילדה ושבועים הרי עשרים יום והיום הוי כ\"א שסוף ספירה הוא ולמחר אמרי' ה' ימים קודם ביאתה ילדה והיום כלים ויום אחרון אימר ביום שבאתה ילדה והיום כלים:"],[13,"בלילותא","דשבוע שלישי מטבילין לה ואף ע\"ג דליכא לספוקי בשבוע שלישי בסוף לידת נקבה:"],[13,"ב\"ש לטעמייהו","דאמרי בפ' אחרון (לקמן נדה דף עא:) טבולת יום ארוך דהיינו יולדת שהיא טבולת יום כל ששים וששה שהרי לסוף שבועים היא טובלת ואינה אוכלת בתרומה עד שיכלו ימי טוהר כדכתיב בכל קדש לא תגע וקאמרי ב\"ש שצריכה לטבול לאור שמונים ואחד שהוא סוף שמונים הילכך כל ליליא איכא לספוקי השתא כלים (עד) שמונים יום מיום שבאת לפנינו ושבוע קמא נמי איכא לספוקי בהכי אלא לא איכפת לן משום דסוף סוף הא קא טבלה בכל ליליא:"]],[[5,"","אימר הרחיקה לידתה. תימה דרבי יוסי ברבי חנינא לא אסיק אדעתיה האי שינוייא וברייתא לא מפרש כלל בענין אחר:"],[9,"","ר\"ש היא. תימה דכ\"ש דאתיא כרבנן דאסרי בפ' בתרא (לקמן נדה סז:) לשמש דאורייתא ועוד קשה דהכא משמע דר\"ש לא אסר טבילה אלא תשמיש דוקא ובפרק בתרא (שם סז:) משמע דאסורה לטבול וי\"ל דטבילה האמוראין אסרוה ולקמן (שם ד\"ה אבל) נפרש בע\"ה:"],[9,"","כשראתה מבערב. וא\"ת כיון דראתה מבערב אמאי מטבילינן לה לב\"ש בלילותא משום טבולת יום ארוך וי\"ל דלאו דוקא מבערב אלא כלומר בשעה או בחצי שעה בלילה וטובלת בתחלת הלילה ורואה מיד אחר הטבילה ואם היתה באה לשמש קודם טבילה הרשות בידה:"],[10,"","בשבוע קמא מטבילין לה בלילותא אימור יולדת זכר היא. זה האריכות אינו צריך אלא לב\"ה דלב\"ש מטבילין לה כל פ' לילות משום טבולת יום ארוך והאי שבוע קמא דלילותא אינו כמו שבועים דיממא אלא ו' לילות משבוע קמא וליל תחלת שבוע שניה ושבוע שניה נמי בלילותא היינו ו' לילות משבוע שניה וליל תחלת שבוע שלישי ושבוע שני ושלישי ביממא אינו כענין זה:"]]],[["מכדי ימי טהרה כמה הוו שתין ושיתא דל שבוע ג' דאטבלינן לה פשו להו שתין נכי חדא שתין נכי חדא ותלתין וה' תשעין וד' הויין תשעין וחמש מאי עבידתייהו","אמר רב ירמיה מדפתי כגון שבאת לפנינו בין השמשות דיהבינן לה טבילה יתירתא","ולב\"ה דאמרי טבולת יום ארוך לא בעי טבילה ל\"ה מאי עבידתייהו","עשרים ותמניא כדאמרן הך שבוע ה' מטבלינן כל ליליא וליליא אימר סוף נדה היא","י' שבועין למה לי בתמניא ופלגא סגי","איידי דתנא פלגא דשבוע מסיק ליה ואיידי דתנא שבוע טמא תנא נמי שבוע טהור","והאיכא טבילת זבה","דלפני תשמיש קחשיב דלאחר תשמיש לא קחשיב","ולב\"ש דחשיב דלאחר תשמיש ניחשוב נמי טבילת זבה בלידה קמיירי בזיבה לא קמיירי","והאיכא יולדת בזוב יולדת בזוב קחשיב זיבה גרידתא לא קחשיב","שבועתא קמא דאתיא לקמן ליטבלה ביומא דילמא כל יומא ויומא שלימו לה ספורים דידה","הא מני ר\"ע היא דאמר בעינן ספורים בפנינו","סוף שבוע קמא ליטבלה חד בשבוע לא קמיירי","יומא קמא דאתיא לקמן ליטבלה דילמא שומרת יום כנגד יום היא בזבה גדולה קמיירי בזבה קטנה לא קמיירי","ש\"מ תלת ש\"מ ר\"ע היא דאמר בעינן ספורים בפנינו","וש\"מ ר\"ש היא דאמר אבל אמרו חכמים אסור לעשות כן שמא תבא לידי ספק","וש\"מ טבילה בזמנה מצוה ורבי יוסי בר' יהודה אומר דיה לטבילה באחרונה ולא אמרינן טבילה בזמנה מצוה","\u0001מתני׳\u0002 המפלת ליום מ' אינה חוששת לולד ליום מ\"א תשב לזכר ולנקבה ולנדה","רבי ישמעאל אומר יום מ\"א תשב לזכר ולנדה יום פ\"א תשב לזכר ולנקבה ולנדה שהזכר נגמר למ\"א והנקבה לפ\"א וחכ\"א אחד בריית הזכר ואחד בריית הנקבה זה וזה מ\"א","\u0001גמ׳\u0002 למה הוזכר זכר","אי לימי טומאה הא קתני נקבה ואי לימי טהרה"],[[0,"מכדי ימי טוהר כמה","משכה ספקא דידהו לבתר שבועים קמאי:"],[0,"שתין ושיתא","ושבועים הרי פ' ומהני ס\"ו טבילות כבר טבלה מהן ז' בלילי שבוע שלישי משום הך ספקא דטבולת יום ארוך:"],[0,"דל הני ז' פשו להו שתין נכי חדא","שעדיין צריכה לטבול משום הך ספק בתוך י' שבועים הבאים ול\"ה שטבלה בתוך ג' השבועים הראשונים שבעה בראשונה וכ\"ח בשתים אחרונות הרי ל\"ה ושתין נכי חדא הרי צ\"ד:"],[1,"טבילה יתירתא","עד השתא הוה ס\"ד דבאת לפנינו ביום כגון ביום ר\"ח ניסן ואטבלוה לאורתא ומשכו פ' דילה ל' מניסן וכ\"ט דאייר וכ\"א דסיון כלים פ' יום הרי פ' טבילות בלילות וי\"ד בימים של ב' שבועות הראשונות הרי צ\"ד והשתא מוקמינן שבאת לפנינו בין השמשות לילה שהוא ר\"ח ואטבלה בההיא ליליא משום ספק סוף טומאה ומשכי נמי פ' שלה עד כ\"א בסיון כאילו באתה ביום ראש חדש דאיכא לספוקי דילמא באותו בין השמשות ילדה והוא מר\"ח וההיא טבילה דליל ראש חדש איתוספא לה נמצאו לה ח' טבילות בשבוע ראשונה וכ\"ח דב' וג' הרי ל\"ו. וקשיא לי אמאי נקט בין השמשות ה\"ל לאוקמא שבאת לפנינו בלילה ומסתברא דלהכי נקט בין השמשות דדק בלישנא דמתני' דנקט ג' שבועים טהורים הילכך כי איכא בין השמשות איכא למיקרי יום זה טהור דשמא בין השמשות יממא הוא ומיום שעבר הוא והיום הזה כולו טהור ומיהו טבילותיה משכי עד שמונים לבד מהך משום דבין השמשות ספק ליליא:"],[2,"ל\"ה","דקאמרי ב\"ה מאי עבידתייהו. ומשני עשרין ותמניא הויין:"],[3,"כדאמר","י\"ד בימים וי\"ד בלילות וכולן משום ספק סוף ימי טומאה. והוא הדין דלב\"ה הוו להו עשרין ותשע דכיון דאוקמינן שבאה בין השמשות איכא ט\"ו טבילות בלילה משום ספק בין השמשות והאי דלא מותבינן ליה לקמיה משום דאותבינן אחריתי ומשנינן חד בשבוע לא קמיירי והך נמי חדא בשבוע היא:"],[3,"האי שבוע ה'","שאינה רואה בו כל יומא איכא לספוקי בסוף נדה ומטבלינן לה בכל לילות דשבוע ד' ראתה בכל יום ויום ראשון דילמא תחלת נדה היא וטובלת לסוף שבעה שהוא ליל ראשון של שבוע ה' וליל שני נמי טבלה דילמא יום ראשון של שבוע רביעי מימי טוהר הוא ויום ב' הואי תחלת נדה והאידנא הוי ליל טבילתה וכן כולהו והוו להו שבעה טבילות. והוא הדין נמי דכל לילות של שבועים טהורים איכא לספוקי סוף נדה משום שבוע טמא שלפניה אלא ב\"ה טבילות דלאחר ל\"ה דהוא ליל תשמיש לא קחשיב דכל טבילות דב\"ה קודם תשמיש נינהו והכי אמר לקמן:"],[4,"בתמניא ופלגא סגיא","לבד הג' שבועות דטהורה דהא כלין ימי טבילה בסוף שמונים והוא באמצע שבוע תשיעי של י' שבועים:"],[5,"שבוע","תשיעי טמא הוא:"],[6,"טבילת זבה","דכל שבוע טמא איכא לספוקי בזיבה לבד משבוע רביעי שאי אתה יכול לספקו בכך כדפרישית לעיל שאין זבה אלא לאחר נדות וזו לא ראתה כלום עד הרביעי וכל שבוע טהור איכא לספוקי בימי ספירת זיבתה ובעיא למטבל ביום ז' של כל שבוע טהור:"],[11,"ר\"ע","דפרק אחרון (לקמן נדה דף סט.):"],[12,"סוף שבוע ראשון","ביום השביעי ליטבלה ביום דילמא בין השמשות יום הוא ויום ראשון שבאתה לפנינו טהור ואיכא ז' ספורים לפנינו:"],[12,"חדא","טבילה בשבוע לא קמיירי. וה\"ה דהוה לן לאותובי לב\"ה דליחשוב עוד טבילה יתירתא לטבילות הלילות של ספק לידה הואיל ובין השמשות באתה אלא האי שינויא גופיה אית בה דחדא בשבוע לא קמיירי הילכך לא פריך:"],[17,"מתני' המפלת","שליא:"],[17,"ליום מ'","לטבילתה:"],[17,"אינה חוששת לולד","שלא נגמר יצירתו עד שיכלו כל מ' יום:"],[17,"ולנדה","דילמא ליכא ולד. ובגמ' מפרש למה הוזכר זכר:"],[18,"תשב לזכר","ז' ימי טומאה ואפילו בלידה יבשתא אבל שבועים דנקבה ליכא לספוקי כדקתני טעמא שיצירת נקבה לפ\"א:"],[20,"גמ' הא קתני נקבה","דה\"ל שבועים ויש בכלל מאתים מנה:"],[20,"אי לימי טוהר","להחמיר שלא יהא לה אלא ימי טוהר דזכר:"]],[[3,"","עשרים ותמניא כדאמרן. אף על גב דכ\"ט הויין עם טבילה יתירתא דבין השמשות שבאתה לפנינו פ\"ה דההיא טבילה יתירתא דהויא חדא בשבוע לא קחשיב ואין נראה דהא ב\"ש חשבי לה אלא ודאי לא חשיב טבילה יתירתא חדא בשבוע כיון שלא היתה בפנינו אלא עכשיו ונראה כמו שפי' רש\"י בתשובתו דב\"ה לא חשיב טבילה דליל תחלת שבוע ג' דכיון דתו לא מטבלינן להנדה לא מיקריא חדא בשבוע אבל לב\"ש דמטבילין לה בלילות לא הוי חדא בשבוע:"],[6,"","והאיכא טבילת זבה. עדיפא הוה מצי למיפרך דכל שבועים טהורים ניטבל לה בלילותא משום נדה דהשתא לא פריך אלא חדא בשבוע ונראה כגירסת ר\"ח דגריס אי הכי כל שבועים טהורים נמי והיינו הך פירכא דפריך ומשני דלפני תשמיש קחשיב:"],[13,"","יומא קמא דאתיא לקמן נטבלה דילמא שומרת יום היא. וא\"ת והא אמר דחד בשבוע לא קמיירי וי\"ל דהשתא לא הויא חד בשבוע דהא איכא נמי טבילה בסוף שבוע ועוד דמשום חששא דשומרת יום טובלת גם ביום שני דשמא עכשיו ראתה כשבאת לפנינו ועוד מטעמא דשומרת יום נטבלה כל שבוע קמא דכל יומא מספקא בסוף לידה ולא סלקא לשימור דאין ימי לידה עולים לימי ספירת זיבתה ומיהו קשה דהוה מצי למיפרך מכל שבוע כדפרישית ולא פריך אלא מיומא קמא:"],[14,"","שמע מינה תלת. הוה מצי למינקט שמע מינה דימי לידה שאינה רואה בהן אין עולין לספירת זיבתה אלא אר\"ת דפשיטא ליה להש\"ס שאין עולין דקי\"ל כאביי בסוף פרק בנות כותים (לקמן נדה לז.) והוא למ\"ד מיע\"ל קג\"ם ולקמן נפרש בע\"ה ותימה דהך ברייתא סברה דלב\"ש וב\"ה אין עולין ובפרק בנות כותים (נדה לה:) גבי פלוגתא דרב ולוי אי שתי מעיינות הן או מעיין אחד איכא ברייתא דלב\"ש ולב\"ה עולין וי\"ל דתרי תנאי הוא אליבייהו:"],[16,"","ושמע מינה טבילה בזמנה מצוה. כך פסק ר\"ח דהלכה כב\"ש וב\"ה ותימה דפשיטא דר' יוסי בר' יהודה יאמר דלא פליגי עליה ב\"ש וב\"ה ומעשים בכל יום שאין לך אשה טובלת בזמן טבילת נדה ולא בזמן טבילת שומרת יום כנגד יום וזבה ובפ' בתרא (לקמן נדה דף סז:) נמי אמר מכדי האידנא כולהו ספק זבות שוינהו ניטבלינהו ביממא דז' משמע שלא היו טובלין ביום בשום פעם ורבינו אליהו הזקן שיסד באזהרות טבילה בזמנה על ד' גדילים כולו יסד דלא כהילכתא דה\"נ יסד כר\"א (סנהדרין דף מה.) דאמר כל נסקלין נתלין דדריש ריבוי ומיעוט וקי\"ל דדרשינן כללי ופרטי דהא קיימא לן דקרקע אינה נגזלת:"]]],[["הא קתני נדה","שאם תראה יום ל\"ד ותחזור ותראה יום מ' ואחד תהא מקולקלת עד מ\"ח","וכן לענין נקבה שאם תראה יום ע\"ד ותחזור ותראה יום פ\"א תהא מקולקלת עד פ\"ח","רבי ישמעאל אומר יום מ\"א תשב לזכר ולנדה כו' תניא רבי ישמעאל אומר טימא וטיהר בזכר וטימא וטיהר בנקבה","מה כשטימא וטיהר בזכר יצירתו כיוצא בו אף כשטימא וטיהר בנקבה יצירתה כיוצא בה אמרו לו אין למדין יצירה מטומאה","אמרו לו לר' ישמעאל מעשה בקליאופטרא מלכת אלכסנדרוס שנתחייבו שפחותיה הריגה למלכות ובדקן ומצאן זה וזה למ\"א אמר להן אני מביא לכם ראייה מן התורה ואתם מביאין לי ראייה מן השוטים","מאי ראיה מן התורה אילימא טימא וטיהר בזכר וטימא וטיהר בנקבה כו' הא קאמרי ליה אין דנין יצירה מטומאה","אמר קרא תלד הוסיף לה הכתוב לידה אחרת בנקבה","ומאי ראיה מן השוטים אימר נקבה קדים ואיעבור ארבעין יומין קמי זכר","ורבנן סמא דנפצא אשקינהו ור' ישמעאל איכא גופא דלא מקבל סמא","אמר להם ר' ישמעאל מעשה בקלפטרא מלכת יוונית שנתחייבו שפחותיה הריגה למלכות ובדקן ומצאן זכר לארבעים ואחד ונקבה לפ\"א אמרו לו אין מביאין ראיה מן השוטים","מאי טעמא הך דנקבה אייתרה ארבעין יומין והדר איעבר","ורבי ישמעאל לשומר מסרינהו ורבנן אין אפוטרופוס לעריות אימא שומר גופיה בא עליה","ודילמא אי קרעוהו להך דנקבה בארבעין וחד הוה משתכחא כזכר אמר אביי בסימניהון שוין","וחכ\"א אחד בריית זכר ואחד בריית נקבה וכו' חכמים היינו ת\"ק","וכי תימא למסתמא רישא כרבנן ויחיד ורבים הלכה כרבים פשיטא","מהו דתימא מסתברא טעמא דרבי ישמעאל דקמסייע ליה קראי קמ\"ל","דרש רבי שמלאי למה הולד דומה במעי אמו לפנקס שמקופל ומונח ידיו על שתי צדעיו שתי אציליו על ב' ארכובותיו וב' עקביו על ב' עגבותיו וראשו מונח לו בין ברכיו ופיו סתום וטבורו פתוח ואוכל ממה שאמו אוכלת ושותה ממה שאמו שותה ואינו מוציא רעי שמא יהרוג את אמו וכיון שיצא לאויר העולם נפתח הסתום ונסתם הפתוח שאלמלא כן אינו יכול לחיות אפילו שעה אחת","ונר דלוק לו על ראשו וצופה ומביט מסוף העולם ועד סופו שנאמר (איוב כט, ג) בהלו נרו עלי ראשי לאורו אלך חשך ואל תתמה שהרי אדם ישן כאן ורואה חלום באספמיא","ואין לך ימים שאדם שרוי בטובה יותר מאותן הימים שנאמר (איוב כט, ב) מי יתנני כירחי קדם כימי אלוה ישמרני ואיזהו ימים שיש בהם ירחים ואין בהם שנים הוי אומר אלו ירחי לידה","ומלמדין אותו כל התורה כולה שנאמר (משלי ד ד) ויורני ויאמר לי יתמך דברי לבך שמור מצותי וחיה ואומר (איוב כט, ד) בסוד אלוה עלי אהלי","מאי ואומר וכי תימא נביא הוא דקאמר ת\"ש בסוד אלוה עלי אהלי","וכיון שבא לאויר העולם בא מלאך וסטרו על פיו ומשכחו כל התורה כולה שנאמר (בראשית ד, ז) לפתח חטאת רובץ","ואינו יוצא משם עד שמשביעין אותו שנאמר (ישעיהו מה, כג) כי לי תכרע כל ברך תשבע כל לשון כי לי תכרע כל ברך זה יום המיתה שנאמר (תהלים כב, ל) לפניו יכרעו כל יורדי עפר תשבע כל לשון זה יום הלידה שנאמר (תהלים כד, ד) נקי כפים ובר לבב אשר לא נשא לשוא נפשו ולא נשבע למרמה","ומה היא השבועה שמשביעין אותו תהי צדיק ואל תהי רשע ואפילו כל העולם כולו אומרים לך צדיק אתה היה בעיניך כרשע והוי יודע שהקב\"ה טהור ומשרתיו טהורים ונשמה שנתן בך טהורה היא אם אתה משמרה בטהרה מוטב ואם לאו הריני נוטלה ממך","תנא דבי ר' ישמעאל משל לכהן שמסר תרומה לעם הארץ ואמר לו אם אתה משמרה בטהרה מוטב ואם לאו הריני שורפה לפניך","א\"ר אלעזר"],[[0,"הא קתני נדה","דכל דמים שתראה טמאים. ומשני לכך הוזכר זכר שאם תראה ליום ל\"ד ותחזור ותראה ליום מ\"א תהא מקולקלת עד מ\"ח שכשראתה ליום ל\"ד ללידתה אמרינן טמאה אע\"ג דאכתי משכי ימי טוהר דזכר מספקינן לה בלא ולד ותשב לנדה וכי הדר חזיא ליום מ\"א שהוא ח' לראייתה ותרצה להיות שומרת יום כנגד יום אמרינן ולד היה וזכר היה וראייה דיום ל\"ד דם טוהר היא והשתא הוא דהויא תחלת נדה והשתא מקלקלינן לה דלא טבלה עד מ\"ח שהוא ח' לראייה אחרונה ואי לאו משום ספקא דזכר הוה טבלה למחר ליום מ\"ב ממ\"נ אי לאו ולד הוא הרי שומרת יום כנגד יום היא ואי ולד הוא ונקבה היא אכתי הוה דם טוהר עד שמונים וספקא דזכר מקלקלא לה:"],[2,"וכן לענין נקבה","כלומר וספקא דנקבה נמי מקלקלא לה האי קלקולא:"],[2,"עד פ\"ח","דלא טבלה עד פ\"ח דאי הוה פשיטא לן דלאו ולד הוא הואי טבלה למחר ביום פ\"ב דראיית פ\"א באחד עשר יום שבין נדה לנדה היא ומשום דמספקא לן דילמא ולד הוה וראייה דיום ע\"ד דם טהור הוה והשתא הויא תחלת נדה לא טבלה עד פ\"ח:"],[3,"טימא וטיהר בזכר","מ' יום בין שתיהן ז' לטומאה ול\"ג יום לימי טוהר:"],[5,"נתחייבו הריגה","ומתוך שעומדות ליהרג ניסו בהם ויחדום לביאה וקרעו שתיהם לסוף מ' ונמצא אחד זכר ואחד נקבה:"],[7,"תלד","דאם נקבה תלד (ויקרא י״ב:ה׳) קרא יתירא הוא דמצי למכתב ואם נקבה וטמאה שבועים דהא כתיב לעיל וילדה זכר:"],[8,"מקמי זכר","ואף ע\"ג שיחדום לבעול ביום אחד שמא מעוברת היתה קודם לכן:"],[9,"סמא דנפצא","סם שמפלת בו ומנפצא כל זרע שבמעים קודם לכן:"],[12,"לשומר מסרינהו","שלא בא אדם עליהן אלא אותו היום:"],[13,"ודילמא אי קרעוה כו'","לרבי ישמעאל פריך נהי נמי דלשומר מסרינהו אפ\"ה מנלן שלא נוצרה נקבה עד פ\"א דילמא אי קרעוה להך ליום מ\"א הוה משתכחא:"],[13,"בסימניהון שוין","נקבה שנמצא ליום פ\"א לא היו אבריה ושערה וצפורניה אלא כשיעור של זכר ליום מ\"א:"],[14,"היינו ת\"ק","דתנא לעיל ליום מ\"א תשב לזכר ולנקבה ולנדה אלמא בריית נקבה ליום מ\"א:"],[15,"וכי תימא","רישא להכי תנא ליה לאשמועינן סתמא דמתניתין כרבנן ונשמע מינה דהלכתא כוותייהו ולא נהירא לי גירסא ופירושה דה\"ל סתם ואח\"כ מחלוקת ואין הלכה כסתם. ונ\"ל דהכי גרס וכי תימא למסתמא כרבנן ויחיד ורבים הלכה כרבים פשיטא מהו דתימא כו'. והכי פירושה וכי תימא תנא הך סיפא לאשמעינן דסתמא דלעיל סתמא דרבנן היא ויחיד ורבים הלכה כרבים פשיטא דסתמא דרבים היא הואיל וסתמא תנייה רבי ולא אשכחן יחידאה דאמר הכי דנימא פלוני היא:"],[16,"מהו דתימא כו'","קמשמע לן מדמהדר רבי ושנאה בלשון חכמים שמע מינה דהלכה כסתם ראשון ואף על פי שמחלוקת ר' ישמעאל בצדו:"],[17,"פנקס","לוחין שכותבין בהן הגלחים:"],[17,"אציליו","איישיל\"ש:"],[17,"שמא יהרוג את אמו","שבית הרחם אינו רחב להוציא רעי הנאסף בו:"],[17,"נפתח הסתום","פיו:"],[17,"ונסתם הפתוח","טבור:"],[20,"ת\"ש בסוד אלוה עלי אהלי","והא אוקמיה בירחי לידה מדכתיב כירחי קדם:"],[23,"ולא נשבע למרמה","שקיים שבועתו לשמור את התורה דאי בשבועה בעלמא אטו משום דלא נשבע למרמה חשיב להו בעולין בהר ה':"]],[[12,"","שומר גופיה בא עליה. ואפילו היה סריס או אשה אפשר שהניח אחרים לבא:"],[15,"","וכי תימא למיסתמא כרבנן. ואע\"ג דרישא נמי סתמא קתני לא חשיב סתמא כיון דפליג עליה רבי ישמעאל והוי אדרבה סתם ואח\"כ מחלוקת כדאמרינן בהחולץ (יבמות מב:):"],[17,"","שני אציליו על שני ארכובותיו. פ\"ה איישילי\"ש ור\"ת פירש דאציל היינו קוד\"א דאמר בפ' האומר משקלי (ערכין יט:) משקל ידי עלי משקל רגלי עלי כו' ומכניס ידו עד האציל ורגלו עד הארכובה וקוד\"א ביד הוא כנגד הארכובה ברגל ועוד דהתם משמע דאציל הוא מרפק ובאהלות (פ\"א מ\"ח) משמע שמנה לפי סדרי אברי האדם דמרפק היינו קוד\"א ועוד אמר בפ\"ב דזבחים (דף יח:) לא יחגרו ביזע שאין חוגרין אלא כנגד אצילי ידיהם והיינו כנגד הקוד\"א שדרך העולם לחגור ובבית השחי אדרבה שם הוא מקום זיעה:"]]],[["מאי קרא (תהלים עא, ו) ממעי אמי אתה גוזי מאי משמע דהאי גוזי לישנא דאשתבועי הוא דכתיב (ירמיהו ז, כט) גזי נזרך והשליכי","ואמר רבי אלעזר למה ולד דומה במעי אמו לאגוז מונח בספל של מים אדם נותן אצבעו עליו שוקע לכאן ולכאן","תנו רבנן שלשה חדשים הראשונים ולד דר במדור התחתון אמצעיים ולד דר במדור האמצעי אחרונים ולד דר במדור העליון וכיון שהגיע זמנו לצאת מתהפך ויוצא וזהו חבלי אשה","והיינו דתנן חבלי של נקבה מרובין משל זכר","ואמר רבי אלעזר מאי קרא (תהלים קלט, טו) אשר עשיתי בסתר רקמתי בתחתיות ארץ דרתי לא נאמר אלא רקמתי","מאי שנא חבלי נקבה מרובין משל זכר זה בא כדרך תשמישו וזה בא כדרך תשמישו זו הופכת פניה וזה אין הופך פניו","תנו רבנן שלשה חדשים הראשונים תשמיש קשה לאשה וגם קשה לולד אמצעיים קשה לאשה ויפה לולד אחרונים יפה לאשה ויפה לולד שמתוך כך נמצא הולד מלובן ומזורז","תנא המשמש מטתו ליום תשעים כאילו שופך דמים מנא ידע אלא אמר אביי משמש והולך (תהלים קטז, ו) ושומר פתאים ה'","תנו רבנן שלשה שותפין יש באדם הקב\"ה ואביו ואמו אביו מזריע הלובן שממנו עצמות וגידים וצפרנים ומוח שבראשו ולובן שבעין אמו מזרעת אודם שממנו עור ובשר ושערות ושחור שבעין והקב\"ה נותן בו רוח ונשמה וקלסתר פנים וראיית העין ושמיעת האוזן ודבור פה והלוך רגלים ובינה והשכל","וכיון שהגיע זמנו להפטר מן העולם הקב\"ה נוטל חלקו וחלק אביו ואמו מניח לפניהם אמר רב פפא היינו דאמרי אינשי פוץ מלחא ושדי בשרא לכלבא","דרש רב חיננא בר פפא מאי דכתיב (איוב ט, י) עושה גדולות עד אין חקר ונפלאות עד אין מספר בא וראה שלא כמדת הקב\"ה מדת בשר ודם מדת בשר ודם נותן חפץ בחמת צרורה ופיה למעלה ספק משתמר ספק אין משתמר ואילו הקב\"ה צר העובר במעי אשה פתוחה ופיה למטה ומשתמר","דבר אחר אדם נותן חפציו לכף מאזנים כל זמן שמכביד יורד למטה ואילו הקב\"ה כל זמן שמכביד הולד עולה למעלה","דרש רבי יוסי הגלילי מאי דכתיב (תהילים קל״ט:י״ד ) אודך (ה') על כי נוראות נפליתי נפלאים מעשיך ונפשי יודעת מאד בא וראה שלא כמדת הקב\"ה מדת בשר ודם מדת בשר ודם אדם נותן זרעונים בערוגה כל אחת ואחת עולה במינו ואילו הקב\"ה צר העובר במעי אשה וכולם עולין למין אחד","דבר אחר צבע נותן סמנין ליורה כולן עולין לצבע אחד ואילו הקב\"ה צר העובר במעי אשה כל אחת ואחת עולה למינו","דרש רב יוסף מאי דכתיב (ישעיהו יב, א) אודך ה' כי אנפת בי ישוב אפך ותנחמני במה הכתוב מדבר","בשני בני אדם שיצאו לסחורה ישב לו קוץ לאחד מהן התחיל מחרף ומגדף לימים שמע שטבעה ספינתו של חבירו בים התחיל מודה ומשבח לכך נאמר ישוב אפך ותנחמני","והיינו דאמר רבי אלעזר מאי דכתיב (תהלים עב, יח) עושה נפלאות (גדולות) לבדו וברוך שם כבודו לעולם אפילו בעל הנס אינו מכיר בנסו","דריש רבי חנינא בר פפא מאי דכתיב (תהלים קלט, ג) ארחי ורבעי זרית וכל דרכי הסכנת מלמד שלא נוצר אדם מן כל הטפה אלא מן הברור שבה תנא דבי רבי ישמעאל משל לאדם שזורה בבית הגרנות נוטל את האוכל ומניח את הפסולת","כדרבי אבהו דרבי אבהו רמי כתיב (שמואל ב כב, מ) ותזרני חיל וכתיב (תהלים יח, לג) האל המאזרני חיל אמר דוד לפני הקב\"ה רבש\"ע זיריתני וזרזתני","דרש רבי אבהו מאי דכתיב (במדבר כג, י) מי מנה עפר יעקב ומספר את רובע ישראל מלמד שהקב\"ה יושב וסופר את רביעיותיהם של ישראל מתי תבא טיפה שהצדיק נוצר הימנה","ועל דבר זה נסמית עינו של בלעם הרשע אמר מי שהוא טהור וקדוש ומשרתיו טהורים וקדושים יציץ בדבר זה מיד נסמית עינו דכתיב (במדבר כד, ג) נאם הגבר שתום העין","והיינו דאמר רבי יוחנן מאי דכתיב (בראשית ל, טז) וישכב עמה בלילה הוא מלמד שהקב\"ה סייע באותו מעשה שנאמר (בראשית מט, יד) יששכר חמור גרם חמור גרם לו ליששכר","אמר רבי יצחק אמר רבי אמי אשה מזרעת תחילה יולדת זכר איש מזריע תחילה יולדת נקבה שנאמר (ויקרא יג, כט) אשה כי תזריע וילדה זכר","תנו רבנן בראשונה היו אומרים אשה מזרעת תחילה יולדת זכר איש מזריע תחלה יולדת נקבה ולא פירשו חכמים את הדבר עד שבא רבי צדוק ופירשו (בראשית מו, טו) אלה בני לאה אשר ילדה ליעקב בפדן ארם ואת דינה בתו תלה הזכרים בנקבות ונקבות בזכרים","(דברי הימים א ח, מ) ויהיו בני אולם אנשים גבורי חיל דורכי קשת ומרבים בנים ובני בנים וכי בידו של אדם להרבות בנים ובני בנים אלא מתוך"],[[0,"מאי קרא","דמשביעין אותו ביום הלידה:"],[0,"נזרך","לשון נזירות דהיינו נדר דדמי לשבועה:"],[1,"","למה ולד דומה:"],[4,"רקמתי","היינו יצירה ראשונה וכתיב בתחתיות דהיינו מדור תחתון:"],[5,"חבלי","צערה:"],[5,"דרך תשמישן","האיש פניו למטה כן זכר נולד פניו למטה ונקבה פניה למעלה הילכך נקבה צריכה להתהפך דהא כשהיא במעי אמה פניה למטה כדאמרינן לעיל [ראשו לו בין ברכיו] אבל זכר אין צריך להתהפך:"],[6,"קשה לאשה וקשה לולד","מפני שדר במדור התחתון. קשה לאשה לא ידענא למאי: זרע מלבן את הולד מגיעוליו:"],[6,"מזורז","חזק ובריא:"],[7,"ליום תשעים","לשליש ימים הוי חיותו:"],[7,"מנא ידע","הא לא ידע אימת מעברה:"],[8,"קלסתר","זיו:"],[8,"מראה העין","שאע\"פ שנבראת העין מן האב והאם אינו רואה תדע שהרי המת יש לו עינים ויש לו שפתים ויש לו אזנים ואינו רואה ולא שומע ולא מדבר:"],[9,"פוץ מילחא","השלך המלח מן הבשר ושוב אינו ראוי אלא לכלבים כך הנשמה היא מלח לגוף לקיימו כיון שהלכה אז מסריח הגוף:"],[11,"עולה למעלה","כדתני לעיל אחרונים דר במדור העליון:"],[12,"כולין עולין למין אחד","זרע האב והאם נעשין בריה אחת:"],[13,"צבע","כמה סממנין צריך לצבע שחור קליפת עץ וטחינת ריחיים של נפחים וכמה דברים וכולן נעשין שחור ואינו יכול לצובעו ביורה אחת משנים ושלשה גוונים בשנים ושלשה מקומות:"],[13,"כל אחד ואחד עולה למינו","לובן מן האיש ושחור מן האשה:"],[14,"כי אנפת בי","מפני שכעסת עלי אני מודה לך שלטובתי היה:"],[15,"ישב לו קוץ","ברגלו לאחד מהם ולא יכול לצאת:"],[16,"לבדו","הוא לבדו יודע שהוא נס אבל בעל הנס אינו מכירו:"],[17,"ארחי","תשמיש כמו דרך גבר בעלמה (משלי ל׳:י״ט):"],[17,"ורבעי","תשמיש לשון לרבעה:"],[17,"זרית","ביררת בנפה שקורין וו\"ן כמו (ישעיהו ל) ברחת ובמזרה:"],[17,"הברור","קלי\"ר בלע\"ז:"],[18,"ותזרני","חסר א' לשון מזרה:"],[18,"ותאזרני","לשון חגירת כח במתנים:"],[18,"זיריתני","מן הברור ואח\"כ זירזתני:"],[19,"רביעיותיהם","עונת תשמישן:"],[21,"הוא","קודשא בריך הוא סייעה שנטה חמורו של יעקב לאהל לאה ואותו הלילה של האחרות היה:"],[23,"ולא פירשו","את הדבר מנלן:"],[23,"זכרים בנקבות","בני לאה:"],[23,"נקבות בזכרים","ואת דינה בתו משום הך דרשה איש מזריע תחלה יולדת נקבה:"]],[[20,"","שתום העין. שתום הוא לשון גילוי ופתיחה כדמתרגם דשפיר חזי וכן בלשון משנה במסכת ע\"ז (דף סט.) הוי לשון פתיחה כדי שישתום ויסתום ויגוב והכא דייק שנסתמה עינו מדכתיב שתום העין לשון יחיד והא דכתיב (במדבר כ״ד:ד׳) וגלוי עינים היינו לפי מה שהיה בתחלה:"]]],[["שמשהין עצמן בבטן כדי שיזריעו נשותיהן תחלה שיהו בניהם זכרים מעלה עליהן הכתוב כאילו הם מרבים בנים ובני בנים והיינו דאמר רב קטינא יכולני לעשות כל בני זכרים אמר רבא הרוצה לעשות כל בניו זכרים יבעול וישנה","ואמר רבי יצחק אמר רבי אמי אין אשה מתעברת אלא סמוך לוסתה שנאמר (תהלים נא, ז) הן בעון חוללתי","ורבי יוחנן אמר סמוך לטבילה שנאמר (תהלים נא, ז) ובחטא יחמתני אמי","מאי משמע דהאי חטא לישנא דדכויי הוא דכתיב (ויקרא יד, מט) וחטא את הבית ומתרגמינן וידכי ית ביתא ואי בעית אימא מהכא (תהלים נא, ט) תחטאני באזוב ואטהר","ואמר רבי יצחק אמר רבי אמי כיון שבא זכר בעולם בא שלום בעולם שנאמר (ישעיהו טז, א) שלחו כר מושל ארץ זכר זה כר","ואמר ר' יצחק דבי רבי אמי בא זכר בעולם בא ככרו בידו זכר זה כר דכתיב (מלכים ב ו, כג) ויכרה להם כירה גדולה","נקבה אין עמה כלום נקבה נקייה באה עד דאמרה מזוני לא יהבי לה דכתיב (בראשית ל, כח) נקבה שכרך עלי ואתנה","שאלו תלמידיו את רבי שמעון בן יוחי מפני מה אמרה תורה יולדת מביאה קרבן אמר להן בשעה שכורעת לילד קופצת ונשבעת שלא תזקק לבעלה לפיכך אמרה תורה תביא קרבן","מתקיף לה רב יוסף והא מזידה היא ובחרטה תליא מילתא ועוד קרבן שבועה בעי איתויי","ומפני מה אמרה תורה זכר לשבעה ונקבה לארבעה עשר זכר שהכל שמחים בו מתחרטת לשבעה נקבה שהכל עצבים בה מתחרטת לארבעה עשר","ומפני מה אמרה תורה מילה לשמונה שלא יהו כולם שמחים ואביו ואמו עצבים","תניא היה ר\"מ אומר מפני מה אמרה תורה נדה לשבעה מפני שרגיל בה וקץ בה אמרה תורה תהא טמאה שבעה ימים כדי שתהא חביבה על בעלה כשעת כניסתה לחופה","שאלו תלמידיו את רבי דוסתאי ברבי ינאי מפני מה איש מחזר על אשה ואין אשה מחזרת על איש משל לאדם שאבד לו אבידה מי מחזר על מי בעל אבידה מחזיר על אבידתו","ומפני מה איש פניו למטה ואשה פניה למעלה כלפי האיש זה ממקום שנברא וזו ממקום שנבראת","ומפני מה האיש מקבל פיוס ואין אשה מקבלת פיוס זה ממקום שנברא וזו ממקום שנבראת","מפני מה אשה קולה ערב ואין איש קולו ערב זה ממקום שנברא וזו ממקום שנבראת שנאמר (שיר השירים ב ) כי קולך ערב ומראך נאוה","\u0001הדרן עלך המפלת חתיכה\u0002","מתני׳ \u0001בנות\u0002 כותים נדות מעריסתן והכותים מטמאים משכב תחתון כעליון מפני שהן בועלי נדות","והן יושבות על כל דם ודם","ואין חייבין עליהן על ביאת מקדש ואין שורפין עליהם את התרומה מפני שטומאתן ספק","\u0001גמ׳\u0002 ה\"ד אי דקא חזיין אפילו דידן נמי ואי דלא קחזיין דידהו נמי לא","אמר רבא בריה דרב אחא בר רב הונא אמר רב ששת הכא במאי עסקינן בסתמא דכיון דאיכא מיעוטא דחזיין חיישינן ומאן תנא דחייש למיעוטא"],[[0,"שמשהין עצמן","מלהזריע:"],[0,"יכולני","שישהא עצמו מלהזריע:"],[0,"יבעול וישנה","שמתוך תאות בעילה ראשונה תהא מזרעת ונהי נמי דתזריע אחריו תקדום הזרעתה בבעילה שניה:"],[1,"בעון","על ידי דם נדה שהוא סימן להריון כדקיימא לן (כתובות דף י:) כל אשה שדמיה מרובין בניה מרובין והוא מביאו לידי עון וקדייק ר' יצחק בעון שסמוך לעון נדות שהוא מוזהר לפרוש הימנה:"],[2,"ובחטא","לשון טבילה וטהרה כדמפרש. וה\"ק על ידי דם נדות שהוא מביא לידי עון חוללתי שהוא גרם לי שנבראתי וכשנתחטאת אמי ממנו יחמתני:"],[4,"כר","מנחה דהיינו סימן שלום:"],[6,"נקיה","חסרה כמו (ב\"ק דף מא.) יצא פלוני נקי מנכסיו:"],[6,"עד דאמרה מזוני","שיודעת להתפלל:"],[6,"נקבה","כשתנקוב ותפרש שכרך ואתנה. ונקבה נמי הכי דרשינן:"],[7,"לפיכך תביא קרבן","שבועת ביטוי חטאת:"],[8,"מזידה היא","ואין כאן קרבן דהא ונעלם כתיב בשבועת ביטוי:"],[8,"ובחרטה תליא","לפתוח לה בחרטה ויתיר לה חכם שבועתה אבל קרבן אינו עוקר ומתיר שבועתה:"],[8,"ועוד קרבן שבועה בעי אתויי","כשבה או שעירה והאי עוף הוא:"],[9,"מתחרטת לשבעה","ומתאוה לתשמיש בעלה כדי שתחזור ותתעבר זכר:"],[10,"מפני מה מילה לשמונה","ולא לשבעה:"],[10,"שלא יהיו הכל שמחין","שאוכלין ושותין בסעודה ואביו ואמו עצבים שאסורין בתשמיש:"],[11,"נדה שבעה","לאו ביולדת קאי:"],[11,"מפני שאדם רגיל באשתו","כל שעה שירצה:"],[11,"קץ בה","מאוסה עליו. אמרה תורה כל שעה שתראה תהא טמאה שבעה כדי שלא יהא רגיל בה ותתחבב עליו:"],[12,"מחזר על האשה","אדם פנוי מבקש ומחזר עד שנושא:"],[13,"פניו למטה","בשעת תשמיש:"],[13,"זהו ממקום שנברא","מסתכל באדמה שנוצר ממנה והיא מסתכלת בו שנוצרה הימנו:"],[14,"מקבל פיוס","נוח לרצות:"],[14,"זה ממקום שנברא","אדמה. עפר תיחוח נוח ליבטל אבל בשר ועצמות קשין:"],[15,"עצם","כשמכין בו קולו נשמע אבל קרקע כשמכין בו אין קולו נשמע:"],[17,"מתני' בנות כותים נדות מעריסתן","מקטנותן. ובגמרא מפרש טעמא:"],[17,"תחתון כעליון","מפרש בגמ':"],[18,"והן יושבות על כל דם ודם","כלומר להכי הוו בועלי נדות משום דכל דם שרואות בין אדום בין ירוק יושבות עליו ימי נדות וזו תקלה היא להם שאם רואה דם ירוק היום מתחלת למנות ששה והוא אם תראה באותם ימי נדות דם אדום אינה מונה אלא מיום ראייה ראשונה ואותו דם ירוק טהור היה ומראייה שניה היא צריכה למנות:"],[19,"אין חייבין עליה","הלובש או מתכסה באותן בגדים ונכנס למקדש פטור מקרבן או אם נגעו אותן בגדים של משכב בתרומה תולין דלא ידעינן אי נדה היא אי לא והא דאמר דמסתמא טמאות גזירה דרבנן היא:"],[20,"גמ' אפילו דידן נמי","אי חזיא בעריסתן טמאה דתניא לקמן (נדה דף לב.) בת יום אחד לנדה מנין תלמוד לומר ואשה:"],[21,"דאיכא מיעוטא דחזיין","בקטנותן:"],[21,"חיישינן למיעוטא","ומטמאינן לכולהו מעריסתן משום דדילמא חזיא:"]],[[15,"","כי קולך ערב. אבל היא אינה מקלסתו בקול ערב אלא בצח ואדום:"],[17,"","מתני' בנות כותים. והן יושבות על כל דם ודם. ואם תאמר ותיפוק ליה שהן נדות מעריסתן ויש לומר דהיינו דוקא בקטנותן דלא דרשי ואשה כדאמר בגמרא אבל גדולות דמפרשי להו וטבלי לא מטמו אלא משום דיושבות על כל דם ודם:"],[17,"","תחתון כעליון. מפרש בגמרא תחתונו של בועל נדה כעליונו של זב דלא מטמא אלא אוכלין ומשקין ועליונו של זב מפרש רשב\"ם שהכריע הזב בכף מאזנים את האוכלין ומשקין שבכף שניה ולא נהירא דבפ' ר\"ע (שבת דף פג.) קרי ליה היסט מה שהכריע הזב בכף מאזנים והיסט נפקא לן מאשר יגע בהם הזב ועליונו של זב נפקא לן בשמעתין מקרא אחרינא ונראה דעליונו של זב היינו בגד שמקצתו על הזב ומקצתו נגרר על הארץ ולאו היינו היסט אלא כשמסיטו כולו כדאמר איזהו מגעו שהוא ככולו הוי אומר זה היסטו:"]]],[["ר\"מ היא דתניא קטן וקטנה לא חולצין ולא מיבמין דברי ר\"מ","אמרו לו לר\"מ יפה אמרת שאין חולצין איש כתוב בפרשה ומקשינן אשה לאיש ומה טעם אין מיבמין","אמר להן קטן שמא ימצא סריס קטנה שמא תמצא אילונית ונמצאו פוגעין בערוה שלא במקום מצוה","ורבנן זיל בתר רובא דקטנים ורוב קטנים לאו סריסים נינהו זיל בתר רובא דקטנות ורוב קטנות לאו אילונית נינהו","אימר דשמעת ליה לר\"מ מיעוטא דשכיח אבל מיעוטא דלא שכיח מי שמעת ליה","הא נמי מיעוטא דשכיח הוא דתניא א\"ר יוסי מעשה בעין בול והטבילוה קודם לאמה ואמר רבי מעשה בבית שערים והטבילוה קודם לאמה וא\"ר יוסף מעשה בפומבדיתא והטבילוה קודם לאמה","בשלמא דר' יוסי ודרבי משום תרומת א\"י אלא דרב יוסף למה לי והא אמר שמואל אין תרומת חו\"ל אסורה אלא במי שטומאה יוצאה מגופו והני מילי באכילה אבל בנגיעה לא","אמר מר זוטרא לא נצרכה אלא לסוכה שמן של תרומה דתניא (ויקרא כב, טו) ולא יחללו את קדשי בני ישראל אשר ירימו לה' לרבות את הסך ואת השותה","שותה למה לי קרא שתיה בכלל אכילה אלא לרבות את הסך כשותה ואיבעית אימא מהכא (תהלים קט, יח) ותבא כמים בקרבו וכשמן בעצמותיו","אי הכי דידן נמי","אנן דדרשינן אשה ואשה וכי חזיין מפרשי להו לא גזרו בהו רבנן אינהו דלא דרשי אשה ואשה וכי חזיין לא מפרשי להו גזרו בהו רבנן","מאי אשה ואשה דתניא אשה אין לי אלא אשה תינוקת בת יום אחד לנדה מנין ת\"ל ואשה","אלמא כי מרבי קרא בת יום אחד מרבי ורמינהו אשה אין לי אלא אשה תינוקת בת ג' שנים ויום אחד לביאה מנין ת\"ל ואשה","אמר רבא הלכתא נינהו ואסמכינהו רבנן אקראי הי קרא והי הלכתא אילימא בת יום אחד הלכתא בת שלש שנים ויום אחד קרא קרא סתמא כתיב","אלא בת ג' שנים ויום אחד הלכתא בת יום אחד קרא ומאחר דהלכתא קרא ל\"ל"],[[1,"איש כתוב בפרשה","(דברים כ״ה:ז׳) ואם לא יחפוץ האיש איש פוטרה בחליצה ולא קטן. אלא מה טעם אין מיבמין ויגדלו יחד:"],[2,"סריס","לאו בר הקמת שם הוא ואינו מצווה ליבם וכן אילונית וכיון דמייבם בלא מצוה נושא אשת אחיו בחנם וערוה היא ובכרת:"],[5,"בעין בול","מקום:"],[5,"קודם לאמה","יולדת נקבה טובלת לי\"ד ובתה ראתה ליום או ליומים שנולדה והטבילוה קודם לאמה משום מגע תרומה: עין בול ובית שערים מא\"י פומבדיתא חוץ לארץ:"],[6,"משום תרומת א\"י","דמיפסלא בנגיעה:"],[6,"יוצאה מגופו","כגון זב וזבה ונדה:"],[6,"והני מילי באכילה","כולה שמואל אמרה בבכורות בפ' הלוקח בהמה (דף כז.) ואפי' זב ונדה לא פסלי לה בנגיעה:"],[7,"לסוכה שמן של תרומה","דסיכה כאכילה ובאכילה קאמרינן דתרומת חו\"ל אסורה לנדה:"],[7,"דתניא","דסיכה כאכילה:"],[7,"ולא יחללו","בפרשת אזהרת טמאים בתרומה כתיב:"],[7,"לרבות את הסך","בכלל בקדשים לא יאכל עד אשר יטהר. שתיה בכלל אכילה דכתיב (דברים י״ד:כ״ג) ואכלת מעשר דגנך וגו' תירוש חמרא הוא וקרי ליה אכילה:"],[8,"ותבא כמים וגו'","בקללה גבי רשע קאי:"],[9,"א\"ה","דחייש למיעוטא:"],[9,"דידן נמי","ליטמו כולהו מעריסתן:"],[10,"אשה ואשה","לרבות קטנה כדמפרש:"],[10,"מפרשי להו","ממגע קדשים:"],[11,"ואשה כי תהיה זבה וגו'","בנדה משתעי קרא דכתיב (ויקרא ט״ו:י״ט) שבעת ימים תהיה בנדתה:"],[12,"ורמינהו אשה","ואשה אשר ישכב איש אותה שכבת זרע:"],[12,"לביאה","שמטמאה בביאת אדם מגזרת הכתוב דכתיב וטמאו ולא משום נוגעת בשכבת זרע הוא שהרי מגע בית הסתרים הוא ואינו מטמא:"],[13,"הלכתא נינהו","לענין נדה בת יום אחד ולענין ביאה בת ג' דברים הללו הלכה למשה מסיני הם כדמפרש ואזיל דחדא מינייהו הלכתא:"],[13,"הי קרא והי הלכתא","כלומר מכדי קרא חדא מינייהו משתמע הי מינייהו משתמע מקרא בלא הלכתא והי מינייהו אצטריך הלכתא:"],[13,"קרא סתמא כתיב","כיון דוי\"ו לרבויי אתא כל שהוא אשה משמע בת יום אחד אבל בת ג' לא משמע מיניה טפי מבת ב' או בת ד':"],[14,"אלא בת ג'","לענין ביאה הלכתא דמקרא לא משתמע ורבנן אסמכתא בעלמא אסמכוה ובת יום א' לנדה משתמעא מקרא:"],[14,"ומאחר","דביאה בת ג' הלכה למשה מסיני היא ומקרא לא משתמע עיקר קרא דוי\"ו יתירא למאי אתא:"]],[[0,"","רבי מאיר היא. תימה דמשמע דמתני' (לעיל נדה דף לא:) דבנות כותים נדות מעריסתן לא אתיא כרבנן אלא כרבי מאיר דחייש למיעוטא וסבר דכותים גרי אמת הן כדמוכח פ' שור שנגח ד' וה' (ב\"ק לח:) אבל לרבנן דלא חיישי למיעוטא לא הוו נדות מעריסתן ולא לר' יוסי אע\"ג דחייש למיעוטא בפרק אלמנה (יבמות דף סז:) כיון דקסבר כותים גרי אריות הן כדמוכח במנחות בפרק רבי ישמעאל (מנחות דף סו:) דקאמר תורמין משל (ישראל) על של עובדי כוכבים ואם כן כותים לא מטמאו בנדות כדאמר לקמן בנות ישראל מטמאין בזיבה ואין עובדי כוכבים מטמאים בזיבה ותימה והא בנות כותים דהוו נדות מעריסתן הוו מי\"ח דבר ובפ\"ק דשבת (דף יג:) משמע דליכא מאן דפליג על י\"ח דבר ומשמע התם (דף יז:) דהוי מי\"ח דבר לכ\"ע וי\"ל דאפי' רבנן דלא חיישי למיעוטא ואפילו גרי אריות הן שוינהו רבנן נדות מעריסתן וגזרו עליהם טומאה כדי שלא יטמעו בהן כמו שגזרו על בת עובד כוכבים וא\"ת אם כן אמאי מוקי לה כר\"מ ומשום דחייש למיעוטא לוקמיה ככ\"ע ומשום טימוע דר\"מ נמי אית ליה טעמא דטימוע דאמר בפ' ד' וה' (ב\"ק דף לח:) קנסא דקניס ר\"מ בממונא כדי שלא יטמעו בהן וי\"ל משום דע\"כ מתני' לית ליה טעמא דטימוע אלא משום חשש ראיה כדקתני לפי שיושבות על כל דם ודם והא דא\"ר יוסי מעשה בעין בול והטבילוה קודם לאמה אע\"ג דטעמא דרבי יוסי משום טימוע הוצרך להביא ראיה דשכיח הוא שרואות הן בקטנותן דאי לאו הכי הוי כחוכא וטלולא למיגזר בהן נדות וא\"ת לר\"מ דחייש למיעוטא וקסבר דכותים גרי אמת הן א\"כ הוו נדות מעריסתן מן התורה ולמה מני לה מי\"ח דבר וי\"ל דמסתמא לא ראתה מיד אחר ההולדה רגע אחד א\"כ אוקמה בחזקת שלא ראתה וסמוך רובא דלא חזו לחזקה שלא ראתה והוו הנך דחזו מיעוטא דמיעוטא ולא מטמו מדאורייתא אלא מדרבנן הוא דגזרו עליהם מי\"ח דבר וא\"ת ולר' יוסי דגרי אריות הן אמאי גזרו בכותים דהוו נדות מעריסתן ובבת עובד כוכבים לא גזרו עד בת ג' שנים כדאמרינן התם ויש לומר דהחמירו בכותים דעבדי קצת מצות ולא בדילי ישראל מינייהו וגזרו עליהם מעריסתן דלא ליתי וליטמעו בהן אבל מעובדי כוכבים הוו בדילי טובא ולא גזרו עלייהו עד דליהוי ראויות לביאה:"],[2,"","שמא תמצא אילונית. וא\"ת ותתיבם ממה נפשך דאם אילונית היא הוי קידושי אחיו טעות כדתנן (יבמות דף ב:) וכולן שנמצאו אילונית צרותיהן מותרות משום דלא הויא צרת ערוה ותירץ ר\"ת דהכא איירי בדקבל עלויה אחיו וכי האי גוונא משני בריש בן סורר ומורה (סנהדרין דף סט:) ואין להאריך כאן יותר וא\"ת ובקטן אמאי חיישינן שמא ימצא סריס וניבדקיה אם עושה כיפה כשמשתין או אחד משאר סימנין דאמר בהערל (יבמות דף פ:) ואיכא למ\"ד התם דלא הוי סריס עד שיהו בו כל סימני סריס וי\"ל דאין מועלת הבדיקה עד שהוא גדול בשנים:"],[5,"","והטבילוה קודם לאמה. ומשום שראתה דאי משום שנגעה באמה שטמאה לידה א\"כ מאי אשמעינן כל ולדות נמי טמאין. ובפרק עד כמה (בכורות דף כז'.) דקאמר גבי חלה דמאכילתו לכהן קטן ה\"ה לכהן גדול שטבל כדמשמע הכא:"],[8,"","שתיה בכלל אכילה. וא\"ת בפרק העור והרוטב (חולין דף קכ.) גבי חלב למה לי כל נפש לרבות שותה ויש לומר דאשמעינן דחלב מהותך שמיה חלב:"],[8,"","וכשמן בעצמותיו. ואם תאמר דמעיקרא מייתי מן התורה והדר מייתי אסמכתא דבפרק ר\"ע (שבת דף פו.) תנן דסיכה ביוה\"כ אסור אע\"ג שאין ראיה לדבר זכר לדבר שנאמר ותבא כמים בקרבו ואומר רבינו תם דקרא דלא יחללו נמי אסמכתא הוא דבפרק הנשרפין (סנהדרין דף פג.) דרשינן מיניה דטבל במיתה ובפרק קמא דזבחים (דף ג:) מידרש לדרשא אחריתי ומדאורייתא לא הוי סך כשותה וכן לענין יוה\"כ ותדע דאין חייבין כרת אלא אוכל ושותה בלבד ואמר נמי בפרק בתרא דיומא (דף עז:) מי שיש לו חטטין בראשו סך כדרכו ואינו חושש ועוד אומר ר\"ת דדוקא סיכת שמן אסמכוה רבנן אקרא ואסור מדרבנן אבל סיכה של שומן חזיר ושל חלב שריא ובפרק כל שעה (פסחים דף כד:) אמר המניח חלב של שור הנסקל ע\"ג מכתו פטור אבל אסור הוא משום דאסור בהנאה משמע אבל חלב דעלמא אפילו איסורא ליכא:"],[13,"","אי גרס הלכתא הוא א\"ש דלא הוי הלכתא אלא חדא ומיהו ברוב ספרים גרס נינהו היינו לפי שלא פירש רבא הי קרא והי הלכתא כלומר אחד מן הפסוקים וא\"צ לפרש משום דקאי נמי אקרא דזכרים דלקמן ובסוף הישן (סוכה דף כח.) גבי אזרח להוציא את הנשים קאמר הלכתא נינהו אע\"ג דליכא אלא חדא:"]]],[["למעוטי איש מאודם","והא דתניא אשה אין לי אלא אשה בת י' ימים לזיבה מנין ת\"ל ואשה למה לי ליגמר מנדה","צריכא דאי כתב רחמנא בנדה הוה אמינא נדה משום דכי חזאי חד יומא בעיא למיתב ז' אבל זבה דאי חזאי חד יומא בשומרת יום כנגד יום סגי לה אימא לא צריכא","וליכתוב רחמנא בזבה ולא בעי בנדה ואנא ידענא דאין זבה בלא נדה אין ה\"נ ואלא קרא למה לי למעוטי איש מאודם","הא מיעטתיה חדא זימנא חד למעוטי משכבת זרע וחד למעוטי מדם","וכן לענין זכרים דתניא (ויקרא טו, ב) איש איש מה ת\"ל איש איש לרבות תינוק בן יום אחד שהוא מטמא בזיבה דברי רבי יהודה","רבי ישמעאל בנו של ר' יוחנן בן ברוקה אומר אין צריך הרי הוא אומר (ויקרא טו, לג) לזכר ולנקבה לזכר כל שהוא זכר בין שהוא גדול בין שהוא קטן ולנקבה כל שהיא נקבה בין גדולה בין קטנה א\"כ מה ת\"ל איש איש דברה תורה כלשון בני אדם","אלמא כי מרבי קרא בן יום אחד מרבי ורמינהו איש אין לי אלא איש בן תשע שנים ויום אחד מנין ת\"ל (ויקרא טו ) ואיש","אמר רבא הלכתא נינהו ואסמכינהו רבנן אקראי הי הלכתא והי קרא אילימא בן יום אחד הלכתא ובן ט' שנים ויום אחד קרא קרא סתמא כתיב","אלא בן ט' שנים ויום אחד הלכתא ובן יום א' קרא וכי מאחר דהלכתא היא קרא למה לי למעוטי אשה מלובן","למה לי למכתב בזכרים ולמה לי למכתב בנקבות","צריכי דאי כתב רחמנא בזכרים משום דמטמאו בראיות כבימים אבל נקבות דלא מטמאו בראיות כבימים אימא לא","ואי כתב רחמנא בנקבות משום דקמטמו באונס אבל זכרים דלא מטמאו באונס אימא לא צריכא","הכותים מטמאין משכב תחתון כעליון מאי משכב תחתון כעליון אילימא דאי איכא י' מצעות ויתיב עלייהו מטמו להו פשיטא דהא דרס להו","אלא שיהא תחתונו של בועל נדה כעליונו של זב מה עליונו של זב אינו מטמא אלא אוכלין ומשקין אף תחתונו של בועל נדה אינו מטמא אלא אוכלין ומשקין","עליונו של זב מנלן דכתיב (ויקרא טו, י) וכל הנוגע בכל אשר יהיה תחתיו יטמא מאי תחתיו"],[[0,"למעוטי איש מאודם","ואע\"ג דקרא לאו באודם מיירי על כרחיך כיון דקרא יתירתא הוא לדרשא אתא ומה שיש לך לדרוש דבר הקרוב לענין דרוש בו וה\"ק אשה טמאה בדבר האמור בה דהיינו אודם ואין איש טמא בדבר האמור באשה. ואי קשיא ה\"ל למיכתב להך דרשה גבי נדה אין ה\"נ דלגבי נדה נמי קרא אחרינא כתיב דדרשינן לה לקמן הכי ומיהו תרוייהו צריכי כדקאמר לקמן ההוא דגבי נדה למעוטי איש מדם ממש שאין דם היוצא מפי האמה מטמא בזיבה והאי למעוטי שכבת זרע אדום האי במאי דאישתעי ביה והאי במאי דאישתעי ביה:"],[1,"והא דתניא אשה","לענין זבה כתיב ואשה כי יזוב זוב דמה ימים רבים ימים ב' רבים ג':"],[1,"בת י' ימים","דבציר מהכי ליכא זיבה ז' ימי נדה וג' ימי זיבה שאין זיבה אלא לאחר נדות כדמפרש בשמעתא בתרייתא דמכילתין:"],[1,"לגמר מנדה","כיון דבת יום אחד מטמא בנדה בת י' נמי מטמאה בזיבה דאין זיבה בלא נדה שאינה אלא לאחר נדות:"],[3,"ואלא קרא","ואשה דכתיב גבי נדה למה לי:"],[3,"למעוטי איש מאודם","דהכי משמע אשה מטמאה בנדה ולא איש:"],[4,"והא מיעטתיה","לעיל:"],[4,"חד למעוטי משכבת זרע","אדום אם יראה שכבת זרע אדום:"],[5,"וכן לענין זכרים","מרבי בן יום אחד:"],[5,"איש איש","כי יהיה זב:"],[7,"איש אין לי אלא איש","ואיש כי תצא ממנו שכבת זרע:"],[9,"ה\"נ גרסינן ומאחר דהלכתא קרא למה לי","ואבן תשעה לשכבת זרע קמהדר:"],[10,"למה לי למיכתב בזכרים","איש איש לרבות קטן בן יומו ולמה לי למיכתב בנקבות ואשה לרבות בת יום אחד לנדה ובת י' לזיבה:"],[11,"בראיות כבימים","בין שרואה ג' ביום אחד בין שרואה שלש בשלשה ימים רצופין הוי זב כדילפינן בב\"ק בפרק כיצד (דף כד.) לזכר ולנקבה מה נקבה בימים אף זכר בימים וראיות בגופיה כתיב מנה הכתוב שלש וקראו טמא אבל זבה שראתה שלש ביום אחד לא הויא זבה:"],[14,"","זב לא מיטמא באונס דכתיב מבשרו ולא מחמת אונסו. זבה מיטמאה באונס בהאי פירקא (לקמן נדה דף לו:) כשהוא אומר כי יזוב זוב דמה הרי אונס אמור:"],[14,"","משכב הזב והנדה מטמא אדם דכתיב (ויקרא ט״ו:ה׳) ואיש אשר יגע במשכבו וכתיב (שם) וכל הנוגע במשכבה וגו':"],[14,"כעליונו של זב","ולא כתחתונו שמטמא אדם:"]],[[6,"","(שייך לע\"ב) לנקבה כל שהיא בין גדולה בין קטנה. וקרא דואשה דזבה אתי לדרשא אחרינא ומעיינות דמצורע ומצורעת צריך לומר דמפיק ליה מקרא אחרינא דליכא למימר דתרוייהו משתמעי מהאי קרא דהא לקמן אמר אביי מדקאמר ר' יוסי זאת תורת הזב בין גדול בין קטן אייתור לזכר לרבות מעיינות:"],[9,"","למעוטי אשה מלובן. אע\"ג דבכל דוכתין דורשין וי\"ו לרבות והכא דורשין למעוטי פרש\"י כיון דלא אצטריך לרבות מיפרשי לקרא דלכך אייתר לומר דדוקא איש אמרתי לך ולא אשה וכן גבי אשה אשה אמרתי לך ולא איש הקשה הריב\"ן למה לי למעוטי אשה מלובן הא ממעטינן לעיל בפ\"ב (נדה דף יט.) מדמיה דמיה דד' דמים טמאים באשה ותו לא ותירץ דמ\"מ ה\"א דאתי בק\"ו מאיש דלא מיטמא באודם מיטמא בלובן אשה לא כ\"ש ואע\"ג דאיכא למיפרך מה לאיש שכן מיטמא בראיות כבימים איכא למימר גילוי מילתא בעלמא הוא:"],[11,"","צריכי דאי כתב רחמנא זכר כו'. תימה הא פרשב\"ם בפ' דם הנדה (לקמן נדה דף נד:) דאיתקש זב לנדה מדכתיב והדוה בנדתה וגו' לטמא אדם לטמא בגדים אם נישא משכבה ומושבה וכן פי' בסמוך גבי כלי חרס דמטמא בהיסט וכן משמע ביוצא דופן (לקמן נדה דף מא:) דמצריך קרא גבי נדה דמיטמאה בפנים כבחוץ מדכתיב בבשרה וגבי זב צריך קרא דלא מיטמא בפנים כבחוץ כי יהיה זב מבשרו עד שתצא מבשרו משמע דאיצטריך קרא דלא נגמר מנדה:"],[15,"","עליונו של זב מנלן. זאת היתה גירסת רש\"י דכתיב וכל הנוגע בכל אשר יהיה תחתיו יטמא מאי תחתיו אילימא תחתיו דזב מאשר יגע במשכבו נפקא אלא כל אשר יהיה הזב תחתיו והיה כתוב בספרים ומאי ניהו נושא מאי טעמא והנשא כתיב ולא גריס רש\"י דהא כבר נפקא מתחתיו ועוד דכתיב והנושא כתיב כבוס בגדים וחזר בו רש\"י מגירסא זו דהיכי מוקי האי קרא בעליונו של זב הא בהדיא בת\"כ מוקי לה במרכב ועוד היכי הוה בעי לאוקומי במשכב הא במשכב כתיב כבוס בגדים בנוגע בו והכא לא כתיב כבוס בגדים וכי ה\"ג פרכינן בפ\"ק (לעיל נדה דף ט.) גבי מזה מי נדה ועוד היכי מוקי ליה בעליונו של זב דאינו מטמא אלא אוכלין ומשקין הלא אין להם טהרה במקוה וקרא כתיב יטמא עד הערב ונראה דרש\"י ל\"ג מאי תחתיו אילימא כו' אלא גריס כל הנוגע בכל אשר יהיה תחתיו יטמא עד הערב והנושא נמי יטמא ומאי ניהו נישא מאי טעמא והנשא כתיב נתקו הכתוב מטומאה כו' וה\"פ והנוגע בכל אשר יהיה תחתיו במרכב איירי כדמוקי לה בת\"כ דהאי קרא אחר מרכב כתיב וחלק בין מגעו למשאו דמגעו מטמא אדם ולא בגדים דהכא לא כתיב כבוס בגדים ובמשאו מטמא אדם לטמא בגדים כדקמסיים קרא והנושא אותם יכבס בגדיו וקאי על כל מה דכתיב בענין מעיינותיו ומרכבו ומושבו ועליונו של זב דרשינן הכא מדכתיב והנשא חסר בלא וי\"ו קאי ארישא דקרא דמרכב דכתיב ביה יטמא ולא כתיב ביה כבוס בגדים והכי קאמר דהנוגע במרכב הזב יטמא וכן הנושא דהיינו עליונו של זב נתקו הכתוב מטומאה שלאחריו דע\"כ והנישא ארישא דקרא קאי ולא אסיפא דהא כתיב אותם וגבי נישא לא שייך אותם אלא אותם קאי אמאי דקרינן נושא והמסורת קאי ארישא דקרא ופריך אימא דנתקו מטומאה חמורה לטמא אדם לטמא בגדים אבל אדם או בגדים ליטמא כמו מרכב ומשני דיטמא טומאה קלה משמע דהנושא סמוך לנוגע במרכב ובגד שנגע במרכב לא מטמא אלא אוכלין ומשקין ומיהו יש ליישב גירסא ראשונה דדריש מתחתיו ואף על גב דקרא איירי במרכב מכל מקום תיבה דתחתיו לא איירי במרכב אלא בתחתיו דאמר בת\"כ ומייתי לה בפרק בכל מערבין (עירובין דף כז.) האוכף טמא מושב והתפוס טמא מרכב אלמא מה שתחתיו לא אקרי מרכב אלא מושב ולהכי קאמר דבעי תחתיו במאי מיירי אי במשכב מאשר יגע כו' והוה מצי למפרך דבמשכב כתיב כבוס בגדים והכא לא כתיב אלא דעדיפא מיניה פריך א\"נ מש\"ה לא כתיב כבוס בגדים משום דעיקר קרא במרכב כתיב דלא בעי כבוס בגדים ומפרש אלא שהזב תחתיו דהיינו עליונו של זב דלא מטמא אלא אוכלין ומשקין וטומאת ערב דכתיב בקרא משום מרכב דמרכב מטמא אדם או בגדים וגרס שפיר מאי טעמא והנשא כתיב דמתחתיו גרידא לא הוה מוקמינן בעליונו של זב דלא היינו בודים טומאה מלבנו אלא הוה מוקמינן לה במרכב ואי לאו נמי תחתיו מנושא לא הוה מוקמינן ליה לטומאה קלה דאוכלין ומשקין בנשא כיון דכתיב ביה כבוס בגדים וה\"א דנתקו לטמא אדם או בגדים קמ\"ל תחתיו דאיירי בעליונו של זב ונכתב גבי מרכב דליכא כבוס בגדים וכתיב ביה יטמא דמשמע טומאה קלה ועוד דע\"כ גרסינן והנשא כתיב דאי לא דרשינן עליונו של זב אלא מתחתיו היכי פריך אימא נתקו מטומאה חמורה היכא כתיב ביה טומאה חמורה דקאמר נתקו:"]]],[["אילימא תחתיו דזב (ויקרא ט״ו:י׳ ) מואיש אשר יגע במשכבו נפקא אלא הנוגע בכל אשר יהיה הזב תחתיו ומאי ניהו עליון של זב","והנושא נמי יטמא ומאי ניהו נישא מ\"ט והנשא כתיב","נתקו הכתוב מטומאה חמורה והביאו לידי טומאה קלה לומר לך שאינו מטמא אלא אוכלין ומשקין","אימר נתקו הכתוב מטומאה חמורה דלא מטמא אדם לטמא בגדים אבל אדם או בגדים ליטמא אמר קרא יטמא טומאה קלה משמע","ותחתונו של בועל נדה מנלן דתניא (ויקרא טו, כד) ותהי נדתה עליו","יכול יעלה לרגלה ת\"ל יטמא ז' ימים","ומה ת\"ל ותהי נדתה עליו שיכול לא יטמא אדם וכלי חרס ת\"ל ותהי נדתה עליו מה היא מטמאה אדם וכלי חרס אף הוא מטמא אדם וכלי חרס","אי מה היא עושה משכב ומושב לטמא אדם לטמא בגדים אף הוא עושה משכב ומושב לטמא אדם לטמא בגדים ת\"ל וכל המשכב אשר ישכב עליו יטמא","שאין ת\"ל וכל המשכב אשר ישכב עליו יטמא ומה ת\"ל וכל המשכב אשר וגו' נתקו הכתוב מטומאה חמורה והביאו לידי טומאה קלה לומר לך שאינו מטמא אלא אוכלין ומשקין","פריך רב אחאי אימא נתקו הכתוב מטומאה חמורה והביאו לטומאה קלה דלא ליטמא אדם לטמויי בגדים אבל אדם ובגדים ליטמא אמר רב אסי יטמא טומאה קלה משמע","אימא ותהי נדתה עליו כלל וכל המשכב פרט כלל ופרט אין בכלל אלא מה שבפרט משכב ומושב אין מידי אחרינא לא","אמר אביי יטמא ז' ימים מפסיק הענין הוי כלל ופרט המרוחקין זה מזה וכל כלל ופרט המרוחקין זה מזה אין דנין אותו בכלל ופרט","רבא אמר לעולם דנין וכל ריבויא הוא","מתקיף לה רבי יעקב אימא כהיא מה היא לא חלקת בה בין מגעה למשכבה לטמא אדם ולטמא בגדים לחומרא אף הוא לא תחלוק בו בין מגעו למשכבו לטמא אדם ולטמא בגדים לקולא","אמר רבא עליו להטעינו משמע","מפני שהן בועלי נדות וכו' אטו כולהו בועלי נדות נינהו א\"ר יצחק מגדלאה בנשואות שנו","והן יושבות על דם וכו' תניא אר\"מ אם הן יושבות על כל דם ודם תקנה גדולה היא להן","אלא שרואות דם אדום ומשלימות אותו לדם ירוק","דבר אחר יום שפוסקת בו סופרתו למנין שבעה","מתקיף לה רמי בר חמא ותספרנו ואנן נמי ניספריה דקיימא לן מקצת היום ככולו","אמר רבא אם כן שכבת זרע דסתר בזיבה היכי משכחת לה והא מקצת היום ככולו","אי דחזאי בפלגא דיומא ה\"נ הכא במאי עסקינן דחזאי סמוך לשקיעת החמה","וליקום ולימא ליה לקרא כי כתיבא סמוך לשקיעת החמה כתיבא אין על כרחך שבקיה לקרא דאיהו דחיק ומוקי אנפשיה","בעי רמי בר חמא פולטת שכבת זרע מהו שתסתור בזיבה רואה היתה וסותרת"],[[0,"אילימא תחתיו דזב","דהוא מדרס הזב:"],[1,"ומאי ניהו נישא","בגד הנישא על הזב. מאי טעמא והנושא והנישא כתיב לא ידענא מאי היא ונראה בעיני שהוא פי' משובש:"],[2,"נתקו הכתוב מטומאה חמורה","מדכתיב וכל הנוגע בכל אשר יהיה תחתיו יטמא והנושא אותם יכבס בגדיו ומדלא ערבינהו ונכתוב וכל הנוגע בכל אשר יהיה תחתיו והנושא אותם יכבס בגדיו ואפסקינהו ביטמא מכלל דהאי יטמא לאו באדם ובגדים קמיירי אלא באוכלין ומשקין והנושא אותם נדרש בתורת כהנים לנושא משכבו ומושבו של זב:"],[3,"אימא","להכי אפסקינהו קרא דלא יטמא אדם לטמא בגדים שעליו להכי כתב יטמא דאדם לחודיה טמא או אם נגעו בגדים יהו בגדים טמאים ולא הוא:"],[5,"יעלה לרגלה","יעלה לסופה. כגון בא עליה בששי שלה יטבול בליל המחרת כמותה:"],[5,"ז' ימים","ואפילו בא עליה בשביעי:"],[6,"מה היא מטמאה אדם","לטמא בגדים שעליו דאתי בקל וחומר ממשכבה אף הוא מטמא אדם לטמא בגדים שעליו:"],[6,"וכלי חרס","בהיסט. ואע\"ג דאין כלי חרס מקבל טומאה אלא מאוירו בהיסט זב וזבה מיטמא כדכתיב (ויקרא טו) (כל כלי) חרס אשר יגע בו הזב ואמרי' במכילתין איזהו מגעו שהוא ככולו הוי אומר זה היסטו:"],[8,"שאין ת\"ל וכל המשכב אשר ישכב עליו יטמא","שהרי כבר נאמר ותהי נדתה עליו ובדידה כתיב וכל הנוגע במשכבה יכבס בגדיו:"],[8,"מטומאה חמורה","שלא יהיה משכבו חמור כמשכבה לטמא אדם ובגדים שעליו:"],[9,"אבל אדם ובגדים","או אדם אם תגע בו או בגדים אם תגע בהם:"],[10,"מידי אחרינא לא","כגון אדם וכלי חרס:"],[12,"","וכל המשכב ריבויא הוא ולאו פרטא:"],[13,"אימא כהיא","בועלה כמותה דהא אקשינהו קרא:"],[13,"לחומרא","ששניהן מטמאין אדם לטמא בגדים:"],[13,"אף הוא לא תחלוק בין מגעו למשכבו","ולקולא ששניהם לא יטמאו דהא במשכבו פשיטא לן שנתקו הכתוב הלכך במגעו נמי שאם נגע באדם לא יטמאנו לטמא בגדים דהא כתיב ותהי נדתה עליו דהוקשו הוא והיא בהאי קרא:"],[14,"עליו","להחמיר משמע ולא להקל:"],[15,"אטו כולהו בועלי נדות נינהו","והא איכא פנויים:"],[16,"אם הן יושבות על כל דם ודם","שהן רואות בין טמא בין טהור יושבת עליו ז' ימי נדתה שהתחיל מנינה משנשתנה מראה דם ותמנה ז' ימים:"],[16,"תקנה גדולה היא להם","אבל אינן עושות כן אינן מונות אלא מראיה ראשונה כשאר נשים וזהו קלקולה שרואה דם אדום ומשלימתו לדם ירוק כגון ראתה ירוק תחלה סבורה היא שהיא טמאה ומונה ממנו ז' ימים וכשרואה בחמישי שלה דם אדום אינה משמרת אלא שני ימים להשלים ז' לראייתה הראשונה והיא צריכה למנות מראייה שניה:"],[18,"יום שפוסקת בו","כשהיא רואה ג' רצופים לאחר ז' ימי הנדה והויא זבה ופוסקת באמצע היום סופרת אותו קצת היום שעד הערב למנין שבעה נקיים ואנן ז' נקיים שלמים בעינן לזבה:"],[20,"א\"כ","דלענין נקיים מקצת היום ככולו זב שפסק והתחיל לספור וראה קרי וקיי\"ל דסותר אותו היום ותו לא בהמפלת בשמעתא קמייתא (לעיל נדה דף כב.) ואי מקצת היום ככולו מאי סותר הא איכא קצת היום לבא:"],[21,"אי דחזאי בפלגא דיומא כו'","קושיא היא. ומשני ולימא ליה לקרא כו' בתמיה:"],[22,"וקא מהדר לאוקמי אתקפתיה אין על כרחיך שבקיה לקרא כו'","דכיון דקיי\"ל בכל דוכתי מקצת היום ככולו איהו דחיק ומוקים אנפשיה בסמוך לשקיעת החמה:"],[23,"פולטת","כגון ששמשה בזוב ופסקה והתחילה למנות ופלטה מהו שתסתור מניינה הא דקי\"ל דפולטת טמאה משום רואה היא וסתרה:"]],[[1,"","והנשא כתיב. חסר וי\"ו. תימה דבמסורת הוא מלא מיהו מצינו שהמסורת הוא חולק על הש\"ס במסכת שבת (דף נה:) גבי בני עלי מעבירם כתיב ובמקראות שלנו כתיב מעבירים מלא:"],[6,"","מה היא מטמאה אדם וכלי חרס. משום דבהשותפין (ב\"ב ט:) גבי נושא נבלה ומדרס אע\"ג דמטמא שאר בגדים שעליו אינו מטמא אדם וכלי חרס לכך נקטינהו הכא:"],[11,"","כלל ופרט המרוחקין זה מזה. מפורש בפ' החובל (ב\"ק פה.):"],[16,"","תניא א\"ר מאיר וכו'. לרבי יוחנן דאמר בפ' כל היד (לעיל נדה יט:) ירד ר\"מ לשיטת עקביא בן מהללאל וטימא דם ירוק יפרש דם ירוק דהכא לאו ירוק ממש כי ההיא דלעיל אלא דיהה ממנו וכן לעקביא מטמאה כותית דם ירוק דיהה מדם ירוק שהוא טמא ולעיל פי' בע\"א:"],[18,"","סופרתו למנין ז'. וא\"ת ודאמר בכיצד צולין [ובמס' נזיר] (דף טו:) מקצת היום ככולו וזבה גדולה אמר התם דמשכחת אליביה ברואה בין השמשות וכי ככותים סובר דהכי פריך לקמן (נדה דף סט.) לרב דאמר יום שפוסקת בו עולה למנין שבעה ורב ככותאי אמרה לשמעתיה וי\"ל דר' יוסי לית ליה מקצת היום ככולו אלא בסוף ספירה כמו שומרת יום אבל בתחלה כמו שאומרים כותים מודה דלא אמרינן ומה שקשה מפ\"ק דר\"ה (דף י.) נפרש בסוף מכילתין בע\"ה:"],[22,"","דאיהו דחיק ומוקי אנפשיה. אין האמת כן מדפריך בפ' בתרא (לקמן נדה דף סט.) ורב ככותאי אמרה לשמעתיה:"],[23,"","רואה הויא וסתרה. אור\"י דמשכחת בשמשה בהיתר שתסתור ע\"י פליטה אחר ראיית ג' ימים רצופין דקי\"ל כרבנן בפ' ר' עקיבא (שבת פו:) דבעינן שש עונות שלמות א\"נ אחר ראייה אחת ואחר תיקון רבי זירא דסופרת שבעה נקיים על טיפת דם כחרדל דמסתמא צריך נמי נקיים מזרע דכעין דאורייתא תקון ומכאן אשה ששמשה וראתה מיד אין לה להתחיל לספור נקיים עד אחר יום ד' דבעינן ו' עונות שלמות וכן פסק ר\"ח ואפילו רבא דפליג הכא ארמי בר חמא נראה דחזר בו מדלא השיבו וכולהו אמוראי סברי פרק יוצא דופן (לקמן נדה דף מב.) דרואה הויא וסתרה אף לר\"ש וכ\"ש לרבנן והא דקאמר רבא לקמן (נדה דף לז.) ואחר תטהר שלא תהא טומאה מפסקת ביניהם אביי אומר שלא תהא זיבה מפסקת ביניהם משם אין להוכיח דרבא לא חזר בו דהתם איירי בטומאת לידה שטמאה ז' ועושה משכב ומושב כמו נדה ולכך קאמר שלא תהא מפסקת אבל קרי דלא סותר אלא יום א' לא מפסיק:"]]],[["או דילמא נוגעת היתה ולא סתרה","אמר רבא לפום חורפא שבשתא נהי נמי דסתרה כמה תסתור תסתור שבעה דיה כבועלה","תסתור יום אחד (ויקרא טו, כח) ואחר תטהר אמר רחמנא אחר אחר לכולן שלא תהא טומאה מפסקת ביניהם","וליטעמיך זב גופיה היכי סתר לטהרתו אמר רחמנא שלא תהא טומאה מפסקת ביניהן","אלא מאי אית לך למימר שלא תהא טומאת זיבה מפסקת ביניהן הכא נמי שלא תהא טומאת זיבה מפסקת ביניהן","ואין חייבין עליהן על ביאת מקדש וכו' רב פפא איקלע לתואך אמר אי איכא צורבא מרבנן הכא איזיל אקבל אפיה אמרה ליה ההיא סבתא איכא הכא צורבא מרבנן ורב שמואל שמיה ותני מתניתא יהא רעוא דתהוי כוותיה","אמר מדקמברכי לי בגוויה ש\"מ ירא שמים הוא אזל לגביה רמא ליה תורא רמא ליה מתני' אהדדי תנן אין חייבין עליהן על ביאת מקדש ואין שורפין עליהן את התרומה מפני שטומאתה ספק אלמא מספיקא לא שרפינן תרומה","ורמינהי על ששה ספקות שורפין את התרומה על ספק בגדי עם הארץ","אמר רב פפא יהא רעוא דלתאכיל האי תורא לשלמא הכא במאי עסקינן בכותי חבר","כותי חבר בועל נדה משוית ליה","שבקיה ואתא לקמיה דרב שימי בר אשי אמר ליה מאי טעמא לא משנית ליה בכותי שטבל ועלה ודרס על בגדי חבר ואזלו בגדי חבר ונגעו בתרומה","דאי משום טומאת עם הארץ הא טביל ליה ואי משום בועל נדה ספק בעל בקרוב ספק לא בעל בקרוב","ואם תמצי לומר בעל בקרוב ספק השלימתו ירוק ספק לא השלימתו והוי ספק ספיקא ואספק ספיקא לא שרפינן תרומה","ותיפוק ליה משום בגדי עם הארץ דאמר מר בגדי עם הארץ מדרס לפרושין אמר ליה בכותי ערום","\u0001מתני׳\u0002 בנות צדוקין בזמן שנהגו ללכת בדרכי אבותיהן הרי הן ככותיות פרשו ללכת בדרכי ישראל הרי הן כישראלית רבי יוסי אומר לעולם הן כישראלית עד שיפרשו ללכת בדרכי אבותיהן","\u0001גמ׳\u0002 איבעיא להו סתמא מאי ת\"ש בנות צדוקין בזמן שנוהגות ללכת בדרכי אבותיהן הרי הן ככותיות הא סתמא כישראלית אימא סיפא פרשו ללכת בדרכי ישראל הרי הן כישראלית הא סתמא ככותיות אלא מהא ליכא למשמע מיניה","ת\"ש דתנן ר' יוסי אומר לעולם הן כישראלית עד שיפרשו ללכת בדרכי אבותיהן מכלל דת\"ק סבר סתמא ככותיות ש\"מ","תנו רבנן מעשה בצדוקי אחד שספר עם כהן גדול בשוק ונתזה צנורא מפיו ונפלה לכהן גדול על בגדיו והוריקו פניו של כהן גדול וקדם אצל אשתו","אמרה לו אף על פי שנשי צדוקים הן מתיראות מן הפרושים ומראות דם לחכמים","אמר רבי יוסי בקיאין אנו בהן יותר מן הכל והן מראות דם לחכמים חוץ מאשה אחת שהיתה בשכונתינו שלא הראת דם לחכמים ומתה","ותיפוק ליה משום צנורא דעם הארץ אמר אביי בצדוקי חבר אמר רבא צדוקי חבר בועל נדה משוית ליה אלא אמר רבא"],[[0,"או משום נוגעת","ונוגע לא סותר:"],[1,"דיה כבועלה","זב המונה וראה קרי אינו סותר אלא יום אחד:"],[2,"תסתור יום אחד","אם כן לא הוו רצופין ורחמנא אמר ואחר תטהר אחר אחר לכולן כלומר זמן אחד לכולן שיהו רצופין טהרתן:"],[3,"לטהרתו אמר רחמנא","שבעת ימים לטהרתו משמע טהרה אחת שלא תהא הפסקה ביניהם והיכי סתר קרי יום א' ולא הוו רצופין:"],[4,"אלא מאי אית לך למימר שלא תהא טומאת זיבה מפסקת ביניהן","שאם רואה זוב סותר את כל מה שמנה אבל קרי לא הוה הפסקה:"],[5,"לתואך","מקום:"],[6,"רמא ליה תורא","רב שמואל שחט שור לכבוד רב פפא:"],[7,"על ספק בגדי עם הארץ","כלומר על בגדי עם הארץ אם נגעו בה נשרפת משום שמא טמא היה והאי כותי נמי תיפוק ליה אם נגע משכבו בתרומה דתהא נשרפת משום דעם הארץ הוא והוה ליה בגדי עם הארץ:"],[10,"שבקיה","רב פפא לאושפיזיה משום דכספיה ואזל לגבי רב שימי:"],[10,"מאי טעמא לא תשני ליה","מתני' דתנן אין שורפין על תחתונו של כותי את התרומה בכותי שטבל ועלה ודרס על בגדי חבר דהיינו במשכבו ונגע ההוא מדרס בתרומה:"],[11,"לא בעל בקרוב","כבר עברו ימי טומאתו וסלקא ליה טבילה:"],[13,"משום בגדי עם הארץ מדרס לפרושים","כלומר כשם שמדרס מטמא אדם ובגדים כך בגדי עם הארץ מדרס לפרושים:"],[15,"סתמא מאי","לתנא קמא דאמר נהגו ללכת בדרכי אבותיהן הרי אלו ככותיות פרשו ללכת בדרכי ישראלית הרי אלו כישראלית סתמא מאי:"],[16,"עד שיפרשו","אבל סתמא כישראלית מכלל דלת\"ק סתמא ככותיות:"],[17,"והוריקו פניו","חרה לו שנטמאו בגדיו וקדם כהן גדול אצל אשתו של צדוקי לשואלה אם השלימה לדם ירוק או לא:"],[19,"בקיאין אנו בהן","אני מכיר בנשי צדוקים ששכן היה להן:"],[20,"ותיפוק ליה","דאפילו עם הארץ ישראל דאינו בועל נדה קי\"ל צינורא דע\"ה מטמאה כל זמן שהיא לחה:"]],[[3,"","לטהרתו אמר רחמנא. ורבא סבר דלא משמע מלטהרתו שלא תהא טומאה מפסקת:"],[7,"","ורמינהו על ו' ספקות שורפין את התרומה. משום דכותי דמתני' ע\"ה הוא קפריך מדמספקי' ליה בבועל נדה והא קתני דעל ספק בגדי עם הארץ שורפין אבל פשיטא דאיכא ספקי טובא שאין שורפין עליהם את התרומה כגון טומטום בלובן או באודם וכיוצא בו ובמסקנא דאמר ספק בועל ברחוק ספק בועל בקרוב ואפילו בועל בקרוב שמא לא השלימתו לדם ירוק לא היה צריך לעשות ספק ספיקא כדפירשנו או שמא נראה להחמיר בזה כמו בספק בגדי ע\"ה לכך משכח ביה ספק ספיקא ומכאן קשה על מה שפירש\"י בפ\"ק דשבת (דף טו:) על הך (ברייתא) דעל ו' ספקות כו' על ספק מי רגלי אדם שכנגד מי רגלי בהמה ופירש דהשתא יש להסתפק שמא של בהמה הן ואפילו של אדם הן שמא של חבר הן והכא משמע דעל ספק ספיקא אין שורפין ומיהו אין להשוות גזירת חכמים דפעמים נראה להם להחמיר אפילו בספק ספיקא ור\"ת פי' התם דכיון דהם כנגד מי רגלי בהמה ודאי דעובד כוכבים הם דישראל היה נפנה לצדדין כדאמר בהניזקין (דף סד) וקשה דאפילו ודאי הם דישראל שורפין משום דשמא דע\"ה הן כדשרפינן על ספק הרוקין הנמצאים בההיא (ברייתא) ועוד דאטומאה דעובד כוכבים לא שרפינן תרומה כדאמר לקמן (נדה דף לד.) עבדו רבנן היכרא דלא לישרוף עליה תרומה וקדשים ונראה לפרש דלהכי נקט כנגד מי רגלי בהמה דאז ניכר שאינה של בהמה שאינן דומין לאותן שכנגדן וליכא אלא ספיקא אחת אבל אם היה להסתפק בשל בהמה לא הוי שרפי דהוי ליה ספק ספיקא:"],[9,"","בועל נדה משוית ליה. ואיהו סבר שהוא חבר למילי דעלמא ובזאת סבר לעשות בטוב וכן אביי דסמוך:"],[10,"","שדרס על בגדי חבר. והם נגעו בתרומה והא דלא אוקי כגון שנגע הכותי בתרומה משום דמתניתין לא איירי בהכי:"],[13,"","בכותי ערום. והא דלא אוקי כגון שדרס ברגלו יחף משום דאי היה לבוש בגדים שישבה עליהן אשתו נדה אע\"ג דטבל הוי אב הטומאה כדאמר בת\"כ והנושא את המדרס הרי הוא מטמא שנים ופוסל אחד לכך מוקי בערום דכשפירש מן המדרס לא היה אלא ראשון כדאמרינן בת\"כ ואינו מטמא כלי והוה מצי למימר כשהטביל גם הבגדים או שלבש בגדי חבר:"],[20,"","ותיפוק ליה משום צינורא דע\"ה. דוקא לענין צינורא עשאוהו כזב שאפשר ליזהר ויכולין לעמוד בה אבל חומרא יתירא כגון משכב ומושב והיסט לא עשאוהו כזב דבשילהי הניזקין (גיטין סא:) פריך וליחוש שמא תסיטם אשתו נדה אבל להיסט דנפשיה לא איכפת לן ושמעתין נמי מוכח דאין לו טומאת מדרס דאי אית ליה לעיל דפריך על ו' ספיקות כו' למאי דחשיב כותי כע\"ה הוה ליה לאקשויי מתני' גופה אמאי קתני מטמא משכב התחתון כעליון הא תחתונו של ע\"ה הוי כתחתונו של זב אלא ודאי אין לו טומאת מדרס והא דמשני בכותי שטבל ועלה ודרס כו' דאי משום טומאת ע\"ה הא טביל ליה היינו משום דאי לא טביל היה טמא מטעם מגעו דהא מוקי ליה בכותי ערום והא דנקט ודרס ולא נקט ונגע משום דמתניתין איירי בתחתונו ואין להקשות ולוקמה בדלא טבל וכגון שיש דבר מפסיק בין בגדי חבר לרגליו של כותי דהא ע\"כ איצטריך לאוקמי בטבל כי היכי דליהוי ספק ספקא דאי לא טבל מה לי בועל בקרוב מה לי ברחוק וכן משמע בפרק ד' דמסכת טהרות דתנן הגנבים שנכנסו בבית אין טמא אלא מקום רגלי הגנבים ומה הם מטמאין אוכלין ומשקין וכלי חרס פתוחים אבל משכבות ומושבות וכלי חרס המוקף צמיד פתיל טהורים ואם יש עמהם עובד כוכבי' או אשה הכל טמאין משמע דאין עם הארץ עושה משכב ומושב ואין מטמא בהיסט והא דקתני (שם פ\"ח מ\"א) הדר עם עם הארץ בחצר ושכח כלים בחצר אפי' חביות המוקפות צמיד פתיל הרי אלו טמאין היינו משום אשתו וכן הא דתנן בתוספתא דחגיגה (פ\"ג) ספק רשות עם הארץ מדרסו והיסטו טהורין לחולין וטמאין לתרומה היינו נמי משום חששא דאשתו ומיירי ההיא דטהרות נמי לתרומה והא דבגדי עם הארץ מדרס נמי לפרושים היינו משום דחיישינן שמא ישבה עליהם אשתו נדה והר\"ר משה מפונטיי\"ז היה מפרש דלשום דבר לא עשו עם הארץ כזב ואינו מטמא אלא משום בגדיו שישבה עליהן אשתו נדה והרי הוא נושא את המדרס וצינורא שלו טמא לפי שנגעה בשפתיו ולא משום מעיין ולא נראה דאם כן למה ליה למימר לעיל אי משום טומאת עם הארץ הא טביל ליה דכיון דעל כרחך איירי בערום כדפי' לעיל אפילו אי לא טביל ליה לא מטמא כיון שפירש מן המדרס כדתנא בתורת כהנים שהבאתי לעיל ועוד גבי צדוקי דהכא דפריך תיפוק ליה משום צינורא דעם הארץ פירוש ומה הרויח במה שקדם אצל אשתו והא אם בועל נדה הוא נטמא הוא ובגדיו כנושא רוקו של זב ואי משום צינורא דעם הארץ לא נטמא אלא הבגד לחוד משום משקה שמטמא כלי מדרבנן:"]]],[["רגל הוה וטומאת עם הארץ ברגל כטהרה שוינהו רבנן דכתיב (שופטים כ, יא) ויאסף כל איש ישראל אל העיר כאיש אחד חברים הכתוב עשאן כולן חברים","\u0001מתני׳\u0002 דם עובדת כוכבים ודם טהרה של מצורעת ב\"ש מטהרים ובית הלל אומרים כרוקה וכמימי רגליה","דם היולדת שלא טבלה ב\"ש אומרים כרוקה וכמימי רגליה וב\"ה אומרים מטמא לח ויבש","ומודים ביולדת בזוב שהיא מטמאה לח ויבש","\u0001גמ׳\u0002 ולית להו לב\"ש (ויקרא טו, ב) דבר אל בני ישראל ואמרת אליהם איש איש כי יהיה זב בני ישראל מטמאין בזיבה ואין העובדי כוכבים מטמאין בזיבה אבל גזרו עליהן שיהו כזבין לכל דבריהם","אמרי לך ב\"ש (ההוא בזכרים איתמר דאי בנקבות) היכי לעביד ליטמא לח ויבש עשיתו כשל תורה ליטמי לח ולא ליטמי יבש חלקת בשל תורה","אי הכי רוקה ומימי רגליה נמי כיון דעבדינן היכרא בדמה מידע ידיע דרוקה ומימי רגליה דרבנן","ולעביד היכרא ברוקה ומימי רגליה ולטמויי לדמה רוקה ומימי רגליה דשכיחי גזרו בהו רבנן דמה דלא שכיחא לא גזרו ביה רבנן","אמר רבא זובו טמא אפילו לב\"ש קריו טהור אפילו לב\"ה","זובו טמא אפילו לב\"ש דהא איכא למעבד היכרא בקריו","קריו טהור אפי' לב\"ה עבוד ביה רבנן היכרא כי היכי דלא לשרוף עליה תרומה וקדשים","ולעביד היכרא בזובו ולטמויי לקריו זובו דלא תלי במעשה גזרו ביה רבנן קריו דתלי במעשה לא גזרו ביה רבנן","לימא מסייע ליה עובדת כוכבים שפלטה שכבת זרע מישראל טמאה ובת ישראל שפלטה שכבת זרע מן העובד כוכבי' טהורה מאי לאו טהורה גמורה לא טהורה מדאורייתא טמאה מדרבנן","ת\"ש נמצאת אומר שכבת זרע של ישראל טמאה בכל מקום"],[[0,"רגל הוה וטומאת עם הארץ","דלאו צדוקי דדרך אשתו להראות דם:"],[0,"כטהרה שוינהו רבנן","ברגל. אבל צדוקי דסתמא בועל נדה הוא נהי נמי דטומאת עם הארץ ליכא טומאת בועל נדה איכא:"],[0,"ויאסף וגו'","בפלגש בגבעה כתיב ומיניה שמעינן בכל זמן שישראל נאספים למקום אחד קרי להו חברים ורגל היינו אסיפה:"],[1,"מתני' בית שמאי מטהרין","בדם עובדת כוכבים אע\"ג דברוקה ובמימי רגליה מודו דחכמים גזרו עליהם להיות כזבין לכל דבריהם אפי' הכי דמה טהור. וטעמא מפרש בגמרא דשיירו בה רבנן למיהוי היכרא דטומאתה מדרבנן:"],[1,"ודם טוהר של מצורעת","ואע\"ג דמעיינות מצורעת כגון רוקה ומימי רגליה הוי אב הטומאה כדאמר בהמפלת (לעיל נדה דף כח:) לזכר לרבות מצורע שמעיינותיו טמאים כשל זב דכתיב ביה וכי ירוק הזב בטהור אפילו הכי דם טוהר שלה טהור דלאו מעיין הוא דדומיא דרוק בעינן שמתעגל ויוצא כדאמרינן בפ\"ב (לעיל נדה דף יט:) גבי דם הירוק:"],[1,"וב\"ה אומרים כרוקה וכמימי רגליה","שמטמאין לחין ואין מטמאין יבשין גבי דם עובדת כוכבים מטמא מדרבנן שגזרו עליהן שיהו כזבין לכל דבריהם והך היכרא הוא דעבוד בה דאילו דישראלית מטמא לח ויבש ודעובדת כוכבי' לח ולא יבש כרוקה וכמימי רגליה דאמר לקמן בפרק דם הנדה דאין מטמאין יבשין ודם טוהר של מצורעת נמי אע\"ג דדם לאו מעיין הוא דין מעיין אית ליה דרחמנא רבייה כדאמר בגמרא:"],[2,"דם היולדת","שעברו ימי טומאת לידה ולא טבלה:"],[2,"בית שמאי אומרים כרוקה וכמימי רגליה","מטמא לח ואינו מטמא יבש והכי תני לה בהדיא בתוספתא דעדיות דנדה כל זמן שלא טבלה הרי היא בנדתה לכל דבריה הלכך רוקה ומימי רגליה בטומאתן ולקמן בפרק דם הנדה (נדה נו.) ילפינן מקראי דאין רוק של זב מטמא יבש ודמה נמי אף על גב דדם טוהר הוא לבית שמאי כדאמר בגמרא דביומי תליא רחמנא והא מלו ומשום מעיין נמי ליכא לטמויי דהא אין מתעגל ויוצא אפילו הכי רבנן גזור עליה הואיל וטמאה היא גזרה לאחר ז' אטו תוך ז' ומיהו לא גזור עליה שיטמא לח ויבש כלפני ז' דעבוד בה היכרא דלידעו דטומאתה מדרבנן ולא נשרוף עליה תרומה וקדשים. ואע\"ג דגבי דם עובדת כוכבים לא אמרי בית שמאי הכי אלא מטהרי לגמרי והיינו טעמא כדאמר בגמרא משום דחיישינן דלמא אתי לחלק בשל תורה ולמימר מטמא לח ולא יבש התם הוא דכל טומאת עובד כוכבים דרבנן כדי שלא יהו ישראל רגילין אצלן במשכב זכור וכיון דטמאו מגען ורוקן ומימי רגליהן ואיכא הרחקה טובא הלכך טהרו את דמה לגמרי להיכרא דלידעו דטומאת רוקה ומימי רגליה דרבנן דלא נשרוף תרומה עלייהו ולא חלקו בדמה דילמא אתי לחלק בשל תורה אבל הכא אין כאן מדרבנן אלא דם לבדו שהוא דם טוהר הלכך גזור ושיור בה להיכרא דליכא למיחש דלמא אתי לחלוקי בשל תורה דהכל יודעין דכיון דעברו ימי לידתה דדם טוהר הוא:"],[2,"ובית הלל אומרים מטמא לח ויבש","דטומאתן מן התורה כל זמן שלא טבלה דקסברי ביומי וטבילה תלא רחמנא:"],[4,"גמ' גזרו עליהן שיהו כזבין לכל דבריהן","משום שלא יהא תינוק ישראל רגיל אצלו במשכב זכור:"],[5,"עשיתו כשל תורה","דכיון דליכא היכרא אתי למשרף עליה תרומה וקדשים:"],[5,"ליטמא לח ולא יבש","כדקאמריתו:"],[5,"חלקת בשל תורה","אתי לחלק בדם ישראלית שהוא של תורה ולמימר דמטמא לח ולא יבש הילכך שיירוה ולא גזור בה שום טומאה כי היכי דניהוי היכרא לטומאת עובדי כוכבים דמדרבנן היא ולא נשרוף עליה תרומה:"],[6,"אי הכי רוקה ומימי רגליה נמי","דלגבי ישראלית לח ולא יבש כי מטמית להו בעובדת כוכבים עשיתו כשל תורה דקיי\"ל בפ' דם הנדה (לקמן נדה דף נד:) רוקו וניעו מטמאין לחין ולא יבשין ונעביד היכרא ברוקה דעובדת כוכבים ומימי רגליה לטהרן לגמרי:"],[7,"","דם לגבי רוק לא שכיח חשיב ליה:"],[8,"זובו","של עובד כוכבים:"],[8,"טמא אפילו לבית שמאי","דמקילי בדם האשה בזוב של זכר מודו שהטיפה מטמא אחרים במגע:"],[8,"קריו טהור אפילו לבית הלל","עבדי ביה היכרא דלידעו דטומאת עובדי כוכבים דרבנן דב\"ה נמי היכרא בעו כדאמרינן בדם העובדת כוכבים ברוקה ובמימי רגליה ולא טמאוהו לח ויבש כישראלית וגבי זב דגבי ישראל נמי כל טומאותיו לחין ולא יבשין אי לא מטהרי חדא מינייהו לגמרי ליכא היכרא:"],[11,"קריו תלוי במעשה","אין קרי בא אלא ע\"י חימום:"],[12,"עובדת כוכבים שפלטה כו' טמאה","השכבת זרע אבל בעובדת כוכבים לא שייכא בה טומאה כבהמה דעלמא:"],[12,"טהורה","הטיפה אלא קריו טהור:"]],[[5,"","ליטמא לח ולא יבש חילקת בשל תורה. אע\"ג דדם יולדת שלא טבלה דטהורה מן התורה אמרי ב\"ש דמטמא לח ולא יבש התם ידעי כיון שעברו ימי לידה דאין דמה [טמא] מן התורה אבל עובדת כוכבים שעשאוה כנדה שהרי הם כזבין אם נחלק בדמה אתי לחלק בשל ישראל ודם טהרה של מצורעת שטהור לגמרי אין לחוש שלא החמירו בה כיון דכבר טבלה ודם טהור הוא:"],[9,"","וזובו טמא דעבדי היכרא בקריו. וא\"ת ואמאי לא שרפינן הא שרפינן על ספק רוקו דעם הארץ פרק קמא דשבת (טו:) כל שכן בזובו של עובד כוכבים ויש לומר דבעם הארץ שורפין משום דאית ביה דררא דטומאה דאורייתא אם הוא זב או בועל נדה אבל עובד כוכבים אין לו שום טומאה דאורייתא:"]]],[["ואפי' במעי עובדת כוכבים ושל עובד כוכבים טהור' בכל מקום ואפי' במעי ישראלית חוץ ממי רגלים שבה","וכי תימא ה\"נ טהור' מדאוריית' אבל טמאה מדרבנן אטו מי רגליה מדאורייתא מי מטמאו אלא ש\"מ טהורה אפילו מדרבנן ש\"מ","אמר מר שכבת זרע של ישראל טמאה בכ\"מ אפי' במעי עובדת כוכבים תפשוט דבעי רב פפא דבעי רב פפא שכבת זרע של ישראל במעי עובדת כוכבים מהו","בתוך ג' לא קמיבעיא ליה לרב פפא כי קמיבעיא ליה לאחר ג' מאי","ישראל דדייגי במצות חביל גופייהו ומסריח עובדי כוכבים דלא דייגי במצות לא חביל גופייהו ולא מסריח או דילמא כיון דאכלי שקצים ורמשים חביל גופייהו ומסריח תיקו","דם טהרה של מצורעת ב\"ש כו' מאי טעמא דב\"ה אמר ר' יצחק לזכר לרבות מצורע למעינותיו ולנקבה לרבות מצורעת למעינותיה","מאי מעינותיה אילימא שאר מעינותיה מזכר נפקא אלא לדמה לטמא דם טהרה שלה","וב\"ש נקבה מזכר לא אתיא דאיכא למיפרך מה לזכר שכן טעון פריעה ופרימה ואסור בתשמיש המטה תאמר בנקבה דלא","וב\"ה לכתוב רחמנא בנקבה ולא בעי זכר ואנא אמינא ומה נקבה שאינה טעונה פריעה ופרימה ואינה אסורה בתשמיש המטה רבי רחמנא מעינותיה זכר לא כ\"ש","אם אינו ענין לזכר תנהו ענין לנקבה ואם אינו ענין למעינותיה תנהו ענין לדמה לטמא דם טהרה שלה","וב\"ש זכר מנקבה לא אתיא דאיכא למיפרך מה לנקבה שכן מטמאה מאונס תאמר בזכר דלא","וב\"ה קיימי במצורע ופרכי מילי דזב וב\"ש שום טומאה פרכי","ואיבעית אימא אמרי לך ב\"ש האי לזכר מיבעי ליה לזכר כל שהוא זכר (האי) בין גדול בין קטן ובית הלל נפקא להו מזאת תורת הזב בין גדול בין קטן","אמר רב יוסף כי פשיט רבי שמעון בן לקיש בזב בעי הכי ראייה ראשונה של זב קטן מהו שתטמא במגע (ויקרא טו, לב) זאת תורת הזב ואשר תצא ממנו שכבת זרע אמר רחמנא","כל ששכבת זרע שלו מטמא ראייה ראשונה שלו מטמאה והאי כיון דשכבת זרע שלו לא מטמאה ראייה ראשונה נמי לא תטמא או דילמא כיון דאילו איהו חזי תרתי מצטרפא מטמיא","אמר רבא ת\"ש זאת תורת הזב בין גדול בין קטן מה גדול ראייה ראשונה שלו מטמא אף קטן ראייה ראשונה נמי מטמא","בעי רב יוסף ראייה ראשונה של מצורע מהו שתטמא במשא מקום זיבה מעין הוא ומטמא או דילמא לאו מעין הוא","אמר רבא ת\"ש (ויקרא טו, ב) זובו טמא הוא לימד על הזוב שהוא טמא במאי אילימא בזב גרידא"],[[0,"ואפי' במעי עובדת כוכבים","שאם תפלטנו על הבגד תטמאנו:"],[0,"חוץ ממימי רגליה שבה","דאי פתיכי במימי רגליה טמאים כדאמרינן לעיל גזרו עליהם שיהו כזבים אבל קריו טהור כדאמרינן עבדו ביה רבנן היכרא:"],[3,"כי מיבעיא ליה לאחר ג'","דלגבי ישראלית טהורה כדאמר במסכת שבת בפרק ר\"ע:"],[4,"דדייגי","יראים וחרדים במצות ומתוך דאגתן מתחממין:"],[4,"חביל","חם:"],[6,"שאר מעינותיה","כגון רוקה ומימי רגליה דאתו מזב דכתיב ביה (ויקרא ט״ו:ח׳) וכי ירוק הזב ומיניה נפקי שאר מעיינות:"],[6,"מזכר נפקא","כיון דאתרבי מצורע למעינותיו אתרבי מצורעת לכל מעינותיה דאיכא דכוותיהו בזכר:"],[6,"אלא לדמה","דליתיה בזכר:"],[7,"ואסור בתשמיש המטה","בשבעת ימי ספירו דכתיב וישב מחוץ לאהלו ואין אהלו אלא אשתו שנאמר (דברים ה׳:כ״ז) שובו לכם לאהליכם:"],[7,"תאמר בנקבה","מצורעת דליתא בכל הני. בכריתות בפרק ד' מחוסרי כפרה (כריתות דף ח:) איש פורע ופורם ואין אשה פורעת ופורמת וגבי תשמיש נמי מחוץ לאהלו כתיב ולא מחוץ לאהלה הילכך לא אתיא מזכר ואיצטריך לנקבה לגופה ולעולם לשאר מעינות. ומהיכא דנפקי שאר מעינות ליכא למימר דילפינן לדם דשאר מעינות ילפינן מרוק מה רוק שמתעגל ויוצא הוא מתאסף תחלה יחד ואחר כך יוצא ודם לאו מתעגל ויוצא הוא:"],[9,"ואם אינו ענין לשאר מעינותיה","דנפקי מלנקבה:"],[10,"שכן מטמאה באונס","לגבי זיבה:"],[11,"ופרכי מילי דזב","בתמיה:"],[12,"ה\"ג ואי בעית אימא אמרי לך ב\"ש האי לזכר מיבעי ליה כל שהוא זכר כו'","ול\"ג נקבה כל שהיא נקבה כו' דא\"כ מעינות למצורע מנא להו אלא לנקבה לרבות מצורעת למעינותיה ויליף זכר מנקבה למעינות והאי לזכר דמייתר להו לב\"ה דרשי ליה ב\"ש לזב קטן שמטמא בזיבה בן יומו ולא נפקא להו מאיש איש דסבירא להו דברה תורה כלשון בני אדם ותינוקת קטנה נפקא להו מאשה ואשה כדילפינן בריש פירקא ואייתר להו לנקבה דהכא לרבות מצורעת למעינותיה וב\"ה נמי לא דרשי איש איש מיהו נפקא להו מזאת תורת הזב בין גדול בין קטן מטמא בזיבה:"],[13,"כי פשיט","כי דריש:"],[13,"מהו שתטמא","שניה לא מיבעיא לן דהא מרבינן לה מלזכר כל שהוא זכר והתם תרתי ראיות כתיבי והזב את זובו וראשון של זב גדול נפקא לן מהאי קרא זאת תורת הזב דהיינו חדא ראייה דחדא זיבה כתיב בקרא (ויקרא ט״ו:ל״ב) ואשר תצא ממנו שכבת זרע איתקש ראייה ראשונה לקרי אבל דקטן מאי מי אמרינן כיון דלקרי איתקש לא משכחת לה אלא בגדול דאיתיה בקרי אבל קטן דליתיה בקרי ליתיה בראייה ראשונה. או דילמא כיון דאילו חזי קטן ראייה אחריתי מצטרפת לקמייתא טומאת שבעה כדין זב בעל שתי ראיות:"],[14,"מטמא","נמי כשל גדול טומאת ערב בקרי:"],[16,"ראייה ראשונה של מצורע מהו שתטמא במשא","של איש טהור לא תבעי לך דודאי לא מטמא במשא דאיתקש לקרי וקרי לא מטמא במשא כדתנן בפ\"ק דמסכת כלים ושניה נמי לא תבעי לך דאפילו באדם טהור מטמיא במשא כדאמר לקמן בפרק דם הנדה (נדה דף נה.) זוב מטמא במשא ויליף לה מזובו טמא הוא וההוא בראייה שניה כתיב דמנה הכתוב שתים וזב בעל שתי ראיות זב גמור הוא לטומאה אלא שאין טעון קרבן כי תיבעי לן ראשונה דבאדם דעלמא לא מטמיא אלא במגע הכא במצורע מאי מקום זיבה מעיין הוא ואיתרבי מלזכר לרבות מצורע למעיינותיו ומעיינות מטמאו במשא כדאמר בפרק דם הנדה (לקמן נדה דף נה:) וכי ירוק הזב בטהור במה שביד טהור:"],[16,"או לאו מעיין הוא","והויא כשאר ראייה ראשונה של כל אדם דבמגע מטמיא:"],[17,"זובו טמא","היינו ראייה שניה שהרי מנה הכתוב שתים זב מבשרו זובו טמא:"],[17,"לימד על הזוב שהוא טמא","ואמר בדם הנדה (שם דף נה.) דהאי קרא לרבות למגע לא איצטריך דלא גרע משכבת זרע אלא למשא:"],[17,"אילימא בזב גרידא","דלאו מצורע למה לי קרא לטיפה עצמה פשיטא:"]],[[3,"","כי קמיבעיא ליה לאחר ג'. אע\"פ שהש\"ס קבעו בדברי רב פפא בשבת פרק ר\"ע (שבת דף פו:) אינו מדברי רב פפא כדמשמע הכא וכי האי גוונא אשכחן פ' המקבל (ב\"מ דף קיב.) דבעו מרב ששת קבלן עובר בבל תלין או לא אומן קונה בשבח כלי והלואה היא או אינו קונה ושכירות היא אמר להו עובר ובהגוזל קמא (ב\"ק דף צט.) מוקי לה ההיא בעיא בשליח דאגרת דלא שייך אומן קונה בשבח כלי א\"נ י\"ל דהכל מדברי רב פפא והכא סבר המקשה דרב פפא בעי בין תוך ג' בין לאחר ג' מי אמרינן דכיון דאכלי שקצים ורמשים אף בתוך ג' מסריח וטהור או דלמא כיון דלא דייגי במצות אף אחר ג' טמא:"],[9,"","אם אינו ענין לזכר תנהו ענין לנקבה. וא\"ת ולוקי ליה בדם מגפתו או יוצא מפיו או מנחיריו ושאר משקין שבו שאינו מעין דמטהר לקמן בפרק דם הנדה (נדה דף נה:) בזב וי\"ל דלא בעי לאוקמיה בהו משום דלא אשכחן בהו טומאה בשום מקום אבל דם טוהר דמי לדם נדה אפילו למ\"ד ב' מעינות הן:"],[12,"","ובית הלל נפקא להו מזאת תורת הזב. הוה מצי למימר מאיש איש אלא דבעי לאוקמי בית הלל אפי' כמ\"ד דברה תורה כלשון בני אדם:"],[16,"","מקום זיבה מעין הוא או לא . וא\"ת דבפ' דם הנדה (לקמן נדה דף נו.) משמע דזוב לאו מעין הוא דאמר ונילף מזובו שאינו מתעגל וי\"ל דהתם קאמר ונילף מזובו אי לאו מעין הוא א\"נ אף על גב דאינו מתעגל כדקאמר התם מ\"מ בעי ליה הכא אי כמעין הוא ורבינן ליה במצורע מקרא דלזכר כמו שאר מעינות כיון דבזב אית ליה לזוב טומאה חמורה כמו ברוקו ומימי רגליו:"],[17,"","אילימא בזב גרידא לאחרים גורם טומאה. תימה וכי לא ידע רבא סיפא דברייתא דקתני בה בהדיא לקמן בפרק דם הנדה (נדה דף נה.) שעיר המשתלח יוכיח:"]]],[["לאחרים גורם טומאה לעצמו לא כל שכן אלא פשיטא בזב מצורע","ומדאיצטריך קרא לרבויי בראייה שניה שמע מינה מקום זיבה לאו מעין הוא","אמר ליה רב יהודה מדסקרתא לרבא ממאי דילמא לעולם אימא לך בזב גרידא ודקאמרת לאחרים גורם טומאה לעצמו לא כל שכן שעיר המשתלח יוכיח שגורם טומאה לאחרים והוא עצמו טהור","אמר אביי מאי תבעי ליה והא הוא דאמר זאת תורת הזב בין גדול בין קטן וכיון דנפקא ליה מהתם אייתר ליה לזכר לרבות מצורע למעינותיו נקבה לרבות מצורעת למעינותיה","ואקשיה רחמנא מצורע לזב גמור מה זב גמור מטמא במשא אף ראייה ראשונה של מצורע מטמא במשא","א\"ר הונא ראייה ראשונה של זב מטמאה באונס שנאמר (ויקרא טו, לב) זאת תורת הזב ואשר תצא ממנו שכבת זרע מה שכבת זרע מטמא באונס אף ראייה ראשונה של זב מטמאה באונס","תא שמע ראה ראייה ראשונה בודקין אותו מאי לאו לטומאה לא לקרבן","ת\"ש בשניה בודקין אותו למאי אילימא לקרבן אבל לטומאה לא אקרי כאן מבשרו ולא מחמת אונסו אלא לאו לטומאה ומדסיפא לטומאה רישא נמי לטומאה","מידי איריא הא כדאיתא והא כדאיתא","תא שמע רבי אליעזר אומר אף בשלישי בודקין אותו מפני הקרבן מכלל דתנא קמא מפני הטומאה קאמר","לא דכולי עלמא לקרבן והכא באתים קא מיפלגי רבנן לא דרשי אתים ורבי אליעזר דריש אתים","רבנן לא דרשי אתים הזב חדא זובו תרתי לזכר בשלישי אקשיה רחמנא לנקבה","ורבי אליעזר דריש אתים הזב חדא את תרתי זובו תלת ברביעי אקשיה רחמנא לנקבה","תא שמע רבי יצחק אומר והלא זב בכלל בעל קרי היה ולמה יצא להקל עליו ולהחמיר עליו להקל עליו שאין מטמא באונס ולהחמיר עליו"],[[0,"לאחרים גורם טומאה","כלומר טיפה זו גורמת לבעלה שמטמא במשא כדכתיב (ויקרא טו) וכל אשר יהיה תחתיו ואוקמינן בעליונו של זב היא עצמה לא כל שכן:"],[0,"אלא בזב מצורע","איצטריך דלא אתי בקל וחומר דלא גרמה לו טומאה שהרי מחמת נגעו היה מטמא במשא ואפילו באהל:"],[1,"ומדאיצטריך קרא לרבויי לשניה ש\"מ","בראשונה דלאו מעיין הוא דאי מעיין הוא ראשונה מטמאה שניה לא כל שכן:"],[2,"לעולם אימא לך בזב גרידא","דאי במצורע לא איצטריך קרא לרבויי דאפילו ראשונה מטמא משום מעיין:"],[2,"ודקאמרת כו' שעיר המשתלח יוכיח שגורם טומאה","למשלחו כדכתיב (ויקרא ט״ז:כ״ו) והמשלח את השעיר וגו' והוא עצמו טהור שאין בהמה מטמאה מחיים:"],[3,"מאי תיבעי ליה","לרב יוסף:"],[3,"הא איהו אמר כו' בין קטן בין גדול","לזיבה ולא איצטריך והזב את זובו לזכר לרבות קטן דהא מזאת תורת הזב נפקא ואייתר לזכר לרבות מצורע:"],[4,"ואיתקש מצורע לזב גמור","בעל שתי ראיות דהא בהאי קרא דהיקשא דמצורע תרתי כתיבי והזב את זובו הרי שתים וכתיב ביה לזכר לרבות מצורע כדין זב גמור מה זב גמור זובו מטמא במשא אף מצורע זובו מטמא במשא ואפילו ראשונה דבשלמא אי מפיק ליה האי לזכר לזב קטן ויליף מצורע זכר ממצורעת נקבה איכא למבעי ראייה ראשונה מהו מי הוי מתעגל ויוצא ומתרבי עם שאר מעיינות או לאו דבנקבה ליכא זוב לובן למילפיה מהיקשא דזב גמור אי לאו מעיין הוי אבל השתא דמצורע זכר איתקש לזב גמור לא צריך תו למבעי: ואית דמפרשי בעיא דרב יוסף הכי ראייה ראשונה של מצורע מהו שתטמא במשא בזב גרידא לא תבעי לך דודאי מטמא כדאמר לקמן לימד על הזוב שהוא טמא ומוקמינן בדם הנדה דקרא למשא אתא כי תבעי לך במצורע דאיכא למימר בזב גרידא הוא דמטמא משום דגורמת לו טומאה אבל במצורע כבר טמא הוא ואינה גורמת לו טומאה לא מטמיא הטיפה אי לא אמרינן מעיין הוא כרוקו או מימי רגליו מאי מעיין הוא או לא. לימד על הזוב ומוקמינן לה בראייה ראשונה והכי משמע כי יהיה זב מבשרו אותו הזב טמא. לאחרים לבעלה. ומדאיצטריך לרבויי לראייה ראשונה ש\"מ לאו מעיין הוא. ושיבוש הוא מפני כמה תשובות חדא דקא פשיט ליה מקום זיבה לאו מעיין הוא והא למשא רבייה קרא כדאמר בדם הנדה מה לי מעיין ומה לי לאו מעיין ועוד מי איכא לאוקמי להאי קרא בראייה ראשונה והא מהכא נפקא לן בכל דוכתי מנה הכתוב שתים וקראו טמא ועוד מי איכא למימר בראייה ראשונה בזב גרידא לאחרים גורם טומאת משא הא זב בעל ראייה אחת אינו אלא כרואה קרי כדאמר בכמה מקומות שתים לטומאת זיבה ושלש לקרבן ועוד ראייה ראשונה הא אקשיה לעיל לקרי וקרי לא מטמא במשא ומשום שכתוב בספרים מדאיצטריך קרא בראייה ראשונה מפרשי ליה הכי ולאו מילתא היא דהאי בראייה ראשונה פירוש היה בספרים ולקמיה קאי והכי קאמר מדאיצטריך קרא לרבויי לשניה ש\"מ ראשונה מקום זיבה לאו מעיין הוא וה\"ג בשלהי שמעתתא מה זב גמור מטמא זובו במשא אף מצורע כו' אלמא זב גמור הוא דמטמא טיפת זובו במשא אבל זב בעל ראייה אחת לא:"],[5,"מטמא באונס","אותה טומאה קלה האמורה בה מגע וטומאת ערב בקרי ולהצטרף לשניה לטמא כזב גמור והא דכתיב מבשרו ולא מחמת אונסו על כרחך אראייה שניה דכתיב בתרה קאי ולא אראשונה דהא איתקש לשכבת זרע ושכבת זרע כל עצמו מחמת אונס חימום בא:"],[6,"בודקין אותו","בשבעה דרכים במאכל במשתה בקפיצה ובמשאוי כו':"],[6,"מאי לאו לטומאה","דאי באונס הוא הוי טהור לגמרי:"],[6,"לא לקרבן","דאי קמייתא באונס לא מצטרפא לשלש לחייבו קרבן:"],[7,"אילימא לקרבן אבל לטומאה","האמורה בו דהיינו טומאה חמורה לא בעי בדיקה:"],[7,"קרי כאן מבשרו ולא מחמת אונסו","והאי מבשרו בקרא דשתי ראיות כתיב:"],[10,"אתים","והזב את זובו לזכר ולנקבה (ויקרא ט״ו:ל״ג):"],[11,"זב חדא זובו תרתי לזכר","כלומר עד כאן יש לו דין זכר שאינו מטמא באונס מכאן ואילך דהיינו שלישית לנקבה כתיב כלומר יש לו דין נקבה שמטמאה באונס כדילפינן בפירקין (לקמן נדה דף לו:) מכי יזוב זוב ואיהי נמי מייתא ליה לידי קרבן:"],[12,"ברביעית","אז אקשיה רחמנא לנקבה דאפילו באונס. ולא לענין טומאה דהא מכי חזיא תרתי איטמי ליה ולקרבן נמי לא דמשלשה איחייב ליה אלא לסתירה כגון דפסק והתחיל לספור שבעה נקיים וראה ראייה רביעית אפילו באונס סותר:"],[13,"והלא זב בכלל בעל קרי היה","כדמפרש לקמיה ואזיל דאיתקוש לשכבת זרע:"],[13,"ולמה יצא","בפרשת זבין להכתב לעצמו:"],[13,"להקל עליו שלא יטמא באונס","דהא קרי מטמא באונס:"]],[[0,"","לאחרים גורם טומאה. פירש רש\"י לזב עצמו גורם טומאת משא כדכתיב וכל אשר יהיה תחתיו ואוקמינן ליה בעליונו של זב ואין נראה דעליונו של זב אינו קרוי משא ואינו מטמא אלא אוכלין ומשקין ועוד דבזוב כי האי גוונא לא אשכחן אלא כשהטיפה בכף מאזנים וכרעה לכף שניה לכן נראה לפרש לזב עצמו גורם טומאת משא שהנושא הזב טמא הנושא הזוב לא כל שכן דטמא ובשאר טומאות דלאו משא כגון משכב ומושב אין לפרש דהא למצורע נמי גורם טומאה דאילו מצורע גרידא אינו עושה משכב ומושב אלא לטמא אוכלין ומשקין כדפרישית בפרק אלו דברים (פסחים סו.) ואם זב הוא מטמא משכבו אדם ובגדים:"],[2,"","לעולם אימא לך בזב גרידא. תימה דמכל מקום תפשוט דלאו מעיין הוא דאי מעיין הוא למה לי קרא לטמא בזוב דהא מיד שראה משהו של ראייה שניה מיד נעשה זב למ\"ד זוב מטמא במשהו דלא בעי כחתימת פי האמה ומשהו שני לטמא כדין מעיין דאי אפשר לטיפה שלא תתחלק שני משהויין ושמא כמו שמשהו ראשון שבו נעשה זב אינו מטמא במשא הוא הדין כל מה שנקרא ראייה אחת דהיינו כמו גריון לשילה (זבים פ\"א מ\"ה) דלא מטמא במשא אע\"ג דרוקו ומימי רגליו טמאין מיד אחר ראיית זוב משהו ראשון:"],[4,"","אף ראייה ראשונה של מצורע מטמאה במשא. תימה אם כן לעיל מנליה לאוקומי קרא בדם טהרה של מצורעת הא איצטריך קרא לכדהכא:"],[6,"","מאי לאו לטומאה. וא\"ת מאי קושיא דילמא הא דאמר רב הונא מטמא באונס היינו טומאת ערב כבעל קרי והכא מיירי להצטרף לשניה לטמא טומאה חמורה לעשותו זב והוי השתא שפיר רישא דומיא דסיפא וי\"ל מדלא נקט הרואה ראייה אחת של זיבה אלא נקט ראייה ראשונה של זב משמע דאיירי באותו שראה שתי ראיות והראשונה היתה באונס דזב אינו קרוי עד שיראה שתי ראיות ויליף מהיקשא דזאת תורת דאיירי בזב גמור ומקיש ראשונה של השתים לשכבת זרע:"],[9,"","מכלל דתנא קמא לטומאה. לאו מן הלשון מדקדק מדאצטריך ר' אליעזר להזכיר קרבן מכלל דת\"ק איירי לטומאה דא\"כ לא הוה משני מידי אלא הכי דייק מכלל דתנא קמא לא מצריך בדיקה משום קרבן אלא משום טומאה דאי משום קרבן הוה ליה לאצרוכי נמי בדיקה בשלישי כרבי אליעזר וקשה דהא בלאו מילתיה דרבי אליעזר הוה מצי למפרך מדקתני במס' זבים (פרק ב' מ\"ב) בהדיא במילתיה דרבנן גופייהו בשלישי אין בודקין אותו ושמא מייתי מרבי אליעזר משום דבעי לפרושי במאי פליגי:"]]],[["שהוא עושה משכב ומושב","אימת אילימא בראייה שניה היכא הוה בכלל בעל קרי אלא פשיטא בראייה ראשונה וקתני להקל עליו שאינו מטמא באונס","ותסברא להחמיר עליו שהוא עושה משכב ומושב בראייה ראשונה בר משכב ומושב הוא","אלא הכי קאמר רבי יצחק אומר והלא זב בכלל בעל קרי היה בראייה ראשונה ולמה יצא בראייה שנייה להקל עליו ולהחמיר עליו להקל עליו שאינו מטמא באונס ולהחמיר עליו שהוא עושה משכב ומושב","אמר רב הונא זוב דומה למי בצק של שעורים זוב בא מבשר המת שכבת זרע בא מבשר החי זוב דיהה ודומה ללובן ביצה המוזרת שכבת זרע קשורה ודומה ללובן ביצה שאינה מוזרת","דם היולדת שלא טבלה וכו'","תניא אמרו להן בית הלל לבית שמאי אי אתם מודים בנדה שלא טבלה וראתה דם שהיא טמאה אמרו להם בית שמאי לא אם אמרתם בנדה שאפילו טבלה וראתה טמאה תאמרו ביולדת שאם טבלה וראתה שהיא טהורה","אמרו להם יולדת בזוב תוכיח שאם טבלה וראתה לאחר ימי ספירה טהורה לא טבלה וראתה טמאה","אמרו להם הוא הדין והיא התשובה","למימרא דפליגי והתנן ומודים ביולדת בזוב שהיא מטמאה לח ויבש","לא קשיא כאן שספרה כאן שלא ספרה","והתניא יולדת בזוב שספרה ולא טבלה וראתה הלכו בית שמאי לשיטתן וב\"ה לשיטתן","איתמר רב אמר מעין אחד הוא התורה טמאתו והתורה טהרתו","ולוי אמר שני מעינות הם נסתם הטמא נפתח הטהור נסתם הטהור נפתח הטמא","מאי בינייהו איכא בינייהו שופעת מתוך שבעה לאחר שבעה ומתוך ארבעה עשר לאחר ארבעה עשר ומתוך ארבעים לאחר ארבעים ומתוך שמנים לאחר שמנים","לרב רישא לקולא וסיפא לחומרא","ללוי רישא לחומרא וסיפא לקולא","מיתיבי דם היולדת שלא טבלה בית שמאי אומרים כרוקה וכמימי רגליה וב\"ה אומרים מטמא לח ויבש","קא ס\"ד דפסקה בשלמא לרב דאמר מעין אחד הוא משום הכי מטמא לח ויבש אלא ללוי דאמר שני מעינות הן אמאי מטמא לח ויבש","אמר לך לוי הכא במאי עסקינן בשופעת אי בשופעת מ\"ט דב\"ש קסברי ב\"ש מעין אחד הוא","בשלמא ללוי היינו דאיכא בין ב\"ש וב\"ה אלא לרב מאי בינייהו","איכא בינייהו יומי וטבילה דבית שמאי סברי ביומי תלה רחמנא וב\"ה סברי ביומי וטבילה","ת\"ש ומודים ביולדת בזוב שהיא מטמאה לח ויבש ס\"ד הכא נמי דפסקה","בשלמא לרב דאמר מעין אחד הוא משום הכי מטמא לח ויבש אלא ללוי דאמר שני מעינות הן אמאי מטמא לח ויבש","אמר לך הכא נמי בשופעת אי בשופעת למאי איצטריך","לב\"ש איצטריך אף על גב דקאמרי בית שמאי מעין אחד הוא וביומי תלה רחמנא הני מילי ביולדת גרידתא דשלימו להו יומי אבל יולדת בזוב דבעי ספירה לא","תא שמע (ויקרא יב, ב) דותה תטמא לרבות את בועלה","דותה תטמא לרבות הלילות דותה תטמא לרבות היולדת בזוב שצריכה שתשב שבעה ימים נקיים בשלמא לרב דאמר מעין אחד הוא משום הכי בעיא שבעה ימים נקיים"],[[0,"שהוא עושה משכב ומושב","אב הטומאה מה שאין כן בקרי:"],[1,"אלא פשיטא בראייה ראשונה","דהוי בכלל קרי כדאקשינן לעיל הזב ואשר תצא ממנו וכו':"],[4,"דיהה","כלומר מתמקמק ונפרד ואינו קשור:"],[4,"מוזרת","שאינה משרצת אפרוח תחת תרנגולת:"],[7,"יולדת בזוב תוכיח שאם טבלה","לאחר שמנתה ז' נקיים לבד ימי טומאת לידה:"],[7,"וראתה טהורה היא","דדם טהור הוא וכי לא טבלה וראתה טמא:"],[8,"אמרו להם בית שמאי הוא הדין כו'","כלומר כי היכי דאמרינן ביולדת גמורה גרידא שלא טבלה וראתה טהורה כך יולדת בזוב שעברו עליה ימי לידה ושבעה נקיים ולא טבלה וראתה טהורה:"],[10,"כאן שספרה","בראיותה בספרה ז' נקיים. מתניתין דמודו בית שמאי כשעברו ימי לידה ועדיין לא ספרה אחריהם שבעה נקיים והכי קאמר אף על גב דאמרי בית שמאי ביולדת גרידתא כרוקה וכמימי רגליה מודים ביולדת בזוב שלא ספרה דכל זמן שלא ספרה זבה היא ואם ראתה לא הוי כרוקה וכמימי רגליה דאילו רוק מטמא לח ולא יבש כדאמר בדם הנדה (לקמן נדה נו.) וכי ירוק כעין רקיקה דהיינו לח אבל דמה מטמא לח ויבש כשאר דם הנדה כדילפינן בדם הנדה (שם דף נד:):"],[11,"והתניא","בניחותא:"],[11,"בית שמאי לשיטתן","כי היכי דמטהרי ביולדת גרידתא מטהרי בהך דקסברי ביומי תלה רחמנא והא מלו לה כל ימים שלה:"],[11,"ובית הלל לשיטתן","דקסברי ביומי וטבילה תלה רחמנא וכיון דלא טבלה הוי דמה טמא כטומאת לידה דהוי אב הטומאה:"],[12,"מעין אחד הוא","דם הבא בימי לידה ודם הבא בימי טוהר ממעין אחד הן באין:"],[12,"התורה טמאתו","כל שבעה לזכר וי\"ד לנקבה:"],[12,"והתורה טהרתו","אחר מכן:"],[13,"נסתם הטמא","לאחר שבועים ונפתח הטהור:"],[13,"נסתם הטהור","לאחר שמנים ונפתח הטמא:"],[15,"לרב רישא","דשופעת מתוך ימי טומאה לימי טהרה לקולא וטהורה ואף על גב דלא פסק דהא התורה טהרתו:"],[15,"וסיפא","דשפעה מתוך מ' לאחר מ' ומתוך פ' לאחר שמנים לחומרא וטמאה לאחר שמנים דהתורה טמאתו:"],[16,"ללוי רישא לחומרא","כיון דלא פסקה לא נסתם מעין טמא:"],[16,"וסיפא לקולא","דכיון דלא פסקה לא נסתם מעין טהור:"],[18,"קס\"ד דפסקה","יום או שנים לאחר שבועים ומשום הכי מטמא לח ויבש דממעין טמא בא והתורה לא טהרתו לב\"ה אלא ביומי וטבילה:"],[18,"אלא ללוי","הא ממעין טהור אתא דכי פסקה נסתם הטמא:"],[19,"בשופעת","מתוך ימי טומאה לימי טהרה ולא פסקה:"],[20,"בשלמא ללוי","דאמר לב\"ה ב' מעינות הן:"],[20,"היינו דאיכא בין בית שמאי ובית הלל","דלבית הלל שני מעינות הן וכיון דלא פסק טמאה דלא נסתם הטמא ולבית שמאי מעין אחד הוא והתורה טהרתו אחר שבועים:"],[20,"אלא לרב","דאמר מעין אחד הוא אי בית הלל קיימי כוותיה:"],[20,"מאי איכא כו'","כלומר במאי קמיפלגי ומאי טעמא דבית הלל דמטמאין:"],[21,"ביומי וטבילה","לא שנא שופעת לא שנא פוסקת כל זמן שלא טבלה הוי דמה טמא בימי לידתה:"],[22,"ומודים ביולדת בזוב שמטמאה","ואוקימנא כשעברו ימי לידתה ולא ספרה אחריהן ז' נקיים וקס\"ד הכא נמי דפסקה אחר שבועים ומשום הכי מטמא דממעיין טמא אתו והתורה לא טהרתו עד שתשב ז' נקיים כדין זבה:"],[23,"אמאי מטמאה","דהא ממקום טהור הוא בא והרי הוא כדם מגפתה וכרוקה שמטמא לח משום מעין הזב ולא יבש:"],[25,"לב\"ש אצטריך","דקאמר מעין אחד הוא ומטהרי לה ביולדת גרידתא אחר ימי לידתה מיד דביומי תלא רחמנא אצטריך ביולדת בזוב לאשמועינן דמטמאה:"],[25,"דהני מילי","דהוי דם טוהר לאחר ימי לידה ביולדת גרידתא אבל ביולדת בזוב דבעיא ספורים כל זמן שלא ספרה הוי דמה כדם זיבה דהא מחד מעין אתי ותורה לא טהרתו עד שתספור כדכתיב ואחר תטהר אחר אחר לכולן:"],[26,"דותה תטמא","קרא יתירא הוא דה\"ל למכתב וטמאה ז' ימים כימי נדה ולשתוק:"],[27,"לרבות שמטמאה את בועלה כנדה ולרבות את הלילות כימים","דלא תימא ימים כתיב:"],[27,"משום הכי בעיא","הפסקה שבעה נקיים דממעין דמים טמאים אתי והתורה לא טהרתו עד שתספור שבעה נקיים כדכתיב דותה תטמא:"]],[[6,"","אי אתם מודים בנדה. תימה מאי קסברי בית הלל דקמייתי מנדה דפשיטא כדמהדר להו בית שמאי וי\"ל דמייתי משום דאיתקש לידה לנדה דכתיב כימי נדת דותה וכתיב וטמאה שבועים כנדתה:"],[14,"","איכא בינייהו שופעת מתוך שבעה כו'. איכא בינייהו טובא כל הני דפריך בסמוך אלא דפשוט יותר נקט:"],[19,"","בשופעת. והשתא אפי' בטבלה יטמאו בית הלל לח ויבש ומתניתין דנקט ולא טבלה משום בית שמאי וא\"ת דבעדיות קתני הך דיולדת גבי קולי בית שמאי וחומרי בית הלל הלא בשופעת מתוך מ' (למה) הוו בית הלל לקולא וי\"ל דכי אתשיל בתחלת לידה אתשיל:"],[24,"","אי בשופעת למאי איצטריך. וא\"ת מכל מקום משום בית שמאי איצטריך כדמשני ומאי סלקא דעתיה דמקשה דהא לרב נמי לא אצטריך סיפא אלא לאשמועינן דמודו בית שמאי דמטמא לח ויבש משום דלא ספרה ויש לומר דלרב איצטריך לאשמועינן דמודו בית שמאי ביולדת בזוב משום דמעיין אחד הוא דאי מרישא הוה אמינא דטעמייהו משום דקסברי ב' מעיינות הן ואפילו ביולדת בזוב מטהרין ובית הלל סברי דמעיין אחד הוא לכך אצטריך סיפא אלא ללוי דמוקי רישא בשופעת וסברי ב\"ש מעיין אחד הוא סיפא מאי קא משמע לן:"]]],[["אלא ללוי דאמר שני מעינות הן למה לי שבעה במשהו סגיא","הכי קאמר צריכה שתפסוק משהו שיעלו לה לשבעה נקיים","ת\"ש ימי עיבורה עולים לה לימי מניקותה וימי מניקותה עולים לה לימי עיבורה","כיצד הפסיקה שתים בימי עיבורה ואחת בימי מניקותה שתים בימי מניקותה ואחת בימי עיבורה אחת ומחצה בימי עיבורה ואחת ומחצה בימי מניקותה עולין לה לג' עונות","בשלמא לרב דאמר מעין אחד הוא משום הכי בעי הפסק שלש עונות אלא ללוי דאמר שני מעינות הן למה לי הפסק שלש עונות במשהו סגי","הכי קאמר צריכה שתפסוק משהו כדי שיעלו לה לשלש עונות","ת\"ש ושוין ברואה אחר דם טוהר שדיה שעתה","בשלמא ללוי דאמר שני מעינות הן משום הכי דיה שעתה אלא לרב דאמר מעין אחד הוא אמאי דיה שעתה תטמא מעת לעת","דליכא שהות","ותטמא מפקידה לפקידה כיון דמעת לעת ליכא מפקידה לפקידה נמי לא גזרו בה רבנן","תא שמע יולדת בזוב שספרה ולא טבלה וראתה הלכו ב\"ש לשיטתן ובית הלל לשיטתן","בשלמא לרב דאמר מעין אחד הוא משום הכי מטמא לח ויבש אלא ללוי דאמר שני מעינות הן אמאי מטמא לח ויבש","אמר לך לוי אנא דאמרי כתנא דשוין","ואיבעית אימא בשופעת והא ספרה קתני","הכא ביולדת נקבה בזוב עסקינן דשבוע קמא פסקה שבוע בתרא לא פסקה וקסבר ימי לידתה שאין רואה בהן עולין לה לספירת זיבתה","אמר ליה רבינא לרב אשי אמר לן רב שמן מסכרא אקלע מר זוטרא לאתרין ודרש הילכתא כוותיה דרב לחומרא והלכתא כוותיה דלוי לחומרא","רב אשי אמר הלכתא כוותיה דרב בין לקולא בין לחומרא דריש מרימר הלכתא כוותיה דרב בין לקולא בין לחומרא והלכתא כוותיה דרב בין לקולא בין לחומרא"],[[0,"אלא ללוי במשהו סגי","ותפסוק משהו לאחר שבועים דנסתם הטמא ותמתין שבעה ותטבול ואפי' תראה כל שבעה יעלו לה בנקיים דהא לאו דם טמא הוא:"],[1,"שתפסוק משהו","לאחר שבועים דנקבה דאי בתוך שבועים לאו הפסק היא דכיון דחוזרת ורואה בתוך שבועים חזר הטמא להפתח:"],[2,"ימי עיבורה עולין לה","בפ\"ק (לעיל נדה דף י:) אמרי' מעוברת ומניקה שעברו עליה ג' עונות וראתה דיה שעתה:"],[3,"עולין לה","כלומר מצטרפים לימי מניקותה כגון היתה מניקה והתחילה לפסוק ונתעברה והשלימה ג' עונות מצטרפין ימי עיבורה לימי מניקותה:"],[4,"בשלמא לרב דאמר מעין אחד הוא משום הכי","מעוברת שהתחילה להפסיק וילדה צריכה להשלים ג' עונות שלא תראה אחר לידה כלום ודם לידה לא מפסיק לשלש עונות כדתרצינן בפ\"ק דם נדה לחוד ודם לידה לחוד אבל אחר לידה אי חזאי לא השלימה ג' עונות ומטמאה מעת לעת שאין דמיה מסולקין:"],[4,"אלא ללוי","אפי' אי חזיא לאחר שבועים הא לאו ממעין טמא אתי ויעלו לה להשלמת שלש עונות דהוי כאילו דם מחוטמה אתא:"],[4,"במשהו סגיא","שתפסוק אחר ימי לידה משהו דנימא נסתם הטמא:"],[5,"שיעלו לה","ימי טהרה:"],[5,"לשלש עונות","ואפי' תראה:"],[6,"ושוין","שמאי והלל דפליגי במעת לעת:"],[6,"ברואה אחר דם טוהר שדיה שעתה","קס\"ד אפי' לזמן מרובה כגון שלא ראתה עד יום שמונים וארבע או תשעים:"],[7,"בשלמא ללוי דאמר שני מעינות הן משום הכי דיה שעתה","שהרי דמיה מסולקין שכמה ימים שעברו ולא ראתה דם ממעין זה והויא לה ראייה ראשונה ודיה שעתה ומניקה מארבע נשים היא דדיין שעתן בראייה ראשונה:"],[7,"אלא לרב דאמר מעין אחד הוא","לאו ראייה ראשונה היא והרי הוחזקה בדמים:"],[8,"דליכא שהות","כגון שראתה ביום שמונים ואחד מיד דליכא למימר מעת לעת דאפי' הוה מאתמול כי האידנא בבית החיצון דם טהור הוא:"],[9,"ותטמא מפקידה לפקידה","כגון אם בדקה שחרית ומצאתה טמאה תטמא טהרות של ערבית והכא ליכא למימר דליכא שהות דאי אפילו מפקידה לפקידה ליכא צריכא למימר דדיה שעתה:"],[10,"וב\"ה לשיטתן","דכל זמן שלא טבלה מטמא לח ויבש והא כיון דספרה אחר ימי לידה ודאי פסק וקשיא ללוי:"],[12,"כתנא דשוין","דאמר לעיל ושוין ברואה אחר דם טוהר שדיה שעתה ואנא אוקימנא בדאיכא שהות ואפ\"ה דיה שעתה אלמא שני מעינות הן:"],[13,"והא ספרה קתני","ואי לא פסק היכי ספרה. ומשני לעולם בשופעת מימי טומאה לימי טוהר וספירה הכי הואי כגון שהיתה יולדת נקבה בזוב וימי טומאת לידה שני שבועים ופסקה שבוע קמא וזו היא ספירתה דקסבר ימי לידתה שאינה רואה בהן עולין לה לספירת זיבתה ושבוע שני לא פסקה וחזר ונפתח מעין טמא ושופעת מתוכו בתוך שבוע שלישי ומש\"ה מטמא לח ויבש לב\"ה דהא ממעין טמא אתא ותורה לא טהרתו אלא ביומי וטבילה ולב\"ש טהור דביומי תליא רחמנא והא שלמו להו ולהכי נקט יולדת נקבה דאי ילדה זכר אי אפשר לה לספור שבעה שלא תפסוק משהו אחר ימי לידה דלא הוו אלא שבעה:"],[15,"כוותיה דרב לחומרא","בשופעת מתוך שמונים לאחר שמונים דמטמאה ולא אמרי' ממעין טהור אתא:"],[15,"והלכתא כוותיה דלוי לחומרא","בשופעת מתוך י\"ד לאחר י\"ד דאמר ב' מעיינות הן וכיון דלא נסתם הטמא לא הוי דם טוהר:"],[16,"בין לקולא","כגון שופעת מתוך י\"ד לאחר י\"ד דהוה ליה רב לקולא דאמר מעין אחד הוא והתורה טהרתו ולא בעי הפסקה:"]],[[6,"","ושוין ברואה אחר דם טוהר שדיה שעתה. וא\"ת לרבי יוסי דאמר בפ\"ק (לעיל נדה דף ז.) מעוברת ומניקה צריכות שלש עונות ומפרש דמצטרפי ב' עונות דעיבורה ואחת דמניקתה למה לי עונה דמניקתה הא אמר הכא דאחר דם טוהר דיה שעתה וי\"ל הא דלא כר' יוסי אי נמי בהפסיקה ג' עונות וראתה ראשונה מאונס אף שניה דיה שעתה כדאמר בפ\"ק (שם:) אבל אחר דם טוהר אין דיה שעתה אלא בראייה ראשונה אבל שניה לא אפי' היתה הראשונה מאונס כיון שנפתח מעין טמא וא\"ת לר\"מ ולאידך תנאי דאית להו בפ\"ק (שם:) מניקה דיה שעתה תיפוק ליה דהוה אחר דם טוהר ומיהו לתירוץ שני אתי שפיר וי\"ל דמטעם שהוא אחר דם טוהר אין דיה שעתה אלא לראייה ראשונה אבל מטעם מניקה דיה שעתה כל ימי מניקותה כר\"מ דפ\"ק (שם דף יא.) וא\"ת והכא למה לי משום דם טוהר תיפוק ליה דמניקה היא וי\"ל דנ\"מ להיכא דמת בנה או גמלתו לרבי מאיר דאמר לעיל הרי היא ככל הנשים ולרבי יוסי נמי דאמר בפ\"ק אפי' גמלתו או נתנה בנה למניקה דיה שעתה נפקא מינה לאחר דם טוהר להיכא דלא ראתה עד לאחר כ\"ד חדש וטעמא דמניקה איצטריך לראייתה הראשונה באונס דאף השניה דיה שעתה כדפרישית:"],[8,"","דליכא שהות. אבל איכא שהות מטמאה מעת לעת לרב דאמר מעין אחד הוא ואע\"ג דדיה שעתה כל ימי מניקותה הכא מיירי במת בנה או בהפילה כדפרישית וא\"ת דבפרק אלו נערות (כתובות דף לז.) אמר הגיורת שראתה דם בתוך מעת לעת דיה שעתה רבי יוסי אומר הרי היא ככל הנשים וי\"ל סוגיא דהכא לא אתיא כר' יוסי דהתם א\"נ התם היתה בת טומאה אם היתה מתגיירת מקודם או משום דאיתא בגוה טומאה דרבנן:"],[13,"","ואיבעית אימא בשופעת והא ספרה קתני. וא\"ת מאי קאמר ב\"ה לעיל יולדת בזוב תוכיח שאם טבלה וראתה טהורה והא כיון דשופעת אפי' טבלה טמאה ללוי דאמר שני מעיינות הן דהא מעין טמא הוא וי\"ל דלדברי ב\"ש קאמרי להו דאית להו מעין אחד הוא:"],[14,"","שבוע בתרא לא פסקה. מכאן אומר ר\"ת דיולדת בזוב או בזמן הזה דכולהו נשים חשבינהו כיולדת בזוב שסופרין אחר ימי טומאת הלידה שבעה נקיים וראתה בימי טוהר קודם טבילה אינה סותרת דהא אמר הכא דכי ראתה שבוע שלישי דלא סתרה אע\"ג דדם טמא הוא כ\"ש דראיית דם טוהר אינה סותרת דאפי' ב\"ה דמטמאין לח ויבש מודו דעלתה לה ספירתה ומכאן אין להוכיח על זבה שאינה יולדת שספרה ז' נקיים וראתה שלא תסתור דאיכא למימר דהכא דוקא לא סתרה משום דראייה זו אינה גורמת לה טומאה דכל שבועים טמאים בלאו הכי ואע\"ג דבשבוע ג' גורם לה טומאה מ\"מ אינה נעשית בת נדה ולא זבה וכשתפסק טהורה מיד ומ\"מ נראה דאשה דעלמא נמי לא סתרה דמסתברא דאין סתירה מועלת אלא בתוך החשבון כדאמר ואחר תטהר שלא תהא טומאה מפסקת ביניהם אבל לאחר ספירה לא מיהו לדידן דאית לן חומרא דרבי זירא פשיטא דסותרת דהא אפי' טבלה וראתה צריכה ז' נקיים:"],[15,"","הלכתא כרב לחומרא. ואם תאמר הא תרי חומרי דסתרי אהדדי נינהו וי\"ל דהכא דמספקא לן פסיק כמר להחמיר וכמר להחמיר וכי האי גוונא איכא שלהי יוצא דופן (לקמן נדה דף מז:) הלכה כדברי כולן להחמיר גבי סימני בגרות וחצר צורית הקשה הרב רבי מרדכי בר יצחק ללוי דאמר שני מעינות הן הא דתניא בפרק יש בכור (בכורות דף מו:) גיורת שיצא פדחת ולדה בהיותה עובדת כוכבים ואחר כך נתגיירה אין נותנין לה ימי טומאה וימי טהרה ואי שני מעינות הן אמאי אין נותנין לה ימי טהרה הלא מעין טמא סתום ובריש יוצא דופן (לקמן נדה דף מ.) נמי תנן דאין יושבין עליו ימי טומאה וימי טהרה ומההיא ברייתא דבכורות (דף מו:) לא קשה כל כך ללוי דמוקי כב\"ש דאמר מעין אחד הוא א\"נ כדמשני הכא אנא דאמר כתנא דשוין אבל סתם מתניתין דיוצא דופן קשה וי\"ל דאין נותנין לה ימי טוהר איכא לאוקמי לענין שאם ראתה ביום ז' לזכר או ביום י\"ד לנקבה דהויא תחלת נדה דאין טומאת לידה עליה אי נמי אע\"ג דשני מעינות הן יש לטמא הדם דמן המקור קאתי אלא דוקא במקום שהתורה מטהרתו:"]]],[["\u0001מתני׳\u0002 המקשה נדה קשתה שלשה ימים בתוך י\"א יום ושפתה מעת לעת וילדה הרי זו יולדת בזוב דברי רבי אליעזר","רבי יהושע אומר לילה ויום כלילי שבת ויומו ששפתה מן הצער ולא מן הדם","כמה היא קישויה ר' מאיר אומר אפילו ארבעים וחמשים יום רבי יהודה אומר דיה חדשה ר' יוסי ור' שמעון אומרים אין קישוי יותר משתי שבתות","\u0001גמ׳\u0002 אטו כל המקשה נדה היא","אמר רב נדה ליומא ושמואל אמר חיישינן שמא תשפה","ור' יצחק אמר המקשה אינה כלום והקתני המקשה נדה","אמר רבא בימי נדה נדה בימי זיבה טהורה והתניא המקשה בימי נדה נדה בימי זיבה טהורה","כיצד קשתה יום אחד ושפתה שנים או שקשתה שנים ושפתה יום אחד או ששפתה וקשתה וחזרה ושפתה הרי זו יולדת בזוב","אבל שפתה יום אחד וקשתה שנים או ששפתה שנים וקשתה יום אחד או שקשתה ושפתה וחזרה וקשתה אין זו יולדת בזוב כללו של דבר קושי סמוך ללידה אין זו יולדת בזוב שופי סמוך ללידה הרי זו יולדת בזוב","חנניא בן אחי ר' יהושע אומר כל שחל קישויה בשלישי שלה אפילו כל היום כולו בשופי אין זו יולדת בזוב","כללו של דבר לאתויי מאי לאתויי דחנניא","מה\"מ דת\"ר דמה דמה מחמת עצמה ולא מחמת ולד","אתה אומר מחמת ולד או אינו אלא מחמת אונס כשהוא אומר (ויקרא טו, כה) ואשה כי יזוב זוב דמה הרי אונס אמור הא מה אני מקיים דמה דמה מחמת עצמה ולא מחמת ולד","ומה ראית לטהר את הולד ולטמא באונס מטהר אני בולד שיש טהרה אחריו ומטמא אני באונס שאין טהרה אחריו","אדרבה מטהר אני באונס שכן אונס בזב טהור השתא מיהא באשה קיימינן ואונס באשה לא אשכחן","ואיבעית אימא מאי דעתיך לטהורי באונס ולטמויי בולד אין לך אונס גדול מזה","אי הכי נדה נמי נימא זובה זובה מחמת עצמה ולא מחמת ולד","אתה אומר ולד או אינו אלא אונס כשהוא אומר (ויקרא טו, יט) ואשה כי תהיה זבה הרי אונס אמור הא מה אני מקיים זובה זובה מחמת עצמה ולא מחמת ולד","אמר ר\"ל אמר קרא תשב יש לך ישיבה אחרת שהיא כזו ואיזו זו זו קושי בימי זיבה ואימא זו קושי בימי נדה","אלא אמר אבוה דשמואל אמר קרא (ויקרא יב, ה) וטמאה שבועים כנדתה ולא כזיבתה מכלל דזיבתה טהור ואיזו זו זו קושי בימי זיבה","והשתא דכתיב וטמאה שבועים כנדתה דמה למה לי אי לאו דמה הוה אמינא כנדתה ולא כזיבתה ואפילו בשופי קמ\"ל","שילא בר אבינא עבד עובדא כוותיה דרב כי קא נח נפשיה דרב א\"ל לרב אסי זיל צנעיה ואי לא ציית גרייה הוא סבר גדייה א\"ל","בתר דנח נפשיה דרב א\"ל הדר בך דהדר ביה רב א\"ל אם איתא דהדר ביה לדידי הוה אמר לי לא ציית גדייה א\"ל ולא מסתפי מר מדליקתא","א\"ל אנא איסי בן יהודה דהוא איסי בן גור אריה דהוא איסי בן גמליאל דהוא איסי בן מהללאל אסיתא דנחשא דלא שליט ביה רקבא א\"ל ואנא שילא בר אבינא בוכנא דפרזלא דמתבר אסיתא דנחשא","חלש רב אסי עיילוה בחמימי אפקוה מקרירי עיילוה בקרירי אפקוה מחמימי נח נפשיה דרב אסי"],[[0,"מתני' המקשה","וראתה דם הרי זו נדה. ובגמרא פריך ומתרץ לה:"],[0,"קשתה","מחמת ולד:"],[0,"ג' ימים בתוך אחד עשר יום","שבין נדה לנדה וראתה כל שלשתן הימים רצופין:"],[0,"ושפתה","מצערה:"],[0,"מעת לעת","ברביעי:"],[0,"וילדה","איגלאי מילתא דדמים שראתה לא באו מחמת ולד הלכך הרי זו יולדת בזוב אבל אם לא שפתה סמוך ללידתה כל דמים שראתה מחמת ולד הוא ורחמנא טהרינהו מזיבה דכתיב זוב דמה דמה מחמת עצמה ולא דמה מחמת ולד:"],[1,"לילה ויום","דאם שפתה בחצי יום שלישי וילדה יום רביעי דשפתה מעת לעת אין זו שופי אלא אם כן שפתה לילה ויום שלאחר הלילה כלילי שבת ויומו:"],[1,"ששפתה מן הצער ולא מן הדם","דאע\"ג דחזיא דם הוי שופי:"],[2,"כמה הוא קישויה","דלא אתיא לידי זיבה בכל דמים שתראה:"],[2,"אפילו ארבעים או חמשים יום","אם לא שפתה יום אחד סמוך ללידה לא אתיא לידי זיבה ולא הויא יולדת בזוב:"],[2,"דיה חדשה","דיה אם נטהר את הקושי חדש אחד היינו תשיעי אבל קשתה שלשה בתוך י\"א ימי זיבה בחדש השמיני ואפי' מקשה והולכת כל תשיעי הרי זו יולדת בזוב מחמת שלשה ימים של שמיני:"],[3,"גמ' אטו כל המקשה נדה היא","אילו קשתה בימי זיבה מי הויא נדה והא אין נדות בימי זוב:"],[4,"אמר רב נדה ליומא","וה\"ק המקשה ורואה דם בימי זיבה אע\"ג דלא אתיא ביה לידי זיבה מיהו באותו היום אסורה לשמש אבל לערב טובלת ואינה צריכה לשמור יום כנגד יום דרחמנא טהריה לדם קושי:"],[4,"ושמואל אמר","אף צריכה לשמור יום כנגד יום מדרבנן דחיישינן שמא תשפה ונמצא שלא היה דם קושי מחמת ולד ונמצא משמש עם זבה קטנה דאורייתא וענוש כרת:"],[5,"אינה כלום","ואפילו באותו היום משמשת:"],[6,"בימי נדה","בימים הראוים לנדות:"],[6,"נדה","דקושי לא טהריה רחמנא אלא מזיבה אבל מנדה לא טהריה כדאמרי' לקמן:"],[6,"בימי זיבה","בתוך אחד עשר יום טהורה:"],[6,"והתניא","בניחותא:"],[7,"ושפתה","שנים מן הצער ולא מן הדם:"],[7,"הרי זו יולדת בזוב","אם ראתה כל שלש הואיל ושופי סמוך ללידה נמצא דם הקושי שלא מחמת ולד:"],[9,"כל שחל קישויה","לאו לשון התחלה הוא אלא הכי קאמר כל שקשתה בשלישי אפי' שעה אחת בליל כניסת שלישי אפילו כל היום כולו בשופי ושפתה מליל ד' שעה אחת להשלמת מעת לעת אין זו יולדת בזוב דבעינן שופי כל יום ג' המביאה לידי זבה:"],[12,"וכי יזוב זוב","זוב משמע זוב מ\"מ ואפי' באונס:"],[13,"שיש טהרה אחריו","דם טוהר:"],[14,"ואונס באשה לא אשכחן","דטהור:"],[16,"זובה","דם יהיה זובה ובנדה משתעי דפרשה ראשונה נאמרה בנדה ושניה בזבה כדכתיב בשניה בלא עת נדתה:"],[16,"ולא מחמת ולד","אלמה אמרינן לעיל בימי נדה נדה:"],[18,"תשב על דמי טהרה","דהוה ליה למכתב וששים יום וששת ימים דמי טהרה:"],[18,"שהיא כזו","שדמיה טהורים:"],[18,"ואיזו זו","כלומר היכא משכחת זיבה טהורה:"],[18,"זו קושי בימי זיבה","דסמיך אדכתיב דמה מחמת עצמה ולא מחמת ולד:"],[20,"ואפי' בשופי","ואפי' הפסיק שופי בין קושי ללידה נימא טהורה הואיל ודם בקושי בא:"],[21,"כוותיה דרב","נדה ליומא:"],[21,"צנעיה","הסתר אותו דבר אמור לו שיחזור בו דטהור לגמרי:"],[21,"גרייה","ברי\"ש. כלומר גרור ומשוך אותו בדברי טעם וראיות שיחזור בו:"],[21,"גדייה","הכריתו בשמתא כמו (דניאל ד) גודו אילנא:"],[22,"לדידי הוה אמר לי","דתלמידיה אנא:"],[22,"גדייה","שמתיה:"],[22,"מדליקתא","שמא תכוה בגחלתי:"],[23,"אסיתא","משום דשמיה הכי דריש לשמיה הכי:"],[24,"עיילוה בחמימי","חולי חם:"],[24,"קרירי","חולי צונן:"]],[[1,"","כלילי שבת ויומו. קים ליה לרבי יהושע דאם לא שפתה לילה ויום אע\"פ ששפתה מעת לעת מחמת ולד היה:"],[4,"","נדה ליומא. נראה דאף לבעלה לא חיישינן שמא תשפה דאזלינן בתר רוב נשים מקשות דאינן שפות לילה ויום דהא עובדא דשילא בר אבינא נראה דלבעלה הוי ולא לטהרות:"],[7,"","או ששפתה וקשתה וחזרה ושפתה. כדי נסבה דהא מרישא שמעינן לה דקתני קשתה שנים ושפתה יום אחד וכ\"ש הא דטמאה וכן בסיפא לא היה צריך למתני קשתה ושפתה וקשתה כיון דתנא שפתה שנים וקשתה יום אחד דטהורה אי נמי אתא לאשמועינן אע\"ג דלא קשתה כל יום הסמוך ללידה אלא מקצתו וכן ברישא בכי האי גוונא:"],[18,"","ואימא קושי בימי נדה. ור\"ל ס\"ד דמסתבר טפי לאוקומיה בזיבה משום דאשכחן זב אונס דטהור הוא:"],[21,"","גדייה. פרש\"י דרב אסי טעה בין רי\"ש לדלי\"ת ואין נראה אלא נראה דאיהו אמר ליה גדייה בדלי\"ת רפה כלומר משכהו בדברי טעם עד שיחזור כמו (שמות יב) משכו דמתרגמינן נגודו וכמו (ב\"ב דף יג.) גוד או איגוד והוא סבר גדייה בדגש כמו גודו אילנא:"],[23,"","איסי בן מהללאל. בערבי פסחים (פסחים דף קיג:) יש תנא דיש לו כל השמות הללו ועוד קרי ליה התם הוא יוסף הבבלי הוא יוסף איש הוצל ולא תנא אחר הוא כמו שיש מפרשין שם דהא בפרק הוציאו לו (יומא דף נב:) פריך מאיסי בן יהודה ליוסף איש הוצל והכא לא מייתי אלא שמות דאיסי דדמי לרב אסי:"]]],[["אזל שילא אמר לדביתהו צבית לי זוודתא דלא ליזיל ולימא ליה לרב מילי עילואי צביתה ליה זוודתא נח נפשיה דשילא חזו דפרחא אסא מהאי פוריא להאי פוריא אמרי ש\"מ עבדו רבנן פייסא","בעי רבא קושי מהו שתסתור בזיבה","דבר המטמא סותר והאי נמי מטמא כימי נדה הוא או דילמא דבר הגורם סותר והאי לאו גורם הוא","א\"ל אביי אונס בזיבה יוכיח שאינו גורם וסותר","אמר ליה לאיי האי נמי גורם הוא דתנן ראה ראייה ראשונה בודקין אותו שניה בודקין אותו שלישית אין בודקין אותו","ולרבי אליעזר דאמר אף בשלישי' בודקין אותו ה\"נ כיון דלא גרים לא סתר אמר ליה לרבי אליעזר ה\"נ","ת\"ש רבי אליעזר אומר אף בשלישית בודקין אותו ברביעית אין בודקין אותו מאי לאו לסתירה","לא לטמויה לההיא טיפה במשא","ת\"ש בשלישית רבי אליעזר אומר בודקין אותו ברביעית אין בודקין אותו לקרבן אמרתי ולא לסתירה","אלא לר\"א תפשוט דדבר שאינו גורם סותר לרבנן מאי","ת\"ש דתני אבוה דרבי אבין מה גרם לו זובו שבעה לפיכך סותר שבעה מה גרם לו קריו יום אחד לפיכך סותר יום אחד","מאי שבעה אילימא דמטמא שבעה האי מה זובו טמא שבעה מבעי ליה אלא לאו דבר הגורם סותר דבר שאינו גורם אינו סותר ש\"מ","אמר אביי נקטינן אין קושי סותר בזיבה ואי משכחת תנא דאמר סותר ההוא ר\"א היא","תניא רבי מרינוס אומר אין לידה סותרת בזיבה איבעיא להו מהו שתעלה אביי אמר אינה סותרת ואינה עולה רבא אמר אינה סותרת ועולה","אמר רבא מנא אמינא לה דתניא (ויקרא טו, כח) ואחר תטהר אחר אחר לכולן שלא תהא טומאה מפסקת ביניהם","אי אמרת בשלמא עולה היינו דלא מפסקת טומאה אלא אי אמרת אינה עולה אפסיק ליה לידה ואביי אמר לך שלא תהא טומאת זיבה מפסקת ביניהם","אמר רבא מנא אמינא לה דתניא מזובה מזובה ולא מנגעה מזובה ולא מלידתה ואביי אמר לך תני חדא מזובה ולא מנגעה ולא תתני ולא מלידתה","ורבא האי מאי אי אמרת בשלמא מזובה ולא מלידתה איידי דאצטריך ליה לידה תנא נגעה אטו לידה אלא אי אמרת מזובה ולא מנגעה האי (ויקרא ט״ו:י״ג) מוכי יטהר הזב מזובו נפקא מזובו ולא מנגעו","ואביי חד בזב וחד בזבה וצריכי דאי כתב רחמנא"],[[0,"אזל שילא אמר לדביתהו צבית לי זוודתא","תכריכין:"],[0,"מילי","שלא ילשין עלי בפני רב:"],[0,"דקא פרח אסא","רגילין היו להניח הדס על המטה וההדס של אלו פורח היה והולך ממטה למטה:"],[0,"פייסא","שלום:"],[1,"קושי מהו שתסתור בזיבה","כל מה שספרה:"],[2,"דבר הגורם","לידי זיבה אם ראתה שלש והאי לאו גורם הוא דלא אתיא בה לידי זיבה. ואי קשיא והרי קרי שאינו גורם כדקי\"ל וסותר ההיא לאו סתירה היא דחד יומא הוא דסותר וכי קא בעי רבא לסתור הכל:"],[3,"שאינו גורם","כדקי\"ל ולא מחמת אונסו:"],[3,"וסותר","כדאמר בפירקין ברביעית אין בודקין אותו:"],[4,"לאיי","באמת אונס נמי גורם הוא לידי זוב שאם ראה שתים שלא באונס ושלישית באונס מצטרפין לקרבן דתנן שלישית אין בודקין אותו:"],[8,"לקרבן אמרתי","דבעי בדיקה ולא לסתירה:"],[9,"אלא","לא תוקי כדתרצה לטמויי במשא אלא ודאי לסתירה ובעיין לא תפשוט דאנן לרבנן בעינן ואת פשטת מדר\"א:"],[11,"ש\"מ","מדנקט לשון גרמא מכלל דקיימא ליה דבר הגורם סותר:"],[12,"רבי אליעזר היא","דאמר אונס סותר ואינו גורם:"],[13,"מהו שתעלה","אם ילדה בזוב ובימי לידתה לא ראתה מהו שיעלה לה לנקיים ולא תצטרך לספור אחריהן:"],[13,"אינה סותרת","אם היתה זבה ופסקה והתחילה לספור וילדה אינה סותרת וימי לידתה אפי' אינה רואה בהן אין משלימין לספירתה אלא משלמת אחריהן אם טהרה:"],[16,"מזובה","וספרה לה מזובה:"],[16,"ולא מנגעה","כיון שטהרה מזובה סופרת מיד ותביא קרבן לזיבתה ואז תטהר מלטמא בועלה ואפילו מנוגעת ולא צריכה להמתין עד שתטהר אף מנגעה:"],[16,"ולא מלידתה","כיון שטהרה מזובה סופרת מיד ואינה צריכה להמתין עד שיעברו ימי לידתה. אלמא ילדה בימי ספירה אינה סותרת ועולה:"]],[[2,"","דבר הגורם סותר כו'. וא\"ת יולדת בזוב תוכיח דסותרת לרב דאמר מעין אחד הוא אע\"ג דדם טוהר אינו גורם שום טומאה וי\"ל דדם טוהר חשיב גורם טפי כיון שאם לא ילדה הויא זבה או נדה לרב דאמר מעין אחד הוא ולא דמי לקושי דלעולם דם שתראה מחמת קושי לידה אינו גורם זיבה:"],[12,"","נקטינן דאין קושי סותר. מכאן משמע דלא דרשי אתים אם לא שנפרש לעיל (נדה דף לה.) ורבנן אתים לא דרשי היינו להך דרשא אך משמע דלא דרשי כלל:"],[13,"","אביי אמר אינה סותרת ואינה עולה. כתב רש\"י בתשובה אחת דאביי מודה דימי לידה שאינה רואה בהן עולים לספירת זיבתה דהכי מוכח פרק בא סימן (לקמן נדה דף נד:) מן הברייתא והכא אליבא דר' מרינוס קיימין תדע דאין רגילות למיבעי חדא מילתא בתרי דוכתי דבעי לה הכא ובשילהי בפ' בא סימן (שם) ותו היאך חולק אביי אברייתא דהתם ותו דמה להם לאביי ורבא להזכיר סתירה לא היה להם להזכיר אלא עלייה דפליגי בה אלא אליבא דר' מרינוס בעי מהו שתעלה דמדנקט אין לידה סותרת ולא קאמר נמי דעולה מכלל דסבירא ליה דאינה עולה או דלמא הא בהא תליא כיון דאינה סותרת ע\"כ עולה מואחר תטהר שלא תהא טומאה מפסקת ביניהן ומייתי רבא מנא אמינא לה דמסתמא רבי מרינוס לא פליג אקרא ואביי מייתי מנא אמינא לה דאיכא תנא דפליג אברייתא דבא סימן (שם) ואיכא למימר דר' מרינוס סבירא ליה נמי הכי מדלא קאמר ר' מרינוס אינה סותרת ועולה וה\"ה דהוה מצי אביי לאתויי ברייתא דטועה בהמפלת (לעיל נדה דף כח:) דסברה דאין עולה אלא דרבא הוה מוקי לה כר' אליעזר כדמוקי ברייתא דבסמוך כן פרש\"י ומה שפירש דמייתי רבא מנא אמינא לה דמסתמא לא פליג ר' מרינוס אקרא קשה דהא ע\"כ ר\"א פליג וי\"ל דהוה מצי למימר וליטעמיך אלא בלאו הכי דחי ליה אביי שפיר ומה שפירש ברייתא דהמפלת (שם דף כח:) מוקי לה רבא כרבי אליעזר דוקא בהא הויא כרבי אליעזר דאין עולין לה אבל לגמרי לא הויא כר' אליעזר דהא מוקי לה כר\"ע דבעי ספורים בפנינו ור\"א פליג עליה בפ\"ק (לעיל נדה דף ז:) ור\"ת מפרש דהלכתא כאביי דאין עולין וכברייתא דהמפלת (שם דף כט:) ומדקדק מדלא קאמר עלה (לעיל נדה ל.) ש\"מ ארבע דימי לידה אין עולין לאפוקי מן הברייתא דלעיל ללוי לחד שינוייא ומברייתא דבא סימן (לקמן נדה דף נד:) דסברי דעולין אלא אינו מונה אלא דברים של חדוש אבל הא פשיטא לן דאין עולין ועוד אומר ר\"ת דברייתא דבא סימן איכא למימר כדמפרש ליה רב פפא משום דאימא ילדה זכר להכי עולה שבוע שני לספירת זיבתה ודבריו נראה טפי מדקתני ואין קרבנו נאכל א\"כ איכא למימר אימר לא ילדה ואפי' ילדה אימא ילדה זכר ותדע דלא קיבל דברי רב הונא דהתם ולא הדר ביה אלא סבר דאין עולין מדקאמר בשמעתין רב פפא אמר ע\"כ הקישן הכתוב ואי סבר עולין א\"כ ע\"כ צריך לאוקמי כר\"א כדמוקי רבא ואמאי דחיק לאוקמי כרבנן דר\"א דאמרי אין דנין אפשר משאי אפשר כיון דבלאו הכי צריך לאוקמי כר\"א דאמר אין עולין אלא ודאי לא הדר ביה ומיהו אי גרסינן לעיל דאמר סותר רבי אלעזר והכא רבי אליעזר אין להוכיח כלום ודברי רב פפא דלקמן איכא למימר דאינו עיקר אע\"פ דהוי ספק ספיקא שבוע שני אינו עולה לספירת זיבתה דאיכא למיחש דילמא נקבה היא כדאמר רב הונא התם משום דאיכא נמי ספק ספיקא בסוף ימי טוהר דסתרה לה כדפרישית לעיל גבי המפלת חיה ועוף (דף כז. סד\"ה חומר) ומיהו כיון דאין קרבנה נאכל איכא בלאו הכי ספק ספיקא שמא לא ראתה ואפילו ראתה שמא לא ילדה ואומר ר\"ת דימי לידה שאינה רואה בהן הוא למ\"ד מיע\"ל קג\"ם ולא לחי העומד מאיליו בפ\"ק דעירובין (דף טו.) ורב סעדיה כתב דנשים שלנו דחשבינן להו כיולדות בזוב אם עברו ימי טומאת ז' לזכר או י\"ד לנקבה וספרה שבעה נקיים בימי טוהר או אפילו בימי טומאה מותרת לבעלה עד מ' לזכר ופ' לנקבה אע\"פ שרואה דם הכתוב קראו דם טוהר שכן שנו חכמים ימי לידה שאינה רואה בהן עולים לה לימי ספירת זיבתה הרי בהדיא חולק על ר\"ת והא דלא קאמר בהמפלת (שם דף ל.) ש\"מ ד' איכא למימר משום דלא קאמר אלא היכא דמצי למימר הא מני פלוני היא כדקאמר ש\"מ ר\"ע היא ש\"מ ר\"ש היא ש\"מ טבילה בזמנה מצוה לאפוקי מדר' יוסי בר' יהודה אבל בהא דאין עולין לא מצי למימר הא מני רבי אליעזר היא דלאביי לכ\"ע אין עולין:"],[13,"","רבא אמר אינה סותרת. וא\"ת והא רב סובר בפ\"ב (דף טו) דאי אפשר לפתיחת הקבר בלא דם וא\"כ תסתור דהכא בעינן שבעה נקיים מדם וי\"ל דרב אליבא דר' מרינוס קאמר כדפרישית וסבר דאפשר לפתיחת הקבר בלא דם דהא קאמר דאינה סותרת:"]]],[["בזב משום דלא מטמא באונס אבל זבה דמטמיא באונס אימא לא צריכא","ואי כתב רחמנא בזבה משום דלא מטמיא בראיות כבימים אבל זב דמטמא בראיות כבימים אימא לא צריכא","אמר אביי מנא אמינא לה דתניא (ויקרא יב, ב) דותה תטמא לרבות את בועלה","דותה תטמא לרבות את הלילות דותה תטמא לרבות את היולדת בזוב שצריכה שתשב שבעה נקיים","מאי לאו נקיים מלידה לא מדם","ואמר אביי מנא אמינא לה דתניא כימי נדתה כך ימי לידתה מה ימי נדתה אין ראוין לזיבה ואין ספירת שבעה עולה מהן אף ימי לידתה שאין ראוין לזיבה אין ספירת שבעה עולה מהן","ורבא הא מני רבי אליעזר היא דאמר מסתר נמי סתרה","וכי דנין אפשר משאי אפשר","אמר רב אחדבוי בר אמי ר' אליעזר היא דאמר דנין אפשר משאי אפשר ורב ששת אמר על כרחך הקישן הכתוב איכא דאמרי אמר רב אחדבוי בר אמי אמר רב ששת רבי אליעזר היא דאמר דנין אפשר משאי אפשר ורב פפא אמר על כרחך הקישן הכתוב","קשתה שלשה ימים וכו'","איבעיא להו שפתה מזה ומזה מהו רב חסדא אמר טמאה רבי חנינא אמר טהורה","א\"ר חנינא משל למלך שיצא וחיילותיו לפניו בידוע שחיילותיו של מלך הן","ורב חסדא אמר כל שכן דבעי נפיש חיילות טפי","תנן רבי יהושע אומר לילה ויום כלילי שבת ויומו ששפתה מן הצער ולא מן הדם טעמא דמן הצער ולא מן הדם הא מזה ומזה טהורה תיובתא דרב חסדא","אמר לך רב חסדא לא מבעיא מזה ומזה דטמאה דפסקי להו חיילות לגמרי אבל מן הצער ולא מן הדם אימר כי היכי דמדם לא פסקה מקושי נמי לא פסקה והא תונבא בעלמא הוא דנקט לה קמ\"ל","תנן קשתה שלשה ימים בתוך אחד עשר יום ושפתה מעת לעת וילדה הרי זו יולדת בזוב","היכי דמי אילימא כדקתני למה לי שלש בתרי בקושי וחד בשופי סגי","אלא לאו הכי קאמר קשתה שלשה ושפתה מזה ומזה או שקשתה שנים ושפתה מעת לעת הרי זו יולדת בזוב ותיובתא דר' חנינא","אמר לך רבי חנינא לא לעולם כדקתני והא קא משמע לן דאע\"ג דמתחיל קישוי בשלישי ושפתה מעת לעת טמאה לאפוקי מרבי חנינא","כמה היא קשויה ר\"מ אומר וכו' השתא חמשים מקשיא ארבעים מיבעיא אמר רב חסדא ל\"ק כאן לחולה כאן לבריאה","א\"ר לוי אין הולד מטהר אלא ימים הראויין להיות בהן זבה ורב אמר אפי' בימים הראויין לספירת זבה אמר רב אדא בר אהבה ולטעמיה דרב"],[[1,"","זב מטמא בין בשלש ראיות ביום אחד בין בשלש ראיות בג' ימים רצופין אבל זבה אינה מטמאה אלא בשלשה ימים כדכתיב בה ימים. בב\"ק (דף כד.) מרבינן זב לימים:"],[4,"נקיים מלידה","שלא תהא לידה ביניהם דאע\"ג דלא חזיא כמאן דחזיא דמי דהא ימי לידה טמאין בלא דם:"],[5,"מה ימי נדתה אין ראויין לזיבה","דאין זבה אלא אחר נדה ואין ספירת שבעה לזיבה עולה מהן דהא מכי הויא זבה לא חיילא ימי נדה לעולם עד שתשב שבעה נקיים וכל דם שרואה אינה אלא סותרת אבל נדה לא הויא הילכך לא משכחת ימי ספירה בימי נדה ולא ימי נדה בימי ספירה:"],[5,"אף ימי לידה","הואיל ודמו לנדה ואין ראויין לזיבה כדאמר ולא דמה מחמת ולד הכי נמי לענין ספירה מדמינן להו לנדה ולא תעלה בהן ספירת שבעה כגון אם ילדה בימי ספירה:"],[5,"","הכי גרסינן אף ימי לידתה שאין ראויין לזיבה אין ספירת שבעה עולה מהן:"],[6,"מסתר נמי סתרה","וכ\"ש דלא סלקא כי היכי דס\"ל באונס בזב שאינו גורם וסותר ימי לידה נמי אע\"ג דלא גרמי סתר וכי קאמינא אנא לרבנן דאמרי דבר שאינו גורם אינו סותר אינה סותרת ועולה:"],[7,"וכי דנין אפשר","כגון לידה דאפשר לה ללדת בימי ספירה:"],[7,"משאי אפשר","מימי נדה דלא אפשר להיות נדה בימי ספירה:"],[8,"ר' אליעזר היא","במסכת מנחות בפ' התודה דיליף פסח דורות מפסח מצרים שלא יביא אלא מן החולין אמר לו ר\"ע וכי דנין אפשר משאי אפשר במצרים אכתי לא הוה מעשר אבל לדורות דאיכא מעות מעשר שני נייתי מנייהו אמר לו אף ע\"פ שאי אפשר ראיה גדולה היא ונלמד הימנה:"],[8,"הקישן הכתוב","ואפי' לר\"ע הני מילי דאין דנין כגון גזרה שוה אבל הקישא אין משיבין על ההיקש:"],[10,"רב חסדא אמר טמאה","דהא איכא שופי:"],[10,"רבי חנינא אמר טהורה","כיון דשפתה אף מן הדם איגלאי מילתא דדם הקושי מחמת ולד אתא אבל כי שפתה מן הצער ורואה דם איגלאי מילתא דמקמי הכי הוי חזיא נמי בלא קושי:"],[11,"לפניו","יום אחד או שנים קודם ביאתו:"],[12,"דמפיש חיילות טפי","סמוך לביאתו:"],[14,"דפסקו להו חיילות לגמרי","דהשתא ודאי קמאי לא מחמתיה אתו דאי מחמתיה אתו כל שכן דמפיש חיילות:"],[14,"תונבא","אשטורדישו\"ן. שאינה מרגשת בצערה מחמת שעמומית החולי:"],[16,"אי נמי כי קתני","שלשה בקושי וא' בשופי ובכולן ראתה למה לי כולי האי:"],[17,"או שקשתה שנים ושפתה מעת לעת","בשלישי מן הצער ולא מן הדם:"],[18,"כדקתני","שלשה בקושי ומקצת שלישי ומקצת רביעי בשופי:"],[18,"הא קמ\"ל דאע\"ג","דקשתה בקצת שלישי ולא שפתה לילה ויום כלילי שבת ויומו אלא לילה ושני חצאי יום טמאה:"],[18,"ולאפוקי מדר' חנינא בן אחי רבי יהושע","דאמר לעיל (נדה דף לו:) כל שחל קישויה להיות בשלישי שלה כו':"],[19,"בריאה","ארבעים:"],[20,"אין הולד מטהר אלא ימים הראויין להיות בה זבה","דהיינו י\"א יום שבין נדה לנדה אבל ראתה אחריהן טמאה נדה כדאמר לעיל בימי נדה נדה:"],[20,"אף ימים הראויין לספירת זיבה","כגון התחיל הקושי בימי הזיבה טהורין כל ימי זיבה ושבעה אחריהם דהא בתר זבה שייכי וכי כתב רחמנא בנדתה ולא בזיבתה דזיבתה טהורה אהני נמי קאי אבל אחר שבעה אם יאריך טמאה נדה:"],[20,"ולטעמיה דרב","כיון דאמר רב בהנך ימים דשייכי בתר זיבה טהרינהו רחמנא לענין קושי:"]],[[5,"","מה ימי נדותה דאין ראוין לזיבה. וא\"ת דבשילהי בא סימן (לקמן נדה דף נד.) אמר ימי נדותה שאינה רואה בהן עולין לספירת זיבתה וי\"ל דהתם מיירי בזבה קטנה שרואה יום י\"א דיום י\"ב הויא ביה תחלת נדה ועולה לה:"],[8,"","על כרחך הקישן הכתוב. ואין משיבין על ההיקש וא\"ת והא בפ' התודה (מנחות דף פב.) פריך ר\"ע לר' אליעזר וכי דנין אפשר משאי אפשר אע\"ג דטעמא דרבי אליעזר דדריש היקשא מועבדת שיהו כל העבודות שוות ור\"ע נמי אית ליה היקשא דועבדת בפרק מי שהיה טמא (פסחים דף צו.) וי\"ל דהתם לא מצי למימר על כרחך הקישן הכתוב דאיצטריך היקשא להנהו דרשות דפסחים (דף צו.):"],[19,"","ארבעים מיבעיא. בסוכה לא פריך כי האי גוונא ארבי יהודה דמכשיר עד ארבעים וחמשים אמה התם משום דקים ליה דלאו דוקא אלא ארבעים וחמשים כדאמרי אינשי ואפילו טובא אבל הכא הוי דוקא חמשים כדקתני בסמוך וחמשים שהולד מטהר ובפרק מפנין (שבת דף קכו:) דפריך השתא ה' קופות ד' מיבעיא המקשה סבר דדוקא נקט ומשני דלאו דוקא נקט אלא ד' וה' כדאמרי אינשי ועוד משני דהוה דוקא ד' מאוצר קטן וה' מאוצר גדול ובפרק אע\"פ (כתובות דף ס.) תינוק יונק אפי' ד' וה' שנים נמי לא דייק התם משום דלאו דוקא ה' אלא לפי צרכו כדקאמר התם ואפילו חבילתו על כתפו ובפרק הזרוע (חולין דף קלב:) דאמר כהן טבח ב' וג' שבתות פטור מן המתנות מכאן ואילך חייב במתנות התם נקט ב' לרבי דאמר בתרי זימני הוה חזקה ולרשב\"ג ג':"],[20,"","ורב אדא בר אהבה אמר אף ימים הראויים לספירת סתירת זיבתה. וא\"ת מה הוסיף על דברי רב הא לרב נמי הראויין לספירה היינו ז' ימים אחר י\"א יום ואז מתחילות י\"א אחרים שהם ימי זיבה וא\"כ לדידיה נמי לעולם קושי מטהר וי\"ל דאינה נדה עד שיעברו שבעה ימי הספירה אחר י\"א ואם ראתה אז אף בקושי טמאה לרב ולרב אדא טהורה דראויין לספירת סתירת זיבתה ור\"ח פי' דלוי אינו מטהר אלא תשעה ימים הראוין ליעשות בהן זבה אבל י' וי\"א דאינם ראויין ליעשות בהן זבה דאפילו ראתה אפי' גם בי\"ב אינה אלא נדה ורב מוסיף ימים הראויין לספירה כגון עשירי וי\"א וחמשה ימים אחרי כן אבל שני ימים משבעה ימים אחרונים אם ראתה בהן טמאה לרב ורב אדא מוסיף אף אותם שני ימים ונמצא כולן טהורין:"]]],[["אפי' ימים הראויין לספירת סתירת זבה","תנן כמה הוא קשויה ר\"מ אומר ארבעים וחמשים יום","בשלמא לרב משכחת לה כרב אדא בר אהבה אלא ללוי קשיא","אמר לך לוי מי קתני טהורה בכולן בימי נדה נדה בימי זיבה טהורה","לישנא אחרינא אמרי א\"ר לוי אין הולד מטהר אלא ימים הראויין להיות בהן זבה גדולה מ\"ט (ויקרא טו, כה) דמה ימים רבים כתיב","אבא שאול משמיה דרב אמר אפילו ימים הראויין להיות בהן זבה קטנה מ\"ט ימי וכל ימי התם כתיבי","תנן כמה הוא קשויה ר\"מ אומר אפי' ארבעים וחמשים יום קשיא לתרוייהו מי קתני טהורה בכולן קשתה בימי נדתה נדה בימי זיבתה טהורה","תניא היה ר\"מ אומר יש מקשה ק\"נ יום ואין זיבה עולה בהן כיצד שנים בלא עת","ושבעה נדה ושנים של אחר הנדה וחמשים שהולד מטהר","ושמונים של נקבה ושבעה נדה ושנים של אחר הנדה","אמרו לו א\"כ יש מקשה כל ימיה ואין זיבה עולה בהן","אמר להן מאי דעתייכו משום נפלים אין קושי לנפלים","ת\"ר יש רואה מאה יום ואין זיבה עולה בהן כיצד שנים בלא עת ושבעה נדה ושנים של אחר הנדה ושמונים של נקבה ושבעה נדה ושנים של אחר הנדה","מאי קמ\"ל לאפוקי ממ\"ד אי אפשר לפתיחת הקבר בלא דם קמ\"ל דאפשר לפתיחת הקבר בלא דם","ר' יהודה אומר דיה וכו' תניא רבי יהודה אומר משום רבי טרפון דיה חדשה ויש בדבר להקל ולהחמיר","כיצד קשתה שנים בסוף שמיני ואחד בתחלת תשיעי ואפילו בתחלת תשיעי ילדה הרי זו יולדת בזוב","אבל קשתה יום אחד בסוף שמיני ושתים בתחלת תשיעי ואפילו בסוף תשיעי ילדה אין זו יולדת בזוב","אמר רב אדא בר אהבה ש\"מ קסבר רבי יהודה שיפורא גרים איני והא אמר שמואל אין אשה מתעברת ויולדת אלא למאתים ושבעים ואחד יום או למאתים ושבעים ושנים יום או למאתים ושבעים ושלשה","הוא דאמר כחסידים הראשונים דתניא חסידים הראשונים לא היו משמשין מטותיהן אלא ברביעי בשבת שלא יבואו נשותיהן"],[[0,"אף ימים הראויין לספירת סתירת זבה","בימי זיבה דלעולם היא טהורה עד שתשפה שהרי כל ימיה ראויין לכך שאם תספור ששה ותראה סותרת הכל ונמצאו הימים הבאין ראויין לספירה והא דתניא בימי נדה נדה היכא דאתחיל קושי מימי נדה אבל אתחיל בימי זיבה כל מה שיאריך הקושי טהורה:"],[1,"ועוד ארבעים וחמשים יום","קס\"ד לגמרי מטהר לה ר\"מ מזוב ומנדות:"],[3,"בימי נדה נדה","וה\"ק ר\"מ כמה הוא קשויה שלא תבא להתחייב בקרבן ולספירת נקיים ארבעים וחמשים יום ומיהו בכל הני ארבעים כי שלמי ימי זוב ומטו ימי נדות טמאה נדה וכי הדרי שלמי ז' ימי נדות ומטו ימי זוב טהורה:"],[4,"זבה גדולה","ראתה שלשה רצופין בתוך י\"א יום טהורה מספירת נקיים ומקרבן אבל לא ראתה אלא יום אחד צריכה לשמור יום כנגד יום דכי כתיב דמה דדרשינן ולא מחמת ולד בזבה גדולה כתיב דכתיב בההוא קרא ימים רבים ואם משך קשויה יותר מאחד עשר יום שנכנסה לימים שראויים לנדה טמאה:"],[5,"ימי וכל ימי זוב טומאתה וגו'","ומינייהו נפקא לן זבה קטנה בשילהי מכילתין בשמעתא בתרייתא:"],[6,"קשיא לתרוייהו","דאמרי זבה גדולה וקטנה הוא דמטהר ולד אבל אם יאריך אחריהן טמא:"],[6,"בימי זיבה","למר כדאית ליה ולמר כדאית ליה:"],[7,"יש מקשה","שהיא רואה:"],[7,"ק\"נ יום","רצופין:"],[7,"ואין זבה עולה בהן","ולא שתהא מקשה כל ק\"נ יום:"],[7,"כיצד ראתה ב' בלא עת","בלא עת נדה הרי י\"א ימים שלאחר נדתה שהן ימי זיבה ואינה זבה עד שתראה בהן ג' רצופין ואם ראתה שנים בסופן כשתראה למחר הוי פתח של נדותה ואינו מצטרף לה לזיבה אלא תחלת נדה הויא וכל שבעה תהיה נדה הרי ט' ימים רצופין ושנים שלאחר הנדה שהן מן י\"א של ימי זוב וכל כמה דלא חזיא ג' בימי זיבה לא הויא זבה הרי י\"א רצופין וקשתה חמשים והיא חולה ואמרינן לעיל בחולה חמשים הרי ס\"א וביום ס\"א ילדה נקבה ואפילו רואה כל שמונים אינה זבה ואחד ושמונים הוי תחילת נדה ואם תראה ז' הרי מאה ומ\"ח ושנים שלאחר הנדה ותפסוק הרי ראתה ק\"נ רצופין ואינה זבה אבל אם תראה יותר הויא זבה דהוו להו ג' לאחר הנדה:"],[8,"וחמשים שהולד מטהר","הנך חמשים של קושי לפני השמונים:"],[10,"א\"כ","דקחשבת שמונים של נקבה:"],[10,"יש מקשה לעולם","ואינה זבה כגון טובלת לי\"ד של נקבה ומתעברת ולסוף שמונים שבעה לנדה ושנים לאחר הנדה ומקשה חמשים וחוזרת ומפלת נקבה וכן לעולם:"],[11,"אמר להן","ר\"מ מאי דעתייכו משום נפלים כדפרשינן:"],[11,"אין קושי לנפלים","אין הנפל מטהר קישויו ואנן בולד דאית ליה קושי קמיירינן:"],[12,"יש רואה","בלא קושי:"],[13,"קמ\"ל דאפשר לפתיחת הקבר בלא דם","דאי לא אפשר הויא לה זבה כשילדה אחר שנים שלאחר הנדה דהוה ליה יום לידה שלישי ואי הויא חזיא קודם לידה בפתיחת הקבר הרי היא זבה הואיל ובלא קושי ראתה:"],[14,"להקל ולהחמיר","פעמים שאינו מטהר כלום פעמים שהוא מטהר חדש ויום אחד:"],[15,"הרי זו יולדת בזוב","הואיל ורוב זיבה בשמיני הואי שאין הולד מטהר שדינן חד יומא בתר תרין והרי היא זבה:"],[16,"ואפי' בסוף תשיעי ילדה","ואע\"ג דתשיעי כולו בשופי חוץ משני ימים אין זו יולדת בזוב בלבד שלא תראה דם בימי השופי ולא אמרינן כיון דשופי סמוך ללידה נטמאנה בדם הקושי דקסבר ר' יהודה שיפורא גרים כלומר החדש של תשיעי גורמת לידת הולד דמכי עייל הוה זמן לידה הילכך כל הדמים שרואה בו בקושי אינו אלא מחמת הולד אע\"ג דאיכא שופי בתרייהו ואפי' בתחלת תשיעי הוי מחמת ולד דקסבר יולדת לט' יולדת למקוטעין:"],[17,"שיפורא","שופר שתוקעין בו ב\"ד בקדוש החדש:"],[17,"או למאתים ושבעים ואחד","דהוו להו ט' חדשים שלמים של שלשים וביום ראשון של עשירי יולדת:"],[17,"או לרע\"ב","כלומר אם לא קלט הזרע יום ראשון קולט בשני ומיום קליטתו הוי התחלת העיבור:"],[17,"או לרע\"ג","שאם לא קלט בשני קולט בשלישי אבל אם לא קלט בשלישי שוב אינו קולט דקי\"ל דעד שלישי הוי ראוי להזריע מכאן ואילך מסריח במסכת שבת (דף פו.) בפולטת שכבת זרע ביום השלישי בפרק ר' עקיבא. אלמא לא ילדה למקוטעין:"],[18,"[הוא]","שמואל דאמר כחסידים:"]],[[4,"","להיות בהן זבה גדולה. רש\"י פירש לאפוקי י' וי\"א דאינה ראויה להתחיל בהן זבה גדולה ור\"ח פירש לאפוקי יום ראשון ויום שני של י\"א דאינה ראויה עדיין להיות זבה גדולה אם לא תראה יום ג':"],[11,"","מאי דעתיך משום נפלים. תימה דבלאו נפלים מצינן לאשכוחי יותר מק\"נ כגון יהודה וחזקיה ואחר הולד השני תספור שמונים לנקבה ושבעה ימים לנדה ושני ימים אחרי כן וי\"ל דלא שכיח וא\"ת והלא בלא קושי משכחת כל ימיה שלא תהא זבה כגון שהפילה אחר פ' לנקבה וז' לנדה וב' ימים אחר נדה ובשלמא בסמוך גבי יש רואה ק' ימים איכא למימר דבחד ולד מיירי אי נמי בבן קיימא אבל הכא מיירי בנפלים מדקאמר אין קושי לנפלים ויש לומר דלא מיירי ביולדת בלא קשוי:"],[17,"","שיפורא גרים. פירוש שופר שתוקעין בר\"ח בקדוש החדש תשיעי של עיבורה ואם תאמר והיכי מוכח דחדש לבנה גרים דילמא חדש תשיעי של אחר ח' חדשים של שלשים יום להריונה גרים אפי' הוא מתחיל באמצע חדש הלבנה וי\"ל דאם כן הו\"ל למימר דיה חדש אחרון אבל חדשה משמע חדש המבורר דהיינו חדש הלבנה וקאי ש\"מ אמתני' כמו אברייתא א\"נ משום דברייתא מוכחא דיולדת למקוטעים כדקתני אפילו בתחלת ט' ילדה וליום אחד לא הוה קרי חדשה אבל אחדש לבנה קרי שפיר חדשה אפי' יום אחד (כו') אי נמי מסיפא דברייתא מוכיח דע\"כ חדש לבנה גרים דקתני אבל קשתה יום אחד בסוף שמיני ושנים בתחלת תשיעי ואפי' ילדה בסוף ט' כו' והיאך יכולה לידע דקשתה שנים בט' אי לא דמיירי בחידושה של לבנה דנהי דהיכא דילדה בסוף ט' יכולה לידע כגון שילדה לרע\"ג ימים לשמושה דאז מתחיל תשיעי שלה שלשים יום לפני לידתה דהזרע לא נקלט עד יום ג' לשמושה דאי נקלט יום ראשון היתה יולדת לרע\"א לשמושה דאין הולד משתהה יותר דלא קי\"ל כרבה תוספאה דפרק הערל (יבמות דף פ:) מ\"מ מדקאמר אפי' ילדה בסוף ט' משמע נמי שילדה באמצע תשיעי ואז אי אפשר לדעת אם קשתה ב' ימים בט' בצמצום דאי קשתה בר\"מ וברמ\"א וברמ\"ב משמושה שמא לא נקלט הזרע עד מחרת התשמיש וא\"כ לא קשתה אלא יום אחד בחדש ט' ואם קשתה ברמ\"א ורמ\"ב ורמ\"ג שנקלט הזרע ביום התשמיש א\"כ ג' ימים קשתה בחדש ט' אלא ודאי שיפורא גרים ונראה דלרבי יהודה שיפורא דט' חדשים גרים ואם נתעברה בסוף החדש יולדת בתחלת תשיעי דאי בעינן שמונה הראשונים שלמים א\"כ כי נתעברה בסוף החדש שיפורא דט' הוה ליה עשירי אא\"כ נתעברה בתחלת החדש:"],[17,"","והא אמר שמואל כו'. לא מצי למימר דרבי יהודה בנפלים איירי מדנקט שמיני ותשיעי ולא נקט ג' וד' אי נמי מדקתני ילדה:"]]],[["לידי חלול שבת ברביעי ותו לא אימא מרביעי ואילך","אמר מר זוטרא מאי טעמייהו דחסידים הראשונים דכתיב (רות ד׳:י״ג ) ויתן [ה'] לה הריון הריון בגימטריא מאתן ושבעים וחד הוו","אמר מר זוטרא אפי' למ\"ד יולדת לתשעה אינה יולדת למקוטעים יולדת לשבעה יולדת למקוטעים שנאמר (שמואל א א, כ) ויהי לתקופות הימים ותהר חנה ותלד בן מיעוט תקופות שנים מיעוט ימים שנים","רבי יוסי ור\"ש אומרים אין קושי יותר מב' שבתות אמר שמואל מאי טעמייהו דרבנן דכתיב (ויקרא יב, ה) וטמאה שבועים כנדתה כנדתה ולא כזיבתה מכלל דזיבתה טהורה וכמה שבועים","ת\"ר יש מקשה עשרים וחמשה יום ואין זיבה עולה בהן כיצד שנים בלא עת ושבעה נדה וב' שלאחר נדה וארבעה עשר שהולד מטהר","ואי אפשר שתתקשה עשרים וששה יום בלא ולד ולא תהא יולדת בזוב","בלא ולד בתלתא נמי סגי אמר רב ששת אימא במקום שיש ולד אמר ליה רבא והא בלא ולד קתני","אלא אמר רבא הכי קאמר אי אפשר שתתקשה עשרים וששה יום במקום שיש ולד ולא תהא יולדת בזוב ובמקום שאין ולד אלא נפל בתלתא נמי הויא זבה מ\"ט אין קושי לנפלים","\u0001מתני׳\u0002 המקשה בתוך שמונים של נקבה כל דמים שהיא רואה טהורין עד שיצא הולד ורבי אליעזר מטמא","אמרו לו לרבי אליעזר ומה במקום שהחמיר בדם השופי היקל בדם הקושי מקום שהיקל בדם השופי אינו דין שנקל בדם הקושי","אמר להן דיו לבא מן הדין להיות כנדון ממה היקל עליה מטומאת זיבה אבל טמאה טומאת נדה","\u0001גמ׳\u0002 תנו רבנן תשב לרבות המקשה בתוך שמונים של נקבה שכל דמים שהיא רואה טהורין עד שיצא הולד ור\"א מטמא","אמרו לו לר\"א ומה במקום שהחמיר בשופי שלפני הולד היקל בשופי שלאחר הולד מקום שהיקל בקושי שלפני הולד אינו דין שנקל בקושי שלאחר הולד","אמר להם דיו לבא מן הדין להיות כנדון ממה היקל עליה מטומאת זיבה אבל מטמאה טומאת נדה","אמרו לו הרי אנו משיבין לך לשון אחר ומה במקום שהחמיר בשופי שלפני הולד היקל בקושי שעמו מקום שהיקל בשופי שלאחר הולד אינו דין שנקל בקושי שעמו","אמר להם אפילו אתם משיבין כל היום כולו דיו לבא מן הדין להיות כנדון ממה היקל עליה מטומאת זיבה אבל מטמאה טומאת נדה","אמר רבא בהא זכינהו ר\"א לרבנן לאו אמריתו דמה דמה מחמת עצמה ולא מחמת ולד ה\"נ (ויקרא יב, ז) וטהרה ממקור דמיה דמיה מחמת עצמה ולא מחמת ולד","אימא בימי נדה נדה בימי זיבה טהורה אמר קרא תשב ישיבה אחת לכולן","\u0001מתני׳\u0002 כל אחד עשר יום בחזקת טהרה"],[[0,"לידי חילול שבת","שלא תלד בשבת ויצטרך לחלל עליה את השבת:"],[0,"ברביעי ותו לא","כל שכן דאי מעברא בה' או בו' או בשבת דלא מטי יום לידה בשבת:"],[0,"אלא מרביעי ואילך","אבל ליל שלישי וליל שני ומוצאי שבת לא דאי מתעברה למוצאי שבת שמא תלד לרע\"ג דמטי בשבת ונמצא שבת מתחלל שניתן רשות לחללו מפני סכנת גופה. והיכי דמי עשה מרע\"ג ימים שבועים מאה ימים הוו שבועים שווין בר מתרי יומי וכן לק' ימים האחרים שני ימים הרי ארבע ימים עודפים על השבועים וע' ימים כולן שוים וג' ימים תן על ד' העודפים הרי שבוע וכיון שהתחילו במוצאי שבת נמצאו כלים בשבת ואם נתעברה בשני דלמא ילדה לרע\"ב דמטי בשבת ואם נתעברה בשלישי דלמא ילדה לרע\"א דמטי בשבת אבל בד' אי ילדה לרע\"א מטי בחד בשבא ואי לרע\"ב מטי בתרי בשבא ואי לרע\"ג מטי בתלתא בשבא. אלמא כשמואל סבירי להו:"],[2,"לתקופות הימים","כתיב:"],[2,"מיעוט ימים שנים","דכל מקום שנאמר ימים ולא נאמר כמה תפוס המועט בידך ולא המרובה שאם אתה אומר ימים שלשה או ארבעה אני אומר עשרה או ק' כך שנו חכמים (סוכה דף ה:) כל ששמועו מרובה ושמועו מועטת תפסת מרובה לא תפסת תפסת מועט תפסת. הלכך כאן שנאמר ימים מכיון שנכנסו שני ימים בחדש שביעי ילדה:"],[3,"מכלל דזיבתה טהורה","ומהכא גמרינן לעיל קושי בימי זיבה:"],[4,"יש מקשה","שרואה כ\"ה יום בין קושי ובין שופי:"],[4,"שנים בלא עת וז' דנדה וב' לאחר נדה","בלא קושי:"],[4,"וי\"ד","בקושי לרבי יוסי ולר\"ש והכא לא חשיב אלא קודם לידה. ואי אפשר למקשה כ\"ו יום שלא תהא זבה שהולד אינו מטהר אלא י\"ד יום הסמוכים ללידה ופשו להו ג' בין נדות לקושי ובהנהו שלשה הויא זיבה:"],[5,"בלא ולד","לקמן פריך משמע שאין שם ולד א\"כ לאו קושי הוא ולמה לי כ\"ו בתלתא לאחר הנדה סגי:"],[8,"מתני' המקשה תוך שמונים","שנתעברה בימי טוהר או שנשתהה ולד אחר חבירו ב' חדשים וחצי אחד נגמרה צורתו באמצע שביעי ואחד נגמרה צורתו לסוף תשיעי כמעשה דיהודה וחזקיה בני ר' חייא (לעיל נדה דף כז.):"],[8,"טהורין","דכל תוך מלאת הוי דם טוהר:"],[8,"ורבי אליעזר מטמא","נדה דכיון דבקושי בא לאו דם טוהר הוא אלא מחמת ולד שבמעיה ומזיבה הוא דטהור אבל בימי נדה נדה:"],[9,"שהחמיר בדם השופי","כגון שאר יולדת שרואה ג' בשופי וילדה הרי זו יולדת בזוב:"],[9,"היקל בדם הקושי","לטהרה מזובה:"],[9,"מקום שהיקל בדם השופי","לטהרה מכל טומאה כגון תוך מלאת:"],[9,"אינו דין שנקל בדם הקושי","לטהרה מכל טומאה ואפי' מנדות:"],[10,"דיו לבא מן הדין","כגון קושי של תוך מלאת שאתם למדין מקושי דעלמא:"],[10,"להיות כנדון","כקושי דעלמא:"],[11,"גמ' תשב","על דמי טהרה:"],[11,"עד שיצא הולד","יצא הולד טמאה לידה:"],[14,"הרי אנו משיבין אותך לשון אחר","שלא נלמד קושי שלאחר מקושי שלפני כדאמרי' לעיל מקום שהיקל בקושי שלפני הולד אינו דין שנקל בקושי שלאחריו דהכא הוא דאיכא למימר דיו לקושי שלאחריו להיות כקושי שלפניו שהרי ממנו אנו למדים אלא הכי גמרינן מקום שהיקל בשופי שלאחריו אינו דין שנקל בקושי שעמו שעם השופי דהשתא יליף קושי של אחריו דטהור לגמרי וליכא למימר ממה היקל מטומאת זיבה כדקאמר:"],[15,"דיו לבא כו'","שהרי ק\"ו אינו נידון אלא מכח קושי שלפניו כדקתני ומה במקום שהחמיר בשופי שלפני הולד היקל בקושי שעמו:"],[16,"זכינהו","תשובה נצחת יכול להשיבן:"],[17,"אימא בימי נדה נדה","לר\"א פריך כיון דאית ליה דיו לודי מיהא דבימי זיבה טהורה כקושי שלפניו כגון ראתה בקושי שבעה ימים ראשונים תהא טמאה ואם ראתה יותר יהא הדם טהור ותטבול לאחר שבעה ראשונים של קושי:"],[17,"ישיבה אחת לכולן","או כולן טהורין או כולן טמאין:"],[18,"מתני' כל אחד עשר יום","אחר הנדות אשה עומדת בחזקת טהרה. ובגמרא מפרש למאי הלכתא:"]],[[15,"","דיו לבא מן הדין להיות כנדון. וא\"ת ובלא ק\"ו נמי אמאי מטמא תיפוק ליה דקושי לא גרע משופי ולמה בשביל קישוי יש לה להיות טמאה וי\"ל דטעמא דרבי אליעזר כדמפרש רבא בגמרא דמיה מחמת עצמה ולא מחמת ולד ולכך צריך להו לרבנן ק\"ו ומחמת ק\"ו אית לן למדרש קרא דדמיה למילתא אחריתי וליכא לאוקמי קרא אפי' בימי נדה דליכא ק\"ו דרבנן נמי דרשי תשב ישיבה אחת לכולן ורבי אליעזר סבר דכיון דאיכא לאוקומי קרא בימי נדה אפי' אי נימא ק\"ו משום דיו אין לך לטהר אלא בימי זיבה אבל בימי נדה טמאה ולדידיה אף בימי זיבה טמאה משום תשב ישיבה אחת לכולן כדאמר בגמ':"],[17,"","אימא בימי זיבה טהורה בימי נדה טמאה. פי' הקונטרס ארבי אליעזר פריך דמטמא אף בימי זיבה מדקאמר ת\"ק כל דמים שהיא רואה טהורה ועלה קא\"ר אליעזר דטמאה ולא מפליג משמע דאף בימי זיבה דטמאה ודיו דקא\"ר אליעזר לדבריהם דרבנן קאמר להו והר\"ר מנחם מפרש דרבי אליעזר לא מטמא אלא בימי נדה כדקאמר דיו והא דקפריך ואימא בימי זיבה טהורה הוי סיום מילתא דרבא דאמר בהא זכינהו רבי אליעזר לרבנן דהא מקרא דדמיה הוו להו לרבנן לטמא בימי נדה ולטהר בימי זיבה ומשני תשב ישיבה אחת לכולן וכיון דמק\"ו מטהרין בימי זיבה אית לן לטהר מקרא דתשב אף בימי נדה דהא משמע ישיבה אחת לכולן ואין לחלק בהן ואם כן קרא דדמיה אתא למילתא אחריתי והכי דרשינן לעיל בברייתא לרבנן מתשב שכל דמיה טהורים ואם תאמר וכיון דאי לאו קרא דתשב אף רבנן הוו מטמאין מקרא דדמיה א\"כ היכי בעו למעבד ק\"ו דאף בימי נדה טהורה דקאמרי הרי אנו משיבין אותך בלשון אחר וי\"ל דפרכינן ליה כיון דמק\"ו מוכיח דטהורה אף בימי נדה אית לן למימר דמיה לדרשא אחריתי:"]]],[["ישבה לה ולא בדקה שגגה נאנסה הזידה ולא בדקה טהורה","הגיע שעת וסתה ולא בדקה הרי זו טמאה ר\"מ אומר אם היתה במחבא והגיע שעת וסתה ולא בדקה הרי זו טהורה מפני שחרדה מסלקת את הדמים","אבל ימי הזב והזבה ושומרת יום כנגד יום הרי אלו בחזקת טומאה","\u0001גמ׳\u0002 למאי הלכתא אמר רב יהודה לומר שאינה צריכה בדיקה והא מדקתני סיפא ישבה ולא בדקה מכלל דלכתחלה בעיא בדיקה","סיפא אתאן לימי נדה וה\"ק כל י\"א בחזקת טהרה ולא בעיא בדיקה אבל בימי נדתה בעיא בדיקה ישבה ולא בדקה שגגה נאנסה הזידה ולא בדקה טהורה","רב חסדא אמר לא צריכא אלא לר\"מ דאמר אשה שאין לה וסת אסורה לשמש ה\"מ בימי נדתה אבל בימי זיבתה בחזקת טהרה קיימא","א\"ה אמאי א\"ר מאיר יוציא ולא יחזיר עולמית דלמא אתיא לקלקולא בימי נדה","הא מדקתני סיפא הגיע שעת וסתה ולא בדקה מכלל דבאשה שיש לה וסת עסקינן חסורי מחסרא והכי קתני כל י\"א בחזקת טהרה ושריא לבעלה ובימי נדה אסורה","בד\"א באשה שאין לה וסת אבל יש לה וסת מותרת וצריכה בדיקה ישבה ולא בדקה שגגה נאנסה הזידה ולא בדקה טהורה הגיע שעת וסתה ולא בדקה טמאה","הא מדסיפא ר\"מ רישא לאו ר\"מ כולה ר\"מ היא וה\"ק אם לא היתה במחבא והגיע שעת וסתה ולא בדקה טמאה שר\"מ אומר אם היתה במחבא והגיע שעת וסתה ולא בדקה טהורה שחרדה מסלקת את הדמים","רבא אמר לומר שאינה מטמאה מעת לעת","מיתיבי הנדה והזבה והשומרת יום כנגד יום והיולדת כולן מטמאות מעת לעת תיובתא","רב הונא בר חייא אמר שמואל לומר שאינה קובעת לה וסת בתוך ימי זיבתה אמר רב יוסף לא שמיע לי הא שמעתתא","א\"ל אביי את אמרת ניהלן ואהא אמרת לן היתה למודה להיות רואה יום ט\"ו (יום) ושינתה ליום כ' זה וזה אסורין לשמש שינתה פעמים ליום כ' זה וזה אסורין","ואמרת לן עלה אמר רב יהודה אמר שמואל ל\"ש אלא ט\"ו לטבילתה שהן כ\"ב לראיתה דהתם בימי נדתה קאי לה אבל ט\"ו לראיתה דבימי זיבתה קאי לא קבעה","אמר רב פפא אמריתא לשמעתא קמיה רב יהודה מדסקרתא מקבע לא קבעה מיחש מהו דניחוש לה","אישתיק ולא א\"ל ולא מידי אמר רב פפא נחזי אנן היתה למודה להיות רואה ליום ט\"ו ושינתה ליום כ' זה וזה אסורין"],[[0,"ישבה לה ולא בדקה","אכל נשים קאי ולאו לעיל מהדר:"],[1,"טמאה","דאורח בזמנו בא:"],[1,"במחבא","מחמת ליסטין או כרכום:"],[2,"ימי הזב","ימי ספירו:"],[2,"ושומרת יום","כיון שנפתח מעיינה וראתה היום אע\"ג דבתוך י\"א היא הויא למחר בחזקת טמאה:"],[3,"גמ' לומר שאינה צריכה בדיקה","שחרית וערבית ומשעברו צריכה לבדוק כדאיתא בפ\"ק (לעיל נדה דף יא.):"],[3,"והא מדקתני סיפא ישבה","דמשמע דיעבד מכלל כו'. והאי דפריך כן דס\"ד דהאי ישבה אתוך י\"א קאי:"],[4,"לימי נדה","לימים שראויין לנדה כגון אחר י\"א שבין נדה לנדה:"],[4,"בחזקת טהרה","שנסתלקו דמיה בנדותה ויצאו:"],[4,"בימי נדה","לאחר שעברו י\"א וראויים לבא ימי נדה:"],[4,"בעיא בדיקה","לכתחלה אבל ישבה ולא בדקה דיעבד טהורה ואם הגיע וסת הקבוע לה ולא בדקה ההיא ודאי טמאה:"],[5,"לא נצרכא","הא דקתני כל י\"א בחזקת טהרה אלא לר\"מ בסוף פרק ראשון בגמרא:"],[6,"אמאי יוציא","תשמש כל י\"א:"],[6,"דלמא אתיא לקלקולא בימי נדה","בימים הראויים לנדה אסורה לשמש שמא תקלקלנו:"],[10,"רבא אמר","מתני' דקתני כל י\"א בחזקת טהרה:"],[10,"לומר","שאם תראה בהם אינה מטמאה מעת לעת לפי שמסולקין דמיה:"],[11,"הנדה","כלומר אשה שרואה דם מטמאה מעת לעת בראיית תחלת נדותה:"],[11,"והזבה ושומרת יום","כלומר והרואה בתוך י\"א בין שרואה ג' ימים דהויא זבה בין שרואה יום אחד דהויא שומרת יום מטמא מעת לעת בראייה ראשונה:"],[11,"היולדת","שיצא דם בפתיחת הקבר מטמאה מעת לעת בראייה ראשונה:"],[12,"חייא בר רב הונא","פי' אמתני' מהדר:"],[12,"בתוך ימי זיבתה","כגון ראתה ג' פעמים מט\"ו לט\"ו אין זה וסת לענין דיה שעתה או לענין שאם לא בדקה תהיה טמאה דמט\"ו לט\"ו הוו ימי זיבה וכן כל הימים מששלמו ז' ימי נדות עד י\"ח דשלמי ימי זיבה בהדי נדות:"],[12,"לא שמיע לי הא שמעתתא","דרב יוסף תלמידו דרב יהודה שהוא תלמיד של רב ושמואל וחלה רב יוסף ונעקר תלמודו וכשהיה שומע מימרא דרב ושמואל ואינו נזכר לאותה שמועה מתמיה ולאו תלמידו של רב יהודה אני ולא אמר לי שמועה זו ואביי תלמידו מזכירו (נדרים דף מא.):"],[13,"את אמרת ניהלן","קודם חולייך:"],[13,"ה\"ג ואהא אמרת ניהלן","על משנה זו אמרת לנו משמיה דאין אשה קובעת לה וסת בימי זיבה:"],[13,"למודה","רגילה:"],[13,"יום ט\"ו","לקמן מפרש ליום ט\"ו לטבילתה:"],[13,"ושינתה","לה וסת ליום כ' פעם אחת:"],[13,"זה וזה אסורין","אין צ\"ל ט\"ו שעבר שאסור שהרי כל היום המתינה שמא תראה דקי\"ל דחייב אדם לפרוש מאשתו סמוך לוסתה ואין צ\"ל יום כ' שראתה בו שהרי נדה היא אלא ה\"ק כשיחזור ויגיע ט\"ו אסורה לשמש שהרי יום וסתה הוא ועדיין לא דילגתו אלא פעם אחת ואין וסת נעקר בפחות מג\"פ וכשיגיע יום כ' לראייה של כ' אסורה לשמש שמא תקבע וסת מכ' לכ' שהרי שינתה פעם אחת ליום כ' וכן פעמים ליום כ' זה וזה אסורין יום ט\"ו ויום כ' הבא אבל ג' פעמים ליום כ' הותר יום ט\"ו ונאסר יום כ':"],[14,"לא שנו","דליום ט\"ו הוי וסת קבוע דליבעי תלתא זימני למיעקריה:"],[14,"אלא","שהיתה רגילה לראות יום ט\"ו לטבילתה לסוף ז' ימי נדה ורואה ליום ט\"ו שהוא יום כ\"ב לראייתה דכבר שלמו ימי זוב לסוף י\"ח והרי ד' ימים שהגיעו ימים שראויה להיות בהם נדה:"],[15,"מקבע לא קבעה","בתוך ימי זיבה דתבעי ג' זימני למיעקריה דבחדא זימנא הוא דעקר לה ואם ישבה ולא בדקה טהורה:"],[15,"מיחש מהו דניחוש לה","אם היתה רגילה מט\"ו לט\"ו דהיינו תוך ימי זוב מי בעיא למיחש ולא תשמש ליום ט\"ו קודם ראייה שמא תראה:"]],[[5,"","לא צריכא לר\"מ. ומועיל מה שהיא בחזקת טהרה שמותרת לשמש כל זמן שלא גירשה א\"נ אינו חייב לגרשה עד שעברו י\"א יום:"],[11,"","והיולדת כולן מטמאות מעת לעת. אע\"ג דמעוברת דיה שעתה היינו בשאר דם שרואה כשהיא מעוברת ולא בראיית דם לידה שרואה מחמת פתיחת הקבר וי\"מ דהכא כרבי יוסי דבעי ג' עונות א\"נ כגון שקודם כבר ראתה פעם אחת וקסבר דבשני מטמאה מעת לעת ולית ליה דיין שעתן כל ימי עיבורן ואשמעינן אע\"ג דראייה שניה זו מחמת אונס לידה ראתה אפ\"ה מטמא מעת לעת הקשה הר\"ר יעקב מאורלייני\"ש דהכא תני דזבה ושומרת יום מטמאה מעת לעת ואפ\"ה מפרש רב יהודה לעיל דכל י\"א יום אינה צריכה בדיקה ובפ\"ק (לעיל נדה דף יא.) אמרי' דאשה שיש לה וסת וד' נשים ואשה שעברו עליה ג' עונות דיין שעתן ותנא התם אע\"פ שאמרו דיין שעתן צריכות להיות בודקות וי\"ל דיש לה וסת איכא למימר כיון דאורח בזמנו בא צריכה בדיקה בשעת וסתה ואהנך נמי איכא למימר דצריכה בדיקה שלא תשתכח תורת בדיקה מהן בתולת דמים כשתראה ומעוברת ומניקה לכשיעברו ימי עיבורה ומניקותה לפי שהורגלו זמן מרובה בלא בדיקה וזקנה אע\"ג דלא אתיא תו לידי בדיקה וליכא למיגזר בה מידי מ\"מ גזר לה אטו אחריני אבל תוך י\"א יום אינה צריכה בדיקה דזמן מועט הוא ולא תשתכח תורת בדיקה דאחר י\"א יום תבדוק וכן זמן מועט יש משבדקה:"],[12,"","רב הונא בר חייא אמר שמואל לומר שאינה קובעת וסת בימי זיבתה. ולא מיבעיא בימי ספירת זיבה ממש דאינה קובעת אלא משמע דאפי' בימים הראוים לזיבה אע\"ג דאינה זבה ומעיינה סתום אינה קובעת כגון שרואה פעם אחת תוך י\"א יום ופליג ארבי יוחנן ור\"ל דאמרי בסמוך אשה קובעת לה וסת תוך ימי זיבתה ממש דהיינו באמצע ספירת זיבתה דומיא דתוך ימי נדותה וכ\"ש דקובעת בימים הראויים לזיבה וקי\"ל כרבי יוחנן לגבי שמואל כדאמר פרק מי שהוציאוהו (עירובין דף מז:):"],[15,"","מקבע לא קבעה ע\"י ראייה זו. של תוך ימי זיבה לא קבעה וסתה שתצטרך לעוקרו על ידי שלש פעמים כאילו קבעה וסת בימי נדה אבל מהו שתחוש ע\"י קביעות של ימי נדה לאסור פעם רביעי אפי' בא הוסת בימי זיבה ואהא מייתי שפיר דחיישינן:"]]],[["ואמר רב יהודה אמר שמואל ל\"ש אלא ט\"ו לטבילתה שהן כ\"ב לראייתה","ושינתה ליום כ\"ז דכי הדרי ואתו עשרין ותרתי קיימא לה בתוך ימי זיבתה וקתני זה וזה אסורין אלמא דחיישינן לה","וקסבר רב פפא עשרין ותרתין מעשרין ותרתין מנינן נדה ופתחה מעשרין וז' מנינן","א\"ל רב הונא בריה דרב יהושע לרב פפא ממאי דלמא עשרין ותרתין נמי מעשרין וז' מנינן דכי הדרי ואתו עשרין ותרתין קיימא לה בתוך ימי נדותה","וה\"נ מסתברא דאי לא תימא הכי האי תרנגולתא דרמיא יומא וכבשה יומא ורמיא יומא וכבשה יומא וכבשה תרי יומי ורמיא חד יומא","כי הדרה נקטה כדלקמיה נקטה או כדמעיקרא נקטה על כרחך כדלקמיה נקטה","א\"ל רב פפא אלא הא דאמר ר\"ל אשה קובעת לה וסת בתוך ימי זיבתה ואין אשה קובעת לה וסת בתוך ימי נדותה ורבי יוחנן אמר אשה קובעת לה וסת בתוך ימי נדותה ה\"ד","לאו כגון דחזאי ריש ירחא וחמשא בירחא וריש ירחא וחמשא בירחא והשתא חזאי בחמשא בירחא ובריש ירחא לא חזאי","וקאמר אשה קובעת לה וסת בתוך ימי נדותה אלמא מריש ירחא מנינא","א\"ל לא הכי א\"ר יוחנן כגון דחזאי ריש ירחא וריש ירחא ועשרין וחמשה בירחא וריש ירחא דאמרינן דמי יתירי הוא דאתוספו בה","וכן כי אתא רבין וכל נחותי ימא אמרוה כרב הונא בריה דרב יהושע","\u0001הדרן עלך בנות כותים\u0002"],[[0,"ואמר רב יהודה","דהאי ט\"ו היינו לטבילה שהוא כ\"ב לראייתה ושינתה לכ\"ז וקתני דכי מטי יום כ\"ב אסורה לשמש. וקס\"ד דהאי כ\"ב לאו לראיית הדילוג קאמר אלא כ\"ב לאותו יום שהיתה ראויה לראות בו ודילגתו דהוי יום י\"ז לראייתה ובתוך ימי זיבה היא לראיית כ\"ז:"],[1,"וקתני אסורה","דכי הדר אתו כ\"ב לחשבון יום שהיתה ראויה לראות בו כשדילגה בה קיימא לה בימי זיבה לחשבון ראייתה כדפרישית. וקסבר רב פפא יום עשרין ותרתין דאסרינן עלה מיום כ\"ב מנינן כלומר לאו כ\"ב לראיית דילוגה שהיה בכ\"ז אלא כ\"ב מיום שהיתה ראויה לראות לימודה. ומדקרי להו רב פפא ימי זיבה קסבר נדה ופתחה ימי נדותה וזובה מעשרין וז' מנינן דהיינו מיום ראיית דילוגה ומיום ראיית כ\"ז עד השתא לא הוו לה י\"ז דאי ליום שראויה לראות כשדילגה מנינן ימי נדות וזוב לא הוה קרי להו ימי זובה דהא חלפו להו כ\"ב מההוא יומא:"],[2,"פתחה","קרי חשבון הנדה לימי הנדה וזוב:"],[3,"ממאי","דהאי יום כ\"ב דאסרינן ליה מנינן מיום כ\"ב שהיתה ראויה לראות כשדילגה דמטי ליה בימי זיבה לחשבון ראייה שראתה בכ\"ז:"],[3,"דלמא","האי יום כ\"ב דאסרינן עלה מנינן מיום ראייתה שכבר שלמו ימי זוב כי הדרי אתו הנך כ\"ב וקיימא לה ד' ימים בימים הראוים לנדות:"],[4,"והכי מסתברא","דהא משום דחיישינן שמא תחזור לקדמותה לראות מכ\"ב לכ\"ב אסרינן לה דהשתא הוי כ\"ב לראייה אבל ליום כ\"ב לחשבון יום שהיתה ראויה לראות לא מצי אסרינן משום הא חששא דאפי' חוזרת לקדמותה לא תראה היום שהוא י\"ז לראייתה דההיא לא היתה למודה לראות אלא לכ\"ב לראייה ואי משום שהוא כ\"ב ליום הראוי לה אין זה דרך החוזרת לוסתה לקצר ימי טהרתה ולמהר ימי ראייתה כדי שיבא לפי חשבון של תחלה אלא חוזרת וקובעת כ\"כ ליום שראתה:"],[4,"דאלת\"ה האי תרנגולתא דרמיא יומא וכבשה יומא ורמיא יומא וכבשה יומא וכבשה תרי יומי ורמיא יומא כי הדרה נקטה כדלקמן נקטה כו'","כלומר תרנגולת הרגילה להטיל ביצה היום ולעמוד למחר ולהטיל יום ג' ולעמוד יום ד' ושינתה וסתה ועמדה מלדת יום ה' עם יום ד' דהוו להו תרי יומי ורמיא יום ששי כי הדרה נקטה אם היא חוזרת למנהגה להטיל יום ולעמוד יום:"],[5,"כדלקמיה נקטה","מעכשיו היא חוזרת למנות כגון שעומדת יום ז' שאחר יום ו' שהטילה ומטלת יום שמיני:"],[5,"או כדמעיקרא נקטה","לפי חשבון שהיתה ראויה להטיל מתחלה שהיתה ראויה לילד בה' ולעמוד בו' ולהטיל בז' ולעמוד בח' השתא מטילה יום ז' עם ו' כנגד ב' ימים שעמדה כדי שתעמוד ביום ח' כפי שהיתה ראויה לחשבון הראשון:"],[5,"על כרחך כדלקמיה נקטה","והא אשה נמי כשחוזרת לוסתה לראות ליום כ\"ב לאו לפי חשבון הראשון אלא ליום כ\"ב לראייתה הלכך האי יומא הוא דאסרינן:"],[6,"א\"ל רב פפא אלא הא דאמר כו' אין אשה קובעת לה וסת תוך ימי נדותה","בימים שהיא נדה כדבעינן לפרושי מילתא דרבי יוחנן דחזאי ריש ירחא וה' בירחא וריש ירחא וה' בירחא והשתא חזאי בה' בירחא דהוו להו ג' זימני בה' בירחא ומעכשיו יהיה לה וסת בה' בחדש. לריש לקיש לא הוה וסת דהא תרי זימני קמאי דה' בירחא הוי תוך ימי נדותה ממש דהא נדה הויא מריש ירחא ופעם ג' הוה ימי נדה לפי חשבון הראוי שהיתה ראויה לראות ריש ירחא ומדקרי לפעם ג' תוך ימי נדה אלמא לפי חשבון הראוי מנינן:"],[9,"א\"ל לא אלא הכי א\"ר יוחנן כגון דחזיא","תרי זימני בריש ירחא ופעם שלישית בכ\"ה ורביעית בר\"ח דה\"ל הך ראייתה בתרייתא שהיא שלישית לראייה של ר\"ח בתוך ימי נדותה ממש שהיא נדה מיום כ\"ה ומש\"ה קרי להו תוך ימי נדותה דהא נדה היא. וטעמא מאי הוי קביעות הא אורחה בהכי שנפתח מעיינה משום דאמר הך ראייה דראש חדש ראיית וסתה היא והיום זמנה והאי דאקדים וחזאי בכ\"ה דמים יתירי איתוספו בה:"],[10,"אמרוה","להא דרבי יוחנן:"],[10,"כרב הונא","וכדמתרצינן:"]],[[8,"","אלמא מריש ירחא מנינן. וא\"ת דילמא משום ראיה ראשונה קרי ליה תוך ימי נדה ופרש\"י דדייק מדקאמר קובעת תוך ימי נדותה משמע דפעם ג' דהוא הקביעות הוי כימי נדתה אלמא חשיב כאילו ראתה ריש ירחא והקשה לו ריב\"א דלמה לא תירץ לו כגון שראתה ריש ירחא וה' בירחא שלשה זימני דהשתא הוי ממש תוך ימי נדתה וקבעה וסת ודיה שעתה אם תראה בחמשא בירחא של חדש ד' או שצריכה לפרוש מבעלה כל ה' בירחא עד שתעקור וסתה ג' פעמים והשיבו רש\"י משום דבפ\"ק (לעיל נדה דף יא.) מוקמינן דר' יוחנן במעיין סתום משום דפריך אמתניתין דהתם דקתני דבימי נדתה אינה צריכה בדיקה ולבדוק דלמא קבעה לה וסת כרבי יוחנן ולכך המקשה אוקי הכא מילתיה דר' יוחנן במעיין סתום שראתה בג' ה' בירחא ולא בריש ירחא דראייה שלישית היא ממעיין סתום ומתניתין דפ\"ק (שם דף יא.) כגון שראתה תרי זימני ריש ירחא וה' בירחא ובשלישית כי ראתה ריש ירחא לא תבדוק בה' בירחא שאפילו תראה לא קבעי' לה וסת דמעיין פתוח הוא אבל פעם ראשונה ושניה בודקת בימי נדה שמא תראה בג' בה' בירחא ולא בריש ירחא ולהכי לא הוה מצי לשנויי כגון דראתה ג' זימני ריש ירחא וה' בירחא דא\"כ הוה ליה מעיין פתוח אלא משני כגון שראתה תרי זימני ריש ירחא לחוד דהוי מעיין סתום ובג' נמי אע\"ג דכבר ראתה בכ\"ה מה שראתה בריש ירחא חשיב מעיין סתום כדמשני דהא דחזאי בכ\"ה דמים יתרים הוא דאתוספו בה ועוד נראה לפרש דהכא דייק דחשיב כאילו ראתה בג' בריש ירחא דאי לאו הכי אמאי קבעה לה וסת הלא ראיה זו אינה מעין האחרות שבאו בימי נדותה ומיהו תימה לומר כיון כדמעיקרא נקטה וחשיב כאילו ראתה ריש ירחא כיון דאכתי לא קבעה לה וסת בריש ירחא דלא דמי לההיא דלעיל דכבר קביע לה וסת לכ\"ב כדקאמר היתה למודה לראות ונראה לפרש דמיירי כגון שראתה ג' זמני בריש ירחא וה' בירחא ואין לחוש אם אין הש\"ס מזכיר תלתא זימני דה\"נ בפ\"ק (שם דף יא.) לא קאמר תלתא זימני גבי קפצה וראתה והא דנקט והשתא חזאי בה' בירחא ובריש ירחא לא חזאי לאו משום דע\"י ראייה זו השתא קבעה לה וסת דהא קבעה לה כבר מג' זימני קמאי אלא לומר לך שדיה שעתה בראייה זו כדרבי דוסא דאמר בפ\"ק (לעיל נדה דף ד:) דאין דיה שעתה אלא בשעת וסת דוקא ומיהו אף בלא ראתה השתא הוה מצי למימר דקבעה לה וסת לענין שאסורה בה' בירחא עד שתעקור הוסת ג' פעמים והשתא מוכח אע\"ג דברביעי לא חזאי ריש ירחא קבעה לה וסת בה' בירחא משום דכיון שראתה ג' זימנין ה' בירחא גם בחדש ד' חשוב כאילו ראתה ריש ירחא וה\"נ כ\"ב מכ\"ב מנינן והוי מצי למימר וליטעמיך דאוקמית מילתיה דר' יוחנן במעין פתוח א\"כ תקשה מתני' דפ\"ק (שם דף יא.) דקתני דאינה בודקת בימי נדה א\"נ הא חשיב מעיין סתום ומעיין פתוח יפרש כמו שפירש\"י בלשון שני בפ\"ק (שם יא.) שראתה אבג\"ד ובהכי איירי מתני דהתם דבהכי לא קבעה לה וסתה:"]]],[["מתני׳ \u0001יוצא\u0002 דופן אין יושבין עליו ימי טומאה וימי טהרה ואין חייבין עליו קרבן ר\"ש אומר הרי זה כילוד","כל הנשים מטמאות בבית החיצון שנאמר (ויקרא טו, יט) דם יהיה זובה בבשרה אבל הזב ובעל קרי אינן מטמאין עד שתצא טומאתן לחוץ","היה אוכל בתרומה והרגיש שנזדעזעו אבריו אוחז באמה ובולע את התרומה ומטמאין בכל שהוא אפילו כעין החרדל ובפחות מכן","\u0001גמ׳\u0002 א\"ר מני בר פטיש מאי טעמייהו דרבנן אמר קרא (ויקרא יב, ב) אשה כי תזריע וילדה זכר עד שתלד במקום שהיא מזרעת","ור\"ש ההיא דאפילו לא ילדה אלא כעין שהזריעה אמו טמאה לידה","ור\"ש מאי טעמיה אמר ר\"ל אמר קרא תלד לרבות יוצא דופן","ורבנן האי מבעי ליה לרבות טומטום ואנדרוגינוס דסלקא דעתך אמינא זכר ונקבה כתיב זכר ודאי נקבה ודאית ולא טומטום ואנדרוגינוס קמ\"ל","ורבי שמעון נפקא ליה מדתני בר ליואי דתני בר ליואי לבן לבן מכל מקום לבת לבת מ\"מ","ורבנן האי מבעי ליה לחייב על כל בן ובן ולחייב על כל בת ובת","ורבי שמעון נפקא ליה מדתני תנא קמיה דרב ששת (ויקרא יב, ז) זאת תורת היולדת מלמד שמביאה קרבן אחד על ולדות הרבה יכול תביא על לידה ועל זיבה כאחת","אלא יולדת דאכלה דם ויולדת דאכלה חלב בחד קרבן תסגי לה","אלא יכול תביא על לידה שלפני מלאת ועל לידה שלאחר מלאת כאחת ת\"ל זאת ורבנן אע\"ג דכתיב זאת איצטריך לבן או לבת","סד\"א בתרי עיבורי (דחד הוי נפל) אבל בחד עבורא כגון יהודה וחזקיה בני ר' חייא אימר בחד קרבן סגי לה קמ\"ל","א\"ר יוחנן ומודה רבי שמעון בקדשים שאינו קדוש מאי טעמא גמר לידה לידה מבכור מה התם פטר רחם אף כאן פטר רחם","ולגמר לידה לידה מאדם מה התם יוצא דופן אף כאן יוצא דופן","מסתברא מבכור הוה ליה למילף שכן אמו מאמו אדרבה מאדם הוה ליה למילף שכן פשוט מפשוט","אלא מבכור הוה ליה למילף שכן אם בהמת קדשים פגול נותר וטמא","אדרבה מאדם הוה ליה למילף שכן פשוט זכר קדוש במתנה הנך נפישן","אמר רב חייא בריה דרב הונא משמיה דרבא תניא דמסייע ליה לר' יוחנן ר' יהודה אומר (ויקרא ו, ב) זאת תורת העולה היא העולה הרי אלו ג' מיעוטין"],[[0,"מתני' יוצא דופן","על ידי סם נפתחו מעיה והוציאו את העובר לחוץ ונתרפאת:"],[1,"כל הנשים","לענין נדה:"],[1,"מטמאות","מכי אתא דם לבית החיצון אע\"ג דהעמידוהו כותלי רחמה:"],[1,"בבשרה","משמע בתוך בשרה:"],[1,"לחוץ","בגמרא יליף לה:"],[2,"שנזדעזעו אבריו","נעקר שכבת זרע מגופו:"],[4,"גמ' אלא כעין שהזריעה","כגון נימוק הולד כדאמר בהמפלת (לעיל נדה כו.) שליא בבית הבית טמא כו' רבי שמעון אומר הולד נימוק ואמר בגמרא מודה רבי שמעון שאמו טמאה לידה ויליף טעמא מהכא אבל רבנן לא צריך להו קרא להכי דהא לדידהו כיון דאמרי הבית טמא לית להו נימוק ופשיטא דאמו טמאה לידה:"],[5,"תלד","ואם נקבה תלד דמצי למכתב ואם נקבה וטמאה שבועים:"],[8,"לחייב על כל בן ובן","שאם טבלה לאחר י\"ד לנקבה ושמשה ונתעברה וילדה לאחר שמונים מביאה שני קרבנות:"],[9,"תורת היולדת","משמע תורה אחת ליולדת ולדות הרבה:"],[11,"שלפני מלאת","ילדה עכשיו וילדה לאחר שמונים קמא הוי לפני מלאת ובתרא הוי לאחר מלאת:"],[11,"זאת","משמע כמו שמפורש בענין קרבן אחד לולד אחד:"],[11,"הני מילי","דאין מביאה על שלפני מלאת ולאחר מלאת קרבן אחד:"],[12,"בתרי עיבורי","שילדה וחזרה ונתעברה בתוך ימי טוהר וילדה לאחר שמונים:"],[12,"כגון יהודה וחזקיה","דאמרינן בהמפלת (לעיל נדה כז.) שנשתהא אחרון אחר הראשון ג' חדשים:"],[13,"מודה ר\"ש","ביוצא דופן:"],[13,"שאינו קדוש","קדושת הגוף אלא כשאר קדשים שקדם מומן להקדשן דלא קדשי אלא כעצים וכאבנים לדמיהם ויוצאין לחולין ליגזוז וליעבד:"],[13,"לידה לידה","כתיב בקדשים (ויקרא כ״ב:כ״ז) שור או כשב או עז כי יולד וכתיב בבכור (דברים ט״ו:י״ט) אשר יולד:"],[14,"מאדם","לענין טומאה וטהרה דכתיב וילדה זכר:"],[15,"אמו מאמו","בבכור כתיב (שמות כב) שבעת ימים יהיה עם אמו ובקדשים כתיב (ויקרא כב) והיה שבעת ימים תחת אמו:"],[16,"שכן אם בהמת קדשים פיגול נותר וטמא","אם בתרוייהו כתיב אמו ותרוייהו בהמת קדשים ופגול ונותר וטמא נוהג בהם לאפוקי אדם דליתיה בכל הני:"],[17,"פשוט","אדם משתעי בין בפשוט בין בבכור וכן קדשים הוו פשוטים. ובין באדם ובין בקדשים לא משתעו בזכרים לחודייהו טפי מבנקבות לאפוקי בכור דליתיה אלא בזכרים. ותרוייהו בין אדם בין קדשים לא הוו קדושין מאליהם אבל בכור קדושתו מאליו. ובין קדשים ובין אדם לא הוו מתנות כהונה כגון שלמים לבעלים הן לאפוקי בכור דהוי ממתנות כהונה:"],[18,"דמסייע ליה לרבי יוחנן","דאמר דמודה ר\"ש ביוצא דופן דקדשים:"],[18,"זאת תורת העולה היא העולה","ומהאי קרא נפקא לן בזבחים (דף כז:) פסולין שאם עלו לא ירדו דכתיב על מוקדה משתעלה תוקד וכתב רחמנא זאת דמשמע מיעוטא כלומר זאת אם עלתה לא תרד אבל אחרת אע\"פ שעלתה תרד וכתיב היא דמשמע מיעוטא וכתיב העולה דמשמע העולה עולה כשרה ולא פסולה. והני תלתא מיעוטי ממעטי הני תלתא פסולי:"]],[[0,"","מתני' יוצא דופן. ממקום שמזרעת. ואם תאמר למה לי קרא נילף לידה לידה מבכור כדילפינן לענין קדשים בסמוך וי\"ל דאי לאו קרא הוה דרשינן מתלד לרבות יוצא דופן כדדריש ר\"ש:"],[4,"","כעין שהזריעה. פרש\"י ולרבנן לא צריך קרא דהא סברי בהמפלת (לעיל נדה כו.) דרובן אינם נימוקים ומיהו איצטריך להיכא דהושיטה חיה ידה במעי אשה ומעכב את הולד דטמאה לרבנן וי\"ל דתרתי ש\"מ:"],[13,"","מודה ר\"ש בקדשים שאינו קדוש. בפ' בתרא דבכורות (דף נז:) גבי ר\"א ברבי יהודה דאית ליה יוצא דופן קדוש אמר סבר לה כר\"ש דאמר יוצא דופן ולד מעליא הוא ותימה דהא ר\"ש מודה דבקדשים אינו קדוש כדאמר רבי יוחנן הכא וכדמוכח נמי בברייתא דמייתי בסמוך וי\"ל דסבר כר\"ש ועדיפא מדר\"ש דאפילו בקדשים קאמר דקדוש:"],[13,"","גמר לידה לידה מבכור. בפ' ולד חטאת (מעילה דף יג.) במעילה גבי ולד המעושרת לא ינק מן המעושרת יליף אמו אמו מבכור והכל אחד כדמוכח בשמעתין וא\"ת דבפרק מרובה (ב\"ק דף עז:) אמר כל מקום שנאמר שה אינו אלא להוציא את הכלאים וקאמר למעוטי מאי אי למעוטי קדשים בהדיא כתיב בהו או כשב פרט לכלאים אם למעשר תחת תחת יליף מקדשים ואי לבכור העברה העברה יליף ממעשר והשתא אמאי אצטריך למילף בכור ממעשר ומעשר גופיה ילפינן מקדשים הוה ליה למימר דנילף בכור לידה לידה או אמו אמו מקדשים וי\"ל דלא ילפינן לידה לידה או אמו אמו אלא כגון הכא דאיירי בלידה או במעילה דאיירי בענין אמהות וא\"ת ובשמעתין אמאי צריך ג\"ש דלידה לידה או אמו אמו נילף פסול יוצא דופן בקדשים מג\"ש דתחת ממעשר ומעשר מג\"ש דהעברה מבכור וי\"ל דג\"ש דלידה ודאמו צריך לשום דרשה אחריתי:"],[17,"","הנך נפישין. וא\"ת דבפרק יש בכור (בכורות דף מז:) אר\"ש דיוצא דופן בכור לנחלה הוי דיליף מוילדו לו בנים לידה לידה מאשה דאית ליה הכא דהוי ולד והשתא לילף מבכור בהמה שכן בכור זכר (מתנות) וי\"ל דאדם מאדם עדיף שכן אין שייך בהו פגול נותר וטמא דאינו קדשים ושייך בהו טומאה וטהרה ובפרק ראשית הגז (חולין דף קלז.) דקאמר פשוט מפשוט עדיף אע\"ג דהנהו נפישי התם משום דהוי בהמה מבהמה אבל הכא דבהמה מאדם לא:"],[18,"","זאת היא העולה. הכי כתיב קרא זאת תורת העולה היא העולה הרי ג' מיעוטי זאת והיא וה' דהעולה תנינא דהעולה קמא דריש רבא בתמיד נשחט (פסחים נח:) העולה עולה ראשונה מהני ג' מיעוטי ממעט הנך ומתורת מרבינן אינך פסולין דאם עלו לא ירדו כר\"ש וא\"ת והא ר' יהודה סבר בפ\"ק דזבחים (דף כד) דרצפה מקדשת כמזבח ואם כן כולם יעלו והיכי משכחת פסול בכל הנהו לבר מהני ג' כיון דאם עלו לא ירדו וי\"ל כגון שיש הפסק בין הבהמה לרצפת עזרה ואם תאמר והיכי ממעט הני ג' פסולי הא צריך חד מיעוט לרובע ונרבע ולכל הנהו דמודה רבי שמעון בהו דאם עלו ירדו וי\"ל דנשחטה בלילה ויצא דמה ממעט תרוייהו מחד מיעוטא דשקולים הם וא\"ת קדשי קדשים ששחטן בדרום דאמר בריש מעילה (דף ב:) דאליבא דר' יהודה כ\"ע ל\"פ דתרד אמאי הא ליכא מיעוטא רביעית ולר\"ש נמי לרבא דאמר תרד הא פסולן בקדש הוא דהא אית ליה הכשר בקדשים קלים דכשרים בדרום כמו שאפרש דהיכא דאית ליה הכשר בעלמא איקרו פסולן בקדש וי\"ל דשחיטה בדרום הוי כעין שחיטת חוץ וכמו דחנקינהו דמי כדקאמר התם לר\"ש:"]]],[["פרט לנשחטה בלילה ושנשפך דמה ושיצא דמה חוץ לקלעים שאם עלתה תרד","רבי שמעון אומר עולה אין לי אלא עולה כשרה מנין לרבות שנשחטה בלילה ושנשפך דמה ושיצא דמה חוץ לקלעים והלן והיוצא והטמא והנותר ושנשחט חוץ לזמנו וחוץ למקומו","ושקבלו פסולין וזרקו את דמן והנתנין למעלה שנתנן למטה והנתנין למטה שנתנן למעלה והנתנין בחוץ שנתנן בפנים והנתנין בפנים שנתנן בחוץ והפסח והחטאת ששחטן שלא לשמן מנין","ת\"ל (ויקרא ו, ב) זאת תורת העולה ריבה תורה אחת לכל העולין שאם עלו לא ירדו","יכול שאני מרבה את הרובע והנרבע והמוקצה והנעבד ואתנן והמחיר והכלאים והטרפה ויוצא דופן ת\"ל זאת","ומה ראית לרבות את אלו ולהוציא את אלו"],[[1,"שנשחטה בלילה ושנשפך דמה","לארץ ולא נזרק:"],[1,"ושיצא דמה חוץ לקלעים","אבל כל הנך פסולי אחריני דמכשר בהו רבי שמעון כגון לן ויוצא שיצא הבשר קודם זריקת דם וטמא ושנשחט לאוכלו חוץ לזמנו וחוץ למקומו כולן מודה נמי רבי יהודה דלא ירדו וטעמא מפרש רבי יהודה במסכת זבחים בפרק המזבח מקדש (זבחים דף פד:) מפני מה אמרו לן בדם כשר שהרי לן כשר בבשר וכן כולן:"],[1,"והלן","דם הלן:"],[1,"והיוצא","בשר עולה שיצא והכניסה והעלה:"],[1,"והנותר","בשר שנתותר חוץ לזמנו והקטירו:"],[1,"ושנשחט","על מנת לאוכלו חוץ לזמנו דהוי פגול:"],[2,"ושקבלו פסולין את דמו וזרקוהו","כגון בעל מום או שאר פסולין. ולהכי נקט קבלו פסולין ולא נקט ששחטוהו פסולין שהשחיטה כשרה בפסולין כדתנן (זבחים דף לא:) כל הפסולין ששחטו שחיטתן כשרה:"],[2,"והנתנין למעלה","מחוט הסיקרא דקי\"ל חטאת בהמה למעלה דכתיב בה קרנות ועולה למטה:"],[2,"הנתנין בפנים","על מזבח הפנימי כגון פר העלם דבר ופר כהן משיח:"],[2,"והחטאת ששחטו שלא לשמן","להכי נקט פסח והחטאת דקיימא לן (זבחים דף ב.) כל הזבחים שנזבחו שלא לשמן כשרין חוץ מפסח וחטאת:"],[4,"הרובע והנרבע מוקצה ונעבד","פסולין ליקרב כדיליף לקמן בשמעתין:"],[4,"מוקצה","שיחדו לצורך תקרובת עבודת כוכבים:"],[4,"ונעבד","שהשתחוה לו:"],[4,"כלאים","פסולין לקרבן שנאמר (ויקרא כ״ב:כ״ז) שור או כשב פרט לכלאים:"]],[[0,"","פרט לנשחטה בלילה. בפרק המזבח מקדש (זבחים דף פד:) מפרש טעמא אמאי מודה רבי יהודה בהנך דלא ירדו טפי מהני ג' וקאמר לן בדם כשר שכן לן באימורין כשר שהרי לן כשר בבשר לכתחלה דנאכל לשני ימים ולילה אחד יוצא כשר שהרי יוצא כשר בבמה וטמא דחזי לעבודת צבור חוץ לזמנו שהרי מרצה בפגולו חוץ למקומו איתקש לחוץ לזמנו קבלו פסולין וזרקו בהנך פסולים דחזו לעבודת צבור ואם תאמר נשחטה בלילה ויצא דמה נמי ליתכשרו דאין לילה ויוצא פסול בבמה כדאמר בפרק פרת חטאת (זבחים דף קכ.) וכן קבלו פסולין דלא מכשר אלא בהנך דחזו לעבודת צבור אבל זר לא דהא כשר בבמה וכן חוץ למקומו מה צריך לטעמא דאיתקש לחוץ לזמנו תיפוק ליה דכשר בבמה מיהו רש\"י פי' בהמזבח מקדש (שם פד:) דיוצא דכשר הוא דילפינן מבמה אבל הכשר דם דחמיר לא ילפינן מבמה אם לא נמצא לן הכשר בפנים אך קשה אמאי אצטריך למילף לן בדם מאימורין ואימורין מלן דבשר ופשיט מיניה באיזה מקומן (שם דף נא) דגמרי בנין אב מבנין אב לילף חד בנין אב לן בדם מלן דבשר וכ\"ת דלא בעי למילף דם מבשר שאינו קרב אלא ילפינן מאימורין דקרבי ואימורין מבשר משום דהוי בשר מבשר מכל מקום תימה דנילף לן דמה שנפסל בשקיעת החמה דאם עלו לא ירדו מאימורין שלנו בלא מזבח בשקיעת החמה דלא מיפסלי בשקיעת החמה דמצותן כל הלילה וכיון דלן דם בשקיעת החמה אע\"ג דמיפסל לא ירד מעתה גם לן בעמוד השחר לא ירד דאין חילוק ותדע דהא לן שתי לילות לא ירד אע\"ג דאין כיוצא בו כשר ואפילו בבשר על כן י\"ל דפסול דם לא ילפינן מאימורין שכשרים לכתחלה כל הלילה משום דאיכא תרתי חדא דהוי דם מבשר ועוד דהוי פסול מהכשרו בכך ולהכי נמי גבי דם לא ילפינן מבמה דאיכא נמי תרי שנויי פנים מחוץ ופסול מהכשרו בכך אבל יוצא דבשר לא חמיר וילפינן מבמה דמים הנתנין למטה שנתנן למעלה או איפכא וכן הנתנין בפנים שנתנן בחוץ כיון דכל אחד כשר בחבירו לא תרד דדם מדם בפנים ילפינן [פסול] מהכשרו ומיהו תימה יצא דמה חוץ לקלעים אמאי תרד לר\"י נילף יצא דם מאימורין שיצאו ואימורים שיצאו מבמה או מבשר שלמים שיצא חוץ לקלעים דכשר וכיון דיצא חוץ לקלעים לא ירד הוא הדין אפילו חוץ לחומה דאין חילוק כדפירשתי לעיל וא\"ת דבפרק חטאת העוף (זבחים דף סח:) גבי זר וסכין מטמאין בגדים בבית הבליעה פריך מאי שנא שמאל דהכשירו ביום הכפורים ולילה באברין ופדרים זר נמי נילף מבמה דתניא מנין ליוצא שהוא כשר שהרי כשר בבמה ומאי פריך הא דווקא בשר ילפינן מבמה לההוא תנא ולא דם כדפרישית ותו בשמאל ולילה דהוא עבודת דם היכי יליף מהכשרו בכך וי\"ל דההיא סוגיא כר\"ש דמכשיר אפילו נשחטה בלילה ויצא דמה ואפילו דם יליף מהכשרו מבמה ומבשר ונשפך דמה לפי שכבר נעשה השחיטה בהכשר או גם הקבלה כמו שאפרש ותדע דההיא כרבי שמעון דבמשנה דהתם קאמר כל שפסולו בקדש אין מטמא בגדים בבית הבליעה וכל שאין פסולו בקדש מטמא ורבי שמעון נמי בשמעתין קאמר כל שפסולו בקדש אם עלו לא ירדו והכי פריך והתניא יוצא כשר שהרי כשר בבמה וכמו דיליף ר' יהודה אימורין מבמה ה\"נ לילף לר\"ש פסול דם מבמה ומיהו לר\"ת דגרסינן פ\"ב דזבחים (דף כד:) והתניא מלק בשמאל פסול ול\"ג זרק בשמאל דלא מצינו משנה זו בשום מקום ומשני פליגי בברייתא ור\"ש מכשיר ההיא דפ' חטאת העוף (זבחים דף סח:) לא אתיא כר\"ש דלדידיה מלק בשמאל כשר אלא תנא אחר הוא וסבר לה כר' שמעון ובמלק בשמאל לא סבר ליה כוותיה:"],[0,"","ושנשפך דמה. נראה דלרבי יהודה תרד אפילו נתקבלה ואח\"כ נשפך דומיא דיצא דמה דהוי אפילו נתקבל דאי ביצא קודם שנתקבל כגון שיצא מן הצואר לחוץ אם כן היינו נשפך דמה דאין כלי שרת מקדש אלא בפנים כדאמר בהמזבח מקדש (שם פח.):"],[1,"","הלן. היינו לן דדם והנותר היינו לן דאימורין דאילו בשר אפילו אינו נותר ירד דכל שממנו לאשים הרי הוא בבל תקטירו:"],[1,"","חוץ למקומו. ור' יהודה נמי לא פליג אלא בג' דלעיל וקשה דבפרק התודה (מנחות דף עט.) אמרינן חטאת ששחטה חוץ למקומה רבא אומר תרד רבה אומר לא תרד והדר ביה רבה לגבי רבא והתם אתי כרבי יהודה דקתני התם אמר רבי יהודה לא נחלקו על חוץ לזמנו שקדש הלחם על מה נחלקו על חוץ למקומו רבי אליעזר אומר קדש רבי יהושע אומר לא קדש והדר ביה רבי אליעזר לגבי רבי יהושע ויש לומר דהתם רבי יהודה אליבא דרבי יהושע קאמר דלא מקיש חוץ למקומו לחוץ לזמנו אבל רבי יהודה גופיה מקיש דקאמר בהמזבח מקדש (זבחים פד:) טעמא דחוץ למקומו דלא ירדו משום דאיתקש לחוץ לזמנו:"],[2,"","והנתנין למעלה שנתנן למטה. אפילו רבי יהודה מודה דלא ירדו דדם מדם בפנים יליף שפיר מהכשרו בכך כדפירשתי לעיל והכי נמי אמר בפ\"ב דזבחים (דף כז:) קתני מיהא הנתנין למעלה שנתנן למטה ולא פליג רבי יהודה וקשה דאמר בריש מעילה קדשי קדשים ששחטן בדרום מהו שירדו אליבא דר' יהודה פשיטא דירדו כי תבעי לך אליבא דר' שמעון מאי רב יוסף אמר לא ירדו רבה אמר עד כאן לא קאמר ר\"ש התם דלא ירדו אלא בנתנין למטה שנתנן למעלה למעלה שנתנן למטה ולעולם ששחטן וקבל דמן בצפון אבל הכא ששחטן בדרום אף ר\"ש מודה דירדו דכחנקינהו דמי והשתא אמאי נקט הנתנין למעלה שנתנן למטה טפי מאחריני אדרבה הוה ליה למנקט נשחטין בלילה ונשפך דמה אע\"ג דפליג אדרבי יהודה ואמר דלא ירדו היינו משום ששחטן בצפון אלא יש לומר דנקט הנתנים למעלה שנתנן למטה משום דמינה מייתי רב יוסף דנתנין למעלה משמע ליה דהוי בכלל עולת העוף שדינה למעלה ומלקה ומצה דמה למטה וכי היכי דהתם לא ירדו אע\"פ שהמליקה לא היתה במקומה הכי נמי קדשי קדשים שנשחטו בדרום ורבה אומר הנתנין למעלה שנתנן למטה איירי דווקא בזבחים ולכך לא ירדו ששחיטה וקבלה היתה כדינה בצפון אבל שחיטת דרום וכן מליקת עולת העוף למטה לא אם כן לרב יוסף דהוי בכלל הנתנים למעלה עולת העוף פליג רבי יהודה כדאמר התם דבשחיטת דרום אליבא דרבי יהודה פשיטא דירדו ובפ\"ב דזבחים (דף כז:) אמר דלא פליג רבי יהודה וי\"ל דכיון דבזבחים מיהא מודה רבי יהודה דלא ירדו שייך שפיר למימר לא פליג רבי יהודה כמו בקבלו פסולין וזרקו דקאמר נמי התם דלא פליג אע\"ג דרבי יהודה לא מודה אלא בהנך דחזו לעבודת צבור ור\"ש אפילו בהנך דלא חזו לעבודת צבור קאמר דלא ירדו דלא גרע מנשפך דמה שלא נזרק כלל דלא ירדו לר\"ש ומיהו אין ראיה דמצינן למימר דאף לרבי שמעון בהנך דלא חזו לעבודת צבור כגון זר אם קיבל דם ירדו כיון דלא מצינו בעלמא הכשר בפנים ומבמה לא ילפינן עבודת דם אף לר\"ש ונשחטה בלילה דלא ירד לרבי שמעון היינו משום דילפינן מאימורין ונשפך הדם נמי דלא ירד לרבי שמעון דווקא שנשפך אחר שכבר נתקבל אבל נשפך מן הצואר ירד דמשום שחיטה לבדה שנעשית בהכשר לא מיקרי פסולו בקדש וקבלו פסולין בהנך דווקא דחזו לעבודת ציבור אף לר\"ש ולא הוי פירוש קבלו או זרקו דאם כן פליג אר' יהודה דהא לרבי שמעון אפילו זרקו הנך דלא חזו לעבודת צבור לא ירדו דלא גרע מנשפך אלא פי' קבלו וזרקו אותו דם עצמו מכל מקום בלא ראיה יש לומר דשייך שפיר דלא פליג רבי יהודה כיון דמודה בזבחים וכן משמע בריש מעילה דמשום שחיטה לבדה שנעשה בהכשר לא חשיב פסולו בקדש אף לרבי שמעון דפריך רב יוסף לרבה מדתניא בפרק דם חטאת העוף בזבחים (דף סו:) וכולן אין מטמאין בבית הבליעה וקתני לעיל עולת העוף שעשאה כמעשה החטאת ותנן התם (דף סח:) כל שפסולו בקדש אינו מטמא וה\"ה דלא ירדו ומאי פריך הא התם מוכח בזבחים דעולת העוף שעשאה כמעשה חטאת היינו שהמיצוי עשה למטה אבל המליקה היתה במקומה אלא ודאי רבה דאמר ירדו אפילו שחט בצפון וקבל בדרום דמשום שחיטה גרידא לא מקרי פסולו בקדש אף לרבי שמעון ומיהו יש לדחות דבשחט בצפון מודה רבה דלא ירדו ופריך ליה רב יוסף משום שהמיצוי הוי כמו השחיטה שממצה ומוציא דם מן העוף כמו שעושה בשחיטה ואע\"פ שמלק למעלה כיון שמיצה למטה הוי כשחט בדרום:"]]],[["אחר שריבה הכתוב ומיעט אמרת מרבה אני את אלו שהיה פסולן בקדש ומוציא אני את אלו שלא היה פסולן בקדש","קתני מיהת יוצא דופן דלא מאי לאו יוצא דופן דקדשים אמר רב הונא בריה דרב נתן לא יוצא דופן דבכור","בכור מפטר רחם נפקא","אלא מאי דקדשים מאמו אמו נפקא","האי מאי אי אמרת בשלמא דקדשים היינו דאצריכי תרי קראי חד לבהמת חולין דאוליד דרך דופן ואקדשה","וחד לבהמת קדשים דאוליד דרך דופן וקסבר ולדות קדשים בהוייתן הן קדושים אלא אי אמרת דבכור מפטר רחם נפקא","הכי נמי מסתברא מדקתני הרובע והנרבע והמוקצה והנעבד והכלאים","הני מהכא נפקא מהתם נפקא (ויקרא א, ב) מן הבהמה להוציא הרובע והנרבע מן הבקר להוציא את הנעבד מן הצאן להוציא את המוקצה ומן הצאן להוציא את הנוגח","ותו כלאים מהכא נפקא מהתם נפקא (ויקרא כב, כז) שור או כשב או עז שור פרט לכלאים או עז פרט לנדמה","אלא אצטריכו תרי קראי חד לבהמת חולין וחד לבהמת קדשים הכא נמי איצטריך תרי קראי","ת\"ר המקשה שלשה ימים ויצא ולד דרך דופן הרי זו יולדת בזוב ורבי שמעון אומר אין זו יולדת בזוב ודם היוצא משם טמא ורבי שמעון מטהר","בשלמא רישא רבי שמעון לטעמיה ורבנן לטעמייהו אלא סיפא במאי פליגי אמר רבינא כגון שיצא ולד דרך דופן"],[[0,"אחר שריבה הכתוב ומיעט אמרת כו'","הואיל וכתוב אחד ריבה וכתוב אחד מיעט מעתה יש לך לילך אחר אומד הדעת:"],[0,"מרבה אני את אלו שהיה פסולן בקדש","שלאחר שבאו לעזרה אירע פסולן:"],[2,"מפטר רחם נפקא","דלא קדיש וכיון דחולין הוא למה לי למעוטי פשיטא אם עלה ירד:"],[3,"מאמו אמו נפקא","נמי דלא קדיש דגמר מבכור:"],[4,"תרי קראי","אמו אמו וזאת:"],[4,"חד לבהמה דחולין ואוליד דרך דופן ואקדשיה","ושמעינן מאמו אמו דלא קדיש וחד לבהמה דקדשים דעל כרחך ולד היוצא ממנה קדוש מאליו ואיצטריך למעוטי מזאת דאע\"ג דקדיש אם עלה ירד הואיל ולא היה פסולו בקדש:"],[5,"וקסבר ולדות קדשים בהוייתן הן קדושין","נראה בעיני דלא גרסי' ליה ופירוש משובש הוא דכל שכן למאן דאמר משעת יצירה הן קדושים דהיינו במעי אמו דאיצטריך למעוטי מזאת:"],[6,"הכי נמי מסתברא","דכל הני פסולין דהכא בבהמות קדשים קאמר. ורובע ונרבע כגון שהקדישן ולבסוף נרבעו. ומוקצה ונעבד נמי בקדשים קלים ואליבא דרבי יוסי הגלילי דאמר ממון בעלים הן ויכול לאוסרן והכי נמי מוקמינן בפרק בתרא דזבחים (דף קיד.). ואתנן ומחיר כשנתן לה עובר בהמת קדשים קלים באתנן וקסבר בהוייתן הם קדושים ולא קודם לכן לפיכך איסור אתנן ומחיר חל עליהם וקדושה דממילא נמי חיילא עלייהו והרי הם קדושים. וכלאים וטרפה ויוצא דופן נמי בולדות קדשים:"],[6,"הכי נמי מסתברא","דבקדשים קאי ותרי קראי איצטריכא ליה כדאמר מדקתני הרובע והנרבע וקא ממעט להו מהאי קרא וכי מהכא נפקא מהתם נפקא:"],[7,"מן הבהמה","אדם כי יקריב מכם מן הבהמה ולא כל בהמה להוציא את הרובע והנרבע:"],[7,"נוגח","שהמית את האדם. והאי רובע ונרבע ונוגח דקתני כגון על פי עד אחד או על פי הבעלים דמודה בקנס פטור הלכך להדיוט שרי ולגבוה אסור אבל ע\"פ שני עדים בסקילה הוא ולהדיוט נמי אסור:"],[8,"כלאים","מן העז ומן הכבש:"],[8,"נדמה","אביו ואמו מן העז והוא כבש. וכיון דנפקי מהתם דלא קדש למה לי למעוטי מהכא דירדו הא חולין נינהו:"],[9,"לבהמה דחולין","ואקדשה:"],[10,"המקשה ג' ימים","בימי זיבה וראתה דם כל שלשה דרך רחם:"],[10,"ויצא ולד דרך דופן הרי זו יולדת בזוב","כלומר זבה היא דכי טיהר רחמנא מזיבה דם הקושי הני מילי בלידה מעלייתא אבל דרך דופן לאו לידה היא:"],[10,"אין זו יולדת בזוב","ור\"ש לטעמיה דאמר יוצא דופן ולד מעליא הוא ומטהר את קישויו:"],[10,"ודם היוצא משם","לקמן מפרש מאי קאמר:"],[11,"ר\"ש לטעמיה","דאמר במתניתין יושבין עליו ימי טומאה אפילו בלידה יבשתא וימי טהרה אלמא ולד הוא הלכך לענין קושי נמי ולד הוא ומטהר את קישויו:"],[11,"אלא סיפא במאי פליגי","הא ליכא למימר דם היוצא עמו דרך דופן יהיה טמא כדם הלידה דאם כן איפכא מבעי ליה רבי שמעון מטמא דאמר ולד הוא וחכמים מטהרים אלא ודאי אפי' לרבי שמעון לא הוי אלא כדם המכה והא דאמר רבי שמעון במתניתין יושבין עליו ימי טומאה משום ולד קאמר ולא משום דם:"]],[[0,"","שהיה פסולן בקדש. שאין פסולן יכול להיות עד אחר שהוקדש אבל רובע ונרבע מצי להיות בעודן חולין וקשה דאמרינן בזבחים פ' חטאת העוף (זבחים דף סח:) זר וסכין מטמאין אלמא חשיב אין פסולן בקדש אע\"ג דלא שייכי עד לאחר שהוקדש ושמאל ולילה נמי הוה מטמאין אי לאו דאית להו הכשר במקום אחר כדאמר התם ודוקין שבעין קאמר רבי עקיבא דאם עלו לא ירדו משום דכשר בעוף אלמא חשיב פסולו בקודש אע\"ג דיכול להיות קודם הקדש ונראה לפרש דהיכא דכיוצא בו כשר במקום אחר קרי פסולו בקדש ונשחט בלילה אית ליה הכשר באברים ופדרים ויוצא דמה שכן כשר באימורים ואימורים שכן כשר בבמה ונשפך דמה כיון שקבלה היתה בהכשר מיקרי פסולו בקדש ולשון פסולו בקדש היינו שאין כאן פסול גמור אלא נפסל בקדושתו וכן משמע דפריך התם מ\"ש שמאל דאית ליה הכשר ביום הכיפורים ולילה באברים ופדרין ולכך אין מטמאין דהוי פסולן בקדש:"],[4,"","היינו דאיצטריך תרי קראי. וא\"ת וליבעי ג' קראי בכל הפסולין כמו בטרפה דחשיב הכא בהדייהו דבפרק קמא דמנחות (דף ו.) מצריך ב' קראי בטרפה חד לנטרפה קודם הקדשה וחד לנטרפה לאחר הקדשה ואפילו הכי איצטריך הכא למעוטי מזאת דאם עלתה תרד וה\"נ בשאר פסולין ליבעי תרי קראי בלא קרא דזאת חד לקודם הקדש וחד לאחר הקדש דלא יעלו וקרא דזאת לירדו ויש לומר כיון דגלי לן קרא בטרפה ה\"ה לשאר פסולים:"],[5,"","קסבר ולדות קדשים בהוייתן הן קדושים. פרש\"י דל\"ג ליה דהא כ\"ש למ\"ד במעי אמן הן קדושים דאיצטריך למעוטי מזאת ונראה דגרס ליה ולרבותא נקטיה דאע\"ג דבהויתן הן קדושים ולא קדם הקדשן לפסולן אצטריך קרא למעוטי כיון דהפסול לא בא תחלה אלא בבת אחת אבל לא מצי למגרס קסבר במעי אמן הן קדושים דהא בסוף פרק דם שחיטה (כריתות דף כג:) קאמר דקסבר ר\"ש בהויתן הן קדושים וכן מוכח משמעתין דמוקי קרא דזאת לבהמת קדשים ואתנן ומחיר לא אשכחן אחר הקדש אפי' לרבי יוסי הגלילי דאמר קדשים קלים ממון הדיוט הוא דאמר בפרק מי שהיה טמא (פסחים דף צ.) לכל נדר פרט לנדור שאין אתנן חל עלייהו ולא משכחת אלא בולדות קדשים וכמ\"ד בהויתן הן קדושים ונתנם לזונה בעודם בבטן והכי מוקי לה בפ' פרת חטאת (זבחים דף קיד.) וכן פ\"ה וא\"ת דבשילהי תמורה (דף לג:) תנן אלו הן הנקברים קדשים שהפילו וחולין שנשחטו בעזרה ור\"ש אומר חולין שנשחטו בעזרה ישרפו משמע דלא פליג אקדשים שהפילו וכיון דבהוייתן הן קדושים אמאי יקברו והלא אין קדושה חלה עלייהו כדתנן פרק כיצד מערימין (תמורה דף כד:) רשב\"ג אומר ילדה טומטום ואנדרוגינוס אין קדושה חלה עלייהו וקאמר דקסבר דבהויתן הן קדושים ואפילו קדושת דמים אין חלה עלייהו דאי חלה הא אמר בפרק אלו קדשים (תמורה דף יט:) מגו דנחתא קדושת דמים נחתא נמי קדושת הגוף ואם כן קדשים שהפילו דאסורים בהנאה לרבי שמעון אמאי ויש לומר דפליג גם ארישא אלא דלא נחת לפלוגי אלא בחולין שנשחטו בעזרה תדע דהא חשיב התם נמי בשר בחלב בקבורה ולרבי שמעון שרי בהנאה בפ\"ק דבכורות (דף י.) א\"נ י\"ל דנפל קדושה חלה עלויה טפי מטומטום ואנדרוגינוס משום דאי הוה בר קיימא היה ראוי לקרבן וא\"ת כיון דסבר בהויתן הן קדושים היאך קדושה חלה על יוצא דופן וכלאים דמ\"ש מטומטום ואנדרוגינוס וי\"ל דמיירי כגון שהקדישן בפה קודם שנולדו דאע\"ג דאין קדושת אמן חלה עליהם קדושת פה חלה עליהם מיהו מתני' דכיצד מערימין (תמורה דף כד:) משמע דאפילו בקדושת פה אין קדושה חלה עליהם ועוד דבשילהי פ\"ב דתמורה (דף יז.) קאמר אי אתה מוצא אלא בולדות קדשים ואליבא דרבי יהודה ואמאי לא משכחת בהקדישו בפה ושמא י\"ל דדווקא טומטום ואנדרוגינוס אין קדושה חלה עליהם:"],[11,"","ורבנן לטעמייהו. וא\"ת אע\"ג דלא מטמאי לידה מ\"מ ליטהר דם קישויה דאפי' בהפילה רוח פריך בפ\"ק (לעיל נדה דף ח:) שיהא קישויה טהור אע\"ג דאין נותנין לה ימי טומאה וימי טהרה ויש לומר דהתם משום דבעי למימר דמיקרי לידה כדמייתי קרא כמו ילדנו רוח אבל הכא מיעטיה קרא מדין ולד:"]]],[["ודם דרך רחם ואזדא ר' שמעון לטעמיה ורבנן לטעמייהו","מתקיף לה רב יוסף חדא דהיינו רישא ועוד משם מקום ולד משמע","אלא אמר רב יוסף כגון שיצא ולד ודם דרך דופן","ובמקור מקומו טמא קמיפלגי מר סבר מקור מקומו טמא ומ\"ס מקור מקומו טהור","אמר ר\"ל לדברי המטמא בדם מטמא באשה לדברי המטהר בדם מטהר באשה ור' יוחנן אמר אף לדברי המטמא בדם מטהר באשה","ואזדא ר' יוחנן לטעמיה דאמר רבי יוחנן משום ר\"ש בן יוחי מנין שאין אשה טמאה עד שיצא מדוה דרך ערותה שנאמר (ויקרא כ, יח) ואיש אשר ישכב את אשה דוה וגלה את ערותה את מקורה הערה מלמד שאין אשה טמאה עד שיצא מדוה דרך ערותה","אמר ריש לקיש משום רבי יהודה נשיאה מקור שנעקר ונפל לארץ טמאה שנאמר (יחזקאל טז, לו) יען השפך נחושתך ותגלי ערותך","למאי אילימא לטומאת שבעה דם אמר רחמנא ולא חתיכה אלא לטומאת ערב","אמר רבי יוחנן מקור שהזיע כשתי טיפי מרגליות טמאה למאי אילימא לטומאת שבעה חמשה דמים טמאין באשה ותו לא אלא לטומאת ערב ודווקא תרתי אבל חדא אימא מעלמא אתיא","כל הנשים מטמאין בבית החיצון הי ניהו בית החיצון אמר ריש לקיש כל שתינוקת יושבת ונראת","א\"ל רבי יוחנן אותו מקום גלוי הוא אצל שרץ אלא אמר רבי יוחנן עד בין השינים","איבעיא להו בין השינים כלפנים או כלחוץ ת\"ש דתני רבי זכאי עד בין השינים בין השינים עצמן כלפנים","במתניתא תנא מקום דישה מאי מקום דישה אמר רב יהודה מקום שהשמש דש","תנו רבנן בבשרה מלמד שמטמאה בפנים כבחוץ ואין לי אלא נדה זבה מנין ת\"ל זובה בבשרה","פולטת ש\"ז מנין ת\"ל יהיה ור' שמעון אומר דיה כבועלה מה בועלה אינו מטמא עד שתצא טומאה לחוץ אף היא אינה מטמאה עד שתצא טומאתה לחוץ","וסבר רבי שמעון דיה כבועלה והתניא (ויקרא טו, יח) ורחצו במים וטמאו עד הערב אמר ר' שמעון וכי מה בא זה ללמדנו אם לענין נוגע בשכבת זרע הרי כבר נאמר למטה או איש","אלא מפני שטומאת בית הסתרים היא וטומאת בית הסתרים אינה מטמאה אלא שגזרת הכתוב הוא","לא קשיא כאן במשמשת כאן בפולטת","פולטת תיפוק ליה דהא שמשה בשטבלה לשמושה","למימרא דמשמשת בטומאת ערב סגי לה והא אמר רבא משמשת כל שלשה ימים אסורה לאכול בתרומה שאי אפשר לה שלא תפלוט","הכא במאי עסקינן שהטבילוה במטה מכלל דכי קאמר רבא דאזלה איהי בכרעה וטבלה דילמא בהדי דקאזלה שדיתא"],[[0,"ודם דרך רחם","בשלשת ימי הקושי קודם לידה ואמור רבנן דזיבה היא דלא מטהר לה ולד דלאו לידה היא ורבי שמעון מטהר לטמא הואיל וימי זיבה הן ודם קושי בימי זיבה רחמנא טהריה:"],[2,"שיצא ולד ודם דרך דופן","ופלוגתא אחריתי היא ולאו אקושי קאי דרישא איירי כשיצא דם דרך רחם קודם לידה:"],[3,"רבנן סברי מקור מקומו טמא","הלכך טיפת דם מטמאה. ואע\"ג דדרך דופן לאו ראייה היא לטמא את האשה טומאת שבעה מיהו טיפה עצמה מטמאה במגע משום דנגע במקור ומקור מקומו טמא. ורבי שמעון סבר מקור מקומו טהור מלטמא טיפה הנוגעת בו הלכך כי אתא דם דרך דופן טהור מלטמא וכדם מכה דמי וכי אתא נמי דרך רחם טהור כל ימי זיבה היכא דליכא שופי סמוך ללידה דולד מטהרו ואע\"ג דולד דרך דופן נפק:"],[4,"מטמא באשה","טומאת שבעה משום ראיית נדה ואע\"ג דבא דרך דופן:"],[6,"שנעקר","חתיכת בשר:"],[6,"נחושתך","שולייך והיינו מקור וכתיב ותגלי ערותך אלמא נעקר ונשפך לארץ קרי ליה ערוה כאילו הוא במקומו הילכך טמא. נחושתך שולים כדאמר במסכת שבת (דף מא.) מפני שנחושתה מחממתה ובטהרות נמי בכמה דוכתין נחושתו של תנור (כלים פ\"ח מ\"ג):"],[7,"לטומאת ערב","מפני שנגעה בו ביציאתה:"],[8,"טיפי מרגליות","דם לבן וצלול:"],[8,"לטומאת ערב","מפני שנגע במקור ונוגע בה:"],[8,"מעלמא","מן הצדדין:"],[9,"כשהתינוקת יושבת","נפתח רחמה קצת:"],[10,"א\"ר יוחנן","לשון קושיא הוא:"],[10,"אותו מקום","מי קרי בבשרה כולו חוץ הוא ואפי' אצל מגע שרץ דקיימא לן אין מגע בית הסתרים מטמא גלוי הוא אם נגע שם שרץ:"],[10,"","טומאת בית הסתרים לקמן יליף מוידיו לא שטף במים (ויקרא ט״ו:י״א) דלאו בר טמויי הוא ובתורת כהנים נמי מינה נפקא לן:"],[10,"","כמין שינים יש בתוך הרחם תלתולי בשר:"],[12,"שהשמש","אבר:"],[13,"תלמוד לומר זובה בבשרה","ואע\"ג דבנדה כתיב מדאפקיה בלשון זובה ילפינן זיבה:"],[14,"יהיה","זובה בבשרה:"],[14,"בועלה","בעל קרי אינו מטמא עד שתצא טומאתו לחוץ כדכתיב (שם טו) ואשר תצא ממנו שכבת זרע:"],[15,"","ה\"ג בתורת כהנים מה בא זה ללמדנו אם לענין הנוגע בשכבת זרע הרי כבר אמור למטה אלא מפני כו':"],[15,"מה בא זה ללמדנו","הא משום טבילה דידיה לא איצטריך דהא כתיב לעיל ואיש כי תצא ממנו שכבת זרע ואם ללמד עליה שצריכה טבילה אם נגע בשרה מבחוץ בשכבת זרע כשיצתה ממנו הרי כבר אמור למטה בפרשת אמור אל הכהנים (ויקרא כ״ב:ד׳) או איש אשר תצא ואמר לקמן בפרקין (נדה דף מג:) מנין לנוגע בש\"ז ת\"ל או איש אלמא מיניה נפקא לן:"],[16,"אלא","בא ללמדנו שאפי' לא נגע בשרה מבחוץ בקרי טמאה מפני טיפת תשמיש והוצרך להשמיענו שטמא דאי לא אשמעי' לא הוה קיימא לן מפני שהיא טומאת בית הסתרים ואינה מטמאה אלא מפני שגזירת הכתוב הוא. אלמא לא אמרינן דדיה כבועלה:"],[17,"במשמשת","גזרת הכתוב ולא בפולטת:"],[18,"פולטת תיפוק ליה","דקודם יציאתו חוץ טמאה היא דהא שמשה:"],[18,"בשטבלה לשמושה","ולמחר פלטה וקאמר לך ר' שמעון בה דיה כבועלה:"],[19,"כל שלשה כו'","וכיון דכל שלשה אסורה משום תשמישה דיה כבועלה היכי משכחת לה אי לאחר שלשה אפי' יצא נמי טהורה דהא שכבת זרע מסרחת היא:"],[20,"הכא במאי עסקינן","הא דקאמר ר\"ש דטהורה בטבלה לתשמישה שהטבילוה במטה דכיון דלא זזה ממקומה אפשר לה בלא פליטה:"],[20,"מכלל","דהא דרבא כגון דאזלא איהי בכרעה א\"כ מאי אי אפשר שלא תפלוט כל שלשה דמשמע טמאה ודאית הא בחזקת טהורה היא טפי דאיכא למימר בהדי דאזלא ומסגייא בכרעה שדיתיה לכוליה קודם טבילה:"]],[[5,"","ואזדא ר' יוחנן לטעמיה. וא\"ת והא משמיה דר\"ש קאמר ור\"ל נמי מודה דר' שמעון מטהר באשה דקאמר לדברי המטהר בדם מטהר באשה וי\"ל דה\"פ מילתיה דר\"ל לדברי המטמא בדם מטמא באשה משום ראייה ומיירי כגון שיצא הולד והדם דרך דופן ובקושי דלאו קושי דולד הוא ורבי שמעון דמטהר בדם מטהר באשה דולד הוה וקושי סמוך ללידה רחמנא טהריה אבל אי לאו ולד הוא אף לרבי שמעון טמאה דלא בעינן שיצא דרך ערותה לכ\"ע ור' יוחנן אמר דאף רבנן מטהרי באשה דבעינן שיצא דרך ערותה לכ\"ע והשתא קאמר שפיר ואזדא רבי יוחנן לטעמיה אע\"ג דמשמיה דרבי שמעון קאמר דמדרבי שמעון נשמע לרבנן:"],[15,"","וסבר ר\"ש דיה כבועלה והתניא וכו'. אע\"ג דקרא במשמשת איירי סבר המקשה דמטעם משמשת לא היתה טמאה אי לאו משום שהזרע נפלט לבית החיצון וא\"ת לרבנן נמי תקשה דאמאי איצטריך קרא תיפוק ליה מיהיה ויש לומר אף דרבי שמעון אדרבי שמעון פריך וכי משני כאן בפולטת כאן במשמשת אתי נמי שפיר אף לרבנן ואיצטריך קרא למשמשת אע\"פ שנכנס הזרע מתחלה לבית הפנימי ולא יצא לבית החיצון דאי יצא תיפוק ליה משום פליטת הזרע ואפילו למ\"ד לעיל במקום שהשמש דש הוי בית החיצון היינו באדם בינוני וכן באשה בינונית אבל בגדול וקטנה משכחת לה שפיר שהזרע נכנס לבית הפנימי מתחלה אי נמי שמא לרבנן לא מטמא משום פליטת זרע אלא כשהיה הזרע בבית הפנימי ונפלט לחיצון אבל כשעומד הזרע בחיצון במקומו ולא נפלט שם ממקום אחר לא מטמא אלא משום משמשת:"],[18,"","פולטת תיפוק ליה דהא שמשה. היה יודע דלישני ליה כשטבלה לשימושה דהא כתיב וטמאה עד הערב אלא משום דבעי למפרך מרבא דאמר כל שלשה לא מהני לה טבילה ואם תאמר בלאו הכי מצי לאקשויי מרבא אקרא ויש לומר דקרא איכא לאוקומי דאזלא איהי בכרעה אי נמי כשקנחה עצמה יפה דאפשר לכבד הבית שלא ישתייר כלום דתנן במס' מקוואות (פ\"ח מ\"ד) האשה ששמשה את ביתה וירדה וטבלה ולא כבדה את הבית כאילו לא טבלה אבל השתא אמאי דמשני כאן בפולטת כאן במשמשת פריך שפיר דאי איתא דכבדה הבית אם כן תיפוק ליה דהרי פלטה:"]]],[["וכי תימא דילמא אשתייר אי הכי חיישינן שמא נשתייר מבעי ליה","אלא לרבא נמי שהטבילוה במטה ולא קשיא כאן במתהפכת כאן בשאינה מתהפכת","ורבא אקרא קאי והכי קאמר כי כתב רחמנא ורחצו במים וטמאו עד הערב בשאינה מתהפכת אבל במתהפכת כל שלשה ימים אסורה לאכול בתרומה שאי אפשר לה שלא תפלוט","בעא מיניה רב שמואל בר ביסנא מאביי פולטת שכבת זרע רואה הויא או נוגעת הויא","נפקא מינה לסתור ולטמא במשהו ולטמא בפנים כבחוץ","מה נפשך אי שמיע ליה מתניתין לרבנן רואה הויא ולר' שמעון נוגעת הויא","ואי לא שמיע ליה מתניתין מסתברא נוגעת הויא","לעולם שמיע ליה מתניתין ואליבא דרבנן לא קמיבעיא ליה כי קא מיבעיא ליה אליבא דר\"ש","ולטמא בפנים כבחוץ לא קמיבעיא ליה כי קמיבעיא ליה לסתור ולטמא בכל שהוא מאי","כי קאמר רבי שמעון דיה כבועלה הני מילי לטמויי בפנים כבחוץ אבל לסתור ולטמא בכל שהוא רואה הויא או דילמא לא שנא","איכא דאמרי לעולם לא שמיע ליה מתניתא והכי קמיבעיא ליה מדאחמיר רחמנא אבעלי קריין בסיני רואה הויא","או דילמא לא גמרינן מסיני דחדוש הוא דהא זבין ומצורעים דחמירי ולא אחמיר בהו רחמנא","א\"ל רואה הויא אתא שייליה לרבא א\"ל רואה הויא אתא לקמיה דרב יוסף א\"ל רואה הויא הדר אתא לקמיה דאביי א\"ל כולכו ברוקא חדא תפיתו","אמר ליה שפיר אמרי לך עד כאן לא קאמר ר\"ש דיה כבועלה אלא לטמא בפנים כבחוץ אבל לסתור ולטמא בכל שהוא רואה הויא","ת\"ר הנדה והזבה והשומרת יום כנגד יום והיולדת כולן מטמאות בפנים כבחוץ","בשלמא כולהו לחיי אלא יולדת אי בימי נדה נדה אי בימי זיבה זיבה","לא צריכא שירדה לטבול מטומאה לטהרה","וכי הא דאמר רבי זירא א\"ר חייא בר אשי אמר רב יולדת שירדה לטבול מטומאה לטהרה ונעקר ממנה דם בירידה טמאה בעלייה טהורה","א\"ל רבי ירמיה לר' זירא בירידה אמאי טמאה טומאה בלועה היא א\"ל זיל שייליה לרבי אבין דאסברית ניהליה וכרכיש לי ברישיה בי מדרשא","אזל שייליה א\"ל עשאוה כנבלת עוף טהור שמטמאה בגדים בבית הבליעה מי דמי"],[[0,"וכי תימא חיישי' שמא נשתייר בה","ומספיקא קא מטמאה א\"כ מאי אי אפשר חיישינן מיבעי ליה:"],[1,"אלא לרבא נמי","דלא אזלה הילכך כל שעה פלטה והא דר' שמעון דיכולה לטבול לשמושה כגון שלא נתהפכה לאחר הטבילה ודרבא במתהפכת:"],[2,"ורבא","לפרושי לן קרא אתא דכי כתיב ורחצו במים דמשמע דיכולה לטבול בו ביום כשאינה מתהפכת. ל\"א מתהפכת בשעת תשמיש ואין הזרע נקלט ברחם יחד הילכך פולטת והולכת מעט מעט אינה מתהפכת בשעת תשמיש נקלט הזרע יחד ויוצא בבת אחת:"],[3,"רואה הויא","משום ראייה טמייה קרא ומשום נוגעת בשכבת זרע דעד השתא הויא נגיעת בית הסתרים ולא הויא טמאה אלא ביום תשמיש ומגזרת הכתוב וכי פלטה נגעה לבראי ומטמיא:"],[4,"לסתור","בזיבה בימי ספירה אי רואה הויא סותרת אבל נוגעת לא שאם נגעה בשום טומאה אינה סותרת דהא וספרה לה כתיב והאיכא:"],[4,"ולטמא במשהו","לראייה לא בעינן שיעורא כדאמרי' במתני' לדם נדה ולזיבה ולקרי מטמאין בכל שהוא אבל נוגע בעי שיעורא כדאמר בפירקין (לקמן נדה דף מג:) איכא למ\"ד בכעדשה ואיכא למ\"ד כחתימת פי האמה:"],[5,"אי שמיע ליה","לרב שמואל:"],[5,"מתניתא","דפליגי רבנן ור\"ש לעיל דקאמרי רבנן פולטת שכבת זרע מטמא בפנים כבחוץ ולר\"ש דדיה כבועלה:"],[5,"לרבנן רואה הויא","לענין לטמא בפנים כבחוץ ולר\"ש נוגעת הויא:"],[6,"ואי לא שמיע ליה","אמאי מספקא ליה מסברא נוגעת הויא דהא לא מגופה חזיא אלא מה שקבלה היא פולטת:"],[7,"ואליבא דרבנן לא קמיבעיא ליה","דכיון דלרבנן מטמיא בפנים כבחוץ אלמא רואה הויא וכ\"ש דמטמאה במשהו ולענין סתירה נמי סתרה דהא בתורת זיבה מרבי ליה מיהיה זובו:"],[7,"כי קא מיבעי ליה אליבא דר\"ש ולטמא בפנים לא מיבעי ליה","דהא שמעינן לר\"ש דלא מטמיא:"],[8,"כי קא מבעיא ליה לסתור ולטמא במשהו","מהו מי אמרי' כי אמר ר' שמעון דיה כבועלה לטמא בפנים כבחוץ מה בועלה לא מטמא איהי נמי לא מטמאה אבל לסתור ולטמא במשהו לא משוי לה כנוגעת דהא א\"נ אמר דיה כבועלה סתרה ומטמאה במשהו כבועלה או דילמא לא שנא דכי היכי דלענין טומאת פנים משוי לה נוגעת לענין משהו וסתירה נמי משוי לה נוגעת:"],[10,"לעולם לא שמיע ליה מתני'","ודקאמרינן מסברא נוגעת הויא לא היא מסברא לא מיפשט לן דאיכא למימר מדאחמיר רחמנא בבעלי קריין בסיני דכתיב (שמות י״ט: ט״ו) אל תגשו אל אשה ולא הזהיר על טמא שרץ רואה הויא:"],[12,"כולכו ברוקא חדא תפיתו","כולכם שמעתם שמועה אחת. תפיתו לשון רוק וחבירו בכתובות תוף שדי בפרק אף על פי (כתובות דף סא:):"],[13,"אמר ליה","אביי שפיר אמר לך:"],[13,"אבל לסתור ולטמא במשהו רואה הויא","דאי נמי דיה כבועלה מטמיא כבועלה במשהו וסתרה כבועלה:"],[14,"הזבה ושומרת יום","הכי קאמר בין שראתה ג' ימים בין שראתה יום אחד מטמאה בבית החיצון בראייה ראשונה:"],[14,"והיולדת","לקמן מפרש:"],[14,"כולן מטמאין בפנים כבחוץ","בראייה ראשונה אבל בשניה ליכא למימר דהא בלא ראייה טמאה היא:"],[15,"אי בימי נדה","ילדה וראתה הא תני ליה ואי בימי זיבה הא תני ליה לזיבה:"],[16,"מטומאה לטהרה","לאחר שבועים וקיימא לן כבית הלל דאמרי בבנות כותים (לעיל נדה דף לה:) ביומי וטבילה תלא רחמנא דלא הוי דם טוהר אלא לאחר טבילה:"],[17,"ונעקר דם","לבית החיצון ועמד שם יום או יומים:"],[17,"טמאה","כל זמן שהוא בה וכשיצא בעיא טבילה אחריתי דלא טהרתה טבילה והיינו דתניא יולדת מטמיא בבית החיצון:"],[18,"טומאה בלועה היא","וקיימא לן בפרק בהמה המקשה (חולין דף עא.) טומאה בלועה אינה מטמאה לא במגע ולא במשא והכא הא טומאה בלועה היא ולא דמיא לכל הנשים שמטמאות בבית החיצון דהתם משום ראייה דמאתמול היא וטומאת שבעה ורחמנא אמר בבשרה מכי אתא בבית החיצון הויא ראייה אבל הכא משום משא ונגיעה היא וטומאת ערב דאי משום ראייה מאתמול איעקר ומאתמול הויא ראייה וראייה דמאתמול לא מהניא לה האידנא דמאתמול הוה להו ימי טומאה והשתא הוו להו ימי טוהר וטומאה בלועה לא מטמיא במגע ובמשא:"],[18,"אסברית ניהליה","פירשתי לו טעמא:"],[18,"וכרכיש לי ברישיה","הודה לדברי ונענע בראשו:"],[19,"בגדים בבית הבליעה","בגדים שהוא לבוש בהן בשעה שנוגע בה אינן טמאין שאין להן טומאת מגע דאמר רחמנא לא יאכל לטמאה בה (ויקרא כ״ב:ח׳) אין לך אלא מה שאמור בה אכילה ולא מגע ומה היא מטמאה בגדים שהוא לבוש בשעת בליעה כדכתיב (שם יז) [וכל] נפש אשר תאכל נבלה וטריפה באזרח ובגר וכבס בגדיו וטהר ובנבלת עוף טהור כתיב דנבלת בהמה לא מטמאה בבית הבליעה כדאמר בשמעתין ונבלת עוף טמא נמי לא מטמאה כדאמר בתורת כהנים מי שאיסורו משום בל תאכל נבלה יצא עוף טמא שאין איסורו משום בל תאכל נבלה אלא משום בל תאכל טמא:"]],[[6,"","מסתברא דנוגע הויא. ומסיני לא גמרינן דחדוש הוא ולהכי לרבנן נמי איצטריך יהיה דלא גמרינן מסיני אע\"ג דבסמוך בעי למימר דאף לר\"ש רואה הויא וסתרה:"],[10,"","מדאחמיר רחמנא אבעלי קריין בסיני. מאיש לא מוכח דפשיטא דרואה הוי אלא מאשה דמשום פולטת הזהיר רחמנא ג' ימים אל תגשו אל אשה:"],[11,"","דהא זבין ומצורעים דחמירי. אף ע\"ג דאכתי לא נאמרה פרשת טומאה ושילוח טמאים מ\"מ ראוי להחמיר בהן יותר מבפולטת:"],[13,"","עד כאן לא קאמר ר' שמעון כו'. אבל לטמא במשהו רואה הויא וא\"ת והא אמר בפסחים פרק אלו דברים (פסחים דף סז:) דר' שמעון סבר כר' נתן דזב בעי שיעור כחתימת פי האמה ויליף בעל קרי מזב וא\"כ אמאי מטמא במשהו נימא דיה כבועלה וי\"ל דרבי שמעון ודאי לא מטמא במשהו והכא ה\"ק אפי' למאן דאית ליה כר' שמעון דפולטת ולא מטמאה בפנים כבחוץ מ\"מ מטמאה במשהו אי סבר דאיש מטמא במשהו:"],[17,"","בירידה טמאה. הדם טמא דביומי וטבילה תליא רחמנא וטמאה האשה משום נוגע טומאת ערב:"],[18,"","אמאי טומאה בלועה היא. לאביי דאמר בסמוך אותו מקום של אשה בלוע הוי ניחא דקרי ליה טומאה בלועה ולרבא נמי דאמר בית הסתרים הוי י\"ל דמיירי בשנעקר הדם מן המקור ולא יצא לבית החיצון והא דמסיק שיצא לחוץ לרבא לא צריך שיצא לחוץ לגמרי אלא שיצא לבית החיצון דהוי בית הסתרים וטמא במשא ומיהו עשאוה כנבלת עוף טהור משמע דסבר כאביי דלרבא אמר לקמן דמקום נבלת עוף טהור בית הסתרים הוי:"],[19,"","עשאוה כנבלת עוף טהור. אע\"ג דבעלמא לא החמירו בטומאה בלועה הכא גזרו רבנן טפי כדי שלא יבא לטעות ולטהרו על ידי טבילה אפילו כשיצא לחוץ וכי משני הכא נמי כשיצא לחוץ סבר דלא גזרו:"]]],[["התם אין לה טומאה בחוץ הכא כי נפיק לבראי ליטמי הכא נמי כשיצא לחוץ","אי יצא לחוץ מאי למימרא מהו דתימא מגו דמהני טבילה לדם דאיכא גואי תהני נמי להאי קמ\"ל","שמעתין איפריק אלא יולדת אי בימי נדה נדה אי בימי זיבה זיבה","הכא במאי עסקינן בלידה יבשתא לידה יבשתא מאי מטמא בפנים כבחוץ איכא","כגון שהוציא ולד ראשו חוץ לפרוזדור וכדרב אושעיא דאמר רב אושעיא גזרה שמא יוציא הולד ראשו חוץ לפרוזדור","וכי ההוא דאתא לקמיה דרבא אמר ליה מהו לממהל בשבתא אמר ליה שפיר דמי בתר דנפק אמר רבא ס\"ד דההוא גברא לא ידע דשרי לממהל בשבתא אזל בתריה אמר ליה אימא לי איזי גופא דעובדא היכי הוה","אמר ליה שמעית ולד דצויץ אפניא דמעלי שבתא ולא אתיליד עד שבתא אמר ליה האי הוציא ראשו חוץ לפרוזדור הוא והוי מילה שלא בזמנה וכל מילה שלא בזמנה אין מחללין עליה את השבת","איבעיא להו אותו מקום של אשה בלוע הוי או בית הסתרים הוי","למאי נפקא מינה כגון שתחבה לה חבירתה כזית נבלה באותו מקום אי אמרת בלוע הוי טומאה בלועה לא מטמאה ואי אמרת בית הסתרים הוי נהי דבמגע לא מטמיא במשא מיהא מטמיא","אביי אמר בלוע הוי רבא אמר בית הסתרים הוי אמר רבא מנא אמינא לה דתניא אלא מפני שטומאת בית הסתרים היא","וטומאת בית הסתרים לא מטמאה אלא שגזרת הכתוב היא","ואביי חדא ועוד קאמר חדא דטומאה בלועה היא ועוד אפילו אם תמצי לומר טומאת בית הסתרים היא אינה מטמאה אלא שגזרת הכתוב היא","איבעיא להו מקום נבלת עוף טהור בלוע הוי או בית הסתרים הוי","למאי נפקא מינה כגון שתחב לו חבירו כזית נבלה לתוך פיו אי אמרת בלוע הוי טומאה בלועה לא מטמיא (אלא אי) אמרת בית הסתרים הוי נהי נמי דבמגע לא מטמא במשא מיהא מטמא","אביי אמר בלוע הוי ורבא אמר בית הסתרים הוי אמר אביי מנא אמינא לה דתניא יכול תהא נבלת בהמה מטמאה בגדים אבית הבליעה ת\"ל (ויקרא כב, ח) נבלה וטרפה לא יאכל לטמאה בה","מי שאין לה טומאה אלא אכילתה יצתה זו שטמאה קודם שיאכלנה","ותיתי בק\"ו מנבלת עוף טהור ומה נבלת עוף טהור שאין לה טומאה בחוץ יש לה טומאה בפנים זו שיש לה טומאה בחוץ אינו דין שיש לה טומאה בפנים","אמר קרא בה בה ולא באחרת","אם כן מה תלמוד לומר (ויקרא יא ) והאוכל","ליתן שיעור לנוגע ולנושא כאוכל מה אוכל בכזית אף נוגע ונושא בכזית","אמר רבא שרץ בקומטו טהור נבלה בקומטו טמא","שרץ בקומטו טהור שרץ בנגיעה הוא דמטמא ובית הסתרים לאו בר מגע הוא נבלה בקומטו טמא נהי דבמגע לא מטמא במשא מיהא מטמא","שרץ בקומטו והכניסו לאויר התנור טמא פשיטא מהו דתימא תוכו אמר רחמנא"],[[0,"התם אין לה טומאה בחוץ","כדפרישית לטמאה בה אין לך בה אלא מה שאמור בה והך הוא דגזור בה רחמנא:"],[0,"הכא כי נפיק לבראי תיטמי","וכיון דמטמא בחוץ הויא כשאר טומאות דלא מטמאות בלועות:"],[0,"הכא נמי כשיצא לחוץ","לכשיצא לחוץ מטמא אותה אם נעקר קודם טבילה ואם טבלה טהורה כל זמן שהוא שם ולכשיצא ויגע בה יטמאנה:"],[1,"מאי למימרא","הא דם טמא הוא דקודם טבילה נעקר:"],[2,"שמעתין","דרבי זירא דהוה קשיא לן טומאה בלועה היא:"],[2,"איפריק","דלכשיצא לחוץ הוא דקאמר. והשתא לא מתוקמא ברייתא דקתני יולדת מטמאה בבית החיצון כדרבי זירא דהא לרבי זירא לא מטמיא עד השתא שיצא והדרא קושיא לדוכתין:"],[3,"בלידה יבישתא","דליכא לא נדה ולא זיבה:"],[3,"","אי ביבשתא מאי מטמיא בפנים איכא:"],[4,"כגון שהוציא ולד ראשו חוץ לפרוזדור","ואוליד וקאמר דאע\"ג דאכתי ראשו בפנים הוא דהיינו בבית החיצון הוי כילוד וטמאה לידה וכרב אושעיא דאמר חוץ לפרוזדור ולד הוי:"],[4,"דאמר רב אושעיא","בפרק בהמה המקשה (חולין דף עב.) אהא דתנן אשה שמת עוברה בתוך מעיה ופשטה חיה את ידה ונגעה בו החיה טמאה טומאת שבעה והאשה טהורה עד שיצא הולד והוינן בה חיה אמאי טמאה טומאה בלועה היא ואמר רב אושעיא הך טומאת חיה מדרבנן גזרה שמא יוציא ולד את ראשו חוץ לפרוזדור ותגע בו דמכי נפק הוה ליה ילוד ולא הוי בלועה וטמא מדאורייתא משום נוגע במת. אלמא חוץ לפרוזדור ילוד הוא הילכך לענין לטמא את אמו טומאת לידה נמי ילוד הוא:"],[5,"וכי ההוא דאתא כו'","כלומר מדרבא נמי שמעינן דראשו חוץ לפרוזדור הוי כילוד:"],[5,"ס\"ד","כלומר אפשר שאין זה האיש יודע שמילה בשבת מותרת אלא ודאי דבר ספק אירע בו:"],[6,"דצויץ","שמעתי את הולד צועק בתוך המעיים מבעוד יום של ערב שבת:"],[8,"טומאה בלועה לא מטמאה","דהרי היא כמי שאינה ואין בה לא מגע ולא משא וטהורה אשה זו:"],[8,"ואי אמרת בית הסתרים הוי","כשאר בית הקמטים טומאה לא בטלה ונהי דבמגע לא מטמיא דלא מטמא בית הסתרים בנגיעה במשא מיהא מטמאה וטמאה אשה זו שהרי נושאת את הנבלה:"],[12,"מקום נבלת עוף טהור","בית הבליעה של אדם שאין לנבלת עוף טהור טומאה אלא שם:"],[13,"שתחב לו חבירו","דאי תחב הוא לעצמו איטמי ליה במגע:"],[14,"בה","בגדים טמאים בבית הבליעה ולא באחרת:"],[20,"קומטו","כגון בין אציליו או שאר קמטים פרונצ\"ש בלע\"ז:"]],[[4,"","שהוציא ולד ראשו חוץ לפרוזדור. אבל בפרוזדור עצמו טהורה דלא חשוב כבחוץ ואם תאמר והא אמר לעיל בפ\"ק (נדה דף יז:) דם הנמצא בפרוזדור ספקו טמא ויש לומר התם ספקו טמא כשיצא לחוץ ועוד יש לחלק בין (דם) לידה לדם נדה וא\"ת דבריש בהמה המקשה (חולין דף סח.) ובפרק יש בכור (בכורות דף מו:) עביד צריכותא הא דתניא דראשו כילוד באדם ובבהמה דאי תנא בהמה משום דלית לה פרוזדור אבל אשה דאית לה פרוזדור אימא לא ומאי נפקא מינה במאי דאית לה פרוזדור כיון דבעינן שיוציא ולד ראשו חוץ לפרוזדור כדמשמע הכא ויש לומר דפרוזדור דהתם לא הוי כי האי דהכא דהתם קרי פרוזדור לעובי הירכים שמתכסה בהן ראשו של ולד וה\"א דלא חשיב כילוד וכן פירש שם בקונטרס:"],[4,"","וכדרב אושעיא כו'. דיצא ראשו חוץ לפרוזדור הוי כילוד ומלתיה דרב אושעיא איתמר אהא דפריך בבהמה המקשה (חולין עב. ושם) גבי אשה שמת עוברה בתוך מעיה ונגעה חיה בעובר טמאה ואמאי טמאה הא טומאה בלועה היא ומשני רב אושעיא כו' תימה אמאי נקט ראשו למשום דהוי כילוד כדמשמע הכא אפילו הוציא ידו נמי טמאה החיה שנגעה בו או הסיטתו דהא תו לאו טומאה בלועה היא ויש לומר דגזרת הכתוב הוא דלא מטמא עד שיהא כילוד כדדריש התם רבי ישמעאל על פני השדה להוציא עובר שבמעי אמו והשתא ניחא דבעי התם מאי טעמא דרבי ישמעאל אע\"פ שטעמו פשוט דהא טומאה בלועה היא אלא קים ליה דמטהר עד שיצא כל כך דמקרי לידה:"],[15,"","יצתה זו שטמאה כו'. לאו מיעוטא הוא דא\"כ מאי קאמר דתיתי בק\"ו אלא יצתה זו היינו שאינו בכלל פסוק זה וא\"ת ומאי יתרץ רבא מן הברייתא וי\"ל דמיירי כגון שבית הבליעה רחב כ\"כ שלא יסיט נבלה שתחב לו חבירו:"],[18,"","מה ת\"ל והאוכל ליתן שיעור אכילה לנוגע ולנושא. תימה כיון דבאכילה כתיב כבוס בגדים ובנוגע לא כתיב לית לן לאוקמא שיעור אכילה לנוגע אלא בנושא דכתיב ביה כבוס בגדים כדאשכחן לעיל בפ\"ק (דף ט.) ובפ\"ק דיומא (נדה דף יד.) דאמר ומזה מי הנדה יכבס בגדיו היינו נושא ואפקה רחמנא בלשון הזאה ליתן שיעור הזאה כנושא ולא כנוגע משום דלא כתיב ביה כבוס בגדים ויש לומר דהתם לא כתיב נושא בהדיא אבל הכא אי לא קאי והאוכל אלא אנושא גרידא א\"כ לא נכתוב נושא וממילא נימא דמאי אוכל נושא כמו התם דלא כתיב נושא ואמרינן מאי מזה נושא ומיהו תימה כבוס בגדים דכתב רחמנא באוכל למה לי וכ\"ת דאי לא הוה כתיב ביה כבוס בגדים הוה מוקמינן ליה בנוגע ולא בנושא דבעי כבוס בגדים א\"כ לא לכתוב נוגע כלל ושמא לשום דרשא איצטריך ואם תאמר דבפרק בהמה המקשה (חולין דף עא.) מפיק טומאה בלועה מהאי קרא דוהאוכל מנבלתה יכבס בגדיו וטמא עד הערב מי לא עסקינן דאכל סמוך לשקיעת החמה והשתא הא דקאמר הכא האי אוכל לא אכילה ממש הוא אלא ליתן שיעור אכילה לנוגע ולנושא ויש לומר דהתם מפיק משום דאין מקרא יוצא מידי פשוטו:"]]],[["ולא תוך תוכו קמ\"ל","אמר ר\"ל קנה בקומטו של זב והסיט בו את הטהור טהור קנה בקומטו של טהור והסיט בו את הזב טמא","מאי טעמא דאמר קרא (ויקרא טו, יא) וכל אשר יגע בו הזב וידיו לא שטף במים זהו הסיטו של זב שלא מצינו לו טומאה בכל התורה כולה","ואפקיה רחמנא בלשון נגיעה למימרא דהיסט ונגיעה כידיו מה התם מאבראי אף הכא מאבראי","אבל הזב ובעל קרי אינן מטמאין וכו' זב דכתיב (ויקרא טו, ב) כי יהיה זב מבשרו עד שיצא זובו מבשרו בעל קרי דכתיב (ויקרא טו, טז) ואיש כי תצא ממנו שכבת זרע","היה אוכל בתרומה והרגיש וכו' אוחז והתניא ר\"א אומר כל האוחז באמה ומשתין כאילו מביא מבול לעולם","אמר אביי במטלית עבה רבא אמר אפילו תימא במטלית רכה כיון דעקר עקר ואביי חייש דילמא אתי לאוסופי ורבא לאוסופי לא חייש","והתניא למה זה דומה לנותן אצבע בעין שכל זמן שאצבע בעין מדמעת וחוזרת ומדמעת","ורבא כל אחמומי והדר אחמומי בשעתא לא שכיח","אמר שמואל כל שכבת זרע שאין כל גופו מרגיש בה אינה מטמאה מ\"ט שכבת זרע אמר רחמנא בראויה להזריע","מיתיבי היה מהרהר בלילה ועמד ומצא בשרו חם טמא תרגמא רב הונא במשמש מטתו בחלומו דאי אפשר לשמש בלא הרגשה","לישנא אחרינא אמר שמואל כל שכבת זרע שאינו יורה כחץ אינה מטמאה מאי איכא בין האי לישנא להאי לישנא איכא בינייהו נעקרה בהרגשה ויצאה שלא בהרגשה","מילתא דפשיטא ליה לשמואל מיבעיא ליה לרבא דבעי רבא נעקרה בהרגשה ויצתה שלא בהרגשה מהו","ת\"ש בעל קרי שטבל ולא הטיל מים לכשיטיל מים טמא שאני התם דרובה בהרגשה נפק","לישנא אחרינא אמרי לה אמר שמואל כל שכבת זרע שאינו יורה כחץ אינה מזרעת אזרועי הוא דלא מזרעא הא טמויי מטמיא שנאמר (דברים כג, יא) כי יהיה בך איש אשר לא יהיה טהור מקרה אפילו קרי בעולם","בעי רבא עובד כוכבים שהרהר וירד וטבל מהו","אם תמצי לומר בתר עקירה אזלינן הני מילי לחומרא אבל הכא דלקולא לא אמרינן או דילמא לא שנא תיקו","בעי רבא זבה שנעקרו מימי רגליה וירדה וטבלה מהו","אם תמצא לומר בתר עקירה אזלינן הני מילי שכבת זרע דלא מצי נקיט לה אבל מימי רגליה דמצי נקיט לה לא או דילמא לא שנא תיקו","בעי רבא עובדת כוכבים זבה שנעקרו מימי רגליה"],[[0,"קמ\"ל","דהאי לא תוך תוכו הוא אלא כגון כלי בתוך התנור ופיו למעלה מפי התנור:"],[1,"והסיט בו את הטהור טהור","כדמפרש טעמא לקמן:"],[1,"בקומטו של טהור והסיט בו את הזב טמא","הטהור שהרי נשא את הזב וזב מטמא במשא דכתיב במשכב (ויקרא ט״ו:י׳) והנושא אותם וק\"ו לזב עצמו:"],[2,"מאי טעמא","טהור הניסט בקנה של קומטו של זב טהור:"],[2,"דכתיב וכל אשר יגע בו הזב וגו'","והאי קרא לאו למגע איצטריך דהא כתיב והנוגע בבשר הזב אלא זה הסיטו של זב מכאן למדנו זב שהסיט את הטהור טמא שלא מצינו בכל התורה טומאה המסטת טהרה שתטמא אלא אם כן נשא טהור את הטמא והכא בזב הוא דגלי רחמנא וכתב וידיו דדרשינן הכי היכא דהסיט בו הזב בידיו כלומר בגלוי:"],[2,"לא שטף במים","מילתא אחריתי היא למילף לנטילת ידים לאכילה מהכא. אלמא הסיט זב את הטהור אינו טמא אלא א\"כ הסיטו בגלוי בידיו ומדאפקיה בלשון נגיעה ילפינן נמי לכל נגיעות דאין מגע בית הסתרים מטמא אבל טהור שהסיט את הזב דנפקא לן מקרא אחרינא דלא כתיב ביה ידיו טמא אפילו הסיטו בקנה שבקומטו מידי דהוה אנבלה בקומטו שהיא מטמאה במשא דהא מ\"מ הרי הוא נושא את הטומאה. ל\"א קנה בקומטו של טהור והסיט את הזב להכי טמא שנגע הקנה בגילוי של זב ונטמא הקנה מחמת הזב וחוזר ומטמא את הטהור ואע\"ג דטהור קמוט דגילויא גבי זב הוא דבעינן אבל קנה בקומטו של זב והסיט את הטהור טהור הואיל וזב קמוט וגבי זב כתיב וידיו. ושיבוש הוא מפני כמה דברים חדא דקנה פשוטי כלי עץ הוא ואינו מקבל טומאה וא\"ת בקנה חלול נהי נמי דמקבל טומאה אפ\"ה אין חוזר ומטמא הטהור שהרי אין מגע של זב חוזר ומטמא אדם שאין לך נוגע בטומאה מטמא אדם חוץ מן הנוגע במת ועוד אי טומאת הטהור משום נגיעת קנה היא והרי בקומטו הוא דנגע ובית הסתרים לאו בר מגע הוא דהא אמרינן לעיל שרץ בקומטו טהור ועוד לשון הסיט אמאי נקט ועוד הסיט טהור את הזב מי נפק מהאי קרא וכל אשר יגע בו הזב כתיב והיינו אשר יסיטנו הזב ולא כתיב כל אשר יגע בזב:"],[5,"כאילו מביא מבול","שמחמם את אבריו ומביא לידי קרי וזהו קלקול דור המבול שנאמר (בראשית ו׳:י״ב) כי השחית כל בשר:"],[6,"במטלית עבה","שאינה מחממת:"],[8,"לא שכיח","והא דתניא כל זמן שאצבע בעין מדמעת ה\"מ היכא דמתחלה ממשמש וחימם את עצמו ויוצא כל שעה מעט אבל זה שנזדעזעו אבריו נעקר כל הזרע ביחד ושוב אינו חוזר ומתחמם לעקור עוד מיד בשעה אחת:"],[10,"בשרו חם","אברו:"],[10,"טמא","שמא יצא ממנו קרי ואמאי והא לא ארגיש:"],[10,"במשמש מטתו בחלומו","דאי נפק ודאי ארגיש:"],[12,"ויצתה בלא הרגשה","דאינו יורה כחץ:"],[13,"לכשיטיל מים טמא","דנשתייר מן הקרי ויוצא עכשיו ואע\"ג דלא נפיק בהרגשה הואיל ומעיקרא איעקר בהרגשה:"],[15,"עובד כוכבים שהרהר","ונעקר ולא יצא:"],[15,"וירד וטבל","לשם גירות ואח\"כ יצא קריו:"],[15,"מהו","אפי' אם תמצי לומר לגבי ישראל דכי נעקר בהרגשה ויצא שלא בהרגשה טמא דאזלינן בתר עקירה הכא לא ניזיל בתר עקירה דהיינו קולא הואיל וכשהוא עובד כובים נעקר וטהור דאמר בבנות כותים קריו טהור אפילו לב\"ה:"],[16,"או דילמא לא שנא","לחומרא כגון לגבי עקירה דהרגשה דישראל ולא שנא לקולא כי הכא אזלינן בתר עקירה:"],[17,"שנעקרו מימי רגליה","דהוי מעין אב הטומאה:"],[17,"וירדה וטבלה","וטהרה מזובה ואח\"כ הטילתו מהו מי אזלינן בתר עקירה ומטמאו או לא:"],[18,"דלא מצי נקיט לה","מלצאת הילכך מכי עקר חשיב ליה צורך יציאה:"],[19,"[עובדת כוכבים]","סתם עובדת כוכבים מי רגליה מטמאין דחכמים גזרו עליהן שיהו כזבין לכל דבריהם:"]],[[3,"","למימרא דהיסט ונגיעה כידיו. פרש\"י דמהכא ילפינן לכל נגיעות כגון שרץ ונבלה שנגעו בסתרו של טהור וקשה דאי מזב ילפינן כי היכי דבעינן גלוי הזב ה\"נ בעינן שיגע בגלוי של טהור לענין היסט נמי נילף דנבעי שיסיט הטהור בגילוי כדבעינן בגילוי הזב והכא אמרינן דקנה בקומטו של טהור והסיט בו את הזב טמא ואמר נמי דבית הסתרים מטמא במשא אלא נראה לפרש דזב ושרץ ונבלה שנגעו בסתרו של טהור דטהור לאו מזב ילפינן אלא ילפינן מלשון נגיעה דכתיב בכולהו וטהור הנוגע בזב נמי כתיב הנוגע בבשר הזב ולשון נגיעה משמע מאבראי שיגע הטהור בגלוי בטומאה וכן משמע פ\"ק דקדושין (דף כה.) דאמר עולא הכל מודים דלשון גלוי הוא אצל שרץ וכי יגע אמר רחמנא והאי בר נגיעה הוא משמע דמלשון נגיעה דכתיב בשרץ הוא דריש דלא מייתי קרא דידיו דכתיב בזב ומיהו רש\"י גריס התם אשר יגע בו והיינו קרא דכתיב גבי זב והא דאצטריך הכא למדרש מידיו ולא נפקא ליה מנגיעה דכתיב בזב משום דההיא נגיעה בהיסט מיירי ולא משמע גילוי כמו נגיעה ממש לכך דריש לה מידיו דבעינן גילוי הזב בין בהיסט בין במגע מדאפקיה בלשון נגיעה א\"נ מנגיעה דהכא דכתיב גבי ידיו מינה ילפינן לכל נגיעות דהוו מאבראי:"],[9,"","בראויה להזריע. ואפי' יצאה בלא הרגשה איירי כדמוכח בסמוך ותימה דא\"כ משמע דראוי להזריע אע\"פ שאינו יורה כחץ ובשילהי נדרים (דף צא.) וכן ביבמות (דף סה.) אמר איהי קים לה ביורה כחץ משמע דאי אין יורה כחץ אינו ראוי להזריע וי\"ל דלהא לישנא דהכא לא מצריך רק שבתחלת עקירת שכבת זרע תהא ראויה להזריע אע\"ג דלסוף יציאתה היא בענין שאינו ראוי להזריע א\"נ ראוי להזריע הוא אלא שאינה ראוייה להתעבר לפי שאינו יורה כחץ ואינו נכנס לתוך גופה אלא שותת ויוצא לחוץ:"],[14,"","הא טמויי מטמיא. פירוש ואפילו נעקרה בלא הרגשה דאם לא כן היינו לישנא קמא:"],[19,"","זבה שנעקרו מימי רגליה. וכן בעי מעובדת כוכבים שאל ריב\"א מרש\"י אמאי לא בעי מזכר זב ועובד כוכבים והשיב דנראה לו לפי שבאשה מתעגלין כל [מימי] רגליה בבת אחת לפתחה מה שאין כן באיש:"]]],[["וירדה וטבלה מהו","אם תמצי לומר בתר עקירה אזלינן אע\"ג דמצי נקיט להו ה\"מ ישראלית דטמאה דאורייתא אבל עובדת כוכבים זבה דטמאה דרבנן לא או דילמא לא שנא תיקו","ומטמאין בכל שהן אמר שמואל זב צריך כחתימת פי האמה שנאמר (ויקרא טו, ג) או החתים בשרו מזובו","והאנן תנן מטמאין בכל שהן הוא דאמר כרבי נתן דתניא רבי נתן אומר משום רבי ישמעאל זב צריך כחתימת פי האמה ולא הודו לו","מ\"ט דרבי ישמעאל דאמר קרא או החתים בשרו מזובו","ורבנן ההוא מבעי ליה לח מטמא ואינו מטמא יבש","ורבי ישמעאל ההוא מרר נפקא","ורבנן ההוא למנינא הוא דאתא זובו חדא רר בשרו תרי את זובו תלת לימד על זב בעל שלש ראיות שחייב בקרבן","או החתים בשרו מזובו טמא מקצת זובו טמא לימד על זב בעל שתי ראיות שמטמא משכב ומושב ורבי ישמעאל מנינא מנא ליה נפקא ליה מדרבי סימאי","דתניא רבי סימאי אומר מנה הכתוב שתים וקראו טמא שלש וקראו טמא הא כיצד שתים לטומאה ושלש לקרבן","ולמאן דנפקא ליה תרוייהו (ויקרא טו ) מזאת תהיה טומאתו בזובו (ויקרא טו, ב) איש איש כי יהיה זב מבשרו מאי עביד ליה מבעי ליה עד שיצא מבשרו","זובו טמא למה לי לימד על הזוב שהוא טמא","אמר רב חנילאי משום ר\"א בר\"ש שכבת זרע לרואה במשהו לנוגע בכעדשה והאנן מטמאין בכל שהן תנן מאי לאו לנוגע לא לרואה","ת\"ש חומר בשכבת זרע מבשרץ וחומר בשרץ מבשכבת זרע חומר בשרץ שהשרץ אין חלוקה טומאתו מה שאין כן בשכבת זרע חומר בשכבת זרע שהשכבת זרע מטמא בכל שהוא מה שאין כן בשרץ","מאי לאו לנוגע לא לרואה","והא דומיא דשרץ קתני מה שרץ בנגיעה אף שכבת זרע בנגיעה אמר רב אדא בר אהבה שום שרץ קתני ושום שכבת זרע קתני","ושרץ לא מטמא במשהו והא אנן תנן האברים אין להם שיעור פחות מכזית בשר המת ופחות מכזית בשר נבלה ופחות מכעדשה מן השרץ","שאני אבר דכוליה במקום עדשה קאי דהא אילו חסר פורתא אבר מי קמטמיא","שכבת זרע דחלוקה טומאתו מאי היא אילימא בין ישראל לדנכרים ה\"נ איכא עכבר דים ועכבר דיבשה","אלא בין קטן לגדול","אמר רב פפא כתנאי מנין לרבות נוגע בש\"ז ת\"ל (ויקרא כב, ד) או איש","ופליגי תנאי בעלמא דאיכא דאמרי דון מינה ומינה ואיכא דאמרי דון מינה ואוקי באתרא","למ\"ד דון מינה ומינה מה שרץ בנגיעה אף שכבת זרע בנגיעה ומינה מה שרץ בכעדשה אף ש\"ז בכעדשה","ולמ\"ד דון מינה ואוקי באתרא מה שרץ בנגיעה אף ש\"ז בנגיעה ואוקי באתרא מה ש\"ז לרואה במשהו אף לנוגע במשהו","א\"ל רב הונא בריה דרב נתן לרב פפא ממאי דמאו איש דשרץ קמרבי ליה דילמא מאו איש אשר תצא ממנו שכבת זרע קמרבי ליה ודכ\"ע דון מינה ומינה","שיילינהו לתנאי איכא דתני כרב פפא ואיכא דתני כרב הונא בריה דרב נתן","\u0001מתני׳\u0002 תנוקת בת יום אחד מטמאה בנדה בת י' ימים מטמאה בזיבה","תנוק בן יום אחד מטמא בזיבה ומטמא בנגעים ומטמא בטמא מת וזוקק ליבום ופוטר מן היבום ומאכיל בתרומה ופוסל (את) [מן] התרומה"],[[0,"וירדה וטבלה","לשם יהודית אם תמצי לומר בזבה נעקרו מימי רגליה וירדה וטבלה אזלינן בתר עקירה ה\"מ בישראל דטומאתו מדאורייתא:"],[5,"לח מטמא","דהחתים משמע לח שהיבש אינו חותם פי האמה דנפיל:"],[7,"רר","משמע לח כמו (שמוא\"ל א כא) ויורד רירו:"],[7,"בזובו חדא","זאת תהיה טומאתו בזובו חדא רר תרי את זובו תלת לקרבן:"],[8,"או החתים","לח:"],[8,"מזובו טומאתו היא","מקצת זובו אית ביה טומאת זיבה:"],[9,"שתים וקראו טמא","כי יהיה זב מבשרו חדא זובו טמא תרי טמא:"],[9,"שלש וקראו טמא","זאת תהיה טומאתו בזובו חדא רר בשרו את זובו תרי או החתים בשרו מזובו תלת טומאתו היא:"],[11,"על הזוב","שהטיפה עצמה טמאה:"],[12,"לנוגע בכעדשה","דמנגיעה דשרץ נפקא לן נגיעה דש\"ז לקמן מאו איש אשר יגע וגו':"],[13,"אין לו חלוקת טומאה","דשרץ קטן מטמא כגדול אבל קטן פחות מבן ט' אין לו קרי:"],[15,"שום שרץ קתני","אין לך שרץ מטמא במשהו אבל ש\"ז יש מטמא במשהו כגון לרואה:"],[17,"דכוליה במקום כעדשה קאי","כלומר מתוך חשיבותיה שהוא אבר הוי חשוב במקום כעדשה:"],[17,"תדע דמשום חשיבותא דאבר הוא דהא אילו חסר פורתא","מן האבר דהוי בציר מכעדשה מי מטמא:"],[18,"עכבר דים","אינו מטמא כדתניא בהעור והרוטב (חולין דף קכו:) דעל הארץ כתיב:"],[20,"כתנאי","נוגע אי במשהו אי בכעדשה:"],[20,"ת\"ל או איש","קס\"ד מאו איש אשר יגע בכל שרץ אשר יטמא ילפי':"],[21,"","ושמעי' בעלמא תנאי דפליגי בכמה דוכתי בדון מינה ומינה ובדון מינה ואוקי באתרא הילכך הנהו תנאי על כרחך פליגי בנוגע בקרי למ\"ד דון מינה ומינה דון ש\"ז משרץ דהא מקרא דשרץ ילפינן לה דמה שרץ מטמא בנגיעה אף ש\"ז בנגיעה ומינה מה שרץ בכעדשה כו':"],[21,"ואוקי באתרא","הנח ש\"ז במקומה כדאשכחן בראיה דבמשהו:"],[24,"דילמא מאו איש אשר תצא ממנו כו' ילפינן לה","ואפי' למ\"ד דון מינה ומינה הוה במשהו דהא נגיעה מראיה יליף ודכ\"ע דון מינה ומינה הוה דהכא ליכא פלוגתא דאוקי באתרא דהא מיניה וביה יליף:"],[25,"איכא דתני כרב פפא","מאו איש אשר יגע בכל שרץ:"],[27,"מתני' וזוקק ליבום","אם נולד יום אחד קודם מיתת אחיו אבל נולד לאחר מיתת אחיו אינו זוקק דכתיב (דברים כ״ה:ה׳) כי ישבו אחים יחדו:"],[27,"ופוטר מן היבום","אם נולד לאחר מיתת אביו וחיה שעה אחת ומת אבל כל זמן שמעוברת אינו מתירה לינשא:"],[27,"ומאכיל בתרומה","בת ישראל שניסת לכהן ומת ונולד לה בן לאחר מיתתו אוכלת בשבילו בתרומה בו ביום שנולד כדכתיב (ויקרא כ״ב:י״א) ויליד ביתו הם יאכלו בלחמו ודרשינן יאכילו את אמם אבל הניחה מעוברת אינה אוכלת בשבילו עד שיולד:"],[27,"ופוסל (את) [מן] התרומה","קס\"ד כגון בת כהן שניסת לישראל ומת והניח בן יום אחד פסלה מתרומת בית אביה כל ימי חייו דכתיב (ויקרא כ״ב:י״ג) וזרע אין לה ושבה אל בית אביה והא יש לה זרע ובגמרא פריך אפילו עובר נמי פוסל:"]],[[7,"","את זובו תלת. לא דריש אתין אי נמי אתי לדרשא אחריתי:"],[10,"","עד שיצא מבשרו. ובפרק בנות כותים (לעיל נדה דף לה.) דדריש מבשרו ולא מחמת אונסו תרתי שמעת מינה וא\"ת ול\"ל קרא עד שיצא מבשרו מהיכא תיתי שיטמא בפנים כבחוץ דאי מנדה וזבה הא בריש בנות כותים (נדה דף לב:) מצריך קרא לרבות קטן לזב ולנדה ולזבה ולא ילפינן מהדדי וי\"ל דהוה ילפינן מנדה וזבה ופולטת במה הצד לר\"ש נמי י\"ל כיון דגלי לן קרא ששוין הן זב וזבה לענין קטנים גם לענין פנים כבחוץ היינו משוין אותם אי לאו מבשרו:"],[16,"","והתנן האברים אין להם שעור. וא\"ת וכי' לא ידע דאבר שלם דוקא קאמר וי\"ל דפריך אמאי דמשני דשום שכבת זרע קתני דשום שרץ נמי אשכחן כגון אברים ומשני דלאו היינו כל שהוא דאי חסר ליה טהור:"],[20,"","מנין לרבות נוגע בשכבת זרע ת\"ל או איש. מוהבגד אשר יהיה עליו שכבת זרע לא מצי למילף דבגד חמור מאדם דנושא הנבלה מטמא בגדים בחבורו ולא אדם כדאמר בפ\"ק דבבא בתרא (דף ט:) וא\"ת מ\"ט דריש מאו איש דשרץ ושביק או איש דכתיב בש\"ז גופיה וי\"ל דמסתבר ליה טפי לרבות נוגע מקרא דנוגע ולא מההיא דש\"ז דמיירי ברואה וא\"ת ול\"ל יתורא דאו איש תיפוק ליה מדאיתקש ש\"ז לשרץ דמהאי טעמא ילפינן בשרץ בגד ועור משכבת זרע בפ' במה אשה (שבת דף סד.) ובפרק כיצד הרגל (ב\"ק דף כה:) וי\"ל דאי לאו או איש הוה אמינא דלא הוקשה אלא מ\"ש בפירוש כגון נוגע דשרץ לרואה דש\"ז ומצי למימר דרב פפא דמרבה נוגע מאו איש דשרץ הא דאמר התם דאיתקש אהדדי היינו משום דקרא דשרץ איירי בש\"ז ומאו איש דשרץ נמי לא הוה מוקמינן לנוגע בש\"ז אי לאו דאסמכינהו בהדיא:"],[27,"","ומטמא בנגעים. משום דבנגעים כתיב (ויקרא י״ג:כ״ט) איש או אשה ובטומאת מת נמי כתיב (במדבר י״ט:כ׳) ואיש אשר יטמא ולא יתחטא איצטריך קרא בהו לרבויי אבל לענין זוקק ליבום ופוטר מן היבום ומאכיל תרומה לא כתיב איש ולא איצטריך קרא אלא למעוטי עובר:"]]],[["ונוחל ומנחיל וההורגו חייב והרי הוא לאביו ולאמו ולכל קרוביו כחתן שלם","\u0001גמ׳\u0002 מנהני מילי דת\"ר אשה אין לי אלא אשה בת יום אחד לנדה מנין ת\"ל ואשה","בת י' ימים לזיבה מנא ה\"מ דת\"ר אשה אין לי אלא אשה בת י' ימים לזיבה מנין ת\"ל ואשה","תינוק בן יום אחד כו' מנא הני מילי דת\"ר (ויקרא טו, ב) איש איש מה ת\"ל איש איש לרבות בן יום אחד שמטמא בזיבה דברי רבי יהודה","רבי ישמעאל בנו של רבי יוחנן בן ברוקא אומר אינו צריך הרי הוא אומר (ויקרא טו, לג) והזב את זובו לזכר ולנקבה לזכר כל שהוא בין גדול בין קטן לנקבה כל שהיא בין גדולה בין קטנה אם כן מה ת\"ל איש איש דברה תורה כלשון בני אדם","ומטמא בנגעים דכתיב (ויקרא יג, ב) אדם כי יהיה בעור בשרו אדם כל שהו","ומטמא בטמא מת דכתיב (במדבר יט, יח) ועל הנפשות אשר היו שם נפש כל דהו","וזוקק ליבום דכתיב (דברים כה, ה) כי ישבו אחים יחדיו אחים שהיה להם ישיבה אחת בעולם","ופוטר מן היבום (דברים כה, ה) ובן אין לו אמר רחמנא והא אית ליה","ומאכיל בתרומה דכתיב (ויקרא כב, יא) ויליד ביתו הם יאכלו בלחמו קרי ביה יאכילו בלחמו","ופוסל מן התרומה (ויקרא כב, יג) וזרע אין לה אמר רחמנא והא אית לה","מאי איריא זרע אפילו עובר נמי דכתיב כנעוריה פרט למעוברת","צריכי דאי כתב רחמנא וזרע אין לה משום דמעיקרא חד גופא והשתא תרי גופי אבל הכא דמעיקרא חד גופא והשתא חד גופא אימא תיכול כתב רחמנא כנעוריה","ואי כתב רחמנא כנעוריה משום דמעיקרא גופה סריקא והשתא גופה מליא אבל הכא דמעיקרא גופה סריקא והשתא גופה סריקא אימא תיכול צריכא","קראי אתרוץ אלא מתניתין מאי אריא בן יום אחד אפי' עובר נמי אמר רב ששת הב\"ע בכהן שיש לו שתי נשים אחת גרושה ואחת שאינה גרושה ויש לו בנים משאינה גרושה ויש לו בן יום אחד מן הגרושה","דפוסל בעבדי אביו מלאכול בתרומה ולאפוקי מדר' יוסי דאמר עובר נמי פוסל קמ\"ל בן יום אחד אין עובר לא","נוחל ומנחיל נוחל ממאן מאביו ומנחיל למאן לאחיו מאביו אי בעי מאבוה לירתי ואי בעי מיניה לירתי","אמר רב ששת נוחל בנכסי האם להנחיל לאחיו מן האב ודוקא בן יום אחד אבל עובר לא מ\"ט דהוא מיית ברישא ואין הבן יורש את אמו"],[[0,"ונוחל ומנחיל","מפרש בגמרא:"],[0,"כחתן שלם","מפרש בגמרא:"],[1,"גמ' אשה","ואשה כי תהיה זבה וגו' והאי קרא בנדה משתעי:"],[2,"בת עשרה ימים כו'","ואשה כי תזוב זוב דמה קא דריש:"],[5,"אדם","משמע כל שהוא מין אדם אפילו קטן כדכתיב (במדבר ל״א:ל״ה) ונפש אדם מן הנשים וגו' ובקטנות משתעי קרא:"],[6,"נפשות","כל שיש בו נפש:"],[11,"כנעוריה","ושבה אל בית אביה כנעוריה כלומר אם דומה לימי נעורים ושבה ואם לאו לא תשוב:"],[14,"קראי אתרוץ","דתרוייהו צריכי:"],[14,"אלא מתניתין","מדנקט יום אחד ולא נקט עובר דוקא נקט:"],[14,"אמר רב ששת","האי פוסל לאו אאמו קאי אלא אעבדיו קאי והכא בכהן שהיו לו שתי נשים וכו':"],[14,"אחת גרושה","שהיתה גרושה ועבר ונשאה:"],[14,"ויש לו בנים משאינה גרושה","והן כהנים כשרים ועבדים שנפלו להן בירושה אוכלין בתרומה בשבילן דכתיב (ויקרא כ״ב:י״א) וכהן כי יקנה נפש קנין כספו וגו':"],[14,"ויש לו בן יום אחד מן הגרושה","והוא חלל ואינו ראוי לכהונה ויש לו חלק בעבדים ופוסל את כולן מן התרומה שאין אנו יודעין לברור מי מגיע לחלקו. ודוקא בן יום אחד דראוי לירושה אבל כל זמן שלא נולד אוכלין כולן דאין זכייה לעובר:"],[15,"ולאפוקי מדר' יוסי","דאמר במסכת יבמות בפרק אלמנה לכהן גדול (יבמות דף סז.) יש לו זכייה ואפילו הוא במעי אשה זרה הכשרה לכהונה פוסלה דקסבר כל זמן שהוא במעי זרה זר הוא וכל שכן האי דבמעי גרושה הוא דאפילו כשיולד לא יהא ראוי:"],[16,"לאחיו מן האב","דהא אין ירושה אלא לקרובי האב:"],[16,"אי בעי מאבוה לירת","אפי' חשיבנא ליה כמאן דליתיה ירתי לאחר מיתת אביהם ואיהו מאי אהני:"],[17,"נוחל בנכסי האם","אם מתה אמו ביום שנולד הרי הוא יורשה וכשמת הוא באין אחיו מאביו ויורשין הימנו נכסי אמו דאי לאו איהו הוו שקלי ליה קרובי האם דבן נוחל את אמו. אבל האם אינה נוחלת את בנה וכל שכן קרובי האם שאין נוחלין אותו דכתיב (במדבר א׳:ב׳) למשפחותם לבית אבותם משפחת האם אינה קרויה משפחה:"],[17,"אבל עובר","שבמעיה אם מתה מעוברת אינו נוחל להנחיל את קרוביו מן האב:"]],[[11,"","כנעוריה פרט למעוברת. ואם תאמר תיפוק ליה מוזרע אין לה עיין עליה כי היכי דפסלינן בריש החולץ (יבמות לה:) חליצת מעוברת מאין לו עיין עליו וי\"ל דהתם לא קאמר אלא עיין והמתן אם יהיה ולד של קיימא אבל לא מיפטרא מן היבום משום דכתיב אין לו וה\"נ לא מיפסלא מן התרומה בהכי:"],[14,"","אמר רב ששת הכא במאי עסקינן בכהן שיש לו ב' נשים. וא\"ת למה לי ב' נשים לוקמה באשה אחת גרושה ויש לו בן אחד ממנה דדוקא בן יום אחד פוסל ולא עובר ואכלי העבדים בשביל כל המשפחה כולה לרבנן דר' יוסי כדאמר ביבמות בפרק אלמנה (דף סז.) ועוד הקשה ה\"ר אפרים דבפרק מי שמת (ב\"ב דף קמב.) אמר רב ששת אחד זה ואחד זה קנה בין מזכה לעובר בין לכשתלד ופריך ליה ממתני' דבן יום אחד נוחל אבל עובר לא ומשני דהתם משום דאיהו מיית ברישא והשתא ליפרוך מרישא דבן יום אחד פוסל אבל עובר לא משום דעובר לית ליה זכייה כדמפרש הכא רב ששת גופיה ולא ה\"מ לשנויי מידי וי\"ל דסבר רב ששת דלרבנן דר' יוסי נמי עובר אית ליה זכייה וטעמא דעובר אינו פוסל משום סמוך מיעוטא דמפילות למחצה דנקבות והוה ליה זכרים מיעוטא ולמיעוטא לא חיישינן כדחייש רבי יוסי ולהכי אוקי הכא בכהן שיש לו ב' נשים ויש לו בנים משאינה גרושה דכיון דיש לו בנים לא פסיל עובר אף ע\"ג דיש לו זכייה דלא חיישינן למיעוט הזכרים כדפי' אבל אם אין לו בנים פוסל עובר גם לרבנן דאית ליה זכייה דבין הוא זכר בין היא נקבה הרי הן שלה ופליג רב ששת אשמואל דאמר בפרק אלמנה (יבמות דף סז.) דלרבנן אוכלין בשביל כל המשפחה כולה דסבר שמואל דלרבנן לית ליה זכייה לעובר והשתא ניחא הא דקאמר התם רב ששת מנא אמינא לה דתניא גר שמת כו' ולא דחי ליה דהך ברייתא כר' יוסי דרבנן נמי לא פליגי אלא דלא חיישי למיעוטא כדפי' ואם תאמר דבפרק מי שמת (ב\"ב דף קמב.) גבי גר שמת ובזבזו ישראל נכסיו והיתה אשתו מעוברת לא קנו שמעו אחרי כן שהפילה אשתו המחזיק בשניה קנה בראשונה לא קנה אמאי לא קנה המחזיק בראשונה כיון דלבסוף הפילה הא בפ' אלמנה (יבמות סז:) אמרינן דזכרים הוו מיעוטא משום מיעוטא דמפילות ואין לעובר שסופו להיות נפל חלק בעבדים וי\"ל דהתם משום דתלינן שמא כבר בשעת אכילת העבדים מת העובר בבטן ולית ליה זכייה:"],[16,"","ואי בעי מיניה לירות כו'. וא\"ת דבפרק מי שמת (ב\"ב קמב.) דפריך לרב ששת מהך דבן יום א' נוחל ומנחיל אבל עובר לא ומשני נוחל את האם להנחיל לאחים מן האב והשתא מה היתה סברת המקשה דע\"כ צריך לומר כדמשני רב ששת דאי לאו הכי תקשה ליה אי בעי מיניה לירות אי בעי מאבוה לירות כדמקשה הכא וי\"ל דיפרש כמר בריה דרב יוסף שממעט בחלק בכורה אבל עובר לא ולאו משום וילדו לו אלא משום דעובר לית ליה זכייה א\"נ ידע שפיר כדמשני רב ששת נוחל את האם להנחיל לאחיו מן האב אך היה סבור דאיהי מייתא ברישא וקאמר עובר לא משום דלא קנה ובשילהי פ\"ק דערכין (דף ז.) דאמר שמואל אשה שיצתה ליהרג מכין אותה כנגד הריון שלה כדי שימות הולד תחלה הא לאו הכי הולד מת לבסוף ופריך ליה מהא דבן יום אחד נוחל אלמא ולד מת תחלה הוה מצי לשנויי אבל עובר לא לומר שממעט בחלק בכור כדאמר בשמעתין אלא דניחא ליה לאוקמי מילתא דרב ששת דאמר הכא איהו מיית ברישא אליבא דשמואל ולחלק האמת שיש חילוק בין מתה לנהרגה:"],[17,"","איהו מיית ברישא. והא דתנן בפ' בהמה המקשה (חולין דף עד.) השוחט את הבהמה ומצא בה בן ט' חי יש חילוק בין מתה לנהרגה כדאמר בערכין (דף ז.) והא דאמר נמי בהשוחט במתה אמה והדר ילידתיה היינו נמי כשנהרגה אי נמי כגון דמתה אמו מחמת לידה דכיון דעקר הולד לצאת אז לא מיית כדאמר שמואל שילהי פ\"ק דערכין (דף ז.) ישבה על המשבר ומתה מחתכין אותה בשבת ומוציאין הולד וא\"ת אם כן עובר נוחל ומנחיל בישבה על המשבר ומתה תחלה י\"ל דאין הכי נמי ונקט בן יום אחד משום דפסיקא ליה דנוחל ומנחיל אבל עובר לא פסיקא ליה ומיהא בן יום אחד ההורגו חייב דקתני אבל עובר לא היינו אפילו נהרגה או ישבה על המשבר עד שיצא ראשו כדתנן במסכת אהלות פ\"ז (משנה ו) ומייתי לה בפרק בן סורר ומורה (סנהדרין דף עב:) אשה המקשה חותך אבר יצא ראשו אין דוחין נפש מפני נפש ומיהו אפשר דדוקא היכא דאמו חיה לא מיחייב ההורגו עד שיצא ראשו שתלוי קצת בחיות אמו אבל היכא דמתה חייב משום דכמונח בקופסא דמי וא\"ת אם תמצי לומר דמותר להורגו בבטן אפי' מתה אמו ולא הוי כמונח בקופסא אמאי מחללין עליו את השבת שמביאין סכין דרך ר\"ה לקרוע האם כדמוכח בפ' קמא דערכין (דף ז:) וי\"ל דמכל מקום משום פקוח נפש מחללין עליו את השבת אף ע\"ג דמותר להרגו דהא גוסס בידי אדם ההורגו פטור כדאמר פרק הנשרפין (סנהדרין עח.) דרוב גוססים למיתה ומחללין את השבת עליו כדאמר פרק בתרא דיומא (ד' פד:) דאין מהלכין בפקוח נפש אחר הרוב:"]]],[["בקבר להנחיל לאחיו מן האב","איני והא הוה עובדא ופרכס עד תלת פרכוסי אמר מר בריה דרב אשי מידי דהוה אזנב הלטאה דמפרכסת","מר בריה דרב יוסף משמיה דרבא אמר לומר שממעט בחלק בכורה ואמר מר בריה דרב יוסף משמיה דרבא בן שנולד אחר מיתת האב אינו ממעט בחלק בכורה מאי טעמא (דברים כא, טו) וילדו לו בעינן","בסורא מתנו הכי בפומבדיתא מתנו הכי אמר מר בריה דרב יוסף משמיה דרבא בכור שנולד לאחר מיתת אביו אינו נוטל פי שנים מאי טעמא (דברים כ״א:י״ז ) יכיר בעינן והא ליכא","והלכתא ככל הני לישני דמר בריה דרב יוסף משמיה דרבא","וההורגו חייב דכתיב (ויקרא כד, יז) ואיש כי יכה כל נפש מ\"מ","והרי הוא לאביו ולאמו ולכל קרוביו כחתן שלם למאי הלכתא אמר רב פפא לענין אבלות","כמאן דלא כרשב\"ג דאמר כל ששהה שלשים יום באדם אינו נפל הא לא שהה ספק הוי הכא במאי עסקינן דקים ליה שכלו לו חדשיו","\u0001מתני׳\u0002 בת שלש שנים ויום אחד מתקדשת בביאה ואם בא עליה יבם קנאה וחייבין עליה משום אשת איש","ומטמאה את בועלה לטמא משכב תחתון כעליון","נשאת לכהן תאכל בתרומה בא עליה אחד מן הפסולין פסלה מן הכהונה בא עליה אחד מכל העריות האמורות בתורה מומתין עליה והיא פטורה","פחות מכן כנותן אצבע בעין","\u0001גמ׳\u0002 ת\"ר בת ג' שנים מתקדשת בביאה דברי רבי מאיר וחכ\"א בת ג' שנים ויום אחד מאי בינייהו אמרי דבי רבי ינאי ערב ראש השנה איכא בינייהו","ור' יוחנן אמר ל' יום בשנה חשובין שנה איכא בינייהו","מיתיבי בת ג' שנים ואפי' בת שתי שנים ויום אחד מתקדשת בביאה דברי רבי מאיר וחכמים אומרים בת שלשה שנים ויום אחד"],[[0,"בקבר","כי מת הוא קודם לה:"],[1,"ופרכס","עובר שבמעי אמו אחר מיתתה תלתא פרכוסי. אלמא היא מייתה ברישא:"],[2,"לומר שממעט כו'","מתניתין דקתני נוחל ומנחיל לומר שממעט בחלק בכורה כגון אם היה בן יום אחד כשמת אביו והיה לו אח בכור ואח פשוט ומת הוא אחר אביו נוחל הוא מאביו את חלק רביעי שבנכסיו ומנחילו לשני אחיו וחולקין הבכור והפשוט את חלקו של זה בשוה ונמצא ממעט בחלק הבכור דאי לאו איהו הוה שקיל בכור תרי תילתי כגון מששה זהובים ארבעה ופשוט נוטל ב' זהובים ועכשיו נוטל הבכור ג' זהובים כנגד שני אחין ומחלקו של זה ג' רבעי זהוב נמצאו ביד בכור ד' זהובים חסר רביע וביד פשוט ב' זהובים ורביע. ודוקא בן יום א' אבל עובר אינו ממעט כדאמר לקמן בן שנולד לאחר מיתת אביו אינו ממעט בחלק הבכורה ונוטל הבכור שליש בכורתו ובין שלשתן יחלקו ב' שלישים:"],[2,"מאי טעמא","אמרינן בן יום אחד דממעט אבל עובר לא:"],[2,"וילדו לו בעינן","משמע בחייו:"],[3,"בכור שנולד אחר מיתת אביו","כגון מת אביו והאשה מעוברת תאומים אין היוצא ראשון נוטל פי שנים. בלאו תאומים לא משכחת לה דכיון דבכור לא נולד עד מות אביו פשוט מהיכן בא. אי נמי שהניח ב' נשים מעוברות:"],[7,"כמאן דלא כר' שמעון","אכולה מתני' קאי דקא חשיב בן יום אחד בן קיימא:"],[7,"באדם","דאילו בבהמה שמונה ימים לא הוי נפל:"],[8,"מתני' בת ג' שנים","ביאתה ביאה לכל דבר:"],[8,"מתקדשת","אם מסרה אביה לכך:"],[8,"אם בא עליה יבם קנאה","וזכה בנכסי אחיו ליורשה ולטמא לה:"],[8,"וחייבין עליה","אם קבל בה אביה קדושין מזה ובא אחר עליה נהרג דביאתה ביאה:"],[9,"ומטמאה את בועלה","אם היא נדה. אבל פחות מכן אע\"ג שמטמאה במגע אינה מטמאה את בועלה משום בועל נדה לטומאת ז' אלא משום נוגע ולטומאת ערב:"],[9,"תחתון","של בועל נדה:"],[9,"כעליונו","של זב:"],[10,"מן הפסולין","כגון חלל נתין וממזר ועבד ועובד כוכבים:"],[10,"פסלה","מתרומת אביה אם היא בת כהן כדתניא בגמרא דאלמנה לכהן גדול ביבמות (דף סח.) מנין לכהנת לויה וישראלית שבא עליהן כו' ת\"ל כי תהיה לאיש זר כיון שנבעלה לפסול לה פסלה:"],[10,"מכל העריות","כגון אביה או חמיה:"],[10,"והיא פטורה","מפני שהיא קטנה ולאו בת עונשין:"],[12,"גמ' ערב ראש השנה","של שנה רביעית לרבי מאיר גופיה לא הוי בת ביאה עד יום אחרון של שלישית דהוא ערב ראש השנה ולרבנן עד למחר דמיקלע יום ראשון ברביעית:"],[13,"שלשים יום איכא בינייהו","לרבי מאיר מכי איקלע שלשים יום בשנה שלישית הויא בת ביאה ולרבנן עד דמיקלע שנה רביעית ואיכא בינייהו טובא:"]],[[2,"","מאי טעמא וילדו לו בעינן. למ\"ד המזכה לעובר לא קנה לא איצטריך למדרש מוילדו כדאמר בפ' מי שמת (ב\"ב דף קמב:):"],[5,"","איש כי יכה כל נפש אפילו כל דהו. האי קרא כתיב באמור אל הכהנים ותימה דבריש הנחנקין (סנהדרין דף פד:) דריש מקרא אחרינא דכתיב באלה מסעי כל מכה נפש:"],[7,"","הא לא שהה ספקא הוי. משמע הכא דלרבנן הוי טפי בר קיימא מלרשב\"ג דאפילו בן יום א' הוי לדידהו בן קיימא וכן בפ' החולץ (יבמות דף לו:) ואילו בתוספתא מתניא פלוגתייהו על בן ח' דלרבנן אפילו שהה שלשים יום הוי נפל ואתא רשב\"ג למימר דאם שהה ל' יום הוי בר קיימא דאמר בן ז' הוא ואישתהויי אשתהי וכן בפרק הערל (יבמות דף פ:) ויש לומר דבתרתי פליגי ודייק מדלא קאמר רשב\"ג אם שהה ל' יום אינו נפל כיון דקאי ארבנן דאמרי בבר ח' דהוי נפל ומדנקט כל ששהה משמע דבכל ולדות בעי רשב\"ג יום ל' ואם כן שמעינהו לרבנן דלאו בל' תלוי אלא בחדשי ההריון:"],[7,"","דקים ליה דכלו לו חדשיו. הא לא קים ליה ספקא הוי ובנפל מן הגג או אכלו ארי איירי דבפיהק ומת אפילו לרבנן הוי נפל כדאמר פרק רבי אליעזר אם לא הביא (שבת קלו.) ואם תאמר אם כן מאי טעמא דרשב\"ג כיון דליכא ריעותא אמאי אינו מתאבל עליו דניזיל אחר רוב ולדות דהוו בני קיימא ובפ' רבי אליעזר אם לא הביא (שם) דאסר ההוא עגלה דאשתחיט ביומא דשביעאה משום דהתם פסיק הלכה כרשב\"ג אמאי לא אזלינן בתר רובא וי\"ל דנפלין הוי מיעוט דשכיח ודבר ההווה הוא ולכך החמירו חכמים ולענין אבלות הקילו וגדולה מזאת מצינו דאמר בפרק יש בכור (בכורות דף מט.) דיום ל' כשלפניו לענין אבלות אע\"ג דקי\"ל בהחולץ (יבמות לו:) דמת ביום ל' ועמדה ונתקדשה אם אשת כהן היא אינה חולצת דחשיב בר קיימא וא\"ת דהכא אמר דבלא שהה ספקא הוא ואינו מתאבל עליו ובמסכת שמחות (פ\"ד ה\"ב) תנן ספק אחיו ספק אינו אחיו מתאבל עליו וי\"ל דשאני התם כיון דבר קיימא הוא אי אין מתאבל עליו סברי עלמא דאין מתאבלין על אחין א\"נ בספק בן ט' לראשון או בן ז' לאחרון דמה נפשך חד מינייהו חייב וגנאי הדבר לפטור שניהם:"],[13,"","שלשים יום איכא בינייהו. הא דלא קאמר יום אחד בשנה חשוב שנה איכא בינייהו דלרבי מאיר בב' שנים ויום אחד סגי ולא הוי פליג אברייתא דבסמוך היינו משום דשנת ג' בשביל יום אחד לא הוה קרי ליה שלש שנים וא\"ת ולימא דיום ראשון של שנה רביעית איכא בינייהו דלרבי מאיר במקצת היום סגי ולרבנן בעינן מעת לעת עד שעה שנולדה כדאמר פ\"ב דזבחים (דף כה:) דשעות פוסלות בקדשים וי\"ל דקים ליה דרבנן לא בעו מעת לעת ועוד דאם כן אף לר' מאיר הוה ליה למתני ג' שנים ויום אחד והוה ליה לפרושי דלא בעינן מעת לעת והא דתנן בפרק אלו נערות (כתובות דף כט.) הגיורת שנתגיירה פחותה מבת ג' שנים ויום אחד יש לה קנס לא אתיא כרבי מאיר מדמצריך יום אחד אחר שלש שנים ואם תאמר והיכי מוכח התם דרישא כרבי מאיר דקאמר פרק אלו נערות נערה אין קטנה לא והתם ע\"כ אסיפא דמתני' סמיך דקתני כל מקום שיש מכר אין קנס דמנערות איכא למימר דלא אתי למעוטי קטנות אלא בוגרות דבפרק ארבע מיתות (סנהדרין דף סו:) תנן אין חייב הבא על נערה המאורסה עד שתהא נערה ודייק התם דאתא לאפוקי קטנה דאי לאפוקי בוגרת אלא על נערה מבעי ליה אלמא נערה אפילו קטנה משמע אלא אסיפא סמיך כדפרישית והיכי דייק מסיפא דמתני' דרישא נמי ר\"מ כיון דמציעתא לא אתיא כוותיה וי\"ל דלאו ממש ר\"מ היא קאמר אלא דדייק דתנא דההוא פירקא סבר דקטנה אין לה קנס כדקתני בסיפא וא\"כ נערות נקט לאפוקי קטנות ורבא דפריך בפ\"ק דכתובות (דף יא.) הגיורת יש לה קנס יהבינן לה קנס דאזלה ואכלה בהיותה נכרית אלמא סבר דמתני' סבר דקטנה יש לה קנס היינו משום דסבר כיון דהך בבא דגיורת לא אתיא כר' מאיר במאי דנקט שלש שנים ויום אחד אם כן גם לענין דקטנה יש לה קנס אתיא כרבנן וה\"ה דפריך בפ' ד' וה' (ב\"ק לח:) ממתני' דאלו נערות (דף כט.) דקתני כותית יש לה קנס לרבי מאיר אע\"ג דההיא דגיורת לא אתיא כר\"מ מ\"מ כיון דסתם מתני' ר\"מ היא מאי דמצינן לאוקומי כוותיה מוקמינן:"]]],[["בשלמא לר' יוחנן כי היכי דאיכא תנא דקאמר יום אחד בשנה חשוב שנה הכי נמי איכא תנא דאמר ל' יום בשנה חשובין שנה","אלא לר' ינאי קשיא קשיא","פחות מכאן כנותן אצבע בעין איבעיא להו הני בתולין מיזל אזלי ואתו או דלמא אתצודי הוא דלא מתצדי עד לאחר ג'","למאי נפקא מינה כגון שבעל בתוך ג' ומצא דם ובעל לאחר שלש ולא מצא דם אי אמרת מיזל אזלי ואתו שהות הוא דלא הויא להו","אלא אי אמרת אתצודי הוא דלא מתצדי עד לאחר ג' הא אחר בא עליה מאי","מתקיף לה רב חייא בריה דרב איקא ומאן לימא לן דמכה שבתוך ג' אינה חוזרת לאלתר שמא חוזרת לאלתר והא אחר בא עליה","אלא נפקא מינה כגון שבעל בתוך ג' ומצא דם ובעל לאחר ג' ומצא דם אי אמרת מיזל אזלי ואתו האי דם בתולין הוא אלא אי אמרת אתצודי הוא דלא מתצדי אלא עד לאחר ג' האי דם נדה הוא מאי","אמר רב חסדא ת\"ש פחות מכאן כנותן אצבע בעין למה לי למתני כנותן אצבע בעין לתני פחות מכאן ולא כלום מאי לאו הא קמ\"ל מה עין מדמעת וחוזרת ומדמעת אף בתולין מיזל אזלי ואתי","ת\"ר מעשה ביוסטני בתו של אסוירוס בן אנטנינוס שבאת לפני רבי אמרה לו רבי אשה בכמה ניסת אמר לה בת ג' שנים ויום אחד","ובכמה מתעברת אמר לה בת י\"ב שנה ויום אחד אמרה לו אני נשאתי בשש וילדתי בשבע אוי לשלש שנים שאבדתי בבית אבא","ומי מעברה והתני רב ביבי קמיה דרב נחמן ג' נשים משמשות במוך קטנה מעוברת ומניקה","קטנה שמא תתעבר ותמות מעוברת שמא תעשה עוברה סנדל מניקה שמא תגמול את בנה וימות","ואיזוהי קטנה מבת י\"א שנה ויום אחד ועד י\"ב שנה ויום אחד פחות מכאן או יתר על כן משמשת והולכת דברי ר\"מ","וחכ\"א אחת זו ואחת זו משמשת כדרכה והולכת ומן השמים ירחמו שנאמר (תהלים קטז, ו) שומר פתאים ה'","איבעית אימא (יחזקאל כג, כ) אשר בשר חמורים בשרם ואיבעית אימא (תהלים קמד, ח) אשר פיהם דבר שוא וימינם ימין שקר","ת\"ר מעשה באשה אחת שבאת לפני ר\"ע אמרה לו ר' נבעלתי בתוך שלש שנים מה אני לכהונה אמר לה כשרה את לכהונה","אמרה לו רבי אמשול לך משל למה הדבר דומה לתינוק שטמנו לו אצבעו בדבש פעם ראשונה ושניה גוער בה שלישית מצצה אמר לה אם כן פסולה את לכהונה","ראה התלמידים מסתכלים זה בזה אמר להם למה הדבר קשה בעיניכם [אמרו ליה] כשם שכל התורה הלכה למשה מסיני כך פחותה מבת שלש שנים כשרה לכהונה הלכה למשה מסיני ואף רבי עקיבא לא אמרה אלא לחדד בה את התלמידים","\u0001מתני׳\u0002 בן תשע שנים ויום אחד שבא על יבמתו קנאה ואין נותן גט עד שיגדיל","ומטמא בנדה לטמא משכב תחתון כעליון","ופוסל ואינו מאכיל בתרומה ופוסל את הבהמה מע\"ג המזבח ונסקלת על ידו ואם בא על אחת מכל העריות האמורות בתורה מומתין על ידו והוא פטור","\u0001גמ׳\u0002 ולכשיגדיל בגט סגי לה והתניא עשו ביאת בן ט' כמאמר בגדול","מה מאמר בגדול צריך גט למאמרו וחליצה לזיקתו אף ביאת בן ט' צריך גט למאמרו וחליצה לזיקתו","אמר רב הכי קאמר"],[[0,"בשלמא לרבי יוחנן","דאמר מכי איקלע חשיבות שנה בשנה שלישית לרבי מאיר הויא בת ביאה ניחא ואע\"ג דאמר רבי יוחנן ל' יום והכא קתני יום אחד תנאי היא בפרק ארבעה ראשי שנים (ר\"ה דף י.) דאיכא למ\"ד יום אחד בשנה חשוב שנה ואיכא למאן דאמר כו':"],[1,"אלא לרבי ינאי","דאמר לר\"מ עד סוף שנה שלישית לאו בת ביאה היא קשיא:"],[2,"הני בתולין","בתוך ג' שנים:"],[2,"איתצוד","לשון צידה. כלומר אינן ניטלין על ידי ביאה ואינו דם בתולין עד ג' שנים ויום אחד:"],[3,"אי אמרת מיזל אזלי","בביאה בתוך ג' לגמרי והדר אתו לא מחזקינן לה כזונה דהא דלא הדור שהות הוא דלא הויא להו מתוך בעילה שבעל תדיר:"],[4,"אלא אי אמרת","לא אזלי בביאה תוך ג' הוה ליה למיתי דם לאחר ג' וכיון דלא חזיא אחר בא עליה לאחר ג' וזונה היא ופסולה לכהונה:"],[5,"ומאן לימא לן","כלומר אפי' אם תמצי לומר מיזל אזלי בביאה תוך ג' מי איכא למימר שהות לא הוה להו מאן לימא לן דלא הדרי לאלתר:"],[6,"האי דם נדה הוא","האי דתוך ג':"],[8,"","יוסטני:"],[9,"אוי לשלש שנים שאבדתי","משנראיתי לביאה:"],[10,"משמשות במוך","תקנתן הוה לשמש במוך שלא יתעברו:"],[11,"סנדל","כשמתעברת תאומים פעמים שאחד דוחק את חבירו ופוחת את צורתו כדאמרינן במכילתין אין סנדל שאין עמו ולד:"],[11,"תגמול","תפריש את בנה מלהניק מחמת עיבורה:"],[12,"פחות מכן","אינה צריכה לשמש במוך דודאי לא תתעבר:"],[12,"יתר על כן","אם תתעבר לא תמות:"],[16,"מצצה","כלומר אף אני טעמתי טעם זנות:"],[17,"לא אמרה","הא דקאמר פסולה לכהונה אלא לחדד:"],[18,"מתני' קנאה","וזכה בנכסי אחיו ואע\"ג שאין קנין לקטן הרי קנויה לו ועומדת:"],[18,"ואינו נותן גט עד שיגדיל","אם בא לגרשה דקידושי אחיו קידושין גמורין וגירושין של זה אינם גירושין גמורין דאינו בן דעת:"],[19,"ומטמא בנדה","אם בא עליה דביאתו ביאה לכל דבר:"],[20,"ופוסל","כגון בן ט' שנים כותי או ממזר שבא על הכהנת פסלה מתרומת אביה אבל בבן תשע ישראל שבא על בת כהן ליכא למימר דפוסל מן התרומה דאי משום ביאת זנות לא פסלה זנות דכשר מן התרומה ואי משום קדושין למהוי בת כהן לישראל לאו קדושין נינהו דקטן דקדיש אין קדושיו קדושין:"],[20,"ואינו מאכיל","כגון יבם בן ט' כהן הבא על יבמתו אע\"ג דקני לה בהך ביאה לא אכלה בתרומה:"],[20,"ופוסל את הבהמה","אם רבעה ע\"פ עד אחד או ע\"פ הבעלים אבל סקילה לא דמודה בקנס פטור:"],[20,"ונסקלת על ידו","אם יש עדים:"],[21,"גמ' בגט סגיא לה","בתמיה אם בא לגרשה:"],[22,"מאמר","קידושי יבמה:"],[22,"וחליצה לזיקתו","דאין קדושין גומרין ביבמה להיות כאשתו לצאת בגט בלא חליצה אבל ביאה גומרת בה כדכתי' (דברים כה) יבא עליה:"],[22,"ביאת בן תשע","ביבמתו:"]],[[5,"","אחר בא עליה. ואם אשת כהן היא אסורה אבל אשת ישראל לא דפיתוי קטנה אונס הוא ואם תאמר אמאי דחיק לאשכוחי נפקותא שבא עליה אחר לגבי זנות לימא בפשיטות כגון שבעל תוך שלשה ומצא דם דאי לא מיתצדו האי דם נדות הוא כדאמר בסמוך וי\"ל דניחא ליה לאשכוחי לענין זנות דהויא כל ימיה אסורה לבעלה ותו דלענין אי הוה דם נדות או דם בתולין לא נפקא מינה האידנא מידי דאפילו הוא דם בתולים הא תקון דבועל בעילת מצוה ופורש:"],[6,"","האי דם נדה הוא. פירוש הך דתוך ג' דהך דלאחר ג' לכ\"ע הוי דם בתולין ותימה דאמאי נקט כלל שבעל אחר ג' כיון דלא נפקא מינה מידי ופירש ר\"ת משום דנקטיה לעיל נקטיה נמי הכא ומיהו י\"ל אף דם שלאחר ג' יש להסתפק בדם נדה אי אמרינן איתצודי הוא דלא מיתצוד כיון דבתוך ג' ראתה ודאי דם נדות אם כן דרכה לראות מחמת חימוד בעילה אם כן גם אחר ג' יש להסתפק בדם נדה ובתשובה אחת פרש\"י דאיתצודי הוא דלא מיתצוד דקאמר היינו דלא שכיח הוא דמיתצוד אבל כי איתצודי תו לא הדרי וקאמר דנפקא מינה דבעל תוך ג' ומצא דם ואחר ג' לא מצא דאי לא איתצוד האי אחר בא עליה דליכא אלא ספיקא אחת דאי דם בתולין היה תוך ג' מותרת ואם דם נדה היה הרי היא זונה והדר קאמר שבעל ומצא דם תוך ג' ואחר ג' דאיכא לספוקי בתרווייהו בדם נדה דאי בתוך ג' דם בתולין אחר ג' דם נדה דהא לא הדרי ואי תוך ג' דם נדה הוא אחר ג' דם בתולין וקשה לפי זה דאמאי לא אשכחן לענין זנות דמצא דם תוך ג' ושוב לא בעל עד י\"ב שנים ולא מצא דם דאי מיזל ואתו האי אחר בא עליה אע\"ג דספק בא עליה אחר בקטנות או בגדלות כיון דספקא אחת היא אסורה אף לבעלה ישראל ואי אתצודי לא מיתצוד שריא לבעלה ישראל דאימור דם דתוך ג' דם בתולין הוה ואפי' אי הוה דם נדות אימר אחר בא עליה בקטנות ואונס הוה וי\"ל דאין רגילות שישהא עד י\"ב שנה מלבא על אשתו:"],[8,"","בת י\"ג שנים ויום א'. תימה דלקמן תניא אלו דברי רבי אמתני' דקתני בת י\"ב ויום אחד נדרה נדר ויש ספרים דגרסי בת י\"ב ויום אחד ואי גרסינן בת י\"ד שנה בלא יום אחד אתי שפיר ומתעברת ויולדת קאמר ושנת י\"ג אין צריך להיות שלם:"],[15,"","מה אני לכהונה. שנבעלה לפסול לה:"]]],[["לכשיגדיל יבעול ויתן גט","\u0001מתני׳\u0002 בת אחת עשרה שנה ויום א' נדריה נבדקין בת שתים עשרה שנה ויום א' נדריה קיימין ובודקין כל שתים עשרה","בן שתים עשרה שנה ויום אחד נדריו נבדקין בן י\"ג שנה ויום אחד נדריו קיימין ובודקין כל שלש עשרה","קודם לזמן הזה אע\"פ שאמרו יודעין אנו לשם מי נדרנו לשם מי הקדשנו אין נדריהם נדר ואין הקדשן הקדש לאחר הזמן הזה אע\"פ שאמרו אין אנו יודעין לשם מי נדרנו לשם מי הקדשנו נדרן נדר והקדשן הקדש","\u0001גמ׳\u0002 וכיון דתנא בת אחת עשרה שנה ויום א' נדריה נבדקין בת י\"ב שנה ויום א' נדריה קיימין למה לי סד\"א בודקין לעולם קמ\"ל","וכיון דתני בת י\"ב שנה ויום אחד נדריה קיימין בודקין כל שתים עשרה למה לי סלקא דעתך אמינא הואיל ואמר מר ל' יום בשנה חשובים שנה היכא דבדקנא ל' ולא ידעה להפלות אימא תו לא ליבדוק קמ\"ל","ולתני הני תרתי בבי בת י\"ב שנה ויום א' נדריה קיימין ובודקין כל י\"ב בת אחת עשרה ויום א' נדריה נבדקין למה לי","איצטריך סד\"א סתמא בשתים עשרה בעיא בדיקה באחת עשרה לא בעיא בדיקה והיכא דחזינן לה דחריפא טפי מיבדקה באחת עשרה קמ\"ל","קודם הזמן הזה ואחר הזמן הזה למה לי סד\"א הנ\"מ היכא דלא קאמרי אינהו אבל היכא דקאמרי אינהו נסמוך עלייהו קמ\"ל","ת\"ר אלו דברי רבי ר\"ש בן אלעזר אומר דברים האמורים בתינוקת בתינוק אמורים דברים האמורים בתנוק בתנוקת אמורים","א\"ר חסדא מ\"ט דרבי דכתיב (בראשית ב׳:כ״ב ) ויבן ה' [אלהים] את הצלע מלמד שנתן הקב\"ה בינה יתירה באשה יותר מבאיש","ואידך ההוא מבעי ליה לכדריש לקיש דאמר ריש לקיש משום ר\"ש בן מנסיא ויבן ה' [אלהים] את הצלע אשר לקח מן האדם לאשה ויביאה אל האדם מלמד שקלעה הקב\"ה לחוה והביאה אצל אדם הראשון שכן בכרכי הים קורין לקלעיתא בנייתא","ור\"ש בן אלעזר מ\"ט אמר רב שמואל בר רב יצחק מתוך שהתינוק מצוי בבית רבו נכנסת בו ערמומית תחלה","איבעיא להו תוך זמן כלפני זמן או כלאחר זמן","למאי הלכתא אי לנדרים לאו כלפני זמן דמיא ולאו כלאחר זמן דמיא","אלא לעונשין מאי רב ור' חנינא דאמרי תרווייהו תוך זמן כלפני זמן ר' יוחנן ור' יהושע בן לוי דאמרי תרווייהו תוך זמן כלאחר זמן","אמר רב נחמן בר יצחק וסימניך (רות ד, ז) וזאת לפנים בישראל","מתיב רב המנונא אחר זמן הזה אע\"פ שאמרו אין אנו יודעים לשם מי נדרנו לשם מי הקדשנו נדריהם נדר והקדשן הקדש הא תוך זמן כלפני זמן","אמר ליה רבא אימא רישא קודם הזמן הזה אע\"פ שאמרו יודעים אנו לשם מי נדרנו לשם מי הקדשנו אין נדריהם נדר ואין הקדשן הקדש הא תוך זמן כלאחר זמן","ולא היא רבא קטעי הוא סבר רב המנונא ממשנה יתירה קדייק ואדדייק מסיפא לידוק מרישא","ולא היא רב המנונא מגופא דמתניתין קא דייק הא לאחר זמן היכי דמי אי דלא אייתי שתי שערות קטן הוא אלא לאו דאייתי שתי שערות"],[[0,"לכשיגדיל יבעול","והך ביאה הוי קנין גמור ואם בא לגרשה אינה צריכה חליצה דכתיב (דברים כ״ה:ה׳) ולקחה לו לאשה כיון שלקחה נעשית כאשתו לכל דבר:"],[1,"מתני' נבדקין","אם ידעה לשם מי נדרה ולשם מי הקדישה:"],[3,"קודם הזמן הזה","כגון בתינוקת קודם שיבא ראש השנה של שתים עשרה ובתינוק קודם ראש השנה של שלש עשרה:"],[3,"אין נדריהן נדר","דקטנים הן:"],[3,"אחר הזמן הזה","בתינוקת מבת שתים עשרה ויום אחד ולמעלה בתינוק מי\"ג שנה ויום אחד ולמעלה:"],[3,"אפילו אמרו אין אנו יודעין כו'","גדולים הם ובכלל שוטה נמי לא מחזקינן להו דסופו לבא לכלל דעת ואין שוטה אלא המקרע כסותו והלן בבית הקברות והיוצא יחידי בלילה. אבל תוך הזמן הזה אם יודע לשם מי נדר הוי נדר ואם לאו לא הוי נדר דקטן הוא. ובגמרא מפרש כולה מילתא:"],[4,"גמ' למה לי","ממילא ידענא דמכאן ואילך לא בעי בדיקה:"],[4,"סד\"א בודקין לעולם","והאי דקתני בת אחת עשרה נבדקין למעוטי קודם זמן הזה דלא בדקינן ליה דאפילו ידע קטן הוא קמ\"ל דלמעוטי אחר זמן נמי אתא:"],[5,"בודקין כל י\"ב למה לי","הא תנא דמיום א' בשתים עשרה מתחילין לבדוק ואינן קיימין בלא בדיקה עד יום אחד בי\"ג אלמא כל י\"ב הוי זמן בדיקה:"],[5,"היכא דבדקנא ל' יום","קמאי דשתים עשרה:"],[5,"ולא ידעה להפלות","לפרש לשם מי נדרה. ולישנא דקרא נקט כי יפליא לנדור:"],[5,"תו לא נבדוק","וליחזקה בקטנה:"],[6,"בת י\"א כו' למה לי","מדתנן ליה בודקין כל י\"ב שמעינן דמקמי הכי לא:"],[8,"הני מילי","דמקמי הכי מוחזקין קטנים ולאחר זמן מוחזקין גדולים:"],[8,"היכא דלא קאמרי אינהו","קודם הזמן יודעין אנו ולאחר זמן אין אנו יודעין:"],[9,"דברים האמורים כו'","דתינוק ממהר להתחכם יותר מתינוקת:"],[15,"לעונשין","וכגון דאייתי שתי שערות תוך הזמן דאי לא אייתי אפילו לאחר זמן לאו בר עונשין הוא ולאחר זמן אי אייתי ב' שערות הוי גדול ובר עונשין:"],[15,"כלפני הזמן","ולא ענשינן ליה ושתי שערות הויא להו שומא:"],[16,"וזאת לפנים","וזאת לשון נקבה כלומר רב חנינא דשמיה לשון נקבה אמר לפנים כלומר לפני זמן ולא תטעה להחליף דבריהם. ל\"א שמו של רב דאמר כלפני הזמן מובלע בתיבת בישראל:"],[17,"מתיב רב המנונא","קס\"ד כדאמר לקמן דרב המנונא משנה יתירה דייק דלא איצטריך למתנייה כדפרכינן לעיל והא דתני ליה תנא דמתני' למידק מינה לענין עונשין הא תוך הזמן כלפני הזמן דאי לענין נדרים לא כלפני זמן ולא כלאחר זמן:"],[20,"מגופא דמתני' דייק","דלא מתוקמא אלא כשהביא שתי שערות ואפ\"ה לא חשיב ליה גדול עד לאחר זמן. והשתא ליכא למיפרך לידוק מרישא דהא לא דייק מידי דבין רישא ובין סיפא לגופא איצטריך לענין נדרים דלא תימא הני מילי היכא דלא קאמרי אינהו אבל היכא דאמרי אינהו כו' כדאמר לעיל ומיהו מגופא דסיפא שמעינן דעד דמטו לאחר זמן בעינן יודע להפלות ואם אינו יודע להפלות ואפילו הביא ב' שערות לאו איש הוא דניהוי נדרו נדר מחמת אישות בלא הפלאה:"],[20,"קטן הוא","ואמאי נדרו נדר הא לאו בחזקת גדול הוא כל זמן שלא הביא ב' שערות ומופלא סמוך לאיש נמי לא הוי דהא אינו יודע לשם מי נדר ומהיכא תיתי דנדרו נדר:"],[20,"אלא לאו כשהביא","ומשום הכי נדרו נדר אע\"ג דאין יודע להפלות דהא גדול הוא:"]],[[8,"","קודם הזמן הזה למה לי סד\"א כו'. וא\"ת ובת י\"א שנה למה ליה למימר דאילו חריפא לא בדקינן לה דהיינו קודם הזמן ויש לומר דזו אף זו קתני דלא מיבעיא דלא אמרי אלא אפילו אמרי לא מהני:"],[9,"","אלו דברי רבי. נראה דהלכה כרבי דלקמן בפירקין אמרי' כל י\"ב שנה ממאנת ומכאן ואילך אינה ממאנת ובפ' נערה שנתפתתה (כתובות ד' נא.) אמר דהלכה כרבי לגבי רשב\"א לבד מלגבי מילתא דהתם וביש נוחלין (ב\"ב דף קכד:) נמי פסיק הלכה כרבי מחבירו:"],[12,"","שהתינוק מצוי בבית רבו. ואפילו אין לו רב רגיל לצאת ולבא ומתפקח יותר:"],[14,"","אילימא לנדרים. ובלא הביא ב' שערות ואפ\"ה נדרו נדר אם ידע למי נדר כיון שהוא שנה לפני גדלות דמסתמא יביא ב' שערות כשיהיה בן י\"ג ויום אחד כדאמר רבא לקמן חזקה הביאה שערות:"],[15,"","אלא לענין עונשין. וכגון שהביא ב' שערות תוך הזמן מי חשיב גדול כמו לאחר זמן לענין חליצה וקדושין ונדרים לקיים נדרו אפי' אינו יודע למי נדר כיון שהביא ב' שערות ומיבעיא ליה אי הוי שומא אי לאו:"]]],[["וטעמא דלאחר זמן הוא דגמר' לה למילתיה הא תוך זמן כלפני זמן","ועוד מתיב רבי זירא (במדבר ו ) איש כי יפליא לנדור נדר מה ת\"ל איש לרבות בן י\"ג שנה ויום אחד שאע\"פ שאינו יודע להפליא נדריו קיימין","ה\"ד אי דלא אייתי שתי שערות קטן הוא אלא לאו דאייתי שתי שערות וטעמא דבן י\"ג ויום אחד הוא דהוה ליה איש הא תוך זמן כלפני זמן תיובתא","אמר ר\"נ כתנאי בן ט' שנים שהביא ב' שערות שומא מבן ט' ועד י\"ב שנה ויום אחד שומא רבי יוסי ברבי יהודה אומר סימן בן י\"ג שנה ויום אחד דברי הכל סימן","הא גופא קשיא אמרת מבן ט' ועד י\"ב שנה ויום אחד שומא הא י\"ג שנה גופא סימן והדר תני בן י\"ג שנה ויום אחד סימן הא י\"ג שנה גופא שומא","מאי לאו תנאי היא דמר סבר תוך זמן כלאחר זמן ומר סבר תוך זמן כלפני זמן","לא דכ\"ע תוך זמן כלפני זמן ואידי ואידי בתינוקת ורישא רבי וסיפא ר\"ש בן אלעזר","ואיבעית אימא הא והא בתינוק ורישא ר\"ש בן אלעזר וסיפא רבי","ואיבעית אימא הא והא רבי הא בתינוק הא בתינוקת ואב\"א הא והא ר\"ש בן אלעזר הא בתינוק הא בתינוקת","רבי יוסי ברבי יהודה אומר סימן א\"ר כרוספדאי בריה דרבי שבתאי והוא שעודן בו","תניא נמי הכי בן ט' שנים ויום אחד שהביא ב' שערות שומא מבן ט' ועד י\"ב שנה ויום אחד ועודן בו שומא ר' יוסי בר' יהודה אומר סימן","אמר רבא הילכתא תוך זמן כלפני זמן רב שמואל בר זוטרא מתני לה לשמעתא דרבא בהאי לישנא אמר רבא קטנה כל י\"ב שנה ממאנת והולכת מכאן ואילך אינה ממאנת ואינה חולצת","הא גופא קשיא אמרת אינה ממאנת אלמא גדולה היא אי גדולה היא תחלוץ","וכי תימא מספקא ליה ומי מספקא ליה והאמר רבא קטנה שהגיעה לכלל שנותיה אינה צריכה בדיקה חזקה הביאה סימנין","ה\"מ בסתמא אבל הכא דבדקו ולא אשכחו לא","אי הכי תמאן חוששין שמא נשרו","הניחא למ\"ד חוששין אלא למ\"ד אין חוששין מאי איכא למימר דאיתמר רב פפא אמר אין חוששין שמא נשרו רב פפי אמר חוששין הני מילי לענין חליצה אבל לענין מיאון חוששין","מכלל דמ\"ד חוששין חולצת והא חוששין בעלמא קאמר","אלא לעולם דלא בדקה ולענין חליצה חיישינן וכי קאמר רבא חזקה למיאון אבל לחליצה בעיא בדיקה","אמר רב דימי מנהרדעא הלכתא חוששין שמא נשרו","והני מילי היכא דקדשה בתוך זמן ובעל לאחר זמן דאיכא ספיקא דאורייתא אבל מעיקרא לא","אמר רב הונא הקדיש ואכל לוקה","שנאמר (במדבר ו׳:ב׳ ) איש כי יפליא לנדור (במדבר ל, ג) ולא יחל דברו כל שישנו בהפלאה ישנו בבל יחל וכל שאינו בהפלאה אינו בבל יחל","מתיב רב הונא בר יהודה (לרבא) לסיועי לרב הונא"],[[2,"וטעמא","דחשיבי להו שערות דלאחר זמן הוא דגמרו למלתיה בין בשערות בין בשנים הא תוך הזמן חשבינן להו שומא דקטן הוא ולא מצית לרבויי מאיש:"],[3,"בן ט' שנים שהביא שערות שומא","ואפי' לר' יוסי ברבי יהודה ומבן ט' ועד בן י\"ב ויום אחד פלוגתא:"],[3,"שומא","ורוא\"ה בלע\"ז. ודרכה ליגדל שער בה:"],[4,"הא י\"ג גופיה סימן","ואפי' לרבנן והדר תני כו':"],[5,"מאי לאו תנאי היא","ואליבא דרבנן י\"ג הוי תוך זמן לתינוק כדקתני במתני':"],[6,"ורישא","דמשוית י\"ג סימן:"],[6,"רבי היא","דאמר בתנוקת הויא י\"ג לאחר זמן:"],[6,"וסיפא","דמשמע שומא:"],[6,"ר\"ש בן אלעזר","דאמר י\"ג בתינוקת הוי תוך זמן. בכל הנך תירוצי מוקמינן תוך זמן כלפני זמן:"],[9,"והוא שעודן בו","כשהגדיל אבל נשרו בינתיים איגלאי מילתא דשומא הוי:"],[11,"מתני לשמעתא דרבא בהאי לישנא","דשמעת מיניה נמי תוך זמן כלפני זמן:"],[11,"ממאנת והולכת","ואין חוששין שמא הביאה ב' שערות דאפילו הביאה שומא נינהו והיינו תוך זמן כלפני זמן:"],[12,"אינה ממאנת","שמא הביאה ועכשיו הוי סימן דהא לאחר זמן הוא ואם יבמה היא לא חשבינן לה גדולה לענין חליצה ואינה חולצת:"],[12,"גדולה היא","אם הביאה:"],[13,"וכי תימא מספקא ליה","אם הביאה אם לא הביאה הלכך מיאון לא דלמא הביאה וחליצה נמי לא שמא לא הביאה:"],[13,"והא מיפשט פשיטא ליה לרבא","דכיון דהגיעה לכלל שנותיה דודאי הביאה:"],[16,"ה\"מ לענין","דאי אתיא למיחלץ לאחר זמן ובדקנו ולא אשכחן ליה חיישינן למימר גדולה היא ותחלוץ שהסימנין נשרו:"],[16,"אבל לענין מיאון חיישינן","שמא נשרו לחומרא וקנאה בביאה ובעיא גט:"],[17,"והא חיישינן קאמר","ולא ודאי נשרו וחיישינן לחומרא משמע:"],[18,"אלא לעולם","אינה ממאנת דרבא בדלא בדקנוה הלכך מסתמא אמרינן כיון שהגיעה לכלל שנותיה ודאי אית לה ואינה צריכה בדיקה ובעיא גט:"],[18,"ולענין חליצה חיישינן גרסינן","כלומר ולענין חליצה משום הכי אינה חולצת דחיישינן שמא לא הביאה סימנין ודקשיא לך האמר רבא חזקה הביאה סימנין. ל\"ק כי אמר רבא חזקה למיאון דלא ממאנת מסתמא אבל לחליצה בעיא בדיקה:"],[19,"חוששין שמא נשרו","ואם הגיעה לכלל שנותיה ובדקו ולא אשכחו לא ממאנת:"],[20,"דקדשה תוך זמן","יתומה מדעת אמה ואחיה לדעתה:"],[20,"ובעל אחר זמן דאיכא ספיקא","דאשת איש דאורייתא דבשעת בעילה דלאחר זמן שמא הביאה והויא לה ביאה זו קדושין גמורין דהא גדלה ושוב אינה יוצאה במיאון:"],[20,"אבל מעיקרא","דמכי עברה שתא דתרתי סרי ולא בעל לא חיישינן שמא נשרו דהא לא הוו בה קדושין גמורין דאין מעשה קטנה כלום אא\"כ קבל אביה קדושין הלכך מספיקא לא מחמרינן עלה היכא דלא אשכחן אבל הביאה ודאי סימנין אע\"ג דקדושי קמאי לא הוו קדושין אלא מדרבנן לא תקנו רבנן מיאון בגדולה דלמא אתיא למאן הנבעלת לאחר שגדלה דההיא הויא אשת איש דביאה שבא עליה משגדלה מקדשה לה:"],[21,"הקדיש","תוך הזמן תינוק היודע להפליא:"],[21,"ואכל","את הקדשו:"],[21,"לוקה","ואע\"ג דבמילתא אחריתי לאו בר עונשין הוא:"],[22,"כי יפליא","מיניה מרבינן מופלא סמוך לאיש. מופלא יודע לפרש לשם מי נדר. סמוך לאיש שהוא סמוך לבא לכלל גדול דהיינו שנה אחת קודם זמן שהוא ראוי להביא שערות והיינו בתינוקת כל י\"ב ובתינוק כל י\"ג:"],[22,"ולא יחל","אע\"ג דבהאי קרא לא כתיב כי יפליא מ\"מ כיון דנפקא לן מיניה דיודע להפלות הוי נדרו נדר קאי בבל יחל דהא כתיב איש כי ידור נדר וגו' ומופלא סמוך לאיש בכלל איש וסמיך ליה ולא יחל דברו:"]],[[3,"","בן ט' שנים שהביא ב' שערות שומא. אי ל\"ג ויום אחד אתי שפיר דאתיא אף כרבי יוסי ואי גרסינן ויום אחד מיירי באין עודן בו בשנת י\"ג דמודה רבי יוסי בנשרו:"],[11,"","קטנה כל י\"ב שנה ממאנת. להך לישנא אין להוכיח דתוך זמן כלפני זמן דהא ממאנת היינו דבדקו ולא אשכחו או כמו שמעמיד במסקנא דלא בדקו אבל היכא דאיכא שערות מצינו למימר דהוי כלאחר זמן ואינה ממאנת ומ\"מ נראה דהלכה דתוך זמן כלפני זמן דמ\"ד כלאחר זמן איתותב לעיל ור\"נ דאמר לעיל נמי כתנאי דחי ליה הש\"ס וגם בלישנא קמא פסיק רבא בהדיא דתוך זמן כלפני זמן:"],[18,"","אבל לחליצה בעיא בדיקה. תימה דרבא סבר הכא דאינה חולצת עד שתהא גדולה ובפ' התקבל (גיטין דף סה.) אמר רבא ג' מדות בקטן הגיע לעונת נדרים נדרו נדר וכנגדו בקטנה חולצת משמע דקטנה בהגעת לעונת נדרים דידה חולצת דהיינו בת י\"א ויום אחד ואפי' מיירי התם בהביאה הא אמר הכא דתוך זמן כלפני זמן ורשב\"ם פירש כנגדו בקטנה היינו בת י\"ב שנה ויום אחד דהוי עונת נדרים דקטן ולא נהירא ומפרש ר\"ת דהתם רבא אליבא דר' יוסי דקאמר קטנה חולצת וקמ\"ל דדוקא כשהגיעה לעונת נדרים וכן משמע בפרק מצות חליצה (יבמות דף קה:) דאמר מדברי ר' יוסי נלמד קטנה חולצת בפעוטות כבת שית וכבת שבע דאז היא בת כוונה לחליצה ורבא אמר עד שתגיע לעונת נדרים פירוש לרבי יוסי והילכתא עד שתביא ב' שערות וכל זה מדברי רבא ועוד י\"ל דהתם בפ' התקבל (גיטין דף סה.) גרסינן רבה דהא קאמר התם ולמכור בנכסי אביו עד שיהא בן כ' שנה ואילו רבא אית ליה בפרק מי שמת (ב\"ב דף קנה.) דלמכור בנכסי אביו עד שיהא בן י\"ח וכן צריך להיות שם בספרים ולא כספרים דגרסי התם איפכא כדמוכח סוגיא דהתם:"]]],[["לפי שמצינו שהשוה הכתוב הקטן כגדול לזדון שבועה ולאיסר ולבל יחל יכול יהא חייב על הקדשו קרבן","ת\"ל (במדבר ל, ב) זה הדבר","קתני מיהת לאיסר ולבל יחל חייב אימא לאיסור בל יחל","איסור בל יחל מה נפשך אי מופלא סמוך לאיש דאורייתא מילקא נמי לילקי ואי מופלא סמוך לאיש לאו דאורייתא איסור נמי ליכא לאותן המוזהרים עליו","שמע מינה קטן אוכל נבלות ב\"ד מצווין עליו להפרישו הכא במאי עסקינן כגון שהקדיש הוא ואכלו אחרים","הניחא למ\"ד הקדיש הוא ואכלו אחרים לוקין אלא למ\"ד אין לוקין מאי איכא למימר דאיתמר הקדיש הוא ואכלו אחרים רב כהנא אמר אין לוקין רבי יוחנן ור\"ל דאמרי תרוויהו לוקין","מדרבנן וקרא אסמכתא בעלמא","גופא הקדיש ואכלו אחרים רב כהנא אמר אין לוקין רבי יוחנן ור\"ל דאמרי תרוייהו לוקין במאי קמיפלגי מר סבר מופלא סמוך לאיש דאורייתא ומר סבר מופלא סמוך לאיש מדרבנן","מתיב רב ירמיה יתומה שנדרה בעלה מפר לה אי אמרת בשלמא מופלא סמוך לאיש דרבנן אתו נשואין דרבנן ומבטלי נדרא דרבנן אלא אי אמרת דאורייתא אתו נשואין דרבנן ומבטלי נדרא דאורייתא","אמר רב יהודה אמר שמואל בעלה מפר לה ממה נפשך אי דרבנן דרבנן הוא אי דאורייתא קטן אוכל נבלות הוא ואין ב\"ד מצווין עליו להפרישו","והא כי גדלה אכלה בהפרה קמייתא","אמר רבה בר ליואי בעלה מפר לה כל שעה ושעה והוא שבעל","והא אין בעל מפר בקודמין כדרב פינחס משמיה דרבא דאמר רב פנחס משמיה דרבא כל הנודרת על דעת בעלה היא נודרת","אמר אביי ת\"ש קטן שלא הביא ב' שערות רבי יהודה אומר אין תרומתו תרומה רבי יוסי אומר עד שלא בא לעונת נדרים אין תרומתו תרומה משבא לעונת נדרים תרומתו תרומה","סברוה קסבר ר' יוסי תרומה בזמן הזה דאורייתא אי אמרת בשלמא מופלא סמוך לאיש דאורייתא אתי גברא דאורייתא ומתקן טבלא דאורייתא אלא אי אמרת דרבנן אתי גברא דרבנן ומתקן טבלא דאורייתא לא קסבר רבי יוסי תרומה בזמן הזה דרבנן","וסבר ר' יוסי תרומה בזמן הזה דרבנן והתניא בסדר עולם (דברים ל, ה) אשר ירשו אבותיך וירשתה","ירושה ראשונה ושניה יש להן שלישית אין להן","וא\"ר יוחנן מאן תנא סדר עולם ר' יוסי","ר' יוסי תני לה ולא סבר לה ה\"נ מסתברא דתניא עיסה שנדמעה או שנתחמצה בשאור של תרומה"],[[0,"לפי שמצינו שהשוה הכתוב","מכי יפליא דמשמע יודע להפלות סמוך לאיש דאכתי קטן הוא כל שנה זו:"],[1,"זה הדבר אשר צוה וגו'","כלומר לאיסר ולא יחל אמרתי שיהא איסרו איסר ונדרו בבל יחל ולא לקרבן מעילה ובל יחל היינו מלקות ומסייע ליה לרב הונא:"],[2,"אימא לאיסור בל יחל","כלומר איסורא בעלמא ולא מלקות:"],[3,"אי מופלא סמוך לאיש דאורייתא","מכי יפליא לנדור נדר:"],[3,"מילקא נמי לילקי","דהא כל זמן דנדרו נדר קאי עליה בבל יחל:"],[3,"איסורא נמי ליכא","עליו אם אכלו דהא אי אתו רבנן לתקוני הכי תקון שלא יאכלו אחרים את הקדשו או הוא לכשיגדיל אבל בקטנותו לא באו לאסור עליו דקטן לאו בר קבולי עליה תקנתא דרבנן הוא: ומשני לעולם דרבנן ואיסורא אמאן קאי על אותן המוזהרים עליו להפריש מאיסורא:"],[4,"ש\"מ כו'","פלוגתא היא בפרק חרש שנשא פקחת ביבמות (דף קיד.):"],[4,"אלא הכא במאי עסקינן כו'","ולעולם כדקתני ולאיסר ולבל יחל דהוי מלקות גמור ואפ\"ה לא תסייעיה לרב הונא מהא דהא דקתני מלקות אהקדש קטן לאו לדידיה קאמר אלא לאחרים שאכלו את הקדשו:"],[7,"מדרבנן","כלומר מ\"ד אין לוקין מוקים להא דקתני לאיסר ולבל יחל כדאוקמינן לאיסור בל יחל איסורא בעלמא ומדרבנן ומקרא דכי יפליא דקתני שהשוה הכתוב אסמכתא בעלמא:"],[8,"יתומה","שהשיאתה אמה דבת מיאון היא דנשואין דידה מדרבנן:"],[8,"בעלה מפר נדרה","ולא קרי לה יתומה אלא בקטנותה כל זמן שראויה למיאון:"],[8,"אי אמרת בשלמא מופלא סמוך לאיש","לא הוי נדרו נדר אלא מדרבנן מש\"ה בעלה מפר לה דאתו נשואין דרבנן כו':"],[10,"והא לכי גדלה אכלה","בההיא הפרה דלאו הפרה היא ונמצא גדול אוכל נבלות:"],[11,"כל שעה","ואף משגדלה:"],[11,"והוא שבעל","לאחר שגדלה דהויא הך בעילה קדושין גמורין דאורייתא דמעשה גדולה מעשה הלכך אתו נישואין דאורייתא ומבטלין נדרא דאורייתא:"],[12,"אין הבעל מפר","נדרים הקודמין לנישואין במסכת נדרים והאי נדר קדם להך בעילה דאורייתא:"],[12,"כדרב פנחס","כלומר לא תוקי לה לברייתא כשהבעל מפר לה כל שעה ושעה לעולם נדרה דאורייתא ודקשיא לך אתו נשואין דרבנן ומבטלין נדרא דאורייתא אהכי מבטלת דכל הנודרת כו':"],[12,"על דעת בעלה","והך קטנה על דעתו של זה נדרה וכי אמרינן אין הבעל מפר בקודמין היכא דלית לה בעל בשעת נדר כלל:"],[13,"לעונת נדרים","היינו מופלא הסמוך לאיש שנדריו נבדקין:"],[14,"סברוה","רבנן בני הישיבה דבעו לאותובי לרב כהנא מהכא:"],[14,"תרומה דאורייתא","וקאמר משבא לעונת נדרים תרומתו תרומה ותרומה והקדש ונדר חדא היא דמקדשה בדבורו שקורא עליה שם:"],[15,"אבל שלישית","לעתיד לבא:"],[16,"ירושה ראשונה","של יהושע:"],[16,"ושניה","בימי עזרא:"],[16,"יש להן","כלומר בגלות נבוכדנצר בטלה קדושת הארץ ונצטרכו ליורשה ולקדשה בשניה:"],[16,"אין להם","כלומר אינה ירושה דלא יצטרכו לרשתה ולקדשה דלא בטלה קדושתה מגזרת הכתוב:"],[17,"ואמר רבי יוחנן","בעלמא:"],[17,"מאן תנא סדר עולם רבי יוסי","דהוא סתמה כי היכי דסתם מתניתין ר\"מ:"],[18,"תני ולא סבר לה","להא דרשא דקתני שלישית אין להן אלא ודאי בטלה קדושת הארץ ותרומתה דהשתא דרבנן:"],[18,"עיסת חולין שנדמעה","כגון שנפל סאה של תרומה לתוך פחות ממאה של חולין:"]],[[3,"","אי מופלא הסמוך לאיש דאורייתא מילקא נמי לילקי. וא\"ת ואמאי פריך בפשיטות דלילקי הא איכא אמוראי דאמרי דנדרו נדר לענין שאם אכלו אחרים שלוקין אבל הוא לא לקי דקטן הוא לעונשין וי\"ל דהכי פריך אי מופלא הסמוך לאיש דאורייתא ואית ליה איסורא לקטן מילקא נמי לילקי:"],[3,"","לאותן המוזהרין עליו. תימה א\"כ היכי ס\"ד דלחייבו קרבן לפי שמניחין לו לעבור על נדרו וי\"ל דהוה מצי למימר ולטעמיך אלא דבלאו הכי פריך שפיר:"],[4,"","כגון שהקדיש הוא ואכלו אחרים. וא\"ת ואמאי לא מוקי כגון שאכל הוא בעצמו לכשהגדיל והוה ניחא טפי דזדון שבועה לא מתוקמא אלא כשאכל בעצמו דאפי' נשבע שלא יאכלו אחרים אין בכך כלום כל זמן שלא אסר עליהם בקונם דהוי כהקדש וי\"ל דניחא ליה לאוקומי כשאכלו אחרים מיד סמוך לנדרו:"],[5,"","רבי יוחנן ור\"ל דאמרי תרוייהו לוקין. וא\"ת והא סבר ר\"ל התראת ספק לא שמה התראה בהתערובות (זבחים עח.) גבי נותר ופגול שבללן זה בזה והכא התראת ספק הוא דשמא לא יביא ב' שערות עד ב' שנים או ג' ונמצא דאכתי לא הוי מופלא סמוך לאיש ואי מיירי שאכלו אחרים לאחר שהגדיל א\"כ הל\"ל כשאכלו הוא בעצמו ובהביא שתי שערות נמי לא איירי דא\"כ הוא עצמו אם יאכלנו ילקה דרבי יוחנן אית ליה לעיל דתוך זמן כלאחר זמן וי\"ל דאזלינן בתר רוב שמביאין שתי שערות בזמנן דהיינו בני י\"ג ויום א':"],[9,"","אין ב\"ד מצווין להפרישו. וא\"ת לרב הונא דאמר שהוא עצמו לוקה מה מועיל הפרתו ותו מה משני הא בעי רבי יוחנן למימר בפרק חרש (יבמות דף קיד.) דב\"ד מצווין להפרישו וי\"ל דלמסקנא דקאמר דעל דעת בעלה נודרת אתי שפיר והוה מצי למימר השתא וליטעמיך הא סבר ר' יוחנן דב\"ד מצווין להפרישו אלא דבלא\"ה פריך שפיר:"],[12,"","כדרב פנחס דאמר על דעת בעלה היא נודרת. והוי כמו אלא אע\"ג דלא כתוב בספרים אלא וכעין זה יש בפ' אע\"פ (כתובות דף נט.) אמר רב הונא בריה דרב יהושע באומר יקדשו ידיך לעושיהם דאין בספרים אלא ובנדרים (דף יג) יש בספרים אלא וא\"ת א\"כ אמאי נכתב בפרשת נדרים דבעל מפר לאשתו אפי' אינה אשתו כגון הכא הבעל מפר דעל דעתו נודרת וי\"ל דאיצטריך לענין שאם אמר קיים ליכי שאינו יכול להפר א\"נ משום דאמר רחמנא בעל מפר קאמר דלעולם על דעתו היא נודרת ואע\"ג דהכא לא הוו אלא נישואין דרבנן ולא אמרה תורה שיפר מ\"מ היא סבורה שבידו להפר כמו בשאר נשים ונודרת על דעתו:"],[14,"","אי אמרת בשלמא מופלא הסמוך לאיש דאורייתא. וא\"ת אדפריך מרבי יוסי לסיועי מדרבי יהודה דאמר אין תרומתו תרומה אלמא סבר דמופלא הסמוך לאיש דרבנן ולכך לא מתקן טבל דאורייתא וי\"ל דר' יהודה נמי אית ליה דמופלא סמוך לאיש דאורייתא ולהקל לתקן טבל לא איתרבי להיות כגדול:"]]],[["חייבת בחלה ואינה נפסלת בטבול יום דברי ר\"מ ור' יהודה ר' יוסי ור\"ש פוטרין מן החלה","סברוה מאן דאמר תרומה דאורייתא חלה דאורייתא מאן דאמר תרומה דרבנן חלה דרבנן אי אמרת בשלמא קסבר רבי יוסי חלה בזמן הזה דרבנן אתי דמוע דרבנן ומפקע חלה דרבנן","אלא אי אמרת חלה דאורייתא אתי דמוע דרבנן ומפקע חלה דאורייתא","ודלמא קסבר רבי יוסי תרומה בזמן הזה דאורייתא וחלה דרבנן","וכדאהדר רב הונא בריה דרב יהושע דאמר רב הונא בריה דרב יהושע אשכחתינהו לרבנן דבי רב דיתבי וקאמרי אפילו למ\"ד תרומה בזמן הזה דרבנן חלה דאורייתא","שהרי שבע שכבשו ושבע שחלקו נתחייבו בחלה ולא נתחייבו במעשר","ואמינא להו אנא אפילו למ\"ד תרומה בזמן הזה דאורייתא חלה דרבנן דתניא אי בבואכם יכול משנכנסו לה שנים ושלשה מרגלים ת\"ל בבואכם בביאת כולכם אמרתי ולא בביאת מקצתכם","וכי אסקינהו עזרא לא כולהו סלוק","\u0001מתני׳\u0002 משל משלו חכמים באשה פגה בוחל וצמל פגה עודה תנוקת בוחל אלו ימי נעוריה","בזו ובזו אמרו אביה זכאי במציאתה ובמעשה ידיה ובהפרת נדריה צמל כיון שבגרה שוב אין לאביה רשות בה","איזהו סימנין ר' יוסי הגלילי אומר משיעלה הקמט תחת הדד ר\"ע אומר משיטו הדדים בן עזאי אומר משישחיר הפיטומת רבי יוסי אומר כדי שיהא נותן ידו על העוקץ והוא שוקע ושוהא לחזור","\u0001גמ׳\u0002 פגה עודה תנוקת כדכתיב (שיר השירים ב׳:י״ג ) התאנה חנטה פגיה בוחל אלו ימי הנעורים כדתנן התאנים משיבחלו ואמר רבה בר בר חנה אמר רב משילבין ראשיהן","ואיבעית אימא מהכא (זכריה יא, ח) ותקצר נפשי בהם וגם נפשם בחלה בי צמל כמ\"ד יצתה מלאה","ואיזהו סימנים ר' יוסי הגלילי אומר משיעלה הקמט אמר שמואל לא משיעלה הקמט ממש אלא כדי שתחזיר ידיה לאחוריה ונראית כמי שיעלה הקמט תחת הדד","שמואל בדק באמתיה ויהב לה ד' זוזי דמי בושתה שמואל לטעמיה דאמר שמואל (ויקרא כה, מו) לעולם בהם תעבודו לעבודה נתתים ולא לבושה","שמואל מייחד להן רב נחמן מחליף להן רב ששת מסר להן לערבי ואמר להן אזדהרו מישראל","רבי יוסי אומר כו' מאי עוקץ אמר שמואל עוקצו של דד","ת\"ר אלו הן סימני בגרות ר\"א בר' צדוק אומר משיתקשקשו הדדין ר' יוחנן בן ברוקה אומר משיכסיף ראש החוטם משיכסיף אזקונה לה אלא א\"ר אשי משיפציל ראש החוטם ר' יוסי אומר משתקיף העטרה ר\"ש אומר משנתמעך"],[[0,"חייבת בחלה","ולא אמרינן דתרומה פוטרת לה ואע\"ג דתרומה אינה חייבת בחלה מדומע חייב בחלה מ\"ט דדימוע דרבנן הוא דמדאורייתא חד בתרי בטיל דכתיב (שמות כ״ג:ב׳) אחרי רבים להטות ורבנן הוא דאצרוך אחד ומאה הלכך לא אתי דימוע דרבנן ומפקע חלה אפילו בזמן הזה דקסברי ר\"מ ורבי יהודה חלה בזמן הזה דאורייתא:"],[0,"פוטרין מן החלה","כדמפרש לקמן דקסברי חלה בזמן הזה דרבנן ואתי דימוע דרבנן ומפקע חלה דרבנן והיינו דאמרן לעיל תני ולא סבר לה דהא חזינן דלרבי יוסי חלה בזמן הזה דרבנן וסברוה הנך רבנן דמייתי ראייה מהכא דכי היכי דקאמר ר' יוסי חלה בזמן הזה דרבנן הוא הדין לתרומה:"],[3,"ודלמא","אע\"ג דקא חזית מהכא לר' יוסי חלה דרבנן אפ\"ה סבירא ליה תרומה דאורייתא וליכא הכי נמי מסתברא דקא בעית לאתויי:"],[5,"נתחייבו בחלה","דכתיב בחלה (במדבר ט״ו:י״ח) בבואכם אל הארץ והרי באו:"],[5,"ולא נתחייבו במעשר","דבמעשר כתיב (דברים י״ד:כ״ב) תבואת זרעך עד שיביא כל אחד ואחד את שלו:"],[8,"מתני' פגה","סמדר כך באשה עודה תינוקת קרו לה פגה כל זמן שאין לה סימן לא בדדים ולא בשערות:"],[8,"בוחל","כשהפרי גדל קצת כדתני בגמרא התאנים משיבחלו כך כשיש לה סימן דדין קצת בידוע שהביאה שתי שערות ונערה היא:"],[8,"צמל","בגמ' מפרש לה לשון נוטריקון יצתה מלאה שיש לה סימן מובהק בדדיה ולקמן מפרש סימנין במתני'. והיא בוגרת:"],[9,"בזו ובזו","אפי' כשהיא נערה אביה זכאי כו' דכתיב (במדבר ל׳:י״ז) בנעוריה בית אביה כל שבח נעוריה לאביה:"],[10,"איזו היא סימנין","אצמל קאי:"],[10,"קמט","פרונצ\"ש. שגדלו דדיה עד שכפול מעט על החזה ויראה כקמט:"],[10,"משיטו","גדולים יותר:"],[10,"הפיטומת","ראש הדד כמו (סוכה דף לד:) ניטלה פיטמתו:"],[10,"עוקץ","כמו עוקצי האגסים (עוקצין פ\"א מ\"ו). פוכיצ\"ש בלע\"ז. חודו של דד שהתינוק יונק ופיטומת היינו סביבות עוקץ:"],[11,"גמ' משיבחלו","חייבין במעשר:"],[11,"משילבין ראשיהן","שמשתנין כשמגדילין. הכא נמי משישתנה הדד ויראה בו סימן שמגדיל:"],[12,"בחלה בי","גדלה עלי. אדם הקץ בדבר נראה לו כגדול. אנקיישנ\"ץ בלע\"ז:"],[15,"מייחד להו","שפחותיו מייחד לאנשים עבדיו ואינו מפקירן משום בושת:"],[15,"מחליף להן","את של זה בזה ואינו מקפיד על בושתן:"],[15,"לערבי","מפקיר שפחותיו לערביים ונוהג בהן מנהג הפקר:"],[17,"משיתקשקשו","כמו (סוטה דף ט:) מקשקשת לפניו כזוג בטנ\"ט בלע\"ז. כלומר גדולים הרבה:"],[17,"חוטם","ספק:"],[17,"משיפציל","ספק:"],[17,"משתקיף עטרה","שגדול העוקץ ועב ומוקף עטרה והיינו שיעורא דא\"ר יוסי נמי במתני' שיהא נותן ידו על העוקץ ושוקע ושוהא לחזור:"]],[[0,"","ואינה נפסלת בטבול יום. וא\"ת באלו עוברין (פסחים דף מד.) גבי מקפה של חולין ושום ושמן של תרומה קאמר דאם נגע טבול יום במקצתו דפסל כולו במגעו וי\"ל דהתם מיירי בשעשאו גוש בקערה:"],[1,"","אתי דימוע דרבנן ומפקע חלה דרבנן. מכאן מביא ריב\"א ראיה דתרומה בטלה ברוב דאורייתא והא דדרשינן בסיפרא מאת מקדשו ממנו דעולה בק\"א אסמכתא בעלמא הוא וכן הא דקאמר התם דערלה וכלאי הכרם דכפל איסורו ליאסר בהנאה כפל בעלייתו שצריך אחד ומאתים ומיהו ראייה דהכא יש לדחות דלעולם מדאורייתא הכל נאסר לזרים מטעם תערובת התרומה שאינה ניכר אבל מה שגם החולין נחשבו כתרומה ליפטר מן החלה כאילו הכל תרומה זה אינו אלא מדרבנן ומיהו יש להביא ראיה גבי נפלו אגוזים ונתפצעו בהניזקין (גיטין דף נד:) דיש ספרים דגרסי והא הכא דמדאוריית' ברובו בטלה ובשלהי הערל (יבמות דף פב.) גבי שתי קופות אחת של חולין ואחת של תרומה ולפניהן שתי סאות כו' דקא\"ר יוחנן והוא שרבו חולין על התרומה פי' דשרי מדאורייתא ולהכי אמר שאני אומר ובריש ההוא פירקא (דף עג:) נמי קאמר תרומה חמורה ממעשר שכן מחפ\"ז ולא חשיב ק\"א:"],[6,"","ל\"ג אילו נאמר כי תבואו הייתי אומר משנכנסו ב' או ג' מרגלים דהא רישא דברייתא הכי איתא בספרי (פרשת שלח) (ובספ\"ק דקדושין מייתי לה) משונה ביאה זו של חלה דבעלמא כתיב כי תבואו כי יביאך וכאן כתיב בבואכם לומר מיד כשנכנסו קודם כבוש וחילוק אלמא משמע דכי תבואו משמע ביאה חשובה דהיינו לאחר כבוש וחילוק והיכי מצי למימר אפי' ב' או ג' מרגלים אלא הכי גרסינן אי בבואכם יכול אפי' ב' או ג' מרגלים וקאי אדלעיל מיניה:"],[7,"","לא כולהו סלוק. ואם תאמר והלא כל יושביה עליה קרינן לענין יובל לפי שמקצת כל השבטים עלו לפר\"ת דאמר דיובל נהג בבית שני מהאי טעמא וי\"ל דבבואכם משמע טפי בביאת כולכם ואם תאמר היכי ס\"ד מעיקרא דתרומה בזמן הזה דאורייתא לרבי יוסי והוי סייעתא לר\"ל דלעיל הא ר\"ל גופיה סבר דלר' יוסי תרומה בזמן הזה דרבנן בפרק הערל (יבמות ד' פא.) וי\"ל דהוי מצי למימר וליטעמיך:"],[10,"","איזהו סימניה. פ\"ה סימני בגרות ורבי יוסי דאמר בגמרא משתקיף העטרה היינו נמי דקאמר הכא משיתן ידו על העוקץ וקשה דאי חד שיעורא הוא למה שינה רבי יוסי לשונו ותו דכל תנאי דגמרא שום אחד מהם אינו מזכיר משיעורא דמתניתין ועוד דאם כן בבוחל לא נתן שום סימן ובגמרא קאמר בוחל מלמעלה בידוע שהביאה ב' שערות הא לא שמעינן סימני דבוחל לכך פר\"ת דאיזהו סימניה דקאמר הכא אבוחל קאי ולפירוש זה אתי שפיר הא דקאמר בגמרא הלכה כדברי כולן להחמיר לענין מיאון:"],[14,"","בדק באמתיה ויהיב ד' זוזי דמי בושתה. להנצל מעונש היה נותן לה דהא ר' יהודה אמר בהחובל (ב\"ק דף פז.) אין לעבדים בושת ואפילו למ\"ד יש לעבדים בושת הוי לרבו:"],[15,"","מסר להו לערבי. משמע מכאן דשפחה כנענית מותרת בעובד כוכבים וה\"ה דעבד כנעני מותר בעובדת כוכבים ולא גזרו עליו משום נשג\"ז אע\"ג דאיסור נדה ואשת איש דאורייתא שייך שפיר בעבד וא\"כ בשלהי מסכת ע\"ז (דף עו:) דא\"ל שבור מלכא לבטי אדכר לך מה דעבדת באורתא שקבל עובדת כוכבים זונה שמסר לו אושפיזו (ורב) יהודה לא קבל עובדת כוכבים זונה לא עשה בטי איסורא דמותר הוה בה דהא עבד הוה כדקאמר בפרק עשרה יוחסין (קדושין דף ע:) דבטי בר טבי ברמות רוחיה לא קבל גיטא דחירותא:"],[17,"","ראש החוטם. פ\"ה ספק דלא אתפרש ובפרק לולב הגזול (סוכה דף לה:) גבי אתרוג מזכיר פיטומא ועוקץ וחוטם ומתוך כך משמע דשלשתן באתרוג לצד ראשו ואין אחד מהם לצד זנבו דומיא דדד דגבי דד ליכא לפרושי הכי כמו שפירש באתרוג:"]]],[["הכף","וכן היה רבי שמעון (בן יוחי) אומר שלשה סימנין נתנו חכמים באשה מלמטה וכנגדן מלמעלה פגה מלמעלה בידוע שלא הביאה שתי שערות בוחל מלמעלה בידוע שהביאה שתי שערות צמל מלמעלה בידוע שנתמעך הכף","מאי כף אמר רב הונא מקום תפוח יש למעלה מאותו מקום כיון שמגדלת מתמעך והולך שאלו את רבי הלכה כדברי מי שלח להו כדברי כולן להחמיר","רב פפא ורב חיננא בריה דרב איקא חד מתני אהא וחד מתני אחצר צורית דתנן איזוהי חצר צורית שחייבת במעשר ר\"ש אומר חצר הצורית שהכלים נשמרים בתוכה","מאי חצר הצורית אמר רבה בר בר חנה א\"ר יוחנן שכן בצור מושיבין שומר על פתח החצר ר\"ע אומר כל שאחד פותח ואחד נועל פטורה","ר' נחמיה אומר כל שאין אדם בוש לאכול בתוכה חייבת רבי יוסי אומר כל שנכנסים לה ואין אומרים לו מה אתה מבקש פטורה","ר' יהודה אומר שתי חצרות זו לפנים מזו הפנימית חייבת והחיצונה פטורה","שאלו את רבי הלכה כדברי מי אמר להו הלכה כדברי כולן להחמיר","\u0001מתני׳\u0002 בת עשרים שנה שלא הביאה שתי שערות תביא ראיה שהיא בת עשרים שנה והיא איילונית לא חולצת ולא מתיבמת","בן עשרים שנה שלא הביא שתי שערות יביאו ראיה שהוא בן עשרים שנה והוא סריס לא חולץ ולא מיבם אלו דברי בית הלל בית שמאי אומרים זה וזה בן שמונה עשרה","ר' אליעזר אומר הזכר כדברי בית הלל והנקבה כדברי בית שמאי שהאשה ממהרת לבא לפני האיש","\u0001גמ׳\u0002 ורמינהי אחד לי בן תשע שנים ויום אחד ואחד לי בן עשרים שלא הביא שתי שערות","אמר רב שמואל בר רב יצחק אמר רב והוא שנולדו בו סימני סריס אמר רבא דיקא נמי דקתני והוא סריס ש\"מ","וכי לא נולדו לו סימני סריס עד כמה תני ר' חייא עד רוב שנותיו","כי אתו לקמיה דרבי חייא אי כחיש אמר להו אבריוה אי בריא אמר להו אכחשוה דהני סימנים זימנין דאתו מחמת כחישותא זימנין דאתו מחמת בריאותא","אמר רב הלכתא בכולי פרקא מעת לעת ועולא אמר דתנן תנן ודלא תנן לא תנן","בשלמא לעולא היינו דקתני הכא יום אחד והכא לא קתני אלא לרב ליתני","ועוד תני רבי יוסי בן כיפר אומר משום רבי אליעזר שנת עשרים שיצאו ממנה שלשים יום הרי היא כשנת עשרים לכל דבריה וכן הורה רבי בלוד שנת שמנה עשרה שיצאו ממנה שלשים יום הרי היא כשנת שמנה עשרה לכל דבריה","בשלמא דרבי ודרבי יוסי בן כיפר לא קשיא הא כבית שמאי הא כבית הילל אלא לרב קשיא","תנאי היא דתניא שנה האמורה בקדשים שנה האמורה בבתי ערי חומה שתי שנים שבשדה אחוזה","שש שנים שבעבד עברי וכן שבבן ושבבת כולן מעת לעת","שנה האמורה בקדשים מנא לן אמר רב אחא בר יעקב אמר קרא (ויקרא יב, ו) כבש בן שנתו שנתו שלו ולא שנה של מנין עולם","שנה האמורה בבתי ערי חומה מנלן אמר קרא (ויקרא כה, כט) עד תום שנת ממכרו ממכרו שלו ולא שנת של מנין עולם שתי שנים שבשדה אחוזה מנלן אמר קרא (ויקרא כה ) במספר"],[[0,"הכף","מלמטה הוא על בית הרחם כמין תפוח גבוה כדמפרש לקמן:"],[1,"מלמעלה","בדדין:"],[2,"להחמיר","איזה מאלו שתביא שוב אין אביה מפר נדריה דמחזקינן לה בבוגרת נתקשקשו ואע\"ג דלא הכסיף הכסיף אע\"ג דלא התקשקשו וכן כולם. אית דאמרי להחמיר אינה ממאנת משעה שנראה בה אחד מן הסימנין הללו ואינה חולצת עד שיהו כולם ולאו מילתא היא דאפילו לא הביאה אחד מהן גדולה היא ואינה ממאנת וחולצת שהרי כל הסימנים הללו בבגרות נאמרו ומימי נערות היא גדולה למיאון ולחליצה שהרי הביאה שתי שערות. ל\"א הלכה כדברי כולן להחמיר הביאה אחד מן הסימנים הללו ואפילו הקודם שבכולן ולא הביאה את כולן בוגרת ואינה בוגרת ואם קבל אביה בה קדושין וקדשה היא את עצמה לאחר צריכה גט משניהם דכיון שהביאה אחד מן הסימנין הללו יצתה לה במקצת מרשות אביה דאיכא למימר בוגרת הויא ואין כח בקדושי אביה להפקיע קדושין שלה וגם בה אין כח להפקיע קדושי אביה עד שתביא את כולם:"],[3,"שחייבת במעשר","שקובעת תבואה למעשר דקי\"ל חצר קובעת במסכת ביצה (דף לד:):"],[4,"שאחד פותח ואחד נועל","שאין השומר קבוע לפתוח ולנעול אלא זה פותח וזה נועל לאו בת שימור היא ופטורה דלאו שמה חצר:"],[5,"כל שנכנסין לה כו' פטורה","ואע\"ג דאין אדם בוש לאכול בתוכה:"],[7,"כדברי כולן להחמיר","דאם יש בה אחד מכל אלו חייבת אם יש שם שומר חייבת כר' ישמעאל אע\"ג דאחד פותח ואחד נועל ואי ליכא פותח ונועל חייבת כר\"ע ואע\"ג דליכא שומר ואי אין אדם בוש לאכול בתוכה חייבת ואע\"ג דליכא שומר ואיכא פותח ונועל ואם אמר לו מה אתה מבקש חייבת ואפי' לית בה חד מכל הני. ל\"א הלכה כדברי כולן להחמיר כיון שאין אדם בוש לאכול בתוכה קובעת למעשר שאין אוכלין מפירות הנכנסים לה עד שיתעשרו ולהפריש מהן על טבל אחר אסור עד שיהיה לה שומר קבוע:"],[8,"מתני","לא חולצת ולא מתיבמת. ונשאת לכל שתרצה דרחמנא פטרה דכתיב (דברים כ״ה:ו׳) והיה הבכור אשר תלד פרט לאילונית שאינה יולדת:"],[9,"סריס","לאו בר חליצה הוא דכתיב (דברים כ״ה:ז׳) להקים לאחיו שם בישראל והאי לאו בר הכי הוא:"],[9,"ה\"ג יביאו ראיה שהוא בן עשרים","קרובי האשה יביאו ראיה:"],[11,"גמ' ורמינהי אחד לי בן תשע שנים וכו'","שניהם דין אחד להם וביאתו כמאמר בגדול כדאמרינן לעיל אלמא קטן הוא ובעיא אמתוני:"],[12,"אמר רב שמואל","מתני' כגון שנולדו בו סימני סריס המפורשים בהערל כל שאין בשרו מוציא הבל כשהוא רוחץ ושערו לקוי ובשרו מחליק:"],[14,"כי אתו לקמיה דר' חייא","בן עשרים שנה שלא הביא:"],[15,"בכוליה פרקא מעת לעת","חשבינן לה שנה ולא בתר מנין עולם שיהא יום אחד של שנת עשרים חשוב שנה דאף על גב דלא תנן במתניתין בן עשרים שנה ויום אחד כמאן דתנן יום אחד דמי וצריך להשלים את כולה:"],[15,"דתנן תנן","היכא דתנן יום אחד כגון בת שלשה שנים ויום אחד וכולהי דמתני' בר מסיפא דקתני בת עשרים שלא הביאה שתי שערות דהתם לא בעינן עשרים שלמים אלא משנכנס יום אחד בשנת עשרים:"],[18,"בשלמא דרבי ודר' יוסי בן כיפר לא קשיין","אהדדי למהוי מתני' משבשתא דמר כב\"ש ודמר כב\"ה דמתני':"],[19,"בקדשים","היכא דכתיב כבש בן שנתו:"],[20,"מעת לעת","מיום ליום ולא אמרינן למנין עולם שתכלה שנתו ערב ר\"ה:"],[20,"שבבן ושבבת","קסבר היינו בן עשרים שנה ובת עשרים שנה דמתני'. אלמא מעת לעת בעינן אליבא דהאי תנא והנך דלעיל סברי לה כעולא:"],[22,"שתי שנים שבשדה אחוזה","המוכר שדה אחוזה לחבירו אינו מותר לגואלה בפחות משתי שנים שיאכלנה לוקח שתי שנים כדכתיב (ויקרא כה) במספר שני תבואות ימכר לך ומכאן ואילך אם בא לגאול גואל ומחשב לו פירות של שתי שנים לפי חשבון הדמים שמכרה לו לפי שנים הבאים עד היובל שהלוקח שדה מחבירו יודע שיחזירנו לו ביובל ואם היו עד היובל עשר שנים ומכרה לו בעשרה ליטרין נמצא קונה פירות של כל שנה בליטרא:"]],[[2,"","הלכה כדברי כולן להחמיר. מספק פוסק כמר לחומרא וכמר לחומרא כדפרישי' בפרק בנות כותים (לעיל נדה דף לו.):"],[3,"","איזהו חצר (צורית) כו'. קשה לר\"ת דבפרק השוכר את הפועלים (ב\"מ דף פח.) א\"ר ינאי אין הטבל חייב במעשר עד שיראה פני הבית ותירץ דמדרבנן חצר קובעת למעשר ומדאורייתא בעינן ראיית פני הבית:"],[8,"","בת עשרים כו' יביאו ראיה. פירוש קרובי האשה ואי גרסינן תביא היינו היא בעצמה ואי גרסינן יביא קאי אבעל שיביא ראיה שזו היא אילונית והוו קדושי טעות אם רוצה לישא אחותה:"],[9,"","דברי ב\"ה. תימה דבפ' הערל (יבמות דף פ.) איתמר אכל חלב מבן י\"ב שנה עד י\"ח שנה ונולדו בו סימני סריס אמאי שביק דברי ב\"ה דאמר כ' שנה ונקט דברי ב\"ש ואפי' לר' אליעזר הזכר כדברי ב\"ה והתם איירי בזכר וי\"ל דהתם נקט כרבי שהורה בסמוך עד י\"ח:"],[13,"","עד רוב שנותיו. ומכאן ואילך גדול הוא והוי ודאי סריס:"],[14,"","זימנין דאתו מחמת כו'. יש ספרים דגרסי זימנין דנתרן [ע' תוס' ב\"ב קנה: ד\"ה הכי גרס ר\"ת]:"],[20,"","כולן מעת לעת. בפרק שני דזבחים (דף כה:) אמר דשעות פוסלות בקדשים וכן בבתי ערי חומה כדמשמע (פ\"ב דזבחים) ולא דמי לאחריני כדאמרינן דלא בעינן בהן מעת לעת לשעות כדפרישית לעיל (נדה דף מד:) גבי ל' יום איכא בינייהו: [ועי' תוספות ערכין לא. ד\"ה מיום]:"]]],[["שני תבואות ימכר לך פעמים שאתה מוכר שלשה תבואות בשתי שנים","שש שנה שבעבד עברי מנלן אמר קרא (שמות כא, ב) שש שנים יעבוד ובשביעית ובשביעית נמי יעבוד","שבבן ושבבת למאי הלכתא אמר רב גידל אמר רב לענין ערכין ורב יוסף אמר לפרקין דיוצא דופן","א\"ל אביי מי פליגת א\"ל לא הוא אמר חדא ואנא אמינא חדא ולא פליגינן","והכי נמי מסתברא דאי ס\"ד פליגי מאן דאמר לערכין לא אמר ליוצא דופן והאמר רב הלכתא בכולה פרקין מעת לעת","אלא למ\"ד לערכין מ\"ט לא אמר ליוצא דופן דומיא דהנך מה הנך דכתיבן אף הני נמי דכתיבן","ואידך האי שבבן ושבבת שבזכר ושבנקבה מבעי ליה","אמר רב יצחק בר נחמני א\"ר אלעזר הלכה כר' יוסי בן כיפר שאמר משום ר' אליעזר א\"ר זירא אזכה ואיסק ואגמר לשמעתא מפומיה דמרא","כי סליק אשכחיה לר' אלעזר אמר ליה אמרת הלכה כרבי יוסי בן כיפר אמר ליה מסתברא אמרי מדכוליה פירקין תני יום אחד והכא לא קתני שמע מינה מסתברא כותיה:","\u0001הדרן עלך יוצא דופן\u0002","מתני׳ \u0001בא\u0002 סימן התחתון עד שלא בא העליון או חולצת או מתיבמת","בא העליון עד שלא בא התחתון אף על פי שאי אפשר ר' מאיר אומר לא חולצת ולא מתיבמת","וחכ\"א או חולצת או מתיבמת מפני שאמרו אפשר לתחתון לבא עד שלא בא העליון אבל אי אפשר לעליון לבא עד שלא בא התחתון","\u0001גמ׳\u0002 אע\"פ שאי אפשר והלא בא בא לר' מאיר אע\"פ שאי אפשר לרבנן","ולתני בא העליון ר\"מ אומר לא חולצת ולא מתיבמת וחכ\"א או חולצת או מתיבמת ואנא ידענא משום דאי אפשר הוא","אי לא תנא אע\"פ שאי אפשר הוה אמינא רוב נשים תחתון אתי ברישא ומיעוט עליון אתי ברישא ורבי מאיר לטעמיה דחייש למיעוטא ורבנן לטעמייהו דלא חיישי למיעוטא","והני מילי בסתמא אבל היכא דבדקן ולא אשכחן אימר מודו ליה רבנן לר\"מ דעליון קדים","קמ\"ל דאי אפשר ודאי אתי ומנתר הוא דנתר","בשלמא לר\"מ היינו דכתיב (יחזקאל טז, ז) שדים נכונו ושערך צמח אלא לרבנן איפכא מבעי ליה ה\"ק כיון ששדים נכונו בידוע ששערך צמח","בשלמא לר\"מ היינו דכתיב (יחזקאל כג, כא) בעשות ממצרים דדיך למען שדי נעוריך אלא לרבנן איפכא מבעי ליה","ה\"ק כיון שבאו דדיך בידוע שבאו נעוריך ואיבעית אימא מאי שדי כולה בדדי כתיב וה\"ק הקב\"ה לישראל"],[[0,"שני תבואות","מיעוט שני שנים וכתיב תבואות ומשמע כל תבואות של שתי שנים להביא תבואה שלישית ושלש תבואות לא משכחת לה בשתי שנים אלא מעת לעת כגון מכרה לו באלול מלאה פירות נמצא אוכלן ואוכל תבואה עד שיחזור ויקצור קודם אלול הבא הרי שתי תבואות בשנה אחת ועוד יאכל תבואה השנית שהיא שנה השלישית לפי מנין העולם:"],[1,"בשביעית נמי יעבוד","כגון נמכר בניסן וכשיגיע תשרי של שביעית עברו שש למנין עולם והוא יעבוד עד ניסן:"],[2,"לערכין","דהיכא דכתיב (ויקרא כ״ז:ז׳) מבן ששים שנה ומעלה פשיטא לן דשנת ששים כלמטה דהא ומעלה כתיב אבל בן חמש שנים דלא כתיב אלא (שם) מבן חמש שנים ועד בן עשרים שנה ולא כתיב מבן חמש שנים ומעלה אי לא אשמועינן הכא מעת לעת הוה אמינא שנת חמש כלמעלה להכי אשמועינן הכא דבעינן ה' שנים מלאים בכלל ערך הראשון שהוא מועט:"],[2,"לפרקין דיוצא דופן","להיכא דלא תנן ויום אחד כגון בן עשרים ובת עשרים:"],[5,"מ\"ט לא אמר ליוצא דופן","הואיל וס\"ל נמי בהנך מעת לעת:"],[5,"דומיא דהנך","כלומר אף על גב דבהנך דיוצא דופן הוי נמי מעת לעת מיהו האי שבבן ושבבת דמתניתין לא איירי בהן כלל דהא דומיא דקדשים וערי חומה ועבד עברי קתני דכתיבן הלכך ערכין נמי כתיבן אבל שנת עשרים לענין שערות לא כתיבי באורייתא אלא הלכתא היא:"],[6,"שבזכר ושבנקבה מיבעי ליה","לישנא דקרא דכתיב (שם) ולנקבה עשרת שקלים אלא בן ובת לישנא דמתניתין היא בן עשרים ובת עשרים:"],[7,"אזכה ואיסק","לארעא דישראל לאתריה דרבי אלעזר בן פדת:"],[7,"ואגמר שמעתא","דרבי יצחק בר נחמני:"],[7,"מפומיה דמרא","רבי אלעזר:"],[10,"מתני' בא סימן התחתון","שתי שערות סימן נערות:"],[10,"העליון","בוחל:"],[10,"או חולצת","גדולה היא שהשערות סימן מובהק ועליהן סמכינן ולקמן מפרש טעמא:"],[11,"אע\"פ שאי אפשר","פרכינן בגמרא והלא בא:"],[12,"אבל אי אפשר כו'","דהא ודאי מדאתא עליון תחתון נמי אתא אלא שנשרו:"],[13,"גמ' בא לר\"מ","דכיון דאמר ר\"מ לא חולצת דקטנה היא מכלל דס\"ל אפשר לעליון לבא קודם לתחתון:"],[14,"וליתני בא העליון","עד שלא יבא התחתון ולא ליתני אע\"פ שאי אפשר:"],[15,"רוב נשים תחתון אתי ברישא ומיעוט עליון","והאי דקאמר ר\"מ קטנה היא משום דחייש למיעוטא שהעליון בא בקטנותה ורבנן אזלו בתר רובא הלכך מכי אתא עליון לא בעיא בדיקה דמסתמא תחתון אתא. וכיון דטעמייהו דרבנן משום רובא הוא ה\"מ בסתמא היכא דלא בדקו:"],[16,"אבל היכא דבדקו ולא אשכחו","תחתון:"],[16,"אימא מודו","דקטנה היא וממעוטא היא קמ\"ל כו':"],[18,"שדים נכונו","והדר ושערך צמח אלמא עליון זימנין דקדים:"],[19,"בעשות ממצרים דדיך","שהיו מצרים משחקים ביך וממעכין דדיך:"],[19,"למען שדי נעוריך","כדי להתאנף ולזנות ביך כשתהיה ראויה לאשה ותבואי לימי נערות. שדי לשון השלכה כלומר עדיין היו שערות נעוריך עומדים להשתלח ולצאת. אלמא דדים קדמי:"],[20,"ומאי שדי","דמשמע דעדיין היו לצאת:"],[20,"כולה בדדי כתיב","והאי שדי לשון שדים:"]],[[1,"","ובשביעית נמי יעבוד. וא\"ת הא תינח שנת ששית אלא בתחלה אימא ל' יום לפני ראש השנה יהיו חשובים שנה ומשם ואילך ה' שנים שלמים ויש לומר כיון דגלי קרא דששית הויא שנה שלמה הוא הדין דראשונה בעינן שלמה:"],[2,"","רב גידל אמר רב לערכין. וא\"ת כיון דבערכין מוקי לה א\"כ הדרא קושיא לדוכתין דלרב גידל לא משכח רב תנא כוותיה וי\"ל דקסבר רב תנא הוא ופליג:"],[7,"","אמר ר\"א הלכה כר' יוסי בן כיפר. וא\"ת והא רבי אלעזר גופיה פסיק בפ\"ק (לעיל נדה ח.) כרבי אליעזר בד' ותו לא וכ\"ת דהך דהכא לא חשיב משום דר' יוסי בן כיפר קאי כוותיה הא חשיב נמי התם ההיא דד' נשים אע\"ג דרבי יהושע קאי כוותיה אלא משום דרבי יהושע מרבי אליעזר קבלה הכא נמי רבי יוסי משמיה דרבי אליעזר קאמר לה וי\"ל משום דהכא קאי רבי כוותיה כדקאמר וכן הורה רבי בלוד ולא מכח רבי אליעזר פסיק א\"נ דוקא במשניות אמר בפ\"ק דהלכתא כוותיה בארבע:"],[10,"","בא סימן. ר\"מ אומר לא חולצת ולא מתיבמת. וא\"ת ולר' מאיר למה הוזכר סימן העליון כיון דלא סמכינן עליה ולעיל נמי דתנא איזהו סימנים ומפרש ר\"ת דאבוחל קאי וי\"ל דאיצטריך לענין עונשים וקידושין ומילי טובא דרוב פעמים תחתון אתי ברישא כדקאמר בגמרא וא\"נ אי חזינן עליון מסתמא כבר בא התחתון וגדולה היא וצריכה גט לקדושין וגם אסור באחותה:"],[10,"","וחכ\"א או חולצת או מתיבמת. אפילו היא קטנה מתיבמת לרבנן דר\"מ דלא חיישי למיעוטא גבי ההיא דקטן וקטנה לא חולצין כו' אבל לחליצה בעינן שתהא גדולה כדאמר נמי התם יפה אמרת שאין חולצין איש כתיב בפרשה ומקשינן אשה לאיש ולית להו דרבי יוסי דאמר בפרק מצות חליצה (יבמות דף קה:) אשה בין גדולה בין קטנה:"]]],[["איכרפו דדיך לא הדרת בך אישתדו דדיך נמי לא הדרת בך","דכולי עלמא מיהא אתחתון סמכינן מנלן אמר רב יהודה אמר רב וכן תנא דבי ר' ישמעאל אמר קרא (במדבר ה, ו) איש או אשה כי יעשו מכל חטאות האדם השוה הכתוב אשה לאיש לכל עונשין שבתורה מה איש בסימן אחד אף אשה בסימן אחד","ואימא או האי או האי כאיש מה איש תחתון ולא עליון אף אשה תחתון ולא עליון","תניא נמי הכי א\"ר אליעזר בר' צדוק כך היו מפרשין ביבנה ואמרו כיון שבא תחתון שוב אין משגיחין על עליון","תניא רשב\"ג אומר בנות כרכים תחתון ממהר לבא מפני שרגילות במרחצאות בנות כפרים עליון ממהר לבא מפני שטוחנות ברחים","ר\"ש בן אלעזר אומר בנות עשירים צד ימין ממהר לבא שנישוף באפקריסותן בנות עניים צד שמאל ממהר לבא מפני ששואבות כדי מים עליהן ואיבעית אימא מפני שנושאין אחיהן על גססיהן","ת\"ר צד שמאל קודם לצד ימין רבי חנינא בן אחי ר' יהושע אומר מעולם לא קדם צד שמאל לצד ימין חוץ מאחת שהיתה בשכונתי שקדם צד שמאל לצד ימין וחזר לאיתנו","ת\"ר כל הנבדקות נבדקות על פי נשים וכן היה רבי אליעזר מוסר לאשתו ורבי ישמעאל מוסר לאמו","רבי יהודה אומר לפני הפרק ולאחר הפרק נשים בודקות אותן תוך הפרק אין נשים בודקות אותן שאין משיאין ספקות על פי נשים ר\"ש אומר אף תוך הפרק נשים בודקות אותן ונאמנת אשה להחמיר אבל לא להקל","כיצד גדולה היא שלא תמאן קטנה היא שלא תחלוץ","אבל אין נאמנת לומר קטנה היא שתמאן וגדולה היא שתחלוץ","אמר מר רבי יהודה אומר לפני הפרק ולאחר הפרק נשים בודקות אותן בשלמא לפני הפרק בעי בדיקה דאי משתכחי לאחר הפרק שומא נינהו","אלא לאחר הפרק למה לי בדיקה והאמר רבא קטנה שהגיעה לכלל שנותיה אינה צריכה בדיקה חזקה הביאה סימנין כי אמר רבא חזקה למיאון אבל לחליצה בעיא בדיקה","תוך הפרק אין נשים בודקות אותן קסבר תוך הפרק כלאחר הפרק (דמי)","ולאחר הפרק דאיכא חזקה דרבא סמכינן אנשים ובדקי תוך הפרק דליכא חזקה דרבא לא סמכינן אנשים ולא בדקי נשים","ר\"ש אומר אף תוך הפרק נשים בודקות אותן קסבר תוך הפרק כלפני הפרק ובעיא בדיקה דאי משתכחי לאחר הפרק שומא נינהו","ונאמנת אשה להחמיר אבל לא להקל האי מאן קתני לה איבעית אימא רבי יהודה ואתוך הפרק"],[[0,"איכרפו","כשהתחילו לגדל ולעקוץ:"],[0,"אישתדו","גדולות כל צרכן כשדים גמורים. לשון אחר איכרפו נפחו ממיעוך מצרים כלומר לקית על ידם אישתדו יבשו זאת מצאתי:"],[1,"איש","אין בו סימן עליון שאין בו סימן דדים משתנים:"],[3,"תניא נמי הכי","דאתחתון סמכינן:"],[4,"שטוחנות ברחים","ומתוך שמנידות זרועותיהן תדיר מתפשטים דדיהן:"],[5,"שנישוף","פריי\"ר בלע\"ז כמו (יומא דף ל.) מצוה לשפשף:"],[5,"אפקריסותן","מעפורת והוא סודר ותולה על דד הימין אבל בנות עניים אין להן מעפורת:"],[5,"על גססיהן","על צדיהן. על צד תנשאו מתרגמינן על גססיהן תתנטלון (ישעיהו ס״ו:י״ב):"],[8,"לפני הפרק","קודם עונת נדרים שאפילו הביאה שומא נינהו וקטנה היא:"],[8,"נשים בודקות אותן","דבין אמרו איתנהו בין אמרו ליתנהו בקטנה מחזקינן לה ולאו עלייהו סמכינן ובדיקתן להכי מהניא דאי משתכחי בה הני גופייהו לאחר הפרק אמרינן שומא נינהו כדמפרש לקמן ולאחר הפרק נמי אי אמרי איתנהו מהימני וחלצה דהא אורחא הוא למיהוי לה ואי אמרי ליתנהו לא ממאנת דחיישינן שמא נשרו הלכך אנשים לא סמכינן:"],[8,"תוך הפרק","דמסתמא לאו גדולה היא ואי משתכחי מחזקינן לה בגדולה:"],[8,"אין נשים בודקות אותן","שאין נשים כדאי לסמוך עלייהו להתיר ספקות על פיהן ולומר גדולה היא שתחלוץ וס\"ל לרבי יהודה הביאה שתי שערות תוך הפרק סימן הוא כלאחר הפרק הלכך לא מהימנן והכי מפרש לה לקמן:"],[8,"ר\"ש אומר כו'","מפרש לקמן:"],[11,"דאי משתכחי","השתא אמרינן נמי לאחר הפרק שומא נינהו ולא חלצה אי לא אתו בה אחריני ולהכי הוא דמהימני למיאון להחמיר שלא תמאן:"],[12,"אבל לחליצה בעיא בדיקה","ואשה נאמנת עליה הואיל ולאחר הפרק הוה ואורחא למהוי לה כדפרשינן לקמן לאחר הפרק דאיכא חזקה דרבא סמכינן אנשים:"],[13,"ה\"ג קסבר תוך הפרק כלאחר הפרק (דמי) ולאחר הפרק דאיכא חזקה כו'","והכי פירושא תוך הפרק להכי לא מהימנא דקסבר רבי יהודה תוך הפרק אם הביאה אמרינן סימן הם וגדולה היא הלכך אתי למשרי מידי דלאו אורחא ע\"פ נשים דלאו כהלכתא דאע\"ג שנאמנות הן לאחר הפרק התם הוא דאיכא חזקה דרבא אבל תוך הפרק כו':"],[15,"ר\"ש אומר כלפני הפרק דמי","ושומא נינהו הלכך לאו עלייהו סמכינן למימר גדולה היא או קטנה היא ולהכי הוא דמהני דאי משתכחי לאחר הפרק שומא נינהו:"],[16,"הא מאן קתני לה","דהא אדר\"ש לא מתוקמא דכיון דאמר תוך הפרק כלפני הפרק אי בדקו לה תוך הפרק מאי גדולה היא שלא תמאן איכא והא אמרת אפי' משתכחי שומא נינהו:"],[16,"אי בעית אימא רבי יהודה ואתוך הפרק","דקאמר אין הנשים בודקות אותן דתוך הפרק כלאחר הפרק דמי ואי לא בדקו שפיר אתי למימר אקטנה דגדולה היא וקמ\"ל דלהחמיר מהימנא אבל לפני הפרק ליכא למימר גדולה שלא תמאן דהא אפילו הביאה דברי הכל שומא נינהו ולאחר הפרק אפילו להקל קאמר רבי יהודה מהימנא:"]],[[4,"","רבן שמעון בן גמליאל אומר בנות כפרים כו'. פליג אדרבנן דאמרי בכולהון ממהר לבא התחתון ואדר\"מ נמי פליג דהא ר' מאיר לא מפליג בין כרכים לכפרים:"],[11,"","בשלמא לפני הפרק כו' דאי משתכחי לאחר הפרק שומא נינהו. פירש בקונט' ולא תחלוץ והדין עמו דליכא לפרושי שומא נינהו ותמאן דהא קתני בסיפא דאינה נאמנת לומר קטנה היא ותמאן וא\"ת אמאי בודקין אותה לא תבדוק ותחלוץ לאחר הפרק דהא השתא סבר המקשן דחזקה דהביאה סימנין דקאמר רבא דהויא לחליצה ולמאי דמשני נמי דבחליצה בעי בדיקה נבדוק אחר הפרק ותו לא דליכא למיחש שמא מלפני הפרק באו והוו שומא דהא דוקא כי ראו אותם לפני הפרק קאמר הכא דשומא נינהו אבל אם לא ראו אותם מקודם משמע דאין לנו לחוש ובשלהי מצות חליצה (יבמות דף קה:) נמי דאמר ליה רבי לאבדן זיל בדקה מסתמא לא בדקוה לפני הפרק וכן משמע בפרק מי שמת (ב\"ב דף קנה.) גבי בני ברק דקאמר מהו לבודקו אלמא אי משתכחי בהו סימנים לא אמרינן דלפני הפרק באו וי\"ל דהא דקאמר דבודקין אותן היינו לכתחילה א\"נ בודקין לאו דוקא אלא כלומר דאם בדקו דמהני בדיקתן קאמר וא\"ת אמאי פריך אלא לאחר הפרק למה לי בדיקה הא נפקא מינה שאם בדקו ולא מצאו שום שערות או שמצאו אותן שערות עצמן דאינה חולצת כמו שאנו מפרשים בדיקה דלפני הפרק ויש לומר דהך בדיקה דלאחר הפרק משמע ליה דהיינו להחזיקה כגדולה דאי להחזיקה כקטנה א\"כ תוך הפרק אמאי אינן נאמנות השתא אחר הפרק נאמנות כ\"ש תוך הפרק ולכך פריך דבלא בדיקה נמי מחזקינן לה כגדולה:"],[16,"","איבעית אימא רבי יהודה ואתוך הפרק ואי בעית אימא ר' שמעון כו'. וא\"ת ומאי קאמר דנאמנת לומר גדולה היא שלא תמאן מה צריך לנאמנות הא בלאו הכי לא ממאנת ואפילו אמרה קטנה היא אינה נאמנת כדקתני סיפא אבל אינה נאמנת לומר קטנה היא ותמאן וי\"ל דנפקא מינה שאם בדקו אנשים אחר בדיקתה ולא מצאו שערות אפ\"ה לא תמאן ואי לאו נשים הוה ממאנת שפיר דאפילו למ\"ד חוששים שמא נשרו היינו דוקא לאחר הפרק לר' יהודה משום דרבא דחזקה שהביאה סימנין אבל תוך הזמן לרבי יהודה דליכא חזקה או אחר זמן לר\"ש דלית ליה חזקה דרבא אין חוששין שמא נשרו והשתא שאמרו הנשים שהיו שערות נאמנות ולא תמאן ואע\"ג דאפילו תוך הזמן לר' יהודה דליכא חזקה או אחר זמן לר\"ש אינה ממאנת אהני חזקה דרבא לבדקו ולא מצאו שערות דמשום חזקה אמרינן דנשרו כדפסיק לעיל והילכתא חוששין שמא נשרו והוא שבעל לאחר זמן וא\"ת ונאמנת לומר קטנה היא שלא תחלוץ מאי אהני נאמנת הלא אפילו אמרה יש שערות אינה נאמנת כדקתני סיפא אינה נאמנת לומר גדולה היא כו' וי\"ל דנאמנת לומר שאותן שערות היו קודם הפרק דאי לאו האשה הוה אמינא אחר הפרק באו וחלצה כדפריך לעיל:"]]],[["ואיבעית אימא רבי שמעון ולאחר הפרק ולית ליה חזקה דרבא","מפני שאמרו אפשר כו' הא תו למה לי הא תנא ליה רישא","וכי תימא משום דקא בעי למסתמה כרבנן פשיטא יחיד ורבים הלכה כרבים","מהו דתימא מסתברא טעמא דר\"מ דקא מסייע ליה קראי קמ\"ל ואיבעית אימא משום דקא בעי למתני כיוצא בו","\u0001מתני׳\u0002 כיוצא בו כל כלי חרס שהוא מכניס מוציא ויש שמוציא ואינו מכניס","כל אבר שיש בו צפורן יש בו עצם ויש שיש בו עצם ואין בו צפורן","כל המטמא מדרס מטמא טמא מת ויש שמטמא טמא מת ואינו מטמא מדרס","\u0001גמ׳\u0002 מכניס פסול למי חטאת ופסול משום גסטרא מוציא כשר למי חטאת ופסול משום גסטרא","אמר רב אסי שונין כלי חרס שיעורו בכונס משקה ולא אמרו מוציא משקה אלא לענין גסטרא בלבד מאי טעמא אמר מר זוטרא בריה דרב נחמן לפי שאין אומרים הבא גסטרא לגסטרא","תנו רבנן כיצד בודקין כלי חרס לידע אם ניקב בכונס משקה אם לאו יביא עריבה מלאה מים ונותן קדרה לתוכה אם כנסה בידוע שכונס משקה ואם לאו בידוע שמוציא משקה"],[[0,"ואיבעית אימא ר\"ש ולאחר הפרק","קאי דקאמר ר\"ש תוך הפרק בודקות ולא אתינן למסמך עלייהו לחליצה ולמיאון דהא אפי' משתכחי כלפני הפרק דמי וקטנה היא אבל לאחר הפרק דאי משתכחי סימן נינהו ושרינן לה לא מהימני אלא להחמיר דלית ליה חזקה דרבא:"],[2,"למסתמה כרבנן","דהא מפני שאמרו סתמא היא וקמ\"ל סתם משנה כרבנן דאמרי אי אפשר:"],[3,"קראי","שדים נכונו בעשות מצרים דדיך:"],[4,"מתני' שהוא מכניס","משקה. כשמניחו על המים יש בו נקב גדול שהמים נכנסין לתוכו:"],[4,"מוציא","כל שכן אם נותן המים לתוכו יוצא המשקה לחוץ:"],[4,"ויש","נקב קטן שמוציא ואינו מכניס. ובגמרא מפרש מאי נפקא מינה:"],[5,"כל אבר","אצבע יתרה:"],[5,"שיש בו צפורן יש בו עצם","והוי אבר חשוב ומטמא באהל אפי' אין בה שיעור דקיימא לן האברים אין להם שיעור אפי' פחות מכזית מן המת:"],[5,"ויש שיש בו עצם כו'","לא הוי אבר אם יתרת היא אבל אינה של יתרת אפי' אין בו צפורן אבר הוא ומטמא:"],[6,"כל המטמא במדרס הזב מטמא במת","כדמפרש בגמרא שאין לך כלי הראוי למושב הזב שאין שם כלי עליו וראוי לקבל כל טומאות. והא דנקט טמא מת משום דומיא דמדרס הוא דאב הטומאה הוא והכי קאמר כל הראוי להיות אב הטומאה במדרס הזב ראוי להיות אב הטומאה אם נגע במת או נטמא באהל המת:"],[6,"ויש","שהוא כלי גמור לקבל כל טומאות ונעשה אב הטומאה על ידי מת ואינו נעשה אב הטומאה על ידי הזב במדרס כדמפרש בגמרא:"],[7,"גמ' למי חטאת","לקדש בו מי חטאת דרחמנא אמר (במדבר י״ט:י״ז) מים חיים אל כלי והאי לאו כלי הוא:"],[7,"ופסול משום גסטרא","כלומר כל שכן אם נקבה גסטרא בכונס משקה בטיל לה מתורת גסטרא וטהורה מכל טומאה דהא אפי' כלי שלם מכי נקיב ככונס משקה בטיל ליה:"],[7,"גסטרא","היינו שברי כלי חרס הראויין למלאכה ועדיין מקבלין טומאה כדתניא בגמרא באלו טרפות (חולין דף נד:) הדקין שבכלי חרס הן וקרקרותיהן ודופנותיהן יושבין שלא מסומכין שיעורן בכדי סיכת קטן עד לוג ומלוג עד סאה ברביעית כו':"],[7,"מוציא","דנקב קטן הוא:"],[7,"כשר למי חטאת","דכלי שלם בנקב קטן כולי האי לא בטיל:"],[7,"ופסול משום גסטרא","גסטרא שנקבה אפילו כמוציא משקה בטלה לה:"],[8,"שונין","הלכה למשה מסיני:"],[8,"שיעורו ככונס משקה","פחות של שיעורים המבטלים אותו מהיות כלי. כונס משקה הוא שיעור הראשון שהוא מבטלו מהיות כלי למי חטאת כדאמר במסכת שבת (דף צה:) חמש מדות בכלי חרס לן [ניקב כמוציא משקה טהור מלטמא גסטרא ועדיין כלי הוא לקדש בו מי חטאת] ניקב ככונס משקה פסול לקדש בו מי חטאת ועדיין כלי הוא לכל שאר דברים ניקב כשורש קטן טהור להכשיר זרעים ועדיין כלי הוא לטומאה שהרי ראוי לקבל בו זיתים ניקב כמוציא זית טהור מטומאה שקבל עד שייחדנו לרמונים ניקב כמוציא רמון טהור מכלום נמצא כונס משקה הוא שיעור הראשון אבל כמוציא משקה לא בטיל:"],[8,"ולא אמרו מוציא משקה","בטיל אלא לענין גסטרא בלבד אע\"פ שאינו מכניס לפי שאין אומרים הבא גסטרא לגסטרא כשניקבה כמוציא משקה שוב אין חס עליה ואינו משתמש בה שאין אומר הבא גסטרא אחרת ונניח תחת גסטרא זו לקבל משקה היוצא אבל בכלי שלם שנקב כמוציא משקה לא בטיל מכלום לפי שהוא חס עליו ואינו שוברו ומשתמש בו ומביא גסטרא ומניח תחתיו לקבל משקה היוצא:"],[9,"אם כנסה","אם נכנס משקה לתוכה:"]],[[0,"","ואיבעית אימא רבי שמעון ולאחר הפרק ולית ליה חזקה דרבא. ר\"ח פוסק דהלכה כרבי שמעון דתוך הפרק כלפני הפרק כדמסקינן שלהי יוצא דופן (לעיל נדה דף מו.) וההוא דאית ליה דתוך הזמן כלאחר זמן איתותב לעיל ומתוך כך פסק נמי דאין הלכה כרבא דאמר חזקה הביאה סימנין דהא ר' שמעון דפסקינן כוותיה לית ליה דרבא ועוד בפרק מי שמת (ב\"ב דף קנו.) אמר רב נחמן בודקין לחליצה ולמיאונים ואין נראה דאפילו יהיה הלכה כר' שמעון בהא דתוך הפרק כלפני הפרק אין הלכה כמותו בהא דלית ליה חזקה דרבא דלאו הא בהא תליא ורבא גופיה פסיק לעיל דתוך הזמן כלפני זמן והא דמוקי הש\"ס ברייתא כרבי שמעון ולית ליה דרבא אע\"ג דאתי שפיר כרבי יהודה וכרבא אין זו ראייה מן הש\"ס דמיישב הברייתא בכל ענין ודרב נחמן נמי ליתא מקמי רבא דהוי בתראה ועוד דרבא נמי איכא לאוקומי מילתיה דרב נחמן דאמר בודקין למיאונין היינו תוך הפרק דליכא חזקה אי נמי אחר הפרק ובודקין אם לא ימצאו שערות תמאן דאין חוששין שמא נשרו אלא כשבעל אחר זמן ורבא איירי בשבעל ומעשים בכל יום דסמכינן אבדיקת נשים לאחר הפרק והיינו דלא כר\"ש ואפי' בתוך הפרק כלפני הפרק אומר רבי דאין הלכה כרבי שמעון דעל כרחך תוך הזמן ותוך הפרק לאו חדא מילתא הוא דאי חדא מילתא הוא א\"כ אמאי איתותבו לעיל רבי יוחנן ורבי יהושע בן לוי דאמרי תוך הזמן כלאחר הזמן כיון דפליגי הכא תנאי ועוד דלעיל קרי ליה זמן והכא קרי ליה פרק ועוד פרק משמע גדלות כמו (יבמות דף סב:) המשיאן סמוך לפרקן ובפרק המוציא יין (שבת דף פ:) בנות ישראל שהגיעו לפרקן ולא הגיעו פירוש הביאו ב' שערות ולא הגיעו לכלל שנים ומפרש רבינו תם דפליגי הכא ביום אחרון של שנת י\"ב ויום אחד לנקבה או ביום שנת י\"ג ויום אחד לזכר ואותו יום אקרי תוך הפרק דלר' יהודה הוי זמן הבאת שערות מתחלת היום ולרבי שמעון בסופו וקי\"ל כרבי יהודה לגבי רבי שמעון בפרק מי שהוציאוהו (עירובין דף מו:) והשתא יבם קטן או יבמה קטנה שבאו לחלוץ טוב לכתחלה לבודקם לפני הפרק אם יש להם שערות וכן לאחר הפרק ואם הן אותן שהיו קודם נמתין עד שיביאו שערות אחרות אבל יבם גדול ויבמה גדולה דלא אפשר עוד לברר חולצין שפיר אם יש להם שערות ואין לחוש שמא לפני הפרק באו כדפירשתי לעיל ואם יש ליבמה דדים גדולים אין צריך לבדוק אחר השערות דהא אמרינן לעיל אי אפשר שיבא העליון עד שיבא התחתון:"],[7,"","כשר למי חטאת. והא דאמרינן (יומא דף ב.) שכל מעשיה בכלי גללים בכלי אבנים בכלי אדמה היינו בזמן שמזין על כהן השורפה שהחמירו שם לפי שהקילו לטמאותה לשחטה בטבול יום להוציא מלבן של צדוקים:"],[8,"","אלא לענין גסטרא. פירש ר\"ח גסטרא הוא שבר בלשון יון ונראה דאין שבר כלי חרס טמא משום גסטרא אלא א\"כ יחדו דהא אפילו שלם כשניקב בכונס משקה טהור עד שייחדנו לאוכלין כ\"ש אם נשבר לגמרי דבעו השברים יחוד וא\"ת והא דתנן ומייתי לה בפרק אלו טרפות (חולין דף נד:) הדקין שבכלי חרס הן וקרקרותיהן ודופנותיהן שיעורן בכדי סיכת קטן עד לוג ומלוג עד סאה ברביעית כו' כיון דאיירי ע\"י יחוד אפילו שבר מכלי גדול יהא שיעורו בכדי סיכת קטן וי\"ל דאין דרך לייחד שבר קטן הבא מכלי גדול ובטלה דעתו אצל כל בני אדם ואם תאמר הא דתניא בתוספתא דכלים ס\"פ מחט וטבעת ושולי המחצין וקרקעות הכלים אין ממלאים ואין מקדשין בהם שפאן ועשאן כלי מקדשין בהן כו' דברי ר\"מ וחכ\"א כלי שטהר שעה אחת אין לו טומאה עולמית ואין לומר דכשצריך תקון תו לא נחית ליה טומאה דהתנן במסכת כלים (פ\"ה מ\"ח) חתכו חוליות פחות מד' טפחים טהור מרחו בטיט מקבל טומאה משיסיקנו לאפות בו סופגנין אלמא מהני בה תיקון ולא מסתברא דאתיא כר\"מ ולא כרבנן וי\"ל דמה שאין לו טומאה לעולם היינו בשברים הפחותים משיעור המפורש בחולין (דף נה.) ומחמת גריעותם לא מהני תקון בהן אבל הך דתנור מיירי דע\"י תקון הוא כבתחלה:"],[9,"","אם כנסה בידוע שהוא ככונס משקה. והא דאמר בפרק כל הבשר (חולין דף קז.) אי בזיע דוולא ככונס משקה מילף לייפי ומטבילין בו הידים דהוו מחוברין לנהר לאו היינו ככונס משקה דהכא דהתם איירי כשהנקב כל כך גדול עד שהמים מקלחין והוי חבור ע\"י נצוק לידים דאע\"ג דלענין טבילה לא הוי חבור וכונס משקה דהכא שיורד טיף טיף כדאמר בסמוך מיהו אפשר דההוא כונס משקה הוי כדהכא דהתם נמי מייתי האי כונס משקה דהכא דאמר רבא כלי שניקב בכונס משקה אין נוטלין הימנו לידים משמע דשוין ואע\"ג דלא הוי נצוק דבדבר מועט הוי חבור לענין טבילת ידים וגם רש\"י לא הזכיר שם נצוק ואע\"ג דבכולי שמעתין במתניתין ובברייתא לא קאמר כונס משקה אלא בכלי חרס ובסוף המצניע (שבת דף צה:) נמי קאמר ה' מדות בכלי חרס משמע דדווקא בכלי חרס הן כל אותם מדות ולא בכלי עץ מ\"מ הא דרבא דאמר בפ' כל הבשר כלי שנקב בכונס משקה אין נוטלין הימנו לידים יש להחמיר בכל הכלים שניקבו ככונס משקה שלא ליטול מהם כיון שלא הזכיר שם כלי חרס אלא קאמר כלי סתם:"]]],[["רבי יהודה אומר כופף אזני קדרה לתוכה ומציף עליה מים ואם כונס בידוע שכונס משקה ואם לאו בידוע שמוציא משקה","או שופתה על גבי האור אם האור מעמידה בידוע שמוציא משקה ואם לאו בידוע שמכניס משקה","ר' יוסי אומר אף לא שופתה על גבי האור מפני שהאור מעמידה אלא שופתה על גבי הרמץ אם רמץ מעמידה בידוע שמוציא משקה ואם לאו בידוע שכונס משקה היה טורד טיפה אחר טיפה בידוע שכונס משקה","מאי איכא בין ת\"ק לר' יהודה אמר עולא כינוס על ידי הדחק איכא בינייהו","כל אבר שיש בו צפורן וכו' יש בו צפורן מטמא במגע ובמשא ובאהל יש בו עצם ואין בו צפורן מטמא במגע ובמשא ואינו מטמא באהל","אמר רב חסדא דבר זה רבינו הגדול אמרו המקום יהיה בעזרו אצבע יתרה שיש בו עצם ואין בו צפורן מטמא במגע ובמשא ואינו מטמא באהל","אמר רבה בר בר חנה א\"ר יוחנן וכשאינה נספרת על גב היד","כל המטמא מדרס וכו' כל דחזי למדרס מטמא טמא מת","ויש שמטמא טמא מת ואין מטמא מדרס לאתויי מאי לאתויי סאה ותרקב","דתניא (ויקרא טו, ו) והיושב על הכלי יכול כפה סאה וישב עליה או תרקב וישב עליו יהא טמא","ת\"ל (ויקרא טו, ו) אשר ישב עליו הזב מי שמיוחד לישיבה יצא זה שאומרים לו עמוד ונעשה מלאכתנו","\u0001מתני׳\u0002 כל הראוי לדון דיני נפשות ראוי לדון דיני ממונות ויש שראוי לדון דיני ממונות ואינו ראוי לדון דיני נפשות","\u0001גמ׳\u0002 אמר רב יהודה לאתויי ממזר","תנינא חדא זימנא הכל כשרין לדון דיני ממונות ואין הכל כשרין לדון דיני נפשות והוינן בה לאתויי מאי ואמר רב יהודה לאתויי ממזר חדא לאתויי גר וחדא לאתויי ממזר","וצריכי דאי אשמעינן גר משום דראוי לבא בקהל אבל ממזר דאין ראוי לבא בקהל אימא לא","ואי אשמעינן ממזר משום דקאתי מטפה כשרה אבל גר דקאתי מטפה פסולה אימא לא צריכא","\u0001מתני׳\u0002 כל הכשר לדון כשר להעיד ויש שכשר להעיד ואינו כשר לדון","\u0001גמ׳\u0002 לאתויי מאי א\"ר יוחנן לאתויי סומא באחת מעיניו ומני"],[[0,"ר' יהודה אומר","לא כך בודקין אותה דהא קולא הוא דאיידי דדחיק להו לשולים אימא עיילי מיא לגוה אפילו בנקב קטן אלא הכי בדקינן לה כופה פי הקדרה לתוך העריבה קודם שיתן המים ואח\"כ נותן מים בעריבה עד שיהו מים צפין על שוליה אם כנסה בידוע כו':"],[1,"אם האור מעמידה","שלא יצא המשקה בידוע שנקב קטן הוא ואינו ראוי להכניס משקה:"],[2,"שהאור מעמיד","אפילו נקב גדול:"],[2,"רמץ","גחלים ואפר בוערים:"],[2,"היה טורד טיפה אחר טיפה","כלומר וזו נמי בדיקה אם נתן לתוכו מים והן יוצאין טיף אחר טיף בידוע שכונס משקה:"],[3,"ה\"ג מאי איכא בין תנא קמא לר' יהודה כינוס ע\"י הדחק איכא בינייהו","לת\"ק הוי כינוס כדפרישית:"],[4,"יש בו צפורן","ואפי' היא יתרה כגון אצבע ששית:"],[4,"מטמא במגע ובמשא ובאהל","דהוי אבר חשוב ואפי' ליכא כזית בשר מטמא באהל דקי\"ל האברים אין להן שיעור בפ' יוצא דופן (לעיל נדה דף מג:). אין בו צפורן לא הוי אבר ומיהו מטמא במגע ובמשא כדין עצם כשעורה שהרי יש בו עצם:"],[4,"ואינו מטמא באהל","עד דאיכא כזית בשר דקיימא לן עצם כשעורה מטמא במגע ובמשא ולא באהל ואי איכא כזית בשר ודאי מטמא דהא איכא כזית מן המת ואי לאו יתרה היא ודאי מטמא משום אבר באהל ואע\"ג דליכא כזית בשר דאפילו יתרה אמרי' לקמן דאי נספרת על גב היד הויא אבר:"],[5,"רבינו הגדול","רב:"],[6,"על גב היד","שאינה עומדת בשורת האצבעות:"],[8,"לאתויי סאה ותרקב","שאינן מדרס הזב לטמא אדם וכלים אבל טמאין הם טומאת מגע הזב להיות ראשונים ובמת נעשין אב הטומאה:"],[10,"מי שמיוחד לישיבה","הוא דהוו אב הטומאה דכתיב וכבס בגדיו וגו':"],[11,"מתני' כל הראוי לדון דיני נפשות","כ\"ש שהוא כשר לדיני ממונות:"],[12,"גמ' לאתויי ממזר","דכשר לדיני ממונות ופסול לדיני נפשות כדכתי' (בסנהדרין דף לו:) כולך יפה רעיתי:"],[13,"גר","נמי כשר לדיני ממונות:"],[17,"לאתויי סומא באחת מעיניו","דכשר להעיד ואינו כשר לדון אבל בשתי עיניו אפילו לעדות פסול דכתיב (ויקרא ה) או ראה:"]],[[4,"","יש בו עצם ואין בו צפורן מטמא במגע ובמשא אבל לא באהל. בפ' אלו מומין (בכורות מה.) אית דמפרש טעמא גזרה שאינה נספרת על גב היד אטו נספרת אבל באהל המת לא גזרו דעבדי היכרא דלא לישרוף עליה תרומה וקדשים ואית דאמר משום דעצם כשעורה נגע בה ותימה להאי טעמא אמאי מטמא במגע כשנוגע בבשר ואינו נוגע בעצם דאי משום דבשר הוי יד ושומר לעצם האמר רב בפרק העור והרוטב (חולין דף קיח:) דאין יד לפחות מכזית ואין שומר לפחות מכפול ורבינו הגדול דהכא היינו רב ויש לומר דגזרו חכמים אטו לפעמים דיש בעצם כפול אי נמי נגיעת בשר אטו נגיעת עצם או גזרו מגע אטו משא:"],[7,"","כל המטמא מדרס. היינו מק\"ו דפכין קטנים ובפ' כיצד הרגל (ב\"ק דף כה:) פירשנו:"],[13,"","תנינא חדא זימנא. תימה מאי קושיא הא כמה כללות תנא במתני' אע\"ג דתנא להו בדוכתא אחריתי דקתני כל שהוא חייב בפאה חייב במעשר כו' ושמעינן לה ממתני' במסכת פאה (פ\"א מ\"ד) דקתני לקיטתו כאחד ומכניסו לקיום ובמעשר לא תני ליה וכן כל שחייב בראשית הגז חייב במתנות ושמעינן לה ממתניתין דראשית הגז וכל שיש לו ביעור יש לו שביעית שמעינן נמי ממתני' דשביעית וי\"ל דלא פריך אלא אדרב יהודה דמאי הוצרך למימר לאתויי ממזר הכא והתם והשתא אתי שפיר דלא קאמר דההיא דסנהדרין (דף לו:) לאתויי חלל דכשר לדיני ממונות ופסול לדיני נפשות כדתנן התם אין כשר לדיני נפשות אלא מן המשיאין לכהונה אלא לא פריך אמתני' כי אם על רב יהודה וארב יהודה לא מצי לשנויי דחדא לאתויי חלל דמלישנא דסיפא דאחד דיני ממונות דקתני דאין כשר לדיני נפשות אלא מן המשיאין לכהונה משמע אבל כשר לדיני ממונות ולכל הפחות מוקמינן אחלל דכשר וצ\"ל דרב יהודה אתא לאשמועינן דגר וממזר כשרים לדיני ממונות דפסולין לדיני נפשות שמעינן ממתני' דהתם וגרסינן הכא כמו שיש ספרים דגרסי בסנהדרין (דף לו:) אי אשמועינן גר משום דראוי לבא בקהל כו' ואי אשמועינן ממזר דבא מטפה כשרה להכי כשר לדיני ממונות אבל גר אימא לא ול\"ג איפכא כמו שהיה בספרים אי אשמועינן גר משום דבא מטיפה פסולה ולכך פסול לדיני נפשות דרב יהודה לא אתא לאשמועי' הא דפסול לדיני נפשות כדפרישנא:"],[13,"","לאתויי ממזר. וא\"ת ואמאי לא קאמר לאתויי בעל מום דפסול בדיני נפשות ומפיק לה בפרק אחד דיני ממונות (סנהדרין דף לו:) ובריש מצות חליצה (יבמות דף קא.) כשם שבית דין מנוקין בצדק כך מנוקין מכל מום וי\"ל דלא איירי אלא בפסול יוחסין וה\"נ איתא בפ' זה בורר (סנהדרין דף כז:) דפריך והא עד זומם דדיני ממונות דכשר לדיני נפשות ופסול לדיני ממונות ומשני בפסול יוחסין קמיירי:"],[13,"","חדא לאתויי גר. משמע דכשר אע\"ג דאין אמו מישראל ותימה דבפ' החולץ (יבמות דף מה:) אמרי' דרבא אכשר לרב מרי בר רחל ומנייה בפורסי דבבל דכיון דאמו מישראל מקרב אחיך קרינא ביה וי\"ל דהכא מיירי לדון גר חבירו כדאמר בפרק מצות חליצה (יבמות דף קב.) גר דן חבירו דבר תורה ואם היתה אמו מישראל דן אפילו ישראל ולא כמו שפירש שם בקונט' דלענין דיני נפשות איירי הא דדן את חברו אבל בדיני ממונות דן אפי' ישראל וא\"ת דבפרק עשרה יוחסין (קדושין דף עו:) על גמרא דמי שהוחזקו אבותיו כו' דפריך למימרא דלא אוקמינן פסולין ורמינהי הכל כשרין כו' ואמר רב יהודה לאתויי ממזר ומאי קושיא לישני דהיינו דוקא לדון ממזר כיוצא בו דומיא דגר ואם נאמר דהכא מיירי בגר שאמו מישראל הוה אתי שפיר וי\"ל דשאני ממזר דכיון דאביו ואמו מישראל מקרב אחיך קרינן ביה תדע דהא דדרשינן עליך הוא דבעינן מקרב אחיך וממזר מקרי שפיר עליך דבא מזרע ישראל ואם ממזר פסול לדון את ישראל מיפסיל נמי לדון את ממזר חברו והא דתניא בתוספתא אין מעמידין מלך אלא מן המשיאין לכהונה היינו מדרבנן דמדאורייתא אפי' ממזר חשיב מקרב אחיך והא דעביד צריכותא בין גר לממזר אע\"ג דחלוקין זה מזה כדפי' נקט צריכותא לפי שהמשנה שנויה סתם ואין חלוק זה מפורש בה וא\"ת בפ' מצות חליצה (יבמות דף קא:) דא\"ל רב שמואל בר יהודה לרב יהודה תנינן בב\"ד של ישראל ולא בב\"ד של גרים ורגיל ר\"ת לומר דאותו רב שמואל היינו בנו של רב יהודה הינדואה דאמר בפ\"ק דקידושין (דף כב:) דגר שאין לו יורשין הוה ונתגייר הוא ובנו וכן משמע הלשון דקאמר ואנא גר אנא משמע דהוא עצמו נתגייר וכיון דלא היתה אמו מישראל לשאר דינין נמי מיפסיל ואמאי הוצרך להביא קרא דחליצה וגם רב יהודה היאך בררו לדיין וי\"ל דקבלו עליהם החולץ והחולצת דבדיני ממונות הוי כשר ולחליצה מיפסיל כדאמר התם אי נמי התם לחליצת גרים מיירי ואין להאריך כאן יותר:"],[16,"","כל הכשר לדון כשר להעיד. וא\"ת והרי אשה דכשרה לדון כדכתיב בדבורה והיא שופטה את ישראל בעת ההיא ובשלהי פ\"ק דב\"ק (דף טו.) דרשינן אשר תשים לפניהם השוה הכתוב אשה לאיש לכל עונשין שבתורה וכי היכי דהאי קרא מיירי בנדונין מיירי נמי בדיינין כדדרשינן בהמגרש (גיטין פח:) לפניהם ולא לפני עובדי כוכבים ואשה פסולה להעיד כדאמר בפרק שבועת העדות (שבועות דף ל.) וי\"ל דה\"ק כל איש הכשר לדון כשר להעיד אי נמי נהי דבנידונין הוי אשה בכלל מ\"מ בדיינים אין אשה בכלל ודבורה היתה דנה ע\"פ הדיבור אי נמי לא היתה דנה אלא מלמדת להם הדינים ובירושלמי פוסל אשה לדון אית דילפי מועמדו שני אנשים שני מעל פי שנים עדים ואית דילפי מוישארו שני אנשים במחנה:"]]],[["רבי מאיר היא דתניא היה רבי מאיר אומר מה ת\"ל (דברים כא, ה) על פיהם יהיה כל ריב וכל נגע וכי מה ענין ריבים אצל נגעים מקיש ריבים לנגעים מה נגעים ביום דכתיב (ויקרא יג, יד) וביום הראות בו אף ריבים ביום","ומה נגעים שלא בסומא דכתיב (ויקרא יג, יב) לכל מראה עיני הכהן אף ריבים שלא בסומא ומקיש נגעים לריבים מה ריבים שלא בקרובים אף נגעים שלא בקרובים","אי מה ריבים בשלשה אף נגעים בשלשה ודין הוא ממונו בשלשה גופו לא כ\"ש ת\"ל (ויקרא יג, ב) והובא אל אהרן הכהן או אל אחד מבניו הכהנים הא למדת שאפילו כהן אחד רואה את הנגעים","ההוא סמיא דהוה בשבבותיה דרבי יוחנן דהוה קדיין דינא ולא קאמר ליה ולא מידי היכי עביד הכי והאמר רבי יוחנן הלכה כסתם משנה","ותנן כל הכשר לדון כשר להעיד ויש כשר להעיד ואין כשר לדון ואמרינן לאתויי מאי ואמר רבי יוחנן לאתויי סומא באחת מעיניו","רבי יוחנן סתמא אחרינא אשכח דתנן דיני ממונות דנין ביום וגומרין בלילה","ומאי אולמיה דהאי סתמא מהאי סתמא איבעית אימא סתמא דרבים עדיף ואיבעית אימא משום דקתני לה גבי הלכתא דדיני","\u0001מתני׳\u0002 כל שחייב במעשרות מטמא טומאת אוכלין ויש שמטמא טומאת אוכלין ואינו חייב במעשרות","\u0001גמ׳\u0002 לאתויי מאי לאתויי בשר ודגים וביצים","\u0001מתני׳\u0002 כל שחייב בפאה חייב במעשרות ויש שחייב במעשרות ואינו חייב בפאה","\u0001גמ׳\u0002 לאתויי מאי לאתויי תאנה וירק שאינו חייב בפאה דתנן כלל אמרו בפאה כל שהוא אוכל ונשמר וגידולו מן הארץ ולקיטתו כאחד ומכניסו לקיום חייב בפאה","אוכל למעוטי ספיחי סטים וקוצה ונשמר למעוטי הפקר וגידולו מן הארץ למעוטי כמהים ופטריות ולקיטתו כאחד למעוטי תאנה ומכניסו לקיום למעוטי ירק","ואילו גבי מעשר תנן כל שהוא אוכל ונשמר וגידולו מן הארץ חייב במעשרות ואילו לקיטתו כאחד ומכניסו לקיום לא קתני","אם היו בהם שומים ובצלין חייבין דתנן מלבנות בצלים שבין הירק ר' יוסי אומר פאה מכל אחת ואחת וחכ\"א מאחת על הכל","אמר רבה בר בר חנה א\"ר יוחנן עולשין שזרען מתחילה לבהמה ונמלך עליהן לאדם"],[[0,"רבי מאיר היא","דפסיל סומא באחת מעיניו לדון:"],[1,"שלא בסומין","אפילו סומא באחת מעיניו:"],[1,"דכתיב לכל מראה עיני הכהן","עד דאיכא כולו מראה:"],[1,"ומה ריבים שלא בקרובים","דנפקא לן מלא יומתו אבות על בנים (דברים כ״ד:ט״ז) אף נגעים אין כהן רואה נגע קרובו:"],[5,"וגומרין בלילה","אלמא לא מקשינן ריבים לנגעים דכתיב וביום הראות בו בשר וכי היכי דלענין לילה לא מקיש לענין סומא נמי לא מקיש:"],[6,"סתמא דרבים עדיף","ההיא דלעיל אוקמינן כר\"מ דיחיד הוא:"],[6,"דקתני לה גבי הלכתא דדיני","בסנהדרין דקא מיירי כולי מסכתא בדינין הילכך עיקר היא אבל הך לא תנן לה הכא גבי נדה אלא אגב גררא דנקט כיוצא בו:"],[7,"מתני' כל שחייב במעשרות מטמא טומאת אוכלין","דאין לך חייב במעשר אלא אוכל:"],[10,"גמ'","בפאה כתיב (ויקרא י״ט:ט׳) ובקוצרכם את קציר וגו' דומיא דקציר דמכניסו לקיום ואיכא כל הני:"],[10,"מכניסו לקיום","שאדם יכול לאוצרו:"],[11,"למעוטי ספיחי סטים וקוצה","דאין אוכל אלא מין צבע:"],[11,"סטים","קרו\"ג:"],[11,"קוצה","גויטר\"א. ולא ידענא אמאי נקט ספיחים וכמדומה לי שהראשונים ראויים לאכילה:"],[11,"תאנה","אינה מבשלה כאחד:"],[12,"ואילו לקיטתו כאחד","דממעט תאנה ומכניסו לקיום דממעט ירק:"],[12,"לא קתני","אלמא תאנה וירק חייבין במעשר מדרבנן דמדאורייתא לא מיחייב אלא דגן ותירוש ויצהר:"],[13,"שומים ובצלים","מכניסן לקיום לפיכך חייבים בפאה:"],[13,"מלבנות","שורות:"],[13,"מכל אחד ואחד","דירק הזרוע בין שורה לשורה מפסיק להו:"],[14,"עולשין","עשב ושמו קרישפל\"א:"]],[[0,"","ורבי מאיר היא. וא\"ת אמאי קאמר לאתויי סומא ופליג מתניתין אסתמא דסנהדרין (דף לב.) לימא לאתויי אוהב ושונא דכשרין להעיד ופסולין לדון כדאמר בפרק זה בורר (סנהדרין כז:) לרבנן דרבי יהודה וי\"ל דלא פסיקא ליה שהרי לכל העולם כשרין א\"נ מתניתין ע\"כ לא מיתוקמא כרבנן דהא קתני כל הכשר לדון כשר להעיד והרי סומא בשתי עיניו לרבנן דכשר לדון דהא לא מקשינן ריבים לנגעים ואילו להעיד פסול מאו ראה ואפילו במה שראה קודם שנסתמא פסול להעיד כדאמר ביש נוחלין (ב\"ב קכח.) היה יודע לו עדות קודם שנסתמא ונסתמא פסול וא\"ת בפרק חזקת הבתים (בבא בתרא דף מג.) דפריך וליסלקו בי תרי מינייהו ולידיינו הא בפ' יש נוחלין שהבאתי פוסל תחלתו בפסול וסופו בכשרות וכי תימא לדון כשר טפי והתנן כל הכשר לדון כשר להעיד וי\"ל דמתניתין מיירי בלהבא כל הכשר לדון להבא כשר להעיד מה שיראה מכאן ולהבא:"],[7,"","כל שחייב במעשר מטמא טומאת אוכלין. וא\"ת הא אמרינן בפ\"ק דחולין (דף ו.) אינו חושש לשאור ותבלין שבה לא משום מעשר ולא משום שביעית משמע דמעשר נוהג בתבלין וא\"כ מטמא טומאת אוכלין ובפרק העור והרוטב (חולין דף קיז:) תנן והקיפה מצטרפין לטומאת אוכלין ומפרש בגמרא (שם דף קכ.) מאי קיפה תבלין אלמא אין להם טומאת אוכלין אלא ע\"י צירוף וי\"ל דאיכא ב' מיני תבלין דהנהו דאין ראויין אלא לטעמא לא מטמו טומאת אוכלין ואין חייבין במעשר אבל תבלין דראויין נמי בפני עצמן ועבידן נמי לטעמא כגון שומים ובצלים חייבין במעשר ומטמאים טומאת אוכלין אי נמי ההיא דפ\"ק דחולין (דף ו.) לצדדין קתני ולא קאי מעשר אתבלין אלא אשאור גרידא ושביעית קאי אף אתבלין דאף במאכל בהמה נהגא כדתנן במס' שביעית עוד הקשה הרב ר\"ש מטוי\"ל דלקמן (נדה דף נא:) אמרינן דנמנו וגמרו דאין פלפלין מטמאין טומאת אוכלין ובפ' בכל מערבין (עירובין כח:) אמר זרע הגרגיר למאי חזי וקאמר שכן ראשונים שלא היה להם פלפלין היו שוחקין אותו ומטבילין בו את הצלי וכ\"ש דפלפלין מתעשרין מהאי טעמא וי\"ל דזרע גרגיר כי שוחקין אותו להטביל בו חזי אף בעינו אלא דאין רגילות לשוחקן כדי לאוכלן בלא טיבול לפי שע\"י טיבול עדיף טפי אבל פלפלין לאחר שנשחקו לא חזו בעינייהו אלא ע\"י טיבול:"],[11,"","ספיחי סטים. פי' בקונטרס דדוקא נקט ספיחים אבל תחלתן ראויין לאכילה אי נמי ספיחים ראויין יותר וס\"ד דחייב בפאה קמ\"ל:"],[11,"","וגידולו מן הארץ למעוטי כמהין ופטריות. בפרק כיצד מברכין (ברכות דף מ:) פריך והא תנן אם אמר כל גידולי קרקע עלי קונם אסור בכמהים ופטריות ומשני מירבא רבו מארעא מינק לא ינקי מארעא והא כל דבר שאין גידולו מן הארץ קתני תני וכל דבר שאין יונק מן הארץ א\"כ נמי בשמעתין צריך למיתני יונק מן הארץ:"],[11,"","למעוטי תאנה. תימה מאי שנא דתאנה וירק חייבין במעשר ופטורים מן הפאה דמן התורה אין נוהג פאה ומעשר אלא בדגן תירוש ויצהר בלבד ומאי שנא דחייבו חכמים טפי במעשר מבפאה ואומר ר\"ת משום דתאנה אין לקיטתה כאחד הלכך לא גזרו חכמים פאה בה שלא יצפו עניים מתי יגמור בעל הבית לקיטתו ויפסידו יותר במקום אחר ממה שירויחו בפאה זאת וירק נמי אין הפאה חשובה ואינה שוה כ\"א מעט ואם ימתינו אחריה עד הערב יפסידו יותר:"],[14,"","שזרען מתחלה לבהמה. משמע דסתמא לאדם קיימי או לתרוייהו ואפ\"ה כי זרען לבהמה פקע שם אוכל מינייהו אף על גב' דאמר (כריתות דף) כל המיוחד לאוכל אדם טמא עד שיפסל מלאכול לכלב דכיון שזרען לבהמה אין עליה שם אוכל ולא היה שני גידולים מעולם לאדם והא דאמר בהעור והרוטב (חולין קכח.) עולשין שלקטן והדיחם לבהמה ונמלך עליהן לאדם צריכות הכשר שני קשה כיון דסתמן לאדם משום דהדיחן לבהמה לא פקעי מינייהו שם אוכל שיפסל מלאכול לכלב ואמאי לא הוכשרו וי\"ל דמיירי שהיו מתחילה מיוחדים לבהמה אי נמי שמא אין הכשר מועיל אף באוכל אדם אי הוי הכשר לצורך בהמה:"]]],[["צריכות מחשבה לכשיתלשו קסבר מחשבת חבור לא שמה מחשבה","אמר רבא אף אנן נמי תנינא י\"ג דברים נאמרו בנבלת עוף טהור וזה אחד מהן צריכה מחשבה ואינה צריכה הכשר אלמא מחשבת חיים לא שמה מחשבה הכא נמי מחשבת חבור לא שמה מחשבה","רבי זירא אמר הכא בגוזל שנפל מן הרום עסקינן דלא הוה קמן דלחשוב עליה","א\"ל אביי תרנגולת שביבנה מאי איכא למימר א\"ל תרנגול ברא הוה","אחיכו עליה תרנגול ברא עוף טמא הוא ועוף טמא מי קמטמא אמר להו אביי גברא רבה אמר מילתא לא תחיכו עליה בתרנגולת שמרדה ומאי ברא דאיבראי ממרה","רב פפא אמר תרנגולתא דאגמא הואי רב פפא לטעמיה דאמר רב פפא תרנגול דאגמא אסור תרנגולתא דאגמא שריא","וסימניך עמוני ולא עמונית דרש מרימר תרנגולתא דאגמא אסירא חזיוה רבנן דדרסה ואכלה והיינו גירותא","ת\"ר גוזל שנפל לגת וחשב עליו להעלותו לכותי טמא לכלב טהור ר' יוחנן בן נורי אומר אף לכלב טמא","א\"ר יוחנן בן נורי ק\"ו אם מטמא טומאה חמורה שלא במחשבה לא יטמא טומאה קלה שלא במחשבה","אמרו לו לא אם אמרת בטומאה חמורה שכן אינה יורדת לכך תאמר בטומאה קלה שכן יורדת לכך","אמר להן תרנגולת שביבנה תוכיח שיורדת לכך וטמאוה שלא במחשבה אמרו לו משם ראיה כותים היו שם וחשבו עליה לאכילה","במאי עסקינן אילימא בכרכים למה לה מחשבה והתנן נבלת בהמה טהורה בכל מקום ונבלת עוף טהור והחלב בכרכים אין צריכין לא מחשבה ולא הכשר","אלא בכפרים ומי איכא למ\"ד דלא בעיא מחשבה והתנן נבלת בהמה טמאה בכל מקום ונבלת עוף טהור בכפרים צריכה מחשבה ואינה צריכה הכשר","א\"ר זעירא בר חנינא לעולם בכרך וגתו מאסתו ועשאתו ככפר","א\"ר יוחנן בן נורי קל וחומר אם מטמאה טומאה חמורה שלא במחשבה לא תטמא טומאה קלה שלא במחשבה","אמרו לו לא אם אמרת בטומאה חמורה שכן אינה יורדת לכך","מאי אינה יורדת לכך אמר רבא הכי קאמרי ליה לא אם אמרת"],[[0,"צריכות מחשבה","לאכילה ושוב תטמא טומאת אוכלין שיחשב עליהן לאחר תלישתן לאוכלן ואע\"ג דכבר חשב בחבורן שהרי נמלך עליהן לאדם:"],[1,"צריכות מחשבה","לאכילה ושוב תטמא מאיליה ותחזור ותטמא אוכלין במגע דהא מאיליה קודם מחשבה אין לה טומאה אלא בבית הבליעה:"],[1,"ואינה צריכה הכשר","כדיליף לקמן בשמעתין כל שסופו לטמא טומאה חמורה אין צריך הכשר לא שום הכשר ירידת טומאה לא הכשר מים ולא הכשר שרץ אלא מאיליה בלא שום נגיעה:"],[1,"אלמא מחשבת חיים","דהא מחיים סתמא לאכילה ואפ\"ה לא מהניא ההיא מחשבה לטומאה דבעינן מחשבה בשעה שראוי לקבל טומאה ומחיים לאו בר קבולי טומאה הוא:"],[1,"הכא נמי מחשבת חבור","הואיל ומחובר לאו בר קבולי טומאה לא שמה מחשבה:"],[2,"מן הרום","עוף הבר פורח באויר דלא הוה קמן מחיים דליחשביה:"],[3,"תרנגולת שביבנה","דאמרינן לקמן כותים היו שם וחשבו עליה והא תרנגולת עוף מזומן הוה והויא קמן מחיים ואפילו הכי בעי מחשבה לטומאת מגע:"],[4,"עוף טמא מי מטמא","בבית הבליעה והא קיימא לן (חולין דף ק:) מי שאיסורו משום בל תאכל נבלה יצא זה שאיסורו משום בל תאכל טמא לא ותרנגולת שביבנה מטמיא בבית הבליעה הואי מדקא מייתי לה רבי יוחנן בן נורי לקמן סייעתא למילתיה דפליג בגוזל שנפלה בגת אלמא דומיא דגוזל הוא:"],[4,"שמרדה","שברחה ונעשית מדברית לאדוניה ושם גדלה אפרוחין ומהן נפל אחד כאן דלא היתה בו מחשבה מעולם:"],[4,"ומאי ברא","דקאמר לכו:"],[4,"דאיבראי ממרה","הנעשה מדברית לאדוניה:"],[5,"תרנגולתא","נקבה דאגמא הואי דההוא עוף טהור הוא אליבא דרב פפא:"],[6,"חזיוה רבנן דדרסה","מקבלת ברגליה מה שאוכלת. ואני אומר שדורסת על מאכלה ברגליה לאחוז שלא יבא כולו לפיה ואין עוף טהור עושה כן:"],[6,"והיינו גירותא","דקיימא לן גירותא עוף טמא הוא דאמר בפרק כל הבשר (חולין דף קט:) כל מה דאסר לן רחמנא שרא לן לקבליה אסר לן דמא שרא לן כבדא אסר לן גירותא שרא לן לישנא דכוורא:"],[7,"גוזל","טהור:"],[7,"שנפל לגת","ומת:"],[7,"וחשב עליו להעלותו לכותי","להאכילו:"],[7,"טמא","טומאת אוכלין ומטמא אוכלין אחרים במגע דמעצמו באה עליו טומאה משחשב עליו כדיליף לקמן הואיל וסופו מטמא אדם כגון האוכלו מטמא בגדים בבית הבליעה לענין טומאה קלה נמי לא בעי הכשר מים ולא הכשר נגיעת שרץ. הכשר היינו דבר שמכשירו לטומאה כגון שרץ ומים:"],[7,"אף לכלב טמא","טומאת אוכלין ולאו משום דאכילת כלב מחשבה היא אלא לר' יוחנן בן נורי לא בעי מחשבה:"],[8,"טומאה חמורה","כגון האוכלה מטמא בגדים בבית הבליעה ואפילו לא חשב עליו כגון שלא ידע שזה הוא:"],[8,"טומאה קלה","אוכלין ומשקין:"],[9,"אינה יורדת לכך","אינה יורדת לדין מחשבה. ולקמן מפרש מה היא:"],[10,"תרנגולת שביבנה תוכיח","שמתה תרנגולת ביבנה ובא מעשה לפני חכמים וטמאוה שלא במחשבה ואף על פי שיורדת לכך כלומר דלטומאה קלה טמאוה שלא במחשבה ובטומאה קלה אמרת יורדת לכך:"],[11,"בכל מקום","ואפילו בכפרים דליכא אוכלין מרובין סתמא לאכילה:"],[11,"ונבלת עוף טהור בכרכים","דאיכא עם רב ואוכלין הכל וכן חלב בהמה דכרכים אין צריכין מחשבה אבל בכפרים בעי מחשבה:"],[12,"נבלת בהמה טמאה בכל מקום","סתמא לאו לאכילה הלכך בעיא מחשבה. ונהי דאי איכא כזית בלא מחשבה מטמיא אפילו אדם וכלים וכל שכן אוכלין ומשקין אלא להכי מהניא מחשבתה דאי איכא פחות מכביצה שאר אוכלין ופחות מכזית נבלה משלים לכביצה אי חשיב ליה מצטרפא בהדייהו ומקבלת טומאה במגע שרץ ואי לא לא:"],[12,"ואינה צריכה הכשר","דסופה לטמא טומאה חמורה:"],[13,"לעולם בכרך","והיינו טעמא דלרבנן בעיא מחשבה דגת שנפל לתוכה מאסתו ואינו הגון לאכילה כל כך:"]],[[1,"","מחשבת חיים לא שמה מחשבה. דמחיים לא חשב לאוכלה עד אחר שחיטה והרי מתה אבל אי שמה מחשבה לא פקע שם אוכל מינה במה שנתבטלה עד שתפסד מאכילת כלב:"],[5,"","תרנגולתא דאגמא. הזכר אסור לפי שאין לו סימני טהרה ולא שרי מטעם כל היוצא מן הטהור טהור שהרי האם לא ילדה האפרוח אלא ביצים הטילה והאפרוח מעפרא קא גדיל ונאסר ממילא ע\"י סימני טומאה ונקבה נמי אין לאוסרה למאן דאסר זה וזה גורם דהא אפרוח לא יצא אלא מן הביצה ומעפרא קגדיל כדפרישית ומיהו נראה עיקר ששני מינים הן והמין שקורין תרנגולתא דאגמא שרי הזכר והנקבה דיש להן סימני טהרה והמין שקורין תרנגול דאגמא אסור הזכר והנקבה דאין נראה שמין אחד חלוק הזכר מהנקבה ועוד כיון דלא הוי מעופות טמאין הכתובין דבהנהו בכל מין יש זכר ונקבה משום סימני טומאה אין לאסור עד שיהא בו כל ד' סימנים דמנשר ילפינן:"],[12,"","אלא בכפרים. תימה דע\"כ רבי יוחנן בן נורי לא בעי מחשבה אפילו בכפרים מדעביד ק\"ו וא\"כ מאי פריך ויש לומר דה\"פ [אלא] בכפרים ומי איכא כו' וא\"כ בלא נפל לגת נמי לרבנן צריך מחשבה ואע\"ג דמקשה אסיק אדעתיה הא דנקט נפל לגת מכל מקום פריך מעיקרא אילימא בכרכים כו' דסבר דמחמת נפילה לגת לא מימאס כולי האי עד שיעשה ככפר עד דמשני רבי זירא:"],[12,"","\u0003ל\"ג\u0004 גבי כפרים והחלב דחלב דמאי אי דבהמה טהורה וצריכה מחשבה בכפרים דאין דרך לאכול חלב אם כן אמאי אין צריך הכשר דחלב נבלת בהמה טהורה אין סופה לטמא טומאה חמורה כדאמרינן בכל שעה (פסחים כג.) מחלב נבלה וחלב טרפה יעשה לכל מלאכה ואי בחלב שחוטה הא דם שחיטה לא מכשר כיון דקאמר צריך מחשבה וליכא אכתי שם אוכל עליו עד שחישב דהכשר אינו מועיל עד שיהא אוכל כדאמר בהעור והרוטב (חולין קכח.) גבי עולשין שהדיחן לבהמה ובחלב בהמה טמאה פשיטא דחלב צריך מחשבה דמ\"ש מבשרה וגבי כרכים גרסינן ליה ומיירי בחלב שחוטה דכיון דאין צריך מחשבה הוי אוכל ומתכשר בדם שחיטה:"]]],[["בטומאה חמורה שכן אינה עושה כיוצא בה תאמר בטומאה קלה שעושה כיוצא בה","אמר ליה אביי כל דכן הוא ומה טומאה חמורה דקילא דאינה עושה כיוצא בה מטמאה שלא במחשבה טומאה קלה דחמירא דעושה כיוצא בה אינו דין שמטמאה שלא במחשבה","אלא אמר רב ששת הכי קאמר לא אם אמרת בטומאה חמורה שכן אינה צריכה הכשר תאמר בטומאה קלה שצריכה הכשר","ומי צריכה הכשר והתנן שלשה דברים נאמרו בנבלת עוף טהור צריכה מחשבה ואינה מטמאה אלא בבית הבליעה ואינה צריכה הכשר","נהי דהכשר שרץ לא בעיא הכשר מים בעיא","מאי שנא הכשר שרץ דלא בעיא כדתנא דבי רבי ישמעאל הכשר מים נמי לא תבעי כדתנא דבי רבי ישמעאל","דתנא דבי רבי ישמעאל (ויקרא יא, לז) על כל זרע זרוע אשר יזרע","מה זרעים שאין סופן לטמא טומאה חמורה צריכין הכשר אף כל שאין סופן לטמא טומאה חמורה צריכין הכשר יצתה נבלת עוף טהור שסופה לטמא טומאה חמורה שאין צריך הכשר","אלא אמר רבא ואיתימא רב פפא שום טומאה חמורה בעולם שום טומאה קלה בעולם","אמר רבא ומודה רבי יוחנן לענין מעשר דמחשבת חיבור שמה מחשבה אמר רבא מנא אמינא לה דתנן הסיאה והאזוב והקורנית שבחצר אם היו נשמרין חייבין","היכי דמי אילימא דזרעינהו מתחלה לאדם צריכא למימר אלא לאו דזרעינהו מתחלה לבהמה וקתני אם היו נשמרין חייבין","אמר רב אשי הכא בחצר שעלו מאיליהן עסקינן וסתמא לאדם קיימי והכי קאמר אם החצר משמרת פירותיה חייבין ואם לאו פטורין","מתיב רב אשי כל שחייבין במעשרות מטמאין טומאת אוכלין ואם איתא הא איכא הני דקחייבין במעשר ואין מטמאין טומאת אוכלין","אמר רבא הכי קאמר כל מין שחייב במעשר מטמא טומאת אוכלין","ה\"נ מסתברא מדקתני סיפא כל שחייב בראשית הגז חייב במתנות ויש שחייב במתנות ואין חייב בראשית הגז","ואם איתא האיכא טרפה דחייבת בראשית הגז ואינה חייבת במתנות","אמר רבינא הא מני רבי שמעון היא דתנן ר\"ש פוטר את הטרפה מראשית הגז","אמר רב שימי בר אשי תא שמע המפקיר את כרמו והשכים בבקר ובצרו חייב בפרט ובעוללות ובשכחה ובפאה ופטור מן המעשר","והא אנן תנן כל שחייב בפאה חייב במעשרות אלא לאו שמע מינה מין קתני שמע מינה","תנן התם מודים חכמים לר' עקיבא בזורע שבת או חרדל בשנים ושלשה מקומות שנותן פאה מכל אחד ואחד"],[[0,"טומאה חמורה אינה עושה כיוצא בה","מאחר שמטמאה נבלה את האדם אין אותו אדם חוזר ומטמא אדם שאין מטמא אדם אלא אב הטומאה אבל אוכל חוזר ומטמא אוכל מדרבנן:"],[4,"הכשר שרץ","שיכשירו שרץ להביאו לידי טומאה:"],[7,"שאין סופן לטמא טומאה חמורה","אין לך אוכל מטמא אדם:"],[8,"שום טומאה חמורה שום טומאה קלה","לא אם אמרת בטומאה חמורה דין הוא שמטמא בלא מחשבה שלא מצינו שום טומאה ששמה טומאה חמורה שתהא צריכה הכשר תאמר בטומאה קלה דאוכלין שאע\"פ שזו אינה צריכה הכשר הרי כל אוכלין יש עליהם שום טומאה קלה וצריכין הכשר הלכך הכא נמי בעיא מחשבה:"],[9,"לענין מעשר","דהואיל ונמלך עליהן לאדם הויא מחשבה וחייבין במעשר:"],[9,"הסיאה","פוליו\"ל:"],[9,"והקורנית","שדריא\"ה:"],[9,"נשמרין","ס\"ד אם היו נשמרין לאכילת אדם:"],[10,"אלא לאו דזרען לבהמה וקתני","אם חזר ושמרן לאדם חייבין:"],[11,"לאדם קיימי","וכיון דסתמייהו לאדם מאי אם היו נשמרין הכי קאמר אם החצר משמרת פירותיה דלא הוי הפקר חייבין:"],[12,"מתיב רב אשי","לרבא:"],[12,"ואם איתא","דלענין מעשר הויא מחשבה הא איכא עולשין שזרען לבהמה ונמלך עליהם לאדם דחייבין במעשר ואינן מטמאין דהא לענין טומאה אמרת לאו מחשבה היא:"],[14,"ראשית הגז","הגוזז צאנו חייב ליתן בכל שנה מן הגז מעט לכהן ובשחיטת חולין מפרש שיעורא:"],[14,"במתנות","זרוע לחיים והקיבה:"],[14,"ויש שחייב במתנות","כגון בקר ואינו חייב בראשית הגז:"],[17,"ת\"ש","דמין קתני במתני':"],[17,"ופטור מן המעשר","דהפקר פטור מן המעשר. ובפרט ובפאה להכי מחייב כדאמרינן בהגוזל בבבא קמא משום תעזוב יתירתא דכתיב במשנה תורה לא תפאר אחריך ואמר מר (חולין דף קלא.) לא תטול תפארתו ממנו והיינו פאה ודרשינן בספרי אחריך זו שכחה וכתיב לגר ליתום ולאלמנה יהיה וכתיב בתריה כי תבצור כרמך לא תעולל אחריך לגר ליתום ולאלמנה יהיה הרי פאה ושכחה ועוללות ל\"ל למהדר ומכתב בפרשה קדושים בכולהו לעני ולגר תעזוב אותם לרבות הפקר כי האי גוונא אבל הפקר גמור פטור מכולם כדתנן לעיל ונשמר פרט להפקר:"],[19,"תנן התם כו'","האי דנקט לה הכא משום דאותיב עלה ממתני' ודר' יוחנן נמי עולשין שזרען כו' משום דאותיב עליה ממתני' נקט לה הכא:"],[19,"מודים חכמים לרבי עקיבא","אע\"פ דפליגי במנמר שדהו ושייר קלחים לחים. מנמר טיי\"ר בלע\"ז שמלקט כאן את המבושלים כל צרכן ומניח את הלחים שלא בשלו וחוזר ומלקט במקום אחר דהוה ליה מנומר. וקאמר ר' עקיבא כשהוא חוזר ולוקט נותן פאה מכל אחד ואחד שהקציר שבינתים מפסיק וחכמים אומרים פאה מאחת על הכל ומודים חכמים לרבי עקיבא בזורע שבת או חרדל כו'. להכי נקט הני שאין דרכן לעשות מהן ערוגה אלא זורען לתבלין בעלמא בשנים ושלשה מקומות. שבת אני\"ט:"]],[[8,"","שום טומאה חמורה בעולם כו'. תימה דיפרש הא דקתני דאינה יורדת לכך המחשבה גופה דלא מצינו טומאה חמורה שצריכה מחשבה בשום מקום דהא דאמרינן דנבלת בהמה ועוף טהור צריכין מחשבה היינו לטומאת אוכלין לצרף פחות מכזית ופחות מכביצה אוכלין אבל כזית מהם מטמא אדם וכלים בלא מחשבה כדפרישית אבל טומאה קלה צריכה מחשבה בעלמא ומיהו נבלה נמי בעינן שתהא ראויה לגר לבר פדא:"],[10,"","אלא דזרעינהו לבהמה. והא דנקט שבחצר לפי מאי דמסיק שעלו מאיליהן אתי שפיר משום דבחצר אין דרך לזרוע אלא בגינה ועוד דבחצר סתמא לאדם לפי שרואה ויודע מתי ללוקטן עד שלא יתקשו ולפי מאי דס\"ד השתא יש לפרש דנקט חצר לפי שדרך התנא למנקט חצר דגם בשאר דבר תני חצר דקתני התם תאנה עומדת בחצר אוכל אחת מהן ופטור ואם צירף חייב גפן נטוע בחצר כקורנית שבחצר שהחצר קובעת בדבר שנגמרה מלאכתו אם צירף או בלא צירוף כהנהו שאין רגילין לעשות מהן גורן והא דתנן פ\"ח דשביעית [מ\"א] כל שאינו מיוחד לא לאוכל אדם ולא לאוכל בהמה חישב עליו לאוכל אדם ולאוכל בהמה נותנין חומרי אדם וחומרי בהמה כגון האזוב והקורנית לא קשה אהא דאמרינן בשמעתין דסתמיה לאדם דהיינו דוקא בחצר כדפרישית לעיל:"],[18,"","מין קתני ש\"מ. וא\"ת בריש הגוזל קמא (ב\"ק צד.) קאמר אביי דלר' ישמעאל שינוי אין קונה דקאמרי רבנן לא הפריש פאה מן הקמה יפריש מן העמרים או מן הכרי ולא מן העיסה ולר\"ש אף מן העיסה ודחי רבא בעלמא שינוי קונה והכא משום תעזוב יתירא ואביי תעזוב יתירא למפקיר כרמו אם כן לרבא מפקיר כרמו פטור מן הפאה לר\"ש וא\"כ היכי מוכח הכא דמין קתני דילמא מתני' דקתני כל שחייב בפאה חייב במעשר ר\"ש היא וי\"ל דלרבא נמי תעזוב יתירא למפקיר כרמו ותרתי ש\"מ דהא אביי נמי דדריש ליה בהגוזל קמא (שם צד.) למפקיר כרמו לכ\"ע דריש לה בפ\"ק דתמורה (דף ו.) למילתא אחריתי דקאמר התם אביי כל דאמר רחמנא לא תעביד אי עביד מהני ליה מותיב רבא והרי פאה דאמר רחמנא לא תכלה ואמרינן דאם לא הפריש מן הקמה יפריש מן העומרין או מן הכרי לרבנן או אף מן העיסה לר\"ש אלמא דלא מהני ומשני אביי התם משום תעזוב יתירא ורבא תעזוב יתירא למפקיר כרמו והשתא בין אביי ובין רבא דרשי תעזוב למפקיר כרמו ואביי דסבר דבעלמא אי עביד מהני דריש נמי מתעזוב דיפריש מן העומרים או מן הכרי או מעיסה לר\"ש דלא נימא אי עביד מהני אבל אי בעלמא שינוי קונה לר\"ש כמו בגזל אין סברא להעמיד תעזוב שיפריש מן העיסה אלא דדוקא מעמרים או מהכרי ורבא סבר דתעזוב למפקיר כרמו ולר' שמעון שיפריש מן העיסה אע\"ג דבעלמא שינוי קונה אבל להפריש מן העומרים או מן הכרי לא צריך קרא דבעלמא נמי כל דאמר רחמנא לא תעביד אי עביד לא מהני לרבא:"]]],[["והא שבת דמיחייב בפאה ומיחייב במעשר דתנן כל שחייב בפאה חייב במעשר","ומדחייב במעשר מטמא טומאת אוכלין אלמא כל מילי דעביד לטעמא מטמא טומאת אוכלין דהאי שבת לטעמא עבידא","ורמינהי הקושט והחימום וראשי בשמים והתיאה והחלתית והפלפלים וחלת חריע נקחין בכסף מעשר ואין מטמאין טומאת אוכלין דברי רבי עקיבא","אמר לו רבי יוחנן בן נורי אם נקחין בכסף מעשר מפני מה אין מטמאין טומאת אוכלין ואם אינן מטמאין אף הם לא ילקחו בכסף מעשר","וא\"ר יוחנן בן נורי נמנו וגמרו שאין נקחין בכסף מעשר ואין מטמאין טומאת אוכלין","אמר רב חסדא כי תניא ההיא בשבת העשויה לכמך","אמר רב אשי אמריתה לשמעתי' קמיה דרב כהנא (אמר) לא תימא בשבת העשויה לכמך הא סתמא לקדרה אלא סתם שבת לכמך עשויה דתנן השבת משנתנה טעם בקדרה אין בה משום תרומה ואינה מטמאה טומאת אוכלין","הא עד שלא נתנה טעם בקדרה יש בה משום תרומה ומטמאה טומאת אוכלין ואי ס\"ד סתמא לקדרה כי לא נתנה נמי סתמא לקדרה אלא לאו ש\"מ סתמא לכמך עשויה ש\"מ","\u0001מתני׳\u0002 כל שחייב בראשית הגז חייב במתנות ויש שחייב במתנות ואינו חייב בראשית הגז","כל שיש לו ביעור יש לו שביעית ויש שיש לו שביעית ואין לו ביעור","\u0001גמ׳\u0002 כגון עלה הלוף שוטה והדנדנה יש שיש לו שביעית ואין לו ביעור עיקר הלוף שוטה ועיקר הדנדנה","דכתיב (ויקרא כה, ז) ולבהמתך ולחיה אשר בארצך תהיה כל תבואתה לאכול כל זמן שחיה אוכלת מן השדה אתה מאכיל לבהמתך בבית כלה לחיה מן השדה כלה לבהמתך שבבית והני לא כלו להו","\u0001מתני׳\u0002 כל שיש לו קשקשת יש לו סנפיר ויש שיש לו סנפיר ואין לו קשקשת כל שיש לו קרנים יש לו טלפים ויש שיש לו טלפים ואין לו קרנים","\u0001גמ׳\u0002 כל שיש לו קשקשת דג טהור יש שיש לו סנפיר ואין לו קשקשת דג טמא מכדי אנן אקשקשת סמכינן סנפיר דכתב רחמנא למה לי","אי לא כתב רחמנא סנפיר הוה אמינא מאי קשקשת דכתיב סנפיר ואפילו דג טמא כתב רחמנא סנפיר וקשקשת","והשתא דכתב רחמנא סנפיר וקשקשת מנלן דקשקשת לבושא הוא דכתיב (שמואל א יז, ה) ושריון קשקשים הוא לבוש","ולכתוב רחמנא קשקשת ולא בעי סנפיר א\"ר אבהו וכן תנא דבי רבי ישמעאל (ישעיהו מב, כא) יגדיל תורה ויאדיר","\u0001מתני׳\u0002 כל הטעון ברכה לאחריו טעון ברכה לפניו ויש שטעון ברכה לפניו ואין טעון ברכה לאחריו","\u0001גמ׳\u0002 לאתויי מאי לאתויי ירק ולרבי יצחק דמברך אירק לאתויי מאי לאתויי מיא","ולרב פפא דמברך אמיא לאתויי מאי לאתויי מצות ולבני מערבא דמברכי בתר דסליקו תפילייהו אשר קדשנו במצותיו וצונו לשמור חוקיו לאתויי מאי לאתויי"],[[0,"והא שבת וכו'","לאו קושיא היא אלא מילתיה דייק ואזיל:"],[1,"לטעמא","למתק הקדרה:"],[2,"והחימום","פיטרטר\"א:"],[2,"והתיאה","היינו סאה:"],[2,"חלת חריע","קרו\"ג והוא כרכום:"],[3,"אף הם לא ילקחו בכסף מעשר","דרחמנא אמר ונתת הכסף וגו' ואכלת לפני וגו' והני לדידן לאו אוכל נינהו:"],[4,"נמנו וגמרו כו'","אלמא כל מידי דלא עביד לאוכלו אלא להטעים הקדירה לא מטמא דהא פלפלין וכרכום לטעמא עבידי:"],[5,"לכמך","דכותשין אותו ונותנין אותו בכותח ועיקרו שבתוכו מטבילין כל אוכל דהאי לאו לטעמא עביד דהוה עיקר:"],[6,"אמריתה לשמעתא כו'","הך שמעתא דפרישית לקמיה לא תימא כו':"],[6,"העשויה","שהצניעה לכך הא סתמא לקדרה ולא מטמא:"],[6,"אלא סתם שבת לכמך","ומטמא:"],[6,"דתנן השבת","סתם שבת משמע:"],[6,"אין בה משום תרומה","שאם חזר הקלח ונפל לתוך קדרה של חולין אינו מדמע:"],[7,"כי לא נתנה נמי סתמא לקדרה","ואמאי מטמאה הא אמרינן לעיל דמידי דעביד לטעמא לא מטמא:"],[9,"מתני' כל שיש לו ביעור","שהוא מצווה לבערו מן הבית בשביעית כשכלה לחיה מן השדה:"],[9,"יש לו שביעית","לענין שחייב להפקיר ואסור לעשותן סחורה ומלוגמא ואפיקטויזין:"],[9,"ויש","שנוהגת בו קדושת שביעית ואין לו ביעור כדמפרש בגמרא עיקר הלוף והדנדנה שאין כלים מן השדה בימות הגשמים:"],[10,"גמ' לוף שוטה","שם לווי הוא ועשבים הם:"],[10,"עלה הלוף שוטה והדנדנה","וה\"ה לכל הכלים בימות הגשמים מהשדה אלא הא דנקט הני משום דסיפא דמתניתין מיתוקמא בעיקרין ואשמועינן חילוף בין עיקרן לעליהן:"],[12,"מתני' קשקשת","מלבושין של דג:"],[12,"סנפיר","אלו כנפים ששט בהן על פני המים:"],[12,"יש לו טלפים","פרסותיו סדוקות שאין קרנים אלא לבהמה ולחיה טהורה:"],[12,"ויש שיש לו טלפים","כגון חזיר ואין לו קרנים:"],[13,"גמ' דג טמא","איכא דיש לו סנפיר:"],[13,"אקשקשת סמכינן","דהאמרת כל שיש לו קשקשת:"],[14,"ה\"א מאי קשקשת דכתב רחמנא היינו סנפיר","כנפים שפורח בהן מכי אית ביה כנפים שרי ואתי למישרי דג טמא ולהכי כתב תרוייהו דעל כרחך חד מינייהו לבושא הוא. אייקררי\"ץ בלע\"ז:"],[15,"ופרכינן והשתא דכתיבי תרוייהו מנלן דקשקשת לבושא הוא","דקתני כל שיש לו קשקשת יש לו סנפיר אלמא פשיטא לן מאי קשקשת ודאי מהאי קרא נפקא ושריון קשקשים הוא לבוש אלמא לבושא מיקרי וכיון דמהאי קרא נפקא לן השתא לא לכתוב סנפיר ולכתוב קשקשת דהא ליכא למימר הוה אמינא מאי קשקשת סנפיר:"],[18,"דמברך אירקא","לאחריו בורא נפשות רבות כי היכי דמברכינן אכל מיני מאכל ועל כל פרי העץ חוץ משבעת המינים דבעינן ברכה אחת מעין ג':"],[19,"מצות","ציצית ולולב ושאר מצות שמברכין עליהן עובר לעשייתן:"]],[[0,"","והא שבת מדחייב בפאה חייב נמי במעשר. הוי מצי לאתויי הא דתנא במס' (שביעית) (פ\"ד) ומייתי לה בפ\"ק דמסכת ע\"ז (דף ז:) השבת מתעשר זרע וירק ובהדיא תנן ומייתי בסמוך דשבת משנתנה טעם בקדרה אינה מטמאה טומאת אוכלין הא עד שלא נתנה מטמאה אלא דניחא ליה למפרך דרבי עקיבא אדרבי עקיבא:"],[2,"","התיאה. פרש\"י דהיינו סיאה וקשה דלעיל אמר דסתמיה לאדם וחייב במעשר וא\"כ מטמא טומאת אוכלין והכא קאמר תיאה אין מטמא טומאת אוכלין וי\"ל דדוקא בחצר סתמייהו לאדם אי נמי ב' מינים הן:"],[3,"","אם נקח בכסף מעשר מפני מה אין מטמא טומאת אוכלים כו'. וא\"ת והא אמרינן בפרק בכל מערבין (עירובין כח:) קור נקח בכסף מעשר ואין מטמא טומאת אוכלין וי\"ל דקור נמי אם שלקו וטגנו מטמא טומאת אוכלין ולכך אף קודם שליקה נקח בכסף מעשר מידי דהוי אבהמה וחיה דנקחות בכסף מעשר לפי שראויין לשחוט אבל טומאת אוכלים אין להם מחיים והכא פריך שפיר אי נקחת בכסף מעשר לפי שראויה אחר תיקון לאכילה אם כן יטמא טומאת אוכלים מיד שהרי בקל יכול לתקנה ומעתה יש עליה שם אוכל ולא דמי לקור שמחוסר שליקה וטגון ואי אין מטמא טומאת אוכלין לפי שאחר התקון אינה ראויה בפני עצמה לאכילה אם כן גם לא יהו נקחות בכסף מעשר:"],[16,"","ולכתוב רחמנא קשקשת כו'. וא\"ת והיכי הוי ידעי מה קשקשת קודם שנכתב קרא דגלית ויש לומר דמקבלה הוה ידעינן דהכי נמי נגיחה לא ידעינן דהויא בקרן אלא מקרא דויעש לו צדקיהו בן כנענה קרני ברזל וגו' (ב\"ק דף ב:) וא\"ת ומנלן דבעינן תרוייהו אימא דטהור בחדא מינייהו או בהא או בהא עד שיפרט לך הכתוב יחדו וי\"ל דומיא דסימני בהמה בעינן מעלת גרה ומפרסת פרסה מדאסר רחמנא חזיר וגמל:"],[17,"","כל הטעון ברכה לאחריו טעון ברכה לפניו. וברכת טבילה דאמרינן בפ\"ק דפסחים (דף ז:) דמברך אחר טבילה התם נמי דינה להיות לפניה אלא משום דגברא דלא חזי הוא:"],[19,"","ולבני מערבא דמברכי כי מסלקין תפילייהו לשמור חוקיו. אומר ר\"ת דעל תפילין לבד הוו מברכי לשמור חוקיו דקרא (שמות יג) דושמרת את החוקה הזאת למועדה ס\"ל לבני מערבא דבתפילין כתיב כדאמר בירושלמי אבל ציצית כי קמסלק מעליו ליכא מאן דמברך ותפילין נמי דוקא כשמסלקן סמוך לשקיעת החמה שמחויב לסלקן כדאמר בהקומץ רבה (מנחות דף לו:) הניח תפילין לאחר שקיעת החמה עובר בעשה דכתיב ושמרת את החוקה והשמר דעשה עשה אבל ציצית אע\"ג דפטור בלילה ליכא איסור ואין חייב לסלקן ובשמעתין הוי מצי למימר לאתויי ציצית אלא דניחא למינקט ריחני משום דפסיקא דאכל ריחני אין מברך אחריהן ולדידן לא קי\"ל כבני מערבא ולא מברכין אחר תפילין לשמור חוקיו דבפרק הקומץ רבה (מנחות דף לו:) מוכח דלילה זמן תפילין הוא דהכי סבר רב אשי התם ומדרבנן הוא דאסור שלא ישן בהן וקרא דושמרת מוקמינן לה דבחוקת הפסח הכתוב מדבר ואף על גב דשבת לאו זמן תפילין הוא מכל מקום אין מברך עליהם כשמסלקן ע\"ש עם חשכה דאין חייב לסלקן דנפקא לן (שם) מלאות על ידך יצאו שבתות ויו\"ט שהן גופן אות:"]]],[["ריחני","\u0001מתני׳\u0002 תינוקת שהביאה שתי שערות או חולצת או מתיבמת וחייבת בכל מצות האמורות בתורה","וכן תינוק שהביא שתי שערות חייב בכל מצות האמורות בתורה וראוי להיות בן סורר ומורה משיביא שתי שערות עד שיקיף זקן","התחתון ולא העליון אלא שדברו חכמים בלשון נקיה","תינוקת שהביאה שתי שערות אינה יכולה למאן רבי יהודה אומר עד שירבה השחור","\u0001גמ׳\u0002 וכיון דתנן חייבת בכל מצות האמורות בתורה או חולצת או מתיבמת למה לי","לאפוקי מדרבי יוסי דאמר איש כתוב בפרשה אבל אשה בין גדולה ובין קטנה קמ\"ל דאי אייתי שתי שערות אין אי לא לא מאי טעמא אשה כאיש","וכיון דתנא וכן התינוק שהביא ב' שערות חייב בכל המצות האמורות בתורה ל\"ל","וכי תימא משום דקבעי למתני וראוי להיות בן סורר ומורה תנינא חדא זימנא אימתי הוא בן סורר ומורה משיביא שתי שערות ועד שיקיף זקן התחתון ולא העליון אלא שדברו חכמים בלשון נקיה","אין ה\"נ אלא איידי דפריש מילי דתינוקת קמפרש נמי מילי דתינוק","תינוקת שהביאה כו' א\"ר אבהו א\"ר אלעזר הלכה כרבי יהודה","ומודה רבי יהודה שאם נבעלה לאחר שהביאה שתי שערות שוב אינה יכולה למאן","חברוהי דרב כהנא סבור למעבד עובדא כרבי יהודה ואע\"ג דנבעלה","אמר להו רב כהנא לא כך היה מעשה בבתו של רבי ישמעאל שבאת לבית המדרש למאן ובנה מורכב לה על כתפה ואותו היום הוזכרו דבריו של רבי ישמעאל בבית המדרש ובכתה בכייה גדולה בבית המדרש","אמרו דבר שאמר אותו צדיק יכשל בו זרעו","דאמר רב יהודה אמר שמואל משום רבי ישמעאל (במדבר ה, יג) והיא לא נתפשה אסורה הא נתפשה מותרת ויש לך אחרת שאע\"פ שלא נתפשה מותרת ואיזו זו שקדושיה קדושי טעות שאע\"פ שבנה מורכב על כתפה ממאנת והולכת לה","ונמנו וגמרו עד מתי הבת ממאנת עד שתביא שתי שערות פרוש ולא עבוד עובדא","רבי יצחק ותלמידי דרבי חנינא עבוד עובדא כרבי יהודה ואע\"ג דנבעלה אזל רב שמן בר אבא אמרה קמיה דר' יוחנן אזל רבי יוחנן אמרה קמיה דרבי יהודה נשיאה שדר בלשא ואפקוה","אמר רב חסדא אמר מר עוקבא לא שירבה השחור ממש אלא כדי שיהיו שתי שערות שוכבות ונראות כמי שירבה השחור על הלבן רבא אמר שתי שערות המקיפות משפה לשפה","א\"ר חלבו אמר רב הונא שתי שערות שאמרו צריך שיהא בעיקרן גומות רב מלכיו אמר רב אדא בר אהבה גומות אע\"פ שאין שערות","אמר רב חנינא בריה דרב איקא שפוד שפחות וגומות רב מלכיו בלורית אפר מקלה וגבינה רב מלכיא","רב פפא אמר מתני' ומתניתא רב מלכיא שמעתתא רב מלכיו וסימנא מתניתא מלכתא","מאי בינייהו איכא בינייהו שפחות","אמר רב אשי אמר לי מר זוטרא קשה בה רבי חנינא מסורא לא לישתמיט תנא ואשמועי' גומות אי אשמועינן גומות ה\"א עד שיהו שתי שערות בשתי גומות קמ\"ל דאפילו שתי שערות בגומא אחת","ומי איכא כה\"ג והכתיב (איוב ט, יז) אשר בשערה ישופני והרבה פצעי חנם ואמר רבא איוב בסערה חירף בסערה השיבוהו בסערה חירף אמר לפניו רבש\"ע שמא רוח סערה עברה לפניך ונתחלפה לך בין איוב לאויב בסערה השיבוהו (איוב לח ) ויען ה' את"],[[0,"ריחני","מברכין עליהן בורא עצי בשמים ואין טעון ברכה לאחריו דהנאה מועטת היא:"],[2,"מתני' וראוי להיות בן סורר ומורה משיביא שתי שערות עד שיקיף זקן","אבל קודם ב' שערות לאו בר עונשין הוא ומשהקיף זקן ראוי להוליד ורחמנא אמר בן ולא הראוי להיות אב:"],[3,"התחתון ולא העליון","באיזו הקפת זקן אמרו בתחתון שלמטה ולא העליון:"],[4,"ה\"ג רבי יהודה אומר עד שירבה השחור ול\"ג על הלבן","כלומר שישחיר אותו מקום משערות הרבה:"],[6,"גמ' איש כתיב בפרשה","(דברים כ״ה:ז׳) ואם לא יחפוץ האיש הלכך קטן לא חליץ אבל אשה בין גדולה בין קטנה:"],[10,"הלכה כרבי יהודה","שאם לא בא עליה משהביאה שתי שערות שיכולה לעקור נישואי קטנותיה עד שירבה השחור:"],[11,"שוב אינה יכולה למאן","דהך ביאה הוו להו קדושין גמורין דגדולה היא ובידה לקדש עצמה וכי פליג כשלא בעל לאחר שגדלה פליג ואפ\"ה לר\"מ לא ממאנת דכיון שהגדילה שעה אחת ולא מיחתה שוב אינה יכולה למחות וחלו להו קדושין קמאי:"],[13,"בבתו של רבי ישמעאל","שהשיאתה אמה כשהיא קטנה יתומה ולאחר שילדה באת למאן:"],[15,"והיא","מיעוטא הוא והכי דריש היא אשה סתמא שקדושיה גמורין היא דכי לא נאנסה אסורה לבעלה ויש לך אחרת שאפילו זנתה שלא באונס מותרת לבעל ולבועל ואיזו זו שקידושיה קדושי טעות כגון ע\"מ שאני כהן והרי הוא ישראל וכגון קטנה דאין מעשיה כלום ואמה נמי אין בידה לקדשה:"],[15,"ואפילו בנה מורכב כו'","דלאו נישואין הוו לענין זנות נמי לא מיתסרה עליה דפנויה בעלמא היא ולא אמרינן בעילות שבעל משגדלה הוו קדושין דקסבר כל הבועל על דעת קדושין הראשונים הוא בועל ולא נתכוין לחזור ולקדשה:"],[17,"בלשא","חיל:"],[17,"ואפקוה","מבעלה האחרון שנשאה במיאון זה:"],[19,"שתי שערות שוכבות","שיהו ארוכות:"],[20,"שפחות","מתניתין היא בכתובות ואמר רב מלכיא עלה הלכה כר\"א:"],[20,"בלורית","מתניתין היא עובד כוכבים המסתפר מישראל כיון שהגיע לבלורית שומט את ידו ואמרינן וכמה ואמר רב מלכיא עלה ג' אצבעות לכל רוח:"],[20,"גבינה","נמי משנה היא באין מעמידין מפני מה אסרו גבינות העובדי כוכבים כו' ואמר רב מלכיא עלה מפני שמחליקין פניהן בשומן חזיר. כל הנך תלתא לא אתא רב מלכיא אלא לפרושי טעמא דמתניתין [או] שיעורא או לאוקמי הלכתא אבל גומות שפוד ואפר מקלה שמעתא דנפשיה היא ורב פפא מחליף שפחות לרב מלכיא ואפר מקלה לרב מלכיו:"],[23,"קשה בה רבי חנינא","אי סלקא דעתך גומות אף על פי שאין שערות לא לישתמיט בכוליה הש\"ס חד תנא ולאשמועי' תינוקת שהביאה שתים גומות:"]],[[15,"","קדושי טעות. הקשה ריב\"ן וכי לית ליה מתניתין דיבמות (דף ב:) ואי אתה יכול לומר בחמותו ואם חמותו שמיאנו וליכא למימר דמתני' דהתם בקדושי קטנות והכא איירי בקדושי טעות כדקתני בהדיא דרבי ישמעאל בקדושי קטנה נמי איירי שהרי בתו שבאת למאן הוו קדושי קטנות דמינה מייתי רב כהנא ראייה דאינה ממאנת אחר הבאת שערות וקאמר דבר שאמר אותו צדיק יכשל בו זרעו אלמא ר' ישמעאל בקדושי קטנות נמי איירי ואע\"ג דיש לפרש למה שאמר אותו צדיק היינו כעין דבר שאמר אותו צדיק שהוא אומר בקדושי טעות ובתו באת למאן מחמת קדושי קטנות מ\"מ מדקאמר נמנו וגמרו עד מתי הבת ממאנת עד שתביא ב' שערות משמע דנמנו וגמרו לאפוקי מדר' ישמעאל דליכא למימר לאפוקי מדרבי יהודה דהא רבי יהודה מודה בנבעלה וזאת נבעלה שהרי בנה מורכב על כתפה היה ושמואל דסבר כרבי ישמעאל ואמר בפרק המדיר (כתובות דף עב:) קדשה על תנאי וכנסה סתם אפילו בעל אינה צריכה הימנו גט וכי לית ליה לשמואל מתני' דיבמות (דף ב:) ובפ' המדיר (כתובות דף עג.) פריך לשמואל ממשניות טובא ומשני להו ולא בעי למימר דפליג אסתם משנה וי\"ל דר' ישמעאל לית ליה מתני' דיבמות ושמואל לא סבר כר' ישמעאל אלא בקדושי טעות אבל בקדושי קטנות לא סבר כוותיה אלא כמתני' דיבמות (דף ב:) ודמכילתין דתנן עד מתי הבת ממאנת עד שתביא ב' שערות ובפרק מי שמת (ב\"ב דף קנו.) קאמר שמואל בהדיא בודקין למיאונין לאפוקי מדרבי יהודה וכן מוכח נמי בפרק נושאין (יבמות דף ק:) דפריך ממאנת מי קא ילדה ומשני בקדושי טעות וכרבי ישמעאל משמע דוקא בקדושי טעות סבר כוותיה ולא בקדושי קטנות דאליבא דשמואל איירי התם והא דאמר שמואל בפ' ב\"ש (יבמות דף קט:) ובהמדיר (כתובות דף עג.) קטנה שלא מיאנה והגדילה ועמדה ונישאת צריכה גט משני משמע דאינה מקודשת לראשון מדצריכה גט משני היינו מן התורה אבל מדרבנן צריכה גט מראשון דמשהגדילה אינה יוצאה במיאון כדפרישית:"],[22,"","איכא בינייהו שפחות. וא\"ת לימא נמי איכא בינייהו אפר מקלה דהוי שמעתתא ותני לה בדרב מלכיא דרב פפא אמר שמעתא דרב מלכיו ויש לומר דה\"ק כולהו מתניתא רב מלכיא ושמעתתא יש מהן רב מלכיא ויש מהן רב מלכיו:"]]],[["איוב מן הסערה ויאמר אליו שוטה שבעולם הרבה נימין בראתי בראשו של אדם ולכל נימא ונימא בראתי לו גומא בפני עצמה שלא יהיו שתים יונקות מגומא אחת שאלמלא שתים יונקות מגומא אחת מכחיש מאור עיניו של אדם גומא בגומא לא נתחלף לי איוב באויב נתחלף לי","לא קשיא הא בגופא הא ברישא","אמר רב יהודה אמר שמואל שתי שערות שאמרו אפילו אחת על הכף ואחת על הביצים","תניא נמי הכי שתי שערות שאמרו אפילו אחת בגבה ואחת בכריסה אחת ע\"ג קשרי אצבעותיה של יד ואחת ע\"ג קשרי אצבעותיה של רגל דברי ר' שמעון בן יהודה איש כפר עכו שאמר משום רבי שמעון ורבנן אמר רב חסדא עד שיהו ב' שערות במקום אחד","ת\"ר עד מתי הבת ממאנת עד שתביא שתי שערות דברי רבי מאיר ר' יהודה אומר עד שירבה השחור רבי יוסי אומר עד שתקיף העטרה בן שלקות אומר עד שתכלכל","ואמר רבי שמעון מצאני חנינא בן חכינאי בצידן ואמר כשאתה מגיע אצל ר\"ע אמור לו עד מתי הבת ממאנת אם יאמר לך עד שתביא שתי שערות אמור לו והלא בן שלקות העיד במעמד כולכם ביבנה עד שתכלכל ולא אמרתם לו דבר","כשבאתי אצל רבי עקיבא אמר לי כלכול זה איני יודע מהו בן שלקות איני מכיר עד מתי הבת ממאנת עד שתביא ב' שערות","\u0001מתני׳\u0002 שתי שערות האמורות בפרה ובנגעים והאמורות בכל מקום כדי לכוף ראשן לעיקרן דברי רבי ישמעאל ר\"א אומר כדי לקרוץ בציפורן ר' עקיבא אומר כדי שיהו ניטלות בזוג","\u0001גמ׳\u0002 אמר רב חסדא אמר מר עוקבא הלכה כדברי כולן להחמיר","\u0001מתני׳\u0002 הרואה כתם הרי זו מקולקלת","וחוששת משום זוב דברי רבי מאיר וחכ\"א אין בכתמים משום זוב","\u0001גמ׳\u0002 מאן חכמים ר' חנינא בן אנטיגנוס היא דתניא ר\"ח בן אנטיגנוס אומר כתמים אין בהן משום זוב ופעמים שהכתמים מביאין לידי זיבה","כיצד לבשה ג' חלוקות הבדוקות לה ומצאה עליהם כתם או שראתה ב' ימים וחלוק אחד הן הן הכתמים המביאין לידי זיבה","השתא שלשה חלוקות דלאו מגופה קחזיא חיישינן ב' ימים וחלוק אחד מיבעיא","מהו דתימא כל כי האי גוונא מביאה קרבן ונאכל קא משמע לן","אמר רבא בהא זכנהו ר' חנינא בן אנטיגנוס לרבנן מאי שנא פחות מג' גריסין במקום אחד דלא חיישינן דאמרי' בתרי יומי חזיתיה שלשה גריסין במקום אחד נמי נימא תרתי ופלגא מגופה חזיתיה ואידך אגב זוהמא דם מאכולת הוא","ורבנן כיון דאיכא לפלוגי בגריס ועוד לכל יומא לא תלינן","ור\"ח בן אנטיגנוס ג' גריסין במקום א' הוא דלא חיישינן הא בג' מקומות חיישינן הא אמרת בג' חלוקות אין בג' מקומות לא","לדבריהם דרבנן קאמר להו לדידי בג' חלוקות אין בג' מקומות לא אלא לדידכו אודו לי מיהת דהיכא דחזאי ג' גריסין במקום אחד דאמרינן תרי ופלגא מגופה חזיתיה ואידך אגב זוהמא דם מאכולת הוא","ורבנן כיון דאיכא לפלוגי בגריס ועוד לכל יומא לא תלינן","ת\"ר הרואה כתם אם יש בו כדי לחלק ג' גריסין שהן כגריס ועוד חוששת ואם לאו אינה חוששת","ר' יהודה בן אגרא אומר משום רבי יוסי אחת זו ואחת זו חוששת"],[[0,"מן הסערה","כלומר משער הראש אני משיבך תשובה הרבה נימין בראתי באדם וכו':"],[2,"על הכף","גובה שעל האבר למטה מן הכרס:"],[2,"אפילו אחת על הכף כו'","אע\"ג דאינו במקום אחד:"],[3,"אחת בגבה","תחת אותו מקום:"],[3,"בין קשרי אצבעותיה","ואינה מביאה שער עד שתגדיל:"],[4,"שתכלכל","לא שמעתי מהו ונראה בעיני שחברו במס' שבת (עח:) כדי לסוך כלכול ואמרינן (שם פ:) מאי כלכול צדעה ובת צדעה ה\"נ עד שיהו שם שערות הרבה שיהא רצוף ומלובש בשער. ואני מצאתי עד שתבלבל בבי\"ת שער גדול כפוף ומבולבל ולא ישר בעיני:"],[6,"איני יודע מהו","כלומר לא סבירא לי:"],[7,"מתני' ב' שערות האמורות בפרה","דקיימא לן ב' שערות שחורות פוסלות בה בגמרא דאין מעמידין (ע\"ז דף כד.) ובמסכת פרה (פ\"ב מ\"ה):"],[7,"ובנגעים","שער לבן דקי\"ל בת\"כ מיעוט שערות שתים:"],[7,"והאמורות בכל מקום","בתינוק ובתינוקת:"],[7,"לקרוץ","לאחוז מעט:"],[7,"שיהו ניטלות בזוג","שיעורא רבה (דכולהו):"],[8,"גמ' להחמיר","משנקרצות בצפורן לא ממאנת שמא גדולה היא ולענין חליצה עד דאיכא שיעורא רבה דכולהו:"],[9,"מתני' הרי זו מקולקלת","אינה יודעת פתח נדותה לידע מתי יתחילו י\"א יום שבין נדה לנדה דהא לא ידעה אימת חזאי:"],[10,"וחוששת משום זוב","אם עברו עליה ג' ימי זיבה משלבשה חלוק זה ומצאה עליו כתם גדול שיעור ג' גריסין ועוד מספקינן להו דילמא כל חדא וחדא בחד יומא חזיא אע\"ג דבמקום אחד נמצאו:"],[12,"גמ' ג' חלוקות הבדוקות לה","ולבשתן בשלשת ימי זיבה אחד ליום:"],[12,"או שראתה ב' ימים","ראיה ממש מגופה בתוך י\"א יום ובשלישי לבשה חלוק הבדוק לה ומצאתה עליו כתם:"],[14,"מהו דתימא כל כי האי גוונא וכו'","להכי נקט ב' ימים וחלוק אחד לאשמועינן דהשתא נמי חששא בעלמא היא ומביאה קרבן ואינו נאכל דשמא לאו מגופה הואי הך כתם שלישי ומליקת חולין נבלה דאי לא אשמועינן הוה אמינא הרי רגלים לדבר דודאי זבה היא:"],[15,"זכנהו","תשובה ניצחת השיבן:"],[15,"אגב זוהמא","דנדות אתאי מאכולת ונתמעכה שם:"],[17,"ורבי חנינא כו'","לרבא פרכינן דאמר לרבי חנינא שלשה גריסין במקום אחד:"],[18,"תרי ופלגא כו'","אלמא לא פליג רבי חנינא אלא במקום אחד אבל בשלשה מקומות מודה והא קתני רבי חנינא לעיל לבשה ג' חלוקות כו' אבל בחלוק אחד בג' מקומות לא:"],[20,"שהן כגריס ועוד","כלומר שלשה גריסין גסין דאיכא בכל חד וחד כגריס ועוד דהכי הוי שיעור כתם לקמן בפרק הרואה כתם (נדה דף נט.):"],[21,"אחת זו ואחת זו","אפילו בשתי גריסין חוששין שמא ראתה אותן בשני בין השמשות או אחת היום ואחת בין השמשות של מחר וראיית בין השמשות עולה לשני ימים שמקצתה מן היום ומקצתה מן הלילה ויש כאן שלשה רצופין:"]],[[4,"","עד שתכלכל לשון גדול שער הוא כדאמר בריש נזיר (דף ב.) הריני מכלכל הרי זה נזיר וקאמר בגמרא מאי משמע דכלכול לישנא דגדול שער הוא דתניא אמר רבי יהודה סיד כדי לסוד כלכול קטן ואמר צדעה ובת צדעה:"],[8,"","הלכה כדברי כולן להחמיר. בפ' מי שמת (ב\"ב דף קנו.) אמר ר\"נ אמר שמואל בודקין לחליצה ולמיאונין לאפוקי מדרבי יהודה דאמר עד שירבה השחור על הלבן והתם פסק ככולהו דאמר התם ר\"נ אמר שמואל וה\"נ קאמר הלכה כדברי כולן להחמיר הלכך אינה חולצת עד שתביא שער גדול שבכולן ועד שיהו ב' שערות במקום אחד כרב אשי ואם יש לה דדים גדולים כשאר נשים אינה צריכה לבדוק התחתון ולא תמאן משהביאה שתי שערות קטנות ואפי' אחת בגבה ואחת בין קשרי אצבעותיה ור\"ת כתב בספר הישר דמשהגיעה לכלל שנותיה לא תמאן בזמן הזה דאע\"ג דהיכא דלא בעל פסקינן בפ' יוצא דופן (לעיל נדה דף מו.) דלא חיישינן שמא נשרו אין אנו בקיאין לבדוק בכל גופה שלא יהו לה שערות דאפי' אחת בגבה ואחת בכריסה ובקשרי אצבעותיה מצטרפים או גומות גרידא:"],[18,"","שלש גריסין נמי בתרי יומי תרתי ופלגא חזיתיה ואידך דם מאכולת הוא. תימה אמאי לא פריך דלמא כל ג' גריסין בתרי יומי חזיתיה כדקאמר בפחות מג' גריסין ונראה למהר\"ם וכן מצאתי דאי לא דתלינן בדם מאכולת ונימא דכל הכתם מגופה חזיתיה אין לנו להקל ולומר דבתרי יומי חזיתיה כיון דיש בו שיעור דאפשר לחלקו לג' ראיות לכך פריך דילמא תרי ופלגא בתרי יומי חזיתיה כיון דראתה מעט פחות מג' גריסין אע\"ג דאית בהו טפי משיעור שתי ראיות אתה מיקל לתלות המותר באותן ב' ראיות ולא בראייה ג' ה\"נ בג' גריסין וג' עודות נימא תרי ופלגא אע\"ג דהוה טפי מב' ראיות נימא דבתרי יומי חזיתיה והמותר נתלה בדם מאכולת וא\"ת מנא ליה לרבא דבג' גריסין במקום א' חיישי רבנן דילמא דוקא בג' מקומות ומצאתן ביום אחד ולר' חנינא דוקא בג' חלוקות או בחלוק א' ומצאתו בג' ימים וי\"ל דלא מפלגי רבנן:"]]],[["אמר רבי נראין דברי רבי יהודה בן אגרא בשלא בדקה ודברי חכמים בשבדקה","מאי בדקה ומאי לא בדקה אמר רבא אשכחתינהו לרבנן דבי רב דיתבי וקאמרי הכא במאי עסקינן כגון שבדקה עצמה ולא בדקה חלוקה ואף עצמה לא בדקה אלא בין השמשות דרבי יהודה ובבין השמשות דר' יוסי לא בדקה","דרבנן סברי בבין השמשות דרבי יוסי ליליא הוא והא בדקה בבין השמשות דרבי יהודה ור' יוסי לטעמיה דאמר בין השמשות ספיקא הוי","ואמינא להו אנא אילמלי ידיה בעיניה כל בין השמשות יפה אתם אומרים עכשיו שמא עם סלוק ידיה ראתה ואמרו לי כי קאמרינן כשנתנה ידיה בעיניה כל בין השמשות","אמר רבי נראין דברי רבי יהודה בן אגרא כשלא בדקה מאי לא בדקה","אילימא דבדקה בדרבי יהודה ולא בדקה בדרבי יוסי מכלל דרבי יהודה סבר אע\"ג דבדקה בתרוייהו חיישא הא בדקה","אלא פשיטא דלא בדקה לא בדרבי יהודה ולא בדרבי יוסי אבל בדקה בדר' יהודה ולא בדקה בדר' יוסי לא חיישא","אלמא בין השמשות דר' יוסי לרבי ליליא הוא אימא סיפא ודברי חכמים כשבדקה מאי בדקה","אילימא דבדקה בדרבי יהודה ולא בדקה בדרבי יוסי מכלל דרבנן סברי אע\"ג דלא בדקה בתרוייהו לא חיישינן הא לא בדקה","אלא פשיטא דבדקה בין בדר' יהודה ובין בדרבי יוסי אבל בדקה בדר' יהודה ולא בדקה בדר' יוסי חיישינן","אלמא בין השמשות דרבי יוסי לרבי ספקא הוי קשיא דרבי אדרבי","ה\"ק נראין דברי רבי יהודה בן אגרא לרבנן דלא בדקה כלל לא בדרבי יהודה ולא בדרבי יוסי שאף חכמים לא נחלקו עליו אלא דבדקה בדר' יהודה ולא בדקה בדר' יוסי אבל היכא דלא בדקה כלל מודו ליה","ורמינהו הרואה כתם לראיה מרובה חוששת לראיה מועטת אינה חוששת זו דברי רבי יהודה בן אגרא שאמר משום רבי יוסי","אמר רבי אני שמעתי ממנו שאחת זו ואחת זו חוששת ומן הטעם הזה אמר לי ומה אילו נדה שלא הפרישה בטהרה מן המנחה ולמעלה לא תהא בחזקת טמאה ונראין דבריו כשבדקה","מאי בדקה אילימא דבדקה בדר' יהודה ולא בדקה בדרבי יוסי מכלל דרבי יהודה בן אגרא סבר אע\"ג דלא בדקה לא בדר' יהודה ולא בדר' יוסי לא חיישא והא לא בדקה","אלא פשיטא דבדקה בין בדר' יהודה ובין בדרבי יוסי מכלל דרבי יהודה בן אגרא סבר בדקה בדר' יהודה ולא בדקה בדר' יוסי לא חיישא","אלמא בין השמשות דרבי יוסי לר' יהודה בן אגרא ליליא הוא קשיא דרבי יהודה בן אגרא אדר' יהודה בן אגרא","בשלמא בלא רבי לא קשיא התם דבדקה בדר' יהודה ולא בדקה בדר' יוסי הכא דבדקה נמי בדר' יהודה ובדר' יוסי אלא בדרבי קשיא","תרי תנאי ואליבא דרבי יהודה בן אגרא האי תנא סבר שלים בין השמשות דר' יהודה"],[[0,"א\"ר נראין כו'","כולה מפרש לה:"],[1,"הכא במאי עסקינן","פלוגתא דרבנן ורבי יהודה בן אגרא:"],[1,"כשבדקה עצמה","כל שני בין השמשות:"],[1,"ולא בדקה חלוקה","בשני ימים אלא בג' ומצאה ב' גריסין ולפי שלא בדקה חלוקה עד הנה לא ידעה מאימת הן באין לפיכך יש לחוש שמא בשני בין השמשות ראתה או אחת ביום ראשון ואחת בין השמשות של מחר דהוו להו ג' ראיות:"],[1,"בין השמשות דרבי יהודה","בבמה מדליקין הכסיף העליון ולא הכסיף התחתון ושיעורו חצי מיל ולר' יוסי כהרף עין ובסוף היום הוא זה נכנס וזה יוצא:"],[2,"והא בדקה בבין השמשות דרבי יהודה","הלכך לא ראתה אחת מהן בין השמשות שתעלה לחומר ב' ימים:"],[2,"ספקא הוא","דחיישינן שמא לאחר סילוק ידיה בבין השמשות דרבי יוסי חזאי והוא עולה לשני ימים והוו להו שלשה ימים רצופים ולרבנן לילה הוא ואפילו חזאי לא הוו להו שלשה ראיות:"],[3,"אילמלי ידיה בעיניה","באותו מקום:"],[3,"כל בין השמשות","דרבי יהודה:"],[3,"יפה אתם אומרים","לרבנן דלא חיישי כיון דכל בין השמשות דר' יהודה לא חזאי:"],[3,"אימור עם סילוק ידיה ראתה","דהא בין השמשות דרבי יהודה ארוך הוא:"],[4,"נראין דברי רבי יהודה","דחייש:"],[4,"בשלא בדקה","ומדקאמר רבי בהא ס\"ל כרבי יהודה אבל בשבדקה לא ס\"ל כוותיה מכלל דרבי יהודה בן אגרא אפילו בדקה נמי חייש ומאי לא בדקה אי נימא ה\"ק רבי רואה אני את דברי ר' יהודה בשלא בדקה בדרבי יוסי ואע\"ג דבדקה בדר' יהודה דאיכא לספוקי בבין השמשות דרבי יוסי אבל איני רואה את דבריו כשבדקה בשניהם:"],[5,"מכלל דרבי יהודה אפילו בדקה בתרוייהו","חייש הא ודאי בין השמשות לא חזאי ואין לך לחלוק ראיה אחת לשתים:"],[6,"אלא פשיטא דלא בדקה לא","בהא ולא בהא דחוששת שמא ראתה בבין השמשות דר' יהודה:"],[6,"אבל בדקה בדר' יהודה","אין אני רואה את דבריו לחוש לזיבה:"],[7,"אלמא","קסבר רבי בין השמשות דרבי יוסי לילה הוא והראייה שבה אינה עולה לשתים:"],[8,"אי נימא כשבדקה בדרבי יהודה ולא בדרבי יוסי","וקאמר רבי בזו אני רואה את דבריהם דלא חיישינן אבל לא בדקה לא בזו ולא בזו איני רואה את דבריהם דאנא סבירא לי דחיישא:"],[8,"","מכלל דלרבנן אע\"ג דלא בדקה לא בהא ולא בהא לא חיישא והא לא בדקה. ויש לחוש לראיית בין השמשות המתחלקת לשתים:"],[9,"אלא פשיטא","דנראין דברי חכמים כשבדקה דקאמר רבי שבדקה בשניהם קאמר אבל באחד מהן דקאמרי אינהו נמי לא חיישא איני רואה דבריהם דכיון דלא בדקה בדר' יוסי יש לחוש לראיית בין השמשות. אלמא לרבי ספקא הוא כו':"],[11,"ה\"ק","האי נראין דקאמר רבי לאו לטעמיה דנפשיה קאמר דתידוק מינה מדקאמר בזו אני רואה את דברי זה ובזו איני רואה מכלל דאינהו בתרוייהו פליגי ותקשי לך אלא רבי לפרושי פלוגתייהו אתא לאשמועינן במאי פליגי וה\"ק נראין דברי ר' יהודה לחכמים ומודים לו דחיישינן כשלא בדקה לא בזה ולא בזה שדברי חכמים כשבדקה באחד מהני דקסברי בין השמשות דרבי יוסי ליליא הוא ורבי יוסי לטעמיה דאמר ספקא הוא הילכך עד שתבדוק בשניהם יש לחוש בראיית בין השמשות:"],[12,"לראייה מרובה","ג' גריסין בועודות:"],[12,"לראייה מועטת","שני גריסין בועודות:"],[13,"ממנו","מדרבי יוסי:"],[13,"שלא הפרישה בטהרה","בשביעי שלא בדקה בין השמשות:"],[13,"לא תהא בחזקת טומאה","ואינה טובלת לערב ואע\"פ שהפרישה בטהרה שחרית. אלמא משראתה הויא כל היום בחזקת חוזרת ורואה עד גמר היום אף זו הואיל ולא בדקה בין השמשות שלם איכא למיחש דלמא בסוף בין השמשות ראתה והיא עולה לשתי ראיות:"],[13,"ונראין לי דבריו","ומודה אני לו:"],[13,"כשבדקה","בין השמשות שלם תו לא חיישא ובשלא בדקה אני חולק עליו:"],[16,"קשיא דרבי יהודה אדר' יהודה","דלעיל ס\"ל בין השמשות דרבי יוסי ספיקא הוא:"],[17,"בשלמא בלא רבי","אי לא פירש רבי לפלוגתייהו בין לעיל בין הכא לא הוה קשיא דרבי יהודה אדר' יהודה התם דבדקה כו':"],[17,"אלא בדרבי","מכי אתא רבי לפרושי פלוגתייהו ולא מתוקמא לן אלא כדפירשה דלרבי יהודה דלעיל ספיקא הוא והכא מיתחזי דליליא הוא קשיא:"]],[[6,"","אבל בדקה בדרבי יהודה כו'. וא\"ת דלמא אבל בדקה בדרבי יוסי ולא בדקה בדר' יהודה לא חיישינן דבין השמשות דר' יהודה יממא הוא וי\"ל דבהא ר' יהודה בן אגרא מודה דלא חיישינן כיון דבדקה דדר' יוסי:"],[11,"","שאף חכמים לא נחלקו כו' בכמה דוכתין משני כי הכא אבל בפרק הזהב (ב\"מ דף נד.) גבי חומש ומעשר ובפרק כל הבשר (חולין דף קט.) גבי אפשר לסוחטו לא משני הכי משום שיכול ליישב בענין אחר בהגהה מועטת:"],[13,"","ומה אילו נדה שלא הפרישה כו'. וא\"ת דבפ\"ב (דף סח:) לקמן א\"ר יוסי גופיה דהיא בחזקתה וי\"ל דהתם מיירי כשבדקה יום ב' או יום ג' ומצאתה טהורה שפסקה והכא בדלא בדקה א\"נ הכא מיירי שבדקה שחרית של שביעי ומצאתה טמא:"],[15,"","מכלל דרבי יהודה בן אגרא סבר בדקה בדר' יהודה ולא בדקה בדרבי יוסי אינה חוששת. השתא הוה מצי למיפרך הא משמיה דרבי יוסי קאמר וא\"ת ואימא מכלל דרבי יהודה בן אגרא סבר דבדקה בדר' יוסי גרידא אינה חוששת ורבי סבר חוששת כיון דלא בדקה בדרבי יהודה דבין השמשות דרבי יוסי מישך שייך בדר' יהודה כדאמר בסוף והשתא לא הוה צריך למימר תרי תנאי ואליבא דר' יהודה בן אגרא וי\"ל דומיא דברייתא דלעיל דמיירי רבי יהודה בן אגרא כשבדקה בדרבי יהודה ולא בדקה בדרבי יוסי:"]]],[["והדר חייל בין השמשות דר' יוסי והאי תנא סבר בין השמשות דר' יוסי מישך שייך בדר' יהודה","ת\"ר הרואה כתם מטמאה עצמה וקדשים למפרע דברי רבי","ר\"ש בן אלעזר אומר קדשים מטמאה עצמה אינה מטמאה שלא יהא כתמה חמור מראייתה","והא מצינו כתמה חמור מראייתה לענין קדשים","אלא תני הכי ר\"ש בן אלעזר אומר אף קדשים אינה מטמאה שלא יהא כתמה חמור מראייתה לכל דבר","ת\"ר ראתה כתם ואחר כך ראתה דם תולה כתמה בראייתה מעת לעת דברי רבי","ר\"ש בן אלעזר אומר יומו א\"ר נראין דבריו מדברי שהוא מתקנה ואני מעוותה","מתקנה עוותי מעוית לה אמר רבינא איפוך","רב נחמן אמר לעולם לא תיפוך שהוא מתקן הלכותיה לידי זיבה","ואני מעוות הלכותיה לידי זיבה","בעי מיניה ר' זירא מר' אסי כתמים צריכין הפסק טהרה או לא אשתיק ולא א\"ל ולא מידי","זימנין אשכחיה דיתיב וקאמר תולה כתמה בראייתה מעת לעת דברי רבי","אמר ר\"ל והוא שבדקה ורבי יוחנן אמר אע\"פ שלא בדקה","א\"ל מכלל דכתמים צריכין הפסקת טהרה א\"ל אין והא זימנין סגיאין בעא מינך ולא אמרת ולא מידי דלמא אגב שיטפך אתיא לך א\"ל אין אגב שיטפאי אתיא לי","\u0001מתני׳\u0002 הרואה יום י\"א בין השמשות תחלת נדה וסוף נדה תחלת זיבה וסוף זיבה","יום ארבעים לזכר ויום שמונים לנקבה בין השמשות לכולן הרי אלו טועות","א\"ר יהושע עד שאתם מתקנים את השוטות באו ותקנו את הפקחות","\u0001גמ׳\u0002 תחלת נדה וסוף נדה תחלת נדה וסוף זיבה היא","אמר רב חסדא הכי קאמר הרואה יום י\"א בין השמשות תחילת נדה וסוף זיבה","ובשביעי לנדתה סוף נדה ותחלת זיבה","א\"ר יהושע עד שאתם מתקנין את השוטות כו' הני"],[[0,"והדר","מתחיל דרבי יוסי וספקא הוא:"],[0,"מישך שייך בדרבי יהודה","מובלע הוא בתוך של רבי יהודה וכיון דלדידיה בעינן כל בין השמשות דרבי יהודה הרי בדקה בשניהם:"],[1,"מטמאה עצמה","הרואה כתם מטמאה עצמה לטהרות וקדשים:"],[1,"למפרע","עד שעת הכבוס:"],[2,"חמור מראייתה","למפרע דלראייתה לא הוי אלא מעת לעת וכתמה עד שעת הכבוס:"],[3,"והא מצינו כו'","דהא מודה ר\"ש בן אלעזר בקדשים דמטמאתן למפרע עד שעת הכבוס:"],[5,"ראתה כתם ואח\"כ ראתה דם","תוך מעת לעת:"],[5,"תולה כתמה בראייתה","ואמרינן האי כתם מדם נדות זה הוא וטהורה מלטמא עד שעת הכבוס אלא משמצאתו ולהבא:"],[6,"יומו","אם ראתה בו ביום תולה ואם שקעה חמה אף על פי שראתה בתוך מעת לעת אינה תולה:"],[6,"שהוא מתקנה","מיקל עליה וכיון דכתמים דרבנן נראין דברי המיקל. ולקמן פריך עוותי מעוות לה דהא ר\"ש בן אלעזר מחמיר:"],[7,"איפוך","ואימא נראין דברי מדבריו:"],[8,"הוא מתקן הלכותיה לידי זיבה","לענין זיבה הוא מיקל דלדידיה היכא דלא חזיא בו ביום לא תלינן כתמה בראייתה ומונה ימי נדות מיום ראייתה ואין ימי זיבה מתחילין עד יום ח' לראייתה לרבי מונה מיום מציאת כתמה ואף להקל ולטבול לליל שביעי לכתמה אם פסקה ומיום ח' לכתמה הוו ימי זוב ונמצא רבי מחמיר לענין זיבה דכי חזיא בח' לכתמה אמרינן יום זיבה הוא וצריכה לשמור תשיעי יום כנגד יום ואם תראה שנים עמו תהא זבה ולר\"ש סוף נדה הוא ולא מצריך שימור ואם תראה שנים עמו לא תהיה זבה נמצא אני מביאה ע\"י כתמה לזיבה אבל איהו לא:"],[10,"צריכין הפסק טהרה","בשביעי לטבול בערב צריכה לבדוק בין השמשות להפסיק בטהרה או לא:"],[11,"זימנין","פעם אחרת:"],[11,"אשכחיה","רבי זירא לרבי אסי:"],[11,"דיתיב וקאמר","הך מלתא דרבי ומפרש עלה אמר ר\"ל והוא שבדקה בין השמשות של שביעי לכתמה להפסיק בטהרה אבל לא הפרישה בטהרה גליא דעתה דמיום ראייתה נקטה מנינא דידה והיא גרמה לעצמה להבדיל כתמה מראייתה וכתמה מטמא למפרע מיום לבישה ורבי יוחנן אמר אף על פי שלא בדקה דכיון דיכולה לתלות לאו בגילוי דעתה תליא מלתא ולא מפסדא בהכי:"],[13,"א\"ל","רבי זירא לרבי אסי מדפליגי רבי יוחנן ור\"ל לענין תליא בבדקה ולא בדקה מכלל דאורחא הוא לבדוק ביום שביעי לכתמה ולהפסיק בטהרה:"],[13,"שיטפך","ריהטך:"],[14,"מתני' הרואה יום אחד עשר בין השמשות","וספק יום הוא והוי דם זיבה או ספק לילה ותחלתו נדה:"],[14,"תחלת נדה וסוף נדה כו'","ובגמרא פריך תחלת נדה וסוף זיבה היא והויא טועה ובע\"כ תשב שבעה ואם ראתה לסוף שבעה יום אחד נחמיר עליה לומר ראיה ראשונה סוף זיבה הואי והשתא הויא תחלת נדה ותשב שבעה ואם שלשה תראה נחמיר עליה לומר ראייה ראשונה תחלת נדה הואי והשתא זבה וצריכה שבעה נקיים ולא תשב ארבעה והן וכן לעולם היא מקולקלת ותקנתה כדמפרש בערכין (דף ח.):"],[15,"יום ארבעים לזכר ויום שמונים ללידת נקבה בין השמשות לכולן","כלומר באיזה מאלו שתראה בין השמשות הוי האי בין השמשות ספק טמא ספק טהור ואם תראה ליום שמיני ספק נדה ספק שומרת יום כנגד יום וכן לעולם עד שתפסוק כדי שיעור המפורש לה בערכין:"],[16,"את השוטות","את הטועות כגון אלו שראו בשעת הספק:"],[16,"באו ותקנו את הפקחות","הרואות בשעה ודאית וצריכין אנו לתקן פתחיהן ולפרש ימי שימורן ותשמישן כדמפרש בברייתא בגמרא:"]],[[1,"","עצמה וקדשים. פירש בקונטרס עצמה לטהרות ותימה אמאי איצטריך למתני קדשים דכ\"ש הוא וי\"ל דמשום רשב\"א נקטיה דמסיק דאפילו קדשים אינה מטמאה א\"נ תנא קדשים לגלויי דעצמה אף לטהרות ומיהו לישנא דעצמה לא משמע לטהרות ועוד קשה לרשב\"א אכתי הוי כתמה חמור מראייתה דהא איהו גופיה אמר בסמוך דתולה בראיית יומו אבל כתם שמצאה ביום שלפני הראייה טמאה למפרע ומקולקלת למניינה משעת כבוס ונראה לפרש דעצמה היינו שמקולקלת למניינה משעת כבוס ורשב\"א פליג אתרוייהו דאינה מקולקלת למניינה ולא מטמאה קדשים אלא מעת לעת והא דקאמר רשב\"א בסמוך דתולה כתמה בראיית יומו הא כתם דאתמול לא תליא בראייה לאו משום שתהא מקולקלת בכתמה דאתמול משעת כבוס אלא ע\"י ראייה דהשתא וכתם דאתמול היא מקולקלת דלא ידעה אי מניא מהיום או מכתם וא\"ת אכתי כתמה חמור מראייתה דבכתמה היא מקולקלת למניינה מעל\"ע אבל בראייתה אע\"ג דלקדשים ולטהרות מטמאה מעל\"ע מ\"מ אינה מקולקלת דמונה מיום שראתה וי\"ל דלא חייש רשב\"א אלא שלא יהיה כתמה חמור מראייתה בזמן לטמאות יותר מעל\"ע:"],[7,"","איפוך. פ\"ה נראין דברי מדבריו א\"נ איפוך שהוא מעוותה ואני מתקנה והמחמיר עדיף:"],[8,"","שהוא מתקן הלכותיה לידי זיבה. פ\"ה דלר\"ש אם ראתה בח' וט' וי' לכתמה לא הויא זבה ולרבי דתולה כתמה בראייתה הויא זבה ואין נראה דלר\"ש נמי הויא מקולקלת למניינה כדפרישית לעיל ואדרבה ר\"ש מחמיר טפי שמטמא ממציאת הכתם מעל\"ע ומה שפירש נמי דלרבי טובלת בשביעי לכתמה ומשמשת אין נראה להקל כולי האי ולא תלינן כתמה בראייתה ונראה כפר\"ח כשמצאה הכתם ביום הראייה לרבי דתלי כתמה כל מעת לעת בראייה היא מקולקלת כל מעת לעת והויא כאילו ראתה שני ימים יום הראייה ויום שלפניו ואם ראתה גם למחר הויא זבה אם עומדת בימי זובה ולר\"ש דלא תלי אלא יומו א\"כ לא חשבינן כאילו ראתה אתמול ולא תהיה זבה עד שתראה עוד שני ימים והיינו ר\"ש מתקנה ורבי מעוותה דר\"ש מיקל טפי ומיהו אם ראתה היום ואתמול ומצאה כתם רבי שמעון מחמיר כדפירשנו:"],[10,"","צריכה הפסק טהרה. פ\"ה צריכה בדיקה להפסיק בשביעי לכתמה כדי לטבול בערב ופירש דלר\"ל אם בדקה בשביעי לכתמה דגליא דעתה דכתמה מראייתה הוא אבל לא בדקה ומונה מן הראייה פירש לפי שיטתו ואין נראה דאין לה לטבול בליל שמיני לכתמה דרבי לא אמר שתולין כתמה בראייתה בודאי אלא בספק כדפי' ותו היכי מוכח מהכא דבכתם צריכה בדיקה בשביעי דשאני הכא שראתה ראייה ודאית ותו אדרבה מדקאמר רבי יוחנן אע\"פ שלא בדקה בשביעי לכתמה טובלת לערב א\"כ אינה צריכה בדיקה ונראה לפרש צריכה הפסקת טהרה בין הכבוס למציאת הכתם דדלמא הא דתלי רבי כתמה בראייתה ולא מטמא משעת כבוס היינו כשבדקה בין כבוס למציאת הכתם וקאמר ריש לקיש והוא שבדקה פירוש סמוך למציאת הכתם תוך מעת לעת אבל אם יש מעת לעת מבדיקה למציאת הכתם מטמאין לה למפרע עד שעת הבדיקה ורבי יוחנן אמר אף על פי שלא בדקה פירוש סמוך אלא יש מעת לעת בין בדיקה למציאה אפילו הכי תלינן הכתם בראייתה כיון דמשעת כיבוס ליכא מעת לעת נמי ליכא אלמא לכולי עלמא צריכה הפסק דאין נראה לומר דלרבי יוחנן אע\"פ שלא בדקה כלל קאמר דכולי האי לא הוה פליג אריש לקיש:"]]],[["שוטות נינהו טועות נינהו אלא תני טועות","דתניא יום אחד טמא ויום אחד טהור משמשת שמיני ולילו עמו","וארבעה לילות מתוך שמונה עשר יום ואם היתה רואה מבערב אינה משמשת אלא שמיני בלבד","שני ימים טמאין ושני ימים טהורין משמשת שמיני ושנים עשר וששה עשר ועשרים","ותשמש נמי בתשסר אמר רב ששת זאת אומרת גרגרן דתנן אסור","רב אשי אמר נהי דחד עשר לא בעי שימור עשירי מיהא בעי שימור","שלשה ימים טמאין ושלשה ימים טהורין משמשת שני ימים ושוב אינה משמשת לעולם","ארבעה ימים טמאים וארבעה ימים טהורין משמשת יום אחד ושוב אינה משמשת לעולם","חמשה ימים טמאים וחמשה ימים טהורין משמשת שלשה ימים ושוב אינה משמשת לעולם ששה ימים טמאין וששה ימים טהורין משמשת חמשה ימים ושוב אינה משמשת לעולם","שבעה ימים טמאין ושבעה ימים טהורין משמשת רביע ימיה מתוך כ\"ח ימים","שמונה ימים טמאין ושמונה ימים טהורין משמשת חמשה עשר יום מתוך ארבעים ושמונה","הרי ארביסר הוו","אמר רב אדא בר יצחק זאת אומרת ימי נדתה שאין רואה בהן עולין לספירת זיבתה דאיבעיא להו"],[[0,"שוטות נינהו","בתמיה:"],[1,"דתניא","לפרושי פקחות דמתניתין קאתי:"],[1,"יום אחד טמא ויום אחד טהור","כל ימיה וקמיירי כשרואה ביום:"],[1,"משמשת שמיני","ליום שראתה בו ראייה ראשונה שהרי טהורה הות שהרי בשביעית לערב טבלה ולא תראה עד תשיעי הלכך משמשת שמיני שלם לילה ויום:"],[1,"ולילו עמו","ליל אחריו נגהי תשיעי:"],[2,"וארבעה לילות מתוך שמונה עשר יום","לראייה הראשונה שהרי אשה זו לא תהא זבה לעולם שאינה רואה ג' רצופין וכשהיא רואה תשיעי תהא שומרת עשירי ותשמש בלילה ותראה בי\"א ותשמור י\"ב ותשמש בלילה הרי שתים ותראה בי\"ג ותשמור י\"ד ותשמש בלילה הרי שלשה ותראה ט\"ו ותשמור ט\"ז ותשמש לערב הרי ד' ובי\"ז תראה ותשמור י\"ח הרי כלו י\"ח ולא שמשה אלא ד' לילות לבד שמיני ולילו ותשמיש אחרון אינו בתוך י\"ח ולמחר בי\"ט כשתראה תהא תחלת נדה שהרי שלמו י\"א שבין נדה לנדה וחוזרת למנינה שאמרנו:"],[2,"ואם היתה רואה","בכל הימים הטמאים מבערב:"],[2,"אינה משמשת אלא שמיני","שלם לילה ויום אבל לא ליל של אחריו שהרי תראה בו ותהא טמאה וצריכה לשמור עשירי ובלילה לא תטבול שהרי רואה וכן עד סוף י\"ח שהן י\"ח עם ימי הנדות ובי\"ט תהא תחלת נדה ותחזור למנינה ותשמש בשמיני וכן לעולם:"],[3,"ב' ימים טמאים כו'","כללא דמילתא כל ימים דלקמן עד סוף פירקין כשרואה מבערב:"],[3,"משמשת שמיני","שהוא משני ימים הטהורים ששביעי ושמיני טהורין הן אלא שהשביעי מהנדות וטובלת לערב ומשמשת שמיני שלם ולערב תראה שהוא תשיעי וכן עשירי ותשמור י\"א יום לאלו שני ימים וטובלת לערב ומשמשת י\"ב שלם ותראה י\"ג וי\"ד ותהא שומרת ט\"ו ותשמש ט\"ז ותראה י\"ז וי\"ח ותשמור י\"ט דקסבר הרואה יום י\"א אסור לשמש למחר ולקמן פריך ותשמש בתשסרי דהא כלו להו ימים שצריכה שימור ומ\"מ ביום עשרים משמשת וכשתראה יום כ\"א הרי היא תחלת נדה וחוזרת למנין זה שאמרנו:"],[4,"ותשמש בתשסר","דקיימא לן בפרק אחרון (לקמן נדה עב:) יום אחד עשר לימי זיבה לא בעי שימור יום כנגדו וזו למה משמרת י\"ט בשביל י\"ח שהוא סוף זיבה:"],[4,"גרגרן דתנן","בפרק תינוקת (שם.) הרואה יום י\"א וטבלה ליום שלאחריו ושמשה וראתה בו ביום בית הלל אומרים הרי זה גרגרן שלא המתין יום זה ומהך ברייתא דקתני ומשמשת יום עשרים ולא יום י\"ט שמעינן דאסור להיות גרגרן ולשמש ביום י\"ב עם הרואה בי\"א:"],[5,"רב אשי אמר","לעולם אינו אסור והכא דתני אסור משום שראתה יום עשירי דאיהו בעי שימור לפיכך תשב י\"ט הטהור ויהא שימור ליום י\"ז שהוא עשירי לימי זיבה. שימור לא הוי אלא יום טהור דהכי נפקא לן יהיה מלמד שסופרת יום אחד לאחד וספירה לא הוי אלא יום טהור:"],[6,"משמשת שני ימים","אחד עשר וי\"ב שהשמיני ותשיעי מי\"א שבין נדה לנדה הן ועשירי שימור הוא להן ושוב אינה משמשת לעולם שהרי תהא זבה בי\"ג וי\"ד וט\"ו וצריכה לספור ז' נקיים והיא לא תראה ז' נקיים לעולם:"],[7,"יום אחד","שמיני דכולה ברייתא בשרואה בערב:"],[9,"רביע ימיה מתוך כ\"ח","שבעה ימים שאחר שבעה הטמאים של נדות היא משמשת ובשבעה השלישיים תהא זבה ובשבעה האחרונים הן ימי הספירה הרי כ\"ח וביום כ\"ט תהא תחלת נדה ונמצאת משמשת רביע ימיה ולהכי נקט כ\"ח מפני שתחלת נדותה של זו מכ\"ח לכ\"ח:"],[10,"ט\"ו יום מתוך מ\"ח","כגון ח' הראשונים השמיני ימי זיבה ומשמונה השניים תשמור יום לשמיני שלפניו ותשמש שבעה הרי ט\"ז שעברו עליה ונשארו ב' לבא מימי זיבה ושמונה השלישיים שנים מהן ימי זוב והששה תחילת נדתה ושמונה הרביעיים שהן טהורים הראשונים ישלים ז' ימי נדה והשבעה תשמש ועכשיו נותרו ד' ימים מימי זיבה שמונה החמשיים הרי היא זבה משלשה ראשונים וח' שלאחריהן שבעה לספירה ושמיני לתשמיש הרי ט\"ו יום מתוך מ\"ח וביום מ\"ט כשתראה תהא תחלת נדה ותחזור למנין שאמרנו:"],[11,"ארביסר הוו","קסבר האי דמותיב שהאשה הזאת לא תשמש יום מ\"ח לפי שהשמונה החמשיים שנעשית בהן זבה אין מהן אלא ד' מימי זיבה וד' האחרונים מימי נדה הן ומיהו תחלת נדה לא הוי כל זמן שלא ספרה ולא טהרה מזובה אבל להכי מהניא הך ראייה ד' האחרונים הראויין לנדות שכשיבאו שמונה טהורין שאחריהם לא יעלו שלשה הראשונים לימי הספירה לפי שהן השלמת ימי נדה וימי נדתה שאינה רואה בהן אין עולין לספירת זיבתה הלכך אין כאן אלא חמשה לספירה וכשתראה יום מ\"ט סותרת וכן כל ח' השביעיים (יום) ועד שיגיע יום ס\"ג לא ישלימו ימי ספירתה:"]],[[2,"","וארבעה לילות מתוך י\"ח. משמע כאן בהדיא דאין נעשה זבה גדולה ולא צריכה ז' נקיים עד שתראה ג' ימים רצופין בי\"א יום ודלא כאותם שכתבו בשם רבינו סעדיה שצריכה שבעה נקיים אפילו ראתה בי\"א ג' ימים מפוזרים:"],[4,"","תשמש בתשסר. וא\"ת כיון דקס\"ד דעשירי לא בעי שימור תקשה ליה רישא אמאי לא משמשת אלא ד' מתוך י\"ח דכי ראתה בי\"ז תשמש בי\"ח ותו דפלוגתא היא בפרק בתרא (לקמן נדה עב:) לרבי יוחנן עשירי בעי שימור ולר\"ל לא בעי שימור ויש לומר דהא דקאמר רבי יוחנן עשירי בעי שימור היינו בימי זיבה שאסורה לשמש ביום י\"א אפילו פסקה ולר\"ל מותרת דעשירי כיון דאינה יכולה להיות זבה גדולה לא בעי שימור ולהכי ברישא ניחא דאסורה בי\"ח דהוו בימי זיבה דאפילו ר\"ל מודה דמדרבנן אסור אבל בימי נדה סבר המקשה דאפילו רבי יוחנן מודה דלא בעי שימור ולכך פריך תשמש בתשסר ומשני רב ששת גרגרן אסור דאפילו בראיית י\"א צריכה שימור מדרבנן ביום י\"ב לכ\"ע ורב אשי אמר דאינו אסור אלא משום שראתה בעשירי וצריכה שימור לרבי יוחנן אף בימי נדה מן התורה כמו בימי זיבה ולר\"ל מדרבנן:"],[11,"","הני ארביסר הוו. פ\"ה דפריך אמאי משמשת יום מ\"ח דשמונה חמישיים שהן טמאין הן ד' ימי זיבה וד' ימי נדה ושמונה טהורין שאחריהם ג' בימי נדה וחמש בימי זיבה וג' ימים הראשונים דימי נדה לא יעלו לה לספירת זיבה דאין ימי נדה עולין לספירתה דאע\"ג דאינה נדה שהרי אינה חוזרת לפתח נדתה עד שתספור ז' נקיים מ\"מ כיון דבימים הראוים לימי נדה הן אין עולין לספירת זיבתה וקשה לפירוש זה דא\"כ תקשה ליה רישא דקתני משמשת רביע ימיה מתוך כ\"ח הלא ז' שלישיים שהן טמאין היו ד' בימי זיבה וג' בימי נדה וא\"כ ז' ימים טהורין שאחריהם לא יעלו לספירת זיבתה והיאך תחזור חלילה מכ\"ח לכ\"ח דאסורה לשמש בז' ימים טהורין של כ\"ח שניים ועוד קשה דמשמע דאי הוה תני ומשמשת י\"ד הוה ניחא ליה והא עד ס\"ג יום לא יעלו לה ז' לספירתה כדפירש\"י וא\"כ היאך חוזרת חלילה ממ\"ח למ\"ח לכן נראה דה\"פ הני י\"ד הוו דבח' רביעיות אינה משמשת רק ו' דהא ח' שלישיים שהיו טמאים היו ב' בימי זיבה וששה אחריהן ימי נדה ויום ראשון מרביעיות שהן טהורין לא תשמש דהוי מז' ימי נדה ויום שני נמי לא תשמש לרב אשי דאמר לעיל עשירי בעי שימור והרי יום שני הוה שימור ליום י\"ז שהוא עשירי ויום ראשון אע\"ג דטהור הוי סבר המקשה דלא הוי שימור כיון דהוי מימי נדה וימים שהיא נדה גמורה אינן עולין לספירת זיבה קטנה אבל מיום מ\"ח לא פריך דכיון דאינה נדה גמורה עד שתספור ז' נקיים עולין לה שפיר לכ\"ע אע\"פ שהן ראויין לימי נדה ולכך ניחא ליה רישא דמשמשת רביע ימיה מתוך כ\"ח ומה שפרש\"י דעד ס\"ג לא ישלמו ימי זיבה נראה דלא דק דאינה טובלת עד ליל פ' שהרי ח' ימים שביעיים הם ששה ימי זיבה ושני ימי נדה ושמיניים הטהורים הן ה' בימי נדה וג' בימי זיבה ותשיעיים הטמאות כל ח' ימי זיבה והעשיריים ז' לספירת נקיים:"],[11,"ולמאי","דמשנה הש\"ס ימי לידה וימי נדה א\"כ לר\"ת דפסק דימי לידתה שאינה רואה בהן אין עולין לספירת זיבתה (וה\"ה) ולפרש\"י דימים הראויים לימי נדה אין עולין אין תקנה לנשים בזמן הזה דהוי כלהון ספק זבות וצריכות ז' נקיים ופעמים דקיימי בימים הראויים לנדה ולא עלו לה לספירתה ומיהו לפירוש רש\"י אתי שפיר דהוא פסק דימי לידה עולין לימי ספירתה ולר\"ת נמי ימי נדה דווקא אין עולין אבל ימים הראויין עולין שפיר:"]]],[["ימי לידה שאינה רואה בהן מהו שיעלו לספירת זיבתה","אמר רב כהנא ת\"ש ראתה שנים ולשלישי הפילה ואינה יודעת מה הפילה","הרי זו ספק זיבה ספק לידה","מביאה קרבן ואינו נאכל וימי לידתה שאין רואה בהן עולין לה לספירת זיבתה","אמר רב פפא שאני התם כיון דאיכא למימר יולדת זכר היא וכל הני שבעה יתירי דקיהבינן לה סלקי לה לספירת זיבתה","אמר ליה רב הונא בריה דרב יהושע לרב פפא ביולדת זכר איכא לספוקי ביולדת נקבה ליכא לספוקי אלא לאו שמע מינה עולין שמע מינה","תשעה ימים טמאין ותשעה ימים טהורין משמשת שמונה ימים מתוך שמונה עשר","עשרה ימים טמאין ועשרה ימים טהורים ימי שמושה כימי זיבתה וכן למאה וכן לאלף","\u0001הדרן עלך בא סימן\u0002","מתני׳ \u0001דם\u0002 הנדה ובשר המת מטמאין לחין ומטמאין יבשין אבל הזוב והניע והרוק והשרץ והנבלה והשכבת זרע מטמאין לחין ואין מטמאין יבשין ואם יכולין להשרות ולחזור לכמות שהן מטמאין לחין ומטמאין יבשין","וכמה היא שרייתן בפושרין מעת לעת רבי יוסי אומר בשר המת יבש ואינו יכול להשרות ולחזור לכמות שהיה טהור","\u0001גמ׳\u0002 מנא הני מילי אמר חזקיה דאמר קרא (ויקרא טו, לג) והדוה בנדתה מדוה כמותה מה היא מטמאה אף מדוה מטמאה","אשכחן לח יבש מנלן אמר רבי יצחק אמר קרא (ויקרא טו ) יהיה בהויתו יהא","ואימא הני מילי בלח ונעשה יבש יבש מעיקרו מנלן ותו הא דתנן המפלת כמין קליפה כמין עפר כמין שערה כמין יבחושין אדומים תטיל למים אם נמוחו טמא מנלן יהיה רבויא הוא","אי מה היא עושה משכב ומושב לטמא אדם ולטמא בגדים אף דמה נמי עושה משכב ומושב לטמא אדם ולטמא בגדים אטו דמה בר משכב ומושב הוא","ולטעמיך אבן מנוגעת בת משכב ומושב היא דאיצטריך קרא למעוטי דתניא יכול תהא אבן מנוגעת עושה משכב ומושב לטמא אדם לטמא בגדים","ודין הוא ומה זב שאינו מטמא בביאה עושה משכב ומושב לטמא אדם לטמא בגדים אבן מנוגעת שמטמאה בביאה אינו דין שמטמאה משכב ומושב לטמא אדם לטמא בגדים","ת\"ל הזב הזב ולא אבן מנוגעת טעמא דמעטיה קרא הא לאו הכי מטמאה","ומינה לאו מי אמרת הזב ולא אבן מנוגעת ה\"נ אמר קרא אשר היא יושבת עליו היא ולא דמה"],[[0,"ימי לידתה","כגון ילדה בזוב ופסקה מיד:"],[1,"הכי גרסינן ראתה שנים","ראתה שני ימים בשופי בתוך י\"א שבין נדה לנדה:"],[2,"ספק לידה ספק זיבה","שמא לידה שמא זיבה שמא לא זו ולא זו אם ולד הוא ולא ראתה בפתיחת הקבר הרי היא לידה ולא זיבה ואם אינו ולד וראתה דם בפתיחת הקבר הרי היא זיבה ואין כאן לידה ואם ולד הוא וראתה דם בלידה הרי זו יולדת בזוב ואם נפתח קבר בלא דם ואינו ולד אין כאן לא זו ולא זו הלכך ספק הוא ונטיל עליה חומר לידה לטמא שבועיים אפילו לא תראה וחומר זיבה שכל זמן שלא תפסוק ז' נקיים לא תטהר ומביאה קרבן ואינו נאכל שמא אין כאן לא לידה ולא זיבה:"],[3,"וימי לידתה שאין רואה בהן עולין כו'","ואע\"ג דאיכא לספוקי ביולדת בזוב ויש כאן לידה וזיבה:"],[4,"משום דאיכא למימר כו'","אבל אי הוה פשיטא לן דיולדת נקבה היא לא סלקי לה:"],[6,"ט' ימים טמאין","תרי מינייהו זיבה וכי חזיא טהורין חד מינייהו הוי שימור ושמונה לתשמיש וביום י\"ט הויא תחלת נדה וכן לעולם לא תהא זבה:"],[7,"ימי שמושה כימי זיבתה","דמעשרה טמאין הוו ז' נדה וג' זיבה ומעשרה טהורין ז' לספירה וג' לתשמיש הרי ימי שימוש בימי זיבה:"],[7,"וכן למאה","טמאין ז' ימי נדה וכולהו ימי זיבה ומאה טהורין ז' לספירה וכולהו לתשמיש וכן לאלף:"],[9,"","מתני' דם הנדה:"],[9,"והניע","קר\"ק בלע\"ז. וממעיינות הזב הן והוי אב הטומאה:"],[10,"וכמה היא שרייתן","דנימא אי הדרא בכי האי שיעורא לחין נינהו:"],[10,"בפושרים מעת לעת","אבל אי בעי טפי מים חמים או יותר ממעת לעת יבשין הן:"],[11,"גמ' מנא הני מילי","דדם נדה מטמא מגעו ומשאו:"],[12,"אשכחן לח","דדוה לח משמע כעין שהוא זב:"],[12,"יהיה","דם יהיה זובה:"],[13,"יבש מעיקרו","כגון הני דתנינן:"],[13,"מין שערה","אדומה:"],[14,"עושה משכב","שיהא משכבו מטמא אדם ולא יהא ראשון במגעו אלא אב הטומאה כמשכב נדה עצמה:"],[16,"שאינו מטמא בביאה","אדם הנכנס עם הזב בבית אינו טמא:"],[16,"אבן המנוגעת","מטמאה בביאה אדם הנכנס עמה לבית דכתיב והבא אל הבית וגו':"],[17,"הזב","אשר ישכב עליו הזב (ויקרא ט״ו:ד׳):"],[18,"היא","עושה משכבה אב הטומאה ולא דמה עושה משכבה אב הטומאה אבל מטמא הוא את שתחתיו משום משא להיות ראשון ואף על פי שאין נוגע בו דהא איתקש לנדה והכי נמי תנן באבות הטומאה (כלים פ\"א מ\"ג) דדם נדה מטמא במשא:"]],[[5,"","אלא ש\"מ עולין ש\"מ. וטעמא דרב הונא בריה דרב יהושע אע\"ג דהוי ספק ספקא מ\"מ אי בעלמא אין עולין הכא נמי הוה לן למגזר אטו בעלמא:"],[7,"","וכן למאה וכן לאלף. ימי שמושה בימי זיבתה דמאחר ז' ימי נדה כל הימים שתראה אפילו מאה או אלף מקרו ימי זיבתה עד שתספור ז' נקיים:"],[11,"","דם הנדה. מנא הני מילי. לרבא דאמר בפ' בנות כותים (לעיל נדה לה.) לאחרים גורם טומאה לעצמו לא כ\"ש ולית ליה דשעיר המשתלח יוכיח הכא לא צריך קרא ומיהו לדם נדה של מצורעת אצטריך שפיר קרא דהדם אינו גורם טומאה ולקמן דמצריך קרא לטומאת זובו במגע ובמשא ולא יליף מדם הנדה דהכא משום דאיכא למפרך מה לדם הנדה שכן מטמא באונס ואם תאמר וכיון דלא ילפינן מהכא אמאי אצטריך לקמן קרא למעוטי זוב יבש מהיכא תיתי לטמא ויש לומר כיון דהשוה הכתוב דם נדה וזוב לטומאה ממילא ילפינן מהדדי דגילוי מילתא בעלמא הוא:"],[13,"","ותו הא דתנן המפלת כו'. תימה דהיינו ההיא קושיא גופיה וי\"ל דה\"ק וכ\"ת דאין הכי נמי דיבש מעיקרא טהור והתנן המפלת כו' אי נמי י\"ל ותו יבש משונה כמין יבחושין או כמין קליפה מנלן:"],[15,"","יכול תהא אבן מנוגעת כו'. אבן מנוגעת שמטמאה בביאה כו' וא\"ת מת יוכיח שמטמא בביאה ואינו עושה משכב ומושב ועוד מצורע גופיה מפרש ר\"ת בריש אלו דברים (פסחים דף סז:) דלא עביד משכב ומושב אלא לטמא אוכלין ומשקין ויש לומר דמקרא דהכא ממעטינן להו הזב ולא המצורע ולא המת:"]]],[["אי מה היא מטמאה באבן מסמא אף מדוה נמי מטמאה באבן מסמא","אמר רב אשי אמר קרא (ויקרא טו, י) והנושא אותם אותם מיעוטא הוא","ובשר המת מנלן אמר ר\"ל אמר קרא (ויקרא כב, ה) לכל טומאתו לכל טומאות הפורשות ממנו","רבי יוחנן אמר (במדבר יט, טז) או בעצם אדם או בקבר אדם דומיא דעצם מה עצם יבש אף כאן יבש","מאי בינייהו איכא בינייהו דאפריך אפרוכי","מיתיבי בשר המת שהופרך טהור התם דאקמח והוי עפרא","מיתיבי כל שבמת מטמא חוץ מן השינים והשער והצפורן ובשעת חבורן הכל טמא","אמר רב אדא בר אהבה דומיא דעצם מה עצם שנברא עמו אף כל שנברא עמו והאיכא שער וצפורן שנבראו עמו וטהורין","אלא אמר רב אדא בר אהבה דומיא דעצם מה עצם שנברא עמו ואין גזעו מחליף אף כל שנברא עמו ואין גזעו מחליף יצאו השינים שלא נבראו עמו יצאו שער וצפורן שאף על פי שנבראו עמו גזעו מחליף","והרי עור דגזעו מחליף ותנן הגלודה רבי מאיר מכשיר וחכמים פוסלין ואפילו רבנן לא קפסלי אלא דאדהכי והכי שליט בה אוירא ומתה ולעולם גזעו מחליף ותנינן אלו שעורותיהם כבשרן עור האדם","הא איתמר עלה אמר עולא דבר תורה עור אדם טהור ומאי טעמא אמרו טמא גזרה שמא יעשה אדם עורות אביו ואמו שטיחין לחמור","ואיכא דאמרי הרי עור דאין גזעו מחליף ותנן וחכמים פוסלין ואפי' רבי מאיר לא קא מכשר אלא דקריר בשרא וחייא ולעולם אין גזעו מחליף ואמר עולא דבר תורה עור אדם טהור","כי איתמר דעולא אסיפא איתמר וכולן שעבדן או שהילך בהן כדי עבודה טהורין חוץ מעור אדם ואמר עולא דבר תורה עור אדם כי עבדו טהור ומה טעם אמרו טמא גזרה שמא יעשה אדם עור אביו ואמו שטיחין","והרי בשר דגזעו מחליף וטמא אמר מר בר רב אשי בשר נעשה מקומו צלקת","אבל הזוב זוב מנלן דתניא (ויקרא טו, ב) זובו טמא לימד על הזוב שהוא טמא","והלא דין הוא לאחרים גורם טומאה לעצמו לא כ\"ש שעיר המשתלח יוכיח שגורם טומאה לאחרים והוא עצמו טהור אף אתה אל תתמה על זה שאע\"פ שגורם טומאה לאחרים הוא עצמו טהור ת\"ל זובו טמא לימד על הזוב שהוא טמא","ואימא ה\"מ במגע אבל במשא לא מידי דהוה אשרץ אמר רב ביבי בר אביי במגע לא איצטריך קרא דלא גרע משכבת זרע"],[[0,"אי מה","משא נדה חמור לטמא אבן מסמא אבן גדולה המושמה על הכלים ונדה נשאת עליה מטמאה בגדים שתחת האבן כדאמר בתורת כהנים אף משא דמה חמור לטמא באבן מסמא דיש מטמא במשא ואינו מטמא באבן מסמא במסכת שבת בפרק רבי עקיבא (שבת דף פב:) דאמרינן במשא כולי עלמא לא פליגי דמטמא כי פליגי באבן מסמא דאין משאו אלא בדבר הראוי לינשא אבל גדולה אינה מטלטלת להיות הטומאה נישאת עליה וגבי זב הוא דרבייה קרא:"],[1,"והנושא אותם","במשכב הזב כתיב ומשכב הזב הנישא על אבן מסמא מטמא כלים שתחתיה כדמפרש בתורת כהנים וכתיב אותם למעוטי דמה:"],[2,"לאחרים","לזב:"],[2,"לכל טומאות הפורשות","לא שנא לח ולא שנא יבש:"],[4,"דמפרך אפרוכי","שיבש יותר מדאי לר' יוחנן טהור דדומיא דעצם בעינן ועצם לא מיפרך:"],[5,"דאקמח","לשון טחינה כקמח:"],[6,"חוץ מן השינים","והא שינים דומיא דעצם הן וטהורין וקשיא לתרוייהו:"],[8,"","שינים לא נבראו עמו שגדלין לאחר זמן:"],[9,"אין גזעו מחליף","אם ניטל אינו חוזר:"],[9,"הגלודה","בהמה שנקלף עורה מפני טורח מלאכה או מחמת שחין:"],[9,"דתנן ר\"מ מכשיר","ואינה טרפה דהדרא בריא אלמא גזעו מחליף:"],[9,"אדהכי והכי","עד שהוא חוזר וגדל:"],[9,"שליט בה אוירא ומתה","הלכך טרפה:"],[10,"שטיחין","מרדעת לחמור:"],[11,"וחכמים פוסלין","דלא הדרא בריא אלמא אין גזעו מחליף:"],[11,"קריר עלה בשרא","מתקשה בשרה ונעשה כעור:"],[12,"אסיפא","סיפא דואלו שעורותיהן כבשרן:"],[12,"וכולן","העורות שמנו חכמים להיות מטמאין כבשר בפ' העור והרוטב:"],[12,"שעבדן או הילך בהן כדי עבודה","כדרך שרגילין לתת עור לפני דורסן ושיעור עבודה מפרש בברכות (דף טו) ובפסחים (דף מו.) כדי מיל:"],[12,"טהורין","שבטלן מתורת בשר:"],[12,"כי עבדו","נמי טהור דהא בטילה:"],[13,"נעשה מקומו צלקת","כלומר רושם נראה בה חריץ או גומא ואין כולו חוזר אבל שער וצפורן אין נטילתן ניכר:"],[15,"שעיר המשתלח","גורם טומאה למשלחו דכתיב (ויקרא ט״ז:כ״ו) והמשלח את השעיר וגו':"],[16,"","שרץ מטמא במגע ולא במשא:"]],[[0,"","אבן מסמא. פ\"ה אבן המונחת על גבי יתדות וזב יושב עליה וכלי תחת האבן וטמא מוכל אשר יהיה תחתיו וקשה דבת\"כ מפיק אבן מסמא מוכל המשכב וקרא דוכל אשר יהיה תחתיו מוקי בפרק בנות כותים (לעיל נדה לג.) לעליונו של זב ובת\"כ מוקי לה במרכב ועוד דאי מוכל אשר יהיה תחתיו נפקא אם כן אפילו כלים שאינן ראויים למשכב ומושב נמי ובתורת כהנים מוכח בהדיא דכלים שאינם ראויין למשכב ומושב אין להם אפילו טומאה קלה ועוד אמאי נקט אבן אפילו דף על גבי יתדות נמי ועוד מדקרי ליה מסמא משמע לשון שימה ומפרש רבינו תם ורבינו שמואל דאבן מסמא היינו אבן גדולה שהיא כבדה בגדים תחתיה וכבדה כל כך עד שאין ניכר כובד הזב היושב עליה ועל הבגדים ואין בה אלא טומאה קלה כדפי' לעיל והשתא אתי שפיר דמייתי בפ' בתרא (לקמן נדה סט:) והיתיאת אבן חדא ושומת על פום גובא שצריכה שימה ואתויי לפי שאינה קלה לטלטל אך קשה דבת\"כ מרבה אבן מסמא מוכל המשכב מטעם משכב ומושב ובכל הש\"ס משמע דהוה מטעם משא ובשמעתין ממעט לה מוהנושא אותם וכן לקמן בפרק בתרא (נדה דף סט:) תנן הזב והזבה מטמאין במשא עד שימוק הבשר ומפרש בגמרא מאי משא אבן מסמא ובשבת פרק רבי עקיבא (שבת דף פב:) קאמר כי פליגי באבן מסמא ובמתניתין קתני היסט ובתוספתא דכלים תניא אין טומאה לכלי חרס אלא מאוירו ובהסיטו על גבי אבן מסמא והיסט היינו משא כדאמרינן בהעור והרוטב (חולין קכד:) אטו נושא לאו מסיט הוא ועוד אי היסט מטעם משכב ומושב הא אמר בפרק ר\"ע (שבת פד.) דמדרס כלי חרס טהור וי\"ל דמה שקרא בכל הש\"ס משא היינו כגון שיד הטהור או רגלו תחת האבן והזב או דם הנדה על האבן דנראה דהטהור נשא את הזב או את הדם אבל כלים תחת האבן והזב יושב עליה הוי מטעם משכב ומושב והא דתנן במסכת זבים (פ\"ה מ\"ב) כיצד אצבעו של זב תחת הנדבך והטהור מלמעלה כו' נראה דהיינו היסטו על גבי אבן מסמא דתוספתא וכגון שהנדבך דוחק אצבעו של זב דאי לאו הכי הוי כאילו היה אויר בין אצבעו לנדבך דאין כאן טומאה כלל:"],[0,"","אף מדוה נמי מטמא באבן מסמא. ואם תאמר כיון דממעטינן מדוה מהיא לטמא משכב ומושב ממעטינן נמי מאבן מסמא דהא מכח משכב ומושב הוי טומאה לאבן מסמא כדתנן בת\"כ מנין לרבות עשר מצעות זו על גב זו ועל גביהן אבן מסמא תלמוד לומר כל המשכב ואור\"י דאבן מסמא נפקא לן משום דרשא דלא מטמא אלא אוכלין ומשקין ולהכי איצטריך למעוטי מדוה אף מאבן מסמא שהיא טומאה קלה:"],[5,"","מיתיבי בשר המת שהופרך טהור. וא\"ת ולימא ר' יוסי היא דאמר במתני' בשר שיבש טהור וי\"ל דלא אתיא כרבי יוסי מדקתני הופרך ולא קתני שיבש:"],[6,"","חוץ מן השינים. פ\"ה וקשה לתרוייהו וקשה דא\"כ תקשה ליה קרא דאו בעצם אלא נראה דלר\"ל לחוד פריך ופשיטא דשינים אינם בכלל עצם:"],[8,"","אלא אמר רב אדא. אינו חוזר בו ממה שאמר אלא מפרש והולך מעט מעט:"],[10,"","שמא יעשה שטיחין. וא\"ת והלא מת אסור בהנאה דגמרינן (ע\"ז דף כט:) שם שם מעגלה ערופה וי\"ל דטומאה חמירא להו טפי כדאמר בפרק ב' דיומא (דף כג.) ללמדך שקשה עליהם טומאת כלי יותר משפיכות דמים ועוד נראה דעור אינו בכלל בשר ליאסר בהנאה דהא עגלה ערופה נמי לא נפקא אלא מדכתיב בה כפרה כקדשים ועוד קדשים מותרין בהנאה לאחר זריקה שהוא זמן כפרה וניחא השתא דאיצטריך בשור הנסקל לא יאכל להנאת עורו דלא אתי מבשרו:"],[13,"","בשר נעשה מקומו צלקת ואין גזעו מחליף. הקשה רשב\"ם דאמר בסוף העור והרוטב (חולין קכח:) דבשר מן החי אינו מטמא באהל מה מת אינו עושה חליפין אף כל כו' ובשר עושה חליפין ותירץ דאין הכל אחד דגזעו מחליף משמע חוזר לגמרי וזה אינו עושה בבשר אבל עושה חליפין משמע שגדל קצת ולא לגמרי וזהו אף בבשר וא\"ת כיון דמעצם ילפינן נימא בהאי לישנא מה עצם שאינו עושה חליפין ונמעט אפילו בשר וי\"ל דשמא גם עצם מתחזק או גדל מעט אחר שחסר:"],[15,"","שעיר המשתלח יוכיח. ואם תאמר ולימא דם הנדה יוכיח שגורם משכב ומושב לנדה ודמה אמעיט לעיל מינייהו וי\"ל דאין זה יוכיח כיון שיש לו לדם טומאת משא כמו נדה וה\"נ ליהוי זוב כמו דם הנדה אבל שעיר המשתלח אין לו שום טומאה כלל:"]]],[["כי איצטריך קרא למשא ואימא במשא מטמא אדם ובגדים במגע אדם מטמא בגדים לא לטמא מידי דהוה אמגע נבלה","לא ס\"ד דתניא אחרים אומרים (ויקרא טו, לג) הזב את זובו לזכר ולנקבה מקיש זובו לו מה הוא לא חלקת בין מגעו למשאו לטמא אדם ולטמא בגדים אף זובו כן","והשתא דנפקא לן מהזב את זובו זובו טמא למה לי","אמר רב יהודה מדסקרתא איצטריך סד\"א שעיר המשתלח יוכיח שגורם טומאה לאחרים והוא עצמו טהור ואי משום הזב את זובו למניינא הוא דאתא","זוב חד זובו תרתי ובשלישי אקשיה רחמנא לנקבה","כתב רחמנא זובו טמא והשתא דאמר רחמנא זובו טמא הוא דרוש ביה נמי האי","והרוק רוק מנלן דתניא (ויקרא טו ) וכי ירוק יכול אע\"פ שלא נגע ת\"ל בטהור עד שיגע בטהור","אין לי אלא רוקו כיחו וניעו ומי האף שלו מנין ת\"ל וכי ירוק","אמר מר יכול אע\"פ שלא נגע מהיכא תיתי","סד\"א נילף רוק רוק מיבמה מה התם אע\"פ דלא נגע אף ה\"נ דלא נגע קמ\"ל","ואימר הני מילי במגע אבל במשא לא מידי דהוה אשרץ אמר ריש לקיש תנא דבי רבי ישמעאל אמר קרא בטהור מה שביד טהור טמאתי לך","ואימא במשא מטמא אדם ובגדים במגע אדם לטמא בגדים לא לטמא מידי דהוה אמגע נבלה","אמר ריש לקיש וכן תנא דבי רבי ישמעאל אמר קרא בטהור טהרה שטהרתי לך במקום אחר טמאתי לך כאן ואיזה זה זה מגע נבלה","ואימא כמשא דשרץ א\"כ נכתוב קרא באדם מאי בטהור ש\"מ תרתי","ומי האף מאי מי האף אמר רב בנגררין דרך הפה לפי שאי אפשר למי האף בלא צחצוחי הרוק ור' יוחנן אמר אפילו בנגררין דרך החוטם אלמא קסבר מעיין הוא ורחמנא רבייה","ורב נחשוב נמי דמעת עינו דאמר רב האי מאן דבעי דלסתמיה לעיניה ליכחול מעובד כוכבים ולוי אמר האי מאן דבעי דלימות ליכחול מעובד כוכבים","ואמר רב חייא בר גוריא מ\"ט דרב דלא אמר האי מאן דבעי דלימות הואיל ויכול לגוררן ולהוציאן דרך הפה ורב נהי דזיהרא נפיק דמעתא גופא לא נפיק","ת\"ש תשעה משקין הזב הן הזיעה והליחה סרוחה והריעי טהורין מכלום דמעת עינו ודם מגפתו וחלב האשה מטמאין טומאת משקין ברביעית אבל זובו רוקו ומימי רגליו מטמאין טומאה חמורה ואילו מי האף לא קתני","בשלמא לרב לא קתני דלא פסיקא ליה למתני זימנין דאתי דרך הפה וזימנין דאתי דרך החוטם אלא לר' יוחנן ליתני","ולטעמיך כיחו וניעו מי קתני אלא תנא רוק וכל דאתא מרבויא הכא נמי תנא רוקו וכל דאתא מרבויא","דמעת עינו דכתיב (תהלים פ, ו) ותשקמו בדמעות שליש ודם מגפתו דכתיב (במדבר כג, כד) ודם חללים ישתה מה לי קטליה כוליה מה לי קטליה פלגיה חלב האשה דכתיב (שופטים ד, יט) ותפתח את נאד החלב ותשקהו","מימי רגליו מנלן דתניא זובו טמא וזאת לרבות מימי רגליו לטומאה והלא דין הוא ומה רוק הבא ממקום טהרה טמא מימי רגליו הבאין"],[[0,"נבלה","במגע מטמאה אדם ולא בגדים שעליו ובמשא מטמאה אדם ובגדים שעליו כדכתיב (ויקרא י״א:כ״ז-כ״ח) והנוגע בנבלתה יטמא עד הערב והנושא את נבלתה יכבס בגדיו אבל במגע לא כתיב כבוס: זב אפילו מגעו מטמא בגדים דכתיב והנוגע בבשר הזב יכבס בגדיו וכן משאו דכתיב במשכב ומושב והנושא אותם יכבס בגדיו וקל וחומר לנושא זב עצמו:"],[2,"והשתא דנפקא לן","טומאת הזב מוהזב את זובו דאיתקש זובו לו זובו טמא למה לי:"],[4,"זב חדא זובו תרתי","וכתיב לזכר דבשתי ראיות ראשונות דין זכר עליו שאינו מטמא באונס ומכאן ואילך איתקש לנקבה דאפילו ראה שלישי באונס חייב קרבן:"],[5,"והשתא דכתיב זובו טמא","דנפקא לן מיניה עיקר טומאת זוב מהשתא דרוש מוהזב את זובו הך דרשא דלא תחלוק בין מגעו למשאו ואע\"פ שאתה דורשו לדרשא אחריני:"],[7,"כיחו וניעו","מין רוק הן:"],[7,"תלמוד לומר וכי ירוק","וי\"ו דריש:"],[10,"במה שביד טהור","אם רק במה שביד טהור דהוה ליה טהור נושא את הרוק:"],[12,"זה מגע נבלה","שטהרתי לך בגדים שעליו וטמאתים לך כאן במגע הרוק:"],[13,"ואימא משא דשרץ","שטהרתי לך את הנושאו טמאתי לך בכאן בנושא הרוק אבל מגעו כנבלה:"],[13,"לימא באדם","דדרשינן במה שביד אדם והיינו משאו ובלאו דרשא דטהרה שטהרתי לך וכו' נפקא לן משא:"],[13,"מאי בטהור","דמשמע טהרה שטהרתי במקום אחר טמאתי בכאן:"],[13,"ש\"מ תרתי","משא מרבויא דבי\"ת שבטהור ומגע לטמא בגדים מטהור:"],[14,"בנגררין דרך הפה","שגררן והוציאן דרך הפה:"],[14,"ורחמנא רבייה","מכי ירוק כל דדמי לרוק:"],[15,"ורב","כיון דלאו מעין הוא אלא מפני שגררן דרך פיו קתני לה ומשום צחצוחי הרוק:"],[15,"ליחשוב נמי","במתניתא דמעת עינו ונוקמה בשגוררה דרך הפה דהאמר רב אפשר לגוררה דרך הפה:"],[15,"דאמר רב האי מאן דבעי דלסתמיה","שיתעוור:"],[15,"","ליכחול עיניה מעובד כוכבים ולוי אמר כו' מאי טעמא דרב דלא אמר לימות. דסבר אם נתן העובד כוכבים לתוכו סם המות יכול לגוררו ולהוציאו דרך פיו כדרך הרוקקין שמושכין מי האף בפיהם ע\"י רוח נשימתם לגופן:"],[16,"זיהרא","ארס של סם המות:"],[17,"ליחה סרוחה","קויטור\"א:"],[17,"מגפתו","מכתו:"],[17,"טומאת משקין","לטמא אוכלין ומשקין כשאר משקין טמאים:"],[17,"ברביעית","זהו שיעור משקין לטומאה:"],[17,"טומאה חמורה","אדם ובגדים דמעיינות הן:"],[18,"בשלמא לרב","דאמר האי דקתני להו תנא דלעיל בנגררין דרך הפה איכא לתרוצי דהאי תנא להכי לא תני להו דכיון דטומאתן לאו מחמת עצמן היא אלא משום צחצוחי רוק לא פסיקא ליה דהא זימנין דנפקי דרך חוטם וטהורין ובמילתא דלא פסיקא לא קמיירי:"],[18,"אלא לרבי יוחנן","דאמר לעולם טמאין ליתני:"],[20,"ותשקמו בדמעות שליש","אלמא משקה איקרו:"],[20,"דם חללים ישתה","אלמא דם חלל איקרי משקה ודם מגפתו נמי דם חללים הוא דהא קטליה פלגיה:"],[21,"זובו טמא וזאת","דסמיך ליה וזאת תהיה טומאתו וגו' ודרשי האי וזאת אקרא דלעיל זובו טמא וזאת כלומר דבר אחר נמי כזוב:"]],[[0,"","כי איצטריך קרא למשא. וא\"ת למשא נמי לא איצטריך מההיא טעמא דלא גרע משכבת זרע דהא בזב קיימין ואיכא למ\"ד סוף פ\"ב דב\"ק (דף כה.) שכבת זרע מטמאה במשא אפילו בלא ציחצוחי זיבה מק\"ו ומה טהור בטהור פירוש רוק טמא בטמא טמא בטהור שכבת זרע אינו דין שיהא טמא בטמא ויש לומר דלא קשה מידי דאין לנו לעשות זאת הזיבה שהיא גורמת טומאה דהיינו ראייה שניה משאם היתה שכבת זרע וקרי שאחר ראייה ראשונה טהור ממשא שאינו זב וה\"ק דלא גרע מאילו היתה ראייה זו שכבת זרע דמטמא במגע ולא במשא ומק\"ו לא אתי דאין זה טמא בטמא דאכתי אינו טמא אלא על ידי ראייה זו הוא נעשה טמא וא\"ת כיון דמגע נפקא לן בלא קרא היכי שייך לומר שעיר המשתלח יוכיח הא לא דמי דבזוב איכא טומאת מגע וכי האי גוונא אמר בפרק כל הבשר (חולין קטו:) גבי בשר בחלב דיליף איסור אכילה מואנשי קדש תהיון ואיסור הנאה מערלה מק\"ו ופריך ונילף כולה מילתא מערלה ומשני משום דאיכא למימר חוסם פי פרה ודש בה וחורש בשור וחמור יוכיח שנעבדה בהן עבירה ומותרין אף באכילה אבל עכשיו דנפקא לן איסור אכילה מקרא ליכא למימר תו יוכיח דלא דמי דאינהו שרי באכילה ויש לומר דשעיר המשתלח נמי כיון דמטמא אחרים העוסקין בו אינו טהור גמור ושייך לטומאת עצמו והוי כאילו טמא במגע ודמיא לזוב:"],[7,"","כיחו וניעו. כיחו הוא הבא מכח רב מן החזה ניעו ע\"י נענוע מעט כך מפרש ר\"ת ויש לפרש נמי איפכא ניעו שמנענע כל גופו כיחו בכח מעט ובמתני' דלא תנא כיחו לא חש להאריך אבל תימה דתנן ניעו מקמי רוק דעיקר דכתיב בהדיא וי\"ל דהך דאתיא מדרשא חביבא ליה:"],[9,"","נילף רוק רוק מיבמה. תימה דהשתא נילף רוק דיבמה מהכא דנגע ויש לומר דבסיפרי דרשינן ליה מקרא דלא בעינן נגע וירקה בפניו יכול בפניו ממש ת\"ל לעיני הזקנים רוק הנראה לזקנים:"]]],[["ממקום טמא אינו דין שיהו טמאין דם היוצא מפי האמה יוכיח שבא ממקום טמא וטהור אף אתה אל תתמה על זה שאע\"פ שבא ממקום טומאה יהיה טהור ת\"ל זובו טמא וזאת לרבות מימי רגליו לטומאה","דם היוצא מפי האמה מנלן דטהור דתניא יכול יהא דם היוצא מפיו ומפי האמה טמאין ת\"ל (ויקרא טו, ב) זובו טמא הוא הוא טמא ואין דם היוצא מפיו ומפי האמה טמא אלא טהור","ואיפוך אנא אמר רבי יוחנן משום רבי שמעון בן יוחי דומיא דרוק מה רוק שמתעגל ויוצא אף כל שמתעגל ויוצא יצא דם שאין מתעגל ויוצא","והרי חלב שבאשה שמתעגל ויוצא ואמר מר חלב שבאשה מטמא טומאת משקין טומאת משקין אין אבל לא טומאה חמורה","אלא אמר ר' יוחנן משום רבי שמעון בן יוחי דומיא דרוק מה רוק מתעגל ויוצא וחוזר ונבלע אף כל מתעגל ויוצא וחוזר ונבלע יצא דם שאינו מתעגל ויוצא יצא חלב שבאשה שאע\"פ שמתעגל ויוצא אינו חוזר ונבלע","ונילף מזובו מה זובו שאין מתעגל ויוצא מטמא אף כל אמר רבא מזובו ליכא למילף שכן גורם טומאה לאחרים","והשרץ אמר ריש לקיש שרץ שיבש ושלדו קיימת טמא והאנן תנן מטמאין לחין ואין מטמאין יבשין אמר רבי זירא לא קשיא הא בכולן הא במקצתן","דתניא א\"ר יצחק ברבי ביסנא אמר רבי שמעון בן יוחי (ויקרא י״א:כ״ו) בהם יכול בכולן ת\"ל מהם","אי מהם יכול במקצתן תלמוד לומר בהם הא כיצד כאן בלח כאן ביבש","אמר רבא הני זבוגי דמחוזא כי שלדן קיימת טמאין ואמר ריש לקיש שרץ שנשרף ושלדו קיימת טמא","מיתיבי נמצא שרץ שרוף על גבי הזיתים וכן מטלית המהוהא טהורין שכל הטמאות כשעת מציאתן א\"ר זירא לא קשיא הא בכולן הא במקצתן","דתניא אמר רבי יצחק בר' ביסנא משום ר\"ש בן יוחי בהם יכול בכולן ת\"ל מהם","אי מהם יכול במקצתן ת\"ל בהם הא כיצד כאן בשרוף כאן בשאינו שרוף","מטמאין לחין זב דכתיב (ויקרא טו, ג) רר בשרו כיחו וניעו ורוקו דכתיב (ויקרא טו, ח) כי ירוק הזב כעין רוק","שרץ (ויקרא יא) במותם אמר רחמנא כעין מיתה שכבת זרע הראויה להזריע נבלה דכתיב (ויקרא יא, לט) כי ימות כעין מיתה","אם יכולין להשרות בעי רבי ירמיה תחילתו וסופו בפושרין או דלמא תחילתו אף על פי שאין סופו","ת\"ש דתניא כמה היא שרייתן בפושרין יהודה בן נקוסא אומר מעת לעת תחילתו אף על פי שאין סופו רשב\"ג אומר צריכין שיהו פושרין מעת לעת","רבי יוסי אומר בשר המת כו' אמר שמואל טהור מלטמא בכזית אבל מטמא טומאת רקב תניא נמי הכי רבי יוסי אומר בשר המת שיבש ואין יכול לשרות ולחזור כמות שהיה טהור מלטמא בכזית אבל טמא טומאת רקב","\u0001מתני׳\u0002 השרץ שנמצא במבוי מטמא למפרע עד שיאמר בדקתי את המבוי הזה ולא היה בו שרץ או עד שעת כבוד","וכן כתם שנמצא בחלוק מטמא למפרע עד שיאמר בדקתי את החלוק הזה ולא היה בו כתם או עד שעת הכבוס","ומטמא בין לח בין יבש ר\"ש אומר היבש מטמא למפרע והלח אינו מטמא אלא עד שעת שיהא יכול לחזור ולהיות לח","\u0001גמ׳\u0002 איבעיא להו עד שעת כבוד חזקתו בדוק או דלמא חזקתו מתכבד","ומאי נפקא מינה דאמר כביד ולא בדיק אי אמרת חזקתו בדוק הא לא בדק אי אמרת חזקתו מתכבד הא מתכבד"],[[0,"ממקום טומאה","ממקום שזובו יוצא שהוא טמא בשבילו:"],[1,"דם היוצא מפי אמתו","של זב גמור יליף ליה לקמן דטהור:"],[1,"יכול דם היוצא מפיו","של זב יהא נדון כרוק ודם היוצא מפי אמתו יהא נדון כזוב:"],[2,"ואיפוך אנא","וזאת לרבות דם והוא להוציא מי רגלים:"],[2,"שמתעגל","מתאסף הרבה כאחד ואח\"כ יוצא כגון רוק ומי רגלים ושכבת זרע: דם אין מתעגל ויוצא דכי אתא קמא קמא נפיק:"],[4,"וחוזר ונבלע","כשאינו מוציאו:"],[5,"אף כל כו'","כגון סילון של מי רגלים חוזר ונבלע יצא דם שאינו מתעגל ויוצא חלב אע\"ג שמתעגל אינו חוזר ונבלע:"],[6,"ושלדו","דפוס צורתו:"],[6,"קיימת","שלא נשבר ונתפזר:"],[6,"בכולן","בשכולו שלם טמא אפילו יבש:"],[7,"בהם","בשרצים כתיב (ויקרא י״א:כ״ו) כל הנוגע בהם:"],[7,"מהם","וכל אשר יפול עליו מהם במותם יטמא (שם):"],[9,"זבוגי","פרוי\"ט הנמצאים יבשים במחוזא והוא צב ויש שקורין אותו בלע\"ז בו\"ט:"],[10,"המהוהא","בלויה ונרקבת:"],[13,"רר","כעין ריר שהוא לח כמו (שמואל א כ״א:י״ד) ויורד רירו על זקנו:"],[15,"תחילתו אע\"פ שאין סופו","אין צריך שיהו המים פושרין בסוף כשיכלה מעת לעת:"],[16,"יהודה בן נקוסא אומר","אין צריך שיהו המים פושרין בסוף אכן יהו על השרץ כמעת לעת אע\"פ שאין סופן וקולא היא דאי לא הדר בהכי טהור ואע\"ג דאי הוו פושרין כל מעת לעת הוה הדר:"],[17,"טומאת רקב","מלא תרווד ממנו מטמא במגע ומשא ואהל:"],[20,"מתני' ומטמא בין לח ובין יבש","הכתם או השרץ בין שנמצאו לחין בין שנמצאו יבשין מטמא כל טהרות שנמצאו במבוי מיום כיבודו ושעשתה האשה מיום כבוס:"],[20,"היבש מטמא למפרע","עד שעת כיבוד או כיבוס דאיכא למימר לאחר כיבוס מיד נפל. אבל הלח אינו מטמא למפרע אלא עד שעה שנוכל לומר אם נפל באותו יום עדיין הוא יכול להיות עכשיו לח אבל עד שעת הכיבוד לזמן מרובה לא דהא לח הוא ואי מההיא שעתא נפל הוה מתעביד יבש:"],[21,"גמ' חזקתו בדוק","מי מחזקינן דבדיק ליה בשעת הכיבוד ומשום הכי טהרות דקודם כיבוד טהורות:"],[21,"או משום דחזקתו מתכבד","דאי הוה התם בשעת כיבוד הוי נפיק האי שרץ מחמת כיבוד:"],[22,"דאמר כביד ולא בדיק","כבדתיו ולא בדקתיו. אי אמרת דהא דמטהרין הנך דמקמי כיבוד משום דחזקתו שבדקו בשעת כיבוד הא לא בדיק וטהרות דמקמי כיבוד נמי טמאו' ואי אמרת כו':"]],[[0,"","דם היוצא מפיו טהור. בפרק מצות חליצה (יבמות דף קה.) מוקי בשותת דאי לאו הכי טמא משום צחצוחי הרוק:"],[0,"","דם היוצא מפי האמה. ואם תאמר הא כבר ממעטינן בריש בנות כותים (לעיל נדה דף לב:) איש מאודם ויש לומר דהיינו דאין נעשה זב ע\"י ראיית אודם אבל אם כבר נעשה זב ליהוי דם היוצא מפי האמה טמא כמו רוקו ולכך צריך קרא הכא למעוטי:"],[0,"","וזאת לרבות מימי רגליו לטומאה. מוי\"ו דוזאת קדריש כי היכי דדרשינן לעיל כיחו וניעו מוי\"ו דוכי ירוק אבל זאת בכל דוכתי אתא למעוטי והאי זאת נמי אתא למעוטי דבת\"כ מצריך תרי מיעוטי זאת וטמא הוא חד למעוטי זיעה וליחה סרוחה וחד למעוטי דם היוצא מפיו ומפי האמה:"],[2,"","מה רוק שמתעגל ויוצא כו'. מכח ריבויא דוכי ירוק הזב בטהור ודוזאת דריש הכי אבל אי לאו הני קראי הוה ממעטינן כולהו כיחו וניעו ומי רגלים מטמא הוא כמו דם היוצא מפי האמה וא\"ת ולמה לי תרי קראי וכי ירוק לכיחו וניעו וזאת למי רגלים וי\"ל דמוכי ירוק לא הוה דרשינן אלא כיחו וניעו שיוצא דרך הפה או מי האף נמי לרבי יוחנן דדמי כמו רוק ומוזאת לא הוה מרבינן אלא מי רגלים שיוצאין מפי האמה כמו זוב דקרא דוזאת גבי זוב כתיב או משום דבאין ממקום טמא מיהו קשה דמשמע דהוה מרבינן חלב האשה מוזאת אם היה חוזר ונבלע ואמאי והא אפילו כיחו וניעו לא הוה מתרבי מוזאת אי לאו ריבויא דוכי ירוק וצריך לומר דאי לאו ריבויא דוכי ירוק הוה מוקמינן וזאת לכיחו וניעו דוקא דהוי כעין רוק אבל השתא דכתיב וכי ירוק אייתר וזאת לכל דבר המתעגל ויוצא וחוזר ונבלע:"],[5,"","ונילף מזובו. אי זיבה לאו מעין הוה דבעיא היא בפרק בנות כותים (לעיל נדה לד:):"],[8,"","אי בהם אי מהם כו'. ואע\"ג דמהאי בהם ומהם דרשינן בפ\"ק דחגיגה (דף יא.) ששיעורו בכעדשה התם אסמכתא הוא דשיעורים הלכה למשה מסיני:"],[9,"","שרץ שנשרף. ק\"ק דלא עריב יבש ושרוף בהדי הדדי דמחד קרא קדריש להו:"],[14,"","שכבת זרע בראויה להזריע. ואם תאמר והלא שכבת זרע שאינו יורה כחץ אינו ראוי להזריע ומטמא ויש לומר דמין ראוי להזריע בעינן ואפי' שאינו יורה כחץ כיון שהוא לח חשיב מין שכבת זרע הראוי להזריע:"]]],[["אי נמי דאשתכח בגומא אי אמרת חזקתו בדוק מאן דבדק בגומא נמי בדיק אי אמרת חזקתו מתכבד גומא לא מתכבדא","וכן הכתם וכו' איבעיא להו עד שעת כבוס חזקתו בדוק או דלמא חזקתו מתכבס","למאי נפקא מינה דאמר כיבס ולא בדק אי אמרת חזקתו בדוק הא לא בדק אי אמרת חזקתו מתכבס הא מתכבס","אי נמי דאשתכחה בסטרא אי אמרת חזקתו בדוק מאן דבדק בסטרא נמי בדיק אי אמרת חזקתו מתכבס בסטרא לא מתכבס","מאי תא שמע דתניא א\"ר מאיר מפני מה אמרו השרץ שנמצא במבוי מטמא למפרע עד שיאמר בדקתי את המבוי הזה ולא היה בו שרץ או עד שעת כיבוד מפני שחזקת בני ישראל בודקין מבואותיהן בשעת כבודיהם ואם לא בדקו הפסידוהו למפרע","ומפני מה אמרו כתם שנמצא בחלוק מטמא למפרע עד שיאמר בדקתי את החלוק ולא היה בו כתם או עד שעת הכבוס מפני שחזקת בנות ישראל בודקות חלוקיהן בשעת כבוסיהן ואם לא בדקו הפסידו למפרע","ר' אחא אמר תחזור ותכבסנו אם נדחה מראיתו בידוע שלאחר כבוס ואם לאו בידוע שלפני הכבוס","רבי אומר אינו דומה כתם שלאחר הכבוס לכתם שלפני הכבוס שזה מקדיר וזה מגליד ש\"מ חזקתו בדוק ש\"מ","ומטמא בין לח וכו' א\"ר אלעזר לא שנו אלא שרץ אבל כתם לח נמי מטמא למפרע אימר יבש היה ומיא נפיל עליה","שרץ נמי אימר יבש היה ומיא נפיל עליה אם איתא דהכי הוא אמרטוטי אימרטט","\u0001מתני׳\u0002 כל הכתמין הבאין מרקם טהורין רבי יהודה מטמא מפני שהם גרים וטועין הבאין מבין העובדי כוכבים טהורין מבין ישראל ומבין הכותים רבי מאיר מטמא וחכמים מטהרים מפני שלא נחשדו על כתמיהן","\u0001גמ׳\u0002 קפסיק ותני אפילו מתרמוד א\"ר יוחנן זאת אומרת מקבלין גרים מתרמוד","איני והא רבי יוחנן וסביא דאמרי תרוייהו אין מקבלין גרים מתרמוד","וכי תימא זאת ולא סבירא ליה והאמר רבי יוחנן הלכה כסתם משנה","אמוראי נינהו ואליבא דרבי יוחנן","מבין ישראל וכו' ורבנן אי דישראל מטהרי דמאן מטמו","חסורי מחסרא והכי קתני מבין ישראל טמא מבין הכותים רבי מאיר מטמא דכותים גרי אמת הן וחכמים מטהרין דכותים גרי אריות הן","אי הכי שלא נחשדו על כתמיהן גרי אריות מבעי ליה","אלא הכי קאמר מבין ישראל ומבין הכותים טמאין דכותים גרי אמת הן הנמצאין בערי ישראל טהורין שלא נחשדו על כתמיהם ואצנועי מצנעי להו","הנמצאין בערי כותים רבי מאיר מטמא דנחשדו על כתמיהם וחכמים מטהרין שלא נחשדו על כתמיהן","\u0001מתני׳\u0002 כל הכתמים הנמצאים בכל מקום טהורין חוץ מן הנמצאים בחדרים ובסביבות בית הטמאות","בית הטמאות של כותים מטמאין באהל מפני שהם קוברין שם את הנפלים ר' יהודה אומר לא היו קוברין אלא משליכין וחיה גוררתו","נאמנים לומר קברנו שם את הנפלים או לא קברנו נאמנים לומר על הבהמה אם בכרה אם לא בכרה נאמנים על ציון קברות","ואין נאמנין לא על הסככות ולא על הפרעות ולא על בית הפרס","זה הכלל דבר שחשודים בו אין נאמנין עליו \u0001גמ׳\u0002"],[[0,"אי נמי","בסתמא דלא אמר לא בדקתי ואשתכח שרץ בגומא:"],[3,"בסטרא","בצדי הבגד שיש שם קמטים ותפירות שקורין וירונ\"ש:"],[4,"מפני מה אמרו כו'","כלומר מפני מה תלו בכיבוד וטיהרו טהרות דקודם כיבוד:"],[4,"למפרע","אפילו דקודם כיבוד טמאות:"],[5,"ומפני מה אמרו","ומפני מה תלו טהרה בכבוס:"],[6,"תחזור ותכבסנו","אם לא בדקתו בשעת כבוסו ולאחר זמן נמצא בו כתם ואין ידוע אם קודם כבוס היה בו לטמא טהרות של קודם לכן:"],[6,"אם נדחו מראיו","מחמת כבוס זה:"],[6,"בידוע שלאחר כבוס","ראשון נפל בו וטהרות של קודם כבוס ראשון טהורות דאי קודם כבוס קמא הוה ביה כבר נדחו מראיו מחמת כבוס ראשון:"],[7,"מקדיר","נכנס בבגד טרשטריי\"ש. כתם שלפני כבוס מגליד וגלדו עבה:"],[8,"לא שנו","אדר' שמעון קאי:"],[8,"למפרע","עד שעת הכבוס:"],[10,"מתני' באין מרקם טהורים","שהן עובדי כוכבים ודמן טהור:"],[10,"שהן גרים","ודמן טמא:"],[10,"וטועין","שאין מצניעין את כתמיהם:"],[10,"וחכמים מטהרין","בגמרא פריך ואי דישראל טהור דמאן טמא:"],[10,"שלא נחשדו","ומכבסין אותם:"],[11,"גמ' קא פסיק ותני","הבאין מבין העובדי כוכבים טהורין ואפילו מתרמוד אלמא בני תרמוד עובדי כוכבים גמורים הן:"],[11,"זאת אומרת מקבלין גרים מן התרמוד","וכשרין לבא בקהל ולא אמרינן ממזרים הן שנתערבו בבנות עשרת השבטים ועובד כוכבים ועבד הבא על בת ישראל הולד ממזר:"],[17,"גרי אריות הן","מפורש בספר מלכים (ב יז) וישלח ה' בהם את האריות וגו':"],[18,"גרי אמת הן","ודמן טמא:"],[18,"בערי ישראל","במקום גלוי:"],[19,"נחשדו על כתמיהן","דלא מצנעי להו:"],[20,"מתני' בכל מקום","במקום ישראל:"],[20,"בחדרים","מסתמא מדאצנעי דם נדה הוא:"],[20,"בית הטמאות","חדר שהנשים משתמשות בו בימי נדותן:"],[23,"סככות ופרעות","בגמ' מפרש להו וספק נינהו ומדרבנן וכותיים לית להו:"]],[[0,"","בגומא נמי בדיק. והא דאמר בפ\"ק דפסחים (דף ז.) דגומא אינה נבדקת גבי תיבה שנשתמשו בה מעות מעשר שני התם בחריץ המכוסה בקרשי התיבה דההיא גומא אינה נבדקת:"],[1,"","וכן הכתם עד שעת כבוס חזקתו בדוק כו'. ל\"ג איבעיא להו דקאי אאיבעיא להו דלעיל גבי שרץ:"],[5,"","בודקות חלוקיהן בשעת כבוסיהן. לאחר הכבוס בודקות ואם לא מצאה הכתם טהור החלוק אע\"פ שהיה בו בודאי כתם קודם כבוס וכגון שהטבילתו והא דאמר לקמן בפרק האשה (נדה דף סא.) בגד שאבד בו כתם מעבירים עליו ז' סממנים לבטלו ה\"ה דאזיל ליה לכתם ע\"י כבוס סתם והא דמסיק דאין חזקתו מתכבס היינו כשהכתם בסיטרא או בזוית אי נמי ע\"י כבוס סתם לא אזיל ובודקות חלוקיהן היינו לפני כבוס ואי מצאה הכתם מעבירה עליו ז' סממנים או תעשה כבוס גמור וטוב דהא חזינן דע\"י כבוס טוב הולך הכתם בלא סממנים:"],[7,"","שמע מינה חזקתו בדוק. והא דאמר בפ\"ק דפסחים (דף ז.) ובאלו מציאות (ב\"מ דף כו.) מעות שנמצאו בירושלים בשאר ימות השנה חולין לפי ששוקי ירושלים עשויין להתכבד בכל יום לא שחזקתן מתכבדים אלא בשעת כבוד רגילים לעיין ולחפש אם יש שם מעות אי נמי כשבודקין השוקים שלא יהא שם עצם כשעורה או כעדשה מן השרץ אם היו שם מעות היו נמצאות:"],[10,"","הבאים מרקם. ר\"ת גריס רקס דאילו ברקם היו ישראל כדאמר בריש מסכת גיטין (דף ב.) אף המביא מן הרקם ומן החגר ולא קשה מידי דטובי רקם הוו כדפרישית שם ועוד אע\"ג דברקם ישראל הוו קאמר הכא דכתמן טהורין דישראל מצניעים כתמיהן אלא של עובדי כוכבים הן וטהורין ורבי יהודה מטמא משום שיש שם גרים וטועים להשתמש אי נמי הכא איירי בידוע שהן של עובדי כוכבים הדרים שם:"],[10,"","מבין העובדי כוכבים טהורים. אע\"ג דבפרק בנות כותים (לעיל נדה לד.) אמר דדם עובדת כוכבים מטמא כרוקה וכמימי רגליה בכתמים דרבנן לא גזרו עליהם:"],[14,"","אמוראי נינהו כו'. ואם תאמר א\"כ מ\"מ תקשה לרבי יוחנן דאמר אין מקבלין גרים מן התרמוד אע\"ג דסתם מתניתין דעשרה יוחסין (קדושין דף עה:) ודפרק אלמנה (יבמות סח:) וכמה תנאי סברי דעובד כוכבים ועבד הבא על בת ישראל הולד ממזר מ\"מ תקשה ליה ממתניתין דסברה דלא באו עובדי כוכבים על בנות ישראל דאי באו הוי כתמן טמא דבין אם הולד ממזר או כשר ישראל הוי ויש לומר דרבי יוחנן וסביא סברי כדתני רמי בר יחזקאל בפ\"ק דיבמות (דף טז.) דאין מקבלין גרים מן הקרמיין ומן התרמודין דפליג אמתניתין דהכא דמטהר כתמי כל העובדי כוכבים ולא בעי לשנויי לא לבר מתרמוד כדמשני בפ\"ק דגיטין (דף ו.) לא לבר מבבל מדמחלק ברקם ולא בשאר עובדי כוכבים משמע דכולהו טהורים:"],[18,"","לא נחשדו על כתמיהם. ואע\"ג דכתמים דרבנן הך טומאה אית להו דסברה דמגופה אתא:"],[21,"","קוברין שם הנפלים. ואם תאמר והיאך משתמשים שם בימי טומאתן והלא נזהרים הם מטומאת מת ונפלים כדתניא נאמנים לומר לא קברנו שם הנפלים ומוקי לה בגמרא בכותי כהן עומד שם ובפרק בנות כותים (לעיל נדה דף לג.) אמר דנשוי מטמא משום בועל נדה אבל פנוי לא וי\"ל דלפי שעה קוברין שם נפלין ולאחר זמן מסלקין אותם לקוברן בבית הקברות ואין אנו יודעין מתי מסירין אותן:"]]],[["מאי דרוש (דברים יט, יד) לא תסיג גבול רעך אשר גבלו ראשונים בנחלתך","כל שיש לו נחלה יש לו גבול כל שאין לו נחלה אין לו גבול","נאמנים לומר קברנו והא לית להו (ויקרא יט, יד) ולפני עור לא תתן מכשול א\"ר אבהו בכהן עומד שם","ודילמא כהן טמא הוא דנקיט תרומה בידיה ודילמא תרומה טמאה היא דקאכיל מינה","אי הכי מאי למימרא מהו דתימא לא בקיאי ביצירה קמ\"ל","נאמנין על הבהמה וכו' והא לית להו ולפני עור לא תתן מכשול א\"ר חייא בר אבא א\"ר יוחנן בגוזז ועובד","אי הכי מאי למימרא מהו דתימא לא בקיאי בטינוף קמ\"ל","נאמנין על ציון וכו' ואע\"ג דמדרבנן הוא כיון דכתיבא מזהר זהירי ביה דכתיב (יחזקאל לט, טו) וראה עצם אדם ובנה אצלו ציון","אבל אין נאמנין לא על הסככות וכו' סככות דתנן אלו הן סככות אילן המיסך על הארץ פרעות דתנן אבנים פרעות היוצאות מן הגדר","בית הפרס א\"ר יהודה א\"ר שמואל מנפח אדם בית הפרס והולך","רב יהודה בר אמי משמיה דרב יהודה אמר בית הפרס שנידש טהור ותנא החורש בית הקברות הרי זה עושה בית הפרס ועד כמה הוא עושה מלא מענה מאה אמה בית ארבעת סאין רבי יוסי אומר חמש","ולא מהימני והתניא שדה שאבד בה קבר נאמן כותי לומר אין שם קבר","לפי שאינו מעיד אלא על גופו של קבר אילן שהוא מיסך על הארץ נאמן לומר אין תחתיו קבר לפי שאינו מעיד אלא על גופו של קבר","א\"ר יוחנן במהלך ובא על פני כולה","אי הכי מאי למימרא מהו דתימא רצועה נפקא קמ\"ל","זה הכלל כו' זה הכלל לאתויי מאי לאתויי תחומין ויין נסך","\u0001הדרן עלך דם הנדה\u0002"],[[0,"מאי דרוש","כותיים שאין קוברים את הנפלים:"],[0,"לא תסיג גבול רעך","ומוקמינן לה בספרי במוכר קברי אבותיו:"],[2,"נאמנין לומר קברנו","דמידי דאורייתא הוא טומאת המת:"],[2,"והא לית להו ולפני עור לא תתן מכשול","לא דרשי ליה במחטיא את חבירו ולא איכפת להם אם אנו חוטאים על פיהם:"],[2,"בכהן","כותי עומד שם:"],[3,"דקאכיל מינה","ותרומה טמאה באזהרה לטהור וכ\"ש לטמא:"],[4,"לא בקיאי ביצירה","וכי קברי נפל לא ידעי דהוא בן מ' יום וסברי מיא בעלמא הוא ואינו מטמא:"],[6,"בטינוף","בבהמה דקה ופוטר את הבהמה מן הבכורה ובבכורות (דף כא:) מפרש מאי טינוף שמבצבצת ומוציאה דם דרך רחם וזהו הולד שנימוח ויוצא הלכך הבא אחריו אינו בכור והני כותיים לא בקיאי בטינוף וזימנין דלא טניף ואמרו טינוף הוא ופוטרין את הבא אחריו קמ\"ל:"],[7,"על ציון","לציין וסומכין עליהן ועבדינן טהרות היכא דלא ציינו:"],[8,"אילן המיסך על הארץ","והוא סמוך לדרך בית הקברות וזימנין דמיתרמי בין השמשות וקברי התם ואם הענפים מובדלים שאין האהל שלם וידוע ודאי שיש קבר תחת האהלות ואין ידוע איזה הוא והכותי מעיד על אחד זה טהור אינו נאמן לפי שאינו חש על הספק ותולה הטומאה באהל שני מספק:"],[8,"פרעות","גדולות ובולטות מן הגדר וקברו תחת אחת מהן ואין אנו יודעין תחת איזהו מהן ובא כותי והעיד על מקצתן שהן טהורות אינו נאמן משום דלספקא לא חייש ותולה הספק באחרות:"],[9,"בית הפרס","שדה שנחרש בה קבר ואוקמי רבנן על סביבות הקבר מאה אמה בספק טומאה שדיקדקה המחרישה את העצמות ומגלגלתן:"],[9,"מנפח","דבשר ליכא ועצם כשעורה לא מטמא אלא במגע ובמשא הלכך מנפח כדי שלא יגעו רגליו בו והולך:"],[10,"שנידש","ברגלי אדם שהרגלים נושאים את העצמות ושחקום:"],[10,"פרס","לשון דבר שבור ופרוס על שם שנפרסו העצמות:"],[10,"בית ארבעת סאין","היינו ק' על ק' שהרי חצר המשכן מאה על חמשים והוא בית סאתים:"],[11,"שדה שאבד בה קבר","מיקרי נמי בית הפרס ורבנן גזרו בכולה דתניא במועד קטן (דף ה:) ג' בית הפרס הן שדה שאבד בה קבר ושנחרש בה קבר ושדה בוכין:"],[12,"שאין מעיד אלא על גופו של קבר","דכיון דאמרי אין שם קבר ברוח זה על גופו של קבר הוא מעיד וגופו של קבר דאורייתא ובדאורייתא מהימני. אלמא נאמנין על בית הפרס ועל (בית) הסככות:"],[13,"מהלך על פני כל השדה","דכיון דעל פני כולה מהלך ודאי פשיטא ליה דניטלה הטומאה משם ומתני' דקתני דאין נאמן כגון שאינו מהלך על פני כולה שמשייר רוח אחת הלכך אפילו במקום שעבר אינו נאמן משום דאיהו לספקא לא חייש:"],[14,"מאי למימרא","נהי דלספק לא חייש לודאי חייש וכיון דפשיטא לן דקבר הוה בה והוא מהלך על פני כולה הרי עובר על מקום הקבר ואי לאו דקים ליה שניטלה הטומאה לא עבר:"],[14,"רצועה נפקא","מן השדה ונקראת על שם שדה זו ושם הוא תולה את מקום הטומאה והכא עבר מספקא דלספקא לא חייש:"],[14,"קמ\"ל","כיון דעל כל ד' רוחותיה עובר בתוכה לרצועה לא חיישינן:"],[15,"לאתויי תחומין","אין נאמנין לומר עד כאן תחום שבת דתחומין דרבנן וכותיים לא סבירא להו:"],[15,"ויין נסך","דאין כותי מקפיד על מגע עובד כוכבים:"]],[[3,"","ודלמא כהן טמא הוא. ואע\"ג דטמא נמי אסור לשהות בבית הקברות דבנזיר בפרק מי שאמר (נזיר דף יז.) בעי נזיר והוא בבית הקברות מי בעי שהייה למלקות או לא ובפרק ג' מינין (נזיר דף מב:) אמר רב הונא נזיר שעומד בבית הקברות והשיטו לו מתו או מת אחר חייב וטעמא לפי שמוסיף טומאה עליו דבחבורים עושין את האחר אב הטומאה כדאמר התם כותיים לית להו הנך מימרות:"],[7,"","ובנה אצלו ציון. במועד קטן (דף ה.) מפיק מהכא ציון של בית הקברות וא\"ת ולר\"ש דאמר אין קברי עובדי כוכבים מטמאין באהל היכי מפיק מהכא הא אמר במו\"ק דאין מציינין אלא על טומאת אהל וי\"ל מדמציינין לפי שעה ציון משום טומאת מגע ומשא אם כן לכל הפחות יש לציין בטומאת אהל ולמאי דבעי למימר בהבא על יבמתו (יבמות דף סא.) דלר\"ש מתי עובדי כוכבים לא מטמאי אפילו במגע ובמשא נפיק ליה לר\"ש ציון מדרשא אחריתי דהתם וציון דגבי גוג לאו משום טומאה אלא לנקות הארץ מן המתים וא\"ת ולר\"ש דדריש (שם) דאין עובדי כוכבים קרויין אדם הא כתיב וראה עצם אדם וי\"ל דנקט אדם לאפוקי דס\"ד דקברו שם עצמות בהמה:"],[8,"","אילן המיסך. מיירי בידוע שיש מת קבור שם אך שאין ידוע תחת איזו ענף ואין כותי נאמן לומר שאינו קבור תחת ענף זה אפילו הולך תחתיו דאין מקפיד על ספק טומאה ודוקא במאהיל על פני כולה אמר בסמוך דנאמן ומה שפ\"ה אילן בסמוך לבית הקברות ופעמים קוברין שם בחנם פירש כן כיון שצריך לפרש בידוע שמת קבור שם דבספק לא היה נאמן אפילו היה מהלך על פני כולה ואע\"ג דספק טומאה ברה\"ר טהור הכא גזור רבנן והא דקאמר לקמן בפ\"ב (נדה דף סח:) דסככות ופרעות לאו אהל הוא ורבנן גזרו עלייהו לאו דוקא קאמר דלאו אהל הוא דבודאי קבור שם איירי כדפי' אלא כלומר הך טומאת אהל אינה אלא מדרבנן דברה\"ר ספקו טהור א\"נ הענפים המובדלין זה מזה רואים אותם כאילו הן סמוכות ליחשב אהל כדאמר באהלות (דף סט) המיסך על הארץ רבי יהודה אומר רואין התחתונות כאילו עולות למעלה והעליונות כאילו יורדות למטה ואם היו נוגעות זו בזו כפותח טפח מביאות וחוצצות כו':"],[9,"","בית הפרס. על שם פריסה שהעצמות נפרסים במדרס רגלים או ע\"י מחרישה ובשדה שאבד בה קבר לא שייך האי טעמא וקרי ליה בפ\"ק דמועד קטן (דף ה:) בית הפרס ושמא אגב דקרי בית הפרס לשדה שנחרש בה קבר קרי גם לאבד בית הפרס א\"נ לשון בית הפרס על שם שפרסות רגלי אדם נמנעות מלילך שם מפני הטומאה ובפ\"ק דמו\"ק (דף ה:) תניא גבי בית הפרס הוא שדה שנחרש בה קבר ושאבד בה קבר ושדה בוכים ומפרש טעמא דשדה בוכים משום יאוש בעלים ומפרש בערוך שדה מיוחד שקרובי המת מביאין אותו על אותו שדה ואנשי בית הקברות באין לקראתו ובוכים יחד וכו' והראשונים חוזרים לביתם ואלו נוטלין אותו ומוליכין אותו לקוברו ואותו שדה טמא דשמא נתדלדל ונתנענע מעט מעט ממנו ונפל ושכחוהו ורבינו שמואל פי' פעמים שבני העיר מניחין אותו שם לפי שסוברין שאנשי בית הקברות יבואו ויטלו אותו ובני בית הקברות יסברו שאנשי העיר יוליכוהו לבית הקברות ונשאר שם ועוד פי' שם שדה כוכין שדה שיש בה כוכין ומניחין המת שם לפי שעה עד שיהו פנוים להוליכו לבית הקברות לקוברו ופעמים שנשכח שם ולא הוסר וזהו יאוש בעלים:"],[10,"","בית הפרס שנידש טהור. אשדה שנחרש בה קבר קאי דמספקינן לעצם כשעורה ק' אמה סביבות הקבר דכיון שנידש ונרמס ברגלים י\"ל שהוליכו כשעורה משם אבל אשדה שאבד בה קבר לא שייכא הך קולא:"],[10,"","מלא מענה ק' אמה. בתוספתא דאהלות [רפי\"ז] מפרש דהנך ק' אמה היינו לכל רוח:"],[13,"","אמר ר' יוחנן במהלך ובא על פני כולה. אבל בשדה שנחרש בה קבר אפילו מהלך ובא על פני כולה לא מהימן דאין כאן אלא ספקא דרבנן שמא הסיט עצם כשעורה ואין הכותי חושש עליה וא\"ת כי היכי דציון קברות דמהימן אדאורייתא דאוקימנא בכהן עומד שם ה\"נ ליתני במתני' דמהימן אסככות ופרעות ובמהלך על פני כולה וי\"ל דלא חשיבא ליה למתני' רבותא לאשמועינן דלא חיישינן לרצועה נפקא ועוד אבית הפרס דנחרש בה קבר לא מהני מהלך ובא על פני כולה כדפרישית אלא דוקא באבד בה קבר וא\"ת ובאבד נמי היכי מהני דלמא טמאה היא וי\"ל דמיירי דנקיט תרומה ואכיל מינה כדקאמר לעיל וה\"ה דנקט ולא אכיל וכגון שידוע לנו שהיא טהורה דלא הוה כותי מטמא לה:"]]],[["מתני׳ \u0001הרואה\u0002 כתם על בשרה כנגד בית התורפה טמאה ושלא כנגד בית התורפה טהורה על עקבה ועל ראש גודלה טמאה","על שוקה ועל פרסותיה מבפנים טמאה מבחוץ טהורה ועל הצדדין מכאן ומכאן טהורה","ראתה על חלוקה מן החגור ולמטה טמאה מן החגור ולמעלה טהורה ראתה על בית יד של חלוק אם מגיע כנגד בית התורפה טמאה ואם לאו טהורה","היתה פושטתו ומתכסה בו בלילה כל מקום שנמצא בו כתם טמאה מפני שהוא חוזר וכן בפוליוס","\u0001גמ׳\u0002 אמר שמואל בדקה קרקע עולם וישבה עליה ומצאה דם עליה טהורה שנאמר (ויקרא טו, יט) בבשרה עד שתרגיש בבשרה","האי בבשרה מיבעי ליה שמטמאה בפנים כבחוץ א\"כ לימא קרא בבשר מאי בבשרה שמע מינה עד שתרגיש בבשרה","ואכתי מיבעי ליה בבשרה ולא בשפיר ולא בחתיכה תרתי שמע מינה","תא שמע האשה שהיא עושה צרכיה וראתה דם רבי מאיר אומר אם עומדת טמאה ואם יושבת טהורה","היכי דמי אי דארגשה יושבת אמאי טהורה אלא לאו דלא ארגשה וקתני עומדת טמאה","לעולם דארגשה ואימור הרגשת מי רגלים הואי עומדת הדור מי רגלים למקור ואייתי דם יושבת טהורה","ת\"ש עד שהיה נתון תחת הכר ונמצא עליו דם אם עגול טהור ואם משוך טמא","היכי דמי אי דארגישה עגול אמאי טהור אלא לאו דלא ארגישה וקתני משוך טמא","לא לעולם דארגישה ואימור הרגשת עד הואי משוך ודאי מגופה אתא עגול טהור","תא שמע נמצא על שלו טמאין וחייבין בקרבן נמצא על שלה אתיום טמאין וחייבין בקרבן נמצא על שלה לאחר זמן טמאים מספק ופטורין מן הקרבן","היכי דמי אי דארגישה לאחר זמן אמאי פטורין מן הקרבן אלא לאו דלא ארגישה וקתני נמצא על שלה אתיום טמאין וחייבין בקרבן לא לעולם דארגישה ואימא הרגשת שמש הוה","תא שמע נמצאת אתה אומר ג' ספקות באשה על בשרה ספק טמא ספק טהור טמא על חלוקה ספק טמא ספק טהור טהור ובמגעות ובהיסטות הלך אחר הרוב","מאי הלך אחר הרוב לאו אם רוב ימיה טמאין טמאה ואע\"ג דלא ארגשה","לא אם רוב ימיה בהרגשה חזיא טמאה דאימור ארגשה ולאו אדעתה","אמר מר על בשרה ספק טמא ספק טהור טמא על חלוקה ספק טמא ספק טהור טהור","ה\"ד אי מחגור ולמטה על חלוקה אמאי טהור והא תנן מן החגור ולמטה טמא ואי מחגור ולמעלה על בשרה אמאי טמא והתנן ראתה דם על בשרה שלא כנגד בית התורפה טהורה","אב\"א מחגור ולמטה ואב\"א מחגור ולמעלה אי בעית אימא מחגור ולמטה כגון שעברה בשוק של טבחים על בשרה מגופה אתאי דאי מעלמא אתאי על חלוקה מיבעי ליה אשתכוחי על חלוקה מעלמא אתא דאי מגופה אתא על בשרה מיבעי ליה אשתכוחי","ואיבעית אימא מחגור ולמעלה כגון דאזדקרה על בשרה ודאי מגופה אתאי דאי מעלמא אתאי על חלוקה איבעי ליה אשתכוחי על חלוקה מעלמא אתאי דאי מגופה אתאי על בשרה איבעי ליה אשתכוחי","קתני מיהת על בשרה ספק טמא ספק טהור טמא ואע\"ג דלא הרגישה ועוד תנן הרואה כתם על בשרה כנגד בית התורפה טמאה ואע\"ג דלא הרגישה אמר רב ירמיה מדפתי מודה שמואל שהיא טמאה"],[[0,"מתני' הרואה כנגד בית התורפה","אותו מקום דאיכא למימר דם מאותו מקום נפל להתם וטמאה:"],[0,"על עקבה ועל ראש גודלה טמאה","ראש גודלה של רגל. ובגמרא מפרש טעמא:"],[1,"מבפנים","בין שני שוקים כל גובהן מן הארץ:"],[1,"מבחוץ","מכאן ומכאן:"],[1,"צדדים","אחורי השוק כל גובהן כנגד העקב ולפניו כל גובהן כנגד הרגל:"],[2,"מן החגור ולמטה","כנגד בית התורפה הוא:"],[2,"אם מגיע כנגד בית התורפה","כגון שנמצא בראש בית ידה סמוך ליד שפעמים שפושטתן מזרועה ונופל כנגד מטה:"],[2,"שלא כנגד בית התורפה","כגון שנמצא סמוך לכתפה:"],[3,"שהוא חוזר","פעמים שראש החלוק נהפך כלפי פניה שלמטה:"],[3,"וכן בפוליוס","מעפורת שמתכסה בו. אירי\"ל בלע\"ז:"],[7,"גמ' צרכיה","מטלת מים:"],[7,"עומדת טמאה","דאיידי דדחיק לה עלמא דמעומד השתינה ולא יכלה לעצור הדור מי רגלים למקור ואייתו דם:"],[7,"יושבת טהורה","דמכה יש לה במקום מי רגלים שאין דרך דם נדה לצאת עם מי רגלים:"],[10,"עד","סדין שבודקת בו:"],[10,"עגול","אין זה דם בדיקה דדרך קינוח להיות משוך:"],[11,"דארגישה","בשעת בדיקה ועגול להכי טהור לעולם דאימור הרגשת עד הואי שציערתה בדיקת העד:"],[15,"על בשרה ספק טמא ספק טהור טמא","כולו מפרש לקמן:"],[15,"ובמגעות ובהיסטות הלך אחר הרוב","אשה שלא מצאה כתם והרי היא מחזקת עצמה בספק נדה כגון שאין לה וסת ורגילה לראות תדיר ונגעה או הסיטה הלך אחר רוב ימיה אם רוב ימיה רגילה לראות מגעה והסיטה טמא ואע\"ג דהשתא לא ארגישה:"],[21,"דאזדקרה","זקפה עצמה לאחוריה ואע\"ג דעברה בשוק של טבחים טמאה דאי מעלמא אתאי על חלוקה אבעי ליה לאשתכוחי:"]],[[0,"","הרואה כתם. ת\"ש האשה שעושה צרכיה. תימה מאי מהדר אפירכות הא כמה משניות פ' בא סימן ודם הנדה בדיני כתמים וליפרוך מינייהו ולא שייך לשנויי עלייהו לא הרגשת עד ולא הרגשת שמש ואומר הר\"י דמדיני כתמים ליכא למפרך דהיינו יכולין להעמיד שיש זמן מרובה משעת הכבוס ואימור הרגישה ולאו אדעתה אבל בשמעתין פריך מכתמים דבבשרה דאין רגילות לשהות כתם בבשר בלא דעתה שלא ייבש ויפול מיהו ברייתא דג' ספקות דמייתי לקמן פריך מחלוקה כמו שנפרש בההיא וי\"ל דמשמע דזמן מועט היה שם דומיא דבשר ומשני דמזמן רחוק הוה ואימור ארגשה ולא אדעתה אי נמי כיון דרוב ימיה טמאים יש לחוש:"],[14,"","אימור הרגשת שמש הואי. וא\"ת אמאי לא נקט הרגשת מי רגלים כמו לעיל ואע\"פ שלא הטילה כדאמר בריש מכילתין והל\"ל כסבור' הרגשת מי רגלים הוא וי\"ל דהכא זמן מועט בין תשמיש למציאת הדם והיתה יודעת אם תרגיש במי רגלים אבל לעיל בין פקידה לפקידה יש זמן ארוך והרבה פעמים יש הרגשת מי רגלים בינתיים:"],[15,"","ובמגעות ובהיסטות הלך אחר הרוב. פ\"ה אשה שאין לה וסת ורגילה לראות תדיר ובודקת עצמה תמיד וכל זמן שלא בדקה עצמה מחזקת עצמה בטומאה הלכך אם רוב ימיה היא טמאין טמאה וזהו תימה שזו החומרא לא מצינו בשום מקום דהא אשה שיש לה וסת דיה שעתה וטומאה דמעת לעת אינה אלא באין לה וסת ולא מפקידה לפקידה ואפי' ברואה וכ\"ש הכא דאין כאן אלא כתם ואין לחלק בין ברואה תדיר בין שאינה רואה תדיר ונראה דקאי אנמצא על חלוקה (ספק טמא ספק טהור) וקאמר דאם אחרי מציאת הכתם רוב ימיה טמאין טמאה ואף על גב דעברה בשוק של טבחים ולא אמרינן אי מגופה אתא על בשרה איבעי ליה לאשתכוחי:"],[18,"","אמר מר על בשרה כו'. ולבסוף פריך מינה לשמואל והא דלא פריך מינה ברישא אלא פריך ממגעות והיסטות דסיפא ברישא משום דפשוט הוא יותר אבל רישא מיבעי ליה לתרוצי ברישא והדר פריך מינה:"],[21,"","על בשרה ודאי מגופה אתאי. וא\"ת מאי שנא דלקמן בשמעתין גבי לבשה שלשה חלוקות ועברה בשוק של טבחים תולה אפילו בתחתון ולא אמרינן אי איתא דמעלמא אתאי אעליון ה\"ל לאשתכוחי ויש לומר דהתם לפעמים שהיא מגלה חלוקה העליון ואתי על התחתון אבל אי דרך לגלות בשרה:"],[22,"","קתני מיהא על בשרה כו'. וא\"ת ומאי קושיא ה\"נ אימור ארגשה ולאו אדעתה כדאמר לעיל וי\"ל דהתם דרוב ימיה טמאין יש רגלים לדבר שיש לתלות בהרגשה ולאו אדעתה אבל הכא אין שום הוכחה שנתלה בהרגשה ולאו אדעתה שאין רק שעה מועטת שהוא על בשרה:"],[22,"","מודה שמואל שהיא טמאה מדרבנן. פי' הקונטרס דתלינן דלמא ארגשה ולאו אדעתה ואין נראה דאפילו מוחזק לה שלא הרגישה טמאה הואיל וראתה דם נדות ורב אשי נמי מודה דלשמואל היכא דלא הרגישה טהורה מן התורה וטמאה מדרבנן אלא אתי לפרושי דכי נמצא אקרקע דטהורה אפילו מדרבנן:"]]],[["מדרבנן","רב אשי אמר שמואל הוא דאמר כר' נחמיה דתנן ר' נחמיה אומר כל דבר שאינו מקבל טומאה אינו מקבל כתמים","בשלמא לרב אשי היינו דקאמר קרקע אלא לרב ירמיה מאי איריא קרקע אפילו גלימא נמי לא מיבעיא קאמר","לא מיבעיא גלימא דלא מבדק שפיר ואיכא למימר מעלמא אתא אלא אפילו קרקע דמבדק שפיר דאיכא למימר מגופה אתיא טהור","על עקבה ועל ראש גודלה טמאה וכו' בשלמא עקבה עביד דנגע באותו מקום אלא ראש גודלה מאי טעמא וכי תימא זימנין דנגע בעקבה ומי מחזקינן טומאה ממקום למקום","והתניא היתה לה מכה בצוארה שתוכל לתלות תולה על כתפה שאינה יכולה לתלות אינה תולה","ואין אומרים שמא בידה נטלתו והביאתו לשם אלא שאני ראש גודלה דבהדי דפסעה עביד דמתרמי","ולא מחזקינן טומאה ממקום למקום והתניא נמצאת על קשרי אצבעותיה טמאה מפני שידים עסקניות הן","מאי טעמא לאו משום דאמרינן בדקה בחד ידא ונגעה באידך ידא לא שאני ידה דכולה עבידא דנגעה","על שוקה ועל פרסותיה מבפנים וכו' מבפנים עד היכא אמרי דבי רבי ינאי עד מקום חבק","איבעיא להו מקום חבק כלפנים או כלחוץ ת\"ש דתני רב קטינא עד מקום חבק וחבק עצמו כלפנים רב חייא בריה דרב אויא מתני לה בהדיא אמרי דבי רבי ינאי עד מקום חבק וחבק עצמו כלפנים","בעי רבי ירמיה כשיר מהו כשורה מהו טיפין טיפין מהו לרוחב ירכה מהו","ת\"ש על בשרה ספק טמא ספק טהור טמא על בשרה מאי לאו כי האי גוונא לא דלמא דעביד כרצועה","ההיא איתתא דאשתכח לה דמא במשתיתא אתאי לקמיה דרבי ינאי אמר לה תיזיל ותיתי","והתניא אין שונין בטהרות כי אמרינן אין שונין לקולא אבל לחומרא שונין","היתה פושטתו וכו' תניא אר\"א בר' יוסי דבר זה הוריתי בעיר רומי לאיסור וכשבאתי אצל חכמים שבדרום אמרו לי יפה הוריתה","ת\"ר ארוכה שלבשה חלוקה של קצרה וקצרה שלבשה חלוקה של ארוכה אם מגיע כנגד בית התורפה של ארוכה שתיהן טמאות ואם לאו ארוכה טהורה וקצרה טמאה","תניא אידך בדקה חלוקה והשאילתו לחבירתה היא טהורה וחבירתה תולה בה אמר רב ששת ולענין דינא תנן אבל לענין טומאה היא טהורה וחבירתה טמאה"],[[0,"מדרבנן","דלמא ארגשה ולאו אדעתה:"],[1,"רב אשי אמר","טעמא דשמואל דאמר לעיל בדקה קרקע עולם כו' לאו משום הרגשה אלא כרבי נחמיה ס\"ל דאמר לא הזכירו חכמים גזרת כתם אלא על דבר המקבל טומאה הלכך כל הנך תיובתא לאו קושיא נינהו דשמואל לא איירי בהרגשה כלל:"],[2,"אלא רב ירמיה מדפתי","דקבלה לתיובתא דלעיל ושני מודה שמואל כו' ומדקבלה לתיובתא מכלל דטעמא דשמואל משום הרגשה ואי משום הרגשה מאי איריא קרקע אפילו גלימא נמי בדקה בטלית וישבה עליה ואחר כך מצאה דם טהורה שלא הרגישה:"],[5,"בצוארה","אם נמצא דם כנגד תורפה יכולה לתלות במכה של צוארה שפעמים שמטה את צוארה לפניה ונופל דם המכה על תחתית חלוקה:"],[5,"על כתפה שאינה יכולה לתלות","שאין דם בא מכתפה ונופל לפניה אין תולה:"],[6,"ואין אומרים בידה נטלתו","ממכה שבכתפה והביאתו לפניה:"],[6,"עביד דמתרמי","תחת אותו מקום ודם נוטף עליו:"],[7,"על קשרי אצבעותיה","היינו גב היד. והא גב היד אפילו בשעת בדיקה לא נגעה מ\"ט טמאה:"],[8,"לאו משום דאמרינן בדקה באידך ידא ונגעה","יד שבדקה על גב חבירתה:"],[9,"עד היכא","קרוי פנים מעובי השוק ולא אמרינן צדדין נינהו:"],[9,"עד מקום חבק","ספק. וכמדומה לי שהוא קפץ הירך והשוק שקורין יירי\"ט וקאמר עד מקום שהוא מתחיל קרוי פנים וחבק היא מתיחת הגידין שחובקין הירך והשוק יחד סמוך לאותו קפץ כמו (שבת דף סד.) את הקילקי ואת החבק:"],[11,"כשיר","רצועה בעיגול כצמיד:"],[11,"מהו","מי מספקינן בדם הנדה או לאו:"],[12,"כרצועה","לאורך הירך דהיינו אורחיה כשנופל ושותת נעשה כרצועה:"],[13,"במשתיתא","עם המסכת דשמשון (שופטים טז) מתרגמינן עם משתיתא. שהיתה מסכת טווי לאריג ונמצא דם על השתי:"],[13,"תיזיל ותיתי","כדרך שעשתה עד עכשיו שהלכה ושבה אי מתרמי שהטווי המוסך שקורין אורדי\"ר בא בין רגליה כנגד אותו מקום טמאה:"],[14,"והתניא אין שונין בטהרות","גבי מתעטף בטליתו וטהרות וטמאות בצדו בפ\"ק (לעיל נדה דף ה:) ספק נגע ספק לא נגע טהור ואם אי אפשר אא\"כ נגע טמא רבן שמעון בן גמליאל אומר אע\"פ דלא אפשר לא מטמינן ליה אלא אומרים לו שנה ואי לא נגע מטהרינן ליה אמרו לו אין שונין בטהרות דאף על גב דהשתא לא מיתרמי דלמא מעיקרא לא הוה הכי:"],[14,"כי אמרינן אין שונין לקולא","כגון בההיא דא\"א לו אא\"כ נגע וטמא ואנן ניקו ונימא ליה שנה להקל אבל הכא חומרא הוא דמסתמא טהורה דהא לא על בשרה ולא על חלוקה אשתכח והאי דאמר תיזיל ותיתי ואי מתרמי מטמינן לה חומרא היא:"],[15,"דבר זה","היתה פושטתו ומתכסה בו בלילה כו':"],[16,"חלוקה של קצרה","ולא בדקתו קודם לבישה ואחר כך נמצא עליו דם:"],[16,"אם מגיע","כתם:"],[16,"כנגד בית התורפה של ארוכה","טמאה אף ארוכה וכ\"ש קצרה:"],[16,"ואם לאו טהורה הארוכה","אבל קצרה טמאה שהרי כנגד בית התורפה שלה הוא מגיע:"],[17,"היא טהורה","הראשונה:"],[17,"ולענין דינא","דכבוס הכתם מן החלוק תנן דחבירתה תולה בה דאמרה אחרונה לא מהימנת לי דאת בדקתיה:"]],[[1,"","כרבי נחמיה דאמר כל דבר שאינו מקבל טומאה כו'. טעמא דרבי נחמיה כיון דדבר שהכתם בו טהור גם על האשה לא גזרו טומאה וההיא משתיתא דבסמוך נהי דלא מקבלה טומאה מ\"מ מקבל טומאה בנגעים:"],[4,"","ומי מחזקינן טומאה ממקום למקום. וקשה דמאי פריך דודאי להקל לא מחזקינן אבל להחמיר כי הכא מחמרינן דהכי אמר לקמן אין שונין בטהרות להקל אבל לחומרא שונין ויש לומר כיון דכתמים דרבנן אי איתא דתלינן להחמיר להקל נמי היה לנו לתלות בדבר הרגיל קצת אבל לענין ממקום למקום שאין רגילות כל כך אמרינן לקמן בסמוך דאפילו בכתמים שונין לחומרא ולא להקל תימה דליפרוך ממתניתין שלא כנגד התורפה טהורה ולא אמר בדקה בהאי ידא ונגעה בבשרה למעלה מן התורפה וי\"ל דאם איתא דבדקה ומצאה טמאה היתה זכורה והויא רמיא אדעתה שהיא טמאה אבל כי נגעה בדם שעל כתפה לא רמיא אנפשה כיון דאין זה דם טמא ובסמוך גבי דם טמא דפריך ואימא דבדקה בהאי ידא ונגעה באידך פריך מכ\"ש וממתניתין נמי הוה מצי למפרך ויש לחלק בין ממקום למקום דהכא לההוא דפ\"ק (לעיל נדה דף ד.) דהתם טומאה עצמה באה ממקום למקום והכא טומאה עצמה במקום אחד עומדת:"],[9,"","מקום חבק. פרש\"י שהוא קפץ הירך והשוק וחבק הוא מקום מתיחת הגידים שחובקים הירך והשוק ובערוך פירש שנועלין אנפליאות שיש בה לולאות ומקום חבור הלולאות קרי חבק ועוד פירש פירוש אחר שכופף השוק על הירך מה שמתכסה הבשר ע\"י כפיפת השוק על ירך שחובקין זה את זה קרי מקום חבק:"],[11,"","כשורה מהו. אומר ר\"י דהיינו טיפין טיפין דאי מחוברת השורה יחד היינו רצועה דבסמוך וטיפין טיפין היינו מעורבבין שאינו לא כשיר ולא כשורה והא דאמר לקמן טיפין טיפין אין מצטרפין היינו על הבגד והכא מיירי על בשרה דיש יותר לתלות בדם מאכולת על הבגד מעל בשרה:"],[17,"","ולענין דינא תנן. וא\"ת מדינא נמי תתחייב השניה לכבסו כדאמר בהמדיר (כתובות עו:) כל שנולד ספק ברשותו עליו להביא ראיה וי\"ל כיון דאינה לשניה אלא בתורת שאלה אינה ממש ברשותה ועוד יש לומר דהתם קאמר שאם ירצה להוציא יביא ראיה אבל הכא לא תתחייב האחרונה לכבסו:"]]],[["מאי שנא מהא דתניא שתי נשים שנתעסקו בצפור אחד ואין בו אלא כסלע דם ונמצא כסלע על זו וכסלע על זו שתיהן טמאות שאני התם דאיכא סלע יתירה","ת\"ר לבשה שלשה חלוקות הבדוקין לה אם יכולה לתלות תולה ואפילו בתחתון אין יכולה לתלות אינה תולה ואפי' בעליון","כיצד עברה בשוק של טבחים תולה אפילו בתחתון לא עברה בשוק של טבחים אף בעליון אינה תולה","\u0001מתני׳\u0002 ותולה בכל דבר שהיא יכולה לתלות שחטה בהמה חיה ועוף נתעסקה בכתמים או שישבה בצד העסוקין בהן הרגה מאכולת הרי זו תולה בה","עד כמה תולה רבי חנינא בן אנטיגנוס אומר עד כגריס של פול ואף ע\"פ שלא הרגה ותולה בבנה או בבעלה אם יש בה מכה והיא יכולה להגלע ולהוציא דם הרי זו תולה","מעשה באשה אחת שבאת לפני ר\"ע אמרה לו ראיתי כתם אמר לה שמא מכה היתה ביך אמרה לו הן וחיתה אמר לה שמא יכולה להגלע ולהוציא דם אמרה לו הן וטהרה ר\"ע","ראה תלמידיו מסתכלין זה בזה אמר להם מה הדבר קשה בעיניכם שלא אמרו חכמים הדבר להחמיר אלא להקל שנאמר (ויקרא טו, יט) ואשה כי תהיה זבה דם יהיה זובה בבשרה דם ולא כתם","עד שהוא נתון תחת הכר ונמצא עליו דם עגול טהור משוך טמא דברי ר\"א ברבי צדוק","\u0001גמ׳\u0002 תנינא להא דת\"ר מעשה ותלה ר\"מ בקילור ורבי תלה בשרף שקמה","או שישבה ישבה אין לא ישבה לא","תנינא להא דת\"ר עברה בשוק של טבחים ספק ניתז עליה ספק לא ניתז עליה תולה ספק עברה ספק לא עברה טמאה:","הרגה מאכולת: הרגה אין לא הרגה לא מתני' מני רשב\"ג היא דתניא הרגה תולה לא הרגה אינה תולה דברי רשב\"ג וחכ\"א בין כך ובין כך תולה","אמר רשב\"ג לדברי אין קץ ולדברי חברי אין סוף","לדברי אין קץ שאין לך אשה שטהורה לבעלה שאין לך כל מטה ומטה שאין בה כמה טיפי דם מאכולת","לדברי חברי אין סוף שאין לך אשה שאינה טהורה לבעלה שאין לך כל סדין וסדין שאין בו כמה טיפי דם","אבל נראין דברי ר' חנינא בן אנטיגנוס מדברי ומדבריהם שהיה אומר עד כמה היא תולה עד כגריס של פול ולדבריו אנו מודים ולרבנן דאמרי תולה עד כמה אמר ר\"נ בר יצחק תולה בפשפש ועד כתורמוס","ת\"ר פשפש זה ארכו כרחבו וטעמו כריחו ברית כרותה לו שכל המוללו מריח בו ארכו כרחבו לענין כתמים","טעמו כריחו לענין תרומה דתנן או שטעם טעם פשפש בפיו ה\"ז יפלוט מנא ידע טעמו כריחו ואכתי מנא ידע ברית כרותה לו שכל המוללו מריח בו","אמר רב אשי עיר שיש בה חזירים אין חוששין לכתמים אמר ר\"נ בר יצחק והא דדוקרת כעיר שיש בה חזירים דמיא","עד כמה היא תולה וכו' אמר רב הונא כגריס אינה תולה פחות מכגריס תולה ורב חסדא אמר כגריס תולה יתר מכגריס אינה תולה","לימא בעד ועד בכלל קא מיפלגי דרב הונא סבר עד ולא עד בכלל ורב חסדא סבר עד ועד בכלל","אמר לך רב הונא איכא עד ועד בכלל ואיכא עד ולא עד בכלל והכא לחומרא והכא לחומרא","ורב חסדא אמר לך בעלמא אימא לך לחומרא אמרינן לקולא לא אמרינן והכא כדרבי אבהו דא\"ר אבהו כל שיעורי חכמים להחמיר חוץ מכגריס של כתמים להקל","איכא דאמרי לה להא שמעתא באפי נפשה רב הונא אמר כגריס כיתר מכגריס ורב חסדא אמר כגריס כפחות מכגריס וקמיפלגי בעד ועד דהכא כדאמרינן מיתיבי"],[[0,"שתיהן טמאות","ולא תלינן אחד מן הכתמים בצפור ואע\"ג דאיכא למתלי. וה\"נ אע\"ג דבדקה לימא שתיהן טמאות דאימור לאו יפה בדקה:"],[0,"סלע יתירה","ומאי חזית דתלית ליה לסלע יתירה דטמאה בהך תלייה בהך הלכך שתיהן טמאות אבל הכא טומאה תלויה בהך דלא בדקה:"],[1,"שלשה חלוקות","זה על גב זה:"],[1,"יכולה לתלות","כדמפרש עברה בשוק של טבחים:"],[4,"מתני' עד כמה היא תולה","בדם מאכולת:"],[4,"כגריס","אבל טפי מהכי אין דם מאכולת כל כך גדול ובהכי מיהא תלייה:"],[4,"ואע\"פ שלא הרגה","ורבי חנינא פליג אדרבנן דקאמרי הרגה אין לא הרגה לא:"],[4,"ותולה בבנה ובבעלה","אם יש בהם מכה:"],[4,"ואם יש בה מכה","יבשה וראויה להגלע כלומר להתלחלח ולהוציא דם תולה:"],[8,"גמ' קילור","אפלשטור\"א אדום:"],[9,"לא ישבה לא","ולא אמרינן דלמא ישבה ולאו אדעתה:"],[12,"לדברי אין קץ","שאיני נותן שיעור ואם לא הרגה אפילו כחרדל טמאה:"],[12,"ולדברי חברי אין סוף","שהם מקילים יותר מדאי דאפילו לא הרגה תולה ואין נותנין שיעור אלא אפילו כסלע תולה או יותר:"],[15,"עד כגריס","ואפילו לא הרגה ויתר מכגריס לא ואפילו הרגה ולדבריו יש לטמא כגריס ועוד ולטהר פחות מכגריס:"],[15,"עד כמה","כלומר וכי אפשר לתלות כתם גדול במאכולת:"],[15,"אמר ר\"נ תולה בפשפש עד כתורמוס","כתם רחב כתורמוס יכולה לתלות ולא במאכולת אלא בפשפש שמא פשפש הרגה שכתמו גדול. פשפש פונייש\"א בלע\"ז:"],[16,"ברית כרותה לו","כלומר ריחו נודף ומבאיש וכל המוללו על כרחו מריח ריחו:"],[16,"לענין כתמים","דאי הוה כתם ארכו כרחבו אפילו יותר מכגריס תלינן בפשפש:"],[17,"או שטעם טעם פשפש","באוכל תרומה מיירי. וכ\"ש חולין דהא שרץ הוא אלא האי דנקט תרומה משום דפליגי לעיל מיניה אמרו לו נטמאת ונטמאת התרומה ר\"א אומר יבלע ר' יהושע אומר יפלוט אבל אומר לו טמא היית וטמאה היתה התרומה או שנודע שהוא טבל או שטעם טעם פשפש לתוך פיו ה\"ז יפלוט הואיל ועד שלא נתנה לתוך פיו אירע בה פסול זה לא חיישינן להפסד תרומה:"],[17,"מנא ידע","טעם פשפש:"],[17,"ואכתי מנא ידע","והלא לא הריח בו:"],[18,"חזירים","אוכלים שקצים ורמשים ומתיזים דם:"],[18,"דדוקרת","טבחים הרבה ואשפות ושקצים מצויין בה:"],[21,"והכא לחומרא","הילכך עד ולא עד בכלל דאי עד ועד בכלל הוה ליה קולא דקתני עד כגריס תולה וקיימא לן באלו טריפות (חולין נה.) דבכל עד אזלינן לחומרא אי עד ועד חומרא הוא אזלינן בתריה ואי עד ולא עד חומרא הוא אזלינן בתריה:"],[23,"אמרי לה באנפי נפשה","ולאו אמתני':"],[23,"ה\"ג וקמיפלגי בעד ועד דהכא","כדאמר רב הונא לחומרא כדאמרינן בכל דוכתי הלכך עד ולא עד בכלל ולרב חסדא כרבי אבהו:"]],[[0,"","מאי שנא מהא דתניא ב' נשים כו'. תימה מה דומה להך דלעיל דהכא אין לתלות בזו יותר מבזו אבל לעיל אין לתלות בראשונה הואיל ובדקה ואומר ר\"ת דברייתא איירי שנתעסקה בצפור זו אחר זו ואם היתה נשאלת הראשונה היינו מטהרין אותה הואיל ונתעסקה ובשביל חברתה אנו מטמאין הראשונה שהיא טהורה גמורה גם למעלה אע\"פ שהראשונה בדוקה נטמאנה הואיל ושניה תולה בה לענין דינא:"],[13,"","אין לך כל מטה ומטה. הכא לא נקט סדין וסדין כדבסמוך משום דהכא בעי למימר מטה אפילו של איש שאין בה כמה טיפין של דם מאכולת אם כן ה\"נ של אשה יש לנו לתלות במאכולת אבל בסמוך לא איירי אלא בשל אשה להכי נקט סדין:"],[15,"","וכדבריו אנו מודים. ומיהו היכא דהרגה הרבה מאכולת או פשפש תולה כפי מה שהרגה מידי דהוה אשוק של טבחים:"],[18,"","עיר שיש בה חזירים אין חוששין בכתמים. אומר רשב\"ם דאפי' יותר מכגריס ואפי' מן החגור ולמטה ואפילו לא נתעסקה ואין לה מכה שיש לה להגלע ולהוציא דם מיהו אור\"י דאין לסמוך על זה עכשיו להקל כשמוצאה כתמים במקום שאין רגילות ליגע בהן חזירים וכן מנהג דלא תלינן ומיהו במקום שיש רגלים לדבר שיש לתלות בחזירים וכיוצא בהן תלינן כדקאמר הש\"ס:"]]],[["היו עליה טיפי דמים למטה וטיפי דמים למעלה תולה בעליון עד כגריס מאי לאו כגריס מלמטה לא כגריס מלמעלה","איתמר נמצא עליה כגריס ועוד ואותו עוד רצופה בו מאכולת ר' חנינא אומר טמאה ר' ינאי אומר טהורה רבי חנינא אומר טמאה כי תליא בכגריס בכגריס ועוד לא תליא","רבי ינאי אומר טהורה הני מילי היכא דלא רצופה בו מאכולת אבל היכא דרצופה בו מאכולת מוכחא מילתא דהאי ועוד דם מאכולת הוא פש ליה כגריס כיון דבעלמא תליא הכא נמי תליא","בעי רבי ירמיה נתעסקה בכגריס ונמצא עליה בכגריס ועוד מהו תבעי לר' חנינא תבעי לר' ינאי","תבעי לר' חנינא עד כאן לא קאמר ר' חנינא התם טמאה אלא דלא נתעסקה אבל הכא דנתעסקה תליא או דלמא אפילו לרבי ינאי דאמר טהורה הני מילי היכא דרצופה בו מאכולת אבל היכא דאין רצופה בו מאכולת לא תליא","תא שמע נתעסקה באדום אין תולה בה שחור במועט אין תולה בו מרובה היכי דמי לאו כי האי גוונא","לא כגון דנתעסקה בכגריס ונמצא עליה שני גריסין ועוד אי הכי מאי למימרא","מהו דתימא שקול כגריס צפור שדי בי מצעי זיל הכא ליכא שיעורא זיל הכא ליכא שיעורא קמ\"ל","אמר רבא נמצא עליה מין אחד תולה בו כמה מינין מיתיבי נתעסקה באדום אין תולה בו שחור נתעסקה שאני","איכא דאמרי אמר רבא נתעסקה במין אחד תולה בו כמה מינין מיתיבי נתעסקה באדום אין תולה בו שחור כי קאמר רבא דאתעסקה בתרנגולת דאית בה כמה מיני דמא","מעשה באשה [וכו'] והתניא לא אמרו חכמים את הדבר להקל אלא להחמיר","אמר רבינא לא להקל על דברי תורה אלא להחמיר על דברי תורה וכתמים עצמן דרבנן","עד שהוא נתון איבעיא להו מי פליגי רבנן עליה דר\"א ברבי צדוק או לא","תא שמע כתם ארוך מצטרף טפין טפין אין מצטרפין מני אי רבי אליעזר בר' צדוק למה לי צירוף האמר משוך כל שהוא טמא","אלא לאו רבנן שמע מינה פליגי לא לעולם ר' אליעזר ברבי צדוק וכי אמר רבי אליעזר ברבי צדוק בעד אבל בכתם לא","ת\"ש דאמר רב יהודה אמר שמואל הלכה כרבי אליעזר ברבי צדוק הלכה מכלל דפליגי שמע מינה","\u0001הדרן עלך הרואה כתם\u0002"],[[0,"טיפי דמים למטה","כלומר קטנים:"],[0,"למעלה","גדולים:"],[0,"כגריס מלמטה","בפחות מכגריס ותלינן:"],[1,"נמצא עליה כגריס ועוד","דהלכתא כרב חסדא דמיקל:"],[2,"כיון דבעלמא","היכא דליכא ועוד תליא כגריס במאכולת השתא נמי תליא האי גריס במאכולת אחרינא:"],[3,"נתעסקה בכגריס","דם צפור או קילור:"],[4,"אבל הכא דנתעסקה תליא","כגריס בדם צפור ועוד דם מאכולת הוה:"],[6,"מאי למימרא","הא אפילו תליא כגריס בצפור אכתי פש ליה גריס ועוד:"],[7,"","מהו דתימא שקול כגריס דם צפור ושדי בי מצעי:"],[8,"נמצא עליה מין אחד","מדבר הדומה לכתם כגון קילור או שרף ואחר כך מצאה על חלוקה כתם אפי' אין מראיתו דומה לאותו המין תולה בו:"],[8,"נתעסקה שאני","דכיון דנתעסקה במין אדום היכי תלינן ביה כתם שחור אבל נמצא עליה מין אדום תולה בה כתם שחור דאמרינן כי היכי דניתן עליה האי מין בדלא ידעה הכי נמי הוה עלה מינא אחרינא ולא ידעה:"],[11,"לא להקל על דברי תורה","האי דגזור רבנן בכתמים להחמיר על ד\"ת שלא להקל בנדה גמורה ומיהו כתמים עצמן דרבנן ואזלינן בהן לקולא ותלינן בכל מידי:"],[13,"כתם ארוך מצטרף","לכגריס ועוד:"],[13,"משוך כל דהו טמא","דכיון דאמר משוך מגופה אתי ובמשיכה תליא טעמא אפילו בכחרדל טמא:"],[14,"לעולם","אפי' לרבי אליעזר בעי צירוף:"],[14,"וכי אמר רבי אליעזר","משוך ודאי מגופה אתא:"],[14,"בעד","שבודקת בו:"],[14,"אבל בכתם","שעל חלוקה כגריס ועוד בעינן:"]],[[0,"","היו בה טיפי דמים למטה וטיפי דמים למעלה תלינן בעליון עד כגריס. פ\"ה למטה קטנים למעלה גדולים תלינן בעליון הגדול בדם מאכולת עד כגריס מאי לאו עד כגריס כלמטה בפחות מכגריס לא כלמעלה ביותר מכגריס וזהו תימה אמאי נקט למעלה ולמטה הוה ליה למנקט גדולים וקטנים ועוד היכי משמע ליה כלמטה מאי אולמיה ממתניתין ועוד דלא הוה ליה למנקט כלמעלה וכלמטה דהוה ליה למימר כפחות מכגריס ויותר מכגריס לישנא דנקט עד הכא ונראה לי דה\"פ למטה למטה מן החגור למעלה למעלה מן החגור תולה בעליון אותו שלמטה נתלה בעליון דשמא כמו שעליון מעלמא אתי תחתון נמי מעלמא אתי ועוד כגריס נתלה בו וקאמר מאי לאו כגריס למטה דעד כגריס דקתני מיירי שהתחתון עד כגריס תולה בעליון שממקום שבא העליון בא התחתון מכלל דאי לאו עליון מטמינן ליה ולא תלינן בדם מאכולת אלמא כגריס כיותר מכגריס ומשני לא כגריס ולמעלה כלומר תולה תחתון בעליון כשהעליון עד כגריס ומלמעלה למטה קחשיב כשהעליון ג' גריסין או שני גריסין עד כגריס שאז אין אנו תולין עליון בדם מאכולת אלא מעלמא אתי אז נתלה בו התחתון ומיירי כשתחתון יותר מכגריס אבל אם היה העליון כגריס אז לא יהיה התחתון טהור שאין רגלים לדבר דאתא דם בה מעלמא שהרי העליון יש לתלותו בדם מאכולת:"],[3,"","נתעסקה בכגריס ומצאה עליה כגריס ועוד. אור\"י הוא הדין נתעסקה בפחות מכגריס ונמצא עליה כגריס ועוד דבכלל בעיא זו דאין לומר דבהא פשיטא ליה דאינה תולה אפי' לרבי ינאי דא\"כ כי פשיט לקמן מאי לאו בכה\"ג לוקמה בשנתעסקה בפחות מכגריס דפשיטא ליה דאינה תולה אלא ודאי בכל ענין בעי:"],[8,"","נמצא עליה מין אחד. פ\"ה מדבר הדומה לכתם כגון שרף או קילור דהא ודאי מעלמא אתא תולה בו כמה מיני כתמים ואינה מכרת אם דם היא ור\"י מפרש נמצא שמצאה מין אחד למעלה מן החגור תולה בו כמה מינים שלמטה מן החגור משום שכמו שהעליון ודאי מעלמא אתא כך נאמר בתחתון דמעלמא אתא:"]]],[["מתני׳ \u0001האשה\u0002 שהיא עושה צרכיה וראתה דם רבי מאיר אומר אם עומדת טמאה ואם יושבת טהורה ר' יוסי אומר בין כך ובין כך טהורה","איש ואשה שעשו צרכיהן לתוך הספל ונמצא דם על המים רבי יוסי מטהר ורבי שמעון מטמא שאין דרך האיש להוציא דם אלא שחזקת דמים מן האשה","\u0001גמ׳\u0002 מאי שנא עומדת דאמרינן מי רגלים הדור למקור ואייתי דם יושבת נמי נימא מי רגלים הדור למקור ואייתי דם","אמר שמואל במזנקת מזנקת נמי דלמא בתר דתמו מיא אתא דם","אמר ר' אבא ביושבת על שפת הספל ומזנקת בתוך הספל ונמצא דם בתוך הספל דאם איתא דבתר דתמו מיא אתא על שפת הספל איבעי ליה לאשתכוחי","אמר שמואל ואמרי לה אמר רב יהודה אמר שמואל הלכה כר' יוסי וכן אורי ליה רבי אבא לקלא הלכה כרבי יוסי","איש ואשה [כו'] איבעיא להו איש ואשה עומדין מה לי א\"ר מאיר","כי אמר רבי מאיר בחד ספקא אבל בספק ספקא לא מטמא או דלמא לא שנא","אמר ריש לקיש היא היא ממאי מדלא קתני ר' מאיר ורבי יוסי מטהרין","א\"ה השתא רבי מאיר בספק ספקא מטמא בחד ספקא מיבעיא להודיעך כחו דרבי יוסי דאפילו בחד ספקא מטהר","ואדמיפלגי בחד ספק להודיעך כחו דר' יוסי ליפלגו בספק ספקא להודיעך כחו דר' מאיר כח דהיתרא עדיף ליה","ור' יוחנן אמר כי קאמר רבי מאיר בחד ספקא אבל בספק ספקא לא אמר אם כן ליתני ר\"מ ור' יוסי מטהרין אין הכי נמי ואיידי דסליק מרבי יוסי פתח בדרבי יוסי","ורבי יוסי בחד ספקא מטהר בספק ספקא מיבעיא מהו דתימא הני מילי דיעבד אבל לכתחלה לא קא משמע לן","תניא כוותיה דרבי יוחנן איש ואשה שעשו צרכיהן לתוך הספל ונמצא דם על המים רבי מאיר ורבי יוסי מטהרין ור' שמעון מטמא","איבעיא להו אשה יושבת מה לי אמר רבי שמעון כי אמר רבי שמעון בעומדת דדחיק לה עלמא אבל יושבת לא או דלמא לא שנא","ת\"ש דתניא יושבת תולה עומדת אינה תולה דברי ר\"מ רבי יוסי אומר בין כך ובין כך תולה ר\"ש אומר בין כך ובין כך אינה תולה","איבעיא להו איש ואשה יושבין מה לי א\"ר שמעון כי אמר רבי שמעון עומדת דדחיק לה עלמא ויושבת דחד ספק אבל בספק ספקא לא אמר או דלמא לא שנה","ת\"ש כיון דא\"ר שמעון חזקת דמים מן האשה ל\"ש עומדין ולא שנא יושבין","\u0001מתני׳\u0002 השאילה חלוקה לנכרית או לנדה הרי זו תולה בה","ג' נשים שלבשו חלוק אחד או שישבו על ספסל אחד ונמצא עליו דם כולן טמאות","ישבו על ספסל של אבן או על האיצטבא של מרחץ רבי נחמיה מטהר שהיה רבי נחמיה אומר כל דבר שאינו מקבל טומאה אינו מקבל כתמים","\u0001גמ׳\u0002 אמר רב בנכרית"],[[0,"","מתני' האשה:"],[0,"אם עומדת","מפרש בגמרא:"],[1,"צרכיהן","מי רגלים:"],[1,"ר' יוסי מטהר","דהא אפי' באשה גרידתא מטהר דליכא אלא חד ספק ספק בא מן המקור ספק בא ממקום מי רגלים וכ\"ש הכא דדלמא מאיש אתו. ובגמרא פרכינן השתא בחד ספק מטהר בתרי ספקי מיבעיא:"],[3,"גמ' במזנקת","מקלחת דכיון דנפק בקילוח כי אורחא לא דחיקא ולא הדור מי רגלים למקור ואין דרך דם מקור לצאת עם מי רגלים אבל שותתת איידי דאוקמה אנפשה הוא ואיכא למימר הדור כאילו עומדת אבל עומדת אי אפשר לה לזנק:"],[3,"מזנקת","נהי נמי דלא הדור למקור מיהו מאן לימא לן דבהדי מי רגלים אתא דנימא ודאי לאו ממקור הוא מדאתא בהדי מי רגלים אלא ממקום מי רגלים ומכה יש בה:"],[3,"דלמא בתר דתמו מיא אתא דם","ממקור ולא מחמת מי רגלים:"],[5,"וכן אורי ליה לקלא","שם אדם שהוצרך לדבר:"],[6,"איש ואשה עומדין מאי אמר בה ר' מאיר","דמטמא באשה עומדת הכא איכא ספק ספקא להקל דלמא מאיש אתי ואפילו אם תמצי לומר דמינה אתא דלמא לא הדור מי רגלים למקור וממקום מכה בא:"],[8,"היא היא","כי היכי דמטמא ר' מאיר באשה לחודה הכי נמי מטמא באיש ואשה עומדין:"],[9,"בחד ספקא מיבעיא","ולמה ליה לפלוגי ר\"מ ברישא לאשמועינן בסיפא ר\"מ מטמא דלישתמעו תרוייהו:"],[12,"דיעבד","כגון שנתעסקה בטהרות אבל לכתחלה אומרין לה אל תתעסקי:"],[12,"קמ\"ל","ממשנה יתירתא דלא אצטריך דאפי' לכתחלה קאמר:"],[14,"אשה","לחודה יושבת ועושה צרכיה ונמצא דם בספל:"],[14,"מה לי א\"ר שמעון","מי אמרי' כי א\"ר שמעון בעומדת דכיון דעומדת אפי' איכא איש בהדה מטמא דכיון דאמר ר\"ש חזקת דמים מן האשה אין כאן ספק ספקא אבל יושבת ודאי ממקום מי רגלים אתא ותולה במכה:"],[16,"איש ואשה יושבין מה לי אמר ר\"ש","מי אמרי' כי אמר מתני' בעומדין ואלימא ליה עומדת דאפי' בתרי ספקי מטמא וברייתא נמי דמטמא ר\"ש ביושבת משום דליכא איש בהדה אבל הכא דתרתי לקולא יושבת ואיש בהדה לא:"],[17,"ת\"ש","מדקתני' חזקה אלמא לא מספקא דם באיש כלל:"],[18,"מתני' השאילה חלוקה לנכרית או לנדה","ואחר כך לבשתה היא ומצאה עליה כתם:"],[18,"הרי זו תולה בה","וטהורה דכיון דנדה היא לא מקלקלה לה מידי ונכרית נמי טמאה ותליא בה. אבל ישראלית טהורה ששאלה חלוק מחבירתה טהורה ואחר כך לבשתה חבירתה שתיהן טמאות כדקתני שלש נשים כו' דכיון דאי תליא בה מקלקלה לה מאי חזית דמקלקלה לה להך טפי מהך:"],[20,"של אבן","שאינו מקבל טומאה. וספסל דרישא בשל עץ דראוי ליטמא במושב הזב והנדה:"],[20,"אין מקבל כתמים","כלומר לא גזרו על כתמים. טעמא דרבי נחמיה מפרש בגמרא:"]],[[2,"","האשה. מאי שנא עומדת דאמר הדור מי רגלים למקור ואייתי דם. פרש\"י בריש פירקין דלעיל דאיידי דדחיק לה עלמא דמעומד השתינה ולא יכלה לעצור הדור מי רגלים למקור ואייתי דם יושבת נמי לימא הדור מי רגלים למקור דס\"ד השתא בשותתת דהשתא נמי דחיק לה עלמא ומשני במזנקת מקלחת כיון דנפיק כי אורחיה לא דחיק לה ולא הדור מי רגלים למקור דאין דרך לדם מקור לצאת עם מי רגלים אבל שותתת איידי דמוקמה אנפשה איכא למימר הדור כאילו עומדת אבל עומדת אי אפשר לה לזנק ופריך מזנקת נמי נהי דלא הדור למקור מיהו מאן לימא לן דבהדי מי רגלים אתא דנימא ודאי לאו ממקור הוא דאתא כיון דאתו בהדי מי רגלים אלא ממקום מי רגלים באו ומכה יש בה דלמא בתר דתמו מיא אתא דם ממקור ולא ממי רגלים ע\"כ לשון רש\"י וקשה על מה שפי' דעומדת אי אפשר לה לזנק א\"כ אמאי נקט כלל עומדת לא ליתני אלא יושבת וליפלוג בין מזנקת לשותתת ויש ליישב פ\"ה דנקט עומדת משום דפסיקא ליה דלעולם שותתת היא אי נמי משום ר' יוסי נקט לה דאפי' בעומדת שאין רחמה נפתח מטהר ועוד יש לומר דעומדת שפיר אפשר לה לזנק והמקשה היה סבור דמתניתין איירי בכל ענין בין בשתיתה בין בזנוק ולהכי פריך מאי שנא עומדת דטמאה משום חדא ריעותא דאין רחמה נפתח אע\"ג דמזנקת יושבת נמי תהא טמאה היכא דשותתת ומשני דכולה איירי דווקא במזנקת והא דלא מפליג ביושבת גופה וליתני דטמאה בשותתת משום דבעי לאשמועינן דעומדת טמאה היא אפי' מזנקת ועוד י\"ל דהמקשה סבר דאיירי מתני' בשותתת דבמזנקת אפי' עומדת טהורה דליכא למימר הדור הואיל ומזנקת ולהכי פריך יושבת כיון דשותתת ואיכא חדא לריעותא ומשני דאיירי במזנקת ואפילו הכי עומדת טמאה דאיכא למימר הדור כו' ובעינן תרתי לטיבותא:"],[3,"","דלמא בתר דתמו מיא. פירוש אפילו במזנקת דלמא בתר שהניחה מלזנק ושותתת הדור למקור ואתי דם אבל על פי' הקונטרס דפי' דלאחר שכלו מי רגלים אתא דם כי אורחא קשה דאם כן בשעה שמזנקת נמי לפרוך דילמא בא דם כדרכו כשאר אשה שהיא רואה אלא ודאי פשיטא ליה מדלא חזאי קודם עשיית צרכיה או אחר כך אם כן הדם לאו ממילא אתא אלא על ידי מי רגלים שחזרו למקור ואתא דם ושמא בשעת זינוק אי אפשר לדם לבא כדרכו שמחמת הזינוק נסתם המעיין של דם:"],[5,"","וכן אורי ליה רבי אבא לקלא. נראה דקלא שם חכם אבל ל\"ג לקולא דמה לו להזכירו:"],[8,"","מדלא קאמר ר' מאיר ור' יוסי מטהרין. וא\"ת אדרבה מדלא קאמר רבי מאיר ורבי שמעון מטמאין שמע מינה שרבי מאיר מטהר וי\"ל דלא הוה מצי למיתני הכי דהא מסיק דחזקת דמים מן האשה ומהא מסיק לקמן דר' שמעון מטמא אפילו באיש ואשה יושבים ורבי מאיר מטהר אפילו באשה יושבת:"],[14,"","(לעיל) יושבת מה לי אמר ר\"ש. מדלא קאמר ר\"מ ור' שמעון מטמאים ליכא למפשט דלרבי יוחנן מטהר ר\"מ בספק ספקא ומיהו מרישא ה\"מ למפשט מדלא קאמר ר' מאיר ור\"ש אומרים עומדת טמאה יושבת טהורה אלא דעדיפא מייתי מברייתא:"]]],[["הרואה","ממאי דומיא דנדה מה נדה דקחזיא אף נכרית דקא חזיא","אמר רב ששת כי ניים ושכיב רב אמרה להא שמעתא דתניא תולה בנכרית רבי מאיר אומר בנכרית הראויה לראות ואפילו ר\"מ לא קאמר אלא בראויה לראות אבל רואה לא איצטריך","אמר רבא ותסברא ר\"מ לחומרא רבי מאיר לקולא","דתניא אינה תולה בנכרית רבי מאיר אומר תולה ואלא קשיא הך תריץ הכי והיא שרואה ר' מאיר אומר בראויה לראות ואף ע\"פ שאינה רואה","ת\"ר תולה בשומרת יום כנגד יום בשני שלה","ובסופרת שבעה שלא טבלה לפיכך היא מתוקנת וחברתה מקולקלת דברי רשב\"ג רבי אומר אינה תולה לפיכך שתיהן מקולקלות","ושוין שתולה בשומרת יום כנגד יום בראשון שלה","וביושבת על דם טוהר ובבתולה שדמיה טהורין","לפיכך דרשב\"ג למה לי משום דרבי","לפיכך דרבי למה לי מהו דתימא ההיא דאשתכח כתם גבה תתקלקל אידך לא תתקלקל קמשמע לן","אמר רב חסדא טמא וטהור שהלכו בשני שבילין אחד טהור ואחד טמא באנו למחלוקת רבי ורשב\"ג","מתקיף לה רב אדא עד כאן לא קאמר רבי התם אלא דתרוייהו כי הדדי נינהו הכא מאי נפקא לן מינה","ורב חסדא סוף סוף איהי טבילה בעיא","איתמר א\"ר יוסי בר' חנינא טמא וטהור ואפילו טהור ותלוי שהלכו בשני שבילין אחד טמא ואחד טהור תולה טמא בתלוי וטהור בטהור לדברי הכל","בעא מיניה ר' יוחנן מרבי יהודה בר ליואי מהו לתלות כתם בכתם אליבא דרבי לא תבעי לך","השתא ומה התם דקא חזיא מגופה אמרת אינה תולה הכא דמעלמא קא אתי לא כל שכן","כי תבעי לך אליבא דרשב\"ג התם הוא דקא חזיא מגופה תליא הכא דמעלמא קאתי לא תליא או דלמא לא שנא","א\"ל אין תולין מה טעם לפי שאין תולין","איתיביה אין תולין כתם בכתם השאילה חלוקה לנכרית או ליושבת על הכתם הרי זו תולה בה","הא גופה קשיא רישא אמרת אין תולין סיפא אמרת תולין הא לא קשיא הא רבי והא רשב\"ג","איכא דאמרי הא והא רבי הא בראשון שלה הא בשני שלה","רב אשי אמר הא והא רשב\"ג ולא קשיא"],[[0,"הרואה","שגדולה היא וידעינן בה דכבר ראתה:"],[2,"ראויה לראות","שהגיעו ימי הנעורים:"],[3,"ותסברא רבי מאיר לחומרא הוא","דתימא דלתנא קמא אפילו אינה ראויה ותשמע מינה דלתרוייהו לא בעינן שראתה כבר והא תניא דרבי מאיר לקולא מכלל דלת\"ק לא סגי בראויה לראות עד שתהא רואה ממש:"],[4,"ופרכינן אלא קשיא הך","קמייתא דמשמע דר' מאיר לחומרא:"],[4,"תריץ הכי כו'","וברייתא דקתני אינה תולה בנכרית לת\"ק הכי קאמר אינה תולה בנכרית הראויה לראות אלא אם כן רואה ר' מאיר אומר תולה ותרוייהו מתניתא חדא מילתא אמרי ורב דאמר כתנא קמא דתרוייהו:"],[5,"בשני שלה","אם השאילתה לשומרת יום בשני שלה תולה בה ואף על גב דלא הוחזקה רואה היום כיון דמעיינה פתוח תולה בה ואע\"ג דמקלקלה לה פורתא דצריכה לשמור יום המחרת כיון דטמאה השתא:"],[6,"ובסופרת ז'","נקיים אחר זיבה ואף ע\"פ שמקלקלה הרבה שסתרה כל ימי ספירתה וצריכה לספור ז' נקיים הואיל ועכשיו טמאה תולה בה:"],[6,"וחברתה מקולקלת","שומרת יום צריכה עוד לשמור שלישי בשביל כתם זה ואם סופרת היא סותרת כל שלפניה:"],[6,"רבי אומר אינה תולה","הואיל ומקלקלה לה מאי חזית דמקלקלת להך טפי מהך:"],[7,"ושוין שתולה בשומרת יום כנגד יום בראשון שלה","דלא מקלקלה מידי:"],[8,"וביושבת על דם טוהר ובבתולה שדמיה טהורין","דלא מקלקלה לה מידי שאין לה כתם כדאמרי' בפ' קמא (נדה דף י:) זו שירפה מצוי ותלינן כתמה בדם בתולים:"],[9,"לפיכך דרבן שמעון למה לי","כיון דתנא תולה בה פשיטא דהיא מתוקנת וזו מקולקלת:"],[11,"שהלכו בשני שבילין","ולא ידענא הי להאי על והי להאי על:"],[11,"באנו למחלוקת","לרבן שמעון דאמר תולין כתם בשומרת יום הכא נמי תולין שביל טמא באדם טמא וטהור בטהור ולרבי שניהם טמאים:"],[12,"עד כאן לא אמר רבי","דשניה טמאה:"],[12,"אלא משום דכי הדדי נינהו","שתיהן היו בחזקת טהרה השומרת יום בשני שלה ראויה לטבול כל שעה שתרצה כיון שספרה שעה אחת הילכך אין כאן טומאה שתוכל לתלות בה יותר מזאת לפיכך שתיהן טמאות אבל הכא דטמא הוא מאי נפקא ליה מינה אי תלית ביה הילכך אפילו לרבי תלינן:"],[13,"ורב חסדא אמר סוף סוף","הך שומרת יום טבילה היא בעיא הילכך טמאה הואי ואפילו הכי קאמר רבי לא תלינן בה:"],[14,"איתמר נמי","כרב אדא דאמר אפילו לרבי תלינן שביל טמא בטמא. וכמדומה לי דלא גרס נמי:"],[14,"טמא וטהור","או אפילו טהור ותלוי שהלכו כו' תולה טהור את שביל טמא בתלוי:"],[14,"לדברי הכל","ואפילו לרבי וכדאמרינן דהתם הוא דכי הדדי נינהו אבל הכא דתלוי טמא מספק וטהור טהור גמור תולין טומאה בתלוי:"],[15,"כתם בכתם","השאילה חלוקה לבעלת הכתם ואח\"כ לבשתה היא מהו שתתלה בראשונה להיות היא טהורה:"],[16,"","שומרת יום חזאי אתמול מגופה:"],[17,"לא תליא","ושתיהן טמאות:"],[18,"לפי שאין תולין","דמעלמא אתי לה טומאת כתם קמא ולא בחזקת רואה היא:"],[21,"בשני שלה","אינה תולה דמקלקלה לה שמארכת ימי טומאת כתמה יום אחד אבל ביום ראשון שלבשה חלוק זה ביום ראשון (לכתמה הראשון) תולה דלא מקלקלה לה מידי:"]],[[5,"","תולה בשומרת יום כנגד יום. מספקא ליה להר\"י אם טמא קל כגון סופרת מקצת או הכל ולא טבלה תולה בלא ספרה כלל בין בנדה בין בטמא מת ושבילי דשמעתין לא איירי אלא בטהור וטמא:"],[11,"","טמא וטהור שהלכו בשני שבילין. הך טמא לא מיירי בטמא שספר והזה אלא שלא טבל מדקאמר רב אדא התם כי הדדי נינהו הכא מאי נפקא ליה מינה משמע דלאו דומיא דפלוגתא לעיל הוא ובטמא שלא ספר כלל נמי לא איירי דאפילו רבי מודה דתולה כדאמר ושוין כו' ואמאי קאמר רב חסדא באנו למחלוקת אלא מיירי בטמא שספר קצת וס\"ל לרב חסדא דלרבי אפי' בספרה קצת אינה תולה ורב אדא דקאמר מאי נפקא ליה מינה לא קרי הפסד כיון דלא סתר הכל והא דנקט סופרת ז' שלא טבלה לרבותא דרשב\"ג נקטיה דאפ\"ה תולה:"],[11,"","באנו למחלוקת דרבי ורשב\"ג. וא\"ת ורב חסדא אמאי לא נקט מילתיה בזבה גופה ולימא זבה שספרה מקצתה באנו למחלוקת כו' וי\"ל דניחא ליה לאשמועינן דאפי' בב' שבילין מטמא דאע\"ג דהוי ספק טומאה ברה\"ר וא\"ת אם כן מה ענין כתמים לשבילין דאע\"ג דבתרוייהו אתרע חזקת טהרה דידהו קצת מ\"מ יש לטהר יותר בשבילין משום ספק טומאה ברה\"ר וי\"ל דגבי כתם נמי איכא למימר דלא אתרע חזקתה כלל דאיכא למתלי בחברתה כמו בשוק של טבחים ואפ\"ה לרבי אינה תולה משום דמ\"ש זו מזו כיון ששניהם טהורין שספרה כבר ז' ימים הכי נמי מאי חזית דתלינן בטמא שספר מקצת טפי מבטהור גמור ואע\"ג דאית ליה חזקה דטהרה מיחזי כי חוכא ואטלולא דמהאי טעמא מטמינן ב' טהורין שהלכו בשני שבילין ובאו לשאול בבת אחת דטהורין מדינא ומטמינא להו כי היכי דלא ליהוי כי חוכא ואע\"ג דלא דמי דהתם אי מטהרין לתרוייהו הוי חוכא דאי אפשר להיות ששניהם טהורין אבל הכא אפשר דטהור הלך בטהור מ\"מ הוי חוכא דאמאי תלינן טפי בטמא מבטהור כדאמר לעיל גבי נשים וא\"ת מ\"ש משני קופות דאמרינן חולין לתוך חולין נפלו וי\"ל דהתם אינו מפסיד לחברתה בתלייתו כלום והכא נמי אפילו רבי מודה שתולה בנדה גמורה שלא טבלה כלל:"],[15,"","מהו לתלות כתם בכתם. אומר הר\"י דליכא למימר דבעי לתלות בסופרת שבעה שלא טבלה אבל בראשון פשיטא ליה דתולה דאם כן מאי קאמר לקמן מ\"מ קשיא הא איכא לשנויי בין לרבי בין לרשב\"ג בראשון שלה איירי ברייתא ועוד דאליבא דרבי נמי ה\"ל למבעי בראשון שלה כיון דלא חזיא מגופה אלא אפי' בראשון שלה מבעי ליה ופשיט ליה דאין תולין אפי' לרשב\"ג אלא לחזיא מגופה והשתא לכולהו שינויי קשה לר' יהודה בר ליואי והא דקמשני הא והא רבי הא בראשון שלה והא בשני שלה הש\"ס הוא דקמהדר לשנויי בכל ענין שיכול לתרץ ולא בשיטתיה דר\"י דהא קאמר אליבא דרבי לא תבעי לך ואוקימנא בעיא שלו אפילו בראשון שלה וקאמר כיון דהיכא דמגופה חזיא לא תלינן בשני שלה לרבי בכתם לא תלינן אפילו בראשון שלה:"]]],[["כאן למפרע כאן להבא","מכל מקום קשיא אמר רבינא לא קשיא הכי קאמר השאילה חלוקה לנכרית בעלת כתם הרי זו תולה בה","והא או ליושבת על הכתם קתני הכי קאמר או ליושבת על דם טוהר בעלת כתם תולה בה","שלש שלבשו כו' שהיה ר' נחמיה כו' אמר רב מתנה מ\"ט דר' נחמיה דכתיב (ישעיהו ג, כו) ונקתה לארץ תשב כיון שישבה לארץ נקתה","אמר רב הונא אמר רבי חנינא מטהר היה רבי נחמיה אפילו באחורי כלי חרס פשיטא","מהו דתימא ליגזור גבו אטו תוכו קמ\"ל","אמר אביי מטהר היה ר' נחמיה במטלניות שאין בהן שלש על שלש דלא חזיין לא לעניים ולא לעשירים","דרש רב חייא בר רב מתנה משמיה דרב הלכה כר' נחמיה אמר ליה רב נחמן אבא תני מעשה בא לפני חכמים וטמאום ואת אמרת הלכה כרבי נחמיה","מאי היא דתניא שתי נשים שהיו טוחנות ברחיים של יד ונמצא דם תחת הפנימית שתיהן טמאות תחת החיצונה החיצונה טמאה והפנימית טהורה בינתים שתיהן טמאות","היה מעשה ונמצא דם על שפתה של אמבטי ועל עלה של זית בשעה שמסיקות את התנור ובא מעשה לפני חכמים וטמאום","תנאי היא דתניא ר' יעקב מטמא ורבי נחמיה מטהר והורו חכמים כרבי נחמיה","\u0001מתני׳\u0002 שלש נשים שהיו ישנות במטה אחת ונמצא דם תחת אחת מהן כולן טמאות בדקה אחת מהן ונמצאת טמאה היא טמאה ושתיהן טהורות ותולות זו בזו ואם לא היו ראוין לראות רואין אותן כאילו הן ראויות","\u0001גמ׳\u0002 אמר רב יהודה אמר רב והוא שבדקה עצמה בשיעור וסת","סבר לה כבר פדא דאמר כל שבעלה בחטאת טהרותיה טמאות","בעלה באשם תלוי טהרותיה תלויות בעלה פטור טהרותיה טהורות","ורבי אושעיא אמר אפילו בעלה בחטאת טהרותיה תלויות","בשלמא התם אימר שמש עכביה לדם [אבל] הכא אם איתא דהוי דם מאן עכביה","א\"ר ירמיה משל דר' אושעיא למה הדבר דומה לילד וזקן שהיו מהלכין בדרך כל זמן שהיו בדרך ילד שוהא לבא נכנסו לעיר ילד ממהר לבא ואמר אביי משל דר' אושעיא למה הדבר דומה לאדם שנותן אצבע בעין כל זמן שאצבע בעין דמעה שוהא לבא נטל האצבע דמעה ממהרת לבא","ותולות זו בזו ת\"ר כיצד תולות זו בזו עוברה ושאינה עוברה תולה עוברה בשאינה עוברה","מניקה ושאינה מניקה תולה מניקה בשאינה מניקה זקנה ושאינה זקנה תולה זקנה בשאינה זקנה בתולה ושאינה בתולה תולה בתולה בשאינה בתולה","היו שתיהן עוברות שתיהן מניקות שתיהן זקנות שתיהן בתולות זו היא ששנינו לא היו ראויות לראות רואין"],[[0,"כאן למפרע","לענין טומאת מפרע תולין דלא מקלקלה לה בהכי ולא תטמא למפרע אבל מכאן ולהבא אין תולה דמקלקלה לה ומאי חזית דמקלקלה לה טפי מינה:"],[1,"מכל מקום קשיא","דלרבן שמעון תולין וקשיא לבר ליואי:"],[1,"אמר רבינא","תריץ רישא וסיפא הכי ולא תקשי לבר ליואי:"],[1,"לנכרית בעלת הכתם הרי זו תולה בה","כלומר לנכרית הרואה הרי בעלת הכתם זו תולה בנכרית:"],[2,"והא או ליושבת קתני","והך לאו יושבת היא דהא השתא היא דאישתכח עלה ויושבת משמע שהתחילה למנות שבעת ימים:"],[2,"הכי קאמר","השאילה חלוקה לנכרית או לישראלית יושבת על דם טוהר דדמיה טהורין ואין כאן קלקול הרי בעלת כתם תולה בה:"],[5,"אטו תוכו","דדבר המקבל טומאה הוא ומקבל גזרת כתמים לטמא אשה מדרבנן:"],[8,"פנימית","שאצל הרחיים:"],[8,"שתיהן טמאות","שחיצונה דוחקת עצמה להתקרב אל הרחיים ועוברת ונכנסה למעמדה הפנימית הילכך שתיהן עברו שם ולא ידעינן מהי נפל:"],[8,"הפנימית טהורה","שהפנימית אינה מתרחקת מן הרחיים ליכנס במעמד החיצון:"],[9,"אמבטי","מרחץ שהיו באות לרחוץ:"],[9,"וטמאום","והא עלה של זית דלא מקבל טומאה ומקבל כתמים ומדקתני והביאום לפני חכמים מכלל דרבים פליגי עליה:"],[10,"תנאי היא","דאיכא תנא דתנא דיחידאה פליג עליה ורבנן מודו ליה:"],[11,"מתני' ותולות זו בזו","בגמרא מפרש לה שאם היתה האחת מעוברת תולה הדם בשאינה מעוברת והיא טהורה:"],[11,"ואם לא היו ראויות וכו'","בגמ' מפרש שאם היו כולן מעוברות או כולן מניקות כולן טמאות כאילו ראויות לראות דאמרן דם מבינייהו נפק:"],[12,"גמ' והוא שבדקה עצמה כשיעור וסת","של מציאתה הילכך מחזקינן האי דם בדידה ואינך טהורות:"],[13,"כבר פדא דאמר כל שבעלה בחטאת כו'","אשה שנתעסקה בטהרות ופרשה וראתה דם כשיעור וסת דלגבי בעלה בכי האי שיעורא הוי בעלה בחטאת דמחזקינן האי דם בשעת בעילה ודאי הכא נמי מחזקינן ליה בודאי בשעת עסיקתה בהנך טהרות וטהרות טמאות ודאי ושורפין ואינו כשאר מעת לעת לתלות:"],[14,"בעלה באשם תלוי","אם לאחר שפירשה מן הטהרות שהתה כדי שתרד מן המטה ותדיח פניה דאי לגבי בעלה בכי האי שיעורא הוי בעלה באשם תלוי דספק דם הוה בשעת ביאה ספק בתר הכי ה\"נ ספק הוא אי הוה דם בשעת טהרות או לאו טהרותיה תלויות:"],[14,"בעלה פטור","כגון שהתה יותר מכן דלגבי בעלה פטור דאפי' אשם תלוי ליכא דמחזקי' להאי דם לאחר ביאה הכא נמי טהרותיה טהורות ולית ליה לבר פדא טומאה מעת לעת כשמאי דאמר דיין שעתן או בארבע נשים שאמרו דיין שעתן ומתני' נמי דקתני היא טמאה וכולן טהורות אלמא ודאי בדידה מחזקינן דמטהרינן להנך אלמא כבר פדא הוא דמשוי לטהרות טומאה ודאית היכא דבדקה שיעור וסת ולא כר' אושעיא דאמר אפי' בעלה בחטאת טהרותיה תלויות ואפי' כשיעור וסת לית ליה טומאה ודאית:"],[16,"בשלמא התם","גבי בעילה כי ראתה כשיעור וסת אמרינן בשעת ביאה הוה דם והאי דלא אתא עד השתא שמש עכביה אבל גבי טהרות אם איתא דהוה דם בשעת טהרות מאן עכביה הלכך ודאי טומאה ליכא אלא גזרת מעת לעת מדרבנן:"],[17,"משל דר' אושעיא","דאמר שמש מעכב את הדם:"],[17,"ילד שוהא לבא","הולך בנחת וממתין לזקן:"],[17,"נכנסו לעיר","ונפרדו זה לצד ביתו וזה לצד ביתו אז הילד ממהר לבא:"],[18,"עוברה","דמיה מסולקין וכן מניקה וזקנה. בתולה האי בתולה בתולת דמים שלא ראתה מימיה ואפילו היא נשואה קרי לה בתולה להכי כדאמרינן בפרק קמא (לעיל נדה דף ח:):"]],[[0,"","כאן למפרע כאן להבא. פרש\"י למפרע תולה דלא מקלקלה לה בהכי ולא תטמא למפרע להבא אינה תולה בבעלת כתם בשני שלה דמקלקלה לה ומאי חזית דמקלקלה לה להך טפי מינה וזהו תימה שנתלה זה הכתם בחברתה לחצאין ומפרש הר\"י למפרע אם בעלת הכתם הכירה בכתמה ואח\"כ לבשה היא וחברתה חלוק ונמצא בה כתם תולה בה כיון שכבר הכירה בטומאה קודם שבא הספק בשתיהן כאן להבא שלבשו שתיהן חלוק ונמצא בו כתם ולא נודע ממי הוא ואח\"כ לבשה חלוק ונמצא בו כתם אע\"ג שזאת ודאי טמאה ע\"י כתם שלה הואיל ולא נודע בה עד אחר שאירע בה ובחברתה הספק אינה תולה ויש לפרש לשון הש\"ס איפכא למפרע אין תולין ולהבא תולין וקאי למפרע ולהבא אשאלת החלוק אם שאלת החלוק היה למפרע קודם שבעלת החלוק הכירה כתמה ולהבא ששאלת החלוק שממנו אירע הספק בשתיהן היתה אחר מציאת הכתם של בעלת הכתם תולין והיא היא:"],[6,"","במטלניות שאין בהן שלש על שלש. והכא לא פריך פשיטא כמו לעיל דבזבחים פרק דם חטאת (זבחים דף צד.) משמע דאי חשיב עלייהו ויחדם מקבלים טומאה:"],[12,"","והוא שבדקה עצמה כשיעור וסת. לאו דוקא בדקה אלא קנחה כדאמר בפ\"ק (לעיל נדה דף יב.) דלא משכחת בדיקה כשיעור וסת:"],[14,"","בעלה פטור טהרותיה טהורות. פ\"ה ולית ליה טומאה מעת לעת כשמאי אי נמי בד' נשים שדיין שעתן ועוד י\"ל באשה שיש לה וסת אי נמי בחולין שאין בהן טומאה מעת לעת:"],[16,"","אימא שמש עכביה לדם אבל הכא כו'. וא\"ת כיון דיכול להיות דאע\"ג דנמצא כשיעור וסת שלא היה דם בשעת ביאה אם כן אמאי בעלה בחטאת הא ספק הוא וי\"ל כיון דרוב פעמים בא מקודם ובתשמיש דאיכא למתלי בעיכוב שמש טמא מן התורה:"],[18,"","עוברה ושאינה עוברה כו'. אור\"י דדוקא בהך ענינא דקאמר הש\"ס תולין אבל יש לה וסת דמסולקת בדמים דהא אמרינן בה דיה שעתה אינה תולה באין לה וסת וכן יש לה וסת ולא הגיע שעת וסתה אין תולה בהגיע שעת וסתה:"]]],[["כאילו הן ראויות","\u0001מתני׳\u0002 שלש נשים שהיו ישנות במטה אחת ונמצא דם תחת האמצעית כולן טמאות תחת הפנימית שתים הפנימיות טמאות והחיצונה טהורה תחת החיצונה שתים החיצונות טמאות והפנימית טהורה","אימתי בזמן שעברו דרך מרגלות המטה אבל אם עברו דרך עליה כולן טמאות בדקה אחת מהן ונמצאת טהורה היא טהורה ושתים טמאות בדקו שתים ומצאו טהורות הן טהורות ושלישית טמאה שלשתן ומצאו טהורות כולן טמאות","למה הדבר דומה לגל טמא שנתערב בין שני גלים טהורים ובדקו אחת מהן ומצאו טהור הוא טהור ושנים טמאים שנים ומצאו טהורין הם טהורין ושלישי טמא","שלשתן ומצאו טהורין כולן טמאים דברי ר\"מ שר\"מ אומר כל דבר שהוא בחזקת טומאה לעולם הוא בטומאתו עד שיודע לך טומאה היכן היא","וחכמים אומרים בודק עד שמגיע לסלע או לבתולה","\u0001גמ׳\u0002 מאי שנא רישא דלא מפליג ומאי שנא סיפא דקמפליג אמר רבי אמי במשולבות","בדקה אחת [וכו'] למה ליה למתני למה זה דומה","הכי קאמר להו ר' מאיר לרבנן מ\"ש בדם דלא פליגיתו ומ\"ש בגל דפליגיתו","ורבנן בשלמא התם אימא עורב נטלה אלא הכא האי דם מהיכא אתא","תניא אמר ר\"מ מעשה בשקמה של כפר סבא שהיו מחזיקין בה טומאה ובדקו ולא מצאו לימים נשבה בו הרוח ועקרתו ונמצא גולגולת של מת תחובה לו בעיקרו אמרו לו משם ראיה אימר לא בדקו כל צרכו","תניא א\"ר יוסי מעשה במערה של שיחין שהיו מחזיקין בה טומאה ובדקו עד שהגיעו לקרקע שהיתה חלקה כצפורן ולא מצאו לימים נכנסו בה פועלים מפני הגשמים ונתזו בקרדומותיהן ומצאו מכתשת מלאה עצמות אמרו לו משם ראיה אימר לא בדקו כל צרכו","תניא אבא שאול אומר מעשה בסלע בית חורון שהיו מחזיקין בה טומאה ולא יכלו חכמים לבדוק מפני שהיתה מרובה והיה שם זקן אחד ורבי יהושע בן חנניא שמו אמר להן הביאו לי סדינים הביאו לו סדינים ושראן במים ופרסן עליהם מקום טהרה יבש מקום טומאה לח ובדקו ומצאו בור גדול מלא עצמות","תנא הוא הבור שמילא ישמעאל בן נתניה חללים דכתיב (ירמיהו מא, ט) והבור אשר השליך שם ישמעאל את כל פגרי אנשים אשר הכה ביד גדליה","וכי גדליה הרגן והלא ישמעאל הרגן אלא מתוך שהיה לו לחוש לעצת יוחנן בן קרח ולא חש מעלה עליו הכתוב כאילו הרגן","אמר רבא האי לישנא בישא אע\"פ דלקבולי לא מבעי מיחש ליה מבעי","הנהו בני גלילא דנפק עלייהו קלא דקטול נפשא אתו לקמיה דרבי טרפון אמרו ליה לטמרינן מר אמר להו היכי נעביד אי לא אטמרינכו חזו יתייכו אטמרינכו הא אמור רבנן האי לישנא בישא אע\"ג דלקבולי לא מבעי מיחש ליה מבעי זילו אתון טמרו נפשייכו","(במדבר כא, לד) ויאמר ה' אל משה אל תירא מכדי סיחון ועוג אחי הוו דאמר מר סיחון ועוג בני אחיה בר שמחזאי הוו מאי שנא מעוג דקמסתפי ומאי שנא מסיחון דלא קמסתפי","א\"ר יוחנן אר\"ש בן יוחי מתשובתו של אותו צדיק אתה יודע מה היה בלבו אמר שמא תעמוד לו זכות של אברהם אבינו","שנאמר (בראשית יד, יג) ויבא הפליט ויגד לאברם העברי ואמר רבי יוחנן זה עוג שפלט מדור המבול","תנו רבנן בגד שאבד בו כתם מעביר עליו שבעה סממנין ומבטלו רבי שמעון בן אלעזר אומר"],[[0,"כאילו הן ראויות","לראות ושתיהן טמאות דמכל מקום דם מבינייהו נפיק:"],[1,"מתני' חיצונה","קרי להך דלצד דרך עליית המטה. פנימית אותה שלצד הקיר. ובגמרא מפרש מאי שנא הכא דמפליג בין נמצא תחת הפנימית לנמצא תחת אמצעית וברישא קתני תחת אחת מהן כולן טמאות אפילו נמצא תחת פנימית או חיצונה:"],[2,"אימתי","אמרו נמצא תחת חיצונה פנימית טהורה בזמן שעלו דרך מרגלות המטה דלא עברה פנימית על מקום מציאת הדם:"],[2,"אבל עברו","שלשתן דרך עלייה שהן דורסות ועוברות על החיצונה כולן טמאות ואפי' פנימית דשמא כשעברה פנימית דרך שם נפל ממנה:"],[3,"גל טמא","שהיה שם כזית מן המת:"],[5,"לבתולה","קרקע בתולה ואם לא מצא הגל טהור:"],[6,"גמ' מאי שנא רישא","דקתני לעיל נמצא דם תחת אחת מהן כולן טמאות ולא מפליג בין נמצא תחת אמצעית לנמצא תחת פנימית או חיצונה:"],[6,"א\"ר אמי רישא במשולבות","תכופות ודבוקות יחד הלכך אפילו נמצא תחת הפנימית איכא לספוקי נמי בחיצונה:"],[8,"מאי שנא בדם דלא פליגיתו","דמודים אתם לי דהיכא דנמצא שלשתן טהורות כולן טמאות:"],[8,"ובגל","אתם חלוקים עלי דאם בדק ולא מצא טהור ואע\"ג דמוחזק לן דהואי טומאה בחד מינייהו:"],[11,"לקרקע חלקה כצפורן","לקרקע חלקה שלא נזרעה מעולם:"],[12,"מקום הטומאה לח","שנבלעו שם מים של סדין מתוך שהיה העפר רך:"],[13,"ביד גדליה","משמע שע\"י גדליה נהרגו:"],[14,"יוחנן בן קרח","אמר לו לגדליה שמעתי שבא ישמעאל בן נתניה להרגך (ירמיהו מ׳:י״ד):"],[15,"מיחש ליה מיבעי","ושמא הרגתם ואסור להציל אתכם:"],[17,"בני אחיה","שבא משמחזאי ועזאל שני מלאכים שירדו בדור אנוש:"],[18,"מתשובתו של אותו צדיק","הוצרך הקב\"ה להשיב שלא יירא ממנו:"],[19,"עוג פלט מן המבול","שברח לא\"י כדאמרינן בחלק:"],[20,"שאבד בו כתם","כגון שנכנס במים או נגלל בדם בהמה ואין נודע מקום הנדות וקי\"ל במתני' אין דם הנדות טהור בלא שבעה סממנין:"],[20,"מעביר [עליו] ז' סממנין","על הבגד:"],[20,"ומבטלו","לדם והאי דנקט הך ברייתא הכא משום דאיירי לעיל בגלים שאבדה בהם טומאה ואין ידוע מקומה:"]],[[6,"","אמר רבי אמי [רישא] במשולבות. פ\"ה רישא דלא מפליג איירי במשולבות ותכופות זו לזו ולהכי איכא לספוקי בכולהו ובהרבה ספרים לא גרסינן רישא ואומר הר\"י דיש לפרש דסיפא איירי במשולבות כלומר מכוונות כל אחת במקומה ולא היו תכופות ומעורבות זו בזו ובפירוש ר\"ח כתוב דמשלחפי שלחופי שמתפרדות זו מזו:"],[12,"","מקום טהרה לח. אסדינים קאי דמתוך שהיה הקרקע קשה לא בלע מים שבהסדינין ומקום הטומאה יבש ואית ספרים דגרסינן איפכא מקום טומאה לח ואקרקע קאי שהיה לח מחמת הסדינין שבלע לפי שהיה רך ותיחוח וכה\"ג בדק רבי יוחנן בן זכאי כשקצץ תורמוסי תרומה בעובדא דרבי שמעון בן יוחי במסכת שבת (דף לד.):"],[16,"","אטמרינכו הא אמור רבנן האי לישנא בישא כו'. פי' בקונטרס ושמא הרגתם ואסור להצילכם ובשאלתות דרב אחאי מפרש שמא הרגתם ואם אטמין אתכם חייבתם ראשי למלך והיינו מיחש מיבעי ליה למיחש שיש לחוש ללשון הרע להאמינו לגבי זה שיזהר שלא יבא לו הפסד ולא לאחרים:"],[19,"","זה עוג שפלט מדור המבול. הכי נמי נפלט סיחון מדור המבול כיון דאחי הוו אלא דהך הפליט קים ליה דהוא עוג ולא סיחון מהאי טעמא גופיה כיון דדחיל ליה משה ועוד אמר (בפרק רבי אליעזר) (דף לד) שעוג מצאו לאברהם אבינו שהיה עומד בגרנות לתקן עוגות לפסח ועל שם זה נקרא עוג ומייתי ליה משום דמחזי כלישנא בישא דאמר במדרש עוג אמר בלבו אלך ואומר לאברהם וילחם וימות ואשא שרה אשתו אפילו הכי היה ירא משה שמא תעמוד לו זכות אברהם:"],[20,"","מעביר עליו שבעה סממנין. וא\"ת ומה צריך להעביר עליו הלא כיון שאבד ואינו ניכר אינו מקפיד עליו ובטל ממילא כדקתני ר' חייא לקמן (נדה דף סב:) דם הנדה ודאי מעביר עליו ז' סממנין ומבטלו שכיון שהעביר עליו אזל ליה חזותא ואינו מקפיד עליו יותר אע\"פ שניכר אלא בקפידא תליא מילתא ויש לומר דהכא קרי שפיר מקפיד עליו דאם אינו מוצאו עכשיו שמא ימצאנו פעם אחרת:"]]],[["בודקו שכונות שכונות","אבדה בו שכבת זרע חדש בודקו במחט שחוק בודקו בחמה תנא אין שכונה פחותה משלש אצבעות","ת\"ר בגד שאבד בו כלאים הרי זה לא ימכרנו לעובד כוכבים ולא יעשנו מרדעת לחמור אבל עושה ממנו תכריכין למת אמר רב יוסף זאת אומרת מצות בטלות לעתיד לבא","א\"ל אביי ואי תימא רב דימי והא א\"ר מני א\"ר ינאי לא שנו אלא לספדו אבל לקוברו אסור א\"ל לאו איתמר עלה א\"ר יוחנן אפילו לקוברו","ור' יוחנן לטעמיה דא\"ר יוחנן מאי דכתיב (תהלים פח, ו) במתים חפשי כיון שמת אדם נעשה חפשי מן המצות","אמר רפרם בר פפא אמר רב חסדא בגד שאבד בו כלאים צובעו ומותר א\"ל רבא לרפרם בר פפא מנא ליה לסבא הא","א\"ל מתני' היא דתנן בודק עד שמגיע לסלע ואי ליכא אימר עורב נטלה הכי נמי עמרא וכיתנא בהדדי לא סליק להו צבעא וכיון דלא ידיע אימר מנתר נתר","אמר רב אחא בריה דרב ייבא משמיה דמר זוטרא האי מאן דרמי חוטא דכיתנא בגלימיה דעמרא ונתקיה ולא ידע אי נתיק אי לא נתיק שפיר דמי","מ\"ט מדאורייתא שעטנז כתיב עד שיהיה שוע טווי ונוז ורבנן הוא דגזרו ביה וכיון דלא ידע אי נתקיה שרי","מתקיף לה רב אשי אימר או שוע או טווי או נוז והלכתא כמר זוטרא מדאפקינהו רחמנא בחדא לישנא","ת\"ר בגד צבוע מטמא משום כתם רבי נתן בר יוסף אומר אינו מטמא משום כתם שלא תקנו בגדי צבעונין לאשה אלא להקל על כתמיהן","תקנו מאי תקנינהו אלא שלא הותרו בגדי צבעונין לאשה אלא להקל על כתמיהן הותרו מכלל דאסירי","אין דתנן בפולמוס של אספסינוס גזרו על עטרות חתנים ועל האירוס בקשו לגזור על בגדי צבעונין אמרי הא עדיפא כדי להקל על כתמיהן","\u0001מתני׳\u0002 שבעה סמנין מעבירין על הכתם רוק תפל ומי גריסין ומי רגלים ונתר ובורית"],[[0,"בודקו שכונות שכונות","כל שלש ושלש אצבעות לבד:"],[1,"במחט","מקום הזרע קשה והמחט מתעכב ליכנס בו:"],[1,"חדש","אין נבדק בחמה לפי שהוא עב ומהודק אבל שחוק נבדק בחמה שוטחו כנגד עיניו מקום הזרע הוי סתום ואין החמה נראית בבגדו כל כך:"],[2,"שאבד בו כלאים","שאם היה מכיר חוט הצמר בבגד הפשתן נותקו וכשר:"],[2,"לא ימכרנו לעובד כוכבים","דאתא העובד כוכבים ומזבן ליה לישראל:"],[5,"צובעו ומותר","שעל ידי הצבע הוא ניכר כדמפרש עמרא וכיתנא לא שליט בהו צבעא כי הדדי שהפשתן קשה לקבל הצבע יותר מן הצמר ואי לא מינכר בצבעא ודאי נפל:"],[5,"מנליה לסבא הא","דסמכינן אהכי:"],[8,"שוע","לשון חלק תרגום של חלק שעיע. כלומר שיהו חלוקין יחד במסרק:"],[8,"וטווי","יחד:"],[8,"ונוז","ארוג. ורבנן הוא דגזור בארוג בלא שוע וטווי:"],[10,"להקל על כתמיהן","שאין הכתם ניכר בו כמראה דם גמור:"],[12,"בפולמוס","חיל:"],[12,"אירוס","מפרש בגמרא בסוטה (דף מט:) טבלא דחד פומא והיינו זוג המקשקש:"],[13,"מתני' מעבירין על הכתם","שאין הדם בטל עד שיעבירו כולן עליו:"],[13,"רוק תפל","לקמן מפרש שלא טעם כלום כל אותו היום קודם לכן והיינו תפל בלא טעם:"],[13,"מי גריסין","מפרש לקמן:"]],[[0,"","בודקו שכונות שכונות. תימה דמשמע דאם לא נמצא טהור ותימה דאמר לעיל לר\"מ כל דבר שבחזקת טומאה לעולם הוא בטומאתו עד שיודע לך טומאה היכן היא ואפילו רבנן לא פליגי לגבי דם כדאמרן לעיל האי דם מהיכא אתי וי\"ל דהכא נמי דמי לגל דשמא מעצמו הלך או נתכבס על ידי שום דבר ולאו אדעתיה ואפשר דאפילו ר\"מ מודה הכא דשכיח טפי מלמימר עורב בא ונטלה:"],[2,"","בגד שאבד בו כלאים לא ימכרנו לעובד כוכבים. וא\"ת וליבטיל ברובא כדפרכינן בסוף תמורה (דף לד.) גבי שער נזיר שנארג בבגד ידלק וליבטיל ברובא ומשני בצפרתא שארג בו צורת צפור דחשיב ולא בטיל וי\"ל דלא שייך בטול ברוב אלא כשהאיסור מעורב בהיתר אבל כלאים ששניהם היתר ונאסרין על ידי תערובות כך אסור המרובה כמו המועט:"],[2,"","לא ימכרנו לעובד כוכבים. פרש\"י דנקט אבד שאם היה מכירו נותקו מן הבגד ומותר וכן י\"ל שהיה מותר למוכרו לעובד כוכבים אם היה ניכר אף בלא נתיקה וכן לעשות מרדעת לחמור וכל שכן תכריכים למת כיון שהכלאים ניכרין לא קני ליה ישראל מעובד כוכבים וכן המרדעת לא חיישינן דלמא מימליך לעשות בגד כדתנן במסכת כלאים (פ\"ט מ\"ד) מרדעת החמור ותכריכי המת אין בהם משום כלאים אי נמי לא חיישינן בעודה מרדעת שיעלנה על כתפו דתנן בהך סיפא לא יעלה את המרדעת על כתפו ואפי' להוציא בה את הזבל אבל בהצעה לא גזרינן הואיל ואין דרכה בהעלאה דמן התורה לא אסור אלא העלאה אבל להציעו תחתיו שרי ורבנן גזרו אפילו עשר מצעות זו ע\"ג זו בשאר כלאים אטו העלאה ובאין דרכו בהעלאה שרי להציעו תחתיו ואפילו מדרבנן ובלבד שלא יהא בשרו נוגע בהן אבל אבד בו כלאים אסור למרדעת אע\"ג דאין דרכו בהעלאה והיינו טעמא דתנן במסכת כלאים (שם מ\"ב) הכרים והכסתות אין בהם משום כלאים ובלבד שלא יהא בשרו נוגע בהן לפי שאין דרכן בהעלאה לא גזרו חכמים בהצעתן ובמרדעת נמי בעינן שלא יהא בשרו נוגע בהם דתו ליכא למיחש לכריכת נימא:"],[2,"","אבל עושה אותם תכריכין למת. וכל שכן אם לא אבד ואבד דנקט לרבותא דאע\"ג דאסירא כדפרישית דתכריכי המת שרו כדאמר במסכת כלאים (פ\"ט מ\"ד) תכריכי המת אין בהן משום כלאים דכיון דאסירי בהנאה לא משתמשי בהו ולא אתי לזבוני לעובד כוכבים וא\"ת והאיכא לועג לרש שמלבישו בדבר האסור ומראה לו שאין לו עוד חלק במצות כדאמר בהתכלת (מנחות דף מא.) גבי ציצית וההיא שעתא ודאי רמינן ליה משום לועג לרש ופרשב\"ם דאין בו איסור ואפילו לחי כי האי גוונא שאין המת נהנה בו וקשה דהא ציצית נמי אין החי חייב בו אם אין בו הנאת לבישה ומוכרי כסות דפטירי מכלאים פטורים נמי מציצית ומפרש רבינו תם דדוקא שייך לועג לרש בציצית משום דשקולה כנגד כל המצות כדנפקא לן במנחות (דף מג:) מוזכרתם את כל מצות ה' והא דאמר בפרק מי שמתו (ברכות דף יח.) אמר ליה (רבי לרבי חייא) דליה לכנפך דלא לימרו למחר באין אצלנו ועכשיו מלעיגים אותנו אע\"ג דיש למתים ציצית מכל מקום מה שאנו מראים עצמנו בפניהם מקיימי מצות והם אינם מצווין קרי לועג לרש ואם תאמר ועכשיו שאנו רגילין להסיר ציצית מטליתות המתים היאך הוא זה והא אמרינן במנחות (דף מא.) שלכתחילה צריך ליתן ציצית בבגדי המתים משום לועג לרש ובמתי מדבר מצינו בהמוכר הספינה (ב\"ב דף עד.) שהיה להם ציצית מיהו מהא לא קשה שבכל ט' באב היו נכנסים בקבריהם חיים ולמחר הכרוז יצא הבדלו חיים מתוך המתים כדאיתא באיכה רבתי אבל על מנהגנו יש לתמוה מכח ההיא דהתכלת (מנחות דף מא.) ואור\"י דבימי חכמים שכולן היו לובשים ציצית אם לא היה להם גם במותם לעג גדול היה שדומה כמו שהיו אומרים הואיל ומת אין צריך עוד ציצית אבל עכשיו שאין הכל לובשים ציצית בחייהם אם ישימו ציצית לכולן הוא יותר לועג לרש שבחייו לא קיים ובמותו יקיים ואם ישים למי שהיה לו בחייו ולא למי שלא היה לו יתביישו החיים כדתניא בפ' בתרא (לקמן נדה דף עא.) בראשונה היו מטבילין על גב נדות מתות והיו החיות מתביישות התקינו שיהיו מטבילין על הכל ועוד יש קצת סמך למנהגנו שמסירין הציצית ממסכת שמחות (פי\"ב) שאבא שאול צוה את בניו קברוהו תחת מרגלותיו של אביו והתירו תכלת מאנפליונו מיהו טעמא של אבא שאול לא נתברר:"],[2,"","אמר רב יוסף זאת אומרת מצות בטילות לעתיד לבא. תימה אמאי לא קאמר רב יוסף מילתיה אמתניתין דכלאים דתנן בהדיא תכריכין למת אין בהם משום כלאים ויש לומר דמהך מתניתין לא משמע אלא שכל זמן שהוא מת אין עליו משום איסור כלאים אבל הך דקתני דלכתחילה עושה לו תכריכין מכלאים אע\"פ שכשיעמוד לעתיד יעמוד במלבושיו שנקבר בהן שמע מינה שמצות בטילות לעתיד לבא:"],[8,"","שוע טווי ונוז. פירש\"י תרגום של חלק שעיע שחולקין אותו יחד במסרק וטווי יחד ונוז ארוג ורבנן גזור בארוג בלא שוע וטווי וקשה דא\"כ כלאים בציצית היכי משכחת לה דאיצטריך קרא למשרי והלא חוטי תכלת חלוקין במסרק וטווי לבדם וע\"ק דאי נוז ארוג הוא מאי פריך ואימא או שוע או טווי או נוז היאך יהיה שוע או טווי כלאים בלא נוז שהאריגה היא החיבור ועוד דלמה לי קרא דנוז לאריגה מיחדו נפקא דדרשינן מינה שתי תכיפות וכל שכן ארוג ומפרש רבינו תם דמדאורייתא שעטנז כתיב עד שיהיה שוע טווי ונוז שוע כל אחד לבדו וכן נמי טווי וכן נוז לבדו ואחר כך יחדיו לחברם ופירוש נוז היינו שזור כדאיתא במשניות (כלאים פ\"ט מ\"ח) נוז נלוז ומליז הוא לאביו שבשמים אצטוו\"ש הוא בלע\"ז לשון עקש ופתלתול (דברים לב) ומשום הכי איצטריך קרא למשרי כלאים בציצית שחוטי הציצית שזורין כדאיתא בספרי פתיל תכלת טווי ושזור אין לי אלא תכלת לבן מנין אמרה תורה תן תכלת ותן לבן מה תכלת שזור אף לבן שזור וארוג נפקא לן מיחדו כדפרישית וחוטי דכיתנא מיירי בשלא נשזר ופריך ואימא או שוע כל אחד לבדו ואחר כך חברם או טווי כל אחד לבדו וחברם או נוז כל אחד לבדו וחברם אחר כך ומשני דהלכה כמר זוטרא מדאפקינהו קרא בחד לישנא [וע\"ע תוס' יבמות ה: ד\"ה עד שיהא]:"]]],[["קמוניא ואשלג","הטבילו ועשה על גביו טהרות העביר עליו שבעה סמנין ולא עבר הרי זה צבע הטהרות טהורות ואינו צריך להטביל עבר או שדיהה הרי זה כתם והטהרות טמאות וצריך להטביל","איזהו רוק תפל כל שלא טעם כלום מי גריסין לעיסת גריסין של פול חלוקת נפש מי רגלים שהחמיצו","וצריך לכסכס שלש פעמים לכל אחד ואחד העבירן שלא כסדרן או שהעביר שבעה סמנין כאחת לא עשה ולא כלום","\u0001גמ׳\u0002 תנא נתר אלכסנדרית ולא נתר אנטפטרית","בורית אמר רב יהודה זה אהלא והתניא הבורית והאהל אלא מאי בורית כבריתא","ורמינהי הוסיפו עליהן הלביצין והלעונין הבורית והאהל ואי בורית כבריתא מי אית ליה שביעית והתנן זה הכלל כל שיש לו עיקר יש לו שביעית וכל שאין לו עיקר אין לו שביעית אלא מאי בורית אהלא והתניא הבורית והאהל תרי גווני אהלא","קמוניא אמר רב יהודה שלוף דוץ ואשלג אמר שמואל שאלתינהו לנחותי ימא ואמרו אשלגא שמיה ומשתכח ביני נקבי מרגניתא ומפקי לה ברמצא דפרזלא","הטבילו ועשה [כו'] תנו רבנן העביר עליו שבעה סמנין ולא עבר צפון ועבר טהרותיו טמאות","צפון צבע נמי מעבר אלא העביר עליו ששה סמנין ולא עבר העביר עליו צפון ועבר טהרותיו טמאות שאם העביר שביעי מתחילה שמא עבר","תניא אידך העביר עליו שבעה סמנין ולא עבר שנאן ועבר טהרותיו טהורות","א\"ר זירא לא שנו אלא הטהרות שנעשו בין תכבוסת ראשונה לשניה אבל טהרות שנעשו אחר תכבוסת שניה טהרותיו טמאות שהרי הקפיד עליו ועבר"],[[0,"קמוניא ואשלג","מפרש בגמ':"],[1,"הטבילו","קודם שהעבירן עליו:"],[1,"הרי זה צבע","דאי הוה דם הוה עבר:"],[1,"שדיהה","נשתנה מאדמימותו:"],[2,"לעיסת גריסין של פול חלוקת נפש","שנחלק האוכל מן הקליפה לועסה לגריסת הפול ומעבירו על הכתם:"],[3,"לכסכס","לשפשף:"],[3,"שלש פעמים","בין שתי ידיו כדרך כיבוס בגדים שכופל צדו עם צדו ומשפשף ומוליך ומביא:"],[3,"כסדרן","כדרך ששנויין כאן:"],[3,"לא עשה ולא כלום","לא לבדוק ולא לבטל:"],[5,"גמ' כבריתא","גפרית:"],[6,"הוסיפו עליהן","לענין שביעית הלביצין:"],[6,"עיקר","שורש שממנו חי. וגפרית קרקע בעלמא הוא:"],[7,"","רמצא דפרזלא:"],[9,"צפון","שבו\"ן בלע\"ז:"],[10,"שנאן ועבר טהרותיו טהורות","דאם איתא דדם הוא בהעברה קמייתא הוה עבר:"],[11,"תכבוסת","העברת סממנין:"],[11,"שהרי הקפיד עליו","כשחזר והעבירן גילה דעתו שמקפיד עליו בספק דם:"],[11,"ועבר","על ידי העברה זו ונעשה בו מעשה דם שכן דרך דם לעבור על ידי שבעה הסממנים:"]],[[1,"","הטבילו ועשה על גביו טהרות כו' הרי זה צבע. אין לפרש הרי זה ודאי צבע כדפירש בקונטרס בפרק ארבע מיתות (סנהדרין דף מט:) דאם כן לקמן אמאי קאמר אבל טהרות שאחר תכבוסת שניה טמאות הלא כיון שלא עבר מתחלה בז' סממנים ודאי צבע הוא ועוד כי פריך לקמן לר\"ל דאמר בלוע שיכול לצאת ע\"י הדחק לא שמיה בלוע ממתניתין דהרי זה צבע מאי פירכא היא הרי היא ודאי צבע ואין כאן טומאה בלועה כלל ואמאי נקט נמי והטבילו אפי' לא הטבילו נמי על כן צריך לפרש הרי זה ספק צבע כלומר יש לנו לתלות בצבע ואע\"פ דפעמים דדם נדה [אינו] עובר ע\"י ז' סמנין הכא איכא ספק ספקא מלבד טעמא דבטול דשמא צבע הוא כיון דלא עבר ואם תמצי לומר דדם הוא אימא מעלמא אתא הילכך מטהרינן אפילו למפרע אבל טעמא דבטול לחוד לא מהני דגבי דם נדה דקאמר מעביר עליו ז' סמנין ומבטלו אינו אלא לטהר מכאן ולהבא אבל למפרע טמא מדרבנן הואיל והקפיד שסבור שיכול לצאת ע\"י ז' סממנין ואכתי לא בטלו ואע\"ג דמן התורה טהור דהואיל ואין סופו לצאת ע\"י ז' סממנין נתבטל אבל כאן כיון דאיכא ספק ספקא ובטול טהור אף מדרבנן למפרע ומיהו מטעם ספק ספקא לחוד לא הוה מטהרינן ליה אי לאו טעמא דבטול משום דרגילות לבא דם מגופה כדאמרינן בפרק קמא (לעיל נדה דף ג.) בצפור לא נתעסקה בשוק של טבחים לא עברה האי דם מהיכא אתא דעל כרחך בלא טעמא דבטול לא מטהרינן ליה מטעם ספק ספקא מדנקט הטבילו אע\"ג דמקילינן בשאר ספק ספקא ומשום הכי פריך מינה לר\"ל דבטל אע\"ג דיכול לצאת ע\"י הדחק בצפון ואם תאמר אכתי למה לי הטבילו כיון דטהור מטעם בטול וספק ספקא וי\"ל דנהי דכשנתייבש הבגד נתבטל מיהו בעודו לח לא נתבטל ובעודו לח נגע בו הבגד ומשום הכי צריך להטביל ועוד יש לומר הרי זה צבע צביעות דם בעלמא ונתבטל ולא נצטרך לטעם דספק ספקא והשתא נתפרש טעם בטול במשנה דמינה פריך לריש לקיש ומיהו פירוש ראשון נראה עיקר דלשון צבע לא משמע צביעות דם אלא צבע ממש:"],[5,"","אמר רב יהודה זה אהל. בשבת פרק רבי עקיבא (שבת דף צ.) איכא ספרים דגרסי זה החול ופריך והתניא הבורית והחול ותימה דהתנן חול בפרק המוציא (שם פ:) וי\"ל דתרי גווני חול חד לבנין וחד לחפיפה וכבוס ואתי שפיר לההיא גירסא במסקנא דקאמר אלא מאי בורית אהל ולא קאמר אלא לעולם כו':"],[5,"","והתניא הבורית והאהל. פי' לענין שביעית נשנית אבל לפי גירסת הספרים דשבת דגרס הבורית והחול תימה היא לענין מה נשנית ואי לענין הוצאת שבת הא קאמר רבי יהודה שיעור בנתר ובורית כדי להעביר בו את הכתם והך שיעורא לא שייך רק מהני ז' מיני סמנים ומיהו אפשר דרבנן אית להו דבורית וחול הראויין לחפיפה וכבוס אית להו חד שיעורא לענין שבת ורבי יהודה פליג אבורית לחוד וקאמר כדי להעביר בו את הכתם:"],[5,"","כבריתא. פירש\"י גפרית וכן בערוך אש וגפרית תרגום אשתא וכבריתא (תהילים י״א:ו׳) והקשה הר\"ר יעקב מאורליינ\"ש בשבת כי פריך כבריתא מי אית ליה שביעית לפרוך ממתני' דשבת דתנן בפ' המוציא (דף עח:) שיעור אחרינא בגפרית וזפת כדי לסתום נקב ומיהו לא קשה דבכמה מקומות מצי למפרך ממשנה וכשהפירכא יותר פשוטה מן הברייתא פריך מינה ועוד כיון שסידר הש\"ס הכא הובאה שם והוקבעה:"],[6,"","כל שאין לו עיקר. פירש בקונטרס במסכת עבודה זרה (דף יד.) עיקר המתקיים בארץ בימות החמה ובימות הגשמים וזה קשה דא\"כ תבואה לא יהא נוהג בה שביעית שאינה מתקיימת בימות הגשמים ונראה כמו שפירש הכא שאין לו שורש בארץ כמו גפרית וגם מה שפירש שם תורניתא מין ארז כדאיתא בראש השנה (דף כג.) שיטה תורניתא זה אינו נראה דבמסכת ע\"ז (דף יד.) פריך כי הכא ומי אית ליה שביעית והתניא כו' והרי ודאי לארז יש לו שורש על כן נראה כמו שפי' רש\"י בשבת (דף צ.) שהוא כעין מחפורת צריף שקורין אלו\"ם ומין קרקע הוא וכמו גפרית הוא שאינו נשרש בארץ:"],[6,"","תרי גווני אהלא. תימה לספרים דגרסי בשבת (שם) והתניא הבורית והחול אמאי לא משני מעיקרא תרי גווני חול כדמשני במסקנא גבי אהל וי\"ל דקים ליה להש\"ס דלא הוו תרי גווני חול לכבוס:"],[9,"","צפון צבע נמי מעבר. וא\"ת ומה בכך והא הקפיד עליו כיון שהעביר צפון אחר שבעה סמנין ונימא דטהרותיו טמאות דקאמר קאי אתכבוסת שניה ומהאי טעמא נמי קאמרינן לקמן שנאן ועבר דטהרות שנעשו אחר תכבוסת שניה טמאות והכא נמי ליטמא וליכא למימר דקפידא לא מהני אלא כשעובר בז' סממנין שמעבירין בקל אבל צפון שמעביר על ידי הדחק אפילו הקפיד טהורות דלקמן מסיק רב פפא יכול לצאת והקפיד עליו דברי הכל טמא אע\"פ שאין יכול לצאת אלא ע\"י הדחק והיינו שיכול לצאת על ידי צפון דהא ממתני' פריך רבי יוחנן לריש לקיש אמאי טהורה כי לא עבר ע\"י ז' סמנין הא יכול לצאת ע\"י צפון וי\"ל דברייתא לא מיירי בטהרות דאחר תכבוסת שניה דיותר היה ראוי לאשמועינן טהרותיו טהורות אטהרות דאחר תכבוסת ראשונה כדקאמר בברייתא דלקמן אלא אתכבוסת ראשונה נמי קאי והוה מצי למפרך מברייתא דבסמוך דקתני שנאן ועבר טהרותיו טהורות אלא דניחא ליה למיפרך מגופה:"],[9,"","העביר עליו ששה סמנין ולא עבר העביר עליו צפון ועבר כו'. תימה פשיטא והלא אינו מזכיר במשנתינו צפון במנין ז' סממנין ומאי קא משמע לן והא פשיטא דבששה לא סגי ויש לומר דאשמועינן דאע\"ג דלא עבר כלל ולא נשתנה ע\"י ו' סמנין איכא למימר משום השביעי לא יעבור קא משמע לן דיש להחמיר דשמא בשביעי אם העביר קודם הצפון היה עובר:"],[10,"","שנאן ועבר. נראה לר\"י דע\"י שנאן צבע נמי עובר דאי לאו הכי אמאי טהורות אפילו למפרע הא ליכא הכא ספק ספקא ויהיו טמאות למפרע כיון דליכא אלא חדא ספקא כדפרישית במתניתין:"],[11,"","שהרי הקפיד עליו. וא\"ת אמתני' דקתני הרי זה צבע מ\"מ כשיכבסנו הרי מקפיד עליו וליטמא טהרות דאחר תכבוסת וי\"ל דכבוס אינו קפידא דאינו אלא ללבנו וא\"ת מ\"מ כשיכבסנו יטמא הבגד שיצא הדם ואינו בלוע וי\"ל דביציאתו יבטל נמי בתכבוסת:"],[11,"","שהרי הקפיד עליו ועבר. וא\"ת מה צריך לומר ועבר וכי תימא משום דנפלט וטמא הבגד א\"כ אמאי נקט והקפיד וי\"ל דנקט ועבר דאז קפידתו קפידא הואיל והועילה מחשבתו שעבר ומשום הכי נמי קתני במתניתין דכי לא עבר טהור ואף על גב דהקפיד:"]]],[["אמר ליה רבי אבא לרב אשי מידי בקפידא תליא מילתא","א\"ל אין דתניא רבי חייא אומר דם הנדה ודאי מעביר עליו ז' סמנין ומבטלו","ואמאי הא דם נדה הוא אלמא בקפידא תליא מילתא ה\"נ בקפידא תליא מילתא","תנן התם חרסין שנשתמש בהן זב שבלעו משקין ונפלו לאויר התנור והוסק התנור התנור טמא שסוף משקה לצאת","אמר ר\"ל לא שנו אלא משקין קלים אבל משקין חמורין טמא אע\"פ שלא הוסק התנור רבי יוחנן אמר אחד משקין קלין ואחד משקין חמורין אם הוסק התנור אין אי לא לא","איתיביה רבי יוחנן לריש לקיש הטבילו ועשה על גביו טהרות והעביר עליו ז' סמנין ולא עבר הרי זה צבע וטהרותיו טהורות ואין צריך להטביל","אמר ליה הנח לכתמים דרבנן","והתני רבי חייא דם הנדה ודאי מעביר עליו ז' סמנין ומבטלו","אמר ליה רבי לא שנה רבי חייא מנא ליה","איתיביה רבי יוחנן לריש לקיש רביעית דם שנבלע בבית הבית טמא ואמרי לה הבית טהור ולא פליגי הא בכלים דמעיקרא הא בכלים דבסוף","נבלעה בכסות אם מתכבסת ויוצא ממנה רביעית דם טמאה ואם לאו טהורה","אמר רב כהנא מקולי רביעיות שנו כאן שאני דם תבוסה דרבנן","איתיביה ר\"ל לרבי יוחנן כל הבלוע שאינו יכול לצאת טהור הא יכול לצאת טמא ואף ע\"ג דלא נפיק","א\"ר פפא כל היכא דאין יכול לצאת ולא הקפיד עליו דברי הכל טהור יכול לצאת והקפיד עליו דברי הכל טמא","כי פליגי דיכול לצאת ולא הקפיד עליו מר סבר כיון דיכול לצאת אף על גב דלא הקפיד עליו ומר סבר אע\"ג דיכול לצאת"],[[0,"מידי בקפידא תליא מילתא","בתמיה. כיון דטהרות שבינתיים טהורות אלמא לאו דם הוא אחרונות משום קפידא אמאי טמאות:"],[1,"דם הנדה ודאי","כגון נדה שקנחה בסדין דם אף על גב דודאי דם הוא:"],[1,"מעביר עליו ז' סממנין ומבטלו","ואפילו לא עבר הרי הוא בטל וטהור הוא הואיל ואין אדם מקפיד עליו אחר העברת הסמנין מדאזל לה חזותא:"],[3,"חרסין","כגון עביט של מי רגלים של זב ושל זבה:"],[3,"שסוף משקה לצאת","כלומר דרך משקה לצאת ע\"י ליבון החרס וכיון שהיו חרסין אלו בתנור בשעת היסקו יצאו המשקין ונטמא תנור מאוירו:"],[4,"לא שנו","הא דקתני הוסק אין לא הוסק לא דכל זמן שהן נבלעין בחרסין אין מטמאין את אויר התנור אלא משקין קלין שאינן אב הטומאה כגון דמעת עינו ודם מגפתו או מי רגלים דטמא מת או טמא שרץ דאפילו כשהוסק ויצאו והיו הן ממש באויר התנור לא טמאוהו אלא מדרבנן דאין משקה מטמא כלי חוץ ממשקה אב הטומאה:"],[4,"אבל משקין חמורין","כגון מי רגלים של זב ושל זבה שריבה בהן הכתוב מעיינות לטמא אדם וכלים:"],[4,"טמא","התנור אפילו לא הוסק כיון דיכולין לצאת ע\"י היסק לאו טומאה בלועה היא ומטמאה:"],[4,"אי לא לא","דהוה ליה טומאה בלועה בחרסין וטומאה בלועה לא מטמיא כדאמר בבהמה המקשה (חולין עא.):"],[5,"טהרותיו טהורות","אי אמרת בשלמא בלוע שאינו יכול לצאת אלא ע\"י הדחק טהור משום הכי תלינן לקולא ואמרינן צבע הוא וטהור משום דאי נמי דם הוא כיון דנבלע כל כך דאין הסממנין יכולין להעבירו ואף על פי שיכול לצאת על ידי צפון טהור אלא לדידך דאמרת הואיל ויכולין לצאת על ידי היסק כי לא יצאו נמי טמאין הכא היכי תלינן לקולא לאכול תרומה תלויה דדלמא דם הוא:"],[6,"אמר ליה הנח לכתמים","דעיקר תחילת גזרתן אינה אלא מדרבנן הילכך מקילינן דמדאורייתא עד שתראה בבשרה:"],[7,"מעביר עליו כו'","והא הכא דודאי דם הוא מטהרינן ליה משום דנבלע כל כך ואע\"פ שיכול לצאת ע\"י צפון:"],[8,"אמר לו זו אינה משנה","ומשובשת היא הואיל ורבי לא שנאה במשנתינו שסידר את המשנה:"],[8,"ר' חייא","תלמידו מנין לו:"],[9,"רביעית דם","של מת מטמא באהל:"],[9,"הבית טמא","כלי הבית טמאין באהל:"],[9,"בכלים דמעיקרא","שהיו שם קודם שנבלעה טמאים שנטמאו באהל:"],[9,"והא בכלים דלבסוף","שבאו לבית לאחר שנבלע הדם בקרקע טהורים דתו לא מטמיא:"],[10,"ואם לאו טהורה","ואע\"ג דרביעית שלמה נבלעת בו. אלמא בלוע שאינו יכול לצאת להדיא אלא ע\"י הדחק כי הכא דע\"י צפון נפקא כולה וקתני טהורה:"],[11,"דם תבוסה","האי רביעית דמקילין בה לא בבאה ממש מן המת אלא ברביעית דם תבוסה שהוא ספק ואפי' לא נבלעה אין לה טומאה ודאית כדתניא בפ' בתרא (לקמן נדה דף עא.) איזהו דם תבוסה הרוג שיצא ממנו רביעית דם בחייו ובמותו ספק יצא רובו מחיים ספק יצא רובו לאחר מיתה וטמא:"],[14,"כיון דיכול לצאת כו'","והנך חרסין אע\"ג דלא קפיד בהו להוציא כל מה שבתוכן טמאין כל זמן שלא יצא הואיל ויכול לצאת על ידי היסק:"]],[[0,"","אמר רבי אבא מידי בקפידא תליא מילתא. דכיון דלא עבר בראשונה נתבטל בבגד וכי עבר נמי בשניה לא טמא הבגד ביציאתו לחוץ לפי שנתבטל במי תכבוסת וא\"ת ולר' אבא תקשה אמאי נקט במתניתין הרי זה צבע אפילו דם (נדה) ודאי טהור אף למפרע דכיון דלא עבר איגלאי מילתא למפרע שנתבטל בבגד אלא ודאי בקפידא תליא מילתא וי\"ל דלא איגלאי מילתא למפרע שלא היה ראוי לעבור מתחלה ע\"י שלא עבר עתה שהרי כל שעה הוא מתייבש יותר ויותר ומעיקרא שמא היה ראוי לעבור אי נמי היה סבור כריש לקיש דמטמא טומאה בלועה לכך. אצטריך לומר ה\"ז צבע:"],[2,"","אלמא בקפידא תליא מילתא. וא\"ת אם כן מה צורך בהעברת סמנים כיון דמבטל בלבו סגי וי\"ל דבטלה דעתו אצל כל אדם אם יבטלנו בלא שבעה סממנים:"],[6,"","הנח לכתמים דרבנן. מיהו כיון דרגילות לבא כתם מגופה לא מקילינן אי לאו משום דאיכא למתלי בצבע כדפירש במתניתין ולא דמי לדם תבוסה דלקמן דמקילינן משום דהוי מדרבנן אי נמי כדי לטהר אפילו למפרע נקט הרי זה צבע או שמא מתחלה שלא נתייבש כל כך היה יכול לצאת:"],[8,"","רבי חייא מנא ליה. וא\"ת אם כן לעולם לא ניתיב תיובתא מברייתא דמתני בי ר' חייא ובי רבי אושעיא וי\"ל דבכולהו איכא למימר כדאמר אילפא בתענית (דף כא.) ובכתובות (דף סט:) כל דאמר מילתא דבי ר' חייא ור' אושעיא ולא פשיטנא ליה ממתני' כו' והך הוה פשיטא ליה לר\"ל דלא רמיזא במתניתין ועוד דסברא הוא מדנקט מתניתין כתם ולא דם נדה שמע מינה דדם נדה ודאי לא מצי לבטל ולית ליה חילוק בין להבא בין למפרע:"],[10,"","אם מתכבסת ויוצא ממנה רביעית דם. פרש\"י בהגוזל (ב\"ק קא:) שיתנו מים במדה ואם כשיסחטנו לחוץ ימצאו רביעית יותר א\"כ ודאי היה בו רביעית דם וקשה דאפילו לא ימצאו רביעית יותר מ\"מ יכול להיות שהיה בו רביעית שהרי הכסות בלועה גם מן המים וגם מן הדם שאין הכל יכול לצאת ונראה כדתניא בתוספתא דאהלות (פ\"ד) רביעית דם שבלוע בכסות כיצד משערין אותו מביא מים במדה ומכבס ומביא מים אחרים ונותן בתוכו רביעית דם ואם היה שוה מראיהן טמאה שאם כן גם מן הבגד יצא רביעית דם שהרי גם מן המים ומן הדם נשארו בבגד ולא יהיה מראהו שוה אם לא היה בו רביעית דם מתחלה ואם תאמר ומה צריך מדה למים הראשונים לא היה צריך אלא שיתן מים במדה שיצא מן הבגד פחות רביעית ויתן רביעית דם לתוכו ואם ישוה מראיהן טמא וכ\"ת שלא הזכיר מדה ראשונה אלא לתת מן השניה כמדתה הלא על כרחך אינו צריך מן השניים כשיעור שבלעה כסות מן הראשונים ויש לומר דמשום הכי נקט מדה בראשונה שאם ימצא רביעית יותר א\"צ לחזור ולטרוח ולהביא מים שניים כדפרש\"י:"],[10,"","ואם לאו טהורה. אע\"ג דכל הרביעית נבלע בבגד וא\"ת משעה שנפל עליה יחד נטמא הכסות וי\"ל דמיירי דקודם שנפל רביעית נבלע בכסות מה שאינו יכול לצאת ע\"י סתם כבוס ונתבטל בבגד ולא היה רביעית שלם מעולם:"],[11,"","מקולי רביעיות שנו כאן. תימה דבהגוזל קמא (ב\"ק דף קא.) פריך תנא בגד שצבעו בקליפי ערלה ידלק אלמא חזותא מילתא היא ורמינהי רביעית דם שנבלע בבגד כו' ומשני מקולי רביעיות שנו כאן והא הך שינויא לא הוי אלא לר\"ל א\"כ תקשה לר' יוחנן וי\"ל דלר' יוחנן לא קשה מידי טומאה לערלה דגבי טומאה משום קפידא וכיון דאינו יכול לצאת אלא ע\"י הדחק בטל דטומאה בלועה לא מטמיא אבל גבי ערלה ניחא ליה בחזותא ולא מבטל ליה והתם משני שינוייא דמהני לר\"ל וה\"ק אפילו לפי דבריך שאתה מדמה טומאה לאיסור לא קשה דדם תבוסה דרבנן:"],[12,"","הא יכול לצאת טמא. ואם תאמר ומאי קושיא דלמא הכי פירושו כל הבלוע שאינו יכול לצאת על ידי סתם תכבוסת טהור אע\"ג דיכול לצאת על ידי הדחק בצפון הא יכול לצאת ע\"י סתם תכבוסת טמא דהא הך דכל הבלוע סיפא דהך דלעיל שנבלע בכסות והאי בסתם תכבוסת אוקמינן ופרישנא ואם לאו טהורה אע\"ג דיכול לצאת ע\"י הדחק בצפון ואדרבה קשיא לריש לקיש ויש לומר דהך דכל הבלוע משמע שאינו יכול לצאת כלל דסתמא קתני ואפילו הכי קיימא שפיר ארישא דה\"פ לריש לקיש שכל הבלוע שאינו יכול לצאת אפילו על ידי הדחק בצפון טהורה ואם לאו דיכול לצאת ע\"י הדחק טמאה אפילו בטומאה דאורייתא ואם כן בדם תבוסה דרבנן אפילו יוצא על ידי הדחק טהור והשתא מפרש בסיפא ויהיב טעמא לרישא בטומאה דאורייתא דכי אינו יכול לצאת טהורה אבל יכול לצאת על ידי הדחק טמאה ולר' יוחנן דמפרש כדמשני רב פפא פירוש דרישא אם מתכבסת ויוצא ממנו בתכבוסת סתם טמא שכן דרך להקפיד עליו הואיל ויוצא בקל ואם לאו טהורה ואפילו יוצא ע\"י צפון דאין דרך להקפיד עליו כיון שאינו יוצא בתכבוסת סתם ומייתי כל הבלוע ליתן טעם לרישא דכיון דאינו יכול לצאת כלל אפילו הקפיד בפירוש אין קפידתו קפידא דבטלה דעתו אצל כל אדם שאין דרכן להקפיד ברישא נמי יכול לצאת על ידי הדחק ועל ידי כבוס סתם אינו יכול לצאת טהור הואיל ואין דרך להקפיד בסתם והיינו כדמשני רב פפא כל היכא דאינו יכול לצאת כו' והשתא רב פפא אינו סותר מה שאמר למעלה אלא בא לתרץ דה\"פ הא יכול לצאת על ידי הדחק והקפיד עליו להוציאו טמא וכי קאמר לעיל טהור בשלא הקפיד עליו להוציאו ולא היה צריך רב פפא לומר אלא התם בדקפיד אלא בא להשמיענו פלוגתא דרבי יוחנן ור\"ל דפליגי בדלא קפיד ויכול לצאת על ידי הדחק דר\"ל מטמא ור\"י מטהר:"]]],[["אם הקפיד עליו אין אי לא לא","איזהו רוק תפל תנא כל שלא טעם כלום מבערב סבר רב פפא קמיה דרבא למימר כמאן דאמר לא טעם מידי באורתא אמר ליה רבא מי קתני בערב מבערב קתני לאפוקי היכא דקדים ואכיל","אמר רבה בר בר חנה אמר רבי יוחנן איזהו רוק תפל כל שעבר עליו חצות לילה ובשינה למימרא דבשינה תליא מילתא והתנן ישן כל היום אין זה רוק תפל ניעור כל הלילה הרי זה רוק תפל התם במתנמנם","היכי דמי מתנמנם אמר רב אשי נים ולא נים תיר ולא תיר דקרו ליה ועני ולא ידע לאהדורי סברא וכי מדכרו ליה מדכר","תנא השכים ושנה פרקו אין זה רוק תפל ועד כמה אמר רב יהודה בר שילא אמר רב אשי אמר רבי אלעזר כל שיצא רוב דבורו של שלש שעות","מי גריסין לעיסת גריסין של פול וכו' לימא מסייע ליה לריש לקיש דאמר ר\"ל רוק תפל צריך שיהא עם כל אחד ואחד דלמא הבלא דפומא מעלי","מתניתין דלא כרבי יהודה דתניא ר' יהודה אומר מי גריסין רותח ועובר שיתן לתוכו מלח","מאי משמע דהאי עובר לישנא דאקדומי הוא אמר ר\"נ בר יצחק דאמר קרא (שמואל ב יח, כג) וירץ אחימעץ דרך הככר ויעבור את הכושי אביי אמר מהכא (בראשית לג, ג) והוא עבר לפניהם ואיבעית אימא מהכא (מיכה ג ) ויעבור מלכם לפניהם וה' בראשם","מי רגלים שהחמיצו תנא כמה חימוצן שלשה ימים","א\"ר יוחנן כל שיעורי חכמים בכתמים צריך שיעור לשיעורן דילד או דזקן דאיש או דאשה מכוסים או מגולים בימות החמה או בימות הגשמים","וצריך לכסכס שלש פעמים בעי רבי ירמיה אמטויי ואתויי חד או דלמא אמטויי ואתויי תרתי מאי תיקו","העבירן שלא כסדרן ת\"ר הקדים שניים לראשונים תני חדא שניים עלו לו ראשונים לא עלו לו ותניא אידך ראשונים עלו לו שניים לא עלו לו","אמר אביי אידי ואידי שניים עלו לו ולא ראשונים ומאי ראשונים ראשונים לכסדרן ושניים להעברתן","\u0001מתני׳\u0002 כל אשה שיש לה וסת דיה שעתה ואלו הן הוסתות מפהקת ומעטשת וחוששת בפי כריסה ובשפולי מעיה ושופעת וכמין צמרמורות אוחזין אותה וכן כיוצא בהן וכל שקבעה לה שלשה פעמים הרי זה וסת","\u0001גמ׳\u0002 תנינא חדא זימנא כל אשה שיש לה וסת דיה שעתה התם בוסתות דיומי הכא בוסתות דגופא","כדקתני אלו הן וסתות היתה מפהקת מעטשת וחוששת בפי כריסה ובשפולי מעיה ושופעת","שופעת הא שפעה ואזלא אמר עולא בריה דרב עלאי"],[[0,"אם הקפיד עליו אין","והא דקתני אם יכול לצאת טמא כשהקפיד:"],[1,"באורתא","שאפילו אמש לא טעם כלום:"],[1,"מבערב קתני","אבל אמש אכל כשאר ב\"א:"],[1,"לאפוקי דקדים","קודם היום לאחר שניעור משנתו ואכיל דלא הוי רוק תפל לפי שהשינה ממררת את הרוק ומחזקתו והאוכל ממתקו ומעביר את כחו:"],[2,"התם","דקתני ניעור כל הלילה הרי זה רוק תפל לא דניעור ממש אלא מתנמנם דודאי שינה של לילה בעינן ושינת היום אע\"ג דישן לאו תפל הוא הואיל וטעם כלום שהטועם שחרית נהנה כל היום כולו:"],[4,"השכים ושנה פרקו","הדבור מעביר כח הרוק:"],[4,"של שלש שעות","שהוא עשוי לדבר בשלש שעות:"],[5,"לימא","מתני' דבעי לעיסה כדי שיהא רוק מעורב בגריסין מסייע ליה לריש לקיש:"],[7,"עובר","קודם. שהמלח מעביר כח הגריסין:"],[7,"ויעבור את הכושי","קדם לפניו:"],[8,"שהחמיצו","שהסריחו:"],[9,"הני מי רגלים דילד או דזקן","של זקן מעלו טפי:"],[9,"מכוסין","מעלו טפי:"],[9,"בימות החמה","מעלו טפי:"],[10,"בעי רבי ירמיה האי שלש פעמים דקתני אמטויי ואתויי חד","הולכה והובאה חשיב חד או דלמא אמטויי חשיב חד ואתויי חד דהוו להו תרי:"],[11,"שניים לראשונים","נתר ובורית וקמוניא ואשלג לרוק תפל ומי גריסין ומי רגלים:"],[11,"תני חדא שניים עלו לו","אותם שהעביר בשנייה עלו לו:"],[11,"ראשונים לא עלו לו","וכי הדר מעביר נתר ובורית וקמוניא ואשלג זימנא אחריתי בתר רוק וגריסין ומי רגלים נמצא עוברין עליו כסדרן:"],[11,"ותניא אידך כו'","וקשיין אהדדי:"],[12,"אמר אביי הא והא סבירא להו שניים","שהעביר שניים שהיה לו להעביר ראשון עלו לו וראשונים שהעביר ראשון לא עלו לו דהכי שפיר דכי הדר מצרכינן לעבורינהו בתר שניים הוי ליה כסדרן:"],[12,"ומאי ראשונים","דקתני באידך ברייתא עלו לו:"],[12,"ראשונים לכסדרן","שהיה לו להעביר תחלה שהוא העביר לבסוף דהוו להו הנך ראשונים לכסדרן שניים להעברתן:"],[13,"מתני' מפהקת","אישטריליי\"ר בלע\"ז:"],[13,"פי כרסה","נגד טבורה:"],[13,"שפולי מעיה","בית הרחם:"],[13,"ושופעת","בגמרא פריך מאי קאמר:"],[13,"צמרמורות","פריצונ\"ש:"],[13,"אוחזין אותה","בכך למודה להיות בכל עת שהיא רואה:"],[13,"דיה שעתה","בכל ראיות שתראה ע\"י וסתות אלו:"],[13,"כיוצא בהן","מפרש בגמרא:"],[14,"גמ בוסתות דיומי","כגון מט\"ו לט\"ו:"],[16,"הא קא שפעה ואזלא","והיכן הוא הוסת הואיל וכל ימיה רואה:"]],[[3,"","נים ולא נים תיר ולא תיר. פי' נים ולא נים בתחלת שינה תיר ולא תיר בסוף שינה כשהוא ניעור משנתו ובערבי פסחים (פסחים קכ:) נמי גבי נתנמנמו יאכלו ונקיט כי האי לישנא נים ולא נים תיר ולא תיר איכא לפרושי בכי האי גוונא נים ולא נים שעתה בחצות הלילה מתחיל להתנמנם תיר ולא תיר שישן בחצי הראשון ועתה כשמגיע בחצות הלילה היה מתחיל ליעור והוא תיר ולא תיר:"],[8,"","תנא כמה חימוצן שלשה ימים. קשה דבפרק רבי עקיבא (שבת דף צ.) קאמר גבי מי רגלים שהחמיצו בני מ' יום משמע ולא קודם לכן ואיכא ספרים דגרסי עד ארבעים יום ולפי זה ניחא דאיכא למימר משלשה ועד ארבעים מעלו ואיכא ספרים דגרסי בן ארבעים וקאי אתינוק שהוא בן מ' יום וקשה דהא לקמן איבעיא להו דילד או דזקן וי\"ל דה\"פ דילד דווקא או אפילו דזקן נמי ולא כפ\"ה דפירש דזקן מעלו טפי וכן משמע מדקאמר דאיש או דאשה וליכא למימר או דאשה דוקא דהא דילד או דזקן נקט לשון זכר וכן בשבת בן מ' לשון איש מיהו תימה אמאי לא מייתי הכא הך ברייתא דשבת דבן מ' יום ועוד מילי טובא שמאריך באותה ברייתא יותר מהכא והכא מאריך בדין מי רגלים יותר מהתם ונראה לומר דברייתא דהתם קאי אמילתא דת\"ק דאמר כדי לכבס בו בגד קטן והתם לא מעלו אלא בני מ' יום והכא לגבי כתם איירי ומעלו בני שלשה ימים ולא שייכי כולהו מילי דהתם הכא ומשום הכי לא מייתי ההיא ברייתא הכא:"],[13,"","מפהקת. פי' בקונטרס אשטריליי\"ר בלע\"ז ואין נראה אלא כמו שפירש בשבת (דף קלו.) גבי פיהק ומת באליי\"ר כדאמר בברכות (דף כד:) גבי רבי שהיה מפהק ומניח ידו תחת סנטרו:"],[13,"","מעטשת. אישטרנויי\"ר וגוסה פירש רש\"י בגמרא באליי\"ר ואין נראה אלא פירוש רוטי\"ר וכן גיהק בתפלה רוטי\"ר ובערוך פירש קול היוצא מן הגרון מתוך מאכל כבד וזה רוטי\"ר ואין נראה לפרש שנגלוטי\"ר. וכולהו הני וסתות איירי שמפהקת או מעטשת שעה או שתים בעת שרגילה לראות אבל משום פיהוק או עיטוש חדא זימנא לא קבעה מדמפליג בין תחלת וסת לסוף וסת ובחד פיהוק וחד עיטוש לא שייך תחלה וסוף:"]]],[["בשופעת דם טמא מתוך דם טהור","וכמין צמרמורות וכו' וכן כיוצא בהן לאתויי מאי אמר רבה בר עולא לאתויי אשה שראשה כבד עליה ואבריה כבדים עליה ורותתת וגוסה","אמר רב הונא בר חייא אמר שמואל הרי אמרו לימים שנים לוסתות אחת למה שלא מנו חכמים שלשה","למה שלא מנו חכמים לאתויי מאי אמר רב יוסף לאתויי ראשה כבד עליה ואבריה כבדין עליה ורותתת וגוסה א\"ל אביי מאי קא משמע לן מתני' היא דהא פרשה רבה בר עולא אלא אמר אביי לאתויי אכלה שום וראתה ואכלה בצלים וראתה כססה פלפלים וראתה","אמר רב יוסף לא שמיע לי הא שמעתא","אמר ליה אביי את אמריתה ניהלן ואהא אמריתה ניהלן היתה למודה להיות רואה יום חמשה עשר ושינתה ליום עשרים זה וזה אסורין שלש פעמים ליום עשרים הותר יום חמשה עשר וקבעה לה יום עשרים שאין אשה קובעת לה וסת עד שתקבענה שלש פעמים","ואמרת לן עלה אמר רב יהודה אמר שמואל זו דברי ר\"ג בר רבי שאמר משום רשב\"ג אבל חכמים אומרים ראתה אינה צריכה לא לשנות ולא לשלש","ואמרינן לך לשנות אמרת לן לשלש מיבעיא ואמרת לן לשנות בוסתות לשלש בימים","ונימא זו דברי רשב\"ג הא קמ\"ל שמואל דר\"ג ברבי כרשב\"ג סבירא ליה","\u0001מתני׳\u0002 היתה למודה להיות רואה בתחלת הוסתות כל הטהרות שעשתה בתוך הוסתות טמאות בסוף הוסתות כל הטהרות שעשתה בתוך הוסתות טהורות","רבי יוסי אומר אף ימים ושעות וסתות היתה למודה להיות רואה עם הנץ החמה אינה אסורה אלא עם הנץ החמה רבי יהודה אומר כל היום שלה","\u0001גמ׳\u0002 תנא כיצד א\"ר יוסי ימים ושעות וסתות היתה למודה להיות רואה מיום עשרים ליום עשרים ומשש שעות לשש שעות הגיע יום עשרים ולא ראתה אסורה לשמש כל שש שעות ראשונות דברי רבי יהודה ורבי יוסי מתיר עד שש שעות וחוששת בשש שעות","עברו שש שעות ולא ראתה אסורה לשמש כל היום כולו דברי ר' יהודה ורבי יוסי מתיר מן המנחה ולמעלה","היתה למודה והתניא רבי יהודה אומר כל הלילה שלה","לא קשיא הא דרגילה לראות בתחלת יממא והא דרגילה לראות בסוף ליליא","תני חדא רבי יהודה אוסרה לפני וסתה ומתירה לאחר וסתה ותניא אידך אוסרה לאחר וסתה ומתירה לפני וסתה","ולא קשיא הא דרגילה למחזי בסוף ליליא הא דרגילה למחזי בתחלת יממא","אמר רבא הלכה כרבי יהודה ומי אמר רבא הכי והתניא (ויקרא טו, לא) והזרתם את בני ישראל מטומאתם מכאן א\"ר ירמיה אזהרה לבני ישראל שיפרשו מנשותיהן סמוך לוסתן","וכמה אמר רבא עונה מאי לאו עונה אחריתי לא אותה עונה","ותרתי למה לי צריכא דאי אשמועינן הא הוה אמינא ה\"מ לטהרות אבל לבעלה לא קמ\"ל","ואי מההיא הוה אמינא סמוך לוסתה עונה אחריתי קמ\"ל אותה עונה","\u0001מתני׳\u0002 היתה למודה להיות רואה יום ט\"ו ושינתה להיות רואה ליום כ' זה וזה אסורין שינתה פעמים ליום כ' זה וזה אסורין","שינתה ג' פעמים ליום כ' הותר ט\"ו וקבעה לה יום כ' שאין אשה קובעת לה וסת עד שתקבענה ג' פעמים ואינה מטהרת מן הוסת עד שתעקר ממנה ג' פעמים"],[[0,"בשופעת דם טמא מתוך דם טהור","רגילה לראות דם טהור תחלה ואח\"כ דם טמא הוי וסת וכל שעה שתראה דם טמא אחר דם טהור אמרינן דדיה שעתה:"],[1,"גוסה","בלאיי\"ר:"],[2,"הרי אמרו","לקמן בשמעתין אינה צריכה לא לשנות ולא לשלש ומפרש לה לשנות בוסתות כו':"],[2,"לימים שנים","וסתות דיומי משקבעתן שתי פעמים הוי וסת:"],[2,"לוסתות","דגופה כגון הני דמתניתין משקבעתן פעם אחת הוי וסת:"],[2,"למה שלא מנו חכמים","וסת שלש. וקמיבעיא ליה לשמואל למה שלא מנו חכמים מאי היא והכי קאמר שמואל אני שמעתי כן למה שלא מנו חכמים שלש אבל איני יודע מהו:"],[3,"מתניתין היא","דקתני וכן כיוצא בהן ופירשה רבה בר עולא לאתויי הני:"],[4,"הא שמעתתא","דשמואל דאמר לימים שנים לוסתות אחד:"],[5,"זה וזה","כשיגיע עוד חמשה עשר אסורה לשמש שמא תחזור לוסתה וכשיגיע יום עשרים נמי תאסר שמא מעכשיו תקבע וסת ליום עשרים:"],[6,"שאמר משום רבן שמעון בן גמליאל","דלא הוי חזקה בציר מתלת זימני כדשמעינן ליה לרבן שמעון בן גמליאל בכל דוכתי לשלישי תנשא לרביעי לא תנשא (יבמות דף סד:):"],[8,"ונימא זו דברי רשב\"ג","דהא קיימא לן בכל דוכתי דבעי שלשה זימני לחזקה:"],[9,"מתני' בתוך וסתות","בוסתות דגופה קאמר:"],[10,"אף ימים ושעות","בגמ' מפרש:"],[10,"אינה אסורה אלא עם הנץ החמה","וכל הלילה משמשת ואם עבר הנץ החמה ולא ראתה משמשת כל היום ורבי יוסי קתני לה דדייק שעת הוסתות ותו לא:"],[10,"רבי יהודה אומר כל היום שלה","מותרת לשמש משעבר הנץ החמה ולא ראתה אבל כל הלילה שלפני הנץ החמה של וסתה אסורה לשמש. ומפרש בגמרא דהאי למודה עם הנץ החמה דקתני דרגילה למחזי בסוף ליליא מקמי דלימטי תחלת יממא ואנן אסרינן לה כל עונת וסתה נמצאת אסורה כל הלילה שהיא עונת וסתה ורבי יהודה מחמיר:"],[11,"גמ' אסורה לשמש כל היום כולו דברי רבי יהודה","ורבי יהודה לטעמיה דאמר כל עונת וסתה אסורה ועונה הוי או יום או לילה ומי שוסתה בלילה ואפילו בסופה אסורה כל הלילה ואם וסתה ביום ואפי' בסופו כל היום אסורה:"],[11,"עד שש שעות","דשעות דייקינן הואיל ווסתה בשעה ששית אינה אסורה לא לפניה ולא לאחריה:"],[11,"וחוששת לשש שעות","שעה ששית היא אסורה שהוא וסתה:"],[12,"מן המנחה","היינו משש שעות ולמעלה מכי ינטו צללי ערב ובשבע כבר נטו הצללים שהחמה במערב:"],[16,"","עם הנץ דמתניתין בסוף לילה לפיכך כל היום שלה והלילה אסורה. עם הנץ דברייתא בתחלת יממא ולפיכך לילה מותרת ויום אסורה:"],[17,"והזרתם את בני ישראל","וסמיך ליה והדוה בנדתה:"],[18,"עונה אחריתי","דאם וסתה ביום אסורה כל היום וכל הלילה שלפניו ורבי יהודה לא אסר אלא עונת וסתה:"],[19,"ותרתי למה ליה","לרבא לאשמועינן:"],[22,"מתני' ואינה מטהרת מן הוסת","דאסורה כל ימי וסתה שמא תראה:"]],[[2,"","לימים שנים. היינו כרבי דאמר בתרי זימני הויא חזקה ושלא מנו חכמים ג' הואיל ואינו וסת גמור מודה רבי דבעי ג' זימני והכי קים ליה:"],[3,"","אכלה שום וראתה. הואיל ועל ידי מעשה הם אינו וסת גמור ולא הוה בכלל דמתני' וא\"ת ואמאי לא קאמר נמי קפצה וראתה דהוו נמי על ידי מעשה ויש לומר דאינה קובעת וסת לקפיצות לחודיהו כדאמר בפרק קמא (לעיל נדה יא.) דכל שתקבענה מחמת אונס אפי' כמה פעמים לא קבעה אבל אכלה שום לא חשיב אונס כמו טורח של קפיצה שאין הראייה באה על ידי טורח אלא ממילא:"],[6,"","זו דברי רשב\"ג אבל חכמים אומרים כו'. לכאורה משמע זו ולא סבירא ליה מדלא קאמר אבל רבי אומר ואפילו את\"ל הכי לא תקשי לקמן גבי דילוג דמוקמינן שמואל כרשב\"ג דאליבא דמתניתין פליגי רב ושמואל ולמאי דאמר מעיקרא הש\"ס דפליגי בפלוגתא דרבי ורשב\"ג צריך לומר זו וסבירא ליה כדמשני בפרק שור שנגח (ב\"ק דף לז:):"],[11,"","אסורה לשמש כל שש שעות דברי רבי יהודה. לר' יהודה הוה שייך למתני כל היום כולו כדמוכח בסיפא שהוא אוסר כל היום אלא משום רבי יוסי תני לה בתרתי בבי:"],[11,"","וחוששת בששה שעות. היינו כל שעה ששית:"],[12,"","מן המנחה ולמעלה. פירש\"י סוף שש שמאז נוטי' צללי ערב ופי' רשב\"ם דאף על גב דאמר בתמיד נשחט (פסחים נח.) דזמן המנחה לכל המוקדם הוי מששה שעות ומחצה ואילך היינו משום דלא קים לן שפיר בשיעור שעות היום אבל מן הדין הוא מתחילת ז' ומיהו לגבי וסת נמי אסורה עד חצי שעה שביעית דהיינו מן המנחה ולמעלה:"]]],[["\u0001גמ׳\u0002 איתמר ראתה יום חמשה עשר לחדש זה ויום ט\"ז לחדש זה ויום שבעה עשר לחדש זה רב אמר קבעה לה וסת לדילוג ושמואל אמר עד שתשלש בדילוג","נימא רב ושמואל בפלוגתא דרבי ורשב\"ג קמיפלגי דתניא ניסת לראשון ומת לשני ומת לשלישי לא תנשא דברי רבי רשב\"ג אומר לג' תנשא לד' לא תנשא","לא דכ\"ע כרשב\"ג והכא בהא קמיפלגי רב סבר חמשה עשר ממנינא ושמואל סבר כיון דלאו בדילוג חזיתיה לאו ממנינא הוא","איתיביה היתה למודה להיות רואה יום ט\"ו ושינתה ליום ששה עשר זה וזה אסורין שינתה ליום שבעה עשר הותר ששה עשר ונאסר חמשה עשר ושבעה עשר","שינתה ליום שמונה עשר הותרו כולן ואין אסור אלא משמונה עשר ואילך קשיא לרב אמר לך רב למודה שאני","ודקארי לה מאי קארי לה למודה אצטריכא ליה מהו דתימא כיון דלמודה ועקרתיה בתרי זימני עקרה ליה קמ\"ל","מיתיבי ראתה יום עשרים ואחד בחדש זה יום עשרים ושנים בחדש זה יום עשרים ושלשה בחדש זה קבעה לה וסת סירגה ליום עשרים וארבעה לא קבעה לה וסת תיובתא דשמואל","אמר לך שמואל הכא במאי עסקינן כגון דרגילה למחזי ביום עשרים ושינתה ליום עשרים ואחד דיקא נמי דשבקינן ליום עשרים ונקט ליום עשרים ואחד ש\"מ","שאין האשה קובעת לה וסת עד שתקבענה וכו' א\"ר פפא לא אמרן אלא למקבעה אבל למיחש לה בחדא זימנא חיישא","מאי קמ\"ל תנינא היתה למודה להיות רואה יום חמשה עשר ושינתה ליום עשרים זה וזה אסורין","אי מהתם ה\"א ה\"מ היכא דקיימא בתוך ימי נדתה אבל היכא דלא קיימא בתוך ימי נדתה אימא לא קמ\"ל","ואינה מטהרת מן הוסת וכו' א\"ר פפא לא אמרן אלא דקבעתיה תלתא זימני דצריכי תלתא זימני למעקריה אבל תרי זימני בחדא זימנא מיעקר","מאי קמ\"ל תנינא אין האשה קובעת לה וסת עד שתקבענה שלש פעמים מהו דתימא חדא לחד תרי לתרתי ותלתא לתלתא קא משמע לן","תניא כותיה דרב פפא היתה למודה להיות רואה יום עשרים ושינתה ליום שלשים זה וזה אסורין הגיע יום עשרים ולא ראתה מותרת לשמש עד יום שלשים וחוששת ליום שלשים","הגיע יום שלשים וראתה הגיע יום עשרים ולא ראתה והגיע יום שלשים ולא ראתה והגיע יום עשרים וראתה הותר יום שלשים"],[[0,"קבעה לה וסת לדילוג","ואסורה ליום י\"ח לחדש רביעי וליום י\"ט בחדש חמישי וכן לעולם:"],[0,"עד שתשלש בדילוג","ויום ט\"ו אינו מן המנין שהוא תחלת ראייתה ואין שם דילוג:"],[3,"היתה למודה","וסת קבוע לט\"ו ושינתה לי\"ו זה וזה אסורין כלומר כשיגיע ט\"ו וי\"ו עוד תאסר חזרה ושינתה בשניה [לשבעה עשר] הותר ט\"ז מכאן ואילך שלא קבעתו אלא פעם אחת הלכך בפעם אחת הוא נעקר:"],[4,"הותרו כולן","ט\"ו שהרי עקרתו שלשה פעמים וט\"ז וי\"ז בחדא זימנא מיעקר ואפילו י\"ח הבא לא יאסר אלא י\"ט כדקתני משמונה עשר ואילך שהרי שילשה בדילוג וקבעה לה וסת לדילוג:"],[4,"תיובתא דרב","דהא קתני שינתה לשבעה עשר נאסר ט\"ו וי\"ו ולא קתני מי\"ז ואילך ואע\"ג דדילגה ב' זימני אלמא ראייה קמייתא לאו ממנינא:"],[4,"למודה שאני","כיון דוסתה קבוע לט\"ו שדינן ראייה של ט\"ו עם ראיות שעברו עליה שהרי בזמנה ראתה והיכי הוה מצינן למימנייה עם הני דדילוג וכי אמינא אנא היכא דראיית ט\"ו שהיתה תחלת ראייתה או שלא היה לה וסת קודם לכן או שהיה לה וסת ליום עשרים:"],[5,"ודקארי לה מאי קארי לה","הא ודאי היכי מצי לאקשויי מלמודה:"],[5,"","קס\"ד ה\"ה לשאינה למודה בעינן תלתא זימני דילוג והאי דנקט למודה לאו משום עקירת וסת דילוג למידק דלמודה הוא דבעי שתשלש בדילוג אלא משום עקירת וסת ראשון דקתני חזרה ושינתה לי\"ז הותר ט\"ז ונאסר ט\"ו וי\"ז ואע\"ג דעקרתיה לט\"ו תרי זימני דסד\"א כיון דלמודה הואי בט\"ו ועקרתיה ב' זימני תו לא הדרה ותשתרי לט\"ו הבא:"],[5,"קמ\"ל","דאין וסת קבוע נעקר בפחות משלש פעמים:"],[6,"סירגה","מיום כ\"ב ליום כ\"ד:"],[6,"לא קבעה לה וסת","שאין דילוג זה דומה לראשון דראשון יום אחד וזה שני ימים כאחד. קתני מיהא קבעה לה וסת בג' ראיות וראשונה בכלל:"],[7,"ושינתה ליום כ\"א","דאיכא דילוג תלת זימני:"],[7,"דיקא נמי מדשבקינן ליום עשרים","דהוה ליה למיתני ראתה ביום עשרים בחדש זה ויום עשרים ואחד בחדש זה ויום עשרים ושנים בחדש זה שכן דרך לשון תנאים לשנות כלל ולשון קצרה:"],[8,"לא אמרן","דאין קובעת עד שתקבענו שלש פעמים אלא למקבעיה דתהוי דיה שעתה ולא יעקר בפחות מג':"],[8,"אבל למיחש בחדא זימנא חיישא","ליה שאם ראתה ביום ט\"ו פעם אחת חוששת לט\"ו הבא ולא תשמש:"],[10,"הני מילי היכא דקאים","ליה אותו יום ששינתה בו בתוך ימים שראויה להיות בהן נדה כי מתני' שהיא למודה להיות רואה ביום ט\"ו לטבילתה שהוא כ\"ב לראייתה וכדאוקימנא בבנות כותים (לעיל נדה לט.) ושינתה ליום עשרים לטבילה שהן עשרים ושבע לראייה דכי הדר מטי יום ט\"ו לטבילתה קיימא לה בימים הראויים לנדה שהרי שלמו לאחר טבילה י\"א שבין נדה לנדה ונכנסה ארבעה ימים בימים הראויים לנדות אבל היכא דקאי בתוך ימי זיבתה כגון שהיתה למודה לראות ליום חמשה עשר לטבילתה והקדימה וראתה בתוך ימי הזוב כגון ליום עשירי לטבילה:"],[10,"אימא לא","תיחוש לה דכי מטיא טבילתה אחריתי ותטבול ויגיע יום עשרים לא תאסר לשמש דהא קיימא לן בפרק דלעיל (נדה דף לט.) כל אחד עשר בחזקת טהרה שאינה מוחזקת רואה הלכך משום חדא זימנא לא תיחוש לה דאקראי בעלמא הוה קמ\"ל:"],[12,"תנינא אין האשה קובעת ואינה מטהרת","ומדתנא להו גבי הדדי משמע דלא בעי עקירה שלש פעמים אלא למי שנקבע שלש פעמים:"],[12,"חד לחד","חדא עקירה לחד קביעות וקא משמע לן דאפילו קבעתיה תרי זימני מיעקרא בחד זימנא:"],[13,"כוותיה","דאפילו קבעתיה תרי זימני מיעקר בחד זימנא:"],[13,"ה\"ג מותרת לשמש עד יום שלשים","כל ימים שבינתים מותרים:"],[14,"הגיע יום שלשים ולא ראתה הגיע יום עשרים וראתה הותר שלשים","העתיד לבא דהא איעקר מינה ואף על גב דקבעתיה תרי זימני מיעקר בחד זימנא:"]],[[0,"","איתמר ראתה ט\"ו בחדש זה וט\"ז בחדש זה. פי' דווקא בכי האי גוונא אבל ראתה בג' חדשים או בב' לחדש או באחד לכ\"ע אין צריך יותר כדאמר לעיל בסוף בנות כותים (נדה דף לט:) דחזאי ריש ירחא וריש ירחא כו' ואפילו שאחד מלא ואחד חסר ואין הימים שבין ראייה לראייה שוין מ\"מ קביעות החדש גורם והיכא דבראשונה אין לה שיעור בחדש שתהא השניה נראת דילוג מן הראשונה דכ\"ע דאין הראשונה מן המנין ובעינן שתשלש בדילוג כגון ראתה עכשיו ושניה בעשרים לה ושלישית בכ\"א לשניה ומשום הכי נקט ט\"ו בחדש זה ולפירוש זה קשה דבפרק שור שנגח ד' וה' (ב\"ק לז:) מדמה נגח יום חמשה עשר בחדש זה וששה עשר בחדש זה ושבעה עשר בחדש זה לפלוגתא דהכא ואם כן היכי קאמר התם לעיל גבי ראה שור ונגח שור ולא נגח דהויא ראשונה מן המנין הא בכי האי גונא אפי' רב מודה דלא הוי ראשונה מן המנין שהרי לא היתה לשום זמן לא לחדש ולא לשבת ויש לחלק בין סירוגין דימים לסירוגין דשוורים ור\"ח פי' קבעה לה וסת לדילוג כשעשתה שלש פעמים כסדר הזה כגון שראתה ט\"ו בניסן וי\"ו באייר וי\"ז בסיון וכן ראתה ט\"ו בתמוז וי\"ו באב וי\"ז באלול ועוד ראתה ט\"ו בתשרי וי\"ו במרחשון וי\"ז בכסליו חוששת מכאן ואילך ט\"ו לחדש זה וי\"ו לשני וי\"ז לשלישי ולשמואל צריכה שתשלש בדילוג שתראה בחדש רביעי יום י\"ח ובג' חדשים שאחריהם יום י\"ו וי\"ז וי\"ח וכן בשלישי עוד שאחרי כן דראייה של ט\"ו יום בחדש הראשון לא היה ממנינא ותימה למה פי' כן דא\"כ כששאל הש\"ס לימא בדרבי ורשב\"ג קמיפלגי לא פליגי בראייה ראשונה לחוד אלא בשלש ראיות של דילוג ראשון ובמסקנא יהיה הפירוש בע\"א ואמאי לא סגי בג' חדשים כדפי' בקונטרס:"],[4,"","ואינה אסורה אלא מי\"ח ואילך. וא\"ת ויאסר נמי יום י\"ח כי שינתה לי\"ז שהרי דילגה ויהיה בכלל וסת דילוג כמו ט\"ו וי\"ו דחיישינן בחדא זימנא ואומר הר\"י דאין לחוש בדילוג משום חדא זימנא:"],[8,"","מיחש בחדא זימנא חיישינן. פירש\"י דחיישינן לתשמיש וכן צריך לפרש מדלא פרי' הש\"ס בהדיא לטהרות ואין להזכיר בשום קביעות וסת ג' פעמים לגבי תשמיש דהא בחדא זימנא חיישינן אלא לגבי שאם נקבעו שלש פעמים חוששין לו עד שיעקר שלש פעמים:"]]],[["ונאסר יום עשרים מפני שאורח בזמנו בא","\u0001מתני׳\u0002 נשים בבתוליהם כגפנים יש גפן שיינה אדום ויש גפן שיינה שחור ויש גפן שיינה מרובה ויש גפן שיינה מועט ר' יהודה אומר כל גפן יש בה יין ושאין בה יין ה\"ז דורקטי","\u0001גמ׳\u0002 תנא דור קטוע תני רבי חייא כשם שהשאור יפה לעיסה כך דמים יפין לאשה תנא משום ר\"מ כל אשה שדמיה מרובין בניה מרובין","\u0001הדרן עלך האשה\u0002","מתני׳ \u0001תינוקת\u0002 שלא הגיע זמנה לראות וניסת ב\"ש אומרים נותנין לה ארבעה לילות בית הלל אומרים עד שתחיה המכה","הגיע זמנה לראות וניסת ב\"ש אומרים נותנין לה לילה הראשון וב\"ה אומרים עד מוצאי שבת ארבע לילות","ראתה ועודה בבית אביה ב\"ש אומרים נותנין לה בעילת מצוה וב\"ה אומרים כל הלילה כולה:","\u0001גמ׳\u0002 אמר רב נחמן בר יצחק ואפילו ראתה ממאי מדקא מפליג בסיפא בין ראתה בין בשלא ראתה מכלל דרישא לא שנא הכי ולא שנא הכי","תניא נמי הכי ב\"ה אומרים עד שתחיה המכה בין ראתה בין לא ראתה","עד שתחיה המכה עד כמה אמר רב יהודה אמר רב כל זמן שנוחרת כי אמריתה קמיה דשמואל אמר לי נחירה זו איני יודע מה היא אלא כל זמן שהרוק מצוי בתוך הפה מחמת תשמיש","נחירה דקאמר רב היכי דמי אמר רב שמואל בר רב יצחק לדידי מפרשא לי מיניה דרב עומדת ורואה יושבת ואינה רואה בידוע שלא חיתה המכה על גבי קרקע ורואה על גבי כרים וכסתות ואינה רואה בידוע שלא חיתה המכה על גבי כולם ורואה ע\"ג כולם ואינה רואה בידוע שחיתה המכה","הגיע זמנה וכו' איתמר שימשה בימים רב אמר לא הפסידה לילות ולוי אמר הפסידה לילות","רב אמר לא הפסידה לילות עד מוצאי שבת תנן ולוי אמר הפסידה לילות מאי ארבע לילות דקתני ארבעה עונות","ולרב למה לי למיתנא ארבע לילות אורח ארעא קמ\"ל דדרכה דביאה בלילות וללוי ליתני ארבע לילות עד מוצאי שבת למה לי הא קמ\"ל דשרי למבעל לכתחלה בשבת","כדשמואל דאמר שמואל פרצה דחוקה מותר ליכנס בה בשבת ואע\"פ שמשיר צרורות","איתמר בעל ולא מצא דם וחזר ובעל ומצא דם רבי חנינא אמר טמאה ורבי אסי אמר טהורה","ר' חנינא אמר טמאה דאם איתא דהוה דם בתולים מעיקרא הוי אתי ורבי אסי אמר טהורה דילמא אתרמי ליה כדשמואל דאמר שמואל יכולני לבעול כמה בעילות בלא דם ואידך שאני שמואל דרב גובריה","אמר רב בוגרת נותנין לה לילה הראשון וה\"מ שלא ראתה אבל ראתה אין לה אלא בעילת מצוה ותו לא","מיתיבי מעשה ונתן לה רבי ארבע לילות מתוך י\"ב חדש ה\"ד אילימא דיהיב לה כולהו בימי קטנות"],[[0,"ונאסר יום עשרים","הבא שהרי למודה בעשרים ולא עקרתו אלא שני פעמים שהרי עקירה האחרונה של עשרים האחרונה שלא ראתה שאחר השלשים שניים לאו עקירה היא שהרי לא שינתה ליום שלשים השלישיים ולא ראתה עד יום עשרים לחדש כווסתה:"],[0,"מפני שאורח","זה שחזר לשוב יום עשרים בזמנו הראשון בא:"],[1,"מתני' כל גפן יש בה יין","כל אשה יש לה בתולים ודמים:"],[1,"ושאין לה הרי זה דור קטוע","וכיון שאין להן דמים מרובים אין בניהן מרובין:"],[4,"מתני' תינוקת נותנין לה ארבע לילות","לשמש ואפי' רואה אמרינן דם בתולים הוא:"],[4,"עד שתחיה המכה","מפרש בגמרא:"],[5,"הגיע זמנה לראות","ולא ראתה:"],[5,"עד מוצאי שבת","והיא ניסת ברביעי:"],[7,"גמ' אפילו ראתה","בבית אביה אמרו ב\"ה הואיל ולא הגיע זמנה לראות נותנין לה עד שתחיה המכה:"],[7,"מדפליג בסיפא","בהגיע זמנה קתני חילוק בין ראתה ללא ראתה:"],[9,"שנוחרת","לקמן מפרש:"],[9,"שהרוק מצוי","שרואה מחמת תשמיש:"],[12,"עד מוצאי שבת תנן","ביום ובלילה:"],[13,"דשרי למבעל בשבת","אף ע\"פ שלא בעל עדיין כי אם שתי בעילות ופתח דחוק:"],[15,"וחזר ובעל","בתוך ארבע לילות:"],[15,"טמאה","דדם נדה הוא:"],[17,"בוגרת נותנין לה לילה הראשון","ואפי' לב\"ה דאמרי בהגיע זמנה לראות ארבעה הני מילי נערה דמשיגיעו ימי הנעורים הוי זמנה אבל בוגרת לילה הראשון ותו לא:"],[18,"מתוך שנים עשר חדש","שבעל לילה הראשון והלך בדרך מיד ושהה שלשה חדשים וחזר ובעל ומצא דם וכן פעם שניה ושלישית ובא לפני רבי ואמר דם בתולים הוא:"]],[[4,"","מתני' תינוקת:"],[5,"","ד' לילות. ב\"ה לא בעו רצופין כדאמר בגמרא מעשה ונתן לה רבי ד' לילות מתוך שנים עשר חדש וכן נראה דד' לילות לב\"ש אפילו מפוזרות כמו לב\"ה:"],[9,"","כל זמן שהרוק מצוי בתוך הפה. שרואה מחמת תשמיש תלינן כל היום המחרת וכל הלילה שאחריו אפילו לא שמשה בהם בדם בתולים ואפי' אינה נוחרת אבל תו לא תלינן הואיל ולא שמשה כדאמר לעיל בספ\"ק (נדה דף יא:) עבר עליה לילה אחת בלא תשמיש טמאה ורב מחמיר טפי דדוקא כשנוחרת ביום שלאחר תשמיש תלינן בו ובלילה שלאחריו אבל בלא נחירה לא:"],[10,"","על גבי כולם ורואה על גבי כולם ואינה רואה בידוע שחיתה המכה. לספרים דגרסינן הכי על גבי כלים ורואה ליכא לפרושי בידוע דאיכא הוכחה דהא לא מוכח ולא מידי הואיל ורואה אלא ה\"פ בידוע שיש לתלות שחיתה המכה וכן צריך לומר בפ' דם הנדה לעיל (נדה דף נו:) בידוע שלפני הכבוס כלומר שיש לתלותו לפני הכבוס:"],[12,"","רב אמר לא הפסידה לילות עד מוצאי שבת תנן. וא\"ת בפ\"ק דכתובות (דף ו:) דפריך למאן דאסר לבעול בשבת מדקאמר הכא עד מוצאי שבת וקאמר מאי לאו דאי לא בעיל מצי בעיל ומשני לא כשבעל ופריך אי כשבעל מאי למימרא ומשני הא קמ\"ל כדשמואל דאמר פרצה דחוקה כו' והשתא מאי פריך מאי למימרא הא אשמעינן טובא דלא הפסידה לילות כדקאמר הכא וי\"ל דהתם איכא לישנא דשמואל אוסר למבעל לכתחלה וכן לרב ואיצטריך ליה לשנויי הכי לשמואל דאפילו אי כלוי סבירא ליה דהפסידה לילות:"],[13,"","דשרי למבעל לכתחלה כדשמואל כו'. אף על גב דבפ\"ק דכתובות (דף ו:) מייתי הך דשמואל אבעילה שניה מ\"מ לפי האמת דשרי למבעל בתחלה נקט הכא דהוי רבותא טפי:"],[15,"","רבי אסי אמר טהורה. ואף על גב דלית ליה הך סברא דאם איתא דהוה דם מעיקרא הוה אתי מיהו ס\"ל שפיר הא דרב גידל דלעיל ספ\"ק (דף יא:) דאם פסקה מחמת תשמיש וראתה אפילו מחמת תשמיש טמאה דאם איתא דדם בתולין הוא מעיקרא כששמשה הוה אתי ולא הוה לה למפסק מחמת תשמיש כיון דבתחלה בעל ומצא דם אם איתא שנשאר עוד דם בתולין לא היה לה לפסוק כששמשה אבל הכא איירי דבעל ולא מצא דם ולהכי איכא למימר דבעל כדשמואל:"],[16,"","שאני שמואל דרב גובריה. משמע הכא דשמואל לא שכיחא וכן בפרק קמא דחגיגה (דף יד:) גבי בתולה שעיברה פירוש שהושיבוה על פי החבית ואין ריחה נודף ובזה נודע שהיא בתולה ומפיק דכשרה לכהן גדול דאיכא למימר באמבטי עיברה דשכיח טפי מדשמואל וקשה דבפרק קמא דכתובות (דף ו:) קאמר רוב בקיאין בהטיה ויש לומר דהטיה דכתובות אינה בעילה גמורה שתתעבר בה כבשאר ביאות:"]]],[["עד שתחיה המכה תנן","אלא דיהיב לה כולהו בימי נערות נערות י\"ב חדש מי איכא והא אמר שמואל אין בין נערות לבגרות אלא ו' חדשים בלבד וכי תימא בציר מהכי הוא דליכא הא טפי איכא הא בלבד קאמר","אלא דיהיב לה שתים בימי קטנות ושתים בימי נערות הא בעא מיניה רב חיננא בר שלמיא מרב הגיע זמנה לראות תחת בעלה מהו","אמר ליה כל בעילות שאתה בועל אינן אלא אחת והשאר משלימין לד' לילות","אלא דיהיב לה אחת בימי קטנות ושתים בימי נערות ואחת בימי בגרות אי אמרת בשלמא בוגרת בעלמא יהבינן לה טפי כי היכי דאהני קטנות בימי נערות למבצר לה חדא אהני נמי נערות לבגרות למבצר לה חדא","אלא אי אמרת בוגרת דעלמא לא יהבינן לה טפי לא ליתב לה אלא בעילת מצוה ותו לא","לעולם דיהיב לה אחת בימי קטנות וג' בימי נערות מי סברת כל תלתא ירחי חדא עונה כל תרי ירחי חדא עונה","מנימין סקסנאה הוה שקיל ואזיל לאתריה דשמואל סבר למעבד עובדא כוותיה דרב אפילו ראתה אמר לא פליג רב בין ראתה בין לא ראתה","קדים שכיב באורחא קרי שמואל עליה דרב (משלי יב, כא) לא יאונה לצדיק כל און","אמר רב חיננא בר שלמיא משמיה דרב כיון שנתקו שניו של אדם נתמעטו מזונותיו שנאמר (עמוס ד ) גם (אנכי נתתי לך) נקיון שנים בכל עריכם וחוסר לחם בכל מקומותיכם","ראתה ועודה תנו רבנן ראתה ועודה בבית אביה בית הלל אומרים כל הלילה שלה ונותנין לה עונה שלמה וכמה עונה שלמה פירש רבן שמעון בן גמליאל לילה וחצי יום","ומי בעינן כולי האי ורמינהי הרי שהיו גתיו ובית בדיו טמאות ובקש לעשותן בטהרה כיצד הוא עושה הדפין והלולבין והעדשין מדיחן"],[[0,"עד שתחיה המכה תנן","וד' לילות לקטנה מאי עבידתייהו:"],[3,"אינן אלא אחת","ושלש בעי למיתב לה לבד ב' דקטנות:"],[4,"אי אמרת בשלמא בוגרת בעלמא","שניסת לאחר שבגרה:"],[4,"אית לה טפי","מלילה אחת דאית לה ב' לילות מש\"ה יהיב להך משבגרה לילה אחת שלמה ואע\"ג דנבעלה קודם לכן דכי היכי דאהני בעילות קטנות למבצר חדא מד' לילות הניתנות לנערה דהא אמרינן כל בעילות שבעל אינן אלא אחת הא לילה אחת מיהא מבצרי דתו לא יהבינן לה ד' אלא ג':"],[4,"אהני נמי בעילת נערות למבצר חדא","מלילות דבגרות ותו לא הלכך להך בוגרת שנבעלה קודם לכן יהבינן מיהא לילה אחת מהשתים:"],[5,"אלא אי אמרת בוגרת","לילה הראשון ותו לא אמאי יהיב לה להך אחת בימי בגרות א\"כ בעילות דקודם לכן מאי אהנו חדא בעילה הוא דבעי למיתב לה בימי בגרות ולא כל הלילה:"],[6,"וג' בימי נערות","וליכא הכא בגרות כלל. ודקשיא לך הא לא משכחת ג' עונות של ג' חדשים בימי נערות מי סברת כו':"],[7,"כוותיה דרב","בוגרת כל לילה הראשון:"],[8,"לא יאונה כו'","שלא נכשל זה בדבריו:"],[9,"משנתקו שניו","זקנה:"],[9,"נתמעטו מזונותיו","קשין לבא:"],[11,"גתיו","ליין:"],[11,"ובית בדיו","לשמן:"],[11,"הדפין","זהו הדלת שנותנין על הענבים:"],[11,"הלולבים","היינו חופיא אישקוב\"א שמנקים בה את הגת:"],[11,"והעדשין","זו היא הגת עצמה שהענבים נתונים שם:"]],[[1,"","וכי תימא בציר הוא דליכא הא טפי איכא. במסכת קדושין (דף עט.) פרש\"י דלא גרסי' ליה (בלבד) דבלאו בלבד נמי משמע לא פחות ולא יותר מיהו נראה דאי לאו בלבד מצינו לפרושי הכי אין שיעור הקטן שבין נערות לבגרות אלא ו' חדשים והוה משמע שפיר דאיכא טפי:"],[4,"","אלא דיהיב לה אחת בימי קטנות ושתים בימי נערות כו'. מדמסיק לקמן מי סברת דכל תלתא ירחי חדא עונה מכלל דכך היה סבור מתחלה וע\"כ או הראשונה שבקטנות רחוקה מן השניה ו' חדשים והשאר ג' ג' או הרביעית רחוקה ו' חדשים מהשלישית והשאר ג' ג' שאם לא כן לא היו מתוך י\"ב חדש וא\"כ כי מסיק תלתא בימי נערות וכל תרי ירחי חדא עונה לא היה צריך לשנות סדר העונות אלא כל תלתא ירחי חדא עונה הראשונה לפני הנערות והשניה בתחלת נערות והשלישית באמצע נערות ג' ירחים אחרים והרביעית בסוף נערות ויש לומר דניחא ליה להש\"ס להשוות הפסקות הביאות זו מזו כמו שהוא יכול ואע\"ג דביאת קטנות צריך שתהא ו' חדשים לפני נערות דאם לא כן לא היו י\"ב חדש מ\"מ נראה דלאו דוקא בשלא בעל אלא ו' חדשים לפני נערות דהא אפילו בעל כל ימי משך קטנות קאמר דאינו אלא בעילה אחת הילכך אי כל חדא תלתא ירחי תהיה השניה שבתחלת נערות סמוך לביאה אחרונה של קטנות מש\"ה קאמר כל תרי ירחי חדא עונה השניה תהיה בסוף ב' חדשים של נערות רחוק מסוף קטנות והשלישית לסוף ד' חדשים והרביעית לסוף ו' חדשים וריחוקם שוה תרי תרי ירחי וכן כדקס\"ד מעיקרא בכל תלתא ירחי חדא עונה היא שוה בזה הענין ג' חדשים לפני קטנות ונמשכות הביאות עד סוף קטנות דאינה אלא ביאה אחת ומשם לג' חדשים באמצע נערות ומשם לג' חדשים בסוף נערות ורביעית ג' חדשים בבגרות או ראשונה בסוף קטנות ושניה באמצע נערות ושלישית בסוף נערות ורביעית ג' חדשים בבגרות:"],[7,"","סבר למעבד עובדא כוותיה דרב ואפילו ראתה. וא\"ת והא אפילו אי לא הוה מפליג בין ראתה ללא ראתה מ\"מ לא ה\"ל למעבד כרב דהא מסקינן לקמן רב ושמואל דאמרי תרוייהו הלכה בועל בעילת מצוה ופורש וי\"ל דאי לא עביד כהך דלקמן לא הוה מקפיד שמואל דמ\"מ הוה עביד כמתני' אבל בהך שהיה רוצה לעשות מה שלא אמר רב מעולם בזה היה מקפיד שמואל:"],[11,"","הדפין והלולבים והעדשין. העדשין פ\"ה זו היא הגת עצמה שהענבים נתונים בה ובס\"פ בתרא דמסכת ע\"ז (דף עה.) קאמר בעו מיניה מר' אבהו הני גורגי דעובדי כוכבים מהו פרש\"י וכן בערוך גורגי עקלים ופשיט ליה מהא מתני' דהדפין והלולבין וכו' דעקלים מנגבן ופרש\"י התם דמדפשיט מהך מתני' ש\"מ דעיקר היא הילכך סמכינן עלה למשרי גת בהדחה ולא סמכינן אברייתא דלעיל הגת והמחץ דקתני של עץ ושל אבן מנגבן והן טהורין וזהו תימה אי מייתי ההיא ברייתא דהדפין לגבי עקלין דליכא דפליג גבי שאר דברים דפליג אידך ברייתא עלה וליכא טעמא למסמך עליה ומיהו מטעם דבשל סופרים הלך אחר המיקל הוה מצי פסיק כוותיה ועוד דבתוספתא דטהרות גרסינן הדפין והלולבין והעדשין מנגבן והן טהורין ומיהו אומר ר\"י דאפי' אי גרסינן מדיחן כגירסת הספרים ל\"ק לברייתא דלעיל דעדשין לאו גת עצמה הוא אלא עיגול של טיט שמכביד על ענבים שבגת לדורכן וכן פי' בערוך בערך טלפח והוא ים דאמר בפ' המוכר הבית (ב\"ב דף סז:) מאי ים טלפחא ולפי שהוא עגול קרוי עדשים וטלפחא ונקרא ים על שם שהענבים נעצרים על ידו ומתמלאת יין כמים יכסו על ים ומה שלא שנה הכא דין גת היינו משום שהיא כבדה ואינה מטלטלת כל כך ומשתמרת יותר מטומאה מכל כלי הגת שיד הכל ממשמשין בהן וכן בהמוכר הבית לא הוצרך לשנות גת כי פשיטא שמכר את הגת עצמו ומכר את היקבים דקתני בגמרא לאו היינו גת כפרשב\"ם אלא כמו שפירש הערוך סלים שמביאין בהן זיתים לבית הבד ור\"ת מפרש דהך מתני' בכלי בית הבד איירי כדאמר באיזהו נשך (ב\"מ דף עד.) גבי מעטן של זיתים והא מחסר מכמר ועיולי לבי דפי וגבי עביט של ענבים נקט ועיולי לבי מעצרתא וכן עדשין דפרק המוכר את הבית (ב\"ב דף סז:) קאמר להו גבי בית הבד דקאמר המוכר את בית הבד מכר את הים ומפרש מאי ים טלפחא והיינו עדשין דהכא וכן עקלים מצינו בבד בפרק זה בורר (סנהדרין כו.) לעקל בית הבד אני צריך ובהגוזל בתרא (ב\"ק קטו:) כשעקל בית הבד כרוך עליה ואע\"ג דפתח בתרתי גתיו ובית בדיו טמאים גת שייריה כדקאמר בהחולץ (יבמות דף לח:) כתובה לב\"ש שיירה ומיהו קשה דלא דמי אי התם שייר לב\"ש מ\"מ תני לב\"ה אבל הכא אמאי תנא גת כלל אי לאו לאשמועינן בהו מידי אלא ע\"כ משמיענו בבד ומינה שמעינן דגת כיוצא בו וע\"ק אי לא מיירי אלא בבד היכי פשיט דגורגי דעובדי כוכבים דהיינו עקלין דגבי גת דלענין יין נסך מעקלין דברייתא דאיירי בכלי בד אלא ע\"כ צ\"ל דתנא בד ומיניה נשמע גת וכיוצא בו ורשב\"ג נמי קאמר מגת לגת ומבד לבד דדינם שוה ועוד אומר ר\"י דאפילו לפירש\"י דפי' דעדשין היינו גת ולגירסת הספרים דגרסי' מדיחן לא פליג אברייתא דגת ומחץ דקתני מנגבן והן טהורין דהתם בשל עובדי כוכבים מיירי לפיכך מחמרינן לנגב אע\"ג דאינן מזופפין כדקתני אם היו מזופפין אסורין והך דהכא איירי בשל ישראל ונגע בהן עובד כוכבים כדקתני מי שהיו גתיו ובית בדיו טמאין ומש\"ה סגי בהדחה וכן צ\"ל לרבא דאמר התם ל\"ש פירוש דבעי ניגוב אלא שזפתה אבל דרך בה בלא זפיתה לא ובהך ברייתא קתני של עץ ושל אבן מנגבן והם טהורין ואם היו מזופפין אסורין אלמא בלא זפיתה נמי בעי נינוב אלא מתניתא איירי בשל עובד כוכבים ומיהו קשה דהיכי פשיט גורגי דעובדי כוכבים מעקלין דברייתא דשמעתין דלמא דעובדי כוכבים חמירי וי\"ל דאע\"ג דבגת מפלגינן בין ישראל לשל עובדי כוכבים יש דברים דלא שייך לאפלוגי בהו כמו גבי נודות וגבי דבר שמכניסו לקיום דאפי' לפי שעה גזרו בהו רבנן ל\"ש דישראל ל\"ש דעובדי כוכבים ומש\"ה מייתי ראייה שפיר מעקלים אי בגורגי של שיפא ושל גמי איירי ומייתי ראיה דאפי' בשל ישראל מיישנה שנים עשר חדש:"]]],[["העקלים של נצרים ושל בצבוץ מנגבן של שיפא ושל גמי מיישנן וכמה מיישנן י\"ב חדש רשב\"ג אומר מניחן מגת לגת ומבד לבד","היינו ת\"ק איכא בינייהו חרפי ואפלי","רבי יוסי אומר הרוצה לטהר מיד מגעילן ברותחין או חולטן במי זיתים רשב\"ג אומר משום ר' יוסי מניחן תחת הצינור שמימיו מקלחין או במעיין שמימיו רודפין וכמה עונה כדרך שאמרו ביין נסך כך אמרו בטהרות","כלפי לייא בטהרות קיימינן אלא כדרך שאמרו בטהרות כך אמרו ביין נסך","וכמה עונה א\"ר חייא בר אבא א\"ר יוחנן או יום או לילה ר' חנה שאונא ואמרי לה רבי חנה בר שאונא אמר רבה בר בר חנה א\"ר יוחנן חצי יום וחצי לילה","ואמר רב שמואל בר רב יצחק ולא פליגי הא בתקופ' ניסן ותשרי הא בתקופת תמוז וטבת","הכא נמי אימא גבי נדה חצי יום וחצי לילה והא לילה וחצי יום קאמר אלא אי לילה דניסן ותשרי אי חצי יום וחצי לילה דטבת ותמוז","ואב\"א שאני כתובה דמגבי בה טפי עד דחתמי","רב ושמואל דאמרי תרוייהו הלכה בועל בעילת מצוה ופורש","מתיב רב חסדא מעשה ונתן לה רבי ד' לילות מתוך י\"ב חדש","א\"ל רבא הדורי אפירכא למה לי אותיב ממתני' הוא סבר מעשה רב","מ\"מ לרב ושמואל קשיא אינהו דעבדו כרבותינו דתניא רבותינו חזרו ונמנו בועל בעילת מצוה ופורש","אמר עולא כי הוו בה ר' יוחנן ור\"ל בתינוקת לא הוו מסקי מינה אלא כדמסיק תעלא מבי כרבא ומסיימי בה הכי בועל בעילת מצוה ופורש","א\"ל ר' אבא לרב אשי אלא מעתה בעל נפש לא יגמור ביאתו א\"ל א\"כ לבו נוקפו ופורש","ת\"ר וכולן שהיו שופעות דם ובאות מתוך ד' לילות לאחר ד' לילות מתוך הלילה לאחר הלילה כולן צריכות לבדוק את עצמן","ובכולן ר\"מ מחמיר כדברי ב\"ש","ושאר ראיות שבין ב\"ש וב\"ה הלך אחר מראה דמים","שהיה ר\"מ אומר מראה דמים משונים הן זה מזה כיצד דם נדה אדום דם בתולים אינו אדום דם נדה זיהום דם בתולים אינו זיהום דם נדה בא מן המקור דם בתולים בא מן הצדדין","אמר רבי יצחק בר רבי יוסי אמר רבי יוחנן זו דברי ר' מאיר אבל חכמים אומרים כל מראה דמים אחת הן","תנו רבנן הרואה דם מחמת תשמיש משמשת פעם ראשונה ושניה ושלישית מכאן ואילך לא תשמש עד שתתגרש"],[[0,"העקלים","רדוט\"ש. יש מקומות שקושרין את התפוח של חרצנים בעקלים סביב:"],[0,"בצבוץ","קנבוס:"],[0,"מנגבן","שאינם בולעין כל כך:"],[0,"שיפא","גומא גליי\"ד בלע\"ז:"],[1,"חרפי ואפלי","לר\"ש פעמים שהן יותר מי\"ב חדש פעמים שהן פחות:"],[5,"לא פליגי","רבי חייא ורבה בר בר חנה:"],[5,"בתקופת ניסן ותשרי","שהיום והלילה שוים או יום או לילה:"],[5,"בתקופת תמוז וטבת","שאינם שוין חצי יום וחצי לילה דהוי עונה שלימה של י\"ב שעות:"],[7,"שאני כתובה דמגהי בה טפי","יש עיכוב בדבר לדקדק בכל ולחותמה הילכך בעינן לילה שלימה וחצי יום:"],[8,"הלכה בועל בעילת מצוה","בין הגיע זמנה בין לא הגיע:"],[12,"כי הוו מעייני בתינוקת","בהאי פרקא ששמה תינוקת:"],[12,"תעלא","שועל:"],[12,"מבי כרבא","מן המחרישה שאינו מוציא משם אלא אבק ברגליו. הכי נמי לא ילפינן מפרקא דמתני' מידי אלא מברייתא וכרבותינו דאמרי בועל בעילת מצוה ופורש:"],[14,"מתוך ד' לילות","ללא ראתה בבית אביה או מתוך הלילה לראתה בבית אביה צריכות לבדוק שאין סומכות לומר הואיל ושופעות דם מדם בתולים הוא ואפילו אחר ד' לילות אלא בודקות אם נשתנו מראה דמים כדמפרש:"],[15,"ובכולן ר\"מ מחמיר כדברי ב\"ש","לקטנה ד' לילות להצריכה בדיקה אם שופעת מתוך ד' לאחר ד' ולנערה לילה אחד:"],[16,"ושאר ראיות","היכא דאינה שופעת שבין ב\"ש וב\"ה דלב\"ה טהורין ואפי' נשתנו ואמר ר\"מ הלך אחר מראה דמים ובהא לא ס\"ל כב\"ש לגמרי דלב\"ש אפילו לא נשתנו טמאין כיון דאינה שופעת מתוך ד' לאחר ד' לקטנה ומתוך לילה לאחר לילה להגיע זמנה ולא ראתה:"],[19,"הרואה דם","לאו בבתולה קא מיירי אלא בדם נדות:"]],[[1,"","היינו ת\"ק. וא\"ת טובא איכא בינייהו דהא ת\"ק מצריך י\"ב חדש ורשב\"ג קאמר דכשנטמא בזה הגת ישתמש בהן בגת הבאה א\"כ הוא מסוף גת לתחלת גת וחסר משנה כל ימי משך הגת וי\"ל דס\"ל דת\"ק לא מחמיר טפי מי\"ב חדשי לבנה ובישול פירות הולך אחר החמה אם כן מסוף גת לתחלת גת איכא י\"ב חדשי לבנה ומשני איכא בינייהו חרפי ואפלי כלומר אשתקד הוו אפלי ועכשיו חרפי ואיכא פחות מי\"ב חדשי לבנה מגת לגת א\"נ פשיטא ליה דת\"ק לא קאמר י\"ב חדש משנתרוקנה הגת דא\"כ כלו ימי בציר ולא יכול להשתמש עד כ\"ד חודש והיא גת אחרת אלא י\"ב חדש דקאמר ת\"ק עם זמן שהיין בו והיינו כרשב\"ג דאמר לגת הבאה ומשני איכא בינייהו חרפי ואפלי כדפירש רש\"י חרפי שממהר הבציר של שנה זו משל אשתקד רשב\"ג מיקל דליכא י\"ב חדש ואפלי שמאחר הבציר של שנה זו משל אשתקד רשב\"ג מחמיר אבל ת\"ק מודה נמי דכל זמן שיש בו י\"ב חדש עם זמן שהיין בגת די בכך וזו היא קולא:"],[14,"","וכולן ששופעות ובאות מתוך ד' לילות לאחר ד' לילות כולן צריכות לבדוק את עצמן. אור\"י דלאו דוקא כששלמו כל ד' לילות דה\"ה מכל לילה מתוך ד' לילות ליום של אחרי כן דהא אם ראתה ביום טמאה ללוי דאמר ד' עונות ואפילו לרב דאמר לא הפסידה לילות מ\"מ מודה דאם נשתנו תהא ראייה טמאה הילכך צריכה לבדוק אולי נשתנה אע\"ג דבלילה נמי אם נשתנה טמאה מ\"מ לא בעיא בדיקה אבל ביום בעי' בדיקה ולא סמכינן למימר הואיל ושופעת דם בתולים והך הוא בדיקה אפילו לרבנן דפליגי לקמן עליה דר\"מ דאמר כל מראה דמים אחת הן דודאי אית להו הא דספ\"ק (לעיל נדה יא.) אם נשתנו מראה דמים שלה טמאה ולקמן לא פליגי בנשתנה הדם מבתחלה אלא אם בין זה ובין הראשון דומה לדם נדה וה\"פ ובכולן ר\"מ מחמיר כב\"ש בכל מחלוקת שבין ב\"ש וב\"ה (וב\"ה) דמתניתין מחמירין ודוקא באותן ד' לילות לתינוקת שלא הגיע זמנה לראות ובלילה לתינוקת שהגיע זמנה מטהר ר\"מ אפילו דומה לדם נדה תלינן ליה בדם בתולים ושאר ראיות שבין ב\"ש וב\"ה כגון מד' לילות ועד שתחיה המכה לתינוקת שלא הגיע זמנה וכגון מלילה הראשונה לד' לילות בהגיע זמנה דלב\"ש לא תלינן כלל בדם בתולים ולב\"ה תלינן בבתולים אפי' דומה לדם נדה התם מחלק ר\"מ שאם דומה לדם נדה טמאה אע\"פ שבתוך הלילות או הלילה היינו תולין בדם בתולים עכשיו לא נתלה ואם דומה כל הדם שאחרי הד' לילות או הלילה לדם בתולים טהור וחכ\"א כל מראה דמים אחת הן וסבירא להו לגמרי כב\"ה ולעולם תלינן בדם בתולים עד שתחיה המכה או עד ד' לילות רק שלא ישתנה הדם מכמות שהיה ושפיר סבירא להו לרבנן הך דספ\"ק דאם נשתנו מכמות שהיו מראה דמים שלה טמאה ודלא כפירש\"י שפירש דאפי' נשתנו מכמות שהיו מראה דמים טהורה לרבנן וא\"ת מאי קמ\"ל בהך בדיקה והא אפי' בתוך זמן תליית דם בתולים כמו בלא הגיע זמנה לראות לב\"ה דתלינן בדם בתולים עד שתחיה המכה אמר בפ\"ק (לעיל נדה יא:) דבתולה בודקת שחרית וערבית שמא נשתנו מראה דמיה כ\"ש לאחר שעבר זמן תלייתה בבתולים שצריכה לבדוק דהך בדיקה שחרית היא וכי תימא משום שופעת נקט דכיון דשופעת איכא למתלי בבתולים חוץ לזמנה כמו תוך הזמן אדרבה כיון דאפילו בשאינה מרגשת בשום ראייה צריכה לבדוק כ\"ש כשמרגשת בראייה וי\"ל דבדיקה דלעיל שחרית וערבית אוקמינן לטהרות אבל לבעלה לא בעיא בדיקה והכא איירי לבעלה דבעיא בדיקה א\"נ הך בדיקה הויא בשפופרת אם בא ממקור או מן הצדדים וכן משמע בתוספתא וניחא דמשום הכי קתני בסיפא דם נדה בא מן המקור:"]]],[["ותנשא לאחר","ניסת לאחר וראתה דם מחמת תשמיש משמשת פעם ראשונה ושניה ושלישית מכאן ואילך לא תשמש עד שתתגרש ותנשא לאחר ניסת לאחר וראתה דם מחמת תשמיש משמשת פעם ראשונה ושניה ושלישית מכאן ואילך לא תשמש עד שתבדוק עצמה","כיצד בודקת את עצמה מביאה שפופרת ובתוכה מכחול ומוך מונח על ראשו אם נמצא דם על ראש המוך בידוע שמן המקור הוא בא לא נמצא דם על ראשו בידוע שמן הצדדין הוא בא","ואם יש לה מכה באותו מקום תולה במכתה ואם יש לה וסת תולה בוסתה","ואם היה דם מכתה משונה מדם ראייתה אינה תולה ונאמנת אשה לומר מכה יש לי במקור שממנה דם יוצא דברי רבי","רשב\"ג אומר דם מכה הבא מן המקור טמא ורבותינו העידו על דם המכה הבא מן המקור שהוא טהור","מאי בינייהו אמר עולא מקור מקומו טמא איכא בינייהו","שפופרת אפגורי מפגרא לה אמר שמואל בשפופרת של אבר ופיה רצוף לתוכה","אמר ליה ריש לקיש לרבי יוחנן ותבדוק עצמה בביאה שלישית של בעל הראשון אמר ליה לפי שאין כל האצבעות שוות","אמר ליה ותבדוק עצמה בביאה ראשונה של בעל שלישי לפי שאין כל הכחות שוות","ההיא דאתאי לקמיה דרבי אמר ליה לאבדן זיל בעתה אזל בעתה ונפל ממנה חררת דם אמר רבי נתרפאה זאת","ההיא אתתא דאתאי לקמיה דמר שמואל אמר ליה לרב דימי בר יוסף זיל בעתה אזל בעתה ולא נפל ממנה ולא מידי אמר שמואל זו ממלאה ונופצת היא וכל הממלאה ונופצת אין לה תקנה","ההיא דאתאי לקמיה דרבי יוחנן דכל אימת דהות סלקא מטבילת מצוה הות קחזיא דמא א\"ל שמא דימת עיריך עלתה ביך לכי והבעלי לו ע\"ג הנהר","איכא דאמר אמר לה תגלי לחברותיך כי היכי דתהוו עליך להך גיסא נתהוו עלך להך גיסא ואיכא דאמר אמר לה גלי לחברותיך כי היכי דלבעו עליך רחמים דתניא (ויקרא יג, מה) וטמא טמא יקרא צריך להודיע צערו לרבים ורבים מבקשים עליו רחמים","אמר רב יוסף הוה עובדא בפומבדיתא ואתסי","אמר רב יוסף אמר רב יהודה אמר רב התקין רבי בשדות ראתה יום אחד תשב ששה והוא","שנים תשב ששה והן שלשה תשב שבעה נקיים","אמר ר' זירא בנות ישראל החמירו על עצמן שאפילו רואות טפת דם כחרדל יושבות עליה שבעה נקיים","אדבריה רבא לרב שמואל ודרש קשתה שני ימים ולשלישי הפילה תשב שבעה נקיים קסבר אין קשוי לנפלים ואי אפשר לפתיחת הקבר בלא דם","א\"ל רב פפא לרבא מאי אריא קשתה שני ימים אפילו משהו בעלמא דהא א\"ר זירא בנות ישראל החמירו על עצמן שאפילו רואות טפת דם כחרדל יושבות עליה שבעה נקיים","א\"ל אמינא לך איסורא ואת אמרת מנהגא היכא דאחמור אחמור היכא דלא אחמור לא אחמור","(תבעוה נתר בחמין לטבול קמטים ע\"ג נמל סי') אמר רבא תבעוה לינשא ונתפייסה צריכה שתשב שבעה נקיים","רבינא איעסק ליה לבריה בי רב חנינא א\"ל סבר ליה מר למכתב כתובה לארבעה יום א\"ל אין כי מטא לארבעה נטר עד ארבעה אחרינא איעכב שבעה יומי בתר ההוא יומא","א\"ל מאי האי א\"ל לא סבר לה מר להא דרבא דאמר רבא תבעוה לינשא ונתפייסה צריכה לישב שבעה נקיים א\"ל אימר דאמר רבא בגדולה דקחזיא דמא אבל בקטנה דלא חזיא דמא מי אמר","א\"ל בפירוש אמר רבא ל\"ש גדולה לא שנא קטנה גדולה טעמא מאי משום דמחמדא קטנה נמי מחמדא","אמר רבא אשה"],[[0,"ותנשא לאחר","כדמפרש לקמיה שאין כל האצבעות שוות:"],[1,"ותנשא לאחר","דתלתא זימני בעינן לחזקה כרשב\"ג. בכולה גרסינן ושלישית:"],[2,"מכחול","קיסם ארוך ומוך על ראשו של מכחול:"],[2,"מן הצדדין","וטהור:"],[3,"ואם יש לה וסת","לקלקול הזה שאינה רואה כל שעה מחמת תשמיש אלא לפרקים תולה בוסתה ומשמשת בלא בדיקה בין וסת לוסת:"],[4,"דברי רבי","הך מילתא לחודה דנאמנת אשה קאמר רבי אבל רישא כולה רבן שמעון היא:"],[7,"אפגורי מפגרא","שהעץ אינו חלק ומסרטט ומוציא דם:"],[7,"רצוף","כפול:"],[8,"ותבדוק בביאה שלישית של בעל ראשון","כלומר מביאה שלישית של ראשון ואילך תשמש ע\"י בדיקה ולמה תתגרש:"],[8,"לפי שאין כל האצבעות שוות","ושמא בבעל אחר לא תצטרך בדיקה ומוטב שתתגרש ותתקן ולא תבא לידי כרת הלכך מתגרשת עד שתתחזק בשלש אצבעות:"],[9,"ותבדוק בביאה ראשונה של בעל שלישי","משבא עליה פעם אחת לא תשמש שניה בלא בדיקה שהרי הוחזקה בג' אצבעות. ומשנינן אין חזקת ביאה אחת חזקה דאין כל הכחות שוין ושמא בעילה זו היתה בכח מרובה הלכך עד שתתחזק בג' ביאות לכל אחד ואחד והדר תבעי בדיקה לביאה רביעית של בעל שלישי:"],[10,"ההיא דאתאי","שהיתה רואה דם מחמת תשמיש:"],[10,"בעתה","הבהילה פתאום:"],[11,"ממלאה ונופצת","מתמלאה דם ומנפצתו בשעת תשמיש:"],[12,"דימת עיריך","בנות עיריך שהיו מתקנאות ביך בחיבה שביניך לבעליך. דימת לשון ליעוז פרליר\"ץ כמו (יבמות דף נב.) מידם דיימא וכמו (סוטה דף כז.) לא ישא אדם דומה:"],[13,"כי היכי דתהוו עליך","עד השתא להאי גיסא על חיבה יתירה שביניכם:"],[13,"נתהוו עליך לאידך גיסא","ויאמרו כמה שנואה זו ותשוב קנאה ממך:"],[14,"הוה עובדא","וגילתה צערה לרבים ובקשו עליה רחמים ונתרפאה:"],[15,"בשדות","מקום שאין בני תורה ואינן יודעות למנות פתח נדות מתי הן ימי נדה מתי הן ימי זוב:"],[15,"ששה והוא","כדין תורה ושמא בימי נדה הוא:"],[16,"שנים תשב ששה והן","לחומרא שמא ראשון סוף זוב ושני תחלת נדה וצריכה עוד ששה אבל שלשה דאילו הוה ימי זיבה צריכה ז' נקיים השתא נמי תשב שבעה נקיים שמא בימי זיבה עומדת:"],[19,"קשתה שנים","וראתה בימי זוב:"],[20,"איסורא","דאפי' היכא דלא אחמור תשב על כרחה מן התורה:"],[21,"צריכה לישב שבעה נקיים","שמא מחמת תאות חימוד ראתה דם:"],[22,"איעכב ז' יומי","בתר יומא שנתפייסה לינשא:"]],[[4,"","ונאמנת אשה לומר וכו' דברי רבי. פרש\"י דדוקא הך סיפא דנאמנת כרבי אבל כולה רישא כרשב\"ג דסבירא ליה בג' זימני הוי חזקה ור\"י מפרש דאפילו רבי מודה ברואה מחמת תשמיש דבעי ג' זימנין לאחזוקה דומיא דהך דלעיל דאמר לימים ב' ולמה שלא מנו חכמים ג' כגון אכלה שום או פלפלין דאפילו לרבי בעי תלת זימני:"],[8,"","ותבדוק עצמה בביאה שלישית כו'. פירש בקונטרס מביאה שלישית ואילך תשמש על ידי בדיקה ולמה תתגרש מתוך לשונו משמע דאסורה לראשון אפי' בבדיקה וה\"ה דהוה מצי למיפרך לפי פירושו דגם לשני לא תשתרי אלא ע\"י בדיקה כיון דלא ידע שינויא דלאו כל האצבעות שוות ור\"ת מתיר לראשון בבדיקה ויש להעמיד הברייתא כשאינה רוצה לטרוח בבדיקה או שאינה יודעת לבדוק וכן משמע בירושלמי בפ' דם הנדה דפריך ותבדוק עצמה בבעל שני ומשני לפי שאין כל האצבעות שוות כן י\"ל דהש\"ס דידן נמי פריך אשני ובתוספתא (פ\"ח) נמי תניא עד כמה מותרת לינשא עד שלשה כו' פירוש עד כמה מותרת בלא בדיקה ומדלא מהדר אאיסורא לפרש עד כמה היא אסורה אפילו בבדיקה משמע דבבדיקה שריא אפילו לראשון ואתי שפיר לפירוש ר\"ת דפירכא קמייתא הוי כמו פירכא שניה:"],[9,"","ותבדוק עצמה בביאה ראשונה של בעל שלישי. תימה למאי דלא ידע שינויא דאין כל הכחות שוות ליפרוך דתבדוק עצמה בביאה שניה של בעל שני דלענין אצבע שלו אין לומר לא כל האצבעות שוות שהרי כבר ראתה פעם ראשונה על ידי בעילתו ומשום חזקת כחות אין להתירה שהרי הוחזקה בג' כחות של בעל ראשון ואין להתירה אלא מטעם זה דאין כל הכחות שוין ואין חזקת כחו של ראשון מועלת לשני ואכתי לא ידעינן הך טעמא:"],[13,"","כי היכי דתהוו עליך להך גיסא. פירש\"י תחת אשר קנאו באהבת אישך יאמרו כמה שנאה גדולה ותשוב קנאתם ממך ובערוך פי' ששלטו בך עינים להתרחק מבעליך תודיעם עכשיו שאת בת דמים מרובים שבניך מרובין ביותר ויתנו עיניהם בך ויאמרו אשריה שדמיה מרובים שמתוך כך בניה מרובים ומתוך העין שיתנו בך יפסקו הדמים ותתרפא:"],[16,"","שנים תשב ששה. שמא ראתה יום ראשון דם ירוק ואינו מן המנין:"]]],[["לא תחוף לא בנתר ולא בחול בנתר משום דמקטף ובחול משום דמסריך","ואמר אמימר משמיה דרבא אשה לא תחוף אלא בחמין אבל לא בצונן ואפילו בחמי חמה צונן מאי טעמא לא משום דקרירי ומשרו מזייא","ואמר רבא לעולם ילמד אדם בתוך ביתו שתהא אשה מדיחה בית קמטיה במים מיתיבי בית הקמטים ובית הסתרים אינן צריכין לביאת מים","נהי דביאת מים לא בעינן מקום הראוי לביאת מים בעינן כדר' זירא דא\"ר זירא כל הראוי לבילה אין בילה מעכבת בו ושאין ראוי לבילה בילה מעכבת בו","אמר רבין בר רב אדא אמר רבי יצחק מעשה בשפחתו של רבי שטבלה ועלתה ונמצא לה עצם חוצץ בין שיניה והצריכה רבי טבילה אחרת","ואמר רבא טבלה ועלתה ונמצא עליה דבר חוצץ אם סמוך לחפיפה טבלה אינה צריכה לחוף ולטבול ואם לאו צריכה לחוף ולטבול","איכא דאמרי אם באותו יום שחפפה טבלה אינה צריכה לחוף ולטבול ואם לאו צריכה לחוף ולטבול","מאי בינייהו איכא בינייהו למסמך לחפיפה טבילה למיחף ביממא ולמטבל בליליא","אמר רבא אשה לא תעמוד על גבי כלי חרס ותטבול סבר רב כהנא למימר טעמא מאי משום גזירת מרחצאות הא על גבי סילתא שפיר דמי","א\"ל רב חנן מנהרדעא התם טעמא מאי משום דבעית סילתא נמי בעיתא","אמר רב שמואל בר רב יצחק אשה לא תטבול"],[[0,"לא תחוף","שערה:"],[0,"מקטף","נותק שער ומתבלבל וחוצץ:"],[0,"סריך","מדביק השער וחוצץ:"],[1,"ואפילו בחמי חמה","די לה בחמין שהוחמו בשמש:"],[1,"דמשרו מזיא","מקשין את השערות ואין לכלוכן עובר:"],[2,"קמטיה","בית השחי ובית הסתרים שלה:"],[3,"כל הראוי לבילה","במסכת מנחות ששים עשרונים הבאים בכלי אחד ראוין לבלול ואין בילה מעכבת בו שאם לא בלל כשר ושאין ראוי לבילה כגון ששים ואחד עשרונים בכלי אחד בילה מעכבת בו ופסולה הואיל ואי בעי לבלול לא מצי למבלל:"],[5,"אינה צריכה לחוף ולטבול","דודאי לאחר שטבלה בא עליה:"],[7,"איכא בינייהו כו'","ללישנא קמא בעינן סמוך לחפיפה טבילה:"],[8,"גזירת מרחצאות","שדרך מרחצאות לישב ע\"ג אצטבאות של אדמה דדמי לכלי חרס ואתי למימר טבילה עולה בהן:"],[8,"סילתא","בקעת עבה כמו בחברתה ולא בסילתא [ביבמות] (דף סג:):"],[9,"דבעיתא","שלא תפול ולא טבלה שפיר:"]],[[3,"","כל הראוי לבילה אין בילה מעכבת בו. וא\"ת הא בכמה מקומות כתיב בלולה ונימא שנה עליו הכתוב לעכב וי\"ל דכולהו צריכי לגופייהו וקשה דנימא מדתנא בהו קרא בפרשת נשיאים תריסר זימני בלולה בשמן דמעכבא דהכי אמרינן בהקומץ רבה (מנחות יט:) דפריך לשמואל גבי מנחה דלא יליף דורות משעה דכתיב וימלא כפו ממנה לומר דשנה עליו הכתוב לעכב על מלא קומצו ופריך והא אמר שמואל מזרקות מקדשים את היבש דכתיב שניהם מלאים סולת ומשני שאני התם דתנא בהו קרא תריסר זימני לעכב ויש לומר דשמא יש שום דרשא בשום מקום דבילה לא מעכבא וא\"ת כיון דלא מעכבא היכא דאין ראוי לבילה נמי ליתכשר ויש לומר דסברא הוא דכיון דקפיד קרא לכתחלה לעשות המצוה בעינן שיהא ראוי לכך אע\"פ שאינו מעכב דאם לא כן נתבטלה המצוה לגמרי שלא היה יכול לעשותה וכן בכמה מקומות כגון ביאת מים דכתיב כל בשרו וממעטים בית הסתרים ומ\"מ בעינן ראוי לביאת מים בכל בשרה וכן בכמה דוכתי וגבי ערל וטמא דמשלחין קרבנן אף על פי שאינן ראויים לסמיכה ולא מעכבין דהא רבינהו קרא דמזובו ולא מנגעו וקרא בהבאת קרבן מיירי ואמאי הא לא מצי סמיך ובפרק כל פסולי המוקדשין (זבחים לג.) דתכף לסמיכה שחיטה דאורייתא ואע\"ג דלא טהר מנגעו משלח קרבן זיבה וא\"ת אמאי לא בעינן ביאת מים לכתחילה בבית הסתרים כמו בילה וקריאה בחליצה ובביכורים וי\"ל דאין סברא גבי טבילה שלא הקפידה תורה אלא שיטהר האדם ואין לומר דלכתחילה לבעי דכיון דבדיעבד טהור לכתחלה נמי לא בעי ותעלה לו טבילה אבל בילה ומקרא בכורים וחליצה מצות נינהו הלכך לכתחלה ליעבד וא\"ת כיון דלכתחלה בעי' בילה במנחות (ד' יח:) גבי עיקר מילתיה דרבי זירא דקאמר מתנדב אדם מנחה של ס' עשרון ומביאה בכלי אחד מנחה של ס\"א מביא ס' בכלי אחד ואחד בכלי אחד דקים להו דס' נבללין וס\"א אין נבללין ופריך וכי אין נבללין מאי הוי והא תנן אם לא בלל כשר ומשני א\"ר זירא כל הראוי וכו' ומאי פירכא כיון דלכתחילה מצוה לבלול משום הכי מצוה להביא בב' כלים לקיים בה מצות בלילה ואומר ר\"י כיון שנדר מנחה של ס\"א אינו יוצא ידי נדרו אם לא יביא מנחה גדולה הלכך כיון דדיעבד כשר בלא בילה יש לו להביא בכלי אחד לקיום נדרו ואע\"ג דגבי ב' עשרונים קאמר אם רוצה מביא בב' כלים מ\"מ גבי ס\"א מוכח מילתא דנתכוין לקרבן גדול אי נמי מתנדב אדם מנחה קאי אמנחה אחת דאמרינן התם לעיל ומשום הכי לא בעי לפלוגינהו בשני כלים משום בילה כיון דאינה מעכבת מיהו קשה דהך סוגיא דהתם לר\"ש דאית ליה דס\"א אינן נבללים ור\"ש פליג אדרבנן דקאמרי הרי עלי מנחה להביא בכלי אחד והביא בב' כלים דאף ידי נדרו יצא וכיון דבדיעבד יצא בשני כלים שפיר אית ליה לפלוגינהו כדי לקיים מצות בלילה ואכתי קשה מאי פירכא וי\"ל דמנחה של ס\"א משמע יותר מנחה אחת ממנחה קבועה סתם אע\"ג דפריש בהדיא בכלי אחד אי נמי הך פירכא דוכי אין נבללין מאי הוי לרבנן פריך ונאמר דאית ליה לההוא תנא טעמא דר\"ש דס\"א אין נבללים יפה:"],[5,"","אם סמוך לחפיפה טבלה אינה צריכה לחוף ולטבול. והא דאמר בפ\"ק דחולין (דף י.) טבל ועלה ונמצא עליו דבר חוצץ אפילו נתעסק באותו המין כל היום כולו לא עלתה לו טבילה עד שיאמר ברי לי שלא היה עלי קודם לכן התם בשלא טבל סמוך לחפיפה אע\"ג דהתם לא מפליג ועוד אומר ר\"ת דההיא דחולין לטהרות ומחמרינן טפי דאפילו טבל סמוך לחפיפה לא מועלת לו טבילה והכא איירי לבעלה והא דאמרינן בסוף שמעתין ולית הילכתא ככל הני שמעתתא כי איתמר הני לטהרות לא קאי אהך מימרא אלא קאי אכולהו מימרות דמכלי חרס ואילך ועוד אומר ר\"י דאי הך דחולין מיירי לטהרות איכא לאוקמיה בשלא חפפה כלל כדאיתא בירושלמי דמסכת פסחים סוף פרק כל שעה נדה חופפת וסורקת וטובלת כהנת אינה חופפת וסורקת נדה כהנת חופפת וסורקת שלא תחלוק בין נדה לנדה וטעמא מפרש התם לפי שכהנת תדירה בטבילה לא החמירו עליה ובעיוני סגי לה ושוב פירש ר\"ת דחפיפה לא שייכא אלא בראש והך דחולין איירי בשאר הגוף דליכא חפיפה וכן משמע לעיל דקאמר אשה לא תחוף אלא בחמין כו' וקאמר טעמא דמשרו מזיא ומדלא קאמר לא תחוף ראשה ש\"מ דבכ\"מ חפיפה שייך טעמא דמשרו מזיא דבמקום שער הוא ועוד מביא ר\"י ראיה דאמרינן בפרק מרובה (ב\"ק דף פב.) גבי עשר תקנות דעזרא שתהא אשה חופפת וטובלת ופריך מדאורייתא הוא וכו' מאי נינהו שערות ומשני לעיוני מדאורייתא דילמא מיקטר ואתא איהו ותקן חפיפה ומדקאמר דילמא מיקטר שמע מינה דאיכא חפיפה בראש ובכמה מקומות הוזכרה חפיפה אצל הראש אבל במחזור ה\"ר שמריה מפרש בשם רש\"י דבכל הגוף שייך חפיפה כדאמרינן בפ' כל כתבי (שבת דף קכ:) הרי שהיה שם כתוב על בשרו ה\"ז לא יחוף ומיהו בכל הספרים ליכא אלא לא ירחץ ולא יסוך ועוד מייתי ראיה מדמייתי לקמן (נדה דף סז:) אההיא דאשה חופפת בלילה וטובלת בלילה מעובדא דהוה בי ריש גלותא ואמר לה עבדי חסרת דודי חסרת טשטקי חסרת פי' עבדי חסרת להביא מים להחם לרחוץ כל הגוף דאילו חפיפת הראש לא בעי כולי האי ומיהו לפירוש ר\"ת אין ראיה שפירש עבדי חסרת להחם מים להטיל לתוך מי הטבילה הצוננין להחם וטשטקי הוא טשטקי דפיזא והוא כסא לישב עליו בבית המרחץ ורבינו סעדיה פירש טשטקי מסרקות היינו לחוף הראש הילכך אין לנו ראייה שיצטרך חפיפה בגוף אלא לעיוני בעלמא כמו בראש מדאורייתא ואע\"פ שאנו מדמין אין לעשות מעשה אלא צריך לחפוף כל הגוף וכן מנהג כל הנשים לרחוץ כל הגוף עכשיו. [ועי' תוס' ב\"ק פ\"ב. ד\"ה ושתהא]:"],[7,"","איכא בינייהו סמוך לחפיפה טבילה. לא מיירי הכא מידי בהצרכת סמוך לחפיפה טבילה אלא לענין לתלות אחר הטבילה אם נמצא עליה דבר חוצץ קאמר דפליגי אם צריך לענין זה סמוך לחפיפה טבילה:"],[8,"","על גבי כלי חרס. גרסי' דשייך ביה גזירות מרחצאות שרגיל להיות ומצוי שם כלי חרס לצורך חמין:"],[10,"","אשה לא תטבול בנמל. כתוב בספרים אע\"ג דהשתא ליכא אימור ברדיוני נפל ופירש\"י בנמל מפני שהספינות רגילות להיות שם כל שעה מצוי שם טיט ואע\"ג דהשתא ליכא עליה טיט אימור ברדיוני בצאתה מן המים שכשכה רגליה במים ונפל ופי' נמי מפצי ביומי תשרי דבסמוך מחצלות תחתיהן מפני הטיט ולרבינו תם נראה כפירוש ר\"ח לא תטבול בנמל כי בני אדם מצויין שם ובעיתא וממהרת מפני שבושה מבני אדם המצויין שם והוי דומיא דסילתא דהוי טעמא משום דבעיתא ופירש מפצי מחצלות כמין גדר בנהר לצניעות שלא יראוה עוברין ושבין ול\"ג הכא אע\"ג דהשתא ליכא כו' עד בסמוך גבי נתנה תבשיל לבנה וטבלה לא עלתה לה טבילה אע\"ג דהשתא ליכא אימור ברדיוני נפל ומפרש ר\"ת בשני דלתי\"ן לשון נדידה ור\"ח פי' לשון הוחלקה ונפל בירידה ובערוך פירש מפצי משום צניעות ור\"ח פי' מקוואות ביומי ניסן משום דחייש לשאובין וכן פי' בערוך ותימה הוא מה שאיבה שייך וי\"ל כי כמה צינורות מושכין לתוך הנהרות שהם בכלים שחקקן ולבסוף קבען אבל פירש\"י עיקר דנוטפין כמקוה ואינם מטהרין אלא באשבורן ולא דרך זחילה ומשום מים חיים ליכא לפרושי כדפירש\"י דתניא בתוספתא חומר בזב מבזבה שהזב טעון מים חיים [כו']:"]]],[["בנמל אע\"ג דהשתא ליכא אימר ברדיוני נפל","אבוה דשמואל עבד לבנתיה מקוואות ביומי ניסן ומפצי ביומי תשרי","אמר רב גידל אמר רב נתנה תבשיל לבנה וטבלה ועלתה לא עלתה לה טבילה אף על גב דהשתא ליכא אימר ברדיוני נפל","אמר רמי בר אבא הני רבדי דכוסילתא עד תלתא יומי לא חייצי מכאן ואילך חייצי","אמר מר עוקבא לפלוף שבעין לח אינו חוצץ יבש חוצץ אימתי נקרא יבש משעה שמתחיל לירק","אמר שמואל כחול שבתוך העין אינו חוצץ ושעל גבי העין חוצץ אם היו עיניה פורחות אפי' על גבי העין אינו חוצץ","א\"ר יוחנן פתחה עיניה ביותר או עצמה עיניה ביותר לא עלתה לה טבילה","אמר ריש לקיש האשה לא תטבול אלא דרך גדילתה כדתנן האיש נראה כעודר ומוסק זיתים אשה נראת כאורגת וכמניקה את בנה","אמר רבה בר רב הונא נימא אחת קשורה חוצצת"],[[0,"בנמל","פורט\"ו מקום שהספינות נקבעות שמעלות טיט וחוצץ:"],[0,"ברדיוני נפל","הטיט מעליה. ברדיוני איני יודע לשונו ונראה שהוא לשון שיכשוך שכששכשכה רגליה במים בצאתה נפל:"],[1,"מקוואות בימי ניסן","מקוה מים מכונסין ואינן טובלות בנהר לפי שרבו המים בימות הגשמים מגשמים שנפלו וחייש שמא ירבו נוטפין על הזוחלין. ותניא בתורת כהנים מה מעין מטהר בזוחלין אף מקוה מטהר בזוחלין כלומר שמטבילין במכונסין דרך זחילתן קודם שנקוו ונחו במקוה ת\"ל אך מעין מעין מטהר בזוחלין והמקוה מטהר באשבורן ומהו אשבורן דקוו וקיימי דאין מטבילין במכונסים אלא משנקוו למקוויהם ונחו מזחילתן ותנן במסכת מקוואות (פ\"ה מ\"ה) הזוחלין כמעין כלומר זוחלין שבנהרות כמעין והנוטפין כמקוה ומים הנוטפין מההרים הרי הן כמקוה ואין מטהרים בזחילה. הילכך בימי ניסן שנתרבה הנהר על ידי גשמים חייש שמא רבו נוטפין שבו על חיים שבו ובטלו זוחלין ואין מטהרין את הטמא הטובל בהן דרך זחילה וכל הנהרות לעולם הן הולכים וזוחלין לפיכך עביד להו מקוה באשבורן לטבול בתוכו. יש מפרשים דבעינן מים חיים לזבה ולאו מילתא היא דתניא בתוספתא חומר בזב מבזבה שהזב טעון מים חיים כו':"],[1,"ומפצי ביומי תשרי","שטובלין בנהר שהזוחלין מרובין אבל מפני חציצת הטיט נותן מחצלות בנהר שעוברות עליהן:"],[3,"רבדי","פוינטור\"ט:"],[3,"כוסילתא","פלומ\"א. ודרכן של מכות של הקזת דם להעלות גלד:"],[3,"תלתא יומי","גלדן רך ומחובר והוי כגוף הבשר ולא חייצי:"],[4,"לפלוף","קציד\"א:"],[5,"פורחות","פותחת ועוצמת תדיר בין כך ובין כך אינו חוצץ לפי שפריחתה מעבירתו ואינו עב על גב העין ואין בו ממש. ל\"א דומעות שהדמעה מלחלחת את הכחול ואינו חוצץ:"],[6,"פתחה עיניה ביותר","הויא חציצה למעלה:"],[6,"עצמה עיניה ביותר","הויא חציצה למטה:"],[7,"לא תטבול אלא כדרך גדילתה","כלומר לא תדחק זרועותיה על בשרה ולא רגליה ושוקיה זה בזה אלא כדרך הליכתה ושמושה תמיד ומה שנכסה וקמוט ואין מים באין בו לא איכפת לן ואינה צריכה לפשט בית קמטיה וסתריה אלא כדרכן תמיד:"],[7,"כדתנן","גבי ראיית נגעים שטיהר בהן הכתוב בית הסתרים דכתיב (ויקרא יג) לכל מראה עיני הכהן ותנן האיש מראה נגעו לכהן כעודר וכמוסק זיתים:"],[7,"כעודר","בבית השחי וכמוסק זיתים בבית הערוה דאם יש לו נגע בבית השחי אין צריך להגביה זרועותיו יותר מדאי להראותו אלא כעודר שמגביה ואינו מאנס עצמו ומה שיוכל כהן לראות יראה ואם לא יוכל לראות טהור ובבית הערוה א\"צ לכוף ולשוח יותר מדאי אלא כמוסק זיתים אחר שנשרו מן האילן ומלקטן על הארץ:"],[7,"והאשה נראית","לכהן בנגעה:"],[7,"כאורגת","בבית השחי ואם בבית הערוה היא כופפת עצמה כמניקה את בנה:"],[8,"נימא אחת","מיהדקא שפיר וחוצצת:"]],[[2,"","נתנה תבשיל לבנה. בפירוש ר\"ח כתוב עוד מימרא אחרת שאינה כתובה בספרים שלנו וזו היא מפשלת את בנה וטובלת לא עלתה לה טבילה ויש לפרש מפשלת את בנה לאחוריה והיא ערומה ולא היו בגדיה עליה וטבלה לא עלתה לה טבילה דחיישינן שמא הוה עליה דינוקא טיט וכיוצא בו ונדבק באמו וחוצץ בטבילתה ולא ידעה לה אף על גב דחזינן לה השתא דליכא מידי עליה חיישינן דלמא בעלייתה מן הטבילה נפל ברדיוני הוחלק ונפל דרך ירידה כפי' ר\"ח וצ\"ל שהיתה מפשלת בנה אפי' לפני טבילתה בסמוך ולאו דוקא בטבילתה:"],[4,"","לפלוף שבעין לח אינו חוצץ יבש חוצץ. דדווקא שבתוך העין מפני שהדמעה שבעין מלחלחתו ואינו מניחתו להיות יבש אבל לפלוף חוץ לעין אפי' לח חוצץ והכי משמע במסכת מקוואות פ\"ט (מ\"ב) דגבי אלו חוצצין קתני לפלוף שחוץ לעין וגבי שאין חוצצין קתני לפלוף שבעין ולא מפליג בין לח ליבש אלא בין חוץ לעין לתוך העין והיינו בלח דיבש בעין נמי חוצץ וצואה שתחת הצפורן יבשה חוצץ והא דתנן התם במס' מקוואות גבי ואלו שאין חוצצין בטבילה לכלוכי צואה שעל הבשר וצואה שתחת הצפורן (וצפורן המדולדלת) מיירי בלח דומיא דלכלוכי צואה שעל הבשר דאי ביבש אמאי לא חייצי ועוד דלעיל גבי ואלו חוצצין קתני גלדי צואה שעל בשרה ובצק שתחת הצפורן:"],[6,"","פתחה עיניה ביותר או עצמה עיניה ביותר. לכך יש ללמוד לכל אשה הטובלת שלא תטבול ותפתח עיניה ולא תעצים עיניה ביותר לפירש\"י דלא גרסינן בסמוך דהני שמעתא לטהרות ולכל הפירושים צריך ללמדה לפתוח פיה שיהא ראוי לביאת מים כדאמרינן לעיל דכל בית הסתרים בעינן שיהא ראוי לביאת מים ומייתי נמי משפחתו של רבי שטבלה ונמצא עצם בין שיניה והצריכה רבי טבילה אחרת ותנן נמי בהדיא במס' מקוואות בפ\"ח (מ\"ה) נדה שנתנה מעות בפיה ירדה וטבלה טהרה מטומאתה אבל טמאה אגב רוקה נתנה שער בפיה קפצה ידיה קמצה שפתותיה כאילו לא טבלה וגם צריך ללמדה להרחיק ירכותיה קצת כדאמרינן בסמוך כאורגת וכמניקה את בנה לענין הגבהת הדד קצת מעל החזה:"],[6,"","פתחה עיניה כו'. אחר זה כתוב בפירוש רבינו חננאל ובמקצת הספרים ולית הלכתא ככל הני שמעתתא דכי איתמר הני לטהרות אבל לבעלה טהורה כי הא דאמר ריש לקיש אשה לא תטבול אלא דרך גדילתה ובתשובה אחת כתב רש\"י דל\"ג חדא דקאמר אבל לבעלה טהורה כי הא דאמר ר\"ל מה ענין ר\"ל להנך דלעיל ועוד דכל הני שמעתתא דרב ודרב גידל ורמי בר חמא וכולן היו בבבל ולצורך מקומן היו צריכין וזהו דוחק דלבני א\"י היו מדברין ועוד דאבוה דשמואל דעבד לבנתיה מקוואות בבבל ועוד דכולהו בלשון נקבה נקטינהו אשה לא תעמוד על כלי חרס אשה לא תטבול בנמל נתנה תבשיל לבנה פתחה עיניה ואי לטהרות היה לא היה צריך להזכיר בכל פעם אשה ועוד דתניא בפרק החולץ (יבמות דף מז: ושם) כל דבר שחוצץ בטבילה חוצץ בגר ובעבד משוחרר ובנדה והיינו נדה לבעלה דאי לטהרות מאי שנא דנקט נדה ועוד דומיא דגר ועבד משוחרר דאיירי בטבילת איסור והיתר והכי קאמר כל החוצץ בטבילת טומאה וטהרה חוצץ בטבילת איסור והיתר וכן פרש\"י בתשובתו דכל חומרות דהך שמעתתא נוהגות עכשיו בטבילת נדה לבעלה אבל רבינו תם פירש שנראה כגירסת הספרים ואיתא נמי בפי' ר\"ח והלכות גדולות ובהלכות נדה שפירש רב סעדיה וכן צריך לחלק דלעיל אמרינן דבית הסתרים לא בעיא ביאת מים ובפ\"ט דמס' מקוואות (מ\"ב) גבי ואלו חוצצין באדם ומחשב בית הסתרים שבאשה אלמא בעיא ביאת מים אלא ודאי ההיא לטהרות ובשמעתין לבעלה והך דהחולץ (יבמות דף מז:) דכל שחוצץ בטבילה חוצץ בגר כו' ובנדה קיימא אהני חציצות דפרק ט' דמקוואות דחצצי לענין בעלה שכן דרך הברייתא לעמוד על המשנה אבל הנך חומרי דכלי חרס וסילתא ונמל ומפצי ומפשלת וריבדא ולפלוף שמחמירות יותר מן המשנה דקתני בפ\"ט לפלוף שבתוך העין אינו חוצץ ומשמע בין לח בין יבש אינו חוצץ מדלא מפליג ובסילתא ופתחה עיניה ועצמה ובכל הנך חומרי לית הילכתא כוותייהו אלא בהך חומרא דריש לקיש דאיתא אפי' לבעלה ומיהו קשה לפירוש ר\"ת דהך משנה דפ\"ט דבית הסתרים שבאשה חוצץ דמוקי לטהרות קתני נמי דין לפלוף שבעין שחוץ לעין חוצץ שבתוך העין אינו חוצץ דהא מוקים לה לבעלה וכן פי' דהך דהחולץ וכל דבר שחוצץ בטבילה קיימא אמשנה דטהרות דאיירי לבעלה ומה שהקשה מבית הסתרים דשמעתין למתני' דמקוואות לא קשה מידי דבסיפא גבי ואלו שאין חוצצין קא חשיב בית הסתרים שבאיש והיינו כשמעתין וצריך ליתן טעם בהך בבא גופה מה חילוק יש בין בית הסתרים דאיש ודאשה ונראה שיש בית הסתרים שהאשה מקפדת ולא האיש ובזה קא מפליג בין איש ובין אשה ולפלוף שבעין איירי דוקא בלח כדפירשתי:"],[7,"","וכמניקה את בנה. פרש\"י לענין בית הערוה ואין נראה דבת\"כ תני לה גבי הדד כדפרישית לעיל והכי תניא לכל מראה עיני הכהן פרט לבית הסתרים מכאן אמרו האיש נראה כעודר וכמוסק כו' כעודר בבית הסתרים וכמוסק בין השיחין והאשה כאורגת וכמניקה את בנה מניקה את בנה תחת הדד כאורגת ביד הימנית רבי אומר כטווה פשתן ביד השמאלית ובפ\"ב דנגעים (מ\"ד) תנן נמי כעורכת פי' כעורכת פת לענין בית הסתרים:"]]],[["שלש אינן חוצצות שתים איני יודע ור' יוחנן אמר אנו אין לנו אלא אחת","אמר ר' יצחק דבר תורה רובו המקפיד עליו חוצץ רובו ואינו מקפיד עליו אינו חוצץ וגזרו על רובו שאינו מקפיד משום רובו המקפיד וגזרו על מיעוטו המקפיד משום רובו המקפיד","ולגזור נמי על מיעוטו שאינו מקפיד משום מיעוטו המקפיד היא גופה גזרה ואנן ניקום ונגזור גזרה לגזרה","אמר רב נדה בזמנה אינה טובלת אלא בלילה ושלא בזמנה טובלת בין ביום בין בלילה רבי יוחנן אמר בין בזמנה בין שלא בזמנה אינה טובלת אלא בלילה משום סרך בתה","ואף רב הדר ביה דאמר רבי חייא בר אשי אמר רב נדה בין בזמנה בין שלא בזמנה אינה טובלת אלא בלילה משום סרך בתה","אתקין רב אידי בנרש למטבל ביומא דתמניא משום אריותא רב אחא בר יעקב בפפוניא משום גנבי","רב יהודה בפומבדיתא משום צנה רבא במחוזא משום אבולאי","אמר ליה רב פפא לרבא ולאביי מכדי האידנא כולהו ספק זבות שוינהו רבנן ליטבלינהו ביממא דשביעאה","משום דרבי שמעון דתניא (ויקרא טו, כח) אחר תטהר אחר אחר לכולן שלא תהא טומאה מפסקת ביניהן ר' שמעון אומר אחר תטהר אחר מעשה תטהר","אבל אמרו חכמים אסור לעשות כן שמא תבא לידי ספק","אמר רב הונא אשה חופפת באחד בשבת וטובלת בשלישי בשבת שכן אשה חופפת בערב שבת וטובלת במוצאי שבת","אשה חופפת באחד בשבת וטובלת ברביעי בשבת שכן אשה חופפת בערב שבת וטובלת במוצאי יו\"ט שחל להיות אחר השבת","אשה חופפת באחד בשבת וטובלת בחמישי בשבת שכן אשה חופפת בערב שבת וטובלת במוצאי שני ימים טובים של ראש השנה שחל להיות אחר השבת","ורב חסדא אמר כולהו אמרינן שכן לא אמרינן היכא דאפשר אפשר היכא דלא אפשר לא אפשר","ורב יימר אמר אפילו שכן נמי אמרינן לבר מאשה חופפת באחד בשבת וטובלת בחמישי בשבת דלמוצאי שני ימים טובים של ראש השנה שלאחר השבת ליתא דאפשר דחופפת בלילה וטובלת בלילה","דרש מרימר הלכתא כרב חסדא וכדמתרץ רב יימר","איבעיא להו אשה מהו שתחוף בלילה ותטבול בלילה מר זוטרא אוסר ורב חיננא מסורא שרי","א\"ל רב אדא [לרב חיננא מסורא] לאו הכי הוה עובדא בדביתהו דאבא מרי ריש גלותא דאיקוט אזל ר\"נ בר יצחק לפיוסה ואמרה ליה מאי איתיה השתא"],[[0,"שלש","לא מיהדקי:"],[1,"דבר תורה","הלכה למשה מסיני דאמר מר (סוכה דף ה:) שיעורין חציצין ומחיצין הלכה למשה מסיני:"],[1,"רובו","רוב שערו קשור אחת אחת:"],[3,"בזמנה","בשביעי. ובנדה דאורייתא קמיירי שלא ספרה ז' נקיים:"],[3,"בלילה","דכתיב בה (ויקרא ט״ו:י״ט) תהיה בנדתה תהא בנדתה כל ז':"],[3,"שלא בזמנה","בשמיני:"],[3,"משום סרך בתה","שנוהגת אחריה לטבול ביום ואפילו בזמנה ואתיא לידי כרת ולא ידעה דאמה בשמיני הוא דטבלה ביום:"],[6,"אבולאי","שוערי העיר ועובדי כוכבים הן. ל\"א בנינים של מערות היו בדרך בית הטבילה ואם תפול שם תסתכן:"],[7,"ספק זבות שוינהו","שאפילו נדה סופרת ז' נקיים דהחמירו על עצמן כדר' זירא:"],[7,"ליטבלה ביממא דשבעה","ממה נפשך אם נדה היא הרי יום טבילתה יותר מז' לראייתה ואם זבה היא טובלת זבה ביום:"],[8,"אחר מעשה","כיון שספרה מקצת היום של ז' תטהר ע\"י טבילה:"],[9,"לידי ספק","שמא תשמש בו ביום ותראה מיד לאחר תשמיש ונמצא סותרת כל שלפניה וטבילתה פסולה:"],[10,"שכן אשה חופפת בע\"ש וטובלת למוצ\"ש","דהא אינה יכולה לחוף בשבת ודנין אפשר משאי ואפשר:"],[13,"כולהו אמרי'","היכא דהגיע טבילתה במוצ\"ש חופפת בע\"ש ואם הגיע טבילתה במוצאי י\"ט אחר השבת או למוצאי ב' ימים טובים של ר\"ה אחר השבת חופפת נמי מבע\"ש דהא לא אפשר לחוף ביו\"ט:"],[13,"שכן לא אמרי'","היכא דטובלת בליל יום חול שיכולה לחוף היום אסורה לחוף מאתמול כדקאמרן משום טעמא דשכן אשה חופפת בע\"ש וטובלת למוצאי שבת דהתם לא אפשר אבל מוצאי יום חול אפשר לחוף היום:"],[14,"אפילו שכן אמרינן","דאפילו טבלה מוצאי יום חול יכולה לחוף מאתמול:"],[14,"לבד מאשה חופפת באחד בשבת וטובלת בחמישי בשבת","דרחוק יותר מדאי ואפילו טעמא דשכן ליכא למימר דאפילו במוצאי שני ימים טובים של ר\"ה שאחר השבת אסורה לחוף בע\"ש ומוטב שתחוף בליל טבילתה:"],[15,"והלכתא כרב חסדא","לחומרא דאמר שכן לא אמרינן דהיכא דטבלה מוצאי יום חול לא תחוף מאתמול ובמאי דאמר רב חסדא כולהו אמרינן דהיכא דטבלה במוצאי ב' ימים טובים [של ראש השנה] אחר השבת חופפת בע\"ש לית הלכתא כוותיה אלא כדמתרץ רב יימר חייפא בליליא וטבלה בליליא. מרימר חומרי חומרי נקט מדרב חסדא ומדרב יימר:"],[16,"מהו שתחוף בלילה","בליל טבילתה מי אמרינן מתוך שממהרת לטבילתה לא חייפא שפיר:"],[17,"דאיקוט","לשון קטטה ולא רצתה לטבול:"],[17,"מאי איתיה השתא","מה לך למהר הלילה:"]],[[3,"","משום סרך בתה. ליכא לפרושי דדוקא בנדה אסור משום סרך בתה שתהא סבורה שהוא שביעי ותטבול בשביעי ותשמש ואיכא כרת אבל זבה אפילו אם בתה סבורה שהוא שביעי ליכא איסורא דאורייתא אלא חששא בעלמא שמא תראה אחר שתטבול ביום שביעי כדר\"ש הא ליכא למימר דהא אתקין רבא למטבל ביממא דתמינאה במחוזא משום אבולאי משמע הא לאו אבולאי אסור אע\"ג דחומרא דרבי זירא היתה נוהגת בימיו וטובלת בשמיני כדא\"ל רב פפא לאביי ולרבא מכדי האידנא כולהו ספק זבות שוינהו רבנן ואביי ורבא בדור אחד היו הילכך אפי' בזמן הזה אסור לטבול בין בח' בין בט' ביום ומיהו אומר ר\"ת שאין קפידא רק כשתשוב לביתה שיהיה לילה וא\"צ שתצא בלילה מביתה דשוב לא יבוא לידי ספק ליכא למיחש אם תטבול היא ביום סמוך לחשיכה תטבול בתה בעוד היום גדול דמרגשת הבת בכך שתטבול סמוך לחשיכה כאמה אבל במקום שיש לירא מפריצי העיר או מגנבים שרי כדאיתא בשמעתין ורבינו משולם התיר לאשה בעיר שהיה לחוש לגנבים לחוף בע\"ש בז' שלה ולטבול ביום שבת שהוא שמיני מבעוד יום משום גנבים ור\"ת אוסר דתרי קולי לא אשכחן דשרי הש\"ס הרחקת חפיפה מטבילה וסרך בתה:"],[9,"","אבל אמרו חכמים אסור לעשות כן שלא תבוא לידי ספק. צ\"ל אסור לעשות כן לטבול דאי אתשמיש מהו שלא תבוא לידי ספק הא כבר באה בשעת תשמיש שמא תראה והוה ליה למימר שלא תבא לידי ודאי ועוד היכי שרו רבנן לשמש הא ודאי אמרי' לקמן במתני' (נדה דף עב.) הרי זה תרבות רעה גבי שומרת יום כנגד יום שטבלה בשני לראייתה וקאמר מגעה ובעילתה תלויה וכן משמע בשמעתין מדפריך ונטבלינהו ביממא דז' ומשני משום דר\"ש אלמא אטבילה קאמר ר\"ש דאסור ומיהו זה יש לדחות דלעולם קאי אתשמיש אבל טבילה שריא לר\"ש אלא אח\"כ החמירו לאסור בה הטבילה גזרה שמא תשמש אבל קשה דלעיל פ' המפלת (נדה דף כט:) בשמעתין דטועה פריך בכ\"א תשמש ומשני ר\"ש היא דאמר אבל אסור לעשות כן אם כן אתשמיש קאי דהא ודאי ביממא מטבלינן לה משום טבילה בזמנה מצוה וי\"ל דה\"פ ר\"ש היא דאמר גבי ודאי זבה דאסור לעשות כן לטבול ביום שמא תבא לידי ספק לשמש שבעילתה תהא תלויה הילכך בהך טועה אע\"ג דאיכא בה כמה ספקות דשמא לא היתה זבה כלל ואם היתה זבה אימר הרחיקה לידתה ושמא לא תראה אסורה לשמש לר' שמעון אבל טבילה תהא מותרת אפילו לר\"ש דשרי לה לטבול משום טבילה בזמנה מצוה:"]]],[["תסגי אייתי למחר וידע מאי קאמרה ליה אמר דודי חסרת טשטקי חסרת עבדי חסרת","דרש רבא אשה חופפת בערב שבת וטובלת במוצאי שבת אמר ליה רב פפא לרבא והא שלח רבין באגרתיה אשה לא תחוף בערב שבת ותטבול במוצאי שבת","ותמה על עצמך היאך חופפת ביום וטובלת בלילה הא בעינן תכף לחפיפה טבילה וליכא","הדר אוקי רבא אמורא עליה ודרש דברים שאמרתי לפניכם טעות הן בידי ברם כך אמרו משמיה דרבי יוחנן אשה לא תחוף בערב שבת ותטבול במוצאי שבת ותמה על עצמך היאך חופפת ביום וטובלת בלילה הא בעינן סמוך לחפיפה טבילה וליכא","והלכתא אשה חופפת ביום וטובלת בלילה והלכתא אשה לא תחוף אלא בלילה (אלא) קשיא הלכתא אהלכתא","לא קשיא הא דאפשר הא דלא אפשר","\u0001מתני׳\u0002 נדה שבדקה עצמה יום שביעי שחרית ומצאה טהורה ובין השמשות לא הפרישה ולאחר ימים בדקה ומצאה טמאה הרי היא בחזקת טהורה","בדקה עצמה ביום שביעי שחרית ומצאה טמאה ובין השמשות לא הפרישה ולאחר זמן בדקה ומצאה טהורה הרי זו בחזקת טמאה","ומטמאה מעת לעת ומפקידה לפקידה ואם יש לה וסת דיה שעתה","ור' יהודה אומר כל שלא הפרישה בטהרה מן המנחה ולמעלה הרי זו בחזקת טמאה וחכמים אומרים אפילו בשנים לנדתה בדקה ומצאה טהורה ובין השמשות לא הפרישה ולאחר זמן בדקה ומצאה טמאה הרי זו בחזקת טהורה","\u0001גמ׳\u0002 איתמר רב אמר זבה ודאי ולוי אמר זבה ספק","אהייא אילימא ארישא הרי זו בחזקת טהורה קתני","אלא אסיפא בשלמא ספק זבה אמרינן אלא זבה ודאי נמי הרי בדקה ומצאה טהורה","אלא כי איתמר דרב ולוי שמעתא באפי נפשה איתמר נדה שבדקה עצמה ביום השביעי שחרית ומצאה טמאה ובין השמשות לא הפרישה ולאחר ימים בדקה ומצאה טמאה רב אמר זבה ודאי ולוי אמר זבה ספק","רב אמר זבה ודאי כיון דמעיקרא נמצאת טמאה ועכשיו נמצאת טמאה טמאה ודאי ולוי אמר ספק זבה אימר פסקה ביני וביני"],[[0,"תסגי ואייתי למחר","די לך אם אטבול למחר:"],[0,"וידע","רב נחמן:"],[0,"מאי קאמרה ליה","שלא חפפה:"],[0,"עבדי חסרת","להביא מים ולחמם:"],[0,"דודי","קדרות להחם בהם חמין:"],[0,"טשטקי","פלדושטו\"ל לישב עליהן:"],[2,"ותמה על עצמך היאך אשה כו'","שהרי בקושי התירו להרחיק חפיפתה מטבילתה כל כך אלא משום דאי חפפה בליל טבילתה אימור לא חייפא שפיר משום דממהרת לטבילתה מתוך שמהומה לביתה:"],[5,"הא דאפשר","לחוף ביום חופפת ביום:"],[5,"הא דלא אפשר","לחוף כגון מוצאי יום טוב לא תחוף אלא בלילה:"],[6,"מתני' לא הפרישה","לא בדקה עצמה להפריש בטהרה:"],[6,"הרי זו בחזקת טהורה","בימים שבינתיים וטהרותיה שנגעה בהן לאחר שטבלה בליל שמיני טהורות דהשתא הוא דחזאי:"],[8,"ומטמאה מעת לעת","ארישא קאי דקתני אחר ימים בדקה ומצאה טמאה מטמאה מעת לעת של ראייה זו:"],[9,"אפילו בשנים לנדתה בדקה","שחרית ומצאה טהורה ובין השמשות לא הפרישה ולסוף ז' טבלה ואחר ימים בדקה ומצאה טמאה הרי זו עד עכשיו בחזקת טהורה. ושלש מחלוקות בדבר לתנא קמא שביעי הוא דמטהרתה בדיקת שחרית אבל שני לא ולר' יהודה אפילו בדיקת שביעי שחרית לא מטהרה עד שתפריש בין השמשות ולרבנן בתראי אפילו בשני:"],[10,"גמ' זבה ודאי","מפרש ואזיל:"],[11,"אהייא","קאי:"],[12,"אסיפא","בדקה שביעי שחרית ומצאה טמאה ובין השמשות לא הפרישה:"],[12,"בשלמא ספק זבה לחיי","דכיון דלא הפרישה בטהרה לא שחרית ולא ערבית איכא לספוקי ברואה ח' וט' וי':"],[12,"אלא זבה ודאי נמי","בתמיה. והרי בדקה לאחר הימים ומצאה טהורה ואיכא למימר כיון דמצאה טהורה עד השתא נמי לא חזאי:"],[13,"באפי נפשה","ולאו אמתניתין:"]],[[3,"","כך אמרו משמיה דרבי יוחנן אשה לא תחוף בערב שבת ותטבול למוצאי שבת ותמה על עצמך היאך אשה חופפת ביום וטובלת בלילה. שהרי בקושי התירו לה להרחיק חפיפתה כל כך אלא משום דאי חופפת בליל טבילתה אימור לא חייפא שפיר מתוך שמהומה לביתה ממהרת לטבילתה ופירש רש\"י הא דאפשר לחוף ביום כגון בימי החול חופפת ביום וטובלת בלילה הא דלא אפשר לחוף ביום כגון שאירעה טבילתה במוצאי שבת ואם תחוף בע\"ש תרחיק יותר מדאי מטבילתה חופפת בליל טבילתה במוצאי שבת וא\"ת הא דפסקינן לעיל הלכתא כרב חסדא וכדמתרץ רב יימר לא קאי דהכא אמרינן דאינה חופפת ע\"ש וטובלת למוצאי שבת וי\"ל דאיכא לאוקמי פסק דלעיל שליל טבילתה במוצ\"ש והוא יו\"ט אז ודאי תחוף מע\"ש ולא תפסיד עונתה הואיל ואינה יכולה לחוף בליל טבילתה ולא ביום שלפני טבילה מ\"מ לפירוש רש\"י נראה דמותר לחוף בליל טבילה אלא שטוב לה יותר לחוף ביום מפני שמהומה לביתה וכן משמע מדקאמר אשה חופפת ביום ולא קאמר אשה לא תחוף אלא ביום כדקאמר אשה לא תחוף אלא בלילה וכן משמע לעיל בעובדא דבי ריש גלותא דמותר לחוף בליל טבילה ולא מסתבר לפלוגי משום דאיקוט מדמייתי מההוא עובדא דנדה חופפת בלילה משמע אף בלא אונס ובשאלתות דרב אחאי פרשת אחרי מות [סי' צו] פירשה הא דאפשר לחוף בליל טבילה שהוא חול לא תרחיק חפיפה מטבילה כלל ואפילו אם היום כמו כן חול לא תחוף אלא בלילה והא דלא אפשר כגון שליל טבילה יום טוב או שבת אז תחוף ביום שלפני הטבילה ואפילו אם יום שלפני הטבילה כמו כן יו\"ט או שבת אז תחוף מערב שבת או מערב יו\"ט כפסק שלמעלה דדריש מרימר דהילכתא כרב חסדא וכדמתרץ רב יימר ולדברי השאלתות כל זמן שתוכל אין לחוף אלא בליל טבילה מיהא לפי מנהג הנשים של עכשיו ששוהות במרחץ עד הלילה מותר לחוף ביום אף לפי השאלתות ואינו אסור אלא לחוף מבעוד יום ולצאת מן המרחץ קודם הלילה אבל בששהתה שם עד הלילה חפיפה אריכתא היא שכל שעה עוסקת בחפיפת גופה ושערה ותבא עליה ברכה ועוד יש שמחמירות אע\"פ שחופפת נושאות עמהן מסרק וסורקות עצמן בבית הטבילה ור\"ת פירש ותמה על עצמך זהו כפל מלה כלומר היאך אתה אומר דבר זה שאשה חופפת ביום וטובלת בליל מוצאי שבת והא בעינן סמוך לחפיפה טבילה ואומר ר\"י דכי האי גוונא איכא בפסחים פרק כל שעה (פסחים דף כג.) ותמה על עצמך היאך חמץ אסור בהנאה כל שבעה:"],[4,"","והלכתא אשה חופפת ביום וטובלת בלילה. פי' בערב שבת וטובלת במוצאי שבת והלכתא אשה לא תחוף אלא בלילה פירוש במוצאי שבת ולא תמהר לחוף בערב שבת:"],[5,"","הא דאפשר. לחוף במוצאי שבת שהוא חול תחוף בו ולא תמהר לחוף מערב שבת והא דלא אפשר לחוף במוצאי שבת ליל טבילתה כגון שהוא יום טוב חופפת מערב שבת אף על פי שטבילתה למוצאי שבת או ליל שני בשבת והם שני ימים טובים אחר השבת ולא איירי כלל הש\"ס באיסור חפיפה שחרית וטבילה ערבית בלא הפסקת יום וכן לא איירי באיסור חפיפת לילה ואומר ר\"י דאם אירע טבילתה ליל תשעה באב אסורה לטבול דלית הלכתא כהך ברייתא דכל כתבי הקדש (שבת קיא.) דכל חייבי טבילות טובלין כדרכן בין בט' באב בין ביה\"כ אלא קי\"ל כרבי חנינא סגן הכהנים דאמר סוף פרק קמא דתענית (דף יג.) כדי הוא בית אלהינו לאבד עליו טבילה אחת בשנה ואומר עלה בירושלמי בפ\"ב דביצה אורי רבי לוי כהדא דרבי חנינא סגן הכהנים ועוד יש לפרש דההיא דכל כתבי בימי התנאים שהיו עסוקים בטהרות והיו צריכים ביום תשעה באב להתעסק בטהרות לפיכך טובלת מבערב אבל בזמן הזה דלבעלה דוקא אפשר לה לחוף ולטבול במוצאי תשעה באב ואם אין לה פנאי לרחוץ ולחוף בלילה תרחוץ ותחוף ערב תשעה באב כדי שיהיה בקל לה עדיין לחוף קצת מוצאי תשעה באב ולטבול:"]]],[["וכן תנא לוי במתניתא אחר הימים בין בדקה ומצאה טהורה בין בדקה ומצאה טמאה הרי זו ספק זבה","ומטמאה מעת לעת לימא תהוי תיובתא דרבא דאמר רבא לומר שאין האשה מטמאה מעת לעת בתוך ימי זיבתה","ולאו אותביניה לרבא חדא זימנא הכי קאמרינן לימא תהוי תיובתא דרבא נמי מהא","אמר לך רבא כי קתני מטמאה מעת לעת אריש פרקין קאי אראתה ועודה בבית אביה","סד\"א כיון דמפסקי להו ימים טהורין כתחלת נדתה דמיא ולא תטמא מעת לעת קמ\"ל","אם יש לה וסת נימא תהוי תיובתא דרב הונא בר חייא אמר שמואל דאמר רב הונא בר חייא אמר שמואל לומר שאין האשה קובעת לה וסת בימי זיבתה","אמר לך רב הונא בר חייא כי אמרינן אין אשה קובעת לה וסת בימי זיבתה דלא בעיא תלתא זימני למיעקר דאמרינן דמיה מסולקין וכיון דדמיה מסולקין דיה שעתה","רבי יהודה אומר תניא אמרו לו לר' יהודה אלמלי ידיה מונחות בעיניה כל בין השמשות יפה אתה אומר","עכשיו אימר עם סלוק ידיה ראתה מה לי הפרישה בטהרה בז' מן המנחה ולמעלה מה לי הפרישה בטהרה בראשון","בראשון מי איכא למאן דאמר","אין והתניא אמר רבי שאלתי את רבי יוסי ור' שמעון כשהיו מהלכים בדרך נדה שבדקה עצמה יום ז' שחרית ומצאה טהורה ובין השמשות לא הפרישה ולאחר הימים בדקה ומצאה טמאה מהו","אמרו לו הרי זו בחזקת טהרה ששי חמישי רביעי שלישי שני מאי א\"ל לא שנא","בראשון לא שאלתי וטעיתי שלא שאלתי אטו כולהו לאו בחזקת טומאה קיימי וכיון דפסק פסק ראשון נמי כיון דפסק פסק","ומעיקרא מאי סבר הואיל והוחזק מעין פתוח","\u0001מתני׳\u0002 הזב והזבה שבדקו עצמן ביום ראשון ומצאו טהור וביום השביעי ומצאו טהור ושאר ימים שבינתיים לא בדקו רבי אליעזר אומר הרי הן בחזקת טהרה ר' יהושע אומר אין להם אלא יום ראשון ויום שביעי בלבד ר' עקיבא אומר אין להם אלא יום ז' בלבד","\u0001גמ׳\u0002 תניא אמר לו רבי אליעזר לר' יהושע לדבריך אתה מונה בסירוגין והתורה אמרה (ויקרא טו, כח) אחר תטהר אחר אחר לכולן שלא תהא טומאה מפסקת ביניהן","אמר לו רבי יהושע ואתה אי אתה מודה בזב שראה קרי ובנזיר שהילך סככות ופרעות שמונה בסירוגין והתורה אמרה (במדבר ו, יב) והימים הראשונים יפלו","ורבי אליעזר בשלמא התם (ויקרא טו, לב) לטמאה בה אמר רחמנא שאינה סותרת אלא יומה ואי משום איחלופי זב בבעל קרי לא מיחלף","נזיר שהילך על גבי סככות ופרעות נמי מדאורייתא אהל מעליא בעינן ורבנן הוא דגזור ורבנן בדאורייתא לא מיחלף","אבל הכא אי חיישינן דלמא חזאי בספק אתי לאיחלופי בודאי","תני ר' יוסי ור' שמעון אמרי נראין דברי רבי אליעזר מדברי רבי יהושע ודברי רבי עקיבא מדברי כולן אבל הלכה כרבי אליעזר","איבעיא להו הזב והזבה שבדקו עצמן יום ראשון ויום שמיני ומצאו טהור ושאר הימים לא בדקו"],[[0,"וכן תנא לוי במתניתא","אסיפא דמתני' תני הכי בדקה ז' שחרית ומצאה טמאה ובין השמשות לא הפרישה ואחר הימים בין בדקה ומצאה טהורה בין בדקה ומצאה טמאה הרי זו ספק זבה:"],[1,"לומר שאינה מטמאה מעת לעת","בפ' בנות כותים (לעיל נדה לט.) קתני כל אחד עשר בחזקת טהרה ואמרינן למאי הלכתא ואמר רבא לומר שאם תראה בתוך י\"א אינה מטמאה מעת לעת ומתניתין קתני מטמאה מעת לעת ארישא דקתני אחר הימים בדקה ומצאה טמאה ומתמה הש\"ס ולאו אותביניה בפ' בנות כותים (שם) ולא איפרוק:"],[3,"","כי קתני ומטמאה מעת לעת:"],[3,"אריש פירקין קאי ראתה ועודה בבית אביה","ב\"ה אומרים כל הלילה שלה וקאמר דאם ראתה לאחר מכאן מטמאה מעת לעת:"],[4,"כתחלת נדה","כבתולת דמים דקי\"ל (לעיל נדה דף ז.) דיה שעתה בראייה ראשונה:"],[5,"ואם יש לה וסת","קא סלקא דעתך אסיפא דמתני' קאי דקתני אחר הימים בדקה ומצאה טמאה מטמאה מעת לעת ואם יש לה וסת קבוע לאחר הימים דהיינו ימי זיבה וראתה בו דיה שעתה:"],[5,"לומר שאינה קובעת","בפ' בנות כותים גבי כל י\"א בחזקת טהרה:"],[6,"אמר לך שמואל","כי אמרי אנא לקולא דלא בעינן תלת זימני למיעקריה דהא קתני כל י\"א בחזקת טהרה דהיינו קולא דדמיה מסולקין אבל לענין דיה שעתה כל שכן דהוי וסת דהא דמיה מסולקין:"],[8,"עם סילוק ידיה ראתה","ואפילו הכי אמרת טהורה הלכך מה לי הפסיקה בטהרה בראשון כו':"],[9,"מי איכא למאן דאמר כו'","והא אפילו רבנן בתראי בשני שלה הוא דקאמרי אבל בראשון דהוי פתיחת מעיינה ליכא למאן דאמר דאם בדקה בצהרים ומצאה טהור דתהוי הפרשה:"],[12,"וטעיתי שלא שאלתי","שאילו שאלתי היו מטהרין:"],[13,"מעיקרא מאי סבר","שלא רצה לשאול:"],[14,"מתני' הזב והזבה","שפסקו והתחילו לספור ז' ובדקו יום ראשון ושביעי כו':"],[14,"רבי עקיבא אומר אין להם אלא שביעי","שמא ראו בינתיים וסתרו ספירתן הראשונה:"],[16,"גמ' אי אתה מודה בזב שראה קרי","בימי ספירו שאינו מונה אותו יום דקיימא לן דסותר יום א' ומונה לסירוגין:"],[16,"ונזיר שהילך סככות ופרעות","שהן ספק אהל אין אותו יום עולה למנין נזירותו ונמצא שמונה ל' יום של סתם נזירות בסירוגין:"],[17,"התם","זב שראה קרי:"],[17,"לטמאה בה כתיב","זאת תורת הזב ואשר תצא ממנו שכבת זרע וגו' (ויקרא טו) מה זיבה סותרת אף קרי סותר אי מה זיבה סותרת הכל אף קרי סותר הכל ת\"ל לטמאה בה אין לך סתירה אלא בטומאתה האמור בה מה טומאת קרי יום אחד אף סתירתה יום אחד:"],[17,"ואי משום איחלופי","דלא ליתי למנות לסירוגין בזיבה גמורה:"],[18,"אהל מעליא בעינן","אין נזיר מטמא אלא באהל מת ודאי כדכתיב (במדבר ו׳:ט׳) וכי ימות מת עליו במחוורת עליו כדאמר בכיצד צולין (פסחים פא:):"],[18,"ורבנן גזור ביה","לסתור אותו יום. וא\"ת אתי לאיחלופי באהל מת גמור ולא יסתור אלא יום א':"],[18,"דרבנן בדאורייתא","אהל ספק דרבנן באהל דאורייתא לא מיחלף:"],[19,"אבל הכא אי חיישינן","ולא תמנה יום שבינתיים משום דלמא חזאי בספק אתי למיחלף בודאי דאמרינן מדלא מנינן הני ימים ודאי חזאי בינתיים וקא מניא לראשון ואתיא למנות ודאי רואה בסירוגין:"],[20,"נראין דברי ר\"א מדברי רבי יהושע","דכיון דחייש רבי יהושע לשמא ראה בינתיים היה לו לסתור אף הראשון:"],[20,"ודברי ר\"ע מדברי כולן","דבעי ספורין ובדוקין:"],[21,"יום שמיני","כבר עברו ימי הספירה ולא היה סופן בטהרה דלא בדקה יום ז':"]],[[11,"","אמרו ליה הרי זו בחזקת טהרה. וא\"ת תקשה דרבי יוסי דהכא דקאמר דסגי לה בהפרשה שחרית אדרבי יוסי דפרק בא סימן (לעיל נדה דף נג.) דקאמר ומה אילו נדה שלא הפרישה בטהרה מן המנחה ולמעלה לא תהא בחזקת טומאה אלמא בעי הפרשה מן המנחה ולמעלה ויש לומר דהתם מיירי כשהפרישה ביום שראתה בו שחרית והכא מיירי בבדקה שחרית ומצאה טהורה וקשה דאם כן כי פרכינן לרבי יהודה אילו ידיה בעיניה כל בין השמשות וכו' לימא ר' יוסי לנפשיה דהא איהו נמי מצריך הפרשה מן המנחה ולמעלה כשהפרישה ביום שראתה ומה מועיל עיכוב זה שמא עם סילוק ידיה ראתה וי\"ל דלנפשיה לא קשה דכיון דהוחזקה רואה שחרית דין הוא להצריכה הפרשה מן המנחה ולמעלה בלא חומרא אלא מן הדין ואין לנו להחמיר ולספק שמא עם סילוק ידיה ראתה להצריכה בדיקה בסוף היום אבל רבי יהודה שבא להחמיר ולספק דאפילו בשלא ראתה שחרית אלא בבדקה עצמה ומצאה טהורה הוא מצריך הפרשה גם בסוף היום היה לו להחמיר ולבדוק מספק שמא עם סילוק ידיה ראתה:"],[20,"","אבל הלכה כרבי אליעזר. אע\"ג דאין למדין הלכה מפי הש\"ס הא פסקינן בפ\"ק לעיל (נדה דף ז:) כרבי אליעזר בארבע והא חד מינייהו:"]]],[["לרבי אליעזר מהו תחלתן וסופן בעינן והכא תחלתן איכא סופן ליכא או דילמא תחלתן אף על גב שאין סופן","אמר רב היא היא תחלתן אע\"פ שאין סופן ורבי חנינא אמר תחלתן וסופן בעינן הכא תחלתן איכא סופן ליכא","מיתיבי ושוין בזב ובזבה שבדקו עצמן יום ראשון ויום שמיני ומצאו טהור שאין להם אלא שמיני בלבד מאן שוין לאו רבי אליעזר ורבי יהושע","לא ר' יהושע ור' עקיבא","אמר רב ששת אמר רב ירמיה בר אבא אמר רב נדה שהפרישה בטהרה בשלישי שלה סופרתו למנין שבעה נקיים","נדה ספירה למה לה אלא אימא זבה שהפרישה בטהרה בשלישי שלה סופרתו למנין ז' נקיים","אמר ליה רב ששת לרב ירמיה בר אבא רב ככותאי אמרה לשמעתיה דאמרי יום שפוסקת בו סופרתו למנין ז'","כי קאמר רב לבר משלישי בר משלישי פשיטא לא צריכא כגון דלא בדקה עד שביעי","ואשמועינן התם תחלתן אע\"פ שאין סופן והכא קמ\"ל סופן אע\"פ שאין תחלתן","דמהו דתימא תחלתן אף על פי שאין סופן הוא דאמרינן דאוקמינהו אחזקייהו אבל סופן אע\"פ שאין תחלתן לא קמ\"ל","איני והא כי אתא רבין אמר מתיב ר' יוסי ברבי חנינא טועה","ולא ידענא מאי תיובתיה דקי\"ל שבוע קמא דאתיא לקמן בלילותא מטבלינן לה ביממא לא מטבלינן לה","ואי ס\"ד לא בעינן ספורין לפנינו ביממא נמי נטבלינה דילמא יולדת זכר בזוב היא ועבדה לה ספורין אלא לאו שמע מינה בעינן ספורין בפנינו","ולאו מי אוקימנא כר\"ע דאמר בעינן ספורין לפנינו","ומנא תימרא דלרבנן לא בעינן ספורין לפנינו דתנן טועה שאמרה יום אחד טמא ראיתי מטבילין אותה ט' טבילות","ז' לנדה ותרי לזיבה בין השמשות טמא ראיתי מטבילין אותה י\"א טבילות","י\"א מאי עבידתייהו אמר רב ירמיה מדפתי כגון שבאת לפנינו בין השמשות","והויין תמני לנדה ותלת לזיבה","לא ראיתי כל עיקר מטבילין אותה ט\"ו טבילות אמר רבא האי דינא דלא דינא דייני בגלחי דאית ליה תורא לירעי חד יומא דלית ליה תורא לירעי תרי יומי","אתרמי להו יתמא בר ארמלתא יהבי ליה תורי אזל נכסינהו אמר להו דאית ליה תורא לשקול חד משכא דלית ליה תורא לשקול תרי משכי אמרי ליה מאי האי דקאמרת אמר להו סוף דינא כתחלת דינא תחלת דינא לאו מאן דלית ליה עדיף סוף דינא נמי מאן דלית ליה עדיף","הכא נמי ומה היכא דאמרה ראיתי סגי לה אי בתשע טבילות אי בי\"א טבילות היכא דקאמרה איהי לא ראיתי בעיא חמש עשרה טבילות","אלא אימא הכי ראיתי ואיני יודע כמה ראיתי אי בימי נדה ראיתי או בימי זיבה ראיתי מטבילין אותה ט\"ו טבילות אתאי קמן ביממא יהבינן לה שב לנדה"],[[0,"לרבי אליעזר","דמכשר בבדיקת שביעי עם הראשון:"],[0,"מהו","דלרבי יהושע ודאי אין להם אלא שמיני בלבד דאף ע\"ג דתליא מילתיה בבדיקה ומונה ימים הבדוקין אפילו בסירוגין הני מילי בראשון ושביעי דחזו לאיצטרופי לחד מנינא אבל שמיני לאו מסדר ספירת הראשון הוא ולא מצטרף ולר' עקיבא נמי אין לו אלא שמיני בלבד שמא ראה בינתים ומכאן ואילך צריך לספור ששה אלא לרבי אליעזר מי מחזקינן כל ז' בטהרה משום בדיקת ראשון דהוו תחלתן בטהרה או לא:"],[1,"היא היא","טהורין:"],[2,"לאו רבי אליעזר ורבי יהושע","דאע\"ג דפליגי עליה דרבי עקיבא בראשון ושביעי הכא מודו:"],[3,"לא רבי יהושע ורבי עקיבא","כדפרישית אבל לרבי אליעזר הואיל ותחלתן בטהרה מחזקינן לכולהו בטהרה:"],[6,"ככותאי אמרה לשמעתיה","בפרק בנות כותים (לעיל נדה דף לג.):"],[7,"דלא בדקה עד שביעי","דלא הוי תחילת ימי ספירה בטהרה דלא בדקה בראשון משהפרישה בבין השמשות של שלישי לזיבה שראתה בו ביום עד ז' לספירה ותרי קולי אשמועי' רב בספירה:"],[8,"התם","דאמר רב לעיל דמטהר רבי אליעזר בבודק ראשון ושמיני אשמועינן תחלתן אע\"פ שאין סופן:"],[8,"והכא אשמועינן סופן אע\"פ שאין תחלתן","דמשום בדיקת ז' מחזקינן כל ששה לפניו בטהרה הואיל ופסקה בשלישי. ומיהו הפרשה בטהרה בעינן דמשהוחזק מעין פתוח ליכא לאחזוקי בטהרה עד שתבדוק ותמצא שפסק כדאמרינן במתני' דהפרשה בטהרה בעינן:"],[10,"איני","לרב פריך דלא בעי ספורין ובודקין ודאי וקיימא לן בהמפלת (לעיל נדה דף כט:) דשבוע קמא בלילותא מטבלינן לה כל ליליא דילמא השתא שלמו שבעה של טומאת זכר ביממא לא מטבילין לה לספוקה ביולדת בזוב ולמימר בכל יומא היום כלין ז' נקיים שאחר טומאת לידה ומשום הכי לא מטבילין לה דאי נמי מתרמי האידנא ז' של נקיים משום דטבילה בזמנה מצוה ונדה ויולדת טבילתן בלילה וזבה טבילתה ביום לא הויא ספירה הואיל ולא ספרה בפנינו עד שתשב בפנינו שבוע טהור:"],[14,"יום אחד טמא ראיתי","ואיני יודע אימתי ואפילו היום י\"ל זהו ואינה יודעת אם יום ראייתה בימי נדה אם בימי זבה מטבילין אותה משום טבילה בזמנה מצוה:"],[14,"תשע טבילות ז' לנדה ותרתי לזיבה","וכגון דאתאי לקמן ביממא ומטבילין אותה הלילה שמא נדה היא והלילה כלו ז' ימי נדה וכן לליל יום ז' וכן כל ליל שבוע זה וטפי לא איכא לספוקי ותרתי לזיבה ביממא ביומא דאתאי לקמן מטבילין לה דלמא אתמול חזאי וימי זיבה הוו והואי שומרת יום כנגד יום ולמחר נמי טבלה דילמא ביומא דאתאי לקמן הוא דחזאי וטפי ליכא לספוקי. אבל אתיא לקמן בליליא איכא י' טבילות ח' לנדה וב' לזיבה דההוא ליליא גופיה איכא לספוקי השתא זמן טבילתה וכן כל לילות שבוע זה ולמוצאי שביעי נמי טבלה משום דילמא בליליא דאתאי קמן חזאי והשתא הואי זמן טבילה. והאי דלא קא תני י' טבילות משום מילתא דלא פסיקא היא דהא כי אתיא ביממא ליכא אלא ט' אבל ט' פסיקא ליה דבציר מהכי ליכא והכי מוקי לקמן:"],[16,"מאי עבידתייהו","אם באתה ביום או בלילה ואומרת בין השמשות טמא ראיתי אין כאן טבילה יתירתא דהא כי אמרה נמי יום טמא ראיתי ואיני יודע מתי אם בימי נדה ואם בימי זיבה מספקי ליה דילמא האידנא ביום שבאת לפנינו חזאי:"],[17,"תמני לנדה","כגון באת לפנינו בין השמשות של ערב שבת טובלת מיד בלילי שבת שמא השתא זמן טבילתה וכן כל שבוע זה ולילי שבת הבאה שמא בין השמשות שבאת לפנינו ראתה ולילה היא ומשכה ז' ימי נדה עד עכשיו ולפי שיום שבת היה תחלת נדתה הרי ח' טבילות לנדה ותלת לזבה דמטבילין לה בין השמשות דאתאי לקמן דילמא בין השמשות דאתמול חזאי ומיום ה' בשבת היה ושמרה ערב שבת כנגד יום ה' וטובלת בין השמשות עד שלא תחשך דשמא עדיין יום הוא וראוי לטבילת זוב ולמחר בשבת נמי טבלה שמא בין השמשות דאתמול כשבאת לפנינו ראתה ומיום ששי היה והיום טובלת ליום כנגד יום ובאחד בשבת נמי טבלה משום ספק ההוא בין השמשות גופיה שמא לילה הוא כשראתה ובאת לפנינו ובכל יום השבת הוי ראשון וא' בשבת הוי שימור וטבלה:"],[18,"האי דינא דלא דינא דייני בגלחי","דין זה שאינו דין היו דנין באותו מקום:"],[18,"לירעי חד יומא","כל בהמות העיר:"],[19,"אזל יתמא","שלא היה לו שור וכפאוהו לרעות בהמותיהן ב' ימים:"],[19,"נכסינהו","שחטן:"],[21,"כמה ראיתי","אם א' אם ג':"],[21,"שב לנדה","באתה בשבת טובלת למוצאי שבת שמא באחד בשבת ראתה תחלה וכן עד לילי שבת הבאה ולילי שבת בכלל שמא בשבת שבאת לפנינו ראתה ואותו היום לבד ראתה:"]],[[8,"","והכא קמ\"ל סופן אע\"פ שאין תחלתן. ואם תאמר (א\"כ) לרב כל זבה צריכה הפרשה ביום שפוסקת בו כמו נדה ואמאי קתני במתני' שבדקה עצמה יום ראשון הא כבר בדקה עצמה מאתמול והפרישה בטהרה ואי הוה אומר ד' לא בעינן הפרשה ביום ג' הוה ניחא וי\"ל דליכא למידק הכי דאפי' אי סגי בהפרשת שלישי לרבי אליעזר לא סגי דלא תני שבדקה ביום ראשון משום פלוגתא דרבי יהושע ורבי עקיבא כמו ראשון ושמיני דקאמר רב לרבי אליעזר היא היא ולא תני במתני' אע\"ג דלר' אליעזר הוי רבותא טפי משום דלא מיתני ליה תו פלוגתא דר' יהושע ור' עקיבא:"],[15,"","שבעה לנדה ושנים לזיבה. מכאן אין יכול לדקדק דלא בעינן ספורים בפנינו מדטובלת אע\"פ שלא הפסיקה בטהרה ולא בדקה נמי בתחלת ספורים דאע\"ג דלא בעינן ספורים בפנינו בזבה קטנה בזבה גדולה בעינן ועוד דסוף סוף סגי לה במה שבדקה ביום הספירה ומצאה טהורה דאי אין בדיקת סוף היום עולה לספירה לא היה תקנה לבנות ישראל אלא אם כן יבדקו בעליית עמוד השחר דספירת לילה אינה ספירה:"]]],[["ותמני לזיבה אתאי קמן בלילותא יהבינן לה תמני לנדה ושב לזיבה","זיבה תמני בעיא אלא אידי ואידי שב לנדה ותמני לזיבה","בלילותא תמני לנדה בעי","זיבה דפסיקא ליה דלא שנא כי אתיא קמן ביממא לא שנא כי אתיא קמן בליליא חשיב לה נדה דלא פסיקא ליה דכי אתיא קמן בלילותא בעי תמני ביממא לא קבעי תמני לא קחשיב לה","ואי ס\"ד ספורין לפנינו בעינן כל הני טבילות למה לי תספור ז' והדר תטבול אלא לאו שמע מינה רבנן היא דאמרי לא בעינן ספורין לפנינו","אמר ליה רב אחא בריה דרב יוסף לרב אשי לאו תרוצי קמתרצינן לה תריץ ואימא הכי ספרתי ואיני יודעת כמה ספרתי אם בימי נדה ספרתי ואם בימי זיבה ספרתי מטבילין אותה ט\"ו טבילות","ספרתי ואיני יודעת כמה ספרתי חד יומא מיהא אי אפשר דלא ספרה חסרה לה טבילה","אלא אימא איני יודעת אם ספרתי אם לא ספרתי","\u0001מתני׳\u0002 הזב והזבה והנדה והיולדת והמצורע שמתו מטמאין במשא עד שימוק הבשר עובד כוכבים שמת טהור מלטמא","בית שמאי אומרים כל הנשים מתות נדות וב\"ה אומרים אין נדה אלא שמתה נדה","\u0001גמ׳\u0002 מאי במשא אילימא במשא ממש אטו כל מת מי לא מטמא במשא","אלא מאי במשא באבן מסמא","דכתיב (דניאל ו, יח) והיתית אבן חדא ושומת על פום גובא","מאי טעמא אמר רב גזרה שמא יתעלפה","תנא משום ר' אליעזר אמרו עד שיבקע כריסו","עובד כוכבים שמת [כו'] תניא אמר רבי מפני מה אמרו עובד כוכבים שמת טהור מלטמא במשא לפי שאין טומאתו מחיים מדברי תורה אלא מדברי סופרים","ת\"ר שנים עשר דברים שאלו אנשי אלכסנדריא את רבי יהושע בן חיננא ג' דברי חכמה ג' דברי הגדה ג' דברי בורות ג' דברי דרך ארץ","ג' דברי חכמה הזב והזבה והנדה והיולדת והמצורע שמתו עד מתי מטמאין במשא אמר להן עד שימוק הבשר","בת משולחת מה היא לכהן","מי אמרינן קל וחומר ומה אלמנה לכ\"ג שאין איסורה שוה בכל בנה פגום זו שאיסורה שוה בכל אינו דין שבנה פגום או דילמא מה לאלמנה לכהן גדול שהיא עצמה מתחללת","אמר להן"],[[0,"ותמני לזיבה","בשבת גופה אתאי מטבילין לה שמא שלשה ימים ראתה בימות זוב והיום כלין ספורין וכן למחר וכן ביום שבת הבאה יש לומר ביום שבאתה לפנינו ראתה והוא שלישי לזיבה והיום כלו ספורין שלה:"],[0,"בלילותא","אם באת לפנינו בלילה תמני לנדה באת בלילי שבת טובלת מיד שמא הלילה כלו ימי נדה וכן כל לילות שבוע זה ולילי יום שבת הבא משום דשמא בליל שבאת לפנינו ראתה הרי ח':"],[0,"ושב לזיבה","לאו מילתא היא דהא פרכינן זבה תמני הויין דהא למחר בשבת טבלה ויום שבת הבא נמי טבלה שמא בלילי שבת כשבאת לפנינו ראתה והוא שלישי לזיבתה והיום כלין ימי הספירה:"],[1,"אידי ואידי","בין באת לפנינו ביום בין באת לפנינו בלילה. וקא פריך נדה בלילותא כו' כלומר כשבאת לפנינו בלילה איכא טבילה יתירתא שטובלת מיד משום נדה. ומהדר ומשום זיבה דפסיקא ליה טבילה ספק זיבה דפסיקא ליה דתמני נינהו לעולם חשיב להו כתמני:"],[4,"למה לי","כל הני טבילות. אטבילות דיממי דזיבה קא פריך לספור שבעה קמן ולטבלה בשביעי ומקמי הכי לא דאפילו שלמי נקיים דילה לאו בת טבילה היא הואיל ולא בדקה:"],[4,"אלא לאו ש\"מ רבנן היא","דפליגי עליה דרבי עקיבא ורבי דאמר לא בעינן ספורין לפנינו כרבנן סבירא ליה:"],[5,"ספרתי","בדקתי קצת נקיים או כולן ואיני יודעת כמה או שמא נקיים שראיתי לאו אחר ימי הזוב היו אלא לאחר ימי נדות מטבילין אותה ט\"ו טבילות שמא עכשיו כלין וכדפרישית:"],[6,"חד יומא מיהא אי אפשר דלא ספרה","וליכא לספוקה ברואה יום שבאת לפנינו ובצרי להו טבילות דשביעי:"],[7,"אימא איני יודעת אם ספרתי אם לא ספרתי","הלכך אפילו יומא קמא טבלה דלמא כל ז' שלפנינו ספרה ובדקה דהא קאמרה שמא ספרתי ויום ז' נמי טבלה שמא לא ספרה קודם לכן:"],[8,"מתני' מטמאין במשא","בגמרא פריך כל מת נמי מטמא במשא ומשנינן באבן מסמא דשאר מתים לא מטמו הכא מטמו מדרבנן הואיל ומחיים מטמו באבן מסמא מדאורייתא שהרי מטמאין מושב כל שתחתיהם גזור בהו רבנן לאחר מיתה כדמפרש טעמא בגמרא גזרה שמא יתעלפה:"],[8,"עד שימוק הבשר","דמהשתא הוי מת ודאי:"],[8,"עובד כוכבים שמת","אע\"ג דמחיים הרי הוא כזב לכל דבריו ולטמא באבן מסמא משמת טהור מלטמא באבן מסמא כדמפרש בגמרא הואיל וטומאת זיבה שעליו מחיים אינה אלא מדברי סופרים:"],[9,"כל הנשים","מחזקינן להו כנדות ומטבילין כלים שהיו עליהן סמוך ליציאת נשמה וטעמא מפרש בגמרא:"],[12,"גמ' כדכתיב והיתית אבן חדא ושומת על פום גובא","לשון מסמא קא מפרש דהיינו אבן כבדה העשויה להינוח ואינה מטלטלת הלכך כשהיא על גבי כלים ומת נתון עליה אין זה משא הואיל ואינה ראויה להטלטל עמו:"],[13,"מאי טעמא","גזור רבנן בזב וזבה לטמא אף לאחר מיתה באבן מסמא:"],[13,"גזרה שמא יתעלפה","פאשמיי\"ר ודומה למת ואי אמרת זב מת לא מטמא בזב חי אתי נמי לטהורי כי האי:"],[16,"דברי חכמה","הלכה:"],[16,"דברי בורות","שטות:"],[18,"בת משולחת","ישראל שהחזיר גרושתו משניסת לאחר והוליד בת:"],[19,"","אלמנה אינה אסורה אלא לכ\"ג:"],[19,"בנה פגום","חלל דכתיב (ויקרא כ״א:ט״ו) לא יחלל זרעו:"],[19,"זו שאיסורה שוה בכל","בישראל ובכהנים אסור להחזיר גרושתו משניסת:"],[19,"היא עצמה","משניסת לכהן גדול מתחללת שאם מת אסורה להנשא להדיוט ואם היתה כהנת נפסלת מן התרומה בביאתו דכתיב לא יחלל זרעו בעמיו ועמיו זו אשתו:"]],[[19,"","מה לאלמנה לכהן גדול שכן היא עצמה מתחללת תאמר במחזיר גרושתו שאינה מתחללת. פי' מן התרומה לפירוש רש\"י דכי תהיה לאיש זר דמיניה ילפינן (יבמות דף סח.) כיון שנבעלה לפסול לה פסלה מן הכהונה איירי באלמנה לכ\"ג דלא מיירי במחזיר גרושתו דלאו זר מעיקרא הוא אצלה מיהו קשה דנהי דלא מצינן למילף מהאי קרא מ\"מ תתחלל מהאי קל וחומר גופיה וכן בפ' החולץ (יבמות דף מד.) דיליף לר' יהושע דחייבי כריתות בנה פגום מהאי קל וחומר דאלמנה לכ\"ג ופריך כי הכא לימא היא עצמה מתחללת מק\"ו ותאסר אף מתרומה וי\"ל כיון דאין חלל אלא מאיסור כהונה ליכא למילף בעלמא לפסול האשה עצמה מאיסור כהונה דלהכי אייתר התם חללה למימר דאין חללה אלא מאיסור כהונה דהיינו פסול האשה שהיתה כשרה ונתחללה ואף ע\"ג דגר עמוני ומואבי פוסלין אע\"ג דלא הוו איסור כהונה התם מקרא דרשינן ליה אבל מק\"ו ליכא למילף ומיהו קשה נילף מאלמנה לכה\"ג ומעובד כוכבים ועבד אי נמי מחלל ועובד כוכבים ועבד או גר עמוני ומצרי ואדומי במה הצד דהיא עצמה מתחללת דכי פרכינן מה לאלמנה לכ\"ג או לחלל שכן איסור כהונה איכא למימר עובד כוכבים ועבד יוכיחו דלאו איסור כהונה ופוסלין בביאתם מה לעובד כוכבים ועבד שכן אסורין לבא בקהל או דלא תפסי בהו קדושין אלמנה לכ\"ג או חלל יוכיחו הצד השוה שבהן שאינם ברוב הקהל ופוסלין בביאתן אף מחזיר גרושתו יפסלנה בביאתו והכי מייתי ר' יהודה דגר פוסל בביאתו בפ' בתרא דקדושין (דף עח.) במה הצד דאיסור כהונה ומילתא אחריתי בהדה דהיינו מחלל ומצרי ראשון וכן נמי תקשה אמאי מצריך בפ' אלמנה לכה\"ג (יבמות דף סח.) קרא דוכי תהיה לאיש זר לגר עמוני ומואבי דפוסלין בביאתם נילף במה הצד מחלל ועובד כוכבים ועבד כדפירשתי ויש לומר כיון דבעובד כוכבים ועבד הולד ממזר ליכא למילף תו מינייהו פסול ביאה כיון דחמירי כולי האי דוולדן ממזר דדוקא רבי יהודה יליף בקדושין (שם) דגר פוסל בביאתו ממצרי ראשון אף על גב דבתו פסולה לבא בקהל אבל רבנן פליגי עליה דלית להו הך סברא ומתוך האי שינויא מתרצא נמי קושיא אחריתי בפרק הערל (יבמות דף עז.) דקאמר עמוני שנשא בת ישראל בתו כשרה לכהונה ופריך ונימא דפסול במה הצד דאלמנה לכה\"ג וחלל ומשני דאיכא למפרך מה להצד השוה שבהן שכן יש בהן צד עבירה ואמאי לא קאמר מצרי ראשון יוכיח דהכי יליף בקדושין (דף עח.) לר' יהודה אלא כיון דבתו פסולה לא ילפינן מיניה פסול ביאה אלא דוקא לר' יהודה וא\"ת למאן דאמר (יבמות דף מה.) עובד כוכבים ועבד הבא על בת ישראל הולד כשר אם כן נילף דהיא עצמה מתחללת כדפי' ויש לומר דלא ילפינן מאיסור כהונה ומילתא אחריתי בהדה אלא לר' יהודה דוקא כדאשכחן בקדושין אבל לרבנן לית להו הך סברא:"]]],[["היא תועבה ואין בניה תועבין","שני מצורעין שנתערבו קרבנותיהן זה בזה וקרב קרבנו של אחד מהן ומת אחד מהן השני מה תהא עליו","אמר להן כותב נכסיו לאחרים והוי עני ומביא חטאת העוף הבא על הספק","והאיכא אשם אמר שמואל כשקרב אשמו","אמר רב ששת גברא רבה כשמואל לימא כי האי מילתא כמאן אי כר' יהודה דאמר אשם קבעה וכיון דקבעה לה אשם בעשירות לא מצי מייתי חטאת בדלות","דתנן מצורע שהביא קרבן עני והעשיר או עשיר והעני הכל הולך אחר חטאת דברי ר' שמעון","ורבי יהודה אומר הכל הולך אחר אשם רבי אליעזר בן יעקב אומר הכל הולך אחר צפורים","ואי כרבי שמעון דאמר חטאת קבעה אע\"ג דלא קרב אשם ניתי אחר דהא שמעינן ליה לרבי שמעון דאמר לייתי ולתני","דתניא אמר ר\"ש למחרת מביא אשמו ולוגו עמו ומעמידו בשער נקנור ומתנה עליו ואומר אם מצורע הוא הרי אשמו ולוגו עמו ואם לאו אשם זה יהא שלמי נדבה","ואותו אשם טעון"],[[0,"היא תועבה","במחזיר גרושתו כתיב (דברים כד) כי תועבה היא:"],[1,"השני מה תהא עליו","היאך יטהר לקדשים שאילו היה מצורע חבירו חי אע\"פ שנתערבו קרבנותיהם זה יקרב לשם מי הוא וזה יקרב לשם מי שהוא או אם מת האחד והיו שני הקרבנות בפנינו היו הקרבנות מתים וזה מקריב קרבן אחר אבל עכשיו אינו יכול להקריב את זה שמא של מת הוא והוי חטאת שמתו בעליה וקרבן אחר נמי אינו יכול להביא שמא אותו שקרב היה שלו ונפטר ונמצא מביא חולין לעזרה ואינו יכול להתנות בנדבה שאין חטאת באה נדבה ואפי' לרבי שמעון דאמר לקמן אשם קרב מספק על תנאי אם הוא חייב אשם הרי זה לאשם ואם לאו הרי זה שלמי נדבה הני מילי אשם שמתן דמו דומה לשלמים אבל חטאת שאין מתן דמה דומה לשלמים אינו יכול להתנות ולומר אם קרבה חטאתי הרי חטאת זו שלמי נדבה דמתן דמה היכי ליעביד ליעביד ארבעה מתנות ולמעלה מחוט הסיקרא שמא שלמי נדבה נינהו ואם שתי מתנות ולמטה מחוט הסיקרא שמא חטאת הוא:"],[2,"והוי ליה עני","וראוי להביא בדלות וחטאת העוף באה בספק ואין שם משום מביא חולין בעזרה:"],[3,"והא איכא אשם","ששוה בעשיר ובעני והיאך הוא מביא אשם מספק דלמא מייתי חולין בעזרה:"],[3,"אמר שמואל","הך תקנתא דרבי יהושע כשהביא את אשמו קודם מיתת חבירו אבל אם לא קרב אין לו תקנה:"],[4,"אי כרבי יהודה","דאמר אין אשם בא על תנאי ומשום הכי ליכא תקנתא באשם:"],[4,"הא אמר אשם קבע","ואם קרב את אשמו לית ליה תקנתא בחטאת דאשם שהביא בעשירות קבע את שאר קרבנותיו בעשירות ואין יכול להביא את חטאתו עני:"],[5,"מצורע שהביא","אחד מקרבנותיו:"],[5,"והעשיר","עד שלא הספיק להביא את כולו או עשיר והעני:"],[5,"הכל הולך אחר חטאת","אם הביא חטאת בדלות מקריב נמי עולתו בדלות ואם בעשירות מקריב נמי עולה בעשירות:"],[6,"אחר אשם","אם כשהקריב אשמו היה עשיר יקריב את האחרים בעשירות:"],[6,"אחר צפורים","שתי צפרים חיות טהורות שהיה כהן מטהר בהם את המצורע שבעה ימים קודם תגלחתו ולאו קרבן הן ושוות בעשיר ובעני ואם באותה שעה היה עשיר מביא כל קרבנותיו בעשירות. וטעמא דכולהו מפרש בכריתות אשר לא תשיג ידו בטהרתו רבי שמעון סבר טהרתו דבר המכפרו ורבי יהודה סבר דבר המכשירו והיינו אשם שממנו נותן על הבהונות ורבי אליעזר סבר דבר הגורם לו טהרה ומאי נינהו צפורין:"],[7,"ואי כרבי שמעון","דאמר אשם לא קבע והלכך אפילו הקריב את אשמו כשהוא עשיר יכול להביא חטאת עני למה ליה לשמואל לאוקמי כשקרב אשמו כשהוא עשיר יכול להביא חטאת עני אפילו לא קרב נמי איכא תקנתא באשם לאתויי אשם מביתו ולומר אם קרבן שקרב של חבירי הרי זה שלי ואם שלי היה הרי זה לשלמים:"],[8,"למחרת","בספק מצורע קאי וקאמר למחר של טבילתו שהוא יום הבאת קרבנותיו מביא את אשמו כו':"]],[[0,"","היא תועבה ואין בניה תועבין. וא\"ת מה צריך והא פרכינן אקל וחומר דאלמנה לכהן גדול מה לאלמנה לכהן גדול שכן היא עצמה מתחללת וליכא למימר דלאו פירכא גמורה היא דהא על ידי הך פירכא הדר ביה בפ' החולץ (יבמות דף מד.) מהא דקאמר הכל מודים במחזיר גרושתו שהולד פגום מקל וחומר דאלמנה לכהן גדול ואומר אלא אי איתמר הכי איתמר ועוד קשה דבפ\"ק דיבמות (דף יד:) קאמר רבי יוחנן בן נורי כיצד נעשה כדברי ב\"ה שמתירין את הצרות לשוק בלא חליצה ויבום הולד פגום לדברי ב\"ש ומנלן דהוי פגום אי מקל וחומר דאלמנה לכהן גדול איכא למיפרך כי הכא וי\"ל אהך קושיא בתרייתא דנפקא לן הולד פגום בצרות לשוק מהיא תועבה ואין בניה תועבין מכלל דבעלמא אפילו בניה תועבין מיהו בשמעתא ליכא למימר דמשום הכי נקט האי קרא אע\"ג דלא צריך משום דאשמועינן דאיצטריך ליה ר' יהושע למדרש בעלמא כגון ביבמה לשוק דבניה תועבין דבשמעתין דיבמות אית ליה לר' יהושע דהולד של צרות כשר לשוק דקאמר בני צרות אני מעיד לכם וי\"ל אי לאו מיעוט דהיא הוה מפקינן דולד פגום משום דטומאה כתיב בה כעריות ואפי' למ\"ד דלא קאי טומאה אלא אסוטה דכיון דאיעקר איעקר מ\"מ לשון תועבה הוה אמינא דקאי נמי אבנים אי לאו היא א\"נ הא דמייתי הכא קרא דהיא תועבה. היינו משום דלא נילף מאלמנה לכהן גדול ומעבד ונכרי דתתחלל כר' יהודה דבפ' בתרא דקדושין (דף פח.):"],[1,"","ומת אחד מהן. תימה למאי דס\"ד דלא קרב אשמו וכדבעי רב ששת לאוקומי בלא מת נמי היינו יכולין לשאול היאך יקרב השני הלא אינם יודעין מי נפטר כבר מקרבן ולמי יעשו מתן בהונות מדם האשם שלא קרב וי\"ל יכולין לעשות לשניהם ואי משום סמיכה יקריבו בלא סמיכה משום תקוני גברא:"],[2,"","ומביא חטאת העוף הבא על הספק. וקשה דבגיטין פרק כל הגט (גיטין דף כח:) גבי השולח חטאתו ממדינת הים ואוקמיה רב פפא בחטאת העוף היכי קאמר בתר הכי וצריכי כו' אבל חטאת העוף מספקא לא לייתי חולין לעזרה והא אמרינן בשמעתין דבא על הספק וי\"ל דהכא כשהמצורע לפנינו משום תקוני גברא מקריבין אותו אספקא הואיל ואינו יכול לתקן בענין אחר אבל התם שהבעלים במדינת הים אם היה מת אין לו דין חטאת להיות קרב ואז לא יקריבוהו מספק:"],[5,"","דתנן מצורע שהביא קרבן עני וכו'. דתנן גרסי' ואע\"ג דדברי ר' אליעזר אינן שנויין במשנה לא חש להאריך ולומר תניא על דבריו הואיל ולא היה צריך לדבריו כ\"כ אלא לדברי ר\"ש ור\"י אבל בערכין פרק השג יד (ערכין דף יז:) קאמר תניא ר' אליעזר בן יעקב אומר כו' ושלשתן מקרא אחד דרשו:"],[8,"","למחרת מביא אשמו ולוגו עמו. פירש\"י בספק מצורע איירי למחרת טבילתו שהוא יום הבאת קרבנותיו והך ברייתא מייתי לה בזבחים פ' התערובת (זבחים דף עו.) ושם פי' רש\"י למחרת ביום שמיני לצרעתו וה\"נ מייתי לה במנחות פרק בתרא (דף קה.) ופי' רש\"י שם למחרת ביום ס\"א והכל אחד הוא שיום ס\"א במקום שמיני לצרעתו אלא שהוצרך להתאחר ס' יום משום דשמא נזיר טמא הוא ואז תגלחת שניה שלו והכי מתניא בתוספתא דנזיר ספק נזיר טמא ספק נזיר טהור אבל ודאי נזיר היה ספק מצורע טמא ספק מצורע טהור אבל ודאי מצורע היה פירוש הוא יודע שהיה נזיר אבל אינו יודע אם נטמא למת או לאו וכן יודע הוא שמצורע היה אבל אינו יודע אם נטמא בצרעתו אי לאו אוכל בקדשים לאחר ס\"א יום ושותה יין ומטמא למתים לאחר מאה וכ' יום כיצד אומרים לו נזיר טמא אתה וצריך אתה לעשות כל דין נזיר טמא ואחר תתחיל נזירות טהרה הזה ושנה וגלח והביא קרבן מנה ז' והזה ושנה ומבקש לגלח אומר לו טהור אתה ואין טהור מגלח פחות מל' יום פירוש שמא נזיר טהור אתה צא ומנה כ\"ג פירוש כדי להשלים ל' מנה ל' ובקש לגלח אומרים לו נזיר טהור אתה ואי אתה מגלח אלא על הדמים פירוש עד שיזרק הדם עליו מאחד מקרבנותיו שהוא מביא ג' בהמות חטאת עולה ושלמים ואין מעכב אותו מלגלח אלא אחד מהן כיצד הוא עושה מביא עולת בהמה ומתנה אם טהור הוא זו חובה ואם לאו נדבה וכשיזרוק דמה יכול לגלח פירוש לכך יתנה מן העולה ולא מן החטאת שאין חטאת בהמה באה על הספק וכן לא על השלמים ששלמי נזיר טעונים תנופה וזהו ספק מצורע ואינו יכול להניף ועוד שהן טעונין לחם וזרוע בשלה ואין שלמים כאלו באין נדבה הילכך אין יכול להתנות שיהיה מוכשר לגלח אלא בזריקת דמי העולה כיצד יעשה להחמיר עליו מביא פיילי חרס חדשה ונותן לתוכה רביעית מים חיים ומביא צפור דרור פירוש כדרך כל המצורעים בתגלחת הראשונה וחטאת העוף כדין טמא פירוש דשמא נזיר טמא הוא ותגלחת זו של טומאה היא ואין מתחיל נזירות טהרה עד שיביא חטאת טומאה שחטאתו מעכבתו אבל אשמו אינו מעכבו וישהא אותו עד תגלחת שניה שיעשה כשיטהר בודאי מן הצרעת או שמא לא יביא אשמו כלל כיון שאינו אלא ספק טמא וא\"צ לו להביא להכשירו שום דבר ומה שמביא חטאתו ביום תגלחתו היינו כר\"ע דאמר במסכת נזיר שאם גלח בשמיני מביא קרבנותיו בו ביום והכא זהו כמו גילוח בשמיני ששהא אותו מפני נזירות טהרה ומתנה על חטאתו אם טמא אני חטאתי זו חובתי לנזירות טומאה ועולה נדבה פירוש עולת בהמה שהיא ספק משום נזירות טומאה ואם טהור אני עולה זו חובתי וחטאת מספק ומגלח ראשו וזקנו וגבות עיניו כדרך שהמצורעים מגלחים ואחר גילוח זה כתוב בתוספתא (פ\"ו) מביא עולת בהמה כו' ונראה שחסר כאן וסופר שלשים יום פירוש לימי נזירות טהרה וספק נזירות טהרה הוא מונה ואינו יכול לגלח לצרעתו תגלחת שניה הראויה להיות לסוף ח' ימים של ראשונה עד שיזרוק עליו מן הדמים ושמא נזיר טהור הוא וטוב לו להביא עולה מספק מחטאת ושלמים כדפירשתי לעיל לפיכך ישהא החטאת והשלמים עד סוף נזירות טהרה שיהא אחר טהרת צרעתו בודאי ומתנה על העולה שהוא מביא עכשיו ואומר אם טמא אני פירוש אם טמא הייתי בתגלחת ראשונה העולה ראשונה היא נדבה וחטאת העוף חובה וזו תהא חובה ואם טהור אני עולה ראשונה היא חובה וזו נדבה כי תגלחת זו של עכשיו אינה כלום שאינה צריכה לא לנזירות ולא לצרעת כי אם הראשונה היתה של נזירות טהרה א\"כ לא היה מצורע שימי צרעתו אינן עולין לימי נזירות כדאמרינן בפרק מי שאמר הריני נזיר מגלח (נזיר יז:) וכן בפ' ב' נזירים (נזיר דף ס:) וחטאת העוף שהבאתי אז ספק ומגלח ראשו וזקנו וגבות עיניו כדרך שהמצורעים מגלחים וזו היא תגלחת שניה של מצורע הראויה להיות בסוף ז' ימי ספירות מתגלחת ראשונה אלא שאינו יכול לעשות עד עכשיו מפני ספק נזירות שעליו שגילוח ספק מצורע אינו דוחה איסור גילוח נזיר כדפירשנו רבי שמעון אומר למחר מביא אשמו כו' כדין מצורע בשמיני שלו והוא יום ס\"א ומתנה עליו כו' ואוכל בקדשים מיד היינו אוכל בקדשים אחר ששים יום דקתני לעיל ומוכח בהדיא שיום הס\"א בשמיני שלו ומוכח נמי דלמחרת זהו למחרת של ס\"א והוא במקום יום שמיני לתגלחתו כדפרישית:"]]],[["שחיטתו בצפון וטעון מתנת בהונות וסמיכה ונסכים ותנופה וחזה ושוק ונאכל לזכרי כהונה ליום ולילה","ולא הודו לו חכמים לר' שמעון מפני שמביא קדשים לבית הפסול","שמואל סבר לה כרבי שמעון בחדא ופליג עליה בחדא","שלשה דברי אגדה כתוב אחד אומר (יחזקאל יח, לב) כי לא אחפוץ במות המת וכתוב אחד אומר (שמואל א ב, כה) כי חפץ ה' להמיתם כאן בעושין תשובה כאן בשאין עושין תשובה","כתוב אחד אומר (דברים י ) כי לא ישא פנים ולא יקח שוחד וכתוב אחד אומר (במדבר ו, כו) ישא ה' פניו אליך כאן קודם גזר דין כאן לאחר גזר דין","כתוב אחד אומר (תהלים קלב, יג) כי בחר ה' בציון וכתוב אחד אומר (ירמיהו לב, לא) כי על אפי ועל חמתי היתה העיר הזאת למן היום אשר בנו אותה עד היום הזה כאן קודם שנשא שלמה את בת פרעה כאן לאחר שנשא שלמה את בת פרעה","שלשה דברי בורות אשתו של לוט מהו שתטמא אמר להם מת מטמא ואין נציב מלח מטמא","בן שונמית מהו שיטמא אמר להן מת מטמא ואין חי מטמא","מתים לעתיד לבא צריכין הזאה שלישי ושביעי או אין צריכין אמר להן לכשיחיו נחכם להן איכא דאמרי לכשיבא משה רבינו עמהם","שלשה דברי דרך ארץ מה יעשה אדם ויחכם אמר להן ירבה בישיבה וימעט בסחורה אמרו הרבה עשו כן ולא הועיל להם אלא יבקשו רחמים ממי שהחכמה שלו שנאמר (משלי ב, ו) כי ה' יתן חכמה מפיו דעת ותבונה","תני ר' חייא משל למלך בשר ודם שעשה סעודה לעבדיו ומשגר לאוהביו ממה שלפניו","מאי קמ\"ל דהא בלא הא לא סגיא","מה יעשה אדם ויתעשר אמר להן ירבה בסחורה וישא ויתן באמונה אמרו לו הרבה עשו כן ולא הועילו אלא יבקש רחמים ממי שהעושר שלו שנאמר (חגי ב, ח) לי הכסף ולי הזהב","מאי קמ\"ל דהא בלא הא לא סגי","מה יעשה אדם ויהיו לו בנים זכרים אמר להם ישא אשה ההוגנת לו"],[[0,"שחיטתו בצפון ומתן בהונות וליום ולילה","כחומר אשם ותנופה וסמיכה וחזה ושוק כחומר שלמים דבאשם ליכא סמיכה כדאמרינן במנחות בפ' שתי מדות:"],[1,"לבית הפסול","דלמא לא מצורע הוא והוי שלמים וממעט זמן אכילתן ששורף את הנותר ליום ולילה והיה לו לאוכלו בשני ימים:"],[2,"כוותיה בחדא","דאשם לא קבע:"],[2,"ופליג עליה בחדא","שאין אשם בא על תנאי:"],[7,"בן השונמית","שהחיה אלישע מהו שיטמא לאחר שהחיהו מי חשוב כמת:"],[8,"נחכם להן","נתיישב בדבר:"],[10,"לאוהביו משגר ממה שלפניו","כך חכמה שהיא לאוהביו של מקום נתנה להם מפיו ולא מאוצר אחר:"],[13,"מאי קמ\"ל","למה ליה למימר להו ירבה בישיבה הואיל וברחמים הדבר תלוי:"]],[[0,"","וסמיכה ונסכין. פי' בקונטרס דבאשם ליכא סמיכה כדאמרינן במנחות פרק שתי מדות (מנחות דף צב.) ולא עיין בה דתנן כל קרבנות היחיד טעונין סמיכה חוץ מבכור ומעשר ופסח ואילו אשם לא מפיק ובפרק כל הפסולין (זבחים דף לג.) פליגי אי סמיכת אשם מצורע דאורייתא או לא ומיהו לכ\"ע סמיכה בעי ובפ\"ב דנגעים (מ\"ח) תנן בא לו [אצל] אשם סומך ב' ידיו עליו והא דקאמר הכא ואותו אשם טעון סמיכה היינו באקופי ידא למ\"ד סמיכת אשם מצורע לאו דאורייתא ומשום דסמיכתו חלוקה משאר אשמות קאמר הכי וכן נסכים נמי לא קתני משום ספקא דשלמים דהא תנן (מנחות דף צ:) דכל חטאת ואשם אין טעונין נסכים אלא שחטאתו ואשמו של מצורע טעונים נסכים אלא משום דחלוקה משאר אשמות קא חשיב לכל הנהו מילי דחלוק מינייהו:"],[3,"","כאן בעושה תשובה וכו'. בספרי משני אהך קושיא כאן קודם גזר דין כו' ותימה דבר\"ה פ\"ק (דף יז:) אמר גדולה תשובה שמקרעת גזר דינו של אדם שנאמר ושב ורפא לו מיתיבי השב בינתיים מוחלין לו לא שב בינתיים פירוש קודם גזר דין אפילו הביא כל אילי נביות אין מוחלין לו ומשני לא קשיא הא ביחיד הא בצבור אלמא ביחיד אין תשובה מקרעת גזר דין של אדם ובשמעתין משמע דמועלת תשובה אפי' ביחיד דומיא דבני עלי ואפי' לאחר גזר דין דאילו קודם גזר דין פשיטא דהקב\"ה מקבל תשובה ועוד דלהמיתם משמע לאחר גזר דין וי\"ל דסוגיא דשמעתין כרבי יצחק דאמר יפה צעקה בין קודם גזר דין בין לאחר גזר דין:"],[4,"","כתוב אחד אומר ישא ה' פניו אליך. לפי הפשט לא משמע שהקב\"ה נושא את פניהם דלא כתיב ישא ה' פניך ומשמע שיפנה אליך להשלים לך שלום ובספרי נמי דריש שיסיר הקב\"ה פנים של זעם מיהו הש\"ס חשיב ליה כאילו כתיב פניך וטפי ה\"ל להש\"ס לאקשויי מהנה נשאתי פניך גם לדבר הזה דלוט (בראשית י״ט:כ״א) ומן וישא ה' פני איוב (איוב מ״ב:ט׳):"],[4,"","כאן קודם גזר דין וכו'. תימה דבפרק מי שמתו (ברכות דף כ:) קאמר אמרו מלאכי השרת לפני הקב\"ה רבש\"ע כתוב בתורתך אשר לא ישא פנים מפני מה אתה נושא פנים לישראל אמר להם לא אשא פנים לישראל אני אמרתי ואכלת ושבעת והם מדקדקים עד כביצה משמע שמחלק בין עובדי כוכבים לישראל ואמאי לא משני כי הכא או הכא כהתם ויש לומר דלעולם שינויא דהכא עיקר וקרא דאמר לא ישא פנים מיירי בין בישראל בין בעובדי כוכבים בעובדי כוכבים אפילו קודם גזר דין שזהו קו המשפט ולישראל לאחר גזר דין אבל הוא נכנס להם לישראל לפנים משורת הדין ונושא להם פנים קודם גזר דין כדמשמע הכא מקרא דישא ה' פניו אליך ומלאכי השרת אמרו לפני הקדוש ברוך הוא למה נכנסת לישראל לפנים משורת הדין יותר מלעובדי כוכבים לישא להם פנים קודם גזר דין והשיב לא אשא להם פנים וכו':"],[6,"","ואין נציב מלח מטמא. משמע אבל אי לא הוה נציב מלח מטמא אפילו לרבי שמעון נמי איכא למימר דמטמא אפילו באהל וכן נמי ציון מערתא דרבי בנאה בפרק חזקת הבתים (ב\"ב דף נח.) אתי נמי כר\"ש דאחר מתן תורה דאיקרו ישראל אדם איכא לפלוגי אבל קודם מתן תורה אין חילוק והרב רבי משה מפונטיז\"א פירש דבנזיר פרק כהן גדול (נזיר דף נד.) מרבי מאו בקבר קברי מתים שלפני הדבור אלמא קודם מתן תורה מטמא אע\"ג דלא איקרו אדם ואי אפשר לומר כך דהך סוגיא דכהן גדול לא אתיא אלא כרבי שמעון דממעט להו מאדם ועוד או בקבר גבי מגע כתיב ואחר מתן תורה מטמאין קברי עובדי כוכבים במגע ולא אימעוט לרבי שמעון אלא מאהל והכי מסיק בפרק הבא על יבמתו (יבמות דף סא.) ונראה לפרש דלפני הדבור היינו קודם שנאמר פרשת אהל דהיינו קודם שהוקם המשכן כדאיתא בגיטין פ' הניזקין (גיטין דף ס.) שמונה פרשיות נאמרו ביום הקמת המשכן וחשיב פרשת פרה ופרשת טמאין דס\"ד כי ימות באהל מכאן ולהבא כתיב ולהכי איצטריך או בקבר וקאי ריבויא אכי ימות ולא אאדם וכי האי גוונא איכא בפ' בתרא דהוריות (דף י.) כי יהיה פרט שלפני הדבור דגבי זיבה:"],[8,"","מתים לעתיד לבא צריכים הזאה. ואם תאמר אמאי לא בעי הך בעיא על בן השונמית דאיירי ביה וי\"ל שמא משום דכתיב קרא לעתיד לבא (יחזקאל ל״ו:כ״ה) וזרקתי עליכם מים טהורים ומספקא ליה אי הך זריקה הויא שלישי ושביעי אי לא אבל בן השונמית פשיטא ליה דלא בעי הזאה:"]]],[["ויקדש עצמו בשעת תשמיש","אמרו הרבה עשו כן ולא הועילו אלא יבקש רחמים ממי שהבנים שלו שנאמר (תהלים קכז, ג) הנה נחלת ה' בנים שכר פרי הבטן","מאי קא משמע לן דהא בלא הא לא סגי","מאי שכר פרי הבטן א\"ר חמא ברבי חנינא בשכר שמשהין עצמן בבטן כדי שתזריע אשתו תחילה נותן לו הקב\"ה שכר פרי הבטן","בית שמאי אומרים [וכו'] מאי טעמייהו דבית שמאי אי נימא משום דכתיב (אסתר ד, ד) ותתחלחל המלכה ואמר רב מלמד שפרסה נדה הכא נמי אגב ביעתותא דמלאכא דמותא חזיא והאנן תנן שחרדה מסלקת את הדמים הא לא קשיא פחדא צמית ביעתותא מרפיא","אלא הא דתנן ב\"ש אומרים כל האנשים מתים זבין וב\"ה אומרים אין זב אלא מי שמת זב","אקרי כאן מבשרו ולא מחמת אונסו","אלא טעמא דב\"ש כדתניא בראשונה היו מטבילין כלים על גבי נדות מתות והיו נדות חיות מתביישות התקינו שיהו מטבילין על גבי כל הנשים מפני כבודן של נדות חיות","בראשונה היו מטבילין על גבי זבין מתין והיו זבין חיין מתביישין התקינו שיהו מטבילין על גבי כל האנשים מפני כבודן של זבין חיים","\u0001מתני׳\u0002 האשה שמתה ויצאה ממנה רביעית דם מטמאה משום כתם ומטמאה באהל","רבי יהודה אומר אינה מטמאה משום כתם מפני שנעקר משמתה ומודה רבי יהודה ביושבת על משבר ומתה ויצאה ממנה רביעית דם שהיא מטמאה משום כתם אמר רבי יוסי לפיכך אינה מטמאה באהל","\u0001גמ׳\u0002 מכלל דתנא קמא סבר אף על גב דנעקר דם משמתה מטמאה משום כתם","אמר (רבי) זעירי מקור מקומו טמא איכא בינייהו","ומודה רבי יהודה","מכלל דתנא קמא סבר באהל נמי מטמא אמר רב יהודה דם תבוסה איכא בינייהו","דתניא איזהו דם תבוסה פירש ר\"א ברבי יהודה הרוג שיצא ממנו דם בין בחייו בין במותו ספק בחייו יצא ספק במותו יצא ספק בחייו ובמותו זהו דם תבוסה","וחכמים אומרים ברה\"י ספקו טמא ברה\"ר ספקו טהור","אלא איזהו דם תבוסה הרוג שיצא הימנו רביעית דם בחייו ובמותו ועדיין לא פסק ספק רובו בחייו ומיעוטו במותו ספק מיעוטו בחייו ורובו במותו זהו דם תבוסה","רבי יהודה אומר הרוג שיצא ממנו רביעית דם והיה מוטל במטה ודמו מטפטף לגומא טמא מפני שהטפה של מיתה מעורבת בו וחכמים מטהרין מפני"],[[0,"ויקדש עצמו","לשמש בצניעות:"],[3,"שמשהין","להוציא את הזרע:"],[4,"פחדא צמית","דאגת יראה כי הכא מפני פחד כרכום והגיע שעת וסתה ולא בדקה טהורה שהחרדה מסלקת הדמים:"],[4,"ביעתותא","הבהלות פתאום שאדם רואה או שומע נבהל מרפיא:"],[5,"אלא הא דתנן כל האנשים","המתים מחזקינן להו כזבין סמוך למיתתן ואי טעמייהו דב\"ש משום ביעתותא דמלאך המות זכרים היכי מטמאו הא זכר אינו מטמא באונס דקרינן ביה מבשרו ולא מחמת אונסו:"],[7,"אלא טעמייהו דב\"ש","מדרבנן משום כבוד זבין התקינו שיהו מטבילין כלים של סמוך למיתה אף על פי שלא נגעו בהם לאחר מיתה:"],[7,"[כלים]","אף הכלים של קודם למיתה:"],[8,"מתביישין","שאפילו במיתתן הם משונין מכל אדם:"],[9,"מתני' מטמא משום כתם","דדם נדה במשהו דאי משום טומאת מת לא מטמא אלא ברביעית:"],[9,"ומטמא באהל","אם כל הרביעית יחד:"],[10,"שמטמאה משום כתם","שנעקר מחיים:"],[12,"גמ' לת\"ק מקור מקומו טמא","הילכך אף על גב שנעקר לאחר מיתה מטמא בנדות מפני שהיה במקור מחיים ואע\"ג דלאחר מיתה לאו רואה היא:"],[14,"באהל נמי מטמא","בתמיה. הרי יוצא מחיים:"],[14,"דם תבוסה איכא בינייהו","לר' יהודה הואיל וספק הוא ספק אם נעקר כולו מחיים ספק אם נעקר מקצתו לאחר מיתה הוה דם תבוסה ומדרבנן מטמא באהל דמדאורייתא עד שתהא רביעית לאחר מיתה ור' יוסי סבר האי לאו דם תבוסה הוא דכיון דכורעת לילד הוא כולו נעקר מחיים:"],[15,"איזהו דם תבוסה","דאמרינן בפירקין דלעיל (נדה דף סב:) דטומאתו דרבנן:"],[15,"בחייו ובמותו","שהתחילה הרביעית לצאת מחיים ספק כולו מחיים ספק כולו במותו זהו דם תבוסה וטמא מדרבנן באהל כדאמרי' בפירקין דלעיל דם תבוסה דרבנן:"],[16,"וחכ\"א","זה אינו הואיל ואיכא לספוקי שמא כולו במותו הוה ליה ספק טומאה דאורייתא ברה\"י וספקו טמא:"],[17,"אלא איזהו דם תבוסה","דטומאתו מדברי סופרים:"],[17,"הרוג שיצא כו'","דפשיטא לן דלא נפיק מיניה רביעית שלמה לאחר מיתה. וספק רובו מחיים כו' רבותא אשמעינן דאע\"ג דמספקא לן אי רובו מחיים גזר עליה טומאה ומיהו אי הוה נמי רובא לאחר מיתה אין טומאתו מן התורה דרביעית שלמה דמת בעינן ומיהו אי הוה פשיטא לן דרובא מחיים לא גזרו עליה:"]],[[4,"","והאנן תנן שחרדה מסלקת הדמים. בלאו מתניתין דהכא הוה מצי למפרך אדרב אלא אגב דקאי לפרושי מתני' פריך אמתניתין:"],[7,"","אלא טעמא דבית שמאי כדתנן בראשונה. משמע דהך לא אתי כב\"ה ותימה דבסוף מועד קטן (דף כז:) תני לה גבי שאר בראשונה דקתני התם דהוי הילכתא פסיקתא משמע דבכולהו הלכתא כמו שהתקינו לבסוף ובתוספת' דמכילתין (פ\"ט) קתני לכולהו ואומר ר\"ת דברייתא דהכא איירי בכלים שהיו עליה סמוך למיתה ומודו ב\"ה בכלים שיש עליהם טומאת זבה אבל פלוגתא דמתניתין ארישא דזב וזבה מטמאין באבן מסמא עד שימוק הבשר כו' שמא יתעלפה והך חומרא מוקי בית שמאי בכל הנשים שמטמאין באבן מסמא עד שימוק הבשר ואהא דוקא פליגי ב\"ה ועוי\"ל דבראשונה דהכא היינו דמתחילה היו נוהגין כב\"ה ולבסוף התקינו לכ\"ע שיהיו נוהגין כבית שמאי:"],[9,"","מטמא משום כתם. פי' כדם נדה במשהו דאי משום מת בעי רביעית:"],[12,"","מקור מקומו טמא איכא בינייהו. לת\"ק מקומו טמא ולא לענין שיהא הדם הנוגע בו טמא טומאת מגע דאפילו בלא מקור ליטמא אפי' פחות מרביעית משום דנגע במת אלא כתם ראייה גמורה קאמר שיטמא הדם במגע ובמשא אע\"ג דלאו רואה היא לאחר מיתה הואיל והיה במקור מחיים ומשעת כבוס ליכא לטמויי כמו כתם דהא ודאי השתא הוא דאתא דם ולא מהני טומאת כתם אלא להיות טומאה בפחות מרביעית [במשהו]:"],[15,"","בין בחייו בין במותו. מפרש ואזיל ספק בחייו כולו ספק במותו כולו ספק בחייו ובמותו קצת בחייו קצת במותו:"],[17,"","ה\"ג בפי' ר\"ח ובתוספתא דאהלות (פ\"ד) הרוג שיצא ממנו רביעית דם בחייו ובמותו ועדיין לא פסק ספק רובו מחיים כו'. ורבינו שמואל כתב דלא איתפרש ומפרש ר\"י ועדיין לא פסק הדם משמת ושמא הולך ורבה עד שיהא רביעית שלמה ואף ע\"ג דהשתא ליכא אלא רובו לאחר מיתה דגזרו אטו כולו מדין דם תבוסה אבל כשראינו כשפסק משמת לא גזרו עליו דין דם תבוסה כי בודאי לא יצא רביעית לאחר מיתה במה שיצא אחרי כן ודמו מטפטף לגומא (שמא) מספקא ליה לר\"י אי בעי רבי יהודה ועדיין לא פסק כרבנן וטיפה של מיתה לאו דוקא אלא הכי קאמר ומה שיטפטף לאחר מיתה אינו מתבטל ראשון ראשון אלא מצטרפין כולן עד שיהא בו שיעור לטמא ורבנן מטהרים דראשון ראשון בטל או דילמא לא בעי עדיין לא פסק וטיפה דנקט דוקא מדקאמר לקמן שאני אומר טיפה של מיתה עומדת לה על העץ הא אם ירדה למטה הוה מטמא רבי יהודה אע\"ג דאין דרך לעמוד על העץ אלא מעט ורבנן דקאמרי ראשון ראשון נפסק רבותא קאמר אפילו לא פסק כיון דאינו אלא מטפטף ראשון ראשון בטל והרב ר' יהודה בן ה\"ר י\"ט מפרש ועדיין לא פסק פירוש מלהיות שותת אילו היה מטפטף היה טהור דראשון ראשון בטל וחכמים דבתר הכי היינו תנא קמא דמפרשי טעמייהו אמאי פליגי אדרבי יהודה מפני שראשון ראשון נפסק וכן נמי ר' יהודה בתר הכי מפרש טעמא אמאי פליג אדר\"ש שאני אומר טיפה של מיתה עמדה על העץ ור\"ת מפרש ועדיין לא פסק שאחר שנודע לנו שמת ראינו שלא פסק ובודאי איכא מיעוט לאחר מיתה כדמפרש ואזיל ספק רובא מחיים ספק מיעוט כו' ואתא לאפוקי מתנא קמא דאמר אפי' היכא דאיכא לספוקי שמא יצא כולו מחיים טמא:"],[18,"","ודמו מטפטף לגומא. רבי יהודה נקט גומא משום שהזכיר טפטוף שיהא יחד ומצטרף דבלאו גומא אינו מתערב יפה אלא נוטף כאן וכאן אבל רבי שמעון דנקט שותת אפילו בארץ מתערב יפה:"]]],[["שראשון ראשון נפסק שפיר קאמרי ליה רבנן לר' יהודה ר' יהודה לטעמיה דאמר אין דם מבטל דם","ר\"ש אומר צלוב על העץ שדמו שותת לארץ ונמצא תחתיו רביעית דם טמא רבי יהודה מטהר שאני אומר טפה של מיתה עומדת לו על גב העץ","ורבי יהודה נימא איהו לנפשיה שאני אומר טפה של מיתה עומדת על גב המטה שאני במטה דמחלחלה","\u0001מתני׳\u0002 בראשונה היו אומרים היושבת על דם טהור היתה מערה מים לפסח","חזרו לומר הרי היא כמגע טמא מת לקדשים כדברי ב\"ה ב\"ש אומרים אף כטמא מת","\u0001גמ׳\u0002 מערה אין נוגעת לא אלמא חולין שנעשו על טהרת הקדש כקדש דמו","אימא סיפא חזרו לומר הרי היא כמגע טמא מת לקדשים לקדשים אין לחולין לא אלמא חולין שנעשו על טהרת הקדש לאו כקדש דמו","מתני' מני אבא שאול היא דתניא אבא שאול אומר טבול יום תחילה לקדש לטמא שנים ולפסול אחד","\u0001מתני׳\u0002 ומודים שהיא אוכלת במעשר וקוצה לה חלה ומקפת וקורא לה שם","ואם נפל מרוקה ומדם טהרה על ככר של תרומה שהוא טהור","ב\"ש אומרים צריכה טבילה באחרונה ובית הלל אומרים אינה צריכה טבילה באחרונה","\u0001גמ׳\u0002 דאמר מר טבל ועלה אוכל במעשר","וקוצה לה חלה חולין הטבולין לחלה לאו כחלה דמו","ומקפת דאמר מר מצוה לתרום מן המוקף","וקורא לה שם סד\"א נגזור דלמא אתי למנגע בה מאבראי קמ\"ל","ואם נפל מרוקה דתנן משקה טבול יום (משקין היוצאין ממנו) כמשקין הנוגע בהם ואלו ואלו אינן מטמאין חוץ ממשקה הזב שהוא אב הטומאה","בית שמאי מאי בינייהו אמר רב קטינא טבול יום ארוך איכא בינייהו","\u0001מתני׳\u0002 הרואה יום אחד עשר וטבלה לערב ומשמשה","ב\"ש אומר מטמאין משכב ומושב וחייבין בקרבן"],[[0,"שראשון ראשון נפסק","שאין זב בקילוח אלא נוטף והלכך אפי' היה רוב לאחר מיתה טהור שהרי מתחילה דם נפל מחיים בתוך הגומא ואח\"כ נפל דם מיתה עליו טיפין טיפין כל טיפה וטיפה שנפלה בטלה בדם הראשון שהיה בגומא מחיים והיכא אמרי' דם תבוסה בשוכב על הארץ ודמו זב ואינו נפסק ההוא כי הוי לאחר מיתה רובא אזלינן בתריה מדרבנן ואי נמי מספקא לן גזור בה טומאה:"],[0,"דאין דם מבטל דם","בפרק כסוי הדם:"],[1,"שותת לארץ","שאינו נוטף אלא שותת ואינו נפסק הילכך לא מבטל ההוא דלאחר מיתה שהוא הרבה אבל נוטף ראשון בטל ואפילו טפה שלאחר מיתה מרובה בטלה שלא נפל ביחד:"],[3,"מתני' מערה מים לפסח","מכלי אל כלי לרחוץ בו את בשר הפסח אבל במים אינה נוגעת שהיא טבולת יום שטבלה לסוף שבועיים ואין לה הערב שמש עד יום שמונים שהוא תכף להבאת כפרתה והכתוב עשאה טבולת יום דכתיב (ויקרא י״ב:ד׳) בכל קדש לא תגע וקי\"ל בכל קדש לרבות את התרומה וטבול יום שני הוא וכשהיא מערה אינה נוגעת במים אלא בכלים ושני אינו מטמא כלי:"],[4,"חזרו לומר הרי היא כמגע טמא מת","שהוא ראשון לקדשים אבל לחולין לא הילכך אפילו נוגעת במים אם תרצה שהמים חולין הם וטבול יום שני הוא ואין שני עושה שלישי בחולין ואף ע\"פ שהמים הללו נעשים על טהרת הקדש שהרי לרחיצת פסח עשויות לא מהני בהו שני דחולין הנעשה על טהרת הקדש לאו כקדש דמו:"],[5,"גמ' נוגעת","במים לא:"],[5,"כקדש דמו","ומהני בהו שני:"],[8,"מתני' ומודים שאוכלת במעשר","כדין טבול יום:"],[8,"וקוצה לה חלה","עד שלא תקרא עליה שם ומנחתה בכלי:"],[8,"ומקפת","ומקרבת הכלי אצל העיסה כמו אקפינהו ולא אדמו בשחיטת חולין (דף נ.) וכמו אין מקיפין שתי חביות במס' ביצה (דף לב:). ובגמרא מפרש דמצוה לתרום מן המוקף מן הקרוב לדבר שהוא תורם עליו:"],[9,"ואם נפל מרוקה","דהוו להו משקים היוצאין מן הטבול יום וטהורים כדתניא בגמרא:"],[10,"צריכה טבילה","ליל שמונים לתרומה מפני שטבולת יום ארוך היא והסיחה דעתה מן התרומה ואם ישראלית היא טובלת לביאת מקדש:"],[10,"אינה צריכה","אבל לקדשים מודו ב\"ה דקיימא לן (חגיגה דף כא.) האונן ומחוסר כפורים צריכין טבילה לקדש הילכך לאחר שהביאה כפרתה טובלת לקדשים:"],[12,"גמ' לאו כחלה דמו","ולא מהני בהו שני:"],[17,"מתני' הרואה יום י\"א","שהיא סוף ימי זוב ואין יום שלאחריו מצטרף עמו לזיבה:"],[18,"משכב ומושב","אפילו בעלה מטמא משכב ומושב לטמא אוכלין ומשקין שהוא כבועל שומרת יום כנגד יום דקסבר יום י\"א בעי שימור:"]],[[0,"","רבי יהודה לטעמיה דאמר אין דם מבטל דם. וא\"ת לרבא דמשני אליבא דרבי יהודה בזבחים בפרק התערובת (זבחים דף עט:) דבכ\"מ אית ליה לר' יהודה מין במינו לא בטיל וכן נמי בפ' הערל (יבמות דף פא:) גבי חתיכה של חטאת וגבי פרוסה של לחם הפנים דקאמר התם ר' יהודה לא תעלה ומוקי לה התם רבה בר רב הונא כשנמוחה ופריך אי הכי מ\"ט דר' יהודה ומשני ר' יהודה לטעמיה דאמר מין במינו לא בטיל וההיא דקאמר התם בטיל היינו בטומאה דרבנן דמדאורייתא בכל שהוא סגי א\"כ ה\"נ דם תבוסה דרבנן וליבטל ברובא ויש לומר כיון דשייך ביה טומאה רביעית דם דמטמא באהל ראוי להחמיר בו יותר ולא בטל ברובו במינו וא\"ת ולפרוך מהכא לרב חסדא דאמר בפ' הקומץ רבה (מנחות דף כג.) נבלה בטלה בשחוטה דבתר מבטל אזלינן ואי אפשר לשחוטה שתעשה נבלה והוי ליה מין בשאינו מינו והכא נמי אי אפשר לדם המבטל להיות טמא וליבטל ביה דם של אחר מיתה ויש לומר דהתם אליבא דתנא דבי ר' חייא פליגי רב חסדא ורבי חנינא דסבר התם כרבי יהודה אבל לרבי יהודה גופיה אין חילוק ולעולם לא בטיל:"],[5,"","מערה אין נוגעת לא. וא\"ת וליתני אינה נוגעת דלגופיה לא איצטריך דפשיטא דמערה דהא אינה מטמאה בהיסט ויש לומר דאיצטריך לאשמועינן דלא חיישינן שמא נגעה והכי נמי איכא לפרושי הא דתניא במסכת ידים כל שאינו מטמא את המים במשא כשר לנטילת ידים ויש שרוצים לדקדק הא מטמא במשא אינו כשר לנטילת ידים ומתוך כך אוסרין לקבל מים מן עובד כוכבים ושיבוש הוא דהא נדה ויולדת נוטלות ידיהן אף על פי שמטמאות במשא וכ\"ש עכשיו שאנו נוטלין כולנו ממי טמאים ונראה דהתם איירי לתרומה או לחולין שנעשו על טהרת תרומה ולא אתא לדיוקא אלא לגופיה דכשר לערות לידים ואף ע\"ג דמטמא במגע לא חיישינן שמא יגע ולעיל מיניה תניא הכל כשרין ליטול ידים ואפילו טמא מת ואפילו בועל נדה שאינו מטמא (בהיסט) ושמא כי היכי דקיל מנדה שאינו מטמא משכב תחתון [אלא] כעליון ושטבילתו ביום ה\"נ קיל מנדה שאינו מטמא בהיסט ומיהו קשיא הא דתנן במסכת כלים (פ\"א מ\"ב) למעלה מהן נבלה דמטמא במשא למעלה מהן בועל נדה שמטמא משכב תחתון כעליון אלמא מטמא נמי במשא מיהו מצינן למימר דאע\"ג דאינו מטמא במשא קאמר שפיר למעלה מנבלה כיון דאיכא חומרא חדא דלית בנבלה דה\"נ תנן לעיל ומטמא באבן מסמא ותנן בתר הכי למעלה מהן מת שמטמא באהל אע\"ג דאינו מטמא באבן מסמא ואומר ר\"י דלא קשה מידי אפילו אי מטמא במשא כנבלה היינו דמטמא את הטהור הנושא אבל כשהוא נושא את הטהור כגון הכא שהוא נושא את המים לא מטמא כדאמר בפ' ר\"ע בשבת (דף פג:) זה הסיטו של זב שלא מצינו לו חבר בכל התורה כולה שאם תכריע טומאה את הטהרה בכף מאזנים שיהא טמא:"],[9,"","ואם נפל מרוקה ומדם טהרה על ככר של תרומה שהוא טהור. והכי תנן בריש פ\"ב דטבול יום משקין היוצאין ממנו כמשקה הנוגע בהן אלו ואלו אין מטמאין מפ' ר\"ת במשקה תרומה הנוגע בהן אלו ואלו אין מטמאין את הקדשים אבל מפסל פסלי ליה אבל תרומה אפילו אינה פוסלת כדתני הכא שאם נפל רוקה ודם טהרה על ככר של תרומה שטהורה ואין לפרש במשקה חולין הנוגע בהן דהא טבול יום אינו מטמא משקה חולין ומאי קאמר אלו ואלו אין מטמאין (קדשים) אפילו מפסל נמי לא פסלי ואין לפרש במשקה חולין שנעשו על טהרת הקדש דהא חזרו לומר בשמעתין דלאו כקדש דמו:"],[12,"","חולין הטבולין לחלה לאו כחלה דמו. דוקא לענין טבול יום כדאמרינן לעיל בפרק קמא (נדה דף ז.) כל שודאי מטמא חולין כו':"],[17,"","הרואה יום אחד עשר וטבלה לערב כו'. דספירת ערב לאו ספירה היא כדקאמר בגמרא ושוין בטבילת לילה שאינה טבילה מכאן קשה לפירוש רש\"י שפירש בפ' ב' דזבחים (דף כג.) ובפסחים פרק כיצד צולין (פסחים דף פא.) דקאמר לר' יוסי דקאמר מקצת היום ככולו וזבה שראתה בשביעי שלה אינה סותרת לאחר טבילה ופריך התם אלא זבה גמורה היכי משכחת לה ומשני בשופעת אי נמי ברואה בשני בין השמשות ופי' רש\"י הא דלא משני ברואה בלילות משום דלמ\"ד מקצת היום ככולו לילה חשיבא ספירה ולא צריך עמוד השחר לטבול והשתא קשה דא\"כ מתני' דלא כר' יוסי וכן מתני' דמגילה פ' הקורא (מגילה דף כ.) דתנן כולן שעשו משעלה עמוד השחר כשר משמע דבלילה לא הוי ספירה ומפ' ר\"ת דהכי פריך זבה ביממא היכי משכחת לה מדכתיב כל ימי זוב טומאתה אמרי' לקמן אימר ביממא תהוי זבה משמע דבראיית ימים היא נעשית זבה מיהא תימה מאי קא משני ברואה בשני בין השמשות מ\"מ ליכא אלא ב' ראיות ביום וצ\"ל דלא חש להזכיר השלישית כיון שהזכיר השניה ממילא ידעי' השלישית וכן צ\"ל לפירש\"י דבסוף פרק ב' דנזיר (דף טז.) דאיכא נמי הך סוגיא דכיצד צולין (פסחים דף פא.) ומשני דחזאי תלתא יומי סמוך לשקיעת החמה דלא הוי שהות דסליק ליה למנינא ותלתא יומי לאו דוקא דבחדא סגי כשראתה בשני עד הלילה ור\"י מפרש זבה גמורה לר' יוסי היכי משכחת לה כיון דאית ליה לרבי יוסי מקצת היום ככולו בתחילת היום דקאמר זב הרואה בשביעי שלו אינו סותר התחלת היום וישלים ז' ה\"ה נמי דסוף היום ככולו ואפי' ראתה בלילה מה בכך מ\"מ מקצת היום ככולו וסוף היום להוי שימור וכן משמע בנזיר (דף טז.) דקאמר ולרבי יוסי כו' כיון דחזאי פלגא דיומא אידך פלגא סליק לה שימור משמע שסוף היום מחצות ואילך הוי שימור דאידך פלגא ומשני דחזאי תלתא יומי סמוך לשקיעת חמה דלא הוי שהות פי' סוף היום סליק לה למנינא דראייתה וא\"ת ולרבי יוסי נימא וכי ככותאי אמרה לשמעתיה דאית ליה מקצת היום ככולו ושמעתיה דרב אוקמינן לעיל (נדה דף סט.) דלא ככותאי ובנזיר אוקמינן רב כרבי יוסי וי\"ל דכי אית ליה מקצת היום ככולו היינו בשביעי לזבה שהוא יום אחרון של חשבונה וכן בשומרת יום כנגד יום מקצת יום ספירה עולה ואינה סותרת שאין לה למנות יותר והוא סוף חשבונה אבל בתחילת הספירה לא אמרינן שסוף היום שהיא פוסקת בו שיהא ככולו מיהו קשה דאמרי' בפ\"ק דר\"ה (דף י.) אמר רבא ק\"ו ומה נדה שאין תחילת היום עולה לה בסופה סוף היום עולה לה בתחילתה שנה שתחילת היום עולה לה בסופה אינו דין שסוף היום עולה לה בתחילתה ומאי קושיא זבה תוכיח לרבי יוסי שתחילת היום עולה לה בסופה ואין סוף היום עולה לה בתחילתה ואור\"י דאליבא דרבנן קאמר רבא ולא אליבא דר' יוסי ועוד נ\"ל דאפילו לרבי יוסי אין שייך לומר יוכיח מזבה לנדה דגבי נדה דין הוא שיהיה יום ראשון מן החשבון כי למה לא יהיה ככל הטומאות שאין צריכין נקיים אבל זבה דצריכה נקיים נהי דבסוף החשבון יעלה שמיד שנכנס השביעי נכנס בטהרה מ\"מ יום שפוסקת בו שאינו טהור אינו דין שיעלה לה לחשבון הנקיים:"]]],[["וב\"ה אומרים פטורים מן הקרבן","טבלה ביום של אחריו ושמשה את ביתה ואח\"כ ראתה ב\"ש אומרים מטמאין משכב ומושב ופטורין מן הקרבן","וב\"ה אומרים ה\"ז גרגרן ומודים ברואה בתוך י\"א יום וטבלה לערב ושמשה שמטמאין משכב ומושב וחייבין בקרבן","טבלה ביום של אחריו ושמשה ה\"ז תרבות רעה ומגען ובעילתן תלויין","\u0001גמ׳\u0002 ת\"ר ושוין בטובלת לילה לזבה שאינה טבילה ושוין ברואה בתוך י\"א יום וטבלה לערב ושמשה שמטמאה משכב ומושב וחייבין בקרבן","לא נחלקו אלא ביום י\"א יום שב\"ש אומרים מטמאין משכב ומושב וחייבין בקרבן ובית הלל פוטרין מקרבן","אמרו להן ב\"ש לב\"ה מ\"ש יום י\"א מיום תוך י\"א אם שיוה לו לטומאה לא ישוה לו לקרבן","אמרו להן ב\"ה לב\"ש לא אם אמרת בתוך י\"א יום שכן יום שלאחריו מצטרף עמו לזיבה תאמרו ביום י\"א שאין יום שלאחריו שנצטרף עמו לזיבה","אמרו להם בית שמאי השוו מדותיכם אם שיוה לו לטומאה ישוה לו לקרבן ואם לא שיוה לו לקרבן לא ישוה לו לטומאה","אמרו להם ב\"ה אם הביאנוהו לידי טומאה להחמיר לא נביאהו לידי קרבן להקל","ועוד מדבריכם אתם נושכין שאתם אומרין טבלה יום שלאחריו ושמשה ואח\"כ ראתה מטמא משכב ומושב ופטורה מן הקרבן אף אתם השוו מדותיכם אם שיוה לו לטומאה ישוה לו לקרבן","ואם לא שיוה לו לקרבן לא ישוה לו לטומאה אלא להחמיר ולא להקל הכא נמי להחמיר ולא להקל","אמר רב הונא משכבה ומושבה שבשני ב\"ש מטמאין אע\"פ שטבלה אע\"פ שלא ראתה מאי טעמא כיון דאילו חזיא מטמאה השתא נמי מטמיא","אמר רב יוסף מאי קמ\"ל תנינא טבלה יום שלאחריו ושמשה את ביתה ואח\"כ ראתה ב\"ש אומרים מטמאה משכבות ומושבות ופטורה מן הקרבן","אמר רב כהנא ראתה שאני","אמר רב יוסף וכי ראתה מאי הוי ראייה דנדה היא","א\"ל אביי לרב יוסף רב כהנא הכי קא קשיא ליה בשלמא היכא דראתה גזרינן ראייה דנדה אטו ראייה דזבה אלא היכא דלא ראתה מאי נגזר בה","ועוד תנן הרואה ראייה אחת של זוב ב\"ש אומרים כשומרת יום כנגד יום ובה\"א כבעל קרי"],[[0,"וב\"ה פוטרין מן הקרבן","דלא בעי שימור. אבל לענין טומאה מודו מדרבנן להחמיר גזרה יום י\"א אטו תוך י\"א יום דמטמאה בועלה מדאורייתא עד שתספור קצת יום המחרת כדיליף לקמן מיהיה לה:"],[1,"טבלה יום שלאחריו","דעבדה שימור קצת ושימור מעליא הוא אלא שתוך י\"א יום אסור לעשות כן שלא תבא לידי ספק שמא תראה לאחר תשמיש ומצטרפין הימים לזיבה ואין טבילתה טבילה:"],[1,"מטמאין משכב ומושב","ואפילו בועלה מדרבנן גזרו אטו תוך י\"א יום:"],[1,"ופטורין מן הקרבן","דהא עבדי שימור ואע\"פ שחזרה וראתה אין מצטרפין לזיבה שהרי תחילת נדה היא:"],[2,"גרגרן","ממהר לחטוא שמא ירגיל בכך תוך י\"א אבל לענין טומאה טהור:"],[2,"וחייבין בקרבן","ואפילו לא תראה למחר דהא בעי שימור והרי בעל זבה קטנה:"],[3,"טבלה יום שלאחריו","דעבדה קצת שימור ושמשה:"],[3,"ה\"ז תרבות רעה","שמא תראה אחר כן ותצטרף לשלפניו ואין טבילתה טבילה:"],[3,"ומגען","לענין טומאה וטהרה:"],[3,"ובעילתן","לענין קרבן:"],[3,"תלויין","שאם תראה מגען מגע זבה וחייבין בקרבן ואם לא תראה מגען טהור ובעילתן פטורה:"],[4,"גמ' ת\"ר ושוין בטובלת לילה לזבה","ואע\"פ שחלוקין ב\"ה ברואה יום י\"א וטבלה לערב שפטורין מן הקרבן התם משום דיום י\"א לא בעי שימור הילכך לאו זבה הואי אבל זבה קטנה של תוך י\"א יום בעיא שימור דאין טבילת לילה עולה עד שתשמור יום המחרת קצת ותטבול:"],[4,"ושוין ברואה תוך י\"א יום וטבלה לערב ושמשה שחייבין בקרבן","כאילו בועלה ביום. והך סיפא פירוש דרישא הוא:"],[6,"אם שיוה לו לטומאה","שאתם מודים שמטמאה בועלה משכב ומושב ליל מוצאי י\"א:"],[7,"בתוך י\"א מצטרף עמו לזיבה","הילכך צריכה לשמור יום המחרת כנגד יום הראייה:"],[9,"להחמיר","מדרבנן:"],[9,"להקל","להביא חולין בעזרה:"],[10,"נושכים","מוקשין:"],[12,"אמר רב הונא משכבות ומושבות שבשני","לראייתה הרואה תוך י\"א וטבלה יום שלאחריו לב\"ש דמחמירי ומטמאין משכב ומושב מדרבנן לאחר טבילה ואפילו לא ראתה מאי טעמא דכיון דכי חזיא מטמאה למפרע מדאורייתא שהרי מצטרף לזיבה כי לא חזיא נמי גזרינן מדרבנן אטו ראתה:"],[13,"תנינא טבלה יום שלאחריו","יום י\"ב שאינו מצטרף ואחר כן ראתה וקס\"ד האי ראתה דלאחריו כאילו לא ראתה תוך י\"א דמיא דהא עכשיו היא מטמאה מתחילת נדה ואינה פוסלת טבילה של שחרית והך טומאה מדרבנן היא דגזרינן י\"ב אטו י\"א ה\"נ גזרינן לא ראתה אטו ראתה:"],[15,"ראיית נדה היא","ואינה מצטרפת אלא מעכשיו מטמאה וטומאת מעת לעת הוא דאיכא עליה וטומאת מעת לעת אינה מטמאה את בועלה אלא משום דגזרינן יום שלאחר י\"א אטו תוך י\"א דאורייתא ה\"נ תוך י\"א כי לא ראתה בשני אחר טבילתה גזרינן אטו ראתה:"],[16,"א\"ל אביי לרב יוסף רב כהנא","דאמר ראתה שאני הכי קא קשיא ליה אע\"ג דהך טומאה מדרבנן ליכא למימר דכי היכי דגזרי ב\"ש ראייה שניה דלאחר י\"א אטו ראייה שניה תוך י\"א ה\"נ נגזור לא ראתה אטו ראתה דראייה בראייה מיחלפא ראתה בלא ראתה לא מיחלפא:"],[17,"ועוד תנן","דלא כרב הונא:"],[17,"הרואה ראייה אחת של זוב","באיש מיירי:"],[17,"כשומרת יום כנגד יום","בשני שלה שמגעה תלוי אחר טבילה אף זה מגעו תלוי אם טבל לאחר ראייה ונגע במעשר מגעו תלוי שמא יראה ראייה שניה ומצטרף לזיבה:"],[17,"כבעל קרי","וטהור למעשר לאחר טבילה מיד. קתני מיהא לב\"ש שומרת יום וזב בראייה ראשונה שוין:"]],[[10,"","אף אתם השוו מדותיכם. וא\"ת ומאי ס\"ד דב\"ש הא ודאי לדידהו נמי איכא לאקשויי הכי וי\"ל דקסברי ב\"ש דיום י\"א שהוא מדאורייתא אי מחמירינן ביה לטמא משכב ומושב אתי למימר ביה חיוב קרבן אבל ביום שלאחריו שהכל יודעין שהוא מדרבנן לא אתי לחיובי קרבן אי מחמירין ביה לטמויי משכב ומושב:"],[14,"","אמר רב כהנא ראתה שאני. ואדרבה מנליה לרב הונא בתוך י\"א יום בלא ראתה והיינו דקאמר רב כהנא הכי קא קשיא ליה פי' אדרב הונא ועוד תניא דלא כרב הונא:"]]],[["ותניא המסיט את הראייה ב\"ש אומרים תולין וב\"ה מטהרין","משכבות ומושבות שבין ראייה ראשונה לראייה שנייה ב\"ש תולין וב\"ה מטהרין","וקתני רישא הרואה ראייה אחת של זוב ב\"ש אומרים כשומרת יום כנגד יום אלמא שומרת יום כנגד יום לב\"ש תולין","לא תימא שומרת יום כנגד יום אלא אימא כבועל שומרת יום כנגד יום","מאי שנא איהו דלא מטמא משכב ומושב ומאי שנא איהי דמטמיא ליה","איהו דלא שכיחי ביה דמים לא גזור ביה רבנן איהי דשכיחי בה דמים גזור בה רבנן","ומאי שנא משכב ומושב דמטמיא ליה ומאי שנא בועל דלא מטמיא ליה","משכב ומושב דשכיח מטמיא ליה בועל דלא שכיח לא מטמיא","תנן טבלה יום שלאחריו ושמשה הרי זו תרבות רעה","מגען ובעילתן תלויין מאי לאו דברי הכל היא","לא ב\"ה היא דתניא אמר להם רבי יהודה לב\"ה וכי לזו אתם קורין תרבות רעה והלא לא נתכוון זה אלא לבעול את הנדה נדה ס\"ד","אלא אימא לבעול את הזבה זבה ס\"ד אלא אימא לבעול שומרת יום כנגד יום","איתמר עשירי רבי יוחנן אמר עשירי כתשיעי מה תשיעי בעי שימור אף עשירי בעי שימור","ר\"ל אמר עשירי כאחד עשר מה אחד עשר לא בעי שימור אף עשירי לא בעי שימור","איכא דמתני לה אהא אמר לו רבי אלעזר בן עזריה לר\"ע אפי' אתה מרבה בשמן [בשמן] כל היום כולו איני שומע לך אלא חצי לוג שמן לתודה ורביעית יין לנזיר ואחד עשר יום שבין נדה לנדה הלכה למשה מסיני","מאי הלכה ר' יוחנן אמר הלכה י\"א ר\"ל אומר הלכות אחד עשר","ר' יוחנן אמר הלכה אחד עשר אחד עשר הוא דלא בעי שימור הא לאחריני עביד שימור ור\"ל אמר הלכות אחד עשר לא אחד עשר בעי שימור ולא שימור לעשירי הוי","הני הלכות נינהו הני קראי נינהו דתניא יכול הרואה ג' ימים בתחילת נדה רצופים תהא זבה","ומה אני מקיים (ויקרא טו, יט) אשה כי תהיה זבה דם יהיה זובה ברואה יום אחד (אבל הרואה ג' ימים בתחילה תהיה זבה) תלמוד לומר"],[[0,"ותניא","בזב בראייה ראשונה:"],[0,"המסיט את הראייה","טהור שהסיט את הטפה ראשונה:"],[0,"ב\"ש אומרים תולין","אם יחזור הזב ויראה היום שנים נמצא זב גמור למפרע וזוב מטמא במשא:"],[0,"וב\"ה מטהרין","כמסיט את הקרי דלא מטמא במשא:"],[1,"משכבות ומושבות כו'","אלמא מדמקשי ב\"ש ראייה ראשונה לשומרת יום וקתני משכב ומושב של בין ראייה ראשונה לשניה תולין אלמא משכב ומושב דשומרת יום בשני שלה תולין ואם לא תראה טהורה ודוקא בשני אבל בראשון לא סלקא לה טבילה עד שתשמור קצת שני וכל זמן שלא טבלה זבה היא:"],[3,"אלא אימא כבועל שומרת יום","דמודה רב הונא בבעילה בשני לאחר טבילתה שהיא תולה כל זמן שלא ראתה ואין טומאתה עליו אפילו מדרבנן:"],[4,"מאי שנא איהו","בועל:"],[4,"דלא מטמא משכב ומושב","דיליה ומאי שנא איהי דמטמאה:"],[5,"איהו דלא שכיח ביה דמים לא גזרו ביה רבנן","לטמא משכב ומושב כל זמן שלא ראתה לאחר תשמיש:"],[6,"ומאי שנא משכב ומושב","כיון דאמרת איהי דשכיחי בה דמים גזרו בה רבנן מאי שנא בועל דלא גזרו ביה רבנן שתטמאנו:"],[9,"דברי הכל","ואפילו ב\"ש וקתני בשני שבתוך י\"א מגעה תלוי וקשיא לרב הונא:"],[12,"עשירי","אין לו צרוף לזיבה שאין מצטרף עמו אלא י\"א דהוי להו תרי:"],[12,"כתשיעי","דפשיטא לן ביה דבעי שימור אם ראתה בו דהא ראוי להביאה לידי זבה גמורה:"],[12,"אף עשירי","אם התחילה לראות בו:"],[12,"בעי שימור","י\"א כנגדו אע\"ג דאינה ראויה לבא לידי זבה גמורה:"],[13,"כי\"א","לב\"ה דאמרי לא בעי שימור:"],[14,"בשמן בשמן","גבי רבוכה של תודה במנחות בפ' ב' מדות (מנחות דף פט.) דכתיב והקריב על זבח התודה וכתיב תלתא בשמן ותניא אילו נאמר בשמן הייתי אומר כל המנחות ללוג ת\"ל בשמן בשמן דחלות ורקיקין הוי ריבוי אחר ריבוי למעט לחצי לוג:"],[14,"איני שומע לך","ללמד דבר זה מן המקרא שהלכה למשה מסיני על פה הוא:"],[14,"שבין נדה לנדה","בין סוף נדה לתחילת נדה משכלו ימי נדה אינה חוזרת להיות נדה לישב לראייה אחת ששה והוא עד שיכלו י\"א יום:"],[15,"מאי הלכה","דמשמע איום י\"א קאמר רבי אלעזר בן עזריה דהוי הלכה למשה מסיני ובעי הש\"ס מאי הלכותיו משאר הימים שלפניו:"],[15,"הלכה י\"א","בדבר אחד הוא חלוק משלפניו:"],[15,"הלכות י\"א","בשני דברים הוא חלוק:"],[16,"שימור לאחריני","לעשירי:"],[16,"לא איהו בעי שימור","מדאורייתא לשמור י\"א כנגדו ולא לאחריני הוי שימור דעשירי לא בעי שימור מדאורייתא הואיל ולא תבא בהן לידי זיבה ומדרבנן מיהא אפילו רואה יום י\"א אסורה לשמש ביום שלאחריו כדקתני מתני' ה\"ז גרגרן ואמרינן בפרק בא סימן (לעיל נדה דף נד.) גרגרן דתנן אסור:"],[17,"יכול הרואה ג' ימים בתחלת נדה רצופים תהא זבה","לספירת ז' נקיים ולקרבן דכתיב (ויקרא ט״ו:כ״ה) ימים רבים וקמצריך לה ספירה וקרבן:"],[18,"מה אני מקיים ואשה כי תהיה זבה","האמור בפרשה ראשונה שלא הצריכה ספירת נקיים וקרבן:"],[18,"ברואה יום אחד","אבל ראתה ג' תהא זבה:"],[18,"תלמוד לומר","בפרשה שניה:"]],[[3,"","אלא אימא כבועל שומרת יום כנגד יום. וקשה דא\"כ מסקינן דשומרת יום כנגד יום בשני שלה אין בועלה מטמא משכב ומושב והא תניא טבלה ביום שלאחריו ושמשה את ביתה ואח\"כ ראתה מטמאין משכב ומושב ומטמאין משמע לשון רבים דקאי אתרווייהו היא ובועלה וליכא למימר ראתה שאני דהא מתרצא מילתא דרב יוסף ואידחי רב כהנא וי\"ל דהך מסקנא דהכא ליישובי מילתא דרב הונא אתא דלא תקשי ליה מברייתא ומיהו מילתא דרב יוסף אדחי וניחא נמי טפי לרב הונא דלא תקשי מאי קמ\"ל דודאי ראתה שאני כדמתרץ אביי מילתיה דרב כהנא וסבר רב הונא דלענין בועלה דלא שכיח אית לן למימר ראתה שאני אבל איהי דשכיחי בה דמים אפי' לא ראתה גזרינן אטו ראתה כי היכי דגזרינן ראתה ביום י\"ב אטו ראתה תוך י\"א ואע\"ג דראיית י\"ב אינה סותרת ועוד אור\"י דאפילו קיימא מילתא דרב יוסף ניחא דלא קשה ממתני' דודאי ביום שלאחריו דהיינו ביום י\"ב דשכיח בועל גבה דליכא איסור דאורייתא מטמא בועל משכב ומושב אע\"ג דלא ראתה אבל תוך י\"א יום בשני שלה אע\"ג דגבי דידה לא מפלגינן בין ראתה ללא ראתה מ\"מ בועל אינו מטמא משכב ומושב אלא בראתה:"],[4,"","מאי שנא איהו. פי' בקונטרס מאי שנא בועל דלא מטמא משכב ומושב ותימה דהיינו האי דפריך בתר הכי מאי שנא בועל דלא מטמא משכב ומושב וי\"ל דמעיקרא פריך משום לתאי דידיה וכי משני דלא שכיח ביה דמים פריך ולטמא משום לתאי דידה ור\"י מפרש מ\"ש דאיהו רואה ראייה אחת של זוב דתולין משכבות ומושבות שבין ראשונה לשניה ואין מטמא אלא ע\"י תלייה אם יראה ואם לא יראה טהורין ומאי שנא איהי דכי רואה תוך י\"א יום דמטמאה משכב ומושב ואע\"ג דלא ראתה לרב הונא מיהו לא דמי דהתם משום דכי ראתה סתרה ולכך החמירו בלא ראתה אבל זב אפילו יראה לא יסתור לכך נראה מאי שנא איהי דכי טבלה יום שלאחר י\"א יום ושמשה וראתה דמטמא משכב ומושב בלא תלייה אע\"ג דהתם נמי אין סתירה ולהאי פירוש דפרשינן דראתה לאו דוקא פריך אבל לאידך פירושא דאמרינן ראתה שאני אבל לא ראתה תולין שוין איהו ואיהי:"],[14,"","אלא חצי לוג שמן לתודה ורביעית יין לנזיר. נראה דהכי שמע מרביה וגרסינהו א\"נ ר\"ע חלק עליו מכל שלשה אלה כדאמר לקמן גבי אחד עשר יום הלכתא לר' אלעזר בן עזריה קראי לרבי עקיבא והוא הדין נמי דבשלישי פליג אע\"ג דלא אשכחן:"],[16,"","רבי יוחנן אמר הלכה אחד עשר. תימה במאי פליגי ר' יוחנן ור\"ל הא רבי אלעזר בן עזריה לא איירי אלא בחשבון הימים שבתוך אחד עשר דשייכא בהו זיבה אבל בשימור אחד עשר לא איירי כלל וכן משמע מדפריך לקמן הני קראי נינהו ואי איהו איירי בהלכתא אחד עשר לישני קרא למנין הימים שהיא זבה והלכתא לשימור אחד עשר ויש לומר דודאי הלכה דקאמר רבי אלעזר בן עזריה לא איירי אלא במנין הימים דשייכי בהו זיבה ורבי יוחנן ור\"ל בסברא בעלמא פליגי דרבי יוחנן קאמר כיון דיום שאחר י\"א הוא נדות אין י\"א צריך ספירה ור\"ל סבר דאפילו שימור אינו נעשה לעשירי כיון דאינו ראוי להצטרף לזיבה גדולה דליכא אלא ב' ימים והשתא ניחא דהש\"ס פריך שפיר קראי נינהו:"]]],[["(ויקרא טו, כה) בלא עת נדתה (על נדתה) סמוך לנדתה","ואין לי אלא סמוך לנדתה מופלג לנדתה יום אחד מנין ת\"ל (ויקרא טו, כה) או כי תזוב","אין לי אלא יום אחד מנין לרבות מופלג שנים שלשה ארבעה חמשה ששה ושבעה שמונה תשעה עשרה מנין","אמרת מה מצינו ברביעי שראוי לספירה וראוי לזיבה אף אני אביא העשירי שראוי לספירה וראוי לזיבה","ומנין לרבות אחד עשר ת\"ל בלא עת נדתה יכול שאני מרבה אף שנים עשר אמרת לאו","ומה ראית לרבות אחד עשר ולהוציא שנים עשר מרבה אני אחד עשר שראוי לספירת או כי תזוב ומוציא אני י\"ב שאין ראוי לספירת או כי תזוב","ואין לי אלא שלשה ימים שני ימים מנין ת\"ל ימי יום אחד מנין ת\"ל כל ימי","טמאה מלמד שמטמאה את בועלה כנדה היא היא מטמאה את בועלה ואין הזב מטמא מה שהוא בועל","והלא דין הוא ומה היא שאינה מטמאה בראיות כבימים מטמאה את בועלה הוא שמטמא בראיות כבימים אינו דין שמטמא מה שהוא בועל ת\"ל היא היא מטמאה את בועלה ואין הזב מטמא מה שהוא בועל","ומנין שהוא עושה משכב ומושב ת\"ל (ויקרא טו, כו) כמשכב נדתה","ואין לי אלא שלשה ימים שני ימים מנין ת\"ל ימי יום אחד מנין ת\"ל כל ימי","ומנין שסופרת אחד לאחד ת\"ל יהיה לה יכול תספור שבעה לשנים ודין הוא ומה הוא שאין סופר אחד לאחד סופר שבעה לשנים היא שסופרת אחד לאחד אינו דין שתספור שבעה לשנים ת\"ל יהיה לה אינה סופרת אלא יומה","אלמא קראי נינהו לר\"ע קראי לר' אלעזר בן עזריה הלכתא","א\"ל רב שמעיה לר' אבא אימא ביממא תהוי זבה בליליא תהוי נדה א\"ל עלך אמר קרא (ויקרא טו, כה) על נדתה סמוך לנדתה סמוך לנדתה אימת הוי בליליא וקא קרי לה זבה","תנא דבי אליהו כל השונה הלכות בכל יום מובטח לו שהוא בן העולם הבא שנאמר (חבקוק ג, ו) הליכות עולם לו אל תקרי הליכות אלא הלכות","\u0001הדרן עלך תינוקת וסליקא לה מסכת נדה\u0002"],[[0,"בלא עת נדתה","אינו אומר לך אלא ברואה שלשה אחר ימי נדתה סמוך לנדתה שראתה יום ראשון אחר ז' ימי נדתה וראתה שמיני ותשיעי ועשירי:"],[1,"או כי תזוב","לרבות רואה ט' וי' ואחד עשר:"],[2,"מנין לרבות שנים שלשה כו'","שכולן יש להן דין אחד:"],[3,"אמרת מה מצינו ברביעי","לימים שאחר הנדה:"],[3,"שהוא ראוי","לספירת נקיים אם ראתה אב\"ג ופסקה:"],[3,"וראוי לזיבה","לצרף עם בג\"ד אם לא ראתה בא' דהא אתרבי מופלג יום אחד מקרא דאו כי תזוב דהיינו בג\"ד אף אני מרבה כל אלו עד י' ויו\"ד בכלל שהן ראויין לספירה אם ראתה שלשה ראשונים משכי ז' נקיים עד שיהו נמי נראין לזיבה באיזה מהם שתראה שלשה רצופין:"],[4,"מנין לרבות י\"א","שיצטרף עם הראשונים לזיבה לג' רצופין ואע\"ג שאינו ראוי לספירת נקיים של זיבת ג' ראשונים:"],[4,"ת\"ל בלא עת נדתה","ואפילו מופלג לימים הרבה:"],[4,"יכול","כיון דכתיב בלא עת נדתה שאני מרבה אף י\"ב שאם ראתה י' י\"א י\"ב תהא זבה גמורה ולא תהא תחלת נדה בראיית י\"ב אלא מצטרף לזיבה:"],[5,"יום י\"א שהוא ראוי לספירת זיבה או כי תזוב","דזיבה רביעי מתרבי מאו כי תזוב ולאותה זיבה משכי ימי ספירה עד י\"א:"],[6,"ואין לי","שתקרא זבה לטומאה אלא רואה שלשה רצופין:"],[6,"ת\"ל ימי","כל ימי זוב טומאתה כימי נדתה תהיה:"],[7,"טמאה מלמד שמטמאה את בועלה כנדה","שמפורש בה אשר ישכב איש וגו':"],[8,"היא שאינה מטמאה","בשלש ראיות ביום אחד טומאת זוב גמור לקרבן כאילו ראתה שלשה ימים אבל זב מטמא בין בג' ראיות ביום אחד בין בג' ימים רצופין בב\"ק בפ' כיצד הרגל (דף כד.):"],[10,"ואין לי","עושה משכב ומושב בימים שאחר הנדה אלא הרואה שלשה ימים שני ימים מנין:"],[10,"ת\"ל","כל המשכב אשר ישכב עליו כל ימי זובה כמשכב נדתה:"],[11,"יהיה לה","הוסיף לה הויה של שמור:"],[11,"הוא שאינו סופר אחד לאחד","זב בעל ראייה אחת כבעל קרי וטובל בו ביום סופר שבעה לשנים:"],[12,"אלמא קראי נינהו","כל דין י\"א שבין נדה לנדה מכאן למדנו שהן י\"א יום והרואה בהם ג' הרי זו זבה והרואה בא' בב' סופרת יום כנגד יום ולסוף י\"א מתחילין ימי נדה אם תראה אחד תשב ששה והוא שהרי לא רבינן לדין יום זובה אלא י\"א ומכאן ואילך הרי היא בדין פרשה ראשונה דכתיב בה שבעת ימים תהיה בנדתה:"],[12,"לרבי עקיבא קראי","דלא גמר הך הלכתא הלכה למשה מסיני דקאמר ר' אלעזר בן עזריה וכי היכי דיליף חצי לוג שמן לתודה מקראי הכי נמי יליף אחד עשר יום שבין נדה לנדה מקראי:"],[13,"ביממי","ראתה ביום תהיה זבה כדכתיב (ויקרא טו) ימים רבים אבל ראתה בלילות לא תהא זבה:"],[13,"סמוך לנדתה","ליל שמיני שהרי ימי נדות כל שבעה עד הלילה כדכתיב שבעת ימים תהיה בנדתה:"],[14,"הלכות","משנה וברייתא הלכה למשה מסיני:"]],[[2,"","אין לי אלא יום אחד מנין לרבות מופלג שנים ושלשה. אגב ריהטא נקט שנים דשנים היינו יום שני לימי זיבה דהיינו מופלג יום אחד שריבה כבר דהא מני ואזיל עד י' וי\"א וא\"כ שנים היינו שני:"],[8,"","הוא שמטמא בראיות כבימים אינו דין כו'. תימה דאיכא למפרך מה להיא שכן מטמאה באונס והכי אמרינן בריש פרק בנות כותים (לעיל נדה לב:) דלא ילפינן מהדדי וכן לקמן דקאמר מה הוא שאינו סופר אחד לאחד כו' איכא למפרך מה להוא שכן מטמא בראיות כבימים מיהו בזה מצינן שפיר למילף דלגבי ספירה אחמיר רחמנא באשה מבאיש ולענין ספירה עביד שפיר ק\"ו הואיל ולענין ספירה מצינו שהחמיר באשה מבאיש וצ\"ל שאינו קל וחומר גמור אלא כמו גילוי מילתא בעלמא לגלות זה על זה וצ\"ע דאיכא מקומות דאיכא תרי קראי לדם נדות ולזיבות ויש מקומות דנפקא מחד קרא:"],[10,"","ת\"ל כל ימי נדתה. תימה דהך מוקמינן כר\"ע אלמא ר\"ע קא דריש כל וכן בשלהי פ' התערובת (זבחים פב.) דריש ר\"ע כל וא\"כ כי קאמר בפסחים פרק אלו עוברין (פסחים דף מג:) מאן שמעת ליה דדריש כל ר' אליעזר הוא דלמא ר\"ע הוא דדריש נמי כל ויש לומר דאין לדמות דרשות דכל להדדי דיש כל דשייך למדרש לכ\"ע והאי דשמעתין דלמנינא מדרש שפיר דמדימי למנינא כל נמי למנינא:"],[14,"","תנא דבי אליהו כל השונה הלכות. אית ספרים דלא גרסינן ליה מיהו בפירוש רש\"י איתא ור\"ת הגיהו בספרו וכן נראה דאיידי דאיירי לעיל בהלכתא מייתי לה לסיים בדבר טוב ואיתא נמי כן במגילה פרק בתרא (דף כח:) והכי נמי אמרינן באין עומדין (ברכות לא.) שכן מצינו בנביאים הראשונים שסיימו דבריהן בדברי שבח ותנחומין:"]]]]};
